#define MAX_FRAME_SIZE 1500 // Example maximum frame size constraint
#define INITIAL_BUFFER_COUNT 10

typedef struct {
    uint16_t Transport_SN;
    char *MAC_Receive_Buffer;
} MAC_Transport_SN;

void initializeBuffers(MAC_Transport_SN **array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        array[i] = malloc(sizeof(MAC_Transport_SN));
        if (!array[i]) {
            perror("Failed to allocate memory for MAC_Transport_SN");
            exit(EXIT_FAILURE);
        }
        array[i]->Transport_SN = i + 1;
        array[i]->MAC_Receive_Buffer = NULL; // Initially no buffer
    }
}

void validateAndAllocateBuffer(MAC_Transport_SN *transport_sn, size_t frame_size) {
    if (frame_size > MAX_FRAME_SIZE) {
        fprintf(stderr, "Frame size exceeds maximum allowed limit\n");
        return;
    }

    if (!transport_sn->MAC_Receive_Buffer || 
        strlen(transport_sn->MAC_Receive_Buffer) < frame_size) {

        free(transport_sn->MAC_Receive_Buffer);
        transport_sn->MAC_Receive_Buffer = malloc(frame_size + 1); // +1 for null terminator
        if (!transport_sn->MAC_Receive_Buffer) {
            perror("Failed to allocate memory for MAC_Receive_Buffer");
            exit(EXIT_FAILURE);
        }
        memset(transport_sn->MAC_Receive_Buffer, 0, frame_size + 1);
    }
}

void updateBufferConfiguration(MAC_Transport_SN **array, size_t count, 
                               const char *data_source_updates) {
    // Simulating data source updates as JSON string with frame sizes
    // This is a simplified example; in practice use proper parsing for security and robustness

    char *update_token = strtok((char *)data_source_updates, ",");
    while (update_token) {
        size_t transport_sn_index = atoi(update_token);
        if (transport_sn_index < 1 || transport_sn_index > count) {
            fprintf(stderr, "Invalid Transport_SN index from data source: %zu\n", transport_sn_index);
        } else {
            size_t frame_size = atoi(strtok(NULL, ","));
            validateAndAllocateBuffer(array[transport_sn_index - 1], frame_size);
        }
        update_token = strtok(NULL, ",");
    }
}

void freeBuffers(MAC_Transport_SN **array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i]) {
            free(array[i]->MAC_Receive_Buffer);
            free(array[i]);
            array[i] = NULL;
        }
    }
}

int main() {
    MAC_Transport_SN *bufferArray[INITIAL_BUFFER_COUNT];

    initializeBuffers(bufferArray, INITIAL_BUFFER_COUNT);

    // Simulated real-time updates from an external data source
    const char *updates = "1,500,2,1200,3,1600";  // Example format: Transport_SN,frame_size
    updateBufferConfiguration(bufferArray, INITIAL_BUFFER_COUNT, updates);

    freeBuffers(bufferArray, INITIAL_BUFFER_COUNT);

    return 0;
}
