#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define DEFAULT_MAX_SIZE 1024 * 1024 // 1 MB default size limit

typedef struct {
    int value;
    long offset;
} record_t;

int serialize_data(long* offsets, int* keys, record_t* records, uint8_t** out_buffer, size_t* out_size);
int deserialize_data(const uint8_t* in_buffer, size_t in_size, long** des_offsets, int** des_keys, record_t** des_records);

void initialize_arrays_and_serialize(size_t num_elements, size_t max_memory_limit) {
    if (max_memory_limit == 0) {
        max_memory_limit = DEFAULT_MAX_SIZE;
    }

    srand((unsigned int)time(NULL));

    size_t long_size = sizeof(long);
    size_t int_size = sizeof(int);
    size_t record_size = sizeof(record_t);

    // Calculate total required memory
    size_t total_required_memory = num_elements * (long_size + int_size + record_size);

    if (total_required_memory > max_memory_limit) {
        fprintf(stderr, "Memory limit exceeded\n");
        return;
    }

    long* offsets = NULL;
    int* keys = NULL;
    record_t* records = NULL;

    // Allocate memory for arrays
    offsets = (long*)malloc(num_elements * long_size);
    if (!offsets) {
        perror("Failed to allocate offsets");
        goto cleanup;
    }
    keys = (int*)malloc(num_elements * int_size);
    if (!keys) {
        perror("Failed to allocate keys");
        free(offsets);
        goto cleanup;
    }
    records = (record_t*)malloc(num_elements * record_size);
    if (!records) {
        perror("Failed to allocate records");
        free(offsets);
        free(keys);
        goto cleanup;
    }

    // Initialize arrays
    for (size_t i = 0; i < num_elements; ++i) {
        long offset_value = rand();
        int key_value = rand();

        if ((long)((unsigned long)key_value) != key_value) { // Check for overflow
            fprintf(stderr, "Overflow detected in keys\n");
            goto cleanup;
        }

        offsets[i] = offset_value;
        keys[i] = key_value;

        records[i].value = key_value;
        records[i].offset = offset_value;
    }

    // Serialize data
    uint8_t* buffer = NULL;
    size_t buffer_size = 0;
    if (serialize_data(offsets, keys, records, &buffer, &buffer_size) != 0) {
        fprintf(stderr, "Serialization failed\n");
        goto cleanup;
    }

    // Deserialization check
    long* des_offsets = NULL;
    int* des_keys = NULL;
    record_t* des_records = NULL;
    if (deserialize_data(buffer, buffer_size, &des_offsets, &des_keys, &des_records) != 0) {
        fprintf(stderr, "Deserialization failed\n");
        free(buffer);
        goto cleanup;
    }

    // Free allocated memory
cleanup:
    free(offsets);
    free(keys);
    free(records);
    free(des_offsets);
    free(des_keys);
    free(des_records);
    free(buffer);
}

int serialize_data(long* offsets, int* keys, record_t* records, uint8_t** out_buffer, size_t* out_size) {
    size_t num_elements = 0;

    // Assuming the arrays are of the same length
    while (offsets[num_elements] != 0 || keys[num_elements] != 0 || records[num_elements].value != 0) {
        ++num_elements; 
    }

    size_t buffer_size = num_elements * (sizeof(long) + sizeof(int) + sizeof(record_t));
    *out_buffer = (uint8_t*)malloc(buffer_size);
    if (!*out_buffer) {
        perror("Failed to allocate serialization buffer");
        return -1;
    }

    uint8_t* ptr = *out_buffer;
    for (size_t i = 0; i < num_elements; ++i) {
        memcpy(ptr, &offsets[i], sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &keys[i], sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &records[i], sizeof(record_t));
        ptr += sizeof(record_t);
    }

    *out_size = buffer_size;
    return 0;
}

int deserialize_data(const uint8_t* in_buffer, size_t in_size, long** des_offsets, int** des_keys, record_t** des_records) {
    size_t num_elements = in_size / (sizeof(long) + sizeof(int) + sizeof(record_t));

    *des_offsets = (long*)malloc(num_elements * sizeof(long));
    if (!*des_offsets) {
        perror("Failed to allocate offsets for deserialization");
        return -1;
    }
    *des_keys = (int*)malloc(num_elements * sizeof(int));
    if (!*des_keys) {
        free(*des_offsets);
        perror("Failed to allocate keys for deserialization");
        return -1;
    }
    *des_records = (record_t*)malloc(num_elements * sizeof(record_t));
    if (!*des_records) {
        free(*des_offsets);
        free(*des_keys);
        perror("Failed to allocate records for deserialization");
        return -1;
    }

    const uint8_t* ptr = in_buffer;
    for (size_t i = 0; i < num_elements; ++i) {
        memcpy(&((*des_offsets)[i]), ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(&((*des_keys)[i]), ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&((*des_records)[i]), ptr, sizeof(record_t));
        ptr += sizeof(record_t);
    }

    return 0;
}
