```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char *filename;
    long total_lines;
    long total_length;
} FileData;

typedef struct {
    FileData **files;
    int count;
    pthread_mutex_t lock;
    long global_total_lines;
    long global_total_length;
} GlobalData;

void *process_file(void *arg) {
    FileData *file_data = (FileData *)arg;
    FILE *file = fopen(file_data->filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", file_data->filename);
        free(file_data->filename);
        free(file_data);
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    long local_lines = 0;
    long local_length = 0;

    while (fgets(line, sizeof(line), file)) {
        local_lines++;
        local_length += strlen(line);
    }

    fclose(file);

    pthread_mutex_lock(&global_data.lock);
    global_data.global_total_lines += local_lines;
    global_data.global_total_length += local_length;
    pthread_mutex_unlock(&global_data.lock);

    free(file_data->filename);
    free(file_data);

    return NULL;
}

void print_usage() {
    printf("Usage: program [options] <input files>\n");
    printf("Options:\n");
    printf("  -h, --help           Show this help message\n");
    printf("  -d, --debug          Print individual line lengths for debugging\n");
    printf("  -o, --output FILE    Specify output file for aggregated results\n");
}

void parse_config_file(const char *config_filename) {
    FILE *file = fopen(config_filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening config file: %s\n", config_filename);
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        line[strcspn(line, "\n")] = '\0';
        if (strlen(line) > 0 && line[0] != '#') {
            FileData *file_data = malloc(sizeof(FileData));
            file_data->filename = strdup(line);
            pthread_mutex_lock(&global_data.lock);
            global_data.files[global_data.count++] = file_data;
            pthread_mutex_unlock(&global_data.lock);
        }
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    int debug_mode = 0;
    const char *output_file = NULL;
    GlobalData global_data = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, 0, 0};

    if (argc < 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_usage();
            return EXIT_SUCCESS;
        } else if (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "--debug") == 0) {
            debug_mode = 1;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            if (i + 1 < argc) {
                output_file = argv[++i];
            }
        } else if (strchr(argv[i], '.') != NULL && strstr(argv[i], ".config") != NULL) {
            parse_config_file(argv[i]);
        } else {
            FileData *file_data = malloc(sizeof(FileData));
            file_data->filename = strdup(argv[i]);
            pthread_mutex_lock(&global_data.lock);
            global_data.files = realloc(global_data.files, (global_data.count + 1) * sizeof(FileData *));
            global_data.files[global_data.count++] = file_data;
            pthread_mutex_unlock(&global_data.lock);
        }
    }

    if (global_data.count == 0) {
        print_usage();
        return EXIT_FAILURE;
    }

    global_data.files = realloc(global_data.files, global_data.count * sizeof(FileData *));
    pthread_t threads[global_data.count];

    for (int i = 0; i < global_data.count; ++i) {
        if (pthread_create(&threads[i], NULL, process_file, global_data.files[i])) {
            fprintf(stderr, "Error creating thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < global_data.count; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (output_file) {
        FILE *out_file = fopen(output_file, "w");
        if (!out_file) {
            fprintf(stderr, "Error opening output file: %s\n", output_file);
            return EXIT_FAILURE;
        }
        fprintf(out_file, "Total lines: %ld\n", global_data.global_total_lines);
        fprintf(out_file, "Average line length: %.2f\n", (double)global_data.global_total_length / global_data.global_total_lines);
        fclose(out_file);
    } else {
        printf("Total lines: %ld\n", global_data.global_total_lines);
        printf("Average line length: %.2f\n", (double)global_data.global_total_length / global_data.global_total_lines);
    }

    if (debug_mode) {
        for (int i = 0; i < global_data.count; ++i) {
            FileData *file_data = global_data.files[i];
            printf("File: %s, Lines: %ld, Total Length: %ld\n", file_data->filename, file_data->total_lines, file_data->total_length);
        }
    }

    for (int i = 0; i < global_data.count; ++i) {
        free(global_data.files[i]);
    }
    free(global_data.files);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Command-Line Parsing**: Handles options for help, debug mode, and output file specification.
- **Configuration File Support**: Reads additional files from a configuration file.
- **Parallel Processing**: Uses threads to process multiple files concurrently.
- **Thread Safety**: Uses mutexes to ensure safe updates to shared global data.
- **Error Handling**: Provides error messages for invalid inputs and file operations.
- **Output Options**: Supports both console output and writing results to a specified file.

