}

int process_file(FileProcessor *processor) {
    uint8_t *buffer = malloc(BUFFER_SIZE);
    if (!buffer) {
        log_message("Memory allocation failed");
        return -1;
    }

    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, processor->input)) > 0) {
        process_chunk(processor, buffer, bytes_read);
        processor->total_processed_bytes += bytes_read;
        log_message("Processing chunk...");
    }

    free(buffer);
    return 0;
}

int main(int argc, char *argv[]) {
