    processor.input = fopen(argv[1], "rb");
    if (!processor.input) {
        perror("Error opening input file");
        return EXIT_FAILURE;
    }

    processor.output = fopen(argv[2], "wb");
    if (!processor.output) {
        perror("Error opening output file");
        fclose(processor.input);
        return EXIT_FAILURE;
