    processor.prioritize_speed = atoi(argv[5]);
    processor.total_processed_bytes = 0;

    int result = process_file(&processor);

    fclose(processor.input);
    fclose(processor.output);

    if (result == 0) {
        log_message("Processing completed successfully.");
    } else {
        log_message("An error occurred during processing.");
    }

    return result;
}
