#define BUFFER_SIZE 1024

void resolve_hostname(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return;
    }

    printf("Resolved IP addresses for %s:\n", hostname);
    for (p = res; p != NULL; p = p->ai_next) {
        char ipstr[INET6_ADDRSTRLEN];
        void *addr;

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        printf("  %s\n", ipstr);
    }
    freeaddrinfo(res);
}

double calculate_average_of_last_three(const char *line) {
    double values[3];
    int count = sscanf(line + strlen(line) - 6, "%lf,%lf,%lf", &values[0], &values[1], &values[2]);

    if (count < 3) return 0.0;

    double sum = values[0] + values[1] + values[2];
    return sum / 3.0;
}

void process_line(char *line) {
    char *hostname, *processed_line = malloc(strlen(line) + 32); // Allocate extra space for the average
    if (!processed_line) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    hostname = strtok(line, ",");
    if (hostname) resolve_hostname(hostname);

    char *fields[100];
    int field_count = 0;
    char *token = strtok(line, ",");

    while (token != NULL) {
        fields[field_count++] = token;
        token = strtok(NULL, ",");
    }

    strcpy(processed_line, line);
    double avg = calculate_average_of_last_three(line);
    snprintf(fields[field_count - 1] + strlen(fields[field_count - 1]) + 1, strlen(processed_line) - strlen(fields[field_count - 1]) - 2, ",%.2f", avg);

    printf("%s\n", processed_line);
    free(processed_line);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) {
        process_line(line);
    }

    free(line);
    fclose(file);

    return EXIT_SUCCESS;
}
