#define MAX_LINE_LENGTH 32768 // Assuming a maximum length for the input line

// Function to print the largest integer from an array
void printLargestInteger(int *array, size_t count) {
    if (count == 0) {
        printf("No valid integers provided.\n");
        return;
    }

    int max = INT_MIN;
    for (size_t i = 0; i < count; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("The largest integer is: %d\n", max);
}

// Main function to read integers from a file, sort them, and print the largest
void processFile(const char *filePath) {
    FILE *file = fopen(filePath, "r");

    if (!file) {
        perror("Error opening file");
        return;
    }

    // Allocate memory for reading one line of the file
    char buffer[MAX_LINE_LENGTH];
    if (fgets(buffer, sizeof(buffer), file) == NULL) {
        fclose(file);
        printf("File is empty or could not be read.\n");
        return;
    }

    fclose(file);

    // Tokenize the input string based on commas
    char *token = strtok(buffer, ",");
    size_t count = 0;
    int *intArray = NULL;

    while (token != NULL) {
        char *endptr;
        long value = strtol(token, &endptr, 10);

        if (*endptr == '\0' && value >= INT_MIN && value <= INT_MAX) {
            // Reallocate memory for storing integers
            int *newArray = realloc(intArray, (count + 1) * sizeof(int));
            if (!newArray) {
                free(intArray);
                printf("Memory allocation failed.\n");
                return;
            }
            intArray = newArray;

            intArray[count++] = (int)value;
        }

        token = strtok(NULL, ",");
    }

    // Check if we have any valid integers
    if (count == 0) {
        free(intArray);
        printf("No valid integers provided.\n");
        return;
    }

    // Sort the array in descending order
    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = i + 1; j < count; ++j) {
            if (intArray[i] < intArray[j]) {
                int temp = intArray[i];
                intArray[i] = intArray[j];
                intArray[j] = temp;
            }
        }
    }

    // Print the largest integer using a helper function
    printLargestInteger(intArray, count);

    free(intArray);
}
