```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_CHANNELS 10
#define BUFFER_SIZE 1024

typedef enum {
    LOG_TO_FILE,
    LOG_TO_CONSOLE,
    LOG_TO_NETWORK
} LogDestination;

typedef struct {
    char *filename;
    int sockfd; // Socket file descriptor for network logging
} ChannelConfig;

typedef struct {
    pthread_mutex_t lock;
    ChannelConfig channels[MAX_CHANNELS];
    size_t active_channels;
} LogManager;

LogManager log_manager = { .active_channels = 0 };

void initialize_log_manager() {
    pthread_mutex_init(&log_manager.lock, NULL);
}

void destroy_log_manager() {
    pthread_mutex_destroy(&log_manager.lock);
}

int add_logging_channel(LogDestination destination) {
    pthread_mutex_lock(&log_manager.lock);

    if (log_manager.active_channels >= MAX_CHANNELS) {
        pthread_mutex_unlock(&log_manager.lock);
        return -1;
    }

    switch (destination) {
        case LOG_TO_FILE:
            log_manager.channels[log_manager.active_channels].filename = strdup("default.log");
            break;
        case LOG_TO_CONSOLE:
            // No specific config needed
            break;
        case LOG_TO_NETWORK:
            log_manager.channels[log_manager.active_channels].sockfd = socket(AF_INET, SOCK_STREAM, 0);
            // Assume network setup is done elsewhere
            break;
    }

    log_manager.active_channels++;
    pthread_mutex_unlock(&log_manager.lock);
    return 0;
}

int remove_logging_channel(LogDestination destination) {
    pthread_mutex_lock(&log_manager.lock);

    for (size_t i = 0; i < log_manager.active_channels; ++i) {
        if ((destination == LOG_TO_FILE && strcmp(log_manager.channels[i].filename, "default.log") == 0) ||
            (destination == LOG_TO_CONSOLE && !log_manager.channels[i].filename) ||
            (destination == LOG_TO_NETWORK && log_manager.channels[i].sockfd != -1)) {

            if (destination == LOG_TO_FILE) {
                free(log_manager.channels[i].filename);
            } else if (destination == LOG_TO_NETWORK) {
                close(log_manager.channels[i].sockfd);
            }

            // Shift elements
            for (size_t j = i; j < log_manager.active_channels - 1; ++j) {
                log_manager.channels[j] = log_manager.channels[j + 1];
            }
            log_manager.active_channels--;
            pthread_mutex_unlock(&log_manager.lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&log_manager.lock);
    return -1;
}

void configure_logging(LogDestination destination, const char *config) {
    pthread_mutex_lock(&log_manager.lock);

    for (size_t i = 0; i < log_manager.active_channels; ++i) {
        if ((destination == LOG_TO_FILE && log_manager.channels[i].filename) ||
            (destination == LOG_TO_NETWORK && log_manager.channels[i].sockfd != -1)) {

            if (destination == LOG_TO_FILE) {
                free(log_manager.channels[i].filename);
                log_manager.channels[i].filename = strdup(config);
            } else if (destination == LOG_TO_NETWORK) {
                // Assume reconfiguration of network settings
            }
        }
    }

    pthread_mutex_unlock(&log_manager.lock);
}

void log_message(const char *message, LogDestination destination) {
    pthread_mutex_lock(&log_manager.lock);

    for (size_t i = 0; i < log_manager.active_channels; ++i) {
        if ((destination == LOG_TO_FILE && log_manager.channels[i].filename) ||
            (destination == LOG_TO_CONSOLE) || 
            (destination == LOG_TO_NETWORK && log_manager.channels[i].sockfd != -1)) {

            switch (destination) {
                case LOG_TO_FILE:
                    FILE *file = fopen(log_manager.channels[i].filename, "a");
                    if (file) {
                        fprintf(file, "%s\n", message);
                        fclose(file);
                    }
                    break;
                case LOG_TO_CONSOLE:
                    printf("%s\n", message);
                    break;
                case LOG_TO_NETWORK:
                    send(log_manager.channels[i].sockfd, message, strlen(message), 0);
                    break;
            }
        }
    }

    pthread_mutex_unlock(&log_manager.lock);
}

int main() {
    initialize_log_manager();

    add_logging_channel(LOG_TO_FILE);
    add_logging_channel(LOG_TO_CONSOLE);

    log_message("This is a test message", LOG_TO_FILE);
    log_message("This is another test message", LOG_TO_CONSOLE);

    configure_logging(LOG_TO_FILE, "newfile.log");
    remove_logging_channel(LOG_TO_CONSOLE);

    destroy_log_manager();
    return 0;
}
```

**Key Features:**
- **Thread Safety:** Utilizes `pthread_mutex_t` to ensure thread-safe operations when adding, removing, and configuring logging channels.
- **Dynamic Configuration:** Channels can be added/removed/configured at runtime without disrupting ongoing logging processes.
- **Multiple Destinations:** Supports file, console, and network as logging destinations.
- **Performance Considerations:** Implements basic optimizations like mutex locks to handle concurrency efficiently.

This framework serves as a foundation and can be extended with more advanced features such as asynchronous logging, detailed configuration options for each destination, or optimized buffering strategies.']

