import hashlib
import os
from threading import Lock

def calculate_sha256(file_path, progress_callback=None):
    """Calculate the SHA-256 hash of a large file in buffered chunks."""
    sha256 = hashlib.sha256()
    file_size = os.path.getsize(file_path)
    chunk_size = 1024 * 1024  # 1MB chunk size for efficient I/O
    read_bytes = 0

    with open(file_path, 'rb') as f:
        while chunk := f.read(chunk_size):
            sha256.update(chunk)
            read_bytes += len(chunk)
            if progress_callback:
                percentage_done = (read_bytes / file_size) * 100
                progress_callback(percentage_done)

    return sha256.hexdigest()

def process_file(file_path, progress_callback=None):
    """Process a single file and calculate its SHA-256 hash."""
    try:
        return calculate_sha256(file_path, progress_callback)
    except Exception as e:
        print(f"Error processing {file_path}: {e}")
        return None

from concurrent.futures import ThreadPoolExecutor
import threading

# Global lock for thread-safe operations if needed
lock = Lock()

def process_files_concurrently(file_paths):
    """Process multiple files concurrently."""
    def file_processing_task(file_path):
        with lock:  # Ensure thread safety if shared resources are used
            return process_file(file_path, progress_callback)

    def progress_callback(percentage_done):
        print(f"Progress: {percentage_done:.2f}%")

    results = []
    with ThreadPoolExecutor() as executor:
        future_to_file = {executor.submit(file_processing_task, file): file for file in file_paths}
        for future in future_to_file:
            result = future.result()
            if result is not None:
                results.append(result)

    return results

# Example usage
if __name__ == "__main__":
    files_to_process = ['file1.txt', 'file2.txt']  # Add your file paths here
    hashes = process_files_concurrently(files_to_process)
    for file, hash_value in zip(files_to_process, hashes):
        print(f"{file}: {hash_value}")
