public class PokemonReportGenerator {

    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MS = 1000;
    private final ExecutorService executor = Executors.newFixedThreadPool(10);

    public String generatePokemonReports(List<Pokemon> pokemons) {
        StringBuilder reportBuilder = new StringBuilder();

        for (Pokemon pokemon : pokemons) {
            CompletableFuture<Void> future = fetchAndProcessPokemonDetails(pokemon)
                .thenAccept(details -> appendReport(reportBuilder, details));

            try {
                future.get(); // Wait for processing to complete
            } catch (Exception e) {
                System.err.println("Error processing Pokémon: " + pokemon.getId() + ", using default values.");
                appendDefaultReport(reportBuilder, pokemon);
            }
        }

        executor.shutdown();
        return reportBuilder.toString();
    }

    private CompletableFuture<PokemonDetails> fetchAndProcessPokemonDetails(Pokemon pokemon) {
        return CompletableFuture.supplyAsync(() -> {
            PokemonExternalData data = retryWithBackoff(this::fetchFromApi, pokemon.getId());
            return processPokeMonData(pokemon, data);
        }, executor);
    }

    private static PokemonExternalData retryWithBackoff(Function<String, PokemonExternalData> apiCall, String pokemonId) {
        int attempt = 0;
        while (attempt < MAX_RETRIES) {
            try {
                return apiCall.apply(pokemonId);
            } catch (IOException e) {
                attempt++;
                if (attempt >= MAX_RETRIES) {
                    System.err.println("Max retries reached for Pokémon ID: " + pokemonId);
                    break;
                }
                try {
                    Thread.sleep(RETRY_DELAY_MS * attempt);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        return new PokemonExternalData(); // default fallback
    }

    private static PokemonDetails processPokeMonData(Pokemon pokemon, PokemonExternalData data) {
        String name = data.getName() != null ? data.getName() : "Unknown";
        List<String> types = data.getTypes() != null ? data.getTypes() : List.of("Unknown");

        Map<String, List<String>> properties = switch (types) {
            case ["Fire"] -> Map.of(
                "Weaknesses", List.of("Water"),
                "Resistances", List.of("Grass", "Bug", "Steel"),
                "Immunities", List.of()
            );
            case ["Water"] -> Map.of(
                "Weaknesses", List.of("Electric", "Grass"),
                "Resistances", List.of("Fire", "Ice", "Steel"),
                "Immunities", List.of()
            );
            // Add more type cases here...
            default -> Map.of(
                "Weaknesses", List.of(),
                "Resistances", List.of(),
                "Immunities", List.of()
            );
        };

        return new PokemonDetails(name, types, properties.get("Weaknesses"), 
                                  properties.get("Resistances"), properties.get("Immunities"));
    }

    private void appendReport(StringBuilder reportBuilder, PokemonDetails details) {
        reportBuilder.append("Name: ").append(details.getName()).append("\n")
                     .append("Types: ").append(String.join(", ", details.getTypes())).append("\n")
                     .append("Weaknesses: ").append(String.join(", ", details.getWeaknesses())).append("\n")
                     .append("Resistances: ").append(String.join(", ", details.getResistances())).append("\n")
                     .append("Immunities: ").append(String.join(", ", details.getImmunities())).append("\n\n");
    }

    private void appendDefaultReport(StringBuilder reportBuilder, Pokemon pokemon) {
        reportBuilder.append("Name: Unknown (ID: ")
                     .append(pokemon.getId()).append(")\n")
                     .append("Types: Unknown\n")
                     .append("Weaknesses: N/A\n")
                     .append("Resistances: N/A\n")
                     .append("Immunities: N/A\n\n");
    }

    private PokemonExternalData fetchFromApi(String pokemonId) throws IOException {
