        free(cipher_obj);
        return NULL;
    }

    int rv = EVP_EncryptInit_ex(cipher_obj->ctx, EVP_by_id(cipher_name, NULL, 0), NULL, key, iv);
    if (rv != 1) {
        log_message("EVP_EncryptInit_ex failed");
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        return NULL;
    }

    log_message("Cipher object created successfully");
    return cipher_obj;
}

int encrypt_data(CipherObject *cipher_obj, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int max_ciphertext_len) {
    if (!cipher_obj || !cipher_obj->ctx) {
        log_message("Invalid cipher object");
        return 0;
    }

    int len;
    int ciphertext_len;

    // Encrypt the plaintext
    if (EVP_EncryptUpdate(cipher_obj->ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        log_message("EVP_EncryptUpdate failed");
        return 0;
    }
    ciphertext_len = len;

    // Finalize encryption
    if (EVP_EncryptFinal_ex(cipher_obj->ctx, ciphertext + len, &len) != 1) {
        log_message("EVP_EncryptFinal_ex failed");
        return 0;
    }
    ciphertext_len += len;

    log_message("Data encrypted successfully");
    return ciphertext_len;
}

void destroy_cipher_object(CipherObject *cipher_obj) {
    if (cipher_obj) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        log_message("Cipher object destroyed");
    }
}

// Example usage
int main() {
    // Initialize OpenSSL
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    const char *cipher_name = "aes-256-cbc";  // Example cipher
    unsigned char key[] = "0123456789abcdef0123456789abcdef";  // 256-bit key
    unsigned char iv[] = "1234567890abcdef";  // Initialization vector

    CipherObject *cipher_obj = create_cipher_object(cipher_name, key, sizeof(key), iv);
    if (!cipher_obj) {
        return 1;
    }

    const char *plaintext = "This is a test message.";
    unsigned char ciphertext[128];
    int ciphertext_len = encrypt_data(cipher_obj, (unsigned char *)plaintext, strlen(plaintext), ciphertext, sizeof(ciphertext));

    if (ciphertext_len > 0) {
        printf("Ciphertext length: %d\n", ciphertext_len);
        // Handle ciphertext...
    }

    destroy_cipher_object(cipher_obj);

    // Clean up OpenSSL
    EVP_cleanup();
    ERR_free_strings();

    return 0;
}
```

### Key Points:
- **Cipher Object Management**: The function creates, uses, and destroys a `CipherObject` to manage the cipher context.
- **Dynamic Cipher Loading**: Uses `EVP_by_id()` for dynamic loading of ciphers at runtime.
- **Logging**: Integrates with a simple logging framework to log operations.
- **Error Handling**: Provides informative error messages via logging.
- **Memory Management**: Ensures efficient memory usage and cleanup to prevent leaks.
- **Performance Considerations**: Handles large input strings efficiently within the constraints of OpenSSL's EVP interface.']

['Here is a C implementation of a robust semaphore management library designed to handle high concurrency conditions:

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
import "logging.h" // Assume logging, configuration, error reporting are provided by the application framework
import "error_handling.h"
import "config.h"

#define MAX_SEMAPHORES 20
#define SEMAPHORE_CACHE_SIZE 10

typedef struct {
    sem_t semaphore;
    int in_use;
} Semaphore;

Semaphore semaphore_cache[SEMAPHORE_CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Logging and error handling are abstracted through framework functions
extern void log_info(const char *message);
extern void report_error(const char *error);

static int find_free_semaphore() {
    for (int i = 0; i < SEMAPHORE_CACHE_SIZE; ++i) {
        pthread_mutex_lock(&cache_lock);
        if (!semaphore_cache[i].in_use) {
            semaphore_cache[i].in_use = 1;
            pthread_mutex_unlock(&cache_lock);
            return i;
        }
        pthread_mutex_unlock(&cache_lock);
    }
    report_error("No free semaphores available in cache");
    return -1;
}

static void release_semaphore(int index) {
    if (index >= 0 && index < SEMAPHORE_CACHE_SIZE) {
        pthread_mutex_lock(&cache_lock);
        semaphore_cache[index].in_use = 0;
        pthread_mutex_unlock(&cache_lock);
    }
}

int create_semaphore(int initial_value, int max_count) {
    int index = find_free_semaphore();
    if (index == -1) return -1;

    log_info("Creating semaphore");
    if (sem_init(&semaphore_cache[index].semaphore, 0, initial_value)) {
        report_error("Failed to initialize semaphore");
        release_semaphore(index);
        return -1;
    }

    return index;
}

void use_semaphore(int sem_index) {
    if (sem_index >= 0 && sem_index < SEMAPHORE_CACHE_SIZE) {
        log_info("Acquiring semaphore");
        if (sem_wait(&semaphore_cache[sem_index].semaphore)) {
            report_error("Failed to acquire semaphore");
        }
    } else {
        report_error("Invalid semaphore index");
    }
}

void release_semaphore_use(int sem_index) {
    if (sem_index >= 0 && sem_index < SEMAPHORE_CACHE_SIZE) {
        log_info("Releasing semaphore");
        if (sem_post(&semaphore_cache[sem_index].semaphore)) {
            report_error("Failed to release semaphore");
        }
    } else {
        report_error("Invalid semaphore index");
    }
}

void delete_semaphore(int sem_index) {
    if (sem_index >= 0 && sem_index < SEMAPHORE_CACHE_SIZE) {
        log_info("Deleting semaphore");
        if (sem_destroy(&semaphore_cache[sem_index].semaphore)) {
            report_error("Failed to destroy semaphore");
        }
        release_semaphore(sem_index);
    } else {
        report_error("Invalid semaphore index");
    }
}

void cleanup() {
    for (int i = 0; i < SEMAPHORE_CACHE_SIZE; ++i) {
        if (semaphore_cache[i].in_use && sem_destroy(&semaphore_cache[i].semaphore)) {
            report_error("Failed to destroy semaphore during cleanup");
        }
    }
}

// Example of integrating dynamic updates from an external source
void update_semaphore_properties(int sem_index, int new_value) {
    if (sem_index >= 0 && sem_index < SEMAPHORE_CACHE_SIZE) {
        log_info("Updating semaphore properties");
        if (sem_post(&semaphore_cache[sem_index].semaphore)) {
            report_error("Failed to post before updating semaphore");
        }
        if (sem_init(&semaphore_cache[sem_index].semaphore, 0, new_value)) {
            report_error("Failed to reinitialize semaphore with new properties");
        }
    } else {
        report_error("Invalid semaphore index during update");
    }
}
```

### Key Features:
- **Concurrency Management**: Uses a thread-safe cache of semaphores with mutex locks.
- **Logging and Error Handling**: Integrated through the application's logging and error reporting mechanisms.
- **Resource Limits**: Implements basic handling for resource limits using a fixed-size semaphore cache.
- **Dynamic Updates**: Provides a function to update semaphore properties without disrupting ongoing operations.

This library is designed to be integrated into an existing framework, leveraging its logging, configuration, and error handling capabilities.']

