const { createReadStream, promises: fsp } = require('fs');
const { pipeline } = require('stream/promises');

// Cache object to store frequently accessed records
let cache = {};

async function processFilesInDirectory(directoryPath) {
    try {
        const files = await fsp.readdir(directoryPath);
        const filePromises = files.map(filePath => processFile(path.join(directoryPath, filePath)));
        await Promise.all(filePromises);

        console.log('All files processed successfully.');
    } catch (error) {
        console.error('Error reading directory:', error);
    }
}

async function processFile(filePath) {
    if (!fs.existsSync(filePath)) return; // Handle deleted files

    const fileName = path.basename(filePath);

    try {
        const records = await readFileWithCache(filePath);

        // Simulate processing with external data sources
        const enhancedRecords = await enhanceWithExternalData(records);

        console.log(`Processed ${fileName}:`, enhancedRecords.length, 'records');

        // Optionally cache results
        cache[filePath] = enhancedRecords;
    } catch (error) {
        console.error(`Error processing file ${fileName}:`, error);
    }
}

async function readFileWithCache(filePath) {
    if (cache[filePath]) {
        return cache[filePath];
    }

    const stream = createReadStream(filePath);

    const records = [];
    try {
        await pipeline(
            stream,
            readline.createInterface({ input: stream }),
            (err) => { if (err) throw err; }
        );

        for await (const line of readline.createInterface({ input: stream })) {
            // Assuming each line is a record
            records.push(line);
        }
    } catch (error) {
        console.error(`Error reading file ${filePath}:`, error);
        throw error;
    }

    return records;
}

async function enhanceWithExternalData(records) {
    // Placeholder for enhancement logic, e.g., fetching data from an API
    // Simulate asynchronous enhancement
    await new Promise(resolve => setTimeout(resolve, 100));

    return records.map(record => ({ ...record, enhanced: true }));
}

// Usage example:
// processFilesInDirectory('/path/to/your/directory');

module.exports = { processFilesInDirectory };
