function renderScriptsAsFooter(scripts) {
    if (!Array.isArray(scripts)) {
        console.warn("Invalid input: Expected an array of script objects.");
        return '';
    }

    let footerHTML = '';

    for (let i = 0; i < scripts.length; i++) {
        const { src, type = "text/javascript", async = false, defer = false } = scripts[i] || {};

        if (typeof src !== 'string') {
            console.warn(`Warning: Script at index ${i} is missing a valid 'src' attribute.`);
            continue;
        }

        // Construct the script tag with attributes
        let scriptTag = `<script type="${type}"`;

        if (async) scriptTag += ` async`;
        if (defer) scriptTag += ` defer`;

        scriptTag += ` src="${src}"></script>`;

        footerHTML += scriptTag;
    }

    return `<div>${footerHTML}</div>`;
}

// Example usage:
const scripts = [
    { src: "https://example.com/script1.js" },
    { src: "https://example.com/script2.js", type: "module", async: true },
    { src: "invalid-url.js", defer: true }
];

console.log(renderScriptsAsFooter(scripts));
