import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.*;

class ServiceManager {
    private final Map<String, Service> services = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(10);
    private final Logger logger = new ExternalLogger();
    private final MessageNotifier notifier = new MessageNotifier();

    public void addService(String name, ServiceConfig config) {
        services.put(name, new Service(name, config));
    }

    public void start() throws InterruptedException {
        scheduler.scheduleAtFixedRate(this::manageServices, 0, 1, TimeUnit.SECONDS);
    }

    private void manageServices() {
        Random rand = new Random();
        LocalDateTime now = LocalDateTime.now();

        for (Service service : services.values()) {
            boolean shouldStart = rand.nextBoolean(); // Stochastic start/stop logic
            if (shouldStart && !service.isActive()) {
                try {
                    service.start();
                    logger.log("Started: " + service.getName() + " at " + now);
                } catch (Exception e) {
                    handleServiceError(service, e);
                }
            } else if (!shouldStart && service.isActive()) {
                service.stop(now);
                notifier.notifyServiceStop(service.getName(), now, service.getDuration());
                logger.log("Stopped: " + service.getName() + " at " + now);
            }
        }
    }

    private void handleServiceError(Service service, Exception e) {
        if (service.incrementRetryCount() <= 3) {
            try {
                Thread.sleep(1000); // Simple backoff strategy
                service.start();
            } catch (Exception retryEx) {
                logger.log("Failed to restart: " + service.getName(), retryEx);
            }
        } else {
            logger.log("Giving up on restarting: " + service.getName());
            service.resetRetryCount();
        }
    }

    public void shutdown() throws InterruptedException {
        scheduler.shutdown();
        scheduler.awaitTermination(10, TimeUnit.SECONDS);
    }
}

