define('CONFIG_DIR', __DIR__ . '/config');
define('CACHE_DIR', sys_get_temp_dir() . '/app_cache');

// Initialize Logger
function initializeLogger(LoggerInterface $logger): void {
    $logger->pushHandler(new StreamHandler(__DIR__ . '/logs/app.log', MonoLogger::DEBUG));
}

// Load Configuration based on environment or command-line arguments
function loadConfiguration($env = 'production'): array {
    $configPath = CONFIG_DIR . "/{$env}.php";
    if (!file_exists($configPath)) {
        throw new RuntimeException("Configuration file for {$env} not found.");
    }
    return require $configPath;
}

// Cache Configuration to optimize repeated access
function cacheConfiguration(array $config, string $cacheKey): void {
    $cacheFile = CACHE_DIR . "/{$cacheKey}.php";
    if (!is_dir(CACHE_DIR)) {
        mkdir(CACHE_DIR, 0755, true);
    }
    file_put_contents($cacheFile, '<?php return ' . var_export($config, true) . ';');
}

function getConfigurationFromCache(string $cacheKey): ?array {
    $cacheFile = CACHE_DIR . "/{$cacheKey}.php";
    if (file_exists($cacheFile)) {
        return require $cacheFile;
    }
    return null;
}

// Detect Configuration Changes and Invalidate Cache
function detectConfigChanges(array $config, string $cacheKey, LoggerInterface $logger): bool {
    $lastModified = filemtime(CONFIG_DIR . "/{$config['profile']}.php");
    if (!file_exists(CACHE_DIR . "/{$cacheKey}.cache")) {
        file_put_contents(CACHE_DIR . "/{$cacheKey}.cache", json_encode($lastModified));
        return true;
    }

    $cachedLastModified = json_decode(file_get_contents(CACHE_DIR . "/{$cacheKey}.cache"), true);
    if ($cachedLastModified !== $lastModified) {
        unlink(CACHE_DIR . "/{$cacheKey}.php");
        file_put_contents(CACHE_DIR . "/{$cacheKey}.cache", json_encode($lastModified));
        return true;
    }

    return false;
}

// Initialize Application Context
function initializeAppContext(array &$config, LoggerInterface $logger): void {
    if (detectConfigChanges($config, $config['profile'], $logger)) {
        cacheConfiguration($config, $config['profile']);
        $logger->info("Configuration reloaded for profile: " . $config['profile']);
    } else {
        $cachedConfig = getConfigurationFromCache($config['profile']);
        if ($cachedConfig !== null) {
            $config = $cachedConfig;
        }
    }
}

