<?php

function updateEmailPreferences($groupId) {
    $maxRetries = 3;
    $retryDelay = 100; // milliseconds

    $startMemory = memory_get_usage();
    $startTime = microtime(true);

    $successCount = 0;
    $errorMessages = [];
    $performanceMetrics = [];

    try {
        // Assume getDatabaseConnection() returns a connection to the distributed database
        $dbConnection = getDatabaseConnection();

        // Start transaction for consistency across services
        $dbConnection->beginTransaction();

        // Fetch user records for the given group ID
        $usersQuery = "SELECT id FROM users WHERE group_id = ?";
        $stmt = $dbConnection->prepare($usersQuery);
        $stmt->execute([$groupId]);

        while ($user = $stmt->fetch(PDO::FETCH_ASSOC)) {
            $userId = $user['id'];

            for ($retry = 0; $retry <= $maxRetries; $retry++) {
                try {
                    // Prepare update query
                    $updateQuery = "UPDATE users SET 
                                    email_preferences = ?,
                                    last_modified = NOW(),
                                    settings_version = ?
                                    WHERE id = ?";

                    $stmtUpdate = $dbConnection->prepare($updateQuery);

                    // Example values for demonstration; these would be dynamic in practice
                    $emailPreferences = 'new_preferences';
                    $settingsVersion = 2;

                    $stmtUpdate->execute([$emailPreferences, $settingsVersion, $userId]);

                    if ($stmtUpdate->rowCount() > 0) {
                        $successCount++;
                        break;
                    }
                } catch (Exception $e) {
                    // Log the exception for monitoring
                    error_log("Error updating user ID $userId: " . $e->getMessage());

                    if ($retry < $maxRetries) {
                        usleep($retryDelay * 1000); // Delay before retrying
                        continue;
                    } else {
                        $errorMessages[] = "Failed to update user ID $userId after $maxRetries attempts.";
                    }
                }
            }
        }

        // Commit transaction if all updates were successful
        $dbConnection->commit();
    } catch (Exception $e) {
        // Rollback in case of an error
        if ($dbConnection && method_exists($dbConnection, 'rollback')) {
            $dbConnection->rollback();
        }

        $errorMessages[] = "Transaction failed: " . $e->getMessage();
    }

    // Measure performance metrics
    $endTime = microtime(true);
    $endMemory = memory_get_usage();

    $executionTime = $endTime - $startTime;
    $memoryUsage = ($endMemory - $startMemory) / 1024; // Convert to KB

    $performanceMetrics['execution_time'] = $executionTime;
    $performanceMetrics['memory_usage_kb'] = $memoryUsage;

    // Log all operations
    error_log("Update operation completed for group ID $groupId");

    return [
        'success_count' => $successCount,
        'error_messages' => $errorMessages,
        'performance_metrics' => $performanceMetrics,
    ];
}

// Helper function to get a database connection (stub)
