// utils.js

const crypto = require('crypto');
const fs = require('fs');

const cache = new Map();

function generateSecureRandomStringAndHashPassword(charSet, length, password) {
  if (!charSet || typeof charSet !== 'string' || charSet.length === 0) {
    throw new Error('Character set must be a non-empty string.');
  }

  if (!Number.isInteger(length) || length <= 0) {
    throw new Error('Length must be a positive integer.');
  }

  const randomString = crypto.randomBytes(Math.ceil(length / charSet.length)).toString('base64').slice(0, length);
  const filteredRandomString = [...randomString].map(char => charSet[Math.floor(Math.random() * charSet.length)]).join('');

  const hash = crypto.createHash('sha256').update(password).digest('hex');

  return { randomString: filteredRandomString, hashedPassword: hash };
}

function fetchFileContentSynchronously(filePath) {
  if (cache.has(filePath)) {
    return cache.get(filePath);
  }

  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    cache.set(filePath, content);
    return content;
  } catch (error) {
    throw new Error(`Failed to read file at ${filePath}: ${error.message}`);
  }
}

module.exports = {
  generateSecureRandomStringAndHashPassword,
  fetchFileContentSynchronously
};
