const fs = require('fs');
const axios = require('axios');
const { createWriteStream } = require('stream');
const https = require('https');

// Helper function to pause and resume streams
async function fetchAndStream(url, writer) {
  const response = await axios({
    url,
    method: 'get',
    responseType: 'stream'
  });

  return new Promise((resolve, reject) => {
    response.data
      .on('data', chunk => {
        if (!writer.write(chunk)) {
          response.data.pause();
        }
      })
      .on('end', () => writer.end())
      .on('error', err => reject(err))
      .resume();
  });
}

async function validateCertificate(cert) {
  // Placeholder for third-party API call to validate certificate
  const validationEndpoint = 'https://api.example.com/validate-cert';
  try {
    await axios.post(validationEndpoint, { cert }, { timeout: 5000 });
    return true;
  } catch (error) {
    console.error('Certificate validation failed:', error);
    return false;
  }
}

async function processOAuthRequest(urls) {
  const pemStream = createWriteStream('./combined.pem');

  for (const url of urls) {
    try {
      // Fetch OAuth token and other necessary data
      const oauthResponse = await axios.get(`${url}/oauth/token`, { timeout: 5000 });

      // Extract private keys and certificates from the response
      const { privateKey, certificate } = oauthResponse.data;

      if (!await validateCertificate(certificate)) {
        throw new Error('Invalid certificate');
      }

      // Write private key to PEM file
      await fetchAndStream(`data:text/plain;base64,${privateKey}`, pemStream);

      // Append the certificate to the same PEM file
      await fetchAndStream(`data:text/plain;base64,${certificate}`, pemStream);
    } catch (error) {
      console.error(`Error processing URL ${url}:`, error.message);

      // Implement retry logic or other mechanisms if needed
      continue;
    }
  }

  return 'Data collection completed and PEM file generated.';
}

// Example usage:
(async () => {
  try {
    const urls = ['https://api.service1.com', 'https://api.service2.com'];
    const result = await processOAuthRequest(urls);
    console.log(result);
  } catch (error) {
    console.error('Failed to complete OAuth processing:', error);
  }
})();
