    u_char ip_address[16]; // Assuming IPv6, adjust if needed for IPv4
} SessionData;

typedef enum {
    SUCCESS,
    AUTHENTICATION_ERROR,
    DNS_RESOLUTION_ERROR,
    NETWORK_FAILURE,
    MEMORY_ALLOCATION_ERROR,
    TIMEOUT_EXPIRED
} ErrorCode;

ErrorCode authAndResolve(const char* hostname);

