    }

    void deallocate(void* ptr) {
        std::free(ptr);
    }
};

// Node structure for octree
struct OctreeNode {
    int featureSize;
    bool isLeaf;
    std::vector<OctreeNode*> children;
    // Other node-specific data

    OctreeNode(int size) : featureSize(size), isLeaf(true) {}
};

// Memory pool for frequently accessed nodes
class MemoryPool {
public:
    MemoryPool(size_t initialSize, size_t capacity) 
        : currentSize(initialSize), maxCapacity(capacity) {
        expandPool();
    }

    void* allocate() {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (freeList.empty()) {
            expandPool();
        }
        void* ptr = freeList.back();
        freeList.pop_back();
        return ptr;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(poolMutex);
        freeList.push_back(ptr);
    }

private:
    size_t currentSize;
    size_t maxCapacity;
    std::vector<void*> freeList;
    std::mutex poolMutex;

    void expandPool() {
        if (currentSize < maxCapacity) {
            size_t newSize = std::min(currentSize * 2, maxCapacity);
            for (size_t i = currentSize; i < newSize; ++i) {
                freeList.push_back(allocator.allocate(sizeof(OctreeNode)));
            }
            currentSize = newSize;
        }
    }

    CustomAllocator allocator;
};

// Octree class
class Octree {
public:
    Octree(int featureSize, int numLeafNodes, size_t dataCapacity)
        : root(nullptr), featureSize(featureSize) {
        memoryPool = std::make_unique<MemoryPool>(initialPoolSize, dataCapacity);
        initializeOctree(numLeafNodes);
    }

    ~Octree() {
        // Cleanup nodes
    }

private:
    OctreeNode* root;
    int featureSize;
    std::unique_ptr<MemoryPool> memoryPool;

    static constexpr size_t initialPoolSize = 1024;

    void initializeOctree(int numLeafNodes) {
        root = allocateNode(featureSize);
        root->isLeaf = false;
        // Initialize children based on numLeafNodes
        for (int i = 0; i < 8; ++i) {
            root->children.push_back(allocateNode(featureSize));
        }
    }

    OctreeNode* allocateNode(int size) {
        void* mem = memoryPool->allocate();
        return new (mem) OctreeNode(size);
    }

    // Implement other required functionalities
};

// Thread-safe lazy initialization
class LazyOctree : public Octree {
public:
    using Octree::Octree;

    OctreeNode* getOrCreateNode(OctreeNode* parent, int index) {
        std::lock_guard<std::mutex> lock(mutex);
        if (!parent->children[index]) {
            parent->children[index] = allocateNode(featureSize);
        }
        return parent->children[index];
    }

private:
    std::mutex mutex;
};

// Main function to test the octree
int main() {
    int featureSize = 10;
    int numLeafNodes = 1000;
