// Define a simple DOM node structure for demonstration purposes.
typedef struct DomNode {
    char* class;
    char* id;
    char* text_content;  // For simplicity, assume text content is directly stored.
    size_t num_children;
    struct DomNode** children;
} DomNode;

// Function prototype for processing each node.
int processNode(DomNode* node, char** buffer, size_t limit);

// Main function to process the DOM tree.
char* processString(char* buffer, size_t size_limit, DomNode* root) {
    if (!root || !buffer || size_limit == 0) return NULL;

    // Initialize the result string buffer.
    *buffer = malloc(size_limit + 1); 
    if (*buffer == NULL) return NULL;
    **buffer = '\0'; 

    if (processNode(root, &buffer, size_limit) != 0) {
        free(*buffer);
        *buffer = NULL;
    }

    return *buffer;
}

// Helper function to recursively process each DOM node.
int processNode(DomNode* node, char** buffer, size_t limit) {
    if (node == NULL || strlen(*buffer) >= limit - 1) return 1;

    // Example selector check: matches nodes with specific class or id
    const char* classToMatch = "target-class";
    const char* idToMatch = "target-id";

    size_t current_length = strlen(*buffer);

    if (node->class && strcmp(node->class, classToMatch) == 0 ||
        node->id && strcmp(node->id, idToMatch) == 0) {

        // Ensure there's space in the buffer before appending.
        if (current_length + strlen(classToMatch) >= limit - 1) {
            free(*buffer);
            *buffer = NULL;
            return 1; 
        }

        strcat(*buffer, node->class ? node->class : idToMatch); // Append class or ID to the buffer.

        if (strlen(*buffer) >= limit - 1) { 
            free(*buffer);
            *buffer = NULL;
            return 1;
        }
    }

    for (size_t i = 0; i < node->num_children && strlen(*buffer) < limit - 1; ++i) {
        if (processNode(node->children[i], buffer, limit)) { 
            // Propagate failure up the call stack.
            return 1;
        }
    }

    return 0; // Success
}
