// Main function to process the image and compute hash
void processImageAndComputeHash(const char *imagePath, const char *format, const char *hashInput) {
    // Parse the image based on provided format
    ImageMetadata metadata = parseImage(imagePath, format);

    // Compute MD5 hash for the given string input
    char* hashResult = computeMD5Hash(hashInput);

    if (metadata.bitsPerSample == -1) {
        fprintf(stderr, "Error: Unsupported or invalid image format\n");
    } else {
        printf("Image Metadata:\n");
        printf("Bits Per Sample: %d\n", metadata.bitsPerSample);
        printf("Samples Per Pixel: %d\n", metadata.samplesPerPixel);
        printf("Extra Samples: %d\n", metadata.extraSamples);
    }

    if (hashResult != NULL) {
        printf("MD5 Hash of Input String: %s\n", hashResult);
        free(hashResult); // Free the allocated memory for the hash
    } else {
        fprintf(stderr, "Error: Invalid input string for hashing\n");
    }
}

// Function to parse image and extract metadata
ImageMetadata parseImage(const char *filePath, const char *format) {
    ImageMetadata metadata = {-1, -1, -1}; // Initialize with error values

    if (strcmp(format, "TIFF") == 0) {
        // Implement TIFF parsing logic here
        // Example: Extract bitsPerSample, samplesPerPixel, extraSamples from TIFF file
        // Populate the metadata struct accordingly
        metadata.bitsPerSample = 8; // Dummy data
        metadata.samplesPerPixel = 3;
        metadata.extraSamples = 1;
    }
    else {
        fprintf(stderr, "Unsupported image format: %s\n", format);
    }

    return metadata;
}

// Function to compute MD5 hash of a given string input
char* computeMD5Hash(const char *inputString) {
    if (inputString == NULL || strlen(inputString) == 0) {
        return NULL; // Return NULL for invalid input strings
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)inputString, strlen(inputString), digest);

    char *hash = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (hash == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(hash + (i * 2), "%02x", digest[i]);
    }

    hash[MD5_DIGEST_LENGTH * 2] = '\0'; // Null-terminate the string
    return hash;
}
```

This code provides a basic structure for parsing images and computing an MD5 hash, with placeholder logic where specific parsing details need to be implemented. The `ImageMetadata` struct is designed to hold essential image metadata, while error handling ensures informative feedback is given for unsupported formats or invalid inputs.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_PATH_LENGTH 255

// Function to check if a character is alphanumeric
int is_alphanumeric(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9');
}

// Function to get the last alphanumeric character in a string and its index
char *get_last_alphanumeric(const char *str, int *last_index) {
    const char *last_alpha = NULL;
    for (int i = 0; str[i] != '\0'; ++i) {
        if (is_alphanumeric(str[i])) {
            last_alpha = &str[i];
            *last_index = i;
        }
    }
    return (char *)last_alpha;
}

// Function to dynamically rename files
void dynamic_rename_files(const char *directory_path) {
    DIR *dir = opendir(directory_path);
    if (!dir) {
        perror("opendir");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip "." and ".."
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[MAX_PATH_LENGTH];
        snprintf(full_path, sizeof(full_path), "%s/%s", directory_path, entry->d_name);

        struct stat file_stat;
        if (stat(full_path, &file_stat) != 0) {
            perror("stat");
            continue;
        }

        if (!S_ISREG(file_stat.st_mode)) // Skip non-regular files
            continue;

        const char *filename = strrchr(full_path, '/');
        if (!filename)
            filename = full_path; // If no '/', it's in the root directory

        int last_alpha_index = -1;
        char *last_alphanumeric = get_last_alphanumeric(filename, &last_alpha_index);

        int num_digits = 0;
        int non_alpha_count = 0;

        if (last_alphanumeric) {
            for (int i = 0; filename[i] != '\0'; ++i) {
                if (isdigit(filename[i]))
                    num_digits++;
                else if (!is_alphanumeric(filename[i]) && i < last_alpha_index)
                    non_alpha_count++;
            }
        }

        char new_extension[MAX_PATH_LENGTH];
        snprintf(new_extension, sizeof(new_extension), "%d_%d_%d", 
                 (last_alphanumeric ? *last_alphanumeric : '#'), num_digits, non_alpha_count);

        // Construct the new filename
        char base_filename[MAX_PATH_LENGTH];
        strncpy(base_filename, full_path, last_alpha_index + 1);
        base_filename[last_alpha_index + 1] = '\0';

        char new_full_path[MAX_PATH_LENGTH];
        snprintf(new_full_path, sizeof(new_full_path), "%s.%s", base_filename, new_extension);

        // Rename the file
        if (rename(full_path, new_full_path) != 0) {
            perror("rename");
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    dynamic_rename_files(argv[1]);

    return EXIT_SUCCESS;
}
