// Error handling function
void handle_errors(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

// Memory allocation and deallocation functions
void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) handle_errors("Memory allocation failed");
    return ptr;
}

void free_memory(void *ptr) {
    free(ptr);
}

// Thread-safe wrapper for cryptographic operations
pthread_mutex_t lock;

int thread_safe_operation(EVP_CIPHER_CTX **ctx, const unsigned char *key, int key_length, const unsigned char *iv, int operation_type) {
    pthread_mutex_lock(&lock);

    EVP_CIPHER_CTX *new_ctx = EVP_CIPHER_CTX_new();
    if (!new_ctx) handle_errors("Failed to create cipher context");

    switch (operation_type) {
        case 1: // AES Encryption
            if (EVP_EncryptInit_ex(new_ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1)
                handle_errors("AES encryption initialization failed");
            break;
        case 2: // Camellia Decryption
            if (EVP_DecryptInit_ex(new_ctx, EVP_camellia_256_cbc(), NULL, key, iv) != 1)
                handle_errors("Camellia decryption initialization failed");
            break;
        // Add other cases as needed
    }

    *ctx = new_ctx;
    pthread_mutex_unlock(&lock);
    return 0;
}

// HMAC SHA-256 function
void hmac_sha256(const unsigned char *key, size_t key_len, const unsigned char *data, size_t data_len, unsigned char *mac, unsigned int *mac_len) {
    HMAC(EVP_sha256(), key, key_len, data, data_len, mac, mac_len);
}

// RSA encryption and decryption
int rsa_encrypt(RSA *rsa, const unsigned char *plaintext, size_t plaintext_len, unsigned char **encrypted_data, size_t *data_len) {
    *encrypted_data = allocate_memory(RSA_size(rsa));
    int result = RSA_public_encrypt(plaintext_len, plaintext, *encrypted_data, rsa, RSA_PKCS1_OAEP_PADDING);
    if (result == -1) handle_errors("RSA encryption failed");
    *data_len = result;
    return 0;
}

int rsa_decrypt(RSA *rsa, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **decrypted_data, size_t *data_len) {
    *decrypted_data = allocate_memory(RSA_size(rsa));
    int result = RSA_private_decrypt(ciphertext_len, ciphertext, *decrypted_data, rsa, RSA_PKCS1_OAEP_PADDING);
    if (result == -1) handle_errors("RSA decryption failed");
    *data_len = result;
    return 0;
}

// ECDH key exchange
void ecdh_key_exchange(EVP_PKEY *own_key, EVP_PKEY *peer_key, unsigned char **shared_secret, size_t *secret_len) {
    *shared_secret = allocate_memory(EVP_PKEY_size(peer_key));
    if (ECDH_compute_key(*shared_secret, secret_len, peer_key->pkey.ptr, own_key, NULL) != 1)
        handle_errors("ECDH key exchange failed");
}

// Example function to demonstrate API usability
void example_usage() {
    pthread_mutex_init(&lock, NULL);

    // AES key and initialization vector setup
    unsigned char aes_key[32] = { /* 256-bit key */ };
    unsigned char iv[AES_BLOCK_SIZE] = { /* Initialization Vector */ };

    EVP_CIPHER_CTX *aes_ctx;
    thread_safe_operation(&aes_ctx, aes_key, sizeof(aes_key), iv, 1);

    // HMAC setup
    unsigned char mac[EVP_MAX_MD_SIZE];
    unsigned int mac_len;
    hmac_sha256("key", 3, "data", 4, mac, &mac_len);

    // RSA key loading and usage (simplified)
    FILE *rsa_pub_file = fopen("public.pem", "r");
    if (!rsa_pub_file) handle_errors("Failed to open RSA public key file");
    RSA *rsa_pub_key = PEM_read_RSA_PUBKEY(rsa_pub_file, NULL, NULL, NULL);
    fclose(rsa_pub_file);

    unsigned char encrypted_data[256];
    size_t encrypted_len;
    rsa_encrypt(rsa_pub_key, (unsigned char *)"plaintext", strlen("plaintext"), &encrypted_data, &encrypted_len);

    // Cleanup
    EVP_CIPHER_CTX_free(aes_ctx);
    RSA_free(rsa_pub_key);
    free_memory(encrypted_data);
    pthread_mutex_destroy(&lock);
}

int main() {
    // Initialize OpenSSL library
    if (OPENSSL_init_crypto(0, NULL) != 1)
        handle_errors("OpenSSL initialization failed");

    example_usage();

    return 0;
}
