                   HasReadWritePermissions(dirInfo);
        }
        catch (Exception ex)
        {
            LogError("Directory validation failed: " + ex.Message);
            return false;
        }
    }

    private bool HasReadWritePermissions(DirectoryInfo directoryInfo)
    {
