import java.io.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class SystemMonitorApp {
    private final ExecutorService executor;
    private final BlockingQueue<Runnable> scriptQueue = new LinkedBlockingQueue<>();
    private volatile boolean running = true;

    public static void main(String[] args) {
        new SystemMonitorApp().start();
    }

    public SystemMonitorApp() {
        this.executor = Executors.newFixedThreadPool(4);
    }

    public void start() {
        Thread monitorThread = new Thread(this::processScripts);
        monitorThread.start();

        Runtime.getRuntime().addShutdownHook(new Thread(() -> shutdown()));
    }

    private void processScripts() {
        while (running || !scriptQueue.isEmpty()) {
            try {
                Runnable script = scriptQueue.poll(1, TimeUnit.SECONDS);
                if (script != null) {
                    executeScriptWithRetry(script);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void executeScriptWithRetry(Runnable script) {
        int attempts = 0;
        boolean success = false;

        while (attempts < 3 && !success) {
            try {
                executor.submit(script).get(5, TimeUnit.SECONDS);
                log.info("Successfully executed: " + ((RunnableCommand) script).getDescription());
                success = true;
            } catch (ExecutionException | InterruptedException e) {
                attempts++;
                log.warning("Attempt " + attempts + " failed for: " + ((RunnableCommand) script).getDescription() + ". Error: " + e.getMessage());
            }
        }

        if (!success) {
            log.severe("Failed to execute after retries: " + ((RunnableCommand) script).getDescription());
        }
    }

    public void addScript(Runnable script) {
        scriptQueue.offer(script);
    }

    private void shutdown() {
        running = false;
        executor.shutdownNow();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                log.warning("Executor did not terminate in the specified time.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        log.info("Application shutdown gracefully.");
    }

    private static class RunnableCommand implements Runnable {
        private final String description;
        private final String command;

        public RunnableCommand(String description, String command) {
            this.description = description;
            this.command = command;
        }

        @Override
        public void run() {
            try (Process process = Runtime.getRuntime().exec(command)) {
                logOutput(process.getInputStream());
                logError(process.getErrorStream());
            } catch (IOException e) {
                System.err.println("Failed to execute command: " + description);
                throw new RuntimeException(e);
            }
        }

        private void logOutput(InputStream inputStream) throws IOException {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            }
        }

        private void logError(InputStream errorStream) throws IOException {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(errorStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.err.println(line);
                }
            }
        }

        public String getDescription() {
            return description;
        }
    }

    private static final Logger log = Logger.getLogger(SystemMonitorApp.class.getName());

    static {
        try {
            FileHandler fileHandler = new FileHandler("system_monitor.log", true);
            fileHandler.setFormatter(new SimpleFormatter());
            log.addHandler(fileHandler);
        } catch (IOException e) {
            System.err.println("Failed to initialize logging: " + e.getMessage());
        }
    }
}
