// Example configuration for allowed issuers and audience
const char* const allowed_issuers[] = {"trustedIssuer1", "trustedIssuer2"};
size_t allowed_issuers_count = sizeof(allowed_issuers) / sizeof(char*);

const char* intended_audience = "yourServiceAudience";

// Function to check if issuer is trusted
int is_trusted_issuer(const char* iss) {
    for (size_t i = 0; i < allowed_issuers_count; ++i) {
        if (strcmp(iss, allowed_issuers[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// Mock function to validate subject by querying external service
int is_valid_subject(const char* sub) {
    // Simulate network request and possible failure
    // For now, assume all subjects are valid for demonstration purposes
    return (sub != NULL && strlen(sub) > 0);
}

// Function to check expiration time with clock skew tolerance
int is_token_not_expired(time_t exp, int clock_skew_seconds) {
    time_t current_time = time(NULL);
    return (exp > current_time + clock_skew_seconds);
}

// JWT validation function
int validate_jwt(const char* jwt_string, int clock_skew_seconds) {
    json_error_t error;
    json_t *json_root = json_loads(jwt_string, 0, &error);

    if (!json_root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return 0; // Invalid token
    }

    json_t* iss = json_object_get(json_root, "iss");
    json_t* sub = json_object_get(json_root, "sub");
    json_t* aud = json_object_get(json_root, "aud");
    json_t* exp = json_object_get(json_root, "exp");

    if (!json_is_string(iss) || !is_trusted_issuer(json_string_value(iss))) {
        goto cleanup;
    }
    if (!json_is_string(sub) || !is_valid_subject(json_string_value(sub))) {
        goto cleanup;
    }
    if (aud && json_is_array(aud)) {
        size_t index;
        json_t *value;
        json_array_foreach(aud, index, value) {
            if (json_is_string(value) && strcmp(json_string_value(value), intended_audience) == 0) {
                goto check_exp;
            }
        }
    } else if (!aud || !json_is_string(aud) || strcmp(json_string_value(aud), intended_audience) != 0) {
        fprintf(stderr, "Audience mismatch\n");
        goto cleanup;
    }

check_exp:
    if (!json_is_integer(exp) || json_integer_value(exp) <= 0) {
        fprintf(stderr, "Invalid expiration time\n");
        goto cleanup;
    }
    if (!is_token_not_expired(json_integer_value(exp), clock_skew_seconds)) {
        fprintf(stderr, "Token has expired\n");
        goto cleanup;
    }

    return 1; // Token is valid

cleanup:
    json_decref(json_root);
    return 0; // Invalid token
}

int main() {
    const char* jwt = "{\"iss\":\"trustedIssuer1\",\"sub\":\"user123\",\"aud\":[\"yourServiceAudience\"],\"exp\":1699999999}";

    if (validate_jwt(jwt, 300)) { // Allow a clock skew of 5 minutes
        printf("JWT is valid.\n");
    } else {
        printf("JWT is invalid or expired.\n");
    }

    return 0;
}
```

