using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json.Linq;

public class MessageProcessor
{
    private static readonly log4net.ILog logger = log4net.LogManager.GetLogger(typeof(MessageProcessor));

    public bool ProcessMessage(string base64EncodedMessage, byte[] key, byte[] iv, string schemaJson)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage) || key == null || iv == null || string.IsNullOrEmpty(schemaJson))
        {
            logger.Error("Invalid input parameters.");
            return false;
        }

        try
        {
            // Decode the message from Base64
            byte[] encryptedData = Convert.FromBase64String(base64EncodedMessage);
            logger.Info("Decoded message from Base64.");

            // Decrypt using Triple DES
            string decryptedMessage = DecryptTripleDES(encryptedData, key, iv);
            logger.Info("Decrypted message using Triple DES.");

            // Validate against schema
            bool isValid = ValidateSchema(decryptedMessage, schemaJson);
            if (isValid)
            {
                logger.Info("Message validated successfully.");
                return true;
            }
            else
            {
                logger.Warn("Message validation failed.");
                return false;
            }
        }
        catch (Exception ex)
        {
            logger.Error($"Error processing message: {ex.Message}");
            return false;
        }
    }

    private string DecryptTripleDES(byte[] data, byte[] key, byte[] iv)
    {
        using (TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider())
        {
            des.Key = key;
            des.IV = iv;
            des.Mode = CipherMode.CBC;

            ICryptoTransform decryptor = des.CreateDecryptor(des.Key, des.IV);

            using (MemoryStream ms = new MemoryStream(data))
            using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            using (StreamReader sr = new StreamReader(cs))
            {
                return sr.ReadToEnd();
            }
        }
    }

    private bool ValidateSchema(string messageContent, string schemaJson)
    {
        try
        {
            var messageObj = JObject.Parse(messageContent);
            var schemaObj = JObject.Parse(schemaJson);

            foreach (var property in schemaObj.Properties())
            {
                if (!messageObj.TryGetValue(property.Name, out JToken value))
                {
                    logger.Warn($"Missing required field: {property.Name}");
                    return false;
                }
            }

            return true;
        }
        catch (Exception ex)
        {
            logger.Error($"Schema validation error: {ex.Message}");
            return false;
        }
    }
}
```

### Key Points:
- **Logging**: Uses `log4net` for detailed logging at each step.
- **Error Handling**: Gracefully handles invalid inputs and exceptions.
- **Decryption**: Utilizes Triple DES with provided key and IV.
- **Schema Validation**: Compares JSON message against a schema using `Newtonsoft.Json`.
- **Concurrency**: Designed to be thread-safe, suitable for concurrent processing.
- **Extensibility**: Easy integration of future encryption algorithms by modifying the decryption method.']

['```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileProcessor
{
    public static async Task<Dictionary<string, string>> ProcessFileHashesAsync(IEnumerable<string> filePaths)
    {
        var hashDict = new ConcurrentDictionary<string, string>();
        var processedCount = 0;

        foreach (var path in ResolvePaths(filePaths))
        {
            try
            {
                var absolutePath = Path.GetFullPath(path);

                if (!hashDict.ContainsKey(absolutePath) && File.Exists(absolutePath))
                {
                    var fileHash = await ComputeFileSHA256Async(absolutePath);

                    hashDict[absolutePath] = fileHash;
                    processedCount++;

                    if (processedCount % 100 == 0)
                    {
                        Console.WriteLine($"Processed {processedCount} files.");
                    }
                }
            }
            catch (IOException ex)
            {
                Console.WriteLine($"I/O Error processing file: {ex.Message}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing file: {ex.Message}");
            }
        }

        return hashDict;
    }

    private static IEnumerable<string> ResolvePaths(IEnumerable<string> filePaths)
    {
        foreach (var path in filePaths)
        {
            if (!Path.IsPathRooted(path))
            {
                var resolvedPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), path);
                yield return resolvedPath;
            }
            else
            {
                yield return path;
            }
        }
    }

    private static async Task<string> ComputeFileSHA256Async(string filePath)
    {
        using (var sha256 = SHA256.Create())
        {
            using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, useAsync: true))
            {
                var hashBytes = await sha256.ComputeHashAsync(stream);
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            }
        }
    }
}
```

This code defines a `ProcessFileHashesAsync` function that processes file paths to compute their SHA-256 hashes, storing the results in a thread-safe dictionary. It handles I/O exceptions gracefully and updates progress every 100 files processed. The function resolves relative paths using environment variables and ensures efficient resource usage.']

