    public string Decrypt(string ciphertextBase64, string ivBase64, bool useCachedKey = true)
    {
        try
        {
            var iv = Convert.FromBase64String(ivBase64);
            byte[] key;

            if (useCachedKey && _keyCache.TryGetValue(_configuration["DecryptionKey"], out key))
            {
                _logger.LogInformation("Using cached decryption key.");
            }
            else
            {
                key = RetrieveOrGenerateKey();
                _keyCache[_configuration["DecryptionKey"]] = key;
                _logger.LogInformation("Generated or retrieved new decryption key.");
            }

            using var aes = Aes.Create();
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;

