    let offset = 0;
    const buffer = allocateAndCheck(1024); // Start with an arbitrary size

    const writeInt64LE = (buffer, value, offset) => {
      for (let i = 7; i >= 0; i--) {
        buffer[offset + i] = value & 255;
        value >>= 8;
      }
    };

    const writeInt32LE = (buffer, value, offset) => {
      for (let i = 3; i >= 0; i--) {
        buffer[offset + i] = value & 255;
        value >>= 8;
      }
    };

    // Serialize URL
    let urlBytes = Buffer.from(url);
    writeInt32LE(buffer, urlBytes.length, offset);
    offset += 4;
    buffer.copy(buffer, offset, 0, urlBytes.length);
    offset += urlBytes.length;

    // Serialize long offsets list
    const longOffsets = [1234567890123456789n, 9876543210987654321n];
    writeInt32LE(buffer, longOffsets.length, offset);
    offset += 4;
    longOffsets.forEach(offsetValue => {
      writeInt64LE(buffer, Number(offsetValue), offset);
      offset += 8;
    });

    // Serialize int keys list
    const intKeys = [1001, -2002, 3003];
    writeInt32LE(buffer, intKeys.length, offset);
    offset += 4;
    intKeys.forEach(key => {
      writeInt32LE(buffer, key, offset);
      offset += 4;
    });

    // Serialize records
    const records = [{ value: 5555, offset: 7777n }];
    writeInt32LE(buffer, records.length, offset);
    offset += 4;
    records.forEach(record => {
      writeInt32LE(buffer, record.value, offset);
      offset += 4;
      writeInt64LE(buffer, Number(record.offset), offset);
      offset += 8;
    });

    return buffer.slice(0, offset); // Trim to actual size
  }

  function deserialize(buffer) {
    let offset = 0;

    const readInt32LE = (buffer, offset) => {
      let value = 0;
      for (let i = 3; i >= 0; i--) {
        value |= buffer[offset + i] << (i * 8);
      }
      return { value, nextOffset: offset + 4 };
    };

    const readInt64LE = (buffer, offset) => {
      let value = 0n;
      for (let i = 7; i >= 0; i--) {
        value |= BigInt(buffer[offset + i]) << (i * 8n);
      }
      return { value: Number(value), nextOffset: offset + 8 };
    };

    const validateChecksum = (original, checksum) => original === checksum;

    // Deserialize URL
    let { value: urlLength, nextOffset } = readInt32LE(buffer, offset);
    offset = nextOffset;
    const urlBytes = buffer.slice(offset, offset + urlLength);
    offset += urlLength;

    // Deserialize long offsets list
    let { value: longOffsetsCount, nextOffset: nextLongOffset } = readInt32LE(buffer, offset);
    offset = nextLongOffset;
    const longOffsets = [];
    for (let i = 0; i < longOffsetsCount; i++) {
      let { value: longValue, nextOffset } = readInt64LE(buffer, offset);
      longOffsets.push(BigInt(longValue));
      offset = nextOffset;
    }

    // Deserialize int keys list
    let { value: intKeysCount, nextOffset: nextIntKeyOffset } = readInt32LE(buffer, offset);
    offset = nextIntKeyOffset;
    const intKeys = [];
    for (let i = 0; i < intKeysCount; i++) {
      let { value: intValue, nextOffset } = readInt32LE(buffer, offset);
      intKeys.push(intValue);
      offset = nextOffset;
    }

    // Deserialize records
    let { value: recordCount, nextOffset: nextRecordOffset } = readInt32LE(buffer, offset);
    offset = nextRecordOffset;
    const records = [];
    for (let i = 0; i < recordCount; i++) {
      let { value: recordValue, nextOffset: nextRecordValOffset } = readInt32LE(buffer, offset);
      let { value: recordOffset, nextOffset: nextRecordOffsOffset } = readInt64LE(buffer, nextRecordValOffset);
      records.push({ value: recordValue, offset: BigInt(recordOffset) });
      offset = nextRecordOffsOffset;
    }

    // Validate checksum
    const checksumOriginal = crypto.createHash('sha256').update(buffer.slice(0, -32)).digest();
    const checksumBuffer = buffer.slice(-32);
    const checksumDeserialized = crypto.createHash('sha256').update(checksumBuffer).digest();

    if (!validateChecksum(checksumOriginal.toString(), checksumDeserialized.toString())) {
      throw new Error('Data integrity check failed');
    }

    return { url: urlBytes.toString(), longOffsets, intKeys, records };
  }

  try {
    // Seed random number generator
    Math.seedrandom(seedRandom());

    const serializedData = serialize({});

    // Add checksum for data integrity validation
    const checksum = crypto.createHash('sha256').update(serializedData).digest();
    const finalBuffer = Buffer.concat([serializedData, checksum]);

    // Upload file with retry logic
    let uploadedUrl;
    let attempts = 0;
    const maxAttempts = 3;

    while (attempts < maxAttempts) {
      try {
        uploadedUrl = await fileUploader.upload(finalBuffer);
        break;
      } catch (uploadError) {
        attempts++;
        if (attempts === maxAttempts) throw uploadError;
      }
    }

    return uploadedUrl;

  } catch (error) {
    console.error('Error:', error.message);
    // Cleanup or handle cleanup logic here
    throw error;
  }
}

// Usage example:
createStructure('https://example.com/file.txt')
  .then(uploadedUrl => console.log('Uploaded file URL:', uploadedUrl))
  .catch(error => console.error('Failed to upload:', error));
```

### Key Points

- **Memory Management:** The function checks the allocated buffer size against a maximum limit.
- **Serialization & Deserialization:** Handles endianness and includes checksum for data integrity validation.
- **Error Handling:** Includes retry logic for network interruptions and thorough error handling during memory operations.
- **Resource Cleanup:** Error handling ensures cleanup logic can be implemented to prevent resource leaks."]

["Here is a modular JavaScript function that executes custom shell commands using Node.js's `child_process` module. The function dynamically handles command-line arguments, supports centralized logging via an external logger (assumed to be provided), manages outputs efficiently, and considers system performance by limiting concurrency.

```javascript
const { spawn } = require('child_process');
const os = require('os');

// Assuming a logging service is available as a module for centralized logging.
const logger = {
  info: console.log,
  error: console.error,
};

const MAX_CONCURRENT_COMMANDS = os.cpus().length;

class CommandExecutor {
  constructor() {
    this.activeCommands = new Set();
  }

  logCommand(command, args) {
    logger.info(`Executing command: ${command} with arguments: ${args.join(' ')}`);
  }

  handleOutput(childProcess, callback) {
    let stdoutBuffer = '';
    let stderrBuffer = '';

    childProcess.stdout.on('data', (data) => {
      stdoutBuffer += data.toString();
    });

    childProcess.stderr.on('data', (data) => {
      stderrBuffer += data.toString();
    });

    childProcess.on('close', (code) => {
      if (code === 0) {
        logger.info(stdoutBuffer);
        callback(null, stdoutBuffer);
      } else {
        logger.error(`Command failed with code ${code}: ${stderrBuffer}`);
        callback(new Error(stderrBuffer), null);
      }

      this.activeCommands.delete(childProcess.pid);
    });
  }

  execute(command, args = [], callback) {
    if (this.activeCommands.size >= MAX_CONCURRENT_COMMANDS) {
      return logger.error('Maximum concurrent commands reached. Try again later.');
    }

    const childProcess = spawn(command, args);

    this.logCommand(command, args);
    this.activeCommands.add(childProcess.pid);

    this.handleOutput(childProcess, callback);
  }
}

module.exports = CommandExecutor;
```

### Usage Example

```javascript
const CommandExecutor = require('./CommandExecutor');
const executor = new CommandExecutor();

executor.execute('ls', ['-la'], (err, output) => {
  if (err) {
    console.error(`Error: ${err.message}`);
  } else {
    console.log(`Output: ${output}`);
  }
});
```

This implementation considers system load by limiting concurrent commands to the number of CPU cores. It logs command execution and handles outputs efficiently, making it easy to extend with additional features or logging mechanisms in the future."]

