// Function to initialize a configuration directory and set an environment variable.
fn initialize_config_dir(dir_name: &str) -> Result<(), String> {
    let mut retries = 5;
    let base_sleep_time = Duration::from_millis(100);

    // Get current path from environment or create a default one
    let env_var_name = "CONFIG_DIR_PATH";
    let existing_path = env::var(env_var_name).ok();

    loop {
        let dir_path = match existing_path {
            Some(path) => PathBuf::from(path),
            None => Path::new(&format!("./{}", dir_name)).to_owned(),
        };

        // Check if directory exists or attempt creation
        if dir_path.exists() && dir_path.is_dir() {
            info!("Using existing configuration directory at {:?}", dir_path);
            break;
        } else {
            match fs::create_dir_all(&dir_path) {
                Ok(_) => info!("Created configuration directory at {:?}", dir_path),
                Err(e) => {
                    if e.kind() == ErrorKind::AlreadyExists {
                        info!("Directory already exists at {:?}. Retrying...", dir_path);
                        continue;
                    } else {
                        error!("Failed to create directory: {}", e);
                        cleanup_partial_dir(&dir_path)?;
                        return Err(format!("Failed to create config directory: {:?}", e));
                    }
                },
            };
        }

        // Set the environment variable
        if let Err(e) = env::set_var(env_var_name, dir_path.to_str().unwrap()) {
            error!("Failed to set environment variable: {}", e);
            cleanup_partial_dir(&dir_path)?;
            return Err(format!("Failed to set environment variable: {:?}", e));
        }

        // Sync with external config service and handle potential errors
        match sync_with_config_service(dir_path.to_str().unwrap_or_default()) {
            Ok(_) => info!("Successfully synchronized with config service."),
            Err(e) => {
                warn!("Configuration service synchronization failed: {}", e);
                // Log error but continue local operation
            }
        }

        break;
    }

    if retries > 0 {
        let sleep_time = base_sleep_time * (5 - retries + 1); // Exponential backoff
        thread::sleep(sleep_time);
    }

    Ok(())
}

// Helper function to clean up partially initialized directories.
fn cleanup_partial_dir(dir_path: &Path) -> Result<(), String> {
    info!("Cleaning up partial directory at {:?}", dir_path);

    if let Err(e) = fs::remove_dir_all(&dir_path) {
        error!("Failed to clean up directory: {}", e);
        return Err(format!("Cleanup failed: {:?}", e));
    }

    Ok(())
}

fn main() -> Result<(), String> {
    // Initialize logging (typically, this would be more sophisticated)
    env_logger::init();

    let config_dir = "my_config_directory";

    if let Err(e) = initialize_config_dir(config_dir) {
        error!("Error initializing configuration directory: {}", e);
    }

    Ok(())
}
```

### Key Points:

