namespace RandomManager {
    class SingletonRandomManager {
    private:
        static std::mt19937 rng;
        static std::mutex mtx;
        static bool initialized;

        int seedValue;

        SingletonRandomManager(int seed) : seedValue(seed) {
            rng.seed(seedValue);
        }

        ~SingletonRandomManager() {}

        // Private constructor to prevent instantiation
        SingletonRandomManager(const SingletonRandomManager&) = delete;
        SingletonRandomManager& operator=(const SingletonRandomManager&) = delete;

    public:
        static SingletonRandomManager& getInstance(int seed) {
            std::lock_guard<std::mutex> lock(mtx);
            if (!initialized) {
                initialized = true;
                instance = new SingletonRandomManager(seed);
            }
            return *instance;
        }

        int getRandomInt() {
            std::uniform_int_distribution<int> dist(0, 100);
            return dist(rng);
        }

    private:
        static SingletonRandomManager* instance;

    public:
        static void testFunctionality() {
            // Unit tests for randomness and edge cases
            int seed = 42;
            SingletonRandomManager& manager = getInstance(seed);

            std::cout << "Generated random number: " << manager.getRandomInt() << std::endl;

            // Additional tests can be added here
        }
    };

    std::mt19937 SingletonRandomManager::rng{};
    std::mutex SingletonRandomManager::mtx;
    bool SingletonRandomManager::initialized = false;
    SingletonRandomManager* SingletonRandomManager::instance = nullptr;
}

class XMLHandler {
public:
    void parseXMLAndHandleDirectory(const std::string& xmlContent, const std::string& elementName) {
        try {
            xercesc::XMLPlatformUtils::Initialize();
            xercesc::XercesDOMParser parser;

            parser.parseFromString(xmlContent.c_str());
            xercesc::DOMNode* doc = parser.getDocument();

            if (!doc) {
                std::cerr << "Failed to parse XML content." << std::endl;
                return;
            }

            xercesc::DOMElement* root = dynamic_cast<xercesc::DOMElement*>(doc->getDocumentElement());

            xercesc::DOMNodeList* nodes = root->getElementsByTagName(elementName.c_str());
            int length = nodes->getLength();

            if (length == 0) {
                std::cerr << "Warning: No elements found with name '" << elementName << "'." << std::endl;
            } else if (length > 1) {
                std::cerr << "Warning: Multiple elements found with name '" << elementName << "'." << std::endl;
            }

            manageDirectory(elementName);

        } catch (const xercesc::XMLException& e) {
            char* message = xercesc::XMLString::transcode(e.getMessage());
            std::cerr << "XML Exception: " << message << std::endl;
            xercesc::XMLString::release(&message);
        } catch (...) {
            std::cerr << "An unexpected error occurred." << std::endl;
        }

        xercesc::XMLPlatformUtils::Terminate();
    }

private:
    void manageDirectory(const std::string& dirName) {
        const char* envVar = std::getenv("DIRECTORY_PATH");

        if (!envVar || envVar[0] == '\0' || std::strcmp(envVar, dirName.c_str()) != 0) {
            std::filesystem::path path(dirName);

            if (!std::filesystem::exists(path)) {
                try {
                    std::filesystem::create_directory(path);
                    setEnvironmentVariable("DIRECTORY_PATH", dirName.c_str());
                } catch (const std::exception& e) {
                    std::cerr << "Error creating directory: " << e.what() << std::endl;
                }
            } else if (!std::filesystem::is_directory(path)) {
                std::cerr << "Path exists but is not a directory." << std::endl;
            }
        }
    }

    void setEnvironmentVariable(const char* name, const char* value) {
        if (std::getenv(name) == nullptr || std::strcmp(std::getenv(name), value) != 0) {
            if (setenv(name, value, 1) != 0) {
                perror("Failed to set environment variable");
            }
        }
    }
};

int main() {
    // Initialize random number manager with a seed
    int seed = std::random_device{}();
    RandomManager::SingletonRandomManager& rngManager = RandomManager::SingletonRandomManager::getInstance(seed);

    XMLHandler xmlHandler;

    std::string xmlContent = R"(<root><test>Sample</test></root>)";
    std::string elementName = "test";

    xmlHandler.parseXMLAndHandleDirectory(xmlContent, elementName);

    // Run unit tests
    RandomManager::SingletonRandomManager::testFunctionality();

    return 0;
}
