    public DynamicValueGenerator(double minValue, double maxValue)
    {
        SetRange(minValue, maxValue);
    }

    public void SetRange(double minValue, double maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("minValue cannot be greater than maxValue.");
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void SetSubRange(double subMin, double subMax)
    {
        if (subMin > subMax || subMin < minValue || subMax > maxValue)
            throw new ArgumentException("Invalid sub-range.");
        this.subMin = subMin;
        this.subMax = subMax;
    }

    public float GenerateRandomFloat(bool inclusiveBoundaries = true)
    {
        double range = inclusiveBoundaries ? (maxValue - minValue) : (maxValue - minValue - 1);
        return (float)(_random.NextDouble() * range + minValue);
    }

    public int GenerateRandomInteger(bool inclusiveBoundaries = true)
    {
        long range;
        if (inclusiveBoundaries)
            range = (long)(maxValue - minValue);
        else
            range = (long)(maxValue - minValue - 1);

        if (range < int.MinValue || range > int.MaxValue) throw new InvalidOperationException("Range too large for an integer.");

        return _random.Next((int)minValue, (int)maxValue + 1);
    }

