['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define MAX_RECORDS 10000000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    int* parent;
    int* rank;
} DynamicCollection;

void initialize_union_find(int* parent, int* rank, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        parent[i] = -1;
        rank[i] = 0;
    }
}

int find(int x, int* parent) {
    if (parent[x] < 0)
        return x;
    return parent[x] = find(parent[x], parent);
}

void union_sets(int x, int y, int* parent, int* rank) {
    x = find(x, parent);
    y = find(y, parent);

    if (x != y) {
        if (rank[x] > rank[y]) {
            parent[y] = x;
        } else if (rank[x] < rank[y]) {
            parent[x] = y;
        } else {
            parent[y] = x;
            rank[x]++;
        }
    }
}

DynamicCollection* create_collection(size_t initial_capacity) {
    DynamicCollection* collection = malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record));
    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->parent = malloc(initial_capacity * sizeof(int));
    collection->rank = malloc(initial_capacity * sizeof(int));

    if (!collection->records || !collection->parent || !collection->rank) {
        free(collection->records);
        free(collection->parent);
        free(collection->rank);
        free(collection);
        return NULL;
    }

    initialize_union_find(collection->parent, collection->rank, initial_capacity);

    return collection;
}

void resize_collection(DynamicCollection* collection, size_t new_capacity) {
    Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
    int* new_parent = realloc(collection->parent, new_capacity * sizeof(int));
    int* new_rank = realloc(collection->rank, new_capacity * sizeof(int));

    if (!new_records || !new_parent || !new_rank) {
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        free(new_records);
        free(new_parent);
        free(new_rank);
        return;
    }

    collection->records = new_records;
    collection->parent = new_parent;
    collection->rank = new_rank;

    for (size_t i = collection->count; i < new_capacity; ++i) {
        collection->parent[i] = -1;
        collection->rank[i] = 0;
    }

    collection->capacity = new_capacity;
}

bool add_record(DynamicCollection* collection, int key, long offset) {
    if (collection->count >= collection->capacity) {
        resize_collection(collection, collection->capacity * 2);
        if (!collection->records) return false;
    }

    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    collection->count++;

    return true;
}

void free_collection(DynamicCollection* collection) {
    free(collection->records);
    free(collection->parent);
    free(collection->rank);
    free(collection);
}

int log_disjoint_sets(int* parent, size_t n) {
    int disjoint_count = 0;
    for (size_t i = 0; i < n; ++i) {
        if (parent[i] < 0)
            disjoint_count++;
    }
    return disjoint_count;
}

void serialize_collection(DynamicCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&collection->count, sizeof(size_t), 1, file);
    fwrite(collection->records, sizeof(Record), collection->count, file);

    fclose(file);
}

DynamicCollection* deserialize_collection(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    DynamicCollection* collection = malloc(sizeof(DynamicCollection));
    if (!collection) goto error;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    collection->records = calloc(count, sizeof(Record));
    collection->parent = malloc(count * sizeof(int));
    collection->rank = malloc(count * sizeof(int));

    if (!collection->records || !collection->parent || !collection->rank) goto error;

    fread(collection->records, sizeof(Record), count, file);
    initialize_union_find(collection->parent, collection->rank, count);

    fclose(file);

    collection->count = count;
    collection->capacity = count;
    return collection;

error:
    if (file) fclose(file);
    if (collection) {
        free(collection->records);
        free(collection->parent);
        free(collection->rank);
        free(collection);
    }
    return NULL;
}

void log_operation(const char* message, clock_t start_time) {
    printf("%s - Time: %f seconds\n", message, (double)(clock() - start_time) / CLOCKS_PER_SEC);
}
