    pthread_mutex_lock(&lock);

    if (!(ctx = EVP_PKEY_CTX_new(priv_key, NULL))) return -1;
    if (EVP_PKEY_derive_init(ctx) <= 0 ||
        EVP_PKEY_derive_set_peer(ctx, peer_pub_key) <= 0 ||
        EVP_PKEY_derive(ctx, NULL, &secret_len) <= 0) {
