#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>

#define AES_KEY_SIZE 32
#define IV_SIZE 16
#define MAX_THEME_CACHE_SIZE 5
#define PNG_FILE_MAX_SIZE 1024 * 1024 // 1 MB

// Struct for caching themes
typedef struct {
    char* file_path;
    unsigned char* data;
    size_t data_size;
} ThemeCacheEntry;

ThemeCacheEntry theme_cache[MAX_THEME_CACHE_SIZE];
size_t current_cache_size = 0;

// Logging and resource tracking variables
int cipher_initializations = 0;
int cipher_cleanup_count = 0;

// Function prototypes
void init_aes_cipher(const char* password, EVP_CIPHER_CTX** ctx);
void cleanup_aes_cipher(EVP_CIPHER_CTX* ctx);
void log_cryptographic_event(const char* event_description);
size_t find_least_recently_used_cache_index();
void set_theme_bitmap_to_null(ThemeCacheEntry* entry);
int verify_and_set_default_theme_directory(const char* default_dir);
int parse_png_file(const char* file_path, unsigned char** out_data, size_t* out_size);

// Cryptographic Initialization
void init_aes_cipher(const char* password, EVP_CIPHER_CTX** ctx) {
    *ctx = EVP_CIPHER_CTX_new();
    if (!(*ctx)) {
        perror("Failed to create cipher context");
        return;
    }

    // Derive key and IV from the password using SHA-256
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[IV_SIZE];

    // Generate a fresh random IV for each encryption operation
    if (!RAND_bytes(iv, sizeof(iv))) {
        perror("Failed to generate random IV");
        EVP_CIPHER_CTX_free(*ctx);
        return;
    }

    // Use SHA-256 to hash the password into key and iv
    SHA256((unsigned char*)password, strlen(password), key);

    // Initialize AES-256-CBC cipher with derived key
    if (1 != EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        perror("Failed to initialize encryption");
        EVP_CIPHER_CTX_free(*ctx);
        return;
    }

    cipher_initializations++;
    log_cryptographic_event("AES cipher initialized");

    // Optionally copy IV into the context if needed externally
}

void cleanup_aes_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
        cipher_cleanup_count++;
        log_cryptographic_event("AES cipher cleaned up");
    }
}

// Theme Caching

int add_to_theme_cache(const char* file_path, const unsigned char* data, size_t size) {
    if (current_cache_size >= MAX_THEME_CACHE_SIZE) {
        size_t lru_index = find_least_recently_used_cache_index();
        set_theme_bitmap_to_null(&theme_cache[lru_index]);
    }

    for (size_t i = 0; i < current_cache_size; ++i) {
        if (strcmp(theme_cache[i].file_path, file_path) == 0) {
            // Update existing entry
            free(theme_cache[i].data);
            theme_cache[i].data = malloc(size);
            memcpy(theme_cache[i].data, data, size);
            return 1;
        }
    }

    // Add new cache entry if not found
    ThemeCacheEntry* entry = &theme_cache[current_cache_size++];
    entry->file_path = strdup(file_path);
    entry->data = malloc(size);
    memcpy(entry->data, data, size);
    entry->data_size = size;

    return 1;
}

size_t find_least_recently_used_cache_index() {
    // Simple LRU based on current order for this implementation
    return current_cache_size - 1;
}

void set_theme_bitmap_to_null(ThemeCacheEntry* entry) {
    if (entry && entry->data) {
        free(entry->data);
        entry->data = NULL;
        free(entry->file_path);
        entry->file_path = NULL;
    }
}

int verify_and_set_default_theme_directory(const char* default_dir) {
    // Here we can check the current directory, and set it if not already set
    // Assume a global variable `default_theme_directory`
    extern const char* default_theme_directory;

    if (default_theme_directory == NULL || strlen(default_theme_directory) == 0) {
        default_theme_directory = strdup(default_dir);
        return 1;
    }

    return 0;
}

int parse_png_file(const char* file_path, unsigned char** out_data, size_t* out_size) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open PNG file");
        return -1;
    }

    fseek(file, 0L, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    if (filesize > PNG_FILE_MAX_SIZE) {
        fprintf(stderr, "PNG file size exceeds limit\n");
        fclose(file);
        return -2;
    }

    *out_data = malloc(filesize);
    if (!*out_data) {
        perror("Failed to allocate memory for PNG data");
        fclose(file);
        return -3;
    }

    fread(*out_data, 1, filesize, file);
    *out_size = filesize;

    fclose(file);
    return 0;
}

void log_cryptographic_event(const char* event_description) {
    printf("Cryptographic Event: %s\n", event_description);
    // Add more sophisticated logging if needed
}

int main() {
    EVP_CIPHER_CTX* aes_ctx = NULL;
    init_aes_cipher("securepassword123", &aes_ctx);

    const char* default_theme_dir = "/default/theme/dir";
    verify_and_set_default_theme_directory(default_theme_dir);

    unsigned char* png_data;
    size_t png_size;
    if (parse_png_file("/path/to/png.png", &png_data, &png_size) == 0) {
        add_to_theme_cache("theme1.png", png_data, png_size);
    }

    cleanup_aes_cipher(aes_ctx);

    // Clean up remaining theme cache entries
    for (size_t i = 0; i < current_cache_size; ++i) {
        set_theme_bitmap_to_null(&theme_cache[i]);
    }

    return 0;
}
```

This code snippet includes:
- Initialization and cleanup of an AES-256-CBC cipher using OpenSSL.
- A theme caching mechanism with a simple LRU eviction policy.
- Basic logging for cryptographic operations.
- PNG parsing with file size checks.

Note: This code requires linking against the OpenSSL library (`-lssl -lcrypto`). It's also important to handle errors and edge cases robustly in a production environment.']

