```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    struct Record *prev, *next;
} Record;

// Function prototypes for memory management and initialization
long* allocate_offset_array(size_t size);
int* allocate_key_array(size_t size);
Record* allocate_record_list(size_t num_records, int min_value, int max_value);

// Mutex for thread safety during allocation and initialization
pthread_mutex_t alloc_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_random_seed() {
    pthread_mutex_lock(&alloc_mutex);
    time_t t;
    srand((unsigned) time(&t));
    pthread_mutex_unlock(&alloc_mutex);
}

long* allocate_offset_array(size_t size) {
    long *array = (long*)malloc(size * sizeof(long));
    if (!array) {
        perror("Failed to allocate memory for offset array");
        exit(EXIT_FAILURE);
    }
    return array;
}

int* allocate_key_array(size_t size) {
    int *keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }
    return keys;
}

Record* allocate_record_list(size_t num_records, int min_value, int max_value) {
    pthread_mutex_lock(&alloc_mutex);

    Record *head = NULL, *tail = NULL;

    for (size_t i = 0; i < num_records; ++i) {
        Record *new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            perror("Failed to allocate memory for record");
            // Clean up previously allocated records
            while (head != NULL) {
                Record *temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_unlock(&alloc_mutex);
            exit(EXIT_FAILURE);
        }

        new_record->value = rand() % (max_value - min_value + 1) + min_value;

        if (tail == NULL) {
            head = tail = new_record;
            head->prev = head->next = NULL;
        } else {
            tail->next = new_record;
            new_record->prev = tail;
            new_record->next = NULL;
            tail = new_record;
        }
    }

    pthread_mutex_unlock(&alloc_mutex);
    return head;
}

void free_offset_array(long *array) {
    free(array);
}

void free_key_array(int *keys) {
    free(keys);
}

void free_record_list(Record *head) {
    Record *current = head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    initialize_random_seed();

    size_t num_records = 1000; // Example size
    int min_value = 1, max_value = 100;

    long *offset_array = allocate_offset_array(num_records);
    int *key_array = allocate_key_array(num_records);
    Record *record_list = allocate_record_list(num_records, min_value, max_value);

    // Use the allocated structures...

    // Cleanup
    free_offset_array(offset_array);
    free_key_array(key_array);
    free_record_list(record_list);

    return 0;
}
```

### Key Considerations:
- **Thread Safety**: A mutex (`alloc_mutex`) is used to ensure that random seed initialization and memory allocation are thread-safe.
- **Error Handling**: The code checks for `NULL` after each allocation, and if any fail, it cleans up already allocated resources before exiting.
- **Modularity**: Functions are separated by their responsibilities (allocation and deallocation), making the code easy to integrate into larger systems.
- **Random Initialization**: Random values within a specified range are assigned to records using `rand()`.
- **Resource Cleanup**: Proper cleanup functions ensure no memory leaks, even in error scenarios.']

