    for (int attempt = 1; attempt <= 3 && !success; ++attempt) {
        if (!check_disk_space_and_permissions(output_pdf_file)) {
            log_message(LOG_LEVEL_WARNING, "Disk space or permissions issue detected.");
        } else {
            success = write_to_file(output_pdf_file, serialized_data, serialized_size);
            if (!success && attempt < 3) {
                config.compression_level -= 10; // Reduce compression level
                log_message(LOG_LEVEL_INFO, "Retrying with reduced compression level...");
