    time_t end_time = time(NULL);
    double duration = difftime(end_time, start_time);
    log_message(LOG_LEVEL_DEBUG, (success ? "Conversion succeeded." : "Conversion failed.") 
                " Duration: %.2f seconds.", duration);

    return success ? 0 : 1;
}
