import <pthread.h>

#define MAX_RECORDS 10000000

typedef struct {
    short int_field;
    float f_float;
    double d_double;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    pthread_rwlock_t lock;
} RecordArray;

// Function to initialize the record array
RecordArray* init_record_array(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_RECORDS) {
        fprintf(stderr, "Invalid initial capacity\n");
        return NULL;
    }

    RecordArray *arr = malloc(sizeof(RecordArray));
    if (!arr) {
        perror("Failed to allocate memory for RecordArray");
        return NULL;
    }

    arr->records = calloc(initial_capacity, sizeof(Record));
    if (!arr->records) {
        perror("Failed to allocate memory for records");
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    pthread_rwlock_init(&arr->lock, NULL);

    // Load configuration parameters from file
    int short_min = 0, short_max = 32767;
    float float_min = -3.4e+38f, float_max = 3.4e+38f;
    double double_min = -1.7e+308, double_max = 1.7e+308;

    FILE *config_file = fopen("config.txt", "r");
    if (config_file) {
        fscanf(config_file, "%hd %hd %f %f %lf %lf",
               &short_min, &short_max,
               &float_min, &float_max,
               &double_min, &double_max);
        fclose(config_file);
    } else {
        perror("Failed to open configuration file");
        // Use default values if config fails
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        arr->records[i].int_field = short_min + rand() % (short_max - short_min + 1);
        arr->records[i].f_float = float_min + ((float)rand() / RAND_MAX) * (float_max - float_min);
        arr->records[i].d_double = double_min + drand48() * (double_max - double_min);
    }

    return arr;
}

// Function to destroy the record array
void free_record_array(RecordArray *arr) {
    if (!arr) return;

    pthread_rwlock_destroy(&arr->lock);
    free(arr->records);
    free(arr);
}

// Thread-safe function to add a new record
int add_record(RecordArray *arr, Record new_record) {
    if (!arr || arr->capacity == 0) {
        fprintf(stderr, "Invalid record array or capacity exceeded\n");
        return -1;
    }

    pthread_rwlock_wrlock(&arr->lock);
    for (size_t i = 0; i < arr->capacity; ++i) {
        // Check if the slot is empty
        if (arr->records[i].int_field == 0 && 
            arr->records[i].f_float == 0.0f && 
            arr->records[i].d_double == 0.0) {

            arr->records[i] = new_record;
            pthread_rwlock_unlock(&arr->lock);
            return 0; // Success
        }
    }

    // If no empty slot was found, attempt to resize (optional)
    size_t new_capacity = arr->capacity * 2;
    if (new_capacity > MAX_RECORDS) {
        fprintf(stderr, "Capacity limit reached\n");
        pthread_rwlock_unlock(&arr->lock);
        return -1; // Failure
    }

    Record *temp_records = realloc(arr->records, new_capacity * sizeof(Record));
    if (!temp_records) {
        perror("Failed to resize record array");
        pthread_rwlock_unlock(&arr->lock);
        return -1;
    }

    arr->records = temp_records;
    arr->capacity = new_capacity;

    // Initialize the new slots
    for (size_t i = arr->capacity / 2; i < arr->capacity; ++i) {
        arr->records[i].int_field = 0;
        arr->records[i].f_float = 0.0f;
        arr->records[i].d_double = 0.0;
    }

    arr->records[arr->capacity / 2] = new_record;
    pthread_rwlock_unlock(&arr->lock);

    return 0; // Success
}

// Thread-safe function to get a record by index
int get_record(RecordArray *arr, size_t index, Record *out_record) {
    if (!arr || !out_record || index >= arr->capacity) {
        fprintf(stderr, "Invalid parameters\n");
        return -1;
    }

    pthread_rwlock_rdlock(&arr->lock);
    if (index < arr->capacity) {
        *out_record = arr->records[index];
        pthread_rwlock_unlock(&arr->lock);
        return 0; // Success
    } else {
        pthread_rwlock_unlock(&arr->lock);
        return -1; // Failure
    }
}

// Example of integration with external data processing pipeline (pseudo-code)
