#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 1024

typedef struct {
    int32_t value;
    int count;
} IntegerInfo;

// Function prototypes
void processIntegerStream(int sockfd);
void initAndCleanupNetworkConnection(const char* ip, int port);
int topTenUniqueMax(IntegerInfo *uniqueIntegers, size_t size);

int main() {
    const char* serverIP = "127.0.0.1";
    int serverPort = 8080;

    initAndCleanupNetworkConnection(serverIP, serverPort);

    return 0;
}

void processIntegerStream(int sockfd) {
    uint8_t buffer[BUFFER_SIZE];
    IntegerInfo *uniqueIntegers = NULL;
    size_t uniqueCount = 0;
    ssize_t bytesRead;

    while ((bytesRead = read(sockfd, buffer, BUFFER_SIZE)) > 0) {
        int i = 0;
        while (i < bytesRead) {
            char numStr[12] = {0};
            sscanf(buffer + i, "%11s", numStr);
            char *endptr;
            int32_t number = strtol(numStr, &endptr, 10);

            if (*endptr == '\n' || *endptr == ' ' || *endptr == '\t') {
                // Validate integer range
                if (number <= INT32_MAX && number >= INT32_MIN) {
                    // Check for duplicates or add new element
                    int found = 0;
                    for (size_t j = 0; j < uniqueCount; ++j) {
                        if (uniqueIntegers[j].value == number) {
                            uniqueIntegers[j].count++;
                            found = 1;
                            break;
                        }
                    }

                    if (!found) {
                        // Dynamically resize array
                        IntegerInfo *newArray = realloc(uniqueIntegers, (uniqueCount + 1) * sizeof(IntegerInfo));
                        if (newArray == NULL) {
                            free(uniqueIntegers);
                            printf("Memory allocation failed.\n");
                            return;
                        }
                        uniqueIntegers = newArray;
                        uniqueIntegers[uniqueCount].value = number;
                        uniqueIntegers[uniqueCount].count = 1;
                        ++uniqueCount;
                    }
                }

                // Advance to next integer
                i += strlen(numStr) + (endptr == '\n' ? 1 : 0);
            } else {
                // Skip invalid numbers
                while (i < bytesRead && buffer[i] != ' ' && buffer[i] != '\t' && buffer[i] != '\n') {
                    ++i;
                }
            }
        }
    }

    if (uniqueCount > 0) {
        topTenUniqueMax(uniqueIntegers, uniqueCount);
    } else {
        printf("No valid integers received.\n");
    }

    free(uniqueIntegers);
}

void initAndCleanupNetworkConnection(const char* ip, int port) {
    int sockfd;
    struct sockaddr_in serverAddr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        return;
    }

    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(port);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, ip, &serverAddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("Connection Failed");
        close(sockfd);
        return;
    }

    processIntegerStream(sockfd);

    close(sockfd);
}

int topTenUniqueMax(IntegerInfo *uniqueIntegers, size_t size) {
    if (size == 0) {
        return 0;
    }

    // Sort based on value in descending order
    qsort(uniqueIntegers, size, sizeof(IntegerInfo), [](const void* a, const void* b) {
        IntegerInfo *ia = (IntegerInfo *)a;
        IntegerInfo *ib = (IntegerInfo *)b;
        return ib->value - ia->value; // Descending order sort
    });

    printf("Top 10 Largest Unique Integers:\n");

    size_t printedCount = 0;
    for (size_t i = 0; i < size && printedCount < 10; ++i) {
        if (printedCount == 0 || uniqueIntegers[i].value != uniqueIntegers[i - 1].value) {
            printf("%d\n", uniqueIntegers[i].value);
            ++printedCount;
        }
    }

    return 0;
}
