['```csharp
using System;
using System.Collections.Generic;
using System.Threading;

public class DynamicValueGenerator : IEquatable<DynamicValueGenerator>
{
    private int _minInt;
    private int _maxInt;
    private double _minDouble;
    private double _maxDouble;
    private Random _random = new Random();
    private readonly object _lock = new object();

    public void SetIntegerRange(int min, int max)
    {
        lock (_lock)
        {
            _minInt = min;
            _maxInt = max;
        }
    }

    public void SetFloatingPointRange(double min, double max)
    {
        lock (_lock)
        {
            _minDouble = min;
            _maxDouble = max;
        }
    }

    public int GenerateRandomInteger(int stepSize, bool inclusive)
    {
        lock (_lock)
        {
            var rangeStart = inclusive ? _minInt : _minInt + 1;
            var rangeEnd = inclusive ? _maxInt : _maxInt - 1;

            if (rangeStart > rangeEnd || stepSize <= 0) return _random.Next(_minInt, _maxInt);

            var value = rangeStart + stepSize * _random.Next((rangeEnd - rangeStart) / stepSize + 1);
            return Math.Max(rangeStart, Math.Min(value, rangeEnd));
        }
    }

    public List<int> GenerateRandomIntegerList(int n, bool inclusive)
    {
        lock (_lock)
        {
            var randomIntegers = new List<int>(n);
            for (int i = 0; i < n; i++)
            {
                randomIntegers.Add(GenerateRandomInteger(1, inclusive));
            }
            return randomIntegers;
        }
    }

    public double GenerateRandomDouble()
    {
        lock (_lock)
        {
            return _random.NextDouble() * (_maxDouble - _minDouble) + _minDouble;
        }
    }

    public override string ToString()
    {
        lock (_lock)
        {
            return $"Integer Range: [{_minInt}, {_maxInt}], Double Range: [{_minDouble}, {_maxDouble}]";
        }
    }

    public bool Equals(DynamicValueGenerator other)
    {
        if (other == null) return false;

        lock (_lock)
        {
            return _minInt == other._minInt && _maxInt == other._maxInt &&
                   _minDouble.Equals(other._minDouble) && _maxDouble.Equals(other._maxDouble);
        }
    }

    public override bool Equals(object obj)
    {
        if (obj is DynamicValueGenerator other)
        {
            return Equals(other);
        }
        return false;
    }

    public override int GetHashCode()
    {
        lock (_lock)
        {
            return HashCode.Combine(_minInt, _maxInt, _minDouble, _maxDouble);
        }
    }
}
