    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to check if an RNTI is unique in the list
bool is_unique_rnti(NFAPI_CRC_INDICATION_PDU_T *list, size_t current_size, unsigned int rnti) {
    for (size_t i = 0; i < current_size; ++i) {
        if (list[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

// Function to resize the list
NFAPI_CRC_INDICATION_PDU_T* resize_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t *current_size, size_t new_size) {
    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) {
        free(list);
        return NULL;
    }
    *current_size = new_size;
    return new_list;
}

// Main function to manage the list
int manage_nfa_list(size_t max_size, NFAPI_CRC_INDICATION_PDU_T **list_out) {
    size_t current_size = INITIAL_SIZE;
    *list_out = malloc(current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list_out) return -1; // Allocation failure

    for (size_t i = 0; i < max_size; ++i) {
        if (i >= current_size) {
            NFAPI_CRC_INDICATION_PDU_T *resized_list = resize_list(*list_out, &current_size, current_size * 2);
            if (!resized_list) {
                free(*list_out);
                return -1; // Allocation failure
            }
            *list_out = resized_list;
        }

        (*list_out)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Random value for example
        (*list_out)[i].RNTI = rand() % 1000; // Random RNTI value

        if (!is_unique_rnti(*list_out, i, (*list_out)[i].RNTI)) {
            fprintf(stderr, "Duplicate RNTI detected: %u\n", (*list_out)[i].RNTI);
            free(*list_out);
            return -1; // Error on duplicate
        }

        (*list_out)[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF;
        (*list_out)[i].CRCFLAG = rand() % 2 == 0; // Random boolean value

    }

    return 0; // Success
}

int main() {
    size_t max_size = 20;
    NFAPI_CRC_INDICATION_PDU_T *nfa_list;

    int result = manage_nfa_list(max_size, &nfa_list);
    if (result == 0) {
        printf("List managed successfully with %zu entries.\n", max_size);
    } else {
        printf("Failed to manage the list.\n");
    }

    free(nfa_list);
    return 0;
