import org.yaml.snakeyaml.Yaml;

public class FileProcessor {

    private static final Yaml yaml = new Yaml();
    private static ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public static void main(String[] args) {
        CommandLineOptions options = parseCommandLine(args);

        if (options.manpage) {
            displayManpage();
            return;
        }

        List<File> files = loadFilesFromConfig(options.configFile);

        Map<File, FileMetrics> metricsMap = new ConcurrentHashMap<>();

        for (File file : files) {
            executor.submit(() -> {
                try {
                    metricsMap.put(file, processFile(file, options.individualLineLengths));
                } catch (IOException e) {
                    System.err.println("Error processing file " + file.getName() + ": " + e.getMessage());
                }
            });
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        generateReport(metricsMap, options.outputFile);

        if (options.concatenateOutput != null) {
            concatenateFiles(files, options.concatenateOutput);
        }
    }

    private static CommandLineOptions parseCommandLine(String[] args) {
        // Parse command line arguments to create a CommandLineOptions object.
        return new CommandLineOptions(); // Simplified; actual parsing would be needed
    }

    private static void displayManpage() {
        System.out.println("Usage: java FileProcessor [options]\n" +
                "  -i             Print individual line lengths.\n" +
                "  --manpage      Display detailed usage instructions.\n" +
                "  -cs            Concatenate files into a single output file.\n" +
                "  -o <output>    Specify an output file for the result.");
    }

    private static List<File> loadFilesFromConfig(String configFilePath) throws IOException {
        Yaml yaml = new Yaml();
        Map<String, Object> data = yaml.load(new File(configFilePath).toPath().toFile());
        List<Object> filesList = (List<Object>) data.get("files");
        return filesList.stream()
                .map(obj -> Paths.get((String) obj).toFile())
                .collect(Collectors.toList());
    }

    private static FileMetrics processFile(File file, boolean printIndividualLineLengths) throws IOException {
        try (Stream<String> lines = Files.lines(file.toPath())) {
            long totalLines = 0;
            int totalLength = 0;

            if (printIndividualLineLengths) {
                lines.forEach(line -> System.out.println("File: " + file.getName() + ", Line Length: " + line.length()));
            }

            List<Integer> lengths = lines.mapToInt(String::length).boxed().collect(Collectors.toList());
            for (int length : lengths) {
                totalLines++;
                totalLength += length;
            }

            return new FileMetrics(totalLines, totalLength / (totalLines == 0 ? 1 : totalLines), lengths);
        }
    }

    private static void generateReport(Map<File, FileMetrics> metricsMap, String outputFile) throws IOException {
        StringBuilder report = new StringBuilder();

        for (Map.Entry<File, FileMetrics> entry : metricsMap.entrySet()) {
            File file = entry.getKey();
            FileMetrics metrics = entry.getValue();

            report.append("File: ").append(file.getName())
                    .append(", Line Count: ").append(metrics.lineCount)
                    .append(", Average Line Length: ").append(metrics.averageLineLength).append("\n");
        }

        if (outputFile != null) {
            Files.write(Paths.get(outputFile), report.toString().getBytes());
        } else {
            System.out.println(report);
        }
    }

    private static void concatenateFiles(List<File> files, String outputFilePath) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(outputFilePath))) {
            for (File file : files) {
                Files.lines(file.toPath()).forEach(line -> {
                    try {
                        writer.write(line);
                        writer.newLine();
                    } catch (IOException e) {
                        System.err.println("Error writing to output: " + e.getMessage());
                    }
                });
            }
        }
    }

    private static class CommandLineOptions {
        String configFile;
        boolean individualLineLengths = false;
        boolean manpage = false;
        String concatenateOutput = null;
        String outputFile = null;

        // Add getters and setters for these fields
    }

    private static class FileMetrics {
        long lineCount;
        double averageLineLength;
        List<Integer> individualLengths;

        FileMetrics(long lineCount, double averageLineLength, List<Integer> individualLengths) {
            this.lineCount = lineCount;
            this.averageLineLength = averageLineLength;
            this.individualLengths = individualLengths;
        }
    }
}
