#include <openssl/evp.h>
#include <openssl/rand.h>
#include <mysql/mysql.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to initialize AES-256-CBC cipher
EVP_CIPHER_CTX* init_aes_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const int key_len = 32; // 256 bits
    const int iv_len = 16;  // 128 bits

    unsigned char key[key_len], iv[iv_len];
    if (RAND_bytes(key, sizeof(key)) != 1 || RAND_bytes(iv, sizeof(iv)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_BytesToKey(EVP_sha256(), EVP_aes_256_cbc(), NULL,
                        (unsigned char *)password, strlen(password),
                        10000, key, iv)) { // Using SHA-256 and 10,000 iterations
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to clean up AES cipher
void cleanup_aes_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

// Function to retrieve employee data and handle AES cipher
void get_employee_data(const char *password, int supervisor_id, const char *db_user, const char *db_pass) {
    // Initialize AES cipher
    EVP_CIPHER_CTX *aes_ctx = init_aes_cipher(password);
    if (!aes_ctx) {
        fprintf(stderr, "Failed to initialize AES cipher\n");
        return;
    }

    // Connect to the database
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, NULL, db_user, db_pass, NULL, 0, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        cleanup_aes_cipher(aes_ctx);
        return;
    }

    // Prepare and execute the query
    char query[256];
    snprintf(query, sizeof(query), "SELECT employee_name, city, address FROM Employees WHERE supervisor_id = %d;", supervisor_id);

    if (mysql_query(conn, query)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        cleanup_aes_cipher(aes_ctx);
        mysql_close(conn);
        return;
    }

    MYSQL_RES *result = mysql_store_result(conn);
    if (!result) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        cleanup_aes_cipher(aes_ctx);
        mysql_close(conn);
        return;
    }

    // Fetch and print results
    MYSQL_ROW row;
    while ((row = mysql_fetch_row(result))) {
        printf("Employee Name: %s, City: %s, Address: %s\n", row[0], row[1], row[2]);
    }

    // Cleanup
    mysql_free_result(result);
    mysql_close(conn);
    cleanup_aes_cipher(aes_ctx);
}
