#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for an entry in a linked list.
typedef struct Entry {
    char *value;
    struct Entry *next;
} Entry;

// Define the structure for a node containing an integer key and a linked list of entries.
typedef struct Node {
    int key;
    Entry *entries_head;
} Node;

// Function to generate a random string within a specified length range.
char* generate_random_string(size_t min_length, size_t max_length) {
    if (min_length > max_length || max_length == 0) return NULL;

    size_t length = rand() % (max_length - min_length + 1) + min_length;
    char *str = malloc(length + 1);
    if (!str) return NULL;

    for (size_t i = 0; i < length; ++i) {
        str[i] = 'a' + rand() % 26; // Generate a random lowercase letter.
    }
    str[length] = '\0';

    return str;
}

// Function to initialize and populate nodes with linked lists of entries.
void manage_dynamic_memory(Node **nodes, size_t num_nodes, size_t min_entries_per_node, size_t max_entries_per_node,
                           size_t min_string_length, size_t max_string_length) {
    if (!nodes || num_nodes == 0) return;

    // Seed the random number generator for reproducibility in testing.
    srand((unsigned int)time(NULL));

    // Allocate memory for an array of node pointers.
    nodes = malloc(num_nodes * sizeof(Node*));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for nodes.\n");
        return;
    }

    // Initialize each node and populate its linked list with entries.
    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i] = malloc(sizeof(Node));
        if (!nodes[i]) {
            fprintf(stderr, "Memory allocation failed for node at index %zu.\n", i);
            break;
        }

        nodes[i]->key = rand(); // Assign a random integer key.
        nodes[i]->entries_head = NULL;

        size_t num_entries = rand() % (max_entries_per_node - min_entries_per_node + 1) + min_entries_per_node;

        Entry *current_entry = NULL, *prev_entry = NULL;
        for (size_t j = 0; j < num_entries; ++j) {
            current_entry = malloc(sizeof(Entry));
            if (!current_entry) {
                fprintf(stderr, "Memory allocation failed for entry in node at index %zu.\n", i);
                break;
            }

            current_entry->value = generate_random_string(min_string_length, max_string_length);
            if (!current_entry->value) {
                fprintf(stderr, "Failed to allocate memory for string in entry at node %zu, entry %zu.\n", i, j);
                free(current_entry); // Free the Entry struct.
                break;
            }

            current_entry->next = NULL;

            if (prev_entry == NULL) {
                nodes[i]->entries_head = current_entry; // Set head of linked list.
            } else {
                prev_entry->next = current_entry; // Link to previous entry.
            }

            prev_entry = current_entry;
        }
    }
}

// Function to free all allocated memory for the nodes and their entries.
void free_dynamic_memory(Node **nodes, size_t num_nodes) {
    if (!nodes || !*nodes) return;

    for (size_t i = 0; i < num_nodes; ++i) {
        Entry *entry = (*nodes)[i]->entries_head;
        while (entry != NULL) {
            Entry *temp = entry;
            entry = entry->next;
            free(temp->value); // Free the string value.
            free(temp); // Free the entry node.
        }

        free((*nodes)[i]); // Free the Node struct.
    }

    free(*nodes); // Free the array of node pointers.
}
