#define BUFFER_WARNING_THRESHOLD 0.8

typedef struct {
    int Transmission_ID;
    size_t Frame_Data_Size;
    char* Transmission_Buffer;
} Frame_Transmission_Data;

Frame_Transmission_Data* init_frame_transmission_data(int transmission_id, size_t frame_data_size) {
    Frame_Transmission_Data* data = (Frame_Transmission_Data*)malloc(sizeof(Frame_Transmission_Data));

    if (!data) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    data->Transmission_ID = transmission_id;
    data->Frame_Data_Size = frame_data_size;
    data->Transmission_Buffer = (char*)malloc(frame_data_size);

    if (!data->Transmission_Buffer) {
        free(data);
        fprintf(stderr, "Memory allocation error for Transmission Buffer\n");
        return NULL;
    }

    memset(data->Transmission_Buffer, 0, frame_data_size); // Initialize buffer

    return data;
}

void validate_and_monitor_buffers(Frame_Transmission_Data* data, size_t current_usage) {
    if (data == NULL) {
        fprintf(stderr, "Invalid Frame Transmission Data\n");
        return;
    }

    if (current_usage > data->Frame_Data_Size) {
        fprintf(stderr, "Buffer overflow detected for ID %d\n", data->Transmission_ID);
        // Handle buffer overflow logic here
    } else if (current_usage < 0 || current_usage > data->Frame_Data_Size * BUFFER_WARNING_THRESHOLD) {
        fprintf(stderr, "Warning: Buffer usage high for ID %d. Current Usage: %zu\n",
                data->Transmission_ID, current_usage);
    }
}

void manage_transmission_data(Frame_Transmission_Data** array, size_t* count, int transmission_id, size_t frame_data_size) {
    Frame_Transmission_Data* new_frame = init_frame_transmission_data(transmission_id, frame_data_size);

    if (!new_frame) {
        return; // Error handling already logged in init function
    }

    *array = (Frame_Transmission_Data*)realloc(*array, (*count + 1) * sizeof(Frame_Transmission_Data));

    if (!*array) {
        free(new_frame);
        fprintf(stderr, "Memory allocation error during reallocation\n");
        return;
    }

    (*array)[*count] = *new_frame;
    (*count)++;
}

void cleanup_transmission_data(Frame_Transmission_Data** array, size_t count) {
    if (array && *array) {
        for (size_t i = 0; i < count; ++i) {
            free((*array)[i].Transmission_Buffer);
        }
        free(*array);
        *array = NULL;
    }
}

// Example Usage
int main() {
    Frame_Transmission_Data* frames = NULL;
    size_t frame_count = 0;

    manage_transmission_data(&frames, &frame_count, 1, 1024);

    // Simulate buffer usage
    validate_and_monitor_buffers(&frames[0], 900); // This should log a warning

    cleanup_transmission_data(&frames, frame_count);
    return 0;
}
