#define MAX_LINE_LENGTH 1024
#define DNS_CACHE_SIZE 100

typedef struct {
    char hostname[256];
    char ip_address[INET6_ADDRSTRLEN];
} dns_cache_entry;

dns_cache_entry cache[DNS_CACHE_SIZE];
int cache_count = 0;

void log_message(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}

char* get_dns_ip(const char *hostname, struct timeval *start_time, int *resolved) {
    static char ip_address[INET6_ADDRSTRLEN];
    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    gettimeofday(start_time, NULL);

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        log_message("ERROR", strerror(status));
        *resolved = 0;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(p->ai_family, addr, ip_address, sizeof(ip_address));
        freeaddrinfo(res);
        *resolved = 1;
        return strdup(ip_address);
    }

    freeaddrinfo(res);
    log_message("ERROR", "DNS resolution failed");
    *resolved = 0;
    return NULL;
}

char* find_in_cache(const char *hostname) {
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            return strdup(cache[i].ip_address);
        }
    }
    return NULL;
}

void add_to_cache(const char *hostname, const char *ip_address) {
    if (cache_count < DNS_CACHE_SIZE) {
        strcpy(cache[cache_count].hostname, hostname);
        strcpy(cache[cache_count].ip_address, ip_address);
        cache_count++;
    } else {
        log_message("WARNING", "DNS cache is full, unable to add more entries");
    }
}

void process_line(const char *line) {
    char hostname[256];
    int fields[10], field_count = 0;
    float average;

    sscanf(line, "%255[^,],%d,%d,%d,%d,%d,%d,%d,%d,%d,%d", hostname, &fields[0], &fields[1], &fields[2],
           &fields[3], &fields[4], &fields[5], &fields[6], &fields[7], &fields[8]);

    char *cached_ip = find_in_cache(hostname);
    if (cached_ip) {
        log_message("INFO", "Cache hit");
        free(cached_ip);
    } else {
        struct timeval start_time;
        int resolved;
        char *resolved_ip = get_dns_ip(hostname, &start_time, &resolved);

        if (resolved && resolved_ip) {
            add_to_cache(hostname, resolved_ip);
            struct timeval end_time;
            gettimeofday(&end_time, NULL);
            double elapsed = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_usec - start_time.tv_usec) / 1e6;
            log_message("INFO", "DNS resolution succeeded");
            printf("Elapsed time: %.3f seconds\n", elapsed);
        } else {
            resolved_ip = strdup("Resolution failed");
        }

        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d,%d,%s",
               hostname, fields[0], fields[1], fields[2], fields[3],
               fields[4], fields[5], fields[6], fields[7], fields[8],
               resolved_ip);
        free(resolved_ip);
    }

    if (field_count >= 3) {
        average = (fields[field_count - 1] + fields[field_count - 2] + fields[field_count - 3]) / 3.0;
        printf(",%.2f\n", average);
    } else {
        printf("\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        process_line(line);
    }

    free(line);
    fclose(file);

    return EXIT_SUCCESS;
}
