using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;
using System.Xml.Xsl;
using System.IO.MemoryMappedFiles;
using System.Threading;

public class XmlElementParser
{
    private static readonly Dictionary<string, List<XmlNode>> cache = new Dictionary<string, List<XmlNode>>();
    private static readonly ReaderWriterLockSlim cacheLock = new ReaderWriterLockSlim();

    public List<string> ParseXml(string xmlContent, string xpathExpression, string namespaceUri, string localName, string xsltPath)
    {
        try
        {
            using (var reader = XmlReader.Create(new StringReader(xmlContent)))
            {
                if (!IsValidXml(reader)) return new List<string>();

                var doc = new XPathDocument(reader);
                var navigator = doc.CreateNavigator();

                var nsMgr = new XmlNamespaceManager(navigator.NameTable);
                nsMgr.AddNamespace(localName, namespaceUri);

                var results = GetElementsFromCache(cacheKey(xmlContent, xpathExpression, namespaceUri), () =>
                {
                    var elements = navigator.Select(xpathExpression, nsMgr).Cast<XmlNode>().ToList();
                    if (elements.Count > 1)
                        throw new InvalidOperationException("Multiple elements found with the given name.");

                    return elements;
                });

                if (results.Count == 0) return new List<string>();

                var xsltArguments = new XsltArgumentList();
                ApplyXsltTransformation(results[0], xsltPath, xsltArguments);

                cacheLock.EnterWriteLock();
                try
                {
                    cache[cacheKey(xmlContent, xpathExpression, namespaceUri)] = results;
                }
                finally
                {
                    cacheLock.ExitWriteLock();
                }

                return ExtractValuesFromTransformedElement(results[0]);
            }
        }
        catch (XmlException)
        {
            Console.WriteLine("Invalid XML document.");
            return new List<string>();
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine(ex.Message);
            return new List<string>();
        }
        catch (XPathException)
        {
            Console.WriteLine("Invalid XPath expression.");
            return new List<string>();
        }
    }

    private bool IsValidXml(XmlReader reader)
    {
        try
        {
            while (reader.Read()) { }
            return true;
        }
        catch (XmlException)
        {
            return false;
        }
    }

    private string cacheKey(string xmlContent, string xpathExpression, string namespaceUri)
    {
        return $"{xmlContent.GetHashCode()}_{xpathExpression}_{namespaceUri}";
    }

    private List<XmlNode> GetElementsFromCache(string key, Func<List<XmlNode>> fetchElements)
    {
        if (cache.TryGetValue(key, out var cachedElements))
            return cachedElements;

        cacheLock.EnterReadLock();
        try
        {
            if (cache.TryGetValue(key, out cachedElements))
                return cachedElements;
        }
        finally
        {
            cacheLock.ExitReadLock();
        }

        var elements = fetchElements();
        cacheLock.EnterWriteLock();
        try
        {
            cache[key] = elements;
        }
        finally
        {
            cacheLock.ExitWriteLock();
        }

        return elements;
    }

    private void ApplyXsltTransformation(XmlNode element, string xsltPath, XsltArgumentList arguments)
    {
        using (var xslDoc = new XPathDocument(xsltPath))
        using (var transform = new XslCompiledTransform())
        {
            transform.Load(xslDoc);
            using (var stringWriter = new StringWriter())
            {
                transform.Transform(new XmlNodeReader(element), arguments, stringWriter);
            }
        }
    }

    private List<string> ExtractValuesFromTransformedElement(XmlNode element)
    {
        // Placeholder for extracting values from transformed elements
        return new List<string> { element.OuterXml };
    }
}
