using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Text;
using System.Threading;

public class DynamicValueGenerator : IDisposable
{
    private readonly Random _random = new Random();
    private double _minValue;
    private double _maxValue;
    private readonly object _rangeLock = new object();

    public double MinValue => _minValue;
    public double MaxValue => _maxValue;

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        SetRange(minValue, maxValue);
    }

    public void SetRange(double minValue, double maxValue)
    {
        lock (_rangeLock)
        {
            if (minValue > maxValue) throw new ArgumentException("Min value must be less than max value.");
            _minValue = minValue;
            _maxValue = maxValue;
        }
    }

    public int RandomInt() => GenerateRandomInt(true);
    public float RandomFloat() => (float)GenerateRandomDouble(true);

    public int RandomInt(double subMin, double subMax)
    {
        lock (_rangeLock)
        {
            return GenerateRandomInt(false, subMin, subMax);
        }
    }

    public float RandomFloat(double subMin, double subMax)
    {
        lock (_rangeLock)
        {
            return (float)GenerateRandomDouble(false, subMin, subMax);
        }
    }

    private int GenerateRandomInt(bool useMainRange, double? subMin = null, double? subMax = null)
    {
        double minValue, maxValue;
        if (useMainRange)
        {
            lock (_rangeLock)
            {
                minValue = _minValue;
                maxValue = _maxValue;
            }
        }
        else
        {
            lock (_rangeLock)
            {
                minValue = Math.Max(subMin ?? _minValue, _minValue);
                maxValue = Math.Min(subMax ?? _maxValue, _maxValue);
            }

            if (minValue > maxValue) throw new ArgumentException("Sub-range min value must be less than max value.");
        }

        return (int)(_random.NextDouble() * (maxValue - minValue + 1) + minValue);
    }

    private double GenerateRandomDouble(bool useMainRange, double? subMin = null, double? subMax = null)
    {
        double minValue, maxValue;
        if (useMainRange)
        {
            lock (_rangeLock)
            {
                minValue = _minValue;
                maxValue = _maxValue;
            }
        }
        else
        {
            lock (_rangeLock)
            {
                minValue = Math.Max(subMin ?? _minValue, _minValue);
                maxValue = Math.Min(subMax ?? _maxValue, _maxValue);
            }

            if (minValue > maxValue) throw new ArgumentException("Sub-range min value must be less than max value.");
        }

        return _random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public ConcurrentBag<int> GenerateRandomIntSequence(int n)
    {
        ValidateCount(n);
        var sequence = new ConcurrentBag<int>();
        Parallel.For(0, n, i => sequence.Add(RandomInt()));
        return sequence;
    }

    public ConcurrentBag<float> GenerateRandomFloatSequence(int n)
    {
        ValidateCount(n);
        var sequence = new ConcurrentBag<float>();
        Parallel.For(0, n, i => sequence.Add(RandomFloat()));
        return sequence;
    }

    private void ValidateCount(int n)
    {
        if (n <= 0) throw new ArgumentException("The count must be greater than zero.");
    }

    public override string ToString()
    {
        lock (_rangeLock)
        {
            return $"DynamicValueGenerator: Min={_minValue}, Max={_maxValue}";
        }
    }

    // For external logging, consider implementing an interface or using events.
    private void LogGeneration(string message)
    {
        Console.WriteLine($"{DateTime.UtcNow}: {message}");
    }

    public void Dispose()
    {
        _random?.Dispose();
    }
}
```

### Key Considerations

- **Concurrency**: The class uses a lock (`_rangeLock`) to ensure thread-safe updates and reads of the range values.
- **Error Handling**: It throws exceptions for invalid ranges or counts, ensuring robust error handling.
- **Performance**: Uses `ConcurrentBag` for efficient parallel generation of sequences.
- **Resource Management**: Implements `IDisposable` for proper resource cleanup.

This implementation should meet the requirements specified, providing a thread-safe and flexible random value generator.']

