// Function to initialize AES-256-CBC cipher with a given password
int init_aes_256_cbc(const char *password, int iterations, unsigned char **key, unsigned char **iv) {
    if (password == NULL || key == NULL || iv == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 0;
    }

    // Allocate memory for the salt
    const unsigned int SALT_LEN = EVP_MAX_MD_SIZE;
    unsigned char *salt = (unsigned char *)malloc(SALT_LEN);
    if (!salt) {
        fprintf(stderr, "Memory allocation failed for salt.\n");
        return 0;
    }

    // Generate a secure random salt
    if (!RAND_bytes(salt, SALT_LEN)) {
        fprintf(stderr, "Insufficient entropy to generate salt.\n");
        free(salt);
        return 0;
    }

    // Allocate memory for the key and IV
    const unsigned int KEY_LEN = EVP_MAX_KEY_LENGTH;  // AES-256 requires a 32-byte key
    const unsigned int IV_LEN = EVP_MAX_IV_LENGTH;    // AES block size is 16 bytes

    *key = (unsigned char *)malloc(KEY_LEN);
    if (!*key) {
        fprintf(stderr, "Memory allocation failed for key.\n");
        free(salt);
        return 0;
    }

    *iv = (unsigned char *)malloc(IV_LEN);
    if (!*iv) {
        fprintf(stderr, "Memory allocation failed for IV.\n");
        free(*key);
        free(salt);
        return 0;
    }

    // Derive the key using PBKDF2
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, SALT_LEN,
                           iterations, EVP_sha256(), KEY_LEN, *key)) {
        fprintf(stderr, "Key derivation failed.\n");
        free(*iv);
        free(*key);
        free(salt);
        return 0;
    }

    // Generate a secure random IV
    if (!RAND_bytes(*iv, IV_LEN)) {
        fprintf(stderr, "Insufficient entropy to generate IV.\n");
        free(*key);
        free(*iv);
        free(salt);
        return 0;
    }

    printf("AES-256-CBC cipher initialized successfully with %d iterations.\n", iterations);

    // Free the salt as it's no longer needed
    free(salt);
    return 1;  // Success
}

// Example usage
