    unsigned char *key = NULL;
    unsigned char *iv = NULL;
    const char *password = "secure_password";
    int iterations = 100000;

    if (init_aes_256_cbc(password, iterations, &key, &iv)) {
        // Use key and iv for AES operations
        printf("Key and IV initialized.\n");

        // Free allocated memory after use
        free(key);
        free(iv);
    } else {
        fprintf(stderr, "Failed to initialize AES cipher.\n");
    }

    return 0;
}
