// Utility function to check if a number is prime
bool is_prime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return false;
    }
    return true;
}

// Utility function to generate the first n prime numbers within a given range
void generate_primes(long *arr, int count, int max_value) {
    int num = 2;
    for (int i = 0; i < count; ) {
        if (is_prime(num)) {
            arr[i++] = num;
        }
        num++;
    }
}

// Utility function to check if a number is a Fibonacci number
bool is_fibonacci(int num) {
    int a = 0, b = 1, c = a + b;
    if (num == a || num == b) return true;
    while (c <= num) {
        if (c == num) return true;
        a = b;
        b = c;
        c = a + b;
    }
    return false;
}

// Utility function to generate the first n Fibonacci numbers up to 100
void generate_fibonacci(int *arr, int count) {
    int a = 0, b = 1, next;
    for (int i = 0; i < count && b <= 100; ) {
        if (b <= 100) arr[i++] = b;
        next = a + b;
        a = b;
        b = next;
    }
}

// Function to initialize memory and structures
void initialize_structures(long *offsets, int offset_count,
                           int *keys, int key_count,
                           record **records, int record_count) {
    // Initialize offsets with prime numbers
    generate_primes(offsets, offset_count, 10000);

    // Initialize keys with Fibonacci numbers
    generate_fibonacci(keys, key_count);

    // Allocate and initialize records
    *records = (record *)aligned_alloc(alignof(record), record_count * sizeof(record));
    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < record_count; ++i) {
        (*records)[i].offset = &offsets[i % offset_count];
        (*records)[i].key = &keys[i % key_count];
        (*records)[i].metadata = rand() % 1000 + 1;
    }
}

// Function to validate integrity of the initialized structures
bool validate_structures(long *offsets, int offset_count,
                         int *keys, int key_count,
                         record *records, int record_count) {
    for (int i = 0; i < offset_count; ++i) {
        if (!is_prime(offsets[i])) return false;
    }

    for (int i = 0; i < key_count; ++i) {
        if (!is_fibonacci(keys[i])) return false;
    }

    for (int i = 0; i < record_count; ++i) {
        if (records[i].metadata < 1 || records[i].metadata > 1000) return false;
        // Check if pointers are valid (non-null)
        if (records[i].offset == NULL || records[i].key == NULL) return false;
    }

    return true;
}

// Function to deallocate memory
void deallocate_structures(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    const int offset_count = 100; // Example size for prime numbers
    const int key_count = 10;     // Example size for Fibonacci numbers
    const int record_count = 50;  // Example size for records

    long *offsets = (long *)aligned_alloc(alignof(long), offset_count * sizeof(long));
    int *keys = (int *)aligned_alloc(alignof(int), key_count * sizeof(int));
    record *records;

    initialize_structures(offsets, offset_count, keys, key_count, &records, record_count);

    if (!validate_structures(offsets, offset_count, keys, key_count, records, record_count)) {
        printf("Validation failed.\n");
    } else {
        printf("Initialization and validation successful.\n");
    }

    deallocate_structures(offsets, keys, records);
    return 0;
}
