#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t num_offsets;
    size_t num_keys;
    size_t num_records;
    pthread_mutex_t lock;
} MemoryManager;

// Function prototypes
void init_memory_manager(MemoryManager *manager, size_t num_offsets, size_t num_keys, size_t num_records);
void free_memory_manager(MemoryManager *manager);
int calculate_total_memory_usage(const MemoryManager *manager);
void populate_arrays(MemoryManager *manager, int range_min, int range_max);

// Initialize the memory manager
void init_memory_manager(MemoryManager *manager, size_t num_offsets, size_t num_keys, size_t num_records) {
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0) return;

    pthread_mutex_init(&manager->lock, NULL);

    // Allocate memory for offsets and keys
    manager->offsets = malloc(num_offsets * sizeof(long));
    manager->keys = malloc(num_keys * sizeof(int));

    if (!manager->offsets || !manager->keys) {
        free(manager->offsets);
        free(manager->keys);
        pthread_mutex_destroy(&manager->lock);
        return;
    }

    // Allocate memory for records
    manager->records = malloc(num_records * sizeof(record));
    if (!manager->records) {
        free(manager->offsets);
        free(manager->keys);
        pthread_mutex_destroy(&manager->lock);
        return;
    }

    manager->num_offsets = num_offsets;
    manager->num_keys = num_keys;
    manager->num_records = num_records;

    // Populate arrays with initial values
    populate_arrays(manager, 0, INT_MAX - num_records);
}

// Free all allocated resources
void free_memory_manager(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->offsets) free(manager->offsets);
    if (manager->keys) free(manager->keys);
    if (manager->records) free(manager->records);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Calculate total memory usage
int calculate_total_memory_usage(const MemoryManager *manager) {
    int total_memory = 0;

    pthread_mutex_lock((pthread_mutex_t*)&manager->lock);
    if (manager->offsets) total_memory += manager->num_offsets * sizeof(long);
    if (manager->keys) total_memory += manager->num_keys * sizeof(int);
    if (manager->records) total_memory += manager->num_records * sizeof(record);
    pthread_mutex_unlock((pthread_mutex_t*)&manager->lock);

    return total_memory;
}

// Populate arrays with initial values
void populate_arrays(MemoryManager *manager, int range_min, int range_max) {
    pthread_mutex_lock(&manager->lock);

    // Initialize offsets and keys
    for (size_t i = 0; i < manager->num_offsets && i < manager->num_keys; ++i) {
        manager->offsets[i] = i;
        manager->keys[i] = i;
    }

    // Populate records with unique random values
    int *used_values = malloc((range_max - range_min + 1) * sizeof(int));
    if (!used_values) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    for (int j = 0; j < range_max - range_min + 1; ++j)
        used_values[j] = 0;

    for (size_t i = 0; i < manager->num_records; ++i) {
        int random_value;
        do {
            random_value = rand() % (range_max - range_min + 1) + range_min;
        } while (used_values[random_value]);

        used_values[random_value] = 1;
        manager->records[i].value = random_value;
    }

    free(used_values);
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    MemoryManager manager;

    init_memory_manager(&manager, 10, 10, 5);

    printf("Total memory usage: %d bytes\n", calculate_total_memory_usage(&manager));

    free_memory_manager(&manager);

    return 0;
}
```

