#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <yaml.h>
#include <syslog.h>

#define LOG_LEVEL_DEBUG 7

typedef struct {
    const EVP_CIPHER *cipher;
    int key_size;
    int iv_size;
} CipherConfig;

void log_message(int level, const char *message) {
    openlog("encryption_engine", LOG_PID | LOG_NDELAY, LOG_LOCAL1);
    syslog(level, "%s", message);
    closelog();
}

CipherConfig parse_yaml_config(const char *yaml_path) {
    FILE *file = fopen(yaml_path, "rb");
    if (!file) {
        log_message(LOG_ERR, "Failed to open YAML config file.");
        exit(EXIT_FAILURE);
    }

    yaml_parser_t parser;
    yaml_event_t event;

    yaml_parser_initialize(&parser);
    yaml_parser_set_input_file(&parser, file);

    CipherConfig config = {NULL, 0, 0};
    while (1) {
        if (!yaml_parser_parse(&parser, &event))
            break;

        switch (event.type) {
            case YAML_MAPPING_START_EVENT:
                break;
            case YAML_SEQUENCE_START_EVENT:
                break;
            case YAML_SCALAR_EVENT: {
                const char *key = (const char *)event.data.scalar.value;
                if (strcmp(key, "cipher") == 0) {
                    const char *value = (const char *)yaml_get_event_data(&event);
                    config.cipher = EVP_get_cipherbyname(value);
                    if (!config.cipher) {
                        log_message(LOG_ERR, "Unsupported cipher.");
                        exit(EXIT_FAILURE);
                    }
                } else if (strcmp(key, "key_size") == 0) {
                    const char *value = (const char *)yaml_get_event_data(&event);
                    config.key_size = atoi(value);
                } else if (strcmp(key, "iv_size") == 0) {
                    const char *value = (const char *)yaml_get_event_data(&event);
                    config.iv_size = atoi(value);
                }
            } break;
            default:
                break;
        }

        yaml_event_delete(&event);

        if (event.type == YAML_MAPPING_END_EVENT ||
            event.type == YAML_SEQUENCE_END_EVENT) {
            break;
        }
    }

    fclose(file);
    yaml_parser_delete(&parser);

    if (!config.cipher || config.key_size <= 0 || config.iv_size <= 0) {
        log_message(LOG_ERR, "Invalid configuration.");
        exit(EXIT_FAILURE);
    }

    return config;
}

void initialize_encryption_engine(const char *yaml_path, const char *input_data) {
    CipherConfig config = parse_yaml_config(yaml_path);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message(LOG_ERR, "Failed to create cipher context.");
        exit(EXIT_FAILURE);
    }

    unsigned char key[config.key_size / 8];
    unsigned char iv[config.iv_size / 8];

    // Initialize key and IV (example purposes; in practice, use secure methods)
    memset(key, 0x00, sizeof(key));
    memset(iv, 0x01, sizeof(iv));

    if (1 != EVP_EncryptInit_ex(ctx, config.cipher, NULL, key, iv)) {
        log_message(LOG_ERR, "Encryption initialization failed.");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    size_t len;
    unsigned char *encrypted_data = malloc(strlen(input_data) + EVP_MAX_BLOCK_LENGTH);
    if (!encrypted_data) {
        log_message(LOG_ERR, "Memory allocation for encryption failed.");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    int ret = EVP_EncryptUpdate(ctx, encrypted_data, &len, (unsigned char *)input_data, strlen(input_data));
    if (ret != 1) {
        log_message(LOG_ERR, "Encryption update failed.");
        free(encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    int ciphertext_len = len;
    ret = EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len);
    if (ret != 1) {
        log_message(LOG_ERR, "Encryption finalization failed.");
        free(encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    ciphertext_len += len;

    // Output or further process `encrypted_data` here...

    log_message(LOG_INFO, "Encryption successful.");

    free(encrypted_data);
    EVP_CIPHER_CTX_free(ctx);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <config.yaml> <input_string>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initialize_encryption_engine(argv[1], argv[2]);

    return EXIT_SUCCESS;
}
