```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <openssl/bn.h>
#include <openssl/ec.h>
#include <openssl/sha.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_SERVERS 100
#define BUFFER_SIZE 1024

typedef struct {
    char *address;
    int port;
    char *credentials;
} ServerConfig;

typedef struct {
    SSL_CTX *ssl_ctx;
    SSL *ssl;
    struct sockaddr_in server_addr;
    int socket_fd;
    double connection_time; // Placeholder for connection metrics
} ConnectionPoolEntry;

ServerConfig *server_configs[MAX_SERVERS];
int config_count = 0;
ConnectionPoolEntry connection_pool[10]; // Example pool size
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_ssl() {
    SSL_load_error_strings();
    OpenSSL_add_ssl_algorithms();
    SSL_library_init();
}

SSL_CTX* create_ssl_context() {
    const SSL_METHOD *method = TLS_client_method();
    SSL_CTX *ctx = SSL_CTX_new(method);
    if (!ctx) {
        perror("Unable to create SSL context");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    return ctx;
}

void configure_ssl_context(SSL_CTX *ctx) {
    SSL_CTX_set_ecdh_auto(ctx, 1);

    // Load certificates and private key files
    if (SSL_CTX_use_certificate_file(ctx, "cert.pem", SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(ctx, "key.pem", SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
}

void *establish_connection(void *arg) {
    ConnectionPoolEntry *entry = (ConnectionPoolEntry *) arg;
    struct timeval start, end;

    entry->socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (entry->socket_fd < 0) {
        perror("Socket creation failed");
        return NULL;
    }

    entry->server_addr.sin_family = AF_INET;
    entry->server_addr.sin_port = htons(entry->port);

    struct sockaddr_in local_addr = {0};
    inet_pton(AF_INET, entry->address, &entry->server_addr.sin_addr);

    gettimeofday(&start, NULL);
    if (connect(entry->socket_fd, (struct sockaddr *)&entry->server_addr, sizeof(entry->server_addr)) < 0) {
        perror("Connection failed");
        return NULL;
    }
    gettimeofday(&end, NULL);

    entry->ssl = SSL_new(entry->ssl_ctx);
    SSL_set_fd(entry->ssl, entry->socket_fd);

    if (SSL_connect(entry->ssl) <= 0) {
        ERR_print_errors_fp(stderr);
        close(entry->socket_fd);
        return NULL;
    }

    entry->connection_time = ((end.tv_sec - start.tv_sec) * 1000000.0 + end.tv_usec - start.tv_usec) / 1000000.0;

    printf("Connected to %s:%d with connection time: %.2f seconds\n", entry->address, entry->port, entry->connection_time);
    return NULL;
}

void load_server_configs(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Could not open file");
        exit(EXIT_FAILURE);
    }

    char line[BUFFER_SIZE];
    while (fgets(line, sizeof(line), file)) {
        ServerConfig *config = malloc(sizeof(ServerConfig));
        sscanf(line, "%[^:]:%d:%m[^\n]", config->address, &config->port, &(config->credentials));

        server_configs[config_count++] = config;
    }
    fclose(file);
}

void free_server_configs() {
    for (int i = 0; i < config_count; ++i) {
        free(server_configs[i]->address);
        free(server_configs[i]->credentials);
        free(server_configs[i]);
    }
}

void setup_connection_pool(SSL_CTX *ssl_ctx) {
    for (int i = 0; i < 10; ++i) { // Example size of the pool
        connection_pool[i].ssl_ctx = ssl_ctx;
        pthread_create(&connection_pool[i], NULL, establish_connection, &connection_pool[i]);
    }
}

void cleanup_ssl() {
    EVP_cleanup();
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initialize_ssl();
    SSL_CTX *ssl_ctx = create_ssl_context();
    configure_ssl_context(ssl_ctx);

    load_server_configs(argv[1]);

    setup_connection_pool(ssl_ctx);

    // Wait for connections to establish (for demonstration purposes)
    sleep(10); 

    free_server_configs();

    for (int i = 0; i < 10; ++i) {
        SSL_shutdown(connection_pool[i].ssl);
        close(connection_pool[i].socket_fd);
        SSL_free(connection_pool[i].ssl);
    }

    SSL_CTX_free(ssl_ctx);
    cleanup_ssl();

    return EXIT_SUCCESS;
}
```

### Key Points:
- The program reads server configurations from a file and establishes TLS connections using OpenSSL.
- It implements a basic connection pool to manage resources effectively, reducing the overhead of repeated connection attempts.
- Error handling is incorporated throughout, with graceful exits on failure conditions.
- Cryptographic functionalities are initialized but not explicitly utilized in this snippet; they should be integrated as needed based on application logic.

### Note:
- Adjust the file paths for certificates and keys as necessary.
- The connection pool size (`10` in this example) may need tuning based on expected traffic patterns and system resources.']

