using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Runtime.CompilerServices;

public class DynamicRangeGenerator
{
    private readonly object lockObj = new object();

    private double minValue;
    private double maxValue;
    private double? subMinValue;
    private double? subMaxValue;

    public DynamicRangeGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("minValue cannot be greater than maxValue.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    /// <summary>
    /// Generates a random integer within the specified range.
    /// </summary>
    public int GenerateRandomInt(bool inclusive, bool useSubRange = false)
    {
        ValidateInputs();

        double start = useSubRange ? GetValidSubMin() : minValue;
        double end = useSubRange ? GetValidSubMax() : maxValue;

        Random rand = new Random();

        return (int)(inclusive ? rand.NextDouble() * (end - start + 1) + start 
                                : rand.NextDouble() * (end - start) + start);
    }

    /// <summary>
    /// Generates a random float within the specified range.
    /// </summary>
    public double GenerateRandomFloat(bool inclusive, bool useSubRange = false)
    {
        ValidateInputs();

        double start = useSubRange ? GetValidSubMin() : minValue;
        double end = useSubRange ? GetValidSubMax() : maxValue;

        Random rand = new Random();

        return inclusive ? rand.NextDouble() * (end - start + 1) + start 
                         : rand.NextDouble() * (end - start) + start;
    }

    /// <summary>
    /// Generates a sequence of `n` random integers.
    /// </summary>
    public List<int> GenerateRandomIntSequence(int n, bool inclusive)
    {
        if (n <= 0)
            return new List<int>();

        ValidateInputs();

        var result = new List<int>();
        Random rand = new Random();

        for (int i = 0; i < n; i++)
            result.Add(GenerateRandomInt(inclusive));

        return result;
    }

    /// <summary>
    /// Generates a sequence of `n` random floats.
    /// </summary>
    public List<double> GenerateRandomFloatSequence(int n, bool inclusive)
    {
        if (n <= 0)
            return new List<double>();

        ValidateInputs();

        var result = new List<double>();
        Random rand = new Random();

        for (int i = 0; i < n; i++)
            result.Add(GenerateRandomFloat(inclusive));

        return result;
    }

    /// <summary>
    /// Sets a sub-range within the main range.
    /// </summary>
    public void SetSubRange(double subMin, double subMax)
    {
        lock (lockObj)
        {
            if (subMin > subMax || subMin < minValue || subMax > maxValue)
                throw new ArgumentException("Invalid sub-range.");

            this.subMinValue = subMin;
            this.subMaxValue = subMax;
        }
    }

    private double GetValidSubMin() => subMinValue ?? minValue;
    private double GetValidSubMax() => subMaxValue ?? maxValue;

    private void ValidateInputs()
    {
        if (minValue > maxValue)
            throw new InvalidOperationException("Invalid range configuration.");
    }

    /// <summary>
    /// Overrides the ToString method to show current range settings.
    /// </summary>
    public override string ToString()
    {
        return $"Main Range: [{minValue}, {maxValue}] " +
               $"Sub-Range: [{subMinValue ?? double.MinValue}, {subMaxValue ?? double.MaxValue}]";
    }

    // A Rust function placeholder for demonstration purposes
    [MethodImpl(MethodImplOptions.InternalCall)]
    private extern void CreateHttpClient(string url, bool disableCertificateValidation);

    public static RequestBuilder CreateHttpRequest(string url, bool disableCertificateValidation = false)
    {
        lock (lockObj)
        {
            var httpClientHandler = new HttpClientHandler();

            if (disableCertificateValidation)
                httpClientHandler.ServerCertificateCustomValidationCallback =
                    HttpClientHandler.DangerousAcceptAnyServerCertificateValidator;

            using var client = new HttpClient(httpClientHandler);

            return new RequestBuilder(client, url);
        }
    }

    // A simple representation of a RequestBuilder for demonstration
