// Function to generate a Gaussian distributed random number
double gaussian_random(double mean, double stddev) {
    static int hasSpare = 0;
    static double spare;

    if (hasSpare) {
        hasSpare = 0;
        return mean + stddev * spare;
    }

    double u1, u2, w, mult;
    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);

        w = sqrt(-2.0 * log(u1)) * sin(2.0 * M_PI * u2);
        mult = stddev * w + mean;
    } while (u1 <= DBL_EPSILON);

    spare = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
    hasSpare = 1;

    return mult;
}

// Function to initialize sensor data array
sensor_data* init_sensor_data_array(size_t initial_capacity) {
