    data_array[*current_size].sensor_reading = gaussian_random(mean, stddev);
    snprintf(data_array[*current_size].device_type, sizeof(data_array[*current_size].device_type), "%s", device_type);

    (*current_size)++;
}

// Function to manage sensor data with error handling and logging
