```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 150 * 1024 * 1024 // 150 MB
#define MAX_RECORDS 1024

typedef struct {
    int value;
    long* offset_ptr;
} Record;

typedef struct {
    Record* records;
    size_t count;
    pthread_mutex_t lock;
} ResourceManager;

static void cleanup_resources(ResourceManager* res) {
    if (res->records != NULL) {
        for (size_t i = 0; i < res->count; ++i) {
            free(res->records[i].offset_ptr);
        }
        free(res->records);
    }
}

int is_power_of_two(size_t n) {
    return (n > 0) && ((n & (n - 1)) == 0);
}

size_t calculate_size(size_t records, size_t long_count, size_t int_count) {
    return sizeof(Record) * records + sizeof(long) * long_count + sizeof(int) * int_count;
}

void* manage_memory(void* arg) {
    ResourceManager* res = (ResourceManager*)arg;

    srand((unsigned)time(NULL));
    const int INT_MAX_VALUE = 1000; // Define max value for random generation
    size_t record_size = 1;
    while (record_size < MAX_RECORDS && !is_power_of_two(record_size)) {
        ++record_size;
    }

    int total_int_value = 0;
    while (calculate_size(record_size, record_size, record_size) > MAX_MEMORY_USAGE || 
           total_int_value + INT_MAX_VALUE * record_size > 1000000) {

        if (record_size < 1) {
            fprintf(stderr, "Insufficient memory to allocate even the smallest valid size\n");
            return NULL;
        }

        --record_size;
    }

    res->records = (Record*)calloc(record_size, sizeof(Record));
    long* offsets = (long*)malloc(record_size * sizeof(long));
    int* keys = (int*)malloc(record_size * sizeof(int));

    if (!res->records || !offsets || !keys) {
        cleanup_resources(res);
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    for (size_t i = 0; i < record_size; ++i) {
        int random_value = rand() % INT_MAX_VALUE + 1;
        total_int_value += random_value;

        if (total_int_value > 1000000) {
            free(keys);
            free(offsets);
            cleanup_resources(res);
            fprintf(stderr, "Cannot satisfy the integer sum constraint\n");
            return NULL;
        }

        res->records[i].value = random_value;
        res->records[i].offset_ptr = &offsets[i];
    }

    res->count = record_size;

    pthread_mutex_init(&res->lock, NULL);

    // Placeholder for integration with external data source or concurrency handling

    return (void*)res;
}

void free_resources(ResourceManager* res) {
    cleanup_resources(res);
    pthread_mutex_destroy(&res->lock);
}

int main() {
    ResourceManager manager = {0};

    if (!manage_memory(&manager)) {
        fprintf(stderr, "Memory management failed\n");
        return 1;
    }

    // Simulate some operations
    printf("Managed %zu records\n", manager.count);

    free_resources(&manager);
    return 0;
}
```

### Key Design Decisions:

- **Power of Two Records:** The function ensures the number of records is a power of two, optimizing memory allocation and access.
- **Memory Constraints Handling:** Memory allocations respect the 150 MB constraint. If allocations exceed limits or constraints, the size is adjusted down to fit within these boundaries.
- **Error Handling:** Thorough checks ensure that if memory cannot be allocated, resources are properly freed, minimizing leaks.
- **Thread Safety:** A mutex lock is initialized for thread-safe operations on `ResourceManager`.
- **Random Value Generation:** Random values are assigned while ensuring their sum doesn't exceed 1 million. If constraints aren't met, the function degrades gracefully.
- **Pre-allocation and Bulk Allocation:** Memory is allocated in bulk to minimize fragmentation and reduce overhead during potential resizing.

### Areas for Future Enhancement:

- Implement dynamic resizing logic with further error handling if initial allocations are too small but within memory limits.
- Integrate logging or external data sources safely, considering latency effects on performance.
- Optimize concurrency management for high-frequency usage scenarios.']

['Below is a C implementation that addresses the requirements specified. This code uses POSIX threads (`pthread`) and semaphores to manage concurrency, along with dynamic memory allocation for managing a collection of semaphores.

```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define MAX_THREADS 100

typedef struct {
    sem_t *sems;
    int size;
    pthread_mutex_t lock;
} SemaphoreCollection;

SemaphoreCollection* init_semaphore_collection(int initial_size) {
    SemaphoreCollection *collection = (SemaphoreCollection*)malloc(sizeof(SemaphoreCollection));
    if (!collection) {
        perror("Failed to allocate memory for semaphore collection");
        return NULL;
    }

    collection->sems = (sem_t**)malloc(initial_size * sizeof(sem_t*));
    if (!collection->sems) {
        free(collection);
        perror("Failed to allocate memory for semaphores");
        return NULL;
    }

    for (int i = 0; i < initial_size; i++) {
        collection->sems[i] = malloc(sizeof(sem_t));
        if (!collection->sems[i]) {
            for (int j = 0; j < i; j++) free(collection->sems[j]);
            free(collection->sems);
            free(collection);
            perror("Failed to allocate memory for semaphore");
            return NULL;
        }
        sem_init(collection->sems[i], 1, 0); // Initialize with a non-negative value
    }

    collection->size = initial_size;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

int create_semaphore(SemaphoreCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    int index = -1;
    for (int i = 0; i < collection->size; i++) {
        if (!sem_getvalue(collection->sems[i], NULL)) { // Check if semaphore is initialized
            index = i;
            break;
        }
    }

    if (index == -1) {
        sem_t *new_sem = malloc(sizeof(sem_t));
        if (!new_sem) {
            pthread_mutex_unlock(&collection->lock);
            perror("Failed to allocate memory for new semaphore");
            return -1;
        }

        sem_init(new_sem, 1, 0); // Initialize with a non-negative value
        collection->sems = (sem_t**)realloc(collection->sems, (collection->size + 1) * sizeof(sem_t*));
        if (!collection->sems) {
            free(new_sem);
            pthread_mutex_unlock(&collection->lock);
            perror("Failed to reallocate memory for semaphores");
            return -1;
        }

        collection->sems[collection->size] = new_sem;
        index = collection->size++;
    }

    pthread_mutex_unlock(&collection->lock);

    printf("Semaphore created at index %d\n", index);
    return index;
}

void delete_semaphore(SemaphoreCollection *collection, int index) {
    if (index < 0 || index >= collection->size) {
        fprintf(stderr, "Invalid semaphore index: %d\n", index);
        return;
    }

    pthread_mutex_lock(&collection->lock);

    sem_destroy(collection->sems[index]);
    free(collection->sems[index]);

    for (int i = index; i < collection->size - 1; i++) {
        collection->sems[i] = collection->sems[i + 1];
    }

    collection->sems[collection->size - 1] = NULL;
    collection->size--;

    pthread_mutex_unlock(&collection->lock);

    printf("Semaphore deleted at index %d\n", index);
}

void cleanup_semaphore_collection(SemaphoreCollection *collection) {
    if (!collection) return;

    for (int i = 0; i < collection->size; i++) {
        sem_destroy(collection->sems[i]);
        free(collection->sems[i]);
    }

    free(collection->sems);
    pthread_mutex_destroy(&collection->lock);
    free(collection);

    printf("Semaphore collection cleaned up\n");
}

void *thread_function(void *arg) {
    SemaphoreCollection *collection = (SemaphoreCollection *)arg;

    int sem_index = create_semaphore(collection);
    if (sem_index == -1) return NULL; // Error handling

    sem_wait(collection->sems[sem_index]);
    printf("Thread %ld acquired semaphore %d\n", pthread_self(), sem_index);

    sem_post(collection->sems[sem_index]);
    delete_semaphore(collection, sem_index);

    return NULL;
}

int main() {
    SemaphoreCollection *collection = init_semaphore_collection(10);
    if (!collection) return 1;

    pthread_t threads[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_function, collection);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_semaphore_collection(collection);

    return 0;
}
```

### Key Features:
- **Dynamic Management**: Supports dynamic creation and deletion of semaphores.
- **Thread Safety**: Uses mutex locks to ensure thread-safe operations on the semaphore collection.
- **Error Handling**: Checks for memory allocation failures and invalid indices.
- **Resource Cleanup**: Properly destroys semaphores and cleans up resources, even in case of errors.
- **Logging**: Simple logging using `printf` for tracking semaphore operations.

This implementation provides a robust foundation for managing semaphores dynamically while handling concurrency effectively. Adjustments can be made to integrate with existing configuration management systems or enhance logging as needed.']

['Here's a C implementation of a robust semaphore management system that addresses the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

#define MAX_SEMAPHORES 50

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int count;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;

// Custom logging function
void log_error(const char *message) {
    // Placeholder for integration with custom logging framework
    fprintf(stderr, "%s\n", message);
}

// Initialize a semaphore
int init_semaphore(int initial_value) {
    if (semaphore_count >= MAX_SEMAPHORES) {
        log_error("Semaphore limit reached");
        return -ENOMEM;
    }

    Semaphore *sem = &semaphores[semaphore_count++];
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
    sem->count = initial_value;

    if (pthread_mutex_init(&sem->mutex, NULL) != 0 || 
        pthread_cond_init(&sem->cond, NULL) != 0) {
        log_error("Failed to initialize semaphore");
        semaphore_count--;
        return -ENOMEM;
    }

    return 0;
}

// Wait (decrement) operation
int wait_semaphore(Semaphore *sem) {
    if (!sem) {
        log_error("Invalid semaphore reference");
        return -EINVAL;
    }

    pthread_mutex_lock(&sem->mutex);
    while (sem->count == 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->count--;
    pthread_mutex_unlock(&sem->mutex);

    return 0;
}

// Signal (increment) operation
int signal_semaphore(Semaphore *sem) {
    if (!sem) {
        log_error("Invalid semaphore reference");
        return -EINVAL;
    }

    pthread_mutex_lock(&sem->mutex);
    sem->count++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);

    return 0;
}

// Delete a semaphore
int delete_semaphore(Semaphore *sem) {
    if (!sem) {
        log_error("Invalid semaphore reference");
        return -EINVAL;
    }

    int result = pthread_mutex_destroy(&sem->mutex);
    result |= pthread_cond_destroy(&sem->cond);

    if (result != 0) {
        log_error("Failed to destroy semaphore");
        return -EIO;
    }

    // Mark as deleted
    sem->count = -1;

    return 0;
}

// Retrieve current state information
int get_semaphore_count(Semaphore *sem) {
    if (!sem) {
        log_error("Invalid semaphore reference");
        return -EINVAL;
    }

    pthread_mutex_lock(&sem->mutex);
    int count = sem->count;
    pthread_mutex_unlock(&sem->mutex);

    return count;
}

// Example usage
int main() {
    // Initialize a semaphore with initial value 1
    if (init_semaphore(1) != 0) {
        log_error("Failed to initialize semaphore");
        return EXIT_FAILURE;
    }

    Semaphore *sem = &semaphores[0];

    // Simulate thread operations
    wait_semaphore(sem);
    printf("Semaphore count after wait: %d\n", get_semaphore_count(sem));

    signal_semaphore(sem);
    printf("Semaphore count after signal: %d\n", get_semaphore_count(sem));

    delete_semaphore(sem);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Mutexes and condition variables ensure safe access to semaphore states.
- **Error Handling**: Logs errors using a custom logging function without crashing.
- **Resource Management**: Gracefully handles memory allocation failures.
- **Usability**: Provides clear interfaces for initialization, waiting, signaling, deletion, and state retrieval.
- **Scalability**: Supports up to 50 semaphores concurrently.']

