    }

    for (size_t i = 0; i < record_count; i++) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].offset = rand(); // Example offset
    }

    fprintf(log, "Records initialized successfully.\n");
    fclose(log);

    return records;
}

// Function to serialize records into a byte array
void serialize_records(const Record* records, size_t record_count, uint8_t** serialized_data, size_t* data_size) {
    *data_size = record_count * (sizeof(int) + sizeof(long));
    *serialized_data = (uint8_t*)malloc(*data_size);

    if (!*serialized_data) {
        fprintf(stderr, "Error: Memory allocation failed for serialization.\n");
        return;
    }

    uint8_t *ptr = *serialized_data;
    for (size_t i = 0; i < record_count; i++) {
        memcpy(ptr, &records[i].value, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &records[i].offset, sizeof(long));
        ptr += sizeof(long);
    }
}

// Function to deserialize the byte array back into records
int deserialize_records(const uint8_t* serialized_data, size_t data_size, Record** records, size_t* record_count) {
    *record_count = data_size / (sizeof(int) + sizeof(long));
    *records = (Record*)malloc(*record_count * sizeof(Record));

    if (!*records) {
        fprintf(stderr, "Error: Memory allocation failed for deserialization.\n");
        return -1;
    }

    const uint8_t *ptr = serialized_data;
    for (size_t i = 0; i < *record_count; i++) {
        memcpy(&(*records)[i].value, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&(*records)[i].offset, ptr, sizeof(long));
        ptr += sizeof(long);
    }

    return 0;
}

// Function to free allocated memory for records
void free_records(Record* records) {
    if (records) {
        free(records);
    }
}

// Function to generate a random string of specified length from given charset
char* generate_random_string(size_t length, const char* charset) {
    size_t charset_length = strlen(charset);
    char *random_str = (char*)malloc(length + 1); // +1 for null terminator

    if (!random_str) {
        fprintf(stderr, "Error: Memory allocation failed for random string.\n");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < length; i++) {
        random_str[i] = charset[rand() % charset_length];
    }
    random_str[length] = '\0';

    return random_str;
}

// Function to hash a password using a simple hashing algorithm
uint32_t hash_password(const char* password) {
    uint32_t hash = 5381;
    int c;

    while ((c = *password++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }

    return hash;
}

int main() {
    size_t record_count = 10;
    size_t max_size = MAX_MEMORY_SIZE;
    int min_value = 0, max_value = 100;

    Record* records = initialize_records(record_count, min_value, max_value, max_size, "log.txt");
    if (!records) return EXIT_FAILURE;

    uint8_t *serialized_data;
    size_t data_size;
    serialize_records(records, record_count, &serialized_data, &data_size);

    Record *deserialized_records;
    size_t deserialized_record_count;
    deserialize_records(serialized_data, data_size, &deserialized_records, &deserialized_record_count);

    free(serialized_data);
    free_records(records);
    free_records(deserialized_records);

    find_largest_integer();

    char* random_str = generate_random_string(10, "abcdefghijklmnopqrstuvwxyz");
    if (random_str) {
        printf("Random String: %s\n", random_str);
        free(random_str);
    }

    const char *password = "secure_password";
    uint32_t hashed_password = hash_password(password);
    printf("Hashed Password: %u\n", hashed_password);

    return EXIT_SUCCESS;
}
