#define MAX_ENTRIES 100
#define STRING_MIN_LENGTH 5
#define STRING_MAX_LENGTH 20
#define RECORD_INT_RANGE_LOW 1
#define RECORD_INT_RANGE_HIGH 100

typedef struct record {
    int value;
} Record;

typedef struct entry {
    char *value;
    long *offsets;
    Record records[MAX_ENTRIES];
    struct entry *next;
} Entry;

typedef struct node {
    int key;
    Entry *entries_head;
    pthread_mutex_t lock;
} Node;

Node* create_node(int key) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;

    node->key = key;
    node->entries_head = NULL;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

Entry* create_entry(const char *value_str, long offsets_count, int records_count) {
    Entry *entry = (Entry *)malloc(sizeof(Entry));
    if (!entry) return NULL;

    entry->value = strdup(value_str);
    entry->offsets = (long *)malloc(offsets_count * sizeof(long));
    if (!entry->offsets) {
        free(entry->value);
        free(entry);
        return NULL;
    }

    for (int i = 0; i < offsets_count; ++i) {
        entry->offsets[i] = rand() % 1000; // Example offset value
    }

    for (int i = 0; i < records_count; ++i) {
        entry->records[i].value = rand() % (RECORD_INT_RANGE_HIGH - RECORD_INT_RANGE_LOW + 1) + RECORD_INT_RANGE_LOW;
    }

    entry->next = NULL;

    return entry;
}

void add_entry_to_node(Node *node, Entry *entry) {
    if (!node || !entry) return;

    pthread_mutex_lock(&node->lock);

    entry->next = node->entries_head;
    node->entries_head = entry;

    pthread_mutex_unlock(&node->lock);
}

void free_entry(Entry *entry) {
    if (entry) {
        free(entry->value);
        free(entry->offsets);
        free(entry);
    }
}

void free_node(Node *node) {
    if (!node) return;

    Entry *current = node->entries_head;
    while (current) {
        Entry *next = current->next;
        free_entry(current);
        current = next;
    }

    pthread_mutex_destroy(&node->lock);
    free(node);
}

void handle_disconnection() {
    // Placeholder for handling disconnections
}

int main() {
    srand(time(NULL));

    Node *nodes[MAX_ENTRIES];
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        nodes[i] = create_node(i);

        if (!nodes[i]) continue;

        int entries_count = rand() % MAX_ENTRIES;
        for (int j = 0; j < entries_count; ++j) {
            int string_length = STRING_MIN_LENGTH + rand() % (STRING_MAX_LENGTH - STRING_MIN_LENGTH + 1);
            char *value_str = malloc(string_length + 1);
            if (!value_str) continue;

            snprintf(value_str, string_length + 1, "String%d", j);

            Entry *entry = create_entry(value_str, 5, rand() % MAX_ENTRIES); // Example offsets count
            free(value_str);

            if (entry) {
                add_entry_to_node(nodes[i], entry);
            } else {
                handle_disconnection();
            }
        }
    }

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        free_node(nodes[i]);
    }

    return 0;
}
