class HttpClient {
public:
    HttpClient(boost::asio::io_context& ioc, ConfigManager& config_manager)
        : resolver_(ioc), load_balancer_(), config_manager_(config_manager) {}

    void makeRequest(const std::string& method, const std::string& path) {
        auto endpoint = load_balancer_.selectOptimalEndpoint();
        // Create and send HTTP request
        boost::beast::tcp_stream stream{ioc};
        connect(stream, endpoint);
        send_request(stream, method, path);
        receive_response(stream);
    }

private:
