#define FLOAT_ARRAY_SIZE 300000 // Assuming each float is 4 bytes, this takes 1.2 MB
#define CHAR_ARRAY_SIZE (MAX_NODES * 128) // Each string can be up to 128 chars
#define TOTAL_MEMORY_LIMIT (15 * 1024 * 1024)

struct node {
    int index;
    float value;
    char filename[129]; // 128 characters + null terminator
};

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_memory(void* arg) {
    size_t total_size = FLOAT_ARRAY_SIZE + CHAR_ARRAY_SIZE;
    struct {
        float* float_array;
        char** char_array;
        struct node** node_pointers;
    } *memory = (struct *)malloc(sizeof(*memory));

    if (!memory || total_size + NODE_STRUCT_SIZE > TOTAL_MEMORY_LIMIT) {
        fprintf(stderr, "Error: Insufficient memory\n");
        free(memory);
        return NULL;
    }

    memory->float_array = malloc(FLOAT_ARRAY_SIZE);
    memory->char_array = malloc(MAX_NODES * sizeof(char*));
    memory->node_pointers = malloc(MAX_NODES * sizeof(struct node*));

    if (!memory->float_array || !memory->char_array || !memory->node_pointers) {
        fprintf(stderr, "Error: Insufficient memory\n");
        free(memory->float_array);
        free(memory->char_array);
        free(memory->node_pointers);
        free(memory);
        return NULL;
    }

    size_t node_count = MAX_NODES / ARRAY_SIZE_MULTIPLE * ARRAY_SIZE_MULTIPLE;

    struct node* nodes = malloc(node_count * NODE_STRUCT_SIZE);
    if (!nodes) {
        fprintf(stderr, "Error: Insufficient memory\n");
        free(memory->float_array);
        free(memory->char_array);
        free(memory->node_pointers);
        free(memory);
        return NULL;
    }

    srand(time(NULL));
    int index_sum = 0;
    size_t char_length_total = 0;

    for (size_t i = 0; i < node_count; ++i) {
        nodes[i].index = rand() % 100 + 1; // Adjust range as necessary
        index_sum += nodes[i].index;

        if (index_sum > 50000) {
            fprintf(stderr, "Error: Index sum exceeds limit\n");
            free(nodes);
            free(memory->float_array);
            free(memory->char_array);
            free(memory->node_pointers);
            free(memory);
            return NULL;
        }

        nodes[i].value = 0.0f; // Initialize value
        char* filename = nodes[i].filename;
        size_t filename_length = rand() % (64 + 1); // Length between 0 and 64

        snprintf(filename, sizeof(nodes[i].filename), "file_%zu", i);
        strcpy(&filename[filename_length], "\0"); // Ensure null-termination
        char_length_total += filename_length;

        if ((char_length_total / (i + 1)) > 64) {
            fprintf(stderr, "Error: Average string length exceeds limit\n");
            free(nodes);
            free(memory->float_array);
            free(memory->char_array);
            free(memory->node_pointers);
            free(memory);
            return NULL;
        }

        memory->node_pointers[i] = &nodes[i];
    }

    pthread_mutex_unlock(&mutex);

    // Simulate traversal and operation
    for (size_t i = 0; i < node_count; ++i) {
        size_t filename_length = strlen(nodes[i].filename);
        nodes[i].value += filename_length;
    }

    // Free allocated memory
    free(memory->float_array);
    free(memory->char_array);
    free(memory->node_pointers);
    free(nodes);
    free(memory);

    return NULL;
}

void* simulate_concurrent_execution(void* arg) {
    pthread_mutex_lock(&mutex);
    initialize_memory(NULL);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    const int thread_count = 10; // Simulate concurrent clients
    pthread_t threads[thread_count];

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, simulate_concurrent_execution, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
