#include <iostream>
#include <thread>
#include <chrono>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <functional>
#include <atomic>

namespace MetricsFramework {

    enum Granularity {
        SECONDLY,
        MINUTELY,
        HOURLY
    };

    class MetricsCollector {
    private:
        std::vector<std::function<void()>> dataCollectors;
        static struct Config {
            std::chrono::milliseconds samplingRate = std::chrono::seconds(1);
            Granularity granularity = SECONDLY;
        } config;

        std::atomic<bool> running{false};
        std::thread workerThread;
        std::mutex mtx;
        std::condition_variable cv;

        void collectData() {
            while (running) {
                std::unique_lock<std::mutex> lock(mtx);

                // Simulate data collection
                for (auto& collector : dataCollectors) {
                    collector();
                }

                // Adjust sleep time based on granularity and config.samplingRate
                auto sleepDuration = calculateSleepDuration();
                cv.wait_for(lock, sleepDuration);

            }
        }

        std::chrono::milliseconds calculateSleepDuration() const {
            switch (config.granularity) {
                case MINUTELY:
                    return config.samplingRate * 60;
                case HOURLY:
                    return config.samplingRate * 3600;
                default: // SECONDLY
                    return config.samplingRate;
            }
        }

    public:
        MetricsCollector() {
            running = true;
            workerThread = std::thread(&MetricsCollector::collectData, this);
        }

        ~MetricsCollector() {
            stop();
        }

        void registerDataCollector(std::function<void()> collector) {
            dataCollectors.push_back(collector);
        }

        static void adjustSamplingRate(const std::chrono::milliseconds& newRate) {
            config.samplingRate = newRate;
        }

        void stop() {
            if (running) {
                running = false;
                cv.notify_all();
                workerThread.join();
            }
        }
    };

}

int main() {
    MetricsFramework::MetricsCollector collector;

    // Register a sample data collector
    collector.registerDataCollector([](){
        std::cout << "Collecting metrics..." << std::endl;
        // Simulate metric collection logic here
    });

    // Adjust the sampling rate dynamically after initialization
    MetricsFramework::MetricsCollector::adjustSamplingRate(std::chrono::milliseconds(500));

    // Run for demonstration purpose
    std::this_thread::sleep_for(std::chrono::seconds(5));

    return 0;
}
```

