['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_MEMORY 15 * 1024 * 1024 // 15 MB
#define MAX_RECORDS 1024

typedef struct {
    int value;
    long* ptr;
} Record;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

size_t calculate_array_sizes(size_t num_offsets, size_t num_keys) {
    size_t offset_size = sizeof(long) * num_offsets;
    size_t key_size = sizeof(int) * num_keys;

    if (offset_size + key_size > MAX_MEMORY) {
        // Adjust sizes to fit within the limit
        while (num_offsets > 0 && num_keys > 0 &&
               (offset_size + key_size > MAX_MEMORY)) {
            offset_size -= sizeof(long);
            --num_offsets;
            if (offset_size + key_size <= MAX_MEMORY) break;

            key_size -= sizeof(int);
            --num_keys;
        }
    }

    return num_offsets * sizeof(long) + num_keys * sizeof(int);
}

Record* allocate_records(size_t initial_power_of_two, size_t *allocated_count) {
    size_t size = 1 << initial_power_of_two; // power of two
    while (size > MAX_RECORDS || (sizeof(Record) * size >= MAX_MEMORY)) {
        --initial_power_of_two;
        size = 1 << initial_power_of_two;
    }

    Record* records = malloc(sizeof(Record) * size);
    if (!records) return NULL;

    *allocated_count = size;
    return records;
}

void initialize_records(Record* records, size_t count, int max_value_sum) {
    srand(time(NULL)); // Seed for random number generation
    int cumulative_sum = 0;

    for (size_t i = 0; i < count; ++i) {
        int value_range = 10; // initial range can be adjusted
        int value;

        do {
            value = rand() % value_range + 1;
        } while (cumulative_sum + value > max_value_sum);

        records[i].value = value;
        cumulative_sum += value;
        records[i].ptr = NULL; // Can be set to point to specific memory
    }
}

Record* dynamic_resize(Record* current_records, size_t *current_size) {
    if (!(*current_size)) return NULL;

    size_t new_power_of_two = (*current_size == 1 << (8 - 1)) ? 
                              (*current_size) : (2 * (*current_size));

    Record* new_records = allocate_records(__builtin_clz(MAX_RECORDS - new_power_of_two), current_size);
    if (!new_records) return NULL;

    // Copy existing records to the newly allocated space
    for (size_t i = 0; i < *current_size; ++i) {
        new_records[i] = current_records[i];
    }

    free(current_records);
    return new_records;
}

void error_handling_example() {
    Record* records = allocate_records(8, NULL); // Start with 256 records
    if (!records) {
        fprintf(stderr, "Failed to allocate initial records array.\n");
        return;
    }

    initialize_records(records, 256, 100000);

    // Simulate condition for resizing
    size_t current_size = 256; 
    records = dynamic_resize(records, &current_size);
    if (!records && current_size) {
        fprintf(stderr, "Failed to resize records array.\n");
    }

    free(records);
}

int main() {
    error_handling_example();
    return 0;
}
```

This C code demonstrates a complex memory management function designed for dynamic and resource-constrained conditions. The implementation includes:

1. Efficient memory allocation and checks for two arrays.
2. Allocation of an array with `Record` structures, ensuring size constraints based on power of two and total memory limits.
3. Initialization of `Record` values while respecting cumulative sum constraints.
4. A mechanism for dynamic resizing of the records array under conditions where initial allocations are insufficient.
5. Robust error handling to manage memory allocation failures gracefully.

The code ensures thread safety using a mutex lock, though more advanced techniques could be explored depending on specific needs and performance requirements. Adjustments might be necessary based on profiling results or specific system constraints.']

