public class StateLoader {

    private static final ConcurrentHashMap<String, Theme> themeCache = new ConcurrentHashMap<>();
    private static final String DEFAULT_THEME_KEY = "default_theme";

    public static MoSTState initializeState(Path filePath) throws IOException {
        if (filePath == null || !Files.exists(filePath)) {
            try {
                Files.createDirectories(filePath.getParent());
                try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filePath.toFile()))) {
                    MoSTState defaultState = new MoSTState();
                    oos.writeObject(defaultState);
                }
            } catch (IOException e) {
                throw new IOException("Failed to create a default state file.", e);
            }
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath.toFile()))) {
            return (MoSTState) ois.readObject();
        } catch (ClassNotFoundException | IOException e) {
            throw new IOException("Error deserializing the state object from file.", e);
        }
    }

    public static Theme getTheme(String themeKey, Path themesDirectory) throws IOException {
        return themeCache.computeIfAbsent(themeKey, key -> loadExternalTheme(key, themesDirectory));
    }

    private static Theme loadExternalTheme(String themeKey, Path themesDirectory) throws IOException {
        try (InputStream is = new FileInputStream(themesDirectory.resolve(themeKey + ".png").toFile())) {
            return new Theme(new BitmapDecoder().decode(is));
        } catch (FileNotFoundException e) {
            // Fallback to default theme if external theme file is not found
            return loadDefaultTheme();
        }
    }

    private static Theme loadDefaultTheme() throws IOException {
