<?php

// Load Composer's autoloader if available
if (file_exists(__DIR__ . '/vendor/autoload.php')) {
    require __DIR__ . '/vendor/autoload.php';
} else {
    die("Autoload file not found. Run 'composer install' to set up dependencies.\n");
}

// Define default environment and configuration path
$defaultEnv = 'production';
$configPath = __DIR__ . '/config/config.json';

// Determine the current environment based on CLI argument or ENV variable
$currentEnv = getenv('APP_ENV') ?: (isset($argv[1]) ? $argv[1] : $defaultEnv);
$supportedEnvironments = ['development', 'testing', 'production'];

if (!in_array($currentEnv, $supportedEnvironments)) {
    die("Unsupported environment: {$currentEnv}. Supported environments are: " . implode(', ', $supportedEnvironments) . ".\n");
}

// Load the configuration file
$configData = json_decode(file_get_contents($configPath), true);
if (json_last_error() !== JSON_ERROR_NONE) {
    die("Failed to load or parse configuration file.\n");
}

// Merge command-line parameters with config, if provided
foreach ($argv as $index => $arg) {
    if (strpos($arg, '--') === 0 && $index > 1) { // Skip script name and environment parameter
        list($key, $value) = explode('=', substr($arg, 2), 2);
        $configData[$currentEnv][$key] = $value;
    }
}

// Set environment variables based on the loaded configuration
foreach ($configData[$currentEnv] as $key => $value) {
    putenv("{$key}={$value}");
}

echo "Configuration for {$currentEnv} environment has been set.\n";

