#define MAX_ENTRIES 100
#define STRING_MIN_LENGTH 5
#define STRING_MAX_LENGTH 50
#define ARRAY_SIZE 10

struct entry {
    char *value;
};

struct node {
    int key;
    struct entry *entries;
    size_t entry_count;
    pthread_mutex_t lock;  // For concurrency support
