// Helper function for string compression using zlib
void compress_string(const char *input, char **output) {
    uLongf compressed_size = compressBound(strlen(input));
    *output = malloc(compressed_size);
    if (*output != NULL && compress((Bytef *)*output, &compressed_size, (const Bytef *)input, strlen(input)) == Z_OK) {
        // Truncate the buffer to actual size after compression
        char *temp = realloc(*output, compressed_size);
        if (temp != NULL) *output = temp;
    }
}

// Helper function for random string generation
void generate_random_string(char *buffer, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (size_t i = 0; i < length; i++) {
        buffer[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    buffer[length] = '\0';
}

// Function to free all allocated memory
void free_memory(struct node *nodes, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&nodes[i].lock);
        for (size_t j = 0; j < nodes[i].entry_count; ++j) {
            free(nodes[i].entries[j].value);
        }
        free(nodes[i].entries);
        pthread_mutex_unlock(&nodes[i].lock);
        pthread_mutex_destroy(&nodes[i].lock);
    }
    free(nodes);
}

// Function to initialize and populate nodes
struct node* manage_memory(size_t num_entries_per_node) {
    struct node *nodes = malloc(ARRAY_SIZE * sizeof(struct node));
    if (!nodes) return NULL;

    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        nodes[i].key = rand() % 100;
        nodes[i].entry_count = num_entries_per_node;
        nodes[i].entries = malloc(num_entries_per_node * sizeof(struct entry));
        if (!nodes[i].entries) {
            free_memory(nodes, i);
            return NULL;
        }

        pthread_mutex_init(&nodes[i].lock, NULL);

        for (size_t j = 0; j < num_entries_per_node; ++j) {
            size_t length = STRING_MIN_LENGTH + rand() % (STRING_MAX_LENGTH - STRING_MIN_LENGTH + 1);
            char *random_string = malloc(length + 1);
            generate_random_string(random_string, length);

            char *compressed_string;
            compress_string(random_string, &compressed_string);

            nodes[i].entries[j].value = compressed_string;

            free(random_string);
        }
    }

    return nodes;
}

// Example usage
int main() {
    size_t num_entries_per_node = 5;  // Specify the number of entries per node

    struct node *nodes = manage_memory(num_entries_per_node);

    if (nodes) {
        // Do something with the nodes...

        // Free allocated memory at the end
        free_memory(nodes, ARRAY_SIZE);
    }

    return 0;
}
```

### Key Points:
- **Concurrency Support**: Each `struct node` has a mutex for thread-safe operations.
- **String Compression**: Uses zlib for lossless compression of string values.
- **Memory Management**: Ensures all allocated memory is freed properly to prevent leaks.

