```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int integer_field;
    double floating_point_field;
    char status;
} record;

pthread_mutex_t lock;

void log_message(const char *message) {
    printf("%s\n", message);
}

record* initialize_records(int num_records, int int_range_min, int int_range_max, 
                           double float_range_min, double float_range_max) {
    pthread_mutex_init(&lock, NULL);

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    log_message("Starting initialization of records...");

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);
        records[i].integer_field = rand() % (int_range_max - int_range_min + 1) + int_range_min;
        records[i].floating_point_field = ((double)rand() / RAND_MAX) * 
                                         (float_range_max - float_range_min) + float_range_min;
        records[i].status = 'A'; // Default status
        pthread_mutex_unlock(&lock);
    }

    log_message("Completed initialization of records.");

    return records;
}

void free_records(record *records) {
    if (records) {
        free(records);
    }
}

int main() {
    int num_records = 1000000; // Example number
    record *records = initialize_records(num_records, 0, 100, 0.0, 1.0);

    if (records) {
        // Use the records...

        free_records(records);
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
