#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <errno.h>

// Define constants
#define MAX_MEMORY 1048576 // Example max memory size: 1MB
#define RECORD_COUNT 1000
#define STRING_SIZE 256

typedef struct {
    int number;
    long offset;
    char string[STRING_SIZE];
} Record;

typedef struct {
    Record *records;
    size_t count;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection collection = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Random number generator initialization
void seed_rng() {
    srand(time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Helper function to generate a random string
void generate_random_string(char *str, size_t size) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (size) {
        --size; // Leave room for the null terminator
        for(size_t n = 0; n < size; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[size] = '\0';
    } else {
        *str = '\0';
    }
}

// Function to create a record
Record create_record(int min, int max) {
    Record rec;
    rec.number = random_int(min, max);
    rec.offset = rand() % 100000; // Example offset range
    generate_random_string(rec.string, STRING_SIZE - 1);
    return rec;
}

// Function to initialize the collection
int init_collection(size_t record_count, int min, int max) {
    pthread_mutex_lock(&collection.mutex);

    if (collection.count > 0) {
        free(collection.records);
    }

    size_t memory_needed = sizeof(Record) * record_count;
    if (memory_needed > MAX_MEMORY) {
        fprintf(stderr, "Memory allocation exceeds maximum limit\n");
        pthread_mutex_unlock(&collection.mutex);
        return -1;
    }

    collection.records = malloc(memory_needed);
    if (!collection.records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&collection.mutex);
        return -1;
    }

    for (size_t i = 0; i < record_count; ++i) {
        collection.records[i] = create_record(min, max);
    }
    collection.count = record_count;

    pthread_mutex_unlock(&collection.mutex);
    return 0;
}

// Function to serialize the collection
int serialize_collection(uint8_t **buffer, size_t *size) {
    pthread_mutex_lock(&collection.mutex);

    if (!collection.records || !collection.count) {
        pthread_mutex_unlock(&collection.mutex);
        return -1;
    }

    size_t record_size = sizeof(Record);
    *size = collection.count * record_size;

    uint8_t *buf = malloc(*size);
    if (!buf) {
        perror("Failed to allocate buffer for serialization");
        pthread_mutex_unlock(&collection.mutex);
        return -1;
    }

    memcpy(buf, collection.records, *size);

    *buffer = buf;
    pthread_mutex_unlock(&collection.mutex);
    return 0;
}

// Function to deserialize the collection
int deserialize_collection(const uint8_t *buffer, size_t size) {
    pthread_mutex_lock(&collection.mutex);

    if (!buffer || !size) {
        pthread_mutex_unlock(&collection.mutex);
        return -1;
    }

    Record *records = (Record *)malloc(size);
    if (!records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&collection.mutex);
        return -1;
    }

    memcpy(records, buffer, size);

    if (collection.records) {
        free(collection.records);
    }
    collection.records = records;
    collection.count = size / sizeof(Record);

    pthread_mutex_unlock(&collection.mutex);
    return 0;
}

// Helper function to find the largest integer in an array
void find_largest_integer() {
    int n, max;
    printf("Enter number of integers: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    int *numbers = malloc(n * sizeof(int));
    if (!numbers) {
        perror("Failed to allocate memory for numbers array");
        return;
    }

    printf("Enter integers:\n");
    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &numbers[i]) != 1) {
            fprintf(stderr, "Invalid input\n");
            free(numbers);
            return;
        }
    }

    max = numbers[0];
    for (int i = 1; i < n; ++i) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }

    printf("Largest integer: %d\n", max);

    free(numbers);
}

// Main function to demonstrate usage
int main() {
    seed_rng();

    if (init_collection(RECORD_COUNT, 1, 100)) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return EXIT_FAILURE;
    }

    uint8_t *buffer = NULL;
    size_t buffer_size = 0;

    if (serialize_collection(&buffer, &buffer_size)) {
        fprintf(stderr, "Serialization failed\n");
        free(collection.records);
        return EXIT_FAILURE;
    }

    // Example deserialization
    if (deserialize_collection(buffer, buffer_size)) {
        fprintf(stderr, "Deserialization failed\n");
        free(buffer);
        free(collection.records);
        return EXIT_FAILURE;
    }

    find_largest_integer();

    free(buffer);
    free(collection.records);

    return EXIT_SUCCESS;
}
```

