use std::env;
use std::fs::{self, DirEntry};
use std::io;
use std::path::PathBuf;
use log::{info, error};

fn get_directory_from_env(var_name: &str) -> Option<PathBuf> {
    env::var(var_name).ok().map(|s| PathBuf::from(s))
}

fn set_environment_variable(var_name: &str, path: &PathBuf) {
    std::env::set_var(var_name, path.to_str().unwrap());
}

fn create_directory_if_not_exists(path: &PathBuf) -> io::Result<()> {
    if !path.exists() {
        fs::create_dir_all(path)?;
    }
    Ok(())
}

pub fn manage_environment_variable_and_directory(var_name: &str, default_path: &str) {
    match get_directory_from_env(var_name) {
        Some(current_path) => {
            info!("Environment variable '{}' is set to {:?}", var_name, current_path);
        },
        None => {
            let new_dir = PathBuf::from(default_path);

            if let Err(e) = create_directory_if_not_exists(&new_dir) {
                error!("Failed to create directory at {}: {}", default_path, e);
                return;
            }

            set_environment_variable(var_name, &new_dir);
            info!("Created and set environment variable '{}' to {:?}", var_name, new_dir);
        },
    }
}

fn main() {
    env_logger::init();

    let var_name = "MY_APP_DIR";
    let default_path = "/tmp/my_app_directory";

    manage_environment_variable_and_directory(var_name, default_path);
}
