struct gameRecord {
    long* offsetPtr;
    int* keyPtr;
    int randomValue;
};

bool isPrime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i <= std::sqrt(num); ++i)
        if (num % i == 0) return false;
    return true;
}

std::vector<long> generatePrimesUpTo(int max) {
    std::vector<long> primes;
    for (long num = 2; num <= max && primes.size() < 10000; ++num) {
        if (isPrime(num)) primes.push_back(num);
    }
    return primes;
}

bool isFibonacci(int num, int& prevFibo, int& currentFibo) {
    while (currentFibo < num) {
        int temp = currentFibo;
        currentFibo += prevFibo;
        prevFibo = temp;
    }
    return num == currentFibo || num == prevFibo;
}

std::vector<int> generateFibonacciUpTo(int max) {
    std::vector<int> fibos = {0, 1};
    int prevFibo = 0, currentFibo = 1;
    while (currentFibo <= max) {
        if (currentFibo != 1 || fibos.size() > 1)
            fibos.push_back(currentFibo);
        int temp = currentFibo;
        currentFibo += prevFibo;
        prevFibo = temp;
    }
    return fibos;
}

void executeGameStrategy() {
    const int maxOffsetSize = 10000;
    const int maxKeySize = 100;

    std::vector<long> primes = generatePrimesUpTo(10000);
    std::vector<int> fibonacciNumbers = generateFibonacciUpTo(100);

    if (primes.size() < maxOffsetSize || fibonacciNumbers.size() < maxKeySize) {
        std::cerr << "Insufficient prime or Fibonacci numbers for required sizes." << std::endl;
        return;
    }

    long* offsetArray = new long[maxOffsetSize];
    int* keyArray = new int[maxKeySize];

    for (int i = 0; i < maxOffsetSize; ++i) {
        offsetArray[i] = primes[i];
    }

    for (int i = 0; i < maxKeySize; ++i) {
        keyArray[i] = fibonacciNumbers[i];
    }

    const int recordCount = 100;
    gameRecord* records = new gameRecord[recordCount];

    std::srand(std::time(nullptr));

    for (int i = 0; i < recordCount; ++i) {
        records[i].offsetPtr = &offsetArray[i % maxOffsetSize];
        records[i].keyPtr = &keyArray[i % maxKeySize];
        records[i].randomValue = std::rand() % 1000 + 1;
    }

    // Validate memory integrity
    for (int i = 0; i < maxOffsetSize; ++i) {
        if (!isPrime(offsetArray[i])) {
            std::cerr << "Invalid prime number at offset index: " << i << std::endl;
        }
    }

    int prevFibo = 0, currentFibo = 1;
    for (int i = 0; i < maxKeySize; ++i) {
        if (!isFibonacci(keyArray[i], prevFibo, currentFibo)) {
            std::cerr << "Invalid Fibonacci number at key index: " << i << std::endl;
        }
    }

    for (int i = 0; i < recordCount; ++i) {
        if (records[i].randomValue < 1 || records[i].randomValue > 1000) {
            std::cerr << "Invalid random value at record index: " << i << std::endl;
        }
    }

    // Strategy selection with cooldown
    bool strategySelected = false;
    int strategyCooldown = 9;
    int lastStrategyTime = 0;

    for (int currentTime = 0; currentTime < 100; ++currentTime) {  // Simulating time passage
        if (!strategySelected || currentTime - lastStrategyTime >= strategyCooldown) {
            int selectedStrategy = std::rand() % 2 + 1;
            std::cout << "Selected Strategy: " << selectedStrategy << std::endl;
            lastStrategyTime = currentTime;
            strategySelected = true;
        }
    }

    // Cleanup
    delete[] offsetArray;
    delete[] keyArray;
    delete[] records;
}
