typedef struct CryptoModule {
    char *name;
    void *handle; // Handle to the dynamically loaded module
} CryptoModule;

#define MAX_MODULES 100

pthread_mutex_t crypto_mutex = PTHREAD_MUTEX_INITIALIZER;
CryptoModule available_modules[MAX_MODULES];
int module_count = 0;
const char* trusted_module_list[] = {"openssl", "sodium"}; // Example whitelist

// Function prototypes
void load_crypto_modules();
void unload_crypto_modules();
int validate_module(const char *name);
void cache_crypto_functions();
void log_error(const char *message);

void update_available_cryptos(void (*callback)(const CryptoModule *)) {
    pthread_mutex_lock(&crypto_mutex);

    // Load modules dynamically and cache them if valid
    load_crypto_modules();

    // Invoke the callback to report updated list
    for (int i = 0; i < module_count; ++i) {
        callback(available_modules[i]);
    }

    pthread_mutex_unlock(&crypto_mutex);
}

void load_crypto_modules() {
    unload_crypto_modules(); // Ensure no stale modules

    const char* module_names[] = {"libcrypto.so", "libsodium.so"};
    for (int i = 0; i < sizeof(module_names) / sizeof(module_names[0]); ++i) {
        if (!validate_module(module_names[i])) continue;

        void *handle = dlopen(module_names[i], RTLD_LAZY);
        if (!handle) {
            log_error(dlerror());
            continue;
        }

        // Example: Assuming modules expose a `get_supported_cryptos` function
        int (*get_cryptos)(CryptoModule *) = dlsym(handle, "get_supported_cryptos");
        char *error = dlerror();
        if (error) {
            log_error(error);
            dlclose(handle);
            continue;
        }

        CryptoModule module = {module_names[i], handle};
        available_modules[module_count++] = module;

        // Cache cryptographic functions
        (*get_cryptos)(available_modules + module_count - 1);

        HSM_offload_module(module.name); // Example integration with an HSM
    }
}

void unload_crypto_modules() {
    for (int i = 0; i < module_count; ++i) {
        if (available_modules[i].handle) {
            dlclose(available_modules[i].handle);
            available_modules[i].name = NULL;
            available_modules[i].handle = NULL;
        }
    }
    module_count = 0;
}

int validate_module(const char *module_name) {
    for (size_t i = 0; i < sizeof(trusted_module_list) / sizeof(trusted_module_list[0]); ++i) {
        if (strcmp(module_name, trusted_module_list[i]) == 0) {
            return 1;
        }
    }
    log_error("Unauthorized module access attempt: ");
    log_error(module_name);
    return 0;
}

void cache_crypto_functions() {
