class DependencyHandler {
public:
    void fetchData() {
        // Simulate fetching data from an external source.
        std::cout << "Fetching external data...\n";
    }
};

class DynamicVectorManager {
private:
    static const size_t MAX_CALLS = 1000000;
    static int callCount;
    static std::shared_mutex mtx;

public:
    static void manageVector(std::vector<int>* vec, int target, int insertValue, bool sortAscending, DependencyHandler* handler) {
        std::unique_lock<std::shared_mutex> lock(mtx);

        if (++callCount > MAX_CALLS) {
            throw std::runtime_error("Exceeded maximum number of function calls.");
        }

        // Handle external dependency
        handler->fetchData();

        auto it = std::find(vec->begin(), vec->end(), target);

        if (it != vec->end()) {
            vec->insert(it + 1, insertValue);
        } else {
            vec->push_back(insertValue);
        }

        if (sortAscending) {
            std::sort(vec->begin(), vec->end());
        } else {
            std::sort(vec->rbegin(), vec->rend());
        }
    }
};

