    return min + ((double)rand() / RAND_MAX * (max - min));
}

typedef struct record {
    int key;
    double value;
    char status;
} record;

// Synchronization mechanism
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record* create_records(size_t count, int int_min, int int_max, 
                       double double_min, double double_max) {
    log_message("Starting to allocate and initialize records.");

    if (count == 0 || int_min > int_max || double_min > double_max) {
        log_message("Error: Invalid parameters for record creation.");
        return NULL;
    }

    // Allocate memory for records
    record *records = malloc(count * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records.");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Initialize each record with random values and key based on index
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);
        records[i].key = generate_random_int(1, 10000); // Example range for keys
        records[i].value = generate_random_double(double_min, double_max);
        records[i].status = (char)('A' + (rand() % 3)); // Random status 'A', 'B', or 'C'
        pthread_mutex_unlock(&lock);
    }

    log_message("Completed allocation and initialization of records.");
    return records;
}

int* create_keys(size_t count) {
    int *keys = malloc(count * sizeof(int));
    if (!keys) {
        log_message("Memory allocation failed for keys.");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        keys[i] = generate_random_int(1, 10000); // Example range for keys
    }

    return keys;
}

long* create_offsets(size_t count) {
    long *offsets = malloc(count * sizeof(long));
    if (!offsets) {
        log_message("Memory allocation failed for offsets.");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % 1000000; // Example range for offsets
    }

    return offsets;
}

void query_record(record *records, size_t count, int key_to_find, record **result) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < count; ++i) {
        if (records[i].key == key_to_find) {
