import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.io.File;
import java.io.FileInputStream;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class LoggingService {
    private static final Logger logger = Logger.getLogger(LoggingService.class.getName());

    enum Mode { DEBUG, RELEASE }

    private Map<String, JsonNode> configurations = new ConcurrentHashMap<>();
    private ScheduledExecutorService executorService = Executors.newScheduledThreadPool(1);
    private Mode currentMode;
    private boolean isRunning = false;
    private final String environment;

    public LoggingService(String environment) {
        this.environment = environment;
        loadConfiguration();
    }

    private void loadConfiguration() {
        try (FileInputStream fis = new FileInputStream("config.enc")) {
            byte[] encryptedBytes = fis.readAllBytes();
            Key aesKey = new SecretKeySpec(Objects.requireNonNull(getAesKey()), "AES");
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.DECRYPT_MODE, aesKey);

            String decryptedJson = new String(cipher.doFinal(encryptedBytes), StandardCharsets.UTF_8);
            ObjectMapper mapper = new ObjectMapper();
            JsonNode root = mapper.readTree(decryptedJson);

            // Assuming root has an environment-specific structure
            JsonNode envConfig = root.path(environment);
            if (envConfig.isMissingNode()) {
                logger.severe("Configuration for environment '" + environment + "' not found.");
                throw new RuntimeException("Invalid configuration");
            }
            configurations.putAll((Map<String, JsonNode>) BeanUtils.describe(envConfig).entrySet());
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to load and decrypt configuration", e);
            throw new RuntimeException("Error loading configuration", e);
        }
    }

    private String getAesKey() {
        // Retrieve AES key from a secure location or environment variable
        return System.getenv("AES_KEY");
    }

    public void startService() throws InterruptedException {
        if (isRunning) return;

        isRunning = true;
        Random random = new Random();
        int delayMillis = 100 + random.nextInt(200); // Simulating variability

        executorService.scheduleWithFixedDelay(() -> {
            logger.info("Logging service running in " + currentMode + " mode.");
            // Simulate logging tasks
        }, 0, delayMillis, TimeUnit.MILLISECONDS);

        logger.info("Service started in " + environment + " environment with initial delay of " + delayMillis + "ms");
    }

    public void stopService() {
        if (!isRunning) return;

        isRunning = false;
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            logger.log(Level.SEVERE, "Interrupted during shutdown", e);
            Thread.currentThread().interrupt();
        }

        // Send shutdown message to logging aggregator
        sendShutdownMessageToAggregator();

        logger.info("Service stopped.");
    }

    public void toggleMode(Mode mode) {
        if (this.currentMode == mode) return;

        this.currentMode = mode;
        logger.info("Switched service mode to " + mode);

        // Restart service with new mode
        stopService();
        startService();
    }

    private void sendShutdownMessageToAggregator() {
        try {
            // Example sending a message (pseudo-code for demonstration)
            String authToken = configurations.get("authToken").asText();
            boolean rateLimited = false;

            if (!rateLimited) {
                // Send shutdown message
                logger.info("Sent shutdown message to logging aggregator.");
            } else {
                logger.warning("Rate limited, cannot send shutdown message immediately.");
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to send shutdown message", e);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        LoggingService service = new LoggingService("development");

        // Start logging service
        service.startService();

        Thread.sleep(5000); // Run for a while

        // Toggle mode between debug and release
        service.toggleMode(Mode.RELEASE);
        Thread.sleep(5000);

        // Stop the service gracefully
        service.stopService();
    }
}
