#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for sensor data
typedef struct {
    time_t timestamp;
    double reading;
    char device_type[50];
} SensorData;

// Logging function
void log_operation(const char *operation, const char *details) {
    FILE *log_file = fopen("sensor_operations.log", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - %s: %s\n", ctime(&now), operation, details);
        fclose(log_file);
    }
}

// Sensor management structure
typedef struct {
    SensorData **sensors;
    size_t capacity;
    size_t count;
} SensorManager;

// Initialize the sensor manager
SensorManager* init_sensor_manager(size_t initial_capacity) {
    SensorManager *manager = (SensorManager *)malloc(sizeof(SensorManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->sensors = (SensorData **)calloc(initial_capacity, sizeof(SensorData *));
    if (!manager->sensors) {
        free(manager);
        return NULL;
    }

    log_operation("INIT", "Sensor manager initialized");
    return manager;
}

// Resize the sensor array
int resize_sensor_array(SensorManager *manager, size_t new_capacity) {
    SensorData **new_sensors = (SensorData **)realloc(manager->sensors, new_capacity * sizeof(SensorData *));
    if (!new_sensors) return -1;

    manager->sensors = new_sensors;
    manager->capacity = new_capacity;
    log_operation("RESIZE", "Sensor array resized");
    return 0;
}

// Insert a sensor data
int insert_sensor_data(SensorManager *manager, SensorData *data) {
    if (!manager || !data) return -1;

    if (manager->count >= manager->capacity) {
        if (resize_sensor_array(manager, manager->capacity * 2) != 0)
            return -1;
    }

    manager->sensors[manager->count++] = data;
    char details[100];
    snprintf(details, sizeof(details), "Timestamp: %ld, Reading: %.2f, Device Type: %s", 
             (long)data->timestamp, data->reading, data->device_type);
    log_operation("INSERT", details);

    return 0;
}

// Update a sensor data by timestamp
int update_sensor_data(SensorManager *manager, time_t timestamp, SensorData *new_data) {
    if (!manager || !new_data) return -1;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sensors[i]->timestamp == timestamp) {
            memcpy(manager->sensors[i], new_data, sizeof(SensorData));
            char details[100];
            snprintf(details, sizeof(details), "Updated Timestamp: %ld", (long)timestamp);
            log_operation("UPDATE", details);
            return 0;
        }
    }

    log_operation("UPDATE_FAILED", "No sensor found with the specified timestamp");
    return -1;
}

// Delete a sensor data by timestamp
int delete_sensor_data(SensorManager *manager, time_t timestamp) {
    if (!manager) return -1;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sensors[i]->timestamp == timestamp) {
            free(manager->sensors[i]);
            memmove(&manager->sensors[i], &manager->sensors[i + 1], 
                    (manager->count - i - 1) * sizeof(SensorData *));
            manager->count--;
            char details[100];
            snprintf(details, sizeof(details), "Deleted Timestamp: %ld", (long)timestamp);
            log_operation("DELETE", details);

            // Shrink the array if necessary
            if (manager->capacity > 10 && manager->count < manager->capacity / 4) {
                resize_sensor_array(manager, manager->capacity / 2);
            }

            return 0;
        }
    }

    log_operation("DELETE_FAILED", "No sensor found with the specified timestamp");
    return -1;
}

// Export sensor data to JSON format
int export_to_json(SensorManager *manager, const char *filename) {
    if (!manager || !filename) return -1;

    FILE *file = fopen(filename, "w");
    if (!file) return -1;

    fprintf(file, "[\n");
    for (size_t i = 0; i < manager->count; ++i) {
        if (i > 0) fprintf(file, ",\n");
        fprintf(file, "{ \"timestamp\": %ld, \"reading\": %.2f, \"device_type\": \"%s\" }",
                (long)manager->sensors[i]->timestamp, manager->sensors[i]->reading,
                manager->sensors[i]->device_type);
    }
    fprintf(file, "\n]");

    fclose(file);
    log_operation("EXPORT_JSON", "Exported sensor data to JSON");
    return 0;
}

// Clean up the sensor manager
void cleanup_sensor_manager(SensorManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sensors[i]);
    }
    free(manager->sensors);
    free(manager);

    log_operation("CLEANUP", "Sensor manager cleaned up");
}

// Example of integration with an external data source
void sync_with_external_source(SensorManager *manager, const char *source_url) {
    // Simulate network delay and data synchronization
    sleep(1);  // Simulated delay

    // Placeholder for actual network operations and error handling
    log_operation("SYNC", "Synchronized with external source");

    // Example of adding a new sensor from an external source
    SensorData *new_data = (SensorData *)malloc(sizeof(SensorData));
    if (!new_data) return;

    new_data->timestamp = time(NULL);
    new_data->reading = 75.0;
    strcpy(new_data->device_type, "External");

    insert_sensor_data(manager, new_data);
}

int main() {
    SensorManager *manager = init_sensor_manager(10);

    // Example usage
    SensorData data1 = { .timestamp = time(NULL), .reading = 25.5, .device_type = "Temperature" };
    insert_sensor_data(manager, &data1);

    sync_with_external_source(manager, "http://example.com/sensor");

    export_to_json(manager, "sensors.json");
    cleanup_sensor_manager(manager);

    return 0;
}
