// logProcessor.js

const { Transform } = require('stream');
const axios = require('axios');

class LogProcessor extends Transform {
    constructor(criteriaFn, options) {
        super({ objectMode: true });
        this.criteriaFn = criteriaFn;
        this.paused = false;
        this.eventQueue = [];

        // Set up for external logging service interaction
        this.verificationServiceUrl = 'https://logging-service.example.com/verify';
        this.retryDelay = 1000; // ms
    }

    _transform(chunk, encoding, callback) {
        const lines = chunk.toString().split('\n');

        lines.forEach((line) => {
            if (line.trim()) {
                const event = this.parseEvent(line);

                // Filter based on user-defined criteria
                if (this.criteriaFn(event)) {
                    // Transform into structured format
                    this.processAndSend(event, callback);
                }
            }
        });

        callback();
    }

    parseEvent(line) {
        // Placeholder for parsing logic; implement as needed
        return JSON.parse(line); 
    }

    async processAndSend(event, callback) {
        try {
            if (this.paused) {
                this.eventQueue.push({ event, callback });
                return;
            }

            await this.verifyWithExternalService(event);
            // Provide real-time updates to UI
            this.emit('eventProcessed', event);

            callback();
        } catch (error) {
            console.error(`Failed processing event: ${error.message}`);
            setTimeout(() => this.processAndSend(event, callback), this.retryDelay); // Retry after delay
        }
    }

    async verifyWithExternalService(event) {
        for (let attempt = 0; attempt < 3; attempt++) { // Retry logic
            try {
                const response = await axios.post(this.verificationServiceUrl, event);
                if (response.status === 200 && response.data.verified) {
                    return;
                }
            } catch (error) {
                console.error(`Verification error: ${error.message}`);
            }

            await this.delay(this.retryDelay); // Delay before retry
        }
        throw new Error('Event verification failed after retries');
    }

    delay(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    pauseProcessing() {
        this.paused = true;
        console.log('Log processing paused.');
    }

    resumeProcessing() {
        this.paused = false;
        console.log('Resuming log processing...');

        while (this.eventQueue.length > 0) {
            const { event, callback } = this.eventQueue.shift();
            this.processAndSend(event, callback);
        }
    }
}

// Export the LogProcessor class for use in other modules
module.exports = LogProcessor;
