#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <pthread.h>

typedef struct {
    double timestamp;
    double sensor_reading;
    char device_type[50];
    int location_id;
} sensor_data;

typedef struct {
    sensor_data *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SensorArray;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

SensorArray* create_sensor_array() {
    SensorArray *array = (SensorArray *)malloc(sizeof(SensorArray));
    array->data = (sensor_data *)calloc(INITIAL_CAPACITY, sizeof(sensor_data));
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_sensor_array(SensorArray *array) {
    size_t new_capacity = array->capacity * GROWTH_FACTOR;
    sensor_data *new_data = (sensor_data *)realloc(array->data, new_capacity * sizeof(sensor_data));
    if (new_data) {
        array->data = new_data;
        array->capacity = new_capacity;
    }
}

double generate_gaussian(double mean, double stddev) {
    static double z0, z1;
    static int generate;
    if (!generate)
        z0 = rand() / (RAND_MAX + 1.0);
    generate = !generate;
    z1 = rand() / (RAND_MAX + 1.0);
    return mean + sqrt(-2.0 * log(z0)) * cos(2.0 * M_PI * z1) * stddev;
}

void add_sensor_data(SensorArray *array, double timestamp, char *device_type, int location_id, double mean, double stddev) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_sensor_array(array);
    }

    sensor_data new_entry;
    new_entry.timestamp = timestamp;
    new_entry.sensor_reading = generate_gaussian(mean, stddev);
    strncpy(new_entry.device_type, device_type, sizeof(new_entry.device_type));
    new_entry.location_id = location_id;

    // Detect inconsistencies
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].timestamp == timestamp) {
            printf("Duplicate timestamp detected at %f. Handling...\n", timestamp);
            break;
        }
    }

    array->data[array->count++] = new_entry;

    pthread_mutex_unlock(&array->lock);
}

void free_sensor_array(SensorArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Unit tests and integration tests would be defined here
void run_tests() {
    // Example test: Initialization
    SensorArray *array = create_sensor_array();
    assert(array != NULL);

    // Test adding data
    add_sensor_data(array, 1627849200.0, "TemperatureSensor", 1, 25.0, 2.5);
    assert(array->count == 1);

    // Test resizing
    for (int i = 0; i < INITIAL_CAPACITY + 5; ++i) {
        add_sensor_data(array, 1627849200.0 + i, "TemperatureSensor", 1, 25.0, 2.5);
    }
    assert(array->count == INITIAL_CAPACITY + 6);

    // Test freeing
    free_sensor_array(array);

    printf("All tests passed.\n");
}

int main() {
    run_tests();
    return 0;
}
