} record;

void generate_data(long *offsets, int *keys, record **records, size_t count, int min_val, int max_val) {
    if (count <= 0 || min_val > max_val) return;

    offsets = (long *)malloc(count * sizeof(long));
    keys = (int *)malloc(count * sizeof(int));
    *records = (record *)malloc(count * sizeof(record));

    if (!offsets || !keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % 100; // Example offset logic
        keys[i] = rand() % 100;    // Example key logic

        if ((*records)[i].value = rand() % (max_val - min_val + 1) + min_val, (*records)[i].value < 0 || (*records)[i].value > max_val) {
            fprintf(stderr, "Invalid record value generated\n");
            exit(EXIT_FAILURE);
        }
    }
}

void free_data(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
