#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the point structure
typedef struct {
    double x, y;
    int color_index;
} Point;

// Node for hash table linked list
typedef struct HashNode {
    char *key;
    Point value;
    struct HashNode *next;
} HashNode;

// Hash table definition
#define TABLE_SIZE 1024

typedef struct {
    HashNode **buckets;
    pthread_mutex_t *locks; // Array of mutexes for each bucket
} HashTable;

// Custom hash function signature
unsigned int custom_hash(const char *str);

// Function to create a new point
Point create_point(double x, double y) {
    Point p = {x, y, 0};
    double distance = sqrt(x * x + y * y);
    // Example gradient logic: color index based on distance
    p.color_index = (int)(distance * 10) % 256; 
    return p;
}

// Function to initialize the hash table
HashTable* init_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    table->buckets = calloc(TABLE_SIZE, sizeof(HashNode *));
    table->locks = calloc(TABLE_SIZE, sizeof(pthread_mutex_t));

    for (int i = 0; i < TABLE_SIZE; i++) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

// Function to add an entry to the hash table
void ht_insert(HashTable *table, const char *key, Point value) {
    unsigned int index = custom_hash(key) % TABLE_SIZE;

    pthread_mutex_lock(&table->locks[index]);

    HashNode *new_node = malloc(sizeof(HashNode));
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->locks[index]);
}

// Function to safely release memory
void cleanup_hash_table(HashTable *table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        pthread_mutex_lock(&table->locks[i]);

        HashNode *current = table->buckets[i];
        while (current != NULL) {
            HashNode *temp = current;
            current = current->next;
            free(temp->key);
            free(temp);
        }

        pthread_mutex_unlock(&table->locks[i]);
    }

    free(table->buckets);
    free(table->locks);

    for (int i = 0; i < TABLE_SIZE; i++) {
        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table);
}

// Example custom hash function
unsigned int custom_hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash;
}

// Main memory management function
void manage_memory_and_initialize_data(const char *(*load_data)(void)) {
    double *float_array;
    size_t float_size;
    char **string_array;
    size_t string_count;

    if (load_data) {
        // Load data, this is just a placeholder for actual loading logic
        void* data = load_data();
        // Parse the loaded data to fill float_size and string_count
        // float_array = ...
        // string_array = ...
    } else {
        float_size = 100;
        string_count = 50;

        float_array = malloc(float_size * sizeof(double));
        string_array = malloc(string_count * sizeof(char*));

        for (size_t i = 0; i < float_size; ++i) {
            float_array[i] = rand() / (double)RAND_MAX;
        }

        for (size_t i = 0; i < string_count; ++i) {
            size_t len = rand() % 10 + 5;
            string_array[i] = malloc(len * sizeof(char));
            snprintf(string_array[i], len, "string_%zu", i);
        }
    }

    Point *point_array = malloc(float_size * sizeof(Point));
    for (size_t i = 0; i < float_size; ++i) {
        point_array[i] = create_point(float_array[i], float_array[(float_size + i) % float_size]);
    }

    HashTable *hash_table = init_hash_table();

    for (size_t i = 0; i < string_count; ++i) {
        ht_insert(hash_table, string_array[i], point_array[i % float_size]);
    }

    // Simulate usage...

    cleanup_hash_table(hash_table);

    free(float_array);
    for (size_t i = 0; i < string_count; ++i) {
        free(string_array[i]);
    }
    free(string_array);

    free(point_array);
}
