import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.core.env.Environment;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.cache.RedisCacheConfiguration;
import org.springframework.data.redis.cache.RedisCacheManager;
import org.springframework.data.redis.cache.RedisCacheWriter;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import redis.clients.jedis.JedisPoolConfig;

@SpringBootApplication
@EnableCaching
public class DistributedCacheService {

    public static void main(String[] args) {
        SpringApplication.run(DistributedCacheService.class, args);
    }

    @Autowired
    private Environment env;

    @Bean
    public CacheManager cacheManager(RedisConnectionFactory redisConnectionFactory) {
        RedisCacheConfiguration defaultConfig = RedisCacheConfiguration.defaultCacheConfig()
                .entryTtl(Duration.ofMinutes(Integer.parseInt(env.getProperty("cache.ttl", "10"))))
                .disableCachingNullValues();

        Map<String, RedisCacheConfiguration> configMap = new HashMap<>();
        configMap.put("default", defaultConfig);

        return RedisCacheManager.builder(RedisCacheWriter.nonLockingRedisCacheWriter(redisConnectionFactory))
                .initialCacheNames(configMap.keySet())
                .cacheDefaults(defaultConfig)
                .build();
    }

    @Bean
    public JedisPoolConfig jedisPoolConfig() {
        int maxTotal = Integer.parseInt(env.getProperty("redis.pool.maxTotal", "128"));
        int maxIdle = Integer.parseInt(env.getProperty("redis.pool.maxIdle", "64"));
        int minIdle = Integer.parseInt(env.getProperty("redis.pool.minIdle", "16"));

        JedisPoolConfig poolConfig = new JedisPoolConfig();
        poolConfig.setMaxTotal(maxTotal);
        poolConfig.setMaxIdle(maxIdle);
        poolConfig.setMinIdle(minIdle);

        return poolConfig;
    }

    @Bean
    public CommandLineRunner demo(CacheManager cacheManager) {
        return args -> {
            // Simulate external data source update with RESTful API
            simulateExternalUpdates();

            // Log initial metrics
            System.out.println("Cache Manager: " + cacheManager);
        };
    }

    private void simulateExternalUpdates() {
        // Implement logic to periodically fetch updates from a RESTful API and populate the cache
        // Use environment variables for update frequency and endpoint configuration
    }
}
