import os
from datetime import datetime
from collections import defaultdict

def process_log_directory(directory_path, start_date=None, end_date=None, async_mode=False):
    def parse_log_line(line):
        # Assuming log line format: "timestamp user_id event_type event_details"
        parts = line.split()
        if len(parts) < 4:
            return None
        timestamp_str, user_id, event_type, *event_details = parts
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
        details = ' '.join(event_details)
        return timestamp, user_id, event_type, details

    def is_within_date_range(timestamp):
        if start_date and timestamp < start_date:
            return False
        if end_date and timestamp > end_date:
            return False
        return True

    # Initialize the results dictionary
    auth_results = defaultdict(lambda: {'successful': 0, 'failed': 0, 'locations': set()})

    def process_file(file_path):
        with open(file_path, 'r') as file:
            for line in file:
                parsed_line = parse_log_line(line.strip())
                if not parsed_line:
                    continue
                timestamp, user_id, event_type, details = parsed_line

                # Filter based on date range
                if not is_within_date_range(timestamp):
                    continue

                if "authentication" not in event_type.lower():
                    continue

                location = extract_location(details)  # Assume this function abstracts external dependencies

                if "success" in details.lower():
                    auth_results[user_id]['successful'] += 1
                elif "fail" in details.lower() or "error" in details.lower():
                    auth_results[user_id]['failed'] += 1

                if location:
                    auth_results[user_id]['locations'].add(location)

    def extract_location(details):
        # Placeholder for geolocation extraction logic.
        return None

    files = [os.path.join(directory_path, f) for f in os.listdir(directory_path) if os.path.isfile(os.path.join(directory_path, f))]

    if async_mode:
        import asyncio
        loop = asyncio.get_event_loop()

        async def process_all_files():
            tasks = [loop.run_in_executor(None, process_file, file) for file in files]
            await asyncio.gather(*tasks)

        loop.run_until_complete(process_all_files())
    else:
        for file_path in files:
            process_file(file_path)

    # Convert sets to lists
    for user_id in auth_results:
        auth_results[user_id]['locations'] = list(auth_results[user_id]['locations'])

    return dict(auth_results)


# Example usage:
if __name__ == "__main__":
    start_date = datetime(2023, 1, 1)
    end_date = datetime(2023, 12, 31)
    results = process_log_directory('/path/to/log/directory', start_date=start_date, end_date=end_date, async_mode=True)
    print(results)
```

