// utils.js

const crypto = require('crypto');
const fs = require('fs');

function generateRandomStringAndHashPassword(charSet, length, password, maxMemoryUsage) {
  // Helper function to generate a random string
  const generateRandomString = (charset, len) => {
    let result = '';
    for (let i = 0; i < len; i++) {
      const randomIndex = Math.floor(Math.random() * charset.length);
      result += charset[randomIndex];
    }
    return result;
  };

  // Generate a random string
  const randomString = generateRandomString(charSet, length);

  try {
    // Estimate memory usage based on password size and hashing algorithm buffer size
    const bufferSize = Buffer.byteLength(password) + crypto.getHashes()[0].length * 2;

    if (bufferSize > maxMemoryUsage) {
      throw new Error('Memory limit exceeded for hashing operation');
    }

    // Hash the password using a default algorithm, e.g., 'sha256'
    const hash = crypto.createHash('sha256').update(password).digest('hex');

    return { randomString, hashedPassword: hash };
  } catch (error) {
    console.error(error.message);
    throw error;
  }
}

function readLargeFileSynchronously(filePath, encoding = 'utf8', chunkSize = 1024 * 1024) {
  try {
    if (!fs.existsSync(filePath)) {
      throw new Error('File does not exist');
    }

    let content = '';

    const fileStream = fs.createReadStream(filePath, { encoding: null, highWaterMark: chunkSize });

    return new Promise((resolve, reject) => {
      fileStream.on('data', (chunk) => {
        // Handle buffer chunks if no encoding is specified
        content += chunk.toString(encoding);
      }).on('end', () => {
        resolve(content);
      }).on('error', (err) => {
        reject(err);
      });
    });
  } catch (error) {
    console.error(error.message);
    throw error;
  }
}

module.exports = {
  generateRandomStringAndHashPassword,
  readLargeFileSynchronously
};
