#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *name;
    void (*transition)(void);
} State;

typedef struct Node {
    State state;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} FSA_List;

FSA_List* create_fsa_list() {
    FSA_List *fsa = malloc(sizeof(FSA_List));
    fsa->head = NULL;
    pthread_mutex_init(&fsa->lock, NULL);
    return fsa;
}

void add_state(FSA_List *fsa, const char *name, void (*transition)(void)) {
    pthread_mutex_lock(&fsa->lock);

    Node *new_node = malloc(sizeof(Node));
    new_node->state.name = strdup(name);
    new_node->state.transition = transition;
    new_node->next = fsa->head;
    fsa->head = new_node;

    pthread_mutex_unlock(&fsa->lock);
}

void remove_state(FSA_List *fsa, const char *name) {
    pthread_mutex_lock(&fsa->lock);

    Node **curr = &fsa->head;
    while (*curr) {
        if (strcmp((*curr)->state.name, name) == 0) {
            Node *to_delete = *curr;
            *curr = to_delete->next;
            free(to_delete->state.name);
            free(to_delete);
            break;
        }
        curr = &(*curr)->next;
    }

    pthread_mutex_unlock(&fsa->lock);
}

void serialize_fsa_list(const FSA_List *fsa, char **output) {
    // Serialize logic
}

void deserialize_fsa_list(FSA_List *fsa, const char *input) {
    // Deserialize logic
}

int validate_fsm(FSA_List *fsa) {
    // Validation logic
    return 1;
}

void free_fsa_list(FSA_List *fsa) {
    pthread_mutex_lock(&fsa->lock);
    Node *current = fsa->head;
    while (current) {
        Node *next = current->next;
        free(current->state.name);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&fsa->lock);

    pthread_mutex_destroy(&fsa->lock);
    free(fsa);
}

