#include <iostream>
#include <vector>
#include <atomic>
#include <mutex>
#include <unordered_map>
#include <memory>

// Custom memory allocator with stack and heap allocation support
template<typename T>
class MemoryAllocator {
public:
    using value_type = T;

    explicit MemoryAllocator(size_t poolSize) : poolSize(poolSize), pool(new char[poolSize]) {}

    ~MemoryAllocator() { delete[] pool; }

    T* allocate(size_t n) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (currentOffset + n * sizeof(T) <= poolSize) {
            void* ptr = pool.get() + currentOffset;
            currentOffset += n * sizeof(T);
            return static_cast<T*>(ptr);
        }
        return ::operator new(n * sizeof(T)); // Fallback to heap allocation
    }

    void deallocate(T* p, size_t n) noexcept {
        std::lock_guard<std::mutex> lock(mutex_);
        if (p >= pool.get() && p < pool.get() + currentOffset - n * sizeof(T)) {
            // Deallocate from pool is not supported for simplicity
        } else {
            ::operator delete(p);
        }
    }

private:
    size_t poolSize;
    std::unique_ptr<char[]> pool;
    size_t currentOffset = 0;
    std::mutex mutex_;
};

// Node structure
struct OctreeNode {
    bool isLeaf;
    std::atomic<int> referenceCount;
    std::vector<std::unique_ptr<OctreeNode>> children;

    explicit OctreeNode(bool leaf) : isLeaf(leaf), referenceCount(1) {}
};

// Memory region management
class MemoryRegionManager {
public:
    void createRegion(const std::string& label, size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        regions[label] = std::make_unique<MemoryAllocator<OctreeNode>>(size);
    }

    MemoryAllocator<OctreeNode>* getAllocator(const std::string& label) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = regions.find(label);
        if (it != regions.end()) {
            return it->second.get();
        }
        throw std::runtime_error("Memory region not found");
    }

private:
    std::unordered_map<std::string, std::unique_ptr<MemoryAllocator<OctreeNode>>> regions;
    std::mutex mutex_;
};

// Octree structure
class Octree {
public:
    Octree(float featureSize, size_t leafNodes, size_t dataCapacity,
           MemoryRegionManager& regionManager, const std::string& regionLabel)
        : featureSize(featureSize), maxLeafNodes(leafNodes),
          dataCapacity(dataCapacity) {

        allocator = regionManager.getAllocator(regionLabel);
        root = std::unique_ptr<OctreeNode>(allocator->allocate(1));
        *root = OctreeNode(false); // Root is not a leaf
    }

    ~Octree() {
        // Custom deallocation logic if needed
    }

private:
    float featureSize;
    size_t maxLeafNodes;
    size_t dataCapacity;
    MemoryAllocator<OctreeNode>* allocator;
    std::unique_ptr<OctreeNode> root;
};

// Usage example
int main() {
    MemoryRegionManager regionManager;
    regionManager.createRegion("default", 1024 * 1024); // 1MB pool

    Octree octree(0.5f, 100, 256, regionManager, "default");

    return 0;
}
