['```c
#include <stdio.h>
#include <stdlib.h>
import time

#define MAX_HISTORY 1000
#define QUALITY_THRESHOLD 75
#define ANOMALY_THRESHOLD 1.5
#define READINGS_IN_LAST_MINUTE 10

typedef struct {
    double value;
    int quality_score;
    time_t timestamp;
} SensorReading;

typedef struct {
    SensorReading readings[MAX_HISTORY];
    size_t count;
    double rolling_average;
    double sum;
} DataPipeline;

// Function prototypes
void update_data_pipeline(DataPipeline *pipeline, SensorReading new_reading);
SensorReading get_most_recent_valid(SensorReading *readings, size_t count, time_t current_time);
double calculate_rolling_average(const DataPipeline *pipeline);

// Update the data pipeline with a new sensor reading
void update_data_pipeline(DataPipeline *pipeline, SensorReading new_reading) {
    // Filter based on age of the reading (e.g., only consider readings within the last 5 minutes)
    time_t current_time = time(NULL);
    if ((current_time - new_reading.timestamp) > 300) return;

    // Filter based on quality score
    if (new_reading.quality_score < QUALITY_THRESHOLD) return;

    // Maintain rolling data with a fixed size buffer
    pipeline->readings[pipeline->count % MAX_HISTORY] = new_reading;
    pipeline->count++;

    // Update the sum and calculate the rolling average
    pipeline->sum += new_reading.value;
    if (pipeline->count > 0) {
        double oldest_value = pipeline->readings[(pipeline->count - 1 + MAX_HISTORY) % MAX_HISTORY].value;
        pipeline->rolling_average = pipeline->sum / pipeline->count;

        // Adjust for the oldest value leaving the rolling average
        if (pipeline->count >= MAX_HISTORY) {
            pipeline->sum -= oldest_value;
        }
    }

    // Check frequency of readings within the last minute
    size_t recent_count = 0;
    time_t one_minute_ago = current_time - 60;

    for (size_t i = 0; i < pipeline->count; ++i) {
        if ((current_time - pipeline->readings[i].timestamp) <= 60)
            recent_count++;
    }

    // Identify anomalies
    SensorReading most_recent_valid = get_most_recent_valid(pipeline->readings, pipeline->count, current_time);

    double difference = abs(most_recent_valid.value - pipeline->rolling_average);
    if (difference > ANOMALY_THRESHOLD * pipeline->rolling_average) {
        printf("Anomaly detected: %f\n", most_recent_valid.value);
    }

    // Handle latency and connectivity issues by checking update time
    time_t last_update_time = new_reading.timestamp;
    if ((current_time - last_update_time) > 60) {  // Simulating a delay threshold of one minute
        printf("Warning: Potential network latency or connectivity issue detected.\n");
    }
}

// Retrieve the most recent valid reading
SensorReading get_most_recent_valid(SensorReading *readings, size_t count, time_t current_time) {
    for (int i = count - 1; i >= 0; --i) {
        if ((current_time - readings[i].timestamp <= 300) && 
            (readings[i].quality_score >= QUALITY_THRESHOLD)) {
            return readings[i];
        }
    }

    // If no valid reading is found, return a default invalid reading
    SensorReading invalid = { .value = 0.0, .quality_score = 0, .timestamp = current_time };
    return invalid;
}

// Calculate rolling average (already included in the update function)
double calculate_rolling_average(const DataPipeline *pipeline) {
    return pipeline->rolling_average;
}
```']

