// Define the custom structure
typedef struct {
    float average;
    char identifier;
} CustomData;

// Function to serialize data into binary format
void serialize_data(double *doubleArray, short *shortArray, CustomData *customArray, unsigned long *timestampArray,
                    size_t doubleCount, size_t shortCount, size_t customCount, size_t timestampCount, 
                    unsigned char **serializedOutput, size_t *outputSize) {
    // Calculate total size needed
    size_t totalSize = (doubleCount * sizeof(double)) + (shortCount * sizeof(short)) +
                       (customCount * sizeof(CustomData)) + (timestampCount * sizeof(unsigned long));

    // Allocate memory for serialized data
    *serializedOutput = malloc(totalSize);
    if (!*serializedOutput) {
        fprintf(stderr, "Memory allocation failed during serialization.\n");
        exit(EXIT_FAILURE);
    }

    // Serialize the arrays into the output buffer
    memcpy(*serializedOutput, doubleArray, doubleCount * sizeof(double));
    memcpy(*serializedOutput + doubleCount * sizeof(double), shortArray, shortCount * sizeof(short));
    memcpy(*serializedOutput + doubleCount * sizeof(double) + shortCount * sizeof(short),
           customArray, customCount * sizeof(CustomData));
    memcpy(*serializedOutput + doubleSize + shortSize + customSize,
           timestampArray, timestampCount * sizeof(unsigned long));

    // Set the output size
    *outputSize = totalSize;
}

// Function to deserialize data from binary format
void deserialize_data(const unsigned char *serializedInput, size_t inputSize, 
                      double **doubleArray, short **shortArray, CustomData **customArray, 
                      unsigned long **timestampArray, size_t doubleCount, size_t shortCount, 
                      size_t customCount, size_t timestampCount) {
    // Allocate memory for the arrays
    *doubleArray = malloc(doubleCount * sizeof(double));
    *shortArray = malloc(shortCount * sizeof(short));
    *customArray = malloc(customCount * sizeof(CustomData));
    *timestampArray = malloc(timestampCount * sizeof(unsigned long));

    if (!(*doubleArray) || !(*shortArray) || !(*customArray) || !(*timestampArray)) {
        fprintf(stderr, "Memory allocation failed during deserialization.\n");
        exit(EXIT_FAILURE);
    }

    // Deserialize the arrays from the input buffer
    memcpy(*doubleArray, serializedInput, doubleCount * sizeof(double));
    memcpy(*shortArray, serializedInput + doubleCount * sizeof(double), shortCount * sizeof(short));
    memcpy(*customArray, serializedInput + doubleCount * sizeof(double) + shortCount * sizeof(short),
           customCount * sizeof(CustomData));
    memcpy(*timestampArray, serializedInput + doubleSize + shortSize + customSize,
           timestampCount * sizeof(unsigned long));
}

// Function to manage memory and initialize data structures
void manage_memory_and_initialize(size_t maxMemory, size_t doubleCount, size_t shortCount, 
                                  size_t customCount, size_t timestampCount) {
    // Calculate total required memory
    size_t doubleSize = doubleCount * sizeof(double);
    size_t shortSize = shortCount * sizeof(short);
    size_t customSize = customCount * sizeof(CustomData);
    size_t timestampSize = timestampCount * sizeof(unsigned long);
    size_t totalMemoryNeeded = doubleSize + shortSize + customSize + timestampSize;

    if (totalMemoryNeeded > maxMemory) {
        fprintf(stderr, "Exceeded memory budget.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize arrays
    double *doubleArray = malloc(doubleSize);
    short *shortArray = malloc(shortSize);
    CustomData *customArray = malloc(customSize);
    unsigned long *timestampArray = malloc(timestampSize);

    if (!doubleArray || !shortArray || !customArray || !timestampArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(doubleArray); free(shortArray); free(customArray); free(timestampArray);
        exit(EXIT_FAILURE);
    }

    // Seed for random number generation
    srand((unsigned int)time(NULL));

    // Initialize the custom data structures with random values
    for (size_t i = 0; i < customCount; ++i) {
        customArray[i].average = (float)(rand() % 10000) / 100.0f;
        customArray[i].identifier = 'A' + (rand() % 26);
    }

    // Serialize the data
    unsigned char *serializedData = NULL;
    size_t serializedSize = 0;
    serialize_data(doubleArray, shortArray, customArray, timestampArray, doubleCount, 
                   shortCount, customCount, timestampCount, &serializedData, &serializedSize);

    // Free allocated memory
    free(doubleArray);
    free(shortArray);
    free(customArray);
    free(timestampArray);
    if (serializedData) {
        free(serializedData);
    }
}

// Function to iterate over data structures and compute statistics
void compute_statistics(const double *doubleArray, size_t doubleCount) {
    float sum = 0.0f;
    for (size_t i = 0; i < doubleCount; ++i) {
        sum += doubleArray[i];
    }
    printf("Average of doubles: %f\n", sum / doubleCount);
}

int main() {
    size_t maxMemory = 1024 * 1024; // Example memory limit
    manage_memory_and_initialize(maxMemory, 1000, 500, 200, 300);

    return 0;
}
