#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_SESSIONS 100
#define BUFFER_SIZE 1024

typedef struct {
    int Session_ID;
    int Socket_Files;
    char Data_Buffer[BUFFER_SIZE];
} Network_Session;

typedef struct {
    Network_Session* sessions[MAX_SESSIONS];
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int shutdown_flag;
} SessionManager;

SessionManager manager = { .count = 0, .shutdown_flag = 0 };
pthread_mutex_t global_lock;
pthread_cond_t io_ready;

void initialize_manager() {
    pthread_mutex_init(&manager.lock, NULL);
    pthread_cond_init(&manager.cond, NULL);
}

void cleanup_manager() {
    pthread_mutex_destroy(&manager.lock);
    pthread_cond_destroy(&manager.cond);
}

void* session_worker(void* arg) {
    while (1) {
        pthread_mutex_lock(&global_lock);

        while (manager.count == 0 && !manager.shutdown_flag) {
            pthread_cond_wait(&io_ready, &global_lock);
        }

        if (manager.shutdown_flag) {
            pthread_mutex_unlock(&global_lock);
            break;
        }

        Network_Session* session = manager.sessions[0];
        for (size_t i = 1; i < manager.count; ++i) {
            manager.sessions[i - 1] = manager.sessions[i];
        }
        --manager.count;

        pthread_mutex_unlock(&global_lock);

        // Process the session
        printf("Processing Session ID: %d\n", session->Session_ID);
        free(session);
    }

    return NULL;
}

int start_sessions(int num_threads) {
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, session_worker, NULL) != 0) {
            perror("Failed to create thread");
            return 0;
        }
    }

    return 1;
}

void add_session(Network_Session* session) {
    pthread_mutex_lock(&manager.lock);

    if (manager.count < MAX_SESSIONS) {
        manager.sessions[manager.count++] = session;
        pthread_cond_signal(&io_ready);
    } else {
        printf("Session queue is full\n");
    }

    pthread_mutex_unlock(&manager.lock);
}

void shutdown_sessions() {
    pthread_mutex_lock(&global_lock);

    manager.shutdown_flag = 1;
    pthread_cond_broadcast(&io_ready);

    pthread_mutex_unlock(&global_lock);
}

int manage_network_sessions(int num_threads) {
    initialize_manager();
    pthread_mutex_init(&global_lock, NULL);
    pthread_cond_init(&io_ready, NULL);

    if (!start_sessions(num_threads)) {
        return 0;
    }

    // Simulate session initiation
    for (int i = 0; i < 10; ++i) {
        Network_Session* session = malloc(sizeof(Network_Session));
        if (!session) {
            printf("Failed to allocate memory for session\n");
            shutdown_sessions();
            return 0;
        }
        session->Session_ID = i;
        session->Socket_Files = rand() % 100;
        strcpy(session->Data_Buffer, "Sample Data");

        add_session(session);
    }

    sleep(2); // Simulate time for processing

    shutdown_sessions();

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_manager();
    pthread_mutex_destroy(&global_lock);
    pthread_cond_destroy(&io_ready);

    return 1;
}

int main() {
    int num_threads = 4; // Adjust based on expected load and resource availability
    if (manage_network_sessions(num_threads)) {
        printf("All operations successful\n");
    } else {
        printf("Operations failed\n");
    }
    return 0;
}
```

