typedef struct {
    long* offsets;
    int* keys;
    size_t size;
} DataStructure;

long geometric_progression(long start, double ratio, size_t n) {
    return (long)(start * pow(ratio, n));
}

int custom_hash(int index, unsigned int seed) {
    return (index * 2654435761U + seed) % 1000000007;
}

DataStructure* initialize_data_structures(size_t num_elements, long start_offset, double ratio, unsigned int seed) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->offsets = malloc(num_elements * sizeof(long));
    ds->keys = malloc(num_elements * sizeof(int));
    ds->size = num_elements;

    if (!ds->offsets || !ds->keys) {
        free(ds->offsets);
        free(ds->keys);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        ds->offsets[i] = geometric_progression(start_offset, ratio, i);
        ds->keys[i] = custom_hash(i, seed);
    }

    return ds;
}

void free_data_structures(DataStructure* ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds);
    }
}

typedef struct {
    const DataStructure* ds;
    size_t index;
} Iterator;

Iterator iterator_init(const DataStructure* ds, int reverse) {
    Iterator iter = { ds, reverse ? ds->size - 1 : 0 };
    return iter;
}

int iterator_has_next(const Iterator* iter) {
    if (iter->ds == NULL) return 0;
    return (iter->index >= 0 && iter->index < iter->ds->size);
}

void iterator_next(Iterator* iter, int forward) {
    if (!iterator_has_next(iter)) return;
    iter->index += forward ? 1 : -1;
}

