<?php

require 'vendor/autoload.php';

function load_configuration($env, $template_path) {
    if (!file_exists($template_path)) {
        throw new Exception("Configuration template not found.");
    }

    $config = json_decode(file_get_contents($template_path), true);

    if (!$config) {
        throw new Exception("Invalid configuration format.");
    }

    if (!isset($config[$env])) {
        throw new Exception("Environment '$env' not configured.");
    }

    return [
        'host' => $config[$env]['db_host'],
        'user' => $config[$env]['db_user'],
        'password' => $config[$env]['db_password'],
        'dbname' => $config[$env]['db_name'],
    ];
}

function generate_db_config($environments, $template_path) {
    $configs = [];
    foreach ($environments as $env) {
        try {
            $configs[$env] = load_configuration($env, $template_path);
        } catch (Exception $e) {
            echo "Error: " . $e->getMessage() . "\n";
        }
    }
    return $configs;
}

