typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
} SharedData;

void init_shared_data(SharedData *data, size_t size) {
    data->size = size;
    data->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;

    data->offsets = malloc(size * sizeof(long));
    data->keys = malloc(size * sizeof(int));
    data->records = malloc(size * sizeof(Record));

    if (!data->offsets || !data->keys || !data->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        data->offsets[i] = rand() % 100; // Example offset
        data->keys[i] = rand() % 50;     // Example key
        data->records[i].value = rand() % 1000; // Random initial value
    }
}

void *update_records(void *arg) {
    SharedData *data = (SharedData *)arg;

    pthread_mutex_lock(&data->mutex);
    for (size_t i = 0; i < data->size; ++i) {
        data->records[i].value += data->keys[i]; // Example update
    }
    pthread_mutex_unlock(&data->mutex);

    return NULL;
}

void free_shared_data(SharedData *data) {
    free(data->offsets);
    free(data->keys);
    free(data->records);
    pthread_mutex_destroy(&data->mutex);
}

int main(int argc, char *argv[]) {
    size_t size = (argc > 1) ? atoi(argv[1]) : 10; // Default size

    srand(time(NULL)); // Seed random number generator

    SharedData data;
    init_shared_data(&data, size);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) { // Example: 4 threads
        if (pthread_create(&threads[i], NULL, update_records, &data)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_shared_data(&data);

    return 0;
}
