<?php

function loadConfig($environment) {
    $defaultConfig = [
        'db_host' => 'localhost',
        'db_name' => '',
        'cache_enabled' => false,
        'log_level' => 'info'
    ];

    $envConfigPath = "config/{$environment}.json";
    if (file_exists($envConfigPath)) {
        $envConfig = json_decode(file_get_contents($envConfigPath), true);
        return array_merge($defaultConfig, $envConfig);
    }

    return $defaultConfig;
}

function getConfig($argv) {
    global $argv;

    $environment = 'production';
    if (isset($argv[1])) {
        $environment = $argv[1];
    } else {
        $environment = getenv('APP_ENV') ?: $environment;
    }

    $config = loadConfig($environment);

    // Override with command-line arguments if provided
    foreach ($argv as $arg) {
        if (strpos($arg, '--db_host=') === 0) {
            $config['db_host'] = substr($arg, 10);
        } elseif (strpos($arg, '--db_name=') === 0) {
            $config['db_name'] = substr($arg, 10);
        }
    }

    return $config;
}

$config = getConfig($argv);

echo "Database Host: " . $config['db_host'] . "\n";
echo "Database Name: " . $config['db_name'] . "\n";
echo "Cache Enabled: " . ($config['cache_enabled'] ? 'Yes' : 'No') . "\n";
echo "Log Level: " . $config['log_level'] . "\n";

?>
