    size_t buffer_length;

    if (serialize_message(pool.messages[0], &buffer, &buffer_length) == 0) {
        PooledMessage *deserialized_msg;
        if (deserialize_message(buffer, buffer_length, &deserialized_msg) == 0) {
            // Use deserialized message
        }
        free(buffer);
    }

    read_and_update_log("messages.log");

    cleanup_message_pool(&pool);

    return 0;
}
