#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LogEntry {
    long timestamp;
    int statusCode;
    char logBuffer[256];
    struct LogEntry *next;
} LogEntry;

typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
    size_t entryCount;
} LogList;

LogList* createLogList() {
    LogList *list = (LogList*)malloc(sizeof(LogList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->entryCount = 0;
    return list;
}

void freeLogList(LogList *list) {
    LogEntry *current = list->head;
    while (current) {
        LogEntry *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int appendToLogList(LogList *list, long timestamp, int statusCode, const char *logMessage) {
    if (!list || !logMessage) return -1;

    LogEntry *newEntry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!newEntry) return -1;

    newEntry->timestamp = timestamp;
    newEntry->statusCode = statusCode;
    strncpy(newEntry->logBuffer, logMessage, sizeof(newEntry->logBuffer) - 1);
    newEntry->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = newEntry;
    } else {
        LogEntry *current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newEntry;
    }

    list->entryCount++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void updateStatusCodes(LogList *list, int (*conditionFunc)(LogEntry *)) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    LogEntry *current = list->head;
    while (current) {
        if (conditionFunc(current)) {
            current->statusCode = 1; // Example status update
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void logInternalOperation(const char *operation, const char *message) {
    printf("LOG: %s - %s\n", operation, message); // Simplified logging for illustration
}

int conditionFunc(LogEntry *entry) {
    return entry->statusCode == 0; // Example condition
}

// Additional functions to handle network failures, rate limits, etc., can be added here.

void testLogList() {
    LogList *logList = createLogList();
    if (!logList) {
        printf("Failed to create log list.\n");
        return;
    }

    appendToLogList(logList, 1625097600, 0, "Service started.");
    appendToLogList(logList, 1625097660, 0, "First operation completed.");

    updateStatusCodes(logList, conditionFunc);

    LogEntry *current = logList->head;
    while (current) {
        printf("Timestamp: %ld, Status Code: %d, Message: %s\n", current->timestamp, current->statusCode, current->logBuffer);
        current = current->next;
    }

    freeLogList(logList);
}

int main() {
    testLogList();
    return 0;
}
