#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int* allocate_and_initialize_offsets(size_t num_offsets) {
    int *offsets = (int*) malloc(num_offsets * sizeof(int));
    if (!offsets) return NULL; // Handle allocation failure
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }
    return offsets;
}

int* allocate_and_initialize_keys(size_t num_keys) {
    int *keys = (int*) malloc(num_keys * sizeof(int));
    if (!keys) return NULL; // Handle allocation failure
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i;
    }
    return keys;
}

Record* allocate_and_initialize_records(size_t num_records, int min_value, int max_value) {
    Record *records = (Record*) malloc(num_records * sizeof(Record));
    if (!records) return NULL; // Handle allocation failure

    // Seed the random number generator once
    static int initialized = 0;
    if (!initialized) {
        srand((unsigned int) time(NULL));
        initialized = 1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

typedef struct {
    int *offsets;
    size_t num_offsets;
    int *keys;
    size_t num_keys;
    Record *records;
    size_t num_records;
} DataPipeline;

DataPipeline* create_data_pipeline(size_t num_offsets, size_t num_keys, size_t num_records, int min_record_value, int max_record_value) {
    DataPipeline *pipeline = (DataPipeline*) malloc(sizeof(DataPipeline));
    if (!pipeline) return NULL; // Handle allocation failure

    pipeline->offsets = allocate_and_initialize_offsets(num_offsets);
    if (!pipeline->offsets) {
        free(pipeline); // Cleanup on failure
        return NULL;
    }

    pipeline->keys = allocate_and_initialize_keys(num_keys);
    if (!pipeline->keys) {
        free(pipeline->offsets);
        free(pipeline);
        return NULL;
    }

    pipeline->records = allocate_and_initialize_records(num_records, min_record_value, max_record_value);
    if (!pipeline->records) {
        free(pipeline->keys);
        free(pipeline->offsets);
        free(pipeline);
        return NULL;
    }

    pipeline->num_offsets = num_offsets;
    pipeline->num_keys = num_keys;
    pipeline->num_records = num_records;

    return pipeline;
}

void release_data_pipeline(DataPipeline *pipeline) {
    if (pipeline) {
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        free(pipeline);
    }
}
