#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int offset;
    char *key;
    int record_value;
    char *record_string;
} DataElement;

typedef struct {
    size_t count;
    DataElement **elements;
    pthread_mutex_t lock;
} DataManager;

DataManager* init_data_manager(size_t initial_capacity) {
    DataManager *dm = (DataManager *)malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->count = 0;
    dm->elements = (DataElement **)calloc(initial_capacity, sizeof(DataElement *));
    if (!dm->elements) {
        free(dm);
        return NULL;
    }

    pthread_mutex_init(&dm->lock, NULL);
    return dm;
}

void destroy_data_manager(DataManager *dm) {
    if (!dm) return;

    for (size_t i = 0; i < dm->count; ++i) {
        free(dm->elements[i]->key);
        free(dm->elements[i]->record_string);
        free(dm->elements[i]);
    }
    free(dm->elements);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

DataElement* create_data_element(int offset, const char *key, int record_value, const char *string_template) {
    DataElement *element = (DataElement *)malloc(sizeof(DataElement));
    if (!element) return NULL;

    element->offset = offset;
    element->key = strdup(key);
    if (!element->key) {
        free(element);
        return NULL;
    }

    element->record_value = record_value;
    element->record_string = (char *)malloc(strlen(string_template) + 1);
    if (!element->record_string) {
        free(element->key);
        free(element);
        return NULL;
    }

    snprintf(element->record_string, strlen(string_template) + 1, string_template, record_value);
    return element;
}

int add_data_element(DataManager *dm, DataElement *element) {
    if (!dm || !element) return -1;

    pthread_mutex_lock(&dm->lock);

    if (dm->count >= dm->capacity) {
        size_t new_capacity = dm->capacity ? dm->capacity * 2 : 4;
        DataElement **new_elements = realloc(dm->elements, new_capacity * sizeof(DataElement *));
        if (!new_elements) {
            pthread_mutex_unlock(&dm->lock);
            return -1;
        }
        dm->elements = new_elements;
        dm->capacity = new_capacity;
    }

    dm->elements[dm->count++] = element;

    pthread_mutex_unlock(&dm->lock);
    return 0;
}

int serialize_data_manager(DataManager *dm, const char *filename) {
    if (!dm || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&dm->lock);

    fwrite(&(dm->count), sizeof(size_t), 1, file);
    for (size_t i = 0; i < dm->count; ++i) {
        DataElement *element = dm->elements[i];
        fwrite(&(element->offset), sizeof(int), 1, file);
        size_t key_len = strlen(element->key) + 1;
        fwrite(&key_len, sizeof(size_t), 1, file);
        fwrite(element->key, sizeof(char), key_len, file);
        fwrite(&(element->record_value), sizeof(int), 1, file);
        size_t string_len = strlen(element->record_string) + 1;
        fwrite(&string_len, sizeof(size_t), 1, file);
        fwrite(element->record_string, sizeof(char), string_len, file);
    }

    pthread_mutex_unlock(&dm->lock);
    fclose(file);

    return 0;
}

int deserialize_data_manager(DataManager *dm, const char *filename) {
    if (!dm || !filename) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        int offset;
        size_t key_len;
        char *key;
        int record_value;
        size_t string_len;
        char *string;

        fread(&offset, sizeof(int), 1, file);
        fread(&key_len, sizeof(size_t), 1, file);
        key = (char *)malloc(key_len);
        fread(key, sizeof(char), key_len, file);

        fread(&record_value, sizeof(int), 1, file);
        fread(&string_len, sizeof(size_t), 1, file);
        string = (char *)malloc(string_len);
        fread(string, sizeof(char), string_len, file);

        DataElement *element = create_data_element(offset, key, record_value, "%d");
        free(key);
        free(string);

        if (!element) {
            fclose(file);
            return -1;
        }

        add_data_element(dm, element);
    }

    fclose(file);
    return 0;
}
