#define MAX_LOG_SIZE 256

typedef struct LogEntry {
    long timestamp;
    int status_code;
    char log_message[MAX_LOG_SIZE];
    struct LogEntry *next;
} LogEntry;

typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
    // Assuming some cache management system is available
    void (*cache_update)(LogEntry *);
    void (*cache_invalidate)(LogEntry *);
} LogManager;

void init_log_manager(LogManager *manager, 
                      void (*cache_update)(LogEntry *), 
                      void (*cache_invalidate)(LogEntry *)) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->cache_update = cache_update;
    manager->cache_invalidate = cache_invalidate;
}

void destroy_log_manager(LogManager *manager) {
    LogEntry *current, *next;
    pthread_mutex_lock(&manager->lock);
    current = manager->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

void append_log_entry(LogManager *manager, long timestamp, int status_code, const char *message, int priority) {
    LogEntry *new_entry = malloc(sizeof(LogEntry));
    if (!new_entry) {
        perror("Failed to allocate memory for new log entry");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    // Insert based on priority (lower number means higher priority)
    if (!priority || !manager->head || manager->head->timestamp > timestamp) {
        new_entry->timestamp = timestamp;
        strncpy(new_entry->log_message, message, MAX_LOG_SIZE - 1);
        new_entry->status_code = status_code;
        new_entry->next = manager->head;
        manager->head = new_entry;

        if (manager->cache_update) {
            manager->cache_update(new_entry);
        }
    } else {
        LogEntry *current = manager->head;
        while (current->next && current->next->timestamp <= timestamp) {
            current = current->next;
        }

        new_entry->timestamp = timestamp;
        strncpy(new_entry->log_message, message, MAX_LOG_SIZE - 1);
        new_entry->status_code = status_code;
        new_entry->next = current->next;
        current->next = new_entry;

        if (manager->cache_update) {
            manager->cache_update(new_entry);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_log_status(LogManager *manager, long timestamp, int new_status_code) {
    pthread_mutex_lock(&manager->lock);

    LogEntry *current = manager->head;
    while (current != NULL && current->timestamp != timestamp) {
        current = current->next;
    }

    if (current != NULL) {
        current->status_code = new_status_code;

        if (manager->cache_update) {
            manager->cache_update(current);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void serialize_log_manager(const LogManager *manager, FILE *file) {
    LogEntry *current;

    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    current = manager->head;
    while (current != NULL) {
        fwrite(&(current->timestamp), sizeof(current->timestamp), 1, file);
        fwrite(&(current->status_code), sizeof(current->status_code), 1, file);
        fwrite(current->log_message, MAX_LOG_SIZE, 1, file);

        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
}

void deserialize_log_manager(LogManager *manager, FILE *file) {
    LogEntry *current_entry = NULL;

    while (fread(&(current_entry->timestamp), sizeof(current_entry->timestamp), 1, file)) {
        current_entry->status_code = 0;
        fread(current_entry->log_message, MAX_LOG_SIZE, 1, file);

        append_log_entry(manager, current_entry->timestamp, current_entry->status_code, current_entry->log_message, 1);
    }
}

