['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Log level definitions
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

// Structure for a log entry
typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char *message;
    struct LogEntry *next;
} LogEntry;

// Node structure to hold multiple log entries per thread
typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
} LoggerNode;

// Logging system with dynamic memory management
typedef struct {
    LoggerNode **loggers;
    size_t logger_count;
    pthread_mutex_t global_lock;
} LoggingSystem;

// Initialize logging system for a given number of concurrent loggers
void initialize_logging_system(LoggingSystem *system, size_t num_loggers) {
    system->logger_count = num_loggers;
    system->loggers = (LoggerNode **)malloc(num_loggers * sizeof(LoggerNode *));
    pthread_mutex_init(&system->global_lock, NULL);

    for (size_t i = 0; i < num_loggers; ++i) {
        system->loggers[i] = (LoggerNode *)malloc(sizeof(LoggerNode));
        system->loggers[i]->head = NULL;
        pthread_mutex_init(&system->loggers[i]->lock, NULL);
    }
}

// Add or update a log entry for a specific logger
void add_log_entry(LoggingSystem *system, size_t logger_id, LogLevel level, const char *message) {
    if (logger_id >= system->logger_count) return;

    LoggerNode *node = system->loggers[logger_id];
    pthread_mutex_lock(&node->lock);

    LogEntry *entry = node->head;
    while (entry && strcmp(entry->message, message) != 0) {
        entry = entry->next;
    }

    if (!entry) { // Entry not found, create new
        entry = (LogEntry *)malloc(sizeof(LogEntry));
        entry->timestamp = time(NULL);
        entry->level = level;

        size_t len = strlen(message) + 1;
        entry->message = (char *)malloc(len * sizeof(char));
        if (!entry->message) {
            free(entry);
            pthread_mutex_unlock(&node->lock);
            return; // Handle memory allocation failure gracefully
        }
        strcpy(entry->message, message);

        entry->next = node->head;
        node->head = entry;
    } else { // Update existing entry
        entry->timestamp = time(NULL); 
        free(entry->message);

        size_t len = strlen(message) + 1;
        entry->message = (char *)malloc(len * sizeof(char));
        if (!entry->message) {
            pthread_mutex_unlock(&node->lock);
            return; // Handle memory allocation failure gracefully
        }
        strcpy(entry->message, message);
    }

    pthread_mutex_unlock(&node->lock);
}

// Free all allocated memory in the logging system
void free_logging_system(LoggingSystem *system) {
    for (size_t i = 0; i < system->logger_count; ++i) {
        LoggerNode *node = system->loggers[i];
        pthread_mutex_lock(&node->lock);

        LogEntry *entry = node->head;
        while (entry) {
            LogEntry *next_entry = entry->next;
            free(entry->message);
            free(entry);
            entry = next_entry;
        }

        pthread_mutex_unlock(&node->lock);
        pthread_mutex_destroy(&node->lock);
        free(node);
    }
    free(system->loggers);

    pthread_mutex_destroy(&system->global_lock);
}

// Example usage
int main() {
    LoggingSystem system;
    initialize_logging_system(&system, 10); // Initialize for 10 loggers

    add_log_entry(&system, 0, LOG_INFO, "This is an info message");
    add_log_entry(&system, 1, LOG_ERROR, "This is an error message");

    free_logging_system(&system);
    return 0;
}
