#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    atomic_size_t used;
    size_t *offsets;
    size_t *keys;
    Record *records;
} MemoryManager;

void init_random() {
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    pthread_once(&once, srand);
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

MemoryManager* allocate_memory(size_t num_offsets, size_t num_keys, size_t num_records, int record_value_min, int record_value_max) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = (num_offsets > num_keys ? num_offsets : num_keys) > num_records ? (num_offsets > num_keys ? num_offsets : num_keys) * 2 : num_records * 2;

    manager->offsets = calloc(manager->capacity, sizeof(size_t));
    if (!manager->offsets) {
        perror("Failed to allocate memory for offsets");
        free(manager);
        return NULL;
    }

    manager->keys = calloc(manager->capacity, sizeof(size_t));
    if (!manager->keys) {
        perror("Failed to allocate memory for keys");
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    manager->records = malloc(manager->capacity * sizeof(Record));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        free(manager->keys);
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    manager->used.store(0, memory_order_relaxed);

    // Initialize offsets and keys
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < num_offsets && i < manager->capacity; ++i) {
        manager->offsets[i] = i;
    }

    for (size_t i = 0; i < num_keys && i < manager->capacity; ++i) {
        manager->keys[i] = i;
    }

    init_random();
    for (size_t i = 0; i < num_records && i < manager->capacity; ++i) {
        manager->records[i].value = random_int(record_value_min, record_value_max);
    }
    pthread_mutex_unlock(&manager->lock);

    return manager;
}

void free_memory(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void concurrent_update(MemoryManager *manager, size_t index, int new_value) {
    if (index >= manager->capacity || atomic_load(&manager->used) <= index)
        return;

    pthread_mutex_lock(&manager->lock);
    if (index < atomic_load(&manager->used)) {
        manager->records[index].value = new_value;
    }
    pthread_mutex_unlock(&manager->lock);
}

