#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>

typedef struct {
    int value;
    long offset;
} record_t;

#define ALIGNMENT 8

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

record_t *create_records(int record_count, int min_value, int max_value, size_t max_size) {
    if (max_size < sizeof(record_t)) return NULL;

    size_t record_size = sizeof(record_t);
    size_t padding = ALIGNMENT - (record_size % ALIGNMENT);
    if (padding == ALIGNMENT) padding = 0;

    size_t total_record_size = record_count * (record_size + padding);

    if (total_record_size > max_size) return NULL;

    record_t *records = aligned_alloc(ALIGNMENT, total_record_size);
    if (!records) return NULL;

    srand((unsigned int)time(NULL));

    for (int i = 0; i < record_count; ++i) {
        records[i].value = min_value + rand() % ((max_value - min_value) + 1);
        records[i].offset = (long)i * record_size;
    }

    return records;
}

uint8_t *serialize_records(record_t *records, int record_count, size_t *output_size) {
    if (!records || !output_size) return NULL;

    size_t record_size = sizeof(record_t);
    size_t padding = ALIGNMENT - (record_size % ALIGNMENT);
    if (padding == ALIGNMENT) padding = 0;

    size_t total_size = record_count * (record_size + padding);

    uint8_t *output = malloc(total_size);
    if (!output) return NULL;

    for (int i = 0; i < record_count; ++i) {
        uint8_t *ptr = &output[i * (record_size + padding)];

        // Serialize 'value' as int
        *(uint32_t *)ptr = htobe32(records[i].value);

        // Serialize 'offset' as long
        *(uint64_t *)(ptr + 4) = htobe64(records[i].offset);

        if (padding > 0) {
            memset(ptr + record_size, 0, padding);
        }
    }

    *output_size = total_size;
    return output;
}

void find_largest_integer() {
    int size;
    printf("Enter the number of integers: ");
    scanf("%d", &size);

    if (size <= 0) {
        printf("Invalid input size.\n");
        return;
    }

    int *numbers = malloc(size * sizeof(int));
    if (!numbers) {
        printf("Memory allocation failed.\n");
        return;
    }

    printf("Enter the integers:\n");
    for (int i = 0; i < size; ++i) {
        scanf("%d", &numbers[i]);
    }

    int largest = numbers[0];
    for (int i = 1; i < size; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", largest);

    free(numbers);
}

