        printf("Serialization successful. Data size: %zu bytes\n", output_size);
        free(serialized_data);
    } else {
        printf("Failed to serialize records.\n");
    }

    free_aligned(records);

    find_largest_integer();

    return EXIT_SUCCESS;
}
