typedef enum {
    LOG_LEVEL_NONE,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG
} LogLevel;

typedef struct {
    char* buffer;
    size_t used;
    size_t capacity;
} MemoryPool;

// Logging function
void log_message(LogLevel level, const char *message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&log_mutex);
    if (level == LOG_LEVEL_INFO || level == LOG_LEVEL_DEBUG) {
        printf("[INFO]: %s\n", message);
    } else if (level == LOG_LEVEL_ERROR) {
        fprintf(stderr, "[ERROR]: %s\n", message);
    }
    pthread_mutex_unlock(&log_mutex);
}

// Initialize memory pool
int init_memory_pool(MemoryPool* pool, size_t initial_capacity) {
    pool->buffer = malloc(initial_capacity);
    if (!pool->buffer) return -1;

    pool->capacity = initial_capacity;
    pool->used = 0;

    log_message(LOG_LEVEL_DEBUG, "Memory pool initialized.");
    return 0;
}

// Allocate memory from pool
void* pool_alloc(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        char* new_buffer = realloc(pool->buffer, new_capacity);
        if (!new_buffer) return NULL;

        pool->buffer = new_buffer;
        pool->capacity = new_capacity;

        log_message(LOG_LEVEL_DEBUG, "Memory pool resized.");
    }

    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

// Free memory (reset for reuse)
void free_memory_pool(MemoryPool* pool) {
    free(pool->buffer);
    log_message(LOG_LEVEL_INFO, "Memory pool freed.");
}

// Function to manage records
