    srand((unsigned int)time(NULL));

    while (total_memory_used() + sizeof(record) <= MAX_MEMORY_LIMIT) {
        if (total_records % initial_capacity == 0) {
            initial_capacity *= 2;
            log_message(LOG_LEVEL_DEBUG, "Increasing record capacity.");
        }

        record* new_record = pool_alloc(&pool, sizeof(record));
        if (!new_record) break;

        int rand_val = min_value + rand() % (max_value - min_value + 1);
        records = realloc(records, (total_records + 1) * sizeof(record));

        records[total_records].value = rand_val;
        records[total_records].offset = total_records * sizeof(record);

        total_records++;
    }

    *num_records = total_records;
    free_memory_pool(&pool);
    return records;
}

size_t total_memory_used() {
    // Placeholder for actual memory usage calculation
    return 0;
}

// Serialize data into a byte array (binary)
void serialize_binary(const record* records, size_t num_records, unsigned char** buffer, size_t *buffer_size) {
