}

// Serialize data into JSON format
void serialize_json(const record* records, size_t num_records, char** json_str) {
    char* buffer = malloc(512); // Initial allocation for simplicity
    if (!buffer) return;

    strcpy(buffer, "[");
    for (size_t i = 0; i < num_records; ++i) {
