    unsigned char *binary_data;
    size_t binary_size;
    serialize_binary(records, num_records, &binary_data, &binary_size);

    char *json_data;
    serialize_json(records, num_records, &json_data);

    free(records);
    free(binary_data);
    free(json_data);

    printf("Largest integer: %d\n", find_largest_integer());

    return 0;
}
