#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>
#include <endian.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Maximum memory usage in bytes
#define MAX_MESSAGES 10000

typedef struct {
    char* message_buffer;
    uint64_t timestamp;
    int ack_flag;
} Message;

typedef struct {
    Message* messages;
    size_t count;
    size_t capacity;
    size_t current_memory_usage;
    pthread_mutex_t lock;
} MessageCollection;

MessageCollection* create_message_collection(size_t initial_capacity) {
    MessageCollection* collection = (MessageCollection*)malloc(sizeof(MessageCollection));
    if (!collection) return NULL;

    collection->messages = (Message*)calloc(initial_capacity, sizeof(Message));
    if (!collection->messages) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->current_memory_usage = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

int add_message(MessageCollection* collection, const char* message) {
    pthread_mutex_lock(&collection->lock);

    size_t message_len = strlen(message) + 1;
    size_t message_size = sizeof(char*) + message_len;

    if (collection->current_memory_usage + message_size > MAX_MEMORY_USAGE ||
        collection->count >= collection->capacity) {

        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory limit exceeded or capacity full
    }

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Message* new_messages = (Message*)realloc(collection->messages, new_capacity * sizeof(Message));
        if (!new_messages) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->messages = new_messages;
        collection->capacity = new_capacity;
    }

    Message* msg = &collection->messages[collection->count];
    msg->message_buffer = (char*)malloc(message_len);
    if (!msg->message_buffer) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }
    strcpy(msg->message_buffer, message);

    msg->timestamp = time(NULL); // Seed with current time for simplicity
    msg->ack_flag = 0;

    collection->current_memory_usage += message_size;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

void serialize_message(const Message* msg, uint8_t** buffer, size_t* length) {
    size_t message_len = strlen(msg->message_buffer) + 1;
    *length = sizeof(uint64_t) + sizeof(int) + message_len;
    *buffer = (uint8_t*)malloc(*length);
    if (!*buffer) return;

    uint8_t* ptr = *buffer;
    memcpy(ptr, &msg->timestamp, sizeof(uint64_t));
    ptr += sizeof(uint64_t);

    int ack_flag_le = htobe32(msg->ack_flag); // Handle endianness
    memcpy(ptr, &ack_flag_le, sizeof(int));
    ptr += sizeof(int);

    memcpy(ptr, msg->message_buffer, message_len);
}

void deserialize_message(const uint8_t* buffer, size_t length, Message* msg) {
    const uint8_t* ptr = buffer;
    memcpy(&msg->timestamp, ptr, sizeof(uint64_t));
    ptr += sizeof(uint64_t);

    int ack_flag_le;
    memcpy(&ack_flag_le, ptr, sizeof(int));
    msg->ack_flag = be32toh(ack_flag_le); // Handle endianness
    ptr += sizeof(int);

    strcpy(msg->message_buffer, (const char*)ptr);
}

void free_message_collection(MessageCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->messages[i].message_buffer);
    }
    free(collection->messages);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void log_event(const char* event) {
    printf("[%lu] %s\n", time(NULL), event); // Simple logging mechanism
}

// Example usage
int main() {
    MessageCollection* collection = create_message_collection(10);
    if (!collection) {
        log_event("Failed to initialize message collection");
        return EXIT_FAILURE;
    }

    add_message(collection, "Hello, World!");
    add_message(collection, "Another message");

    uint8_t* buffer;
    size_t length;
    serialize_message(&collection->messages[0], &buffer, &length);

    Message new_msg;
    deserialize_message(buffer, length, &new_msg);
    free(buffer);

    log_event("Serialization and deserialization successful");

    free_message_collection(collection);
    return EXIT_SUCCESS;
}
```

