#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} Record;

uint64_t current_time_in_microseconds() {
    struct timeval te;
    gettimeofday(&te, NULL);
    return (te.tv_sec * 1000000LL) + te.tv_usec;
}

void initialize_random_seed() {
    srand((unsigned int)current_time_in_microseconds());
}

int generate_random_int(int min, int max) {
    if (min > max) {
        return min; // Gracefully handle invalid range
    }
    return rand() % (max - min + 1) + min;
}

Record* create_records(size_t num_records, int value_range_min, int value_range_max, size_t max_memory, size_t *actual_num_records) {
    if (num_records == 0 || actual_num_records == NULL) {
        return NULL;
    }

    const size_t record_size = sizeof(Record);
    const size_t total_size = num_records * record_size;

    if (total_size > max_memory) {
        fprintf(stderr, "Exceeded maximum memory allocation limit.\n");
        return NULL;
    }

    Record *records = malloc(total_size);
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = generate_random_int(value_range_min, value_range_max);
        records[i].offset = rand() % (max_memory / sizeof(long));
    }

    *actual_num_records = num_records;
    return records;
}

int serialize_records(Record *records, size_t num_records, uint8_t **buffer) {
    if (!records || !buffer) {
        fprintf(stderr, "Invalid arguments for serialization.\n");
        return -1;
    }

    const size_t record_size = sizeof(Record);
    const size_t buffer_size = num_records * record_size;

    *buffer = malloc(buffer_size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialized data");
        return -1;
    }

    memcpy(*buffer, records, buffer_size);
    return 0;
}

int deserialize_records(uint8_t *buffer, size_t num_records, Record **records) {
    if (!buffer || !records) {
        fprintf(stderr, "Invalid arguments for deserialization.\n");
        return -1;
    }

    const size_t record_size = sizeof(Record);
    const size_t buffer_size = num_records * record_size;

    *records = malloc(buffer_size);
    if (!*records) {
        perror("Failed to allocate memory for deserialized records");
        return -1;
    }

    memcpy(*records, buffer, buffer_size);
    return 0;
}

int largest_integer_in_stream() {
    int num, max = INT_MIN;
    size_t count = 0;

    printf("Enter integers (press Ctrl+D to end):\n");

    while (scanf("%d", &num) == 1) {
        if (num > max) {
            max = num;
        }
        ++count;
    }

    if (count == 0) {
        fprintf(stderr, "No valid input provided.\n");
        return -1;
    }

