    return 0;
}

typedef struct UnionFind {
    int *parent;
    size_t n;
} UnionFind;

UnionFind* union_find_create(size_t n) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    if (!uf) {
        perror("Failed to allocate memory for UnionFind");
        return NULL;
    }

    uf->n = n;
    uf->parent = calloc(n, sizeof(int));
    if (!uf->parent) {
        free(uf);
        perror("Failed to allocate memory for parent array");
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        uf->parent[i] = i;
    }

    return uf;
}

int union_find_destroy(UnionFind *uf) {
    if (!uf) return -1;
    free(uf->parent);
    free(uf);
    return 0;
}

int find(UnionFind *uf, int x) {
    if (x != uf->parent[x]) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void union_sets(UnionFind *uf, int a, int b) {
    int rootA = find(uf, a);
    int rootB = find(uf, b);

    if (rootA != rootB) {
        uf->parent[rootB] = rootA;
    }
}

int count_disjoint_pairs(uint8_t *buffer, size_t num_records) {
    Record *records;
    deserialize_records(buffer, num_records, &records);

    UnionFind *uf = union_find_create(num_records);

    for (size_t i = 0; i < num_records; ++i) {
        int offset_a = records[i].offset % num_records;
        int offset_b = (records[i].offset + records[i].value) % num_records;

        union_sets(uf, offset_a, offset_b);
    }

    size_t disjoint_count = 0;
    for (size_t i = 0; i < uf->n; ++i) {
        if (find(uf, i) == i) {
            disjoint_count++;
        }
    }

    int result = disjoint_count - 1;

    union_find_destroy(uf);
    free(records);

    return result;
}

int main() {
    initialize_random_seed();

