```c
// record.c

#include "record.h"
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

#define LOG_FILE "library_log.txt"

RecordCollection* create_record_collection(size_t max_records, size_t max_memory) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->max_records = max_records;
    collection->allocated_size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    size_t record_size = sizeof(int) + sizeof(long) + 100; // buffer size example
    if (record_size * max_records > max_memory) {
        log_event("Failed to create collection: Memory limit exceeded.");
        free(collection);
        return NULL;
    }

    collection->records = malloc(record_size * max_records);
    if (!collection->records) {
        log_event("Failed to allocate memory for records.");
        pthread_mutex_destroy(&collection->lock);
        free(collection);
        return NULL;
    }

    log_event("Record collection created successfully.");
    return collection;
}

void free_record_collection(RecordCollection *collection) {
    if (collection) {
        for (size_t i = 0; i < collection->max_records; ++i) {
            free(collection->records[i].buffer);
        }
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int initialize_random_generator(void) {
    srand((unsigned int)time(NULL));
    return 0;
}

void populate_with_random_data(RecordCollection *collection, int min_value, int max_value) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->max_records; ++i) {
        collection->records[i].integer = rand() % (max_value - min_value + 1) + min_value;
        collection->records[i].offset = rand();
        collection->records[i].buffer = malloc(100);
        snprintf(collection->records[i].buffer, 100, "Random Data %zu", i);
    }

    pthread_mutex_unlock(&collection->lock);
}

unsigned char* serialize_records(const RecordCollection *collection, size_t *out_size) {
    if (!collection || !out_size) return NULL;

    *out_size = collection->allocated_size;
    unsigned char *data = malloc(*out_size);

    if (!data) {
        log_event("Serialization failed: Memory allocation error.");
        return NULL;
    }

    pthread_mutex_lock(&collection->lock);

    size_t offset = 0;
    for (size_t i = 0; i < collection->max_records; ++i) {
        int integer = htobe32(collection->records[i].integer);
        memcpy(data + offset, &integer, sizeof(int));
        offset += sizeof(int);

        long long_offset = be64tohll(collection->records[i].offset);
        memcpy(data + offset, &long_offset, sizeof(long));
        offset += sizeof(long);

        size_t buf_len = strlen(collection->records[i].buffer) + 1;
        memcpy(data + offset, collection->records[i].buffer, buf_len);
        offset += buf_len;
    }

    pthread_mutex_unlock(&collection->lock);

    log_event("Records serialized successfully.");
    return data;
}

void deserialize_records(RecordCollection *collection, const unsigned char *data, size_t data_size) {
    if (!collection || !data) return;

    pthread_mutex_lock(&collection->lock);

    size_t offset = 0;
    for (size_t i = 0; i < collection->max_records && offset < data_size; ++i) {
        int integer = be32toh(*((int *)(data + offset)));
        collection->records[i].integer = integer;
        offset += sizeof(int);

        long long_offset = htolell(*((long *)(data + offset)));
        collection->records[i].offset = long_offset;
        offset += sizeof(long);

        char *buffer = malloc(100);
        strcpy(buffer, (char *)(data + offset));
        free(collection->records[i].buffer);
        collection->records[i].buffer = buffer;

        offset += strlen((char *)(data + offset)) + 1;
    }

    pthread_mutex_unlock(&collection->lock);

    log_event("Records deserialized successfully.");
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", event);
        fclose(log_file);
    } else {
        perror("Logging failed");
    }
}
```

