#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <inttypes.h>
#include <zlib.h>  // Ensure zlib is installed and linked

// Define the record structure
typedef struct {
    int value;
    long offset;
    char *metadata;
} Record;

// Function to align size to a given boundary
size_t align_size(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

// Helper function to serialize a record into bytes considering endianness
void serialize_record(const Record *record, uint8_t *buffer, size_t buffer_size) {
    if (buffer_size < sizeof(record->value) + sizeof(record->offset) + strlen(record->metadata) + 1) {
        fprintf(stderr, "Buffer too small for serialization\n");
        return;
    }

    // Serialize int value
    uint32_t val = htobe32((uint32_t)record->value);
    memcpy(buffer, &val, sizeof(val));
    buffer += sizeof(val);

    // Serialize long offset
    uint64_t off = htonll(record->offset);  // Use a macro or helper to handle endianness for long long
    memcpy(buffer, &off, sizeof(off));
    buffer += sizeof(off);

    // Serialize metadata string length and content
    size_t len = strlen(record->metadata) + 1;
    memcpy(buffer, &len, sizeof(len));  // Assume len fits in size_t
    buffer += sizeof(len);
    memcpy(buffer, record->metadata, len);
}

// Helper function to deserialize bytes into a record considering endianness
void deserialize_record(const uint8_t *buffer, Record *record) {
    // Deserialize int value
    uint32_t val;
    memcpy(&val, buffer, sizeof(val));
    record->value = be32toh(val);

    // Deserialize long offset
    uint64_t off;
    memcpy(&off, buffer + sizeof(val), sizeof(off));
    record->offset = llhctonl(off);  // Use a macro or helper to handle endianness for long long

    // Deserialize metadata string length and content
    size_t len;
    memcpy(&len, buffer + sizeof(val) + sizeof(off), sizeof(len));
    record->metadata = malloc(len);
    if (record->metadata == NULL) {
        fprintf(stderr, "Failed to allocate memory for metadata\n");
        return;
    }
    memcpy(record->metadata, buffer + sizeof(val) + sizeof(off) + sizeof(len), len);
}

// Function to free a record
void free_record(Record *record) {
    if (record) {
        free(record->metadata);
    }
}

// Main function to allocate and initialize an array of records
Record **initialize_records(size_t count, size_t max_size, int min_val, int max_val, size_t alignment) {
    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Calculate aligned record size
    size_t metadata_size = sizeof(char *) + 1;  // Null-terminated string pointer and '\0'
    size_t record_size = align_size(sizeof(Record), alignment) + metadata_size;

    if (record_size * count > max_size) {
        fprintf(stderr, "Not enough space to allocate records\n");
        return NULL;
    }

    Record **records = malloc(count * sizeof(Record *));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record pointers\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(record_size);
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate memory for a record\n");

            // Free previously allocated records on failure
            while (i > 0) free(records[--i]);
            free(records);
            return NULL;
        }

        Record *record = (Record *)((char *)records[i] + align_size(0, alignment));
        record->value = min_val + rand() % (max_val - min_val + 1);
        record->offset = (long)i;  // Example offset
        record->metadata = (char *)(record + 1);  // Point metadata just after the Record

        snprintf(record->metadata, metadata_size, "Metadata for record %zu", i);
    }

    return records;
}

// Function to free all allocated records
void free_all_records(Record **records, size_t count) {
    if (records) {
        for (size_t i = 0; i < count; ++i) {
            free_record(records[i]);
        }
        free(records);
    }
}

// Compression function using zlib
int compress_data(const uint8_t *input, size_t input_size, uint8_t **output, size_t *output_size) {
    uLongf compressed_size = compressBound(input_size);
    *output = malloc(compressed_size);
    if (!*output) return -1;

    int result = compress(*output, &compressed_size, input, (uLong)input_size);
    if (result != Z_OK) {
        free(*output);
        return -1;
    }

    *output_size = compressed_size;
    return 0;
}

// Decompression function using zlib
int decompress_data(const uint8_t *input, size_t input_size, uint8_t **output, size_t output_capacity) {
    uLongf decompressed_size = output_capacity;

    *output = malloc(output_capacity);
    if (!*output) return -1;

    int result = uncompress(*output, &decompressed_size, input, (uLong)input_size);
    if (result != Z_OK) {
        free(*output);
        return -1;
    }

    return 0;
}

// Helper function to read integers and strings from standard input
void find_largest_and_longest() {
    int max_int = INT_MIN;
    char *longest_str = NULL;
    size_t longest_len = 0;

    printf("Enter number of elements: ");
    size_t n;
    scanf("%zu", &n);

    for (size_t i = 0; i < n; ++i) {
        int num;
        char str[256];

        printf("Enter integer %zu: ", i + 1);
        scanf("%d", &num);

        if (num > max_int) max_int = num;

        printf("Enter string %zu: ", i + 1);
        scanf("%s", str);

        size_t len = strlen(str);
        if (len > longest_len) {
            longest_len = len;
            free(longest_str);
            longest_str = strdup(str);  // Use strdup to allocate and copy
        }
    }

    printf("Largest integer: %d\nLongest string: %s\n", max_int, longest_str);

    if (longest_str) {
        free(longest_str);
    }
}

int main() {
    size_t record_count = 5;
    size_t max_size = 1024;
    int min_val = -10, max_val = 10;
    size_t alignment = 8;

    Record **records = initialize_records(record_count, max_size, min_val, max_val, alignment);
    if (!records) return EXIT_FAILURE;

    // Example: Serialize and compress records
    for (size_t i = 0; i < record_count; ++i) {
        uint8_t buffer[256];
        serialize_record(records[i], buffer, sizeof(buffer));

        uint8_t *compressed_data;
        size_t compressed_size;
        if (compress_data(buffer, sizeof(buffer), &compressed_data, &compressed_size) == 0) {
            printf("Record %zu serialized and compressed successfully\n", i + 1);

            // Decompress for demonstration
            uint8_t *decompressed_data;
            if (decompress_data(compressed_data, compressed_size, &decompressed_data, sizeof(buffer)) == 0) {
                Record record;
                deserialize_record(decompressed_data, &record);
                printf("Deserialized value: %d, offset: %ld\n", record.value, record.offset);

                free(decompressed_data);
            }
            free(compressed_data);
        } else {
            fprintf(stderr, "Failed to compress data for record %zu\n", i + 1);
        }
    }

    free_all_records(records, record_count);

    // Call helper function
    find_largest_and_longest();

    return EXIT_SUCCESS;
}
