config* create_configs(size_t max_size, size_t num_configs, double min_val, double max_val, const char **names, size_t name_len) {
    srand((unsigned int)time(NULL));

    // Calculate the total size needed for one config struct
    size_t config_size = sizeof(config) + (name_len - 1); // Subtracting 1 because of null terminator inclusion in size calculation

    if (num_configs * config_size > max_size) {
        fprintf(stderr, "Error: Insufficient memory available.\n");
        return NULL;
    }

    config* configs = malloc(num_configs * config_size);
    if (!configs) {
        perror("Failed to allocate memory for configs");
        return NULL;
    }

    double range = max_val - min_val;

    for (size_t i = 0; i < num_configs; ++i) {
        configs[i].value = min_val + ((double)rand() / RAND_MAX) * range;
        strncpy(configs[i].name, names[i], name_len);
        configs[i].name[name_len - 1] = '\0'; // Ensure null-termination
        configs[i].active = (i % 2 == 0); // Example: activate every alternate config

        // Simulate potential data handling from an external source and validate
        if (configs[i].value < min_val || configs[i].value > max_val) {
            fprintf(stderr, "Error: Value out of range for config index %zu\n", i);
            free_configs(configs, num_configs);
            return NULL;
        }
    }

    return configs;
}

void serialize_configs(const config* configs, size_t count, unsigned char **buffer, size_t *buf_size) {
    // Calculate required buffer size
    size_t total_size = 0;
    for (size_t i = 0; i < count; ++i) {
        total_size += sizeof(double) + strlen(configs[i].name) + 1 + sizeof(bool);
    }

    *buffer = malloc(total_size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization");
        return;
    }

    unsigned char *ptr = *buffer;

    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &configs[i].value, sizeof(double));
        ptr += sizeof(double);

        strcpy((char *)ptr, configs[i].name);
        ptr += strlen(configs[i].name) + 1;

        memcpy(ptr, &configs[i].active, sizeof(bool));
        ptr += sizeof(bool);
    }

    *buf_size = total_size;
}

void deserialize_configs(const unsigned char* buffer, size_t buf_size, config** configs, size_t* count) {
    // Calculate number of configs from buffer
    size_t index = 0;
    size_t num_configs = 0;

    while (index + sizeof(double) < buf_size) {
        num_configs++;
        index += sizeof(double);

        while (index < buf_size && buffer[index] != '\0') {
            ++index;
        }
        if (buffer[index] == '\0') {
            ++index; // for null terminator
        }

        index += sizeof(bool);
    }

    *count = num_configs;
    *configs = malloc(num_configs * sizeof(config));

    if (!*configs) {
        perror("Failed to allocate memory for deserialization");
        return;
    }

    ptrdiff_t offset = 0;

    for (size_t i = 0; i < num_configs; ++i) {
        memcpy(&(*configs)[i].value, buffer + offset, sizeof(double));
        offset += sizeof(double);

        strncpy((*configs)[i].name, (const char*)(buffer + offset), buf_size - index);
        (*configs)[i].name[255] = '\0'; // Ensure null-termination
        while (offset < buf_size && buffer[offset] != '\0') {
            ++offset;
        }
        if (buffer[offset] == '\0') {
            ++offset; // for null terminator
        }

        memcpy(&(*configs)[i].active, buffer + offset, sizeof(bool));
        offset += sizeof(bool);
    }
}

