public:
    DynamicValueGenerator(int minVal, int maxVal) 
        : minValue(minVal), maxValue(maxVal) {
        if (minVal > maxVal) throw std::invalid_argument("Invalid range: minValue cannot be greater than maxValue.");
    }

    void setRange(int minVal, int maxVal) {
        std::lock_guard<std::mutex> lock(mtx);
        if (minVal > maxVal) throw std::invalid_argument("Invalid range: minValue cannot be greater than maxValue.");
        minValue = minVal;
        maxValue = maxVal;
    }

    void setSubRange(float subMin, float subMax) {
        std::lock_guard<std::mutex> lock(mtx);
        if (subMin >= subMax) throw std::invalid_argument("Invalid sub-range: subMin cannot be greater than or equal to subMax.");
        this->subMin = subMin;
        this->subMax = subMax;
    }

    int generateRandomInt() {
        std::lock_guard<std::mutex> lock(mtx);
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> distrib(minValue, maxValue - 1); // exclusive of maxValue
        return distrib(gen);
    }

    float generateRandomFloat() {
        std::lock_guard<std::mutex> lock(mtx);
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<float> distrib(minValue, static_cast<float>(maxValue) - 0.0001f); // exclusive of maxValue
        return distrib(gen);
    }

    int generateRandomIntInRange(float subMin, float subMax) {
        std::lock_guard<std::mutex> lock(mtx);
