        std::uniform_int_distribution<> distrib(static_cast<int>(subMin), static_cast<int>(subMax - 1)); // exclusive of subMax
        return distrib(gen);
    }

    float generateRandomFloatInRange(float subMin, float subMax) {
        std::lock_guard<std::mutex> lock(mtx);
        if (subMin >= subMax) throw std::invalid_argument("Invalid sub-range: subMin cannot be greater than or equal to subMax.");
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<float> distrib(subMin, subMax - 0.0001f); // exclusive of subMax
        return distrib(gen);
    }

    std::vector<int> generateRandomIntSequence(size_t n) {
        if (n <= 0) throw std::invalid_argument("Invalid sequence size: must be greater than zero.");
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<int> result(n);
