#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <endian.h>

#define MAX_MEMORY_SIZE 1024 * 1024 // Example max size limit (1MB)
#define SENSOR_ID_LENGTH 16
#define TEMPERATURE_RANGE_MIN -50.0f
#define TEMPERATURE_RANGE_MAX 100.0f

typedef struct {
    float temperature;
    char sensor_id[SENSOR_ID_LENGTH];
    time_t last_update;
    uint8_t operational_status;
} Sensor;

// Memory pool structure
typedef struct {
    void *pool;
    size_t total_size;
    size_t used_size;
} MemoryPool;

MemoryPool memory_pool;

void initialize_memory_pool(size_t max_size) {
    memory_pool.pool = malloc(max_size);
    if (!memory_pool.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    memory_pool.total_size = max_size;
    memory_pool.used_size = 0;
}

void *allocate_from_pool(size_t size) {
    if (memory_pool.used_size + size > memory_pool.total_size) {
        return NULL; // Not enough space
    }
    void *ptr = (char *)memory_pool.pool + memory_pool.used_size;
    memory_pool.used_size += size;
    return ptr;
}

void free_memory_pool() {
    free(memory_pool.pool);
}

// Seed the random number generator
void seed_rng() {
    srand((unsigned)time(NULL));
}

float generate_random_temperature() {
    float range = TEMPERATURE_RANGE_MAX - TEMPERATURE_RANGE_MIN;
    return TEMPERATURE_RANGE_MIN + (rand() / (RAND_MAX / range));
}

Sensor *create_sensor(const char *id, uint8_t status) {
    Sensor *sensor = (Sensor *)allocate_from_pool(sizeof(Sensor));
    if (!sensor) {
        fprintf(stderr, "Failed to allocate memory for sensor\n");
        return NULL;
    }

    strncpy(sensor->sensor_id, id, SENSOR_ID_LENGTH - 1);
    sensor->sensor_id[SENSOR_ID_LENGTH - 1] = '\0';
    sensor->temperature = generate_random_temperature();
    sensor->last_update = time(NULL);
    sensor->operational_status = status;

    return sensor;
}

size_t serialize_sensor(Sensor *sensor, uint8_t *buffer) {
    size_t offset = 0;

    memcpy(buffer + offset, &htonl((uint32_t)sensor->temperature), sizeof(float)); // Assuming IEEE 754
    offset += sizeof(float);
    memcpy(buffer + offset, sensor->sensor_id, SENSOR_ID_LENGTH);
    offset += SENSOR_ID_LENGTH;
    memcpy(buffer + offset, &htonll(sensor->last_update), sizeof(time_t));
    offset += sizeof(time_t);
    buffer[offset++] = sensor->operational_status;

    return offset;
}

Sensor *deserialize_sensor(const uint8_t *buffer) {
    Sensor *sensor = (Sensor *)malloc(sizeof(Sensor));
    if (!sensor) {
        perror("Failed to allocate memory for sensor");
        exit(EXIT_FAILURE);
    }

    memcpy(&sensor->temperature, &ntohl((uint32_t)(*(float *)(buffer))), sizeof(float)); // Assuming IEEE 754
    memcpy(sensor->sensor_id, buffer + sizeof(float), SENSOR_ID_LENGTH);
    memcpy(&sensor->last_update, &ntohll(*(time_t *)(buffer + sizeof(float) + SENSOR_ID_LENGTH)), sizeof(time_t));
    sensor->operational_status = buffer[sizeof(float) + SENSOR_ID_LENGTH + sizeof(time_t)];

    return sensor;
}

void check_and_update_sensors(Sensor *sensors, size_t count) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < count; ++i) {
        if (sensors[i].operational_status && difftime(current_time, sensors[i].last_update) > 60) { // Example: update every minute
            sensors[i].last_update = current_time;
            sensors[i].temperature = generate_random_temperature();
        }
    }
}

void free_sensors(Sensor **sensors, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(sensors[i]);
    }
}

int main() {
    initialize_memory_pool(MAX_MEMORY_SIZE);

    const char *sensor_ids[] = {"Sensor1", "Sensor2", "Sensor3"};
    Sensor *sensors[3];

    for (size_t i = 0; i < 3; ++i) {
        sensors[i] = create_sensor(sensor_ids[i], 1); // Operational status set to 1
        if (!sensors[i]) {
            fprintf(stderr, "Error creating sensor %zu\n", i);
            free_memory_pool();
            return EXIT_FAILURE;
        }
    }

    uint8_t buffer[1024];
    for (size_t i = 0; i < 3; ++i) {
        size_t serialized_size = serialize_sensor(sensors[i], buffer);
        printf("Serialized Sensor %zu: %zu bytes\n", i, serialized_size);
    }

    check_and_update_sensors((Sensor *)sensors, 3);

    free_sensors(sensors, 3);
    free_memory_pool();

    return EXIT_SUCCESS;
}
```

### Notes:
- **Memory Management**: A simple memory pool is used to manage allocations and avoid fragmentation.
- **Random Temperature Generation**: Uses `rand()` seeded with the current time to generate temperatures within a specified range.
- **Serialization/Deserialization**: Handles endianness for cross-platform compatibility using `htons`, `htonl`, etc.
- **Sensor Status Check**: Updates sensors periodically based on their operational status and timestamp.
- **Error Handling**: Gracefully handles memory allocation failures and ensures all resources are freed properly.']

