typedef struct {
    pthread_mutex_t mutex;
    size_t count;
    record_t *records;
} RecordArray;

void log_message(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}

int initialize_record_array(RecordArray *arr, size_t max_records, size_t record_size, int retry_count) {
    if (max_records * record_size > MAX_SIZE) {
        log_message("ERROR", "Exceeding maximum memory allocation limit.");
        return -1;
    }

    arr->records = NULL;
    for (int i = 0; i < retry_count; ++i) {
        arr->records = malloc(max_records * record_size);
        if (arr->records != NULL) break;
        log_message("WARNING", "Memory allocation failed, retrying...");
        sleep(1); // Simple backoff strategy
    }

    if (arr->records == NULL) {
        log_message("ERROR", "Failed to allocate memory after retries.");
        return -1;
    }
    arr->count = 0;

    pthread_mutex_init(&arr->mutex, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < max_records; ++i) {
        int value = RECORD_INT_MIN + rand() % (RECORD_INT_MAX - RECORD_INT_MIN + 1);
        arr->records[i].value = value;
        arr->records[i].offset = (long)i * sizeof(record_t);
    }

    return 0;
}

void serialize_record_array(const RecordArray *arr, uint8_t **buffer, size_t *buffer_size) {
    pthread_mutex_lock(&arr->mutex);

    *buffer_size = arr->count * sizeof(record_t);
    if (*buffer_size > MAX_SIZE) {
        log_message("ERROR", "Serialization buffer exceeds maximum size.");
        pthread_mutex_unlock(&arr->mutex);
        return;
    }

    *buffer = malloc(*buffer_size);
    if (*buffer == NULL) {
        log_message("ERROR", "Failed to allocate serialization buffer.");
        pthread_mutex_unlock(&arr->mutex);
        return;
    }

    memcpy(*buffer, arr->records, *buffer_size);

    pthread_mutex_unlock(&arr->mutex);
}

void deserialize_record_array(const uint8_t *buffer, size_t buffer_size, RecordArray *arr) {
    if (buffer == NULL || arr == NULL) {
        log_message("ERROR", "Invalid parameters for deserialization.");
        return;
    }

    pthread_mutex_lock(&arr->mutex);

    size_t record_count = buffer_size / sizeof(record_t);
    arr->count = record_count;

    free(arr->records);
    arr->records = malloc(buffer_size);
    if (arr->records == NULL) {
        log_message("ERROR", "Failed to allocate memory for deserialization.");
        pthread_mutex_unlock(&arr->mutex);
        return;
    }

    memcpy(arr->records, buffer, buffer_size);

    pthread_mutex_unlock(&arr->mutex);
}

char *generate_random_string(size_t length) {
