    size_t charset_size = strlen(CHAR_SET);

    for (size_t i = 0; i < length; ++i) {
        str[i] = CHAR_SET[rand() % charset_size];
    }
    str[length] = '\0';

    return str;
}

void hash_password(const char *password, unsigned char *output_hash) {
    if (!password || !output_hash) {
        log_message("ERROR", "Invalid parameters for password hashing.");
        return;
    }

    unsigned int len = 0;
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    for (unsigned int i = 0; i < HASH_ITERATIONS; ++i) {
        SHA256_Update(&ctx, password, strlen(password));
    }
    SHA256_Final(output_hash, &ctx);

    log_message("INFO", "Password hashed successfully.");
}

void rehash_password(const char *password, unsigned char *output_hash) {
