```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <curl/curl.h>
#include <jansson.h> // JSON parsing library

#define MAX_CONFIG_NAME_SIZE 256
#define CONFIG_DATA_URL "https://api.example.com/config"
#define MAX_SIZE_LIMIT 1024 * 1024 // 1MB max size limit for configurations
#define RETRY_LIMIT 3

typedef struct {
    double value;
    char name[MAX_CONFIG_NAME_SIZE];
    bool active;
} Config;

typedef struct {
    char* memory;
    size_t size;
} MemoryBuffer;

pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

size_t write_memory_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryBuffer* mem = (MemoryBuffer*) userp;

    char* ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

bool fetchConfigDataFromAPI(MemoryBuffer* buffer) {
    CURL *curl;
    CURLcode res;
    curl_global_init(CURL_GLOBAL_DEFAULT);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Authorization: Bearer YOUR_TOKEN");

    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, CONFIG_DATA_URL);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*) buffer);

        for(int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
            res = curl_easy_perform(curl);
            if(res == CURLE_OK) {
                return true;
            }
            printf("Attempt %d failed: %s\n", attempt + 1, curl_easy_strerror(res));
            sleep(2); // Wait before retrying
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return false;
}

bool validateJSONData(const char* jsonData) {
    json_error_t error;
    json_t *root = json_loads(jsonData, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON data: %s\n", error.text);
        return false;
    }

    // Validate the structure
    if (!json_is_array(root)) {
        json_decref(root);
        return false;
    }

    size_t config_count = json_array_size(root);
    for (size_t i = 0; i < config_count; ++i) {
        json_t *config_item = json_array_get(root, i);

        if (!json_is_object(config_item)) {
            json_decref(root);
            return false;
        }

        const char* name = json_string_value(json_object_get(config_item, "name"));
        double value = json_number_value(json_object_get(config_item, "value"));
        bool active = json_boolean_value(json_object_get(config_item, "active"));

        if (name == NULL || !isfinite(value)) {
            json_decref(root);
            return false;
        }
    }

    json_decref(root);
    return true;
}

Config* initializeConfigurations(size_t max_configs) {
    pthread_mutex_lock(&config_lock);

    MemoryBuffer buffer = {NULL, 0};

    if (!fetchConfigDataFromAPI(&buffer)) {
        pthread_mutex_unlock(&config_lock);
        free(buffer.memory);
        fprintf(stderr, "Failed to fetch configuration data from API\n");
        return NULL;
    }

    if (!validateJSONData(buffer.memory)) {
        pthread_mutex_unlock(&config_lock);
        free(buffer.memory);
        fprintf(stderr, "Invalid JSON data received from API\n");
        return NULL;
    }

    json_error_t error;
    json_t *root = json_loads(buffer.memory, 0, &error);

    if (!root || !json_is_array(root)) {
        pthread_mutex_unlock(&config_lock);
        free(buffer.memory);
        fprintf(stderr, "Error parsing JSON: %s\n", error.text ? error.text : "Invalid root");
        return NULL;
    }

    size_t config_count = json_array_size(root);
    if (config_count > max_configs) {
        pthread_mutex_unlock(&config_lock);
        free(buffer.memory);
        fprintf(stderr, "Too many configurations received\n");
        return NULL;
    }

    double totalMemoryUsed = 0.0;

    Config* configs = malloc(config_count * sizeof(Config));
    if (!configs) {
        pthread_mutex_unlock(&config_lock);
        free(buffer.memory);
        fprintf(stderr, "Failed to allocate memory for configurations\n");
        return NULL;
    }

    for (size_t i = 0; i < config_count; ++i) {
        json_t *config_item = json_array_get(root, i);

        const char* name = json_string_value(json_object_get(config_item, "name"));
        double value = json_number_value(json_object_get(config_item, "value"));
        bool active = json_boolean_value(json_object_get(config_item, "active"));

        if (strlen(name) >= MAX_CONFIG_NAME_SIZE) {
            free(configs);
            pthread_mutex_unlock(&config_lock);
            free(buffer.memory);
            fprintf(stderr, "Configuration name too long\n");
            return NULL;
        }

        totalMemoryUsed += sizeof(Config);

        Config* config = &configs[i];
        strncpy(config->name, name, MAX_CONFIG_NAME_SIZE - 1);
        config->name[MAX_CONFIG_NAME_SIZE - 1] = '\0';
        config->value = value; // Replace with random value in a given range as required
        config->active = active;
    }

    json_decref(root);

    if (totalMemoryUsed > MAX_SIZE_LIMIT) {
        free(configs);
        pthread_mutex_unlock(&config_lock);
        free(buffer.memory);
        fprintf(stderr, "Total memory used exceeds limit\n");
        return NULL;
    }

    pthread_mutex_unlock(&config_lock);
    free(buffer.memory);

    return configs;
}

void cleanupConfigurations(Config* configurations, size_t count) {
    if (configurations) {
        free(configurations);
    }
}

