['Below is a basic implementation outline for a connection management library in C that meets the specified requirements. This example focuses on key components such as thread-safe operations, dynamic configuration, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 50000
#define POOL_SIZE_LIMIT (1024 * 1024 * 100) // 100 MB

typedef enum {
    STATE_NEW,
    STATE_ESTABLISHED,
    STATE_CLOSED,
    CUSTOM_STATE_1, // Example custom state
    // Add more states as needed
} ConnectionState;

typedef struct {
    int socket_fd;
    ConnectionState state;
    void* metadata; // Custom metadata for connections
} Connection;

typedef struct {
    Connection* pool[MAX_CONNECTIONS];
    size_t current_size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} ConnectionPool;

ConnectionPool* create_connection_pool() {
    ConnectionPool* cp = (ConnectionPool*)malloc(sizeof(ConnectionPool));
    if (!cp) return NULL;

    memset(cp->pool, 0, sizeof(cp->pool));
    cp->current_size = 0;
    pthread_mutex_init(&cp->lock, NULL);
    pthread_cond_init(&cp->cond_var, NULL);

    return cp;
}

int add_connection(ConnectionPool* cp, int socket_fd) {
    pthread_mutex_lock(&cp->lock);

    if (cp->current_size >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&cp->lock);
        return -1; // Pool is full
    }

    Connection* conn = (Connection*)malloc(sizeof(Connection));
    if (!conn) {
        pthread_mutex_unlock(&cp->lock);
        return -2; // Memory allocation failed
    }

    conn->socket_fd = socket_fd;
    conn->state = STATE_NEW;
    conn->metadata = NULL;

    cp->pool[cp->current_size++] = conn;
    pthread_cond_signal(&cp->cond_var);

    pthread_mutex_unlock(&cp->lock);
    return 0; // Success
}

Connection* get_idle_connection(ConnectionPool* cp) {
    pthread_mutex_lock(&cp->lock);

    for (size_t i = 0; i < cp->current_size; ++i) {
        if (cp->pool[i]->state == STATE_CLOSED) {
            cp->pool[i]->state = STATE_ESTABLISHED;
            Connection* conn = cp->pool[i];
            pthread_mutex_unlock(&cp->lock);
            return conn;
        }
    }

    while (cp->current_size >= MAX_CONNECTIONS) {
        pthread_cond_wait(&cp->cond_var, &cp->lock);
    }

    pthread_mutex_unlock(&cp->lock);
    return NULL; // No idle connection found
}

void close_connection(ConnectionPool* cp, Connection* conn) {
    pthread_mutex_lock(&cp->lock);

    for (size_t i = 0; i < cp->current_size; ++i) {
        if (cp->pool[i] == conn) {
            close(conn->socket_fd);
            free(cp->pool[i]);
            memmove(&cp->pool[i], &cp->pool[i + 1], sizeof(Connection*) * (cp->current_size - i - 1));
            cp->current_size--;
            pthread_cond_signal(&cp->cond_var);
            break;
        }
    }

    pthread_mutex_unlock(&cp->lock);
}

void free_connection_pool(ConnectionPool* cp) {
    pthread_mutex_lock(&cp->lock);

    for (size_t i = 0; i < cp->current_size; ++i) {
        close(cp->pool[i]->socket_fd);
        free(cp->pool[i]);
    }

    pthread_mutex_unlock(&cp->lock);
    pthread_mutex_destroy(&cp->lock);
    pthread_cond_destroy(&cp->cond_var);
    free(cp);
}

void log_event(const char* event) {
    // Simple logging function
    printf("%s\n", event);
}

// Example usage
int main() {
    ConnectionPool* cp = create_connection_pool();
    if (!cp) {
        fprintf(stderr, "Failed to create connection pool.\n");
        return EXIT_FAILURE;
    }

    int socket_fd = 0; // Assume a valid socket descriptor is obtained here

    if (add_connection(cp, socket_fd) != 0) {
        log_event("Error adding connection.");
    } else {
        log_event("Connection added successfully.");
    }

    Connection* conn = get_idle_connection(cp);
    if (conn) {
        log_event("Reused an idle connection.");
        close_connection(cp, conn);
    }

    free_connection_pool(cp);
    return EXIT_SUCCESS;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_mutex` and `pthread_cond` for synchronization.
- **Dynamic Configuration**: Supports custom states and metadata.
- **Error Handling**: Graceful handling of errors like memory allocation failures.
- **Logging**: Basic logging mechanism for key events.
- **Connection Pool Management**: Efficiently manages a pool of connections, reusing idle ones.

This code serves as a starting point. You can expand it by adding more sophisticated error handling, dynamic configuration loading, and integration with external data sources.']

