#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 // Example maximum memory usage in bytes

typedef struct {
    int value;
    long offset;
} Record;

// Error handling macro
#define HANDLE_ERROR(msg) do { perror(msg); exit(EXIT_FAILURE); } while (0)

// Function prototypes
void initialize_records(Record **records, size_t *count, int range_min, int range_max);
size_t calculate_memory_usage(size_t count);
void serialize_records(const Record *records, size_t count, unsigned char **buffer, size_t *buffer_size);
void deserialize_records(unsigned char *buffer, size_t buffer_size, Record **records, size_t *count);
void random_string(char *str, size_t length, const char *charset);
void process_file_and_calculate(int *numbers, size_t num_count, double *average, double *median);
pthread_mutex_t lock;

// Initialize records with memory constraints and populate with random values
void initialize_records(Record **records, size_t *count, int range_min, int range_max) {
    if (clock() == -1) HANDLE_ERROR("Failed to seed RNG");

    srand((unsigned)time(NULL));

    *records = NULL;
    size_t max_count = MAX_MEMORY_USAGE / sizeof(Record);
    for (*count = 0; *count < max_count; ++(*count)) {
        unsigned char *temp = realloc(*records, (*count + 1) * sizeof(Record));
        if (!temp) HANDLE_ERROR("Memory allocation failed");

        Record new_record;
        new_record.value = range_min + rand() % (range_max - range_min + 1);
        new_record.offset = rand();

        memcpy(temp + (*count) * sizeof(Record), &new_record, sizeof(Record));

        if (calculate_memory_usage(*count + 1) > MAX_MEMORY_USAGE)
            break;

        *records = temp;
    }
}

// Calculate the total memory usage of records
size_t calculate_memory_usage(size_t count) {
    return count * sizeof(Record);
}

// Serialize records to binary format considering endianness
void serialize_records(const Record *records, size_t count, unsigned char **buffer, size_t *buffer_size) {
    if (!records || !count) {
        *buffer = NULL;
        *buffer_size = 0;
        return;
    }

    // Calculate required buffer size for serialization
    *buffer_size = count * (sizeof(int) + sizeof(long));
    *buffer = malloc(*buffer_size);

    if (!*buffer) HANDLE_ERROR("Memory allocation failed during serialization");

    unsigned char *ptr = *buffer;
    for (size_t i = 0; i < count; ++i) {
        int value = htobe32(records[i].value); // Convert to big-endian
        memcpy(ptr, &value, sizeof(int));
        ptr += sizeof(int);

        long offset = htobe64(records[i].offset);
        memcpy(ptr, &offset, sizeof(long));
        ptr += sizeof(long);
    }
}

// Deserialize records from binary format
void deserialize_records(unsigned char *buffer, size_t buffer_size, Record **records, size_t *count) {
    if (!buffer || !buffer_size) {
        *records = NULL;
        *count = 0;
        return;
    }

    size_t num_records = buffer_size / (sizeof(int) + sizeof(long));
    *records = malloc(num_records * sizeof(Record));

    if (!*records) HANDLE_ERROR("Memory allocation failed during deserialization");

    unsigned char *ptr = buffer;
    for (size_t i = 0; i < num_records; ++i) {
        int value;
        memcpy(&value, ptr, sizeof(int));
        (*records)[i].value = be32toh(value); // Convert from big-endian

        ptr += sizeof(int);

        long offset;
        memcpy(&offset, ptr, sizeof(long));
        (*records)[i].offset = be64toh(offset);

        ptr += sizeof(long);
    }

    *count = num_records;
}

// Generate a random string
void random_string(char *str, size_t length, const char *charset) {
    if (!str || !length || !charset)
        return;

    for (size_t i = 0; i < length - 1; ++i) {
        int key = rand() % strlen(charset);
        str[i] = charset[key];
    }
    str[length - 1] = '\0';
}

// Process a file to calculate average and median of integers
void process_file_and_calculate(int *numbers, size_t num_count, double *average, double *median) {
    if (!numbers || !num_count)
        return;

    // Calculate average
    long sum = 0;
    for (size_t i = 0; i < num_count; ++i)
        sum += numbers[i];

    *average = (double)sum / num_count;

    // Sort to calculate median
    qsort(numbers, num_count, sizeof(int), (int (*)(const void *, const void *))strcmp);

    if (num_count % 2 == 0) {
        *median = (*(numbers + num_count / 2 - 1) + *(numbers + num_count / 2)) / 2.0;
    } else {
        *median = numbers[num_count / 2];
    }
}

// Example function to simulate thread-safe updates
void update_records(Record **records, size_t count, int new_value, long new_offset, int index) {
    pthread_mutex_lock(&lock);

    if (index >= 0 && index < count) {
        (*records)[index].value = new_value;
        (*records)[index].offset = new_offset;
    }

    pthread_mutex_unlock(&lock);
}

// Main function to demonstrate usage
int main() {
    Record *records = NULL;
    size_t record_count = 0;

    initialize_records(&records, &record_count, 1, 100);

    // Simulate serialization and deserialization
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;

    serialize_records(records, record_count, &buffer, &buffer_size);

    Record *deserialized_records = NULL;
    size_t des_record_count = 0;

    deserialize_records(buffer, buffer_size, &deserialized_records, &des_record_count);

    // Cleanup
    free(records);
    free(deserialized_records);
    free(buffer);

    return 0;
}
```

