} SystemRecord;

typedef struct {
    SystemRecord *records[MAX_RECORDS];
    pthread_mutex_t lock;
    size_t count;
} RecordSystem;

int init_record_system(RecordSystem *system) {
    if (!system) return -1;

    system->count = 0;
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        system->records[i] = NULL;
    }
    pthread_mutex_init(&system->lock, NULL);

    return 0;
}

int add_record(RecordSystem *system, int key, long offset, Record record) {
    if (!system || key < 0 || offset < 0) return -1;

    pthread_mutex_lock(&system->lock);

    if (system->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&system->lock);
        return -2;
    }

    size_t index = system->count % MAX_RECORDS;
    SystemRecord *new_record = malloc(sizeof(SystemRecord));
    if (!new_record) {
        pthread_mutex_unlock(&system->lock);
        return -3;
    }

    new_record->offset = offset;
    new_record->key = key;
    new_record->record = record;
    new_record->metadata.last_accessed = time(NULL);

    ListNode *list_node = malloc(sizeof(ListNode));
    if (!list_node) {
        free(new_record);
        pthread_mutex_unlock(&system->lock);
        return -4;
    }

    list_node->prev = NULL;
    list_node->next = system->records[index] ? system->records[index]->list_node : NULL;

    if (list_node->next) {
        list_node->next->prev = list_node;
    }

    new_record->list_node = list_node;
    system->records[index] = new_record;
    ++system->count;

    pthread_mutex_unlock(&system->lock);
    return 0;
}

void free_record_system(RecordSystem *system) {
    if (!system) return;

    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        SystemRecord *record = system->records[i];
        while (record) {
            ListNode *current = record->list_node;
            record->list_node = current->next;

            free(current);
            free(record);

            record = system->records[i];
        }
    }

    pthread_mutex_unlock(&system->lock);
    pthread_mutex_destroy(&system->lock);
}

