```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <mutex>
#include <stdexcept>

class StringManager {
public:
    StringManager() = default;

    void addString(const std::string& str) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (strings_.size() >= MAX_RECORDS) {
            throw std::runtime_error("Maximum records limit reached.");
        }
        strings_.emplace_front(str);
    }

    bool removeString(const std::string& str) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = find(strings_, str);
        if (it != strings_.end()) {
            strings_.erase_after(it.prev());
            return true;
        }
        return false;
    }

    const std::string* lookupString(const std::string& str) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = find(strings_, str);
        if (it != strings_.end()) {
            return &(*it);
        }
        return nullptr;
    }

    void insertAfterFirstOccurrence(const std::string& target, const std::string& toInsert) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = find(strings_, target);
        if (it != strings_.end()) {
            strings_.insert_after(it, toInsert);
        } else {
            strings_.emplace_front(toInsert);
        }
    }

private:
    static constexpr size_t MAX_RECORDS = 10000;
    mutable std::mutex mutex_;
    std::forward_list<std::string> strings_;

    auto find(const std::forward_list<std::string>& list, const std::string& str) const {
        for (const auto& s : list) {
            if (s == str) return std::find(list.begin(), list.end(), s);
        }
        return list.end();
    }
};

// Test cases
void testStringManager() {
    StringManager manager;

    // Add strings
    manager.addString("apple");
    manager.addString("banana");
    manager.addString("cherry");

    // Lookup strings
    const std::string* found = manager.lookupString("banana");
    if (found) {
        std::cout << "Found: " << *found << std::endl;
    } else {
        std::cout << "Not Found" << std::endl;
    }

    // Remove string
    bool removed = manager.removeString("banana");
    std::cout << "Removed: " << (removed ? "Yes" : "No") << std::endl;

    // Insert after first occurrence
    manager.insertAfterFirstOccurrence("apple", "date");
    found = manager.lookupString("date");
    if (found) {
        std::cout << "Found after insert: " << *found << std::endl;
    } else {
        std::cout << "Not Found" << std::endl;
    }
}

int main() {
    testStringManager();
    return 0;
}
