    pthread_mutex_lock(&data_model_mutex);
    Metadata* new_metadata = realloc(model->metadata, sizeof(Metadata) * (model->metadata_count + 1));
    if (!new_metadata || sizeof(Metadata) * (model->metadata_count + 1) > max_memory_size - sizeof(DataModel)) {
        perror("Memory limit exceeded");
        pthread_mutex_unlock(&data_model_mutex);
        return -1;
    }
    new_metadata[model->metadata_count].tag = strdup(tag);
    if (!new_metadata[model->metadata_count].tag) {
        perror("Failed to allocate memory for metadata tag");
        free(new_metadata);
        pthread_mutex_unlock(&data_model_mutex);
        return -1;
    }
    new_metadata[model->metadata_count].creation_timestamp = timestamp;
    new_metadata[model->metadata_count].flags = flags;
    new_metadata[model->metadata_count].related_record = related_record;
    model->metadata = new_metadata;
    model->metadata_count++;
    pthread_mutex_unlock(&data_model_mutex);
    return 0;
}

int serialize_data_model(DataModel* model, SerializationFormat format) {
    if (!model) return -1;

    pthread_mutex_lock(&data_model_mutex);

    // Example serialization logic
    FILE* file = fopen("data_model.bin", (format == BINARY) ? "wb" : "w");
    if (!file) {
        perror("Failed to open file for serialization");
        pthread_mutex_unlock(&data_model_mutex);
        return -1;
    }

    fwrite(&model->record_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < model->record_count; ++i) {
        if (format == BINARY) {
            fwrite(&model->records[i].value, sizeof(int), 1, file);
            fwrite(&model->records[i].offset, sizeof(long), 1, file);
        } else {
            fprintf(file, "Record %zu: Value=%d, Offset=%ld\n", i, model->records[i].value, model->records[i].offset);
        }
    }

    fclose(file);

    pthread_mutex_unlock(&data_model_mutex);
    return 0;
}

int deserialize_data_model(DataModel* model, SerializationFormat format) {
    if (!model) return -1;

    pthread_mutex_lock(&data_model_mutex);

    FILE* file = fopen("data_model.bin", (format == BINARY) ? "rb" : "r");
    if (!file) {
        perror("Failed to open file for deserialization");
        pthread_mutex_unlock(&data_model_mutex);
        return -1;
    }

    size_t record_count;
    fread(&record_count, sizeof(size_t), 1, file);

    model->records = realloc(model->records, sizeof(Record) * record_count);
    if (!model->records) {
        perror("Failed to allocate memory for records");
        fclose(file);
        pthread_mutex_unlock(&data_model_mutex);
        return -1;
    }
    model->record_count = record_count;

    for (size_t i = 0; i < record_count; ++i) {
        if (format == BINARY) {
            fread(&model->records[i].value, sizeof(int), 1, file);
            fread(&model->records[i].offset, sizeof(long), 1, file);
        } else {
            // Parse text format
            char line[256];
            fgets(line, sizeof(line), file);
            sscanf(line, "Record %zu: Value=%d, Offset=%ld", &i, &model->records[i].value, &model->records[i].offset);
        }
    }

    fclose(file);

    pthread_mutex_unlock(&data_model_mutex);
    return 0;
}

void free_data_model(DataModel* model) {
    if (!model) return;

    pthread_mutex_lock(&data_model_mutex);

    for (size_t i = 0; i < model->metadata_count; ++i) {
        free(model->metadata[i].tag);
    }
    free(model->records);
    free(model->metadata);
    free(model->dependencies);
    free(model);

    pthread_mutex_unlock(&data_model_mutex);
}

int main() {
    DataModel* model = create_data_model(MAX_MEMORY_SIZE);
    if (!model) return EXIT_FAILURE;

    add_record(model, 42, 1234567890L, MAX_MEMORY_SIZE);
    add_metadata(model, "Sample Tag", time(NULL), 1, &model->records[0], MAX_MEMORY_SIZE);

    serialize_data_model(model, BINARY);
    deserialize_data_model(model, BINARY);

    free_data_model(model);
    return EXIT_SUCCESS;
}
