#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_SESSIONS 100
#define BUFFER_SIZE 1024

typedef struct {
    int Session_ID;
    int Socket_Files[2];
    char Data_Buffer[BUFFER_SIZE];
} Network_Session;

typedef struct Node {
    Network_Session session;
    struct Node* next;
} Node;

pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t condition_var = PTHREAD_COND_INITIALIZER;

Node* head = NULL;
int active_sessions = 0;

void enqueue(Network_Session session) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(1);
    }
    new_node->session = session;
    new_node->next = NULL;

    pthread_mutex_lock(&queue_lock);

    if (!head) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next)
            temp = temp->next;
        temp->next = new_node;
    }

    active_sessions++;
    pthread_cond_signal(&condition_var);
    pthread_mutex_unlock(&queue_lock);
}

Network_Session dequeue() {
    pthread_mutex_lock(&queue_lock);

    while (!head) {
        pthread_cond_wait(&condition_var, &queue_lock);
    }

    Node* temp = head;
    Network_Session session = temp->session;

    head = head->next;
    free(temp);

    active_sessions--;
    pthread_mutex_unlock(&queue_lock);

    return session;
}

void* session_handler(void *arg) {
    while (1) {
        Network_Session session = dequeue();

        // Simulate handling the session
        printf("Handling session ID: %d\n", session.Session_ID);

        sleep(1);  // Simulating time taken for processing

        if (!active_sessions) break;
    }
    return NULL;
}

void manage_sessions(Network_Session* sessions, int count) {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, session_handler, NULL)) {
        perror("Failed to create background thread");
        return 0;
    }

    for (int i = 0; i < count; ++i) {
        enqueue(sessions[i]);
    }

    pthread_join(thread_id, NULL);
    return 1;
}

long* allocate_long_array(int size) {
