record* populate_records(int count, int range_min, int range_max) {
    record* records = malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(1);
    }

    pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < count; ++i) {
        int key = range_min + rand() % (range_max - range_min + 1);

        pthread_mutex_lock(&record_lock);
        records[i].key = key;
        while (i > 0 && records[i-1].key > records[i].key) {
            int temp = records[i].key;
            records[i].key = records[i-1].key;
            records[i-1].key = temp;
            i--;
        }
        pthread_mutex_unlock(&record_lock);
    }

    return records;
}

int main() {
