```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataItem {
    double value;
    char *string;
} DataItem;

typedef struct Node {
    DataItem data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void init_linked_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int is_valid_string(const char *str, size_t max_len, const char *allowed_chars) {
    if (strlen(str) > max_len) return 0;
    for (size_t i = 0; i < strlen(str); ++i) {
        if (strchr(allowed_chars, str[i]) == NULL) return 0;
    }
    return 1;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

Node* create_node(double value, const char *string, size_t max_len, const char *allowed_chars) {
    if (!is_valid_string(string, max_len, allowed_chars)) {
        log_error("Invalid string input.");
        return NULL;
    }

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        log_error("Memory allocation failed for new node.");
        return NULL;
    }

    node->data.value = value;
    node->data.string = (char*)malloc(max_len + 1);
    if (!node->data.string) {
        free(node);
        log_error("Memory allocation failed for string buffer.");
        return NULL;
    }

    strncpy(node->data.string, string, max_len);
    node->data.string[max_len] = '\0';
    node->next = NULL;

    return node;
}

void append_node(LinkedList* list, double value, const char *string, size_t max_len, const char *allowed_chars) {
    Node* new_node = create_node(value, string, max_len, allowed_chars);
    if (!new_node) return;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data.string);
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void update_node_value(LinkedList *list, size_t index, double new_value) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current != NULL) {
        current->data.value = new_value;
    } else {
        log_error("Index out of bounds.");
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_and_modify(LinkedList *list, void (*modify_func)(DataItem *)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        modify_func(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void example_modify_function(DataItem *item) {
    item->value *= 2; // Example modification
}

int main() {
    LinkedList list;
    init_linked_list(&list);

    const size_t max_len = 10;
    const char* allowed_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    append_node(&list, 1.5, "HelloWorld", max_len, allowed_chars);
    append_node(&list, 2.7, "AnotherString", max_len, allowed_chars);

    iterate_and_modify(&list, example_modify_function);

    free_list(&list);

    return 0;
}
```

