void* ingest_data(DataStreamSource source, DataRecord** out_record) {
    static pthread_mutex_t ingest_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&ingest_lock);

    if (g_resource_manager.allocated_memory >= g_resource_manager.memory_limit) {
        fprintf(stderr, "Memory limit exceeded.\n");
        pthread_mutex_unlock(&ingest_lock);
        return NULL;
    }

    DataRecord* record = malloc(sizeof(DataRecord));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for data record.\n");
        pthread_mutex_unlock(&ingest_lock);
        return NULL;
    }

    g_resource_manager.allocated_memory += sizeof(DataRecord);

    // Simulate ingestion logic
    record->value = rand();
    record->offset = atomic_fetch_add(&(g_resource_manager.node_state.state_version), 1);
    record->metadata.timestamp = time(NULL);
    record->metadata.flags = rand() % 256;

    pthread_mutex_unlock(&ingest_lock);

    *out_record = record;
    return NULL; // No error
}

void serialize_data(DataRecord* record, unsigned char** out_buffer, size_t* out_size) {
    static pthread_rwlock_t serialize_lock = PTHREAD_RWLOCK_INITIALIZER;

    pthread_rwlock_rdlock(&serialize_lock);

    size_t buffer_length = sizeof(record->value) + sizeof(record->offset) +
                           sizeof(record->metadata.timestamp) + sizeof(record->metadata.flags);
    *out_buffer = malloc(buffer_length);
    if (!*out_buffer) {
        fprintf(stderr, "Failed to allocate memory for serialization.\n");
        pthread_rwlock_unlock(&serialize_lock);
        return;
    }

    unsigned char* buffer = *out_buffer;

    // Serialize the data with endianness consideration
    memcpy(buffer, &(record->value), sizeof(record->value));
    buffer += sizeof(record->value);

    long offset_be = htonl(record->offset); // Convert to big-endian
    memcpy(buffer, &offset_be, sizeof(record->offset));
    buffer += sizeof(record->offset);

    int timestamp_be = htonl(record->metadata.timestamp);
    memcpy(buffer, &timestamp_be, sizeof(record->metadata.timestamp));
    buffer += sizeof(record->metadata.timestamp);

    unsigned char flags = record->metadata.flags;
    memcpy(buffer, &flags, sizeof(flags));

    *out_size = buffer - (unsigned char*)*out_buffer;

    pthread_rwlock_unlock(&serialize_lock);
}

void compress_data(unsigned char* data, size_t size, unsigned char** out_compressed_data, size_t* out_compressed_size) {
    // Placeholder for compression logic
    *out_compressed_data = malloc(size); // For example purposes: no-op compression
    if (*out_compressed_data) {
        memcpy(*out_compressed_data, data, size);
        *out_compressed_size = size;
    } else {
        fprintf(stderr, "Compression failed.\n");
    }
}

void checkpoint_state() {
    pthread_rwlock_wrlock(&g_resource_manager.node_state.lock);

    // Perform checkpointing logic: write state to persistent storage
    printf("Checkpointing state version %d\n", atomic_load(&(g_resource_manager.node_state.state_version)));

    pthread_rwlock_unlock(&g_resource_manager.node_state.lock);
}

void log_metrics() {
    printf("Current memory usage: %zu bytes\n", g_resource_manager.allocated_memory);
}

int main() {
    DataStreamSource source = NULL; // Placeholder
    DataRecord* record;
    unsigned char* serialized_data;
    size_t serialized_size;

    if (ingest_data(source, &record) == NULL) {
        fprintf(stderr, "Data ingestion failed.\n");
        return EXIT_FAILURE;
    }

    serialize_data(record, &serialized_data, &serialized_size);

    unsigned char* compressed_data;
    size_t compressed_size;
    compress_data(serialized_data, serialized_size, &compressed_data, &compressed_size);

    if (compressed_data) {
        free(compressed_data); // Handle compression success
    }

    log_metrics();
    checkpoint_state();

    free(record);
    free(serialized_data);

    return EXIT_SUCCESS;
}
