#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

// Record structure definition
typedef struct {
    int value;
} record;

// Union-Find data structures and functions
typedef struct {
    int *parent;
    size_t n;
} UF;

UF* uf_create(size_t n) {
    UF *uf = (UF*)malloc(sizeof(UF));
    if (!uf) return NULL;
    uf->n = n;
    uf->parent = (int*)malloc(n * sizeof(int));
    if (!uf->parent) {
        free(uf);
        return NULL;
    }
    for (size_t i = 0; i < n; ++i) {
        uf->parent[i] = i;
    }
    return uf;
}

void uf_free(UF *uf) {
    if (uf) {
        free(uf->parent);
        free(uf);
    }
}

int uf_find(UF *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = uf_find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void uf_union(UF *uf, int x, int y) {
    int rootX = uf_find(uf, x);
    int rootY = uf_find(uf, y);
    if (rootX != rootY) {
        uf->parent[rootY] = rootX;
    }
}

// External logging function
void log_operation(const char *message) {
    // Placeholder for actual logging implementation
    printf("%s\n", message);  // For demonstration, replace with proper logging.
}

// Function to generate random integers within a range
int rand_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

void *process_records(void *arg) {
    record *records = ((struct thread_arg *)arg)->records;
    size_t start = ((struct thread_arg *)arg)->start;
    size_t end = ((struct thread_arg *)arg)->end;
    UF *uf = ((struct thread_arg *)arg)->uf;

    for (size_t i = start; i < end; ++i) {
        int value = records[i].value;
        uf_union(uf, value % uf->n, (value + 1) % uf->n);
    }
    return NULL;
}

int main() {
    srand(time(NULL));

    const size_t n_records = 1000000; // Example size
    const int min_value = 0;
    const int max_value = 9999;

    record *records = (record*)malloc(n_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return EXIT_FAILURE;
    }

    // Initialize records with random values
    for (size_t i = 0; i < n_records; ++i) {
        records[i].value = rand_int(min_value, max_value);
    }

    UF *uf = uf_create(10000);  // Assume maximum value range is known
    if (!uf) {
        free(records);
        fprintf(stderr, "Memory allocation failed for Union-Find.\n");
        return EXIT_FAILURE;
    }

    const int num_threads = 8; 
    pthread_t threads[num_threads];
    struct thread_arg args[num_threads];
    size_t chunk_size = n_records / num_threads;

    clock_t start_time = clock();

    // Create and run threads
    for (int i = 0; i < num_threads; ++i) {
        args[i].records = records;
        args[i].start = i * chunk_size;
        args[i].end = (i == num_threads - 1) ? n_records : (i + 1) * chunk_size;
        args[i].uf = uf;

        if (pthread_create(&threads[i], NULL, process_records, &args[i]) != 0) {
            log_operation("Thread creation failed.");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    clock_t end_time = clock();
    double elapsed_time = ((double)(end_time - start_time)) / CLOCKS_PER_SEC * 1000;

    // Count disjoint pairs
    int disjoint_pairs = 0;
    for (size_t i = 0; i < uf->n; ++i) {
        if (uf_find(uf, i) == i) {
            disjoint_pairs++;
        }
    }

    log_operation("Union-Find operation completed.");

    printf("Disjoint pairs: %d\n", disjoint_pairs);
    printf("Time taken: %.2f ms\n", elapsed_time);

    uf_free(uf);
    free(records);

    return EXIT_SUCCESS;
}
