// C Program

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

typedef struct {
    char ip[INET_ADDRSTRLEN];
    int port;
    char access_token[256];
} ServerEntry;

void handle_errors(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

SSL_CTX* create_context() {
    const SSL_METHOD *method = TLS_client_method();
    SSL_CTX *ctx = SSL_CTX_new(method);
    if (!ctx) handle_errors("Unable to create SSL context");

    return ctx;
}

void configure_context(SSL_CTX *ctx) {
    SSL_CTX_set_default_verify_paths(ctx);
    if (SSL_CTX_check_private_key(ctx) != 1)
        handle_errors("Private key does not match the public certificate");
}

ServerEntry* connect_to_server(const char *ip, int port, const char *oauth_client_credentials) {
    ServerEntry *entry = malloc(sizeof(ServerEntry));
    if (!entry) handle_errors("Memory allocation failed");

    snprintf(entry->ip, sizeof(entry->ip), ip);
    entry->port = port;

    // Simulate OAuth token retrieval (details depend on implementation)
    strncpy(entry->access_token, "mock_access_token", sizeof(entry->access_token));

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) handle_errors("Failed to create socket");

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0)
        handle_errors("Invalid address");

    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0)
        handle_errors("Connection failed");

    SSL_CTX *ctx = create_context();
    configure_context(ctx);

    SSL *ssl = SSL_new(ctx);
    SSL_set_fd(ssl, sock);

    if (SSL_connect(ssl) <= 0)
        handle_errors("SSL connection failed");

    SSL_free(ssl);
    close(sock);
    SSL_CTX_free(ctx);

    return entry;
}

void free_server_entry(ServerEntry *entry) {
    free(entry);
}

int main() {
    OpenSSL_add_all_algorithms();
    ERR_load_BIO_strings();
    ERR_load_crypto_strings();

    // Example configuration file parsing (details depend on format)
