<?php
// PHP Script

session_start();

function authenticateUser($clientId, $clientSecret, $authUrl, $redirectUri, $scope = '') {
    if (!isset($_GET['code'])) {
        // Generate OAuth 2.0 URL and redirect user for authorization
        $params = [
            'response_type' => 'code',
            'client_id'     => $clientId,
            'redirect_uri'  => $redirectUri,
            'scope'         => $scope,
        ];

        $authUrlWithParams = $authUrl . '?' . http_build_query($params);
        header('Location: ' . $authUrlWithParams);
        exit();
    }

    // Exchange authorization code for access token
    $tokenUrl = parse_url($authUrl, PHP_URL_PATH) . '/token';
    $code = $_GET['code'];

    $postData = [
        'grant_type'    => 'authorization_code',
        'client_id'     => $clientId,
        'client_secret' => $clientSecret,
        'redirect_uri'  => $redirectUri,
        'code'          => $code
    ];

    $ch = curl_init($tokenUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($postData));

    $response = curl_exec($ch);
    if ($response === false) {
        throw new Exception('Failed to retrieve access token: ' . curl_error($ch));
    }

    $tokenData = json_decode($response, true);
    curl_close($ch);

    $_SESSION['access_token'] = $tokenData['access_token'];
}

function getUserInfo($accessTokenUrl) {
    if (!isset($_SESSION['access_token'])) {
        throw new Exception('Access token not set');
    }

    $ch = curl_init($accessTokenUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        'Authorization: Bearer ' . $_SESSION['access_token']
    ]);

    $response = curl_exec($ch);
    if ($response === false) {
        throw new Exception('Failed to retrieve user info: ' . curl_error($ch));
    }

    curl_close($ch);

    return json_decode($response, true);
}

// Example usage
$clientId = 'your-client-id';
$clientSecret = 'your-client-secret';
$authUrl = 'https://example.com/oauth/authorize';
$redirectUri = 'http://localhost/callback.php';
$scope = 'profile email';

try {
    authenticateUser($clientId, $clientSecret, $authUrl, $redirectUri, $scope);
    $userInfo = getUserInfo('https://example.com/api/userinfo');
    echo "User Info: " . print_r($userInfo, true);
} catch (Exception $e) {
    echo 'Error: ' . $e->getMessage();
}
?>
