#define MAX_MEMORY_LIMIT (1024 * 1024) // 1 MB limit for simplicity

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    uint8_t* data;
    size_t length;
    uint32_t version;
    uint16_t checksum;
} SerializedData;

pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;
const size_t BATCH_SIZE = 1000; // Example batch size

// Function prototypes
