void free_records(Record* records, size_t num_records);
SerializedData serialize_data(Record* records, size_t num_records);
void compress_and_store(SerializedData* serialized, const char* db_key);
uint16_t calculate_checksum(const uint8_t* data, size_t length);

int init_records(Record** records, size_t num_records) {
    if (num_records * sizeof(Record) > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Memory allocation limit exceeded.\n");
        return -1;
    }

    Record* new_records = (Record*)malloc(num_records * sizeof(Record));
    if (!new_records) {
        perror("Failed to allocate memory for records");
        return -1;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        new_records[i].value = rand() % 1000; // Random value within range
        new_records[i].offset = rand() % 10000L; // Example offset
    }

    *records = new_records;
    return 0;
}

void free_records(Record* records, size_t num_records) {
    if (records) {
        free(records);
    }
}

SerializedData serialize_data(Record* records, size_t num_records) {
    SerializedData result;
    size_t record_size = sizeof(int) + sizeof(long);
    size_t total_length = num_records * record_size;

    uint8_t* data = (uint8_t*)malloc(total_length);
    if (!data) {
        perror("Failed to allocate memory for serialization");
        exit(EXIT_FAILURE);
    }

    memcpy(data, records, total_length);

    result.data = data;
    result.length = total_length;
    result.version = 1; // Example version

    uint16_t checksum = calculate_checksum(data, total_length);
    result.checksum = htons(checksum); // Ensure network byte order

    return result;
}

void compress_and_store(SerializedData* serialized, const char* db_key) {
    pthread_mutex_lock(&db_lock);

    uLongf compressed_size = compressBound(serialized->length);
    uint8_t* compressed_data = (uint8_t*)malloc(compressed_size);
    if (!compressed_data) {
        perror("Failed to allocate memory for compression");
        exit(EXIT_FAILURE);
    }

    int status = compress(compressed_data, &compressed_size,
                          serialized->data, serialized->length);
    if (status != Z_OK) {
        fprintf(stderr, "Compression failed with status: %d\n", status);
        free(compressed_data);
        pthread_mutex_unlock(&db_lock);
        return;
    }

    // Simulate database storage
    printf("Storing data in DB under key: %s\n", db_key);

    free(compressed_data);
    pthread_mutex_unlock(&db_lock);
}

uint16_t calculate_checksum(const uint8_t* data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return (uint16_t)(checksum & 0xFFFF);
}

void process_batches(size_t num_batches, size_t batch_size) {
    for (size_t i = 0; i < num_batches; ++i) {
        Record* records;
        if (init_records(&records, batch_size)) continue;

        SerializedData serialized_data = serialize_data(records, batch_size);
        compress_and_store(&serialized_data, "record_key");

        free(serialized_data.data);
        free_records(records, batch_size);
    }
}

void* thread_function(void* arg) {
    size_t num_batches = *(size_t*)arg;
    process_batches(num_batches, BATCH_SIZE);
    return NULL;
}

int main() {
    size_t total_batches = 10; // Example number of batches
    pthread_t threads[4];
    size_t batch_per_thread = total_batches / 4;

    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_function, &batch_per_thread);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

