}

int main_input() {
    size_t length;
    int* input_array = read_input(&length);

    printf("Enter the integer to find: ");
    int target;
    scanf("%d", &target);

    size_t position = find_first_occurrence(input_array, length, target);
    if (position == SIZE_MAX) {
        printf("Integer not found.\n");
    } else {
        printf("First occurrence at index: %zu\n", position);
    }

    free(input_array);
    return 0;
}
