['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

// Define the structure for records
typedef struct record {
    int value;
    long offset;
    struct record *next; // For linked list management
} record_t;

// Global variables for managing records and ensuring thread safety
record_t *head = NULL;
size_t current_size = 0;
size_t max_limit = 1024; // Maximum memory limit in bytes, adjustable
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new record
int add_record(int value, long offset) {
    pthread_mutex_lock(&lock);

    if (current_size + sizeof(record_t) > max_limit) {
        fprintf(stderr, "Memory limit exceeded.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    record_t *new_record = malloc(sizeof(record_t));
    if (!new_record) {
        perror("Failed to allocate memory for new record.");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    new_record->value = value;
    new_record->offset = offset;
    new_record->next = head;
    head = new_record;

    current_size += sizeof(record_t);

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to serialize records into a byte array
size_t serialize_records(uint8_t **buffer) {
    size_t count = 0;
    record_t *current = head;

    // Calculate the total size needed for serialization
    while (current != NULL) {
        count++;
        current = current->next;
    }

    if (count == 0) {
        *buffer = NULL;
        return 0;
    }

    *buffer = malloc(count * sizeof(int) + count * sizeof(long));
    if (!*buffer) {
        perror("Failed to allocate memory for serialization.");
        return -1;
    }

    size_t index = 0;
    current = head;
    while (current != NULL) {
        memcpy(*buffer + index, &current->value, sizeof(int));
        index += sizeof(int);
        memcpy(*buffer + index, &current->offset, sizeof(long));
        index += sizeof(long);

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return count * (sizeof(int) + sizeof(long));
}

// Function to deserialize byte array back into records
int deserialize_records(uint8_t *buffer, size_t buffer_size) {
    if (!buffer || buffer_size % (sizeof(int) + sizeof(long)) != 0) {
        fprintf(stderr, "Invalid buffer for deserialization.\n");
        return -1;
    }

