void* serialize_data(int *keys, long *offsets, record_t *records, size_t num_records, char **out_buffer, size_t *out_size) {
    // Calculate buffer size for serialization
    size_t buffer_size = sizeof(int) * num_records + sizeof(long) * num_records + 
                         sizeof(record_t) * num_records;

    // Allocate memory for the buffer
    *out_buffer = (char*)malloc(buffer_size);
    if (*out_buffer == NULL) {
        perror("Failed to allocate memory for serialization");
        return NULL;
    }

    char *ptr = *out_buffer;

    // Serialize keys array
    memcpy(ptr, keys, sizeof(int) * num_records);
    ptr += sizeof(int) * num_records;

    // Serialize offsets array
    memcpy(ptr, offsets, sizeof(long) * num_records);
    ptr += sizeof(long) * num_records;

    // Serialize records array
    memcpy(ptr, records, sizeof(record_t) * num_records);

    *out_size = buffer_size;
    return *out_buffer;
}

int* deserialize_data(const char *buffer, size_t buffer_size, int **out_keys, long **out_offsets, record_t **out_records, size_t *num_records) {
    if (buffer == NULL || buffer_size % sizeof(record_t) != 0) {
        fprintf(stderr, "Invalid buffer for deserialization\n");
        return -1;
    }

    // Calculate the number of records
    *num_records = buffer_size / sizeof(record_t);

    // Allocate memory for outputs
    *out_keys = (int*)malloc(sizeof(int) * (*num_records));
    *out_offsets = (long*)malloc(sizeof(long) * (*num_records));
    *out_records = (record_t*)malloc(sizeof(record_t) * (*num_records));

    if (*out_keys == NULL || *out_offsets == NULL || *out_records == NULL) {
        perror("Failed to allocate memory for deserialization");
        return -1;
    }

    // Deserialize keys and offsets
    memcpy(*out_keys, buffer, sizeof(int) * (*num_records));
    memcpy(*out_offsets, buffer + sizeof(int) * (*num_records), sizeof(long) * (*num_records));

    // Copy records directly as it's already in the same order and format
    memcpy(*out_records, buffer + sizeof(int) * (*num_records) + sizeof(long) * (*num_records), 
           sizeof(record_t) * (*num_records));

    return 0;
}

void initialize_data(size_t max_size, size_t num_records, int key_range, long* offsets, int** keys, record_t** records, unsigned int seed) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Calculate sizes
    size_t offsets_size = sizeof(long) * num_records;
    size_t keys_size = sizeof(int) * num_records;
    size_t records_size = sizeof(record_t) * num_records;

    if (offsets_size + keys_size + records_size > max_size) {
        fprintf(stderr, "Requested memory exceeds the maximum allowed size.\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    // Allocate and initialize offsets
    offsets = (long*)malloc(offsets_size);
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i;
    }

    // Check allocation
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Allocate and initialize keys
    *keys = (int*)malloc(keys_size);
    for (size_t i = 0; i < num_records; ++i) {
        (*keys)[i] = i;
    }

    // Check allocation
    if (!*keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Seed the random number generator
    srand(seed);

    // Allocate and initialize records
    *records = (record_t*)malloc(records_size);
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].key = rand() % key_range;
        (*records)[i].offset = offsets[i];
    }

    // Check allocation
    if (!*records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(*keys);
        pthread_mutex_unlock(&mutex);
        return;
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    size_t max_size = 1024 * 1024; // Example: 1MB
    size_t num_records = 1000; // Example number of records
    int key_range = 100;

    long* offsets;
    int* keys;
    record_t* records;

    initialize_data(max_size, num_records, key_range, offsets, &keys, &records, 1234);

    if (offsets && keys && records) {
        char *serialized_buffer;
        size_t serialized_size;

        serialize_data(keys, offsets, records, num_records, &serialized_buffer, &serialized_size);

        int* deserialized_keys = NULL;
        long* deserialized_offsets = NULL;
        record_t* deserialized_records = NULL;
        size_t num_deserialized_records;

        deserialize_data(serialized_buffer, serialized_size, &deserialized_keys,
                         &deserialized_offsets, &deserialized_records, &num_deserialized_records);

        // Free allocated memory
        free(offsets);
        free(keys);
        free(records);
        free(serialized_buffer);

        if (deserialized_keys && deserialized_offsets && deserialized_records) {
            free(deserialized_keys);
            free(deserialized_offsets);
            free(deserialized_records);
        }
    }

    return 0;
}
