           (num_records * sizeof(int)) +
           (2 * num_records * sizeof(Record)) +
           sizeof(char); // For metadata; adjust as necessary
}

// Function to initialize data structures and ensure memory constraints
int initialize_data(size_t max_size, int range_min, int range_max, long **offsets,
                    int **keys, Record **records1, Record **records2, char **metadata) {
