        // Randomize record values ensuring no overflow
        int random_value;
        do {
            random_value = (rand() % (range_max - range_min + 1)) + range_min;
        } while ((random_value < range_min) || (random_value > range_max));

        (*records1)[i].value = random_value;
        (*records2)[i].value = random_value;

