}

// Function to serialize data structures into a byte array
int serialize_data(long *offsets, int *keys, Record *records1, Record *records2, char *metadata,
                   unsigned char **byte_array, size_t *size) {
    size_t num_records = 5;

    // Calculate required buffer size (considering padding for endianness)
    size_t buf_size = sizeof(size_t); // To store the number of records
    buf_size += num_records * (sizeof(long) + sizeof(int));
    buf_size += 2 * num_records * (sizeof(Record));
    buf_size += sizeof(char);

    *byte_array = (unsigned char *)malloc(buf_size);
    if (*byte_array == NULL) {
        perror("Failed to allocate memory for byte array");
        return -1;
    }

    // Use a temporary buffer pointer
    unsigned char *ptr = *byte_array;

    // Serialize number of records
    memcpy(ptr, &num_records, sizeof(size_t));
    ptr += sizeof(size_t);

    // Serialize offsets and keys
    for (size_t i = 0; i < num_records; ++i) {
        // Ensure endianness consistency during serialization
        long le_offset = htobe64(offsets[i]);
        memcpy(ptr, &le_offset, sizeof(long));
        ptr += sizeof(long);

        int le_key = htonl(keys[i]);
        memcpy(ptr, &le_key, sizeof(int));
        ptr += sizeof(int);
    }

    // Serialize records1 and records2
    for (size_t i = 0; i < num_records; ++i) {
        long le_offset = htobe64(records1[i].offset);
        int le_value = htonl(records1[i].value);

        memcpy(ptr, &le_offset, sizeof(long));
        ptr += sizeof(long);

        memcpy(ptr, &le_value, sizeof(int));
        ptr += sizeof(int);

        // Repeat for records2
        le_offset = htobe64(records2[i].offset);
        le_value = htonl(records2[i].value);

        memcpy(ptr, &le_offset, sizeof(long));
        ptr += sizeof(long);

        memcpy(ptr, &le_value, sizeof(int));
        ptr += sizeof(int);
    }

    // Serialize metadata
    *size = buf_size;
    return 0;
}

// Function to deserialize byte array back into data structures
int deserialize_data(unsigned char *byte_array, size_t size, long **offsets, int **keys,
                     Record **records1, Record **records2, char **metadata) {
    size_t num_records;

    // Deserialize number of records
    memcpy(&num_records, byte_array, sizeof(size_t));
    byte_array += sizeof(size_t);

    *offsets = (long *)malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        perror("Failed to allocate memory for deserialized offsets");
        return -1;
    }

    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        perror("Failed to allocate memory for deserialized keys");
        return -1;
    }

    *records1 = (Record *)malloc(num_records * sizeof(Record));
    if (*records1 == NULL) {
        free(*offsets);
        free(*keys);
        perror("Failed to allocate memory for deserialized records1");
        return -1;
    }

    *records2 = (Record *)malloc(num_records * sizeof(Record));
    if (*records2 == NULL) {
        free(*offsets);
        free(*keys);
        free(*records1);
        perror("Failed to allocate memory for deserialized records2");
        return -1;
    }

    *metadata = (char *)malloc(sizeof(char)); // Adjust as needed
    if (*metadata == NULL) {
        free(*offsets);
        free(*keys);
        free(*records1);
        free(*records2);
        perror("Failed to allocate memory for deserialized metadata");
        return -1;
    }

    unsigned char *ptr = byte_array;

    // Deserialize offsets and keys
    for (size_t i = 0; i < num_records; ++i) {
        long be_offset;
        memcpy(&be_offset, ptr, sizeof(long));
        (*offsets)[i] = be64toh(be_offset);
        ptr += sizeof(long);

        int be_key;
        memcpy(&be_key, ptr, sizeof(int));
        (*keys)[i] = ntohl(be_key);
        ptr += sizeof(int);
    }

    // Deserialize records1 and records2
    for (size_t i = 0; i < num_records; ++i) {
        long be_offset;
        int be_value;

        memcpy(&be_offset, ptr, sizeof(long));
        (*records1)[i].offset = be64toh(be_offset);
        ptr += sizeof(long);

        memcpy(&be_value, ptr, sizeof(int));
        (*records1)[i].value = ntohl(be_value);
        ptr += sizeof(int);

        // Repeat for records2
        memcpy(&be_offset, ptr, sizeof(long));
        (*records2)[i].offset = be64toh(be_offset);
        ptr += sizeof(long);

        memcpy(&be_value, ptr, sizeof(int));
        (*records2)[i].value = ntohl(be_value);
        ptr += sizeof(int);
    }

    // Deserialize metadata
    *(*metadata) = *ptr;

    return 0;
}

// Function to free allocated memory
void cleanup_resources(long *offsets, int *keys, Record *records1,
                       Record *records2, char *metadata) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records1) free(records1);
    if (records2) free(records2);
    if (metadata) free(metadata);
}

// Example usage
int main() {
    long *offsets = NULL;
    int *keys = NULL;
    Record *records1 = NULL, *records2 = NULL;
    char *metadata = NULL;

    // Initialize data structures with a max size and value range
    if (initialize_data(1024, 10, 100, &offsets, &keys, &records1, &records2, &metadata) == -1) {
        cleanup_resources(offsets, keys, records1, records2, metadata);
        return EXIT_FAILURE;
    }

    // Serialize the data
    unsigned char *byte_array = NULL;
    size_t serialized_size = 0;

    if (serialize_data(offsets, keys, records1, records2, metadata, &byte_array, &serialized_size) == -1) {
        cleanup_resources(offsets, keys, records1, records2, metadata);
        return EXIT_FAILURE;
    }

    // Deserialize the data
    long *deserialized_offsets = NULL;
    int *deserialized_keys = NULL;
    Record *deserialized_records1 = NULL, *deserialized_records2 = NULL;
    char *deserialized_metadata = NULL;

    if (deserialize_data(byte_array, serialized_size, &deserialized_offsets, &deserialized_keys,
                         &deserialized_records1, &deserialized_records2, &deserialized_metadata) == -1) {
        cleanup_resources(offsets, keys, records1, records2, metadata);
        free(byte_array);
        return EXIT_FAILURE;
    }

    // Cleanup resources
    cleanup_resources(offsets, keys, records1, records2, metadata);
    cleanup_resources(deserialized_offsets, deserialized_keys, deserialized_records1,
                      deserialized_records2, deserialized_metadata);
    free(byte_array);

    return EXIT_SUCCESS;
}
