    long offset;
} sensor_data;

typedef struct {
    sensor_data *data_array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} sensor_manager;

// Function to initialize the sensor manager
sensor_manager* init_sensor_manager(size_t initial_capacity) {
    sensor_manager *manager = malloc(sizeof(sensor_manager));
    if (!manager) return NULL;

    manager->data_array = malloc(initial_capacity * sizeof(sensor_data));
    if (!manager->data_array) {
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    srand(time(NULL)); // Seed the random number generator
    return manager;
}

// Function to resize the data array
int resize_sensor_manager(sensor_manager *manager) {
    size_t new_capacity = manager->capacity * 2;
    sensor_data *new_array = realloc(manager->data_array, new_capacity * sizeof(sensor_data));

    if (!new_array) return -1;

    manager->data_array = new_array;
    manager->capacity = new_capacity;
    return 0;
}

// Function to add a sensor data entry
int add_sensor_data(sensor_manager *manager, int timestamp, char* device_type, int location_id,
                    float min_reading, float max_reading, float std_dev) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        if (resize_sensor_manager(manager) != 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    sensor_data *entry = &manager->data_array[manager->count++];
    entry->timestamp = timestamp;
    entry->sensor_reading = min_reading + ((float)rand() / RAND_MAX) * (max_reading - min_reading);
    snprintf(entry->device_type, sizeof(entry->device_type), "%s", device_type);
    entry->location_id = location_id;
    entry->key = rand();
    entry->offset = rand();

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Interpolation function for handling timestamp gaps (simple linear interpolation)
float interpolate_sensor_reading(sensor_data *data, int target_timestamp) {
    // Placeholder interpolation logic
    if (!data || data->count < 2) return -1.0;

    sensor_data first = data[0];
    sensor_data second = data[data->count - 1];

    float t1 = first.timestamp;
    float t2 = second.timestamp;
    float r1 = first.sensor_reading;
    float r2 = second.sensor_reading;

    if (t2 == t1) return r1; // Prevent division by zero

    float ratio = ((float)(target_timestamp - t1)) / (t2 - t1);
    return r1 + ratio * (r2 - r1);
}

// Function to handle data inconsistencies
void handle_data_inconsistency(sensor_manager *manager, int timestamp) {
    pthread_mutex_lock(&manager->lock);

    // Iterate and find duplicates or missing timestamps, apply strategies like averaging
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->data_array[i].timestamp == timestamp) {
            printf("Duplicate timestamp found: %d\n", timestamp);
            // Apply handling strategy here
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Unit test function
void test_sensor_manager() {
    sensor_manager *manager = init_sensor_manager(10);

    add_sensor_data(manager, 1627890123, "TemperatureSensor", 1, 20.0, 30.0, 1.5);
    handle_data_inconsistency(manager, 1627890123); // Example test

    for (size_t i = 0; i < manager->count; ++i) {
        printf("Timestamp: %d, Reading: %.2f\n", manager->data_array[i].timestamp,
               manager->data_array[i].sensor_reading);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->data_array);
    free(manager);
}

int main() {
    test_sensor_manager();
    return 0;
}
