#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

void initialize_data(long max_size, size_t num_offsets, size_t num_keys, size_t records_per_structure,
                     int key_min, int key_max, unsigned seed) {
    // Calculate the total memory requirement
    const size_t offsets_size = num_offsets * sizeof(long);
    const size_t keys_size = num_keys * sizeof(int);
    const size_t records_size = (num_offsets / records_per_structure) * sizeof(record);

    if ((offsets_size + keys_size + records_size) > max_size) {
        fprintf(stderr, "Error: Memory requirement exceeds maximum limit.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets
    long* offsets = malloc(offsets_size);
    if (!offsets) {
        perror("Failed to allocate offsets");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets with consecutive integers starting from 0
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }

    // Allocate memory for keys
    int* keys = malloc(keys_size);
    if (!keys) {
        perror("Failed to allocate keys");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Seed the random number generator
    srand(seed);

    // Initialize keys with random integers within the specified range
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = key_min + rand() % ((key_max - key_min) + 1);
    }

    // Allocate memory for records
    record* records = malloc(records_size);
    if (!records) {
        perror("Failed to allocate records");
        free(keys);
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize records with random data and corresponding offsets
    for (size_t i = 0; i < num_offsets / records_per_structure; ++i) {
        records[i].key = key_min + rand() % ((key_max - key_min) + 1);
        records[i].offset = offsets[i * records_per_structure];
    }

    // Serialize data to a byte array
    size_t serialized_size = offsets_size + keys_size + records_size;
    uint8_t* serialized_data = malloc(serialized_size);
    if (!serialized_data) {
        perror("Failed to allocate serialized data");
        free(records);
        free(keys);
        free(offsets);
        exit(EXIT_FAILURE);
    }

    memcpy(serialized_data, offsets, offsets_size);
    memcpy(serialized_data + offsets_size, keys, keys_size);
    memcpy(serialized_data + offsets_size + keys_size, records, records_size);

    // Deserialize example (for demonstration purposes)
    long* deserialized_offsets = malloc(offsets_size);
    int* deserialized_keys = malloc(keys_size);
    record* deserialized_records = malloc(records_size);

    if (!deserialized_offsets || !deserialized_keys || !deserialized_records) {
        perror("Failed to allocate memory for deserialization");
        free(serialized_data);
        free(deserialized_offsets);
        free(deserialized_keys);
        free(deserialized_records);
        exit(EXIT_FAILURE);
    }

    memcpy(deserialized_offsets, serialized_data, offsets_size);
    memcpy(deserialized_keys, serialized_data + offsets_size, keys_size);
    memcpy(deserialized_records, serialized_data + offsets_size + keys_size, records_size);

    // Ensure memory is freed
    free(serialized_data);
    free(deserialized_offsets);
    free(deserialized_keys);
    free(deserialized_records);
    free(records);
    free(keys);
    free(offsets);
}

// Unit tests and additional code can be added here to validate performance and correctness.

int main() {
    initialize_data(1024 * 1024, 1000, 500, 10, 1, 100, 42); // Example usage
    return 0;
}
