#define MAX_CONNECTIONS 100

typedef struct {
    int socket_fd;
    char ip_address[INET_ADDRSTRLEN];
    uint16_t port_number;
} Connection;

Connection connection_pool[MAX_CONNECTIONS];
int active_connections = 0;

void serialize_connection(const Connection *conn, unsigned char *buffer) {
    size_t offset = 0;
    memcpy(buffer + offset, &conn->socket_fd, sizeof(conn->socket_fd));
    offset += sizeof(conn->socket_fd);
    memcpy(buffer + offset, conn->ip_address, INET_ADDRSTRLEN);
    offset += INET_ADDRSTRLEN;
    uint16_t port_net = htons(conn->port_number);
    memcpy(buffer + offset, &port_net, sizeof(port_net));
}

int deserialize_connection(const unsigned char *buffer, Connection *conn) {
    size_t offset = 0;
    memcpy(&conn->socket_fd, buffer + offset, sizeof(conn->socket_fd));
    offset += sizeof(conn->socket_fd);
    memcpy(conn->ip_address, buffer + offset, INET_ADDRSTRLEN);
    offset += INET_ADDRSTRLEN;
    uint16_t port_net;
    memcpy(&port_net, buffer + offset, sizeof(port_net));
    conn->port_number = ntohs(port_net);
    return 1; // Success
}

int establish_connection(const char *ip, uint16_t port) {
    if (active_connections >= MAX_CONNECTIONS) return -1;

    int random_index = rand() % active_connections;
    Connection *conn = &connection_pool[random_index];

    conn->socket_fd = /* Create socket logic */;
    strncpy(conn->ip_address, ip, INET_ADDRSTRLEN);
    conn->port_number = port;
    active_connections++;

    return 0; // Success
}

int update_connection(int index, const char *new_ip, uint16_t new_port) {
    if (index < 0 || index >= MAX_CONNECTIONS) return -1;

    Connection *conn = &connection_pool[index];
    strncpy(conn->ip_address, new_ip, INET_ADDRSTRLEN);
    conn->port_number = new_port;
    return 0; // Success
}

int close_connection(int index) {
    if (index < 0 || index >= MAX_CONNECTIONS) return -1;

    Connection *conn = &connection_pool[index];
    /* Close socket logic */
    memset(conn, 0, sizeof(Connection));
    active_connections--;
    return 0; // Success
}

Connection* get_connection(int index) {
    if (index < 0 || index >= MAX_CONNECTIONS) return NULL;
    return &connection_pool[index];
}

void find_max_port() {
    int count = 0;
    printf("Enter number of ports: ");
    scanf("%d", &count);

    int *ports = malloc(count * sizeof(int));
    if (!ports) return;

    printf("Enter port numbers:\n");
    for (int i = 0; i < count; ++i) {
        scanf("%d", &ports[i]);
    }

    int max_port = ports[0];
    for (int i = 1; i < count; ++i) {
        if (ports[i] > max_port) {
            max_port = ports[i];
        }
    }

    printf("Maximum port number: %d\n", max_port);
    free(ports);
}

void handle_network_connections() {
    srand(time(NULL));

    // Example usage
    establish_connection("192.168.1.1", 8080);
    update_connection(0, "192.168.1.2", 9090);
    close_connection(0);

    Connection conn;
    unsigned char buffer[sizeof(Connection) + sizeof(uint16_t)];
    serialize_connection(&connection_pool[0], buffer);

    deserialize_connection(buffer, &conn);
}

int main() {
    handle_network_connections();
    find_max_port();
    return 0;
}
