#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

#define LOG_FILE "memory_log.txt"
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct Record {
    int value;
    long offset;
} Record;

typedef struct Node {
    Record *data;
    size_t capacity;
    size_t count;
    struct Node *next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t max_memory_limit = 1024 * 1024; // 1MB default limit
int min_value = 0, max_value = 100;

void log_message(int level, const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) return;

    time_t now = time(NULL);
    fprintf(log_file, "[%s] Level %d: %s\n", ctime(&now), level, message);
    fclose(log_file);
}

void rotate_logs() {
    // Dummy log rotation for demonstration
    rename(LOG_FILE, "memory_log_old.txt");
}

Node* create_node(size_t capacity) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for node.");
        return NULL;
    }

    node->data = (Record*)malloc(capacity * sizeof(Record));
    if (!node->data) {
        free(node);
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for records.");
        return NULL;
    }

    node->capacity = capacity;
    node->count = 0;
    node->next = NULL;
    return node;
}

void free_node(Node *node) {
    if (node) {
        free(node->data);
        free(node);
    }
}

Record* allocate_records(size_t max_size, size_t *record_count) {
    pthread_mutex_lock(&mutex);

    Node *current = head;
    Record *result = NULL;

    while (current && current->count == current->capacity) {
        current = current->next;
    }

    if (!current) {
        size_t new_capacity = max_size / sizeof(Record);
        if (new_capacity == 0) {
            log_message(LOG_LEVEL_ERROR, "Insufficient memory to allocate any records.");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        Node *new_node = create_node(new_capacity);
        if (!new_node) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        if (head == NULL) {
            head = new_node;
        } else {
            current->next = new_node;
        }
    }

    size_t available_space = max_size - sizeof(Node) * ((current - head) + 1);
    size_t space_per_record = sizeof(Record);

    size_t num_records = available_space / space_per_record;
    if (num_records == 0) {
        log_message(LOG_LEVEL_ERROR, "Insufficient memory for even a single record.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    current->data[current->count] = (Record){.value = rand() % (max_value - min_value + 1) + min_value,
                                             .offset = (long)(rand() % 100000)};
    current->count++;

    result = &current->data[current->count - 1];
    *record_count = current->count;

    pthread_mutex_unlock(&mutex);
    return result;
}

void free_all_records() {
    Node *current = head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free_node(temp);
    }
    head = NULL;
}

int find_largest_integer(int sock) {
    int buffer[1024];
    ssize_t bytes_received = recv(sock, buffer, sizeof(buffer), 0);
    if (bytes_received <= 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to receive data from socket.");
        return -1;
    }

    int *data = buffer;
    int largest = data[0];

    for (int i = 1; i < bytes_received / sizeof(int); ++i) {
        if (data[i] > largest) {
            largest = data[i];
        }
    }

    printf("Largest integer: %d\n", largest);
    return largest;
}

void initialize_random_generator() {
    srand((unsigned int)time(NULL));
}

int main() {
    initialize_random_generator();
    size_t record_count;

    Record *records = allocate_records(max_memory_limit, &record_count);
    if (records) {
        log_message(LOG_LEVEL_INFO, "Records allocated successfully.");
        printf("Allocated %zu records.\n", record_count);

        free_all_records();

        // Example network socket setup for finding largest integer
        int sock;
        struct sockaddr_in server_address;

        sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock < 0) {
            log_message(LOG_LEVEL_ERROR, "Socket creation failed.");
            return -1;
        }

        memset(&server_address, '0', sizeof(server_address));
        server_address.sin_family = AF_INET;
        server_address.sin_port = htons(8080);

        if(inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr) <= 0) {
            log_message(LOG_LEVEL_ERROR, "Invalid address/ Address not supported.");
            return -1;
        }

        if (connect(sock, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
            log_message(LOG_LEVEL_ERROR, "Connection Failed.");
            return -1;
        }

        find_largest_integer(sock);
    } else {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate records.");
    }

    close(sock);
    return 0;
}
