#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    unsigned int id;
    char *message;
} Event;

typedef struct {
    size_t capacity;
    size_t size;
    Event *events;
} EventArray;

// Helper function to generate a random string
char* generate_random_string(size_t length, const char *charset) {
    if (length == 0 || charset == NULL)
        return NULL;

    char *randomString = malloc(length + 1);
    if (!randomString)
        return NULL;

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < length; i++) {
        size_t index = rand() % strlen(charset);
        randomString[i] = charset[index];
    }
    randomString[length] = '\0';

    return randomString;
}

// Function to initialize an EventArray
EventArray* init_event_array(size_t initial_capacity) {
    EventArray *array = malloc(sizeof(EventArray));
    if (!array)
        return NULL;

    array->capacity = initial_capacity;
    array->size = 0;
    array->events = malloc(initial_capacity * sizeof(Event));
    if (!array->events) {
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i)
        array->events[i].message = NULL;

    return array;
}

// Function to add an event
int add_event(EventArray *array, long timestamp, unsigned int id_range, const char *charset) {
    if (!array || array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        Event *new_events = realloc(array->events, new_capacity * sizeof(Event));
        if (!new_events)
            return -1;

        for (size_t i = array->capacity; i < new_capacity; ++i)
            new_events[i].message = NULL;

        array->events = new_events;
        array->capacity = new_capacity;
    }

    Event *event = &array->events[array->size++];
    event->timestamp = timestamp;
    event->id = rand() % id_range;
    size_t message_length = 10; // Example length
    char *message = generate_random_string(message_length, charset);
    if (!message) {
        return -1;
    }
    event->message = message;

    return 0;
}

// Function to serialize events into a byte array
size_t serialize_events(EventArray *array, uint8_t **output) {
    size_t total_size = sizeof(size_t); // Store the number of events first

    for (size_t i = 0; i < array->size; ++i) {
        total_size += sizeof(long);
        total_size += sizeof(unsigned int);
        total_size += strlen(array->events[i].message) + 1;
    }

    *output = malloc(total_size);
    if (!*output)
        return 0;

    uint8_t *ptr = *output;
    memcpy(ptr, &array->size, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < array->size; ++i) {
        long timestamp = htobe64(array->events[i].timestamp);
        memcpy(ptr, &timestamp, sizeof(long));
        ptr += sizeof(long);

        unsigned int id = be32toh(array->events[i].id); // Convert to host byte order
        memcpy(ptr, &id, sizeof(unsigned int));
        ptr += sizeof(unsigned int);

        size_t message_length = strlen(array->events[i].message) + 1;
        memcpy(ptr, array->events[i].message, message_length);
        ptr += message_length;
    }

    return total_size;
}

// Function to deserialize events from a byte array
int deserialize_events(uint8_t *input, EventArray *array) {
    size_t num_events;
    memcpy(&num_events, input, sizeof(size_t));
    input += sizeof(size_t);

    if (add_event(array, 0, 1, "") == -1 || array->size != num_events)
        return -1;

    for (size_t i = 0; i < num_events; ++i) {
        long timestamp;
        memcpy(&timestamp, input, sizeof(long));
        input += sizeof(long);
        timestamp = be64toh(timestamp);

        unsigned int id;
        memcpy(&id, input, sizeof(unsigned int));
        input += sizeof(unsigned_int);
        id = htobe32(id);

        char *message_end = (char *)input + strlen((const char *)input) + 1;
        char *message = malloc(input - (uint8_t *)message_end);
        if (!message)
            return -1;

        memcpy(message, input, message_end - (char *)input);
        add_event(array, timestamp, 0, "");
        array->events[array->size - 1].id = id;
        free(array->events[array->size - 1].message);
        array->events[array->size - 1].message = message;

        input = message_end;
    }

    return 0;
}

// Function to free the EventArray
void free_event_array(EventArray *array) {
    if (!array)
        return;

    for (size_t i = 0; i < array->size; ++i) {
        free(array->events[i].message);
    }
    free(array->events);
    free(array);
}

// Example of a logging framework
typedef struct Logger Logger;

struct Logger {
    void (*log)(Logger *self, const char *format, ...);
};

void console_log(Logger *self, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

Logger* create_logger(void (*log_func)(Logger *, const char *, ...)) {
    Logger *logger = malloc(sizeof(Logger));
    if (!logger)
        return NULL;

    logger->log = log_func;
    return logger;
}

void free_logger(Logger *logger) {
    if (!logger)
        return;

    free(logger);
}

// Example usage
int main() {
    EventArray *events = init_event_array(10);
    if (!events) {
        fprintf(stderr, "Failed to initialize event array\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 20; ++i) {
