        }
    }

    uint8_t *serialized_data;
    size_t serialized_size = serialize_events(events, &serialized_data);
    if (!serialized_data) {
        fprintf(stderr, "Serialization failed\n");
        free_event_array(events);
        return EXIT_FAILURE;
    }

    EventArray *deserialized_events = init_event_array(10);
    if (!deserialized_events || deserialize_events(serialized_data, deserialized_events) == -1) {
        fprintf(stderr, "Deserialization failed\n");
        free(serialized_data);
        free_event_array(events);
        free_event_array(deserialized_events);
        return EXIT_FAILURE;
    }

    free(serialized_data);

    Logger *logger = create_logger(console_log);
    if (!logger) {
        fprintf(stderr, "Failed to create logger\n");
        free_event_array(events);
        free_event_array(deserialized_events);
        return EXIT_FAILURE;
    }

    logger->log(logger, "Logging example message\n");

    free_logger(logger);
    free_event_array(events);
    free_event_array(deserialized_events);

    return EXIT_SUCCESS;
}
