#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_MEMORY_SIZE 1024 // Define maximum memory size

// Assume these are defined in your project
extern void serializeToByteArray(const char *html, unsigned char **byteArray, size_t *length);
extern bool updateServiceLayer(unsigned char *data, size_t length);
extern void addToCache(int componentID, int elementID, const char *content);
extern bool getFromCache(int componentID, int elementID, char **content);
extern void syncWithRemoteServer();
extern void logError(const char *message);

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int componentID;
    int elementID;
    const char *htmlContent;
} UpdateRequest;

bool updateWebComponent(UpdateRequest request) {
    unsigned char *byteArray = NULL;
    size_t length = 0;
    bool cacheHit = false;
    bool success = false;
    char *cachedContent = NULL;

    // Lock for thread safety
    pthread_mutex_lock(&lock);

    // Check cache first
    if (getFromCache(request.componentID, request.elementID, &cachedContent)) {
        // If content is cached and matches, avoid update
        if (strcmp(cachedContent, request.htmlContent) == 0) {
            success = true;
            goto end;
        }
        cacheHit = true;
    }

    // Serialize HTML to byte array with error checking
    if (!serializeToByteArray(request.htmlContent, &byteArray, &length)) {
        logError("Serialization failed");
        pthread_mutex_unlock(&lock);
        return false;
    }

    // Check memory allocation size
    if (length > MAX_MEMORY_SIZE) {
        free(byteArray);
        logError("Memory allocation exceeds limit");
        pthread_mutex_unlock(&lock);
        return false;
    }

    // Update service layer and handle errors
    success = updateServiceLayer(byteArray, length);
    if (!success) {
        logError("Service layer update failed");
    } else {
        addToCache(request.componentID, request.elementID, request.htmlContent); // Add to cache after successful update
    }

    free(byteArray);

end:
    pthread_mutex_unlock(&lock);

    if (success && !cacheHit) {
        syncWithRemoteServer(); // Sync with remote server only on successful fresh updates
    }

    return success; // Indicate whether the page should be refreshed based on success and cache hit
}
