#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>
#include <endian.h>

#define MAX_MEMORY_USAGE 1048576 // Example max memory usage in bytes
#define MESSAGE_COUNT 10000

typedef struct {
    char *buffer;
    time_t timestamp;
    bool acknowledged;
    void *custom_header;
} Message;

typedef struct {
    Message *messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageCollection;

void log_event(const char *event) {
    printf("LOG: %s\n", event);
}

MessageCollection* create_message_collection(size_t initial_capacity) {
    MessageCollection *collection = (MessageCollection *)malloc(sizeof(MessageCollection));
    if (!collection) {
        log_event("Failed to allocate memory for message collection.");
        return NULL;
    }
    collection->messages = (Message *)calloc(initial_capacity, sizeof(Message));
    if (!collection->messages) {
        free(collection);
        log_event("Failed to allocate memory for messages.");
        return NULL;
    }
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    log_event("Message collection created successfully.");
    return collection;
}

int add_message(MessageCollection *collection, const char *message, size_t length, void *header) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Message collection capacity reached.");
        return -1;
    }

    Message *msg = &collection->messages[collection->count];
    size_t total_size = sizeof(Message) + length;
    if (total_size > MAX_MEMORY_USAGE / MESSAGE_COUNT) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Memory limit exceeded.");
        return -1;
    }

    msg->buffer = (char *)malloc(length);
    if (!msg->buffer) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Failed to allocate memory for message buffer.");
        return -1;
    }
    memcpy(msg->buffer, message, length);

    time_t now = time(NULL);
    msg->timestamp = now + rand() % 3600; // Random timestamp within the next hour

    msg->acknowledged = false;
    msg->custom_header = header;

    collection->count++;
    pthread_mutex_unlock(&collection->lock);
    log_event("Message added successfully.");
    return 0;
}

void* serialize_message(const Message *msg) {
    size_t buffer_size = sizeof(Message) + strlen(msg->buffer) + 1; // +1 for null terminator
    void *serialized_data = malloc(buffer_size);
    if (!serialized_data) {
        log_event("Failed to allocate memory for serialization.");
        return NULL;
    }

    char *data_ptr = (char *)serialized_data;
    memcpy(data_ptr, msg, sizeof(Message));
    data_ptr += sizeof(Message);

    uint32_t length_net = htobe32(strlen(msg->buffer));
    memcpy(data_ptr, &length_net, sizeof(uint32_t));
    data_ptr += sizeof(uint32_t);

    strcpy(data_ptr, msg->buffer);
    log_event("Message serialized successfully.");
    return serialized_data;
}

Message* deserialize_message(const void *serialized_data) {
    const char *data_ptr = (const char *)serialized_data;

    Message *msg = malloc(sizeof(Message));
    if (!msg) {
        log_event("Failed to allocate memory for deserialization.");
        return NULL;
    }

    memcpy(msg, data_ptr, sizeof(Message));
    data_ptr += sizeof(Message);

    uint32_t length_net;
    memcpy(&length_net, data_ptr, sizeof(uint32_t));
    data_ptr += sizeof(uint32_t);
    uint32_t length = be32toh(length_net);

    msg->buffer = strdup(data_ptr);
    if (!msg->buffer) {
        free(msg);
        log_event("Failed to allocate memory for deserialized message buffer.");
        return NULL;
    }

    log_event("Message deserialized successfully.");
    return msg;
}

void destroy_message_collection(MessageCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->messages[i].buffer);
        // Free custom header if necessary
    }
    free(collection->messages);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
    log_event("Message collection destroyed.");
}

void read_messages_from_file(const char *filename, MessageCollection *collection) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_event("Failed to open file for reading messages.");
        return;
    }

    pthread_mutex_lock(&collection->lock);

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        size_t length = strlen(buffer);
        if (buffer[length - 1] == '\n') {
            buffer[--length] = '\0';
        }

        // Simulate custom header
        void *header = NULL;

        add_message(collection, buffer, length, header);
    }

    pthread_mutex_unlock(&collection->lock);

    fclose(file);
    log_event("Messages read from file successfully.");
}

void update_acknowledgments(MessageCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        // Simulate external criteria
        collection->messages[i].acknowledged = true;
    }

    pthread_mutex_unlock(&collection->lock);
    log_event("Acknowledgments updated successfully.");
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    MessageCollection *collection = create_message_collection(100);
    if (!collection) return 1;

    read_messages_from_file("messages.txt", collection);

    update_acknowledgments(collection);

    for (size_t i = 0; i < collection->count; ++i) {
        void *serialized_data = serialize_message(&collection->messages[i]);
        Message *deserialized_msg = deserialize_message(serialized_data);
        free(serialized_data);
        free(deserialized_msg->buffer);
        free(deserialized_msg);
    }

    destroy_message_collection(collection);

    return 0;
}
```

