#include <stdio.h>
#include <stdlib.h>
import <stdint.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    long value;
    char* identifier;
} record;

// Logging function for demonstration purposes
void log_message(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}

// Utility to handle endianness
uint64_t htonll(uint64_t hostlonglong) {
    static const int num = 1;
    if (*(char *)&num == 0) { // Big-endian
        return hostlonglong;
    } else { // Little-endian
        uint32_t high = (hostlonglong >> 32) & 0xFFFFFFFF;
        uint32_t low = hostlonglong & 0xFFFFFFFF;
        return ((uint64_t)htonl(low) << 32) | htonl(high);
    }
}

// Helper function to serialize a record into bytes
void serialize_record(const record *rec, unsigned char *buffer) {
    memcpy(buffer, &(rec->id), sizeof(rec->id));
    uint64_t value_be = htonll((uint64_t)rec->value); // Convert long to big-endian byte order
    memcpy(buffer + sizeof(int), &value_be, sizeof(rec->value));
}

// Helper function to deserialize bytes into a record
void deserialize_record(const unsigned char *buffer, record *rec) {
    memcpy(&(rec->id), buffer, sizeof(rec->id));
    uint64_t value_le;
    memcpy(&value_le, buffer + sizeof(int), sizeof(rec->value));
    rec->value = (long)htonll(value_le); // Convert back to host byte order
}

// Function to initialize records with given seed and within memory limit
record* init_records(size_t max_memory, unsigned int seed, size_t record_count, 
                     const char *log_level) {
    if (max_memory < sizeof(record) * record_count + record_count * 10) { // rough estimation for identifier strings
        log_message(log_level, "Not enough memory available");
        return NULL;
    }

    srand(seed);
    record* records = malloc(max_memory);

    if (!records) {
        log_message(log_level, "Memory allocation failed");
        return NULL;
    }

    size_t offset = 0;
    for (size_t i = 0; i < record_count; ++i) {
        record *rec = (record *)((char *)records + offset);
        rec->id = rand() % 1000;
        rec->value = rand() % 10000000L;

        char id_str[11];
        snprintf(id_str, sizeof(id_str), "ID%zu", i);

        rec->identifier = malloc(10 * sizeof(char));
        if (!rec->identifier) {
            log_message(log_level, "Failed to allocate identifier string");
            free(records);
            return NULL;
        }
        strcpy(rec->identifier, id_str);

        offset += sizeof(*rec) + 10; // Adjust for allocated identifier
    }

    log_message(log_level, "Records initialized successfully");

    return records;
}

// Function to find the largest integer from standard input
void print_largest_integer() {
    int number, max_number = INT_MIN;

    printf("Enter integers (end with non-integer):\n");
    while (scanf("%d", &number) == 1) {
        if (number > max_number) {
            max_number = number;
        }
    }

    if (max_number != INT_MIN) {
        printf("The largest integer is: %d\n", max_number);
    } else {
        printf("No valid integers were entered.\n");
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments for memory and seed
    size_t max_memory = 1024; // Default to 1KB
    unsigned int seed = time(NULL); // Default random seed

    if (argc > 1) {
        max_memory = strtoul(argv[1], NULL, 10);
    }
    if (argc > 2) {
        seed = strtoul(argv[2], NULL, 10);
    }

    const char *log_level = "INFO";

    record* records = init_records(max_memory, seed, 5, log_level);

    if (!records) {
        return EXIT_FAILURE;
    }

    // Example of serialization
    unsigned char buffer[sizeof(record)];
    for (size_t i = 0; i < max_memory / sizeof(record); ++i) {
        serialize_record((record *)((char *)records + i * sizeof(record)), buffer);
    }

    // Free allocated memory
    free(records);

    // Demonstrate input handling and largest integer finding
    print_largest_integer();

    return EXIT_SUCCESS;
}
