```c
// message_manager.c

#include "message_manager.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

MessageCollection* create_collection(size_t initial_capacity, size_t max_memory) {
    MessageCollection *collection = malloc(sizeof(MessageCollection));
    if (!collection) return NULL;

    collection->messages = calloc(initial_capacity, sizeof(Message *));
    if (!collection->messages) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->max_memory = max_memory;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

bool add_message(MessageCollection *collection, const char *text, time_t timestamp, bool ack) {
    pthread_mutex_lock(&collection->lock);

    size_t text_length = strlen(text) + 1; // including null terminator
    size_t message_size = sizeof(Message) + text_length;

    if (collection->count >= collection->capacity || 
        collection->max_memory - (sizeof(Message *) * collection->count) < message_size) {
        pthread_mutex_unlock(&collection->lock);
        return false;
    }

    Message *new_message = malloc(message_size);
    if (!new_message) {
        pthread_mutex_unlock(&collection->lock);
        return false;
    }

    new_message->text = (char *)(new_message + 1);
    strcpy(new_message->text, text);
    new_message->timestamp = timestamp;
    new_message->ack = ack;

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Message **new_messages = realloc(collection->messages, new_capacity * sizeof(Message *));
        if (!new_messages) {
            free(new_message);
            pthread_mutex_unlock(&collection->lock);
            return false;
        }
        collection->messages = new_messages;
        collection->capacity = new_capacity;
    }

    collection->messages[collection->count++] = new_message;

    pthread_mutex_unlock(&collection->lock);
    return true;
}

bool remove_message(MessageCollection *collection, int index) {
    pthread_mutex_lock(&collection->lock);

    if (index < 0 || index >= collection->count) {
        pthread_mutex_unlock(&collection->lock);
        return false;
    }

    free(collection->messages[index]);
    for (size_t i = index; i < collection->count - 1; ++i) {
        collection->messages[i] = collection->messages[i + 1];
    }

    --collection->count;

    pthread_mutex_unlock(&collection->lock);
    return true;
}

void free_collection(MessageCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->messages[i]);
    }

    free(collection->messages);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
