// serialization.c

#include "serialization.h"
#include <stdlib.h>
#include <string.h>

size_t serialize_message(const Message *message, uint8_t **buffer) {
    if (!message || !buffer) return 0;

    size_t text_length = strlen(message->text) + 1;
    size_t total_size = sizeof(time_t) + sizeof(bool) + sizeof(size_t) + text_length;

    *buffer = malloc(total_size);
    if (!*buffer) return 0;

    uint8_t *ptr = *buffer;

    memcpy(ptr, &message->timestamp, sizeof(time_t));
    ptr += sizeof(time_t);

    memcpy(ptr, &message->ack, sizeof(bool));
    ptr += sizeof(bool);

    size_t stored_text_length = text_length;
    memcpy(ptr, &stored_text_length, sizeof(size_t));
    ptr += sizeof(size_t);

    memcpy(ptr, message->text, text_length);

    return total_size;
}

bool deserialize_message(const uint8_t *buffer, size_t buffer_size, Message *message) {
    if (!buffer || !message || buffer_size < (sizeof(time_t) + sizeof(bool) + sizeof(size_t))) return false;

    const uint8_t *ptr = buffer;

    memcpy(&message->timestamp, ptr, sizeof(time_t));
    ptr += sizeof(time_t);

    memcpy(&message->ack, ptr, sizeof(bool));
    ptr += sizeof(bool);

    size_t text_length;
    memcpy(&text_length, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if (buffer_size < (ptr - buffer + text_length)) return false;

    message->text = malloc(text_length);
    if (!message->text) return false;

    memcpy(message->text, ptr, text_length);

    return true;
}
