void process_file(const char *filename, MessageCollection *collection) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Assuming format: text|timestamp|ack
        char *token = strtok(line, "|");
        char *text = token;

        token = strtok(NULL, "|");
        time_t timestamp = atol(token);

        token = strtok(NULL, "|");
        bool ack = atoi(token) != 0;

        add_message(collection, text, timestamp, ack);
    }

    fclose(file);
}
