uint32_t calculate_checksum(const uint8_t *data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

void serialize_data(const DataCollection *collection, uint8_t **buffer, size_t *length) {
    pthread_mutex_lock(&collection->lock);

    size_t total_size = sizeof(uint32_t) + (sizeof(int) + sizeof(long) + 16) * collection->count;
    uint8_t *buf = malloc(total_size);
    if (!buf) {
        perror("Serialization failed");
        exit(EXIT_FAILURE);
    }

    uint32_t checksum = calculate_checksum(buf, total_size);
    memcpy(buf, &checksum, CHECKSUM_SIZE);

    size_t offset = CHECKSUM_SIZE;
    for (size_t i = 0; i < collection->count; ++i) {
        memcpy(buf + offset, &collection->records[i].value, sizeof(int));
        offset += sizeof(int);
        memcpy(buf + offset, &collection->records[i].offset, sizeof(long));
        offset += sizeof(long);
        memcpy(buf + offset, collection->records[i].id, 16);
        offset += 16;
    }

    *buffer = buf;
    *length = total_size;

    pthread_mutex_unlock(&collection->lock);
}

int deserialize_data(DataCollection *collection, const uint8_t *buffer, size_t length) {
    pthread_mutex_lock(&collection->lock);

    if (length < CHECKSUM_SIZE) {
        log_event("Deserialization failed: buffer too short");
        return -1;
    }

    uint32_t checksum = 0;
    memcpy(&checksum, buffer, CHECKSUM_SIZE);

    if (calculate_checksum(buffer + CHECKSUM_SIZE, length - CHECKSUM_SIZE) != checksum) {
        log_event("Checksum mismatch during deserialization");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    size_t record_count = (length - CHECKSUM_SIZE) / (sizeof(int) + sizeof(long) + 16);
    if (record_count > MAX_RECORDS || record_count * (sizeof(int) + sizeof(long) + 16) != length - CHECKSUM_SIZE) {
        log_event("Deserialization failed: invalid data size");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->count = record_count;
    memcpy(collection->records, buffer + CHECKSUM_SIZE, record_count * (sizeof(int) + sizeof(long) + 16));

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

