    uLongf dest_len = compressBound(input_length);
    *compressed_data = malloc(dest_len);

    if (compress2(*compressed_data, &dest_len, input, input_length, compression_level) != Z_OK) {
        free(*compressed_data);
        log_event("Compression failed");
        exit(EXIT_FAILURE);
    }

    *compressed_length = dest_len;
}

void decompress_data(const uint8_t *input, size_t input_length, uint8_t **decompressed_data, size_t *decompressed_length) {
    uLongf dest_len = input_length; // Initial guess
    while (1) {
        *decompressed_data = malloc(dest_len);
        if (uncompress(*decompressed_data, &dest_len, input, input_length) == Z_OK) {
            break;
        }
        free(*decompressed_data);
        dest_len *= 2;
    }

    *decompressed_length = dest_len;
}

