    size_t str_length = 10;
    int min_val = 0;
    int max_val = 100;

    record* records = initialize_records(max_size, str_length, min_val, max_val);
    if (!records) return EXIT_FAILURE;

    size_t count;
    uint8_t* serialized_data;
    size_t serialized_size = serialize_records(records, 10, "binary", &serialized_data);

    record* deserialized_records;
    size_t deserialized_count;
    deserialized_records = deserialize_records(serialized_data, serialized_size, &deserialized_count);

    free(serialized_data);
    free_records(deserialized_records, deserialized_count);

    printf("Largest integer: %d\n", find_largest_integer());

    return EXIT_SUCCESS;
}

// Function implementations
record* initialize_records(size_t max_size, size_t str_length, int min_val, int max_val) {
    srand(time(NULL));

    record* records = NULL;
    size_t total_size = 0;
    size_t count = 0;

    while (total_size < max_size) {
        record* new_record = malloc(sizeof(record));
        if (!new_record) break;

        new_record->value = min_val + rand() % ((max_val - min_val) + 1);
        new_record->offset = (long)rand();
        new_record->random_string = generate_random_string(str_length, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");

        size_t record_size = sizeof(record) + str_length;
        if (total_size + record_size > max_size) {
            free(new_record);
            break;
        }

        total_size += record_size;
        count++;

        new_record->next = records;
        records = new_record;
    }

    return records ? records : NULL;
}

void free_records(record* records, size_t count) {
    while (records && count > 0) {
        record* temp = records;
        records = records->next;
        free(temp->random_string);
        free(temp);
        count--;
    }
}

size_t serialize_records(record* records, size_t count, const char* format, uint8_t** output) {
    // Example serialization for binary format
    if (strcmp(format, "binary") == 0) {
        *output = malloc(count * sizeof(record));
        if (!*output) return 0;

        record* current = records;
        size_t i = 0;
        while (current && i < count) {
            memcpy(*output + i * sizeof(record), current, sizeof(record));

            uint8_t* str_ptr = ((uint8_t*)*output) + i * sizeof(record);
            memcpy(str_ptr, current->random_string, strlen(current->random_string));
            str_ptr[strlen(current->random_string)] = '\0';

            current = current->next;
            i++;
        }
    }

    return count * (sizeof(record) + 10); // Example size
}

record* deserialize_records(uint8_t* input, size_t input_size, size_t* record_count) {
    *record_count = input_size / (sizeof(record) + 10);
    record* records = NULL;

    for (size_t i = 0; i < *record_count; ++i) {
        record* new_record = malloc(sizeof(record));
        if (!new_record) break;

        memcpy(new_record, input + i * (sizeof(record) + 10), sizeof(record));

        uint8_t* str_ptr = ((uint8_t*)input) + i * (sizeof(record) + 10);
        new_record->random_string = malloc(11); // 10 chars + null terminator
        if (!new_record->random_string) {
            free(new_record);
            break;
        }
        memcpy(new_record->random_string, str_ptr, 10);
        new_record->random_string[10] = '\0';

        new_record->next = records;
        records = new_record;
    }

    return records ? records : NULL;
}

