void findMax(int *arr, int n) {
    if (n == 0) {
        printf("No valid integers provided.\n");
        return;
    }
    int max = arr[0];
    for (int i = 1; i < n; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
