        printf("Invalid input size.\n");
        return;
    }

    int *arr = malloc(n * sizeof(int));
    if (!arr) {
        printf("Memory allocation failed.\n");
        return;
    }

    int validCount = 0;
    for (int i = 0; i < n && scanf("%d", &num) == 1; ++i) {
        if (num >= INT_MIN && num <= INT_MAX) {
            arr[validCount++] = num;
        } else {
            printf("Invalid integer: %d. It must be a 32-bit signed integer.\n", num);
        }
    }

    sortDesc(arr, validCount);
    findMax(arr, validCount);

    free(arr);
}

