['Below is an implementation of a C library that manages dynamic collections of semaphores with considerations for concurrency, robustness, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>
#include <errno.h>

#define MAX_THREADS 100
#define LOG_BUFFER_SIZE 256

typedef struct SemaphoreManager {
    sem_t *semaphores;
    size_t count;
    pthread_mutex_t mutex;
    int initialized;
} SemaphoreManager;

SemaphoreManager *create_semaphore_manager(size_t initial_count) {
    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    if (!manager) return NULL;

    manager->semaphores = calloc(initial_count, sizeof(sem_t));
    if (!manager->semaphores) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    manager->count = initial_count;
    manager->initialized = 1;

    // Initialize semaphores
    for (size_t i = 0; i < initial_count; ++i) {
        if (sem_init(&(manager->semaphores[i]), 0, 1) != 0) { 
            destroy_semaphore_manager(manager);
            return NULL;
        }
    }

    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    if (!manager || !manager->initialized) return;

    for (size_t i = 0; i < manager->count; ++i) {
        sem_destroy(&(manager->semaphores[i]));
    }

    free(manager->semaphores);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int acquire_semaphore(SemaphoreManager *manager, size_t index) {
    if (!manager || !manager->initialized || index >= manager->count)
        return -1;

    int result = sem_wait(&(manager->semaphores[index]));
    if (result != 0 && errno != EINTR) 
        perror("Semaphore acquisition failed");

    return result;
}

int release_semaphore(SemaphoreManager *manager, size_t index) {
    if (!manager || !manager->initialized || index >= manager->count)
        return -1;

    int result = sem_post(&(manager->semaphores[index]));
    if (result != 0 && errno != EINTR)
        perror("Semaphore release failed");

    return result;
}

void log_message(const char *message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

int create_semaphore(SemaphoreManager *manager, int initial_value) {
    if (!manager || !manager->initialized)
        return -1;

    pthread_mutex_lock(&(manager->mutex));

    size_t new_count = manager->count + 1;
    sem_t *new_semaphores = realloc(manager->semaphores, new_count * sizeof(sem_t));
    if (!new_semaphores) {
        log_message("Failed to allocate memory for semaphore");
        pthread_mutex_unlock(&(manager->mutex));
        return -1;
    }

    manager->semaphores = new_semaphores;

    int result = sem_init(&(manager->semaphores[manager->count]), 0, initial_value);
    if (result != 0) {
        log_message("Failed to initialize semaphore");
        pthread_mutex_unlock(&(manager->mutex));
        return -1;
    }

    manager->count++;
    pthread_mutex_unlock(&(manager->mutex));

    log_message("Semaphore created successfully");

    return 0;
}

int delete_semaphore(SemaphoreManager *manager, size_t index) {
    if (!manager || !manager->initialized || index >= manager->count)
        return -1;

    pthread_mutex_lock(&(manager->mutex));

    int result = sem_destroy(&(manager->semaphores[index]));
    if (result != 0 && errno != EINVAL) 
        log_message("Failed to destroy semaphore");

    memmove(&manager->semaphores[index], &manager->semaphores[index + 1],
            (manager->count - index - 1) * sizeof(sem_t));
    manager->count--;

    pthread_mutex_unlock(&(manager->mutex));

    return result;
}

// Main thread pool and configuration management integration would be here.
```

### Key Points:
- The library manages a dynamic array of semaphores within a `SemaphoreManager`.
- Provides thread-safe operations for creating, deleting, acquiring, and releasing semaphores.
- Uses mutexes to ensure safe concurrent access to the semaphore collection.
- Logs messages using a simple logging function that locks a mutex during output to prevent interleaved logs.
- Handles memory allocation failures gracefully by cleaning up resources appropriately.
- Error checking is included in semaphore operations to handle system limits or invalid parameters.

This implementation serves as a foundational example; integration with a thread pool and configuration management system would involve additional logic not covered here.']

