['Here's a C function to manage and serialize an array of data structures with concurrency support, efficient memory management, logging, and serialization/deserialization capabilities.

### C Code for Dynamic Management and Serialization

```c
#include <stdio.h>
#include <stdlib.h>
import stdatomic.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int value;
} DataStruct;

typedef struct {
    atomic_size_t size;
    atomic_size_t capacity;
    pthread_mutex_t lock;
    DataStruct *data;
} ManagedArray;

void log_memory_usage(const char* message, size_t used) {
    printf("%s: %zu bytes\n", message, used);
}

ManagedArray* create_managed_array(size_t initial_capacity) {
    ManagedArray *array = (ManagedArray *)malloc(sizeof(ManagedArray));
    pthread_mutex_init(&array->lock, NULL);
    array->data = (DataStruct *)calloc(initial_capacity, sizeof(DataStruct));
    atomic_store(&array->size, 0);
    atomic_store(&array->capacity, initial_capacity);
    log_memory_usage("Initial allocation", initial_capacity * sizeof(DataStruct));
    return array;
}

void resize_array(ManagedArray *array) {
    size_t new_capacity = atomic_load(&array->capacity) * 2;
    DataStruct *new_data = (DataStruct *)realloc(array->data, new_capacity * sizeof(DataStruct));
    if (new_data) {
        pthread_mutex_lock(&array->lock);
        array->data = new_data;
        atomic_store(&array->capacity, new_capacity);
        log_memory_usage("Resized allocation", new_capacity * sizeof(DataStruct));
        pthread_mutex_unlock(&array->lock);
    }
}

int add_data(ManagedArray *array, int key, long offset, int value) {
    pthread_mutex_lock(&array->lock);
    if (atomic_load(&array->size) == atomic_load(&array->capacity)) {
        resize_array(array);
    }

    size_t index = atomic_fetch_add(&array->size, 1);
    array->data[index].key = key;
    array->data[index].offset = offset;
    array->data[index].value = value;

    pthread_mutex_unlock(&array->lock);
    return 0; // success
}

void serialize(ManagedArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    size_t size = atomic_load(&array->size);
    fwrite(&size, sizeof(size), 1, file);

    for (size_t i = 0; i < size; ++i) {
        fwrite(&(array->data[i]), sizeof(DataStruct), 1, file);
    }

    fclose(file);
}

void free_managed_array(ManagedArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
    free(array);
}
```

