['Below are two code snippets based on your requirements: one for the C function to manage dynamic memory allocation with thread safety, and another for the Java method to safely load a state object from a file.

### C Function for Dynamic Memory Allocation

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <limits.h>

#define MAX_MEMORY_SIZE 1024 * 1024  // Example max size limit
#define RECORD_COUNT 1000            // Number of records to initialize

typedef struct {
    int value;
    long offset;
} Record;

typedef struct MemoryPool {
    void* pool;          // Memory pool pointer
    size_t total_size;   // Total pool size
    size_t used_size;    // Used memory in the pool
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size, size_t max_size) {
    if (initial_size > max_size || max_size == 0) return NULL;

    MemoryPool* mem_pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mem_pool) return NULL;

    pthread_mutex_init(&mem_pool->lock, NULL);
    mem_pool->pool = malloc(max_size);
    mem_pool->total_size = max_size;
    mem_pool->used_size = 0;

    if (!mem_pool->pool) {
        free(mem_pool);
        return NULL;
    }

    // Initialize pool with initial size
    void* initial_block = realloc(mem_pool->pool, initial_size);
    if (!initial_block) {
        free(mem_pool->pool);
        free(mem_pool);
        return NULL;
    }

    mem_pool->used_size = initial_size;
    return mem_pool;
}

void* memory_pool_alloc(MemoryPool* mem_pool, size_t size) {
    pthread_mutex_lock(&mem_pool->lock);

    if (mem_pool->used_size + size > mem_pool->total_size) {
        pthread_mutex_unlock(&mem_pool->lock);
        return NULL; // Exceeded pool capacity
    }

    void* block = ((char*)mem_pool->pool) + mem_pool->used_size;
    mem_pool->used_size += size;

    pthread_mutex_unlock(&mem_pool->lock);
    return block;
}

void free_memory_pool(MemoryPool* mem_pool) {
    if (mem_pool) {
        pthread_mutex_destroy(&mem_pool->lock);
        free(mem_pool->pool);
        free(mem_pool);
    }
}

int initialize_data_structures(long* offsets, int* keys, Record* records, MemoryPool* mem_pool, int range_min, int range_max) {
    if (!offsets || !keys || !records || !mem_pool)
        return -1;

    size_t offset_size = RECORD_COUNT * sizeof(long);
    size_t key_size = RECORD_COUNT * sizeof(int);

    offsets = (long*)memory_pool_alloc(mem_pool, offset_size);
    keys = (int*)memory_pool_alloc(mem_pool, key_size);
    records = (Record*)memory_pool_alloc(mem_pool, RECORD_COUNT * sizeof(Record));

    if (!offsets || !keys || !records)
        return -1; // Allocation failed

    for (int i = 0; i < RECORD_COUNT; ++i) {
        offsets[i] = (long)i;
        keys[i] = i;

        int random_value = range_min + rand() % (range_max - range_min + 1);
        if ((unsigned)random_value > INT_MAX || (unsigned)random_value < INT_MIN)
            return -1; // Out of valid range

        records[i].value = random_value;
        records[i].offset = offsets[i];
    }

    return 0;
}
```

