['Here's a C implementation of a dynamic record storage system designed according to your specifications:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} DynamicRecord;

#define MAX_RECORDS 10000000

DynamicRecord *records = NULL;
size_t record_count = 0;
pthread_mutex_t lock;

unsigned long calculate_checksum(DynamicRecord *data, size_t count) {
    unsigned long checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += data[i].offset + data[i].key + data[i].record.value;
    }
    return checksum;
}

void free_records() {
    if (records != NULL) {
        free(records);
        records = NULL;
    }
    record_count = 0;
}

int allocate_records(size_t count) {
    pthread_mutex_lock(&lock);

    // Free previously allocated memory
    free_records();

    records = malloc(count * sizeof(DynamicRecord));
    if (!records) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    record_count = count;

    // Initialize records with default values
    for (size_t i = 0; i < count; ++i) {
        records[i].offset = 0;
        records[i].key = 0;
        records[i].record.value = 0;
    }

    unsigned long checksum = calculate_checksum(records, record_count);
    printf("Initial Checksum: %lu\n", checksum);

    pthread_mutex_unlock(&lock);
    return 0;
}

void modify_record(int index, long offset, int key, int value) {
    if (index < 0 || index >= record_count) {
        fprintf(stderr, "Invalid record index\n");
        return;
    }

    pthread_mutex_lock(&lock);

    records[index].offset = offset;
    records[index].key = key;
    records[index].record.value = value;

    unsigned long checksum = calculate_checksum(records, record_count);
    printf("Updated Checksum: %lu\n", checksum);

    pthread_mutex_unlock(&lock);
}

void read_and_write_to_file(const char *filename) {
    FILE *file = fopen(filename, "wb+");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    size_t written = fwrite(records, sizeof(DynamicRecord), record_count, file);
    if (written != record_count) {
        perror("Failed to write records to file");
    } else {
        printf("Successfully wrote %zu records to %s\n", written, filename);
    }

    rewind(file); // Reset file position for reading
    DynamicRecord *read_records = malloc(record_count * sizeof(DynamicRecord));
    if (!read_records) {
        perror("Failed to allocate memory for reading");
        fclose(file);
        return;
    }

    size_t read = fread(read_records, sizeof(DynamicRecord), record_count, file);
    if (read != record_count) {
        perror("Failed to read records from file");
    } else {
        unsigned long checksum = calculate_checksum(read_records, record_count);
        printf("Checksum after reading: %lu\n", checksum);
    }

    free(read_records);
    fclose(file);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    // Initialize the system with a specific number of records
    if (allocate_records(1000) != 0) {
        return EXIT_FAILURE;
    }

    // Modify a record and check checksum
    modify_record(10, 12345L, 6789, 42);

    // Read from and write to an external file
    read_and_write_to_file("records.dat");

    free_records();
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
