#define MAX_RECORDS 10000000
#define MAX_MEMORY_SIZE (1024 * 1024 * 512) // 512 MB

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    unsigned int checksum;
} DynamicRecord;

// Global variables for thread safety and resource management
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
DynamicRecord *records = NULL;
size_t current_record_count = 0;

// Function prototypes
void initialize_system(size_t max_records);
void free_resources();
unsigned int calculate_checksum(const DynamicRecord *record);
void serialize_data(const char *format);
void deserialize_data(const char *data, size_t length, const char *format);
