    handle_concurrent_operations((void *(*)(void *))serialize_data, (void *)format);
    handle_concurrent_operations(get_input_and_find_max, NULL);

    free_resources();
    return EXIT_SUCCESS;
}

// Function implementations

void initialize_system(size_t max_records) {
    srand(time(NULL));
    pthread_mutex_lock(&mutex);
    records = (DynamicRecord*)malloc(max_records * sizeof(DynamicRecord));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    current_record_count = 0;
    pthread_mutex_unlock(&mutex);
}

void free_resources() {
    pthread_mutex_lock(&mutex);
    free(records);
    records = NULL;
    current_record_count = 0;
    pthread_mutex_unlock(&mutex);
}

unsigned int calculate_checksum(const DynamicRecord *record) {
    return (unsigned int)(record->offset ^ record->key ^ record->record.value);
}

void serialize_data(const char *format) {
    // Placeholder for serialization logic
    printf("Serializing data in format: %s\n", format);
}

void deserialize_data(const char *data, size_t length, const char *format) {
