}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* generate_random_string(size_t length, const char *charset) {
    char *str = malloc(length + 1);
    if (!str) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % strlen(charset)];
    }
    str[length] = '\0';
    return str;
}

size_t get_input_and_find_max() {
    int *numbers = NULL;
    size_t count = 0, capacity = 10;

    numbers = (int*)malloc(capacity * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter integers (Ctrl+D to finish):\n");

    while (scanf("%d", &numbers[count]) == 1) {
        if (++count >= capacity) {
            capacity *= 2;
            numbers = (int*)realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                fprintf(stderr, "Memory reallocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
    }

    int max_value = INT_MIN;
    for (size_t i = 0; i < count; ++i) {
        if (numbers[i] > max_value) {
            max_value = numbers[i];
        }
    }

    printf("Maximum integer: %d\n", max_value);

    free(numbers);
    return count;
}

void handle_concurrent_operations(void *(*operation)(void *), void *(*arg)) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, operation, arg) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(EXIT_FAILURE);
    }
    pthread_join(thread_id, NULL);
}
