logging.basicConfig(filename='config_management.log', level=logging.INFO)

class ConfigManager:
    def __init__(self, config_file_path: str, env_vars: Dict):
        self.config_file_path = config_file_path
        self.env_vars = env_vars
        self.mandatory_keys = ['API_URL', 'SERVICE_TOKEN']
        self.cache = {}
        self.backup_config = None

    def validate_env_vars(self):
        missing_mandatory = [key for key in self.mandatory_keys if key not in self.env_vars]
        if missing_mandatory:
            raise ValueError(f"Missing mandatory environment variables: {missing_mandatory}")

        for var, value in self.env_vars.items():
            if isinstance(value, str) and not value.strip():
                logging.warning(f"Environment variable '{var}' is empty.")

    def fetch_and_cache_data(self):
        service_url = self.env_vars.get('API_URL')
        auth_token = self.env_vars.get('SERVICE_TOKEN')

        # Use cached data to minimize API calls
        cache_key = (service_url, auth_token)
        if cache_key in self.cache:
            return self.cache[cache_key]

        try:
            sensitive_data = fetch_sensitive_data(service_url, auth_token)
            self.cache[cache_key] = sensitive_data
            return sensitive_data
        except Exception as e:
            logging.error(f"Failed to fetch sensitive data: {e}")
            raise

    def apply_config(self):
        if not os.path.exists(self.config_file_path):
            raise FileNotFoundError("Configuration file does not exist.")

        with open(self.config_file_path, 'r') as f:
            config = json.load(f)

        # Backup existing configuration
        self.backup_config = config.copy()

        try:
            sensitive_data = self.fetch_and_cache_data()
            for key, value in {**self.env_vars, **sensitive_data}.items():
                if key in config:
                    config[key] = value

            with open(self.config_file_path, 'w') as f:
                json.dump(config, f, indent=2)

            logging.info(f"{datetime.now()} - Configuration updated successfully.")

        except Exception as e:
            self.rollback()
            logging.error(f"Failed to apply configuration: {e}")
            raise

    def rollback(self):
        if self.backup_config is not None:
            with open(self.config_file_path, 'w') as f:
                json.dump(self.backup_config, f, indent=2)
            logging.info(f"{datetime.now()} - Configuration rolled back successfully.")

def integrate_with_ci_cd():
    # Placeholder for CI/CD integration logic
