        if (i > 0 && data_array[i].timestamp <= data_array[i - 1].timestamp) {
            log_inconsistency("Duplicate or negative timestamp detected.");
        }
    }

    // Serialize the data
    unsigned char *byte_array;
    size_t byte_count;
    serialize_sensor_data(data_array, capacity, &byte_array, &byte_count);

    // Deserialize back to check integrity
    sensor_data *deserialized_data = deserialize_sensor_data(byte_array, byte_count);

    // Free resources
    free_sensor_data(&data_array);
    free(deserialized_data);
    free(byte_array);
}

// Allocate memory for the sensor data array
sensor_data* allocate_sensor_array(size_t *capacity) {
    return malloc(*capacity * sizeof(sensor_data));
}

// Resize the sensor data array
size_t resize_sensor_array(sensor_data **array, size_t *capacity) {
    size_t new_capacity = *capacity * 2;
    sensor_data *new_array = realloc(*array, new_capacity * sizeof(sensor_data));
    if (new_array == NULL) {
        free(*array);
        *capacity = 0;
        return 0;
    }
    *array = new_array;
    *capacity = new_capacity;
    return new_capacity;
}

// Generate Gaussian distributed value
float generate_gaussian(float mean, float stddev) {
    static const double epsilon = 1e-10; // To prevent division by zero
    static double z0, z1;
    static int use_z1 = 0;

    if (use_z1) {
        use_z1 = 0;
        return z1 * stddev + mean;
    } else {
        do {
            z0 = rand() / ((double) RAND_MAX);
            z1 = rand() / ((double) RAND_MAX);
        } while (z0 == 0);

        double x = sqrt(-2.0 * log(z0)) * cos(2 * M_PI * z1);
        use_z1 = 1;
        return x * stddev + mean;
    }
}

// Log data inconsistencies
void log_inconsistency(const char *message) {
    printf("Inconsistency: %s\n", message);
}

// Serialize sensor data into a byte array
void serialize_sensor_data(const sensor_data *data, size_t count, unsigned char **byte_array, size_t *byte_count) {
    *byte_count = count * sizeof(sensor_data);
    *byte_array = malloc(*byte_count);

    if (*byte_array != NULL) {
        memcpy(*byte_array, data, *byte_count);
    }
}

// Deserialize byte array back to sensor data
sensor_data* deserialize_sensor_data(const unsigned char *byte_array, size_t byte_count) {
    size_t count = byte_count / sizeof(sensor_data);
    sensor_data *data = malloc(byte_count);

    if (data != NULL) {
        memcpy(data, byte_array, byte_count);
    }

    return data;
}

// Free allocated sensor data
void free_sensor_data(sensor_data **array) {
    free(*array);
    *array = NULL;
}

// Helper function to read integers from standard input and find the largest
void find_largest_integer() {
    int count;
    printf("Enter number of integers: ");
    scanf("%d", &count);

    if (count <= 0) return;

    int *numbers = malloc(count * sizeof(int));
    if (!numbers) return;

    printf("Enter %d integers:\n", count);
    for (int i = 0; i < count; ++i) {
        scanf("%d", &numbers[i]);
    }

    int largest = numbers[0];
    for (int i = 1; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", largest);

    free(numbers);
}

