size_t get_allocated_memory(Node* head) {
    size_t total = 0;
    while (head != NULL) {
        total += sizeof(*head) + sizeof(head->metadata[0]);
        head = head->next;
    }
    return total;
}

// Release all allocated memory and handle circular references
void free_all(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        if (current->metadata) {
            free(current->metadata);
        }
        free(current);
        current = next;
    }

    *head = NULL;
}

// Add a new node if within memory budget, else remove least critical
