    Node* newNode = (Node*)malloc(sizeof(Node));
    Record* record = &newNode->record;

    if (!newNode || get_allocated_memory(*head) + sizeof(*newNode) > mem_budget) {
        // Handle memory overflow by removing least critical node
        if (*head && strcmp((*head)->metadata->type, "critical") != 0) {
            Node* temp = *head;
            *head = (*head)->next;
            free_all(&temp);
