    record->next = NULL;

    newNode->metadata = (Metadata*)malloc(sizeof(Metadata));
    strcpy(newNode->metadata->type, type);
    newNode->metadata->size = sizeof(*record);

    newNode->next = *head;
    *head = newNode;

