#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>

// Assuming a third-party logging library is included like this:
// #include "third_party_logging_library.h"

typedef struct {
    int value;
    long offset;
    time_t last_update; // Using time_t for timestamp
} record_t;

typedef struct {
    record_t *records;
    size_t count;
    size_t capacity;
    pthread_rwlock_t lock;  // Read-write lock for thread-safe access
    size_t max_memory_size;
} record_manager_t;

static void log_event(const char* message) {
    // Placeholder for logging function from third-party library
    printf("%s\n", message);
}

record_manager_t* create_record_manager(size_t initial_capacity, size_t max_memory_size) {
    record_manager_t *manager = (record_manager_t*)malloc(sizeof(record_manager_t));
    if (!manager) {
        log_event("Failed to allocate memory for manager");
        return NULL;
    }

    manager->records = (record_t*)calloc(initial_capacity, sizeof(record_t));
    if (!manager->records) {
        free(manager);
        log_event("Failed to allocate memory for records");
        return NULL;
    }

    pthread_rwlock_init(&manager->lock, NULL);

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->max_memory_size = max_memory_size;

    return manager;
}

int add_record(record_manager_t *manager, int value, long offset) {
    if (value > INT_MAX || value < INT_MIN) {
        log_event("Integer overflow detected");
        return -1; // Error: Integer overflow
    }

    pthread_rwlock_wrlock(&manager->lock);

    size_t record_size = sizeof(record_t);
    size_t total_memory_needed = manager->count * record_size + record_size;

    if (total_memory_needed > manager->max_memory_size || manager->capacity <= manager->count) {
        pthread_rwlock_unlock(&manager->lock);
        log_event("Memory limit exceeded or no capacity");
        return -1; // Error: Memory limit exceeded
    }

    record_t *new_records = realloc(manager->records, (manager->count + 1) * sizeof(record_t));
    if (!new_records) {
        pthread_rwlock_unlock(&manager->lock);
        log_event("Failed to allocate memory for new records");
        return -1; // Error: Reallocation failed
    }

    manager->records = new_records;
    manager->capacity = manager->count + 1;

    record_t *record = &manager->records[manager->count++];
    record->value = value;
    record->offset = offset;
    record->last_update = time(NULL);

    pthread_rwlock_unlock(&manager->lock);
    return 0; // Success
}

size_t serialize_records(const record_manager_t* manager, uint8_t** buffer) {
    pthread_rwlock_rdlock(&manager->lock);

    size_t total_size = sizeof(size_t); // For count
    for (size_t i = 0; i < manager->count; ++i) {
        total_size += sizeof(record_t);
    }

    *buffer = malloc(total_size);
    if (!*buffer) {
        pthread_rwlock_unlock(&manager->lock);
        log_event("Failed to allocate memory for serialization buffer");
        return 0;
    }

    uint8_t *ptr = *buffer;

    // Serialize count
    memcpy(ptr, &manager->count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < manager->count; ++i) {
        record_t record = manager->records[i];

        // Ensure endianness consistency
        int value_be = htonl(record.value);
        long offset_be = htobe64(record.offset);
        time_t timestamp_be = htonll((uint64_t)record.last_update);

        memcpy(ptr, &value_be, sizeof(int));
        ptr += sizeof(int);

        memcpy(ptr, &offset_be, sizeof(long));
        ptr += sizeof(long);

        memcpy(ptr, &timestamp_be, sizeof(time_t));
        ptr += sizeof(time_t);
    }

    pthread_rwlock_unlock(&manager->lock);
    return total_size;
}

int deserialize_records(const uint8_t* buffer, size_t buffer_size, record_manager_t* manager) {
    if (buffer_size < sizeof(size_t)) {
        log_event("Invalid serialization buffer");
        return -1; // Error: Invalid data
    }

    const uint8_t *ptr = buffer;
    size_t count;

    memcpy(&count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if (count > manager->capacity) {
        log_event("Deserialization buffer has more records than capacity");
        return -1; // Error: Capacity exceeded
    }

    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < count; ++i) {
        record_t *record = &manager->records[i];

        int value_be;
        long offset_be;
        time_t timestamp_be;

        memcpy(&value_be, ptr, sizeof(int));
        ptr += sizeof(int);

        memcpy(&offset_be, ptr, sizeof(long));
        ptr += sizeof(long);

        memcpy(&timestamp_be, ptr, sizeof(time_t));
        ptr += sizeof(time_t);

        record->value = ntohl(value_be);
        record->offset = be64toh(offset_be);
        record->last_update = (time_t)be64toh((uint64_t)timestamp_be);
    }

    manager->count = count;

    pthread_rwlock_unlock(&manager->lock);
    return 0; // Success
}

void destroy_record_manager(record_manager_t *manager) {
    if (!manager) return;

    free(manager->records);
    pthread_rwlock_destroy(&manager->lock);
    free(manager);

    log_event("Record manager destroyed");
}
