    json_t *allow_duplicate_keys_json = json_object_get(root, "allow_duplicate_keys");
    if (json_is_boolean(allow_duplicate_keys_json)) {
        allow_duplicate_keys = json_is_true(allow_duplicate_keys_json);
    }

    json_decref(root);

