    sys->offsets = (long *)calloc(num_records, sizeof(long));
    sys->keys = (int *)calloc(num_records, sizeof(int));
    sys->records = (record *)malloc(num_records * sizeof(record));

    if (!sys->offsets || !sys->keys || !sys->records) {
