#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000000
#define LOG_FREQUENCY 1000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    int *parent;
    int *rank;
} UnionFind;

// Initialize Union-Find data structure
void uf_init(UnionFind *uf, int size) {
    uf->parent = (int *)calloc(size, sizeof(int));
    uf->rank = (int *)calloc(size, sizeof(int));
    for (int i = 0; i < size; ++i) {
        uf->parent[i] = i;
    }
}

// Find with path compression
int uf_find(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = uf_find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

// Union by rank
void uf_union(UnionFind *uf, int x, int y) {
    int rootX = uf_find(uf, x);
    int rootY = uf_find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

// Generate a random number within the range [min, max]
int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Initialize records with random keys and offsets
void initialize_records(Record *records, int size, int key_min, int key_max) {
    for (int i = 0; i < size; ++i) {
        records[i].key = generate_random(key_min, key_max);
        records[i].offset = generate_random(0, INT64_MAX);
    }
}

// Merge external data into existing records
void merge_records(Record *records, int record_count, Record *external_data, int ext_data_count) {
    for (int i = 0; i < ext_data_count; ++i) {
        int duplicate_found = 0;
        for (int j = 0; j < record_count; ++j) {
            if (records[j].key == external_data[i].key) {
                records[j].offset = external_data[i].offset;
                duplicate_found = 1;
                break;
            }
        }
        if (!duplicate_found) {
            // Add new record
            records[record_count++] = external_data[i];
        }
    }
}

// Serialize records to disk
void serialize_records(Record *records, int count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&count, sizeof(int), 1, file);
        fwrite(records, sizeof(Record), count, file);
        fclose(file);
    }
}

// Deserialize records from disk
int deserialize_records(Record **records, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file) {
        int count;
        fread(&count, sizeof(int), 1, file);
        *records = (Record *)malloc(count * sizeof(Record));
        fread(*records, sizeof(Record), count, file);
        fclose(file);
        return count;
    }
    return -1;
}

// Log processing information
void log_info(int record_count, double processing_time) {
    static int log_counter = 0;
    if (++log_counter % LOG_FREQUENCY == 0) {
        printf("Processed %d records in %.2f seconds.\n", record_count, processing_time);
    }
}

// Manage the dynamic collection of records
void manage_records(Record **records, int *record_count, Record *external_data, int ext_data_count,
                    const char *filename, int key_min, int key_max) {
    clock_t start = clock();

    if (*records == NULL) {
        *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
        *record_count = 0;
        initialize_records(*records, MAX_RECORDS, key_min, key_max);
    }

    merge_records(*records, *record_count, external_data, ext_data_count);

    // Serialize records to disk
    serialize_records(*records, *record_count, filename);

    clock_t end = clock();
    double processing_time = (double)(end - start) / CLOCKS_PER_SEC;
    log_info(*record_count, processing_time);
}

int main() {
    srand(time(NULL));

    Record *records = NULL;
    int record_count = 0;
    Record external_data[] = {{1, 100}, {2, 200}};
    int ext_data_count = sizeof(external_data) / sizeof(Record);

    manage_records(&records, &record_count, external_data, ext_data_count, "records.dat", 0, MAX_RECORDS - 1);

    int count;
    Record *loaded_records = NULL;
    if ((count = deserialize_records(&loaded_records, "records.dat")) > 0) {
        printf("Deserialized %d records.\n", count);
    }

    free(records);
    free(loaded_records);

    return 0;
}
