// Function to read configuration from a file.
Config read_config(const char *filename) {
    Config config = {0};
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_message("ERROR", "Failed to open configuration file.");
        exit(EXIT_FAILURE);
    }

    // Assuming the file contains lines like max_records=100
    while (fscanf(file, "%*s=%d\n", &config.max_records) == 1 ||
           fscanf(file, "%*s=%zu\n", &config.memory_limit) == 1 ||
           fscanf(file, "%*s=%d\n", &config.allow_duplicate_keys) == 1);

    fclose(file);
    return config;
}

// Mutex for synchronizing access to shared resources.
