    long total_memory_used = 0;
    for (int i = 0; i < config.max_records; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record || total_memory_used + sizeof(*record) > config.memory_limit) {
            log_message("ERROR", "Memory allocation failed due to fragmentation.");
            break;
