        int key_size = sizeof(int);

        record->key = malloc(key_size);
        if (!record->key || total_memory_used + key_size > config.memory_limit) {
            log_message("ERROR", "Memory allocation failed for key.");
            free(record);
            break;
        }

        *record->key = rand(); // Replace with actual key generation logic.

        records[i] = record;
        total_memory_used += sizeof(*record) + key_size;

        if (!config.allow_duplicate_keys) {
            for (int j = 0; j < i; ++j) {
                if (*(records[j]->key) == *(record->key)) {
                    log_message("WARNING", "Duplicate key found, linking.");
                    record->next = records[j];
                    break;
                }
            }
        }
    }

    pthread_mutex_unlock(&resource_mutex);

    // Clean up
    for (int i = 0; i < config.max_records && records[i]; ++i) {
        free(records[i]->key);
        free(records[i]);
    }
    free(records);

    return NULL; // In practice, you would return a valid head of the list.
}

void cleanup(Record *records[], int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->key);
            free(records[i]);
        }
    }
}

// Entry point to demonstrate functionality
int main() {
    const char *config_file = "config.txt";

    // Initialize records from configuration file.
    Record *head = create_records_from_config(config_file);

    // Example of cleaning up
    cleanup((Record*[]){NULL}, 0); // Replace with actual handling

    pthread_mutex_destroy(&resource_mutex);
    return 0;
}
