int is_token_unique(const char *session_token, redisContext *redis_ctx) {
    redisReply *reply = (redisReply *)redisCommand(redis_ctx, "EXISTS %s", session_token);
    int exists = reply->integer;
    freeReplyObject(reply);

    if (!exists) {
        return 0; // Token is unique
    }
    time_t now = time(NULL);
    reply = (redisReply *)redisCommand(redis_ctx, "TTL %s", session_token);
    long ttl = reply->integer;
    freeReplyObject(reply);

    return (ttl >= SESSION_TIMEOUT_SECONDS) ? 1 : 0; // Check if not expired
}

// Validate the active status and activity time of a session
int is_session_active(const Session *session) {
    time_t now = time(NULL);
    long last_activity_diff = difftime(now, session->last_activity_time);

    return (session->active_status && 
            last_activity_diff <= GRACE_PERIOD &&
            last_activity_diff <= SESSION_TIMEOUT_SECONDS);
}

