int handle_session(redisContext *redis_ctx, const char *user_id,
                   const char *session_token, time_t last_activity_time) {

    if (!validate_uuid(user_id)) {
        return -1; // Invalid UUID format
    }

    pthread_mutex_lock(&session_cache.lock);
    Session session = {.active_status = 1}; // Assuming active for simplification

    strncpy(session.user_id, user_id, sizeof(session.user_id));
    strncpy(session.session_token, session_token, sizeof(session.session_token));
    session.last_activity_time = last_activity_time;

    pthread_mutex_unlock(&session_cache.lock);

    if (!is_token_unique(session_token, redis_ctx)) {
        return -2; // Token is not unique or expired
    }

    if (!is_session_active(&session)) {
        return -3; // Session inactive or timed out
    }

    update_session(&session);
    return 0; // Success
}

