void initialize_data(long *offset_values, int *keys, short *identifiers,
                     record_t *records1, record_t *records2, time_t *timestamps) {
    size_t total_size = sizeof(long) * 5 + sizeof(int) * 5 + sizeof(short) * 5 +
                        2 * sizeof(record_t) * 5 + sizeof(time_t) * 5;

    if (total_size > MAX_SIZE) {
        fprintf(stderr, "Error: Total allocated memory exceeds maximum size limit.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 5; ++i) {
        offset_values[i] = rand() % 100;
        keys[i] = rand() % 100;
        identifiers[i] = rand() % 32767;
        timestamps[i] = time(NULL);

        records1[i].value = rand() % 1000;
        records1[i].offset = rand() % 10000L;
        records1[i].identifier = rand() % 32767;
        records1[i].timestamp = timestamps[i];

