        records2[i].offset = rand() % 10000L;
        records2[i].identifier = rand() % 32767;
        records2[i].timestamp = timestamps[i];
    }
}

void serialize_data(long *offset_values, int *keys, short *identifiers,
                    record_t *records1, record_t *records2, time_t *timestamps,
                    uint8_t **serialized_data, size_t *size) {
    size_t total_size = sizeof(long) * 5 + sizeof(int) * 5 + sizeof(short) * 5 +
                        2 * sizeof(record_t) * 5 + sizeof(time_t) * 5;

    *serialized_data = (uint8_t *)malloc(total_size);
    if (!*serialized_data) {
        fprintf(stderr, "Error: Memory allocation failed for serialization.\n");
        exit(EXIT_FAILURE);
    }

    size_t offset = 0;
    memcpy(*serialized_data + offset, offset_values, sizeof(long) * 5);
    offset += sizeof(long) * 5;

    memcpy(*serialized_data + offset, keys, sizeof(int) * 5);
    offset += sizeof(int) * 5;

    memcpy(*serialized_data + offset, identifiers, sizeof(short) * 5);
    offset += sizeof(short) * 5;

    memcpy(*serialized_data + offset, records1, sizeof(record_t) * 5);
    offset += sizeof(record_t) * 5;

    memcpy(*serialized_data + offset, records2, sizeof(record_t) * 5);
    offset += sizeof(record_t) * 5;

    memcpy(*serialized_data + offset, timestamps, sizeof(time_t) * 5);
    offset += sizeof(time_t) * 5;

    *size = total_size;
}

void deserialize_data(uint8_t *serialized_data, size_t size,
                      long **offset_values, int **keys, short **identifiers,
                      record_t **records1, record_t **records2, time_t **timestamps) {
    if (size != sizeof(long) * 5 + sizeof(int) * 5 + sizeof(short) * 5 +
        2 * sizeof(record_t) * 5 + sizeof(time_t) * 5) {
        fprintf(stderr, "Error: Deserialization size mismatch.\n");
        exit(EXIT_FAILURE);
    }

    *offset_values = (long *)malloc(sizeof(long) * 5);
    *keys = (int *)malloc(sizeof(int) * 5);
    *identifiers = (short *)malloc(sizeof(short) * 5);
    *records1 = (record_t *)malloc(sizeof(record_t) * 5);
    *records2 = (record_t *)malloc(sizeof(record_t) * 5);
    *timestamps = (time_t *)malloc(sizeof(time_t) * 5);

    size_t offset = 0;
    memcpy(*offset_values, serialized_data + offset, sizeof(long) * 5);
    offset += sizeof(long) * 5;

    memcpy(*keys, serialized_data + offset, sizeof(int) * 5);
    offset += sizeof(int) * 5;

    memcpy(*identifiers, serialized_data + offset, sizeof(short) * 5);
    offset += sizeof(short) * 5;

    memcpy(*records1, serialized_data + offset, sizeof(record_t) * 5);
    offset += sizeof(record_t) * 5;

    memcpy(*records2, serialized_data + offset, sizeof(record_t) * 5);
    offset += sizeof(record_t) * 5;

    memcpy(*timestamps, serialized_data + offset, sizeof(time_t) * 5);
}

void free_memory(long *offset_values, int *keys, short *identifiers,
                 record_t *records1, record_t *records2, time_t *timestamps) {
    free(offset_values);
    free(keys);
    free(identifiers);
    free(records1);
    free(records2);
    free(timestamps);
}

void filter_records(int key_min, int key_max, record_t *records, size_t count,
                    record_t **filtered_records, size_t *filtered_count) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < count; ++i) {
        if (records[i].value >= key_min && records[i].value <= key_max) {
            (*filtered_count)++;
        }
    }

    *filtered_records = (record_t *)malloc(sizeof(record_t) * (*filtered_count));
    size_t j = 0;
    for (size_t i = 0; i < count; ++i) {
        if (records[i].value >= key_min && records[i].value <= key_max) {
            (*filtered_records)[j++] = records[i];
        }
    }

    pthread_mutex_unlock(&mutex);
}

void update_data_with_new_input(record_t *existing_records, size_t existing_count,
                                record_t *new_records, size_t new_count) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < new_count; ++i) {
        int found = 0;
        for (size_t j = 0; j < existing_count; ++j) {
            if (existing_records[j].offset == new_records[i].offset) {
                existing_records[j].value = new_records[i].value;
                existing_records[j].identifier = new_records[i].identifier;
                existing_records[j].timestamp = new_records[i].timestamp;
                found = 1;
                break;
            }
        }
        if (!found) {
            // Add new record to existing records
            existing_count++;
            existing_records = (record_t *)realloc(existing_records, sizeof(record_t) * existing_count);
            existing_records[existing_count - 1] = new_records[i];
        }
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
