    records1 = (record_t *)malloc(sizeof(record_t) * 5);
    records2 = (record_t *)malloc(sizeof(record_t) * 5);
    timestamps = (time_t *)malloc(sizeof(time_t) * 5);

    if (!offset_values || !keys || !identifiers || !records1 || !records2 || !timestamps) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    initialize_data(offset_values, keys, identifiers, records1, records2, timestamps);

