#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

// Structure definition for 'record'
typedef struct {
    int value;
    long offset;
    void *metadata; // Optional pointer, could be any data type or NULL
} Record;

#define MAX_RECORDS 1000
#define MAX_MEMORY_SIZE (1024 * 1024) // Example: 1MB max memory allocation
#define INTEGER_RANGE_MIN -10000
#define INTEGER_RANGE_MAX 10000

// External database mock functions for demonstration purposes
void flush_to_database(const Record* records, size_t count);
void log_error(const char* message);

pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and initialize records
Record* create_records(size_t num_records, int max_memory_size) {
    if (num_records > MAX_RECORDS || num_records * sizeof(Record) > max_memory_size) {
        log_error("Invalid number of records requested");
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        log_error("Memory allocation failed for records");
        return NULL;
    }

    // Seed random number generator with current time
    srand((unsigned int)time(NULL));

    // Populate records with random integer values and example offset
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = INTEGER_RANGE_MIN + rand() % (INTEGER_RANGE_MAX - INTEGER_RANGE_MIN + 1);
        records[i].offset = (long)(rand() % 1000000); // Example offset
        records[i].metadata = NULL; // Optional metadata, can be set as needed
    }

    return records;
}

// Helper function to serialize a single record considering endianness
size_t serialize_record(const Record* record, uint8_t* buffer) {
    size_t index = 0;

    int value = htobe32(record->value);
    memcpy(buffer + index, &value, sizeof(int));
    index += sizeof(int);

    long offset = htobe64(record->offset);
    memcpy(buffer + index, &offset, sizeof(long));
    index += sizeof(long);

    return index; // Return the size of serialized data
}

// Function to serialize all records into a byte array
uint8_t* serialize_records(const Record* records, size_t num_records, size_t* output_size) {
    *output_size = 0;
    for (size_t i = 0; i < num_records; ++i) {
        *output_size += sizeof(int) + sizeof(long);
    }

    uint8_t* serialized_data = malloc(*output_size);
    if (!serialized_data) {
        log_error("Memory allocation failed for serialization");
        return NULL;
    }

    size_t index = 0;
    for (size_t i = 0; i < num_records; ++i) {
        index += serialize_record(&records[i], serialized_data + index);
    }

    return serialized_data;
}

// Deserialize function for records
void deserialize_records(const uint8_t* data, size_t data_size, Record* records, size_t num_records) {
    if (data_size < num_records * (sizeof(int) + sizeof(long))) {
        log_error("Deserialization buffer too small");
        return;
    }

    size_t index = 0;
    for (size_t i = 0; i < num_records; ++i) {
        int value = be32toh(*(int*)(data + index));
        records[i].value = value;
        index += sizeof(int);

        long offset = be64toh(*(long*)(data + index));
        records[i].offset = offset;
        index += sizeof(long);
    }
}

// Mock function to flush records to an external database
void flush_to_database(const Record* records, size_t count) {
    pthread_mutex_lock(&db_lock);
    // Database interaction logic here (mocked for this example)
    printf("Flushing %zu records to the database...\n", count);
    pthread_mutex_unlock(&db_lock);
}

// Mock function for logging errors
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    size_t num_records = 10;
    int max_memory_size = MAX_MEMORY_SIZE;

    Record* records = create_records(num_records, max_memory_size);
    if (!records) {
        return EXIT_FAILURE;
    }

    // Serialize records
    size_t serialized_data_size;
    uint8_t* serialized_data = serialize_records(records, num_records, &serialized_data_size);

    if (serialized_data) {
        // Deserialize back to verify correctness
        Record deserialized_records[MAX_RECORDS];
        deserialize_records(serialized_data, serialized_data_size, deserialized_records, num_records);

        // Free allocated memory for serialization
        free(serialized_data);
    }

    // Flush records to database
    flush_to_database(records, num_records);

    // Cleanup
    free(records);

    return EXIT_SUCCESS;
}
