#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a 'data' structure with timestamp and status indicator
typedef struct Data {
    double value;
    char status;
    struct Data *next; // Pointer to the next data point in the series
} Data;

// Global variables for managing memory limit
size_t max_memory_size = 1024 * 1024; // Example: 1MB
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Data* create_data_point(double value, char status);
void free_data_chain(Data *head);
int serialize_data(Data *head, unsigned char **buffer);
int deserialize_data(const unsigned char *buffer, Data **data_head);
unsigned long get_memory_usage();
int check_circular_references(Data *start);

// Create a new data point
Data* create_data_point(double value, char status) {
    Data *new_data = (Data *)malloc(sizeof(Data));
    if (!new_data) return NULL;

    new_data->value = value;
    new_data->status = status;
    new_data->next = NULL;

    return new_data;
}

// Free the entire chain of data points
void free_data_chain(Data *head) {
    Data *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Serialize data structure into a binary format
int serialize_data(Data *head, unsigned char **buffer) {
    pthread_mutex_lock(&lock);

    if (!head || !buffer) return -1;

    size_t estimated_size = sizeof(size_t); // For the number of elements
    Data *current = head;
    while (current != NULL) {
        estimated_size += sizeof(double) + sizeof(char);
        current = current->next;
    }

    unsigned char *serialized_data = (unsigned char *)malloc(estimated_size);
    if (!serialized_data) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    unsigned char *ptr = serialized_data;
    size_t data_count = 0;

    // Store number of elements
    ptr += sizeof(size_t);
    memcpy(ptr - sizeof(size_t), &data_count, sizeof(size_t));

    current = head;
    while (current != NULL) {
        *(++(unsigned long *)ptr) = htonl(*(unsigned long *)&current->value); // Serialize double
        ptr += sizeof(double);

        *ptr = current->status; // Serialize char
        ptr += sizeof(char);

        data_count++;
        current = current->next;
    }

    // Update the count at the start of the buffer
    memcpy(serialized_data, &data_count, sizeof(size_t));

    pthread_mutex_unlock(&lock);

    *buffer = serialized_data;
    return 0;
}

// Deserialize binary format back into a data structure
int deserialize_data(const unsigned char *buffer, Data **data_head) {
    if (!buffer || !data_head) return -1;

    size_t num_elements;
    memcpy(&num_elements, buffer, sizeof(size_t));
    const unsigned char *ptr = buffer + sizeof(size_t);

    pthread_mutex_lock(&lock);

    Data *head = NULL, *tail = NULL;
    for (size_t i = 0; i < num_elements; ++i) {
        double value;
        memcpy(&value, ptr, sizeof(double));
        value = ntohl(*(unsigned long *)&value); // Deserialize double

        char status = *ptr + sizeof(double);

        Data *new_data = create_data_point(value, status);
        if (!new_data) {
            pthread_mutex_unlock(&lock);
            free_data_chain(head);
            return -1;
        }

        if (tail) tail->next = new_data;
        else head = new_data;

        tail = new_data;
        ptr += sizeof(double) + sizeof(char);
    }

    if (!check_circular_references(head)) {
        pthread_mutex_unlock(&lock);
        free_data_chain(head);
        return -1; // Circular reference detected
    }

    *data_head = head;
    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to calculate current memory usage
unsigned long get_memory_usage() {
    unsigned long total_memory = 0;

    Data *current = (Data *)malloc(sizeof(Data));
    while (current != NULL) {
        current = current->next;
        total_memory += sizeof(Data); // Simplified estimate of used memory
    }

    return total_memory;
}

// Check for circular references in data chain to prevent infinite loops
int check_circular_references(Data *start) {
    Data *slow_p = start, *fast_p = start;

    while (slow_p && fast_p && fast_p->next) {
        slow_p = slow_p->next;
        fast_p = fast_p->next->next;

        if (slow_p == fast_p)
            return 0; // Circular reference detected
    }

    return 1; // No circular reference found
}

// Main function to demonstrate usage
int main() {
    Data *data_head = create_data_point(3.14, 'A');
    data_head->next = create_data_point(2.71, 'B');

    unsigned char *serialized;
    if (serialize_data(data_head, &serialized) == 0) {
        printf("Data serialized successfully\n");

        Data *deserialized_head;
        if (deserialize_data(serialized, &deserialized_head) == 0) {
            printf("Data deserialized successfully\n");
        } else {
            printf("Failed to deserialize data\n");
        }

        free(serialized);
    } else {
        printf("Failed to serialize data\n");
    }

    free_data_chain(data_head);

    return 0;
}
```

This code defines a `Data` structure with serialization and deserialization functions, memory management strategies, thread-safe operations using mutex locks, and mechanisms to detect circular references. The example demonstrates how to manage memory for real-time data processing systems efficiently while handling concurrency issues and ensuring robustness against memory fragmentation.']

