#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // 1MB memory budget for demonstration

typedef struct Record {
    int value;
    long offset;
    struct Record* next_record;
} Record;

typedef struct Metadata {
    size_t size;
    char type[16];
} Metadata;

typedef struct FlexibleRecord {
    long offsets;
    int keys;
    Record* records;
    Metadata* metadata;
} FlexibleRecord;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

size_t total_memory_allocated = 0;

// Helper function to calculate memory usage
size_t calculate_memory_usage(FlexibleRecord* fr) {
    size_t size = sizeof(*fr);
    if (fr->records != NULL) {
        size += sizeof(Record) * fr->keys; // Assuming keys is the number of records
        for (int i = 0; i < fr->keys; ++i) {
            size += sizeof(fr->metadata[i]);
        }
    }
    return size;
}

// Eviction strategy: Remove least recently used record
void evict_records(FlexibleRecord* fr, size_t required_space) {
    if (fr->records == NULL || fr->keys <= 0) return;

    while (total_memory_allocated > MAX_MEMORY - required_space && fr->keys > 0) {
        // Evict the first record for simplicity
        Record* record_to_free = fr->records;
        Metadata* metadata_to_free = &fr->metadata[0];

        total_memory_allocated -= sizeof(*record_to_free) + sizeof(*metadata_to_free);

        if (record_to_free->next_record != NULL) {
            fr->records = record_to_free->next_record; // Shift the records
        } else {
            fr->keys--;
            free(record_to_free);
            fr->records = NULL;
            break;
        }

        free(metadata_to_free); // Free metadata associated with the evicted record
    }
}

// Initialize and manage memory for flexible records structure
FlexibleRecord* initialize_flexible_record(int num_keys, int value_range_min, int value_range_max) {
    FlexibleRecord* fr = (FlexibleRecord*)malloc(sizeof(FlexibleRecord));
    if (!fr) return NULL;

    pthread_mutex_lock(&mutex);

    // Seed random number generator
    srand(time(NULL));

    // Memory budget check
    size_t required_space = sizeof(*fr) + num_keys * (sizeof(Record) + sizeof(Metadata));
    if (required_space > MAX_MEMORY) {
        fprintf(stderr, "Memory limit exceeded\n");
        free(fr);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    total_memory_allocated += required_space;

    fr->keys = num_keys;
    fr->records = malloc(sizeof(Record) * num_keys);
    fr->metadata = (Metadata*)malloc(sizeof(Metadata) * num_keys);

    if (!fr->records || !fr->metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        evict_records(fr, 0); // Clean up in case of partial failure
        free(fr);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (int i = 0; i < num_keys; ++i) {
        fr->records[i].value = value_range_min + rand() % (value_range_max - value_range_min + 1);
        fr->records[i].offset = rand(); // Random offset
        fr->records[i].next_record = (i < num_keys - 1) ? &fr->records[i + 1] : NULL;

        strcpy(fr->metadata[i].type, "Record");
        fr->metadata[i].size = sizeof(Record);
    }

    pthread_mutex_unlock(&mutex);

    return fr;
}

// Function to release all allocated memory for FlexibleRecord
void free_flexible_record(FlexibleRecord* fr) {
    if (!fr) return;

    pthread_mutex_lock(&mutex);

    if (fr->records != NULL && fr->metadata != NULL) {
        total_memory_allocated -= sizeof(*fr) + fr->keys * (sizeof(Record) + sizeof(Metadata));
        free(fr->records);
        free(fr->metadata);
    }

    free(fr);
    pthread_mutex_unlock(&mutex);
}

// Logging function for memory usage
void log_memory_usage() {
    printf("Total Memory Allocated: %zu bytes\n", total_memory_allocated);
}

int main() {
    int num_keys = 10;
    FlexibleRecord* fr = initialize_flexible_record(num_keys, 0, 100);

    if (fr) {
        log_memory_usage();
        free_flexible_record(fr);
        log_memory_usage();
    }

    return 0;
}
