#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>  // For hashing

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Function to generate a random string of specified length from a given character set
char* generate_random_string(const char *charset, size_t length) {
    const size_t charset_size = strlen(charset);
    char *random_string = malloc(length + 1);

    if (!random_string) {
        perror("Failed to allocate memory for random string");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < length; ++i) {
        random_string[i] = charset[rand() % charset_size];
    }
    random_string[length] = '\0';

    return random_string;
}

// Function to compute a hash from a string using SHA256 and convert it to an integer key
int hash_to_key(const char *string) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;

    if (!SHA256_Init(&sha256)) {
        fprintf(stderr, "SHA256 Initialization failed\n");
        return -1;
    }

    if (!SHA256_Update(&sha256, string, strlen(string))) {
        fprintf(stderr, "SHA256 Update failed\n");
        return -1;
    }

    if (!SHA256_Final(hash, &sha256)) {
        fprintf(stderr, "SHA256 Finalization failed\n");
        return -1;
    }

    // Convert the first 4 bytes of the hash to an integer
    int key = 0;
    memcpy(&key, hash, sizeof(int));
    return key;
}

// Function to initialize and manage records
Record* create_records(size_t num_records, size_t string_length, const char *charset, int min_value, int max_value) {
    if (num_records == 0 || !charset || string_length == 0 || min_value > max_value) {
        fprintf(stderr, "Invalid parameters for creating records\n");
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_records; ++i) {
        char *random_string = generate_random_string(charset, string_length);
        if (!random_string) {
            free(records);
            return NULL;
        }

        records[i].key = hash_to_key(random_string);
        if (records[i].key == -1) {  // Check for hash failure
            free(random_string);
            free(records);
            return NULL;
        }

        records[i].offset = rand() % (max_value - min_value + 1) + min_value;

        free(random_string);  // Free the allocated memory for string after use
    }

    return records;
}

// Function to free the allocated memory for records
void free_records(Record *records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t num_records = 10;  // Example configuration parameter
    size_t string_length = 8;
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    int min_value = 0, max_value = 100;

    Record *records = create_records(num_records, string_length, charset, min_value, max_value);

    if (records) {
        for (size_t i = 0; i < num_records; ++i) {
            printf("Record %zu: Key = %d, Offset = %ld\n", i, records[i].key, records[i].offset);
        }
        free_records(records);
    }

    return 0;
}
