} Operation;

// Function prototypes
void initializeStructures(int numOperations, int stringSize, double minVal, double maxVal);
void freeAllocatedMemory(Operation *operations, int numOperations);

int main() {
    // Example usage: Initialize structures with 10 operations and string size of 50.
    initializeStructures(10, 50, 0.0, 100.0);
    return 0;
}

// Function to dynamically allocate memory for data structures and initialize them.
void initializeStructures(int numOperations, int stringSize, double minVal, double maxVal) {
    srand(time(NULL)); // Seed random number generator

    Operation *operations = (Operation *)malloc(numOperations * sizeof(Operation));
    if (!operations) {
        fprintf(stderr, "Memory allocation for operations array failed\n");
        return;
    }

    for (int i = 0; i < numOperations; ++i) {
        Node *node = (Node *)malloc(sizeof(Node));
        if (!node) {
            fprintf(stderr, "Memory allocation for node %d failed\n", i);
            freeAllocatedMemory(operations, i);
            return;
        }

        // Allocate memory for the string in the node
        node->name = (char *)calloc(stringSize, sizeof(char));
        if (!node->name) {
            fprintf(stderr, "Memory allocation for name of node %d failed\n", i);
            free(node);
            freeAllocatedMemory(operations, i);
            return;
        }
        snprintf(node->name, stringSize, "Node_%ld", (long)i); // Example initialization

        operations[i].nodePtr = node;

        // Generate a random double value within the specified range
        operations[i].value = minVal + ((double)rand() / RAND_MAX) * (maxVal - minVal);

        // Assign command identifier based on predefined types (e.g., 'A', 'B', or 'C')
        const char commands[] = {'A', 'B', 'C'};
        operations[i].command = commands[rand() % 3]; // Randomly assign a command
    }

    // Example processing (to be replaced with actual logic as needed)
    for (int i = 0; i < numOperations; ++i) {
        printf("Operation %d: Node ID=%ld, Name=%s, Value=%.2f, Command=%c\n",
               i, operations[i].nodePtr->id, operations[i].nodePtr->name,
               operations[i].value, operations[i].command);
    }

    // Free all allocated memory
    freeAllocatedMemory(operations, numOperations);
}

// Function to free all allocated memory for operations and associated nodes.
void freeAllocatedMemory(Operation *operations, int numOperations) {
    if (!operations) return;

    for (int i = 0; i < numOperations; ++i) {
        Node *node = operations[i].nodePtr;
        if (node->name) free(node->name);
        free(node);
    }
    free(operations);
}
