#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>

#define MAX_FILES 1024
#define MAX_FILENAME_LENGTH 256
#define EXTENSION_LENGTH 6

typedef struct {
    int key;
    char *filename;
} FileMetadata;

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

char* generateNewExtension(const char *filename) {
    static char new_ext[EXTENSION_LENGTH + 1];
    int len = strlen(filename);
    int num_chars = (len > 3) ? 3 : len;
    unsigned long seed = time(NULL);

    for (int i = 0; i < num_chars && filename[i] >= '0' && filename[i] <= '9'; ++i) {
        new_ext[i] = filename[i];
    }
    while (++i < EXTENSION_LENGTH) {
        new_ext[i] = (seed % 10) + '0';
        seed /= 10;
    }
    new_ext[EXTENSION_LENGTH] = '\0';

    return new_ext;
}

void modifyFileExtension(const char *directory) {
    DIR *dir;
    struct dirent *entry;
    FileMetadata metadata[MAX_FILES];
    int file_count = 0;

    if (!(dir = opendir(directory))) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) && file_count < MAX_FILES) {
        if (entry->d_type == DT_REG) { // Regular files
            char filepath[MAX_FILENAME_LENGTH];
            snprintf(filepath, sizeof(filepath), "%s/%s", directory, entry->d_name);

            struct stat st;
            if (stat(filepath, &st) != 0) continue;

            metadata[file_count].filename = strdup(entry->d_name);
            metadata[file_count].key = hash(metadata[file_count].filename) % 100000;

            char new_ext[EXTENSION_LENGTH + 1];
            strcpy(new_ext, generateNewExtension(entry->d_name));

            char new_filepath[MAX_FILENAME_LENGTH];
            snprintf(new_filepath, sizeof(new_filepath), "%s.%s", filepath, new_ext);

            FILE *src = fopen(filepath, "rb");
            if (!src) continue;

            FILE *dst = fopen(new_filepath, "wb");
            if (!dst) {
                fclose(src);
                continue;
            }

            char buffer[1024];
            size_t bytes_read;
            while ((bytes_read = fread(buffer, 1, sizeof(buffer), src)) > 0) {
                fwrite(buffer, 1, bytes_read, dst);
            }

            fclose(src);
            fclose(dst);

            remove(filepath); // Remove the old file

            ++file_count;
        }
    }

    for (int i = 0; i < file_count; ++i) {
        free(metadata[i].filename);
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    modifyFileExtension(argv[1]);

    return EXIT_SUCCESS;
}
