        offsetValues = new long[config.OffsetCapacity];
        keys = new HashSet<int>(new RandomizedEqualityComparer());
        records = new List<Record>(config.InitialRecordCapacity);

        logFilePath = config.LogFilePath;
        Log($"Initialized RecordManager with {offsetValues.Length} offsets, initial record capacity: {config.InitialRecordCapacity}.", false);
    }

    public bool AddRecord(int value)
    {
        if (totalSum + value > MaxTotalSum) return false;

        try
        {
            records.Add(new Record { Value = value });
            keys.Add(value);
            totalSum += value;

            if (records.Count % config.ResizeThreshold == 0)
            {
                ResizeRecords();
                Log($"Resized record collection to {records.Capacity}.", false);
            }

            return true;
        }
        catch (OutOfMemoryException ex)
        {
            Log($"Failed memory allocation: {ex.Message}", true);
            return false;
        }
    }

    public bool GenerateUniqueInt(out int value)
    {
        Random rand = new Random();
        while (true)
        {
            value = rand.Next(int.MinValue, int.MaxValue);
            if (!keys.Contains(value)) break;
        }
        Log($"Generated unique int: {value}.", false);
        return true;
    }

    private void ResizeRecords()
    {
        int newSize = records.Count * 2;
        var newRecordList = new List<Record>(newSize);

        foreach (var record in records)
        {
            newRecordList.Add(record);
        }

        records = newRecordList;
    }

    private bool ValidateConfig(Config config)
    {
        return config.InitialRecordCapacity > 0 && 
               config.OffsetCapacity > 0 &&
               !string.IsNullOrEmpty(config.LogFilePath) &&
               config.ResizeThreshold > 0;
    }

    private Config LoadConfig(string filePath)
    {
        // Mocked loading for demonstration. In practice, load using a JSON/XML parser.
        return new Config
        {
            OffsetCapacity = 100,
            InitialRecordCapacity = 50,
            ResizeThreshold = 10,
            LogFilePath = "log.txt"
        };
    }

    private void Log(string message, bool isError)
    {
        string logMessage = $"{DateTime.Now}: {(isError ? "ERROR" : "INFO")} - {message}";
        File.AppendAllText(logFilePath, logMessage + Environment.NewLine);
    }
}

public struct Record
{
    public int Value;
}

internal class RandomizedEqualityComparer : IEqualityComparer<int>
{
    private readonly HashSet<int> hashSet = new HashSet<int>();

    public bool Equals(int x, int y) => x == y;

    public int GetHashCode(int obj)
    {
        return (hashSet.Add(obj) ? 31 : 0) ^ obj.GetHashCode();
    }
}

public class Config
{
    public int OffsetCapacity { get; set; }
    public int InitialRecordCapacity { get; set; }
    public int ResizeThreshold { get; set; }
    public string LogFilePath { get; set; }
}
