// Memory pool structure
typedef struct {
    size_t block_size;
    void **free_list;
    size_t free_count;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t initial_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->free_count = initial_blocks;
    pool->free_list = calloc(pool->free_count, sizeof(void*));

    for (size_t i = 0; i < pool->free_count; ++i) {
        pool->free_list[i] = malloc(block_size);
        if (!pool->free_list[i]) {
            // Handle memory allocation failure
            while (i-- > 0) free(pool->free_list[i]);
            free(pool->free_list);
            free(pool);
            return NULL;
        }
    }

    return pool;
}

void* allocate_from_pool(MemoryPool *pool) {
    if (!pool || pool->free_count == 0) return NULL;

    void *block = pool->free_list[--pool->free_count];
    memset(block, 0, pool->block_size);
    return block;
}

void free_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->free_count; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    free(pool);
}

