    if (!*output) {
        fprintf(stderr, "Serialization failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(*output, data, size);
    *out_size = size;
}

// Deserialize data from a byte array
int deserialize_data(const unsigned char *input, size_t input_size, void *data, size_t data_size) {
    if (input_size != data_size) return 0;
    memcpy(data, input, data_size);
    return 1;
}
