import java.util.concurrent.CompletableFuture;
import java.util.logging.Logger;

class Event {
    long timestamp;
    String status;
    List<Float> metrics;

    public Event(long timestamp, String status, List<Float> metrics) {
        this.timestamp = timestamp;
        this.status = status;
        this.metrics = metrics;
    }
}

public class DataProcessor {

    private static final Logger logger = Logger.getLogger(DataProcessor.class.getName());
    private static final int DEFAULT_MAX_MEMORY = 1024 * 1024; // Default to 1MB

    public static void processData(String filePath, long maxMemorySize) {
        if (maxMemorySize <= 0) maxMemorySize = DEFAULT_MAX_MEMORY;

        try {
            Random random = new Random(System.currentTimeMillis());

            ByteBuffer buffer = ByteBuffer.allocateDirect((int) maxMemorySize).order(ByteOrder.nativeOrder());
            DataOutputStream dataOut = new DataOutputStream(new BufferedOutputStream(new FileOutputStream(filePath)));

            Map<String, String> keyValueMap = new HashMap<>();
            List<Float> floatList = new ArrayList<>();
            List<Event> events = new ArrayList<>();

            // Initialize structure
            try {
                for (int i = 0; i < 10; i++) { // Arbitrary number of items for example purposes
                    if (buffer.position() + Float.BYTES * 10 > maxMemorySize) throw new OutOfMemoryError("Exceeded memory limit");

                    floatList.add((float) random.nextFloat());
                }

                keyValueMap.put("exampleKey", "exampleValue");

                long eventTimestamp = System.currentTimeMillis();
                events.add(new Event(eventTimestamp, "status" + i, Arrays.asList(random.nextFloat(), random.nextFloat())));

            } catch (OutOfMemoryError e) {
                logger.severe("Out of memory: " + e.getMessage());
                return;
            }

            // Serialize data
            try {
                for (float f : floatList) {
                    buffer.putFloat(f);
                }
                for (Map.Entry<String, String> entry : keyValueMap.entrySet()) {
                    byte[] keyBytes = entry.getKey().getBytes();
                    byte[] valueBytes = entry.getValue().getBytes();
                    buffer.putInt(keyBytes.length).put(keyBytes);
                    buffer.putInt(valueBytes.length).put(valueBytes);
                }

                for (Event event : events) {
                    dataOut.writeLong(event.timestamp);
                    dataOut.writeUTF(event.status);

                    for (float metric : event.metrics) {
                        dataOut.writeFloat(metric);
                    }
                }

            } catch (IOException e) {
                logger.severe("Serialization error: " + e.getMessage());
            }

            // Process events using CompletableFuture
            CompletableFuture.runAsync(() -> {
                try {
                    for (Event event : events) {
                        // Dummy processing logic
                        logger.info("Processing event with timestamp: " + event.timestamp);
                    }
                } catch (Exception ex) {
                    logger.severe("Processing error: " + ex.getMessage());
                }
            }).exceptionally(ex -> {
                logger.severe("Completion stage exception: " + ex.getMessage());
                return null;
            });

        } finally {
            // Cleanup
            try {
                if (dataOut != null) dataOut.close();
            } catch (IOException e) {
                logger.warning("Failed to close output stream: " + e.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        processData("output.dat", 1024 * 512); // Example usage with 512KB
    }
}
