#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char *name;
    int id;
} Element;

void free_resources(double *doubles, char *bytes, Element *elements, size_t count) {
    if (doubles) free(doubles);
    if (bytes) free(bytes);
    for (size_t i = 0; i < count; ++i) {
        if (elements[i].name) free(elements[i].name);
    }
    if (elements) free(elements);
}

int load_configuration(const char *filename, double *coefficients, size_t coeff_count) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    for (size_t i = 0; i < coeff_count; ++i) {
        if (fscanf(file, "%lf", &coefficients[i]) != 1 || coefficients[i] < 0) {
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

double calculate_polynomial(size_t index, const double *coefficients, size_t coeff_count) {
    double result = 0.0;
    for (size_t i = 0; i < coeff_count; ++i) {
        result += coefficients[i] * pow(index, i);
    }
    return result;
}

int initialize_arrays(size_t count, double **doubles_out, char **bytes_out, Element **elements_out,
                      const char *config_file, size_t max_coefficients) {

    if (count == 0 || doubles_out == NULL || bytes_out == NULL || elements_out == NULL) {
        return -1;
    }

    // Allocate memory for arrays
    double *doubles = malloc(count * sizeof(double));
    char *bytes = malloc(count * sizeof(char));
    Element *elements = malloc(count * sizeof(Element));

    if (!doubles || !bytes || !elements) {
        free_resources(doubles, bytes, elements, count);
        return -1;
    }

    // Load configuration for polynomial coefficients
    double coefficients[max_coefficients];
    if (load_configuration(config_file, coefficients, max_coefficients) != 0) {
        free_resources(doubles, bytes, elements, count);
        return -1;
    }

    size_t coeff_count = max_coefficients;
    while (coeff_count > 0 && coefficients[coeff_count - 1] == 0.0) {
        --coeff_count; // Trim trailing zeros
    }

    for (size_t i = 0; i < count; ++i) {
        // Calculate polynomial values
        doubles[i] = calculate_polynomial(i, coefficients, coeff_count);

        // Allocate and initialize bytes array
        bytes[i] = 'A' + (i % 26); // Example: cycle through A-Z

        // Allocate and initialize elements struct's name field
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "Element_%zu", i);
        size_t name_len = strlen(buffer) + 1;
        elements[i].name = malloc(name_len);
        if (!elements[i].name) {
            free_resources(doubles, bytes, elements, count);
            return -1;
        }
        strcpy(elements[i].name, buffer);

        // Initialize other struct fields
        elements[i].value = doubles[i];
        elements[i].id = (int)i;
    }

    *doubles_out = doubles;
    *bytes_out = bytes;
    *elements_out = elements;

    return 0;
}

// Example usage
int main() {
    size_t count = 10000000; // Up to 10 million elements
    double *doubles = NULL;
    char *bytes = NULL;
    Element *elements = NULL;

    if (initialize_arrays(count, &doubles, &bytes, &elements, "config.txt", 5) == 0) {
        printf("Arrays initialized successfully!\n");

        // Free resources when done
        free_resources(doubles, bytes, elements, count);
    } else {
        fprintf(stderr, "Failed to initialize arrays.\n");
    }

    return 0;
}
