['Below is a Rust code implementation for the described directory management utility:

```rust
use std::env;
use std::fs::{self, DirBuilder};
use std::io;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};
use log::{error, info};
use rand::Rng;
use thiserror::Error;

#[derive(Debug, Error)]
enum DirectoryManagerError {
    #[error("IO error: {0}")]
    Io(#[from] io::Error),
    #[error("Failed to create directory after retries")]
    MaxRetriesExceeded,
}

const DEFAULT_RETRY_INTERVAL_MS: u64 = 100;
const DEFAULT_MAX_RETRIES: usize = 3;

struct DirectoryManager {
    max_retries: usize,
    retry_interval_ms: u64,
}

impl DirectoryManager {
    fn new() -> Self {
        let max_retries = env::var("MAX_RETRIES")
            .unwrap_or_else(|_| "3".to_string())
            .parse()
            .unwrap_or(DEFAULT_MAX_RETRIES);

        let retry_interval_ms = env::var("RETRY_INTERVAL_MS")
            .unwrap_or_else(|_| "100".to_string())
            .parse()
            .unwrap_or(DEFAULT_RETRY_INTERVAL_MS);

        DirectoryManager {
            max_retries,
            retry_interval_ms,
        }
    }

    fn create_directory(&self, dir_name: &str) -> Result<PathBuf, DirectoryManagerError> {
        let env_var = "MY_DIR_PATH";
        if let Ok(existing_path) = env::var(env_var) {
            info!("Using existing directory from environment variable: {}", existing_path);
            return Ok(PathBuf::from(existing_path));
        }

        let mut retries = 0;
        let start_time = Instant::now();

        loop {
            match self.create_dir_with_retry(dir_name, &env_var) {
                Ok(path) => {
                    info!(
                        "Directory created successfully in {:?}, attempts: {}",
                        start_time.elapsed(),
                        retries
                    );
                    return Ok(path);
                }
                Err(DirectoryManagerError::MaxRetriesExceeded) => {
                    error!("Failed to create directory after maximum retry attempts.");
                    self.cleanup_failed_directory(dir_name)?;
                    break;
                }
                Err(e) => {
                    error!("Attempt {} failed: {}", retries, e);
                }
            }

            let sleep_duration = Duration::from_millis(self.retry_interval_ms * 2u64.pow(retries as u32));
            std::thread::sleep(sleep_duration);

            if retries >= self.max_retries {
                break;
            }
            retries += 1;
        }

        Err(DirectoryManagerError::MaxRetriesExceeded)
    }

    fn create_dir_with_retry(&self, dir_name: &str, env_var: &str) -> Result<PathBuf, DirectoryManagerError> {
        for _ in 0..=self.max_retries {
            match self.create_directory_inner(dir_name, env_var) {
                Ok(path) => return Ok(path),
                Err(e) if e.is_transient() => continue,
                Err(e) => return Err(e),
            }
        }

        Err(DirectoryManagerError::MaxRetriesExceeded)
    }

    fn create_directory_inner(&self, dir_name: &str, env_var: &str) -> Result<PathBuf, DirectoryManagerError> {
        let path = Path::new(dir_name).canonicalize()?;
        if path.exists() {
            return Err(DirectoryManagerError::Io(io::Error::new(
                io::ErrorKind::AlreadyExists,
                "Directory already exists",
            )));
        }

        DirBuilder::new()
            .recursive(true)
            .create(&path)?;

        env::set_var(env_var, &path.to_string_lossy());

        Ok(path.into())
    }

    fn cleanup_failed_directory(&self, dir_name: &str) -> Result<(), DirectoryManagerError> {
        let path = Path::new(dir_name).canonicalize()?;
        if path.exists() {
            fs::remove_dir_all(&path)?;
        }
        Ok(())
    }
}

impl From<io::Error> for DirectoryManagerError {
    fn from(err: io::Error) -> Self {
        if err.kind().would_block() || err.kind() == io::ErrorKind::ConnectionRefused {
            DirectoryManagerError::Io(err)
        } else {
            DirectoryManagerError::Io(err)
        }
    }
}

trait TransientError {
    fn is_transient(&self) -> bool;
}

impl TransientError for io::Error {
    fn is_transient(&self) -> bool {
        matches!(self.kind(), io::ErrorKind::WouldBlock | io::ErrorKind::ConnectionRefused)
    }
}

fn main() {
    env_logger::init();

    let manager = DirectoryManager::new();
    match manager.create_directory("my_special/dir name") {
        Ok(path) => info!("Directory path: {:?}", path),
        Err(e) => error!("Failed to create directory: {}", e),
    }
}
```

This code provides a robust implementation of the directory management utility, handling concurrent access with exponential backoff retries, cleanup for failed attempts, and dynamic configuration through environment variables. The use of logging and error handling helps manage transient failures gracefully.']

['```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <chrono>

// Game state structure to manage player data.
struct game_state {
    int cooldown_timer;
};

const int MAX_PLAYERS = 100;
std::vector<game_state> players(MAX_PLAYERS);
std::mutex mtx; // Mutex for thread safety.

void initialize_game() {
    std::random_device rd;
    std::mt19937 gen(rd());

    // Initialize each player's cooldown timer to a random value within the range [5, 15].
    std::uniform_int_distribution<> dis(5, 15);
    for (auto &player : players) {
        player.cooldown_timer = dis(gen);
    }
}

void update_cooldowns() {
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(2));

        // Update cooldown timers and select attack based on weighted probability.
        for (int i = 0; i < MAX_PLAYERS; ++i) {
            {
                std::lock_guard<std::mutex> lock(mtx);
                if (--players[i].cooldown_timer <= 0) {
                    players[i].cooldown_timer = 10; // Reset to new random value within [5, 15].

                    // Randomly decide which attack to use based on weighted probability.
                    int weightA = 3;
                    int weightB = 2;

                    std::uniform_int_distribution<> dis(1, (weightA + weightB));
                    if (dis(rd) <= weightA) {
                        std::cout << "Player " << i << ": Attack A selected" << std::endl;
                    } else {
                        std::cout << "Player " << i << ": Attack B selected" << std::endl;
                    }
                }
            }
        }
    }
}

int main() {
    // Initialize game state.
    initialize_game();

    // Start a thread to handle cooldown updates.
    std::thread update_thread(update_cooldowns);

    // Join the thread (in practice, this could be managed differently for long-running applications).
    update_thread.join();

    return 0;
}
```

This code snippet sets up and periodically updates a game state system that manages character cooldown timers in a MOBA-style game. It uses multithreading to handle periodic updates every 2 seconds, ensuring thread safety with mutex locks while updating the cooldowns for each player's primary attack. The weighted probability mechanism selects between two attacks based on defined weights and prints the selected attack number to the console.']

