bool isPasswordComplex(const char *password) {
    bool has_upper = false, has_lower = false, has_digit = false, has_special = false;
    size_t len = strlen(password);

    if (len < 8) return false;

    for (size_t i = 0; i < len; ++i) {
        if (password[i] >= 'A' && password[i] <= 'Z') has_upper = true;
        else if (password[i] >= 'a' && password[i] <= 'z') has_lower = true;
        else if (password[i] >= '0' && password[i] <= '9') has_digit = true;
        else if ((password[i] >= 33 && password[i] <= 47) || 
                 (password[i] >= 58 && password[i] <= 64) ||
                 (password[i] >= 91 && password[i] <= 96) ||
                 (password[i] >= 123 && password[i] <= 126)) has_special = true;
    }

    return has_upper && has_lower && has_digit && has_special;
}

void logUpdateStatus(const char *message) {
    // Log the message to a file or console
    printf("%s\n", message);
}

void createAndDeleteSemaphore(sem_t *semaphore, unsigned int initial_value) {
    sem_init(semaphore, 0, initial_value);
    sem_destroy(semaphore);
}

PasswordManager initializePasswordManager(unsigned int initial_value) {
    PasswordManager manager;
    pthread_mutex_init(&manager.lock, NULL);
    sem_init(&manager.semaphore, 0, initial_value);
    return manager;
}

void cleanupPasswordManager(PasswordManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    sem_destroy(&manager->semaphore);
}

