    char username[50], new_password[50];

    printf("Enter username: ");
    scanf("%s", username);

    printf("Enter new password: ");
    scanf("%s", new_password);

    sem_wait(&manager->semaphore);
    pthread_mutex_lock(&manager->lock);

    if (isPasswordComplex(new_password)) {
        int result = updatePasswordInDB(username, new_password);
        if (result == 0) {
            logUpdateStatus("Password updated successfully for user.");
        } else {
            logUpdateStatus("Failed to update password for user.");
        }
    } else {
        logUpdateStatus("Password does not meet complexity requirements.");
    }

    pthread_mutex_unlock(&manager->lock);
    sem_post(&manager->semaphore);

    return NULL;
}

int main() {
    updateUserPassword();

    PasswordManager manager = initializePasswordManager(1);

    pthread_t threads[2];
    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, updateUserPasswordThread, &manager);
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanupPasswordManager(&manager);

    return 0;
}
