    static const float INITIAL_MAX_PRIORITY_THRESHOLD;

private:
    std::vector<long> offsetValues;
    std::vector<int> keys;
    std::vector<GameEvent> events;
    float maxPriorityThreshold;
    float currentTotalPriority;
    std::mutex mtx;
    std::atomic<bool> running{true};

public:
    GameManager() 
        : maxPriorityThreshold(INITIAL_MAX_PRIORITY_THRESHOLD), currentTotalPriority(0.0f) {}

