void GameManager::initializeArrays(size_t size, float minPriority, float maxPriority) {
    offsetValues.resize(size);
    keys.resize(size);

    for (auto& val : offsetValues) {
        val = generateRandomValue(1L, std::numeric_limits<long>::max());
    }

    for (auto& key : keys) {
        key = static_cast<int>(generateRandomValue(0.0f, 100.0f));
    }

    allocateEvents();
    updatePriorities(minPriority, maxPriority);
}

void GameManager::allocateEvents() {
    events.resize(MAX_EVENT_COUNT);

    for (size_t i = 0; i < MAX_EVENT_COUNT; ++i) {
        events[i].eventType = static_cast<int>(generateRandomValue(1.0f, 100.0f));
    }
}

void GameManager::updatePriorities(float minPriority, float maxPriority) {
    std::lock_guard<std::mutex> lock(mtx);
    currentTotalPriority = 0.0f;

    for (auto& event : events) {
        if (!running.load()) break;

        event.priority = generateRandomValue(minPriority, maxPriority);

        // Ensure total priority does not exceed the threshold.
        while ((currentTotalPriority + event.priority) > maxPriorityThreshold && running.load()) {
            event.priority *= 0.9f; // Reduce priority by 10% and recheck
        }

        currentTotalPriority += event.priority;
    }
}

