    // Adjust max threshold based on active events count.
    size_t activeEvents = std::count_if(events.begin(), events.end(),
                                        [](const GameEvent& e) { return e.priority > 0; });

    if (activeEvents < MAX_EVENT_COUNT / 2) {
        maxPriorityThreshold *= 1.05f;
    } else if (activeEvents > MAX_EVENT_COUNT / 2) {
        maxPriorityThreshold *= 0.95f;
    }
}

void GameManager::logEventFrequency() {
    static int eventCount = 0;

    // Log the number of events processed over time.
    eventCount++;
    std::cout << "Events processed: " << eventCount << std::endl;

    if (currentTotalPriority > maxPriorityThreshold) {
        std::cerr << "Warning: Priority sum exceeds threshold!" << std::endl;
    }
}

