    std::thread gameThread(&GameManager::run, &gameManager);

    // Simulate running for some time before stopping.
    std::this_thread::sleep_for(std::chrono::seconds(30));
    gameManager.stop();

    if (gameThread.joinable()) {
        gameThread.join();
    }

    return 0;
}
