#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    record **records;
    long *offsets;
    int *keys;
    void (*free_callback)(void *);
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity, void (*free_callback)(void *)) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    pthread_mutex_init(&manager->lock, NULL);

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->records = malloc(initial_capacity * sizeof(record *));
    manager->offsets = calloc(initial_capacity, sizeof(long));
    manager->keys = calloc(initial_capacity, sizeof(int));
    manager->free_callback = free_callback;

    return manager;
}

void destroy_record_manager(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        record *r = manager->records[i];
        if (r->offset_ptr) free(r->offset_ptr);
        if (r->key_ptr) free(r->key_ptr);
        manager->free_callback(r);
    }

    free(manager->records);
    free(manager->offsets);
    free(manager->keys);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(RecordManager *manager, int value, long offset, int key) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        record **new_records = realloc(manager->records, new_capacity * sizeof(record *));
        long *new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(manager->keys, new_capacity * sizeof(int));

        if (!new_records || !new_offsets || !new_keys) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->records = new_records;
        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->capacity = new_capacity;
    }

    record *r = malloc(sizeof(record));
    r->value = value;
    r->offset_ptr = &manager->offsets[manager->count];
    r->key_ptr = &manager->keys[manager->count];

    *(r->offset_ptr) = offset;
    *(r->key_ptr) = key;

    manager->records[manager->count++] = r;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int serialize_record_manager(const RecordManager *manager, const char *file_path) {
    pthread_mutex_lock((pthread_mutex_t *)&manager); // Lock the entire manager structure

    FILE *file = fopen(file_path, "wb");
    if (!file) {
        pthread_mutex_unlock(&manager);
        return -1; // File open failed
    }

    fwrite(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->count; ++i) {
        record *r = manager->records[i];
        fwrite(&(r->value), sizeof(int), 1, file);
        fwrite(r->offset_ptr, sizeof(long), 1, file);
        fwrite(r->key_ptr, sizeof(int), 1, file);
    }

    fclose(file);

    pthread_mutex_unlock(&manager);
    return 0; // Success
}

int deserialize_record_manager(RecordManager *manager, const char *file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        return -1; // File open failed
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    manager->capacity = count * 2;
    manager->records = realloc(manager->records, manager->capacity * sizeof(record *));
    manager->offsets = realloc(manager->offsets, manager->capacity * sizeof(long));
    manager->keys = realloc(manager->keys, manager->capacity * sizeof(int));

    if (!manager->records || !manager->offsets || !manager->keys) {
        fclose(file);
        pthread_mutex_unlock(&manager.lock);
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < count; ++i) {
        int value;
        long offset;
        int key;

        fread(&value, sizeof(int), 1, file);
        fread(&offset, sizeof(long), 1, file);
        fread(&key, sizeof(int), 1, file);

        record *r = malloc(sizeof(record));
        r->value = value;
        r->offset_ptr = &manager->offsets[i];
        r->key_ptr = &manager->keys[i];

        *(r->offset_ptr) = offset;
        *(r->key_ptr) = key;

        manager->records[manager->count++] = r;
    }

    pthread_mutex_unlock(&manager.lock);
    fclose(file);

    return 0; // Success
}

// Example callback to free record memory if needed
void custom_free_callback(void *record) {
    free(record);
}
