```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>

// Define record structure
typedef struct Record {
    int key;
    long offset;
    void *fields; // Pointer to dynamically allocated fields of varying types
    size_t field_size;
    struct Record* next;
} Record;

// Data structure for managing records
typedef struct {
    pthread_mutex_t lock;
    Record* head;
    size_t memory_allocated;
    size_t max_memory;
    pthread_t cleanup_thread;
    int active;
} RecordManager;

RecordManager manager;

void init_manager(size_t max_memory) {
    pthread_mutex_init(&manager.lock, NULL);
    manager.head = NULL;
    manager.memory_allocated = 0;
    manager.max_memory = max_memory;
    manager.active = 1;
}

void destroy_record(Record* record) {
    free(record->fields);
    free(record);
}

Record* find_record(int key) {
    pthread_mutex_lock(&manager.lock);
    Record *current = manager.head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&manager.lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager.lock);
    return NULL;
}

int insert_record(int key, long offset, void* fields, size_t field_size) {
    if (manager.memory_allocated + sizeof(Record) + field_size > manager.max_memory)
        return -1; // Memory limit reached

    Record *new_record = malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->fields = malloc(field_size);
    memcpy(new_record->fields, fields, field_size);
    new_record->field_size = field_size;
    new_record->next = NULL;

    pthread_mutex_lock(&manager.lock);
    if (manager.head == NULL) {
        manager.head = new_record;
    } else {
        Record *current = manager.head;
        while (current->next != NULL)
            current = current->next;
        current->next = new_record;
    }
    manager.memory_allocated += sizeof(Record) + field_size;
    pthread_mutex_unlock(&manager.lock);

    return 0;
}

int delete_record(int key) {
    pthread_mutex_lock(&manager.lock);
    Record *current = manager.head, *prev = NULL;

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&manager.lock);
        return -1; // Key not found
    }

    if (prev == NULL)
        manager.head = current->next;
    else
        prev->next = current->next;

    destroy_record(current);
    manager.memory_allocated -= sizeof(Record) + current->field_size;
    pthread_mutex_unlock(&manager.lock);

    return 0;
}

void cleanup_records() {
    // This function would periodically remove infrequently accessed records
    while (manager.active) {
        sleep(10); // Example period; adjust as needed

        pthread_mutex_lock(&manager.lock);
        Record *current = manager.head, *prev = NULL;

        // Example logic to remove the first record for simplicity
        if (current != NULL) {
            manager.head = current->next;
            destroy_record(current);
            manager.memory_allocated -= sizeof(Record) + current->field_size;
        }

        pthread_mutex_unlock(&manager.lock);
    }
}

void start_cleanup_thread() {
    pthread_create(&manager.cleanup_thread, NULL, (void *(*)(void *))cleanup_records, NULL);
}

void stop_cleanup_thread() {
    manager.active = 0;
    pthread_join(manager.cleanup_thread, NULL);
}

void serialize_to_file(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager.lock);
    Record *current = manager.head;

    while (current != NULL) {
        fwrite(&current->key, sizeof(current->key), 1, file);
        fwrite(&current->offset, sizeof(current->offset), 1, file);
        fwrite(&current->field_size, sizeof(current->field_size), 1, file);
        fwrite(current->fields, current->field_size, 1, file);

        current = current->next;
    }

    pthread_mutex_unlock(&manager.lock);
    fclose(file);
}

void deserialize_from_file(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    int key;
    long offset;
    size_t field_size;
    void *fields;

    pthread_mutex_lock(&manager.lock);

    while (fread(&key, sizeof(key), 1, file) == 1) {
        fread(&offset, sizeof(offset), 1, file);
        fread(&field_size, sizeof(field_size), 1, file);

        fields = malloc(field_size);
        fread(fields, field_size, 1, file);

        insert_record(key, offset, fields, field_size);
    }

    pthread_mutex_unlock(&manager.lock);
    fclose(file);
}

int main() {
    init_manager(1024 * 1024 * 10); // Example max memory limit: 10 MB
    start_cleanup_thread();

    int key = 1;
    long offset = 12345L;
    char data[] = "example";
    insert_record(key, offset, data, sizeof(data));

    serialize_to_file("records.dat");
    deserialize_from_file("records.dat");

    stop_cleanup_thread();
    return 0;
}
```

