} SensorArray;

// Function prototypes
void initialize_sensor_array(SensorArray* array, double stddev);
int resize_sensor_array(SensorArray* array);
double generate_gaussian(double mean, double stddev);
void serialize_data(const sensor_data* data, size_t count, unsigned char** serialized_data, size_t* serialized_size);
sensor_data* deserialize_data(const unsigned char* serialized_data, size_t serialized_size, size_t* deserialized_count);
void free_sensor_array(SensorArray* array);
int log_inconsistencies(const SensorArray* array);

// Function implementations

void initialize_sensor_array(SensorArray* array, double stddev) {
    srand((unsigned int)time(NULL));
    array->data = (sensor_data*)malloc(INITIAL_CAPACITY * sizeof(sensor_data));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->stddev = stddev;
}

int resize_sensor_array(SensorArray* array) {
    size_t new_capacity = array->capacity * 2;
    if ((array->data == NULL) || (new_capacity <= array->capacity)) return -1;

    sensor_data* temp = realloc(array->data, new_capacity * sizeof(sensor_data));
    if (!temp) {
        fprintf(stderr, "Memory reallocation failed\n");
        return -1;
    }
    array->data = temp;
    array->capacity = new_capacity;
    return 0;
}

double generate_gaussian(double mean, double stddev) {
    static double saved_stddev = NAN, saved_value;
    static int has_spare = 0;

    if (has_spare) {
        has_spare = 0;
        return saved_value * stddev + mean;
    }

    double u1, u2, s;
    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);

        s = u1 * u1 + u2 * u2;
    } while (s >= 1 || s == 0);

    double multiplier = sqrt(-2.0 * log(s) / s);
    saved_value = u2 * multiplier;

    has_spare = 1;
    return u1 * multiplier * stddev + mean;
}

void serialize_data(const sensor_data* data, size_t count, unsigned char** serialized_data, size_t* serialized_size) {
    // Calculate the total size needed for serialization
    *serialized_size = count * sizeof(sensor_data);
    *serialized_data = (unsigned char*)malloc(*serialized_size);
    if (!*serialized_data) {
        fprintf(stderr, "Serialization memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memcpy(*serialized_data, data, *serialized_size);
}

sensor_data* deserialize_data(const unsigned char* serialized_data, size_t serialized_size, size_t* deserialized_count) {
    if (serialized_size % sizeof(sensor_data) != 0) {
        fprintf(stderr, "Invalid serialized data size\n");
        return NULL;
    }

    *deserialized_count = serialized_size / sizeof(sensor_data);
    sensor_data* data = (sensor_data*)malloc(serialized_size);
    if (!data) {
        fprintf(stderr, "Deserialization memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memcpy(data, serialized_data, serialized_size);
    return data;
}

void free_sensor_array(SensorArray* array) {
    if (array->data) {
        free(array->data);
        array->data = NULL;
        array->capacity = 0;
        array->count = 0;
    }
}

int log_inconsistencies(const SensorArray* array) {
