    array->records = malloc(initial_capacity * sizeof(Record));
    if (!array->records) {
        log_message("Memory allocation failed for records");
        return -1;
    }
    array->capacity = initial_capacity;
    array->count = 0;

    log_message("Initialized record array successfully");
    return 0;
}

int resize_record_array(RecordArray *array) {
    pthread_mutex_lock(&array->lock);

    size_t new_capacity = array->capacity * 2;
    Record *new_records = realloc(array->records, new_capacity * sizeof(Record));
    if (!new_records) {
        log_message("Memory allocation failed during resize");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->records = new_records;
    array->capacity = new_capacity;

    log_message("Resized record array successfully");
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_record_array(RecordArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->records);
    pthread_mutex_destroy(&array->lock);

    log_message("Freed record array resources");
}

