    FILE *log_file = fopen("record_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void seed_random() {
    srand(time(NULL));
}

int add_record(RecordArray *array, int min_value, int max_value) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        if (resize_record_array(array) != 0) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    int sum = 0;
    for (size_t i = 0; i < array->count; ++i) {
        sum += array->records[i].value;
    }

    if (sum >= MAX_SUM_LIMIT) {
        pthread_mutex_unlock(&array->lock);
        log_message("Error: Maximum sum limit exceeded");
        return -1;
    }

    int value = rand() % (max_value - min_value + 1) + min_value;
    array->records[array->count].value = value;
    array->records[array->count].offset = array->count * sizeof(Record);
    array->count++;

    log_message("Added record successfully");
    pthread_mutex_unlock(&array->lock);
    return 0;
}

