        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        records[i].parent = i;
        records[i].rank = 0;
    }
}

int find(int x, record *elements) {
    if (x != elements[x].parent)
        elements[x].parent = find(elements[x].parent, elements);
    return elements[x].parent;
}

void union_sets(int root1, int root2, record *elements) {
    if (root1 == root2) return;

    if (elements[root1].rank > elements[root2].rank) {
        elements[root2].parent = root1;
    } else if (elements[root1].rank < elements[root2].rank) {
        elements[root1].parent = root2;
    } else {
        elements[root2].parent = root1;
        elements[root1].rank++;
    }
}

// Parallel Union-Find using multithreading
void parallel_union_find(record *records, size_t count) {
    pthread_t threads[4]; // Example: 4 threads for simplicity

    void* union_task(void* arg) {
        int start = *(int*)arg;
        int end = start + (count / 4);
        if (start == 3) end = count; // Ensure last thread covers remaining elements

        for (size_t i = start; i < end; ++i) {
            int root_i = find(i, records);
            for (size_t j = 0; j < count; ++j) {
                if (i != j && abs(records[i].value - records[j].value) <= 10) { // Example condition
                    int root_j = find(j, records);
                    union_sets(root_i, root_j, records);
                }
            }
        }
        return NULL;
    }

    int starts[4] = {0, count / 4, (count * 2) / 4, (count * 3) / 4};
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, union_task, &starts[i]);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }
}

