void serialize_data(const record *records, const long *offsets, const int *keys, size_t num_records, unsigned char **buffer, size_t *buffer_size) {
    size_t record_size = sizeof(record);
    *buffer_size = num_records * record_size;
    *buffer = (unsigned char *)malloc(*buffer_size);

    if (!*buffer) exit(EXIT_FAILURE);

    for (size_t i = 0; i < num_records; ++i) {
        memcpy((*buffer) + i * record_size, &records[i], sizeof(record));
    }
}

void deserialize_data(const unsigned char *buffer, size_t buffer_size, record **records, size_t *num_records) {
    size_t record_size = sizeof(record);
    *num_records = buffer_size / record_size;
    *records = (record *)malloc(buffer_size);

    if (!*records) exit(EXIT_FAILURE);

    memcpy(*records, buffer, buffer_size);
}

