} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} Entry;

unsigned long compute_checksum(const void *data, size_t size) {
    unsigned long checksum = 0;
    const unsigned char *ptr = (const unsigned char *) data;
    while (size--) {
        checksum += *ptr++;
    }
    return checksum;
}

void serialize_data(const Entry *entries, int count, uint8_t **output, size_t *output_size) {
    // Calculate serialized size
    *output_size = count * (sizeof(long) + sizeof(int) + sizeof(Record));
    *output = malloc(*output_size);

    if (*output == NULL) {
        perror("Failed to allocate memory for serialization");
        exit(EXIT_FAILURE);
    }

    uint8_t *ptr = *output;
    for (int i = 0; i < count; ++i) {
        memcpy(ptr, &entries[i].offset, sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &entries[i].key, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &entries[i].record.value, sizeof(Record));
        ptr += sizeof(Record);
    }
}

void deserialize_data(const uint8_t *input, size_t input_size, Entry **entries, int *count) {
    *count = input_size / (sizeof(long) + sizeof(int) + sizeof(Record));
    *entries = malloc(*count * sizeof(Entry));

    if (*entries == NULL) {
        perror("Failed to allocate memory for deserialization");
        exit(EXIT_FAILURE);
    }

    const uint8_t *ptr = input;
    for (int i = 0; i < *count; ++i) {
        memcpy(&(*entries)[i].offset, ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(&(*entries)[i].key, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&(*entries)[i].record.value, ptr, sizeof(Record));
        ptr += sizeof(Record);
    }
}

