    if (compressed_data == NULL) {
        perror("Failed to allocate memory for compression");
        exit(EXIT_FAILURE);
    }

    int result = compress(compressed_data, &compressed_size, size, size);

    if (result != Z_OK) {
        fprintf(stderr, "Compression failed\n");
        free(compressed_data);
        return NULL;
    }

    // Simulate data transmission/storage here
