void parse_config(const char *config_path, int *min_range, int *max_range, size_t *max_mem_size) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Error opening config file");
        exit(EXIT_FAILURE);
    }

    fscanf(file, "%d %d %zu", min_range, max_range, max_mem_size);
    fclose(file);
}

void free_memory(long *offsets, int *keys, record *records, unsigned char **serialized_data, size_t num_records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    if (serialized_data && *serialized_data) free(*serialized_data);
}

void serialize_data(record *records, long *offsets, unsigned char **serialized_data, size_t num_records) {
    size_t total_size = num_records * (sizeof(int) + sizeof(long));
    *serialized_data = malloc(total_size);
    if (!*serialized_data) {
        perror("Error allocating memory for serialized data");
        exit(EXIT_FAILURE);
    }

    unsigned char *ptr = *serialized_data;
    for (size_t i = 0; i < num_records; ++i) {
        int value = htobe32(records[i].value);
        long offset = htobe64(offsets[i]);
        memcpy(ptr, &value, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &offset, sizeof(long));
        ptr += sizeof(long);
    }
}

void deserialize_data(unsigned char *serialized_data, record *records, long *offsets, size_t num_records) {
    unsigned char *ptr = serialized_data;
    for (size_t i = 0; i < num_records; ++i) {
        int value;
        memcpy(&value, ptr, sizeof(int));
        records[i].value = be32toh(value);
        ptr += sizeof(int);

        long offset;
        memcpy(&offset, ptr, sizeof(long));
        offsets[i] = be64toh(offset);
        ptr += sizeof(long);
    }
}

void process_and_output_records(int argc, char *argv[]) {
    if (argc < 2) {
        usage();
        return;
    }

    const char *config_path = NULL;
