    size_t max_mem_size = SIZE_MAX;

    if (config_path) {
        parse_config(config_path, &min_range, &max_range, &max_mem_size);
    }

    srand(time(NULL));

    size_t num_records = 100; // Example number of records
    size_t record_size = sizeof(long) + sizeof(int);

