    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));
    unsigned char *serialized_data = NULL;

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free_memory(offsets, keys, records, &serialized_data, num_records);
        return;
    }

    size_t total_size = num_records * record_size + sizeof(unsigned char) * (num_records * (sizeof(int) + sizeof(long)));
    if (total_size > max_mem_size) {
        fprintf(stderr, "Memory allocation exceeds maximum limit\n");
        free_memory(offsets, keys, records, &serialized_data, num_records);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 1000000;
        keys[i] = min_range + rand() % (max_range - min_range + 1);
        records[i].value = keys[i];
        records[i].offset = offsets[i];
    }

    serialize_data(records, offsets, &serialized_data, num_records);

    if (output_file) {
