        fwrite(serialized_data, 1, num_records * (sizeof(int) + sizeof(long)), file);
        fclose(file);
    }

    record deserialized_records[num_records];
    long deserialized_offsets[num_records];

    deserialize_data(serialized_data, deserialized_records, deserialized_offsets, num_records);

    free_memory(offsets, keys, records, &serialized_data, num_records);
}

int main(int argc, char *argv[]) {
