['Below is a possible implementation of the described functionality. This code uses pthreads for concurrency, spinlocks for lock-free operations, and a basic logging mechanism.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define MAX_CONNECTIONS 10000
#define DEFAULT_TIMEOUT 30

typedef enum {
    RESOLVED,
    PENDING,
    FAILED,
    TIMED_OUT
} ConnectionState;

typedef struct DnsConnection {
    char *hostname;
    ConnectionState state;
    int timeout;
    u_char ip_address[16]; // Support for both IPv4 and IPv6 addresses
    pthread_spinlock_t lock;
    struct DnsConnection *next;
} DnsConnection;

typedef struct {
    DnsConnection *head;
    size_t current_size;
    size_t max_memory;
    pthread_spinlock_t pool_lock;
} DnsPool;

void log_event(const char *event) {
    printf("[LOG] %s\n", event);
}

DnsPool* create_dns_pool(size_t max_memory) {
    DnsPool *pool = (DnsPool *)malloc(sizeof(DnsPool));
    if (!pool) {
        perror("Failed to allocate memory for DNS pool");
        return NULL;
    }
    pthread_spin_init(&pool->pool_lock, 0);
    pool->head = NULL;
    pool->current_size = 0;
    pool->max_memory = max_memory;
    log_event("DNS Pool created.");
    return pool;
}

int dns_resolve(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        memcpy(ip_address, addr, p->ai_addrlen);
        break; // Use the first address found
    }

    freeaddrinfo(res);
    return 0;
}

int add_dns_connection(DnsPool *pool, const char *hostname, int timeout) {
    pthread_spin_lock(&pool->pool_lock);

    if (pool->current_size >= MAX_CONNECTIONS) {
        log_event("Max connections reached.");
        pthread_spin_unlock(&pool->pool_lock);
        return -1;
    }

    DnsConnection *conn = (DnsConnection *)malloc(sizeof(DnsConnection));
    if (!conn) {
        perror("Failed to allocate memory for DNS connection");
        pthread_spin_unlock(&pool->pool_lock);
        return -1;
    }

    conn->hostname = strdup(hostname);
    if (!conn->hostname) {
        free(conn);
        pthread_spin_unlock(&pool->pool_lock);
        return -1;
    }

    conn->state = PENDING;
    conn->timeout = timeout;
    pthread_spin_init(&conn->lock, 0);
    conn->next = pool->head;
    pool->head = conn;
    pool->current_size++;

    pthread_spin_unlock(&pool->pool_lock);
    log_event("DNS connection added.");
    return 0;
}

void cleanup_dns_pool(DnsPool *pool) {
    DnsConnection *curr, *tmp;

    pthread_spin_lock(&pool->pool_lock);

    curr = pool->head;
    while (curr) {
        tmp = curr;
        curr = curr->next;
        free(tmp->hostname);
        pthread_spin_destroy(&tmp->lock);
        free(tmp);
    }

    pthread_spin_unlock(&pool->pool_lock);
    pthread_spin_destroy(&pool->pool_lock);
    free(pool);
    log_event("DNS pool cleaned up.");
}

void* dns_resolver_thread(void *arg) {
    DnsConnection *conn = (DnsConnection *)arg;
    int result;

    pthread_spin_lock(&conn->lock);

    if (conn->state == PENDING) {
        conn->state = RESOLVED;
        result = dns_resolve(conn->hostname, conn->ip_address);
        if (result != 0) {
            conn->state = FAILED;
        }
    }

    pthread_spin_unlock(&conn->lock);
    return NULL;
}

void resolve_dns_connections(DnsPool *pool) {
    DnsConnection *curr;
    pthread_t threads[MAX_CONNECTIONS];

    pthread_spin_lock(&pool->pool_lock);

    curr = pool->head;
    int idx = 0;

    while (curr && idx < MAX_CONNECTIONS) {
        if (curr->state == PENDING) {
            pthread_create(&threads[idx++], NULL, dns_resolver_thread, curr);
        }
        curr = curr->next;
    }

    pthread_spin_unlock(&pool->pool_lock);

    for (int i = 0; i < idx; ++i) {
