#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <atomic>
#include <random>

class GameEngine {
public:
    GameEngine() : cooldownActive(false), lastAttackTime(std::chrono::steady_clock::now()) {}

    void processScoresAndSelectAttack() {
        std::vector<int> scores;
        readScoresFromStream(scores);

        int highestScoringPlayer = getHighestScoringPlayer(scores);
        int attackNumber = selectAttack();

        printResults(highestScoringPlayer, attackNumber);

        waitForCooldown();
    }

private:
    std::mutex mtx;
    std::condition_variable cv;
    std::priority_queue<int> scoreQueue;
    bool cooldownActive;
    std::chrono::steady_clock::time_point lastAttackTime;

    void readScoresFromStream(std::vector<int>& scores) {
        // Simulate reading from a network stream
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100);

        for (int i = 0; i < 10; ++i) { // Simulating 10 score reads
            scores.push_back(dis(gen));
        }

        {
            std::lock_guard<std::mutex> lock(mtx);
            for (const auto& score : scores) {
                scoreQueue.push(score);
            }
        }
    }

    int getHighestScoringPlayer(const std::vector<int>& scores) {
        int highestScore = 0;
        for (int score : scores) {
            if (score > highestScore) {
                highestScore = score;
            }
        }
        return highestScore;
    }

    int selectAttack() {
        static std::atomic<int> manaPoints(100);
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(1, 2);

        if (cooldownActive) {
            return -1; // Indicate cooldown
        }

        int attackChoice = dis(gen);
        manaPoints -= 10;

        {
            std::lock_guard<std::mutex> lock(mtx);
            cooldownActive = true;
            lastAttackTime = std::chrono::steady_clock::now();
        }

        return attackChoice;
    }

    void printResults(int highestScoringPlayer, int attackNumber) {
        if (attackNumber == -1) {
            std::cout << "Cooldown active. Cannot select an attack." << std::endl;
        } else {
            std::cout << "Highest Scoring Player: " << highestScoringPlayer
                      << ", Selected Attack: " << attackNumber << std::endl;
        }
    }

    void waitForCooldown() {
        std::unique_lock<std::mutex> lock(mtx);
        if (cooldownActive) {
            cv.wait_until(lock, lastAttackTime + std::chrono::seconds(9), [this] { return !cooldownActive; });
        }
        cooldownActive = false;
    }
};

void runGameEngine() {
    GameEngine engine;

    while (true) {
        engine.processScoresAndSelectAttack();
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate game loop delay
    }
}

int main() {
    std::thread gameThread(runGameEngine);
    gameThread.join();
    return 0;
}
