#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>

// Define record structure
typedef struct {
    int value;
    long offset;
    char identifier;
    bool statusFlag;
} Record;

// Function prototypes
void* initialize_data_structures(size_t max_size);
int serialize_data(void* data, size_t* serialized_size);
void deserialize_data(void* data, void** deserialized_data);
void free_allocated_memory(void* data);

typedef struct {
    int* offsets;
    char** keys;
    Record* records;
    char* metadata;
    bool* statusIndicators;
} DataStructures;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_data_structures(size_t max_size) {
    pthread_mutex_lock(&mutex);

    // Calculate memory requirements
    size_t offset_size = sizeof(int) * 5;
    size_t key_size = 5 * sizeof(char*);
    size_t record_size = 5 * sizeof(Record);
    size_t metadata_size = 256; // Assuming max metadata length
    size_t status_indicator_size = sizeof(bool) * 5;

    size_t total_size = offset_size + key_size + record_size + metadata_size + status_indicator_size;

    if (total_size > max_size) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Exceeds maximum allowed memory
    }

    DataStructures* data_structures = malloc(total_size);

    if (!data_structures) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Allocation failed
    }

    // Initialize structures with error checking
    data_structures->offsets = (int*)malloc(offset_size);
    data_structures->keys = (char**)malloc(key_size);
    data_structures->records = (Record*)malloc(record_size);
    data_structures->metadata = (char*)malloc(metadata_size);
    data_structures->statusIndicators = (bool*)malloc(status_indicator_size);

    if (!data_structures->offsets || !data_structures->keys || 
        !data_structures->records || !data_structures->metadata || 
        !data_structures->statusIndicators) {

        free_allocated_memory(data_structures);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize the metadata
    snprintf(data_structures->metadata, metadata_size, "Data records for transmission");

    // Example initialization
    for (int i = 0; i < 5; ++i) {
        data_structures->offsets[i] = i * 10;
        data_structures->keys[i] = strdup("key");
        data_structures->records[i].value = i;
        data_structures->records[i].offset = i * 1000;
        data_structures->records[i].identifier = 'A' + i;
        data_structures->records[i].statusFlag = (i % 2 == 0);
        data_structures->statusIndicators[i] = true;
    }

    pthread_mutex_unlock(&mutex);

    return data_structures;
}

int serialize_data(void* data, size_t* serialized_size) {
    DataStructures* ds = (DataStructures*)data;

    // Calculate the serialized size
    *serialized_size = 0; 
    *serialized_size += sizeof(int) * 5;
    *serialized_size += 5 * sizeof(char*);
    for (int i = 0; i < 5; ++i)
        *serialized_size += strlen(ds->keys[i]) + 1;
    *serialized_size += sizeof(Record) * 5;
    *serialized_size += strlen(ds->metadata) + 1;
    *serialized_size += sizeof(bool) * 5;

    char* buffer = malloc(*serialized_size);
    if (!buffer)
        return -1; // Allocation failed

    size_t offset = 0;

    memcpy(buffer + offset, ds->offsets, sizeof(int) * 5);
    offset += sizeof(int) * 5;

    for (int i = 0; i < 5; ++i) {
        memcpy(buffer + offset, ds->keys[i], strlen(ds->keys[i]) + 1);
        offset += strlen(ds->keys[i]) + 1;
    }

    memcpy(buffer + offset, ds->records, sizeof(Record) * 5);
    offset += sizeof(Record) * 5;

    memcpy(buffer + offset, ds->metadata, strlen(ds->metadata) + 1);
    offset += strlen(ds->metadata) + 1;

    memcpy(buffer + offset, ds->statusIndicators, sizeof(bool) * 5);

    // Convert to network byte order (endianness)
    for (int i = 0; i < 5; ++i) {
        ((int*)(buffer))[i] = htonl(((int*)ds->offsets)[i]);
        ((Record*)(buffer + offset - sizeof(Record)*5))[i].value = htonl(ds->records[i].value);
        ((Record*)(buffer + offset - sizeof(Record)*5))[i].offset = htonll(ds->records[i].offset);
    }

    return buffer;
}

void deserialize_data(void* data, void** deserialized_data) {
    char* buffer = (char*)data;
    DataStructures* ds = malloc(sizeof(DataStructures));

    size_t offset = 0;

    ds->offsets = (int*)malloc(5 * sizeof(int));
    memcpy(ds->offsets, buffer + offset, 5 * sizeof(int));
    for (int i = 0; i < 5; ++i)
        ((int*)(ds->offsets))[i] = ntohl(((int*)(buffer))[i]);

    offset += 5 * sizeof(int);

    ds->keys = (char**)malloc(5 * sizeof(char*));
    for (int i = 0; i < 5; ++i) {
        ds->keys[i] = strdup(buffer + offset);
        offset += strlen(ds->keys[i]) + 1;
    }

    ds->records = (Record*)malloc(5 * sizeof(Record));
    memcpy(ds->records, buffer + offset, 5 * sizeof(Record));
    for (int i = 0; i < 5; ++i) {
        ds->records[i].value = ntohl(((Record*)(buffer + offset - sizeof(Record)*5))[i].value);
        ds->records[i].offset = htonll(((Record*)(buffer + offset - sizeof(Record)*5))[i].offset);
    }

    offset += 5 * sizeof(Record);

    ds->metadata = (char*)malloc(strlen(buffer + offset) + 1);
    strcpy(ds->metadata, buffer + offset);
    offset += strlen(ds->metadata) + 1;

    ds->statusIndicators = (bool*)malloc(5 * sizeof(bool));
    memcpy(ds->statusIndicators, buffer + offset, 5 * sizeof(bool));

    *deserialized_data = ds;
}

void free_allocated_memory(void* data) {
    if (!data)
        return;

    DataStructures* ds = (DataStructures*)data;

    free(ds->offsets);
    for (int i = 0; i < 5; ++i)
        free(ds->keys[i]);
    free(ds->keys);
    free(ds->records);
    free(ds->metadata);
    free(ds->statusIndicators);

    free(ds);
}

// Example usage in a multi-threaded environment
void* thread_function(void* arg) {
    size_t max_size = 1024 * 1024; // Example max size
    void* data_structures = initialize_data_structures(max_size);

    if (!data_structures) {
        printf("Failed to allocate memory for data structures\n");
        return NULL;
    }

    size_t serialized_size;
    char* serialized_data = (char*)serialize_data(data_structures, &serialized_size);

    if (!serialized_data) {
        printf("Serialization failed\n");
        free_allocated_memory(data_structures);
        return NULL;
    }

    void* deserialized_data;
    deserialize_data(serialized_data, &deserialized_data);

    // Use the data...

    free(serialized_data);
    free_allocated_memory(deserialized_data);

    pthread_exit(NULL);
}

int main() {
    pthread_t thread1, thread2;

    pthread_create(&thread1, NULL, thread_function, NULL);
    pthread_create(&thread2, NULL, thread_function, NULL);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
