['Here's an implementation outline for the described C function that manages memory under dynamic and resource-constrained conditions. This solution assumes familiarity with some standard libraries such as `<stdio.h>`, `<stdlib.h>`, `<pthread.h>`, and a hypothetical external library for logging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_MEMORY_MB 128
#define MAX_TOTAL_INT_SUM 1000000

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    size_t offsets_size;
    int *keys;
    size_t keys_size;
    record **records;
    size_t records_count;
    size_t current_records_capacity;
} MemoryManager;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    FILE* log_file = fopen("memory_manager.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int calculate_memory_usage(size_t offsets_size, size_t keys_size, size_t records_capacity) {
    return sizeof(long) * offsets_size + sizeof(int) * keys_size + sizeof(record*) * records_capacity;
}

int initialize_memory(MemoryManager* mm, size_t initial_offsets, size_t initial_keys, size_t initial_records_capacity) {
    pthread_mutex_lock(&lock);

    size_t total_memory = calculate_memory_usage(initial_offsets, initial_keys, initial_records_capacity);
    if (total_memory > MAX_MEMORY_MB * 1024 * 1024) {
        log_message("Failed to initialize: Memory usage exceeds limit");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    mm->offsets = malloc(sizeof(long) * initial_offsets);
    mm->keys = malloc(sizeof(int) * initial_keys);
    mm->records = calloc(initial_records_capacity, sizeof(record*));

    if (!mm->offsets || !mm->keys || !mm->records) {
        log_message("Failed to allocate memory");
        free(mm->offsets);
        free(mm->keys);
        free(mm->records);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    mm->offsets_size = initial_offsets;
    mm->keys_size = initial_keys;
    mm->current_records_capacity = initial_records_capacity;
    mm->records_count = 0;

    log_message("Memory initialized successfully");

    pthread_mutex_unlock(&lock);
    return 0;
}

int resize_memory(MemoryManager* mm, size_t additional_records) {
    pthread_mutex_lock(&lock);

    if (mm->current_records_capacity + additional_records > MAX_MEMORY_MB * 1024 / sizeof(record*)) {
        log_message("Failed to resize: Memory usage would exceed limit");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    size_t new_capacity = mm->current_records_capacity + additional_records;
    record** new_records = realloc(mm->records, new_capacity * sizeof(record*));

    if (!new_records) {
        log_message("Failed to resize memory");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    mm->records = new_records;
    mm->current_records_capacity = new_capacity;

    log_message("Memory resized successfully");

    pthread_mutex_unlock(&lock);
    return 0;
}

void free_memory(MemoryManager* mm) {
    if (mm) {
        free(mm->offsets);
        free(mm->keys);
        free(mm->records);

        log_message("Memory freed successfully");
    }
}

// Example usage
int main() {
    MemoryManager manager = {0};

    int status = initialize_memory(&manager, 1000000, 500000, 20000);

    if (status == 0) {
        // Use the memory...

        // Resize if necessary
        if (resize_memory(&manager, 10000) != 0) {
            log_message("Warning: Memory resize failed");
        }
    } else {
        log_message("Initialization failed.");
    }

    free_memory(&manager);

    return 0;
}
