#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    int key;
    double value;
    char status;
} record;

typedef struct {
    record *records;
    long *offsets;
    int *keys;
    size_t num_records;
    pthread_mutex_t lock;
} RecordManager;

#define MAX_SIZE_LIMIT 10000000 // Example limit in bytes

// Error checking macro
#define CHECK_MEM(ptr) if (ptr == NULL) { fprintf(stderr, "Memory allocation failed\n"); exit(EXIT_FAILURE); }

void seed_rng() {
    srand(time(NULL));
}

record generate_random_record(int key_min, int key_max, double value_min, double value_max) {
    record rec;
    rec.key = rand() % (key_max - key_min + 1) + key_min;
    rec.value = value_min + ((double)rand() / RAND_MAX) * (value_max - value_min);
    rec.status = 'A' + (char)(rand() % 26); // Random letter A-Z
    return rec;
}

int can_allocate(size_t record_size, size_t num_records) {
    size_t total_size = sizeof(record) * num_records + 
                        sizeof(long) * num_records + 
                        sizeof(int) * num_records;
    return total_size <= MAX_SIZE_LIMIT;
}

RecordManager* init_record_manager(size_t num_records, int key_min, int key_max, double value_min, double value_max) {
    if (!can_allocate(sizeof(record), num_records)) {
        fprintf(stderr, "Exceeds maximum memory allocation limit\n");
        exit(EXIT_FAILURE);
    }

    RecordManager *manager = malloc(sizeof(RecordManager));
    CHECK_MEM(manager);

    manager->records = malloc(num_records * sizeof(record));
    CHECK_MEM(manager->records);

    manager->offsets = malloc(num_records * sizeof(long));
    CHECK_MEM(manager->offsets);

    manager->keys = malloc(num_records * sizeof(int));
    CHECK_MEM(manager->keys);

    manager->num_records = num_records;
    pthread_mutex_init(&manager->lock, NULL);

    seed_rng();

    for (size_t i = 0; i < num_records; ++i) {
        record rec = generate_random_record(key_min, key_max, value_min, value_max);
        manager->records[i] = rec;
        manager->keys[i] = rec.key;
        manager->offsets[i] = rand(); // Example offset generation
    }

    return manager;
}

void free_resources(RecordManager *manager) {
    if (manager) {
        free(manager->records);
        free(manager->offsets);
        free(manager->keys);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

// Serialization and deserialization functions
size_t serialize_data(const RecordManager* manager, uint8_t** buffer_out) {
    size_t record_size = sizeof(record);
    *buffer_out = malloc(manager->num_records * record_size);
    CHECK_MEM(*buffer_out);

    memcpy(*buffer_out, manager->records, manager->num_records * record_size);

    return manager->num_records * record_size;
}

void deserialize_data(const uint8_t* buffer_in, RecordManager** manager_out, size_t num_records) {
    *manager_out = init_record_manager(num_records, 0, INT_MAX, -DBL_MAX, DBL_MAX);
    memcpy((*manager_out)->records, buffer_in, num_records * sizeof(record));
}

// Thread-safe function to query by exact key
record* find_by_key(const RecordManager *manager, int key, size_t *result_count) {
    pthread_mutex_lock(&manager->lock);

    *result_count = 0;
    record *results = malloc(manager->num_records * sizeof(record));
    CHECK_MEM(results);

    for (size_t i = 0; i < manager->num_records; ++i) {
        if (manager->keys[i] == key) {
            results[(*result_count)++] = manager->records[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return *result_count > 0 ? results : NULL;
}

// Example range query function
record* range_query(const RecordManager *manager, int low_key, int high_key, size_t *result_count) {
    pthread_mutex_lock(&manager->lock);

    *result_count = 0;
    record *results = malloc(manager->num_records * sizeof(record));
    CHECK_MEM(results);

    for (size_t i = 0; i < manager->num_records; ++i) {
        if (manager->keys[i] >= low_key && manager->keys[i] <= high_key) {
            results[(*result_count)++] = manager->records[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return *result_count > 0 ? results : NULL;
}

int main() {
    // Example usage
    size_t num_records = 1000000; 
    RecordManager *manager = init_record_manager(num_records, 1, 100, -50.0, 50.0);

    uint8_t *serialized_data;
    size_t serialized_size = serialize_data(manager, &serialized_data);

    // Free the original resources before deserialization
    free_resources(manager);

    RecordManager *new_manager;
    deserialize_data(serialized_data, &new_manager, num_records);

    size_t result_count;
    record* found = find_by_key(new_manager, 42, &result_count);
    if (found) {
        printf("Found %zu records with key 42.\n", result_count);
        free(found);
    }

    // Free resources
    free_resources(new_manager);
    free(serialized_data);

    return 0;
}
```

This code provides the basic structure for managing, serializing, and querying a large dataset of `record` structures. It includes thread-safe access using mutexes and handles memory allocation with error checking. Serialization is simple byte-wise copying here but should be extended to handle endianness correctly for cross-platform compatibility. Adjustments may be necessary based on specific hardware or OS requirements.']

