#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    char sensor_type;
    double threshold_value;
    bool active_status;
} SensorMetadata;

typedef struct {
    float *sensor_readings;
    SensorMetadata *sensor_metadata;
    uint64_t *timestamps;
    size_t num_sensors;
    size_t max_size_bytes;
} SensorDataHandler;

void free_sensor_data(SensorDataHandler *handler) {
    if (handler->sensor_readings) free(handler->sensor_readings);
    if (handler->sensor_metadata) free(handler->sensor_metadata);
    if (handler->timestamps) free(handler->timestamps);
}

bool initialize_sensor_data(SensorDataHandler *handler, size_t num_sensors, size_t max_size_bytes) {
    size_t float_size = sizeof(float);
    size_t metadata_size = sizeof(SensorMetadata);
    size_t timestamp_size = sizeof(uint64_t);

    if (num_sensors == 0 || max_size_bytes < (float_size + metadata_size + timestamp_size) * num_sensors) {
        return false;
    }

    handler->sensor_readings = (float *)malloc(float_size * num_sensors);
    handler->sensor_metadata = (SensorMetadata *)malloc(metadata_size * num_sensors);
    handler->timestamps = (uint64_t *)malloc(timestamp_size * num_sensors);

    if (!handler->sensor_readings || !handler->sensor_metadata || !handler->timestamps) {
        free_sensor_data(handler);
        return false;
    }

    handler->num_sensors = num_sensors;
    handler->max_size_bytes = max_size_bytes;

    for (size_t i = 0; i < num_sensors; ++i) {
        handler->sensor_metadata[i].active_status = false;
    }

    return true;
}

void update_active_status(SensorDataHandler *handler) {
    for (size_t i = 0; i < handler->num_sensors; ++i) {
        handler->sensor_metadata[i].active_status =
            handler->sensor_readings[i] > handler->sensor_metadata[i].threshold_value;
    }
}

void serialize_data(const SensorDataHandler *handler, uint8_t **buffer, size_t *buffer_size) {
    size_t total_size = 3 * sizeof(uint64_t); // Metadata sizes
    total_size += handler->num_sensors * (sizeof(float) + sizeof(SensorMetadata) + sizeof(uint64_t));

    *buffer = (uint8_t *)malloc(total_size);
    if (!*buffer) return;

    uint8_t *ptr = *buffer;

    // Copy number of sensors
    memcpy(ptr, &(handler->num_sensors), sizeof(handler->num_sensors));
    ptr += sizeof(handler->num_sensors);

    // Copy sensor readings
    for (size_t i = 0; i < handler->num_sensors; ++i) {
        float reading = htonf(handler->sensor_readings[i]);
        memcpy(ptr, &reading, sizeof(float));
        ptr += sizeof(float);
    }

    // Copy metadata
    for (size_t i = 0; i < handler->num_sensors; ++i) {
        SensorMetadata meta;
        meta.sensor_type = handler->sensor_metadata[i].sensor_type;
        meta.threshold_value = htond(handler->sensor_metadata[i].threshold_value);
        meta.active_status = handler->sensor_metadata[i].active_status;

        memcpy(ptr, &meta, sizeof(meta));
        ptr += sizeof(meta);
    }

    // Copy timestamps
    for (size_t i = 0; i < handler->num_sensors; ++i) {
        uint64_t timestamp = htonll(handler->timestamps[i]);
        memcpy(ptr, &timestamp, sizeof(uint64_t));
        ptr += sizeof(uint64_t);
    }

    *buffer_size = total_size;
}

void deserialize_data(SensorDataHandler *handler, const uint8_t *buffer, size_t buffer_size) {
    size_t expected_size = 3 * sizeof(uint64_t); // Metadata sizes
    expected_size += handler->num_sensors * (sizeof(float) + sizeof(SensorMetadata) + sizeof(uint64_t));

    if (buffer_size != expected_size) return;

    const uint8_t *ptr = buffer;

    // Read number of sensors
    memcpy(&(handler->num_sensors), ptr, sizeof(handler->num_sensors));
    ptr += sizeof(handler->num_sensors);

    // Read sensor readings
    for (size_t i = 0; i < handler->num_sensors; ++i) {
        float reading;
        memcpy(&reading, ptr, sizeof(float));
        handler->sensor_readings[i] = ntohf(reading);
        ptr += sizeof(float);
    }

    // Read metadata
    for (size_t i = 0; i < handler->num_sensors; ++i) {
        SensorMetadata meta;
        memcpy(&meta, ptr, sizeof(meta));

        handler->sensor_metadata[i].sensor_type = meta.sensor_type;
        handler->sensor_metadata[i].threshold_value = ntohd(meta.threshold_value);
        handler->sensor_metadata[i].active_status = meta.active_status;

        ptr += sizeof(meta);
    }

    // Read timestamps
    for (size_t i = 0; i < handler->num_sensors; ++i) {
        uint64_t timestamp;
        memcpy(&timestamp, ptr, sizeof(uint64_t));
        handler->timestamps[i] = ntohll(timestamp);
        ptr += sizeof(uint64_t);
    }
}

float htonf(float host_float) {
    union { float f; uint32_t i; } source, dest;
    source.f = host_float;
    dest.i = htonl(source.i);
    return dest.f;
}

float ntohf(float net_float) {
    union { float f; uint32_t i; } source, dest;
    source.f = net_float;
    dest.i = ntohl(source.i);
    return dest.f;
}

double htond(double host_double) {
    union { double d; uint64_t i; } source, dest;
    source.d = host_double;
    dest.i = htonll(source.i);
    return dest.d;
}

double ntohd(double net_double) {
    union { double d; uint64_t i; } source, dest;
    source.d = net_double;
    dest.i = ntohll(source.i);
    return dest.d;
}

uint64_t htonll(uint64_t host_longlong) {
    static const int num = 42;
    if (*(char *)&num == 42) { /* little endian */
        uint32_t high_part = htonl((host_longlong >> 32) & 0xFFFFFFFF);
        uint32_t low_part = htonl(host_longlong & 0xFFFFFFFF);
        return ((uint64_t)low_part << 32) | high_part;
    } else { /* big endian */
        return host_longlong;
    }
}

uint64_t ntohll(uint64_t net_longlong) {
    static const int num = 42;
    if (*(char *)&num == 42) { /* little endian */
        uint32_t high_part = ntohl((net_longlong >> 32) & 0xFFFFFFFF);
        uint32_t low_part = ntohl(net_longlong & 0xFFFFFFFF);
        return ((uint64_t)low_part << 32) | high_part;
    } else { /* big endian */
        return net_longlong;
    }
}

int main() {
    SensorDataHandler handler;

    if (!initialize_sensor_data(&handler, 100, 1024 * 1024)) {
        fprintf(stderr, "Failed to initialize sensor data\n");
        return EXIT_FAILURE;
    }

    // Simulate updating and serializing
    update_active_status(&handler);

    uint8_t *serialized_data = NULL;
    size_t serialized_size = 0;

    serialize_data(&handler, &serialized_data, &serialized_size);
    if (serialized_data) {
        deserialize_data(&handler, serialized_data, serialized_size);
        free(serialized_data);
    }

    free_sensor_data(&handler);

    return EXIT_SUCCESS;
}
