['Here's a C implementation for managing a dynamic collection of records efficiently:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB

typedef struct {
    int key;
    long offset;
} record;

typedef struct {
    record *records;
    size_t count;
    size_t capacity;
    size_t total_memory_usage;
} RecordCollection;

// Function prototypes
RecordCollection* create_record_collection(size_t initial_capacity);
void free_record_collection(RecordCollection *collection);
int add_record(RecordCollection *collection, int key, long offset);
record* get_record_by_key(RecordCollection *collection, int key);
void log_memory_usage(const char *message);

// Helper functions
static void ensure_capacity(RecordCollection *collection, size_t additional_size);
static int is_unique_key(RecordCollection *collection, int key);

// Implementation
RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (record*)calloc(initial_capacity, sizeof(record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->total_memory_usage = sizeof(RecordCollection) + initial_capacity * sizeof(record);

    log_memory_usage("Initial allocation");

    return collection;
}

void ensure_capacity(RecordCollection *collection, size_t additional_size) {
    if (collection->count + additional_size > collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        while ((new_capacity - collection->count) < additional_size) {
            new_capacity *= 2;
        }

        record *new_records = (record*)realloc(collection->records, new_capacity * sizeof(record));
        if (!new_records) return;

        memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(record));

        collection->records = new_records;
        collection->capacity = new_capacity;
        collection->total_memory_usage += (new_capacity - collection->count) * sizeof(record);

        log_memory_usage("Reallocated to increase capacity");
    }
}

int is_unique_key(RecordCollection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return 0;
        }
    }
    return 1;
}

int add_record(RecordCollection *collection, int key, long offset) {
    if (!is_unique_key(collection, key)) {
        fprintf(stderr, "Error: Key %d is not unique.\n", key);
        return -1;
    }

    ensure_capacity(collection, 1);

    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;

    if (collection->total_memory_usage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Warning: Memory usage exceeded limit.\n");
    }

    ++(collection->count);
    return 0;
}

record* get_record_by_key(RecordCollection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return &collection->records[i];
        }
    }
    return NULL;
}

void free_record_collection(RecordCollection *collection) {
    if (!collection) return;

    free(collection->records);
    free(collection);

    log_memory_usage("Memory freed");
}

void log_memory_usage(const char *message) {
    printf("%s: Total memory usage is %zu bytes\n", message, collection->total_memory_usage);
}
```

### Key Features:
- **Dynamic Allocation**: Uses `calloc` and `realloc` to manage memory efficiently.
- **Capacity Management**: Doubles the capacity when needed to minimize reallocations.
- **Unique Keys**: Ensures each key is unique before adding a record.
- **Memory Usage Logging**: Logs memory usage after allocations and deallocations.
- **Error Handling**: Provides error messages for non-unique keys and excessive memory usage.']

