#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    long file_offset;
    int key;
    double probability;
} record;

// Function to initialize random number generator
void init_random() {
    srand((unsigned) time(NULL));
}

// Helper function to check for duplicate keys using a simple hash set approach
int has_duplicates(int *keys, size_t count) {
    if (count > 1000) { // Arbitrary threshold for using the hash set optimization
        int *hash_set = calloc(count, sizeof(int));
        if (!hash_set) return -1; // Allocation failure

        for (size_t i = 0; i < count; ++i) {
            if (keys[i] < 0 || keys[i] >= count) {
                free(hash_set);
                return 0; // Invalid key
            }
            if (hash_set[keys[i]]) {
                free(hash_set);
                return 1; // Duplicate found
            }
            hash_set[keys[i]] = 1;
        }

        free(hash_set);
        return 0;
    } else {
        for (size_t i = 0; i < count; ++i) {
            for (size_t j = i + 1; j < count; ++j) {
                if (keys[i] == keys[j]) {
                    return 1; // Duplicate found
                }
            }
        }
    }
    return 0;
}

// Function to allocate and initialize memory for records
record* create_records(int num_offsets, int *keys, size_t key_count, long *file_offsets) {
    if (num_offsets <= 0 || key_count == 0 || num_offsets != key_count) {
        return NULL; // Invalid input sizes
    }
    if (key_count > MAX_RECORDS) {
        return NULL; // Exceeds maximum records limit
    }

    // Check for duplicate keys
    if (has_duplicates(keys, key_count)) {
        return NULL;
    }

    // Allocate memory for file offsets and keys arrays
    long *file_offsets_array = malloc(num_offsets * sizeof(long));
    int *keys_array = malloc(key_count * sizeof(int));

    if (!file_offsets_array || !keys_array) {
        free(file_offsets_array);
        free(keys_array);
        return NULL;
    }

    // Copy data to allocated memory
    for (size_t i = 0; i < num_offsets; ++i) {
        file_offsets_array[i] = file_offsets[i];
        keys_array[i] = keys[i];
    }

    // Allocate memory for records array
    record *records = malloc(key_count * sizeof(record));
    if (!records) {
        free(file_offsets_array);
        free(keys_array);
        return NULL;
    }

    // Initialize records with provided data and random probabilities
    init_random();
    for (size_t i = 0; i < key_count; ++i) {
        records[i].file_offset = file_offsets_array[i];
        records[i].key = keys_array[i];
        records[i].probability = (double)rand() / RAND_MAX;
    }

    // Cleanup temporary allocations
    free(file_offsets_array);
    free(keys_array);

    return records;
}

// Function to free all allocated memory for records
void free_records(record *records) {
    if (records) {
        free(records);
    }
}

int main() {
    int keys[] = {1, 2, 3};
    long file_offsets[] = {100, 200, 300};

    record *records = create_records(3, keys, sizeof(keys)/sizeof(int), file_offsets);

    if (records) {
        for (size_t i = 0; i < 3; ++i) {
            printf("Record %zu: Offset=%ld, Key=%d, Probability=%.2f\n", 
                   i, records[i].file_offset, records[i].key, records[i].probability);
        }
        free_records(records);
    } else {
        fprintf(stderr, "Memory allocation failed or invalid input.\n");
    }

    return 0;
}
