#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <string.h>
#include <sys/mman.h>

#define MAX_RECORDS 10000
#define LOG_THRESHOLD_PERCENTAGE 80

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

// Assume this function is provided by the external logging library.
void log_warning(const char *message);

int get_system_max_memory() {
    // Example placeholder for system max memory retrieval
    return 8 * 1024 * 1024 * 1024; // Assuming 8 GB for example purposes
}

long long get_current_allocated_memory(RecordCollection *collection) {
    return (long long)(collection->capacity * sizeof(Record));
}

bool is_allocation_safe(size_t new_capacity, long long system_max_mem) {
    long long required_memory = (long long)new_capacity * sizeof(Record);
    return required_memory <= 0.8L * system_max_mem;
}

int resize_collection_if_needed(RecordCollection *collection, size_t additional_records, long long system_max_mem) {
    pthread_mutex_lock(&collection->lock);

    if ((collection->count + additional_records) > collection->capacity) {
        while (!is_allocation_safe(collection->capacity * 2, system_max_mem)) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Cannot allocate more memory safely
        }

        Record *new_records = realloc(collection->records, sizeof(Record) * collection->capacity * 2);
        if (new_records == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        memset(new_records + collection->capacity, 0, sizeof(Record) * collection->capacity); // Initialize new space
        collection->records = new_records;
        collection->capacity *= 2;

        if (get_current_allocated_memory(collection) > 0.8L * system_max_mem) {
            log_warning("Warning: Memory usage exceeded 80% of available system memory.");
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int initialize_collection(RecordCollection *collection, size_t num_records) {
    if (num_records > MAX_RECORDS) {
        return -1; // Invalid number of records requested
    }

    long long system_max_mem = get_system_max_memory();

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(sizeof(Record) * num_records);
    if (collection->records == NULL) {
        return -1;
    }

    collection->capacity = num_records;
    collection->count = 0;

    if (!is_allocation_safe(num_records, system_max_mem)) {
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        return -1; // Allocation not safe due to memory constraints
    }

    for (size_t i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (MAX_RECORDS * 2); // Ensure a wide range of keys
        } while (collection->count > 0 && find_key(collection, key));

        collection->records[collection->count].key = key;
        collection->records[collection->count++].offset = (long)rand();
    }

    return 0; // Success
}

bool find_key(RecordCollection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return true;
        }
    }
    return false;
}

void deallocate_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    free(collection->records);
    collection->records = NULL;
    collection->capacity = 0;
    collection->count = 0;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int main() {
    RecordCollection recordCollection = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

    if (initialize_collection(&recordCollection, 5000) != 0) {
        fprintf(stderr, "Failed to initialize the collection\n");
        return -1;
    }

    // Use the recordCollection in your application...

    deallocate_collection(&recordCollection);

    return 0;
}
```

