```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 512 * 1024 // 500 KB in bytes
#define RETRY_LIMIT 3

typedef struct {
    int key;
} record;

typedef struct node {
    record rec;
    struct node* next;
} node_t;

typedef struct {
    node_t* head;
    size_t count;
    pthread_mutex_t lock;
} hashtable_t;

// Function prototypes
int hash_function(int key, int table_size);
void initialize_hashtable(hashtable_t* ht, int table_size);
int add_record(hashtable_t* ht, record rec);
record* get_record(hashtable_t* ht, int key);
void free_hashtable(hashtable_t* ht);

// Memory pool management (simplified)
typedef struct {
    void* memory_pool;
    size_t total_size;
    size_t used_size;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t size) {
    memory_pool_t* pool = malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->memory_pool = malloc(size);
    pool->total_size = size;
    pool->used_size = 0;

    return pool;
}

void* allocate_from_pool(memory_pool_t* pool, size_t size) {
    if (size + pool->used_size > pool->total_size)
        return NULL; // No space left in the pool

    void* mem = (char*)pool->memory_pool + pool->used_size;
    pool->used_size += size;
    return mem;
}

void free_memory_pool(memory_pool_t* pool) {
    if (pool) {
        free(pool->memory_pool);
        free(pool);
    }
}

// Random number generation
int generate_random_key(int min, int max, hashtable_t* ht) {
    int key = rand() % (max - min + 1) + min;

    // Check for uniqueness and retry if necessary
    while (get_record(ht, key) != NULL) {
        key = rand() % (max - min + 1) + min;
    }

    return key;
}

// Hash table functions
int hash_function(int key, int table_size) {
    return key % table_size;
}

void initialize_hashtable(hashtable_t* ht, int table_size) {
    ht->head = calloc(table_size, sizeof(node_t));
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
}

int add_record(hashtable_t* ht, record rec) {
    pthread_mutex_lock(&ht->lock);

    int index = hash_function(rec.key, ht->count + 1);
    node_t* current = ht->head[index].next;

    while (current) {
        if (current->rec.key == rec.key) {
            pthread_mutex_unlock(&ht->lock);
            return -1; // Key already exists
        }
        current = current->next;
    }

    node_t* new_node = (node_t*)allocate_from_pool(memory_pool, sizeof(node_t));
    if (!new_node) {
        pthread_mutex_unlock(&ht->lock);
        return -2; // Memory allocation failed
    }

    memcpy(&new_node->rec, &rec, sizeof(record));
    new_node->next = ht->head[index].next;
    ht->head[index].next = new_node;

    ht->count++;
    pthread_mutex_unlock(&ht->lock);
    return 0; // Success
}

record* get_record(hashtable_t* ht, int key) {
    int index = hash_function(key, ht->count + 1);
    node_t* current = ht->head[index].next;

    while (current) {
        if (current->rec.key == key)
            return &current->rec;
        current = current->next;
    }
    return NULL; // Not found
}

void free_hashtable(hashtable_t* ht) {
    for (int i = 0; i < ht->count + 1; ++i) {
        node_t* current = ht->head[i].next;
        while (current) {
            node_t* temp = current;
            current = current->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht->head);
}

// Main function to create and manage records
void create_records(int min, int max, int max_records) {
    srand(time(NULL));

    memory_pool_t* pool = create_memory_pool(MAX_MEMORY_USAGE);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return;
    }

    hashtable_t ht;
    initialize_hashtable(&ht, 100); // Assuming a hash table size of 100

    for (int i = 0; i < max_records; ++i) {
        int key = generate_random_key(min, max, &ht);

        record rec = {key};
        if (add_record(&ht, rec) != 0) {
            fprintf(stderr, "Failed to add record\n");
            break;
        }
    }

    // Example: Retrieve a record
    int test_key = rand() % (max - min + 1) + min;
    record* retrieved = get_record(&ht, test_key);
    if (retrieved)
        printf("Retrieved Record Key: %d\n", retrieved->key);

    free_hashtable(&ht);
    free_memory_pool(pool);
}

int main() {
    create_records(0, 10000, 50); // Example call with specific range and record count
    return 0;
}
```

