// Define a structure for config data
typedef struct {
    double performance_metric;
    time_t timestamp;
    char *config_name;
} Config;

// Function to hash a performance metric
unsigned long hash_performance_metric(double value) {
    // Simple hash function (for illustration; use more secure in real-world)
    unsigned long hash = 5381;
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%lf", value);
    for (const char *p = buffer; *p != '\0'; p++) {
        hash = ((hash << 5) + hash) + (*p); // hash * 33 + c
    }
    return hash;
}

// Helper function to generate a random string
char* generate_random_string(size_t length, const char *charset) {
    char *random_string = malloc(length + 1);
    if (!random_string) return NULL;

    for (size_t i = 0; i < length; i++) {
        size_t index = rand() % strlen(charset);
        random_string[i] = charset[index];
    }
    random_string[length] = '\0';

    return random_string;
}

// Function to read floating-point numbers and find the maximum
void find_max_floating_point_number() {
    double *numbers = NULL;
    size_t capacity = 10, count = 0;

    printf("Enter floating-point numbers (type 'end' to finish):\n");

    while (1) {
        char input[64];
        if (!fgets(input, sizeof(input), stdin)) break;

        if (strncmp(input, "end", 3) == 0) break;

        double number;
        if (sscanf(input, "%lf", &number) != 1) continue;

        if (count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(double));
            if (!numbers) {
                perror("Failed to reallocate memory");
                exit(EXIT_FAILURE);
            }
        }

        numbers[count++] = number;
    }

    double max_value = -1e308; // Smallest possible double value
    for (size_t i = 0; i < count; ++i) {
        if (numbers[i] > max_value) {
            max_value = numbers[i];
        }
    }

    printf("Maximum floating-point number: %f\n", max_value);

    free(numbers);
}

