    size_t config_struct_size = sizeof(double) + sizeof(time_t) + sizeof(char*);
    size_t name_buffer_size = 32; // Assume a fixed buffer for simplicity
    size_t total_size_per_config = config_struct_size + name_buffer_size;

    if (total_size_per_config * num_configs > max_size) {
        fprintf(stderr, "Error: Not enough memory to allocate requested number of configs\n");
        return NULL;
    }

    Config *configs = malloc(num_configs * sizeof(Config));
    if (!configs) {
        perror("Failed to allocate memory for config structures");
        return NULL;
    }

    for (size_t i = 0; i < num_configs; ++i) {
        Config *config = &configs[i];

        // Allocate and initialize the name buffer
        char *name_buffer = malloc(name_buffer_size);
        if (!name_buffer) {
            perror("Failed to allocate memory for config name");
            free(configs);
            return NULL;
        }
        snprintf(name_buffer, name_buffer_size, "Config_%zu", i);

        // Assign values to the config
        double rand_value = min_range + ((double)rand() / RAND_MAX) * (max_range - min_range);
        config->performance_metric = rand_value;
        config->timestamp = time(NULL);
        config->config_name = name_buffer;

        unsigned long hash = hash_performance_metric(rand_value);

        // Log the allocation and serialized data
        printf("Allocated Config %zu: Name=%s, Metric=%.2f, Timestamp=%ld, Hash=0x%lx\n", i, config->config_name, rand_value, (long)config->timestamp, hash);
    }

    return configs;
}

// Function to serialize Config structures into a byte array
size_t serialize_configs(const Config *configs, size_t num_configs, uint8_t **buffer) {
    if (!configs || !num_configs || !buffer) return 0;

    size_t buffer_size = num_configs * (sizeof(double) + sizeof(time_t) + sizeof(char*) + 32); // Name buffer
    *buffer = malloc(buffer_size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization");
        return 0;
    }

    uint8_t *ptr = *buffer;
    for (size_t i = 0; i < num_configs; ++i) {
        const Config *config = &configs[i];

        // Serialize double
        memcpy(ptr, &config->performance_metric, sizeof(double));
        ptr += sizeof(double);

        // Serialize time_t
        memcpy(ptr, &config->timestamp, sizeof(time_t));
        ptr += sizeof(time_t);

        // Serialize char* (assume fixed length name buffer for simplicity)
        memcpy(ptr, config->config_name, 32);
        ptr += 32;
    }

    return buffer_size;
}

// Function to deserialize byte array back into Config structures
Config* deserialize_configs(const uint8_t *buffer, size_t buffer_size, size_t *num_configs) {
    if (!buffer || !buffer_size || !num_configs) return NULL;

    *num_configs = buffer_size / (sizeof(double) + sizeof(time_t) + 32);
    Config *configs = malloc(*num_configs * sizeof(Config));
    if (!configs) {
        perror("Failed to allocate memory for deserialized configs");
        return NULL;
    }

    const uint8_t *ptr = buffer;
    for (size_t i = 0; i < *num_configs; ++i) {
        Config *config = &configs[i];

        // Deserialize double
        memcpy(&config->performance_metric, ptr, sizeof(double));
        ptr += sizeof(double);

        // Deserialize time_t
        memcpy(&config->timestamp, ptr, sizeof(time_t));
        ptr += sizeof(time_t);

        // Deserialize char* (assume fixed length name buffer for simplicity)
        config->config_name = malloc(32);
        if (!config->config_name) {
            perror("Failed to allocate memory for config name");
            free(configs);
            return NULL;
        }
        memcpy(config->config_name, ptr, 32);
        ptr += 32;
    }

    return configs;
}

int main() {
    // Example usage
    size_t num_configs = 5;
    size_t max_size = 1024 * 1024; // 1 MB
    double min_range = 0.0;
    double max_range = 100.0;

    Config *configs = init_configs(num_configs, max_size, min_range, max_range);
    if (!configs) {
        fprintf(stderr, "Failed to initialize configs\n");
        return EXIT_FAILURE;
    }

    uint8_t *serialized_data = NULL;
    size_t serialized_size = serialize_configs(configs, num_configs, &serialized_data);

    size_t deserialized_count = 0;
    Config *deserialized_configs = deserialize_configs(serialized_data, serialized_size, &deserialized_count);

    find_max_floating_point_number();

    // Free allocated resources
    for (size_t i = 0; i < num_configs; ++i) {
        free(configs[i].config_name);
    }
    free(configs);

    if (serialized_data) free(serialized_data);

    if (deserialized_configs) {
        for (size_t i = 0; i < deserialized_count; ++i) {
            free(deserialized_configs[i].config_name);
        }
        free(deserialized_configs);
    }

    return EXIT_SUCCESS;
}
