#define CHARSET "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

typedef struct {
    int value;
    long offset;
    char random_string[STRING_LENGTH + 1];
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Record *records = NULL;
size_t allocated_memory = 0;

void log_event(const char *message) {
    FILE *log_file = fopen("program.log", "a");
    if (log_file == NULL) return;

    time_t now = time(NULL);
    fprintf(log_file, "[%s] %s\n", ctime(&now), message);
    fclose(log_file);
}

void* generate_random_string(char *str, size_t length) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < length; ++i) {
        str[i] = CHARSET[rand() % strlen(CHARSET)];
    }
    str[length] = '\0';
}

void serialize_records(unsigned char **byte_array, size_t *size) {
    size_t record_size = sizeof(int) + sizeof(long) + STRING_LENGTH + 1;
    *size = RECORD_COUNT * record_size;

    if (*byte_array == NULL) {
        *byte_array = malloc(*size);
        if (*byte_array == NULL) {
            log_event("Memory allocation failure during serialization.");
            return;
        }
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < RECORD_COUNT; ++i) {
        unsigned char *ptr = *byte_array + i * record_size;
        memcpy(ptr, &records[i].value, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &records[i].offset, sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, records[i].random_string, STRING_LENGTH + 1);
    }
    pthread_mutex_unlock(&lock);
}

void deserialize_records(unsigned char *byte_array) {
    size_t record_size = sizeof(int) + sizeof(long) + STRING_LENGTH + 1;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < RECORD_COUNT; ++i) {
        unsigned char *ptr = byte_array + i * record_size;
        memcpy(&records[i].value, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&records[i].offset, ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(records[i].random_string, ptr, STRING_LENGTH + 1);
    }
    pthread_mutex_unlock(&lock);
}

void initialize_records() {
    if (allocated_memory > MAX_MEMORY) {
        log_event("Memory limit exceeded.");
        return;
    }

    records = malloc(RECORD_COUNT * sizeof(Record));
    if (!records) {
        log_event("Memory allocation failure during initialization.");
        return;
    }
    allocated_memory += RECORD_COUNT * sizeof(Record);

    for (int i = 0; i < RECORD_COUNT; ++i) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % 1000;
        records[i].offset = rand() % 100000;
        generate_random_string(records[i].random_string, STRING_LENGTH);
        pthread_mutex_unlock(&lock);
    }
}

int* read_integers(int *count) {
    int *numbers = NULL;
    size_t capacity = 10;
    numbers = malloc(capacity * sizeof(int));
    if (!numbers) {
        log_event("Memory allocation failure during integer input.");
        return NULL;
    }

    int num, largest = INT_MIN;
    *count = 0;

    while (scanf("%d", &num) == 1) {
        if (*count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                log_event("Memory reallocation failure during integer input.");
                return NULL;
            }
        }

        numbers[(*count)++] = num;
        if (num > largest) largest = num;
    }

    return numbers;
}

void* thread_function(void *arg) {
    int index = *(int *)arg;
    free(arg);

    pthread_mutex_lock(&lock);
    records[index].value += 1;
    records[index].offset += 1000;
    generate_random_string(records[index].random_string, STRING_LENGTH);
    pthread_mutex_unlock(&lock);

    return NULL;
}

void run_threads() {
    pthread_t threads[RECORD_COUNT];
    for (int i = 0; i < RECORD_COUNT; ++i) {
        int *index = malloc(sizeof(int));
        if (!index) continue;
        *index = i;

        if (pthread_create(&threads[i], NULL, thread_function, index) != 0) {
            log_event("Thread creation failure.");
        }
    }

    for (int i = 0; i < RECORD_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    initialize_records();

    int count;
    int *numbers = read_integers(&count);

    if (numbers) {
        int largest_number = numbers[0];
        for (int i = 1; i < count; ++i) {
            if (numbers[i] > largest_number)
                largest_number = numbers[i];
        }
        printf("Largest number: %d\n", largest_number);
        free(numbers);
    }

    run_threads();

    unsigned char *byte_array;
    size_t size;
    serialize_records(&byte_array, &size);

    if (byte_array) {
        deserialize_records(byte_array);
        free(byte_array);
    }

    pthread_mutex_destroy(&lock);
    free(records);

    return 0;
}
