        fprintf(stderr, "Invalid number of measurements: %d\n", num_measurements);
        return -1;
    }

    pthread_mutex_lock(&mutex);

    *measurements = malloc(num_measurements * sizeof(measurement));
    if (*measurements == NULL) {
        perror("Failed to allocate memory for measurements");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_measurements; ++i) {
        long random_timestamp = TIMESTAMP_MIN + rand() % (TIMESTAMP_MAX - TIMESTAMP_MIN + 1);
        float random_reading = (float)(rand() % 100) / 10.0; // Example sensor reading

        (*measurements)[i].timestamp = random_timestamp;
        (*measurements)[i].reading = random_reading;

        // Simulate network delay or failure handling
        if ((i % 50 == 0)) {
            printf("Simulating network delay...\n");
            usleep(100000); // Sleep for 100ms to simulate delay
        }
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

