// Function to create and initialize an array of weather stations.
WeatherStation* create_weather_stations(int num_stations, int num_days, double temp_min, double temp_max) {
    if (num_stations <= 0 || num_days <= 0 || temp_min > temp_max) {
        return NULL;
    }

    WeatherStation *stations = malloc(num_stations * sizeof(WeatherStation));
    if (!stations) {
        perror("Failed to allocate memory for weather stations");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < num_stations; ++i) {
        stations[i].id = i + 1;  // Avoid zero or negative identifiers
        stations[i].latitude = rand() % 180 - 90.0;
        stations[i].longitude = rand() % 360 - 180.0;

        stations[i].daily_temps = malloc(num_days * sizeof(double));
        if (!stations[i].daily_temps) {
            fprintf(stderr, "Failed to allocate memory for daily temperatures.\n");
            free_weather_stations(stations, i);
            return NULL;
        }

        if (!initialize_temperatures(stations[i].daily_temps, num_days, temp_min, temp_max)) {
            fprintf(stderr, "Failed to initialize temperatures for station %d\n", stations[i].id);
            free(stations[i].daily_temps);
            free_weather_stations(stations, i + 1);
            return NULL;
        }
    }

    return stations;
}

// Function to release memory used by the weather stations.
void free_weather_stations(WeatherStation *stations, int num_stations) {
    if (stations) {
        for (int i = 0; i < num_stations; ++i) {
            free(stations[i].daily_temps);
        }
        free(stations);
    }
}

// Function to initialize temperatures with random values within a specified range.
int initialize_temperatures(double *temps, int num_days, double min, double max) {
    if (!temps || num_days <= 0) return 0;

    for (int i = 0; i < num_days; ++i) {
        temps[i] = ((double)rand() / RAND_MAX) * (max - min) + min;
    }
    return 1;
}
