// Helper functions
uint64_t htonll(uint64_t value) {
    static const int num = 42;
    if (*(const char *)&num == 42)
        return (value << 56) | ((value & 0x00FFFFFFFFFFFFFFULL) << 40) |
               ((value & 0x0000FFFFFFFFFF00ULL) << 24) |
               ((value & 0x00000000FF00FF00ULL) << 8) |
               ((value >> 56) & 0xFF) | ((value >> 40) & 0x00FF) |
               ((value >> 24) & 0xFF00) | ((value >> 8) & 0xFF0000);
    else
        return (value << 40) | ((value & 0xFFFF000000000000ULL) << 48) |
               ((value & 0x0000FF0000000000ULL) << 24) |
               ((value & 0x00000000FF000000ULL) << 8) |
               ((value >> 40) & 0xFFFF) | ((value >> 24) & 0xFF00) |
               ((value >> 8) & 0xFFFFFF00);
}

uint64_t ntohll(uint64_t value) {
    return htonll(value);
}
