typedef struct {
    int job_id;
    short priority_level;
    time_t start_timestamp;
} Task;

// Function to generate a unique task identifier
uint32_t generate_task_identifier(int job_id, short priority_level) {
    uint32_t seed = (job_id << 16) | (priority_level & 0xFFFF);
    srand((unsigned int)time(NULL));
    return seed + rand() % 10000; // Ensures variability and uniqueness
}

// Function to dynamically allocate memory for tasks
Task* initialize_tasks(size_t max_size, size_t task_count, char **serialized_data, size_t *data_length) {
    if (task_count * sizeof(Task) > max_size) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    Task *tasks = (Task *)malloc(task_count * sizeof(Task));
    if (!tasks) {
        perror("Failed to allocate memory for tasks");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < task_count; ++i) {
        tasks[i].job_id = rand() % 10000;
        tasks[i].priority_level = rand() % 256;
        tasks[i].start_timestamp = time(NULL);
    }

    // Serialize data
    *data_length = task_count * sizeof(Task);
    *serialized_data = (char *)malloc(*data_length);
    if (!*serialized_data) {
        perror("Failed to allocate memory for serialized data");
        free(tasks);
        return NULL;
    }
    memcpy(*serialized_data, tasks, *data_length);

    return tasks;
}

// Function to deserialize task data
Task* deserialize_tasks(const char *data, size_t length, size_t *task_count) {
    if (!data || length % sizeof(Task) != 0) {
        fprintf(stderr, "Invalid serialized data\n");
        return NULL;
    }

    *task_count = length / sizeof(Task);
    Task *tasks = (Task *)malloc(length);
    if (!tasks) {
        perror("Failed to allocate memory for deserialized tasks");
        return NULL;
    }
    memcpy(tasks, data, length);

    return tasks;
}

// Function to find and print the highest priority job
void find_highest_priority_task(Task *tasks, size_t task_count) {
    if (task_count == 0) {
        printf("No tasks available\n");
        return;
    }

    Task highest_priority = tasks[0];
    for (size_t i = 1; i < task_count; ++i) {
        if (tasks[i].priority_level > highest_priority.priority_level) {
            highest_priority = tasks[i];
        }
    }

    printf("Highest Priority Job ID: %d, Priority Level: %d\n",
           highest_priority.job_id, highest_priority.priority_level);
}

// Function to free allocated memory
void free_resources(Task *tasks, char *serialized_data) {
    if (tasks) free(tasks);
    if (serialized_data) free(serialized_data);
}

int main() {
    size_t max_size = 1024; // Example maximum size limit
    size_t task_count;
    Task *tasks = initialize_tasks(max_size, 10, NULL, &task_count);

    if (!tasks) return EXIT_FAILURE;

    char *serialized_data = NULL;
    size_t data_length = 0;
    tasks = initialize_tasks(max_size, 10, &serialized_data, &data_length);
    if (!tasks) {
        free_resources(NULL, serialized_data);
        return EXIT_FAILURE;
    }

    find_highest_priority_task(tasks, task_count);

    Task *deserialized_tasks = NULL;
    size_t deserialized_count;
    deserialized_tasks = deserialize_tasks(serialized_data, data_length, &deserialized_count);
    if (deserialized_tasks) {
        // Use deserialized tasks as needed
        free(deserialized_tasks);
    }

    free_resources(tasks, serialized_data);

    return EXIT_SUCCESS;
}
