// Define a record structure
typedef struct Record {
    int key;
    long value;
    struct Record* next;
} Record;

// Define the linked list structure with head pointer and lock for thread safety
typedef struct {
    Record* head;
    pthread_mutex_t mutex;
    size_t size;
} RecordList;

// Function to initialize a new record list
RecordList* init_record_list() {
    RecordList* list = malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    return list;
}

// Function to generate a unique random key within the specified range
int generate_unique_key(RecordList* list, int min, int max) {
    int key;
    do {
        key = rand() % (max - min + 1) + min;
    } while (!is_key_unique(list, key));
    return key;
}

// Helper function to check if a key is unique in the list
int is_key_unique(RecordList* list, int key) {
    pthread_mutex_lock(&list->mutex);
    Record* current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&list->mutex);
            return 0; // Key is not unique
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return 1; // Key is unique
}

// Function to add a record with a random value within the specified range
int add_record(RecordList* list, int min_value, int max_value) {
    pthread_mutex_lock(&list->mutex);

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }

    new_record->key = generate_unique_key(list, 0, 10000); // Example key range
    new_record->value = rand() % (max_value - min_value + 1) + min_value;
    new_record->next = list->head;
    list->head = new_record;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

// Function to free the record list and clean up resources
void free_record_list(RecordList* list) {
    pthread_mutex_lock(&list->mutex);

    Record* current = list->head;
    while (current != NULL) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

