#define MAX_KEY_RANGE 10000

typedef struct record {
    int key;
    long value;
    struct record *next;
} Record;

typedef struct {
    Record *head;
    pthread_rwlock_t lock;
    size_t count;
} LinkedList;

typedef struct {
    LinkedList list;
    int cache_size; // for LRU
    time_t current_time;
    // Add more fields as needed for TTL, etc.
} CollectionManager;

// Function prototypes
CollectionManager* create_manager(int cache_size);
void destroy_manager(CollectionManager *manager);
Record* find_record(CollectionManager *manager, int key);
void add_or_update_record(CollectionManager *manager, Record *record);
void remove_record(CollectionManager *manager, int key);
void ingest_data(CollectionManager *manager);
void *data_ingestion_thread(void *arg);

// Create a new collection manager
CollectionManager* create_manager(int cache_size) {
    CollectionManager *manager = malloc(sizeof(CollectionManager));
    if (!manager) return NULL;

    manager->list.head = NULL;
    pthread_rwlock_init(&manager->list.lock, NULL);
    manager->cache_size = cache_size;
    manager->current_time = time(NULL);

    return manager;
}

// Destroy the collection manager
void destroy_manager(CollectionManager *manager) {
    if (!manager) return;

    Record *current = manager->list.head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_rwlock_destroy(&manager->list.lock);
    free(manager);
}

// Find a record by key
Record* find_record(CollectionManager *manager, int key) {
    pthread_rwlock_rdlock(&manager->list.lock);

    Record *current = manager->list.head;
    while (current) {
        if (current->key == key) {
            pthread_rwlock_unlock(&manager->list.lock);
            return current;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&manager->list.lock);
    return NULL;
}

// Add or update a record
void add_or_update_record(CollectionManager *manager, Record *record) {
    pthread_rwlock_wrlock(&manager->list.lock);

    // Check for duplicates and insert/update logic
    Record **indirect = &manager->list.head;
    while (*indirect && (*indirect)->key != record->key) {
        indirect = &(*indirect)->next;
    }

    if (*indirect) {
        free((*indirect)->value);  // Free old value memory if updating
    } else {
        manager->list.count++;
    }

    *indirect = record;

    pthread_rwlock_unlock(&manager->list.lock);
}

// Remove a record by key
void remove_record(CollectionManager *manager, int key) {
    pthread_rwlock_wrlock(&manager->list.lock);

    Record **indirect = &manager->list.head;
    while (*indirect && (*indirect)->key != key) {
        indirect = &(*indirect)->next;
    }

    if (*indirect) {
        Record *temp = *indirect;
        *indirect = temp->next;
        free(temp);
        manager->list.count--;
    }

    pthread_rwlock_unlock(&manager->list.lock);
}

// Simulate data ingestion
void ingest_data(CollectionManager *manager) {
    for (int i = 0; i < 100; ++i) {
        int key = rand() % MAX_KEY_RANGE;
        Record *record = malloc(sizeof(Record));
        if (!record) continue;

        record->key = key;
        record->value = rand();
        record->next = NULL;

        add_or_update_record(manager, record);
    }
}

// Data ingestion thread function
void *data_ingestion_thread(void *arg) {
    CollectionManager *manager = (CollectionManager *)arg;

    while (1) {
        ingest_data(manager);
        sleep(5);  // Simulate time between data ingestion events
    }

    return NULL;
}

int main() {
