    CollectionManager *manager = create_manager(100);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_ingestion_thread, manager) != 0) {
        perror("Failed to create thread");
        destroy_manager(manager);
        return EXIT_FAILURE;
    }

    // Simulate running for a while
    sleep(30);

    // Cleanup
    pthread_cancel(thread_id);
    pthread_join(thread_id, NULL);
    destroy_manager(manager);

    return EXIT_SUCCESS;
}
