    double floating_point_value;
    char *char_string;
} data_record;

#define INITIAL_CAPACITY 1000

data_record* create_data_collection() {
    return calloc(INITIAL_CAPACITY, sizeof(data_record));
}

int add_record(data_record** records, int* count, int capacity, long long int large_integer, 
               double floating_point_value, const char* char_string) {
    if (*count >= capacity) {
        int new_capacity = capacity * 2;
        data_record* temp = realloc(*records, new_capacity * sizeof(data_record));
        if (!temp) return -1; // Allocation failed
        *records = temp;
        capacity = new_capacity;
    }

    (*records)[*count].large_integer = large_integer;
    (*records)[*count].floating_point_value = floating_point_value;

    size_t str_length = strlen(char_string);
    char* allocated_str = malloc(str_length + 1); // +1 for null-terminator
    if (!allocated_str) return -2; // Allocation failed

    strcpy(allocated_str, char_string);
    (*records)[*count].char_string = allocated_str;

    (*count)++;
    return 0;
}

void free_data_collection(data_record* records, int count) {
    for (int i = 0; i < count; ++i) {
        if (records[i].char_string) {
            free(records[i].char_string);
