#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <netdb.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char hostname[256];
} LineData;

void *resolve_hostname(void *arg) {
    LineData *data = (LineData *)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(data->hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        char ipstr[INET_ADDRSTRLEN];
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // Not IPv4
            continue;
        }
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        printf("Resolved IP: %s\n", ipstr);
    }

    freeaddrinfo(res);
    return NULL;
}

void process_line(char *line) {
    char *token;
    char *rest = line;
    int field_count = 0;
    double sum = 0.0, last_three_sum = 0.0;

    while ((token = strtok_r(rest, ",", &rest))) {
        if (field_count > 0 && field_count <= 3) {
            last_three_sum += atof(token);
        }
        sum += atof(token);
        printf("%s", token);
        if (*rest != '\0') {
            printf(",");
        }
        field_count++;
    }

    double average = (field_count >= 3) ? last_three_sum / 3 : 0;
    printf(",%.2f\n", average);

    printf("Sum of fields: %.2f\n", sum);
}

void read_and_process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open file");
        return;
    }

    pthread_t threads[256];
    LineData line_data[256];
    int i = 0;

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        if (i >= 256) break; // Limit concurrent threads

        strncpy(line_data[i].hostname, strtok_r(line, ",", &line), sizeof(line_data[i].hostname) - 1);
        pthread_create(&threads[i], NULL, resolve_hostname, &line_data[i]);

        char *rest = line;
        process_line(rest);

        i++;
    }

    for (int j = 0; j < i; j++) {
        pthread_join(threads[j], NULL);
    }

    free(line);
    fclose(file);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    read_and_process_file(argv[1]);

    return EXIT_SUCCESS;
}
