void initialize_session_pool(SessionPool *pool) {
    memset(pool, 0, sizeof(*pool));
    pthread_mutex_init(&pool->lock, NULL);
}

HTTPSession* get_or_create_session(SessionPool *pool, const char *hostname) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (!strcmp(pool->sessions[i]->hostname, hostname)) {
            HTTPSession *session = pool->sessions[i];
            session->last_accessed = time(NULL);
            session->state = IDLE;
            pthread_mutex_unlock(&pool->lock);
            return session;
        }
    }

    if (pool->memory_used + HEADER_SIZE > MEMORY_LIMIT) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Memory limit exceeded
    }

    HTTPSession *session = malloc(sizeof(*session));
    if (!session) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    session->hostname = strdup(hostname);
    session->state = OPEN;
    session->last_accessed = time(NULL);
    session->request_headers_size = 0;
    session->response_headers_size = 0;
    session->request_headers = NULL;
    session->response_headers = NULL;
    session->custom_fields = NULL;

    pool->sessions[pool->count++] = session;
    pool->memory_used += HEADER_SIZE + strlen(hostname) + 1;

    pthread_mutex_unlock(&pool->lock);
    return session;
}

size_t serialize_sessions(const HTTPSession **sessions, size_t session_count, uint8_t **buffer) {
    if (!sessions || !session_count || !buffer) return 0;

    *buffer = malloc(session_count * HEADER_SIZE);
    if (!*buffer) return 0;

    uint8_t *ptr = *buffer;
    for (size_t i = 0; i < session_count; ++i) {
        HTTPSession *session = sessions[i];
        size_t hostname_len = strlen(session->hostname);

        memcpy(ptr, &hton32(hostname_len), sizeof(uint32_t));
        ptr += sizeof(uint32_t);
        memcpy(ptr, session->hostname, hostname_len);
        ptr += hostname_len;

        uint32_t state = hton32((uint32_t)session->state);
        memcpy(ptr, &state, sizeof(state));
        ptr += sizeof(state);

        time_t last_accessed = hton64(session->last_accessed);
        memcpy(ptr, &last_accessed, sizeof(last_accessed));
        ptr += sizeof(last_accessed);

        uint32_t req_headers_size = hton32((uint32_t)session->request_headers_size);
        memcpy(ptr, &req_headers_size, sizeof(req_headers_size));
        ptr += sizeof(req_headers_size);

        uint32_t res_headers_size = hton32((uint32_t)session->response_headers_size);
        memcpy(ptr, &res_headers_size, sizeof(res_headers_size));
        ptr += sizeof(res_headers_size);
    }

    return ptr - *buffer;
}

HTTPSession** deserialize_sessions(uint8_t *buffer, size_t buffer_size, size_t *session_count) {
    if (!buffer || !session_count) return NULL;

    const uint8_t *ptr = buffer;
    size_t count = 0;
    while (ptr - buffer + HEADER_SIZE <= buffer_size) {
        uint32_t hostname_len = ntoh32(*(uint32_t*)ptr);
        ptr += sizeof(uint32_t);

        char *hostname = malloc(hostname_len + 1);
        if (!hostname) break;

        memcpy(hostname, ptr, hostname_len);
        hostname[hostname_len] = '\0';
        ptr += hostname_len;

        uint32_t state = ntoh32(*(uint32_t*)ptr);
        ptr += sizeof(uint32_t);

        time_t last_accessed = ntoh64(*(uint64_t*)ptr);
        ptr += sizeof(last_accessed);

        uint32_t req_headers_size = ntoh32(*(uint32_t*)ptr);
        ptr += sizeof(req_headers_size);

        uint32_t res_headers_size = ntoh32(*(uint32_t*)ptr);
        ptr += sizeof(res_headers_size);

        HTTPSession *session = malloc(sizeof(*session));
        if (!session) {
            free(hostname);
            break;
        }

        session->hostname = hostname;
        session->state = (ConnectionState)state;
        session->last_accessed = last_accessed;
        session->request_headers_size = req_headers_size;
        session->response_headers_size = res_headers_size;
        session->request_headers = NULL; // Handle separately
        session->response_headers = NULL; // Handle separately
        session->custom_fields = NULL;

        count++;
    }

    *session_count = count;
    HTTPSession **sessions = malloc(count * sizeof(*sessions));
    if (!sessions) {
        for (size_t i = 0; i < count; ++i) free(sessions[i]);
        return NULL;
    }

    ptr = buffer;
    for (size_t i = 0; i < count; ++i) {
        sessions[i] = malloc(sizeof(*sessions[i]));
        memcpy(&sessions[i]->hostname, &ptr[4], sizeof(uint32_t));
        ptr += HEADER_SIZE;

        // Deserialize headers and other fields as needed
    }

    return sessions;
}

void free_session_pool(SessionPool *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        HTTPSession *session = pool->sessions[i];
        if (session) {
            free(session->hostname);
            free(session->request_headers);
            free(session->response_headers);
            free(session->custom_fields);
            free(session);
        }
    }

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

uint32_t hton32(uint32_t hostlong) {
    return htonl(hostlong);
}

uint64_t hton64(uint64_t hostlong) {
#ifdef __BYTE_ORDER
#if __BYTE_ORDER == __BIG_ENDIAN
    return hostlong;
#else
    union { uint64_t u; uint8_t c[8]; } source, dest;
    source.u = hostlong;
    dest.c[0] = source.c[7];
    dest.c[1] = source.c[6];
    dest.c[2] = source.c[5];
    dest.c[3] = source.c[4];
    dest.c[4] = source.c[3];
    dest.c[5] = source.c[2];
    dest.c[6] = source.c[1];
    dest.c[7] = source.c[0];
    return dest.u;
#endif
#endif
    return hostlong; // Fallback for unknown endianness
}

uint32_t ntoh32(uint32_t netlong) {
    return htonl(netlong);
}

uint64_t ntoh64(uint64_t netlong) {
#ifdef __BYTE_ORDER
#if __BYTE_ORDER == __BIG_ENDIAN
    return netlong;
#else
    union { uint64_t u; uint8_t c[8]; } source, dest;
    source.u = netlong;
    dest.c[0] = source.c[7];
    dest.c[1] = source.c[6];
    dest.c[2] = source.c[5];
    dest.c[3] = source.c[4];
    dest.c[4] = source.c[3];
    dest.c[5] = source.c[2];
    dest.c[6] = source.c[1];
    dest.c[7] = source.c[0];
    return dest.u;
#endif
#endif
    return netlong; // Fallback for unknown endianness
}

