```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

// Define possible entity types using an enum for flexibility.
typedef enum {
    ENTITY_INT,
    ENTITY_FLOAT,
    ENTITY_CHAR_PTR,
    ENTITY_DOUBLE,
    // Add new data types here in the future.
} EntityType;

// Structure to hold an entity.
typedef struct {
    EntityType type;
    void *data;
} Entity;

// Structure to manage a collection of entities within a container.
typedef struct {
    Entity **entities;
    size_t count;
    size_t capacity;
    size_t max_size;
    pthread_mutex_t lock;
} EntityContainer;

// Logging function for debugging and analysis.
void log_message(const char *message) {
    printf("[LOG] %s\n", message);
}

// Helper function to check memory allocation errors.
void *checked_malloc(size_t size, const char *context) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for %s.\n", context);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize an entity container with a maximum size limit.
EntityContainer *init_entity_container(size_t max_size) {
    EntityContainer *container = checked_malloc(sizeof(EntityContainer), "EntityContainer");
    pthread_mutex_init(&container->lock, NULL);
    container->entities = NULL;
    container->count = 0;
    container->capacity = 0;
    container->max_size = max_size;
    return container;
}

// Function to add an entity to the container.
int add_entity(EntityContainer *container, EntityType type, const void *data, size_t data_size) {
    pthread_mutex_lock(&container->lock);

    if (container->count >= container->capacity) {
        size_t new_capacity = (container->capacity == 0) ? 1 : container->capacity * 2;
        Entity **new_entities = checked_malloc(new_capacity * sizeof(Entity*), "Entity array resize");

        if (container->entities != NULL) {
            memcpy(new_entities, container->entities, container->count * sizeof(Entity*));
            free(container->entities);
        }

        container->entities = new_entities;
        container->capacity = new_capacity;
    }

    Entity *entity = checked_malloc(sizeof(Entity), "Entity allocation");
    entity->type = type;

    size_t required_size = sizeof(size_t) + data_size; // Include type metadata
    if (required_size > container->max_size) {
        pthread_mutex_unlock(&container->lock);
        log_message("Failed to add entity: exceeds max size limit.");
        free(entity);
        return -1;
    }

    void *entity_data = checked_malloc(required_size, "Entity data allocation");
    memcpy(entity_data, &type, sizeof(size_t));
    memcpy((char *)entity_data + sizeof(size_t), data, data_size);

    entity->data = entity_data;
    container->entities[container->count++] = entity;

    pthread_mutex_unlock(&container->lock);
    return 0;
}

// Function to free all allocated memory in the container.
void free_entity_container(EntityContainer *container) {
    pthread_mutex_lock(&container->lock);

    for (size_t i = 0; i < container->count; ++i) {
        if (container->entities[i] != NULL) {
            free(container->entities[i]->data);
            free(container->entities[i]);
        }
    }

    if (container->entities != NULL) {
        free(container->entities);
    }

    pthread_mutex_unlock(&container->lock);
    pthread_mutex_destroy(&container->lock);
    free(container);
