    for (int i = 0; i < n; ++i) {
        printf("Enter integer %d: ", i + 1);
        if (scanf("%d", &numbers[i]) != 1) {
            fprintf(stderr, "Invalid input.\n");
            free(numbers);
            exit(EXIT_FAILURE);
        }
    }

    int max_value = numbers[0];
    for (int i = 1; i < n; ++i) {
        if (numbers[i] > max_value) {
            max_value = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", max_value);
    free(numbers);
}

