```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_MEMORY_LIMIT 10485760 // 10 MB
#define MAX_SESSIONS 10000
#define CONNECTION_AGE_THRESHOLD 300 // seconds

typedef enum { OPEN, CLOSED, IDLE, ERROR } ConnectionState;
typedef struct {
    char *hostname;
    ConnectionState state;
    time_t last_accessed;
    char *request_headers;
    char *response_headers;
    void *custom_fields;
} HTTPSession;

typedef struct {
    int value;
    long offset;
    char random_string[64];
} Record;

typedef struct Node {
    HTTPSession session;
    struct Node *next;
} Node;

typedef struct {
    Node *head, *tail;
    pthread_mutex_t lock;
} LockFreeQueue;

LockFreeQueue queue = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER};

// Utility functions
void log_event(const char *event) {
    printf("[LOG] %s\n", event);
}

int allocate_memory(void **ptr, size_t size) {
    if (size == 0) return -1;
    *ptr = malloc(size);
    return (*ptr != NULL) ? 0 : -1;
}

void deallocate_memory(void *ptr) {
    free(ptr);
}

// Thread-safe queue operations
void enqueue(HTTPSession session) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed for new node");
        return;
    }
    new_node->session = session;
    new_node->next = NULL;

    pthread_mutex_lock(&queue.lock);
    if (queue.tail) {
        queue.tail->next = new_node;
    } else {
        queue.head = new_node;
    }
    queue.tail = new_node;
    pthread_mutex_unlock(&queue.lock);
}

HTTPSession dequeue() {
    pthread_mutex_lock(&queue.lock);
    HTTPSession session = {0};
    if (queue.head) {
        Node *temp = queue.head;
        session = temp->session;
        queue.head = queue.head->next;
        if (!queue.head) {
            queue.tail = NULL;
        }
        free(temp);
    }
    pthread_mutex_unlock(&queue.lock);
    return session;
}

// Serialization and deserialization
size_t serialize_session(const HTTPSession *session, uint8_t **buffer) {
    size_t total_size = sizeof(ConnectionState) + strlen(session->hostname) + 1 +
                        sizeof(time_t) + strlen(session->request_headers) + 1 +
                        strlen(session->response_headers) + 1;
    if (session->custom_fields) {
        // Assuming custom fields are a null-terminated string for simplicity
        total_size += strlen((char *)session->custom_fields) + 1;
    }

    *buffer = (uint8_t *)malloc(total_size);
    uint8_t *ptr = *buffer;

    memcpy(ptr, &session->state, sizeof(ConnectionState));
    ptr += sizeof(ConnectionState);

    size_t hostname_len = strlen(session->hostname);
    memcpy(ptr, session->hostname, hostname_len);
    ptr[hostname_len] = '\0';
    ptr += (hostname_len + 1);

    memcpy(ptr, &session->last_accessed, sizeof(time_t));
    ptr += sizeof(time_t);

    size_t req_headers_len = strlen(session->request_headers);
    memcpy(ptr, session->request_headers, req_headers_len);
    ptr[req_headers_len] = '\0';
    ptr += (req_headers_len + 1);

    size_t resp_headers_len = strlen(session->response_headers);
    memcpy(ptr, session->response_headers, resp_headers_len);
    ptr[resp_headers_len] = '\0';

    if (session->custom_fields) {
        size_t custom_len = strlen((char *)session->custom_fields);
        memcpy(ptr, session->custom_fields, custom_len);
        ptr[custom_len] = '\0';
    }

    return total_size;
}

HTTPSession deserialize_session(const uint8_t *buffer, size_t buffer_size) {
    HTTPSession session = {0};
    const uint8_t *ptr = buffer;

    memcpy(&session.state, ptr, sizeof(ConnectionState));
    ptr += sizeof(ConnectionState);

    session.hostname = (char *)ptr;
    while (*ptr != '\0') ptr++;
    ptr++;

    memcpy(&session.last_accessed, ptr, sizeof(time_t));
    ptr += sizeof(time_t);

    session.request_headers = (char *)ptr;
    while (*ptr != '\0') ptr++;
    ptr++;

    session.response_headers = (char *)ptr;
    while (*ptr != '\0') ptr;

    // Custom fields are not handled in this example
    return session;
}

// Connection management
void manage_connections(HTTPSession *sessions, size_t count) {
    time_t now = time(NULL);
    for (size_t i = 0; i < count; ++i) {
        if (sessions[i].state == OPEN && (now - sessions[i].last_accessed > CONNECTION_AGE_THRESHOLD)) {
            log_event("Connection age exceeded threshold, closing connection");
            sessions[i].state = CLOSED;
        }
    }
}

// Record management
typedef struct {
    Record *records;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

void initialize_record_array(RecordArray *array, size_t initial_size) {
    allocate_memory(&array->records, initial_size * sizeof(Record));
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void add_record(RecordArray *array, int value, long offset, const char *random_string) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record *new_records = realloc(array->records, new_capacity * sizeof(Record));
        if (!new_records) {
            log_event("Failed to reallocate memory for records");
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }
    Record record = {value, offset, ""};
    strncpy(record.random_string, random_string, sizeof(record.random_string) - 1);
    array->records[array->count++] = record;
    pthread_mutex_unlock(&array->lock);
}

void free_record_array(RecordArray *array) {
    pthread_mutex_destroy(&array->lock);
    deallocate_memory(array->records);
}

// Main function
int main() {
    HTTPSession sessions[MAX_SESSIONS];
    RecordArray record_array;

    initialize_record_array(&record_array, 10);

    // Example usage
    add_record(&record_array, 42, 1000, "random_string_1");
    manage_connections(sessions, MAX_SESSIONS);

    uint8_t *buffer;
    size_t buffer_size = serialize_session(&sessions[0], &buffer);
    HTTPSession deserialized_session = deserialize_session(buffer, buffer_size);

    free_record_array(&record_array);
    deallocate_memory(buffer);

    return 0;
}
```

This code provides a basic framework for managing HTTP sessions and records in a multi-threaded environment. It includes mechanisms for serialization/deserialization, connection management, and logging. Adjustments may be needed based on specific requirements or constraints.']

