    pthread_mutex_lock(&mem_pool.lock);

    va_list args;
    va_start(args, format);
    vprintf(format, args);
    printf("\n");
    va_end(args);

    pthread_mutex_unlock(&mem_pool.lock);
}

// Initialize memory pool
int initialize_memory_pool() {
    pthread_mutex_lock(&mem_pool.lock);
    mem_pool.ptr = malloc(mem_pool.size);
    if (!mem_pool.ptr) {
        log_message(LOG_ERROR, "Failed to allocate memory pool");
        pthread_mutex_unlock(&mem_pool.lock);
        return -1;
    }
    pthread_mutex_unlock(&mem_pool.lock);
    return 0;
}

// Allocate memory from pool
void* custom_malloc(size_t size) {
