    void *result = malloc(size); // Implement real pooling strategy here for optimization
    if (!result) {
        log_message(LOG_ERROR, "Failed to allocate memory");
    } else {
        mem_pool.size -= size;
    }

    pthread_mutex_unlock(&mem_pool.lock);
    return result;
}

// Free memory back to pool (not implemented in detail)
void custom_free(void *ptr, size_t size) {
    pthread_mutex_lock(&mem_pool.lock);

    free(ptr); // Implement real pooling strategy here for optimization
    mem_pool.size += size;

    pthread_mutex_unlock(&mem_pool.lock);
}

