Record* create_record(size_t buffer_size) {
    Record *record = custom_malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = rand() % RANDOM_RANGE_MAX; // Random value within range

    record->offset = 0; // Initialize offset

    record->buffer = custom_malloc(buffer_size);
    if (!record->buffer) {
        log_message(LOG_ERROR, "Failed to allocate buffer for Record");
        custom_free(record, sizeof(Record));
        return NULL;
    }

