    size_t offset_size = sizeof(record->offset);
    size_t value_size = sizeof(record->value);
    size_t buffer_size = strlen(record->buffer) + 1;

    *output = custom_malloc(offset_size + value_size + buffer_size);
    if (!*output) return 0;

    memcpy(*output, &record->offset, offset_size);
    memcpy(*output + offset_size, &record->value, value_size);
    memcpy(*output + offset_size + value_size, record->buffer, buffer_size);

    size_t total_size = offset_size + value_size + buffer_size;
    return total_size;
}

// Serialize Record to a JSON format
size_t serialize_record_json(Record *record, char **output) {
