        record->offset, record->value, record->buffer) + 1;

    *output = custom_malloc(json_size);
    if (!*output) return 0;

    snprintf(*output, json_size, "{\"offset\": %ld, \"value\": %d, \"buffer\": \"%s\"}", 
        record->offset, record->value, record->buffer);

    size_t total_size = strlen(*output) + 1;
    return total_size;
