#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

typedef enum {
    INFO,
    WARNING,
    ERROR
} severity;

typedef struct {
    time_t timestamp;
    char *message;
    severity level;
    uint32_t id;
} log_entry;

#define MAX_LOG_SIZE 1024 * 1024 // 1MB
#define ID_RANGE 1000
#define VOLUME 256

const char *vocabulary[] = {"error", "warning", "info", "debug"};

// Forward declarations
log_entry* create_log_entries(size_t count, size_t message_size);
void free_log_entries(log_entry *entries, size_t count);
uint8_t* serialize_logs(const log_entry *entries, size_t count, size_t *out_size);
log_entry deserialize_log(const uint8_t *data, size_t data_size, size_t entry_index);
void find_longest_message();
char* generate_random_message(size_t length);
unsigned long hash_id(uint32_t id);

log_entry* create_log_entries(size_t count, size_t message_size) {
    if (count == 0 || message_size == 0) return NULL;

    // Calculate total required memory
    size_t entry_size = sizeof(log_entry) + message_size;
    size_t total_size = count * entry_size;
    if (total_size > MAX_LOG_SIZE) {
        fprintf(stderr, "Exceeded maximum log size.\n");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    // Allocate memory for entries
    log_entry* entries = malloc(count * sizeof(log_entry));
    if (!entries) {
        perror("Failed to allocate memory for log entries");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        entries[i].timestamp = time(NULL);

        entries[i].message = malloc(message_size + 1); // +1 for null-terminator
        if (!entries[i].message) {
            perror("Failed to allocate memory for log message");
            free_log_entries(entries, i);
            return NULL;
        }

        size_t msg_length = strlen(vocabulary[rand() % VOLUME]);
        strncpy(entries[i].message, vocabulary[rand() % VOLUME], message_size > msg_length ? msg_length : message_size);
        entries[i].message[message_size] = '\0'; // Ensure null-termination

        entries[i].level = rand() % 3;

        uint32_t random_id = (uint32_t)rand();
        entries[i].id = random_id % ID_RANGE; 
    }

    return entries;
}

void free_log_entries(log_entry *entries, size_t count) {
    if (!entries) return;

    for (size_t i = 0; i < count; ++i) {
        free(entries[i].message);
    }
    free(entries);
}

uint8_t* serialize_logs(const log_entry *entries, size_t count, size_t *out_size) {
    if (!entries || !count || !out_size) return NULL;

    size_t total_serialized_size = 0;
    for (size_t i = 0; i < count; ++i) {
        total_serialized_size += sizeof(entries[i].timestamp);
        total_serialized_size += strlen(entries[i].message) + 1; // include null-terminator
        total_serialized_size += sizeof(entries[i].level);
        total_serialized_size += sizeof(entries[i].id);
    }

    uint8_t *serialized_data = malloc(total_serialized_size);
    if (!serialized_data) {
        perror("Failed to allocate memory for serialized data");
        return NULL;
    }

    uint8_t *ptr = serialized_data;
    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &entries[i].timestamp, sizeof(entries[i].timestamp));
        ptr += sizeof(entries[i].timestamp);

        size_t msg_length = strlen(entries[i].message);
        memcpy(ptr, entries[i].message, msg_length + 1); // include null-terminator
        ptr += (msg_length + 1);

        *ptr++ = entries[i].level;

        *ptr++ = (entries[i].id >> 24) & 0xFF;
        *ptr++ = (entries[i].id >> 16) & 0xFF;
        *ptr++ = (entries[i].id >> 8) & 0xFF;
        *ptr++ = entries[i].id & 0xFF;
    }

    *out_size = total_serialized_size;
    return serialized_data;
}

log_entry deserialize_log(const uint8_t *data, size_t data_size, size_t entry_index) {
    if (!data || !data_size || entry_index >= data_size / sizeof(log_entry)) {
        fprintf(stderr, "Invalid parameters for deserialization.\n");
        log_entry invalid = {0};
        return invalid;
    }

    const uint8_t *ptr = data + (entry_index * (sizeof(time_t) 
                + strlen(vocabulary[rand() % VOLUME]) + 1
                + sizeof(severity)
                + sizeof(uint32_t)));

    log_entry entry;
    memcpy(&entry.timestamp, ptr, sizeof(entry.timestamp));
    ptr += sizeof(entry.timestamp);

    size_t msg_length = strlen((const char *)ptr);
    entry.message = strdup(ptr);
    ptr += (msg_length + 1);

    entry.level = *(severity *)ptr;
    ptr++;

    uint32_t id = ((uint32_t)ptr[0] << 24) | ((uint32_t)ptr[1] << 16) |
                  ((uint32_t)ptr[2] << 8) | (uint32_t)ptr[3];
    entry.id = id;
    ptr += sizeof(entry.id);

    return entry;
}

void find_longest_message() {
    char buffer[256];
    size_t max_length = 0;
    char *longest_msg = NULL;

    printf("Enter log messages (type 'END' to finish):\n");
    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (strncmp(buffer, "END", 3) == 0) break;

        buffer[strcspn(buffer, "\r\n")] = '\0'; // Remove newline
        size_t length = strlen(buffer);

        if (length > max_length) {
            free(longest_msg);
            longest_msg = strdup(buffer);
            max_length = length;
        }
    }

    printf("Longest message: %s\n", longest_msg ? longest_msg : "None");
    free(longest_msg);
}

char* generate_random_message(size_t length) {
    if (length == 0) return NULL;

    char *message = malloc(length + 1); // +1 for null-terminator
    if (!message) {
        perror("Failed to allocate memory for random message");
        return NULL;
    }

