['Below is a C library that implements the described functionality with thread-safe memory allocation and deallocation for an array of records. The code uses POSIX threads (pthreads) for synchronization.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int *value_array;
} Record;

typedef struct {
    Record **records;
    size_t count;
    pthread_mutex_t lock;
    pthread_mutex_t log_lock;
    int allocated_logs[2]; // [0] for allocated, [1] for freed
} MemoryManager;

MemoryManager manager = { .count = 0, .allocated_logs = {0, 0}, 
                          .lock = PTHREAD_MUTEX_INITIALIZER,
                          .log_lock = PTHREAD_MUTEX_INITIALIZER };

void initialize_random() {
    srand(time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record *create_record(long offset, int key, size_t value_count, int min_val, int max_val) {
    Record *record = malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;

    record->value_array = malloc(value_count * sizeof(int));
    for (size_t i = 0; i < value_count; ++i) {
        record->value_array[i] = random_int(min_val, max_val);
    }

    return record;
}

void populate_records(size_t num_records, size_t value_count, int min_val, int max_val) {
    pthread_mutex_lock(&manager.lock);

    for (size_t i = 0; i < num_records; ++i) {
        long offset = random_int(0, 100000);
        int key = random_int(1, 1000);

        Record *record = create_record(offset, key, value_count, min_val, max_val);

        manager.records[manager.count] = record;
        manager.count++;
    }

    pthread_mutex_unlock(&manager.lock);

    pthread_mutex_lock(&manager.log_lock);
    manager.allocated_logs[0] += num_records;
    printf("Allocated %zu records\n", num_records);
    pthread_mutex_unlock(&manager.log_lock);
}

void cleanup() {
    pthread_mutex_lock(&manager.lock);

    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.records[i]->value_array);
        free(manager.records[i]);
        manager.allocated_logs[1]++;
    }

    size_t original_count = manager.count;
    manager.count = 0;

    pthread_mutex_unlock(&manager.lock);

    pthread_mutex_lock(&manager.log_lock);
    printf("Freed %zu records\n", original_count);
    pthread_mutex_unlock(&manager.log_lock);
}

int get_allocated_logs(int index) {
    if (index < 0 || index > 1) return -1;

    int logs;
    pthread_mutex_lock(&manager.log_lock);
    logs = manager.allocated_logs[index];
    pthread_mutex_unlock(&manager.log_lock);

    return logs;
}

void init_memory_manager(size_t initial_capacity) {
    manager.records = malloc(initial_capacity * sizeof(Record *));
}

void shutdown_memory_manager() {
    cleanup();
    free(manager.records);
}

int main() {
    size_t capacity = 1000; // Initial capacity for records
    size_t num_records = 500;
    size_t value_count = 10;
    int min_val = -50, max_val = 50;

    init_memory_manager(capacity);

    initialize_random();
    populate_records(num_records, value_count, min_val, max_val);

    printf("Allocated logs: %d\n", get_allocated_logs(0));
    printf("Freed logs: %d\n", get_allocated_logs(1));

    shutdown_memory_manager();

    return 0;
}
```

This code provides a memory manager that handles allocation and deallocation of records, with thread-safe operations using mutexes. It also includes logging for the number of allocated and freed records. The design is optimized for both high throughput and efficient cleanup during shutdown.']

