// Function to initialize and manage memory for arrays with constraints
void* allocate_memory(size_t array_size, size_t element_size) {
    void* ptr = malloc(array_size * element_size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
