// Custom memory pool for records to minimize fragmentation
typedef struct {
    record *pool;
    size_t capacity;
} MemoryPool;

void initialize_memory_pool(MemoryPool* mem_pool, size_t num_records) {
    mem_pool->capacity = num_records;
    mem_pool->pool = allocate_memory(num_records, sizeof(record));
}

record* allocate_from_pool(MemoryPool* mem_pool) {
    // For simplicity, assume pool is never exceeded in this example
    return &mem_pool->pool[0];  // Normally you'd track usage and provide an index
}

// Function to free all allocated memory
void free_all(void *offsets, void *keys, MemoryPool *mem_pool) {
    free(offsets);
    free(keys);
    free(mem_pool->pool);  // Free the entire pool block at once
}

// The main function implementing the task with comments on design choices
void manage_data_structures(size_t num_offsets, size_t num_keys, size_t num_records,
                            int key_range_min, int key_range_max, int init_flag) {
    // Memory budget management: estimate and check before allocation
    size_t total_memory_needed = sizeof(long) * num_offsets + 
                                 sizeof(int) * num_keys + 
                                 sizeof(record) * num_records;

    if (total_memory_needed > MAX_MEMORY_BUDGET) {
        fprintf(stderr, "Total memory needed exceeds budget\n");
        return;
    }

    // Allocate array of long integers for offsets
    long* offsets = allocate_memory(num_offsets, sizeof(long));
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = 0L;  // Initialize all to zero
    }

    // Allocate and initialize unique keys array using a simple set-like approach
    int* keys = allocate_memory(num_keys, sizeof(int));
    for (size_t i = 0; i < num_keys; ++i) {
        bool unique;
        do {
            unique = true;
            keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);
            // Check uniqueness
            for (int j = 0; j < i; ++j) {
                if (keys[i] == keys[j]) {
                    unique = false;
                    break;
                }
            }
        } while (!unique);  // Retry until a unique value is found
    }

    // Initialize memory pool for records
    MemoryPool mem_pool;
    initialize_memory_pool(&mem_pool, num_records);

    // Populate record values based on init_flag
    for (size_t i = 0; i < num_records; ++i) {
        record* rec = allocate_from_pool(&mem_pool);
        if (init_flag == 0) {
            // Initialize long part to a random offset within user-specified range
            rec->data.lvalue = rand() % (key_range_max - key_range_min + 1); // Example range
        } else if (init_flag == 1) {
            // Initialize int part to a random unique key
            bool unique;
            do {
                unique = true;
                rec->data.ivalue = keys[rand() % num_keys];
                for (size_t j = 0; j < i; ++j) {
                    if (&mem_pool.pool[j] == rec && mem_pool.pool[j].data.ivalue == rec->data.ivalue) {
                        unique = false;
                        break;
                    }
                }
            } while (!unique);
        }
    }

    // When done, free all allocated memory
    free_all(offsets, keys, &mem_pool);
}

int main() {
    srand(time(NULL));  // Seed for random number generation

    size_t num_offsets = 1000; 
    size_t num_keys = 500;
    size_t num_records = 200;
    int key_range_min = 1;
    int key_range_max = 10000;

    manage_data_structures(num_offsets, num_keys, num_records,
                           key_range_min, key_range_max, 0);

    return 0;
}
