typedef struct {
    int id;
    char *status;
    char *description;
} Item;

typedef struct Node {
    Item item;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t capacity;
    size_t count;
} ItemCollection;

#define STATUS_UPDATING "updating"
#define STATUS_ERROR "error"

// Function declarations
ItemCollection* create_collection(size_t initial_capacity);
int add_item(ItemCollection* collection, int id, const char* status, const char* description);
void free_collection(ItemCollection* collection);
void update_status(ItemCollection* collection, const char* condition, const char* new_status);
char* resolve_hostname(const char* hostname);

// Asynchronous DNS resolution with caching
typedef struct {
    char* hostname;
    char* ip_address;
} DnsCacheEntry;

DnsCacheEntry* dns_cache = NULL;
size_t dns_cache_size = 0;
pthread_mutex_t dns_lock = PTHREAD_MUTEX_INITIALIZER;

char* resolve_hostname(const char* hostname) {
    pthread_mutex_lock(&dns_lock);
    for (size_t i = 0; i < dns_cache_size; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&dns_lock);
            return dns_cache[i].ip_address;
        }
    }

    struct hostent* host_info = gethostbyname(hostname);
    char* ip_address = NULL;

    if (host_info != NULL && host_info->h_addr_list[0] != NULL) {
        ip_address = strdup(inet_ntoa(*(struct in_addr*)host_info->h_addr_list[0]));
        // Resize DNS cache
        DnsCacheEntry* new_cache = realloc(dns_cache, sizeof(DnsCacheEntry) * (dns_cache_size + 1));
        if (!new_cache) {
            pthread_mutex_unlock(&dns_lock);
            return NULL;
        }
        dns_cache = new_cache;
        dns_cache[dns_cache_size].hostname = strdup(hostname);
        dns_cache[dns_cache_size].ip_address = ip_address;
        ++dns_cache_size;

        pthread_mutex_unlock(&dns_lock);
        return ip_address;
    }

    pthread_mutex_unlock(&dns_lock);
    return NULL;
}

// Function to initialize item collection
ItemCollection* create_collection(size_t initial_capacity) {
    ItemCollection* collection = (ItemCollection*)malloc(sizeof(ItemCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);
    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

// Function to add an item
int add_item(ItemCollection* collection, int id, const char* status, const char* description) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        printf("Collection capacity exceeded\n");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Allocation error
    }

    new_node->item.id = id;
    new_node->item.status = strdup(status);
    new_node->item.description = description ? strdup(description) : NULL;

    if (new_node->item.description == NULL && description != NULL) {
        free(new_node->item.status);
        free(new_node);
        pthread_mutex_unlock(&collection->lock);
        return -2; // Allocation error
    }

    new_node->next = collection->head;
    collection->head = new_node;
    ++collection->count;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

// Function to free the item collection
void free_collection(ItemCollection* collection) {
    if (!collection) return;

    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current->item.status);
        free(current->item.description);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);

    for (size_t i = 0; i < dns_cache_size; ++i) {
        free(dns_cache[i].hostname);
        free(dns_cache[i].ip_address);
    }
    free(dns_cache);

    free(collection);
}

// Function to update item statuses
void update_status(ItemCollection* collection, const char* condition, const char* new_status) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current) {
        if (strcmp(current->item.status, condition) == 0) {
            free(current->item.status);
            current->item.status = strdup(new_status);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

// Example usage
int main() {
    ItemCollection* collection = create_collection(10);

    add_item(collection, 1, "active", "Description for item 1");
    add_item(collection, 2, "inactive", "Description for item 2");

    update_status(collection, "active", STATUS_UPDATING);

    // Resolve hostname example
    char* ip = resolve_hostname("www.example.com");
    if (ip) {
        printf("Resolved IP: %s\n", ip);
        free(ip);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    free_collection(collection);
    return 0;
}
```

