#define MAX_ITEMS 1000

typedef struct {
    int id;
    char *status;
    char *description;
} Item;

typedef struct {
    Item *items[MAX_ITEMS];
    size_t count;
    pthread_mutex_t lock;
    // Simple LRU cache for demonstration purposes
    Item *cache[MAX_ITEMS];
    size_t cache_count;
} ItemCollection;

// Custom memory allocator
void* custom_alloc(size_t size) {
    static void* pool = NULL;
    if (!pool) {
        pool = malloc(1024 * 1024); // 1MB pool
    }
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

// Initialize item collection
void init_item_collection(ItemCollection *collection) {
    memset(collection, 0, sizeof(ItemCollection));
    pthread_mutex_init(&collection->lock, NULL);
}

// Add new item
int add_item(ItemCollection *collection, int id, const char *status, const char *description) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= MAX_ITEMS) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Collection full
    }

    Item *item = custom_alloc(sizeof(Item));
    item->id = id;
    item->status = strdup(status);
    item->description = strdup(description);

    collection->items[collection->count++] = item;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Update existing item
int update_item(ItemCollection *collection, int condition_id, const char *new_status) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i]->id == condition_id) {
            free(collection->items[i]->status);
            collection->items[i]->status = strdup(new_status);
            // Update cache
            for (size_t j = 0; j < collection->cache_count; ++j) {
                if (collection->cache[j] == collection->items[i]) {
                    free(collection->cache[j]->status);
                    collection->cache[j]->status = strdup(new_status);
                    break;
                }
            }
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Iterate and apply changes
void iterate_and_apply(ItemCollection *collection, void (*apply)(Item*)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        apply(collection->items[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Example of an apply function
void example_apply(Item *item) {
    printf("Item ID: %d, Status: %s, Description: %s\n", item->id, item->status, item->description);
}

// Clean up resources
void cleanup_item_collection(ItemCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->items[i]->status);
        free(collection->items[i]->description);
        custom_free(collection->items[i]);
    }

    for (size_t i = 0; i < collection->cache_count; ++i) {
        free(collection->cache[i]->status);
        custom_free(collection->cache[i]);
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int main() {
    ItemCollection collection;
    init_item_collection(&collection);

    add_item(&collection, 1, "new", "First item");
    add_item(&collection, 2, "in-progress", "Second item");

    update_item(&collection, 1, "updated");

    iterate_and_apply(&collection, example_apply);

    cleanup_item_collection(&collection);
    return 0;
}
