void* memory_management_pipeline(size_t record_count) {
    if (record_count == 0 || (record_count % RECORDS_PER_MULTIPLIER != 0) || record_count >= MAX_RECORDS) {
        fprintf(stderr, "Invalid record count\n");
        return NULL;
    }

    size_t total_memory = calculate_array_size(record_count);
    if (total_memory > MEMORY_LIMIT) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    Record *records = malloc(total_memory);
    if (!records) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    long unique_id = 0;
    int min_key = 1, max_key = 100; // Example range
    double min_val = 0.0, max_val = 10.0; // Example range

    if (!initialize_records(records, record_count, min_key, max_key, min_val, max_val, &unique_id)) {
        free_resources(&records, record_count);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    traverse_and_update_records(records, record_count);

    free_resources(&records, record_count);
    pthread_mutex_unlock(&lock);

    return records;
}

size_t calculate_array_size(size_t record_count) {
    size_t record_size = sizeof(Record);
    return record_count * record_size;
}

int initialize_records(Record *records, size_t record_count, int min_key, int max_key, double min_val, double max_val, long *unique_id) {
    if (!records) return 0;

    int sum_keys = 0;
    srand(time(NULL));

    for (size_t i = 0; i < record_count; ++i) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        sum_keys += records[i].key;
        if (sum_keys > 75000) {
