            return 0;
        }

        records[i].offset = (*unique_id)++;
        records[i].value = min_val + ((double)rand() / RAND_MAX * (max_val - min_val));

        // Simulating skew in key distribution
        if (i % RECORDS_PER_MULTIPLIER == 0 && rand() % 2) {
            records[i].key *= 10;
        }
    }

    return 1;
}

void traverse_and_update_records(Record *records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        // Example operation: updating the 'int' value based on key and double
        records[i].key += (int)(records[i].value % 5);
    }
}

void free_resources(Record **records, size_t record_count) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
}
