['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    bool isActive;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    unsigned long seed;
    size_t garbage_interval;
    size_t next_gc;
} RecordCollection;

unsigned long xorshift32(unsigned long state) {
    // Xorshift algorithm for random number generation
    state ^= state << 13;
    state ^= state >> 17;
    state ^= state << 5;
    return state;
}

int seed_to_key(int index, unsigned long seed) {
    // Simple deterministic key generation based on index and seed
    srand(seed + (unsigned int)index);
    return rand();
}

bool is_unique_key(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->lock);
            return false;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return true;
}

long get_random_offset(long min, long max, unsigned long *state) {
    // Generate a random offset within the specified range
    *state = xorshift32(*state);
    return min + (*state % (max - min + 1));
}

RecordCollection* create_record_collection(size_t capacity, unsigned long seed, size_t garbage_interval, long offset_min, long offset_max) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for RecordCollection\n");
        return NULL;
    }

    collection->records = malloc(capacity * sizeof(Record));
    if (!collection->records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(collection);
        return NULL;
    }

    collection->capacity = capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);
    collection->seed = seed;
    collection->garbage_interval = garbage_interval;
    collection->next_gc = garbage_interval;

    unsigned long random_state = time(NULL);

    for (size_t i = 0; i < capacity; ++i) {
        int key = seed_to_key(i, seed);
        while (!is_unique_key(collection, key)) {
            key = seed_to_key(i, seed + 1); // Adjust seed to generate a new key
        }

        long offset = get_random_offset(offset_min, offset_max, &random_state);

        pthread_mutex_lock(&collection->lock);
        collection->records[collection->count].offset = offset;
        collection->records[collection->count].key = key;
        collection->records[collection->count].isActive = true;
        ++collection->count;
        pthread_mutex_unlock(&collection->lock);
    }

    return collection;
}

void* gc_thread(void *arg) {
    RecordCollection *collection = (RecordCollection *)arg;
    while (1) {
        sleep(collection->garbage_interval);

        pthread_mutex_lock(&collection->lock);
        size_t active_count = 0;
        for (size_t i = 0; i < collection->count; ++i) {
            if (collection->records[i].isActive) {
                collection->records[active_count++] = collection->records[i];
            }
        }
        collection->count = active_count;
        pthread_mutex_unlock(&collection->lock);
    }
    return NULL;
}

void start_gc(RecordCollection *collection) {
    pthread_t gc_thread_id;
    if (pthread_create(&gc_thread_id, NULL, gc_thread, collection)) {
        fprintf(stderr, "Failed to create garbage collector thread\n");
    } else {
        pthread_detach(gc_thread_id);
    }
}

size_t get_active_records_count(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    size_t active_count = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].isActive) {
            ++active_count;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return active_count;
}

size_t get_memory_usage(RecordCollection *collection) {
    return sizeof(RecordCollection) + (collection->capacity * sizeof(Record));
}

void free_record_collection(RecordCollection *collection) {
    if (!collection) return;

    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);

    free(collection->records);
    free(collection);
}
