    compress_string(value, &new_entry->compressed_value);
    new_entry->next = n->entries;
    n->entries = new_entry;
}

node* find_or_create_node(core_components *cc, int key) {
    pthread_mutex_lock(&cc->lock);

    node *current = cc->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&cc->lock);
            return current;
        }
        current = current->next;
    }

    node *new_node = (node *)malloc(sizeof(node));
    new_node->key = key;
    new_node->entries = NULL;

    new_node->next = cc->head;
    cc->head = new_node;

    pthread_mutex_unlock(&cc->lock);
    return new_node;
}

void retry_logic(char *(*fetch_data)(void)) {
    int retries = 0;
    char *data = NULL;
    while (retries < MAX_RETRIES) {
        data = fetch_data();
        if (data != NULL) break;

        usleep(RETRY_INTERVAL_BASE * (1 << retries) * 1000); // Exponential backoff
        ++retries;
    }

    if (data == NULL) {
        fprintf(stderr, "Failed to fetch data after %d attempts.\n", MAX_RETRIES);
    } else {
        printf("Data fetched: %s\n", data);
        free(data);
    }
}

