    pthread_mutex_lock(&cc->lock);

    node **current = &cc->head;
    while (*current != NULL) {
        node *entry = *current;
        if (difftime(time(NULL), entry->last_accessed) > cutoff_time) {
            // Remove this node
            *current = entry->next;
            free(entry);
        } else {
            current = &entry->next;
        }
    }

    pthread_mutex_unlock(&cc->lock);
}

