```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_MB 160
#define MB_TO_BYTES (1024 * 1024)
#define ARRAY_ALIGNMENT sizeof(long)

typedef struct {
    int value;
    long offset;
    double floating_point;
} record_t;

typedef struct {
    int *keys;
    long *offsets;
    double *floats;
    record_t *records;
    size_t num_records;
} MemoryManager;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void free_memory(MemoryManager *manager) {
    if (manager->keys) free(manager->keys);
    if (manager->offsets) free(manager->offsets);
    if (manager->floats) free(manager->floats);
    if (manager->records) free(manager->records);
}

int calculate_num_records(size_t max_memory, size_t record_size) {
    return max_memory / (record_size * 7); // Ensure multiple of 7
}

size_t aligned_size(size_t size, size_t alignment) {
    return ((size + alignment - 1) & ~(alignment - 1));
}

MemoryManager* allocate_memory(size_t num_records) {
    pthread_mutex_lock(&memory_lock);

    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) {
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    size_t record_size = sizeof(record_t);
    size_t total_memory_needed = num_records * record_size;

    if (total_memory_needed > MAX_MEMORY_MB * MB_TO_BYTES) {
        free(manager);
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    manager->num_records = num_records;

    size_t aligned_num_records = aligned_size(num_records, ARRAY_ALIGNMENT);

    manager->keys = (int*)aligned_alloc(ARRAY_ALIGNMENT, num_records * sizeof(int));
    manager->offsets = (long*)aligned_alloc(ARRAY_ALIGNMENT, num_records * sizeof(long));
    manager->floats = (double*)aligned_alloc(ARRAY_ALIGNMENT, num_records * sizeof(double));
    manager->records = (record_t*)aligned_alloc(ARRAY_ALIGNMENT, aligned_num_records * record_size);

    if (!manager->keys || !manager->offsets || !manager->floats || !manager->records) {
        free_memory(manager);
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    // Initialize records
    srand(time(NULL));
    int sum_keys = 0;

    for (size_t i = 0; i < num_records; ++i) {
        manager->keys[i] = rand() % 100 + 1;
        sum_keys += manager->keys[i];

        if (sum_keys > 75000) {
            free_memory(manager);
            pthread_mutex_unlock(&memory_lock);
            return NULL;
        }

        manager->offsets[i] = i;

        double random_double = ((double)rand() / RAND_MAX) * 100.0;

        manager->records[i].value = manager->keys[i];
        manager->records[i].offset = manager->offsets[i];
        manager->records[i].floating_point = random_double;
    }

    pthread_mutex_unlock(&memory_lock);
    return manager;
}

void resize_memory(MemoryManager *manager, size_t new_num_records) {
    pthread_mutex_lock(&memory_lock);

    if (new_num_records > manager->num_records && 
        new_num_records * sizeof(record_t) > MAX_MEMORY_MB * MB_TO_BYTES) {
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    free_memory(manager);

    size_t aligned_new_num_records = aligned_size(new_num_records, ARRAY_ALIGNMENT);

    manager->keys = (int*)aligned_alloc(ARRAY_ALIGNMENT, new_num_records * sizeof(int));
    manager->offsets = (long*)aligned_alloc(ARRAY_ALIGNMENT, new_num_records * sizeof(long));
    manager->floats = (double*)aligned_alloc(ARRAY_ALIGNMENT, new_num_records * sizeof(double));
    manager->records = (record_t*)aligned_alloc(ARRAY_ALIGNMENT, aligned_new_num_records * sizeof(record_t));

    if (!manager->keys || !manager->offsets || !manager->floats || !manager->records) {
        free_memory(manager);
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    manager->num_records = new_num_records;

    for (size_t i = 0; i < new_num_records; ++i) {
        manager->keys[i] = rand() % 100 + 1;
        manager->offsets[i] = i;
        manager->records[i].value = manager->keys[i];
        manager->records[i].offset = manager->offsets[i];
        manager->records[i].floating_point = ((double)rand() / RAND_MAX) * 100.0;
    }

    pthread_mutex_unlock(&memory_lock);
}

void update_record_values(MemoryManager *manager, int (*operation)(int, double)) {
    if (!manager || !manager->records) return;

    for (size_t i = 0; i < manager->num_records; ++i) {
        manager->records[i].value = operation(manager->keys[i], manager->records[i].floating_point);
    }
}

void perform_task(MemoryManager *manager, int (*operation)(int, double)) {
    if (!manager || !manager->records) return;

    size_t num_threads = 4;
    pthread_t threads[num_threads];
    size_t chunk_size = manager->num_records / num_threads;

    for (size_t i = 0; i < num_threads; ++i) {
        int start_index = i * chunk_size;
        int end_index = (i == num_threads - 1) ? manager->num_records : start_index + chunk_size;

        pthread_create(&threads[i], NULL, (void *(*)(void *))update_record_values, (void *)(intptr_t)start_index);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int example_operation(int key, double floating_point) {
    return key + (int)(floating_point * 10);
}

void simulate_concurrent_execution() {
    MemoryManager *manager = allocate_memory(1000);

    if (!manager) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }

    perform_task(manager, example_operation);

    free_memory(manager);
}

int main() {
    simulate_concurrent_execution();
    return 0;
}
