#define MAX_CONNECTIONS 10000

typedef enum {
    STATE_ESTABLISHED,
    STATE_IDLE,
    STATE_CLOSED
} ConnectionState;

typedef struct ConnectionObject {
    int socket_descriptor;
    ConnectionState state;
    uint32_t inactivity_timeout; // seconds
} ConnectionObject;

// Mutex for thread-safe access to the connection pool
pthread_mutex_t connection_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
ConnectionObject* connection_pool[MAX_CONNECTIONS];
int pool_size = 0;

// Function declarations
void initialize_connection(ConnectionObject* conn, int socket_descriptor);
void update_connection_state(ConnectionObject* conn, ConnectionState state);
void serialize_connection(const ConnectionObject* conn, uint8_t** output, size_t* length);
void deserialize_connection(uint8_t* input, size_t length, ConnectionObject* conn);
void log_message(const char* message);

// C function to initialize a connection
void create_connection(int socket_descriptor) {
    pthread_mutex_lock(&connection_pool_mutex);

    if (pool_size < MAX_CONNECTIONS) {
        ConnectionObject* new_conn = (ConnectionObject*)malloc(sizeof(ConnectionObject));
        if (!new_conn) {
            log_message("Memory allocation failed");
            pthread_mutex_unlock(&connection_pool_mutex);
            return;
        }

        initialize_connection(new_conn, socket_descriptor);
        connection_pool[pool_size++] = new_conn;

        log_message("Connection created and added to pool");

    } else {
        log_message("Connection pool is full");
    }

    pthread_mutex_unlock(&connection_pool_mutex);
}

void initialize_connection(ConnectionObject* conn, int socket_descriptor) {
    conn->socket_descriptor = socket_descriptor;
    conn->state = STATE_ESTABLISHED; // default state
    conn->inactivity_timeout = 60;   // default timeout (seconds)
}

void update_connection_state(ConnectionObject* conn, ConnectionState state) {
    pthread_mutex_lock(&connection_pool_mutex);

    if (conn && pool_size > 0) {
        conn->state = state;
        log_message("Connection state updated");
    }

    pthread_mutex_unlock(&connection_pool_mutex);
}

void serialize_connection(const ConnectionObject* conn, uint8_t** output, size_t* length) {
    *length = sizeof(int32_t) + sizeof(uint32_t); // socket_descriptor and inactivity_timeout
    *output = (uint8_t*)malloc(*length);

    if (*output) {
        memcpy(*output, &conn->socket_descriptor, sizeof(conn->socket_descriptor));
        uint32_t timeout_be = htonl(conn->inactivity_timeout);
        memcpy((*output) + sizeof(conn->socket_descriptor), &timeout_be, sizeof(timeout_be));

        log_message("Connection serialized");
    } else {
        log_message("Serialization failed due to memory allocation error");
    }
}

void deserialize_connection(uint8_t* input, size_t length, ConnectionObject* conn) {
    if (length == 0 || !input || !conn) return;

    memcpy(&conn->socket_descriptor, input, sizeof(conn->socket_descriptor));
    uint32_t timeout_be;
    memcpy(&timeout_be, input + sizeof(conn->socket_descriptor), sizeof(timeout_be));
    conn->inactivity_timeout = ntohl(timeout_be);

    log_message("Connection deserialized");
}

void log_message(const char* message) {
    printf("[LOG] %s\n", message);
}

