    if (size < 12) return -1;

    memcpy(&rec->value, buffer, sizeof(rec->value));
    memcpy(&rec->offset, buffer + sizeof(rec->value), sizeof(rec->offset));

    return 0;
}

// Function to compress data
int compress_data(const uint8_t *data, size_t data_size, uint8_t **compressed_data, size_t *compressed_size) {
    uLongf compressed_data_size = compressBound(data_size);
    *compressed_data = malloc(compressed_data_size);

    if (!*compressed_data || compress(*compressed_data, &compressed_data_size, data, data_size) != Z_OK) {
        free(*compressed_data);
        return -1;
    }

    *compressed_size = compressed_data_size;
    return 0;
}

