    record *records = malloc(sizeof(record) * max_records_per_batch);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (size_t i = 0; i < max_records_per_batch; ++i) {
        records[i].value = rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1) + INT_RANGE_MIN;
        records[i].offset = rand(); // Example offset generation
    }

    pthread_t threads[max_records_per_batch];
    size_t batch_size = max_records_per_batch / 4; // Adjust based on resources

    for (size_t i = 0; i < max_records_per_batch; i += batch_size) {
        if (i + batch_size > max_records_per_batch) batch_size = max_records_per_batch - i;
        pthread_create(&threads[i / batch_size], NULL, process_batch, &records[i]);
    }

    for (size_t i = 0; i < max_records_per_batch / batch_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Serialize, compress and store records
    uint8_t *serialized_data;
    size_t serialized_size;

    for (size_t i = 0; i < max_records_per_batch; ++i) {
        if (serialize_record(&records[i], &serialized_data, &serialized_size) == -1) {
            fprintf(stderr, "Serialization failed\n");
            return -1;
        }

        uint8_t *compressed_data;
        size_t compressed_size;

        if (compress_data(serialized_data, serialized_size, &compressed_data, &compressed_size) == -1) {
            fprintf(stderr, "Compression failed\n");
            free(serialized_data);
            return -1;
        }

        // Calculate checksum
        uint32_t checksum = calculate_checksum(compressed_data, compressed_size);

        // Store in database (mockup)
        db_connection conn;
        db_init(&conn);
        if (!db_insert(&conn, records, 1)) {
            fprintf(stderr, "Database insertion failed\n");
        }

        free(serialized_data);
        free(compressed_data);
    }

    free(records);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <records_per_batch>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t records_per_batch = atoi(argv[1]);
    if (records_per_batch * sizeof(record) > MAX_SIZE) {
        fprintf(stderr, "Batch size exceeds memory limit\n");
        return EXIT_FAILURE;
    }

    manage_records(records_per_batch, MAX_SIZE);
    return 0;
}
