#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_STRING_LENGTH 50
#define MAX_MEMORY_SIZE 1024 * 1024 // Example max memory size: 1MB
#define INITIAL_CAPACITY 10

typedef struct {
    int value;
    long offset;
    char identifier[MAX_STRING_LENGTH + 1];
    time_t timestamp;
} Record;

// Global atomic variables for thread safety
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t total_allocated_memory = 0;

void* safe_malloc(size_t size, const char* description) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory: %s\n", description);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&log_mutex);
    total_allocated_memory += size;
    printf("Allocated %zu bytes for %s. Total allocated: %zu bytes.\n", size, description, total_allocated_memory);
    pthread_mutex_unlock(&log_mutex);
    return ptr;
}

void safe_free(void* ptr, const char* description) {
    if (ptr) {
        pthread_mutex_lock(&log_mutex);
        total_allocated_memory -= sizeof(*ptr); // This is a simplification
        printf("Freed memory for %s. Total allocated: %zu bytes.\n", description, total_allocated_memory);
        pthread_mutex_unlock(&log_mutex);
        free(ptr);
    }
}

void* safe_realloc(void* ptr, size_t new_size, const char* description) {
    void* new_ptr = realloc(ptr, new_size);
    if (!new_ptr) {
        fprintf(stderr, "Failed to reallocate memory: %s\n", description);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&log_mutex);
