#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    char *identifier;
    struct Record *next;
} Record;

typedef struct {
    Record *head;
    pthread_mutex_t lock;
} RecordList;

void initialize_record_list(RecordList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int generate_random_key(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* allocate_identifier(const char *data_source) {
    size_t len = strlen(data_source) + 1;
    char *identifier = malloc(len);
    if (!identifier) return NULL;
    strcpy(identifier, data_source);
    return identifier;
}

int insert_record(RecordList *list, int min_key_range, int max_key_range, const char *data_source) {
    pthread_mutex_lock(&list->lock);

    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    new_record->key = generate_random_key(min_key_range, max_key_range);
    new_record->identifier = allocate_identifier(data_source);
    if (!new_record->identifier) {
        free(new_record);
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    new_record->next = list->head;
    list->head = new_record;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

void cleanup_records(RecordList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *next = current->next;
        free(current->identifier);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int main() {
    srand(time(NULL));

    const int num_records = 1000; // Example number
    const int min_key_range = 1;
    const int max_key_range = 1000;
    const char *data_source = "ExampleData"; // Placeholder data source

    RecordList list;
    initialize_record_list(&list);

    int initialized_count = 0;

    for (int i = 0; i < num_records; ++i) {
        if (insert_record(&list, min_key_range, max_key_range, data_source)) {
            ++initialized_count;
        }
    }

    printf("Total records successfully initialized: %d\n", initialized_count);

    cleanup_records(&list);

    return 0;
}
```

