#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef int key_t;
typedef int value_t;
typedef long timestamp_t;
typedef size_t offset_t;

#define MAX_KEY_VALUE 10000

typedef struct {
    key_t key;
    value_t value;
    timestamp_t timestamp;
} record_t;

// Function prototypes
int init_collection(offset_t *offsets, key_t **keys, record_t **records, offset_t initial_size);
int add_record(offset_t *offsets, key_t *keys, record_t *records, offset_t *current_size, key_t new_key);
int remove_record(offset_t *offsets, key_t *keys, record_t *records, offset_t current_size, key_t key_to_remove);
void free_collection(offset_t offsets[], key_t keys[], record_t records[], offset_t current_size);

// Initialize the collection with dynamic memory allocation
int init_collection(offset_t *offsets, key_t **keys, record_t **records, offset_t initial_size) {
    if (initial_size == 0) return -1;

    // Allocate and zero-initialize memory
    offsets[0] = initial_size; // Store the size in the first element
    *keys = calloc(initial_size, sizeof(key_t));
    *records = calloc(initial_size, sizeof(record_t));

    if (!(*keys) || !(*records)) {
        free(*keys);
        free(*records);
        return -1;
    }

    return 0;
}

// Add a new record ensuring no duplicate keys
int add_record(offset_t *offsets, key_t *keys, record_t *records, offset_t *current_size, key_t new_key) {
    if (!new_key || !offsets || !*current_size) return -1;

    // Check for duplicates
    for (offset_t i = 0; i < offsets[0]; ++i) {
        if (keys[i] == new_key) return -2; // Key already exists
    }

    // Resize the arrays if needed
    if (*current_size >= offsets[0]) {
        offset_t new_size = *current_size + (*current_size >> 1); // Increase size by 50%
        if (new_size <= *current_size) { // Handle overflow
            return -3;
        }

        keys = realloc(keys, new_size * sizeof(key_t));
        records = realloc(records, new_size * sizeof(record_t));

        if (!keys || !records) return -1; // Reallocation failed

        offsets[0] = new_size;
    }

    // Add the record
    key_t index = *current_size;
    keys[index] = new_key;
    records[index].value = rand() % MAX_KEY_VALUE;
    records[index].timestamp = time(NULL);
    (*current_size)++;

    return 0; // Success
}

// Remove a record by its key
int remove_record(offset_t *offsets, key_t *keys, record_t *records, offset_t current_size, key_t key_to_remove) {
    if (!key_to_remove || !offsets || offsets[0] == 0) return -1;

    int found = 0;
    for (offset_t i = 0; i < current_size; ++i) {
        if (keys[i] == key_to_remove) {
            found = 1;

            // Shift elements to fill the gap
            memmove(&keys[i], &keys[i + 1], (current_size - i - 1) * sizeof(key_t));
            memmove(&records[i], &records[i + 1], (current_size - i - 1) * sizeof(record_t));

            current_size--;
            break;
        }
    }

    if (!found) return -2; // Key not found

    return 0; // Success
}

// Free all allocated memory
void free_collection(offset_t offsets[], key_t keys[], record_t records[], offset_t current_size) {
    free(keys);
    free(records);
}

int main() {
    offset_t initial_size = 10;
    offset_t *offsets = malloc(sizeof(offset_t));
    key_t *keys = NULL;
    record_t *records = NULL;

    if (init_collection(offsets, &keys, &records, initial_size) != 0) {
        fprintf(stderr, "Failed to initialize collection.\n");
        return EXIT_FAILURE;
    }

    offset_t current_size = 0;

    // Example usage: Add records
    for (int i = 1; i <= 15; ++i) {
        if (add_record(offsets, keys, records, &current_size, i) != 0) {
            fprintf(stderr, "Failed to add record with key %d.\n", i);
        }
    }

    // Example usage: Remove a record
    if (remove_record(offsets, keys, records, current_size, 5) != 0) {
        fprintf(stderr, "Failed to remove record with key 5.\n");
    }

    free_collection(offsets, keys, records, current_size);

    free(offsets);
    return EXIT_SUCCESS;
}
```

This code provides a flexible and dynamic way to manage memory for storing variable-sized collections of records while addressing the outlined concerns such as avoiding integer overflow during array resizing and ensuring no duplicate `key_t` values exist.']

