#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 1000

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    long offset;
    int key;
    int *valueArray;
    double floatingNumber;
    Point point;
    char *filePath;
} Record;

typedef struct {
    time_t timestamp;
    char message[256];
} LogEntry;

LogEntry logEntries[MAX_RECORDS];
int logCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int allocatedRecords = 0;

void logOperation(const char* operation) {
    pthread_mutex_lock(&mutex);
    if (logCount < MAX_RECORDS) {
        time_t now = time(NULL);
        snprintf(logEntries[logCount].message, sizeof(logEntries[logCount].message), "%s at %ld", operation, now);
        logEntries[logCount].timestamp = now;
        logCount++;
    }
    pthread_mutex_unlock(&mutex);
}

void *allocateMemoryForRecords(size_t recordSize, size_t valueArraySize) {
    if (allocatedRecords >= MAX_RECORDS) return NULL;

    Record *records = malloc(recordSize * sizeof(Record));
    if (!records) return NULL;

    for (int i = 0; i < recordSize; ++i) {
        records[i].offset = rand() % 100;
        records[i].key = rand() % 50;
        records[i].valueArray = malloc(valueArraySize * sizeof(int));
        if (!records[i].valueArray) {
            for (int j = 0; j < i; ++j) free(records[j].valueArray);
            free(records);
            return NULL;
        }
        records[i].floatingNumber = rand() % 100 + 1.0;

        int x = rand() % 10 + 1.0;
        int y = rand() % 10 + 1.0;
        records[i].point.x = (float)x;
        records[i].point.y = (float)y;

        char *filePaths[] = {"/path/to/file1", "/path/to/file2", "/path/to/file3"};
        records[i].filePath = strdup(filePaths[rand() % 3]);
    }

    pthread_mutex_lock(&mutex);
    allocatedRecords += recordSize;
    logOperation("Memory Allocation");
    pthread_mutex_unlock(&mutex);

    return records;
}

void cleanup(Record *records, size_t recordCount) {
    if (!records) return;

    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i].valueArray);
        free(records[i].filePath);
    }
    free(records);

    pthread_mutex_lock(&mutex);
    allocatedRecords = 0;
    logOperation("Memory Cleanup");
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL));

    size_t recordSize = 10;
    size_t valueArraySize = 5;

    Record *records = allocateMemoryForRecords(recordSize, valueArraySize);
    if (records) {
        cleanup(records, recordSize);
    }

    return 0;
}
```

