typedef struct RateLimiter {
    unsigned long last_request_time;
    unsigned int request_count;
} RateLimiter;

RateLimiter* getUserRateLimiter(int userID) {
    static RateLimiter *limiters = NULL;
    if (limiters == NULL) {
        limiters = malloc(sizeof(RateLimiter) * 100); // Assuming max 100 users
        memset(limiters, 0, sizeof(RateLimiter) * 100);
    }
    return &limiters[userID % 100];
}

int isRateLimited(int userID) {
    RateLimiter *limiter = getUserRateLimiter(userID);
    unsigned long current_time = time(NULL);

    if (current_time - limiter->last_request_time > 60) {
        // Reset the counter every minute
        limiter->request_count = 0;
        limiter->last_request_time = current_time;
    }

    if (limiter->request_count >= REQUEST_LIMIT_PER_MINUTE)
        return 1;

    ++limiter->request_count;
    return 0;
}

void logMessage(const char* message) {
    printf("%s\n", message); // Simple logging function, can be replaced with a more robust system
}

int handleHTTPPOST(int pageSectionID, int elementID, const char *htmlContent, int userID) {
    if (isRateLimited(userID)) {
        logMessage("Rate limit exceeded");
        return -1;
    }

    pthread_mutex_lock(&lock);

    long* offsets = malloc(sizeof(long) * LONG_ARRAY_SIZE);
    int* keys = malloc(sizeof(int) * INT_KEYS_SIZE);

    Record* records = malloc(sizeof(Record) * NUM_RECORDS);
    if (!offsets || !keys || !records) {
        logMessage("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Initialize arrays
    memset(offsets, 0, sizeof(long) * LONG_ARRAY_SIZE);
    memset(keys, 0, sizeof(int) * INT_KEYS_SIZE);

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].value = rand() % 100; // Random value within a range
    }

    // Simulate updating HTML content using service class
    logMessage("Updating HTML content");

    // Serialize the updated content into a byte array (example)
    unsigned char* serializedContent = malloc(strlen(htmlContent) + 1);
    if (!serializedContent) {
        logMessage("Serialization memory allocation failed");
        pthread_mutex_unlock(&lock);
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    memcpy(serializedContent, htmlContent, strlen(htmlContent));
    serializedContent[strlen(htmlContent)] = '\0'; // Null-terminate the string

    logMessage("HTML content updated successfully");

    // Memory deallocation
    free(offsets);
    free(keys);
    free(records);
    free(serializedContent);

    pthread_mutex_unlock(&lock);

    return 0;
}
