#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PRIORITY 3

typedef struct {
    char *title;
    int priority;
    time_t target_date;
} Project;

Project* create_projects(int num_projects, int project_id_start) {
    if (num_projects <= 0 || project_id_start < 1) return NULL;

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for projects array
    Project *projects = malloc(num_projects * sizeof(Project));
    if (!projects) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time_t current_time;
    time(&current_time);

    for (int i = 0; i < num_projects; ++i) {
        int project_id = project_id_start + i;

        // Allocate and initialize title
        projects[i].title = malloc(50 * sizeof(char));
        if (!projects[i].title) {
            fprintf(stderr, "Memory allocation failed for title\n");
            free_projects(projects, num_projects);
            return NULL;
        }
        snprintf(projects[i].title, 50, "Project_%d", project_id);

        // Assign random priority
        projects[i].priority = rand() % MAX_PRIORITY;

        // Calculate and set target_date
        int delay_weeks = 1 + rand() % 4; // Random weeks between 1 to 4
        time_t delay_seconds = delay_weeks * 7 * 24 * 60 * 60;
        projects[i].target_date = current_time + delay_seconds;
    }

    return projects;
}

void free_projects(Project *projects, int num_projects) {
    if (!projects) return;

    for (int i = 0; i < num_projects; ++i) {
        free(projects[i].title);
    }
    free(projects);
}
