typedef struct HashNode {
    char *city_name;
    weather_t *weather_data;
    struct HashNode *next;
} HashNode;

#define TABLE_SIZE 101

// Global variables for data management
float *temperature_array;
char **city_names;
HashNode *hash_table[TABLE_SIZE];
pthread_mutex_t hash_locks[TABLE_SIZE];

// Function to initialize the arrays and hash table
int init_weather_records(size_t num_records) {
    if (num_records == 0 || temperature_array != NULL || city_names != NULL) {
        return -1;
    }

    // Allocate memory for arrays
    temperature_array = malloc(num_records * sizeof(float));
    city_names = malloc(num_records * sizeof(char *));

    if (!temperature_array || !city_names) {
        free(temperature_array);
        free(city_names);
        return -1;
    }

    // Initialize hash table and locks
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_locks[i], NULL);
    }

    // Return the number of initialized records
    return num_records;
}

// Hash function to map city names to table indices
unsigned int hash_function(const char *city_name) {
    unsigned long hash = 5381;
    int c;
    while ((c = *city_name++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % TABLE_SIZE;
}

// Function to insert weather data into the hash table
int add_weather_record(const char *city_name, float temperature, int humidity, const char *description) {
    unsigned int index = hash_function(city_name);

    pthread_mutex_lock(&hash_locks[index]);

    HashNode *current = hash_table[index];
    while (current != NULL) {
        if (strcmp(current->city_name, city_name) == 0) {
            // Update existing record
            current->weather_data->temperature = temperature;
            current->weather_data->humidity = humidity;
            free(current->weather_data->description);
            current->weather_data->description = strdup(description);

            pthread_mutex_unlock(&hash_locks[index]);
            return 1;
        }
        current = current->next;
    }

    // Add new record
    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&hash_locks[index]);
        return -1;
    }

    new_node->city_name = strdup(city_name);
    new_node->weather_data = malloc(sizeof(weather_t));
    if (!new_node->weather_data || !new_node->city_name) {
        free(new_node->city_name);
        free(new_node);
        pthread_mutex_unlock(&hash_locks[index]);
        return -1;
    }

    new_node->weather_data->temperature = temperature;
    new_node->weather_data->humidity = humidity;
    new_node->weather_data->description = strdup(description);

    if (!new_node->weather_data->description) {
        free(new_node->city_name);
        free(new_node->weather_data);
        free(new_node);
        pthread_mutex_unlock(&hash_locks[index]);
        return -1;
    }

    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    pthread_mutex_unlock(&hash_locks[index]);

    // Store data in arrays (for demonstration purposes)
    for (size_t i = 0; i < num_records; ++i) {
        if (!city_names[i]) {
            city_names[i] = strdup(city_name);
            temperature_array[i] = temperature;
            break;
        }
    }

    return 1;
}

// Function to free allocated resources
void cleanup_weather_records() {
    for (size_t i = 0; i < TABLE_SIZE; ++i) {
        HashNode *current = hash_table[i];
        while (current != NULL) {
            HashNode *temp = current;
            current = current->next;

            free(temp->city_name);
            free(temp->weather_data->description);
            free(temp->weather_data);
            free(temp);
        }
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&hash_locks[i]);
    }

    free(temperature_array);
    temperature_array = NULL;

    for (size_t i = 0; i < num_records; ++i) {
        if (city_names[i]) {
            free(city_names[i]);
        }
    }
    free(city_names);
    city_names = NULL;
}

