    strcpy(serializedData, request->htmlContent);

    // Log the update
    printf("Serialized Data: %s\n", serializedData);

    // Free allocated memory
    free(records);
    free(serializedData);
}

void initDynamicRangeGenerator(DynamicRateGenerator *gen, long minVal, long maxVal) {
    gen->minValue = minVal;
    gen->maxValue = maxVal;
    pthread_mutex_init(&gen->lock, NULL);
}

long generateRandomIntInRange(DynamicRateGenerator *gen) {
    pthread_mutex_lock(&gen->lock);
    long result = rand() % (gen->maxValue - gen->minValue + 1) + gen->minValue;
    pthread_mutex_unlock(&gen->lock);
    return result;
}

float generateRandomFloatInRange(DynamicRateGenerator *gen) {
    pthread_mutex_lock(&gen->lock);
    float result = ((float)rand() / RAND_MAX) * (gen->maxValue - gen->minValue) + gen->minValue;
    pthread_mutex_unlock(&gen->lock);
    return result;
}
