#define MAX_CONNECTIONS 5000
#define MEMORY_LIMIT (1024 * 1024 * 100) // Example: 100MB memory limit

typedef enum {
    ESTABLISHED,
    DISCONNECTED,
    BUSY,
    ERROR,
    CUSTOM_STATE // Add more custom states as needed
} ConnectionState;

typedef struct QueryInfo {
    char sql_query[256];
} QueryInfo;

typedef struct DatabaseConnection {
    char db_name[128];
    ConnectionState status;
    time_t last_accessed;
    int query_count;
    int total_execution_time_ms; // Sum of execution times in milliseconds
    QueryInfo *recent_queries;
    size_t recent_queries_size;
    size_t max_recent_queries;
} DatabaseConnection;

typedef struct {
    DatabaseConnection *connections;
    size_t current_size;
    pthread_rwlock_t lock;
    void (*log_event)(const char *);
} ConnectionPool;

typedef struct Record {
    int value;
    long offset;
    char schema_name[64];
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
    size_t max_memory_usage; // in bytes
} RecordArray;

void log_event(const char *message) {
    printf("[LOG] %s\n", message);
}

ConnectionPool* create_connection_pool(size_t initial_capacity, void (*log_fn)(const char *)) {
    ConnectionPool *pool = (ConnectionPool *)malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;

    pool->connections = (DatabaseConnection *)calloc(initial_capacity, sizeof(DatabaseConnection));
    if (!pool->connections) {
        free(pool);
        log_fn("Failed to allocate memory for connection pool.");
        return NULL;
    }
    pool->current_size = initial_capacity;
    pthread_rwlock_init(&pool->lock, NULL);
    pool->log_event = log_fn;

    return pool;
}

int add_connection(ConnectionPool *pool, const char *db_name) {
    if (!pool) return -1;

    pthread_rwlock_wrlock(&pool->lock);
    for (size_t i = 0; i < pool->current_size; ++i) {
        DatabaseConnection *conn = &pool->connections[i];
        if (strcmp(conn->db_name, "") == 0) {
            strncpy(conn->db_name, db_name, sizeof(conn->db_name));
            conn->status = DISCONNECTED;
            conn->last_accessed = time(NULL);
            conn->query_count = 0;
            conn->total_execution_time_ms = 0;
            conn->recent_queries_size = 10; // Example size
            conn->max_recent_queries = 10;
            conn->recent_queries = (QueryInfo *)calloc(conn->recent_queries_size, sizeof(QueryInfo));
            if (!conn->recent_queries) {
                pthread_rwlock_unlock(&pool->lock);
                log_event("Failed to allocate memory for recent queries.");
                return -1;
            }
            pthread_rwlock_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&pool->lock);
    log_event("Connection pool is full, unable to add new connection.");
    return -1;
}

RecordArray* create_record_array(size_t capacity, size_t max_memory_usage) {
    RecordArray *array = (RecordArray *)malloc(sizeof(RecordArray));
    if (!array) return NULL;

    array->records = (Record *)calloc(capacity, sizeof(Record));
    if (!array->records) {
        free(array);
        log_event("Failed to allocate memory for record array.");
        return NULL;
    }
    array->capacity = capacity;
    array->used = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->max_memory_usage = max_memory_usage;

    return array;
}

int add_record(RecordArray *array, int value, long offset, const char *schema_name) {
    if (!array || !schema_name) return -1;

    size_t record_size = sizeof(Record) + strlen(schema_name);
    if (record_size > array->max_memory_usage / array->capacity) {
        log_event("Memory limit exceeded for records.");
        return -1;
    }

    pthread_mutex_lock(&array->mutex);
    if (array->used >= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        log_event("Record array is full, unable to add new record.");
        return -1;
    }

    Record *record = &array->records[array->used++];
    record->value = value;
    record->offset = offset;
    strncpy(record->schema_name, schema_name, sizeof(record->schema_name));
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

void free_connection_pool(ConnectionPool *pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->current_size; ++i) {
        DatabaseConnection *conn = &pool->connections[i];
        if (conn->recent_queries) {
            free(conn->recent_queries);
        }
    }

    free(pool->connections);
    pthread_rwlock_destroy(&pool->lock);
    free(pool);
}

void free_record_array(RecordArray *array) {
    if (!array) return;

    free(array->records);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
