#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <errno.h>

#define MAX_MEMORY_USAGE 1048576 // Example max memory usage (1MB)
#define TIMESTAMP_RANGE_SECONDS 1000

typedef struct {
    char *buffer;
    time_t timestamp;
    int ack_flag;
} Message;

typedef struct {
    Message *messages;
    size_t count;
    size_t capacity;
    size_t current_memory_usage;
    pthread_mutex_t lock;
} MessageCollection;

// Helper function to initialize a message
int init_message(Message *message, const char *data) {
    if (!message || !data) return -1;

    message->buffer = strdup(data);
    if (!message->buffer) return -ENOMEM;

    message->timestamp = time(NULL); // Replace with seeded logic if needed
    message->ack_flag = 0;
    return 0;
}

// Helper function to free a message
void free_message(Message *message) {
    if (message && message->buffer) {
        free(message->buffer);
        memset(message, 0, sizeof(Message));
    }
}

// Initialize the collection
int init_collection(MessageCollection *collection, size_t initial_capacity) {
    if (!collection) return -1;

    pthread_mutex_init(&collection->lock, NULL);
    collection->messages = calloc(initial_capacity, sizeof(Message));
    if (!collection->messages) {
        pthread_mutex_destroy(&collection->lock);
        return -ENOMEM;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->current_memory_usage = sizeof(MessageCollection) + (initial_capacity * sizeof(Message));

    // Seed the random number generator
    srand((unsigned int)time(NULL));
    return 0;
}

// Add a message to the collection
int add_message(MessageCollection *collection, const char *data) {
    if (!collection || !data) return -1;

    pthread_mutex_lock(&collection->lock);

    size_t new_capacity = collection->capacity;
    while (collection->count >= new_capacity || 
           collection->current_memory_usage + strlen(data) + 1 > MAX_MEMORY_USAGE) {
        new_capacity *= 2; // Double the capacity
        Message *new_messages = realloc(collection->messages, new_capacity * sizeof(Message));
        if (!new_messages) {
            pthread_mutex_unlock(&collection->lock);
            return -ENOMEM;
        }
        collection->messages = new_messages;
        collection->capacity = new_capacity;
    }

    if (init_message(&collection->messages[collection->count], data) != 0) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Handle error
    }

    collection->count++;
    collection->current_memory_usage += strlen(data) + 1;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Serialize a message to a byte array
int serialize_message(const Message *message, uint8_t **out_buffer, size_t *out_size) {
    if (!message || !out_buffer || !out_size) return -1;

    size_t buffer_len = strlen(message->buffer);
    *out_size = sizeof(time_t) + buffer_len + sizeof(int);

    *out_buffer = malloc(*out_size);
    if (!*out_buffer) return -ENOMEM;

    uint8_t *ptr = *out_buffer;
    memcpy(ptr, &message->timestamp, sizeof(time_t));
    ptr += sizeof(time_t);

    memcpy(ptr, message->buffer, buffer_len);
    ptr += buffer_len;

    int network_ack_flag = htonl(message->ack_flag);
    memcpy(ptr, &network_ack_flag, sizeof(int));

    return 0;
}

// Deserialize a byte array into a message
int deserialize_message(const uint8_t *in_buffer, size_t in_size, Message *message) {
    if (!in_buffer || !message || in_size < (sizeof(time_t) + sizeof(int))) return -1;

    const uint8_t *ptr = in_buffer;
    memcpy(&message->timestamp, ptr, sizeof(time_t));
    ptr += sizeof(time_t);

    size_t buffer_len = in_size - (ptr - in_buffer) - sizeof(int);
    message->buffer = malloc(buffer_len + 1);
    if (!message->buffer) return -ENOMEM;

    memcpy(message->buffer, ptr, buffer_len);
    message->buffer[buffer_len] = '\0';

    int network_ack_flag;
    memcpy(&network_ack_flag, ptr + buffer_len, sizeof(int));
    message->ack_flag = ntohl(network_ack_flag);

    return 0;
}

// Free the collection
void free_collection(MessageCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; i++) {
        free_message(&collection->messages[i]);
    }
    free(collection->messages);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
}

// Helper function to find the largest integer
void find_largest_integer() {
    int n, *arr, max_val = INT_MIN;

    printf("Enter number of integers: ");
    if (scanf("%d", &n) != 1 || n <= 0) return;

    arr = malloc(n * sizeof(int));
    if (!arr) return;

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &arr[i]) != 1) break;
    }

    for (int i = 0; i < n; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }

    printf("Largest integer: %d\n", max_val);
    free(arr);
}

// Logging function
void log_event(const char *event) {
    time_t now;
    time(&now);
    fprintf(stdout, "[%s] %s\n", ctime(&now), event);
}

int main() {
    MessageCollection collection;

    if (init_collection(&collection, 10) != 0) {
        log_event("Failed to initialize message collection");
        return -1;
    }

    log_event("Initialized message collection");

    add_message(&collection, "Hello, World!");
    log_event("Added a new message");

    // Example usage of serialization
    uint8_t *buffer;
    size_t buffer_size;

    if (serialize_message(&collection.messages[0], &buffer, &buffer_size) == 0) {
        log_event("Serialized a message");
    } else {
        log_event("Failed to serialize a message");
    }

    free_collection(&collection);
    log_event("Freed the message collection");

    find_largest_integer();

    return 0;
}
