#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int integer;
    double dbl;
    char *identifier;
} data;

typedef struct {
    long *offsets;
    int *keys;
    double *values;
    data *entries;
    size_t count;
    size_t capacity;
} DataStore;

void initializeDataStore(DataStore *store, size_t initialCapacity) {
    store->capacity = initialCapacity;
    store->count = 0;

    store->offsets = (long *)calloc(initialCapacity, sizeof(long));
    store->keys = (int *)calloc(initialCapacity, sizeof(int));
    store->values = (double *)calloc(initialCapacity, sizeof(double));

    store->entries = (data *)malloc(initialCapacity * sizeof(data));
}

void resizeDataStore(DataStore *store) {
    size_t newCapacity = store->capacity * 2;

    long *newOffsets = (long *)realloc(store->offsets, newCapacity * sizeof(long));
    int *newKeys = (int *)realloc(store->keys, newCapacity * sizeof(int));
    double *newValues = (double *)realloc(store->values, newCapacity * sizeof(double));

    data *newEntries = (data *)realloc(store->entries, newCapacity * sizeof(data));

    if (!newOffsets || !newKeys || !newValues || !newEntries) {
        free(newOffsets);
        free(newKeys);
        free(newValues);
        free(newEntries);
        perror("Reallocation failed");
        exit(EXIT_FAILURE);
    }

    store->offsets = newOffsets;
    store->keys = newKeys;
    store->values = newValues;
    store->entries = newEntries;

    store->capacity = newCapacity;
}

void addDataEntry(DataStore *store, int key, double value, const char *identifier) {
    if (store->count == store->capacity) {
        resizeDataStore(store);
    }

    size_t index = store->count;

    store->offsets[index] = 0; // Assuming some logic to calculate offset
    store->keys[index] = key;
    store->values[index] = value;

    data *entry = &store->entries[index];
    entry->integer = key;
    entry->dbl = value;

    size_t idLen = strlen(identifier) + 1;
    char *newIdentifier = (char *)malloc(idLen);

    if (!newIdentifier) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    strcpy(newIdentifier, identifier);
    entry->identifier = newIdentifier;

    store->count++;
}

void freeDataStore(DataStore *store) {
    for (size_t i = 0; i < store->count; ++i) {
        free(store->entries[i].identifier);
    }

    free(store->offsets);
    free(store->keys);
    free(store->values);
    free(store->entries);
}

int main() {
    DataStore myData;
    initializeDataStore(&myData, 10);

    addDataEntry(&myData, 1, 3.14, "Identifier_001");
    addDataEntry(&myData, 2, 6.28, "Identifier_002");

    // Use the data store...

    freeDataStore(&myData);
    return 0;
}
