#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int key;
    int value;
    bool active;
} record;

int generate_unique_keys(int *keys, int size) {
    srand(time(NULL));
    for (int i = 0; i < size;) {
        int rand_key = rand() % 1000000; // Arbitrary large range
        bool is_duplicate = false;

        for (int j = 0; j < i; ++j) {
            if (keys[j] == rand_key) {
                is_duplicate = true;
                break;
            }
        }

        if (!is_duplicate) {
            keys[i++] = rand_key;
        }
    }

    return 0;
}

int create_records(record **records, int max_records, int min_value, int max_value) {
    if (max_records <= 0 || records == NULL) {
        return -1;
    }

    // Memory allocation for records and keys
    *records = malloc(max_records * sizeof(record));
    if (*records == NULL) {
        return -1; // Allocation failed
    }

    int *keys = malloc(max_records * sizeof(int));
    if (keys == NULL) {
        free(*records);
        return -1;
    }

    generate_unique_keys(keys, max_records);

    for (int i = 0; i < max_records; ++i) {
        (*records)[i].key = keys[i];
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
        (*records)[i].active = rand() % 2 == 0;

        if ((*records)[i].key == -1 || (*records)[i].value == -1) {
            // Handle any specific error condition
            free(keys);
            free(*records);
            return -1;
        }
    }

    free(keys); // No longer needed after initialization

    return max_records; // Successfully created all records
}
