typedef struct {
    int integer;
    double dbl;
    char *str;
} data_t;

typedef enum {
    TYPE_INT,
    TYPE_FLOAT,
    TYPE_STRING
} record_type_t;

typedef struct {
    record_type_t type;
    union {
        int i_value;
        float f_value;
        char *s_value;
    } value;
} record_t;

void serialize_record(record_t *record, uint8_t **buffer, size_t *size);
int deserialize_record(uint8_t *buffer, size_t size, record_t *record);

typedef struct {
    data_t *data_array;
    size_t capacity;
} dataset_t;

dataset_t* create_dataset(size_t max_records) {
    dataset_t *dataset = (dataset_t *)malloc(sizeof(dataset_t));
    if (!dataset) return NULL;

    dataset->capacity = max_records;
    dataset->data_array = (data_t *)calloc(max_records, sizeof(data_t));

    if (!dataset->data_array) {
        free(dataset);
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Initialize random seed

    for (size_t i = 0; i < max_records; ++i) {
        dataset->data_array[i].integer = rand() % 100;
        dataset->data_array[i].dbl = ((double)rand() / RAND_MAX) * 100.0;
        size_t str_length = rand() % 10 + 1; // Random string length between 1 and 10
        dataset->data_array[i].str = (char *)malloc(str_length + 1);
        if (!dataset->data_array[i].str) {
            for (size_t j = 0; j < i; ++j) free(dataset->data_array[j].str);
            free(dataset->data_array);
            free(dataset);
            return NULL;
        }
        for (size_t j = 0; j < str_length; ++j)
            dataset->data_array[i].str[j] = 'a' + rand() % 26;
        dataset->data_array[i].str[str_length] = '\0';
    }

    return dataset;
}

void free_dataset(dataset_t *dataset) {
    if (dataset) {
        for (size_t i = 0; i < dataset->capacity; ++i)
            free(dataset->data_array[i].str);
        free(dataset->data_array);
        free(dataset);
    }
}

record_t generate_random_record() {
    record_t record;
    int type = rand() % 3;

    switch (type) {
        case TYPE_INT:
            record.type = TYPE_INT;
            record.value.i_value = rand() % 100;
            break;
        case TYPE_FLOAT:
            record.type = TYPE_FLOAT;
            record.value.f_value = ((float)rand() / RAND_MAX) * 100.0f;
