#include <string.h>

#define MAX_MEMORY_USAGE_MB 50
#define MEMORY_LIMIT (MAX_MEMORY_USAGE_MB * 1024 * 1024)
#define LOGGING_ENABLED 1

typedef struct {
    int key;
    long offset;
} record;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

UnionFindNode* uf_data;
pthread_mutex_t mutexes[1000]; // Adjust size as needed
int num_elements = 1000; // Default number of elements, adjust based on need

void log_message(const char *message) {
#if LOGGING_ENABLED
    printf("%s\n", message);
#endif
}

int find(int x) {
    if (uf_data[x].parent != x)
        uf_data[x].parent = find(uf_data[x].parent);
    return uf_data[x].parent;
}

void union_sets(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);

    if (rootX != rootY) {
        pthread_mutex_lock(&mutexes[rootX]);
        pthread_mutex_lock(&mutexes[rootY]);

        if (uf_data[rootX].rank > uf_data[rootY].rank)
            uf_data[rootY].parent = rootX;
        else if (uf_data[rootX].rank < uf_data[rootY].rank)
            uf_data[rootX].parent = rootY;
        else {
            uf_data[rootY].parent = rootX;
            uf_data[rootX].rank++;
        }

        pthread_mutex_unlock(&mutexes[rootX]);
        pthread_mutex_unlock(&mutexes[rootY]);
    }
}

void* thread_union(void *args) {
    int start = *(int*)args;
    for (int i = start; i < num_elements; ++i) {
        union_sets(i, rand() % num_elements);
    }
    return NULL;
}

size_t calculate_memory_usage(size_t size) {
    // Placeholder function to mimic memory usage tracking
    return size;
}

void initialize_union_find(int n) {
    uf_data = (UnionFindNode*)malloc(n * sizeof(UnionFindNode));
    for (int i = 0; i < n; ++i) {
        uf_data[i].parent = i;
        uf_data[i].rank = 0;
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

void free_union_find(int n) {
    for (int i = 0; i < n; ++i)
        pthread_mutex_destroy(&mutexes[i]);
    free(uf_data);
}

unsigned char* serialize_record(const record *r, size_t size) {
    unsigned char *buffer = malloc(size * sizeof(record));
    if (!buffer) {
        log_message("Memory allocation failed during serialization");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        // Assuming system is little-endian
        buffer[i*8] = r[i].key & 0xFF;
        buffer[i*8 + 1] = (r[i].key >> 8) & 0xFF;
        buffer[i*8 + 2] = (r[i].key >> 16) & 0xFF;
        buffer[i*8 + 3] = (r[i].key >> 24) & 0xFF;

        for (int j = 0; j < sizeof(long); ++j) {
            buffer[i*8 + 4 + j] = ((unsigned char*)&r[i].offset)[j];
        }
    }

    return buffer;
}

record* deserialize_record(const unsigned char *buffer, size_t size, record *result) {
    for (size_t i = 0; i < size; ++i) {
        result[i].key = buffer[i*8] | (buffer[i*8 + 1] << 8) |
                        (buffer[i*8 + 2] << 16) | (buffer[i*8 + 3] << 24);

        for (int j = 0; j < sizeof(long); ++j) {
            ((unsigned char*)&result[i].offset)[j] = buffer[i*8 + 4 + j];
        }
    }

    return result;
}

void free_resources(record *records, unsigned long *offsets, size_t count) {
    free(records);
    free(offsets);
}

record* initialize_records(size_t count, int min_val, int max_val, size_t *memory_used) {
    record *records = malloc(count * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records");
        return NULL;
    }

    long *offsets = malloc(count * sizeof(long));
    if (!offsets) {
        free(records);
        log_message("Memory allocation failed for offsets");
        return NULL;
    }

    time_t current_time;
    srand((unsigned int)time(&current_time));

    for (size_t i = 0; i < count; ++i) {
        records[i].key = min_val + rand() % (max_val - min_val + 1);
        offsets[i] = (long)i * 100; // Example offset calculation
    }

    initialize_union_find(count);

    pthread_t threads[4];
    int ranges[] = {0, count / 4, count / 2, 3 * count / 4};

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_union, &ranges[i])) {
            log_message("Thread creation failed");
            free_resources(records, offsets, count);
            return NULL;
        }
    }

    for (int i = 0; i < 4; ++i)
        pthread_join(threads[i], NULL);

    *memory_used = calculate_memory_usage(sizeof(record) * count + sizeof(long) * count + sizeof(UnionFindNode) * count);

    free_union_find(count);
    return records;
}

void read_integers(int *arr, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (scanf("%d", &arr[i]) != 1)
