#define MAX_MESSAGES 10000
#define MAX_MESSAGE_SIZE 1024

typedef struct {
    char *message;
    uint64_t timestamp;
    _Atomic int acknowledged;
} Message;

static pthread_mutex_t message_lock = PTHREAD_MUTEX_INITIALIZER;
static Message messages[MAX_MESSAGES];
static size_t total_memory_usage = 0;
static const size_t MEMORY_LIMIT = 100 * 1024 * 1024; // 100 MB limit for illustration

void log_event(const char *event) {
    printf("[LOG] %s\n", event);
}

uint64_t get_current_time() {
    return (uint64_t)time(NULL);
}

void initialize_messages(size_t message_count) {
    pthread_mutex_lock(&message_lock);

    if (total_memory_usage + message_count * sizeof(Message) > MEMORY_LIMIT) {
        log_event("Memory limit exceeded.");
        pthread_mutex_unlock(&message_lock);
        return;
    }

    for (size_t i = 0; i < message_count; ++i) {
        messages[i].message = malloc(MAX_MESSAGE_SIZE);
        if (!messages[i].message) {
            log_event("Failed to allocate memory for a message.");
            break;
        }
        messages[i].timestamp = get_current_time();
        atomic_store(&messages[i].acknowledged, 0);

        total_memory_usage += sizeof(Message) + MAX_MESSAGE_SIZE;
    }

    pthread_mutex_unlock(&message_lock);
    log_event("Messages initialized successfully.");
}

void free_messages() {
    pthread_mutex_lock(&message_lock);

    for (size_t i = 0; i < MAX_MESSAGES && messages[i].message != NULL; ++i) {
        free(messages[i].message);
        total_memory_usage -= sizeof(Message) + MAX_MESSAGE_SIZE;
    }

    pthread_mutex_unlock(&message_lock);
    log_event("Messages freed successfully.");
}

void serialize_message(const Message *msg, uint8_t *buffer, size_t buffer_size) {
    if (buffer_size < sizeof(*msg)) return;

    memcpy(buffer, &msg->timestamp, sizeof(msg->timestamp));
    memcpy(buffer + sizeof(msg->timestamp), msg->message, strlen(msg->message) + 1);
}

void deserialize_message(const uint8_t *buffer, size_t buffer_size, Message *msg) {
    if (buffer_size < sizeof(*msg)) return;

    memcpy(&msg->timestamp, buffer, sizeof(msg->timestamp));
    strncpy((char *)msg->message, (const char *)(buffer + sizeof(msg->timestamp)), MAX_MESSAGE_SIZE - 1);
    msg->message[MAX_MESSAGE_SIZE - 1] = '\0';
}

