typedef struct {
    int value;
} record;

void serialize_data(long *offsets, int *keys, record *records, size_t size, unsigned char **out_buffer, size_t *out_size) {
    size_t total_size = (size * sizeof(long)) + (size * sizeof(int)) + (size * sizeof(record));
    *out_buffer = malloc(total_size);
    if (!*out_buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    unsigned char *ptr = *out_buffer;
    for (size_t i = 0; i < size; ++i) {
        memcpy(ptr, &offsets[i], sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &keys[i], sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &records[i], sizeof(record));
        ptr += sizeof(record);
    }
    *out_size = total_size;
}

void deserialize_data(unsigned char *in_buffer, size_t in_size, long **offsets, int **keys, record **records, size_t *size) {
    *size = in_size / (sizeof(long) + sizeof(int) + sizeof(record));
    *offsets = malloc((*size) * sizeof(long));
    *keys = malloc((*size) * sizeof(int));
    *records = malloc((*size) * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    unsigned char *ptr = in_buffer;
    for (size_t i = 0; i < *size; ++i) {
        memcpy(&(*offsets)[i], ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(&(*keys)[i], ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&(*records)[i].value, ptr, sizeof(record));
        ptr += sizeof(record);
    }
}

int count_unique_integers() {
    int unique_count = 0;
    const size_t hash_size = 1000003; // A prime number for the hash table
    int *hash_table = calloc(hash_size, sizeof(int));

    if (!hash_table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    int num;
    while (scanf("%d", &num) == 1) {
        int index = abs(num) % hash_size;
        while (hash_table[index] != 0 && hash_table[index] != num) {
            ++index;
            if (index >= hash_size) index = 0;
        }
        if (hash_table[index] == 0) {
            hash_table[index] = num;
            unique_count++;
        }
    }

    printf("Unique integers count: %d\n", unique_count);

    for (size_t i = 0; i < hash_size; ++i) {
        if (hash_table[i] != 0) {
            int freq = 1;
            int num = hash_table[i];
            for (++i; i < hash_size && hash_table[i] == num; ++i) {
                ++freq;
            }
            printf("Value: %d, Frequency: %d\n", num, freq);
        }
    }

    free(hash_table);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <size>\n", argv[0]);
        return 1;
    }

    size_t size = strtoul(argv[1], NULL, 10);
    srand((unsigned int)time(NULL));

    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 1000;
        records[i].value = rand() % 500 + 1;
    }

    unsigned char *serialized_data;
    size_t serialized_size;

    serialize_data(offsets, keys, records, size, &serialized_data, &serialized_size);

    long *deserialized_offsets;
    int *deserialized_keys;
    record *deserialized_records;
    size_t deserialized_size;

    deserialize_data(serialized_data, serialized_size, &deserialized_offsets, &deserialized_keys, &deserialized_records, &deserialized_size);

    free(offsets);
    free(keys);
    free(records);
    free(serialized_data);
    free(deserialized_offsets);
    free(deserialized_keys);
    free(deserialized_records);

    count_unique_integers();

    return 0;
}
