#include "zlib.h"

// Define the complex data structure
typedef struct {
    double average;
    char flag;
    unsigned int identifier;
    void *metadata;
} ComplexData;

// Function prototypes
void* safe_malloc(size_t size);
void free_memory(void *keys, void *complex_data, void *metadata);
int compress_and_serialize(const ComplexData *data, size_t size,
                           unsigned char **compressed_data, uLongf *compressed_size,
                           int compression_level);
int decompress_and_deserialize(unsigned char *compressed_data, uLongf compressed_size,
                               ComplexData **output_data, size_t *output_size);

// Main function to allocate and initialize arrays
void* allocate_and_initialize(size_t max_memory_limit, long min_available_memory,
                              int data_count, int compression_level) {
    if (data_count <= 0) return NULL;

    // Calculate memory requirements
    size_t key_memory = data_count * sizeof(long);
    size_t complex_memory = data_count * sizeof(ComplexData);
    size_t metadata_memory = data_count * sizeof(void*);
    size_t total_memory = key_memory + complex_memory + metadata_memory;

    if (total_memory > max_memory_limit) {
        fprintf(stderr, "Error: Memory allocation exceeds limit.\n");
        return NULL;
    }

    // Allocate memory
    long *keys = safe_malloc(key_memory);
    ComplexData *complex_data = safe_malloc(complex_memory);
    void **metadata = safe_malloc(metadata_memory);

    if (!keys || !complex_data || !metadata) {
        free_memory(keys, complex_data, metadata);
        return NULL;
    }

    // Random seed based on system time
    srand(time(NULL));

    // Initialize keys and complex data structures
    for (size_t i = 0; i < data_count; ++i) {
        keys[i] = rand() % INT_MAX;

        complex_data[i].average = ((double)rand() / RAND_MAX) * 100.0;
        complex_data[i].flag = 'A' + rand() % 26;
        complex_data[i].identifier = rand() % UINT_MAX;
        complex_data[i].metadata = NULL; // Placeholder for actual metadata
    }

    unsigned char *compressed_data = NULL;
    uLongf compressed_size = 0;

    if (compress_and_serialize(complex_data, data_count,
                               &compressed_data, &compressed_size, compression_level) != Z_OK) {
        fprintf(stderr, "Error: Compression/Serialization failed.\n");
        free_memory(keys, complex_data, metadata);
        return NULL;
    }

    printf("Compression successful. Size before: %zu bytes, after: %lu bytes\n", data_count * sizeof(ComplexData), compressed_size);

    // Free allocated memory (for demonstration purposes)
    free(compressed_data);
    free_memory(keys, complex_data, metadata);

    return NULL; // No need to return anything as the purpose is allocation and initialization
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && size > 0) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
    }
    return ptr;
}

void free_memory(void *keys, void *complex_data, void *metadata) {
    if (keys) free(keys);
    if (complex_data) free(complex_data);
    if (metadata) free(metadata);
}

int compress_and_serialize(const ComplexData *data, size_t size,
                           unsigned char **compressed_data, uLongf *compressed_size,
                           int compression_level) {
    // Calculate maximum compressed data size
    uLong uncompressed_size = size * sizeof(ComplexData);
    *compressed_size = compressBound(uncompressed_size);

    *compressed_data = malloc(*compressed_size);
    if (!*compressed_data) return Z_MEM_ERROR;

    int res = compress2((Bytef *)*compressed_data, compressed_size,
                        (const Bytef *)data, uncompressed_size, compression_level);

    free(*compressed_data); // We don't need to keep the memory after testing

    return res;
}

int decompress_and_deserialize(unsigned char *compressed_data, uLongf compressed_size,
                               ComplexData **output_data, size_t *output_size) {
    *output_size = sizeof(ComplexData);

    *output_data = malloc(*output_size);
    if (!*output_data) return Z_MEM_ERROR;

    uLong uncompressed_size = (uLong)*output_size;
    int res = uncompress((Bytef *)*output_data, &uncompressed_size,
                         compressed_data, compressed_size);

    if (res != Z_OK) {
        free(*output_data);
        *output_data = NULL;
    }

    return res;
}
