typedef struct {
    float amount;
    time_t timestamp;
    char description[256];
} transaction;

// Function prototypes
transaction* initialize_transactions(size_t max_size, size_t count, float min_amount, float max_amount);
void serialize_transaction(transaction *trans, unsigned char **buffer, size_t *length);
void deserialize_transaction(const unsigned char *buffer, size_t length, transaction *trans);
void free_transactions(transaction *transactions, size_t count);
void print_latest_timestamp();

// Initialize transactions with random amounts and current time
transaction* initialize_transactions(size_t max_size, size_t count, float min_amount, float max_amount) {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    transaction *transactions = NULL;
    if (max_size < sizeof(transaction)) {
        fprintf(stderr, "Maximum size too small to allocate even one transaction.\n");
        return transactions; // Return early due to insufficient memory
    }

    for (size_t i = 0; i < count && max_size >= sizeof(transaction); ++i) {
        if ((transactions = realloc(transactions, (i + 1) * sizeof(transaction))) == NULL) {
            fprintf(stderr, "Failed to allocate memory.\n");
            free_transactions(transactions, i);
            return transactions;
        }

        // Set random amount within specified range
        float delta = max_amount - min_amount;
        transactions[i].amount = (float)((double)rand() / RAND_MAX * delta + min_amount);

        // Set current time as timestamp
        transactions[i].timestamp = time(NULL);

        // Initialize description with a placeholder text
        snprintf(transactions[i].description, sizeof(transactions[i].description), "Transaction %zu", i + 1);
    }

    return transactions;
}

// Serialize a transaction into a byte array
void serialize_transaction(transaction *trans, unsigned char **buffer, size_t *length) {
    if (buffer == NULL || length == NULL || trans == NULL) {
        fprintf(stderr, "Invalid arguments for serialization.\n");
        return;
    }

    size_t desc_len = strlen(trans->description);
    size_t total_size = sizeof(float) + sizeof(time_t) + desc_len + 1; // +1 for null terminator
    *buffer = (unsigned char *)malloc(total_size);

    if (*buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for serialization buffer.\n");
        return;
    }

    size_t offset = 0;

    // Serialize float amount - handling endianness
    memcpy(*buffer + offset, &trans->amount, sizeof(float));
    offset += sizeof(float);

    // Serialize time_t timestamp
    memcpy(*buffer + offset, &trans->timestamp, sizeof(time_t));
    offset += sizeof(time_t);

    // Serialize description string
    memcpy(*buffer + offset, trans->description, desc_len + 1); // Include null terminator

    *length = total_size;
}

// Deserialize byte array back into a transaction structure
void deserialize_transaction(const unsigned char *buffer, size_t length, transaction *trans) {
    if (buffer == NULL || length < sizeof(float) + sizeof(time_t)) {
        fprintf(stderr, "Invalid arguments for deserialization.\n");
        return;
    }

    size_t offset = 0;

    // Deserialize float amount
    memcpy(&trans->amount, buffer + offset, sizeof(float));
    offset += sizeof(float);

    // Deserialize time_t timestamp
    memcpy(&trans->timestamp, buffer + offset, sizeof(time_t));
    offset += sizeof(time_t);

    // Deserialize description string (assuming max length fits in structure)
    memcpy(trans->description, buffer + offset, length - offset);
}

// Free allocated memory for transactions
void free_transactions(transaction *transactions, size_t count) {
    if (transactions != NULL) {
        free(transactions);
    }
}

// Print the latest timestamp from input and its description
void print_latest_timestamp() {
    time_t timestamps[100];
    char descriptions[100][256];
    int i = 0;

    printf("Enter transactions (type 'done' to finish):\n");

    while (i < 100) {
        char desc[256];
        char temp[32];

        if (fgets(temp, sizeof(temp), stdin)) {
            // Check for termination condition
            if (strcmp(temp, "done\n") == 0 || strcmp(temp, "done\r\n") == 0) {
                break;
            }

            time_t timestamp;
            if (sscanf(temp, "%ld", &timestamp) != 1 || timestamp <= 0) {
                fprintf(stderr, "Invalid or empty timestamp. Skipping.\n");
                continue;
            }

            // Read description
            if (!fgets(desc, sizeof(desc), stdin)) {
                fprintf(stderr, "Failed to read description for transaction %d\n", i + 1);
                break; 
            }

            timestamps[i] = timestamp;
            snprintf(descriptions[i], sizeof(descriptions[i]), "%s", desc);

            ++i;
        }
    }

    if (i == 0) {
        printf("No valid transactions entered.\n");
        return;
    }

    time_t latest_timestamp = timestamps[0];
    int latest_index = 0;

    for (int j = 1; j < i; ++j) {
        if (timestamps[j] > latest_timestamp) {
            latest_timestamp = timestamps[j];
            latest_index = j;
        }
    }

    printf("Latest Timestamp: %ld, Description: %s", latest_timestamp, descriptions[latest_index]);
}

int main() {
    size_t max_size = 1024; // Example maximum size
    size_t count = 10; // Number of transactions to initialize
    float min_amount = 0.0;
    float max_amount = 1000.0;

    transaction *transactions = initialize_transactions(max_size, count, min_amount, max_amount);
    if (transactions == NULL) {
        fprintf(stderr, "Failed to initialize transactions.\n");
        return EXIT_FAILURE;
    }

    // Example serialization
    unsigned char *serialized_data = NULL;
    size_t serialized_length = 0;

    serialize_transaction(transactions, &serialized_data, &serialized_length);

    // Assume deserialization logic is needed
    transaction deserialized_trans;
    if (serialized_data) {
        deserialize_transaction(serialized_data, serialized_length, &deserialized_trans);
        printf("Deserialized Amount: %.2f, Timestamp: %ld\n", deserialized_trans.amount, deserialized_trans.timestamp);
        free(serialized_data);
    }

    // Print latest timestamp with description
    print_latest_timestamp();

    free_transactions(transactions, count);

    return EXIT_SUCCESS;
}
