#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int value;
    long offset;
    int status;  // Validity flag
    int priority; // Priority level
} Record;

#define MAX_SIZE_LIMIT 1024 * 1024  // Example size limit

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory and initialize data structures
int* allocate_and_initialize(int max_size, char* format) {
    int* keys;
    long* offsets;
    Record* records;
    int* statuses;
    int* priorities;

    size_t key_size = sizeof(int);
    size_t offset_size = sizeof(long);
    size_t record_size = sizeof(Record);
    size_t status_size = sizeof(int);
    size_t priority_size = sizeof(int);

    size_t total_size = 5 * (key_size + offset_size + record_size + status_size + priority_size);

    if (total_size > max_size) {
        fprintf(stderr, "Exceeded memory allocation limit.\n");
        return NULL;
    }

    keys = malloc(key_size * 5);
    offsets = malloc(offset_size * 5);
    records = malloc(record_size * 5);
    statuses = malloc(status_size * 5);
    priorities = malloc(priority_size * 5);

    if (!keys || !offsets || !records || !statuses || !priorities) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(keys); free(offsets); free(records); free(statuses); free(priorities);
        return NULL;
    }

    // Initialize random seed
    srand((unsigned int)time(NULL));

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < 5; ++i) {
        keys[i] = rand() % INT_MAX;
        offsets[i] = rand() % LONG_MAX;

        records[i].value = rand() % INT_MAX;
        records[i].offset = offsets[i];
        records[i].status = 1; // Assume valid initially
        records[i].priority = rand() % 10;

        statuses[i] = 1; // Valid
        priorities[i] = records[i].priority;
    }

    pthread_mutex_unlock(&mutex);

    printf("Memory allocated successfully.\n");

    return (int*)records; // Return pointer to the records for usage
}

// Function to serialize data into a byte array or JSON format
void* serialize_data(int* keys, long* offsets, Record* records, int* statuses, int* priorities, char* format) {
    if (strcmp(format, "binary") == 0) {
        size_t total_size = sizeof(int) * 5 + sizeof(long) * 5 + sizeof(Record) * 5;
        void* buffer = malloc(total_size);

        if (!buffer) {
            fprintf(stderr, "Serialization memory allocation failed.\n");
            return NULL;
        }

        memcpy(buffer, keys, sizeof(int) * 5);
        memcpy((char*)buffer + sizeof(int) * 5, offsets, sizeof(long) * 5);
        memcpy((char*)buffer + sizeof(int) * 5 + sizeof(long) * 5, records, sizeof(Record) * 5);

        return buffer;
    } else if (strcmp(format, "json") == 0) {
        char* json = malloc(1024); // Example size
        if (!json) {
            fprintf(stderr, "JSON serialization memory allocation failed.\n");
            return NULL;
        }

        snprintf(json, 1024,
                 "{\"keys\": [%d, %d, %d, %d, %d], \"offsets\": [%ld, %ld, %ld, %ld, %ld], "
                 "\"records\": [{\"value\": %d, \"offset\": %ld, \"status\": %d, \"priority\": %d}, "
                 "{\"value\": %d, \"offset\": %ld, \"status\": %d, \"priority\": %d}, "
                 "{\"value\": %d, \"offset\": %ld, \"status\": %d, \"priority\": %d}, "
                 "{\"value\": %d, \"offset\": %ld, \"status\": %d, \"priority\": %d}, "
                 "{\"value\": %d, \"offset\": %ld, \"status\": %d, \"priority\": %d}]}",
                 keys[0], keys[1], keys[2], keys[3], keys[4],
                 offsets[0], offsets[1], offsets[2], offsets[3], offsets[4],
                 records[0].value, records[0].offset, statuses[0], priorities[0],
                 records[1].value, records[1].offset, statuses[1], priorities[1],
                 records[2].value, records[2].offset, statuses[2], priorities[2],
                 records[3].value, records[3].offset, statuses[3], priorities[3],
                 records[4].value, records[4].offset, statuses[4], priorities[4]);

        return json;
    } else {
        fprintf(stderr, "Unsupported format.\n");
        return NULL;
    }
}

// Function to free allocated memory
void free_resources(int* keys, long* offsets, Record* records, int* statuses, int* priorities) {
    pthread_mutex_lock(&mutex);

    if (keys) free(keys);
    if (offsets) free(offsets);
    if (records) free(records);
    if (statuses) free(statuses);
    if (priorities) free(priorities);

    printf("Resources freed successfully.\n");

    pthread_mutex_unlock(&mutex);
}

// Function to monitor memory usage
void monitor_memory_usage() {
    // Example: Print current heap size, could be platform specific
    printf("Monitoring memory usage...\n");
    // Use system-specific functions like `mallinfo` on POSIX for detailed info
}

int main() {
    int* records = allocate_and_initialize(MAX_SIZE_LIMIT, "binary");

    if (records) {
        char* data_format = "json";
        void* serialized_data = serialize_data(
            ((int*)((char*)records - 3 * sizeof(int) * 5)), // Adjust for actual pointers
            ((long*)((char*)records - 2 * sizeof(long) * 5)),
            records,
            ((int*)((char*)records - sizeof(int) * 5)),
            ((int*)((char*)records - sizeof(int))),
            data_format);

        if (serialized_data) {
            printf("Serialized Data: %s\n", (char*)serialized_data);
            free(serialized_data); // Free serialized data
        }

        free_resources(
            ((int*)((char*)records - 3 * sizeof(int) * 5)), 
            ((long*)((char*)records - 2 * sizeof(long) * 5)),
            records,
            ((int*)((char*)records - sizeof(int) * 5)),
            ((int*)((char*)records - sizeof(int)))
        );
    }

    monitor_memory_usage();

    return 0;
}
