#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <openssl/evp.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

#define MAX_SERVERS 100
#define MAX_CONNECTIONS 10
#define CONFIG_FILE "config.txt"
#define CERT_FILE "certs.pem"

typedef struct {
    char *address;
    int port;
    char *auth_key;
} ServerEntry;

typedef struct {
    ServerEntry servers[MAX_SERVERS];
    size_t count;
    pthread_mutex_t lock;
} ConnectionPool;

ConnectionPool pool = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void add_cipher() {
    EVP_add_cipher(EVP_aes_256_gcm());
    EVP_add_cipher(EVP_chacha20_poly1305());
}

void add_digest() {
    EVP_add_digest(EVP_sha256());
    EVP_add_digest(EVP_blake2b512());
    EVP_add_digest_alias("sha256", "SHA-256");
}

SSL_CTX* create_context() {
    const SSL_METHOD *method;
    SSL_CTX *ctx;

    method = TLS_client_method();
    ctx = SSL_CTX_new(method);
    if (!ctx) {
        log_error("Unable to create SSL context");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    return ctx;
}

void configure_context(SSL_CTX *ctx, const char *cert_file) {
    if (SSL_CTX_load_verify_locations(ctx, cert_file, NULL) <= 0) {
        log_error("Failed to load certificate file");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);
}

void free_server_entry(ServerEntry *entry) {
    if (entry->address) free(entry->address);
    if (entry->auth_key) free(entry->auth_key);
}

int load_config(const char *filename, ConnectionPool *pool) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    char address[256], auth_key[256];
    int port;
    while (fscanf(file, "%s %d %s", address, &port, auth_key) == 3) {
        pthread_mutex_lock(&pool->lock);
        if (pool->count >= MAX_SERVERS) break;

        ServerEntry *entry = &pool->servers[pool->count++];
        entry->address = strdup(address);
        entry->port = port;
        entry->auth_key = strdup(auth_key);

        pthread_mutex_unlock(&pool->lock);
    }

    fclose(file);
    return 0;
}

void* handle_connection(void *arg) {
    ServerEntry *entry = (ServerEntry *)arg;

    struct sockaddr_in server_addr;
    int sockfd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (sockfd < 0) {
        log_error("Failed to create socket");
        return NULL;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(entry->port);

    struct hostent *host = gethostbyname(entry->address);
    if (!host) {
        log_error("DNS resolution failed");
        close(sockfd);
        return NULL;
    }

    memcpy(&server_addr.sin_addr.s_addr, host->h_addr_list[0], host->h_length);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0 &&
        errno != EINPROGRESS) {
        log_error("Connection failed");
        close(sockfd);
        return NULL;
    }

    SSL_CTX *ctx = create_context();
    configure_context(ctx, CERT_FILE);

    SSL *ssl = SSL_new(ctx);
    SSL_set_fd(ssl, sockfd);

    if (SSL_connect(ssl) <= 0) {
        log_error("SSL connection failed");
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        close(sockfd);
        return NULL;
    }

    // Perform secure communication here...

    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(sockfd);

    free_server_entry(entry);
    return NULL;
}

int main(int argc, char *argv[]) {
    add_cipher();
    add_digest();

    if (load_config(CONFIG_FILE, &pool) != 0) {
        log_error("Failed to load configuration");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_CONNECTIONS];
    for (size_t i = 0; i < pool.count && i < MAX_CONNECTIONS; ++i) {
        pthread_create(&threads[i], NULL, handle_connection, &pool.servers[i]);
    }

    for (int i = 0; i < pool.count && i < MAX_CONNECTIONS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
