#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include "lz4.h" // Assuming LZ4 library is available

#define MAX_MEMORY_USAGE 1024 * 1024 // Example: 1MB limit for total memory usage
#define CACHE_SIZE 10
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 100

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    size_t record_size;
    pthread_mutex_t mutex;
} RecordCollection;

typedef struct {
    Record* records;
    size_t cache_index;
    size_t hit_count;
    size_t miss_count;
} Cache;

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_ERROR
} LogLevel;

typedef struct {
    LogLevel level;
    FILE* log_file;
} Logger;

Logger logger = {LOG_LEVEL_INFO, NULL};

void log_message(LogLevel level, const char* message) {
    if (level >= logger.level) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        pthread_mutex_lock(&logger.mutex);
        fprintf(logger.log_file ? logger.log_file : stdout, "[%s] [%ld] %s\n", timestamp, pthread_self(), message);
        fflush(logger.log_file ? logger.log_file : stdout);
        pthread_mutex_unlock(&logger.mutex);
    }
}

void init_logger(LogLevel level, const char* log_filename) {
    logger.level = level;
    if (log_filename) {
        logger.log_file = fopen(log_filename, "a");
        if (!logger.log_file) {
            fprintf(stderr, "Failed to open log file\n");
            exit(EXIT_FAILURE);
        }
    }
}

void destroy_logger() {
    if (logger.log_file) {
        fclose(logger.log_file);
        logger.log_file = NULL;
    }
}

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        free(collection);
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for records");
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->record_size = sizeof(Record);

    pthread_mutex_init(&collection->mutex, NULL);

    log_message(LOG_LEVEL_INFO, "Created record collection");
    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (collection) {
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
        log_message(LOG_LEVEL_INFO, "Destroyed record collection");
    }
}

int add_record(RecordCollection* collection, int value, long offset) {
    size_t required_size = (collection->count + 1) * sizeof(Record);

    if (required_size > MAX_MEMORY_USAGE) {
        log_message(LOG_LEVEL_ERROR, "Exceeded maximum memory usage limit");
        return -1;
    }

    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));

        if (!new_records) {
            log_message(LOG_LEVEL_ERROR, "Failed to resize record array");
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count].value = value;
    collection->records[collection->count].offset = offset;
    collection->count++;

    pthread_mutex_unlock(&collection->mutex);
    log_message(LOG_LEVEL_DEBUG, "Added record");
    return 0;
}

Cache* create_cache(size_t size) {
    Cache* cache = malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->records = malloc(size * sizeof(Record));
    if (!cache->records) {
        free(cache);
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for cache");
        return NULL;
    }

    cache->cache_index = 0;
    cache->hit_count = 0;
    cache->miss_count = 0;

    log_message(LOG_LEVEL_INFO, "Created cache");
    return cache;
}

void destroy_cache(Cache* cache) {
    if (cache) {
        free(cache->records);
        free(cache);
        log_message(LOG_LEVEL_INFO, "Destroyed cache");
    }
}

Record get_cached_record(Cache* cache, size_t index) {
    if (index >= CACHE_SIZE || !cache) return (Record){0, 0};

    size_t effective_index = cache->cache_index + index;
    if (effective_index >= CACHE_SIZE) effective_index -= CACHE_SIZE;

    cache->hit_count++;
    log_message(LOG_LEVEL_DEBUG, "Cache hit");
    return cache->records[effective_index];
}

void add_to_cache(Cache* cache, Record record) {
    if (!cache) return;

    size_t effective_index = (cache->cache_index + 1) % CACHE_SIZE;
    cache->records[effective_index] = record;
    cache->cache_index = effective_index;
    cache->miss_count++;

    log_message(LOG_LEVEL_DEBUG, "Cache miss");
}

void seed_random() {
    srand((unsigned int)time(NULL));
}

int generate_random_value(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

void serialize_records(const RecordCollection* collection, uint8_t** buffer, size_t* buffer_size) {
    *buffer_size = collection->count * sizeof(Record);

    if (*buffer_size == 0) return;

    *buffer = malloc(*buffer_size);
    if (!*buffer) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for serialization");
        return;
    }

    memcpy(*buffer, collection->records, *buffer_size);

    // Compress using LZ4
    size_t compressed_size = (*buffer_size + 64) * 2; 
    uint8_t* compressed_buffer = malloc(compressed_size);
    if (!compressed_buffer) {
        free(*buffer);
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for compression");
        return;
    }

    int result = LZ4_compress_default(*buffer, compressed_buffer, *buffer_size, compressed_size);

    if (result <= 0) {
        free(*buffer);
        free(compressed_buffer);
        log_message(LOG_LEVEL_ERROR, "Compression failed");
        return;
    }

    *buffer_size = result;
    free(*buffer);
    *buffer = compressed_buffer;

    log_message(LOG_LEVEL_INFO, "Serialized and compressed records");
}

void deserialize_records(RecordCollection* collection, const uint8_t* buffer, size_t buffer_size) {
    // Decompress using LZ4
    size_t decompressed_size = buffer_size; 
    uint8_t* decompressed_buffer = malloc(decompressed_size);
    if (!decompressed_buffer) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for decompression");
        return;
    }

    int result = LZ4_decompress_safe(buffer, decompressed_buffer, buffer_size, decompressed_size);

    if (result <= 0) {
        free(decompressed_buffer);
        log_message(LOG_LEVEL_ERROR, "Decompression failed or data corrupted");
        return;
    }

    // Validate integrity using a simple checksum
    uint32_t checksum = 0;
    for (size_t i = 0; i < result; i++) {
        checksum += decompressed_buffer[i];
    }

    if (checksum == 0) { // Simplified example, adjust according to actual validation strategy
        free(decompressed_buffer);
        log_message(LOG_LEVEL_ERROR, "Data integrity check failed");
        return;
    }

    collection->records = malloc(result);
    if (!collection->records) {
        free(decompressed_buffer);
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for records after decompression");
        return;
    }

    memcpy(collection->records, decompressed_buffer, result);
    collection->count = result / sizeof(Record);
    collection->capacity = collection->count;

    free(decompressed_buffer);

    log_message(LOG_LEVEL_INFO, "Deserialized and validated records");
}

void read_integers_and_find_max() {
    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    if (n <= 0) return;

    int* numbers = malloc(n * sizeof(int));
    if (!numbers) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for input numbers");
        return;
    }

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &numbers[i]);
    }

    int max_value = numbers[0];
    for (int i = 1; i < n; ++i) {
        if (numbers[i] > max_value) {
            max_value = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", max_value);

    free(numbers);
}

int main() {
    init_logger(LOG_LEVEL_DEBUG, "app.log");

    RecordCollection* collection = create_record_collection(10);
    if (!collection) return EXIT_FAILURE;

    seed_random();

    for (size_t i = 0; i < 20; ++i) { // Try adding more records than initial capacity
        int value = generate_random_value(INT_RANGE_MIN, INT_RANGE_MAX);
        long offset = rand() % 1000;

        if (add_record(collection, value, offset)) {
            log_message(LOG_LEVEL_ERROR, "Failed to add record");
        }
    }

    uint8_t* buffer;
    size_t buffer_size;
    serialize_records(collection, &buffer, &buffer_size);

    RecordCollection* new_collection = create_record_collection(10);
    if (!new_collection) return EXIT_FAILURE;

    deserialize_records(new_collection, buffer, buffer_size);

    destroy_record_collection(collection);
    free(buffer);

    Cache* cache = create_cache(CACHE_SIZE);
    if (cache) {
        for (size_t i = 0; i < new_collection->count; ++i) {
            add_to_cache(cache, new_collection->records[i]);
        }

        Record cached_record = get_cached_record(cache, 0); // Example usage
        printf("Cached record value: %d\n", cached_record.value);

        destroy_cache(cache);
    }

    read_integers_and_find_max();

    destroy_record_collection(new_collection);

    destroy_logger();

    return EXIT_SUCCESS;
}
