#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Value {
    char data;
    struct Value* next;
} Value;

typedef struct Node {
    char* key;
    Value* values_head;
} Node;

typedef struct DistributedList {
    Node** nodes;
    size_t node_count;
    pthread_mutex_t mutex;
} DistributedList;

DistributedList* create_distributed_list(size_t initial_size) {
    DistributedList* list = (DistributedList*)malloc(sizeof(DistributedList));
    if (!list) return NULL;

    list->nodes = (Node**)calloc(initial_size, sizeof(Node*));
    list->node_count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void init_random_generator() {
    srand(time(NULL)); // Seed for random number generation
}

char generate_random_char(int min, int max) {
    return (char)(rand() % (max - min + 1) + min);
}

int add_node(DistributedList* list, const char* key, int ascii_min, int ascii_max) {
    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    size_t key_length = strlen(key) + 1;
    new_node->key = (char*)malloc(key_length);
    if (!new_node->key) {
        free(new_node);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    snprintf(new_node->key, key_length, "%s", key);

    Value* first_value = (Value*)malloc(sizeof(Value));
    if (!first_value) {
        free(new_node->key);
        free(new_node);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    first_value->data = generate_random_char(ascii_min, ascii_max);
    first_value->next = NULL;

    new_node->values_head = first_value;

    list->nodes[list->node_count++] = new_node;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void print_values(Value* head) {
    Value* current = head;
    while (current) {
        printf("%c ", current->data);
        current = current->next;
    }
    printf("\n");
}

void traverse_and_print(DistributedList* list) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->node_count; ++i) {
        printf("Node Key: %s -> ", list->nodes[i]->key);
        print_values(list->nodes[i]->values_head);
    }

    pthread_mutex_unlock(&list->mutex);
}

void free_distributed_list(DistributedList* list) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->node_count; ++i) {
        Value* current_value = list->nodes[i]->values_head;
        while (current_value) {
            Value* next_value = current_value->next;
            free(current_value);
            current_value = next_value;
        }

        free(list->nodes[i]->key);
        free(list->nodes[i]);
    }

    free(list->nodes);

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int main() {
    init_random_generator();

    DistributedList* list = create_distributed_list(10);

    add_node(list, "node1", 65, 90); // A-Z
    add_node(list, "node2", 97, 122); // a-z

    traverse_and_print(list);

    free_distributed_list(list);

    return 0;
}
