#include <time.h>

typedef enum { ACTIVE, INACTIVE } Status;

typedef struct Item {
    float value;
    Status status;
    struct Item* next;
} Item;

#define MAX_ITEMS 10000

// Function prototypes
Item* initialize_items(int count, float min_value, float max_value);
void cleanup_items(Item** head);
int random_status_probability();
void set_random_value(float* value, float min_value, float max_value);

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Seed for randomness

    int num_items = 5000;  // Example number of items
    Item* item_head = initialize_items(num_items, 0.0f, 100.0f);

    if (item_head == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        return EXIT_FAILURE;
    }

    // Periodic cleanup
    cleanup_items(&item_head);

    // Free remaining items
    while (item_head != NULL) {
        Item* temp = item_head;
        item_head = item_head->next;
        free(temp);
    }

    return EXIT_SUCCESS;
}

// Initialize a dynamic collection of Items with random values and statuses
Item* initialize_items(int count, float min_value, float max_value) {
    if (count <= 0 || count > MAX_ITEMS) return NULL;

    Item* head = NULL;
    Item** last_ptr = &head; // Pointer to the next pointer for easy linking

    for (int i = 0; i < count; ++i) {
        Item* new_item = (Item*)malloc(sizeof(Item));
        if (!new_item) { 
            cleanup_items(&head); // Clean up on failure
            return NULL;
        }

        set_random_value(&new_item->value, min_value, max_value);
        new_item->status = random_status_probability() ? ACTIVE : INACTIVE;
        new_item->next = NULL;

        *last_ptr = new_item; 
        last_ptr = &new_item->next;
    }

    return head;
}

// Periodically clean up unused 'Item' instances
void cleanup_items(Item** head) {
    Item* current = *head;
    Item* prev = NULL;

    while (current != NULL) {
        if (current->status == INACTIVE) { // Example condition for cleanup
            Item* to_delete = current;
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Set a random float value within the specified range
void set_random_value(float* value, float min_value, float max_value) {
    *value = min_value + ((float)rand() / RAND_MAX) * (max_value - min_value);
}

// Determine status based on a predefined probability distribution
int random_status_probability() {
    return rand() % 100 < 70; // Example: 70% chance to be ACTIVE
}
