char memory_pool[POOL_SIZE];
size_t pool_offset = 0;

void* custom_alloc(size_t size) {
    if (pool_offset + size > POOL_SIZE) return NULL; // Out of memory
    void* ptr = &memory_pool[pool_offset];
    pool_offset += size;
    return ptr;
}

void reset_memory_pool() {
    pool_offset = 0;
}

// Initialize a node with a key and random value in the specified range
Node* create_node(const char* key) {
    Node* node = (Node*) custom_alloc(sizeof(Node));
    if (!node) return NULL;

    node->key = strdup(key);
    Value* first_value = (Value*) custom_alloc(sizeof(Value));
    if (!first_value) {
        free(node->key);
        free(node);
        return NULL;
    }

    first_value->data = rand() % (ASCII_RANGE_END - ASCII_RANGE_START + 1) + ASCII_RANGE_START;
    first_value->next = NULL;

    node->values_head = first_value;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

// Add a value to the end of a node's linked list
void add_value(Node* node, char data) {
    if (!node || !pthread_mutex_lock(&node->lock)) return;

    Value* new_value = (Value*) custom_alloc(sizeof(Value));
    if (!new_value) {
        pthread_mutex_unlock(&node->lock);
        return;
    }

    new_value->data = data;
    new_value->next = NULL;

    Value* current = node->values_head;
    while (current->next) {
        current = current->next;
    }
    current->next = new_value;

    pthread_mutex_unlock(&node->lock);
}

// Print all values in a node's linked list
void print_values(Node* node) {
    if (!node || !pthread_mutex_lock(&node->lock)) return;

    Value* current = node->values_head;
    while (current) {
        printf("Value: %c\n", current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&node->lock);
}

// Free a node and its values
void free_node(Node* node) {
    if (!node || !pthread_mutex_lock(&node->lock)) return;

    Value* current = node->values_head;
    while (current) {
        Value* next = current->next;
        custom_alloc(sizeof(Value)); // "Free" by returning to pool
        current = next;
    }

    pthread_mutex_unlock(&node->lock);
    pthread_mutex_destroy(&node->lock);

    free(node->key);
    custom_alloc(sizeof(Node)); // "Free" node itself

    // Reset memory pool for demonstration purposes (in a real system, manage it more carefully)
    reset_memory_pool();
}

int main() {
    srand(time(NULL));

    Node* node = create_node("example_key");
    add_value(node, 'A');
    print_values(node);
    free_node(node);

    return 0;
}
```

