#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

typedef struct {
    record *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordManager;

#define MAX_MEMORY_BUDGET 1024 // Define your maximum memory budget
#define RECORD_SIZE sizeof(record)
#define POINTER_OVERHEAD sizeof(void *)
#define RECORDS_PER_BLOCK ((MAX_MEMORY_BUDGET - POINTER_OVERHEAD) / (RECORD_SIZE + POINTER_OVERHEAD))

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

int create_record(int min, int max, record *rec) {
    if (!rec) return -1;
    rec->key = rand() % (max - min + 1) + min;
    rec->offset = rand();
    return 0;
}

RecordManager* initialize_manager(size_t initial_capacity) {
    RecordManager *manager = (RecordManager *)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (record *)calloc(initial_capacity, RECORD_SIZE);
    if (!manager->records) {
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int add_record(RecordManager *manager, int min_key, int max_key) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity + RECORDS_PER_BLOCK;
        record *new_records = (record *)realloc(manager->records, new_capacity * RECORD_SIZE);

        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    create_record(min_key, max_key, &manager->records[manager->count]);
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_manager(RecordManager *manager) {
    if (!manager) return;

    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

size_t serialize_records(const RecordManager *manager, uint8_t **buffer) {
    size_t total_size = manager->count * RECORD_SIZE;
    *buffer = (uint8_t *)malloc(total_size);

    if (!*buffer) return 0;

    memcpy(*buffer, manager->records, total_size);
    return total_size;
}

int deserialize_records(const uint8_t *buffer, RecordManager *manager) {
    size_t count = buffer ? *(size_t *)(buffer - sizeof(size_t)) : 0; // Assume buffer has a leading `count` size

    if (count > manager->capacity) {
        record *new_records = (record *)realloc(manager->records, count * RECORD_SIZE);

        if (!new_records) return -1;

        manager->records = new_records;
        manager->capacity = count;
    }

    memcpy(manager->records, buffer + sizeof(size_t), count * RECORD_SIZE);
    manager->count = count;

    return 0;
}

void* record_thread_function(void *arg) {
    RecordManager *manager = (RecordManager *)arg;

    if (add_record(manager, 1, 100) != 0) {
        fprintf(stderr, "Failed to add record\n");
    }

    uint8_t *buffer;
    size_t size = serialize_records(manager, &buffer);

    RecordManager deserialized_manager = {};
    memcpy(&deserialized_manager, manager, sizeof(RecordManager));
    deserialized_manager.records = (record *)malloc(deserialized_manager.capacity * RECORD_SIZE);
    deserialize_records(buffer, &deserialized_manager);

    free(buffer);
    return NULL;
}

int main() {
    initialize_random_seed();

    RecordManager *manager = initialize_manager(RECORDS_PER_BLOCK);
    if (!manager) {
        fprintf(stderr, "Failed to initialize record manager\n");
        return 1;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, record_thread_function, (void *)manager) != 0) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_manager(manager);

    return 0;
}
