#define MAX_DESCRIPTION_LENGTH 256

typedef struct {
    int value;
    long offset;
    char description[MAX_DESCRIPTION_LENGTH];
    int status;
} Record;

void log_event(const char *message, FILE *log_file) {
    time_t now = time(NULL);
    fprintf(log_file, "[%s] %s\n", ctime(&now), message);
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_records(Record **records, size_t num_records, int value_range_min, int value_range_max,
                        size_t max_size_limit, unsigned long unique_id_threshold, FILE *log_file) {

    srand(time(NULL)); // Seed the random number generator

    if (*records != NULL) {
        free(*records);
    }

    size_t record_size = sizeof(Record);
    *records = malloc(num_records * record_size);

    if (!*records) {
        log_event("Memory allocation failed", log_file);
        return;
    }

    unsigned long unique_ids[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = generate_random_int(value_range_min, value_range_max);
        (*records)[i].offset = rand() % LONG_MAX;
        snprintf((*records)[i].description, MAX_DESCRIPTION_LENGTH, "Record %zu", i);
        (*records)[i].status = 0;

        unique_ids[i] = (unsigned long)rand();
    }

    // Ensure unique IDs do not surpass the threshold
    for (size_t i = 0; i < num_records - 1; ++i) {
        for (size_t j = i + 1; j < num_records; ++j) {
            if (unique_ids[i] == unique_ids[j]) {
                // Reassign a new random unique ID
                unique_ids[j] = (unsigned long)rand();
                j = i;
            }
        }
    }

    log_event("Records initialized successfully", log_file);
}

void serialize_records(Record *records, size_t num_records, uint8_t **byte_array, FILE *log_file) {
    size_t record_size = sizeof(Record);
    size_t total_size = num_records * record_size;

    *byte_array = malloc(total_size);

    if (!*byte_array) {
        log_event("Serialization memory allocation failed", log_file);
        return;
    }

    memcpy(*byte_array, records, total_size);
    log_event("Records serialized successfully", log_file);
}

void cleanup(Record **records, uint8_t *byte_array, FILE *log_file) {
    if (*records != NULL) {
        free(*records);
        log_event("Memory deallocated for records", log_file);
    }

    if (byte_array != NULL) {
        free(byte_array);
        log_event("Memory deallocated for byte array", log_file);
    }
}

int main() {
    FILE *log_file = fopen("memory_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    Record *records = NULL;
    initialize_records(&records, 1000, 1, 100, 10 * sizeof(Record), 1000, log_file);

    uint8_t *byte_array = NULL;
    serialize_records(records, 1000, &byte_array, log_file);

    cleanup(&records, byte_array, log_file);

    fclose(log_file);
    return EXIT_SUCCESS;
}
