#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Metadata {
    char key[16];
    char value[64];
    struct Metadata *next;
} Metadata;

typedef struct DataItem {
    double value;
    char buffer[256]; // Assume a reasonable default max length
    Metadata *metadata_head; // Optional metadata list
    struct DataItem *next;
} DataItem;

typedef struct LinkedList {
    pthread_mutex_t lock;
    DataItem *head;
    size_t count;
    size_t capacity;
    double growth_factor;
} LinkedList;

// Initialize linked list with given capacity and growth factor
LinkedList* init_list(size_t initial_capacity, double growth_factor) {
    LinkedList *list = malloc(sizeof(LinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->count = 0;
    list->capacity = initial_capacity;
    list->growth_factor = growth_factor;

    return list;
}

// Validate the string
int validate_string(const char *str, size_t max_length, const char *allowed_chars) {
    if (strlen(str) > max_length) return 0;
    for (size_t i = 0; str[i] != '\0'; ++i) {
        if (!strchr(allowed_chars, str[i])) return 0;
    }
    return 1;
}

// Add an item to the list
int add_item(LinkedList *list, double value, const char *str, const char *metadata, size_t max_length, const char *allowed_chars) {
    pthread_mutex_lock(&list->lock);

    if (validate_string(str, max_length, allowed_chars)) {
        DataItem *new_node = malloc(sizeof(DataItem));
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return 0;
        }

        new_node->value = value;
        strncpy(new_node->buffer, str, max_length);

        // Add metadata if provided
        new_node->metadata_head = NULL;
        Metadata *meta_current = new_node->metadata_head;
        if (metadata) {
            while (*metadata != '\0') {
                Metadata *meta = malloc(sizeof(Metadata));
                if (!meta) {
                    pthread_mutex_unlock(&list->lock);
                    return 0;
                }
                sscanf(metadata, "%15[^=]=%63s", meta->key, meta->value);

                if (meta_current == NULL) {
                    new_node->metadata_head = meta;
                    meta_current = meta;
                } else {
                    meta_current->next = meta;
                    meta_current = meta;
                }
                metadata += strlen(meta->key) + strlen(meta->value) + 2; // Skip to next key-value pair
            }
        }

        new_node->next = list->head;
        list->head = new_node;
        list->count++;

        pthread_mutex_unlock(&list->lock);
        return 1;
    } else {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
}

// Iterate over the list
void iterate_list(LinkedList *list, void (*func)(DataItem*)) {
    pthread_mutex_lock(&list->lock);

    DataItem *current = list->head;
    while (current) {
        func(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the linked list
void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    DataItem *current = list->head;
    while (current) {
        DataItem *next = current->next;
        Metadata *meta_current = current->metadata_head;
        while (meta_current) {
            Metadata *meta_next = meta_current->next;
            free(meta_current);
            meta_current = meta_next;
        }
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example function to update a data item
void update_data_item(DataItem *item, double new_value) {
    if (item) {
        item->value = new_value;
    }
}

int main() {
    LinkedList *list = init_list(10, 1.5);

    add_item(list, 3.14, "valid_string", "key=value;key2=value2;", 256, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ");

    iterate_list(list, update_data_item);

    free_list(list);
    return 0;
}
