```javascript
const fs = require('fs').promises;
const crypto = require('crypto');
const path = require('path');

async function readFileWithIntegrityCheck(filePath) {
  try {
    const dataBuffer = await fs.readFile(filePath);
    const hash = crypto.createHash('sha256').update(dataBuffer).digest('hex');
    console.log(`File: ${filePath}, SHA-256 Hash: ${hash}`);
    return { content: dataBuffer, hash };
  } catch (error) {
    console.error(`Error reading file ${filePath}:`, error);
    throw new Error(`Failed to read file: ${filePath}`);
  }
}

async function processFiles(filePaths) {
  try {
    const promises = filePaths.map(readFileWithIntegrityCheck);
    return await Promise.all(promises);
  } catch (error) {
    console.error('Error processing files:', error);
    // Fallback mechanism for unsupported formats or encryption modes
    // Log and continue with other files if applicable
    return [];
  }
}

// Usage
