### Rust: Thread-safe HTTP Client Creation

```rust
use reqwest::{ClientBuilder, Error};
use tokio::sync::Mutex;
use std::sync::Arc;

#[derive(Debug)]
struct HttpClient {
    client: Arc<Mutex<reqwest::Client>>,
}

impl HttpClient {
    pub async fn new(validate_certificate: bool) -> Result<Self, Error> {
        let client_builder = ClientBuilder::new();
        if !validate_certificate {
            client_builder.danger_accept_invalid_certs(true);
        }

        let client = client_builder.build()?;
        Ok(Self {
            client: Arc::new(Mutex::new(client)),
        })
    }

    pub async fn send_request(&self, url: &str) -> Result<reqwest::Response, Error> {
        let mut client_lock = self.client.lock().await;
        client_lock.get(url).send().await
    }
}

#[tokio::main]
async fn main() {
    let http_client = HttpClient::new(true).await.expect("Failed to create HTTP Client");

    if let Ok(response) = http_client.send_request("https://www.example.com").await {
        println!("Response: {:?}", response);
    } else {
        eprintln!("Request failed");
    }
}
```

