#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/resource.h>

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    Record* records;
    size_t num_records;
    int success_allocations;
    int failed_allocations;
} MemoryManager;

void log_allocation_status(MemoryManager* manager) {
    printf("Successful allocations: %d\n", manager->success_allocations);
    printf("Failed allocations: %d\n", manager->failed_allocations);
}

long get_rss(void) {
    struct rusage usage;
    if (getrusage(RUSAGE_SELF, &usage) == 0) {
        return usage.ru_maxrss; // In kilobytes
    }
    return -1;
}

void log_memory_usage(size_t iteration) {
    long rss = get_rss();
    if (rss != -1) {
        printf("Iteration %zu: Resident Set Size = %ld KB\n", iteration, rss);
    }
}

int allocate_and_initialize(MemoryManager* manager, size_t num_records, int key_range_min, int key_range_max, int record_range_min, int record_range_max) {
    time_t start_time = time(NULL);

    pthread_mutex_lock(&manager->lock);

    // Attempt to allocate memory
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        manager->failed_allocations++;
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        manager->failed_allocations++;
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        manager->failed_allocations++;
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Initialize keys and record values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);
        records[i].value = record_range_min + rand() % (record_range_max - record_range_min + 1);
    }

    // Free old memory if resizing
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);

    manager->offsets = offsets;
    manager->keys = keys;
    manager->records = records;
    manager->num_records = num_records;
    manager->success_allocations++;

    pthread_mutex_unlock(&manager->lock);

    time_t end_time = time(NULL);
    printf("Execution time: %ld seconds\n", difftime(end_time, start_time));

    log_allocation_status(manager);
    return 0;
}

void free_memory(MemoryManager* manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->offsets) free(manager->offsets);
    if (manager->keys) free(manager->keys);
    if (manager->records) free(manager->records);

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    MemoryManager manager;
    pthread_mutex_init(&manager.lock, NULL);

    size_t num_records = 1000; // Example number of records
    int key_range_min = 1, key_range_max = 100;
    int record_range_min = -50, record_range_max = 50;

    if (allocate_and_initialize(&manager, num_records, key_range_min, key_range_max, record_range_min, record_range_max) == 0) {
        for (size_t i = 0; i < manager.num_records; ++i) {
            printf("Key: %d, Record Value: %d\n", manager.keys[i], manager.records[i].value);
        }
    }

    free_memory(&manager);

    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```

### Explanation:

- **MemoryManager Structure**: Encapsulates all relevant memory and synchronization components.
- **Synchronization**: Uses `pthread_mutex_t` to ensure thread-safe operations on shared data.
- **Allocation & Initialization**: Allocates and initializes arrays for offsets, keys, and records. Handles failures gracefully by logging and releasing any allocated resources.
- **Logging**: Logs allocation success/failure counts and memory usage trends.
- **Resource Management**: Frees allocated memory safely and reports execution time to monitor performance.
- **Concurrency Handling**: Provides thread safety through mutex locks.']

