// Define the record structure.
typedef struct {
    int value;
} Record;

// Define the linked list node structure.
typedef struct Node {
    size_t record_index; // Index into the records array.
    struct Node *next;
    struct Node *prev;
} Node;

// Function prototypes for modularity and extensibility.
void initialize_data(long num_offsets, long num_keys, Record **records, int **keys);
void create_linked_list(size_t num_records, Node **head, size_t *record_indices);
Node* insert_node(Node *head, size_t record_index);
void free_resources(Record *records, int *keys, Node *head);

// Main function that performs all operations.
void manage_data_and_lists(long num_offsets, long num_keys) {
    if (num_offsets <= 0 || num_keys <= 0) return;

    // Allocate memory for the arrays and handle potential allocation errors.
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = NULL;
    Record *records = NULL;

    if (!offsets) goto cleanup;
    keys = malloc(num_keys * sizeof(int));
    records = malloc(num_keys * sizeof(Record));

    if (!keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        goto cleanup;
    }

    // Initialize data structures with random values.
    initialize_data(num_offsets, num_keys, &records, &keys);

    // Create the linked list based on sorted keys.
    Node *head = NULL;
    create_linked_list(num_keys, &head, (size_t *)malloc(sizeof(size_t) * num_keys));

    if (!head) {
        free_resources(records, keys, head);
        goto cleanup;
    }

    // Example of inserting a new node at the end; actual logic would depend on use case.
    insert_node(head, 0);

    // Cleanup all allocated resources to avoid memory leaks.
cleanup:
    free_resources(records, keys, head);
}

void initialize_data(long num_offsets, long num_keys, Record **records, int **keys) {
    srand(time(NULL)); // Seed for random number generation.

    for (long i = 0; i < num_offsets; ++i) {
        // Initialize offsets here if needed.
    }

    for (long i = 0; i < num_keys; ++i) {
        (*keys)[i] = rand() % 100; // Populate keys with random integers [0, 99].
    }

    for (long i = 0; i < num_keys; ++i) {
        (*records)[i].value = rand() % 100; // Populate records with random integers [0, 99].
    }
}

void create_linked_list(size_t num_records, Node **head, size_t *record_indices) {
    for (size_t i = 0; i < num_records; ++i) {
        record_indices[i] = i;
    }

    // Sort indices based on keys in ascending order.
    for (size_t i = 0; i < num_records - 1; ++i) {
        for (size_t j = 0; j < num_records - i - 1; ++j) {
            if (((*head)[j].record_index)->value > ((*head)[j + 1].record_index)->value) {
                size_t temp = record_indices[j];
                record_indices[j] = record_indices[j + 1];
                record_indices[j + 1] = temp;
            }
        }
    }

    // Create nodes and link them based on sorted indices.
    for (size_t i = 0; i < num_records; ++i) {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) break;

        new_node->record_index = record_indices[i];
        new_node->next = NULL;
        new_node->prev = (*head);

        if ((*head)) (*head)->next = new_node;
        (*head) = new_node;
    }
}

Node* insert_node(Node *head, size_t record_index) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return head;

    // Traverse to the end of the list.
    while (head->next) {
        head = head->next;
    }

    new_node->record_index = record_index;
    new_node->next = NULL;
    new_node->prev = head;

    head->next = new_node;
    return head;
}

void free_resources(Record *records, int *keys, Node *head) {
    // Free the linked list nodes.
    while (head) {
        Node *temp = head;
        head = head->next;
        free(temp);
    }

    // Free allocated memory for keys and records arrays.
    free(keys);
    free(records);
}
