#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>

#define MAX_COMMANDS 5
#define RETRY_LIMIT 10
#define LOG_SIZE 100

typedef struct {
    int Transport_SN;
    char *MAC_Receive_Buffer;
} MAC_Transport_SN;

typedef struct {
    char command[256];
    int is_executing;
} CommandSlot;

typedef struct {
    CommandSlot slots[MAX_COMMANDS];
    int head, tail;
    pthread_mutex_t lock;
} CircularLogBuffer;

CircularLogBuffer log_buffer = {.head = 0, .tail = 0};
pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

void log_command(const char *log) {
    pthread_mutex_lock(&buffer_lock);
    log_buffer.slots[log_buffer.tail % LOG_SIZE].command = strncpy(log_buffer.slots[log_buffer.tail % LOG_SIZE].command, log, sizeof(log_buffer.slots[0].command));
    log_buffer.tail++;
    pthread_mutex_unlock(&buffer_lock);
}

int initialize_mac_transport_sn(MAC_Transport_SN *transport_sn, size_t frame_size) {
    for (int retries = 0; retries < RETRY_LIMIT; ++retries) {
        transport_sn->MAC_Receive_Buffer = malloc(frame_size);
        if (transport_sn->MAC_Receive_Buffer != NULL) {
            return 1;
        }
        sleep(1); // Delay before retrying
    }
    return 0;
}

void execute_command(MAC_Transport_SN *transport_sn, const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        log_command("Fork failed");
        return;
    }

    if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(EXIT_FAILURE); // If exec fails
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);
        char log[256];
        snprintf(log, sizeof(log), "Executed: %s with status %d", command, WEXITSTATUS(status));
        log_command(log);
    }
}

void manage_mac_transport_sn_array(MAC_Transport_SN *array, size_t frame_size, const char *commands[], int num_commands) {
    pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_commands && i < MAX_COMMANDS; ++i) {
        MAC_Transport_SN transport_sn;

        if (!initialize_mac_transport_sn(&transport_sn, frame_size)) {
            log_command("Buffer allocation failed after retries");
            continue;
        }

        pthread_mutex_lock(&array_lock);
        array[i] = transport_sn;
        pthread_mutex_unlock(&array_lock);

        char log[256];
        snprintf(log, sizeof(log), "Initiated command: %s", commands[i]);
        log_command(log);

        execute_command(&transport_sn, commands[i]);

        free(transport_sn.MAC_Receive_Buffer);
    }
}

int main() {
    MAC_Transport_SN transport_array[MAX_COMMANDS];
    const char *commands[] = {"ls -l", "echo 'Hello, World!'", "date"};
    int num_commands = sizeof(commands) / sizeof(commands[0]);

    manage_mac_transport_sn_array(transport_array, 1024, commands, num_commands);

    return 0;
}
