#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit: 1MB
#define LONG_OFFSETS_COUNT 1000
#define INT_KEYS_COUNT 500
#define RECORD_VALUE_RANGE 100

typedef struct {
    int value;
} Record;

// Function prototypes
void initialize_structures(long **offsets, int **keys, Record **records);
int allocate_memory(long **offsets, size_t offset_count, int **keys, size_t key_count, Record **records, size_t record_count);
void free_resources(long *offsets, int *keys, Record *records);
uint8_t* serialize_data(const long *offsets, size_t offset_count, const int *keys, size_t key_count, const Record *records, size_t record_count, size_t *output_size);
int deserialize_data(const uint8_t *data, size_t data_size, long **offsets, size_t *offset_count, int **keys, size_t *key_count, Record **records, size_t *record_count);
void populate_random_values(int *array, size_t count, int min_value, int max_value);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_structures(long **offsets, int **keys, Record **records) {
    pthread_mutex_lock(&mutex);

    size_t total_memory_required = sizeof(long) * LONG_OFFSETS_COUNT + sizeof(int) * INT_KEYS_COUNT + sizeof(Record) * INT_KEYS_COUNT;
    if (total_memory_required > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Memory limit exceeded.\n");
        exit(EXIT_FAILURE);
    }

    if (!allocate_memory(offsets, LONG_OFFSETS_COUNT, keys, INT_KEYS_COUNT, records, INT_KEYS_COUNT)) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Populate offsets and keys with random values
    for (size_t i = 0; i < LONG_OFFSETS_COUNT; ++i) {
        (*offsets)[i] = rand(); // Example offset value
    }
    populate_random_values(*keys, INT_KEYS_COUNT, 1, RECORD_VALUE_RANGE);

    // Populate records with random values
    for (size_t i = 0; i < INT_KEYS_COUNT; ++i) {
        (*records)[i].value = rand() % RECORD_VALUE_RANGE + 1;
    }

    pthread_mutex_unlock(&mutex);
}

int allocate_memory(long **offsets, size_t offset_count, int **keys, size_t key_count, Record **records, size_t record_count) {
    *offsets = (long *)malloc(sizeof(long) * offset_count);
    if (!*offsets) return 0;

    *keys = (int *)malloc(sizeof(int) * key_count);
    if (!*keys) {
        free(*offsets);
        return 0;
    }

    *records = (Record *)malloc(sizeof(Record) * record_count);
    if (!*records) {
        free(*keys);
        free(*offsets);
        return 0;
    }

