typedef struct {
    int value;
    long offset;
} Record;

typedef struct HashNode {
    long key;
    Record record;
    struct HashNode* next;
} HashNode;

#define MAX_HASH_MAP_SIZE 1024

HashNode* hash_map[MAX_HASH_MAP_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(long key) {
    return (key * 2654435761UL) % MAX_HASH_MAP_SIZE;
}

void init_hash_map() {
    for (int i = 0; i < MAX_HASH_MAP_SIZE; ++i)
        hash_map[i] = NULL;
}

void insert_record(Record record, long offset) {
    unsigned long index = hash(offset);
    pthread_mutex_lock(&lock);

    HashNode* node = malloc(sizeof(HashNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for hash map.\n");
        exit(EXIT_FAILURE);
    }
    node->key = offset;
    node->record = record;
    node->next = hash_map[index];
    hash_map[index] = node;

    pthread_mutex_unlock(&lock);
}

Record* find_record(long offset) {
    unsigned long index = hash(offset);

    pthread_mutex_lock(&lock);
    HashNode* node = hash_map[index];

    while (node != NULL) {
        if (node->key == offset) {
            pthread_mutex_unlock(&lock);
            return &node->record;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void free_hash_map() {
    for (int i = 0; i < MAX_HASH_MAP_SIZE; ++i) {
        HashNode* node = hash_map[i];
        while (node != NULL) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
}

void serialize_record(Record record, unsigned char** buffer, size_t* length) {
    *length = sizeof(record.value) + sizeof(record.offset);
    *buffer = malloc(*length);
    if (!*buffer) {
        fprintf(stderr, "Memory allocation failed for serialization.\n");
        exit(EXIT_FAILURE);
    }

    unsigned char* ptr = *buffer;
    memcpy(ptr, &htobe32(record.value), sizeof(record.value));
    ptr += sizeof(record.value);

    memcpy(ptr, &htobe64(record.offset), sizeof(record.offset));
}

Record deserialize_record(unsigned char* buffer) {
    Record record;
    unsigned char* ptr = buffer;

    memcpy(&record.value, ptr, sizeof(record.value));
    record.value = be32toh(record.value);
    ptr += sizeof(record.value);

    memcpy(&record.offset, ptr, sizeof(record.offset));
    record.offset = be64toh(record.offset);

    return record;
}

Record* allocate_records(size_t max_size, size_t initial_count, int range_min, int range_max) {
    srand(time(NULL));

    Record* records = NULL;
    size_t current_size = 0;

    void *p = realloc(records, initial_count * sizeof(Record));
    if (!p) {
        fprintf(stderr, "Initial memory allocation failed.\n");
        free(records);
        return NULL;
    }
    records = p;
    current_size = initial_count;

    for (size_t i = 0; i < initial_count; ++i) {
        int value = rand() % (range_max - range_min + 1) + range_min;
        long offset = i * sizeof(Record); // Example offset calculation
        records[i].value = value;
        records[i].offset = offset;

        insert_record(records[i], offset);
    }

    return records;
}

void resize_records_if_needed(Record** records, size_t* current_size, size_t max_size) {
    if (*current_size < max_size / sizeof(Record)) {
        size_t new_size = *current_size + 1;
        void *p = realloc(*records, new_size * sizeof(Record));
        if (!p) {
            fprintf(stderr, "Resize memory allocation failed.\n");
            free(*records);
            *records = NULL;
        } else {
            *records = p;
            (*current_size)++;
        }
    }
}

void free_records(Record* records) {
    free(records);
    free_hash_map();
}

