void manage_arrays_and_records(size_t offset_count, size_t key_count, size_t record_count, int min_value, int max_value) {
    if (record_count > offset_count || record_count > key_count) {
        fprintf(stderr, "Record count must be less than or equal to both offset and key counts.\n");
        return;
    }

    // Allocate memory for offsets
    long *offsets = malloc(offset_count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return;
    }
    for (size_t i = 0; i < offset_count; ++i) {
        offsets[i] = 0;
    }

    // Allocate memory for keys
    int *keys = malloc(key_count * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return;
    }
    for (size_t i = 0; i < key_count; ++i) {
        keys[i] = i;
    }

    // Allocate memory for records
    Record *records = malloc(record_count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Populate records with unique keys and random values
    int used_keys[record_count];
    for (size_t i = 0; i < record_count; ++i) {
        used_keys[i] = -1;  // Mark as unused initially
    }

    for (size_t i = 0; i < record_count; ++i) {
        int key;
        do {
            key = rand() % key_count;
        } while (used_keys[key] != -1);

        used_keys[key] = key;

        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[key];
    }

    // At this point, you can perform operations on the populated records
    // Example: Print values of all records
    for (size_t i = 0; i < record_count; ++i) {
        printf("Record %zu: Value = %d, Offset = %ld, Key = %d\n",
               i, records[i].value, *records[i].offset_ptr, *records[i].key_ptr);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
