        logs[i].temperature = temperature;

        int status_index = -1;
        for (int attempt = 0; attempt <= MAX_RETRIES; ++attempt) {
            char status = get_status_indicator(attempt);
            if (!used_statuses[(unsigned char)status]) {
                used_statuses[(unsigned char)status] = 1;
                logs[i].status = status;
                status_index = i;
