        }

        if (status_index == -1) {
            logs[i].status = 'N'; // No unique status found after retries
        }
    }

    sort_logs(logs, log_count);

    return logs;
}

void sort_logs(LogEntry *logs, size_t count) {
    qsort_r(logs, count, sizeof(LogEntry), [](const void* a, const void* b, void* arg) -> int {
        (void)arg; // Unused
        LogEntry *log_a = (LogEntry*)a;
        LogEntry *log_b = (LogEntry*)b;
