```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_LEVELS 5

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARN,
    LOG_ERROR,
    LOG_CRITICAL
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char *message;
    pthread_mutex_t lock; // Lock for thread safety
} LogEntry;

// Thread-safe queue structure
typedef struct LogQueue {
    LogEntry **entries;
    size_t capacity;
    size_t count;
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} LogQueue;

LogQueue* create_log_queue(size_t initial_capacity) {
    LogQueue *queue = (LogQueue *)malloc(sizeof(LogQueue));
    queue->entries = (LogEntry **)calloc(initial_capacity, sizeof(LogEntry *));
    queue->capacity = initial_capacity;
    queue->count = 0;
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond_var, NULL);
    return queue;
}

void destroy_log_queue(LogQueue *queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        LogEntry *entry = queue->entries[(queue->head + i) % queue->capacity];
        free(entry->message);
        pthread_mutex_destroy(&entry->lock);
        free(entry);
    }
    free(queue->entries);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond_var);
    free(queue);
}

int log_queue_push(LogQueue *queue, LogEntry *entry) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->count == queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        LogEntry **new_entries = (LogEntry **)realloc(queue->entries, new_capacity * sizeof(LogEntry *));
        if (!new_entries) {
            pthread_mutex_unlock(&queue->mutex);
            return -1; // Memory allocation failure
        }
        for (size_t i = queue->capacity; i < new_capacity; ++i) {
            size_t idx = (queue->tail + i) % queue->capacity;
            new_entries[i] = queue->entries[idx];
        }
        queue->entries = new_entries;
        queue->capacity = new_capacity;
    }

    queue->entries[queue->tail] = entry;
    queue->tail = (queue->tail + 1) % queue->capacity;
    ++queue->count;

    pthread_cond_signal(&queue->cond_var);
    pthread_mutex_unlock(&queue->mutex);

    return 0;
}

LogEntry* log_queue_pop(LogQueue *queue, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    pthread_mutex_lock(&queue->mutex);

    while (queue->count == 0) {
        int rc = pthread_cond_timedwait(&queue->cond_var, &queue->mutex, &ts);
        if (rc == ETIMEDOUT) {
            pthread_mutex_unlock(&queue->mutex);
            return NULL;
        }
    }

    LogEntry *entry = queue->entries[queue->head];
    ++queue->head;
    --queue->count;

    pthread_mutex_unlock(&queue->mutex);

    return entry;
}

void add_log_entry(LogQueue *queue, LogLevel level, const char *message) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    if (!entry) {
        fprintf(stderr, "Failed to allocate memory for log entry\n");
        return;
    }

    pthread_mutex_init(&entry->lock, NULL);
    entry->timestamp = time(NULL);
    entry->level = level;

    size_t len = strlen(message) + 1;
    entry->message = (char *)malloc(len);
    if (!entry->message) {
        fprintf(stderr, "Failed to allocate memory for log message\n");
        pthread_mutex_destroy(&entry->lock);
        free(entry);
        return;
    }
    memcpy(entry->message, message, len);

    if (log_queue_push(queue, entry) != 0) {
        free(entry->message);
        pthread_mutex_destroy(&entry->lock);
        free(entry);
        fprintf(stderr, "Failed to push log entry onto queue\n");
    }
}

void process_log_entries(LogQueue *queue) {
    while (1) {
        LogEntry *entry = log_queue_pop(queue, 1000); // Timeout of 1 second
        if (!entry) continue;

        pthread_mutex_lock(&entry->lock);
        printf("[%ld] [%d]: %s\n", entry->timestamp, entry->level, entry->message);
        pthread_mutex_unlock(&entry->lock);

        free(entry->message);
        pthread_mutex_destroy(&entry->lock);
        free(entry);
    }
}

// Example usage
int main() {
    LogQueue *queue = create_log_queue(10);

    // Simulate adding log entries from multiple threads
    for (int i = 0; i < 100; ++i) {
        add_log_entry(queue, LOG_INFO, "This is a test log message");
    }

    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, (void *(*)(void *))process_log_entries, queue);
    pthread_join(processor_thread, NULL);

    destroy_log_queue(queue);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Utilizes `pthread_mutex` and `pthread_cond` for thread-safe operations on the log queue.
- **Dynamic Memory Management**: Allocates memory dynamically for each log entry's message and handles reallocation of the queue when full.
- **Scalability & Performance**: Designed to handle high-throughput scenarios with dynamic resizing of the internal queue.
- **Concurrency Handling**: Supports concurrent access and modification of log entries, ensuring data integrity with mutex locks.
- **Robustness**: Includes error handling for memory allocation failures and timeouts in condition variable waits.']

