#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

// Third-party logging API mockup
void log_message(const char* message) {
    printf("LOG: %s\n", message);
}

// Struct definition
typedef struct {
    double value;
    char *name;
} record_t;

// Thread lock for concurrency
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void serialize_data(record_t *records, size_t num_records, uint8_t **output, size_t *output_size);
void deserialize_data(uint8_t *input, size_t input_size, record_t **records, size_t *num_records);

// Main function for memory management and initialization
int manage_memory_and_initialize(size_t max_mem_usage, double min_value, double max_value) {
    srand(time(NULL)); // Seed RNG

    double *doubles = NULL;
    char **strings = NULL;
    record_t *records = NULL;

    size_t num_records = 10; // Example number of records
    size_t total_mem_used = 0;
    int success = 1;

    pthread_mutex_lock(&lock);

    log_message("Starting memory allocation and initialization");

    try {
        doubles = (double *)malloc(num_records * sizeof(double));
        if (!doubles) goto error;
        total_mem_used += num_records * sizeof(double);

        strings = (char **)malloc(num_records * sizeof(char *));
        if (!strings) goto error;
        total_mem_used += num_records * sizeof(char *);

        records = (record_t *)malloc(num_records * sizeof(record_t));
        if (!records) goto error;
        total_mem_used += num_records * sizeof(record_t);

        for (size_t i = 0; i < num_records; ++i) {
            doubles[i] = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
            strings[i] = strdup("Example string");
            if (!strings[i]) goto error;
            total_mem_used += strlen(strings[i]) + 1;

            records[i].value = doubles[i];
            records[i].name = strings[i];

            if (total_mem_used > max_mem_usage) {
                log_message("Memory limit exceeded, aborting initialization");
                success = 0;
                goto error;
            }
        }

        uint8_t *serialized_data = NULL;
        size_t serialized_size = 0;

        serialize_data(records, num_records, &serialized_data, &serialized_size);

        // Simulate connection to remote endpoint
        log_message("Connected to remote endpoint");

        // Clean up and exit successfully
        free(doubles);
        for (size_t i = 0; i < num_records; ++i) {
            free(strings[i]);
        }
        free(strings);
        free(records);

    } catch (...) {
        success = 0;
        goto error;
    }

    log_message("Initialization and allocation completed successfully");
    pthread_mutex_unlock(&lock);
    return success;

error:
    if (doubles) free(doubles);
    for (size_t i = 0; doubles && strings[i]; ++i) {
        free(strings[i]);
    }
    if (strings) free(strings);
    if (records) free(records);

    log_message("Error encountered during allocation and initialization");
    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to serialize data
void serialize_data(record_t *records, size_t num_records, uint8_t **output, size_t *output_size) {
    // Calculate required buffer size for serialization
    *output_size = sizeof(size_t); // To store the number of records
    for (size_t i = 0; i < num_records; ++i) {
        *output_size += sizeof(double);
        *output_size += strlen(records[i].name) + 1;
    }

    *output = (uint8_t *)malloc(*output_size);
    if (!*output) return;

    uint8_t *ptr = *output;

    memcpy(ptr, &num_records, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < num_records; ++i) {
        double value = htond(records[i].value);
        size_t name_len = strlen(records[i].name) + 1;

        memcpy(ptr, &value, sizeof(double));
        ptr += sizeof(double);

        memcpy(ptr, records[i].name, name_len);
        ptr += name_len;
    }
}

// Function to deserialize data
void deserialize_data(uint8_t *input, size_t input_size, record_t **records, size_t *num_records) {
    uint8_t *ptr = input;

    memcpy(num_records, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    *records = (record_t *)malloc(*num_records * sizeof(record_t));

    for (size_t i = 0; i < *num_records; ++i) {
        double value;
        size_t name_len;

        memcpy(&value, ptr, sizeof(double));
        ptr += sizeof(double);
        value = dtoh(value);

        records[i].value = value;

        char *name = (char *)malloc(256); // Assume max string length
        memcpy(name, ptr, 256);
        name[255] = '\0'; // Safety null-termination

        while (*ptr && (size_t)(ptr - input + strlen(ptr) + 1) < input_size) {
            ++ptr;
        }
        ++ptr; // Skip the null terminator

        records[i].name = strdup(name);
        free(name);
    }
}

// Network byte order conversion
double htond(double hostp) {
    union {
        double d;
        uint64_t u;
    } source, dest;

    source.d = hostp;
    dest.u = htonl(source.u);

    return dest.d;
}

double dtoh(double netp) {
    union {
        double d;
        uint64_t u;
    } source, dest;

    source.d = netp;
    dest.u = ntohl(source.u);

    return dest.d;
}
