        *hash_length = MD5_DIGEST_LENGTH;
        unsigned char *result = malloc(*hash_length);
        if (!result) return NULL;
        memcpy(result, hash, *hash_length);
        return result;
    }
    return NULL;
}

// Function to manage memory allocation and initialization
int initialize_data_structures(const char *input_string) {
    size_t input_length = strlen(input_string);
    int key_array[input_length];
    long offset_values[input_length];

    unsigned char* md5_hash;
    size_t hash_length;
    if ((md5_hash = calculate_md5_hash(input_string, &hash_length)) == NULL) {
        fprintf(stderr, "Failed to allocate memory for MD5 hash.\n");
        return -1; // Indicate error
    }

    record records[input_length];

    srand(time(NULL));  // Seed random number generator
    long min_offset = 1000;
    long max_offset = 2000;
    int prev_key = -1;

    for (size_t i = 0; i < input_length; ++i) {
        // Generate unique key from MD5 hash bytes
        key_array[i] = (int)md5_hash[i % hash_length];

        while ((records[i].key = key_array[i]) == prev_key) { 
            key_array[i] = (int)md5_hash[(i + 1) % hash_length]; // Adjust if consecutive keys are the same
        }
        prev_key = records[i].key;

        do {
            records[i].offset = min_offset + rand() % (max_offset - min_offset);
        } while ((i > 0 && records[i].offset == records[i-1].offset) || 
                 (i < input_length - 1 && records[i].offset == records[i+1].offset));
    }

    free(md5_hash); // Free dynamically allocated MD5 hash memory

    // Simulating usage of the initialized structures
    for (size_t i = 0; i < input_length; ++i) {
        printf("Record %zu: Key = %d, Offset = %ld\n", i, records[i].key, records[i].offset);
    }

    return 0; // Indicate success
}

int main() {
    const char *input_string = "HelloWorld";
    if (initialize_data_structures(input_string) != 0) {
        fprintf(stderr, "Failed to initialize data structures.\n");
        return -1;
    }
    return 0;
}
