        log_error("Invalid initial size");
        return NULL;
    }

    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) {
        log_error("Failed to allocate DataManager");
        return NULL;
    }

    dm->count = 0;
    pthread_mutex_init(&dm->lock, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
