void destroy_data_manager(DataManager *dm) {
    if (dm) {
        for (size_t i = 0; i < dm->count; ++i) {
            free(dm->records[i]);
        }
        pthread_mutex_destroy(&dm->lock);
        free(dm);
    }
}

int add_record(DataManager *dm, long offset, int key) {
    if (dm->count >= MAX_RECORDS) {
        log_error("Max records reached");
        return -1;
    }

    pthread_mutex_lock(&dm->lock);
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&dm->lock);
        log_error("Failed to allocate new record");
        return -1;
    }

    new_record->offset = offset;
    new_record->key = key;
    dm->records[dm->count++] = new_record;
    pthread_mutex_unlock(&dm->lock);

    return 0;
}

Record* get_record_by_key(DataManager *dm, int key) {
