    if (!file) {
        log_error("Failed to open file");
        return;
    }

    pthread_t threads[10]; // Assuming a maximum of 10 threads
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, thread_read_file, dm);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);
}

