    Cache *cache = malloc(sizeof(Cache));
    if (!cache) {
        log_error("Failed to allocate cache");
        return NULL;
    }

    memset(cache->records, 0, sizeof(cache->records));
    cache->hit_count = 0;
    cache->access_count = 0;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void destroy_cache(Cache *cache) {
    if (cache) {
        pthread_mutex_destroy(&cache->lock);
        free(cache);
    }
}

int cache_get(Cache *cache, long offset, Record **record) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < CACHE_LIMIT; ++i) {
        if (cache->records[i].offset == offset) {
            (*record) = &cache->records[i];
            cache->hit_count++;
        }
    }

    cache->access_count++;
    pthread_mutex_unlock(&cache->lock);

    return (*record != NULL);
}

void cache_put(Cache *cache, Record record) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < CACHE_LIMIT; ++i) {
        if (cache->records[i].offset == 0) { // Assuming offset 0 means unused slot
            cache->records[i] = record;
            break;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

