#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <openssl/md5.h>

#define NUM_THREADS 4

typedef struct {
    int key;
    long offset;
    double precision_value;
    time_t timestamp;
} record;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int available_threads;
    int work_count;
    record **records;
    int capacity;
} ThreadPool;

ThreadPool *create_thread_pool(int capacity) {
    ThreadPool *pool = (ThreadPool *)malloc(sizeof(ThreadPool));
    pool->available_threads = NUM_THREADS;
    pool->work_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->records = (record **)malloc(capacity * sizeof(record *));
    pool->capacity = capacity;
    return pool;
}

void log_message(const char *message) {
    printf("%s\n", message);  // Replace with actual logging implementation
}

void free_resources(ThreadPool *pool) {
    for (int i = 0; i < pool->work_count; ++i) {
        free(pool->records[i]);
    }
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}

void *process_string(void *arg) {
    char **strings = (char **)arg;
    int num_strings = strlen(strings) / sizeof(char *);
    ThreadPool *pool = create_thread_pool(num_strings);

    for (int i = 0; i < num_strings; ++i) {
        if (pthread_mutex_lock(&pool->lock) != 0) continue;

        while (pool->work_count >= pool->capacity || pool->available_threads == 0) {
            pthread_cond_wait(&pool->cond, &pool->lock);
        }

        pool->available_threads--;
        pthread_mutex_unlock(&pool->lock);

        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char *)strings[i], strlen(strings[i]), (unsigned char *)&hash);

        long offset = rand() % 1000; // Example range for offset
        int key = i;
        double precision_value = ((double)rand() / RAND_MAX) * 100.0; // Example range [0, 100]

        record *rec = (record *)malloc(sizeof(record));
        rec->key = key;
        rec->offset = offset;
        rec->precision_value = precision_value;
        rec->timestamp = time(NULL);

        if (pthread_mutex_lock(&pool->lock) != 0) {
            free(rec);
            continue;
        }

        pool->records[pool->work_count++] = rec;
        log_message("Record created successfully");

        pthread_mutex_unlock(&pool->lock);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_mutex_lock(&pool->lock) != 0) continue;

        pool->available_threads--;
        if (pool->work_count == num_strings && pool->available_threads == 0) {
            pthread_cond_broadcast(&pool->cond);
        }
        pthread_mutex_unlock(&pool->lock);
    }

    free_resources(pool);
    return NULL;
}

void manage_memory_and_process(char **strings, int num_strings) {
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, process_string, strings) != 0) {
            log_message("Failed to create thread");
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```

