['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

void manage_memory_and_initialize(const char *input) {
    size_t length = strlen(input);
    if (length == 0) return;

    // Allocate memory for arrays
    long *offsets = malloc(length * sizeof(long));
    int *keys = malloc(length * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    // Calculate MD5 hash of the input string
    unsigned char md5hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)input, length, md5hash);

    // Allocate memory for records
    record *records = malloc(length * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    // Populate records with keys and offsets
    srand((unsigned int)time(NULL));
    long min_offset = 0;
    long max_offset = 1000000; // Example range for random offset

    for (size_t i = 0; i < length; ++i) {
        // Generate key from MD5 hash and index to minimize collisions
        keys[i] = (int)((md5hash[i % MD5_DIGEST_LENGTH] + i) & 0xFF);

        if (i > 0 && keys[i] == records[i - 1].key) {
            keys[i]++;
        }

        // Generate unique random offset
        long offset;
        do {
            offset = min_offset + rand() % (max_offset - min_offset);
        } while (offsets[offset % length] != 0);

        offsets[offset % length] = offset;

        records[i].key = keys[i];
        records[i].offset = offset;
    }

    // Free dynamically allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    const char *input = "example input string";
    manage_memory_and_initialize(input);
    return 0;
}
```

