typedef struct {
    long timestamp;
    char event_type;
    unsigned int event_id;
} Event;

typedef struct {
    long* offset_array;
    int* key_array;
    Event* events;
    size_t num_events;
    pthread_mutex_t lock;
} DataStructures;

void initialize_random() {
    srand((unsigned int)time(NULL));
}

int random_char_range(char start, char end) {
    return rand() % (end - start + 1) + start;
}

unsigned int random_uint_range(unsigned int min, unsigned int max) {
    return (rand() % (max - min + 1)) + min;
}

void free_memory(DataStructures* ds) {
    pthread_mutex_lock(&ds->lock);
    if (ds->offset_array != NULL) {
        free(ds->offset_array);
    }
    if (ds->key_array != NULL) {
        free(ds->key_array);
    }
    if (ds->events != NULL) {
        free(ds->events);
    }
    pthread_mutex_unlock(&ds->lock);
}

void* manage_memory_lifecycle(void* arg) {
    DataStructures* ds = (DataStructures*)arg;

    // Initialize mutex
    pthread_mutex_init(&ds->lock, NULL);

    // Allocate and initialize arrays
    ds->offset_array = malloc(ds->num_events * sizeof(long));
    ds->key_array = malloc(ds->num_events * sizeof(int));

    if (!ds->offset_array || !ds->key_array) {
        perror("Memory allocation failed");
        free_memory(ds);
        pthread_mutex_destroy(&ds->lock);
        return NULL;
    }

    // Initialize event array
    ds->events = malloc(ds->num_events * sizeof(Event));

    if (!ds->events) {
        perror("Event memory allocation failed");
        free_memory(ds);
        pthread_mutex_destroy(&ds->lock);
        return NULL;
    }

    initialize_random();

    // Populate data structures with random values
    for (size_t i = 0; i < ds->num_events; ++i) {
        ds->offset_array[i] = time(NULL); // current timestamp

        ds->key_array[i] = rand(); // Random integer key

        ds->events[i].timestamp = time(NULL); // Current time as timestamp
        ds->events[i].event_type = random_char_range('A', 'Z'); // Random event type
        ds->events[i].event_id = random_uint_range(1, 10000); // Random event ID in range [1, 10000]
    }

    return NULL;
}

void resize_event_array(DataStructures* ds, size_t new_size) {
    pthread_mutex_lock(&ds->lock);

    Event* temp_events = realloc(ds->events, new_size * sizeof(Event));

    if (!temp_events) {
        perror("Failed to resize event array");
        free_memory(ds);
        pthread_mutex_unlock(&ds->lock);
        return;
    }

    ds->events = temp_events;

    // Initialize newly added elements
    for (size_t i = ds->num_events; i < new_size; ++i) {
        ds->events[i].timestamp = time(NULL);
        ds->events[i].event_type = random_char_range('A', 'Z');
        ds->events[i].event_id = random_uint_range(1, 10000);
    }

    ds->num_events = new_size;
    pthread_mutex_unlock(&ds->lock);
}

void cleanup(DataStructures* ds) {
    free_memory(ds);
    pthread_mutex_destroy(&ds->lock);
}
