['Here's a C code snippet implementing the described functionality using POSIX threads and atomic operations for concurrency control:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef enum {
    TASK_PENDING,
    TASK_IN_PROGRESS,
    TASK_COMPLETED
} TaskStatus;

typedef struct Task {
    char name[256];
    int priority;
    TaskStatus status;
    struct Task* next;
} Task;

typedef struct {
    atomic_int total_tasks;
    atomic_int cumulative_priority;
    Task* head;
    pthread_mutex_t lock;
} TaskCollection;

TaskCollection* create_task_collection() {
    TaskCollection* collection = (TaskCollection*)malloc(sizeof(TaskCollection));
    collection->total_tasks = 0;
    collection->cumulative_priority = 0;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_task(TaskCollection* collection, const char* name, int priority, TaskStatus status) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    strncpy(new_task->name, name, sizeof(new_task->name) - 1);
    new_task->priority = priority;
    new_task->status = status;
    new_task->next = NULL;

    pthread_mutex_lock(&collection->lock);
    new_task->next = collection->head;
    collection->head = new_task;

    atomic_fetch_add_explicit(&collection->total_tasks, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&collection->cumulative_priority, priority, memory_order_relaxed);
    pthread_mutex_unlock(&collection->lock);
}

void print_tasks(TaskCollection* collection) {
    Task* current = collection->head;

    while (current != NULL) {
        printf("Task: %s, Priority: %d, Status: %d\n", 
               current->name, current->priority, current->status);
        current = current->next;
    }
}

void print_summary(TaskCollection* collection) {
    int total_tasks = atomic_load_explicit(&collection->total_tasks, memory_order_relaxed);
    int cumulative_priority = atomic_load_explicit(&collection->cumulative_priority, memory_order_relaxed);

    printf("Total Tasks: %d, Cumulative Priority: %d\n", 
           total_tasks, cumulative_priority);
}

void destroy_task_collection(TaskCollection* collection) {
    Task* current = collection->head;
    while (current != NULL) {
        Task* to_free = current;
        current = current->next;
        free(to_free);
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

This implementation uses a simple mutex for thread safety when modifying the task list, ensuring minimal locking overhead. It also employs atomic operations to track the total number of tasks and their cumulative priority efficiently. This design balances ease of maintenance with performance, suitable for handling up to 100,000 tasks effectively.']

['Here's a C implementation for managing a collection of `transaction` objects with considerations for high throughput, error handling, and extensibility:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TRANSACTIONS 10000

typedef struct {
    long timestamp;
    int transaction_id;
    char *description; // Dynamically allocated string
} Transaction;

// Function to create a new transaction
Transaction* create_transaction(long timestamp, int transaction_id, const char *description) {
    Transaction *transaction = (Transaction *)malloc(sizeof(Transaction));
    if (!transaction) {
        perror("Failed to allocate memory for transaction");
        return NULL;
    }

    transaction->timestamp = timestamp;
    transaction->transaction_id = transaction_id;

    // Allocate memory for description
    transaction->description = strdup(description);
    if (!transaction->description) {
        fprintf(stderr, "Failed to allocate memory for transaction description\n");
        free(transaction);
        return NULL;
    }

    return transaction;
}

// Function to free a transaction
void free_transaction(Transaction *transaction) {
    if (transaction) {
        free(transaction->description);
        free(transaction);
    }
}

// Array of transactions and its size
Transaction *transactions[MAX_TRANSACTIONS];
size_t num_transactions = 0;

// Add a transaction to the collection
int add_transaction(Transaction *transaction) {
    if (!transaction || num_transactions >= MAX_TRANSACTIONS) {
        return -1;
    }

    transactions[num_transactions++] = transaction;
    return 0;
}

// Iterate and print all transactions
void print_all_transactions() {
    for (size_t i = 0; i < num_transactions; ++i) {
        Transaction *transaction = transactions[i];
        printf("Timestamp: %ld, ID: %d, Description: %s\n",
               transaction->timestamp,
               transaction->transaction_id,
               transaction->description);
    }
}

// Free all transactions
void free_all_transactions() {
    for (size_t i = 0; i < num_transactions; ++i) {
        free_transaction(transactions[i]);
    }
    num_transactions = 0;
}

int main() {
    // Example usage
    Transaction *tx1 = create_transaction(1627849200, 101, "Transaction one");
    if (tx1) add_transaction(tx1);

    Transaction *tx2 = create_transaction(1627849300, 102, "Transaction two");
    if (tx2) add_transaction(tx2);

    print_all_transactions();

    free_all_transactions();
    return 0;
}
```

