#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>
#include <arpa/nameser.h>
#include <resolv.h>

#define MAX_TRANSACTIONS 10000

typedef struct {
    struct timeval timestamp;
    unsigned long transaction_id;
    char *description; // Interned strings managed by a custom memory pool
} Transaction;

// Memory pool for efficient string allocation
typedef struct {
    size_t block_size;
    char *memory_pool;
    size_t current_offset;
    pthread_mutex_t lock;
} StringPool;

void initialize_string_pool(StringPool *pool, size_t initial_size) {
    pool->block_size = initial_size;
    pool->current_offset = 0;
    pool->lock = (pthread_mutex_t){0};
    pthread_mutex_init(&pool->lock, NULL);
    pool->memory_pool = malloc(pool->block_size);
}

char* allocate_string_from_pool(StringPool *pool, const char *str) {
    size_t len = strlen(str) + 1;
    pthread_mutex_lock(&pool->lock);

    if (pool->current_offset + len > pool->block_size) {
        void *new_memory = realloc(pool->memory_pool, pool->block_size * 2);
        if (!new_memory) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->memory_pool = new_memory;
        pool->block_size *= 2;
    }

    char *result = (char*)pool->memory_pool + pool->current_offset;
    memcpy(result, str, len);
    pool->current_offset += len;

    pthread_mutex_unlock(&pool->lock);
    return result;
}

void free_string_pool(StringPool *pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
}

// DNS resolution function
int resolve_hostname(const char *hostname, struct in_addr *ip_address) {
    int err;
    struct hostent *he = gethostbyname2(hostname, AF_INET);
    if (he == NULL) {
        herror("DNS resolution failed");
        return -1;
    }
    memcpy(ip_address, he->h_addr_list[0], sizeof(struct in_addr));
    return 0;
}

// Transaction processing function
void process_transactions(Transaction *transactions, size_t num_transactions, StringPool *string_pool) {
    for (size_t i = 0; i < num_transactions; ++i) {
        // Resolve hostname before processing the transaction
        struct in_addr ip_address;
        if (resolve_hostname(transactions[i].description, &ip_address) == -1) {
            fprintf(stderr, "Failed to resolve hostname: %s\n", transactions[i].description);
            continue;
        }

        // Process transaction...
        printf("Transaction ID: %lu, Description resolved IP: %s\n",
               transactions[i].transaction_id,
               inet_ntoa(ip_address));

        // Free string from pool if needed
    }
}

// Main function to handle high-throughput transaction processing
void manage_transaction_system() {
    StringPool string_pool;
    initialize_string_pool(&string_pool, 1024 * 1024); // Initialize with 1MB

    Transaction transactions[MAX_TRANSACTIONS];
    for (unsigned long i = 0; i < MAX_TRANSACTIONS; ++i) {
        gettimeofday(&transactions[i].timestamp, NULL);
        transactions[i].transaction_id = i;

        char desc[256];
        snprintf(desc, sizeof(desc), "Transaction %lu", i);
        transactions[i].description = allocate_string_from_pool(&string_pool, desc);

        if (!transactions[i].description) {
            fprintf(stderr, "Failed to allocate string for transaction ID: %lu\n", i);
            break;
        }
    }

    process_transactions(transactions, MAX_TRANSACTIONS, &string_pool);
    free_string_pool(&string_pool);
}

int main() {
    manage_transaction_system();
    return 0;
}
```

This code defines a high-throughput transaction processing system in C. It uses a custom memory pool to efficiently allocate strings for transaction descriptions and resolves hostnames via DNS during transaction processing. The design is modular, allowing for easy extension and integration with additional data sources or pipelines.']

