namespace EventFramework {

    enum TemporalGranularity { MICROSECONDLY, MILLISECONDLY, SECONDLY };

    class Event {
    public:
        std::string data;
        long timestamp; // Unix time in microseconds

        Event(const std::string& d, long t) : data(d), timestamp(t) {}
    };

    class ProcessingConfig {
    public:
        TemporalGranularity granularity;

        ProcessingConfig(TemporalGranularity g = SECONDLY) : granularity(g) {}

        void updateGranularity(TemporalGranularity newGranularity) {
            granularity = newGranularity;
        }
    };

    class EventProcessor {
    private:
        static std::unique_ptr<ProcessingConfig> configInstance;
        std::unordered_map<std::string, std::function<void(Event&)>> filters;
        std::unordered_map<std::string, std::function<Event*(Event*)>> transformers;

    public:
        EventProcessor() {}
        ~EventProcessor() {}

        static ProcessingConfig* getConfig() {
            if (!configInstance) {
                configInstance = std::make_unique<ProcessingConfig>();
            }
            return configInstance.get();
        }

        void addFilter(const std::string& filterName, std::function<void(Event&)> filterFunc) {
            filters[filterName] = filterFunc;
        }

        void addTransformer(const std::string& transformerName, std::function<Event*(Event*)> transformFunc) {
            transformers[transformerName] = transformFunc;
        }

        void processEvents(std::vector<Event>& events) {
            for (auto& event : events) {
                // Apply filters
                for (const auto& [name, filterFunc] : filters) {
                    filterFunc(event);
                }

                // Transform the event if necessary
                for (const auto& [name, transformFunc] : transformers) {
                    Event* transformedEvent = transformFunc(&event);
                    if (transformedEvent != nullptr) {
                        event = *transformedEvent;
                        delete transformedEvent;
                    }
                }

                // Simulate processing (e.g., sending to a data warehouse)
                std::cout << "Processed Event: " << event.data << ", Timestamp: " 
                          << event.timestamp << "\n";
            }
        }
    };

    std::unique_ptr<ProcessingConfig> EventProcessor::configInstance = nullptr;
}

int main() {
    using namespace EventFramework;

    // Create an instance of EventProcessor
    EventProcessor processor;

    // Add a filter to discard events with specific data (for demonstration)
    processor.addFilter("discardEmpty", [](Event& event) {
        if (event.data.empty()) {
            throw std::runtime_error("Filtered out empty event.");
        }
    });

    // Add a transformer to append "_processed" to event data
    processor.addTransformer("appendProcessedTag", [](Event* event) -> Event* {
        event->data += "_processed";
        return event;
    });

    // Simulate a stream of events
    std::vector<Event> events = { Event("event1", 1625078400000000), 
                                  Event("", 1625078401000000), 
                                  Event("event2", 1625078402000000) };

    try {
        processor.processEvents(events);
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
    }

    return 0;
}
