    private static final String ERROR_MESSAGE = "Invalid content";
    private static final int MAX_CONTENT_LENGTH = 1024;
    private static final long TTL_SECONDS = 3600; // 1 hour
    private static final int REQUESTS_PER_MINUTE_LIMIT = 1000;

    private final ScheduledExecutorService rateLimiterExecutor;
    private final ThreadPoolExecutor threadPoolExecutor;
    private final ConcurrentHashMap<String, Long> requestCounts;

    public ContentProcessor() {
        this.rateLimiterExecutor = Executors.newScheduledThreadPool(1);
        this.threadPoolExecutor = (ThreadPoolExecutor) Executors.newFixedThreadPool(10);
        this.requestCounts = new ConcurrentHashMap<>();

        // Schedule rate limiting
        rateLimiterExecutor.scheduleAtFixedRate(this::resetRequestCount, 60, 60, TimeUnit.SECONDS);
    }

    public String processContent(String content, String ipAddress) {
        if (content == null || content.isEmpty()) {
            logAuditEvent("Null or empty content received.");
            return ERROR_MESSAGE;
