        if (requestCounts.get(ipAddress) > REQUESTS_PER_MINUTE_LIMIT) {
            return false;
        }

        return true;
    }

    private void resetRequestCount() {
        requestCounts.clear();
    }

    private String getExternalServiceHash(String content) throws Exception {
        // Simulate external service integration
        boolean isPrimaryServiceAvailable = checkPrimaryServiceAvailability();

        if (isPrimaryServiceAvailable) {
            try {
                return callExternalService(content);
            } catch (Exception e) {
                logger.log(Level.WARNING, "External service failed, using backup.", e);
            }
        }

        // Fallback to backup service
        boolean isBackupServiceAvailable = checkBackupServiceAvailability();

        if (isBackupServiceAvailable) {
            try {
                return callBackupService(content);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Both primary and backup services failed.", e);
