#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define MAX_MEMORY_SIZE 1024 * 1024 // 1 MB limit for simplicity
#define RECORD_COUNT 1000
#define MIN_VALUE -1000
#define MAX_VALUE 1000

// Example character set for password generation
const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Helper function prototypes
char* generate_random_string(int length);
int hash_password(const char *password);

// Function to dynamically manage memory for records
uint8_t* create_records(size_t max_memory, size_t record_count) {
    if (max_memory < sizeof(Record) * record_count) {
        fprintf(stderr, "Insufficient memory allocation requested.\n");
        return NULL;
    }

    // Seed the random number generator with current time
    srand((unsigned int)time(NULL));

    Record *records = malloc(record_count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    uint8_t *byte_array = malloc(max_memory);
    if (!byte_array) {
        perror("Failed to allocate memory for byte array");
        free(records);
        return NULL;
    }

    size_t total_bytes_written = 0;

    for (size_t i = 0; i < record_count; ++i) {
        // Generate a random string of variable length
        int password_length = rand() % 20 + 5; // Random length between 5 and 25
        char *password = generate_random_string(password_length);

        if (!password) {
            fprintf(stderr, "Failed to generate password.\n");
            free(records);
            free(byte_array);
            return NULL;
        }

        // Hash the generated password to obtain an integer key
        records[i].key = hash_password(password);

        // Assign a random offset and value within specified range
        records[i].offset = rand() % 1000000; // Example offset
        records[i].value = MIN_VALUE + (rand() % (MAX_VALUE - MIN_VALUE + 1));

        free(password);

        // Serialize record into byte array
        if (total_bytes_written + sizeof(Record) > max_memory) {
            fprintf(stderr, "Serialization would exceed maximum memory limit.\n");
            free(records);
            free(byte_array);
            return NULL;
        }

        memcpy(byte_array + total_bytes_written, &records[i], sizeof(Record));
        total_bytes_written += sizeof(Record);

        // Ensure endianness is handled appropriately
#ifdef __BYTE_ORDER__
#if (__BYTE_ORDER__ == __ORDER_BIG_ENDIAN__)
        records[i].key = htonl(records[i].key);
        records[i].offset = htobe64(records[i].offset);
#endif
#endif
    }

    printf("Successfully serialized %zu records.\n", record_count);

    free(records); // Clean up the memory after serialization

    return byte_array;
}

// Function to deserialize the byte array back into records
Record* deserialize_records(const uint8_t *byte_array, size_t total_bytes) {
    size_t record_count = total_bytes / sizeof(Record);
    Record *records = malloc(record_count * sizeof(Record));

    if (!records) {
        perror("Failed to allocate memory for deserialized records");
        return NULL;
    }

    memcpy(records, byte_array, total_bytes);

#ifdef __BYTE_ORDER__
#if (__BYTE_ORDER__ == __ORDER_BIG_ENDIAN__)
    for (size_t i = 0; i < record_count; ++i) {
        records[i].key = ntohl(records[i].key);
        records[i].offset = be64toh(records[i].offset);
    }
#endif
#endif

    return records;
}

char* generate_random_string(int length) {
    char *password = malloc(length + 1);
    if (!password) {
        perror("Failed to allocate memory for password");
        return NULL;
    }

    for (int i = 0; i < length; ++i) {
        password[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    password[length] = '\0';

    return password;
}

int hash_password(const char *password) {
    // Simple hash function example
    int hash = 0;
    for (size_t i = 0; i < strlen(password); ++i) {
        hash += password[i];
    }
    return abs(hash);
}

// Example usage
int main() {
    size_t max_memory = MAX_MEMORY_SIZE;

    uint8_t *serialized_data = create_records(max_memory, RECORD_COUNT);
    if (!serialized_data) {
        fprintf(stderr, "Failed to serialize records.\n");
        return EXIT_FAILURE;
    }

    Record *deserialized_records = deserialize_records(serialized_data, max_memory);
    if (!deserialized_records) {
        fprintf(stderr, "Failed to deserialize records.\n");
        free(serialized_data);
        return EXIT_FAILURE;
    }

    // Use deserialized data...

    free(deserialized_records);
    free(serialized_data);

    return EXIT_SUCCESS;
}
