#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MEMORY_LIMIT 1024 * 1024 // Adjust as needed

typedef struct {
    int value;
    char *key;
} Record;

// Comparator function for qsort
int compare_int(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

Record* create_records(int max_records, int range_min, int range_max, int ensure_unique_values, int *created_count) {
    if (max_records <= 0 || created_count == NULL) {
        *created_count = 0;
        return NULL;
    }

    // Allocate initial memory
    Record *records = malloc(max_records * sizeof(Record));
    if (!records) {
        *created_count = 0;
        return NULL;
    }

    int used_memory = max_records * sizeof(Record);
    int key_base_size = sizeof("keyX") - 1; // "keyX" without null terminator

    srand(time(NULL)); // Seed for random number generation
    int current_index = 0;

    for (int i = 0; i < max_records; ++i) {
        if (used_memory + key_base_size > MEMORY_LIMIT) break;

        records[i].value = rand() % (range_max - range_min + 1) + range_min;

        // Ensure unique values if required
        if (ensure_unique_values && i > 0) {
            int *values_array = malloc(i * sizeof(int));
            for (int j = 0; j < i; ++j) {
                values_array[j] = records[j].value;
            }
            qsort(values_array, i, sizeof(int), compare_int);

            if (i > 1 && values_array[i - 1] == values_array[i - 2]) {
                free(values_array);
                continue; // Retry with a new random value
            }

            free(values_array);
        }

        char *key = malloc(key_base_size + 1); // +1 for null terminator
        if (!key) {
            break; // Failed to allocate memory, exit loop
        }

        snprintf(key, key_base_size + 1, "key%d", i);
        records[i].key = key;

        used_memory += strlen(key) + 1;

        int is_duplicate_key = 0;
        for (int j = 0; j < current_index; ++j) {
            if (strcmp(records[j].key, key) == 0) {
                free(key);
                is_duplicate_key = 1;
                break;
            }
        }

        if (!is_duplicate_key) {
            records[current_index] = records[i];
            current_index++;
        } else {
            free(key); // Free duplicate key
        }
    }

    *created_count = current_index;

    Record *result_records = malloc(current_index * sizeof(Record));
    if (result_records && current_index > 0) {
        memcpy(result_records, records, current_index * sizeof(Record));

        for (int i = 0; i < current_index; ++i) {
            result_records[i].key = strdup(records[i].key);
        }
    } else if (records) {
        free(records);
    }

    return result_records;
}

void free_records(Record *records, int count) {
    if (!records) return;

    for (int i = 0; i < count; ++i) {
        free(records[i].key);
    }

    free(records);
}

// Example of iterating over records
void iterate_and_print(Record *records, int count) {
    if (!records || count <= 0) return;

    for (int i = 0; i < count; ++i) {
        printf("Record %d: Value = %d, Key = %s\n", i, records[i].value, records[i].key);
    }
}

// Usage example
int main() {
    int created_count;
    Record *records = create_records(100, 1, 1000, 1, &created_count);

    if (records) {
        iterate_and_print(records, created_count);
        free_records(records, created_count);
    } else {
        printf("Failed to allocate memory for records.\n");
    }

    return 0;
}
```

This code defines a C function that manages a collection of records with integer values and dynamically allocated string keys. It handles memory allocation within a specified limit, ensures unique values if required, prevents key duplication, provides iteration functionality, and frees all resources at the end.']

['Below is a C implementation for managing dynamic memory allocation and lifecycle for two distinct data structures: an array of `offset` long integers, an array of `key` integers, and an array of `record` structures. The code ensures thread-safe access using mutexes and integrates with a logging framework.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Global variables for managing dynamic arrays and synchronization
long *offsets = NULL;
int *keys = NULL;
Record *records = NULL;
size_t offset_count = 0, key_count = 0, record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_data(size_t offset_size, size_t key_size, long offset_min, long offset_max, int value_min, int value_max);
void resize_records(size_t new_size);
void free_resources();
void log_message(const char *format, ...);

#define LOG(format, ...) do { \
    va_list args; \
    va_start(args, format); \
    vprintf("LOG: " format "\n", args); \
    va_end(args); \
} while (0)

// Function to initialize data
void initialize_data(size_t offset_size, size_t key_size, long offset_min, long offset_max, int value_min, int value_max) {
    pthread_mutex_lock(&mutex);

    // Allocate and initialize offsets with random values
    offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        log_message("Failed to allocate memory for offsets.");
        exit(EXIT_FAILURE);
    }
    offset_count = offset_size;
    srand(time(NULL));
    for (size_t i = 0; i < offset_count; ++i) {
        offsets[i] = offset_min + rand() % (offset_max - offset_min + 1);
    }

    // Allocate and initialize keys
    keys = malloc(key_size * sizeof(int));
    if (!keys) {
        log_message("Failed to allocate memory for keys.");
        free(offsets);
        exit(EXIT_FAILURE);
    }
    key_count = key_size;
    for (size_t i = 0; i < key_count; ++i) {
        keys[i] = rand() % 100; // Example initialization
    }

    // Allocate and initialize records with random values
    resize_records(10); // Initial size of 10 records
    record_count = 10;
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = value_min + rand() % (value_max - value_min + 1);
    }

    pthread_mutex_unlock(&mutex);
}

// Function to resize the records array
void resize_records(size_t new_size) {
    if (new_size <= record_count) return;

    Record *temp = realloc(records, new_size * sizeof(Record));
    if (!temp) {
        log_message("Failed to reallocate memory for records.");
        free_resources();
        exit(EXIT_FAILURE);
    }
    records = temp;

    // Initialize new elements
    for (size_t i = record_count; i < new_size; ++i) {
        records[i].value = rand() % 100; // Example initialization
    }

    log_message("Resized records array to size: %zu", new_size);
}

// Function to free allocated resources
void free_resources() {
    pthread_mutex_lock(&mutex);

    if (offsets) {
        free(offsets);
        offsets = NULL;
    }
    if (keys) {
        free(keys);
        keys = NULL;
    }
    if (records) {
        free(records);
        records = NULL;
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    initialize_data(100, 50, 0, 1000, -50, 50);

    // Example of resizing and accessing the data safely
    resize_records(200);

    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&mutex);
        printf("Record %zu: %d\n", i, records[i].value);
        pthread_mutex_unlock(&mutex);
    }

    free_resources();
    return 0;
}
