void manage_memory(size_t offset_array_size) {
    if (offset_array_size == 0 || offset_array_size > SIZE_MAX / sizeof(long)) {
        LOG_ERROR("Invalid offset array size");
        return;
    }

    long *offsets = NULL;
    int keys_count = offset_array_size / 2;

    // Handle potential integer overflow when calculating memory requirements
    if (keys_count < 0 || keys_count * sizeof(int) > SIZE_MAX - sizeof(long) * offset_array_size) {
        LOG_ERROR("Integer overflow in key array size calculation");
        return;
    }

    int *keys = NULL;
    size_t record_count = offset_array_size / 2;

    // Allocate and check memory for long array
    offsets = (long *)malloc(sizeof(long) * offset_array_size);
    if (!offsets) {
        LOG_ERROR("Failed to allocate memory for offset array");
        return;
    }
    memset(offsets, 0, sizeof(long) * offset_array_size);

    // Allocate and check memory for int keys array
    keys = (int *)malloc(sizeof(int) * keys_count);
    if (!keys) {
        free(offsets);
        LOG_ERROR("Failed to allocate memory for keys array");
        return;
    }
    memset(keys, 0, sizeof(int) * keys_count);

    // Allocate and check memory for records array with alignment
    size_t record_size = sizeof(record);
    char *aligned_memory = NULL;

