    aligned_memory = (char *)valloc(record_count * record_size);
#else
    int res = posix_memalign((void **)&aligned_memory, 64, record_count * record_size);
    if (res != 0) {
        free(offsets);
        free(keys);
        LOG_ERROR("Failed to allocate aligned memory for records");
        return;
    }
#endif

    if (!aligned_memory) {
        free(offsets);
        free(keys);
        LOG_ERROR("Failed to allocate memory for records array");
        return;
    }

    record *records = (record *)aligned_memory;

    // Initialize random seed with external data source
    int random_seed = get_random_seed();
    if (random_seed <= 0) {
        LOG_ERROR("Invalid random seed received from the data source");
        free(offsets);
        free(keys);
#if defined(__APPLE__)
        free(aligned_memory);
#else
        free((void *)aligned_memory);
#endif
        return;
    }

    srand(random_seed);

    // Set each record's int field to a random value within a range
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % 100; // Random value between 0 and 99
    }

    LOG_INFO("Memory allocated and initialized successfully");

    // Free all memory before returning to prevent leaks
    free(offsets);
    free(keys);

#if defined(__APPLE__)
    free(aligned_memory);
#else
    free((void *)aligned_memory);
#endif

    LOG_INFO("All resources have been deallocated");
}
