    Record* records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -3;
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i].randomInt = rand() % (RANDOM_INT_RANGE[1] - RANDOM_INT_RANGE[0]) + RANDOM_INT_RANGE[0];

        char* randStr = records[i].randomString;
        for (int j = 0; j < STRING_LENGTH; ++j) {
            randStr[j] = CHAR_SET[rand() % strlen(CHAR_SET)];
        }
        randStr[STRING_LENGTH] = '\0';
    }

