    pthread_mutex_t events_mutex;

    Record *records;
    int record_count;
    int record_capacity;
    int ensure_unique_keys;

    // Lock for records
    pthread_mutex_t records_mutex;
} CollectionManager;

// Utility functions

void free_record(Record *record) {
    if (record->key != NULL) {
        free(record->key);
    }
}

void free_records(CollectionManager *manager) {
    pthread_mutex_lock(&manager->records_mutex);

    for (int i = 0; i < manager->record_count; ++i) {
        free_record(&manager->records[i]);
    }

    if (manager->records != NULL) {
        free(manager->records);
    }

    pthread_mutex_unlock(&manager->records_mutex);
}

void double_event_capacity(CollectionManager *manager) {
    pthread_mutex_lock(&manager->events_mutex);

    size_t new_capacity = manager->event_capacity * 2;
    Event *new_events = (Event *)malloc(new_capacity * sizeof(Event));

    if (!new_events) {
        log_info("Failed to allocate memory for resizing events.");
        return;
    }

    memcpy(new_events, manager->events, manager->event_count * sizeof(Event));

    free(manager->events);
    manager->events = new_events;
    manager->event_capacity = new_capacity;

    pthread_mutex_unlock(&manager->events_mutex);
}

// Initialization and population

void initialize_manager(CollectionManager *manager, int initial_record_count) {
    manager->events = (Event *)malloc(INITIAL_EVENT_SIZE * sizeof(Event));
    if (!manager->events) {
        log_info("Failed to allocate memory for events.");
        return;
    }

    manager->event_capacity = INITIAL_EVENT_SIZE;
    manager->event_count = 0;

    pthread_mutex_init(&manager->events_mutex, NULL);

    // Initialize records
    manager->record_capacity = initial_record_count;
    manager->records = (Record *)malloc(manager->record_capacity * sizeof(Record));

    if (!manager->records) {
        log_info("Failed to allocate memory for records.");
        return;
    }

    pthread_mutex_init(&manager->records_mutex, NULL);
    manager->record_count = 0;

    // Initialize random number generator
    srand(time(NULL));
}

void populate_manager(CollectionManager *manager, int value_range_min, int value_range_max) {
    int unique_keys[manager->record_capacity];
    memset(unique_keys, -1, sizeof(int) * manager->record_capacity);

    for (int i = 0; i < manager->record_count; ++i) {
        Record *record = &manager->records[i];

        record->value = rand() % (value_range_max - value_range_min + 1) + value_range_min;

        if (manager->ensure_unique_keys) {
            int key_value;
            do {
                key_value = rand() % manager->record_capacity;
            } while(unique_keys[key_value] != -1);

            unique_keys[key_value] = i;
            record->key = strdup("Key");
            snprintf(record->key, KEY_MAX_LENGTH, "Unique_Key_%d", key_value);
        } else {
            record->key = strdup("GenericKey");
        }
    }

    // Populate events
    for (int i = 0; i < manager->event_count; ++i) {
        Event *event = &manager->events[i];

        event->timestamp = time(NULL);
        event->event_type = 'A' + rand() % 26;
        event->event_id = rand();
    }
}

// Dynamic resizing

void add_event(CollectionManager *manager, long timestamp, char event_type, unsigned int event_id) {
    pthread_mutex_lock(&manager->events_mutex);

    if (manager->event_count == manager->event_capacity) {
        double_event_capacity(manager);
    }

    Event *event = &manager->events[manager->event_count++];

    event->timestamp = timestamp;
    event->event_type = event_type;
    event->event_id = event_id;

    pthread_mutex_unlock(&manager->events_mutex);
}

// Concurrency and resource management

void free_manager(CollectionManager *manager) {
    free_events(manager);
    free_records(manager);

    if (manager->events != NULL) {
        free(manager->events);
    }

    pthread_mutex_destroy(&manager->events_mutex);
    pthread_mutex_destroy(&manager->records_mutex);
}

// Main function to demonstrate usage

int main() {
    CollectionManager manager;

    initialize_manager(&manager, 10);
    populate_manager(&manager, 1, 100);

    // Add a new event
    add_event(&manager, time(NULL), 'E', 42);

    // Clean up resources
    free_manager(&manager);

    return 0;
}
