#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    double sensor_reading;
    char event_type;
} event_record;

typedef struct {
    event_record *events;
    size_t count;
    size_t capacity;
    size_t max_memory_budget;
    pthread_mutex_t lock;
    double sensor_range_min;
    double sensor_range_max;
} event_manager;

double thread_safe_random(double min, double max) {
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    static pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_once(&once, []() {
        srand((unsigned int)time(NULL));
    });

    pthread_mutex_lock(&rand_lock);
    double random_value = ((double)rand() / RAND_MAX) * (max - min) + min;
    pthread_mutex_unlock(&rand_lock);

    return random_value;
}

int add_event(event_manager *manager, char event_type) {
    pthread_mutex_lock(&manager->lock);

    size_t new_size = sizeof(event_record) * (manager->count + 1);
    if ((new_size * sizeof(event_record)) > manager->max_memory_budget) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    if (new_size > manager->capacity * sizeof(event_record)) {
        size_t new_capacity = manager->capacity * 2;
        event_record *temp_events = realloc(manager->events, new_capacity * sizeof(event_record));
        if (!temp_events) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->events = temp_events;
        manager->capacity = new_capacity;
    }

    event_record new_event;
    new_event.timestamp = time(NULL);
    new_event.sensor_reading = thread_safe_random(manager->sensor_range_min, manager->sensor_range_max);
    new_event.event_type = event_type;

    manager->events[manager->count] = new_event;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int serialize_events(event_manager *manager, uint8_t **buffer) {
    pthread_mutex_lock(&manager->lock);

    size_t header_size = sizeof(size_t) + sizeof(size_t) + sizeof(double) * 2;
    size_t event_data_size = manager->count * sizeof(event_record);
    size_t total_size = header_size + event_data_size;

    uint8_t *temp_buffer = malloc(total_size);
    if (!temp_buffer) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t *num_events_ptr = (size_t *)temp_buffer;
    *num_events_ptr = manager->count;

    size_t *max_size_used_ptr = num_events_ptr + 1;
    *max_size_used_ptr = total_size;

    double *sensor_range_min_ptr = (double *)(max_size_used_ptr + 1);
    *sensor_range_min_ptr = manager->sensor_range_min;

    double *sensor_range_max_ptr = sensor_range_min_ptr + 1;
    *sensor_range_max_ptr = manager->sensor_range_max;

    event_record *event_data_start = (event_record *)(sensor_range_max_ptr + 1);
    for (size_t i = 0; i < manager->count; ++i) {
        event_data_start[i] = manager->events[i];
    }

    *buffer = temp_buffer;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_event_manager(event_manager *manager, uint8_t *serialized_data) {
    if (manager->events) {
        free(manager->events);
    }
    pthread_mutex_destroy(&manager->lock);

    if (serialized_data) {
        free(serialized_data);
    }

    free(manager);
}

event_manager* create_event_manager(size_t max_memory_budget, double sensor_range_min, double sensor_range_max) {
    event_manager *manager = malloc(sizeof(event_manager));
    manager->events = NULL;
    manager->count = 0;
    manager->capacity = 0;
    manager->max_memory_budget = max_memory_budget;
    pthread_mutex_init(&manager->lock, NULL);
    manager->sensor_range_min = sensor_range_min;
    manager->sensor_range_max = sensor_range_max;
    return manager;
}

int main() {
    size_t max_memory = 1024 * 1024; // 1 MB
    double min_reading = 0.0;
    double max_reading = 100.0;

    event_manager *manager = create_event_manager(max_memory, min_reading, max_reading);

    for (int i = 0; i < 10; ++i) {
        if (add_event(manager, 'A') != 0) {
            fprintf(stderr, "Failed to add event %d\n", i);
            break;
        }
    }

    uint8_t *serialized_data = NULL;
    if (serialize_events(manager, &serialized_data) == 0) {
        // Use serialized_data...
        free(serialized_data);
    }

    free_event_manager(manager, NULL);

    return 0;
}
