#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <arpa/inet.h>

#define MAX_MEMORY_LIMIT 1048576 // Example max size limit for memory allocation (1MB)
#define HASH_MAP_SIZE 1024

typedef struct {
    time_t timestamp;
    unsigned long packet_id;
    size_t size;
    char source_ip[16];
    char destination_ip[16];
    char *payload;
} NetworkPacket;

typedef struct HashMapNode {
    unsigned long id;
    NetworkPacket *packet;
    struct HashMapNode *next;
} HashMapNode;

typedef struct {
    HashMapNode *buckets[HASH_MAP_SIZE];
    pthread_mutex_t lock;
} HashMap;

unsigned long generate_packet_id() {
    static unsigned long last_id = 0;
    return (last_id + 1) % ULONG_MAX;
}

int hash_function(unsigned long id) {
    return id % HASH_MAP_SIZE;
}

void init_hash_map(HashMap *map) {
    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        map->buckets[i] = NULL;
    }
    pthread_mutex_init(&map->lock, NULL);
}

NetworkPacket* create_packet(const char *source_ip, const char *destination_ip, size_t payload_size) {
    NetworkPacket *packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));
    if (!packet) return NULL;

    packet->timestamp = time(NULL);
    packet->packet_id = generate_packet_id();
    packet->size = sizeof(NetworkPacket) + payload_size - sizeof(packet->payload);
    strncpy(packet->source_ip, source_ip, 15);
    packet->source_ip[15] = '\0';
    strncpy(packet->destination_ip, destination_ip, 15);
    packet->destination_ip[15] = '\0';

    packet->payload = (char *)malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    memset(packet->payload, 0, payload_size); // Initialize payload
    return packet;
}

void serialize_packet(const NetworkPacket *packet, unsigned char **buffer, size_t *length) {
    *length = sizeof(*packet) + strlen((const char *)packet->payload);
    *buffer = (unsigned char *)malloc(*length);
    if (!*buffer) return;

    memcpy(*buffer, packet, sizeof(*packet));
    memcpy(*buffer + sizeof(*packet), packet->payload, strlen((const char *)packet->payload));

    // Convert IP addresses to network byte order
    struct in_addr src_ip;
    inet_aton(packet->source_ip, &src_ip);
    struct in_addr dst_ip;
    inet_aton(packet->destination_ip, &dst_ip);

    uint32_t src_ip_net = ntohl(src_ip.s_addr);
    uint32_t dst_ip_net = ntohl(dst_ip.s_addr);

    memcpy(*buffer + offsetof(NetworkPacket, source_ip), &src_ip_net, sizeof(uint32_t));
    memcpy(*buffer + offsetof(NetworkPacket, destination_ip), &dst_ip_net, sizeof(uint32_t));

    // Convert timestamp and packet_id to network byte order
    uint64_t timestamp_net = htonll(packet->timestamp);
    memcpy(*buffer + offsetof(NetworkPacket, timestamp), &timestamp_net, sizeof(timestamp_net));

    uint32_t id_net = htonl(packet->packet_id);
    memcpy(*buffer + offsetof(NetworkPacket, packet_id), &id_net, sizeof(id_net));
}

uint64_t htonll(uint64_t value) {
    if (htonl(0x1) == 0x1) { // Check system endianness
        return ((uint64_t)htonl(value) << 32) | htonl((value >> 32) & 0xFFFFFFFF);
    } else {
        return ((uint64_t)ntohl(value) << 32) | ntohl((value >> 32) & 0xFFFFFFFF);
    }
}

void deserialize_packet(const unsigned char *buffer, size_t length, NetworkPacket *packet) {
    if (length < sizeof(*packet)) return;

    memcpy(packet, buffer, sizeof(*packet));

    // Convert IP addresses from network byte order
    uint32_t src_ip_net;
    memcpy(&src_ip_net, buffer + offsetof(NetworkPacket, source_ip), sizeof(uint32_t));
    struct in_addr src_ip = {ntohl(src_ip_net)};
    inet_ntop(AF_INET, &src_ip, packet->source_ip, sizeof(packet->source_ip));

    uint32_t dst_ip_net;
    memcpy(&dst_ip_net, buffer + offsetof(NetworkPacket, destination_ip), sizeof(uint32_t));
    struct in_addr dst_ip = {ntohl(dst_ip_net)};
    inet_ntop(AF_INET, &dst_ip, packet->destination_ip, sizeof(packet->destination_ip));

    // Convert timestamp and packet_id from network byte order
    uint64_t timestamp_net;
    memcpy(&timestamp_net, buffer + offsetof(NetworkPacket, timestamp), sizeof(timestamp_net));
    packet->timestamp = ntohll(timestamp_net);

    uint32_t id_net;
    memcpy(&id_net, buffer + offsetof(NetworkPacket, packet_id), sizeof(id_net));
    packet->packet_id = ntohl(id_net);
}

uint64_t ntohll(uint64_t value) {
    return htonll(value); // Symmetric function
}

void insert_packet(HashMap *map, NetworkPacket *packet) {
    unsigned long id_hash = hash_function(packet->packet_id);

    HashMapNode *new_node = (HashMapNode *)malloc(sizeof(HashMapNode));
    if (!new_node) return;

    new_node->id = packet->packet_id;
    new_node->packet = packet;
    new_node->next = NULL;

    pthread_mutex_lock(&map->lock);
    HashMapNode **bucket = &map->buckets[id_hash];
    while (*bucket) {
        bucket = &(*bucket)->next;
    }
    *bucket = new_node;
    pthread_mutex_unlock(&map->lock);
}

NetworkPacket* find_packet(HashMap *map, unsigned long id) {
    unsigned long id_hash = hash_function(id);

    pthread_mutex_lock(&map->lock);
    HashMapNode *node = map->buckets[id_hash];
    while (node) {
        if (node->id == id) {
            pthread_mutex_unlock(&map->lock);
            return node->packet;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&map->lock);

    return NULL;
}

void delete_packet(HashMap *map, unsigned long id) {
    unsigned long id_hash = hash_function(id);

    pthread_mutex_lock(&map->lock);
    HashMapNode **bucket = &map->buckets[id_hash];
    while (*bucket) {
        if ((*bucket)->id == id) {
            HashMapNode *to_delete = *bucket;
            *bucket = (*bucket)->next;
            free(to_delete->packet->payload);
            free(to_delete->packet);
            free(to_delete);
            pthread_mutex_unlock(&map->lock);
            return;
        }
        bucket = &(*bucket)->next;
    }
    pthread_mutex_unlock(&map->lock);
}

void calculate_average_packet_size() {
    int n, i;
    size_t *sizes = NULL;
    size_t total_size = 0;

    printf("Enter number of packets: ");
    scanf("%d", &n);

    sizes = (size_t *)malloc(n * sizeof(size_t));
    if (!sizes) return;

    printf("Enter packet sizes:\n");
    for (i = 0; i < n; ++i) {
        scanf("%zu", &sizes[i]);
        total_size += sizes[i];
    }

    double average_size = (double)total_size / n;
    printf("Average packet size: %.2f\n", average_size);

    free(sizes);
}

int main() {
    HashMap map;
    init_hash_map(&map);

    // Example usage
    NetworkPacket *packet1 = create_packet("192.168.0.1", "192.168.0.2", 128);
    if (packet1) insert_packet(&map, packet1);

    unsigned char *serialized_data;
    size_t serialized_length;
    serialize_packet(packet1, &serialized_data, &serialized_length);

    NetworkPacket *deserialized_packet = malloc(sizeof(NetworkPacket));
    deserialize_packet(serialized_data, serialized_length, deserialized_packet);

    calculate_average_packet_size();

    delete_packet(&map, packet1->packet_id);
    free(serialized_data);
    free(deserialized_packet);

    return 0;
}
