#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>
#include <endian.h>
#include <stdint.h>

#define MAX_SIZE 1024 * 1024 // Maximum memory size limit

typedef struct {
    int x;
    int y;
    float z;
} Point;

typedef struct {
    double* doublesArray;
    Point* pointsArray;
    size_t doubleCount;
    size_t pointCount;
} DataArrays;

typedef struct {
    uint8_t* serializedData;
    size_t dataSize;
    pthread_mutex_t mutex;
} SerializationCache;

void error(const char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}

double generateNormalRandom() {
    static const double sqrt12 = sqrt(12.0);
    static int haveSpare = 0;
    double rand1, rand2, random;

    if (haveSpare) {
        haveSpare = 0;
        return rand();
    }

    do {
        rand1 = 2.0 * ((double)rand() / RAND_MAX) - 1.0;
        rand2 = 2.0 * ((double)rand() / RAND_MAX) - 1.0;

        random = rand1*rand1 + rand2*rand2;
    } while (random >= 1.0);

    random = sqrt(-2.0 * log(random) / random) * rand1 * sqrt12;
    haveSpare = 1;
    return random;
}

DataArrays createAndInitializeArrays(size_t doubleCount, size_t pointCount, size_t maxMemorySize) {
    DataArrays dataArrays = {NULL, NULL, doubleCount, pointCount};

    if (doubleCount * sizeof(double) + pointCount * sizeof(Point) > maxMemorySize) {
        error("Exceeded maximum memory allocation limit");
    }

    dataArrays.doublesArray = malloc(doubleCount * sizeof(double));
    if (!dataArrays.doublesArray) error("Failed to allocate memory for doubles array");

    dataArrays.pointsArray = malloc(pointCount * sizeof(Point));
    if (!dataArrays.pointsArray) {
        free(dataArrays.doublesArray);
        error("Failed to allocate memory for points array");
    }

    srand(time(NULL));

    for (size_t i = 0; i < doubleCount; ++i) {
        dataArrays.doublesArray[i] = generateNormalRandom();
    }

    for (size_t i = 0; i < pointCount; ++i) {
        dataArrays.pointsArray[i].x = (int)(generateNormalRandom());
        dataArrays.pointsArray[i].y = (int)(generateNormalRandom());
        dataArrays.pointsArray[i].z = (float)generateNormalRandom();
    }

    return dataArrays;
}

size_t serializeData(const DataArrays* dataArrays, uint8_t** outBuffer) {
    size_t bufferSize = sizeof(double) * dataArrays->doubleCount
                      + sizeof(int) * 2 * dataArrays->pointCount
                      + sizeof(float) * dataArrays->pointCount;

    *outBuffer = malloc(bufferSize);
    if (!*outBuffer) error("Failed to allocate memory for serialized buffer");

    uint8_t* ptr = *outBuffer;
    memcpy(ptr, dataArrays->doublesArray, sizeof(double) * dataArrays->doubleCount);
    ptr += sizeof(double) * dataArrays->doubleCount;

    for (size_t i = 0; i < dataArrays->pointCount; ++i) {
        int x = htobe32(dataArrays->pointsArray[i].x);
        int y = htobe32(dataArrays->pointsArray[i].y);
        float z = htole32(*(float*)&dataArrays->pointsArray[i].z);

        memcpy(ptr, &x, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &y, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &z, sizeof(float));
        ptr += sizeof(float);
    }

    return bufferSize;
}

void deserializeData(const uint8_t* buffer, size_t bufferSize, DataArrays* dataArrays) {
    const uint8_t* ptr = buffer;

    memcpy(dataArrays->doublesArray, ptr, sizeof(double) * dataArrays->doubleCount);
    ptr += sizeof(double) * dataArrays->doubleCount;

    for (size_t i = 0; i < dataArrays->pointCount; ++i) {
        int x = be32toh(*(int*)ptr);
        ptr += sizeof(int);

        int y = be32toh(*(int*)ptr);
        ptr += sizeof(int);

        float z = le32tohf(*(float*)ptr);
        ptr += sizeof(float);

        dataArrays->pointsArray[i].x = x;
        dataArrays->pointsArray[i].y = y;
        memcpy(&dataArrays->pointsArray[i].z, &z, sizeof(float));
    }
}

void freeDataArrays(DataArrays* dataArrays) {
    if (dataArrays->doublesArray) free(dataArrays->doublesArray);
    if (dataArrays->pointsArray) free(dataArrays->pointsArray);
}

SerializationCache createSerializationCache() {
    SerializationCache cache = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
    return cache;
}

void storeInCache(SerializationCache* cache, const uint8_t* data, size_t dataSize) {
    pthread_mutex_lock(&cache->mutex);

    free(cache->serializedData);
    cache->serializedData = malloc(dataSize);
    if (!cache->serializedData) error("Failed to allocate memory for serialization cache");

    memcpy(cache->serializedData, data, dataSize);
    cache->dataSize = dataSize;

    pthread_mutex_unlock(&cache->mutex);
}

void retrieveFromCache(SerializationCache* cache, uint8_t** outBuffer, size_t* outBufferSize) {
    pthread_mutex_lock(&cache->mutex);

    *outBuffer = malloc(cache->dataSize);
    if (!*outBuffer) error("Failed to allocate memory for retrieval from cache");

    memcpy(*outBuffer, cache->serializedData, cache->dataSize);
    *outBufferSize = cache->dataSize;

    pthread_mutex_unlock(&cache->mutex);
}

void freeSerializationCache(SerializationCache* cache) {
    pthread_mutex_lock(&cache->mutex);

    free(cache->serializedData);
    cache->serializedData = NULL;
    cache->dataSize = 0;

    pthread_mutex_unlock(&cache->mutex);
}

// Placeholder function for compression and decompression
size_t compressData(const uint8_t* data, size_t dataSize, uint8_t** outCompressedData) {
    // Implement compression logic here
    *outCompressedData = malloc(dataSize); // Dummy allocation
