#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <inttypes.h>
#include <endian.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} severity;

typedef struct {
    time_t timestamp;
    char *message;
    severity level;
    uint64_t id;
    uint32_t hash;  // For storing the hashed ID
} log_entry;

// Function to initialize a random seed with high-resolution clock
void init_random_seed() {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        srand((unsigned int)(ts.tv_nsec ^ ts.tv_sec));
    }
}

// Hash function for log entry ID using a simple hash algorithm for demonstration
uint32_t hash_id(uint64_t id) {
    // Placeholder hash logic; use secure hash in production (e.g., SHA256)
    uint32_t hash = 5381;
    for (int i = 0; i < sizeof(id); ++i) {
        hash = ((hash << 5) + hash) + ((uint8_t*)&id)[i];
    }
    return hash;
}

// Serialize a log_entry into a byte array
size_t serialize_log_entry(const log_entry *entry, uint8_t **buffer) {
    size_t offset = 0;

    // Allocate buffer for serialized data
    *buffer = malloc(sizeof(time_t) + sizeof(uint64_t) + strlen(entry->message) + 1 +
                     sizeof(severity) + sizeof(uint32_t));
    if (*buffer == NULL) return 0;  // Allocation failure

    uint8_t *buf = *buffer;

    // Serialize timestamp (little-endian)
    memcpy(buf, &entry->timestamp, sizeof(time_t));
    offset += sizeof(time_t);

    // Serialize log entry ID (little-endian)
    memcpy(buf + offset, &entry->id, sizeof(uint64_t));
    offset += sizeof(uint64_t);

    // Serialize message length and message
    size_t msg_len = strlen(entry->message) + 1;
    memcpy(buf + offset, &msg_len, sizeof(size_t));  // Include null terminator in length
    offset += sizeof(size_t);
    memcpy(buf + offset, entry->message, msg_len);
    offset += msg_len;

    // Serialize severity level (little-endian)
    uint8_t severity_val = entry->level;
    memcpy(buf + offset, &severity_val, sizeof(severity));
    offset += sizeof(severity);

    // Serialize hashed ID
    uint32_t hash_value = hash_id(entry->id);
    memcpy(buf + offset, &hash_value, sizeof(uint32_t));

    return offset;  // Return the size of serialized data
}

// Deserialize a byte array back into a log_entry
log_entry* deserialize_log_entry(const uint8_t *buffer, size_t buffer_size) {
    if (buffer_size < sizeof(log_entry)) return NULL;

    log_entry *entry = malloc(sizeof(log_entry));
    if (!entry) return NULL;

    const uint8_t *buf = buffer;

    // Deserialize timestamp
    memcpy(&entry->timestamp, buf, sizeof(time_t));
    buf += sizeof(time_t);

    // Deserialize ID
    memcpy(&entry->id, buf, sizeof(uint64_t));
    buf += sizeof(uint64_t);

    // Deserialize message length and message
    size_t msg_len;
    memcpy(&msg_len, buf, sizeof(size_t));
    buf += sizeof(size_t);
    entry->message = malloc(msg_len);
    if (!entry->message) {
        free(entry);
        return NULL;
    }
    memcpy(entry->message, buf, msg_len);
    buf += msg_len;

    // Deserialize severity
    uint8_t severity_val;
    memcpy(&severity_val, buf, sizeof(severity));
    entry->level = (severity)severity_val;
    buf += sizeof(severity);

    // Ignore hash part for now

    return entry;
}

// Helper function to find the longest message in a stream of log entries
void print_longest_message() {
    size_t max_len = 0;
    char *longest_msg = NULL;

    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        size_t len = strlen(line) - 1; // Exclude newline
        if (line[len] == '\n') line[len] = '\0';

        if (len > max_len) {
            free(longest_msg);
            longest_msg = strdup(line);
            max_len = len;
        }
    }

    printf("Longest log message: %s\n", longest_msg ? longest_msg : "None");
    free(longest_msg);
}

// Function to generate a random log message of specified length
void generate_random_log_message(char *buffer, size_t length, const char *vocabulary) {
    for (size_t i = 0; i < length - 1; ++i) {
        buffer[i] = vocabulary[rand() % strlen(vocabulary)];
    }
    buffer[length - 1] = '\0';
}

// Main function to manage log entries
log_entry* create_log_entries(size_t max_entries, size_t max_memory) {
    if (max_entries == 0 || max_memory == 0) return NULL;

    init_random_seed();

    log_entry *entries = malloc(max_entries * sizeof(log_entry));
    if (!entries) return NULL;

    size_t current_size = max_entries * sizeof(log_entry);
    for (size_t i = 0; i < max_entries; ++i) {
        entries[i].timestamp = time(NULL);
        entries[i].id = rand(); // Generate a random ID
        entries[i].level = rand() % 5;

        const char *vocabulary = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ";
        size_t msg_len = rand() % 100 + 1;  // Random message length between 1 and 100

        entries[i].message = malloc(msg_len + 1);
        if (!entries[i].message) {
            for (size_t j = 0; j < i; ++j) free(entries[j].message);
            free(entries);
            return NULL;
        }

        generate_random_log_message(entries[i].message, msg_len, vocabulary);

        current_size += strlen(entries[i].message) + 1;

        if (current_size > max_memory) {
            for (size_t j = i; j < max_entries; ++j) free(entries[j].message);
            free(entries);
            return NULL;
        }
    }

    return entries;
}

void free_log_entries(log_entry *entries, size_t count) {
    if (!entries) return;

    for (size_t i = 0; i < count; ++i) {
        free(entries[i].message);
    }
    free(entries);
}
