    if (!serialized) return NULL;

    unsigned char *ptr = serialized;
    for (int i = 0; i < count; ++i) {
        // Serialize int value
        memcpy(ptr, &records[i].value, sizeof(int));
        ptr += sizeof(int);

        // Serialize long offset
        memcpy(ptr, &records[i].offset, sizeof(long));
        ptr += sizeof(long);

        // Serialize label length and content
        size_t label_len = records[i].label ? strlen(records[i].label) + 1 : 0;
        if (label_len > 255) return NULL; // Invalid label length

        *ptr++ = (unsigned char)label_len;

        if (label_len > 0) {
