typedef struct {
    int value;
    long offset;
    unsigned char deprecated : 1; // Bit field to save space for the flag
} record_t;

record_t* allocate_and_initialize_records(size_t max_memory, size_t record_size, int min_val, int max_val, size_t *num_records);
void serialize_records(record_t *records, size_t num_records, uint8_t **buffer, size_t *buffer_size);
int deserialize_record(const uint8_t *buffer, size_t buffer_size, record_t *record_out);
