}

record_t* allocate_and_initialize_records(size_t max_memory, size_t record_size, int min_val, int max_val, size_t *num_records) {
    srand(time(NULL));
    *num_records = max_memory / record_size;

    // Check for alignment and padding
    if (max_memory % record_size != 0 || (record_size & (sizeof(long) - 1)) != 0) {
        fprintf(stderr, "Memory constraints not met.\n");
        return NULL;
    }

    record_t *records = (record_t *)malloc(max_memory);
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    int value_set[100] = {0}; // Assuming values are between 1 and 100
    for (size_t i = 0; i < *num_records; ++i) {
        int random_value;
        do {
            random_value = min_val + rand() % (max_val - min_val + 1);
        } while (value_set[random_value - min_val] == 1);

        value_set[random_value - min_val] = 1;

        records[i].value = random_value;
        records[i].offset = (long)i * record_size;
        records[i].deprecated = i % 10 == 0; // Mark every 10th record as deprecated
    }

    return records;
}

void serialize_records(record_t *records, size_t num_records, uint8_t **buffer, size_t *buffer_size) {
    *buffer_size = num_records * sizeof(record_t);
    *buffer = (uint8_t *)malloc(*buffer_size);

    if (!*buffer) {
        perror("Failed to allocate memory for serialization buffer");
        return;
    }

    // Handle endianness
    char endian = ENDIANNESS_CHECK();
    uint8_t *ptr = *buffer;

    for (size_t i = 0; i < num_records; ++i) {
        if (endian == 'B') {
            *(int *)(ptr + sizeof(record_t) - sizeof(int)) = __builtin_bswap32(records[i].value);
            *(long *)(ptr + sizeof(record_t) - sizeof(long)) = __builtin_bswap64(records[i].offset);
        } else {
            memcpy(ptr, &records[i], sizeof(record_t));
        }
        ptr += sizeof(record_t);
    }
}

int deserialize_record(const uint8_t *buffer, size_t buffer_size, record_t *record_out) {
    if (buffer_size < sizeof(record_t)) {
        fprintf(stderr, "Buffer too small to deserialize.\n");
        return -1;
    }

    const char endian = ENDIANNESS_CHECK();
    const uint8_t *ptr = buffer;

    int value;
    long offset;

    if (endian == 'B') {
        value = __builtin_bswap32(*(int *)(ptr + sizeof(record_t) - sizeof(int)));
        offset = __builtin_bswap64(*(long *)(ptr + sizeof(record_t) - sizeof(long)));
    } else {
        memcpy(&value, ptr, sizeof(value));
        memcpy(&offset, ptr + sizeof(int), sizeof(offset));
    }

    record_out->value = value;
    record_out->offset = offset;

    // Assuming deprecated flag is at the end of the struct
    record_out->deprecated = *ptr & 0x01;

    return 0;
}

void free_records(record_t *records) {
    if (records) {
        free(records);
    }
}

void read_and_print_max_integer() {
    int count, num, max = INT_MIN;

    printf("Enter the number of integers: ");
    if (scanf("%d", &count) != 1 || count <= 0) {
        fprintf(stderr, "Invalid input.\n");
        return;
    }

    int *numbers = malloc(count * sizeof(int));
    if (!numbers) {
        perror("Failed to allocate memory for numbers");
        return;
    }

    printf("Enter %d integers:\n", count);
    for (int i = 0; i < count; ++i) {
        if (scanf("%d", &num) != 1) {
            fprintf(stderr, "Invalid input.\n");
            free(numbers);
            return;
        }
        numbers[i] = num;
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", max);

    free(numbers);
}
```']

