#define MAX_CONNECTIONS 1000
#define MEMORY_BUDGET 1024 * 1024 // 1 MB

typedef struct {
    char ip_address[16];
    uint16_t port;
    int id;
    int status; // 1 for active, 0 for inactive
} Connection;

typedef struct {
    Connection* connections[MAX_CONNECTIONS];
    size_t count;
    size_t allocated_memory;
    pthread_rwlock_t lock;
    int heartbeat_interval;
    pthread_t monitor_thread;
} ConnectionManager;

ConnectionManager manager = { .connections = {0}, .count = 0, .allocated_memory = 0,
                             .lock = PTHREAD_RWLOCK_INITIALIZER, .heartbeat_interval = 5 };

void init_connection_manager(int interval) {
    pthread_rwlock_init(&manager.lock, NULL);
    manager.heartbeat_interval = interval;
    if (pthread_create(&manager.monitor_thread, NULL, connection_monitor, &manager)) {
        perror("Failed to create monitor thread");
        exit(EXIT_FAILURE);
    }
}

int add_connection(const char* ip_address, uint16_t port) {
    pthread_rwlock_wrlock(&manager.lock);

    size_t new_memory = manager.allocated_memory + sizeof(Connection);
    if (new_memory > MEMORY_BUDGET || manager.count >= MAX_CONNECTIONS) {
        pthread_rwlock_unlock(&manager.lock);
        return -1; // Memory budget exceeded or max connections reached
    }

    Connection* conn = malloc(sizeof(Connection));
    if (!conn) {
        pthread_rwlock_unlock(&manager.lock);
        return -2; // Memory allocation failed
    }

    strncpy(conn->ip_address, ip_address, 15);
    conn->port = htons(port);
    conn->id = manager.count;
    conn->status = 1;

    manager.connections[manager.count++] = conn;
    manager.allocated_memory += sizeof(Connection);

    pthread_rwlock_unlock(&manager.lock);
    return 0; // Success
}

int remove_connection(int id) {
    pthread_rwlock_wrlock(&manager.lock);

    for (size_t i = 0; i < manager.count; ++i) {
        if (manager.connections[i]->id == id) {
            free(manager.connections[i]);
            manager.allocated_memory -= sizeof(Connection);

            memmove(&manager.connections[i], &manager.connections[i + 1],
                    (manager.count - i - 1) * sizeof(Connection*));
            --manager.count;

            pthread_rwlock_unlock(&manager.lock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&manager.lock);
    return -1; // Connection not found
}

void serialize_connections(char** buffer, size_t* length) {
    pthread_rwlock_rdlock(&manager.lock);

    *length = sizeof(size_t); // Size of count
    for (size_t i = 0; i < manager.count; ++i) {
        *length += sizeof(Connection);
    }

    *buffer = malloc(*length);
    if (!*buffer) {
        pthread_rwlock_unlock(&manager.lock);
        return;
    }

    char* ptr = *buffer;

    memcpy(ptr, &manager.count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < manager.count; ++i) {
        memcpy(ptr, manager.connections[i], sizeof(Connection));
        ptr += sizeof(Connection);
    }

    pthread_rwlock_unlock(&manager.lock);
}

void deserialize_connections(const char* buffer, size_t length) {
    pthread_rwlock_wrlock(&manager.lock);

    size_t count;
    const char* ptr = buffer;

    memcpy(&count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if (manager.count > 0) {
        for (size_t i = 0; i < manager.count; ++i) {
            free(manager.connections[i]);
        }
    }

    manager.count = count;
    manager.connections[0] = NULL;

    size_t allocated_memory = sizeof(size_t);
    for (size_t i = 0; i < count; ++i) {
        Connection* conn = malloc(sizeof(Connection));
        if (!conn) {
            pthread_rwlock_unlock(&manager.lock);
            return;
        }

        memcpy(conn, ptr, sizeof(Connection));
        manager.connections[i] = conn;

        allocated_memory += sizeof(Connection);
        ptr += sizeof(Connection);

        // Adjust for endianness
        conn->port = ntohs(conn->port);
    }

    manager.allocated_memory = allocated_memory;

    pthread_rwlock_unlock(&manager.lock);
}

void* connection_monitor(void* arg) {
    ConnectionManager* mgr = (ConnectionManager*)arg;

    while (1) {
        sleep(mgr->heartbeat_interval);

        pthread_rwlock_rdlock(&mgr->lock);
        for (size_t i = 0; i < mgr->count; ++i) {
            // Simulate a heartbeat check
            // Update connection status based on actual network check logic
            printf("Heartbeat sent to %s:%d\n", mgr->connections[i]->ip_address,
                   ntohs(mgr->connections[i]->port));
        }
        pthread_rwlock_unlock(&mgr->lock);
    }

    return NULL;
}

void log_event(const char* message) {
    // Example local logging mechanism
    printf("%s\n", message);
}

int main() {
    init_connection_manager(5);

    if (add_connection("192.168.1.1", 8080) == 0) {
        log_event("Added connection to 192.168.1.1:8080");
    }

    char* buffer;
    size_t length;
    serialize_connections(&buffer, &length);

    deserialize_connections(buffer, length);

    if (remove_connection(0) == 0) {
        log_event("Removed connection ID 0");
    }

    free(buffer);
    return 0;
}
