#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <zlib.h> // For compression (optional)
#include "rte_rwlock.h" // A third-party read-write lock library

#define MAX_TITLE_LEN 256
#define TIMESTAMP_SIZE sizeof(uint64_t)

typedef struct {
    char title[MAX_TITLE_LEN];
    uint64_t publication_date;
    char **content; // Array of word strings
    size_t content_size;
} Document;

typedef struct {
    Document *documents;
    size_t count;
    pthread_rwlock_t rwlock; // Read-write lock for thread safety
} DocumentCollection;

// Initialize a new document collection
DocumentCollection* create_document_collection() {
    DocumentCollection *collection = malloc(sizeof(DocumentCollection));
    if (!collection) return NULL;

    collection->documents = NULL;
    collection->count = 0;
    pthread_rwlock_init(&collection->rwlock, NULL);

    return collection;
}

// Add a document to the collection
void add_document(DocumentCollection *collection, const char *title, uint64_t publication_date, const char **content, size_t content_size) {
    pthread_rwlock_wrlock(&collection->rwlock);

    // Resize the documents array
    Document *new_docs = realloc(collection->documents, (collection->count + 1) * sizeof(Document));
    if (!new_docs) {
        pthread_rwlock_unlock(&collection->rwlock);
        return;
    }
    collection->documents = new_docs;

    // Initialize the new document
    Document *doc = &collection->documents[collection->count];
    strncpy(doc->title, title, MAX_TITLE_LEN - 1);
    doc->publication_date = publication_date;
    doc->content_size = content_size;

    // Allocate and copy content words
    doc->content = malloc(content_size * sizeof(char*));
    for (size_t i = 0; i < content_size; ++i) {
        size_t len = strlen(content[i]) + 1;
        doc->content[i] = malloc(len);
        strcpy(doc->content[i], content[i]);
    }

    collection->count++;
    pthread_rwlock_unlock(&collection->rwlock);
}

// Serialize the document collection to a binary format
size_t serialize_document_collection(const DocumentCollection *collection, uint8_t **buffer) {
    size_t total_size = 0;
    pthread_rwlock_rdlock(&collection->rwlock);

    // Calculate buffer size (simplified)
    for (size_t i = 0; i < collection->count; ++i) {
        const Document *doc = &collection->documents[i];
        total_size += MAX_TITLE_LEN + TIMESTAMP_SIZE;
        for (size_t j = 0; j < doc->content_size; ++j) {
            total_size += strlen(doc->content[j]) + 1;
        }
    }

    // Allocate buffer
    *buffer = malloc(total_size);
    if (!*buffer) {
        pthread_rwlock_unlock(&collection->rwlock);
        return 0;
    }

    uint8_t *ptr = *buffer;

    // Serialize each document
    for (size_t i = 0; i < collection->count; ++i) {
        const Document *doc = &collection->documents[i];
        memcpy(ptr, doc->title, MAX_TITLE_LEN);
        ptr += MAX_TITLE_LEN;
        memcpy(ptr, &doc->publication_date, TIMESTAMP_SIZE);
        ptr += TIMESTAMP_SIZE;

        for (size_t j = 0; j < doc->content_size; ++j) {
            size_t len = strlen(doc->content[j]) + 1;
            memcpy(ptr, doc->content[j], len);
            ptr += len;
        }
    }

    pthread_rwlock_unlock(&collection->rwlock);

    return total_size;
}

// Deserialize a binary buffer into a document collection
DocumentCollection* deserialize_document_collection(const uint8_t *buffer, size_t buffer_size) {
    DocumentCollection *collection = create_document_collection();
    if (!collection) return NULL;

    const uint8_t *ptr = buffer;
    while (ptr - buffer < buffer_size) {
        Document doc;
        memcpy(doc.title, ptr, MAX_TITLE_LEN);
        ptr += MAX_TITLE_LEN;
        memcpy(&doc.publication_date, ptr, TIMESTAMP_SIZE);
        ptr += TIMESTAMP_SIZE;

        // Deserialize content words
        char *word = malloc(MAX_TITLE_LEN); // Assume max length for simplicity
        while (ptr - buffer < buffer_size && *ptr) {
            size_t len = strlen((char*)ptr) + 1;
            memcpy(word, ptr, len);
            ptr += len;

            add_document(collection, doc.title, doc.publication_date, &word, 1);
        }
        free(word);
    }

    return collection;
}

// Free all resources used by the document collection
void free_document_collection(DocumentCollection *collection) {
    if (!collection) return;

    pthread_rwlock_wrlock(&collection->rwlock);

    for (size_t i = 0; i < collection->count; ++i) {
        Document *doc = &collection->documents[i];
        for (size_t j = 0; j < doc->content_size; ++j) {
            free(doc->content[j]);
        }
        free(doc->content);
    }

    free(collection->documents);
    pthread_rwlock_unlock(&collection->rwlock);

    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

// Example logging function
void log_message(const char *message) {
    printf("[LOG] %s\n", message); // Replace with a more sophisticated logger if needed
}

int main() {
    DocumentCollection *collection = create_document_collection();
    const char *content[] = {"word1", "word2"};

    add_document(collection, "Sample Title", 1234567890, content, 2);

    uint8_t *buffer;
    size_t size = serialize_document_collection(collection, &buffer);
    log_message("Serialized document collection.");

    DocumentCollection *new_collection = deserialize_document_collection(buffer, size);
    free(buffer);

    free_document_collection(collection);
    free_document_collection(new_collection);

    return 0;
}
