    if (!transactions) {
        perror("Memory allocation failed for transactions array");
        return NULL;
    }

    size_t total_size = num_transactions * TRANSACTION_STRUCT_SIZE;

    unsigned char *memory_block = malloc(total_size);
    if (!memory_block) {
        free(transactions);
        perror("Memory allocation failed for transaction data");
        return NULL;
    }

    memset(memory_block, 0, total_size);

    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i] = (transaction *)(memory_block + i * TRANSACTION_STRUCT_SIZE);
        generate_uuid(&transactions[i]->transaction_id);
        transactions[i]->timestamp = time(NULL);
    }

    *allocated_count = num_transactions;
    return transactions;
}

