#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <uuid/uuid.h>
#include <stdbool.h>

#define MEMORY_BUDGET 1048576 // Example budget in bytes

typedef struct {
    double amount;
    char status;
    time_t timestamp;
} transaction;

typedef struct {
    int value;
} record;

// Function prototypes
void initialize_arrays(size_t num_transactions, size_t num_offsets, size_t num_keys, 
                       size_t *array_sizes, long **offsets, int **keys, record **records);
bool validate_transaction(double amount);
double calculate_total_valid_transactions();
void seed_random_and_populate_records(record *records, size_t num_records, int min_val, int max_val);
unsigned char* serialize_data(transaction *transactions, size_t num_transactions,
                              long *offsets, size_t num_offsets, 
                              int *keys, size_t num_keys, record *records, size_t num_records,
                              size_t *serialized_size);

// Initialize arrays with error checking
void initialize_arrays(size_t num_transactions, size_t num_offsets, size_t num_keys, 
                       size_t *array_sizes, long **offsets, int **keys, record **records) {
    transaction *transactions = NULL;
    unsigned char *buffer;

    if (num_transactions > 0) {
        transactions = malloc(num_transactions * sizeof(transaction));
        if (!transactions) {
            fprintf(stderr, "Memory allocation failed for transactions\n");
            exit(EXIT_FAILURE);
        }
        array_sizes[0] = num_transactions;
    }

    if (num_offsets > 0) {
        offsets = malloc(num_offsets * sizeof(long));
        if (!offsets) {
            free(transactions);
            fprintf(stderr, "Memory allocation failed for offsets\n");
            exit(EXIT_FAILURE);
        }
        array_sizes[1] = num_offsets;
    }

    if (num_keys > 0) {
        keys = malloc(num_keys * sizeof(int));
        if (!keys) {
            free(transactions);
            free(*offsets);
            fprintf(stderr, "Memory allocation failed for keys\n");
            exit(EXIT_FAILURE);
        }
        array_sizes[2] = num_keys;
    }

    if (num_transactions > 0) {
        records = malloc(num_transactions * sizeof(record));
        if (!records) {
            free(transactions);
            free(*offsets);
            free(*keys);
            fprintf(stderr, "Memory allocation failed for records\n");
            exit(EXIT_FAILURE);
        }
        array_sizes[3] = num_transactions;
    }

    // Check total memory usage
    size_t total_memory = 0;
    if (transactions) total_memory += sizeof(transaction) * num_transactions;
    if (*offsets) total_memory += sizeof(long) * num_offsets;
    if (*keys) total_memory += sizeof(int) * num_keys;
    if (*records) total_memory += sizeof(record) * num_transactions;

    if (total_memory > MEMORY_BUDGET) {
        fprintf(stderr, "Memory allocation exceeds budget\n");
        free(transactions);
        free(*offsets);
        free(*keys);
        free(*records);
        exit(EXIT_FAILURE);
    }

    // Initialize transactions with unique IDs and current timestamp
    for (size_t i = 0; i < num_transactions; ++i) {
        uuid_t id;
        uuid_generate(id);
        transactions[i].timestamp = time(NULL);

        char *uuid_str = malloc(37); // UUID string length is 36 + null terminator
        uuid_unparse_lower(id, uuid_str);
        printf("Transaction ID: %s\n", uuid_str);
        free(uuid_str);

        if (!validate_transaction(transactions[i].amount)) {
            fprintf(stderr, "Invalid transaction amount at index %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Random seed and record population
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_transactions; ++i) {
        (*records)[i].value = rand() % 100 + 1; // Example range [1, 100]
    }
}

// Validate transaction amount using external service
bool validate_transaction(double amount) {
    return amount >= 0.0;
}

// Calculate total sum of valid transactions from standard input
double calculate_total_valid_transactions() {
    double total = 0.0;
    double amount;

    while (scanf("%lf", &amount) == 1) {
        if (validate_transaction(amount)) {
            total += amount;
        }
    }

    return total;
}

// Serialize data to a byte array
unsigned char* serialize_data(transaction *transactions, size_t num_transactions,
                              long *offsets, size_t num_offsets, 
                              int *keys, size_t num_keys, record *records, size_t num_records,
                              size_t *serialized_size) {
    size_t header_size = 3 * sizeof(size_t); // Store the number of elements for each type
    size_t transaction_data_size = num_transactions * (sizeof(double) + sizeof(char) + sizeof(time_t));
    size_t offset_data_size = num_offsets * sizeof(long);
    size_t key_data_size = num_keys * sizeof(int);
    size_t record_data_size = num_records * sizeof(record);

    *serialized_size = header_size + transaction_data_size + offset_data_size + 
                       key_data_size + record_data_size;

    unsigned char* buffer = malloc(*serialized_size);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed for serialization buffer\n");
        exit(EXIT_FAILURE);
    }

    // Serialize data considering endianness
    size_t *header = (size_t*)buffer;
    header[0] = htobe64(num_transactions);
    header[1] = htobe64(num_offsets);
    header[2] = htobe64(num_keys);

    unsigned char *ptr = buffer + header_size;

    for (size_t i = 0; i < num_transactions; ++i) {
        double amount = htobe64(*(double*)&transactions[i].amount);
        char status = transactions[i].status;
        time_t timestamp = htobe64(transactions[i].timestamp);

        memcpy(ptr, &amount, sizeof(double));
        ptr += sizeof(double);
        *ptr++ = status;
        memcpy(ptr, &timestamp, sizeof(time_t));
        ptr += sizeof(time_t);
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        long offset = htobe64(offsets[i]);
        memcpy(ptr, &offset, sizeof(long));
        ptr += sizeof(long);
    }

    for (size_t i = 0; i < num_keys; ++i) {
        int key = htobe32(keys[i]);
        memcpy(ptr, &key, sizeof(int));
        ptr += sizeof(int);
    }

    for (size_t i = 0; i < num_records; ++i) {
        record rec = records[i];
        long rec_val = htobe64(rec.value);
        memcpy(ptr, &rec_val, sizeof(long));
        ptr += sizeof(long);
    }

    return buffer;
}

