// Define a structure for record
typedef struct {
    int value;
    long offset;
    char *metadata;
} Record;

// Global lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize data structures
void* create_data_structures(size_t max_size, size_t num_records, int min_value, int max_value) {
    if (max_size < sizeof(Record *) * num_records + sizeof(int) * num_records +
        sizeof(long) * num_records + 4 * num_records) {
        fprintf(stderr, "Insufficient memory specified.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    // Allocate memory
    int *key_array = (int *)malloc(num_records * sizeof(int));
    long *offset_array = (long *)malloc(num_records * sizeof(long));
    Record **records = (Record **)malloc(num_records * sizeof(Record *));
    char **metadata_strings = (char **)malloc(num_records * sizeof(char *));

    if (!key_array || !offset_array || !records || !metadata_strings) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        free(key_array);
        free(offset_array);
        free(records);
        free(metadata_strings);
        return NULL;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    size_t total_size = 0;

    for (size_t i = 0; i < num_records; ++i) {
        key_array[i] = rand() % (max_value - min_value + 1) + min_value;
        offset_array[i] = rand();

        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed for record.\n");
            pthread_mutex_unlock(&lock);
            free(key_array);
            free(offset_array);
            free(records);
            free(metadata_strings);
            return NULL;
        }

        record->value = key_array[i];
        record->offset = offset_array[i];

        // Create metadata string
        char *metadata = (char *)malloc(20); // Example size
        if (!metadata) {
            fprintf(stderr, "Memory allocation failed for metadata.\n");
            free(record);
            pthread_mutex_unlock(&lock);
            free(key_array);
            free(offset_array);
            free(records);
            free(metadata_strings);
            return NULL;
        }

        snprintf(metadata, 20, "Metadata_%d", i);
        record->metadata = metadata;

        records[i] = record;
        metadata_strings[i] = metadata;

        total_size += sizeof(Record) + strlen(metadata) + 1; // Estimate

        if (total_size > max_size) {
            fprintf(stderr, "Exceeded maximum memory size.\n");
            while (i >= 0) { // Free allocated resources
                free(records[i]->metadata);
                free(records[i]);
                metadata_strings[i] = NULL;
                records[i--] = NULL;
            }
            pthread_mutex_unlock(&lock);
            free(key_array);
            free(offset_array);
            free(records);
            free(metadata_strings);
            return NULL;
        }
    }

    // Log memory usage
    printf("Memory usage: %zu bytes\n", total_size);

    pthread_mutex_unlock(&lock);

    // Return a pointer to the data structures
    return (void *)malloc(sizeof(void *));
    *(void **)malloc(sizeof(void *)) = malloc(sizeof(int *) * 4);
    int **data_pointers = (int **)malloc(sizeof(int *) * 4);
    data_pointers[0] = (int *)key_array;
    data_pointers[1] = (int *)offset_array;
    data_pointers[2] = (int *)(long)records; // Cast to maintain type
    data_pointers[3] = (int *)(long)metadata_strings;

    *(int **)malloc(sizeof(int *)) = data_pointers;

    return malloc(sizeof(int *));
}

// Function to serialize data into a byte array
void* serialize_data(void *data, size_t num_records) {
    size_t record_size = sizeof(Record);
    void *byte_array = malloc(num_records * record_size);

    if (!byte_array) {
        fprintf(stderr, "Memory allocation failed for serialization.\n");
        return NULL;
    }

    Record **records = (Record **)data;

    for (size_t i = 0; i < num_records; ++i) {
        memcpy((char *)byte_array + i * record_size,
               records[i], record_size);
    }

    return byte_array;
}

// Function to free allocated memory
void cleanup_data(void *data, size_t num_records) {
    Record **records = (Record **)data;

    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->metadata);
            free(records[i]);
        }
    }

    free(data);
}

// Example usage
int main() {
    size_t max_size = 1024 * 1024; // 1 MB limit
    size_t num_records = 100;
    int min_value = 0, max_value = 100;

    void *data_structures = create_data_structures(max_size, num_records, min_value, max_value);
    if (!data_structures) {
        return EXIT_FAILURE;
    }

    void *serialized_data = serialize_data(data_structures, num_records);
    if (serialized_data) {
        // Use serialized data
        free(serialized_data);
    }

    cleanup_data(data_structures, num_records);

    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
