['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // Example maximum memory limit (1MB)
#define INITIAL_RECORD_SIZE 10

typedef struct {
    int value;
    long offset;
    char *metadata;
    char status;
    int priority;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
    size_t total_memory;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    collection->records = calloc(initial_capacity, sizeof(Record *));
    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->total_memory = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond_var, NULL);
    return collection;
}

void free_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->metadata);
        free(collection->records[i]);
    }
    free(collection->records);

    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond_var);
    free(collection);
}

int add_record(RecordCollection *collection, int value, long offset, const char *metadata, char status, int priority) {
    pthread_mutex_lock(&collection->lock);

    size_t metadata_size = strlen(metadata) + 1;
    size_t record_memory = sizeof(int) + sizeof(long) + metadata_size + sizeof(char) + sizeof(int);

    if (collection->total_memory + record_memory > MAX_MEMORY || collection->count >= collection->capacity) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory limit exceeded or capacity reached
    }

    Record *record = malloc(record_memory);
    record->value = value;
    record->offset = offset;
    record->metadata = strndup(metadata, metadata_size);
    record->status = status;
    record->priority = priority;

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            free(record->metadata);
            free(record);
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count++] = record;
    collection->total_memory += record_memory;

    pthread_cond_signal(&collection->cond_var);
    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

void *process_records(void *arg) {
    RecordCollection *collection = (RecordCollection *)arg;

    while (1) {
        pthread_mutex_lock(&collection->lock);

        while (collection->count == 0) {
            pthread_cond_wait(&collection->cond_var, &collection->lock);
        }

        // Process records based on priority
        for (size_t i = 0; i < collection->count; ++i) {
            Record *record = collection->records[i];
            // Example processing: update status and log the record
            printf("Processing record with value %d, offset %ld, metadata '%s', status %c\n",
                   record->value, record->offset, record->metadata, record->status);

            record->status = (record->status == 'N') ? 'P' : 'C'; // Example update
        }

        pthread_mutex_unlock(&collection->lock);

        // Simulate processing delay
        sleep(1);
    }

    return NULL;
}

int main() {
    RecordCollection *collection = create_collection(INITIAL_RECORD_SIZE);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_records, collection) != 0) {
        fprintf(stderr, "Failed to create processing thread\n");
        free_collection(collection);
        return EXIT_FAILURE;
    }

    // Example usage: add records
    add_record(collection, 42, 100L, "Sample metadata", 'N', 1);

    pthread_join(thread_id, NULL); // In a real scenario, you'd manage threads more dynamically

    free_collection(collection);
    return EXIT_SUCCESS;
}
