#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct node {
    char *data;
    int priority;
    struct node *next;
} node;

void free_node(node *head) {
    node *tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp->data);
        free(tmp);
    }
}

node* create_nodes(int count, const char *prefix, size_t max_length) {
    if (count <= 0 || prefix == NULL) return NULL;

    node **array = malloc(count * sizeof(node *));
    if (!array) return NULL;

    srand((unsigned int)time(NULL));

    for (int i = 0; i < count; ++i) {
        array[i] = malloc(sizeof(node));
        if (!array[i]) break;

        size_t len = snprintf(NULL, 0, "%s%d", prefix, rand() % 100);
        array[i]->data = malloc(len + 1);
        if (!array[i]->data) {
            free(array[i]);
            break;
        }

        snprintf(array[i]->data, len + 1, "%s%d", prefix, rand() % 100);
        array[i]->priority = rand() % 100;
        array[i]->next = (i < count - 1) ? array[i + 1] : NULL;
    }

    return array[0];
}

void print_reverse(node *head) {
    if (!head) return;

    node *prev = NULL, *current = head, *next = NULL;

    while (current != NULL) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }

    current = prev;
    while (current != NULL) {
        printf("Node data: %s\n", current->data);
        current = current->next;
    }
}

void check_memory_health(node *head) {
    // Placeholder for real memory health checks
    if (!head) return;

    node *current = head;
    while (current != NULL) {
        if (current->data == NULL || strlen(current->data) < 2) {
            printf("Memory inconsistency detected at node.\n");
            break;
        }
        current = current->next;
    }
}

int main() {
    int num_nodes = 5;
    const char *prefix = "Node";
    size_t max_length = 50;

    node *head = create_nodes(num_nodes, prefix, max_length);
    if (!head) {
        fprintf(stderr, "Failed to allocate nodes.\n");
        return EXIT_FAILURE;
    }

    print_reverse(head);
    check_memory_health(head);

    free_node(head);

    return EXIT_SUCCESS;
}
