#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_HASH_TABLE_SIZE 101

typedef struct HashNode {
    int key;
    long offset;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    size_t size;
    size_t count;
} HashTable;

typedef struct Record {
    int value;
} Record;

// Function declarations
HashTable* createHashTable(size_t initialSize);
void freeHashTable(HashTable* table);
int hashFunction(int key, size_t size);
HashNode* createHashNode(int key, long offset);
long* allocateAndInitializeLongArray(size_t size);
int* allocateAndInitializeIntArray(size_t size);
Record* allocateAndInitializeRecords(size_t count, int minRange, int maxRange);
void populateRecords(Record* records, size_t count, int minRange, int maxRange);
void freeAll(long* longArray, size_t longSize, int* intArray, size_t intSize, Record* records, size_t recordCount, HashTable* table);
void resizeHashTable(HashTable* table);
int updateHashNode(HashTable* table, int key, long offset);

// Function implementations
HashTable* createHashTable(size_t initialSize) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = initialSize;
    table->count = 0;
    table->buckets = (HashNode**)calloc(initialSize, sizeof(HashNode*));

    return table;
}

void freeHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

int hashFunction(int key, size_t size) {
    return key % size;
}

HashNode* createHashNode(int key, long offset) {
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) return NULL;

    newNode->key = key;
    newNode->offset = offset;
    newNode->next = NULL;

    return newNode;
}

long* allocateAndInitializeLongArray(size_t size) {
    long* array = (long*)aligned_alloc(16, size * sizeof(long));
    if (!array) return NULL;

    memset(array, 0, size * sizeof(long));

    return array;
}

int* allocateAndInitializeIntArray(size_t size) {
    int* array = (int*)aligned_alloc(16, size * sizeof(int));
    if (!array) return NULL;

    memset(array, 0, size * sizeof(int));

    return array;
}

Record* allocateAndInitializeRecords(size_t count, int minRange, int maxRange) {
    Record* records = (Record*)aligned_alloc(16, count * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));
    populateRecords(records, count, minRange, maxRange);

    return records;
}

void populateRecords(Record* records, size_t count, int minRange, int maxRange) {
    int range = maxRange - minRange + 1;
    if (range <= 0 || count > range) {
        fprintf(stderr, "Invalid input ranges or too many unique values requested.\n");
        exit(EXIT_FAILURE);
    }

    int* seenValues = (int*)calloc(range, sizeof(int));
    for (size_t i = 0; i < count; ++i) {
        int value;
        do {
            value = minRange + rand() % range;
        } while (seenValues[value - minRange]);

        records[i].value = value;
        seenValues[value - minRange] = 1;
    }

    free(seenValues);
}

void freeAll(long* longArray, size_t longSize, int* intArray, size_t intSize, Record* records, size_t recordCount, HashTable* table) {
    if (longArray) free(longArray);
    if (intArray) free(intArray);
    if (records) free(records);
    freeHashTable(table);
}

void resizeHashTable(HashTable* table) {
    size_t newSize = 2 * table->size + 1;
    HashNode** newBuckets = (HashNode**)calloc(newSize, sizeof(HashNode*));

    for (size_t i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* nextNode = node->next;
            size_t newIndex = hashFunction(node->key, newSize);

            node->next = newBuckets[newIndex];
            newBuckets[newIndex] = node;
            node = nextNode;
        }
    }

    free(table->buckets);
    table->buckets = newBuckets;
    table->size = newSize;
}

int updateHashNode(HashTable* table, int key, long offset) {
    if (table->count >= 0.7 * table->size) {
        resizeHashTable(table);
    }

    size_t index = hashFunction(key, table->size);
    HashNode* node = table->buckets[index];

    while (node) {
        if (node->key == key) {
            node->offset = offset;
            return 0; // Key already exists
        }
        node = node->next;
    }

    node = createHashNode(key, offset);
    if (!node) return -1; // Memory allocation failed

    node->next = table->buckets[index];
    table->buckets[index] = node;
    ++table->count;

    return 0;
}

void updateRecordsFromDataSource(Record* records, size_t count) {
    // Simulate data source updates
    for (size_t i = 0; i < count; ++i) {
        // Example logic to update record values based on some external conditions
        records[i].value += rand() % 5;
    }
}

void logMemoryUsage(size_t longSize, size_t intSize, size_t recordCount, HashTable* table) {
    printf("Memory Usage:\n");
    printf("Long Array: %zu bytes\n", longSize * sizeof(long));
    printf("Int Array: %zu bytes\n", intSize * sizeof(int));
    printf("Records: %zu bytes\n", recordCount * sizeof(Record));
    printf("Hash Table: %zu nodes\n", table->count);
}

int main() {
    size_t arraySize = 1000;
    size_t recordCount = 500;
    int minRange = 1, maxRange = 10000;

    long* longArray = allocateAndInitializeLongArray(arraySize);
    if (!longArray) return EXIT_FAILURE;

    int* intArray = allocateAndInitializeIntArray(arraySize);
    if (!intArray) {
        free(longArray);
        return EXIT_FAILURE;
    }

    Record* records = allocateAndInitializeRecords(recordCount, minRange, maxRange);
    if (!records) {
        free(longArray);
        free(intArray);
        return EXIT_FAILURE;
    }

    HashTable* hashTable = createHashTable(INITIAL_HASH_TABLE_SIZE);
    if (!hashTable) {
        free(longArray);
        free(intArray);
        free(records);
        return EXIT_FAILURE;
    }

    // Example usage
    for (size_t i = 0; i < recordCount; ++i) {
        int key = records[i].value % arraySize;
        long offset = rand() % arraySize;

        if (updateHashNode(hashTable, key, offset) != 0) {
            fprintf(stderr, "Failed to update hash table\n");
            freeAll(longArray, arraySize, intArray, arraySize, records, recordCount, hashTable);
            return EXIT_FAILURE;
        }
    }

    // Simulate data source updates
    updateRecordsFromDataSource(records, recordCount);

    logMemoryUsage(arraySize, arraySize, recordCount, hashTable);

    freeAll(longArray, arraySize, intArray, arraySize, records, recordCount, hashTable);

    return 0;
}
