#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int key;
    long *offset;
} record;

// Function prototypes
record* manageDynamicArray(size_t num_records, int min_key, int max_key);
bool allocateMemory(record **records, size_t num_records);
bool initializeOffsets(record *records, size_t num_records);
bool generateUniqueKeys(int *keys, size_t num_keys, int min_key, int max_key);
void logChanges(const char* message);

// Main function to manage dynamic array
record* manageDynamicArray(size_t num_records, int min_key, int max_key) {
