    return true;
}

// Function to initialize offset values with sequential long integers
bool initializeOffsets(record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        *(records[i].offset) = (long)i;
    }
    return true;
}

// Function to generate unique random keys within specified range
bool generateUniqueKeys(int *keys, size_t num_keys, int min_key, int max_key) {
    srand(time(NULL)); // Seed for randomness

    bool keySet[num_keys];
    memset(keySet, false, sizeof(bool) * num_keys);

    int available = max_key - min_key + 1;
    if (available < num_keys) {
        fprintf(stderr, "Not enough range to generate unique keys.\n");
        return false;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        int key;
        do {
            key = min_key + rand() % available;
        } while (keySet[key - min_key]);

        keySet[key - min_key] = true;
        keys[i] = key;
    }

    return true;
}

// Function to log changes for auditing purposes
void logChanges(const char* message) {
    // Simple logging mechanism, can be replaced with a more robust solution if needed
    printf("Log: %s\n", message);
}
