#define KEY_RANGE 1000
#define HASH_TABLE_SIZE 101 // A prime number for better distribution

typedef struct Value {
    char data;
    struct Value* next;
} Value;

typedef struct Record {
    long offset;
    int key;
    struct Value* values;
} Record;

typedef struct HashTableNode {
    Record* record;
    struct HashTableNode* next;
} HashTableNode;

HashTableNode* hash_table[HASH_TABLE_SIZE];

unsigned int hash(int key) {
    return key % HASH_TABLE_SIZE;
}

Record* create_record(long offset, int key, char data_range_min, char data_range_max) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for Record");
        exit(EXIT_FAILURE);
    }
    record->offset = offset;
    record->key = key;

    Value* value = (Value*)malloc(sizeof(Value));
    if (!value) {
        free(record);
        perror("Failed to allocate memory for Value");
        exit(EXIT_FAILURE);
    }
    value->data = data_range_min + rand() % (data_range_max - data_range_min + 1);
    value->next = NULL;

    record->values = value;
    return record;
}

void insert_into_hash_table(Record* record) {
    int index = hash(record->key);

    HashTableNode* node = (HashTableNode*)malloc(sizeof(HashTableNode));
    if (!node) {
        free_record(record);
        perror("Failed to allocate memory for HashTableNode");
        exit(EXIT_FAILURE);
    }
    node->record = record;
    node->next = hash_table[index];
    hash_table[index] = node;
}

void free_record(Record* record) {
    Value* current = record->values;
    while (current != NULL) {
        Value* next = current->next;
        free(current);
        current = next;
    }
    free(record);
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableNode* node = hash_table[i];
        while (node != NULL) {
            HashTableNode* to_free = node;
            node = node->next;
            free_record(to_free->record);
            free(to_free);
        }
    }
}

void print_record_values(Record* record) {
    Value* value = record->values;
    printf("Key: %d, Offset: %ld, Values:\n", record->key, record->offset);
    while (value != NULL) {
        printf("  - %c\n", value->data);
        value = value->next;
    }
}

void initialize_records(int num_records, char data_range_min, char data_range_max) {
    srand(time(NULL));

    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        perror("Failed to allocate memory for records array");
        exit(EXIT_FAILURE);
    }

    long* offsets = (long*)calloc(num_records, sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % KEY_RANGE;

        Record* record = create_record(offsets[i], keys[i], data_range_min, data_range_max);
        records[i] = record;

        insert_into_hash_table(record);
    }

    for (int i = 0; i < num_records; ++i) {
        print_record_values(records[i]);
        free(records[i]);
    }

    free(records);
    free(offsets);
    free(keys);

    free_hash_table();
}

int main() {
    initialize_records(10, 'a', 'z'); // Example usage
    return 0;
}
