typedef struct node {
    char* string;
    int priority;
    struct node* next;
} node;

// Function prototypes
node** create_node_array(size_t size, const char* prefix, size_t max_string_length);
void initialize_nodes(node** nodes, size_t size, const char* prefix, size_t max_string_length);
void insert_node_at(node** head, size_t position, node* new_node);
void free_nodes(node** nodes, size_t size);
void print_reverse(node* head);
int validate_memory_blocks(void);

// Create and initialize an array of node pointers
node** create_node_array(size_t size, const char* prefix, size_t max_string_length) {
    if (size == 0 || prefix == NULL) return NULL;

    node** nodes = malloc(size * sizeof(node*));
    if (!nodes) exit(EXIT_FAILURE);

    initialize_nodes(nodes, size, prefix, max_string_length);
    return nodes;
}

// Initialize each node with a unique string and random priority
void initialize_nodes(node** nodes, size_t size, const char* prefix, size_t max_string_length) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < size; ++i) {
        if (!nodes[i]) continue;

        nodes[i]->string = malloc(max_string_length + 1);
        snprintf(nodes[i]->string, max_string_length + 1, "%s%d", prefix, rand() % 100);

        nodes[i]->priority = rand() % 100;
        nodes[i]->next = (i < size - 1) ? nodes[i + 1] : NULL;
    }
}

// Insert a node at a specific position in the list
void insert_node_at(node** head, size_t position, node* new_node) {
    if (!head || !new_node || position == 0) {
        new_node->next = *head;
        *head = new_node;
        return;
    }

    node* current = *head;
    for (size_t i = 1; current && i < position; ++i) {
        current = current->next;
    }

    if (current) {
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Free allocated memory for nodes
void free_nodes(node** nodes, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (!nodes[i]) continue;

        free(nodes[i]->string);
        free(nodes[i]);
    }
    free(nodes);
}

// Print the strings in reverse order of insertion
void print_reverse(node* head) {
    if (!head) return;

    node* stack[1024];
    size_t top = 0;

    while (head) {
        stack[top++] = head;
        head = head->next;
    }

    for (size_t i = 0; i < top; ++i) {
        printf("%s\n", stack[i]->string);
    }
}

// Simulate memory block validation
int validate_memory_blocks(void) {
    // Placeholder for actual memory validation logic
    return rand() % 2 == 0;
}

int main() {
    size_t array_size = 10;
    const char* prefix = "Node";
    size_t max_string_length = 20;

    node** nodes = create_node_array(array_size, prefix, max_string_length);

    // Insert a new node at position 3
    node* newNode = malloc(sizeof(node));
    if (!newNode) exit(EXIT_FAILURE);
    strcpy(newNode->string, "InsertedNode");
    newNode->priority = 50;

    insert_node_at(nodes, 3, newNode);

    print_reverse(nodes[0]);

    // Validate memory blocks periodically
    if (validate_memory_blocks()) {
        printf("Memory validation passed.\n");
    } else {
        printf("Memory validation failed!\n");
    }

    free_nodes(nodes, array_size);
    free(newNode);

    return 0;
}
