['```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <random>
#include <thread>
#include <mutex>
#include <memory>
#include <numeric>
#include <algorithm>

struct DataRecord {
    int key;
    long value;
};

class DynamicValueGenerator {
private:
    std::vector<DataRecord> records;
    std::pair<long, long> range;
    std::mutex mtx;

public:
    DynamicValueGenerator(const std::string& csvFilePath) : range(0, 0) {
        std::ifstream file(csvFilePath);
        if (!file.is_open()) {
            throw std::runtime_error("Could not open the CSV file.");
        }

        std::string line;
        while (std::getline(file, line)) {
            std::istringstream s(line);
            int key;
            if (!(s >> key) || !s.eof()) {
                throw std::runtime_error("Invalid data in CSV file.");
            }
            records.emplace_back(DataRecord{key, 0});
        }

        file.close();
    }

    void updateRange(long minVal, long maxVal) {
        std::lock_guard<std::mutex> lock(mtx);
        if (minVal > maxVal) {
            throw std::invalid_argument("Minimum range value cannot be greater than maximum.");
        }
        range = {minVal, maxVal};
    }

    void generateRandomValues() {
        std::lock_guard<std::mutex> lock(mtx);

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<long> dis(range.first, range.second);

        for (auto& record : records) {
            record.value = dis(gen);
        }
    }

    double calculateAverage() const {
        if (records.empty()) return 0.0;

        std::lock_guard<std::mutex> lock(mtx);
        long sum = std::accumulate(records.begin(), records.end(), 0L, 
                                   [](long acc, const DataRecord& record) { return acc + record.value; });

        return static_cast<double>(sum) / records.size();
    }

    void batchProcess(std::function<void(DataRecord&)> func, size_t batchSize = 10) {
        std::lock_guard<std::mutex> lock(mtx);

        size_t totalRecords = records.size();
        size_t batches = (totalRecords + batchSize - 1) / batchSize;

        std::vector<std::thread> threads;
        for (size_t i = 0; i < batches; ++i) {
            size_t startIdx = i * batchSize;
            size_t endIdx = std::min(startIdx + batchSize, totalRecords);

            threads.emplace_back([&, startIdx, endIdx]() {
                for (size_t j = startIdx; j < endIdx; ++j) {
                    func(records[j]);
                }
            });
        }

        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    std::string ToString() const {
        std::lock_guard<std::mutex> lock(mtx);
        return "Range: [" + std::to_string(range.first) + ", " + std::to_string(range.second) +
               "] - Records processed: " + std::to_string(records.size());
    }
};

// Example usage:
int main() {
    try {
        DynamicValueGenerator generator("keys.csv");
        generator.updateRange(1, 100);
        generator.generateRandomValues();
        double avg = generator.calculateAverage();
        std::cout << "Average value: " << avg << "\n";
        std::cout << generator.ToString() << "\n";

        // Example batch processing
        generator.batchProcess([](DataRecord& record) {
            // Dummy operation on each record
            record.value *= 2;
        });
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
    }

    return 0;
}
```']

