#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define TABLE_INITIAL_CAPACITY 16

typedef struct {
    int key;
    long offset_ptr;
} Record;

typedef struct {
    long* offsets;
    size_t num_offsets;
    int* keys;
    size_t num_keys;
    Record* records;
    size_t num_records;
    _Atomic(long*) hash_table;
    size_t table_capacity;
    pthread_mutex_t lock;
} MemoryManager;

// Hash function
static unsigned int hash(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

MemoryManager* create_memory_manager(size_t num_offsets, size_t num_keys, size_t num_records) {
    if (!num_offsets || !num_keys || !num_records) return NULL;

    MemoryManager* manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    // Allocate and initialize offsets and keys
    manager->offsets = aligned_alloc(64, sizeof(long) * num_offsets);
    if (!manager->offsets) goto fail;
    manager->num_offsets = num_offsets;

    manager->keys = aligned_alloc(64, sizeof(int) * num_keys);
    if (!manager->keys) goto fail;
    manager->num_keys = num_keys;

    // Allocate records
    manager->records = calloc(num_records, sizeof(Record));
    if (!manager->records) goto fail;
    manager->num_records = num_records;

    // Initialize hash table with atomic long pointers
    size_t initial_capacity = TABLE_INITIAL_CAPACITY;
    _Atomic(long*)*table = malloc(initial_capacity * sizeof(_Atomic(long*)));
    if (!table) goto fail;
    memset(table, 0, initial_capacity * sizeof(_Atomic(long*)));

    manager->hash_table = table;
    manager->table_capacity = initial_capacity;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;

fail:
    free_memory_manager(manager);
    return NULL;
}

void populate_records(MemoryManager* manager, int min_val, int max_val) {
    if (!manager) return;

    for (size_t i = 0; i < manager->num_records; ++i) {
        int unique_value = generate_unique_random(min_val, max_val, manager->records);
        manager->records[i].key = unique_value;
        long* offset_ptr = malloc(sizeof(long));
        if (!offset_ptr) continue;
        atomic_store(&manager->hash_table[hash(unique_value, manager->table_capacity)], (long*)offset_ptr);
        manager->records[i].offset_ptr = (long)offset_ptr;
    }
}

int generate_unique_random(int min_val, int max_val, Record* records) {
    // Implement a fast random generator with uniqueness check
    return rand() % (max_val - min_val + 1) + min_val; 
}

void free_memory_manager(MemoryManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->num_records; ++i) {
        long* offset_ptr = atomic_load(&manager->hash_table[hash(manager->records[i].key, manager->table_capacity)]);
        free((void*)offset_ptr);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->hash_table);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    MemoryManager* manager = create_memory_manager(1000, 500, 200);
    if (!manager) return EXIT_FAILURE;

    populate_records(manager, 1, 10000);

    free_memory_manager(manager);

    return EXIT_SUCCESS;
}
