#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_RETRIES 5

typedef struct {
    int value;
} record;

typedef struct hash_node {
    int key;
    long offset;
    struct hash_node* next;
} hash_node_t;

typedef struct {
    size_t capacity;
    hash_node_t** buckets;
    pthread_mutex_t lock;
} hash_table_t;

hash_table_t* create_hash_table(size_t initial_capacity) {
    hash_table_t* table = malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->buckets = calloc(table->capacity, sizeof(hash_node_t*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void free_hash_table(hash_table_t* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        hash_node_t* node = table->buckets[i];
        while (node) {
            hash_node_t* temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

unsigned long hash_function(int key, size_t capacity) {
    return ((unsigned long)key * 2654435761U) % capacity; // Knuth's multiplicative method
}

void insert_hash_table(hash_table_t* table, int key, long offset) {
    unsigned long index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->lock);

    hash_node_t* node = malloc(sizeof(hash_node_t));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }
    node->key = key;
    node->offset = offset;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    pthread_mutex_unlock(&table->lock);
}

long* allocate_memory(size_t size, size_t alignment) {
    void* ptr = NULL;
    for (int i = 0; i < MAX_RETRIES; ++i) {
