#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>
#include "zlib.h" // Include a third-party compression library

#define MAX_MEMORY 1048576 // Example maximum memory size (1 MB)
#define HASH_TABLE_SIZE 1024
#define DATA_ALIGNMENT 16

typedef struct RecordValue {
    char value;
    struct RecordValue* next;
} RecordValue;

typedef struct Record {
    long offset;
    int key;
    char* metadata;
    RecordValue* values;
    pthread_mutex_t mutex; // For thread safety
} Record;

typedef struct HashNode {
    Record* record;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t memory_used;
    pthread_mutex_t lock;
} RecordManager;

static inline void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) return NULL; // Align and allocate
    return ptr;
}

RecordManager* create_record_manager() {
    RecordManager* manager = aligned_alloc(DATA_ALIGNMENT, sizeof(RecordManager));
    if (!manager) {
        perror("Failed to allocate memory for record manager");
        return NULL;
    }

    memset(manager, 0, sizeof(RecordManager));
    manager->table = aligned_alloc(DATA_ALIGNMENT, sizeof(HashNode*) * HASH_TABLE_SIZE);
    if (!manager->table) {
        perror("Failed to allocate memory for hash table");
        free(manager);
        return NULL;
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        manager->table[i] = NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

Record* get_or_create_record(RecordManager* manager, int key) {
    unsigned long hash_index = key % HASH_TABLE_SIZE;

    pthread_mutex_lock(&manager->lock);
    HashNode* node = manager->table[hash_index];

    while (node) {
        if (node->record->key == key) {
            pthread_mutex_unlock(&manager->lock);
            return node->record;
        }
        node = node->next;
    }

    Record* record = aligned_alloc(DATA_ALIGNMENT, sizeof(Record));
    if (!record || manager->memory_used + sizeof(*record) > MAX_MEMORY) {
        perror("Failed to allocate memory for new record or exceeded maximum memory");
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    record->offset = rand();
    record->key = key;
    record->metadata = NULL; // Optional metadata
    record->values = NULL;

    HashNode* newNode = aligned_alloc(DATA_ALIGNMENT, sizeof(HashNode));
    if (!newNode) {
        perror("Failed to allocate memory for hash node");
        free(record);
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    newNode->record = record;
    newNode->next = manager->table[hash_index];
    manager->table[hash_index] = newNode;

    pthread_mutex_init(&record->mutex, NULL);

    pthread_mutex_lock(&record->mutex);
    // Random ASCII character for value
    char init_value = rand() % 95 + 32; // ASCII range: [32, 126]
    RecordValue* first_value = aligned_alloc(DATA_ALIGNMENT, sizeof(RecordValue));
    if (!first_value) {
        perror("Failed to allocate memory for record value");
        pthread_mutex_unlock(&record->mutex);
        return NULL;
    }

    first_value->value = init_value;
    first_value->next = NULL;
    record->values = first_value;

    pthread_mutex_unlock(&record->mutex);

    manager->memory_used += sizeof(*record) + (newNode ? sizeof(HashNode) : 0);
    pthread_mutex_unlock(&manager->lock);

    return record;
}

void destroy_record_manager(RecordManager* manager) {
    if (!manager) return;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode* node = manager->table[i];
        while (node) {
            HashNode* next_node = node->next;
            pthread_mutex_destroy(&node->record->mutex);
            free(node->record->metadata);
            RecordValue* val = node->record->values;
            while (val) {
                RecordValue* next_val = val->next;
                free(val);
                val = next_val;
            }
            free(node->record);
            free(node);
            node = next_node;
        }
    }

    free(manager->table);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

unsigned char* serialize_record(RecordManager* manager, size_t* out_size) {
    // Implement serialization logic considering endianness
    // Serialize each record and its values in a byte array

    unsigned char* buffer = NULL;
    *out_size = 0;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode* node = manager->table[i];
        while (node) {
            Record* record = node->record;
            size_t record_size = sizeof(record->offset) + sizeof(record->key);
            if (record->metadata) record_size += strlen(record->metadata) + 1;

            buffer = realloc(buffer, *out_size + record_size);
            if (!buffer) {
                perror("Failed to allocate memory for serialization");
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }

            memcpy(buffer + *out_size, &record->offset, sizeof(record->offset));
            memcpy(buffer + *out_size + sizeof(record->offset), &record->key, sizeof(record->key));

            if (record->metadata) {
                strcpy((char*)(buffer + *out_size + sizeof(record->offset) + sizeof(record->key)), record->metadata);
            }

            *out_size += record_size;

            pthread_mutex_lock(&record->mutex);

            RecordValue* value = record->values;
            while (value) {
                buffer = realloc(buffer, *out_size + sizeof(value->value));
                if (!buffer) {
                    perror("Failed to allocate memory for serialization");
                    pthread_mutex_unlock(&record->lock);
                    pthread_mutex_unlock(&manager->lock);
                    return NULL;
                }

                memcpy(buffer + *out_size, &value->value, sizeof(value->value));
                *out_size += sizeof(value->value);

                value = value->next;
            }

            pthread_mutex_unlock(&record->mutex);

            node = node->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return buffer;
}

unsigned char* compress_data(unsigned char* data, size_t size, size_t* compressed_size) {
    *compressed_size = compressBound(size);
    unsigned char* compressed_data = malloc(*compressed_size);
    if (!compressed_data) {
        perror("Failed to allocate memory for compression");
        return NULL;
    }

    int result = compress(compressed_data, compressed_size, data, size);
    if (result != Z_OK) {
        perror("Data compression failed");
        free(compressed_data);
        return NULL;
    }

    return compressed_data;
}

void find_largest_and_longest(const char* input[], size_t count) {
    int largest = INT_MIN;
    const char* longest_string = "";
    size_t max_length = 0;

    for (size_t i = 0; i < count; ++i) {
        int num = atoi(input[i]);
        if (num > largest) largest = num;

        size_t length = strlen(input[i]);
        if (length > max_length) {
            max_length = length;
            longest_string = input[i];
        }
    }

    printf("Largest Integer: %d\n", largest);
    printf("Longest String: '%s'\n", longest_string);
}

int main() {
    srand(time(NULL));

    RecordManager* manager = create_record_manager();
    if (!manager) return EXIT_FAILURE;

    // Sample data addition
    get_or_create_record(manager, 123);
    get_or_create_record(manager, 456);

    size_t serialized_size;
    unsigned char* data = serialize_record(manager, &serialized_size);
    if (data) {
        size_t compressed_size;
        unsigned char* compressed_data = compress_data(data, serialized_size, &compressed_size);
        if (compressed_data) {
            // Use or transmit compressed_data
            free(compressed_data);
        }
        free(data);
    }

    destroy_record_manager(manager);

    const char* inputs[] = {"123", "abcde", "67890"};
    find_largest_and_longest(inputs, 3);

    return EXIT_SUCCESS;
}
```

**Notes:**
- The code provides a basic setup for managing records using linked lists and hash tables.
- Thread safety is managed with mutexes for both the record manager and individual records.
- Memory allocation is aligned to improve performance on certain architectures.
- Serialization includes handling endianness considerations implicitly through standard `memcpy`.
- Compression uses zlib, a popular library suitable for many applications.
- The function `find_largest_and_longest` demonstrates reading from an array of strings/numbers and determining the largest integer and longest string.']

