static char get_status_indicator(char* used_statuses, size_t status_count) {
    for (int i = 0; i < status_count; ++i) {
        if (!used_statuses[i]) {
            used_statuses[i] = 1;
            return 'A' + i;
        }
    }
    return 'N';
}

LogEntry* create_log_entries(size_t temperature_count, size_t status_count, float min_temp, float max_temp) {
    size_t log_count = (temperature_count < status_count) ? temperature_count : status_count;

    LogEntry* entries = calloc(log_count, sizeof(LogEntry));
    if (!entries) {
        perror("Failed to allocate memory for log entries");
        return NULL;
    }

    char used_statuses[256] = {0}; // Assuming a maximum of 256 different statuses
    srand(time(NULL));

    for (size_t i = 0; i < log_count; ++i) {
        entries[i].timestamp = time(NULL); // Using current timestamp

        // Simulate temperature reading with random value within range
        entries[i].temperature = get_temperature_reading(min_temp, max_temp);

        // Assign unique status indicator
        do {
            entries[i].status = get_status_indicator(used_statuses, status_count);
        } while (entries[i].status == 'N');
    }

    // Sort log entries by timestamp using stable sort (e.g., qsort with a custom comparator)
    qsort(entries, log_count, sizeof(LogEntry), [](const void* a, const void* b) {
        LogEntry* entryA = (LogEntry*)a;
        LogEntry* entryB = (LogEntry*)b;
        return (entryA->timestamp > entryB->timestamp) - (entryA->timestamp < entryB->timestamp);
    });

    HashTable* hash_table = init_hash_table(log_count * 2); // Initial size is double the log count
    if (!hash_table) {
        free(entries);
        perror("Failed to initialize hash table");
        return NULL;
    }

    for (size_t i = 0; i < log_count; ++i) {
        insert_into_hash_table(hash_table, entries[i]);
    }

    // Store hash table within the LogEntry array for easy access
    entries[log_count].hash_table = *hash_table;

    return entries;
}

void free_log_entries(LogEntry* entries, size_t log_count) {
    if (!entries) return;

    HashTable* hash_table = &entries[log_count];
    free_hash_table(hash_table);
    free(entries);
}

HashTable* init_hash_table(size_t initial_size) {
    HashTable* hash_table = calloc(1, sizeof(HashTable));
    if (!hash_table) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }

    hash_table->size = initial_size;
    hash_table->load_factor = 0.75; // Common load factor
    hash_table->buckets = calloc(initial_size, sizeof(HashNode*));
    if (!hash_table->buckets) {
        free(hash_table);
        perror("Failed to allocate memory for hash table buckets");
        return NULL;
    }

    return hash_table;
}

void free_hash_table(HashTable* hash_table) {
    if (!hash_table) return;

    for (size_t i = 0; i < hash_table->size; ++i) {
        HashNode* node = hash_table->buckets[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(hash_table->buckets);
    free(hash_table);
}

unsigned long hash_function(long key, size_t table_size) {
    return (unsigned long)(key % table_size);
}

void insert_into_hash_table(HashTable* hash_table, LogEntry entry) {
    unsigned long index = hash_function(entry.timestamp, hash_table->size);
    HashNode* new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        perror("Failed to allocate memory for hash node");
        return;
    }

    new_node->key = entry.timestamp;
    new_node->log_entry = entry;
    new_node->next = hash_table->buckets[index];
    hash_table->buckets[index] = new_node;

    // Check load factor and resize if necessary
    size_t element_count = 0;
    for (size_t i = 0; i < hash_table->size; ++i) {
        HashNode* node = hash_table->buckets[i];
        while (node) {
            ++element_count;
            node = node->next;
        }
    }

    if ((double)element_count / hash_table->size > hash_table->load_factor) {
        resize_hash_table(&hash_table);
    }
}

LogEntry* find_in_hash_table(HashTable* hash_table, long timestamp) {
    unsigned long index = hash_function(timestamp, hash_table->size);
    HashNode* node = hash_table->buckets[index];

    while (node) {
        if (node->key == timestamp) {
            return &node->log_entry;
        }
        node = node->next;
    }

    return NULL;
}

void resize_hash_table(HashTable** hash_table_ptr) {
    HashTable* old_hash_table = *hash_table_ptr;
    size_t new_size = old_hash_table->size * 2;

    HashTable* new_hash_table = init_hash_table(new_size);
    if (!new_hash_table) {
        perror("Failed to resize hash table");
        return;
    }

    for (size_t i = 0; i < old_hash_table->size; ++i) {
        HashNode* node = old_hash_table->buckets[i];
        while (node) {
            insert_into_hash_table(new_hash_table, node->log_entry);
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(old_hash_table->buckets);
    *hash_table_ptr = new_hash_table;
}
