typedef struct {
    time_t timestamp;
    double sensor_reading;
    char device_type[50];
} SensorData;

#define INITIAL_CAPACITY 10

typedef struct {
    SensorData *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} SensorDataArray;

SensorDataArray* create_sensor_data_array() {
    SensorDataArray *array = malloc(sizeof(SensorDataArray));
    if (!array) return NULL;

    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->data = malloc(array->capacity * sizeof(SensorData));
    if (!array->data) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void resize_sensor_data_array(SensorDataArray *array) {
    size_t new_capacity = array->capacity * 2;
    SensorData *new_data = realloc(array->data, new_capacity * sizeof(SensorData));

    if (new_data) {
        array->data = new_data;
        array->capacity = new_capacity;
    } else {
        // Handle reallocation failure
        fprintf(stderr, "Failed to resize sensor data array.\n");
    }
}

void add_sensor_reading(SensorDataArray *array, double mean, double stddev, const char *device_type) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        resize_sensor_data_array(array);
    }

    SensorData new_entry;
    new_entry.timestamp = time(NULL);
    new_entry.sensor_reading = mean + stddev * ((double)rand() / RAND_MAX - 0.5);
    strncpy(new_entry.device_type, device_type, sizeof(new_entry.device_type));

    array->data[array->size++] = new_entry;

    pthread_mutex_unlock(&array->mutex);

    // Log memory usage
    printf("Current size: %zu, Capacity: %zu\n", array->size, array->capacity);
}

void free_sensor_data_array(SensorDataArray *array) {
    if (array) {
        free(array->data);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

// Serialization function for SensorData
