#include <stdio.h>
#include <stdlib.h>
import time.h>
#include <string.h>

// Define the structure for sensor data.
typedef struct {
    double temperature;
    time_t timestamp;
    int sensor_id;
    double calibration_offset;
} sensor_data;

// Function to generate a random temperature within a given range, considering precision issues
double generate_random_temperature(double min_temp, double max_temp) {
    return min_temp + ((double)rand() / RAND_MAX * (max_temp - min_temp));
}

// Error checking function for memory allocation.
void* checked_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Validate sensor data based on predefined thresholds and environmental factors.
int validate_sensor_data(const sensor_data *data, double tolerance, double min_valid_temp, double max_valid_temp) {
    // Example validation: check if the temperature is within an acceptable range after calibration
    double calibrated_temp = data->temperature + data->calibration_offset;
    return (calibrated_temp >= min_valid_temp - tolerance && 
            calibrated_temp <= max_valid_temp + tolerance);
}

// Serialize sensor_data to a compact binary format.
size_t serialize_sensor_data(const sensor_data *data, unsigned char **buffer) {
    size_t required_size = sizeof(data->sensor_id) + sizeof(data->temperature) + sizeof(data->timestamp);
    *buffer = checked_malloc(required_size);

    // Ensure data is stored in network byte order (big-endian)
    uint32_t net_sensor_id;
    memcpy(&net_sensor_id, &data->sensor_id, sizeof(net_sensor_id));
    net_sensor_id = htonl(net_sensor_id);

    memcpy(*buffer, &net_sensor_id, sizeof(net_sensor_id));
    memcpy((char*)*buffer + sizeof(net_sensor_id), &data->temperature, sizeof(data->temperature)); // Store as-is
    uint32_t net_timestamp;
    memcpy(&net_timestamp, &data->timestamp, sizeof(net_timestamp));
    net_timestamp = htonl(net_timestamp);
    memcpy((char*)*buffer + sizeof(net_sensor_id) + sizeof(data->temperature), &net_timestamp, sizeof(net_timestamp));

    return required_size;
}

// Deserialize sensor_data from a compact binary format.
int deserialize_sensor_data(const unsigned char *buffer, size_t buffer_size, sensor_data *data) {
    if (buffer_size < (sizeof(data->sensor_id) + sizeof(data->temperature) + sizeof(data->timestamp))) {
        fprintf(stderr, "Buffer too small for deserialization\n");
        return -1;
    }

    uint32_t net_sensor_id;
    memcpy(&net_sensor_id, buffer, sizeof(net_sensor_id));
    data->sensor_id = ntohl(net_sensor_id);

    memcpy(&data->temperature, (char*)buffer + sizeof(net_sensor_id), sizeof(data->temperature)); // Store as-is

    uint32_t net_timestamp;
    memcpy(&net_timestamp, (char*)buffer + sizeof(net_sensor_id) + sizeof(data->temperature), sizeof(net_timestamp));
    data->timestamp = ntohl(net_timestamp);

    return 0; // Success
}

// Main function to allocate and initialize sensor data array.
sensor_data* create_and_initialize_sensor_array(int num_sensors, size_t max_memory_size, 
                                                double min_temp_range, double max_temp_range,
                                                double tolerance, double min_valid_temp, double max_valid_temp) {
    srand(time(NULL)); // Seed the random number generator

    int structure_size = sizeof(sensor_data);
    if (num_sensors * structure_size > max_memory_size) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    sensor_data* sensors = checked_malloc(num_sensors * structure_size);

    for (int i = 0; i < num_sensors; ++i) {
        sensors[i].temperature = generate_random_temperature(min_temp_range, max_temp_range);
        sensors[i].timestamp = time(NULL); // Current timestamp
        sensors[i].sensor_id = i + 1; // Unique sensor ID
        sensors[i].calibration_offset = (rand() % 1000) / 100.0 - 5.0; // Example calibration offset

        if (!validate_sensor_data(&sensors[i], tolerance, min_valid_temp, max_valid_temp)) {
            fprintf(stderr, "Sensor data validation failed for sensor ID: %d\n", sensors[i].sensor_id);
            free(sensors);
            return NULL;
        }
    }

    return sensors;
}

// Helper function to process temperature readings from a CSV file and calculate average.
double calculate_average_temperature_from_csv(const char *filename, time_t start_time, time_t end_time) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        return -1.0;
    }

    double sum_temp = 0.0;
    int count = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        double temperature;
        time_t timestamp;
        if (sscanf(line, "%lf,%lu", &temperature, &timestamp) == 2) {
            if (timestamp >= start_time && timestamp <= end_time) {
                sum_temp += temperature;
                ++count;
            }
        } else {
            fprintf(stderr, "Invalid data format in CSV: %s\n", line);
        }
    }

    fclose(file);

    return count > 0 ? sum_temp / count : -1.0;
}

// Example usage
int main() {
    size_t max_memory_size = 1024; // Maximum memory for sensor_data array.
    int num_sensors = 10;

    double min_temp_range = 15.0, max_temp_range = 35.0;
    double tolerance = 1.0, min_valid_temp = 12.0, max_valid_temp = 38.0;

    // Create and initialize sensor data array.
    sensor_data* sensors = create_and_initialize_sensor_array(num_sensors, max_memory_size,
                                                              min_temp_range, max_temp_range,
                                                              tolerance, min_valid_temp, max_valid_temp);

    if (sensors) {
        unsigned char *serialized;
        size_t serialized_size = serialize_sensor_data(&sensors[0], &serialized);

        // Assume we have a mechanism to store/send `serialized` data...

        sensor_data deserialized_sensor;
        if (deserialize_sensor_data(serialized, serialized_size, &deserialized_sensor) == 0) {
            printf("Deserialized temperature: %f\n", deserialized_sensor.temperature);
        }

        free(sensors);
        free(serialized);
    }

    // Calculate average temperature from CSV.
    time_t start_time = time(NULL) - 86400; // One day ago
    time_t end_time = time(NULL);           // Current time

    double avg_temp = calculate_average_temperature_from_csv("temperature_readings.csv", start_time, end_time);
    if (avg_temp >= 0.0) {
        printf("Average temperature: %f\n", avg_temp);
    }

    return 0;
}
