#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char *buffer;
} record;

int allocate_records(record **records, size_t num_records, size_t max_memory_kb,
                     int rand_min, int rand_max, unsigned int seed,
                     const char *(*get_key_string)(int)) {

    if (num_records == 0 || get_key_string == NULL) return -1;

    srand(seed);
    size_t max_memory_bytes = max_memory_kb * 1024;
    size_t total_allocated = 0;

    records[0] = calloc(num_records, sizeof(record));
    if (!records[0]) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        const char *key_string = get_key_string(i);
        size_t buffer_length = strlen(key_string) + 1;

        if (total_allocated + sizeof(record) + buffer_length > max_memory_bytes) {
            fprintf(stderr, "Exceeded maximum memory limit.\n");
            goto cleanup;
        }

        (*records)[i].offset = i; // Example offset assignment
        (*records)[i].key = rand() % (rand_max - rand_min + 1) + rand_min;

        char *buffer = malloc(buffer_length);
        if (!buffer) {
            fprintf(stderr, "Memory allocation failed for buffer.\n");
            goto cleanup;
        }

        strcpy(buffer, key_string);
        (*records)[i].buffer = buffer;

        total_allocated += sizeof(record) + buffer_length;
    }

    return 0;

cleanup:
    for (size_t i = 0; i < num_records && records[0]; ++i) {
        free(records[0][i].buffer);
    }
    free(*records);
    *records = NULL;
    return -1;
}
```

### Key Points
- **Dynamic Memory Allocation**: Allocates memory for `record` structures and their buffers dynamically.
- **Memory Limits**: Ensures that the total allocated memory does not exceed a given limit.
- **Random Initialization**: Initializes integer keys using a random number generator seeded by a user-provided value.
- **Error Handling**: Includes checks for allocation failures, reverting changes if necessary.
- **Resource Management**: Properly frees resources in case of errors to prevent leaks.']

