#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
    struct record* next;
} Record;

typedef struct node {
    long offset;
    int key;
    Record* data_head;
} Node;

#define LOG(fmt, ...) printf("[LOG] " fmt "\n", ##__VA_ARGS__)

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(size_t size) {
    LOG("Allocated memory: %zu bytes", size);
}

void free_list(Node* head) {
    pthread_mutex_lock(&mutex);

    Node* current = head;
    while (current != NULL) {
        Record* record = current->data_head;
        while (record != NULL) {
            Record* temp = record;
            record = record->next;
            free(temp);
        }
        Node* node_to_free = current;
        current = current->next;
        free(node_to_free);
    }

    pthread_mutex_unlock(&mutex);
}

Node* create_node(long offset, int key, int min_val, int max_val) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        LOG("Failed to allocate memory for node");
        return NULL;
    }

    new_node->offset = offset;
    new_node->key = key;

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        free(new_node);
        LOG("Failed to allocate memory for record");
        return NULL;
    }

    new_record->value = rand() % (max_val - min_val + 1) + min_val;
    new_record->next = NULL;

    new_node->data_head = new_record;

    log_memory_usage(sizeof(Node) + sizeof(Record));

    return new_node;
}

Node* init_linked_list(size_t count, int min_val, int max_val) {
    pthread_mutex_lock(&mutex);

    Node* head = NULL;
    Node** ptr = &head;

    for (size_t i = 0; i < count; ++i) {
        *ptr = create_node(rand(), rand(), min_val, max_val);
        if (!(*ptr)) {
            LOG("Failed to add node %zu", i);
            free_list(head);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        ptr = &((*ptr)->next);
    }

    pthread_mutex_unlock(&mutex);

    return head;
}

int main() {
    srand(time(NULL));

    int min_val = 1, max_val = 100;
    size_t node_count = 10;

    Node* list_head = init_linked_list(node_count, min_val, max_val);

    if (list_head) {
        LOG("Linked list created with %zu nodes", node_count);

        // Example traversal and usage
        for (Node* current = list_head; current != NULL; current = current->next) {
            printf("Key: %d, Offset: %ld, Record Value: %d\n", 
                   current->key, current->offset, current->data_head->value);
        }

        // Cleanup
        free_list(list_head);
    } else {
        LOG("Failed to create linked list");
    }

    return 0;
}
