#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_NAME_LENGTH 100

typedef struct Transaction {
    int transaction_id;
    double amount;
    time_t timestamp;
    struct Transaction* next;
} Transaction;

typedef struct Customer {
    char name[MAX_NAME_LENGTH];
    int age;
    Transaction* transactions_head;
    pthread_mutex_t lock; // For thread-safe operations
} Customer;

size_t get_memory_footprint(Customer* customer) {
    size_t size = sizeof(*customer);
    for (Transaction* t = customer->transactions_head; t != NULL; t = t->next) {
        size += sizeof(*t);
    }
    return size;
}

void add_transaction(Customer* customer, double amount, int transaction_id) {
    Transaction* new_transaction = (Transaction*)malloc(sizeof(Transaction));
    if (!new_transaction) {
        fprintf(stderr, "Memory allocation failed for transaction.\n");
        exit(EXIT_FAILURE);
    }

    new_transaction->transaction_id = transaction_id;
    new_transaction->amount = amount;
    new_transaction->timestamp = time(NULL);

    pthread_mutex_lock(&customer->lock);
    new_transaction->next = customer->transactions_head;
    customer->transactions_head = new_transaction;
    pthread_mutex_unlock(&customer->lock);
}

Customer* create_customer(const char* name, int age, size_t max_memory_usage) {
    Customer* customer = (Customer*)malloc(sizeof(Customer));
    if (!customer) {
        fprintf(stderr, "Memory allocation failed for customer.\n");
        exit(EXIT_FAILURE);
    }

    strncpy(customer->name, name, MAX_NAME_LENGTH - 1);
    customer->age = age;
    customer->transactions_head = NULL;

    pthread_mutex_init(&customer->lock, NULL);

    // Check memory usage
    if (get_memory_footprint(customer) > max_memory_usage) {
        fprintf(stderr, "Memory limit exceeded while creating a new customer.\n");
        free(customer);
        exit(EXIT_FAILURE);
    }

    return customer;
}

void manage_customers(const char* seed_str, double amount_range_min, 
                      double amount_range_max, size_t max_memory_limit_mb) {

    srand(time(NULL)); // Initialize random number generator with current time

    const long MB_TO_BYTES = 1024 * 1024;
    size_t max_memory_limit_bytes = max_memory_limit_mb * MB_TO_BYTES;

    pthread_mutex_t customers_lock = PTHREAD_MUTEX_INITIALIZER; // To handle concurrent access
    Customer* customer_list_head = NULL;

    int transaction_id_counter = 1;

    while (true) { // Replace with a proper condition in real use-case

        double amount = ((double)rand() / RAND_MAX) * (amount_range_max - amount_range_min) + amount_range_min;

        pthread_mutex_lock(&customers_lock);

        if (get_memory_footprint(customer_list_head) + sizeof(Customer) <= max_memory_limit_bytes) {
            Customer* new_customer = create_customer("John Doe", 30, max_memory_limit_bytes);
            add_transaction(new_customer, amount, transaction_id_counter++);

            // Link the new customer into our list
            new_customer->next = customer_list_head;
            customer_list_head = new_customer;

        } else {
            fprintf(stderr, "Max memory limit reached. Cannot create more customers.\n");
        }

        pthread_mutex_unlock(&customers_lock);

        sleep(1); // Simulating time gap between operations, replace as needed
    }
}

void cleanup_customers(Customer* head) {
    while (head != NULL) {
        Customer* next_customer = head->next;

        Transaction* transaction = head->transactions_head;
        while (transaction != NULL) {
            Transaction* temp_transaction = transaction;
            transaction = transaction->next;
            free(temp_transaction);
        }

        pthread_mutex_destroy(&head->lock);

        free(head);
        head = next_customer;
    }
}

int main() {
    size_t max_memory_limit_mb = 10; // Max memory in MB
    manage_customers("seed_string", 100.0, 500.0, max_memory_limit_mb);

    return 0;
}
```

### Documentation and Assumptions:

1. **Concurrency Handling**: The function uses mutex locks to handle concurrent access to shared resources (`customer_list_head` and individual customer transactions). This is critical for avoiding race conditions when multiple threads might attempt to modify the same data.

2. **Memory Management**: The memory footprint of each customer and their transactions are continually monitored to ensure that total usage does not exceed a specified limit in megabytes, which helps prevent exceeding system limits and crashing due to out-of-memory errors.

3. **Error Handling**: If memory allocation fails or if attempting to create more customers exceeds the memory limit, the function prints an error message and exits gracefully.

4. **Performance Considerations**: By using mutex locks and sleeping between iterations (simulating time gaps), we can manage system responsiveness while handling dynamic allocations frequently.

5. **System Limitations**: Assumes adequate system resources are available for the program's execution with a defined maximum memory limit to prevent excessive usage that could impact other processes on the system.

6. **Cleanup**: Ensure proper deallocation of all allocated memory before the function exits to prevent memory leaks, which is crucial in long-running or heavily iterative programs like this one.

7. **Randomization Seed**: The seed for random number generation should ideally be managed based on more robust strategies (like `srand48` with a better-defined seed) rather than just system time when precise reproducibility is required across runs.

8. **Scalability**: For high scalability, consider using memory pools to reduce frequent allocation/deallocation overhead and improve transaction performance under peak loads.']

