#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_KB 1024 // Maximum memory limit in kilobytes

typedef struct {
    int id;
    double value;
    char *name;
} Record;

typedef struct {
    long *longArray;
    int *intArray;
    double *doubleArray;
    Record **records;
    size_t recordCount;
    pthread_mutex_t lock;
} DataHolder;

void seedRandom(int seed) {
    srand(seed);
}

int allocateMemory(DataHolder *data, size_t numLongs, size_t numInts, size_t numDoubles, size_t numRecords, int rangeMin, int rangeMax) {
    size_t totalSize = 0;
    const size_t KB = 1024;

    pthread_mutex_init(&data->lock, NULL);
    data->longArray = (long *)malloc(numLongs * sizeof(long));
    if (!data->longArray) return -1;
    totalSize += numLongs * sizeof(long);

    data->intArray = (int *)malloc(numInts * sizeof(int));
    if (!data->intArray) {
        free(data->longArray);
        return -1;
    }
    totalSize += numInts * sizeof(int);

    data->doubleArray = (double *)malloc(numDoubles * sizeof(double));
    if (!data->doubleArray) {
        free(data->longArray);
        free(data->intArray);
        return -1;
    }
    totalSize += numDoubles * sizeof(double);

    data->records = (Record **)malloc(numRecords * sizeof(Record *));
    if (!data->records) {
        free(data->longArray);
        free(data->intArray);
        free(data->doubleArray);
        return -1;
    }
    totalSize += numRecords * sizeof(Record *);

    for (size_t i = 0; i < numRecords; ++i) {
        data->records[i] = (Record *)malloc(sizeof(Record));
        if (!data->records[i]) {
            for (size_t j = 0; j <= i; ++j) free(data->records[j]);
            free(data->longArray);
            free(data->intArray);
            free(data->doubleArray);
            free(data->records);
            return -1;
        }
        totalSize += sizeof(Record);

        data->records[i]->id = rangeMin + rand() % (rangeMax - rangeMin + 1);
        data->records[i]->value = rand() / (RAND_MAX + 1.0); // Random double between 0 and 1

        char nameBuffer[32];
        snprintf(nameBuffer, sizeof(nameBuffer), "Record_%zu", i);
        size_t nameLen = strlen(nameBuffer) + 1;
        data->records[i]->name = (char *)malloc(nameLen);
        if (!data->records[i]->name) {
            for (size_t j = 0; j <= i; ++j) free(data->records[j]);
            free(data->longArray);
            free(data->intArray);
            free(data->doubleArray);
            free(data->records);
            return -1;
        }
        strcpy(data->records[i]->name, nameBuffer);
        totalSize += nameLen;
    }

    if (totalSize > MAX_MEMORY_KB * KB) {
        for (size_t i = 0; i < numRecords; ++i) {
            free(data->records[i]);
        }
        free(data->longArray);
        free(data->intArray);
        free(data->doubleArray);
        free(data->records);
        return -1;
    }

    data->recordCount = numRecords;
    return 0;
}

void freeMemory(DataHolder *data) {
    pthread_mutex_lock(&data->lock);

    for (size_t i = 0; i < data->recordCount; ++i) {
        free(data->records[i]->name);
        free(data->records[i]);
    }
    free(data->longArray);
    free(data->intArray);
    free(data->doubleArray);
    free(data->records);

    pthread_mutex_unlock(&data->lock);
    pthread_mutex_destroy(&data->lock);
}

void serializeData(const DataHolder *data, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&data->recordCount, sizeof(size_t), 1, file);

    for (size_t i = 0; i < data->recordCount; ++i) {
        fwrite(data->records[i]->id, sizeof(int), 1, file);
        fwrite(data->records[i]->value, sizeof(double), 1, file);
        size_t nameLen = strlen(data->records[i]->name) + 1;
        fwrite(&nameLen, sizeof(size_t), 1, file);
        fwrite(data->records[i]->name, sizeof(char), nameLen, file);
    }

    fclose(file);
}

int deserializeData(DataHolder *data, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t recordCount;
    fread(&recordCount, sizeof(size_t), 1, file);

    if (allocateMemory(data, 0, 0, 0, recordCount, 0, 0) != 0) {
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < data->recordCount; ++i) {
        fread(&data->records[i]->id, sizeof(int), 1, file);
        fread(&data->records[i]->value, sizeof(double), 1, file);

        size_t nameLen;
        fread(&nameLen, sizeof(size_t), 1, file);

        data->records[i]->name = (char *)malloc(nameLen);
        if (!data->records[i]->name) {
            freeMemory(data);
            fclose(file);
            return -1;
        }

        fread(data->records[i]->name, sizeof(char), nameLen, file);
    }

    fclose(file);
    return 0;
}

int main() {
    DataHolder data;
    int status = allocateMemory(&data, 10, 20, 30, 5, 1, 100);

    if (status == 0) {
        printf("Memory allocated successfully.\n");

        serializeData(&data, "data.bin");

        DataHolder newData;
        status = deserializeData(&newData, "data.bin");

        if (status == 0) {
            printf("Data deserialized successfully.\n");
        }

        freeMemory(&data);
        freeMemory(&newData);
    } else {
        fprintf(stderr, "Failed to allocate memory.\n");
    }

    return status;
}
```

