#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_TABLE_SIZE 16

typedef struct Node {
    int key;
    long offset;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t size;
    pthread_rwlock_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(initial_size, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = initial_size;
    pthread_rwlock_init(&table->lock, NULL);

    return table;
}

unsigned long hash(int key, size_t size) {
    return (unsigned long)key % size;
}

int insert(HashTable* table, int key, long offset) {
    if (!table) return -1;

    pthread_rwlock_wrlock(&table->lock);
    unsigned long index = hash(key, table->size);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_rwlock_unlock(&table->lock);
        return -2;
    }
    new_node->key = key;
    new_node->offset = offset;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_rwlock_unlock(&table->lock);
    return 0;
}

long* retrieve(HashTable* table, int key) {
    if (!table) return NULL;

    pthread_rwlock_rdlock(&table->lock);
    unsigned long index = hash(key, table->size);

    Node* node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            pthread_rwlock_unlock(&table->lock);
            return &node->offset;
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&table->lock);
    return NULL;
}

void resize_table(HashTable* table) {
    size_t new_size = table->size * 2;
    Node** new_buckets = (Node**)calloc(new_size, sizeof(Node*));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            unsigned long new_index = hash(node->key, new_size);
            Node* next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

void free_hash_table(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_rwlock_destroy(&table->lock);
    free(table);
}

void handle_market_data_feed(HashTable* table, int key, long offset) {
    // Simulate market data feed update
    if (insert(table, key, offset) != 0) {
        printf("Error inserting data for key %d\n", key);
    }
}

int main() {
    HashTable* table = create_hash_table(INITIAL_TABLE_SIZE);
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return EXIT_FAILURE;
    }

    handle_market_data_feed(table, 1, 100L);
    long* offset = retrieve(table, 1);
    if (offset) {
        printf("Offset for key 1: %ld\n", *offset);
    } else {
        printf("Key not found\n");
    }

    free_hash_table(table);

    return EXIT_SUCCESS;
}
```

This code defines a hash table with chaining for collision resolution and uses read-write locks to handle concurrency. It includes functions for creating, inserting, retrieving, resizing, and freeing the hash table. The `handle_market_data_feed` function simulates updates from an external market data feed.']

