    *size += 1;
    *array = realloc(*array, (*size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        perror("Failed to allocate memory");
        *size -= 1; // Rollback size change
        exit(EXIT_FAILURE);
