    NFAPI_CRC_INDICATION_PDU_T *temp = malloc((*size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (temp == NULL) {
        free(*array);
        fprintf(stderr, "Failed to allocate temporary memory\n");
        exit(EXIT_FAILURE);
    }

    memcpy(temp, *array, (*size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int i;
    for (i = 0; i < *size - 1; ++i) {
        if ((*array)[i].RNTI > new_pdu->RNTI) break;
    }

    memmove(&temp[i + 1], &temp[i], (*size - 1 - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    temp[i] = *new_pdu;

    free(*array);
    *array = temp;
}

