#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>

typedef struct {
    int value;
} record;

#define MEMORY_THRESHOLD 1024 * 1024 // 1 MB for example

static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static void* cached_memory = NULL;
static size_t cached_size = 0;

int is_power_of_two(size_t n) {
    return (n != 0) && ((n & (n - 1)) == 0);
}

void log_allocation(const char* message, size_t size) {
    printf("LOG: %s of size %zu\n", message, size);
}

void* allocate_memory(size_t size) {
    if (cached_memory && cached_size >= size) {
        pthread_mutex_lock(&cache_lock);
        void* memory = cached_memory;
        cached_memory = NULL; // Clear the cache
        cached_size = 0;
        pthread_mutex_unlock(&cache_lock);
        log_allocation("Reused from cache", size);
        return memory;
    }

    if (size > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory allocation exceeds threshold\n");
        return NULL;
    }

    void* memory = malloc(size);
    log_allocation("Allocated new memory", size);

    pthread_mutex_lock(&cache_lock);
    cached_memory = memory;
    cached_size = size;
    pthread_mutex_unlock(&cache_lock);

    return memory;
}

void free_memory(void* ptr, size_t size) {
    log_allocation("Freed memory", size);
    if (ptr != NULL) {
        pthread_mutex_lock(&cache_lock);
        cached_memory = realloc(cached_memory, cached_size + size);
        memcpy((char*)cached_memory + cached_size, ptr, size);
        cached_size += size;
        pthread_mutex_unlock(&cache_lock);
        free(ptr);
    }
}

int initialize_records(size_t initial_size) {
    if (!is_power_of_two(initial_size)) {
        fprintf(stderr, "Size must be a power of two\n");
        return -1;
    }

    long* offsets = (long*)allocate_memory(initial_size * sizeof(long));
    int* keys = (int*)allocate_memory(initial_size * sizeof(int));
    record* records = (record*)allocate_memory(initial_size * sizeof(record));

    if (!offsets || !keys || !records) {
        free_memory(offsets, initial_size * sizeof(long));
        free_memory(keys, initial_size * sizeof(int));
        free_memory(records, initial_size * sizeof(record));
        return -1;
    }

    pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

    void* init_records(void* arg) {
        size_t index = *(size_t*)arg;
        pthread_mutex_lock(&records_lock);
        records[index].value = (int)index; // Example initialization
        pthread_mutex_unlock(&records_lock);
        return NULL;
    }

    size_t num_threads = 4;
    pthread_t threads[num_threads];
    for (size_t i = 0; i < initial_size; ++i) {
        if (i % num_threads == 0 && i != 0) {
            // Wait for all threads to finish before resizing
            for (size_t j = 0; j < num_threads; ++j) {
                pthread_join(threads[j], NULL);
            }
        }

        size_t index = i;
        if (pthread_create(&threads[i % num_threads], NULL, init_records, &index)) {
            fprintf(stderr, "Error creating thread\n");
            free_memory(offsets, initial_size * sizeof(long));
            free_memory(keys, initial_size * sizeof(int));
            free_memory(records, initial_size * sizeof(record));
            pthread_mutex_destroy(&records_lock);
            return -1;
        }
    }

    for (size_t j = 0; j < num_threads; ++j) {
        pthread_join(threads[j], NULL);
    }

    pthread_mutex_destroy(&records_lock);

    // Example dynamic resizing logic
    size_t required_size = initial_size * 2; // Placeholder for actual requirement check
    if (!is_power_of_two(required_size)) {
        required_size = pow(2, ceil(log2((double)required_size)));
    }

    record* new_records = (record*)allocate_memory(required_size * sizeof(record));
    if (!new_records) {
        free_memory(offsets, initial_size * sizeof(long));
        free_memory(keys, initial_size * sizeof(int));
        free_memory(records, initial_size * sizeof(record));
        return -1;
    }

    memcpy(new_records, records, initial_size * sizeof(record));
    free_memory(records, initial_size * sizeof(record));
    records = new_records;

    // Finalize and free resources
    free_memory(offsets, initial_size * sizeof(long));
    free_memory(keys, initial_size * sizeof(int));

    return (int)required_size;
}
