```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned long *timestamps;
    char **data_packets;
    int *sequence_numbers;
    size_t timestamp_count;
    size_t data_packet_count;
    size_t sequence_number_count;
    pthread_mutex_t lock;
} MessageManager;

#define INITIAL_HASH_TABLE_SIZE 128
#define LOAD_FACTOR 0.75

typedef struct HashNode {
    char *key;
    unsigned long value;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

MessageManager* create_message_manager(size_t timestamp_count, size_t data_packet_count, size_t sequence_number_count) {
    MessageManager *manager = (MessageManager*)malloc(sizeof(MessageManager));
    if (!manager) return NULL;

    manager->timestamps = (unsigned long *)aligned_alloc(32, timestamp_count * sizeof(unsigned long));
    manager->data_packets = (char **)aligned_alloc(32, data_packet_count * sizeof(char*));
    manager->sequence_numbers = (int *)aligned_alloc(32, sequence_number_count * sizeof(int));

    if (!manager->timestamps || !manager->data_packets || !manager->sequence_numbers) {
        free(manager->timestamps);
        free(manager->data_packets);
        free(manager->sequence_numbers);
        free(manager);
        return NULL;
    }

    manager->timestamp_count = timestamp_count;
    manager->data_packet_count = data_packet_count;
    manager->sequence_number_count = sequence_number_count;

    pthread_mutex_init(&manager->lock, NULL);

    memset(manager->timestamps, 0, timestamp_count * sizeof(unsigned long));
    for (size_t i = 0; i < data_packet_count; ++i) {
        manager->data_packets[i] = NULL;
    }
    memset(manager->sequence_numbers, 0, sequence_number_count * sizeof(int));

    return manager;
}

void free_message_manager(MessageManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->data_packet_count; ++i) {
        free(manager->data_packets[i]);
    }

    pthread_mutex_unlock(&manager->lock);

    free(manager->timestamps);
    free(manager->data_packets);
    free(manager->sequence_numbers);
    pthread_mutex_destroy(&manager->lock);

    free(manager);
}

unsigned long hash_function(const char *key, size_t table_size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % table_size;
}

HashTable* create_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = INITIAL_HASH_TABLE_SIZE;
    table->count = 0;
    table->buckets = (HashNode**)calloc(table->size, sizeof(HashNode*));

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void free_hash_table(HashTable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *next = node->next;
            free(node->key);
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&table->lock);

    free(table->buckets);
    free(table);
}

int hash_table_insert(HashTable *table, const char *key, unsigned long value) {
    if (!table || !key) return -1;

    pthread_mutex_lock(&table->lock);

    if ((double)table->count / table->size > LOAD_FACTOR) {
        size_t new_size = 2 * table->size;
        HashNode **new_buckets = (HashNode**)calloc(new_size, sizeof(HashNode*));

        for (size_t i = 0; i < table->size; ++i) {
            HashNode *node = table->buckets[i];
            while (node) {
                size_t index = hash_function(node->key, new_size);
                HashNode *next_node = node->next;

                node->next = new_buckets[index];
                new_buckets[index] = node;

                node = next_node;
            }
        }

        free(table->buckets);
        table->size = new_size;
        table->buckets = new_buckets;
    }

    size_t index = hash_function(key, table->size);
    HashNode *node = (HashNode*)malloc(sizeof(HashNode));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    node->key = strdup(key);
    node->value = value;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    ++table->count;

    pthread_mutex_unlock(&table->lock);

    return 0;
}

unsigned long hash_table_get(HashTable *table, const char *key) {
    if (!table || !key) return (unsigned long)-1;

    size_t index = hash_function(key, table->size);
    HashNode *node = table->buckets[index];

    while (node) {
        if (strcmp(node->key, key) == 0)
            return node->value;
        node = node->next;
    }

    return (unsigned long)-1;
}

void integrate_external_data_feed(MessageManager *manager, const char **data_feed, size_t feed_size) {
