        return -1;
    }

    HashTable *hash_table = create_hash_table();
    if (!hash_table) {
        free_message_manager(manager);
        fprintf(stderr, "Failed to create hash table\n");
        return -1;
    }

    const char *example_packet = "data_packet_123";
    hash_table_insert(hash_table, example_packet, 1627843200);

    unsigned long timestamp = hash_table_get(hash_table, example_packet);
