record* allocate_memory(MemoryManager *manager, size_t record_count, size_t max_size) {
    pthread_mutex_lock(&manager->lock);

    size_t required_size = sizeof(record) * record_count;
    if (required_size > max_size || manager->allocated_size + required_size > MAX_MEMORY_LIMIT) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    record* new_records = (record*)malloc(required_size);
    if (!new_records) {
        pthread_mutex_unlock(&manager->lock);
        log_message("Memory allocation failed.", 1);
        return NULL;
    }

    manager->allocated_size += required_size;

    for (size_t i = 0; i < record_count; ++i) {
        int random_value = rand() % INT_MAX; // Random within range
        new_records[i].value = random_value;
        new_records[i].offset = ((long)i * sizeof(record)) + manager->allocated_size;

        char log_buffer[256];
        snprintf(log_buffer, 256, "Record %zu: Value=%d, Offset=%ld", i, random_value, new_records[i].offset);
