// Serialize and deserialize functions for config
size_t serialize_config(config *cfg, uint8_t **buffer) {
    size_t name_len = strlen(cfg->config_name);
    size_t total_size = sizeof(double) + sizeof(time_t) + 1 + name_len;

    *buffer = (uint8_t *)malloc(total_size);
    if (!*buffer) return 0;

    uint8_t *ptr = *buffer;
    memcpy(ptr, &(cfg->metric), sizeof(double));
    ptr += sizeof(double);
    memcpy(ptr, &(cfg->timestamp), sizeof(time_t));
    ptr += sizeof(time_t);
    *ptr++ = (uint8_t)name_len;
    memcpy(ptr, cfg->config_name, name_len);

    return total_size;
}

size_t deserialize_config(uint8_t *buffer, config **cfg) {
    if (!buffer || !cfg) return 0;

    size_t total_size = sizeof(double) + sizeof(time_t) + 1; // excluding name length
    uint8_t name_len = buffer[total_size];
    total_size += name_len + 1;

    *cfg = (config *)malloc(total_size);
    if (!*cfg) return 0;

    config *deserialized_cfg = *cfg;
    deserialized_cfg->metric = *(double *)(buffer);
    deserialized_cfg->timestamp = *(time_t *)(buffer + sizeof(double));
    deserialized_cfg->config_name = (char *)(buffer + total_size - name_len - 1);

    return total_size;
}

// Main function to initialize array of config structures
config *initialize_config_array(size_t count, double range_min, double range_max, size_t max_size) {
    if (count == 0 || max_size < sizeof(config)) return NULL;

    srand((unsigned int)time(NULL));

    size_t total_memory = count * sizeof(config);
    if (total_memory > max_size) return NULL;

    config *configs = (config *)malloc(total_memory);
    if (!configs) return NULL;

    for (size_t i = 0; i < count; ++i) {
        configs[i].metric = range_min + ((double)rand() / RAND_MAX) * (range_max - range_min);

        time(&configs[i].timestamp);

        size_t name_length = rand() % 20 + 1;
        char *name = (char *)malloc(name_length + 1);
        if (!name) {
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) free(configs[j].config_name);
            free(configs);
            return NULL;
        }
        generate_random_string(name, name_length, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz");
        configs[i].config_name = name;
    }

    return configs;
}

// Function to free allocated memory for config array
void free_config_array(config *configs, size_t count) {
    if (!configs) return;

    for (size_t i = 0; i < count; ++i) {
        free(configs[i].config_name);
    }
    free(configs);
}

// Main function to create and serialize NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_array(size_t count, size_t max_size) {
    if (count == 0 || max_size < sizeof(NFAPI_CRC_INDICATION_PDU_T)) return NULL;

    size_t total_memory = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_memory > max_size) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(total_memory);
    if (!pdus) return NULL;

    for (size_t i = 0; i < count; ++i) {
        pdus[i].rnti = rand() % 65536;
        pdus[i].crc_indication_rel8.crcflag = rand() % 2;
        // Initialize RX_UE_INFORMATION_TAG fields here
