#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
    char string[256];
} record;

// Helper function to generate a random string of specified length using given character set
void generate_random_string(char *buffer, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length > 0 && buffer != NULL) {
        for (size_t n = 0; n < length - 1; ++n) {
            int key = rand() % (int)(sizeof(charset) - 1);
            buffer[n] = charset[key];
        }
        buffer[length - 1] = '\0';
    }
}

// Helper function to hash a given string using a simple XOR-based hash function for demonstration
unsigned long hash_string(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

// Helper function to read integers from standard input, store them in an array and print the largest one
void find_largest_integer() {
    int size, num;
    printf("Enter number of integers: ");
    scanf("%d", &size);
    if (size <= 0) return;

    int *arr = malloc(size * sizeof(int));
    if (!arr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    printf("Enter the integers:\n");
    for (int i = 0; i < size; ++i) {
        scanf("%d", &num);
        arr[i] = num;
    }

    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    printf("Largest integer: %d\n", largest);
    free(arr);
}

// Main function to allocate and initialize an array of records
record* create_records(size_t record_count, size_t max_memory_size, int value_range_min, int value_range_max) {
    if (value_range_min > value_range_max) return NULL;

    // Seed random number generator with current time
    srand((unsigned int)time(NULL));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    record *records = NULL;

    size_t record_size = sizeof(record);
    if (record_count * record_size > max_memory_size) {
        fprintf(stderr, "Requested memory exceeds maximum allowed size.\n");
        return NULL;
    }

    records = malloc(record_count * record_size);
    if (!records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_destroy(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&mutex);

        // Set int value
        records[i].value = value_range_min + rand() % (value_range_max - value_range_min + 1);

        // Set offset to a random number within a range
        records[i].offset = rand();

        // Generate random string
        generate_random_string(records[i].string, sizeof(records[i].string));

        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
    return records;
}

// Function to serialize the record array into a byte array
size_t serialize_records(record *records, size_t record_count, unsigned char **byte_array) {
    if (!records || !byte_array) return 0;

    size_t total_size = record_count * (sizeof(int) + sizeof(long) + sizeof(char[256]));
    *byte_array = malloc(total_size);
    if (!*byte_array) {
        perror("Failed to allocate memory for serialization");
        return 0;
    }

    unsigned char *ptr = *byte_array;
    for (size_t i = 0; i < record_count; ++i) {
        // Serialize int
        memcpy(ptr, &records[i].value, sizeof(int));
        ptr += sizeof(int);

        // Serialize long
        memcpy(ptr, &records[i].offset, sizeof(long));
        ptr += sizeof(long);

        // Serialize string
        memcpy(ptr, records[i].string, sizeof(char[256]));
        ptr += sizeof(char[256]);
    }

    return total_size;
}

// Function to deserialize a byte array back into records
record* deserialize_records(size_t record_count, const unsigned char *byte_array) {
    if (!byte_array) return NULL;

    record *records = malloc(record_count * (sizeof(int) + sizeof(long) + sizeof(char[256])));
    if (!records) {
        perror("Failed to allocate memory for deserialization");
        return NULL;
    }

    const unsigned char *ptr = byte_array;
    for (size_t i = 0; i < record_count; ++i) {
        // Deserialize int
        memcpy(&records[i].value, ptr, sizeof(int));
        ptr += sizeof(int);

        // Deserialize long
        memcpy(&records[i].offset, ptr, sizeof(long));
        ptr += sizeof(long);

        // Deserialize string
        memcpy(records[i].string, ptr, sizeof(char[256]));
        ptr += sizeof(char[256]);
    }

    return records;
}

int main() {
    find_largest_integer();

    size_t record_count = 10;
    size_t max_memory_size = 1024 * 1024; // 1 MB
    int value_range_min = -1000, value_range_max = 1000;

    record *records = create_records(record_count, max_memory_size, value_range_min, value_range_max);
    if (!records) {
        fprintf(stderr, "Failed to create records.\n");
        return EXIT_FAILURE;
    }

    unsigned char *serialized_data = NULL;
    size_t serialized_size = serialize_records(records, record_count, &serialized_data);

    if (serialized_size > 0) {
        printf("Records serialized successfully. Size: %zu bytes\n", serialized_size);

        record *deserialized_records = deserialize_records(record_count, serialized_data);
        free(serialized_data);

        if (deserialized_records) {
            // Verify deserialization
            for (size_t i = 0; i < record_count; ++i) {
                printf("Record %zu: value=%d, offset=%ld, string='%s'\n",
                       i + 1,
                       deserialized_records[i].value,
                       deserialized_records[i].offset,
                       deserialized_records[i].string);
            }
            free(deserialized_records);
        } else {
            fprintf(stderr, "Failed to deserialize records.\n");
        }
    }

    free(records);

    return EXIT_SUCCESS;
}
