import requests
from requests.auth import HTTPBasicAuth
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
import time
import threading
from functools import lru_cache

class APIError(Exception):
    pass

def integrate_analytics(api_key, label, processor_func, batch_size, max_retries):
    token_url = "https://example.com/oauth/token"
    api_base_url = "https://api.example.com/engagement"

    def get_oauth_session(client_id, client_secret):
        client = BackendApplicationClient(client_id=client_id)
        oauth = OAuth2Session(client=client)
        return oauth.fetch_token(token_url=token_url, client_id=client_id, client_secret=client_secret)

    @lru_cache(maxsize=None)
    def fetch_page_data(page_number):
        headers = {'Authorization': f'Bearer {api_key}'}
        params = {'limit': batch_size, 'page': page_number}

        for attempt in range(1, max_retries + 1):
            try:
                response = requests.get(f"{api_base_url}/metrics", headers=headers, params=params)
                if response.status_code == 200:
                    return response.json()
                elif response.status_code == 429:  # Rate limit error
                    time.sleep((2 ** attempt) - 1)
                else:
                    raise APIError(response.text)
            except (requests.exceptions.RequestException, APIError) as e:
                if attempt == max_retries:
                    print(f"Max retries reached for page {page_number}. Error: {e}")
                    return None
                time.sleep((2 ** attempt) - 1)

    def process_data():
        page_number = 1
        all_processed_data = []
        while True:
            data = fetch_page_data(page_number)
            if not data or 'data' not in data:
                break

            processed_data = [processor_func(item) for item in data['data']]
            all_processed_data.extend(processed_data)

            page_number += 1
            time.sleep(0.5)  # To respect API rate limits

        return all_processed_data

    def safe_api_call():
        lock = threading.Lock()

        with lock:
            result = process_data()

        fetch_page_data.cache_clear()  # Reset cache to ensure data freshness for next calls
        return result, f"Processed {len(result)} records under operation: {label}"

    return safe_api_call()

# Example usage:
# def example_processor_func(data):
#     return {'metric': data['value'] * 2}

# results, summary = integrate_analytics(
#     api_key="your_oauth_token_here",
#     label="fetching engagement metrics",
#     processor_func=example_processor_func,
#     batch_size=100,
#     max_retries=3
# )
