        data = response.json()
        location = f"{data['city']}, {data['region']}, {data['country']}"
        geocode_cache[ip] = location
        return location
    except Exception as e:
        print(f"Error fetching geolocation for IP: {e}")
        return "Unknown"

def process_log_line(line, date_filter_start, date_filter_end):
    try:
        timestamp, user_id, event_type, ip, details = line.split(',')
        timestamp_dt = datetime.strptime(timestamp.strip(), "%Y-%m-%d %H:%M:%S")

        if date_filter_start and timestamp_dt < date_filter_start:
            return None
        if date_filter_end and timestamp_dt > date_filter_end:
            return None

        event_data = {
            'timestamp': timestamp_dt,
            'user_id': user_id.strip(),
            'event_type': event_type.strip(),
            'ip': ip.strip(),
            'details': details.strip()
        }

        if event_data['event_type'] == 'authentication':
            location = get_geolocation(event_data['ip'])
            success = "success" in event_data['details']
            return (event_data['user_id'], success, location)

    except Exception as e:
        print(f"Error processing line: {e}")
    return None

def process_log_file(file_path, date_filter_start=None, date_filter_end=None):
    results = {}
    with open(file_path, 'r') as file:
        for line in file:
            processed_line = process_log_line(line, date_filter_start, date_filter_end)
            if processed_line:
                user_id, success, location = processed_line
                if user_id not in results:
                    results[user_id] = {'success': 0, 'failed': 0, 'locations': set()}

                if success:
                    results[user_id]['success'] += 1
                else:
                    results[user_id]['failed'] += 1

                results[user_id]['locations'].add(location)

    for user in results:
        results[user]['locations'] = list(results[user]['locations'])

    return results

def merge_results(result_dict, new_data):
    for user_id, data in new_data.items():
        if user_id not in result_dict:
            result_dict[user_id] = {'success': 0, 'failed': 0, 'locations': set()}

        result_dict[user_id]['success'] += data['success']
        result_dict[user_id]['failed'] += data['failed']
        result_dict[user_id]['locations'].update(data['locations'])

    for user in result_dict:
        result_dict[user]['locations'] = list(result_dict[user]['locations'])

def process_logs_concurrently(file_paths, date_filter_start=None, date_filter_end=None):
    combined_results = {}
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(process_log_file, fp, date_filter_start, date_filter_end) for fp in file_paths]

        for future in as_completed(futures):
            try:
                result_data = future.result()
                merge_results(combined_results, result_data)
            except Exception as e:
                print(f"Error processing log file: {e}")

