    offset: i64,
    is_valid: bool,
}

impl Record {
    fn new(integer_value: i32, offset: i64) -> Self {
        Self { 
            integer_value, 
            offset, 
            is_valid: true
        }
    }
}

// Initialize records with random values.
fn initialize_records(max_memory_usage: usize, seed_range: (u32, u32)) -> Result<Vec<Record>, &'static str> {
    let record_size = std::mem::size_of::<Record>();
    if max_memory_usage < record_size {
        return Err("Insufficient memory for a single record");
    }

    let num_records = max_memory_usage / record_size;
    let mut rng = rand::thread_rng();
    let dist = Uniform::from(seed_range);

    let records: Vec<Record> = (0..num_records).map(|_| {
        let integer_value = dist.sample(&mut rng) as i32;
        let offset = rng.gen::<i64>();

        // You can implement specific logic to validate a record.
        let is_valid = offset % 2 == 0; // Example validation condition.

        Record::new(integer_value, offset)
    }).collect();

    Ok(records)
}

// Compile and analyze the Rust project.
fn compile_and_analyze(config: CompileConfig, project_dir: &str) -> Result<Output, String> {
    let start_time = Instant::now();

    // Use Cargo to update dependencies before compilation
    run_command(project_dir, "cargo", &["update"])?;

    // Compile the Rust project using Cargo
    let output = run_command(project_dir, "cargo", &["build"])?;

    let elapsed_time = start_time.elapsed();

    log_compilation_details(&config.logging_level, elapsed_time);

    Ok(output)
}

// Helper function to execute a command and handle errors.
fn run_command(dir: &str, prog: &str, args: &[&str]) -> Result<Output, String> {
    let status = Command::new(prog)
        .args(args)
        .current_dir(dir)
        .status()
        .map_err(|e| format!("Failed to execute {}: {}", prog, e))?;

    if !status.success() {
        return Err(format!("{} exited with error", prog));
    }

    Ok(Command::new(prog)
        .args(args)
        .current_dir(dir)
        .output()
        .map_err(|e| format!("Command execution failed: {:?}", e))?)
}

// Log details of the compilation.
fn log_compilation_details(logging_level: &u8, elapsed_time: Duration) {
    if *logging_level > 0 { // Adjust logging level threshold as needed
        println!(
            "Compilation completed in {:?}",
            elapsed_time
        );
    }
}

