// Define error codes for different failure points
enum ErrorCode {
    SUCCESS = 0,
    AUTHENTICATION_FAILED,
    CONFIG_RETRIEVAL_FAILED,
    DNS_RESOLUTION_FAILED,
    QUOTA_EXCEEDED,
    NETWORK_ERROR,
    INVALID_CONFIGURATION,
