import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MemoryManager {
    private static final Logger logger = Logger.getLogger(MemoryManager.class.getName());
    private double memoryLimit;
    private AtomicLong currentMemoryUsage;
    private ConcurrentHashMap<Long, String> identifierMap;
    private ConcurrentHashMap<Long, Double> doubleCollection;
    private ExternalIDService idService;

    public MemoryManager() throws IOException {
        Properties properties = loadProperties();
        this.memoryLimit = Double.parseDouble(properties.getProperty("memory.limit", "1000.0"));
        this.currentMemoryUsage = new AtomicLong(0);
        this.identifierMap = new ConcurrentHashMap<>();
        this.doubleCollection = new ConcurrentHashMap<>();
        this.idService = new ExternalIDService(); // Assumes implementation of this class
    }

    private Properties loadProperties() throws IOException {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream("config.properties")) {
            properties.load(fis);
        }
        return properties;
    }

    public synchronized boolean addDouble(Double value) {
        if (currentMemoryUsage.get() + value > memoryLimit) {
            logger.warning("Memory limit exceeded.");
            return false;
        }

        currentMemoryUsage.addAndGet(value);
        long id = generateUniqueID();
        doubleCollection.put(id, value);
        logger.info("Added double with ID: " + id);
        return true;
    }

    public synchronized boolean addString(String identifier) {
        if (identifierMap.size() > getMaxThreshold()) {
            resizeIdentifierMap();
        }

        long id = generateUniqueID();
        identifierMap.put(id, identifier);
        logger.info("Added string with ID: " + id);
        return true;
    }

    private synchronized void resizeIdentifierMap() {
        // Implement resizing logic to manage memory allocation efficiently
        ConcurrentHashMap<Long, String> newMap = new ConcurrentHashMap<>();
        newMap.putAll(identifierMap);
        identifierMap = newMap;
        logger.info("Resized string collection.");
    }

    private long generateUniqueID() {
        try {
            return idService.getUniqueId();
        } catch (IOException | InterruptedException e) {
            logger.log(Level.SEVERE, "Failed to retrieve unique ID", e);
            return -1; // Handle as needed
        }
    }

    public double getCurrentMemoryUsage() {
        return currentMemoryUsage.get();
    }

    private int getMaxThreshold() {
        Properties properties = loadProperties();
        return Integer.parseInt(properties.getProperty("string.collection.max.threshold", "1000"));
    }

    public void handleError(String message, Exception e) {
        logger.log(Level.SEVERE, message, e);
    }
}

class ExternalIDService {
    // Simulate interaction with an external service
    public long getUniqueId() throws IOException, InterruptedException {
        // Simulated network call to retrieve unique ID
        return ThreadLocalRandom.current().nextLong();
    }
}
