                const addOffset = (offset) => {
                    if ((allocatedSize + BigInt(offset).byteLength) > maxMemorySize) throw new Error('Memory limit exceeded');
                    allocatedSize += BigInt(offset).byteLength;
                    this.offsets.push(offset);
                };

                const addKey = (key) => {
                    if ((allocatedSize + 4) > maxMemorySize) throw new Error('Memory limit exceeded');
                    allocatedSize += 4;
                    this.keys.push(key);
