['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define LOWER_BOUND 1
#define UPPER_BOUND 1000000

typedef struct {
    int value;
} Record;

// Global variables for monitoring and logging
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t total_memory_allocated = 0;
const size_t memory_threshold = 80 * 1024 * 1024; // 80 MB threshold

// Logging function
void log_event(const char* event) {
    pthread_mutex_lock(&log_mutex);
    printf("[LOG] %s\n", event);
    pthread_mutex_unlock(&log_mutex);
}

// Memory usage monitoring and alerting system
void check_memory_usage() {
    if (total_memory_allocated > memory_threshold) {
        log_event("Memory usage is critically high. Consider freeing up space.");
        // Implement migration to secondary storage logic here
    }
}

// Error handling for allocation failures
void* safe_malloc(size_t size, const char* desc) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory Allocation Failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&log_mutex);
    total_memory_allocated += size;
    log_event(desc);
    pthread_mutex_unlock(&log_mutex);
    check_memory_usage();
    return ptr;
}

// Integrity check function
void check_array_integrity(int* array, int size) {
    for (int i = 0; i < size; ++i) {
        if (array[i] != array[i]) { // Check for NaN or corrupted data
            log_event("Data corruption detected!");
        }
    }
}

// Initialize and return a dynamically allocated array of long integers
long* init_long_array(int size, const char* desc) {
    if (size < LOWER_BOUND || size > UPPER_BOUND) {
        fprintf(stderr, "Invalid size for long array: %d\n", size);
        exit(EXIT_FAILURE);
    }
    return safe_malloc(size * sizeof(long), desc);
}

// Initialize and return a dynamically allocated array of int integers
int* init_int_array(int size, const char* desc) {
    if (size < LOWER_BOUND || size > UPPER_BOUND) {
        fprintf(stderr, "Invalid size for int array: %d\n", size);
        exit(EXIT_FAILURE);
    }
    return safe_malloc(size * sizeof(int), desc);
}

// Initialize a dynamically allocated array of Record structs
Record* init_record_array(int size, int min_value, int max_value, const char* desc) {
    if (size < LOWER_BOUND || size > UPPER_BOUND) {
        fprintf(stderr, "Invalid size for record array: %d\n", size);
        exit(EXIT_FAILURE);
    }

    Record* records = safe_malloc(size * sizeof(Record), desc);

    // Populate the array with random values
    srand((unsigned int)time(NULL));
    for (int i = 0; i < size; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    return records;
}

// Function to clean up memory and log deallocation
void safe_free(void* ptr, const char* desc, size_t size) {
    if (!ptr) return;
    pthread_mutex_lock(&log_mutex);
    total_memory_allocated -= size;
    free(ptr);
    log_event(desc);
    pthread_mutex_unlock(&log_mutex);
}

// Thread-safe function to query the state of allocated arrays
void query_state(int long_array_size, int int_array_size, int record_array_size) {
    printf("Long Array Size: %d\n", long_array_size);
    printf("Int Array Size: %d\n", int_array_size);
    printf("Record Array Size: %d\n", record_array_size);
    printf("Total Memory Allocated: %zu bytes\n", total_memory_allocated);
}

// Concurrent access management with a maximum thread limit
#define MAX_THREADS 10
pthread_mutex_t data_access_lock = PTHREAD_MUTEX_INITIALIZER;
int active_threads = 0;

void* concurrent_function(void* arg) {
    pthread_mutex_lock(&data_access_lock);
    if (active_threads >= MAX_THREADS) {
        log_event("Max concurrent threads reached.");
        pthread_mutex_unlock(&data_access_lock);
        return NULL;
    }
    active_threads++;
    pthread_mutex_unlock(&data_access_lock);

    // Perform operations on shared data here

    pthread_mutex_lock(&data_access_lock);
    active_threads--;
    pthread_mutex_unlock(&data_access_lock);
    return NULL;
}

int main() {
    int long_array_size = 100000;  // Example size
    int int_array_size = 50000;    // Example size
    int record_array_size = 20000; // Example size
    int min_value = 1, max_value = 10;

    long* long_array = init_long_array(long_array_size, "Allocating long array");
    int* int_array = init_int_array(int_array_size, "Allocating int array");
    Record* record_array = init_record_array(record_array_size, min_value, max_value, "Allocating record array");

    // Example of querying the state
    query_state(long_array_size, int_array_size, record_array_size);

    // Clean up memory before exiting
    safe_free(long_array, "Freeing long array", long_array_size * sizeof(long));
    safe_free(int_array, "Freeing int array", int_array_size * sizeof(int));
    safe_free(record_array, "Freeing record array", record_array_size * sizeof(Record));

    return 0;
}
