    private static $configCache = [];
    private static $lastModifiedTime;

    public static function getConfig($profile) {
        $configFile = __DIR__ . "/config/{$profile}.php";

        if (!isset(self::$configCache[$profile]) || filemtime($configFile) > self::$lastModifiedTime) {
            if (file_exists($configFile)) {
                self::$lastModifiedTime = time();
                self::$configCache[$profile] = require $configFile;
            } else {
                throw new Exception("Configuration file not found: {$configFile}");
