```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_MEMORY_USAGE 1048576 // Example: 1MB limit
#define ENTRY_BUFFER_SIZE 256
#define FLOAT_RANGE_MIN 0.0f
#define FLOAT_RANGE_MAX 100.0f

typedef struct {
    float value;
    struct timeval timestamp;
    char *buffer;
} entry_t;

typedef struct {
    entry_t **entries;
    size_t capacity;
    size_t count;
    size_t total_memory_usage;
    pthread_rwlock_t lock;
    uint32_t seed;
} entry_collection_t;

static inline bool is_valid_input(const char *input, size_t max_length) {
    if (strlen(input) > max_length) return false;
    for (size_t i = 0; i < strlen(input); ++i) {
        if (!isprint((unsigned char)input[i])) return false;
    }
    return true;
}

static float random_float(uint32_t *seed, float min, float max) {
    float r = ((float)rand_r(seed)) / RAND_MAX;
    return min + (max - min) * r;
}

entry_collection_t* create_entry_collection(size_t initial_capacity, uint32_t seed) {
    entry_collection_t *collection = malloc(sizeof(entry_collection_t));
    if (!collection) {
        perror("Failed to allocate collection");
        exit(EXIT_FAILURE);
    }

    collection->entries = calloc(initial_capacity, sizeof(entry_t *));
    if (!collection->entries) {
        free(collection);
        perror("Failed to allocate entries");
        exit(EXIT_FAILURE);
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->total_memory_usage = 0;
    pthread_rwlock_init(&collection->lock, NULL);
    collection->seed = seed;

    return collection;
}

void free_entry_collection(entry_collection_t *collection) {
    pthread_rwlock_wrlock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i]->buffer);
        free(collection->entries[i]);
    }
    free(collection->entries);
    pthread_rwlock_unlock(&collection->lock);
    pthread_rwlock_destroy(&collection->lock);
    free(collection);
}

bool add_entry(entry_collection_t *collection, const char *input) {
    if (!is_valid_input(input, ENTRY_BUFFER_SIZE - 1)) return false;

    pthread_rwlock_wrlock(&collection->lock);

    size_t buffer_size = strlen(input) + 1;
    size_t entry_memory_usage = sizeof(entry_t) + buffer_size;

    if (entry_memory_usage > collection->total_memory_usage || 
        (collection->count == collection->capacity)) {
        pthread_rwlock_unlock(&collection->lock);
        return false;
    }

    entry_t *new_entry = malloc(sizeof(entry_t));
    if (!new_entry) {
        pthread_rwlock_unlock(&collection->lock);
        perror("Failed to allocate new entry");
        exit(EXIT_FAILURE);
    }

    gettimeofday(&new_entry->timestamp, NULL);
    new_entry->value = random_float(&collection->seed, FLOAT_RANGE_MIN, FLOAT_RANGE_MAX);

    new_entry->buffer = malloc(buffer_size);
    if (!new_entry->buffer) {
        free(new_entry);
        pthread_rwlock_unlock(&collection->lock);
        perror("Failed to allocate buffer");
        exit(EXIT_FAILURE);
    }

    strcpy(new_entry->buffer, input);

    collection->entries[collection->count++] = new_entry;
    collection->total_memory_usage += entry_memory_usage;

    pthread_rwlock_unlock(&collection->lock);
    return true;
}

void calculate_average(float *average) {
    float sum = 0.0f;
    size_t count = 0;
    float num;

    while (scanf("%f", &num) == 1) {
        sum += num;
        ++count;
    }

    if (count > 0) {
        *average = sum / count;
        printf("Average: %f\n", *average);
    } else {
        printf("No valid numbers entered.\n");
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    entry_collection_t *collection = create_entry_collection(10, rand());

    // Example usage of adding entries and calculating average
    add_entry(collection, "Test input 1");
    add_entry(collection, "Test input 2");

    float avg;
    calculate_average(&avg);

    free_entry_collection(collection);

    return 0;
}
```

