#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_SIZE_LIMIT 1024 * 1024 // Maximum memory limit in bytes

typedef struct {
    double precision_value;
    char config_name[256];
    int active_state; // Using int to mimic bool for C standards
} Config;

// Global mutex for thread-safety
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_random_generator() {
    srand((unsigned int)time(NULL));
}

Config* allocate_and_initialize_configs(size_t num_configs, size_t *allocated_size) {
    if (num_configs <= 0 || allocated_size == NULL) {
        return NULL;
    }

    size_t total_memory_needed = num_configs * sizeof(Config);

    if (total_memory_needed > MAX_SIZE_LIMIT) {
        fprintf(stderr, "Error: Total memory needed exceeds the maximum limit.\n");
        return NULL;
    }

    Config* configs = malloc(total_memory_needed);
    if (!configs) {
        perror("Failed to allocate memory for configs");
        return NULL;
    }

    *allocated_size = total_memory_needed;

    // Initialize each config
    for (size_t i = 0; i < num_configs; ++i) {
        pthread_mutex_lock(&global_mutex);

        configs[i].precision_value = ((double)rand() / RAND_MAX) * 100.0; // Random double between 0 and 100

        snprintf(configs[i].config_name, sizeof(configs[i].config_name), "Config_%zu", i + 1);

        configs[i].active_state = (i % 2 == 0); // Alternate active/inactive states for demonstration

        pthread_mutex_unlock(&global_mutex);
    }

    return configs;
}

void free_configs(Config* configs) {
    if (configs != NULL) {
        free(configs);
    }
}

int main() {
    size_t allocated_size = 0;
    size_t num_configs_to_allocate = 10;

    initialize_random_generator();

    Config* configs = allocate_and_initialize_configs(num_configs_to_allocate, &allocated_size);

    if (!configs) {
        fprintf(stderr, "Failed to create configurations.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < num_configs_to_allocate; ++i) {
        printf("Config %zu: Name=%s, Value=%.2f, Active State=%d\n",
               i + 1,
               configs[i].config_name,
               configs[i].precision_value,
               configs[i].active_state);
    }

    free_configs(configs);

    return EXIT_SUCCESS;
}
