#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 1000
#define SEVERITY_RANGE_MIN 1
#define SEVERITY_RANGE_MAX 5

typedef struct {
    time_t timestamp;
    char *message;
    int severity_level;
} log_entry;

typedef enum { JSON, BINARY, CUSTOM_TEXT } format_type;

// External logging service mock
typedef struct {
    int version;
    // Additional metadata fields can be added here
} logging_service_metadata;

// Global variables for configuration and state management
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
const size_t MAX_MEMORY_USAGE = 1024 * 1024; // Example limit: 1 MB

// Function to hash a message using a simple default hash function
unsigned long hash_message(const char *message) {
    unsigned long hash = 5381;
    int c;
    while ((c = *message++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

// Helper to generate a random severity level within the specified range
int generate_random_severity() {
    srand((unsigned int)time(NULL));
    return rand() % (SEVERITY_RANGE_MAX - SEVERITY_RANGE_MIN + 1) + SEVERITY_RANGE_MIN;
}

// Function to manage dynamic allocation and initialization of log entries
void *manage_log_entries(void *arg) {
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    size_t max_entries = MAX_LOG_ENTRIES;
    format_type output_format = JSON; // Example default

    if (arg != NULL) {
        char *arg_str = (char *)arg;
        if (strcmp(arg_str, "json") == 0) output_format = JSON;
        else if (strcmp(arg_str, "binary") == 0) output_format = BINARY;
        else if (strcmp(arg_str, "custom_text") == 0) output_format = CUSTOM_TEXT;
    }

    log_entry *logs = NULL;
    size_t entry_size = sizeof(log_entry);
    size_t current_memory_usage = 0;

    pthread_mutex_lock(&lock);

    logs = (log_entry *)malloc(max_entries * entry_size);
    if (!logs) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < max_entries; ++i) {
        current_memory_usage += entry_size + strlen("Sample log message") + 1;

        if (current_memory_usage > MAX_MEMORY_USAGE) break;

        logs[i].timestamp = time(NULL);
        logs[i].message = strdup("Sample log message");
        logs[i].severity_level = generate_random_severity();

        // Hash the message
        unsigned long hash_value = hash_message(logs[i].message);

        printf("Log Entry %zu: Timestamp=%ld, Severity=%d, MessageHash=%lu\n",
               i + 1, logs[i].timestamp, logs[i].severity_level, hash_value);
    }

    pthread_mutex_unlock(&lock);

    free(logs);

    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double elapsed = (end_time.tv_sec - start_time.tv_sec) +
                     (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

    printf("Processing time: %.6f seconds\n", elapsed);

    return NULL;
}

// Helper function to read timestamps from stdin and validate them
void process_timestamps_from_stdin() {
    char input[256];
    time_t timestamps[MAX_LOG_ENTRIES];
    size_t count = 0;

    while (fgets(input, sizeof(input), stdin) && count < MAX_LOG_ENTRIES) {
        if (strptime(input, "%Y-%m-%d %H:%M:%S", localtime(&timestamps[count]))) {
            printf("Valid timestamp: %s\n", input);
            ++count;
        } else {
            fprintf(stderr, "Invalid timestamp format: %s\n", input);
        }
    }

    printf("Processed %zu valid timestamps.\n", count);

    // Log memory usage
    size_t mem_usage = 0;
    for (size_t i = 0; i < count; ++i) {
        mem_usage += sizeof(time_t);
    }

    printf("Memory used for timestamps: %zu bytes\n", mem_usage);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        pthread_t thread;
        pthread_create(&thread, NULL, manage_log_entries, argv[1]);
        pthread_join(thread, NULL);
    }

    printf("Enter timestamps in the format 'YYYY-MM-DD HH:MM:SS':\n");
    process_timestamps_from_stdin();

    return 0;
}
```']

['Here is a C implementation for managing a scalable pool of file descriptors with multi-threading, lock-free queues, and custom state management. It includes error checking, logging, and performance optimizations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_FD_POOL 10000
#define MAX_MEMORY_LIMIT 1024 * 1024 * 500 // 500 MB
#define DEFAULT_AGE_THRESHOLD 300 // seconds

typedef enum {
    FD_OPEN,
    FD_CLOSED,
    FD_BUSY,
    FD_ERROR,
    CUSTOM_STATE_1, // Example custom state
    CUSTOM_STATE_2  // Another example
} fd_state_t;

typedef struct {
    int fd;
    fd_state_t state;
    time_t last_accessed;
    size_t read_bytes;
    size_t write_bytes;
    pthread_mutex_t lock; // For thread safety
} file_descriptor_t;

typedef struct {
    char *buffer;
    size_t size;
    time_t timestamp;
} data_block_t;

typedef struct {
    file_descriptor_t fds[MAX_FD_POOL];
    int count;
    size_t memory_usage;
    size_t max_memory_limit;
    pthread_mutex_t pool_lock; // For managing the pool
} fd_pool_t;

fd_pool_t *create_fd_pool(size_t initial_memory_limit) {
    fd_pool_t *pool = (fd_pool_t *)malloc(sizeof(fd_pool_t));
    if (!pool) return NULL;

    memset(pool, 0, sizeof(fd_pool_t));
    pool->max_memory_limit = initial_memory_limit;
    pthread_mutex_init(&pool->pool_lock, NULL);

    for (int i = 0; i < MAX_FD_POOL; ++i) {
        pthread_mutex_init(&pool->fds[i].lock, NULL);
    }

    return pool;
}

void log_event(const char *event) {
    printf("[LOG] %s\n", event);
}

int acquire_fd(fd_pool_t *pool, fd_state_t desired_state) {
    pthread_mutex_lock(&pool->pool_lock);

    for (int i = 0; i < MAX_FD_POOL; ++i) {
        if (pthread_mutex_trylock(&pool->fds[i].lock) == 0) { // Try to lock
            if ((pool->fds[i].state == FD_CLOSED || pool->fds[i].state == desired_state) &&
                (time(NULL) - pool->fds[i].last_accessed < DEFAULT_AGE_THRESHOLD)) {

                pool->fds[i].state = desired_state;
                pthread_mutex_unlock(&pool->fds[i].lock);
                log_event("File descriptor acquired.");
                return i; // Return the index
            }
            pthread_mutex_unlock(&pool->fds[i].lock);
        }
    }

    log_event("No available file descriptors.");
    pthread_mutex_unlock(&pool->pool_lock);
    return -1;
}

void release_fd(fd_pool_t *pool, int fd_index) {
    if (fd_index < 0 || fd_index >= MAX_FD_POOL) return;

    pthread_mutex_lock(&pool->fds[fd_index].lock);
    pool->fds[fd_index].state = FD_CLOSED;
    pool->fds[fd_index].last_accessed = time(NULL);
    log_event("File descriptor released.");
    pthread_mutex_unlock(&pool->fds[fd_index].lock);
}

void adjust_memory_limit(fd_pool_t *pool) {
    size_t new_limit = /* logic to determine based on system resources */;
    pthread_mutex_lock(&pool->pool_lock);
    pool->max_memory_limit = new_limit;
    pthread_mutex_unlock(&pool->pool_lock);
    log_event("Memory limit adjusted.");
}

void cleanup_fd_pool(fd_pool_t *pool) {
    for (int i = 0; i < MAX_FD_POOL; ++i) {
        pthread_mutex_destroy(&pool->fds[i].lock);
    }
    pthread_mutex_destroy(&pool->pool_lock);
    free(pool);
}

// Example function to demonstrate dynamic memory management
data_block_t* allocate_data_block(size_t size, fd_pool_t *pool) {
    if (size == 0 || pool->memory_usage + size > pool->max_memory_limit) return NULL;

    data_block_t *block = (data_block_t *)malloc(sizeof(data_block_t));
    if (!block) return NULL;

    block->buffer = malloc(size);
    if (!block->buffer) {
        free(block);
        return NULL;
    }

    pthread_mutex_lock(&pool->pool_lock);
    pool->memory_usage += sizeof(data_block_t) + size;
    pthread_mutex_unlock(&pool->pool_lock);

    block->size = size;
    block->timestamp = time(NULL);
    log_event("Data block allocated.");
    return block;
}

void free_data_block(data_block_t *block, fd_pool_t *pool) {
    if (!block) return;

    pthread_mutex_lock(&pool->pool_lock);
    pool->memory_usage -= sizeof(data_block_t) + block->size;
    pthread_mutex_unlock(&pool->pool_lock);

    free(block->buffer);
    free(block);
    log_event("Data block freed.");
}

int main() {
    fd_pool_t *fd_pool = create_fd_pool(MAX_MEMORY_LIMIT);

    // Example usage
    int fd_index = acquire_fd(fd_pool, FD_OPEN);
    if (fd_index != -1) {
        release_fd(fd_pool, fd_index);
    }

    data_block_t *block = allocate_data_block(1024, fd_pool);
    free_data_block(block, fd_pool);

    cleanup_fd_pool(fd_pool);

    return 0;
}
```

This code snippet demonstrates a basic structure for managing file descriptors and memory with threading support. It includes mechanisms to handle file descriptor states, logging events, and dynamically adjusting memory limits based on system resources. The example uses mutexes to ensure thread safety, and it provides functions to acquire, release, allocate, and free resources efficiently.']

