```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int id;
    long value;
    char string[256];
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

void seed_rng() {
    srand(time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* create_record_array(size_t initial_capacity) {
    RecordArray *arr = malloc(sizeof(RecordArray));
    arr->records = malloc(initial_capacity * sizeof(Record));
    arr->capacity = initial_capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_record_array(RecordArray *arr) {
    free(arr->records);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

void resize_record_array(RecordArray *arr);

void add_record(RecordArray *arr, Record record) {
    pthread_mutex_lock(&arr->lock);
    if (arr->count == arr->capacity) {
        resize_record_array(arr);
    }
    arr->records[arr->count++] = record;
    pthread_mutex_unlock(&arr->lock);
}

void resize_record_array(RecordArray *arr) {
    size_t new_capacity = arr->capacity * 2;
    Record *new_records = realloc(arr->records, new_capacity * sizeof(Record));
    if (new_records) {
        arr->records = new_records;
        arr->capacity = new_capacity;
    } else {
        perror("Failed to resize record array");
        exit(EXIT_FAILURE);
    }
}

void serialize_record_array(const RecordArray *arr, uint8_t **buffer, size_t *length) {
    pthread_mutex_lock(&arr->lock);

    // Calculate required buffer length
    size_t total_length = sizeof(size_t);  // For count
    for (size_t i = 0; i < arr->count; ++i) {
        total_length += sizeof(int);          // id
        total_length += sizeof(long);         // value
        total_length += sizeof(uint16_t);     // string length
        total_length += strlen(arr->records[i].string) + 1;  // null-terminated string
    }

    *buffer = malloc(total_length);
    uint8_t *ptr = *buffer;

    memcpy(ptr, &arr->count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < arr->count; ++i) {
        int id = htonl(arr->records[i].id);
        long value = htobe64(arr->records[i].value);

        memcpy(ptr, &id, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &value, sizeof(long));
        ptr += sizeof(long);

        uint16_t str_len = htons(strlen(arr->records[i].string) + 1);
        memcpy(ptr, &str_len, sizeof(uint16_t));
        ptr += sizeof(uint16_t);
        strcpy((char *)ptr, arr->records[i].string);
        ptr += strlen(arr->records[i].string) + 1;
    }

    *length = total_length;
    pthread_mutex_unlock(&arr->lock);
}

void deserialize_record_array(const uint8_t *buffer, size_t length, RecordArray **arr) {
    const uint8_t *ptr = buffer;

    size_t count;
    memcpy(&count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    *arr = create_record_array(count);

    for (size_t i = 0; i < count; ++i) {
        int id;
        long value;

        memcpy(&id, ptr, sizeof(int));
        id = ntohl(id);
        ptr += sizeof(int);

        memcpy(&value, ptr, sizeof(long));
        value = be64toh(value);
        ptr += sizeof(long);

        uint16_t str_len;
        memcpy(&str_len, ptr, sizeof(uint16_t));
        str_len = ntohs(str_len);
        ptr += sizeof(uint16_t);

        Record record = {id, value};
        strncpy(record.string, (const char *)ptr, str_len - 1);
        record.string[str_len - 1] = '\0';

        add_record(*arr, record);
        ptr += str_len;
    }
}

void process_integers_from_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    int numbers[1000];
    size_t count = 0;

    while (fscanf(file, "%d", &numbers[count]) == 1 && count < sizeof(numbers) / sizeof(int)) {
        ++count;
    }

    fclose(file);

    if (count == 0) return;

    // Calculate average
    double sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += numbers[i];
    }
    double average = sum / count;
    printf("Average: %f\n", average);

    // Sort and find median
    qsort(numbers, count, sizeof(int), cmpfunc);
    if (count % 2 == 0) {
        double median = (numbers[count / 2 - 1] + numbers[count / 2]) / 2.0;
        printf("Median: %f\n", median);
    } else {
        printf("Median: %d\n", numbers[count / 2]);
    }
}

int cmpfunc(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

void read_integers_and_find_largest(size_t max_count) {
    int numbers[max_count];
    size_t count = 0;

    printf("Enter integers:\n");
    while (scanf("%d", &numbers[count]) == 1 && count < max_count) {
        ++count;
    }

    if (count == 0) return;

    int largest = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void generate_random_string(char *output, size_t length, const char *charset) {
    for (size_t i = 0; i < length; ++i) {
        output[i] = charset[random_int(0, strlen(charset) - 1)];
    }
    output[length] = '\0';
}

int main() {
    seed_rng();

    RecordArray *records = create_record_array(INITIAL_CAPACITY);

    // Example usage
    Record record = {random_int(1, 100), random_int(1, 10000), "example"};
    add_record(records, record);

    uint8_t *buffer;
    size_t length;
    serialize_record_array(records, &buffer, &length);

    RecordArray *new_records = NULL;
    deserialize_record_array(buffer, length, &new_records);

    process_integers_from_file("numbers.txt");
    read_integers_and_find_largest(100);

    char random_string[20];
    generate_random_string(random_string, sizeof(random_string) - 1, "abcdefghijklmnopqrstuvwxyz");

    printf("Random string: %s\n", random_string);

    destroy_record_array(records);
    free(buffer);
    destroy_record_array(new_records);

    return 0;
}
```

