    int num;
    do {
        num = rand() % (max - min + 1) + min;
    } while (num == last);
    last = num;
    return num;
}

// Add a record to the collection
int add_record(RecordCollection *collection, Record *record) {
    pthread_mutex_lock(&collection->lock);

    if ((collection->count + sizeof(Record *)) > MAX_MEMORY / sizeof(void*)) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Memory limit reached.");
        return -1;
    }

    Record **new_records = realloc(collection->records, (collection->count + 1) * sizeof(Record *));
    if (!new_records) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Failed to allocate memory for new record.");
        return -1;
    }

    collection->records = new_records;
    collection->records[collection->count] = malloc(sizeof(Record));
    if (!collection->records[collection->count]) {
        free(new_records);
        pthread_mutex_unlock(&collection->lock);
        log_event("Failed to allocate memory for record.");
        return -1;
    }

    *collection->records[collection->count] = *record;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
    log_event("Added new record.");
    return 0;
}

