    log_event("Deserialized records.");
    return 0;
}

// Compress data
size_t compress_data(const void *data, size_t data_size, void **compressed_data) {
    uLongf compressed_size = compressBound(data_size);
    *compressed_data = malloc(compressed_size);
    if (!*compressed_data) {
        log_event("Failed to allocate memory for compression.");
        return 0;
    }

    int result = compress((Bytef *)(*compressed_data), &compressed_size, (const Bytef *)data, data_size);
    if (result != Z_OK) {
        free(*compressed_data);
        *compressed_data = NULL;
        log_event("Compression failed.");
    }
    return compressed_size;
}

// Decompress data
size_t decompress_data(const void *compressed_data, size_t compressed_size, void **data) {
    uLongf data_size = compressBound(compressed_size); // Estimate uncompressed size
    *data = malloc(data_size);
    if (!*data) {
        log_event("Failed to allocate memory for decompression.");
        return 0;
    }

    int result = uncompress((Bytef *)(*data), &data_size, (const Bytef *)compressed_data, compressed_size);
    if (result != Z_OK) {
        free(*data);
        *data = NULL;
        log_event("Decompression failed.");
    }
    return data_size;
}

// Free collection
void free_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]);
    }
    free(collection->records);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);

    log_event("Freed record collection.");
}

