#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define TIMESTAMP_RANGE (24 * 60 * 60) // seconds in a day
#define PRIORITY_MIN 1
#define PRIORITY_MAX 10
#define MESSAGE_LIMIT 256

typedef struct {
    time_t timestamp;
    int priority;
    char message[MESSAGE_LIMIT];
} LogRecord;

void log_allocation_failure(const char* operation) {
    fprintf(stderr, "Memory allocation failed during %s\n", operation);
}

LogRecord* initialize_log_records(size_t num_records, int sort_enabled, const char *config_file) {
    if (num_records <= 0) {
        printf("Number of records must be positive.\n");
        return NULL;
    }

    LogRecord *records = malloc(num_records * sizeof(LogRecord));
    if (!records) {
        log_allocation_failure("record initialization");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    // Read configuration file if needed (pseudo code)
    // load_configuration(config_file, &max_records, &timestamp_range, &priority_min, &priority_max);

    for (size_t i = 0; i < num_records; ++i) {
        records[i].timestamp = rand() % TIMESTAMP_RANGE;
        records[i].priority = PRIORITY_MIN + rand() % (PRIORITY_MAX - PRIORITY_MIN + 1);

        snprintf(records[i].message, MESSAGE_LIMIT, "Message #%zu", i + 1);

        // Check total size
        if (strlen(records[i].message) >= MESSAGE_LIMIT) {
            fprintf(stderr, "Warning: Truncated message at record %zu\n", i + 1);
            records[i].message[MESSAGE_LIMIT - 1] = '\0';
        }
    }

    if (sort_enabled) {
        // Sorting records by priority
        for (size_t i = 0; i < num_records - 1; ++i) {
            for (size_t j = 0; j < num_records - i - 1; ++j) {
                if (records[j].priority > records[j + 1].priority) {
                    LogRecord temp = records[j];
                    records[j] = records[j + 1];
                    records[j + 1] = temp;
                }
            }
        }
    }

    return records;
}

void free_log_records(LogRecord *records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t num_records = MAX_RECORDS; // Ideally, this would come from a configuration file
    int sort_enabled = 1;

    LogRecord *logRecords = initialize_log_records(num_records, sort_enabled, "config.cfg");

    if (logRecords) {
        printf("Log records initialized and sorted successfully.\n");

        free_log_records(logRecords);
    } else {
        fprintf(stderr, "Failed to initialize log records.\n");
    }

    return 0;
}
```

This code initializes a logging system with randomly generated records. It handles memory allocation failures gracefully and provides an option to disable sorting when the system is under high load. The configuration for record numbers and random ranges should ideally be read from an external file (currently pseudo-implemented). Memory usage and potential fragmentation are managed by minimizing dynamic allocations during runtime operations.']

