#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MESSAGE_LENGTH 256

typedef struct {
    long timestamp;
    int priority_level;
    char message[MAX_MESSAGE_LENGTH];
} entry;

int allocate_entries(entry **entries, size_t count) {
    if (entries == NULL || count == 0) return -1;

    *entries = malloc(count * sizeof(entry));
    if (*entries == NULL) return -2;

    memset(*entries, 0, count * sizeof(entry));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&mutex);
        (*entries)[i].timestamp = 0;
        (*entries)[i].priority_level = 0;
        strncpy((*entries)[i].message, "", MAX_MESSAGE_LENGTH - 1);
        pthread_mutex_unlock(&mutex);
    }

    return 0;
}

size_t calculate_total_memory(size_t count) {
    size_t entry_size = sizeof(entry);
    // Adjust for padding/alignment if necessary
    return count * entry_size;
}

void free_entries(entry **entries) {
    if (entries && *entries) {
        free(*entries);
        *entries = NULL;
    }
}
```

This code defines an `entry` structure and provides functions to allocate, calculate the total memory size of, and free an array of such entries. The allocation function initializes each entry with default values and uses a mutex for thread safety. Memory is allocated dynamically, and potential failures are handled by returning error codes. The `calculate_total_memory` function computes the total memory used by the entries, considering alignment. Finally, `free_entries` safely deallocates the memory when it's no longer needed.']

['```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Record {
    int value;
    struct Record* next;
} Record;

typedef struct {
    Record* head;
    size_t count;
} RecordList;

void log_operation(const char* operation, size_t record_count) {
    printf("Operation: %s | Records Count: %zu\n", operation, record_count);
}

RecordList* create_record_list() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) {
        perror("Failed to allocate memory for record list");
        return NULL;
    }
    list->head = NULL;
    list->count = 0;
    log_operation("Create List", 0);
    return list;
}

int add_record(RecordList* list, int value) {
    if (!list) return -1;

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for record");
        return -1;
    }

    new_record->value = value;
    new_record->next = list->head;
    list->head = new_record;
    list->count++;

    log_operation("Add Record", list->count);
    return 0;
}

int get_record(RecordList* list, size_t index, int* value) {
    if (!list || !value || index >= list->count) return -1;

    Record* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current == NULL) return -1;

    *value = current->value;
    log_operation("Get Record", index + 1);
    return 0;
}

int remove_record(RecordList* list, size_t index) {
    if (!list || index >= list->count) return -1;

    Record** current_ptr = &list->head;
    for (size_t i = 0; i < index && *current_ptr != NULL; ++i) {
        current_ptr = &((*current_ptr)->next);
    }

    if (*current_ptr == NULL) return -1;

    Record* to_remove = *current_ptr;
    *current_ptr = to_remove->next;
    free(to_remove);

    list->count--;

    log_operation("Remove Record", list->count);
    return 0;
}

void clear_records(RecordList* list) {
    if (!list) return;

    while (list->head != NULL) {
        Record* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }

    list->count = 0;
    log_operation("Clear Records", 0);
}

void destroy_record_list(RecordList** list) {
    if (!list || !(*list)) return;

    clear_records(*list);
    free(*list);
    *list = NULL;

    log_operation("Destroy List", 0);
}
```

This code provides a simple linked-list based dynamic record management system in C. The `RecordList` structure maintains a pointer to the head of the list and tracks the count of records for efficiency. Memory allocation failures are handled with error reporting via `perror`. Operations like adding, retrieving, removing records, clearing all records, and destroying the list are logged for tracking purposes. This setup ensures efficient memory usage and performance for dynamic record management tasks.']

