#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_DESC_LEN 256
#define LOG_FILE "records.log"
#define NUM_RECORDS 1000000

typedef struct {
    long offset;
    int key;
    float timestamp;
    char *description;
} Record;

typedef enum { INFO, WARNING, ERROR } LogLevel;

// Mutex for thread-safe logging
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void logMessage(LogLevel level, const char *message) {
    pthread_mutex_lock(&logMutex);
    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile != NULL) {
        switch (level) {
            case INFO: fprintf(logFile, "[INFO] %s\n", message); break;
            case WARNING: fprintf(logFile, "[WARNING] %s\n", message); break;
            case ERROR: fprintf(logFile, "[ERROR] %s\n", message); break;
        }
        fclose(logFile);
    } else {
        perror("Failed to open log file");
    }
    pthread_mutex_unlock(&logMutex);
}

int compareRecords(const void *a, const void *b) {
    Record *recordA = (Record *)a;
    Record *recordB = (Record *)b;
    return recordA->key - recordB->key;
}

void initializeRecords(Record **records, size_t numRecords) {
    if (numRecords <= 0) return;

    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            logMessage(ERROR, "Memory allocation failed for record");
            exit(EXIT_FAILURE);
        }

        records[i]->offset = rand() % 100000;
        records[i]->key = rand() % 1000;
        records[i]->timestamp = (float)rand() / RAND_MAX * 100.0;

        size_t descLen = rand() % MAX_DESC_LEN + 1;
        records[i]->description = malloc(descLen);
        if (!records[i]->description) {
            logMessage(ERROR, "Memory allocation failed for description");
            free(records[i]);
            exit(EXIT_FAILURE);
        }

        snprintf(records[i]->description, descLen, "Description_%ld", rand());

        char logMsg[256];
        snprintf(logMsg, sizeof(logMsg), "Record %zu: Offset=%ld, Key=%d, Timestamp=%.2f, DescSize=%zu",
                 i, records[i]->offset, records[i]->key, records[i]->timestamp, descLen);
        logMessage(INFO, logMsg);
    }
}

void freeRecords(Record **records, size_t numRecords) {
    if (numRecords <= 0) return;

    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i]) {
            free(records[i]->description);
            free(records[i]);
        }
    }
}

void sortRecords(Record **records, size_t numRecords) {
    if (numRecords <= 1) return;
    qsort(records, numRecords, sizeof(Record *), compareRecords);
}

int main() {
    Record *records[NUM_RECORDS];

    initializeRecords(records, NUM_RECORDS);
    sortRecords(records, NUM_RECORDS);

    // Simulate processing
    for (size_t i = 0; i < NUM_RECORDS; ++i) {
        // Processing logic here
    }

    freeRecords(records, NUM_RECORDS);

    return 0;
}
```

### Key Points:
- **Memory Management**: The function allocates memory for each record and its description, ensuring all allocations are checked.
- **Logging**: Logs detailed information about each record with thread-safe access to the log file.
- **Sorting**: Sorts records by key using `qsort`.
- **Error Handling**: Gracefully handles allocation failures with error logging.
- **Concurrency**: Uses a mutex for thread-safe logging operations.']

