    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

void load_config(int *max_records, int *timestamp_range, int *priority_range, int *message_length);
MemoryPool* create_memory_pool(size_t block_size, size_t pool_size);
LogRecord* allocate_log_record(MemoryPool *pool);
