RecordCollection* initialize_collection() {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
    log_message("Initialized record collection.");

    return collection;
}

int allocate_records(RecordCollection *collection, size_t batch_size) {
    pthread_mutex_lock(&collection->lock);

    if (batch_size + collection->count > MAX_RECORDS) {
        pthread_mutex_unlock(&collection->lock);
        log_message("Error: Attempt to exceed maximum record limit.");
        return -1;
    }

    if (collection->capacity < collection->count + batch_size) {
        size_t new_capacity = collection->count + batch_size;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            log_message("Error: Memory allocation failed.");
            return -1;
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    for (size_t i = 0; i < batch_size; ++i) {
        size_t index = collection->count + i;

        collection->records[index].value = 0.0; // Initialize with a default value
        collection->records[index].buffer = malloc(256); // Allocate buffer with assumed max size

        if (!collection->records[index].buffer) {
            pthread_mutex_unlock(&collection->lock);
            log_message("Error: Buffer allocation failed.");

            while (i > 0) { // Rollback in case of failure
                free(collection->records[collection->count + i - 1].buffer);
                --i;
            }
            return -1;
        }

        memset(collection->records[index].buffer, 0, 256); // Initialize buffer
    }

    collection->count += batch_size;
    log_message("Records allocated successfully.");

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

void clear_records(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].buffer);
    }

    free(collection->records);
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;

    log_message("Records cleared successfully.");

    pthread_mutex_unlock(&collection->lock);
}

void destroy_collection(RecordCollection *collection) {
    if (collection) {
        clear_records(collection);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
        log_message("Destroyed record collection.");
    }
}
