#include <iostream>
#include <string>
#include <unordered_map>
#include <queue>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <fstream>
#include <sstream>

// Forward declaration of external database service interface
class IDatabaseService {
public:
    virtual ~IDatabaseService() = default;
    virtual void connect(const std::string& db_name) = 0;
    virtual void disconnect() = 0;
    virtual bool executeQuery(const std::string& query) = 0;
};

// Connection metadata structure
struct ConnectionMetadata {
    std::string databaseName;
    enum class ConnectionState { Connected, Disconnected } state;
    std::chrono::time_point<std::chrono::steady_clock> lastAccessed;
    int queryCount;
    std::unordered_map<std::string, std::string> customFields;

    // Serialization and deserialization
    void serialize(std::ostream& out) const {
        size_t name_size = databaseName.size();
        out.write(reinterpret_cast<const char*>(&name_size), sizeof(name_size));
        out.write(databaseName.data(), name_size);

        int state_val = static_cast<int>(state);
        out.write(reinterpret_cast<const char*>(&state_val), sizeof(state_val));

        uint64_t time_since_epoch = lastAccessed.time_since_epoch().count();
        out.write(reinterpret_cast<const char*>(&time_since_epoch), sizeof(time_since_epoch));

        out.write(reinterpret_cast<const char*>(&queryCount), sizeof(queryCount));

        size_t custom_fields_size = customFields.size();
        out.write(reinterpret_cast<const char*>(&custom_fields_size), sizeof(custom_fields_size));
        for (const auto& [key, value] : customFields) {
            size_t key_size = key.size(), value_size = value.size();
            out.write(reinterpret_cast<const char*>(&key_size), sizeof(key_size));
            out.write(key.data(), key_size);
            out.write(reinterpret_cast<const char*>(&value_size), sizeof(value_size));
            out.write(value.data(), value_size);
        }
    }

    void deserialize(std::istream& in) {
        size_t name_size;
        in.read(reinterpret_cast<char*>(&name_size), sizeof(name_size));
        databaseName.resize(name_size);
        in.read(&databaseName[0], name_size);

        int state_val;
        in.read(reinterpret_cast<char*>(&state_val), sizeof(state_val));
        state = static_cast<ConnectionState>(state_val);

        uint64_t time_since_epoch;
        in.read(reinterpret_cast<char*>(&time_since_epoch), sizeof(time_since_epoch));
        lastAccessed = std::chrono::steady_clock::time_point(std::chrono::seconds(time_since_epoch));

        in.read(reinterpret_cast<char*>(&queryCount), sizeof(queryCount));

        size_t custom_fields_size;
        in.read(reinterpret_cast<char*>(&custom_fields_size), sizeof(custom_fields_size));
        for (size_t i = 0; i < custom_fields_size; ++i) {
            size_t key_size, value_size;
            std::string key, value;
            in.read(reinterpret_cast<char*>(&key_size), sizeof(key_size));
            key.resize(key_size);
            in.read(&key[0], key_size);

            in.read(reinterpret_cast<char*>(&value_size), sizeof(value_size));
            value.resize(value_size);
            in.read(&value[0], value_size);

            customFields[key] = value;
        }
    }
};

// Connection object
class DatabaseConnection {
public:
    DatabaseConnection(IDatabaseService* service, const std::string& db_name)
        : service(service), metadata({ db_name, ConnectionMetadata::ConnectionState::Disconnected }) {
        service->connect(db_name);
        updateLastAccess();
    }

    ~DatabaseConnection() {
        if (metadata.state == ConnectionMetadata::ConnectionState::Connected) {
            service->disconnect();
        }
    }

    bool executeQuery(const std::string& query) {
        if (metadata.state != ConnectionMetadata::ConnectionState::Connected) return false;
        bool result = service->executeQuery(query);
        metadata.queryCount++;
        updateLastAccess();
        return result;
    }

    const ConnectionMetadata& getMetadata() const { return metadata; }

private:
    void updateLastAccess() {
        metadata.lastAccessed = std::chrono::steady_clock::now();
    }

    IDatabaseService* service;
    ConnectionMetadata metadata;
};

// Pool manager class
class DatabaseConnectionPool {
public:
    DatabaseConnectionPool(size_t pool_size, IDatabaseService* db_service)
        : poolSize(pool_size), dbService(db_service) {}

    ~DatabaseConnectionPool() {
        cleanupConnections();
    }

    std::shared_ptr<DatabaseConnection> acquire(const std::string& database_name) {
        std::unique_lock<std::mutex> lock(poolMutex);
        cv.wait(lock, [this]() { return availableConnections.size() > 0; });

        auto conn = availableConnections.front();
        availableConnections.pop();

        if (conn->getMetadata().databaseName != database_name) {
            // Create new connection if not matching
            conn.reset(new DatabaseConnection(dbService, database_name));
        }
        return conn;
    }

    void release(std::shared_ptr<DatabaseConnection> connection) {
        std::unique_lock<std::mutex> lock(poolMutex);
        availableConnections.push(connection);
        cv.notify_one();
    }

    void cleanupConnections() {
        while (!availableConnections.empty()) {
            auto conn = availableConnections.front();
            availableConnections.pop();
            conn.reset();  // Trigger disconnection in destructor
        }
    }

    void serializePool(const std::string& filename) const {
        std::ofstream file(filename, std::ios::binary);
        if (!file.is_open()) throw std::runtime_error("Unable to open file for serialization");

        size_t pool_size;
        file.write(reinterpret_cast<const char*>(&poolSize), sizeof(poolSize));

        // Serialize each connection's metadata
        std::queue<std::shared_ptr<DatabaseConnection>> tempQueue = availableConnections;
        while (!tempQueue.empty()) {
            const auto& conn = tempQueue.front();
            const auto& metadata = conn->getMetadata();

            size_t name_size = metadata.databaseName.size();
            file.write(reinterpret_cast<const char*>(&name_size), sizeof(name_size));
            file.write(metadata.databaseName.data(), name_size);

            int state_val = static_cast<int>(metadata.state);
            file.write(reinterpret_cast<const char*>(&state_val), sizeof(state_val));

            uint64_t time_since_epoch = metadata.lastAccessed.time_since_epoch().count();
            file.write(reinterpret_cast<const char*>(&time_since_epoch), sizeof(time_since_epoch));

            file.write(reinterpret_cast<const char*>(&metadata.queryCount), sizeof(metadata.queryCount));

            size_t custom_fields_size = metadata.customFields.size();
            file.write(reinterpret_cast<const char*>(&custom_fields_size), sizeof(custom_fields_size));
            for (const auto& [key, value] : metadata.customFields) {
                size_t key_size = key.size(), value_size = value.size();
                file.write(reinterpret_cast<const char*>(&key_size), sizeof(key_size));
                file.write(key.data(), key_size);
                file.write(reinterpret_cast<const char*>(&value_size), sizeof(value_size));
                file.write(value.data(), value_size);
            }
            tempQueue.pop();
        }
    }

    void deserializePool(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) throw std::runtime_error("Unable to open file for deserialization");

        size_t pool_size;
        file.read(reinterpret_cast<char*>(&poolSize), sizeof(poolSize));

        while (availableConnections.size() < poolSize) {
            size_t name_size;
            file.read(reinterpret_cast<char*>(&name_size), sizeof(name_size));

            std::string db_name(name_size, '\0');
            file.read(&db_name[0], name_size);

            int state_val;
            file.read(reinterpret_cast<char*>(&state_val), sizeof(state_val));

            uint64_t time_since_epoch;
            file.read(reinterpret_cast<char*>(&time_since_epoch), sizeof(time_since_epoch));

            ConnectionMetadata metadata;
            metadata.databaseName = db_name;
            metadata.state = static_cast<ConnectionMetadata::ConnectionState>(state_val);
            metadata.lastAccessed = std::chrono::steady_clock::time_point(std::chrono::seconds(time_since_epoch));

            file.read(reinterpret_cast<char*>(&metadata.queryCount), sizeof(metadata.queryCount));

            size_t custom_fields_size;
            file.read(reinterpret_cast<char*>(&custom_fields_size), sizeof(custom_fields_size));
            for (size_t i = 0; i < custom_fields_size; ++i) {
                size_t key_size, value_size;
                std::string key, value;
                file.read(reinterpret_cast<char*>(&key_size), sizeof(key_size));
                key.resize(key_size);
                file.read(&key[0], key_size);

                file.read(reinterpret_cast<char*>(&value_size), sizeof(value_size));
                value.resize(value_size);
                file.read(&value[0], value_size);

                metadata.customFields[key] = value;
            }

            auto conn = std::make_shared<DatabaseConnection>(dbService, db_name);
            conn->getMetadata() = metadata; // Assuming direct assignment works for simplification
            availableConnections.push(conn);
        }
    }

private:
    size_t poolSize;
    IDatabaseService* dbService;
    mutable std::mutex poolMutex;
    std::condition_variable cv;
    std::queue<std::shared_ptr<DatabaseConnection>> availableConnections;
};

// Example usage: A simple mockup of an external database service
class MockDatabaseService : public IDatabaseService {
public:
    void connect(const std::string& db_name) override { /* Simulate connection */ }
    void disconnect() override { /* Simulate disconnection */ }
    bool executeQuery(const std::string& query) override { return true; }  // Simulate successful execution
};

// Main function to demonstrate the usage of DatabaseConnectionPool
int main() {
    MockDatabaseService mockService;
    DatabaseConnectionPool pool(10, &mockService);

    auto conn1 = pool.acquire("TestDB");
    conn1->executeQuery("SELECT * FROM users");

    pool.release(conn1);

    // Serialization and Deserialization demonstration
    pool.serializePool("pool_data.bin");
    DatabaseConnectionPool newPool(10, &mockService);
    newPool.deserializePool("pool_data.bin");

    return 0;
}
