#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <zlib.h>
#include <stdint.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB max allocation for simplicity
#define RETRY_LIMIT 3

typedef struct {
    int value;
    long offset;
} record;

typedef struct {
    uint8_t version;
    size_t num_records;
    char* data;
    uint32_t checksum;
} serialized_data;

pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

uint32_t calculate_checksum(const char* data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

int compress_data(const char *data, size_t data_size, char **compressed_data, size_t *compressed_size) {
    uLongf compressed_data_length = compressBound(data_size);
    *compressed_data = malloc(compressed_data_length);
    if (*compressed_data == NULL) {
        log_message("Memory allocation failed for compression.");
        return -1;
    }

    int result = compress((Bytef *)*compressed_data, &compressed_data_length, (const Bytef *)data, data_size);
    *compressed_size = compressed_data_length;

    return result == Z_OK ? 0 : -1;
}

int serialize_records(record *records, size_t num_records, serialized_data **output) {
    if (num_records == 0 || records == NULL) return -1;

    size_t record_size = sizeof(record);
    char *raw_data = malloc(num_records * record_size);
    if (!raw_data) {
        log_message("Memory allocation failed for serialization.");
        return -1;
    }

    memcpy(raw_data, records, num_records * record_size);

    char *compressed_data = NULL;
    size_t compressed_size = 0;
    int compress_result = compress_data(raw_data, num_records * record_size, &compressed_data, &compressed_size);
    free(raw_data);
    if (compress_result != 0) {
        log_message("Data compression failed.");
        return -1;
    }

    uint32_t checksum = calculate_checksum(compressed_data, compressed_size);

    serialized_data *sd = malloc(sizeof(serialized_data));
    sd->version = 1; // Versioning for future compatibility
    sd->num_records = num_records;
    sd->data = compressed_data;
    sd->checksum = checksum;

    *output = sd;
    return 0;
}

int store_serialized_data(serialized_data *sd) {
    if (sd == NULL) return -1;

    int retries = 0;
    while (retries < RETRY_LIMIT) {
        pthread_mutex_lock(&db_lock);

        // Placeholder for database insertion logic.
        // Assume db_insert(sd->data, sd->num_records * sizeof(record)) is a function that returns 0 on success.
        if (/* db_insert(...) == 0 */) {
            pthread_mutex_unlock(&db_lock);
            return 0;
        }

        log_message("Database insert failed. Retrying...");
        retries++;
        pthread_mutex_unlock(&db_lock);
    }

    log_message("Exceeded retry limit for database insertion.");
    return -1;
}

void process_batch(size_t batch_size) {
    if (batch_size * sizeof(record) > MAX_MEMORY_LIMIT) {
        log_message("Batch size exceeds memory limit.");
        return;
    }

    record *records = malloc(batch_size * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records array.");
        return;
    }

    srand(time(NULL));

    for (size_t i = 0; i < batch_size; ++i) {
        records[i].value = random_int(1, 100);
        records[i].offset = (long)i * sizeof(records[0]);
    }

    serialized_data *sd = NULL;
    if (serialize_records(records, batch_size, &sd) == 0) {
        store_serialized_data(sd);
    } else {
        log_message("Serialization failed.");
    }

    free(records);
}

void* process_batch_thread(void *arg) {
    size_t batch_size = *(size_t *)arg;
    process_batch(batch_size);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <batch_size>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    size_t batch_size = atoi(argv[1]);
    int num_threads = sysconf(_SC_NPROCESSORS_ONLN);

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_batch_thread, &batch_size) != 0) {
            log_message("Thread creation failed.");
            continue;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

record* create_records(size_t num_records, size_t *allocated_size) {
    if (num_records == 0 || allocated_size == NULL) return NULL;

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records.");
        return NULL;
    }

    *allocated_size = num_records;
    return records;
}

int find_first_occurrence(const int *array, size_t size, int target) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] == target)
            return i;
    }
    return -1;
}
