Node* create_node(float value, const char *identifier) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed for new node.");
        return NULL;
    }

    new_node->value = value;
    new_node->identifier = strdup(identifier);
