void add_node_to_list(Node **head, float value, const char *identifier) {
    pthread_mutex_lock(&list_mutex);

    Node *new_node = create_node(value, identifier);
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // Check memory usage
    size_t current_memory_usage = sizeof(Node) + strlen(new_node->identifier) + 1;
    while (*head && (current_memory_usage > memory_limit)) {
        Node *temp = *head;
        *head = (*head)->next;
        free(temp->identifier);
        free(temp);
        // Adjust the memory usage
        current_memory_usage -= sizeof(Node) + strlen(temp->identifier) + 1;
    }

    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&list_mutex);
}

