        fread(&len, sizeof(len), 1, input_file);
        len = ntohl(len);

        char *identifier = malloc(len + 1);
        if (!identifier) {
            log_event("Memory allocation failed during deserialization.");
            break;
        }

        fread(identifier, len, 1, input_file);
        identifier[len] = '\0';

        Node *new_node = create_node(value, identifier);
        free(identifier);

        if (new_node) {
            *tail = new_node;
            tail = &new_node->next;
        } else {
            log_event("Memory allocation failed during deserialization.");
            break;
        }
    }

    return head;
}

