#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ERROR_LOG_SIZE 256

typedef struct {
    double value;
    char *buffer;
} data_item;

typedef struct {
    size_t capacity;
    size_t count;
    data_item *items;
    pthread_mutex_t lock;
} data_array;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

size_t get_resource_utilization_factor() {
    // Placeholder function to simulate resource utilization
    return 2;  // Example growth factor
}

data_array* create_data_array(size_t initial_capacity) {
    data_array *arr = malloc(sizeof(data_array));
    if (!arr) {
        log_error("Failed to allocate memory for data array structure");
        return NULL;
    }

    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->items = calloc(initial_capacity, sizeof(data_item));
    if (!arr->items) {
        free(arr);
        log_error("Failed to allocate memory for items");
        return NULL;
    }

    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

int is_valid_string(const char *str, size_t max_len, const char *allowed_chars) {
    if (strlen(str) > max_len) {
        return 0;
    }
    for (size_t i = 0; str[i]; ++i) {
        if (!strchr(allowed_chars, str[i])) {
            return 0;
        }
    }
    return 1;
}

int add_data_item(data_array *arr, double value, const char *string, size_t max_len, const char *allowed_chars) {
    pthread_mutex_lock(&arr->lock);

    if (!is_valid_string(string, max_len, allowed_chars)) {
        log_error("Invalid string input");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity * get_resource_utilization_factor();
        data_item *new_items = realloc(arr->items, new_capacity * sizeof(data_item));
        if (!new_items) {
            log_error("Failed to reallocate memory for items");
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }
        arr->items = new_items;
        arr->capacity = new_capacity;
    }

    data_item item;
    item.value = value;
    item.buffer = malloc(max_len + 1); // +1 for null terminator
    if (!item.buffer) {
        log_error("Failed to allocate memory for string buffer");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }
    strncpy(item.buffer, string, max_len);
    item.buffer[max_len] = '\0';

    arr->items[arr->count++] = item;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

void free_data_array(data_array *arr) {
    if (!arr) return;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->items[i].buffer);
    }
    free(arr->items);
    pthread_mutex_unlock(&arr->lock);

    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

void* concurrent_function(void *arg) {
    data_array *arr = (data_array *)arg;
    double value = 1.23; // Example value
    const char *string = "example"; // Example string
    size_t max_len = 10;
    const char *allowed_chars = "abcdefghijklmnopqrstuvwxyz";

    add_data_item(arr, value, string, max_len, allowed_chars);
    return NULL;
}

int main() {
    data_array *arr = create_data_array(5);

    if (!arr) return EXIT_FAILURE;

    pthread_t threads[10];
    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_create(&threads[i], NULL, concurrent_function, arr);
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    free_data_array(arr);

    return EXIT_SUCCESS;
}
