int decompress_data(const uint8_t *compressed_data, size_t compressed_size, uint8_t **decompressed_data, size_t *decompressed_size);

void initialize_records(Record **records, size_t *record_count, unsigned int max_memory) {
    if (max_memory < sizeof(Record)) return;

    srand(time(NULL));
    size_t record_capacity = max_memory / sizeof(Record);
    *record_count = 0;
    *records = malloc(record_capacity * sizeof(Record));

    if (!*records) {
