        records[i].key = rand() % INT_MAX;
    }
}

int serialize_records(const Record *records, size_t count, uint8_t **buffer, size_t *buffer_size) {
    pthread_mutex_lock(&lock);

    size_t serialized_size = count * (sizeof(int) + sizeof(long) + sizeof(time_t));
    *buffer = malloc(serialized_size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization buffer");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    uint8_t *ptr = *buffer;
    for (size_t i = 0; i < count; ++i) {
        int key = htobe32(records[i].key);
        long offset = htobe64(records[i].offset);
        time_t timestamp = __sync_val_compare_and_swap((time_t*)&timestamp, records[i].timestamp, timestamp);

        memcpy(ptr, &key, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &offset, sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &timestamp, sizeof(time_t));
        ptr += sizeof(time_t);
    }

    *buffer_size = serialized_size;
    pthread_mutex_unlock(&lock);
    return 0;
}

int deserialize_records(const uint8_t *buffer, size_t buffer_size, Record **records, size_t *count) {
    pthread_mutex_lock(&lock);

    if (buffer_size % (sizeof(int) + sizeof(long) + sizeof(time_t)) != 0) {
        perror("Invalid buffer size for deserialization");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *count = buffer_size / (sizeof(int) + sizeof(long) + sizeof(time_t));
    *records = malloc(*count * sizeof(Record));

    if (!*records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    const uint8_t *ptr = buffer;
    for (size_t i = 0; i < *count; ++i) {
        int key = be32toh(*((int *)ptr));
        long offset = be64toh(*((long *)(ptr + sizeof(int))));
        time_t timestamp = *((time_t *)(ptr + sizeof(int) + sizeof(long)));

        (*records)[i].key = key;
        (*records)[i].offset = offset;
        (*records)[i].timestamp = timestamp;

        ptr += (sizeof(int) + sizeof(long) + sizeof(time_t));
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

int compress_data(const uint8_t *data, size_t data_size, uint8_t **compressed_data, size_t *compressed_size) {
    uLongf compressed_buf_size = compressBound(data_size);
    *compressed_data = malloc(compressed_buf_size);

    if (!*compressed_data) {
        perror("Failed to allocate memory for compression");
        return -1;
    }

    int result = compress(*compressed_data, &compressed_buf_size, data, data_size);
    if (result != Z_OK) {
        free(*compressed_data);
        *compressed_data = NULL;
        return -1;
    }

    *compressed_size = compressed_buf_size;
    return 0;
}

int decompress_data(const uint8_t *compressed_data, size_t compressed_size, uint8_t **decompressed_data, size_t *decompressed_size) {
    uLongf decompressed_buf_size = *decompressed_size; // Should be set to the expected uncompressed size

    *decompressed_data = malloc(decompressed_buf_size);

    if (!*decompressed_data) {
        perror("Failed to allocate memory for decompression");
        return -1;
    }

    int result = uncompress(*decompressed_data, &decompressed_buf_size, compressed_data, compressed_size);
    if (result != Z_OK) {
        free(*decompressed_data);
        *decompressed_data = NULL;
        return -1;
    }

    *decompressed_size = decompressed_buf_size;
    return 0;
}

void cleanup(Record *records, uint8_t *buffer, uint8_t *compressed_data) {
    pthread_mutex_lock(&lock);

    free(records);
    free(buffer);
    free(compressed_data);

    pthread_mutex_unlock(&lock);
