#define MAX_OFFSET_SIZE 1000000

typedef struct {
    int key;
    long offset_index; // Index to the offsets array
} record_t;

typedef struct {
    long* offsets;
    size_t offset_count;
    int* keys;
    size_t key_capacity;
    int unique_key_map[MAX_OFFSET_SIZE / sizeof(int)]; // Simple hash map for uniqueness check
    record_t** records;
    size_t record_count;
    pthread_mutex_t lock; // Mutex for thread safety
} data_manager_t;

data_manager_t* create_data_manager(size_t initial_offset_count, size_t initial_key_capacity) {
    data_manager_t* manager = (data_manager_t*)malloc(sizeof(data_manager_t));
    if (!manager) {
        perror("Failed to allocate memory for data manager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->offsets = (long*)calloc(initial_offset_count, sizeof(long));
    if (!manager->offsets) {
        free(manager);
        perror("Failed to allocate memory for offsets array");
        return NULL;
    }
    manager->offset_count = initial_offset_count;

    manager->keys = (int*)malloc(initial_key_capacity * sizeof(int));
    if (!manager->keys) {
        free(manager->offsets);
        free(manager);
        perror("Failed to allocate memory for keys array");
        return NULL;
    }
    memset(manager->unique_key_map, 0, sizeof(manager->unique_key_map));
    manager->key_capacity = initial_key_capacity;

    manager->records = (record_t**)malloc(initial_offset_count * sizeof(record_t*));
    if (!manager->records) {
        free(manager->keys);
        free(manager->offsets);
        free(manager);
        perror("Failed to allocate memory for records array");
        return NULL;
    }
    manager->record_count = 0;

    return manager;
}

int add_offset(data_manager_t* manager, long offset) {
    if (offset < 0 || offset >= MAX_OFFSET_SIZE) {
        fprintf(stderr, "Offset %ld out of bounds\n", offset);
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->offset_count == MAX_OFFSET_SIZE) {
        pthread_mutex_unlock(&manager->lock);
        fprintf(stderr, "Reached maximum offset capacity\n");
        return -2;
    }

    manager->offsets[manager->offset_count++] = offset;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_key(data_manager_t* manager, int key) {
    if (key < 0 || key >= MAX_OFFSET_SIZE / sizeof(int)) {
        fprintf(stderr, "Key %d out of bounds\n", key);
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->unique_key_map[key]) {
        pthread_mutex_unlock(&manager->lock);
        fprintf(stderr, "Duplicate key %d detected\n", key);
        return -2;
    }

    if ((size_t)key >= manager->key_capacity) {
        int* new_keys = (int*)realloc(manager->keys, 2 * manager->key_capacity * sizeof(int));
        if (!new_keys) {
            pthread_mutex_unlock(&manager->lock);
            perror("Failed to reallocate memory for keys array");
            return -3;
        }
        manager->keys = new_keys;
        memset(manager->unique_key_map + manager->key_capacity, 0,
               (2 * manager->key_capacity - manager->key_capacity) / sizeof(int));
        manager->key_capacity *= 2;
    }

    manager->keys[key] = key;
    manager->unique_key_map[key] = 1;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_record(data_manager_t* manager, int key, long offset_index) {
    if (offset_index >= manager->offset_count || manager->offsets[offset_index] < 0) {
        fprintf(stderr, "Invalid offset index %ld\n", offset_index);
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    if ((size_t)offset_index >= manager->record_count) {
        record_t** new_records = (record_t**)realloc(manager->records,
                                                     2 * manager->record_count * sizeof(record_t*));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            perror("Failed to reallocate memory for records array");
            return -2;
        }
        manager->records = new_records;
    }

    record_t* record = (record_t*)malloc(sizeof(record_t));
    if (!record) {
        pthread_mutex_unlock(&manager->lock);
        perror("Failed to allocate memory for record structure");
        return -3;
    }

    record->key = key;
    record->offset_index = offset_index;

    manager->records[manager->record_count++] = record;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_data_manager(data_manager_t* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->record_count; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);
    free(manager->keys);
    free(manager->offsets);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

