['Below is a C implementation that addresses the specified requirements for managing memory for two arrays (`long` offset values and `int` keys) and an array of `record` structures with custom memory management features:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

// Custom memory allocator for aligned memory
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Custom memory deallocator for aligned memory
void aligned_free(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t num_offsets;
    size_t num_keys;
    size_t num_records;
} MemoryManager;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_event(const char* event) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), event);
}

MemoryManager* initialize_memory(size_t num_offsets, size_t num_keys, size_t num_records, int min_val, int max_val) {
    if (num_offsets == 0 || num_keys == 0 || num_records == 0 || min_val >= max_val) {
        fprintf(stderr, "Invalid parameters\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    MemoryManager* mm = malloc(sizeof(MemoryManager));

    if (!mm) {
        perror("Failed to allocate memory for manager");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    mm->offsets = aligned_alloc(8, num_offsets * sizeof(long));
    if (!mm->offsets) {
        fprintf(stderr, "Failed to allocate offsets\n");
        free(mm);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    log_event("Allocated memory for offsets");

    mm->keys = aligned_alloc(4, num_keys * sizeof(int));
    if (!mm->keys) {
        fprintf(stderr, "Failed to allocate keys\n");
        aligned_free(mm->offsets);
        free(mm);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    log_event("Allocated memory for keys");

    mm->records = aligned_alloc(8, num_records * sizeof(record));
    if (!mm->records) {
        fprintf(stderr, "Failed to allocate records\n");
        aligned_free(mm->keys);
        aligned_free(mm->offsets);
        free(mm);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    log_event("Allocated memory for records");

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        mm->records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    mm->num_offsets = num_offsets;
    mm->num_keys = num_keys;
    mm->num_records = num_records;

    pthread_mutex_unlock(&mutex);

    return mm;
}

void free_memory(MemoryManager* mm, int free_all) {
    if (!mm) return;

    pthread_mutex_lock(&mutex);

    if (free_all || mm->offsets) {
        aligned_free(mm->offsets);
        log_event("Deallocated memory for offsets");
    }
    if (free_all || mm->keys) {
        aligned_free(mm->keys);
        log_event("Deallocated memory for keys");
    }
    if (free_all || mm->records) {
        aligned_free(mm->records);
        log_event("Deallocated memory for records");
    }

    free(mm);
    log_event("Deallocated memory manager");

    pthread_mutex_unlock(&mutex);
}

// Example usage
int main() {
    size_t num_offsets = 10;
    size_t num_keys = 5;
    size_t num_records = 8;
    int min_val = 0, max_val = 100;

    MemoryManager* mm = initialize_memory(num_offsets, num_keys, num_records, min_val, max_val);

    if (mm) {
        // Use the allocated memory for your application logic here
        free_memory(mm, 1);  // Free all resources
    }

    return 0;
}
```

### Key Features:

- **Custom Memory Allocator:** Uses `_aligned_malloc` on Windows and `posix_memalign` on other systems to handle alignment.
- **Logging:** Logs allocation and deallocation events with timestamps for monitoring purposes.
- **Thread Safety:** Utilizes a mutex to ensure thread-safe operations during memory management.
- **Error Handling:** Checks for valid input parameters and handles allocation failures gracefully, providing informative error messages.
- **Memory Pooling/Fragmentation:** While not implemented in detail here due to complexity, the example lays groundwork for potential optimizations like using custom allocators or pools.']

