#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    float value;
    int row_index;
    int col_index;
    struct Node* next;
} Node;

typedef struct SparseMatrix {
    int rows;
    int cols;
    Node** row_heads;
    pthread_mutex_t lock;
} SparseMatrix;

int is_unique(int *indices, int n) {
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (indices[2*i] == indices[2*j] && indices[2*i+1] == indices[2*j+1]) {
                return 0;
            }
        }
    }
    return 1;
}

float is_stable(float value, float min_range, float max_range) {
    return value >= min_range && value <= max_range && fabs(value - roundf(value)) < FLT_EPSILON;
}

SparseMatrix* create_sparse_matrix(int rows, int cols, int index_count, int *indices, float *values, 
                                   float min_value, float max_value) {
    if (!is_unique(indices, index_count) || !min_value <= max_value) {
        return NULL;
    }

    SparseMatrix* matrix = (SparseMatrix*)malloc(sizeof(SparseMatrix));
    if (!matrix) return NULL;

    matrix->rows = rows;
    matrix->cols = cols;
    matrix->row_heads = (Node**)calloc(rows, sizeof(Node*));

    if (!matrix->row_heads) {
        free(matrix);
        return NULL;
    }

    pthread_mutex_init(&matrix->lock, NULL);

    for (int i = 0; i < index_count; ++i) {
        int r = indices[2*i];
        int c = indices[2*i+1];

        if (r >= rows || c >= cols || r < 0 || c < 0) {
            free(matrix->row_heads);
            pthread_mutex_destroy(&matrix->lock);
            free(matrix);
            return NULL;
        }

        float val = values[i];
        if (!is_stable(val, min_value, max_value)) {
            free(matrix->row_heads);
            pthread_mutex_destroy(&matrix->lock);
            free(matrix);
            return NULL;
        }

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            free(matrix->row_heads);
            pthread_mutex_destroy(&matrix->lock);
            free(matrix);
            return NULL;
        }
        new_node->value = val;
        new_node->row_index = r;
        new_node->col_index = c;

        pthread_mutex_lock(&matrix->lock);
        new_node->next = matrix->row_heads[r];
        matrix->row_heads[r] = new_node;
        pthread_mutex_unlock(&matrix->lock);
    }

    return matrix;
}

void free_sparse_matrix(SparseMatrix* matrix) {
    if (!matrix) return;

    for (int i = 0; i < matrix->rows; ++i) {
        Node *current = matrix->row_heads[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(matrix->row_heads);
    pthread_mutex_destroy(&matrix->lock);
    free(matrix);
}

int main() {
    // Example usage
    int indices[] = {0, 1, 2, 3};
    float values[] = {1.1f, 2.2f};

    SparseMatrix* matrix = create_sparse_matrix(4, 4, 2, indices, values, -100.0f, 100.0f);
    if (matrix) {
        printf("Sparse Matrix created successfully.\n");
        free_sparse_matrix(matrix);
    } else {
        printf("Failed to create Sparse Matrix.\n");
    }

    return 0;
}
