#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_OFFSET_ARRAY_SIZE 1024
#define UNIQUE_KEY_RANGE 10000

typedef struct {
    int *data;
    size_t size;
    pthread_mutex_t lock;
} OffsetArray;

typedef struct {
    bool *key_exists;
    pthread_rwlock_t rwlock;
} UniqueKeyArray;

typedef struct {
    int value;
    uint32_t offset_index;
    int key;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordList;

// Memory Pool for efficient allocation
typedef struct MemoryPool {
    void *memory;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

void* memory_pool_alloc(MemoryPool *pool);
void memory_pool_free_all(MemoryPool *pool);

// Offset Array Functions
OffsetArray* offset_array_init(size_t initial_size);
int offset_array_add(OffsetArray *offset_array, int value);
size_t offset_array_get_size(const OffsetArray *offset_array);
void offset_array_cleanup(OffsetArray *offset_array);

// Unique Key Array Functions
UniqueKeyArray* unique_key_array_init();
bool unique_key_array_insert(UniqueKeyArray *key_array, int key);
bool unique_key_array_exists(const UniqueKeyArray *key_array, int key);
void unique_key_array_cleanup(UniqueKeyArray *key_array);

// Record Structure Functions
RecordList* record_list_init(size_t capacity);
int record_list_add(RecordList *record_list, int value, uint32_t offset_index, int key);
Record* record_list_get(const RecordList *record_list, size_t index);
void record_list_cleanup(RecordList *record_list);

// Memory Management Functions
MemoryPool* memory_pool_init(size_t block_size, size_t total_blocks);
void* memory_pool_alloc(MemoryPool *pool);
void memory_pool_free_all(MemoryPool *pool);

// Concurrency and Thread Safety Utilities
void log_event(const char *event);

// Job Prioritization Helper Function
int get_highest_priority_job();

// Implementations

OffsetArray* offset_array_init(size_t initial_size) {
    OffsetArray *array = malloc(sizeof(OffsetArray));
    array->data = calloc(initial_size, sizeof(int));
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int offset_array_add(OffsetArray *offset_array, int value) {
    if (value < 0 || offset_array->size >= MAX_OFFSET_ARRAY_SIZE) return -1;

    pthread_mutex_lock(&offset_array->lock);
    offset_array->data[offset_array->size++] = value;
    pthread_mutex_unlock(&offset_array->lock);

    log_event("Offset added");

    return 0;
}

size_t offset_array_get_size(const OffsetArray *offset_array) {
    return offset_array->size;
}

void offset_array_cleanup(OffsetArray *offset_array) {
    free(offset_array->data);
    pthread_mutex_destroy(&offset_array->lock);
    free(offset_array);
}

UniqueKeyArray* unique_key_array_init() {
    UniqueKeyArray *array = malloc(sizeof(UniqueKeyArray));
    array->key_exists = calloc(UNIQUE_KEY_RANGE, sizeof(bool));
    pthread_rwlock_init(&array->rwlock, NULL);
    return array;
}

bool unique_key_array_insert(UniqueKeyArray *key_array, int key) {
    if (key < 0 || key >= UNIQUE_KEY_RANGE) return false;

    pthread_rwlock_wrlock(&key_array->rwlock);
    if (!key_array->key_exists[key]) {
        key_array->key_exists[key] = true;
        pthread_rwlock_unlock(&key_array->rwlock);
        log_event("Unique key inserted");
        return true;
    }
    pthread_rwlock_unlock(&key_array->rwlock);
    return false;
}

bool unique_key_array_exists(const UniqueKeyArray *key_array, int key) {
    if (key < 0 || key >= UNIQUE_KEY_RANGE) return false;

    pthread_rwlock_rdlock(&key_array->rwlock);
    bool exists = key_array->key_exists[key];
    pthread_rwlock_unlock(&key_array->rwlock);

    log_event("Unique key checked");
    return exists;
}

void unique_key_array_cleanup(UniqueKeyArray *key_array) {
    free(key_array->key_exists);
    pthread_rwlock_destroy(&key_array->rwlock);
    free(key_array);
}

RecordList* record_list_init(size_t capacity) {
    RecordList *list = malloc(sizeof(RecordList));
    list->records = calloc(capacity, sizeof(Record));
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int record_list_add(RecordList *record_list, int value, uint32_t offset_index, int key) {
    if (offset_index >= MAX_OFFSET_ARRAY_SIZE || record_list->count >= record_list->capacity)
        return -1;

    pthread_mutex_lock(&record_list->lock);
    record_list->records[record_list->count++] = (Record){value, offset_index, key};
    pthread_mutex_unlock(&record_list->lock);

    log_event("Record added");
    return 0;
}

Record* record_list_get(const RecordList *record_list, size_t index) {
    if (index >= record_list->count)
        return NULL;

    return &record_list->records[index];
}

void record_list_cleanup(RecordList *record_list) {
    free(record_list->records);
    pthread_mutex_destroy(&record_list->lock);
    free(record_list);
}

MemoryPool* memory_pool_init(size_t block_size, size_t total_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->memory = calloc(total_blocks, block_size);
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->used_blocks = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* memory_pool_alloc(MemoryPool *pool) {
    if (pool->used_blocks >= pool->total_blocks)
        return NULL;

    pthread_mutex_lock(&pool->lock);
    void *block = (char*)pool->memory + pool->used_blocks * pool->block_size;
    pool->used_blocks++;
    pthread_mutex_unlock(&pool->lock);

    log_event("Memory allocated");
    return block;
}

void memory_pool_free_all(MemoryPool *pool) {
    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void log_event(const char *event) {
    // Integrate with an external logging system
    printf("[LOG] %s\n", event);
}

int get_highest_priority_job() {
    int job_id, priority;
    int highest_priority = -1;
    int highest_priority_job_id = -1;

    while (scanf("%d %d", &job_id, &priority) == 2) {
        if (priority > highest_priority) {
            highest_priority = priority;
            highest_priority_job_id = job_id;
        }
    }

    log_event("Highest priority job determined");
    return highest_priority_job_id;
}
