#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>

#define MAX_MEMORY_SIZE 1024 * 1024 // Example max memory size (1 MB)
#define TASK_NAME_MAX_LEN 256

typedef struct Task {
    char task_name[TASK_NAME_MAX_LEN];
    int priority;
    struct timeval last_update;
} Task;

typedef struct TaskManager {
    Task **tasks;
    size_t capacity;
    size_t count;
    size_t used_memory;
} TaskManager;

TaskManager* create_task_manager(size_t initial_capacity) {
    TaskManager *tm = (TaskManager*)malloc(sizeof(TaskManager));
    if (!tm) return NULL;

    tm->tasks = (Task**)calloc(initial_capacity, sizeof(Task*));
    if (!tm->tasks) {
        free(tm);
        return NULL;
    }

    tm->capacity = initial_capacity;
    tm->count = 0;
    tm->used_memory = sizeof(TaskManager) + initial_capacity * sizeof(Task*);

    return tm;
}

void destroy_task_manager(TaskManager *tm) {
    if (!tm) return;

    for (size_t i = 0; i < tm->count; ++i) {
        free(tm->tasks[i]->task_name);
        free(tm->tasks[i]);
    }
    free(tm->tasks);
    free(tm);
}

int add_task(TaskManager *tm, const char *name, int priority, struct timeval last_update) {
    if (!tm || tm->used_memory + sizeof(Task) > MAX_MEMORY_SIZE) return -1;

    Task *task = (Task*)malloc(sizeof(Task));
    if (!task) return -1;

    size_t name_len = strlen(name);
    task->task_name = (char*)malloc(name_len + 1);
    if (!task->task_name) {
        free(task);
        return -1;
    }
    strncpy(task->task_name, name, name_len + 1);

    task->priority = priority;
    task->last_update = last_update;

    if (tm->count == tm->capacity) {
        size_t new_capacity = tm->capacity * 2;
        Task **new_tasks = (Task**)realloc(tm->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            free(task->task_name);
            free(task);
            return -1;
        }
        memset(new_tasks + tm->capacity, 0, tm->capacity * sizeof(Task*));
        tm->tasks = new_tasks;
        tm->capacity = new_capacity;
    }

    tm->tasks[tm->count++] = task;
    tm->used_memory += sizeof(Task) + name_len + 1;

    return 0;
}

void update_task_priority(TaskManager *tm, int index, int new_priority) {
    if (!tm || index < 0 || index >= tm->count) return;

    Task *task = tm->tasks[index];
    task->priority = new_priority;
    gettimeofday(&task->last_update, NULL);
}

unsigned char* serialize_task(Task *task, size_t *out_size) {
    if (!task || !out_size) return NULL;

    size_t name_len = strlen(task->task_name);
    size_t total_size = sizeof(int) + sizeof(struct timeval) + name_len + 1;
    unsigned char *buffer = (unsigned char*)malloc(total_size);
    if (!buffer) return NULL;

    int priority_be = htonl(task->priority);
    memcpy(buffer, &priority_be, sizeof(int));

    struct timeval tv = task->last_update;
    long tv_sec_be = htobe64(tv.tv_sec);
    suseconds_t tv_usec_be = htobe32(tv.tv_usec);

    memcpy(buffer + sizeof(int), &tv_sec_be, sizeof(long));
    memcpy(buffer + sizeof(int) + sizeof(long), &tv_usec_be, sizeof(suseconds_t));

    memcpy(buffer + sizeof(int) + sizeof(struct timeval), task->task_name, name_len + 1);

    *out_size = total_size;
    return buffer;
}

Task* deserialize_task(unsigned char *buffer, size_t size) {
    if (!buffer || size < sizeof(int) + sizeof(struct timeval)) return NULL;

    Task *task = (Task*)malloc(sizeof(Task));
    if (!task) return NULL;

    int priority_be = *(int*)buffer;
    task->priority = ntohl(priority_be);

    long tv_sec_be = be64toh(*(long*)(buffer + sizeof(int)));
    suseconds_t tv_usec_be = be32toh(*(suseconds_t*)(buffer + sizeof(int) + sizeof(long)));

    struct timeval tv = { .tv_sec = tv_sec_be, .tv_usec = tv_usec_be };
    task->last_update = tv;

    size_t name_len = size - (sizeof(int) + sizeof(struct timeval));
    task->task_name = (char*)malloc(name_len + 1);
    if (!task->task_name) {
        free(task);
        return NULL;
    }
    memcpy(task->task_name, buffer + sizeof(int) + sizeof(struct timeval), name_len + 1);

    return task;
}

void log_message(const char *message) {
    printf("Log: %s\n", message);
}
