#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_MEMORY 1048576 // 1MB for example purposes
#define RECORD_SIZE sizeof(record)
#define INT_MIN -100
#define INT_MAX 100

typedef struct {
    int value;
    long offset;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated_memory = 0;
const char* valid_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

typedef struct pool_node {
    record *records;
    struct pool_node *next;
} pool_node;

pool_node *free_list_head = NULL;

void init_random() {
    srand(time(NULL));
}

int random_int_in_range(int min, int max) {
    return min + rand() % ((max - min) + 1);
}

record* allocate_record_array(size_t count) {
    pthread_mutex_lock(&mutex);

    pool_node *new_node = NULL;
    if (free_list_head == NULL || allocated_memory + RECORD_SIZE * count > MAX_MEMORY) {
        new_node = malloc(sizeof(pool_node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for pool node\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        size_t total_records_size = RECORD_SIZE * count;
        allocated_memory += total_records_size;

        if (allocated_memory > MAX_MEMORY) {
            free(new_node);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        new_node->records = malloc(total_records_size);
        if (!new_node->records) {
            fprintf(stderr, "Failed to allocate memory for records\n");
            free(new_node);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        for (size_t i = 0; i < count; ++i) {
            new_node->records[i].value = random_int_in_range(INT_MIN, INT_MAX);
            new_node->records[i].offset = rand(); // Example offset
        }

        new_node->next = free_list_head;
        free_list_head = new_node;
    } else {
        new_node = free_list_head;
        free_list_head = free_list_head->next;

        for (size_t i = 0; i < count; ++i) {
            new_node->records[i].value = random_int_in_range(INT_MIN, INT_MAX);
            new_node->records[i].offset = rand(); // Example offset
        }
    }

    pthread_mutex_unlock(&mutex);
    return new_node->records;
}

void serialize_record_array(record *array, size_t count, uint8_t **buffer) {
    size_t buffer_size = count * (sizeof(int) + sizeof(long));
    *buffer = malloc(buffer_size);

    if (!*buffer) {
        fprintf(stderr, "Failed to allocate memory for serialization buffer\n");
        return;
    }

    uint8_t *ptr = *buffer;
    for (size_t i = 0; i < count; ++i) {
        // Assuming little-endian architecture for demonstration
        memcpy(ptr, &array[i].value, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &array[i].offset, sizeof(long));
        ptr += sizeof(long);
    }
}

record* deserialize_record_array(const uint8_t *buffer, size_t count) {
    record *result = malloc(count * RECORD_SIZE);

    const uint8_t *ptr = buffer;
    for (size_t i = 0; i < count; ++i) {
        memcpy(&result[i].value, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&result[i].offset, ptr, sizeof(long));
        ptr += sizeof(long);
    }

    return result;
}

void find_largest_integer() {
    int n, max = INT_MIN;
    printf("Enter the number of integers: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    int *arr = malloc(n * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Invalid input at position %d\n", i + 1);
            free(arr);
            return;
        }
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    printf("The largest integer is: %d\n", max);
    free(arr);
}

char* generate_random_string(size_t length, const char *charset) {
    if (!charset || length <= 0) return NULL;

    size_t charset_size = strlen(charset);
    char *str = malloc((length + 1) * sizeof(char));

    if (!str) return NULL;

    init_random();
    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % charset_size];
    }
    str[length] = '\0';

    return str;
}

#include <openssl/evp.h>

void hash_password(const char *password, unsigned char **hash_output, size_t *output_len) {
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    const EVP_MD *md_type = EVP_sha256();

    if (!EVP_DigestInit_ex(ctx, md_type, NULL)) {
        fprintf(stderr, "DigestInit failed\n");
        return;
    }

    unsigned char salt[16];
    RAND_bytes(salt, sizeof(salt));

    // Prepend the salt to the password
    size_t password_len = strlen(password);
    unsigned char *salted_password = malloc(password_len + sizeof(salt));

    memcpy(salted_password, salt, sizeof(salt));
    memcpy(salted_password + sizeof(salt), password, password_len);

    if (!EVP_DigestUpdate(ctx, salted_password, password_len + sizeof(salt))) {
        fprintf(stderr, "DigestUpdate failed\n");
        free(salted_password);
        EVP_MD_CTX_free(ctx);
        return;
    }

    *hash_output = malloc(EVP_MAX_MD_SIZE);

    if (!*hash_output) {
        free(salted_password);
        EVP_MD_CTX_free(ctx);
        return;
    }

    if (!EVP_DigestFinal_ex(ctx, *hash_output, output_len)) {
        fprintf(stderr, "DigestFinal failed\n");
        free(*hash_output);
        free(salted_password);
        EVP_MD_CTX_free(ctx);
        return;
    }

    free(salted_password);
    EVP_MD_CTX_free(ctx);
}

int main() {
    // Example usage
    size_t record_count = 10;
    record *records = allocate_record_array(record_count);

    if (records) {
        uint8_t *buffer;
        serialize_record_array(records, record_count, &buffer);

        record *deserialized_records = deserialize_record_array(buffer, record_count);

        find_largest_integer();

        size_t hash_len;
        unsigned char *hashed_password;
        hash_password("securepassword123", &hashed_password, &hash_len);

        // Clean up
        free(records);
        free(buffer);
        free(deserialized_records);
        free(hashed_password);
    }

    return 0;
}
