// record_management.h

#ifndef RECORD_MANAGEMENT_H
#define RECORD_MANAGEMENT_H

#include <pthread.h>
#include <stdint.h>

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    Record *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    size_t max_size;
} DynamicArray;

// Initialize the dynamic array
void init_dynamic_array(DynamicArray *da, size_t initial_capacity, size_t max_size);

// Add a record to the dynamic array
int add_record(DynamicArray *da, int value, long offset);

// Serialize the dynamic array into binary format
size_t serialize(const DynamicArray *da, uint8_t **buffer);

// Deserialize binary data back into a dynamic array
DynamicArray* deserialize(uint8_t *data, size_t length, size_t max_size);

// Free resources associated with the dynamic array
void free_dynamic_array(DynamicArray *da);

// Initialize and populate the array with random values
int populate_random_values(DynamicArray *da, int min_value, int max_value);

// Performance monitoring function (stub)
void monitor_performance(void);

// Helper function to find largest integer from standard input
