// Generate a random string of specified length using character set
char* generate_random_string(size_t length, const char *charset);

#endif // RECORD_MANAGEMENT_H

// record_management.c

#include "record_management.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <errno.h>

#define INITIAL_CAPACITY 10

void init_dynamic_array(DynamicArray *da, size_t initial_capacity, size_t max_size) {
    pthread_mutex_init(&da->mutex, NULL);
    da->capacity = (initial_capacity > 0) ? initial_capacity : INITIAL_CAPACITY;
    da->size = 0;
    da->max_size = max_size;
    da->array = malloc(da->capacity * sizeof(Record));
}

int add_record(DynamicArray *da, int value, long offset) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity || da->size >= da->max_size) {
        pthread_mutex_unlock(&da->mutex);
        return -1;
    }

    da->array[da->size].value = value;
    da->array[da->size].offset = offset;
    da->size++;

    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        if (new_capacity > da->max_size) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        Record *temp = realloc(da->array, new_capacity * sizeof(Record));
        if (!temp) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = temp;
        da->capacity = new_capacity;
    }

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

size_t serialize(const DynamicArray *da, uint8_t **buffer) {
    size_t total_size = sizeof(size_t) + da->size * (sizeof(int) + sizeof(long));
    *buffer = malloc(total_size);

    if (!*buffer) return 0;

    memcpy(*buffer, &da->size, sizeof(size_t));
    uint8_t *ptr = *buffer + sizeof(size_t);

    for (size_t i = 0; i < da->size; ++i) {
        int value = htobe32(da->array[i].value);
        long offset = htobe64(da->array[i].offset);

        memcpy(ptr, &value, sizeof(int));
        ptr += sizeof(int);

        memcpy(ptr, &offset, sizeof(long));
        ptr += sizeof(long);
    }

    return total_size;
}

DynamicArray* deserialize(uint8_t *data, size_t length, size_t max_size) {
    if (length < sizeof(size_t)) return NULL;

    size_t array_size;
    memcpy(&array_size, data, sizeof(size_t));

    DynamicArray *da = malloc(sizeof(DynamicArray));
    init_dynamic_array(da, array_size, max_size);

    uint8_t *ptr = data + sizeof(size_t);

    for (size_t i = 0; i < array_size; ++i) {
        int value;
        long offset;

        memcpy(&value, ptr, sizeof(int));
        ptr += sizeof(int);
        value = be32toh(value);

        memcpy(&offset, ptr, sizeof(long));
        ptr += sizeof(long);
        offset = be64toh(offset);

        if (add_record(da, value, offset) != 0) {
            free_dynamic_array(da);
            return NULL;
        }
    }

    return da;
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_destroy(&da->mutex);
    free(da->array);
    free(da);
}

int populate_random_values(DynamicArray *da, int min_value, int max_value) {
    if (min_value > max_value) return -1;

    srand((unsigned)time(NULL));

    for (size_t i = 0; i < da->capacity && i < da->max_size; ++i) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        long offset = rand();
        if (add_record(da, value, offset) != 0) return -1;
    }

    return 0;
}

void monitor_performance(void) {
    // Performance monitoring logic
}

int read_and_find_largest_integer(void) {
    int largest = INT_MIN;
    int num;

    printf("Enter integers (non-integer to stop): \n");

    while (scanf("%d", &num) == 1) {
        if (num > largest) {
            largest = num;
        }
    }

    return largest;
}

char* generate_random_string(size_t length, const char *charset) {
    if (!charset || length <= 0) return NULL;

    size_t charset_length = strlen(charset);
    char *random_string = malloc(length + 1);

    if (!random_string) return NULL;

    srand((unsigned)time(NULL));

    for (size_t i = 0; i < length; ++i) {
        random_string[i] = charset[rand() % charset_length];
    }

    random_string[length] = '\0';
    return random_string;
}

