int main() {
    DynamicArray da;
    init_dynamic_array(&da, 20, 100);

    populate_random_values(&da, 1, 100);

    uint8_t *buffer;
    size_t buffer_size = serialize(&da, &buffer);

    if (buffer) {
        // Do something with the serialized data
        free(buffer);
    }

    DynamicArray *deserialized_da = deserialize(buffer, buffer_size, 100);
    if (deserialized_da) {
