        url: `https://example-cdn.com/upload/${encodeURIComponent(filePath)}`
      });

      await streamPipeline(fileStream, request);

      const response = await new Promise((resolve, reject) => {
        let data = '';

        request.on('data', chunk => { data += chunk; });
        request.on('end', () => resolve(data));
        request.on('error', err => reject(err));
      });

      if (response.statusCode === 200) {
        success = true;
        return 'Upload successful';
      }
    } catch (error) {
      attempts++;
      console.error(`Upload attempt ${attempts} failed: ${error.message}`);
    }

    // Exponential backoff
    await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempts) * 1000));
  }

  throw new Error('Failed to upload file after multiple retries');
}

async function uploadFileAsynchronously(filePath, callback) {
  const fileStream = fs.createReadStream(filePath, { highWaterMark: 1024 * 1024 }); // 1MB chunks

  try {
    const result = await uploadFile(fileStream, filePath);
    callback(null, result);
  } catch (error) {
    callback(error.message);
  }
}

async function validateFileContent(filePath, schema) {
  const ajv = new Ajv();
  const validate = ajv.compile(schema);

  let isValid = true;
  const errors = [];

  fs.createReadStream(filePath, { encoding: 'utf8' })
    .on('data', chunk => {
      // Assuming file content is JSON for simplicity
      try {
        const data = JSON.parse(chunk);
        if (!validate(data)) {
          isValid = false;
          validate.errors.forEach(err => errors.push(`Line ${err.dataPath}: ${err.message}`));
        }
      } catch (error) {
        isValid = false;
        errors.push(`Parse error: ${error.message}`);
      }
    })
    .on('end', () => {
      if (isValid) {
        return 'Validation successful';
      } else {
        return `Validation failed: ${errors.join(', ')}`;
      }
    });
}

async function compressFile(filePath, outputDir) {
  const algorithms = {
    gzip: zlib.createGzip,
    deflate: zlib.createDeflate,
    brotli: zlib.createBrotliCompress
  };

  if (!algorithms['gzip']) { // Fallback to gzip if no algorithm matches
    throw new Error('No supported compression algorithm found');
  }

  const outputFilePath = `${outputDir}/${path.basename(filePath)}.gz`;
  const readStream = fs.createReadStream(filePath);
  const writeStream = fs.createWriteStream(outputFilePath);
  const compressStream = algorithms['gzip']();

  try {
    await streamPipeline(readStream, compressStream, writeStream);

    const originalSize = fs.statSync(filePath).size;
    const compressedSize = fs.statSync(outputFilePath).size;
    const compressionRatio = (originalSize - compressedSize) / originalSize * 100;

    return `Compression successful. Original size: ${originalSize} bytes, Compressed size: ${compressedSize} bytes (${compressionRatio.toFixed(2)}% reduction)`;
  } catch (error) {
    throw new Error(`Compression failed: ${error.message}`);
  }
}

module.exports = { uploadFileAsynchronously, validateFileContent, compressFile };
