#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_LOG_ENTRIES 1000
#define MAX_MEMORY_SIZE 1024 * 1024  // 1 MB for example

typedef struct {
    char* message;
    time_t timestamp;
    size_t access_count;
    bool archive_flag;
} log_entry;

typedef struct {
    log_entry* entries;
    size_t entry_count;
    pthread_mutex_t lock;
    size_t total_memory_allocated;
    int max_log_size;
} log_collection;

void seed_random_time() {
    srand((unsigned int)time(NULL));
}

log_entry create_log_entry(const char* message, time_t start_range, time_t end_range) {
    log_entry entry;
    entry.message = strdup(message);
    if (!entry.message) exit(EXIT_FAILURE);

    entry.timestamp = start_range + (rand() % (end_range - start_range + 1));
    entry.access_count = 0;
    entry.archive_flag = false;

    return entry;
}

log_collection* initialize_log_collection(size_t max_entries, int max_log_size) {
    log_collection* collection = malloc(sizeof(log_collection));
    if (!collection) exit(EXIT_FAILURE);

    collection->entries = calloc(max_entries, sizeof(log_entry));
    if (!collection->entries) {
        free(collection);
        exit(EXIT_FAILURE);
    }

    collection->entry_count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->total_memory_allocated = max_entries * sizeof(log_entry);
    collection->max_log_size = max_log_size;

    return collection;
}

void add_log_entry(log_collection* collection, const char* message) {
    pthread_mutex_lock(&collection->lock);

    if (collection->entry_count >= MAX_LOG_ENTRIES || 
        collection->total_memory_allocated + strlen(message) + 1 > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Cannot add new log entry: memory or entry limit reached.\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    time_t current_time = time(NULL);
    const time_t start_range = current_time - 86400; // last 24 hours
    const time_t end_range = current_time;

    log_entry new_entry = create_log_entry(message, start_range, end_range);
    collection->entries[collection->entry_count++] = new_entry;

    size_t message_size = strlen(new_entry.message) + 1;
    collection->total_memory_allocated += message_size;

    pthread_mutex_unlock(&collection->lock);

    // Simulate external system load affecting access count
    for (size_t i = 0; i < collection->entry_count; ++i) {
        if (rand() % 10 > 5) { // Arbitrary condition simulating load
            collection->entries[i].access_count++;
        }
    }
}

void serialize_log_collection(log_collection* collection, uint8_t** byte_array, size_t* byte_size) {
    pthread_mutex_lock(&collection->lock);

    *byte_size = 0;
    for (size_t i = 0; i < collection->entry_count; ++i) {
        *byte_size += sizeof(size_t); // message length
        *byte_size += strlen(collection->entries[i].message) + 1; 
        *byte_size += sizeof(time_t);
        *byte_size += sizeof(size_t);
        *byte_size += sizeof(bool);
    }

    *byte_array = malloc(*byte_size);
    if (!*byte_array) {
        pthread_mutex_unlock(&collection->lock);
        exit(EXIT_FAILURE);
    }

    size_t offset = 0;
    for (size_t i = 0; i < collection->entry_count; ++i) {
        size_t msg_len = strlen(collection->entries[i].message) + 1;
        memcpy(*byte_array + offset, &msg_len, sizeof(size_t));
        offset += sizeof(size_t);
        memcpy(*byte_array + offset, collection->entries[i].message, msg_len);
        offset += msg_len;
        memcpy(*byte_array + offset, &collection->entries[i].timestamp, sizeof(time_t));
        offset += sizeof(time_t);
        memcpy(*byte_array + offset, &collection->entries[i].access_count, sizeof(size_t));
        offset += sizeof(size_t);
        memcpy(*byte_array + offset, &collection->entries[i].archive_flag, sizeof(bool));
        offset += sizeof(bool);
    }

    pthread_mutex_unlock(&collection->lock);
}

void deserialize_log_collection(uint8_t* byte_array, size_t byte_size, log_collection* collection) {
    pthread_mutex_lock(&collection->lock);

    if (byte_size == 0) {
        fprintf(stderr, "No data to deserialize.\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    size_t offset = 0;
    while (offset < byte_size) {
        if (collection->entry_count >= MAX_LOG_ENTRIES) break;

        size_t msg_len;
        memcpy(&msg_len, byte_array + offset, sizeof(size_t));
        offset += sizeof(size_t);

        char* message = malloc(msg_len);
        if (!message) exit(EXIT_FAILURE);

        memcpy(message, byte_array + offset, msg_len);
        offset += msg_len;

        time_t timestamp;
        memcpy(&timestamp, byte_array + offset, sizeof(time_t));
        offset += sizeof(time_t);

        size_t access_count;
        memcpy(&access_count, byte_array + offset, sizeof(size_t));
        offset += sizeof(size_t);

        bool archive_flag;
        memcpy(&archive_flag, byte_array + offset, sizeof(bool));
        offset += sizeof(bool);

        collection->entries[collection->entry_count++] = create_log_entry(message, 0, 0);
        free(message);

        collection->entries[collection->entry_count - 1].timestamp = timestamp;
        collection->entries[collection->entry_count - 1].access_count = access_count;
        collection->entries[collection->entry_count - 1].archive_flag = archive_flag;
    }

    pthread_mutex_unlock(&collection->lock);
}

void free_log_collection(log_collection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->entry_count; ++i) {
        free(collection->entries[i].message);
    }

    free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void log_event(const char* event) {
    printf("LOG: %s\n", event);
}

// Example usage
int main() {
    seed_random_time();

    log_collection* collection = initialize_log_collection(MAX_LOG_ENTRIES, 256);
    log_event("Log collection initialized.");

    add_log_entry(collection, "This is a test log message.");
    log_event("Added a new log entry.");

    uint8_t* byte_array;
    size_t byte_size;

    serialize_log_collection(collection, &byte_array, &byte_size);
    log_event("Serialized log entries.");

    free_log_collection(collection);

    // Cleanup
    if (byte_array) {
        free(byte_array);
    }

    return 0;
}
