#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    int field;
} RecordStruct;

typedef struct {
    int key;
    size_t offset;
    RecordStruct record;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    size_t memory_budget;
} RecordList;

// Function prototypes
RecordList* init_record_list(size_t memory_budget);
int add_record(RecordList *list, int key, const RecordStruct *record_struct);
int serialize_record(const Record *record, uint8_t **buffer, size_t *size);
int deserialize_record(const uint8_t *buffer, size_t size, Record *record);
void free_record_list(RecordList *list);

// Initialize the record list with a given memory budget
RecordList* init_record_list(size_t memory_budget) {
    RecordList *list = (RecordList *)malloc(sizeof(RecordList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
    list->memory_budget = memory_budget;

    return list;
}

// Add a record to the list
int add_record(RecordList *list, int key, const RecordStruct *record_struct) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 4 : list->capacity * 2;
        size_t estimated_size = sizeof(Record *) * new_capacity;

        if (estimated_size > list->memory_budget) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory budget exceeded
        }

        Record **new_records = realloc(list->records, estimated_size);
        if (!new_records) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Allocation failed
        }

        list->records = new_records;
        memset(list->records + list->capacity, 0, sizeof(Record *) * (new_capacity - list->capacity));
        list->capacity = new_capacity;
    }

    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Allocation failed
    }

    record->key = key;
    record->record.field = record_struct->field;

    list->records[list->count++] = record;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Serialize a record to a compact binary format
int serialize_record(const Record *record, uint8_t **buffer, size_t *size) {
    // Define versioning byte
    static const uint8_t version = 1;

    *size = sizeof(version) + sizeof(record->key) + sizeof(record->offset) + sizeof(record->record.field);

    *buffer = (uint8_t *)malloc(*size);
    if (!*buffer) return -1; // Allocation failed

    uint8_t *ptr = *buffer;

    *(ptr++) = version;

    memcpy(ptr, &record->key, sizeof(record->key));
    ptr += sizeof(record->key);

    memcpy(ptr, &record->offset, sizeof(record->offset));
    ptr += sizeof(record->offset);

    memcpy(ptr, &record->record.field, sizeof(record->record.field));

    return 0;
}

// Deserialize a record from a compact binary format
int deserialize_record(const uint8_t *buffer, size_t size, Record *record) {
    if (size < sizeof(uint8_t)) return -1; // Invalid buffer size

    const uint8_t version = *(const uint8_t *)buffer;

    if (version != 1) return -2; // Unsupported version

    size -= sizeof(version);
    buffer += sizeof(version);

    if (size < sizeof(record->key) + sizeof(record->offset) + sizeof(record->record.field)) {
        return -3; // Invalid buffer size
    }

    memcpy(&record->key, buffer, sizeof(record->key));
    buffer += sizeof(record->key);

    memcpy(&record->offset, buffer, sizeof(record->offset));
    buffer += sizeof(record->offset);

    memcpy(&record->record.field, buffer, sizeof(record->record.field));

    return 0;
}

// Free all resources associated with the record list
void free_record_list(RecordList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i]);
    }

    free(list->records);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    // Example usage
    RecordList *record_list = init_record_list(1024);
    if (!record_list) return 1;

    RecordStruct record_struct = {42};
    add_record(record_list, 1, &record_struct);

    uint8_t *buffer;
    size_t buffer_size;
    serialize_record(record_list->records[0], &buffer, &buffer_size);

    Record deserialized_record;
    deserialize_record(buffer, buffer_size, &deserialized_record);

    printf("Deserialized record field: %d\n", deserialized_record.record.field);

    free(buffer);
    free_record_list(record_list);

    return 0;
}
