#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MEMORY_LIMIT 1024 * 1024 // Example memory limit (1MB)
#define VERSION 1

typedef struct Record {
    int key;
    long offset;
    struct {
        int field;
    } data;
    void* metadata; // Placeholder for additional pointers
} Record;

typedef struct ListNode {
    Record record;
    struct ListNode *next;
} ListNode;

typedef struct {
    ListNode *head;
    size_t current_memory_usage;
    pthread_mutex_t lock;
    uint32_t version;
} RecordList;

void seed_random() {
    srand(time(NULL));
}

int generate_random_int(int min, int max) {
    return min + rand() % ((max - min) + 1);
}

size_t calculate_record_size(size_t metadata_size) {
    return sizeof(Record) + metadata_size;
}

int add_record(RecordList *list, Record record, size_t metadata_size) {
    pthread_mutex_lock(&list->lock);

    if (list->current_memory_usage + calculate_record_size(metadata_size) > MEMORY_LIMIT) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory limit exceeded
    }

    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Allocation failed
    }

    new_node->record = record;
    list->current_memory_usage += calculate_record_size(metadata_size);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_record(Record *record, uint8_t **buffer) {
    size_t buffer_size = sizeof(int) + sizeof(long) + sizeof(record->data.field);
    *buffer = (uint8_t *)malloc(buffer_size);

    if (!*buffer) {
        return -1; // Allocation failed
    }

    int key = htonl(record->key); 
    long offset = htobe64(record->offset);

    memcpy(*buffer, &key, sizeof(int));
    memcpy(*buffer + sizeof(int), &offset, sizeof(long));
    memcpy(*buffer + sizeof(int) + sizeof(long), &(record->data.field), sizeof(int));

    return 0;
}

int deserialize_record(const uint8_t *buffer, Record *record) {
    if (!buffer || !record) {
        return -1; // Invalid argument
    }

    int key = ntohl(*((int *)buffer));
    long offset = be64toh(*((long *)(buffer + sizeof(int))));

    record->key = key;
    record->offset = offset;
    record->data.field = *((int *)(buffer + sizeof(int) + sizeof(long)));

    return 0;
}

void release_resources(RecordList *list) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current) {
        ListNode *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

void initialize_record_list(RecordList *list, size_t metadata_size) {
    list->head = NULL;
    list->current_memory_usage = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->version = VERSION;

    seed_random();
}

// Example test function
int main() {
    RecordList record_list;
    initialize_record_list(&record_list, sizeof(void *));

    Record record;
    record.key = generate_random_int(1, 1000);
    record.offset = (long)generate_random_int(1, 1000);
    record.data.field = generate_random_int(1, 1000);

    if (add_record(&record_list, record, sizeof(void *)) == 0) {
        printf("Record added successfully.\n");
    } else {
        printf("Failed to add record.\n");
    }

    release_resources(&record_list);
    pthread_mutex_destroy(&record_list.lock);

    return 0;
}
