#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_FD 10000
#define MAX_RECORDS 1000000

typedef struct {
    int value;
    long offset;
    char random_string[64];
} Record;

typedef struct {
    int fd[MAX_FD];
    pthread_mutex_t mutex;
    size_t count;
} FileDescriptorPool;

FileDescriptorPool fd_pool = {.count = 0};
Record *records = NULL;
pthread_rwlock_t record_rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Logging function
void log_event(const char *message) {
    printf("%s\n", message);
}

// Initialize file descriptor pool
int init_fd_pool() {
    pthread_mutex_init(&fd_pool.mutex, NULL);
    memset(fd_pool.fd, -1, sizeof(fd_pool.fd));
    log_event("File Descriptor Pool Initialized");
    return 0;
}

// Add a file descriptor to the pool
int add_fd(int fd) {
    pthread_mutex_lock(&fd_pool.mutex);
    if (fd_pool.count < MAX_FD) {
        for (size_t i = 0; i < MAX_FD; ++i) {
            if (fd_pool.fd[i] == -1) {
                fd_pool.fd[i] = fd;
                fd_pool.count++;
                log_event("File Descriptor Added");
                pthread_mutex_unlock(&fd_pool.mutex);
                return 0;
            }
        }
    }
    pthread_mutex_unlock(&fd_pool.mutex);
    log_event("Failed to Add File Descriptor: Pool Full or Invalid FD");
    return -1;
}

// Initialize records array
int init_records() {
    records = malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        log_event("Memory Allocation Failed for Records");
        return -1;
    }
    pthread_rwlock_init(&record_rwlock, NULL);
    log_event("Records Array Initialized");
    return 0;
}

// Add a record
int add_record(int value, long offset, const char *random_string) {
    pthread_rwlock_wrlock(&record_rwlock);
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (records[i].value == 0) { // Assuming zero as uninitialized state
            records[i].value = value;
            records[i].offset = offset;
            strncpy(records[i].random_string, random_string, sizeof(records[i].random_string) - 1);
            pthread_rwlock_unlock(&record_rwlock);
            log_event("Record Added");
            return 0;
        }
    }
    pthread_rwlock_unlock(&record_rwlock);
    log_event("Failed to Add Record: Array Full");
    return -1;
}

// Helper function to process a list of integers from standard input
int find_largest_int() {
    int max = INT_MIN, num;
    while (scanf("%d", &num) == 1) {
        if (num > max) {
            max = num;
        }
    }
    return max;
}

// Thread function to manage file descriptors and records
void *thread_func(void *arg) {
    int fd = *(int *)arg;
    char random_string[64];
    snprintf(random_string, sizeof(random_string), "RandomString-%d", rand());

    if (add_fd(fd) == 0 && add_record(rand(), rand(), random_string) == 0) {
        log_event("Thread Function Executed Successfully");
    } else {
        log_event("Thread Function Execution Failed");
    }
    return NULL;
}

int main() {
    if (init_fd_pool() != 0 || init_records() != 0) {
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_FD];
    int fds[MAX_FD];

    // Simulate adding file descriptors
    for (size_t i = 0; i < MAX_FD; ++i) {
        fds[i] = open("/dev/null", O_RDWR);
        if (fds[i] == -1) break;
        pthread_create(&threads[i], NULL, thread_func, &fds[i]);
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < MAX_FD && fds[i] != -1; ++i) {
        pthread_join(threads[i], NULL);
        close(fds[i]);
    }

    printf("Largest Integer: %d\n", find_largest_int());

    // Cleanup
    free(records);
    return EXIT_SUCCESS;
}
