#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <limits.h>
#include <stdbool.h>

// Structure definition
typedef struct {
    float value;
    time_t timestamp;
    char *sensor_id;
} metrics;

// Function prototypes
metrics* allocate_metrics(size_t max_size, size_t num_metrics, const char **id_list);
void free_metrics(metrics *metrics_arr, size_t count);
void serialize_metrics(const metrics *metrics_arr, size_t count, unsigned char **buffer, size_t *size);
void deserialize_metrics(unsigned char *buffer, size_t buffer_size, metrics **metrics_arr, size_t *count);
float random_float(float min, float max);
void handle_partial_data(metrics *metric, const char *data);
void log_discrepancy(const char *message);

// Helper functions
double calculate_median(double arr[], size_t n);
char* generate_random_string(size_t length, const char *charset);

// Main function to allocate and initialize metrics array
metrics* allocate_metrics(size_t max_size, size_t num_metrics, const char **id_list) {
    if (max_size == 0 || num_metrics == 0 || id_list == NULL) return NULL;

    // Seed random number generator with current time
    srand((unsigned int)time(NULL));

    metrics *metrics_arr = malloc(num_metrics * sizeof(metrics));
    if (!metrics_arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < num_metrics && i < max_size; ++i) {
        float random_value = random_float(0.0f, 100.0f);
        metrics_arr[i].value = random_value;

        // Simulate timestamp and sensor ID assignment
        metrics_arr[i].timestamp = time(NULL);

        if (id_list[i]) {
            metrics_arr[i].sensor_id = strdup(id_list[i]);
            if (!metrics_arr[i].sensor_id) {
                fprintf(stderr, "Memory allocation for sensor ID failed\n");
                free_metrics(metrics_arr, i);
                return NULL;
            }
        } else {
            char *default_id = generate_random_string(8, "ABCDEFGHIJKLMNOPQRSTUVWXYZ");
            metrics_arr[i].sensor_id = default_id;
        }

        // Simulate partial data handling
        const char *partial_data = "valid_data";  // Example of external data; handle appropriately
        handle_partial_data(&metrics_arr[i], partial_data);
    }

    return metrics_arr;
}

// Function to free allocated memory for the metrics array
void free_metrics(metrics *metrics_arr, size_t count) {
    if (!metrics_arr) return;

    for (size_t i = 0; i < count; ++i) {
        free(metrics_arr[i].sensor_id);
    }
    free(metrics_arr);
}

// Function to serialize metrics data into a byte array
void serialize_metrics(const metrics *metrics_arr, size_t count, unsigned char **buffer, size_t *size) {
    if (!metrics_arr || !buffer || !size) return;

    // Calculate required buffer size
    *size = 0;
    for (size_t i = 0; i < count; ++i) {
        *size += sizeof(float);     // value
        *size += sizeof(time_t);    // timestamp
        *size += strlen(metrics_arr[i].sensor_id) + 1; // sensor_id length + null terminator
    }

    *buffer = malloc(*size);
    if (!*buffer) {
        fprintf(stderr, "Memory allocation for serialization buffer failed\n");
        return;
    }

    unsigned char *ptr = *buffer;
    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &metrics_arr[i].value, sizeof(float));
        ptr += sizeof(float);

        memcpy(ptr, &metrics_arr[i].timestamp, sizeof(time_t));
        ptr += sizeof(time_t);

        size_t str_len = strlen(metrics_arr[i].sensor_id);
        memcpy(ptr, metrics_arr[i].sensor_id, str_len + 1);
        ptr += (str_len + 1);
    }
}

// Function to deserialize byte array back into metrics structures
void deserialize_metrics(unsigned char *buffer, size_t buffer_size, metrics **metrics_arr, size_t *count) {
    if (!buffer || !metrics_arr || !count) return;

    *count = 0;
    unsigned char *ptr = buffer;
    while (ptr < buffer + buffer_size) {
        float value;
        time_t timestamp;
        size_t str_len = 0;

        memcpy(&value, ptr, sizeof(float));
        ptr += sizeof(float);

        memcpy(&timestamp, ptr, sizeof(time_t));
        ptr += sizeof(time_t);

        while (ptr < buffer + buffer_size && *ptr != '\0') {
            ++str_len;
            ++ptr;
        }
        char id_str[str_len + 1];
        memcpy(id_str, ptr, str_len + 1);

        // Allocate and initialize a new metrics structure
        *metrics_arr = realloc(*metrics_arr, (*count + 1) * sizeof(metrics));
        if (!*metrics_arr) {
            fprintf(stderr, "Memory allocation for deserialization failed\n");
            return;
        }

        (*metrics_arr)[*count].value = value;
        (*metrics_arr)[*count].timestamp = timestamp;
        char *id_copy = strdup(id_str);
        if (id_copy) {
            (*metrics_arr)[*count].sensor_id = id_copy;
        } else {
            fprintf(stderr, "Memory allocation for sensor ID failed during deserialization\n");
            break;
        }

        ptr += str_len + 1;
        ++(*count);
    }
}

// Function to generate a random float value within the specified range
float random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Simulated function to handle partial data and log discrepancies
void handle_partial_data(metrics *metric, const char *data) {
    // Example: If data is corrupted or invalid, set default value and log discrepancy
    if (strcmp(data, "valid_data") != 0) { 
        metric->value = -1.0f; // Default corrupted value indicator
        log_discrepancy("Partial or corrupted data received");
    }
}

// Log discrepancies for analysis
void log_discrepancy(const char *message) {
    fprintf(stderr, "Discrepancy: %s\n", message);
}

// Helper function to calculate the median of a float array
double calculate_median(double arr[], size_t n) {
    if (n == 0) return NAN;

    // Sort the array
    for (size_t i = 0; i < n - 1; ++i) {
        for (size_t j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                double temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }

    // Find median
    if (n % 2 == 0) {
        return (arr[n / 2 - 1] + arr[n / 2]) / 2.0;
    } else {
        return arr[n / 2];
    }
}

// Helper function to generate a random string of specified length from given charset
char* generate_random_string(size_t length, const char *charset) {
    if (length == 0 || charset == NULL) return NULL;

    size_t charset_size = strlen(charset);
    char *random_str = malloc(length + 1);
    if (!random_str) return NULL;

    for (size_t i = 0; i < length; ++i) {
        random_str[i] = charset[rand() % charset_size];
    }
    random_str[length] = '\0';

    return random_str;
}

// Example usage of helper functions
int main() {
    const char *sensor_ids[] = {"Sensor1", "Sensor2", NULL, "Sensor4"};
    size_t max_metrics = 10;

    // Allocate metrics array
    metrics *metrics_array = allocate_metrics(max_metrics, 4, sensor_ids);

    if (metrics_array) {
        unsigned char *buffer;
        size_t buffer_size;

        // Serialize metrics data
        serialize_metrics(metrics_array, 4, &buffer, &buffer_size);

        if (buffer) {
            // Deserialize the serialized data back into a metrics array
            metrics *deserialized_metrics = NULL;
            size_t deserialized_count = 0;

            deserialize_metrics(buffer, buffer_size, &deserialized_metrics, &deserialized_count);

            // Clean up
            free(buffer);
        }

        // Free allocated resources
        free_metrics(metrics_array, 4);

        if (deserialized_metrics) {
            free_metrics(deserialized_metrics, deserialized_count);
        }
    }

    return 0;
}
