    if (arg1 > arg2) return 1;
    return 0;
}

unsigned char* initialize_data(int max_records, size_t *size) {
    if (max_records <= 0) return NULL;

    srand((unsigned int)time(NULL));

    long *offsets = safe_malloc(max_records * sizeof(long));
    int *keys = safe_malloc(max_records * sizeof(int));
    record_t *records = safe_malloc(max_records * sizeof(record_t));

    for (int i = 0; i < max_records; ++i) {
        keys[i] = rand() % 10000; // Adjust range as needed
        offsets[i] = rand() % 1000000L;
        records[i].value = keys[i];
        records[i].offset = offsets[i];
        records[i].probability = (double)rand() / RAND_MAX;
    }

    qsort(keys, max_records, sizeof(int), compare_ints);

    // Remove duplicates
    int unique_count = 1;
    for (int i = 1; i < max_records; ++i) {
        if (keys[i] != keys[unique_count - 1]) {
            keys[unique_count] = keys[i];
            offsets[unique_count] = offsets[i];
            records[unique_count].value = keys[i];
            records[unique_count].offset = offsets[i];
            records[unique_count].probability = ((double)rand() / RAND_MAX);
            ++unique_count;
        }
    }

    // Adjust the arrays to only hold unique elements
    max_records = unique_count;

    size_t total_size = sizeof(unsigned char *) * 3 + 
                        (max_records * sizeof(long)) + 
                        (max_records * sizeof(int)) + 
                        (max_records * sizeof(record_t));

    unsigned char *data_buffer = safe_malloc(total_size);

    if (!data_buffer) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Serialize data
    size_t offset = 0;
    memcpy(data_buffer + offset, offsets, max_records * sizeof(long));
    offset += max_records * sizeof(long);

    memcpy(data_buffer + offset, keys, max_records * sizeof(int));
    offset += max_records * sizeof(int);

    memcpy(data_buffer + offset, records, max_records * sizeof(record_t));

    free(offsets);
    free(keys);
    free(records);

    *size = total_size;
    return data_buffer;
}

void free_data(unsigned char* data) {
    if (data) {
        free(data);
    }
}

int main() {
    size_t size;
    unsigned char* data = initialize_data(1000, &size);
    if (data) {
        // Use the serialized data
        free_data(data);
    }

    return 0;
}
