#include <boost/asio.hpp>
#include <boost/filesystem.hpp>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <iostream>
#include <memory>
#include <string>
#include <fstream>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

class Configuration {
public:
    struct Profile {
        std::unordered_map<std::string, std::string> settings;
    };

private:
    std::unordered_map<std::string, Profile> profiles;
    std::string activeProfileName;

    void logError(const std::string& message, const std::string& severity) {
        std::cerr << "[" << severity << "] " << message << std::endl;
        std::ofstream logFile("error.log", std::ios_base::app);
        if (logFile.is_open()) {
            logFile << "[" << severity << "] " << message << std::endl;
            logFile.close();
        }
    }

public:
    explicit Configuration(const std::string& configFilePath) {
        loadConfiguration(configFilePath);
    }

    void loadConfiguration(const std::string& configFilePath) {
        try {
            boost::property_tree::ptree pt;
            boost::property_tree::read_json(configFilePath, pt);

            for (const auto& profile : pt.get_child("profiles")) {
                Profile newProfile;
                for (const auto& setting : profile.second) {
                    if (!setting.first.empty() && !setting.second.data().empty()) {
                        newProfile.settings[setting.first] = setting.second.data();
                    }
                }
                profiles[profile.first.get_value<std::string>()] = std::move(newProfile);
            }

            if (pt.count("active_profile")) {
                activeProfileName = pt.get<std::string>("active_profile");
            } else {
                logError("Active profile not specified, using default.", "WARNING");
                activeProfileName = profiles.begin()->first;
            }
        } catch (const std::exception& ex) {
            logError(ex.what(), "ERROR");
            throw;
        }
    }

    const Profile* getActiveProfile() const {
        auto it = profiles.find(activeProfileName);
        if (it != profiles.end()) {
            return &it->second;
        }
        logError("Active profile not found.", "FATAL");
        return nullptr;
    }

    void setActiveProfile(const std::string& profileName) {
        auto it = profiles.find(profileName);
        if (it != profiles.end()) {
            activeProfileName = profileName;
        } else {
            logError("Profile not found: " + profileName, "ERROR");
        }
    }

    static Configuration* loadConfig(const std::string& path) {
        try {
            return new Configuration(path);
        } catch (const std::exception&) {
            logError("Failed to load configuration.", "FATAL");
            return nullptr;
        }
    }
};

class Cache {
public:
    using Value = std::shared_ptr<void>;

private:
    struct Entry {
        Value value;
        std::chrono::steady_clock::time_point lastAccessed;

        Entry(Value val) : value(val), lastAccessed(std::chrono::steady_clock::now()) {}
    };

    std::unordered_map<std::string, Entry> cacheMap;
    size_t maxSize;
    mutable std::mutex mtx;

    void evictIfNeeded() {
        if (cacheMap.size() > maxSize) {
            auto it = std::min_element(
                cacheMap.begin(), cacheMap.end(),
                [](const auto& a, const auto& b) { return a.second.lastAccessed < b.second.lastAccessed; }
            );

            if (it != cacheMap.end()) {
                cacheMap.erase(it);
            }
        }
    }

public:
    explicit Cache(size_t size) : maxSize(size) {}

    bool get(const std::string& key, Value& valueOut) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = cacheMap.find(key);
        if (it != cacheMap.end()) {
            it->second.lastAccessed = std::chrono::steady_clock::now();
            valueOut = it->second.value;
            return true;
        }
        return false;
    }

    void set(const std::string& key, const Value& value) {
        std::lock_guard<std::mutex> lock(mtx);
        cacheMap[key] = Entry(value);
        evictIfNeeded();
    }
};

class InterfaceTableTestDouble {
public:
    struct Response {
        std::string uuid;
        bool success;
    };

private:
    std::mutex mtx;
    std::condition_variable cv;
    bool isBusy = false;
    int activeRequests = 0;

    Response simulateFindVmUuidFromMetadataIp(const std::string& metadataIp) {
        std::this_thread::sleep_for(std::chrono::milliseconds(30)); // Simulating variable response time
        return { "uuid-1234", true };
    }

public:
    Response findVmUuidFromMetadataIp(const std::string& metadataIp, int timeoutMs = 50) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return activeRequests < 10; });
        isBusy = true;
        activeRequests++;

        auto startTime = std::chrono::steady_clock::now();
        Response response;

        std::thread worker([this, &response, metadataIp]() mutable {
            try {
                response = simulateFindVmUuidFromMetadataIp(metadataIp);
            } catch (...) {
                logError("Internal error during FindVmUuidFromMetadataIp", "FATAL");
            }
            lock.lock();
            isBusy = false;
            activeRequests--;
            cv.notify_one();
            lock.unlock();
        });

        if (worker.joinable()) {
            worker.detach();
        }

        lock.lock();
        bool timeoutOccurred = std::chrono::steady_clock::now() - startTime > std::chrono::milliseconds(timeoutMs);
        while (isBusy && !timeoutOccurred) {
            cv.wait_for(lock, std::chrono::milliseconds(10), [this] { return !isBusy; });
            timeoutOccurred = std::chrono::steady_clock::now() - startTime > std::chrono::milliseconds(timeoutMs);
        }

        if (timeoutOccurred) {
            logError("Request timed out: " + metadataIp, "WARNING");
        }

        lock.unlock();
        return response;
    }
};

int main() {
    const auto config = Configuration::loadConfig("config.json");

    if (!config) {
        std::cerr << "Failed to load configuration. Exiting." << std::endl;
        return EXIT_FAILURE;
    }

    Cache cache(100);
    InterfaceTableTestDouble interface;

    // Example usage
    const Configuration::Profile* profile = config->getActiveProfile();
    if (profile) {
        for (const auto& setting : profile->settings) {
            std::cout << setting.first << ": " << setting.second << std::endl;
        }
    }

    auto response = interface.findVmUuidFromMetadataIp("192.168.0.1");

    if (response.success) {
        std::cout << "Found VM UUID: " << response.uuid << std::endl;
    } else {
        logError("Failed to find VM UUID for metadata IP 192.168.0.1", "ERROR");
    }

    return EXIT_SUCCESS;
}
