['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_METADATA_LENGTH 256

typedef struct {
    int value;
    long offset;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    char **metadata;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} DataStructures;

void log_memory_operation(const char *operation, void *address) {
    time_t now = time(NULL);
    printf("[%ld] %s memory at address: %p\n", now, operation, address);
}

int validate_record(record r, long max_offset, int valid_key_range[2]) {
    return (r.offset <= max_offset) && 
           (valid_key_range[0] <= r.value && r.value <= valid_key_range[1]);
}

void *serialize_data(DataStructures *ds, unsigned char **buffer, size_t *size, int little_endian) {
    size_t total_size = ds->count * (sizeof(long) + sizeof(int) + MAX_METADATA_LENGTH);
    *buffer = malloc(total_size);
    if (*buffer == NULL) return NULL;

    unsigned char *ptr = *buffer;
    for (size_t i = 0; i < ds->count; ++i) {
        long offset = ds->offsets[i];
        int key = ds->keys[i];
        record rec = ds->records[i];

        if (little_endian) {
            ptr += encode_le(ptr, &offset, sizeof(long));
            ptr += encode_le(ptr, &key, sizeof(int));
            ptr += encode_le(ptr, &rec.value, sizeof(int));
            ptr += encode_le(ptr, &rec.offset, sizeof(long));
        } else {
            ptr += encode_be(ptr, &offset, sizeof(long));
            ptr += encode_be(ptr, &key, sizeof(int));
            ptr += encode_be(ptr, &rec.value, sizeof(int));
            ptr += encode_be(ptr, &rec.offset, sizeof(long));
        }

        memcpy(ptr, ds->metadata[i], MAX_METADATA_LENGTH);
        ptr += MAX_METADATA_LENGTH;
    }

    *size = total_size - (ptr - *buffer);
    return *buffer;
}

unsigned char *encode_le(unsigned char *ptr, const void *value, size_t size) {
    for (size_t i = 0; i < size; ++i)
        ptr[i] = ((const unsigned char *)value)[size - 1 - i];
    return ptr + size;
}

unsigned char *encode_be(unsigned char *ptr, const void *value, size_t size) {
    memcpy(ptr, value, size);
    return ptr + size;
}

void free_memory(DataStructures *ds) {
    pthread_mutex_lock(&ds->lock);

    log_memory_operation("Freeing", ds->offsets);
    free(ds->offsets);
    log_memory_operation("Freeing", ds->keys);
    free(ds->keys);
    log_memory_operation("Freeing", ds->records);
    free(ds->records);
    for (size_t i = 0; i < ds->count; ++i) {
        log_memory_operation("Freeing metadata", ds->metadata[i]);
        free(ds->metadata[i]);
    }
    log_memory_operation("Freeing", ds->metadata);
    free(ds->metadata);

    pthread_mutex_unlock(&ds->lock);
}

DataStructures *init_data_structures(size_t count, size_t max_size, long max_offset, int valid_key_range[2]) {
    DataStructures *ds = malloc(sizeof(DataStructures));
    if (!ds) return NULL;

    ds->count = count;
    ds->max_size = max_size;
    pthread_mutex_init(&ds->lock, NULL);

    size_t offset_size = count * sizeof(long);
    size_t key_size = count * sizeof(int);
    size_t record_size = count * sizeof(record);
    size_t metadata_size = count * sizeof(char *);

    if (offset_size + key_size + record_size + metadata_size > max_size)
        return NULL;

    ds->offsets = malloc(offset_size);
    ds->keys = malloc(key_size);
    ds->records = malloc(record_size);
    ds->metadata = malloc(metadata_size);

    if (!ds->offsets || !ds->keys || !ds->records || !ds->metadata) {
        free_memory(ds);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        ds->offsets[i] = rand() % max_offset;
        ds->keys[i] = valid_key_range[0] + rand() % (valid_key_range[1] - valid_key_range[0] + 1);

        record rec = { .value = valid_key_range[0] + rand() % (valid_key_range[1] - valid_key_range[0] + 1), 
                       .offset = ds->offsets[i] };

        if (!validate_record(rec, max_offset, valid_key_range)) {
            free_memory(ds);
            return NULL;
        }

        ds->records[i] = rec;

        ds->metadata[i] = malloc(MAX_METADATA_LENGTH + 1);
        snprintf(ds->metadata[i], MAX_METADATA_LENGTH + 1, "Record %zu", i);

        log_memory_operation("Allocating metadata", ds->metadata[i]);
    }

    return ds;
}

int main() {
    size_t count = 10;
    size_t max_size = 1024 * 1024; // Example maximum size
    long max_offset = 1000;
    int valid_key_range[2] = {0, 100};

    DataStructures *ds = init_data_structures(count, max_size, max_offset, valid_key_range);
    if (!ds) {
        fprintf(stderr, "Failed to initialize data structures\n");
        return EXIT_FAILURE;
    }

    unsigned char *serialized_data;
    size_t serialized_size;

    serialize_data(ds, &serialized_data, &serialized_size, 1); // Little-endian example
    if (serialized_data) {
        printf("Serialization successful. Size: %zu bytes\n", serialized_size);
        free(serialized_data);
    }

    free_memory(ds);

    return EXIT_SUCCESS;
}
