#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/sysinfo.h>

#define MAX_METADATA_LENGTH 256
#define VALUE_RANGE_LOW 0
#define VALUE_RANGE_HIGH 100
#define ENDIANNESS_LITTLE_ENDIAN 0
#define ENDIANNESS_BIG_ENDIAN 1

typedef struct {
    int value;
    long offset;
    time_t timestamp;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_memory_operation(const char* operation, const void* address) {
    pthread_mutex_lock(&mutex);
    printf("[%ld] %s at %p\n", (long)time(NULL), operation, address);
    pthread_mutex_unlock(&mutex);
}

size_t get_available_memory() {
    struct sysinfo info;
    if (sysinfo(&info) == 0) {
        return info.freeram / 2; // Use half of the free RAM
    }
    return 1024 * 1024 * 512; // Fallback to 512MB
}

int check_unique_identifier(const int* ids, size_t count, int id_to_check) {
    for (size_t i = 0; i < count; ++i) {
        if (ids[i] == id_to_check) {
            return 0;
        }
    }
    return 1;
}

void serialize_data(const record* records, const char** metadata, const int* ids, size_t count,
                    uint8_t* buffer, size_t buffer_size, int endianness) {
    size_t offset = 0;
    for (size_t i = 0; i < count; ++i) {
        if (offset + sizeof(int) + sizeof(long) + sizeof(time_t) + strlen(metadata[i]) + 1 > buffer_size) break;

        memcpy(buffer + offset, &records[i].value, sizeof(int));
        offset += sizeof(int);
        if (endianness == ENDIANNESS_BIG_ENDIAN) {
            for (int j = 0; j < sizeof(int); ++j) {
                buffer[offset - sizeof(int) + j] ^= buffer[offset - sizeof(int) + sizeof(int) - 1 - j];
                buffer[offset - sizeof(int) + sizeof(int) - 1 - j] ^= buffer[offset - sizeof(int) + j];
                buffer[offset - sizeof(int) + j] ^= buffer[offset - sizeof(int) + sizeof(int) - 1 - j];
            }
        }

        memcpy(buffer + offset, &records[i].offset, sizeof(long));
        offset += sizeof(long);
        if (endianness == ENDIANNESS_BIG_ENDIAN) {
            for (int j = 0; j < sizeof(long); ++j) {
                buffer[offset - sizeof(long) + j] ^= buffer[offset - sizeof(long) + sizeof(long) - 1 - j];
                buffer[offset - sizeof(long) + sizeof(long) - 1 - j] ^= buffer[offset - sizeof(long) + j];
                buffer[offset - sizeof(long) + j] ^= buffer[offset - sizeof(long) + sizeof(long) - 1 - j];
            }
        }

        memcpy(buffer + offset, &records[i].timestamp, sizeof(time_t));
        offset += sizeof(time_t);
        if (endianness == ENDIANNESS_BIG_ENDIAN) {
            for (int j = 0; j < sizeof(time_t); ++j) {
                buffer[offset - sizeof(time_t) + j] ^= buffer[offset - sizeof(time_t) + sizeof(time_t) - 1 - j];
                buffer[offset - sizeof(time_t) + sizeof(time_t) - 1 - j] ^= buffer[offset - sizeof(time_t) + j];
                buffer[offset - sizeof(time_t) + j] ^= buffer[offset - sizeof(time_t) + sizeof(time_t) - 1 - j];
            }
        }

        memcpy(buffer + offset, metadata[i], strlen(metadata[i]) + 1);
        offset += strlen(metadata[i]) + 1;
    }
}

void deserialize_data(const uint8_t* buffer, size_t buffer_size, record** records_out,
                      const char*** metadata_out, int** ids_out, size_t* count_out) {
    // Implementation of deserialization logic goes here
}

int initialize_and_serialize(int max_records, size_t max_memory_limit, int endianness, uint8_t* serialized_buffer, size_t buffer_size) {
    pthread_mutex_lock(&mutex);

    time_t now = time(NULL);
    srand((unsigned int)now);

    size_t available_memory = get_available_memory();
    size_t memory_to_use = (available_memory < max_memory_limit ? available_memory : max_memory_limit) * 0.8;

    long* offsets = malloc(max_records * sizeof(long));
    int* keys = malloc(max_records * sizeof(int));
    record* records = malloc(max_records * sizeof(record));
    char** metadata = malloc(max_records * sizeof(char*));
    int* ids = malloc(max_records * sizeof(int));

    if (!offsets || !keys || !records || !metadata || !ids) {
        log_memory_operation("Allocation failed", NULL);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    log_memory_operation("Memory allocated", offsets);
    log_memory_operation("Memory allocated", keys);
    log_memory_operation("Memory allocated", records);
    log_memory_operation("Memory allocated", metadata);
    log_memory_operation("Memory allocated", ids);

    size_t total_metadata_size = 0;
    for (size_t i = 0; i < max_records; ++i) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 1000;

        records[i].value = VALUE_RANGE_LOW + rand() % (VALUE_RANGE_HIGH - VALUE_RANGE_LOW + 1);
        records[i].offset = offsets[i];
        records[i].timestamp = now + i;

        metadata[i] = malloc(MAX_METADATA_LENGTH * sizeof(char));
        if (!metadata[i]) {
            log_memory_operation("Allocation failed", NULL);
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        snprintf(metadata[i], MAX_METADATA_LENGTH, "Record %zu data", i);

        total_metadata_size += strlen(metadata[i]) + 1;

        ids[i] = rand() % (max_records * 10); // Random ID
        if (!check_unique_identifier(ids, i, ids[i])) {
            free(metadata[i]);
            log_memory_operation("Duplicate ID found", NULL);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    serialize_data(records, metadata, ids, max_records, serialized_buffer, buffer_size, endianness);

    for (size_t i = 0; i < max_records; ++i) {
        free(metadata[i]);
    }

    free(offsets);
    free(keys);
    free(records);
    free(metadata);
    free(ids);

    log_memory_operation("Memory deallocated", offsets);
    log_memory_operation("Memory deallocated", keys);
    log_memory_operation("Memory deallocated", records);
    log_memory_operation("Memory deallocated", metadata);
    log_memory_operation("Memory deallocated", ids);

    pthread_mutex_unlock(&mutex);
    return 0;
}

void export_serialized_data(const uint8_t* data, size_t size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    fwrite(data, 1, size, file);
    fclose(file);
}

int main() {
    uint8_t serialized_data[1024 * 1024]; // 1MB buffer
    int result = initialize_and_serialize(100, get_available_memory(), ENDIANNESS_LITTLE_ENDIAN, serialized_data, sizeof(serialized_data));
    if (result == 0) {
        export_serialized_data(serialized_data, sizeof(serialized_data), "output.dat");
    }
    return result;
}
