    double timestamp;
} event_t;

typedef struct {
    int user_id;
    char name[NAME_LEN];
    char email[NAME_LEN];
    char **roles;
    size_t roles_count;
    time_t last_login;
    char status[256]; // Additional attribute
} user_profile_t;

int serialize_data(const void *data, size_t data_size, unsigned char **buffer);
void deserialize_data(const unsigned char *buffer, size_t buffer_size, void *data);

// Error checking macro
#define CHECK_PTR(ptr) if (!(ptr)) { fprintf(stderr, "Memory allocation failed\n"); exit(EXIT_FAILURE); }

user_profile_t *initialize_profiles(size_t max_memory_size);
int add_user(user_profile_t **profiles, int user_count, const user_profile_t *new_user);
int update_user(user_profile_t *profiles, int user_id, const user_profile_t *updated_user);
int delete_user(user_profile_t **profiles, int user_index);

double *init_double_array(size_t count);
char **init_char_strings(size_t count);
point_t *init_point_structs(size_t count);
event_t *init_event_structs(size_t count);

user_profile_t *initialize_profiles(size_t max_memory_size) {
    // Calculate total memory required
    size_t double_count = 100;
    size_t char_string_count = 1000;
    size_t point_count = 100;
    size_t event_count = 100;

    size_t required_memory = sizeof(double) * double_count +
                             NAME_LEN * char_string_count +
                             sizeof(point_t) * point_count +
                             (sizeof(event_t) + NAME_LEN) * event_count +
                             sizeof(user_profile_t) * MAX_USERS;

    if (required_memory > max_memory_size) {
        fprintf(stderr, "Exceeding maximum memory size\n");
        return NULL;
    }

    double *doubles = init_double_array(double_count);
    char **strings = init_char_strings(char_string_count);
    point_t *points = init_point_structs(point_count);
    event_t *events = init_event_structs(event_count);

    user_profile_t *profiles = malloc(sizeof(user_profile_t) * MAX_USERS);
    CHECK_PTR(profiles);

    srand(time(NULL));

    for (size_t i = 0; i < point_count; i++) {
        points[i].x = rand() % (2 * MAX_COORDINATE + 1) - MAX_COORDINATE;
        points[i].y = rand() % (2 * MAX_COORDINATE + 1) - MAX_COORDINATE;
    }

    for (size_t i = 0; i < event_count; i++) {
        events[i].location = points[i];
        events[i].timestamp = time(NULL);
    }

    // Initialize user profiles as needed
    return profiles;
}

int add_user(user_profile_t **profiles, int user_count, const user_profile_t *new_user) {
    if (user_count >= MAX_USERS) {
        fprintf(stderr, "User limit reached\n");
        return -1;
    }

    // Copy new user data to the profile list
    memcpy(&(*profiles)[user_count], new_user, sizeof(user_profile_t));
    (*profiles)[user_count].roles = malloc(sizeof(char *) * new_user->roles_count);
    CHECK_PTR((*profiles)[user_count].roles);

    for (size_t i = 0; i < new_user->roles_count; i++) {
        size_t role_len = strlen(new_user->roles[i]) + 1;
        (*profiles)[user_count].roles[i] = malloc(role_len);
        CHECK_PTR((*profiles)[user_count].roles[i]);
        strcpy((*profiles)[user_count].roles[i], new_user->roles[i]);
    }

    return user_count + 1;
}

int update_user(user_profile_t *profiles, int user_id, const user_profile_t *updated_user) {
    for (int i = 0; i < MAX_USERS; i++) {
        if (profiles[i].user_id == user_id) {
            memcpy(&profiles[i], updated_user, sizeof(user_profile_t));
            return 0;
        }
    }
    fprintf(stderr, "User not found\n");
    return -1;
}

int delete_user(user_profile_t **profiles, int user_index) {
    if (user_index < 0 || user_index >= MAX_USERS) {
        fprintf(stderr, "Invalid index\n");
        return -1;
    }

    free((*profiles)[user_index].roles);
    memmove(&(*profiles)[user_index], &(*profiles)[user_index + 1], sizeof(user_profile_t) * (MAX_USERS - user_index - 1));

    return 0;
}

double *init_double_array(size_t count) {
    double *arr = malloc(sizeof(double) * count);
    CHECK_PTR(arr);
    for (size_t i = 0; i < count; i++) arr[i] = 0.0;
    return arr;
}

char **init_char_strings(size_t count) {
    char **arr = malloc(count * sizeof(char *));
    CHECK_PTR(arr);
    for (size_t i = 0; i < count; i++) {
        arr[i] = malloc(NAME_LEN);
        CHECK_PTR(arr[i]);
        memset(arr[i], 0, NAME_LEN);
    }
    return arr;
}

point_t *init_point_structs(size_t count) {
    point_t *arr = malloc(sizeof(point_t) * count);
    CHECK_PTR(arr);
    for (size_t i = 0; i < count; i++) {
        arr[i].x = rand() % (2 * MAX_COORDINATE + 1) - MAX_COORDINATE;
        arr[i].y = rand() % (2 * MAX_COORDINATE + 1) - MAX_COORDINATE;
    }
    return arr;
}

event_t *init_event_structs(size_t count) {
    event_t *arr = malloc(sizeof(event_t) * count);
    CHECK_PTR(arr);
    for (size_t i = 0; i < count; i++) {
        arr[i].location.x = rand() % (2 * MAX_COORDINATE + 1) - MAX_COORDINATE;
        arr[i].location.y = rand() % (2 * MAX_COORDINATE + 1) - MAX_COORDINATE;
        arr[i].timestamp = time(NULL);
    }
    return arr;
}

int serialize_data(const void *data, size_t data_size, unsigned char **buffer) {
    *buffer = malloc(data_size);
    CHECK_PTR(*buffer);
    memcpy(*buffer, data, data_size);
    return 0;
}

void deserialize_data(const unsigned char *buffer, size_t buffer_size, void *data) {
    if (buffer && data && buffer_size > 0) {
        memcpy(data, buffer, buffer_size);
    }
}
```']

