#### `memory_manager.c`
```c
#include <stdio.h>
#include <stdlib.h>
#include "point.h"
#include "event.h"

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Point* create_point(int x, int y) {
    Point *point = (Point*)safe_malloc(sizeof(Point));
    point->x = x;
    point->y = y;
    return point;
}

Event* create_event(int x, int y, time_t timestamp) {
    Event *event = (Event*)safe_malloc(sizeof(Event));
    event->location.x = x;
    event->location.y = y;
    event->timestamp = timestamp;
    return event;
}

void free_point(Point *point) {
    if(point) {
        free(point);
    }
}

void free_event(Event *event) {
    if(event) {
        free(event);
    }
}
```

#### `serialization.c`
```c
#include <stdio.h>
#include "point.h"
#include "event.h"

// Serialize Point to buffer
int serialize_point(Point* point, unsigned char** buffer) {
    size_t size = sizeof(int) * 2;
    *buffer = (unsigned char*)safe_malloc(size);
    if (!(*buffer)) return -1;

    memcpy(*buffer, &(point->x), sizeof(int));
    memcpy(*buffer + sizeof(int), &(point->y), sizeof(int));

    return size;
}

// Deserialize Point from buffer
Point* deserialize_point(unsigned char* buffer) {
    Point *point = (Point*)safe_malloc(sizeof(Point));
    if (!point) return NULL;

    memcpy(&(point->x), buffer, sizeof(int));
    memcpy(&(point->y), buffer + sizeof(int), sizeof(int));

    return point;
}

// Serialize Event to buffer
int serialize_event(Event* event, unsigned char** buffer) {
    size_t size = sizeof(Point) + sizeof(time_t);
    *buffer = (unsigned char*)safe_malloc(size);
    if (!(*buffer)) return -1;

    Point *tmp_point = deserialize_point(*buffer);

    memcpy(tmp_point, &(event->location), sizeof(Point));
    memcpy(*buffer + sizeof(Point), &(event->timestamp), sizeof(time_t));

    free_point(tmp_point);

    return size;
}

// Deserialize Event from buffer
Event* deserialize_event(unsigned char* buffer) {
    Event *event = (Event*)safe_malloc(sizeof(Event));
    if (!event) return NULL;

    Point *tmp_point = deserialize_point(buffer);
    memcpy(&(event->location), tmp_point, sizeof(Point));

    memcpy(&(event->timestamp), buffer + sizeof(Point), sizeof(time_t));

    free_point(tmp_point);

    return event;
}
```

