#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 255

// Structure to hold cache data
typedef struct CacheNode {
    char identifier[20];
    int isValid;
    struct CacheNode* next;
} CacheNode;

CacheNode* cacheHead = NULL;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes for helper functions
int count_digits(const char* str);
int count_non_alnum_before_last_alnum(const char* str);
char* generate_identifier(char lastAlnum, int digitCount, int nonAlnumBeforeLast);

// Simulated asynchronous API call to check identifier uniqueness
void async_api_check(const char* identifier, void (*callback)(const char*, int));

// Callback function for the asynchronous API response
void api_response_handler(const char* identifier, int isValid) {
    pthread_mutex_lock(&cacheMutex);
    CacheNode* current = cacheHead;
    while (current != NULL) {
        if (strcmp(current->identifier, identifier) == 0) {
            current->isValid = isValid;
            break;
        }
        current = current->next;
    }

    // If not found in cache, add to the beginning for faster access
    if (current == NULL && isValid) {
        CacheNode* newNode = (CacheNode*)malloc(sizeof(CacheNode));
        strncpy(newNode->identifier, identifier, sizeof(newNode->identifier) - 1);
        newNode->isValid = isValid;
        newNode->next = cacheHead;
        cacheHead = newNode;

        // Limit cache size
        if (cacheSize >= MAX_CACHE_SIZE) {
            CacheNode* temp = cacheHead;
            cacheHead = cacheHead->next;
            free(temp);
        }
    }
    pthread_mutex_unlock(&cacheMutex);
}

// Function to process the filename
char* process_filename(const char* filename) {
    // 1. Parse and validate the filename to extract relevant information
    const char *lastDot = strrchr(filename, '.');
    size_t nameLength = lastDot ? (size_t)(lastDot - filename) : strlen(filename);
    int digitCount = count_digits(filename);
    int nonAlnumBeforeLast = count_non_alnum_before_last_alnum(filename);

    // 2. Generate the unique identifier based on the specified rules
    char lastAlnum = '\0';
    for (int i = nameLength - 1; i >= 0; --i) {
        if (isalnum((unsigned char)filename[i])) {
            lastAlnum = filename[i];
            break;
        }
    }

    if (!lastAlnum && strlen(filename) > 0) {
        lastAlnum = 'd'; // Default identifier character
    }

    char* identifier = generate_identifier(lastAlnum, digitCount, nonAlnumBeforeLast);

    // 3. Integrate with the external API to check the uniqueness of the identifier asynchronously
    async_api_check(identifier, api_response_handler);

    // 4. Handle concurrency and threading safety (using mutexes for cache)
    pthread_mutex_lock(&cacheMutex);
    CacheNode* current = cacheHead;
    while (current != NULL) {
        if (strcmp(current->identifier, identifier) == 0 && current->isValid) {
            pthread_mutex_unlock(&cacheMutex);
            break; // Identifier is already valid
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cacheMutex);

    // 5. Implement caching for previously validated identifiers
    // This part is handled in the api_response_handler function

    // 6. Ensure the final filename does not exceed 255 characters
    char* newFilename = (char*)malloc(MAX_FILENAME_LENGTH + 1);
    strncpy(newFilename, filename, nameLength);

    size_t extensionStart = lastDot ? (size_t)(lastDot - filename) : strlen(filename);
    snprintf(newFilename + extensionStart, MAX_FILENAME_LENGTH - extensionStart,
             ".%s", identifier);

    // Truncate if necessary
    if (strlen(newFilename) > MAX_FILENAME_LENGTH) {
        newFilename[MAX_FILENAME_LENGTH] = '\0';
    }

    return newFilename;
}

// Helper function implementations
int count_digits(const char* str) {
    int count = 0;
    while (*str) {
        if (isdigit((unsigned char)*str)) {
            ++count;
        }
        ++str;
    }
    return count;
}

int count_non_alnum_before_last_alnum(const char* str) {
    int count = 0;
    int foundAlnum = 0;

    for (const char* p = str; *p != '\0'; ++p) {
        if (isalnum((unsigned char)*p)) {
            if (!foundAlnum) {
                foundAlnum = 1;
            }
        } else if (foundAlnum) {
            ++count;
        }
    }

    return count;
}

char* generate_identifier(char lastAlnum, int digitCount, int nonAlnumBeforeLast) {
    static char identifier[20];
    snprintf(identifier, sizeof(identifier), "%d%c%d", digitCount,
             lastAlnum, nonAlnumBeforeLast);
    return identifier;
}
