['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <zlib.h> // Assume zlib is used for compression

// Define a record structure
typedef struct {
    int value;
} record;

// Define the complex data structure
typedef struct {
    double average;
    char flag;
    unsigned int id;
    void *metadata;
    _Bool isValid;
} ComplexData;

// Function to generate a random number within a specified range
int generate_random_number(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Dynamic memory allocation and initialization function
void manage_dynamic_memory(size_t offset_count, size_t key_count, size_t record_count,
                           size_t max_memory, size_t compression_level,
                           const char *compression_mode, ComplexData *complex_data) {
    // Initialize random number generator
    srand(time(NULL));

    // Memory thresholds (in bytes)
    const size_t MAX_SINGLE_ALLOCATION = 1024 * 1024; // 1 MB for example

    // Check memory limits and allocation sizes
    if (offset_count * sizeof(long) > MAX_SINGLE_ALLOCATION ||
        key_count * sizeof(int) > MAX_SINGLE_ALLOCATION ||
        record_count * sizeof(record) > MAX_SINGLE_ALLOCATION) {
        fprintf(stderr, "Allocation size exceeds the threshold.\n");
        return;
    }

    // Calculate total required memory
    size_t total_memory = offset_count * sizeof(long) +
                          key_count * sizeof(int) +
                          record_count * sizeof(record);

    if (total_memory > max_memory) {
        fprintf(stderr, "Total memory allocation exceeds maximum limit.\n");
        return;
    }

    // Allocate memory for offsets
    long *offsets = malloc(offset_count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        goto cleanup;
    }

    // Allocate memory for keys
    int *keys = malloc(key_count * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        goto cleanup;
    }

    // Allocate memory for records and initialize with random values
    record *records = malloc(record_count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(keys);
        free(offsets);
        goto cleanup;
    }
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = generate_random_number(1, 100); // Example range
    }

    // Initialize complex data structure
    if (complex_data != NULL) {
        complex_data->average = 0.0;
        complex_data->flag = 'A'; // Arbitrary flag value
        complex_data->id = rand(); // Random ID
        complex_data->metadata = NULL; // No metadata initially
        complex_data->isValid = 1; // Assume valid by default
    }

    // Compression setup
    z_stream strm;
    memset(&strm, 0, sizeof(strm));

    if (strcmp(compression_mode, "high") == 0) {
        deflateInit2(&strm, Z_BEST_COMPRESSION, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY);
    } else {
        deflateInit2(&strm, Z_BEST_SPEED, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY);
    }

    // Compress data (example: compressing offsets)
    strm.next_in = (Bytef *)offsets;
    size_t avail_in = offset_count * sizeof(long);
    Bytef outBuffer[1024];
    strm.avail_out = sizeof(outBuffer);

    if (deflate(&strm, Z_FINISH) != Z_STREAM_END) {
        fprintf(stderr, "Compression failed.\n");
        deflateEnd(&strm);
        goto cleanup;
    }

    size_t compressed_size = 1024 - strm.avail_out;

    // Decompression setup
    inflateInit2(&strm, -15);

    // Decompress data (example: decompressing offsets)
    Bytef inBuffer[compressed_size];
    memcpy(inBuffer, outBuffer, compressed_size);
    strm.next_in = inBuffer;
    strm.avail_in = compressed_size;

    strm.next_out = (Bytef *)offsets; // Overwriting original for simplicity
    strm.avail_out = offset_count * sizeof(long);

    if (inflate(&strm, Z_NO_FLUSH) != Z_STREAM_END || strm.avail_out != 0) {
        fprintf(stderr, "Decompression failed.\n");
        inflateEnd(&strm);
        goto cleanup;
    }

    // Cleanup
    deflateEnd(&strm);
    inflateEnd(&strm);

cleanup:
    free(records);
    free(keys);
    free(offsets);
}

int main() {
    ComplexData complex_data;
    manage_dynamic_memory(1000, 500, 300, 1024 * 1024 * 10, Z_DEFAULT_COMPRESSION,
                          "high", &complex_data);
    return 0;
}
```

