RecordCollection* create_record_collection(size_t initial_capacity, double max_memory_usage) {
    if (initial_capacity > MAX_RECORDS || max_memory_usage > MAX_MEMORY_USAGE) {
        log_event("Invalid initial configuration");
        return NULL;
    }

    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        log_event("Memory allocation failed for collection");
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        log_event("Memory allocation failed for records array");
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;

    log_event("Collection initialized successfully");

    return collection;
}

int add_record(RecordCollection *collection, double value, char status) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity || 
        ((collection->records + 1) * sizeof(Record)) > MAX_MEMORY_USAGE) {

        size_t new_capacity = collection->capacity * 2;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            log_event("Memory allocation failed during resize");
            return -1; // Memory error
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = &collection->records[collection->count++];
    record->value = value;
    record->status = status;
    record->timestamp = time(NULL);

    pthread_mutex_unlock(&collection->lock);

    log_event("Record added successfully");

    return 0; // Success
}

void serialize_records(const RecordCollection *collection, unsigned char **byte_array, size_t *size) {
    size_t total_size = collection->count * sizeof(Record);
    *byte_array = malloc(total_size);
    if (!*byte_array) {
        log_event("Memory allocation failed for serialization");
        return;
    }

    memcpy(*byte_array, collection->records, total_size);

    // Endianness handling
    for (size_t i = 0; i < collection->count; ++i) {
        ((double *)(*byte_array))[i] = htod(collection->records[i].value);
    }

    *size = total_size;
    log_event("Records serialized successfully");
}

void deserialize_records(const unsigned char *byte_array, size_t size, RecordCollection *collection) {
    for (size_t i = 0; i < collection->count && i * sizeof(Record) < size; ++i) {
        double value = dtoh(((double *)(byte_array))[i]);
        memcpy(&collection->records[i], &byte_array[i * sizeof(Record)], sizeof(Record));
        collection->records[i].value = value;
    }

    log_event("Records deserialized successfully");
}

