#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_MEMORY_SIZE 1024 * 1024 // Example size limit in bytes
#define NODE_KEY_MAX_LENGTH 10
#define DOUBLE_VALUE_MIN 0.0
#define DOUBLE_VALUE_MAX 100.0
#define SERIALIZE_FORMAT IEEE_754_DOUBLE_PRECISION
#define ENDIANNESS_LITTLE_ENDIAN

typedef struct Node {
    char key[NODE_KEY_MAX_LENGTH];
    double value;
    struct Node* next;
} Node;

typedef enum { IEEE_754_SINGLE_PRECISION, IEEE_754_DOUBLE_PRECISION } SerializeFormat;
typedef enum { LITTLE_ENDIAN, BIG_ENDIAN } Endianness;

// Helper function to check endianness
static int is_little_endian() {
    unsigned int i = 1;
    return *((unsigned char*)&i) == 1;
}

// Function to serialize a node into a byte array
void* serialize_node(Node* node, SerializeFormat format, Endianness endianess) {
    size_t value_size = (format == IEEE_754_DOUBLE_PRECISION) ? sizeof(double) : sizeof(float);
    unsigned char* buffer = malloc(value_size + NODE_KEY_MAX_LENGTH);

    if (!buffer) return NULL;

    memcpy(buffer, node->key, NODE_KEY_MAX_LENGTH);
    double double_value = node->value;

    if (format == IEEE_754_SINGLE_PRECISION && endianess == LITTLE_ENDIAN && !is_little_endian()) {
        float single_value = (float)double_value;
        uint32_t temp = *(uint32_t*)&single_value;
        temp = ((temp & 0x000000FF) << 24) |
               ((temp & 0x0000FF00) << 8) |
               ((temp & 0x00FF0000) >> 8) |
               ((temp & 0xFF000000) >> 24);
        *(uint32_t*)(buffer + NODE_KEY_MAX_LENGTH) = temp;
    } else if (format == IEEE_754_DOUBLE_PRECISION && endianess == LITTLE_ENDIAN && !is_little_endian()) {
        uint64_t temp = *((uint64_t*)&double_value);
        temp = ((temp & 0x00000000000000FFULL) << 56) |
               ((temp & 0x000000000000FF00ULL) << 40) |
               ((temp & 0x0000000000FF0000ULL) << 24) |
               ((temp & 0x00000000FF000000ULL) << 8) |
               ((temp & 0x000000FF00000000ULL) >> 8) |
               ((temp & 0x0000FF0000000000ULL) >> 24) |
               ((temp & 0x00FF000000000000ULL) >> 40) |
               ((temp & 0xFF00000000000000ULL) >> 56);
        *(uint64_t*)(buffer + NODE_KEY_MAX_LENGTH) = temp;
    } else {
        memcpy(buffer + NODE_KEY_MAX_LENGTH, &double_value, value_size);
    }

    return buffer;
}

// Function to deserialize a byte array into a node
Node* deserialize_node(const unsigned char* data, SerializeFormat format, Endianness endianess) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    memcpy(node->key, data, NODE_KEY_MAX_LENGTH);

    size_t value_size = (format == IEEE_754_DOUBLE_PRECISION) ? sizeof(double) : sizeof(float);

    double double_value;
    if (format == IEEE_754_SINGLE_PRECISION && endianess == LITTLE_ENDIAN && !is_little_endian()) {
        uint32_t temp;
        memcpy(&temp, data + NODE_KEY_MAX_LENGTH, sizeof(uint32_t));
        temp = ((temp & 0x000000FF) << 24) |
               ((temp & 0x0000FF00) << 8) |
               ((temp & 0x00FF0000) >> 8) |
               ((temp & 0xFF000000) >> 24);
        *(uint32_t*)&double_value = temp;
    } else if (format == IEEE_754_DOUBLE_PRECISION && endianess == LITTLE_ENDIAN && !is_little_endian()) {
        uint64_t temp;
        memcpy(&temp, data + NODE_KEY_MAX_LENGTH, sizeof(uint64_t));
        temp = ((temp & 0x00000000000000FFULL) << 56) |
               ((temp & 0x000000000000FF00ULL) << 40) |
               ((temp & 0x0000000000FF0000ULL) << 24) |
               ((temp & 0x00000000FF000000ULL) << 8) |
               ((temp & 0x000000FF00000000ULL) >> 8) |
               ((temp & 0x0000FF0000000000ULL) >> 24) |
               ((temp & 0x00FF000000000000ULL) >> 40) |
               ((temp & 0xFF00000000000000ULL) >> 56);
        *(uint64_t*)&double_value = temp;
    } else {
        memcpy(&double_value, data + NODE_KEY_MAX_LENGTH, value_size);
    }

    node->value = double_value;
    node->next = NULL;

    return node;
}

// Function to generate random double values
double get_random_double(double min, double max) {
    double range = (max - min);
    double div = RAND_MAX / range;
    return min + (rand() / div);
}

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Main function to initialize linked list
Node* initialize_linked_list(size_t max_size, size_t num_nodes) {
    pthread_mutex_lock(&mutex);

    Node* head = NULL;
    Node* current = NULL;
    size_t total_memory = 0;
    size_t node_size = sizeof(Node) + NODE_KEY_MAX_LENGTH;

    srand(time(NULL));

    for (size_t i = 0; i < num_nodes && total_memory + node_size <= max_size; ++i) {
        Node* new_node = malloc(node_size);
        if (!new_node) break;

        snprintf(new_node->key, NODE_KEY_MAX_LENGTH, "Key%d", i);

        double value;
        do {
            value = get_random_double(DOUBLE_VALUE_MIN, DOUBLE_VALUE_MAX);
        } while (value < DOUBLE_VALUE_MIN || value > DOUBLE_VALUE_MAX);

        new_node->value = value;
        new_node->next = NULL;

        if (!head) {
            head = new_node;
            current = head;
        } else {
            current->next = new_node;
            current = new_node;
        }

        total_memory += node_size;
    }

    pthread_mutex_unlock(&mutex);

    return head;
}

// Function to free the linked list
void free_linked_list(Node* head) {
    Node* temp;

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
