#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <time.h>

#define MAX_FD 10000
#define MEMORY_LIMIT (1024 * 1024 * 512) // 512 MB
#define AGE_THRESHOLD_SECONDS 3600

typedef enum { FD_OPEN, FD_CLOSED, FD_BUSY, FD_ERROR } FdStatus;

typedef struct {
    int fd;
    FdStatus status;
    time_t last_accessed;
    unsigned long read_ops;
    unsigned long write_ops;
} FileDescriptor;

typedef struct {
    pthread_mutex_t lock;
    FileDescriptor fds[MAX_FD];
    size_t count;
} FdPool;

FdPool* create_fd_pool() {
    FdPool *pool = malloc(sizeof(FdPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->count = 0;

    for (int i = 0; i < MAX_FD; ++i) {
        pool->fds[i].fd = -1;
        pool->fds[i].status = FD_CLOSED;
        pool->fds[i].last_accessed = 0;
        pool->fds[i].read_ops = 0;
        pool->fds[i].write_ops = 0;
    }

    return pool;
}

void free_fd_pool(FdPool *pool) {
    if (!pool) return;
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int get_fd_from_pool(FdPool *pool, int *fd) {
    if (!pool || !fd) return -1;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        FileDescriptor *desc = &pool->fds[i];

        if (desc->status == FD_CLOSED || 
            (time(NULL) - desc->last_accessed > AGE_THRESHOLD_SECONDS)) {

            close(desc->fd);
            desc->fd = -1;
            desc->status = FD_CLOSED;
            continue;
        }

        if (desc->status == FD_OPEN) {
            *fd = desc->fd;
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1;
}

void init_aes_cipher(const char *password, unsigned char **key, unsigned char **iv) {
    const int key_length = 32; // AES-256
    const int iv_length = EVP_MAX_IV_LENGTH;

    *key = malloc(key_length);
    if (!*key) exit(EXIT_FAILURE);

    *iv = malloc(iv_length);
    if (!*iv) { free(*key); exit(EXIT_FAILURE); }

    if (1 != RAND_bytes(*iv, iv_length)) {
        fprintf(stderr, "Failed to generate IV\n");
        exit(EXIT_FAILURE);
    }

    // Derive key using OpenSSL's EVP functions
    EVP_BytesToKey(EVP_sha256(), EVP_des_ede3_cbc(), NULL,
                   (unsigned char*)password, strlen(password), 1,
                   *key, &key_length, iv);

    if (*key == NULL) {
        fprintf(stderr, "Failed to derive key\n");
        free(*iv);
        free(*key);
        exit(EXIT_FAILURE);
    }
}

void cleanup_aes_cipher(unsigned char *key, unsigned char *iv) {
    if (key) free(key);
    if (iv) free(iv);
}

typedef struct {
    long *offsets;
    int *keys;
    size_t count;
} RecordArray;

RecordArray* create_record_array(size_t max_records, int key_range) {
    RecordArray *array = malloc(sizeof(RecordArray));
    if (!array) return NULL;

    array->count = 0;
    array->offsets = malloc(max_records * sizeof(long));
    array->keys = malloc(max_records * sizeof(int));

    if (!array->offsets || !array->keys) {
        free(array->offsets);
        free(array->keys);
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < max_records; ++i) {
        array->keys[i] = rand() % key_range;
        array->offsets[i] = rand();
    }

    array->count = max_records;

    return array;
}

void free_record_array(RecordArray *array) {
    if (!array) return;
    free(array->offsets);
    free(array->keys);
    free(array);
}

int main() {
    // Example usage
    FdPool *fd_pool = create_fd_pool();
    int fd;
    if (get_fd_from_pool(fd_pool, &fd) == 0) {
        printf("Reused FD: %d\n", fd);
    } else {
        printf("Allocating new FD\n");
    }

    unsigned char *key, *iv;
    init_aes_cipher("password123", &key, &iv);

    RecordArray *record_array = create_record_array(1000, 100);
    if (record_array) {
        // Use record array
        free_record_array(record_array);
    }

    cleanup_aes_cipher(key, iv);
    free_fd_pool(fd_pool);

    return 0;
}
```

