        if (!connection_pool.connections[i]) {
            connection_pool.connections[i] = conn;
            connection_pool.current_size++;
            log_event("Connection added.");
            pthread_mutex_unlock(&connection_pool.lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&connection_pool.lock);
    return -1; // Should not reach here
