    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (connection_pool.connections[i] && connection_pool.connections[i]->socket_descriptor == socket_descriptor) {
            free(connection_pool.connections[i]);
            connection_pool.connections[i] = NULL;
            connection_pool.current_size--;
            log_event("Connection removed.");
            pthread_mutex_unlock(&connection_pool.lock);
            return 0;
        }
    }

