    buffer += sizeof(timeout_value);

    // Serialize additional attributes as needed
}

void deserialize_connection(Connection *conn, const uint8_t *buffer) {
    if (!conn || !buffer) return;

    memcpy(&conn->socket_descriptor, buffer, sizeof(conn->socket_descriptor));
    buffer += sizeof(conn->socket_descriptor);

    int state;
    memcpy(&state, buffer, sizeof(state));
    conn->state = ntohl(state);
    buffer += sizeof(state);

    int timeout_value;
    memcpy(&timeout_value, buffer, sizeof(timeout_value));
    conn->timeout_value = ntohl(timeout_value);
    buffer += sizeof(timeout_value);

