        fread(data, 1, record_count * element_size, read_file);
        fclose(read_file);

        int deserialized_count = 0;
        deserialize(data, &records, &deserialized_count);
        free(data);
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

