void log_message(const char* message, const char* severity) {
    pthread_mutex_lock(&lock);
    fprintf(log_file, "[%s] %s: %s\n", severity, time(NULL), message);
    fflush(log_file);
    pthread_mutex_unlock(&lock);
}

// Thread pool management (simplified example)
