    pthread_t threads[max_threads];
    for (int i = 0; i < max_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, NULL) != 0) {
            perror("Failed to create thread");
        }
    }
    for (int i = 0; i < max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* thread_function(void* arg) {
    // Simulate background task
    return NULL;
}

// Helper function to find the maximum integer from input
int read_and_find_max() {
    int num, max = INT_MIN;
    while (scanf("%d", &num) == 1) {
        if ((num > INT_MAX - max) && (max != INT_MAX)) { // Check for overflow
            fprintf(stderr, "Overflow detected\n");
            exit(EXIT_FAILURE);
        }
        if (num > max) {
            max = num;
        }
    }
    return max;
}

// Function to allocate and initialize records
Record* allocate_and_initialize_records(size_t count, size_t int_range, int target_endianness, int max_threads) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    log_message("Function start", "INFO");

    Record* records = NULL;
    size_t total_size = count * sizeof(Record);

    while (total_size > 0 && total_size <= MAX_MEMORY_SIZE) {
        records = malloc(total_size);
        if (records) break;

        // Double the allocation attempt for fragmentation handling
        total_size /= 2;
    }

    if (!records) {
        log_message("Allocation failed", "ERROR");
        fclose(log_file);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % int_range;
        records[i].offset = rand();
        records[i].status = 'N'; // Default status
    }

    // Thread pool management
    start_thread_pool(max_threads);

    log_message("Function end", "INFO");
    pthread_mutex_unlock(&lock);
    fclose(log_file);

    return records;
}

int main() {
