typedef struct {
    int value;
    long offset;
    uint32_t unique_id;
} record;

typedef struct {
    char *buffer;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} log_buffer;

log_buffer logs = { .buffer = NULL, .capacity = 0, .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

uint32_t generate_hash(const record *r) {
    uint32_t hash = r->value ^ ((uint32_t)r->offset >> 16);
    return hash;
}

void log_event(const char *event) {
    pthread_mutex_lock(&logs.lock);
    if (logs.count == logs.capacity) {
        size_t old_capacity = logs.capacity;
        logs.capacity = logs.capacity > 0 ? logs.capacity * 2 : MAX_BUFFER_SIZE;
        char *new_buffer = realloc(logs.buffer, sizeof(char) * logs.capacity);
        if (!new_buffer) {
            fprintf(stderr, "Log buffer reallocation failed\n");
            pthread_mutex_unlock(&logs.lock);
            return;
        }
        logs.buffer = new_buffer;
    }

    size_t event_len = strlen(event);
    snprintf(logs.buffer + (logs.count * MAX_BUFFER_SIZE), MAX_BUFFER_SIZE, "%s", event);
    logs.count++;
    if (logs.count >= LOG_ENTRIES) {
        logs.count = 0;
    }
    pthread_mutex_unlock(&logs.lock);
}

void initialize_logs() {
    logs.capacity = MAX_BUFFER_SIZE;
    logs.buffer = malloc(sizeof(char) * logs.capacity);
    if (!logs.buffer) {
        fprintf(stderr, "Log buffer initialization failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_logs() {
    pthread_mutex_lock(&logs.lock);
    free(logs.buffer);
    logs.buffer = NULL;
    logs.capacity = 0;
    logs.count = 0;
    pthread_mutex_unlock(&logs.lock);
}

typedef enum { BINARY, JSON } format_type;

int serialize_record(const record *r, char **output, format_type format) {
    if (!r || !output) return -1;

    size_t buffer_size;
    switch (format) {
        case BINARY:
            buffer_size = sizeof(r->value) + sizeof(r->offset) + sizeof(r->unique_id);
            break;
        case JSON:
            buffer_size = snprintf(NULL, 0, "{\"int\": %d, \"long\": %ld, \"id\": %u}", r->value, r->offset, r->unique_id) + 1;
            break;
    }

    *output = malloc(buffer_size);
    if (!*output) return -2;

