            memcpy((char *)*output + sizeof(r->value), &r->offset, sizeof(r->offset));
            memcpy((char *)*output + sizeof(r->value) + sizeof(r->offset), &r->unique_id, sizeof(r->unique_id));
            break;
        case JSON:
            snprintf(*output, buffer_size, "{\"int\": %d, \"long\": %ld, \"id\": %u}", r->value, r->offset, r->unique_id);
            break;
    }
    return 0;
}

void manage_records(record **records, size_t *num_records, size_t max_memory, int min_val, int max_val) {
    if (!records || !num_records || max_memory == 0) return;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    while (1) {
        pthread_mutex_lock(&lock);
        size_t current_size = *num_records * sizeof(record);
        if (current_size >= max_memory) break;

        record new_record;
        int random_int = rand() % (max_val - min_val + 1) + min_val;
        long offset = (*num_records > 0) ? ((*records)[*num_records - 1].offset + sizeof(record)) : 0;

        new_record.value = random_int;
        new_record.offset = offset;
        new_record.unique_id = generate_hash(&new_record);

        record *temp = realloc(*records, (*num_records + 1) * sizeof(record));
        if (!temp) {
            log_event("Memory allocation failed for records");
            pthread_mutex_unlock(&lock);
            break;
        }

        (*records) = temp;
        (*records)[*num_records] = new_record;
        (*num_records)++;
        pthread_mutex_unlock(&lock);

        char *serialized_output;
        if (serialize_record(&new_record, &serialized_output, BINARY) != 0) {
            log_event("Serialization failed");
            free(serialized_output);
            continue;
        }

        printf("Serialized record: %s\n", serialized_output);
        free(serialized_output);
    }

    pthread_mutex_destroy(&lock);
}

void find_max_integer() {
    int *numbers = NULL, count = 0;
    size_t capacity = 0;
    int number;

    while (scanf("%d", &number) == 1) {
        if (count == capacity) {
            capacity = capacity > 0 ? capacity * 2 : 4;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                fprintf(stderr, "Reallocation failed\n");
                exit(EXIT_FAILURE);
            }
        }

        numbers[count++] = number;
    }

    int max = count > 0 ? numbers[0] : INT_MIN;

    for (int i = 1; i < count; ++i) {
        if (numbers[i] > max) max = numbers[i];
    }

    printf("Maximum integer: %d\n", max);
    free(numbers);
}

