#include <time.h>

typedef struct {
    int value;
    int keyIndex;
    long offsetIndex;
} Record;

#define SUCCESS 0
#define MEMORY_ALLOCATION_FAILED 1

// Function prototypes
int initialize_data(long size, void (*get_range)(int*, int*), unsigned int seed, Record*** records);
void free_resources(Record** records, long* offsets, int* keys);

int initialize_data(long size, void (*get_range)(int*, int*), unsigned int seed, Record*** records) {
    if (size <= 0 || !records || !get_range) return MEMORY_ALLOCATION_FAILED;

    // Allocate memory for arrays
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    Record** local_records = (Record**)malloc(size * sizeof(Record*));

    if (!offsets || !keys || !local_records) {
        free_resources(NULL, offsets, keys);
        return MEMORY_ALLOCATION_FAILED;
    }

    // Set random seed
    srand(seed);

    int min_range, max_range;
    get_range(&min_range, &max_range); // Get range from external source

    for (long i = 0; i < size; ++i) {
        offsets[i] = i * sizeof(long);
        keys[i] = rand() % 1000; // Example key generation
        local_records[i] = (Record*)malloc(sizeof(Record));

        if (!local_records[i]) {
            free_resources(local_records, offsets, keys);
            return MEMORY_ALLOCATION_FAILED;
        }

        local_records[i]->value = min_range + rand() % (max_range - min_range + 1);
        local_records[i]->keyIndex = i;
        local_records[i]->offsetIndex = i;

        // Bounds checking example
        if (local_records[i]->keyIndex >= size || local_records[i]->offsetIndex >= size) {
            free_resources(local_records, offsets, keys);
            return MEMORY_ALLOCATION_FAILED;
        }
    }

    // Validation function
    for (long i = 0; i < size; ++i) {
        if (local_records[i] == NULL || keys[i] <= 0 || offsets[i] != i * sizeof(long)) {
            free_resources(local_records, offsets, keys);
            return MEMORY_ALLOCATION_FAILED;
        }
    }

    // Successful initialization
    *records = local_records;
    return SUCCESS;
}

void free_resources(Record** records, long* offsets, int* keys) {
    if (records) {
        for (long i = 0; i < size && records[i]; ++i) {
            free(records[i]);
        }
        free(records);
    }
    free(offsets);
    free(keys);
}
