```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_SIZE 1024 * 1024 // Example max size in bytes
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 100

typedef struct {
    int id;
    long offset;
    char *buffer;
} Record;

typedef struct {
    double value;
    char name[32];
    bool active;
} Config;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

static uint32_t seed;

// Random number generator
uint32_t rand_r(uint32_t *seedp) {
    const uint32_t a = 1103515245U;
    const uint32_t c = 12345U;
    uint32_t x = *seedp;
    *seedp = a * x + c;
    return (*seedp);
}

int get_random_int(int min, int max) {
    if (min > max) return -1; // Error case
    return rand_r(&seed) % (max - min + 1) + min;
}

// Initialize random seed with current time
void init_random_seed() {
    seed = (uint32_t)time(NULL);
}

Record* allocate_records(size_t count, int *result_count) {
    if (!count || !result_count) return NULL;

    pthread_mutex_lock(&lock);

    size_t total_size = sizeof(Record) + 256; // Assume max buffer size
    size_t required_memory = total_size * count;

    if (required_memory > MAX_SIZE) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Memory allocation exceeds maximum allowed size\n");
        return NULL;
    }

    Record *records = malloc(count * sizeof(Record));
    if (!records) {
        pthread_mutex_unlock(&lock);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].id = get_random_int(INT_RANGE_MIN, INT_RANGE_MAX);
        records[i].offset = rand_r(&seed); // Example offset
        size_t buf_size = rand_r(&seed) % 256 + 1;
        records[i].buffer = malloc(buf_size);
        if (!records[i].buffer) {
            for (size_t j = 0; j < i; ++j) free(records[i].buffer);
            free(records);
            pthread_mutex_unlock(&lock);
            perror("Failed to allocate memory for buffer");
            return NULL;
        }
        memset(records[i].buffer, 'A' + rand_r(&seed) % 26, buf_size);
    }

    *result_count = count;
    pthread_mutex_unlock(&lock);

    return records;
}

Config* allocate_configs(size_t count, int *result_count) {
    if (!count || !result_count) return NULL;

    pthread_mutex_lock(&lock);

    size_t required_memory = sizeof(Config) + 32; // Assume max name length
    if (required_memory * count > MAX_SIZE) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Memory allocation exceeds maximum allowed size\n");
        return NULL;
    }

    Config *configs = malloc(count * sizeof(Config));
    if (!configs) {
        pthread_mutex_unlock(&lock);
        perror("Failed to allocate memory for configs");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        configs[i].value = rand_r(&seed) / ((double)(UINT_MAX + 1));
        snprintf(configs[i].name, sizeof(configs[i].name), "Config_%zu", i);
        configs[i].active = (rand_r(&seed) % 2 == 0);
    }

    *result_count = count;
    pthread_mutex_unlock(&lock);

    return configs;
}

// Serialization and deserialization functions
void serialize_records(const Record *records, size_t count, uint8_t **buffer, size_t *size) {
    if (!records || !count || !buffer || !size) return;

    // Calculate buffer size needed for serialization
    size_t total_size = 0;
    for (size_t i = 0; i < count; ++i) {
        total_size += sizeof(Record);
        total_size += strlen(records[i].buffer) + 1; // Include null terminator
    }

    *buffer = malloc(total_size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization buffer");
        return;
    }

    uint8_t *ptr = *buffer;
    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &records[i], sizeof(Record));
        ptr += sizeof(Record);
        memcpy(ptr, records[i].buffer, strlen(records[i].buffer) + 1);
        ptr += strlen(records[i].buffer) + 1;
    }

    *size = total_size;
}

void deserialize_records(const uint8_t *buffer, size_t size, Record **records, size_t *count) {
    if (!buffer || !size || !records || !count) return;

    size_t offset = 0;
    size_t record_count = size / sizeof(Record);
    *records = malloc(record_count * sizeof(Record));
    if (!*records) {
        perror("Failed to allocate memory for deserialized records");
        return;
    }

    Record *rec_ptr = *records;
    for (size_t i = 0; i < record_count && offset + sizeof(Record) <= size; ++i, ++rec_ptr) {
        memcpy(rec_ptr, buffer + offset, sizeof(Record));
        size_t buf_size = strlen(buffer + offset + sizeof(Record)) + 1;
        rec_ptr->buffer = malloc(buf_size);
        if (!rec_ptr->buffer) {
            for (size_t j = 0; j < i; ++j) free((*records)[j].buffer);
            free(*records);
            perror("Failed to allocate memory for deserialized buffer");
            return;
        }
        memcpy(rec_ptr->buffer, buffer + offset + sizeof(Record), buf_size);
        offset += sizeof(Record) + buf_size;
    }

    *count = record_count;
}

// Example usage
int main() {
    init_random_seed();

    int record_count = 10;
    Record *records = allocate_records(record_count, &record_count);
    if (records) {
        printf("Allocated %d records.\n", record_count);

        uint8_t *serialized_data;
        size_t serialized_size;
        serialize_records(records, record_count, &serialized_data, &serialized_size);

        Record *deserialized_records = NULL;
        size_t deserialized_count;
        deserialize_records(serialized_data, serialized_size, &deserialized_records, &deserialized_count);

        if (deserialized_records) {
            printf("Deserialized %d records.\n", deserialized_count);
            // Free deserialized records
            for (size_t i = 0; i < deserialized_count; ++i) free(deserialized_records[i].buffer);
            free(deserialized_records);
        }

        // Free original records
        for (int i = 0; i < record_count; ++i) free(records[i].buffer);
        free(records);

        free(serialized_data);
    }

    int config_count = 5;
    Config *configs = allocate_configs(config_count, &config_count);
    if (configs) {
        printf("Allocated %d configs.\n", config_count);
        // Use configs
        free(configs);
    }

    return 0;
}
