['```c
#include <stdio.h>
#include <stdlib.h>
import time.h
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} record;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2
#define MAX_INT_SUM 10000

typedef enum {
    SUCCESS = 0,
    ALLOCATION_ERROR,
    INITIALIZATION_ERROR,
    DUPLICATE_KEY_ERROR,
    SUM_OVERFLOW_ERROR
} status_code_t;

status_code_t initialize_records(record **records, size_t *size, int max_value, const char *log_file_path);
void resize_records_array(record **records, size_t *capacity, FILE *log_file);
int validate_record_initialization(const record *records, size_t size);
int is_duplicate_key(const record *records, size_t size, int key);
void log_message(FILE *log_file, const char *message);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

status_code_t initialize_records(record **records, size_t *size, int max_value, const char *log_file_path) {
    FILE *log_file = fopen(log_file_path, "a");
    if (!log_file) return ALLOCATION_ERROR;

    pthread_mutex_lock(&lock);

    *records = (record *)calloc(INITIAL_CAPACITY, sizeof(record));
    if (*records == NULL) {
        log_message(log_file, "Error: Initial allocation failed.\n");
        fclose(log_file);
        pthread_mutex_unlock(&lock);
        return ALLOCATION_ERROR;
    }

    size_t capacity = INITIAL_CAPACITY;
    *size = 0;
    srand(time(NULL));

    int sum_of_keys = 0;
    for (int i = 0; i < INITIAL_CAPACITY; ++i) {
        if (*size >= capacity) {
            resize_records_array(records, &capacity, log_file);
        }

        int random_key;
        do {
            random_key = rand() % max_value + 1;
        } while (is_duplicate_key(*records, *size, random_key));

        (*records)[*size].key = random_key;
        (*records)[*size].offset = time(NULL) + i; // example offset

        if ((sum_of_keys += random_key) > MAX_INT_SUM) {
            log_message(log_file, "Error: Sum of keys exceeds maximum limit.\n");
            free(*records);
            fclose(log_file);
            pthread_mutex_unlock(&lock);
            return SUM_OVERFLOW_ERROR;
        }

        *size += 1;

        if (!validate_record_initialization(*records, *size)) {
            log_message(log_file, "Error: Record initialization failed.\n");
            free(*records);
            fclose(log_file);
            pthread_mutex_unlock(&lock);
            return INITIALIZATION_ERROR;
        }
    }

    pthread_mutex_unlock(&lock);

    log_message(log_file, "Success: Records initialized successfully.\n");
    fclose(log_file);

    return SUCCESS;
}

void resize_records_array(record **records, size_t *capacity, FILE *log_file) {
    size_t new_capacity = *capacity * GROWTH_FACTOR;
    record *new_records = (record *)realloc(*records, new_capacity * sizeof(record));

    if (!new_records) {
        log_message(log_file, "Error: Resize allocation failed.\n");
        free(*records);
        pthread_mutex_unlock(&lock);
        exit(ALLOCATION_ERROR);
    }

    for (size_t i = *capacity; i < new_capacity; ++i) {
        new_records[i].key = 0;
        new_records[i].offset = -1;
    }

    *records = new_records;
    *capacity = new_capacity;

    log_message(log_file, "Info: Records array resized successfully.\n");
}

int validate_record_initialization(const record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].key <= 0 || records[i].offset < 0) {
            return 0;
        }
    }
    return 1;
}

int is_duplicate_key(const record *records, size_t size, int key) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].key == key) {
            return 1;
        }
    }
    return 0;
}

void log_message(FILE *log_file, const char *message) {
    fprintf(log_file, "%s", message);
}
