['Here is a C function that dynamically manages memory for an array of `record` structures, with considerations for high-performance computing environments:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t max_records) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (record*)calloc(max_records, sizeof(record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = max_records;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int add_record(RecordManager *manager, int value) {
    if (pthread_mutex_lock(&manager->lock) != 0) return -1;

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        record *new_records = (record*)realloc(manager->records, new_capacity * sizeof(record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->count].value = value;
    manager->count++;

    int result = 0; // Success
    pthread_mutex_unlock(&manager->lock);
    return result;
}

void update_record(RecordManager *manager, size_t index, int value) {
    if (pthread_mutex_lock(&manager->lock) != 0 || index >= manager->count) {
        return;
    }

    manager->records[index].value = value;

    pthread_mutex_unlock(&manager->lock);
}

size_t get_record_count(const RecordManager *manager) {
    size_t count;

    if (pthread_mutex_lock(&manager->lock) != 0) return 0;
    count = manager->count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

void release_resources(RecordManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

