#include <pthread.h>

typedef enum { INT_TYPE, FLOAT_TYPE, STRING_TYPE } DataType;

typedef struct {
    void *data;
    DataType type;
} Field;

typedef struct {
    Field fields[10];  // Adjust based on maximum expected number of fields
    size_t field_count;
} Record;

typedef struct {
    Record **records;
    size_t max_records;
    size_t current_size;
    pthread_mutex_t lock;
} RecordArray;

RecordArray* create_record_array(size_t max_records) {
    if (max_records == 0) return NULL;

    RecordArray *array = malloc(sizeof(RecordArray));
    if (!array) return NULL;

    array->records = calloc(max_records, sizeof(Record *));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->max_records = max_records;
    array->current_size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int add_record(RecordArray *array, Record *record) {
    if (!array || !record || array->current_size >= array->max_records)
        return -1;

    pthread_mutex_lock(&array->lock);

    // Validate record size
    if (record->field_count > sizeof(record->fields) / sizeof(record->fields[0])) {
        pthread_mutex_unlock(&array->lock);
        return -2;
    }

    Record **new_records = realloc(array->records, sizeof(Record *) * (array->current_size + 1));
    if (!new_records) {
        pthread_mutex_unlock(&array->lock);
        return -3;
    }

    array->records = new_records;
    array->records[array->current_size] = record;

    array->current_size++;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void release_record_array(RecordArray *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->current_size; ++i) {
        Record *record = array->records[i];
        for (size_t j = 0; j < record->field_count; ++j) {
            Field field = record->fields[j];
            if (field.type == STRING_TYPE && field.data)
                free(field.data);
        }
        free(record);
    }

    free(array->records);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);

    free(array);
}

int main() {
    // Example usage
    RecordArray *record_array = create_record_array(100);

    if (!record_array) {
        fprintf(stderr, "Failed to create record array\n");
        return 1;
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) goto cleanup;

    new_record->field_count = 2; // Example field count

    // Int field
    int int_data = 42;
    new_record->fields[0].data = &int_data;
    new_record->fields[0].type = INT_TYPE;

    // String field
    char *string_data = strdup("example");
    if (!string_data) {
        free(new_record);
        goto cleanup;
    }
    new_record->fields[1].data = string_data;
    new_record->fields[1].type = STRING_TYPE;

    if (add_record(record_array, new_record) != 0) {
        fprintf(stderr, "Failed to add record\n");
        free(string_data);
        free(new_record);
        goto cleanup;
    }

    // Add more records as needed...

cleanup:
    release_record_array(record_array);

    return 0;
}
