                snprintf(str, 11, "%d", randomValue);
                records[i]->stringValue = str; 
                break;
        }

        offsets[i] = currentOffset;
        currentOffset += sizeof(long) + sizeof(int) + sizeof(Record*);
    }

    *error_code = 0;
    return records;
}

// Function to validate data.
int validate_data(const long* offsets, const int* keys, const Record** records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        if ((unsigned long)(offsets[i]) > (unsigned long)(sizeof(long) * numRecords)) return -1;
        if (!keys[i] || !records[i]) return -2;
    }
