#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define STRING_MAX_LENGTH 256

typedef struct {
    long offset;
    int key;
    float value;
    char str[STRING_MAX_LENGTH];
    bool flag;
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager() {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    memset(manager->records, 0, sizeof(manager->records));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int add_record(RecordManager* manager, long offset, int key, float value, const char* str, bool flag) {
    if (manager->count >= MAX_RECORDS) return -1;

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return -1;

    record->offset = offset;
    record->key = key;
    record->value = value;
    strncpy(record->str, str, STRING_MAX_LENGTH - 1);
    record->str[STRING_MAX_LENGTH - 1] = '\0';
    record->flag = flag;

    pthread_mutex_lock(&manager->lock);
    manager->records[manager->count++] = record;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

Record* get_record(RecordManager* manager, int index) {
    if (index < 0 || index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);
    Record* record = manager->records[index];
    pthread_mutex_unlock(&manager->lock);

    return record;
}

int delete_record(RecordManager* manager, int index) {
    if (index < 0 || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);
    Record* record = manager->records[index];
    free(record);

    for (int i = index; i < manager->count - 1; ++i) {
        manager->records[i] = manager->records[i + 1];
    }
    manager->records[--manager->count] = NULL;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int get_record_count(RecordManager* manager) {
    int count;
    pthread_mutex_lock(&manager->lock);
    count = manager->count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

void destroy_record_manager(RecordManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
