    if (collection->memory_usage + record_size > collection->max_memory_usage) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Error: Memory usage limit exceeded");
        return -1;
    }

    collection->records[collection->count++] = new_record;
    collection->memory_usage += record_size;

    pthread_mutex_unlock(&collection->lock);
