    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
    if (buffer) free(buffer);
    log_event("Resources freed successfully");
}

// Unit tests and additional functions can be added here

int main() {
    initialize_random_seed();

    RecordCollection *collection = create_record_collection(MAX_MEMORY_USAGE);
    for (int i = 0; i < 10; ++i) {
        add_record(collection, 1, 100);
    }

    uint8_t *serialized_data;
    size_t serialized_size = serialize_records(collection, &serialized_data);

    if (serialized_size > 0) {
        uint8_t *compressed_data;
        size_t compressed_size = compress_data(serialized_data, serialized_size, &compressed_data);

        if (compressed_size > 0) {
            uint8_t *decompressed_data;
            size_t decompressed_size = decompress_data(compressed_data, compressed_size, &decompressed_data);

            free(compressed_data);
            if (decompressed_size == serialized_size && memcmp(serialized_data, decompressed_data, decompressed_size) == 0) {
                log_event("Compression and decompression successful");
            }
            free(decompressed_data);
        }

        free(serialized_data);
    }

    uint32_t hash = hash_integer(42, "simple");
    printf("Hash: %u\n", hash);

    free_record_collection(collection, NULL);

    return 0;
}
