    char status[STATUS_SIZE];
} Event;

// Function prototypes
Event* initialize_events(size_t num_events, size_t max_memory);
void serialize_events(const Event *events, size_t num_events, unsigned char **buffer, size_t *length);
int deserialize_events(const unsigned char *buffer, size_t length, Event **events, size_t *num_events);
size_t calculate_event_size();
void log_status(const Event *event);
void store_unsent_event(Event event);
void resubmit_unsent_events();
