Event* initialize_events(size_t num_events, size_t max_memory) {
    srand(time(NULL));

    Event *events = NULL;
    size_t event_size = sizeof(Event);
    if (num_events * event_size > max_memory) {
        fprintf(stderr, "Memory allocation exceeds maximum limit.\n");
        return NULL;
    }

    events = malloc(num_events * event_size);
    if (!events) {
        perror("Failed to allocate memory for events");
        return NULL;
    }

    for (size_t i = 0; i < num_events; ++i) {
        events[i].timestamp = time(NULL); // Current timestamp
        events[i].event_id = rand() % (EVENT_ID_MAX - EVENT_ID_MIN + 1) + EVENT_ID_MIN;
        snprintf(events[i].status, STATUS_SIZE, "OK");
    }

    return events;
}

void serialize_events(const Event *events, size_t num_events, unsigned char **buffer, size_t *length) {
    if (!events || !num_events || !buffer || !length) return;

    size_t event_size = calculate_event_size();
    *length = num_events * event_size;

    *buffer = malloc(*length);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization buffer");
        return;
    }

    memcpy(*buffer, events, *length);
}

int deserialize_events(const unsigned char *buffer, size_t length, Event **events, size_t *num_events) {
    if (!buffer || !length || !events || !num_events) return -1;

    size_t event_size = calculate_event_size();
    if (length % event_size != 0) return -2; // Incompatible buffer size

    *num_events = length / event_size;
    *events = malloc(length);

    if (!*events) {
        perror("Failed to allocate memory for deserialized events");
        return -1;
    }

    memcpy(*events, buffer, length);
    return 0;
}

size_t calculate_event_size() {
    return sizeof(Event);
}

void log_status(const Event *event) {
    // Simulate logging by printing (can be replaced with network call)
    printf("Logging status: %s\n", event->status);

    // Simulate possible failure and fallback
    if ((rand() % 10) < 2) { // 20% chance of failure
        fprintf(stderr, "Failed to log status. Storing locally.\n");
        store_unsent_event(*event);
    }
}

void store_unsent_event(Event event) {
    static Event unsent_events[100];
    static size_t count = 0;

    if (count < sizeof(unsent_events) / sizeof(Event)) {
        unsent_events[count++] = event;
    } else {
        fprintf(stderr, "Unsent events buffer is full.\n");
    }
}

void resubmit_unsent_events() {
    // Simulated logic to resend stored events
    static Event unsent_events[100];
    static size_t count = 0;

    for (size_t i = 0; i < count; ++i) {
        log_status(&unsent_events[i]);
    }
    count = 0;
}

void read_and_print_earliest_timestamp() {
    char input[1024];
    time_t timestamps[100];
    size_t count = 0;

    printf("Enter timestamps (seconds since epoch), one per line:\n");
    while (fgets(input, sizeof(input), stdin) && count < sizeof(timestamps) / sizeof(time_t)) {
        if (sscanf(input, "%ld", &timestamps[count]) == 1) {
            ++count;
        }
    }

    if (count == 0) return;

    time_t earliest = timestamps[0];
    for (size_t i = 1; i < count; ++i) {
        if (timestamps[i] < earliest) {
            earliest = timestamps[i];
        }
    }

    printf("Earliest timestamp: %ld\n", earliest);
}

char* generate_random_string(size_t length, const char *charset) {
    char *random_str = malloc(length + 1); // +1 for null-terminator
    if (!random_str) {
        perror("Failed to allocate memory for random string");
        return NULL;
    }

    size_t charset_size = strlen(charset);
    for (size_t i = 0; i < length; ++i) {
        random_str[i] = charset[rand() % charset_size];
    }
    random_str[length] = '\0';

    return random_str;
}
```

