typedef struct {
    unsigned long timestamp;
    float value;
    char *log_message;
} MetricEntry;

MetricEntry* initializeMetrics(size_t num_entries, float min_value, float max_value) {
    if (num_entries == 0 || min_value >= max_value)
        return NULL;

    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for entries array
    MetricEntry *entries = malloc(num_entries * sizeof(MetricEntry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    float range = max_value - min_value;

    for (size_t i = 0; i < num_entries; ++i) {
        // Generate a random timestamp
        entries[i].timestamp = rand() % (ULONG_MAX + 1);

        // Generate a random value within the specified range
        entries[i].value = min_value + ((float)rand() / RAND_MAX) * range;

        // Allocate memory for log message with variable length (e.g., 50 characters)
        size_t log_message_length = rand() % 51; // Random length between 0 and 50
        entries[i].log_message = malloc(log_message_length + 1); // +1 for null terminator

        if (!entries[i].log_message) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free all previously allocated entries before returning NULL
            for (size_t j = 0; j < i; ++j)
                free(entries[j].log_message);
            free(entries);
            return NULL;
        }

        // Generate a random log message
        snprintf(entries[i].log_message, log_message_length + 1, "Log entry %zu", i);
    }

    return entries;
}

void freeMetrics(MetricEntry *entries, size_t num_entries) {
    if (!entries)
        return;

    for (size_t i = 0; i < num_entries; ++i) {
        free(entries[i].log_message); // Free each log message
    }

    free(entries); // Finally, free the array of entries
}

int main() {
    size_t num_entries = 100;
    float min_value = -10.0f;
    float max_value = 10.0f;

    MetricEntry *metrics = initializeMetrics(num_entries, min_value, max_value);
    if (!metrics) {
        fprintf(stderr, "Failed to initialize metrics\n");
        return EXIT_FAILURE;
    }

    // Example of using the metric entries
    for (size_t i = 0; i < num_entries; ++i) {
        printf("Entry %zu: Timestamp = %lu, Value = %.2f, Log Message = %s\n",
               i, metrics[i].timestamp, metrics[i].value, metrics[i].log_message);
    }

    // Clean up
    freeMetrics(metrics, num_entries);

    return EXIT_SUCCESS;
}
