#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    double value;
    char buffer[256];
    bool active;
} entry_t;

typedef struct {
    float *float_values;
    unsigned long *timestamps;
    entry_t **entries;
    size_t count;
    pthread_mutex_t lock;
} data_structure_t;

// Utility function to generate a random double in the specified range
double random_double(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

data_structure_t* initialize_data_structure(size_t count, double min_value, double max_value) {
    data_structure_t *ds = malloc(sizeof(data_structure_t));
    if (!ds) {
        perror("Failed to allocate memory for data structure");
        return NULL;
    }

    ds->float_values = malloc(count * sizeof(float));
    ds->timestamps = malloc(count * sizeof(unsigned long));
    ds->entries = calloc(count, sizeof(entry_t*));

    if (!ds->float_values || !ds->timestamps || !ds->entries) {
        perror("Failed to allocate memory for arrays");
        free(ds->float_values);
        free(ds->timestamps);
        free(ds->entries);
        free(ds);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        ds->float_values[i] = rand() / (float)RAND_MAX;

        ds->timestamps[i] = time(NULL) + i; // Example timestamp initialization

        entry_t *new_entry = malloc(sizeof(entry_t));
        if (!new_entry) {
            perror("Failed to allocate memory for entry");
            break;
        }

        new_entry->value = random_double(min_value, max_value);
        strncpy(new_entry->buffer, "Fixed-length string", sizeof(new_entry->buffer) - 1);
        new_entry->buffer[sizeof(new_entry->buffer) - 1] = '\0';
        new_entry->active = true;

        ds->entries[i] = new_entry;
    }

    ds->count = count;
    return ds;
}

void cleanup_data_structure(data_structure_t *ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->entries[i]);
    }

    free(ds->float_values);
    free(ds->timestamps);
    free(ds->entries);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);

    free(ds);
}

int main() {
    size_t count = 1000;
    double min_value = 0.0, max_value = 1.0;

    data_structure_t *ds = initialize_data_structure(count, min_value, max_value);
    if (ds) {
        // Use the data structure...

        cleanup_data_structure(ds);
    }

    return 0;
}
```

### Key Considerations:

- **Memory Allocation**: Efficient allocation is achieved by using `malloc` and `calloc`, ensuring zero-initialization for pointers. Error handling ensures memory is freed in case of failures.

- **Random Initialization**: The use of a seeded pseudo-random generator provides deterministic random values within a specified range.

- **Thread Safety**: A mutex (`pthread_mutex_t`) is used to ensure thread-safe operations during cleanup, minimizing lock contention by locking only when necessary.

- **Data Locality and Fragmentation**: Memory allocations are contiguous where possible, improving cache locality. Dynamic allocation allows for flexibility in scaling the data structure.

- **Error Handling**: Robust error handling ensures that any failure in memory allocation leads to a graceful exit with resources properly freed.

This implementation balances efficiency, scalability, and thread safety, making it suitable for integration into high-performance engineering environments.']

