} Task;

Task* initialize_tasks(size_t num_tasks, size_t max_name_length) {
    if (num_tasks == 0 || max_name_length == 0) return NULL;

    Task *tasks = malloc(num_tasks * sizeof(Task));
    if (!tasks) {
        perror("Failed to allocate tasks array");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_tasks; ++i) {
        tasks[i].priority = rand() % 100;
        tasks[i].start_time = time(NULL) + rand() % (60 * 60); // Random start within next hour

        size_t name_length = rand() % max_name_length + 1;
        tasks[i].task_name = malloc(name_length);
        if (!tasks[i].task_name) {
            perror("Failed to allocate task name");
            for (size_t j = 0; j < i; ++j) free(tasks[j].task_name);
            free(tasks);
            exit(EXIT_FAILURE);
        }

        snprintf(tasks[i].task_name, name_length, "Task_%zu", i + 1);
    }

    return tasks;
}

void execute_tasks(Task *tasks, size_t num_tasks, void (*callback)(Task*)) {
    if (!tasks || !callback) return;

    for (size_t i = 0; i < num_tasks; ++i) {
        callback(&tasks[i]);
    }
}

void free_tasks(Task *tasks, size_t num_tasks) {
    if (!tasks) return;

    for (size_t i = 0; i < num_tasks; ++i) {
        free(tasks[i].task_name);
    }

    free(tasks);
}

// Example callback function
