['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_MEMORY_USAGE 10485760 // 10 MB limit for demonstration purposes

typedef struct {
    int value;
    long offset;
    unsigned char *pixel_data;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t count;
    size_t capacity;
} dynamic_array;

// Helper function to handle memory allocation and check for errors
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Resize a dynamic array with caching strategy
void resize_array(dynamic_array *arr, size_t new_capacity) {
    arr->offsets = realloc(arr->offsets, sizeof(long) * new_capacity);
    arr->keys = realloc(arr->keys, sizeof(int) * new_capacity);
    arr->records = realloc(arr->records, sizeof(record) * new_capacity);

    if (new_capacity > arr->capacity) {
        for (size_t i = arr->capacity; i < new_capacity; ++i) {
            arr->offsets[i] = 0;
            arr->keys[i] = 0;
            arr->records[i].value = 0;
            arr->records[i].offset = 0;
            arr->records[i].pixel_data = NULL;
        }
    }

    arr->capacity = new_capacity;
}

// Initialize dynamic arrays
void init_dynamic_array(dynamic_array *arr, size_t initial_capacity) {
    arr->count = 0;
    arr->capacity = initial_capacity;
    arr->offsets = safe_malloc(sizeof(long) * initial_capacity);
    arr->keys = safe_malloc(sizeof(int) * initial_capacity);
    arr->records = safe_malloc(sizeof(record) * initial_capacity);
}

// Free all allocated memory
void free_dynamic_array(dynamic_array *arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->records[i].pixel_data);
    }
    free(arr->offsets);
    free(arr->keys);
    free(arr->records);
}

// Load image from file, validate dimensions and quality
int load_image(const char *file_path, unsigned char **pixel_data, size_t *width, size_t *height) {
    // Dummy implementation for illustration
    // In practice, use a library like libpng or libjpeg to handle PNG/JPEG files.
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open image file: %s\n", file_path);
        return -1;
    }

    // Validate dimensions and quality
    *width = 100; // Example dimension
    *height = 100;

    size_t size = *width * *height * 3; // Assuming RGB for simplicity
    *pixel_data = safe_malloc(size);

    fread(*pixel_data, sizeof(unsigned char), size, file);
    fclose(file);

    return 0;
}

// Calculate average brightness of an image
float calculate_average_brightness(const unsigned char *pixel_data, size_t width, size_t height) {
    long total_brightness = 0;
    size_t num_pixels = width * height;

    for (size_t i = 0; i < num_pixels; ++i) {
        // Assuming RGB format
        total_brightness += (int)pixel_data[3*i] + (int)pixel_data[3*i+1] + (int)pixel_data[3*i+2];
    }

    return (float)total_brightness / (num_pixels * 3);
}

// Helper function to calculate average brightness from input image paths
void process_images_from_input() {
    char file_path[256];

    while (fgets(file_path, sizeof(file_path), stdin)) {
        // Remove newline character if present
        size_t len = strlen(file_path);
        if (len > 0 && file_path[len - 1] == '\n') {
            file_path[--len] = '\0';
        }

        unsigned char *pixel_data;
        size_t width, height;

        if (load_image(file_path, &pixel_data, &width, &height) != 0) {
            fprintf(stderr, "Failed to process image: %s\n", file_path);
            continue;
        }

        float avg_brightness = calculate_average_brightness(pixel_data, width, height);
        printf("Average brightness of %s: %.2f\n", file_path, avg_brightness);

        free(pixel_data); // Free the memory allocated for pixel data
    }
}

// Main function demonstrating the usage of dynamic arrays and image processing
int main() {
    dynamic_array arr;
    init_dynamic_array(&arr, 10); // Initial capacity set to 10

    process_images_from_input();

    free_dynamic_array(&arr);

    return 0;
}
```

This code snippet demonstrates a C implementation managing dynamic memory for arrays of `long` offsets, `int` keys, and `record` structures. It includes functions for handling image loading, calculating average brightness, and safely managing memory allocation and deallocation. The code is designed to be maintainable and scalable, with considerations for adding new functionalities or optimizations in the future.']

