using System;
using Docker.DotNet;
using Docker.DotNet.Models;
using Newtonsoft.Json.Linq;
using System.IO;
using System.Threading.Tasks;

public class DockerServiceManager
{
    private readonly DockerClient client;

    public DockerServiceManager()
    {
        client = new DockerClientConfiguration(LocalDockerEndpoint()).CreateClient();
    }

    public async Task AddUserDefinedServiceAsync(string serviceName, string imageName, string configFilePath)
    {
        try
        {
            // Validate image existence
            await ValidateImageExistsAsync(imageName);

            // Validate JSON configuration file
            JToken config;
            using (StreamReader reader = new StreamReader(configFilePath))
            {
                var jsonText = await reader.ReadToEndAsync();
                config = JToken.Parse(jsonText);
            }

            if (!IsValidJsonConfig(config))
            {
                throw new ArgumentException("Invalid JSON configuration file.");
            }

            // Create and start the service
            var createServiceRequest = new CreateServiceParameters
            {
                Name = serviceName,
                TaskTemplate = new ServiceSpec
                {
                    Containers = new[]
                    {
                        new ServiceContainerSpec
                        {
                            Image = imageName,
                            Resources = GetResourcesFromConfig(config)
                        }
                    },
                    EndpointSpec = new ServiceEndpointSpec
                    {
                        Ports = GetPortsFromConfig(config)
                    }
                }
            };

            await client.Services.CreateServiceAsync(createServiceRequest);
            Console.WriteLine($"Service '{serviceName}' has been created and started successfully.");
        }
        catch (Exception ex)
        {
            LogError(ex, serviceName);
        }
    }

    private async Task ValidateImageExistsAsync(string imageName)
    {
        var imageListResponse = await client.Images.ListImagesAsync(new ImagesListParameters { Filters = new Dictionary<string, bool> { ["reference"] = imageName } });

        if (imageListResponse?.Items == null || !imageListResponse.Items.Any())
        {
            throw new ArgumentException($"Docker image '{imageName}' does not exist.");
        }
    }

    private bool IsValidJsonConfig(JToken config)
    {
        // Implement validation logic for the JSON configuration
        return true;
    }

    private Resources GetResourcesFromConfig(JToken config)
    {
        // Extract and configure resource limits based on JSON configuration
        var resources = new Resources();
        if (config["resources"]?["limits"] != null)
        {
            resources.Limits = new Limits
            {
                MemoryBytes = long.Parse(config["resources"]["limits"]["memory"].ToString()),
                NanoCPUs = long.Parse(config["resources"]["limits"]["cpus"].ToString())
            };
        }

        return resources;
    }

    private ServiceEndpointSpec.Ports GetPortsFromConfig(JToken config)
    {
        var ports = new ServiceEndpointSpec.Ports();

        if (config["ports"] != null)
        {
            foreach (var port in config["ports"])
            {
                int publishedPort = int.Parse(port["published"].ToString());
                int targetPort = int.Parse(port["target"].ToString());
                ports.Add(new PortConfig { PublishedPort = publishedPort, TargetPort = (ushort)targetPort });
            }
        }

        return ports;
    }

    private void LogError(Exception ex, string serviceName)
    {
        Console.WriteLine($"Error occurred while creating service '{serviceName}': {ex.Message}");
        // Implement more detailed logging if required
    }

    private static IUnixSocketLocalDockerEndpoint LocalDockerEndpoint()
    {
        return new UnixSocketLocalDockerEndpoint("/var/run/docker.sock");
    }
}
