['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

typedef struct {
    int key;
    double value;
    uint64_t last_access_time;
    uint32_t access_count;
} Record;

typedef struct {
    size_t capacity;
    size_t used;
    Record *records;
} Collection;

// Function to align memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Function to free aligned memory
void aligned_free(void* ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

Collection* create_collection(size_t initial_capacity) {
    Collection *collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->used = 0;
    collection->records = aligned_alloc(16, sizeof(Record) * initial_capacity);
    if (!collection->records) {
        free(collection);
        return NULL;
    }
    return collection;
}

int resize_collection(Collection *collection, size_t new_capacity) {
    Record *new_records = aligned_alloc(16, sizeof(Record) * new_capacity);
    if (!new_records) return -1;

    memcpy(new_records, collection->records, sizeof(Record) * collection->used);

    aligned_free(collection->records);
    collection->records = new_records;
    collection->capacity = new_capacity;
    return 0;
}

int add_record(Collection *collection, int key, double value) {
    if (collection->used == collection->capacity) {
        if (resize_collection(collection, collection->capacity * 2)) return -1;
    }

    Record *record = &collection->records[collection->used++];
    record->key = key;
    record->value = value;
    record->last_access_time = time(NULL);
    record->access_count = 1;

    return 0;
}

double get_random_value(uint64_t seed) {
    srand(seed ^ (uint32_t)time(NULL));
    return rand() / (RAND_MAX + 1.0);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void cleanup(Collection *collection) {
    if (collection) {
        aligned_free(collection->records);
        free(collection);
    }
}

int main() {
    Collection *my_collection = create_collection(10);
    if (!my_collection) {
        log_error("Failed to create collection");
        return EXIT_FAILURE;
    }

    uint64_t unique_id = 123456789; // Example unique ID from external data source
    double random_value = get_random_value(unique_id);

    add_record(my_collection, 1, random_value);

    cleanup(my_collection);
    return EXIT_SUCCESS;
}
```

This code defines a `Collection` structure to manage records with key-value pairs and associated metadata. It dynamically allocates memory for the collection, handles resizing when needed, generates reproducible random values, logs errors, and ensures proper cleanup of resources. The function is optimized for performance while maintaining robust error handling and alignment considerations.']

