#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define various types of data elements
typedef enum { TYPE_FLOAT, TYPE_CHAR, TYPE_STRUCT, TYPE_ENUM, TYPE_UNION } DataType;

typedef struct {
    float x;
    float y;
} Point;

typedef enum { ID_A, ID_B, ID_C } Identifier;

typedef union {
    char *string;
    int integer;
} UnionData;

// Define the data element structure
typedef struct DataElement {
    DataType type;
    void *data;
    size_t size;
    struct DataElement *next; // Linked list for dynamic management
} DataElement;

// Function to allocate memory safely
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to add a new data element
DataElement *add_data_element(DataElement **head, DataType type, const void *data, size_t size, size_t max_memory_usage, size_t current_memory_usage) {
    if (current_memory_usage + sizeof(*head) + size > max_memory_usage) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    DataElement *new_element = safe_malloc(sizeof(DataElement));
    new_element->type = type;
    new_element->size = size;

    switch (type) {
        case TYPE_FLOAT:
            new_element->data = safe_malloc(size);
            memcpy(new_element->data, data, size);
            break;
        case TYPE_CHAR:
            new_element->data = safe_malloc(size);
            *(char *)new_element->data = *(const char *)data;
            break;
        case TYPE_STRUCT:
            new_element->data = safe_malloc(size);
            memcpy(new_element->data, data, size);
            break;
        case TYPE_ENUM:
            new_element->data = safe_malloc(sizeof(Identifier));
            *(Identifier *)new_element->data = *(const Identifier *)data;
            break;
        case TYPE_UNION:
            if (strstr((char *)data, "string")) {
                UnionData *union_data = safe_malloc(size);
                union_data->string = strdup(data);
                new_element->data = union_data;
            } else {
                UnionData *union_data = safe_malloc(sizeof(UnionData));
                union_data->integer = *(const int *)data;
                new_element->data = union_data;
            }
            break;
    }

    new_element->next = *head;
    *head = new_element;

    return new_element;
}

// Function to serialize the data structure
size_t serialize_data(DataElement *head, unsigned char **buffer) {
    size_t total_size = 0;
    DataElement *current = head;

    // Calculate required buffer size
    while (current) {
        total_size += sizeof(current->type) + current->size;
        current = current->next;
    }

    *buffer = safe_malloc(total_size);
    unsigned char *ptr = *buffer;
    current = head;

    while (current) {
        memcpy(ptr, &current->type, sizeof(current->type));
        ptr += sizeof(current->type);

        switch (current->type) {
            case TYPE_FLOAT:
                memcpy(ptr, current->data, current->size);
                break;
            case TYPE_CHAR:
                *(char *)ptr = *(char *)current->data;
                break;
            case TYPE_STRUCT:
                memcpy(ptr, current->data, current->size);
                break;
            case TYPE_ENUM:
                memcpy(ptr, current->data, sizeof(Identifier));
                break;
            case TYPE_UNION:
                if (strstr((char *)((UnionData *)current->data)->string, "string")) {
                    size_t str_size = strlen(((UnionData *)current->data)->string) + 1;
                    memcpy(ptr, &str_size, sizeof(str_size)); // Store string length
                    ptr += sizeof(str_size);
                    memcpy(ptr, ((UnionData *)current->data)->string, str_size);
                } else {
                    memcpy(ptr, &((UnionData *)current->data)->integer, sizeof(int));
                }
                break;
        }

        ptr += current->size;
        total_size -= (ptr - *buffer);
        current = current->next;
    }

    return total_size;
}

// Function to free the data structure
void free_data_structure(DataElement **head) {
    DataElement *current = *head;
    while (current) {
        DataElement *next = current->next;
        switch (current->type) {
            case TYPE_FLOAT:
            case TYPE_CHAR:
            case TYPE_STRUCT:
                free(current->data);
                break;
            case TYPE_UNION:
                if (strstr((char *)((UnionData *)current->data)->string, "string")) {
                    free(((UnionData *)current->data)->string);
                }
                break;
        }
        free(current);
        current = next;
    }
    *head = NULL;
}

// Example usage
int main() {
    DataElement *data_list = NULL;
    size_t max_memory_usage = 1024; // 1KB for example
    size_t current_memory_usage = sizeof(DataElement) * 10;

    add_data_element(&data_list, TYPE_FLOAT, &3.14f, sizeof(float), max_memory_usage, current_memory_usage);
    add_data_element(&data_list, TYPE_CHAR, (const void *)'A', sizeof(char), max_memory_usage, current_memory_usage);

    unsigned char *serialized_data;
    size_t serialized_size = serialize_data(data_list, &serialized_data);
    printf("Serialized data size: %zu\n", serialized_size);

    free(serialized_data);
    free_data_structure(&data_list);

    return 0;
}
```

