["Below is a simplified implementation outline in C for managing distributed hash tables across nodes with some key features as requested:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_BUCKETS 1024
#define MEMORY_BUDGET_BYTES (100 * 1024 * 1024) // Example global memory budget

typedef struct Entry {
    unsigned long key;
    double value;
    int ref_count;
    struct Entry* next;
} Entry;

typedef struct HashTable {
    Entry** buckets;
    size_t capacity;
    size_t entry_count;
    size_t memory_usage_bytes;
} HashTable;

// Custom hash function
unsigned int custom_hash(unsigned long key, size_t capacity) {
    return (key * 2654435761UL) % capacity; // Knuth's multiplicative method
}

// Initialize a new hash table
HashTable* init_table(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_BUCKETS) return NULL;

    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(initial_capacity, sizeof(Entry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->entry_count = 0;
    table->memory_usage_bytes = sizeof(HashTable) + initial_capacity * sizeof(Entry*);

    return table;
}

// Add or update an entry
void add_entry(HashTable* table, unsigned long key, double value) {
    if (!table || !table->buckets) return;

    size_t index = custom_hash(key, table->capacity);
    Entry** bucket = &table->buckets[index];

    while (*bucket) {
        if ((*bucket)->key == key) {
            (*bucket)->value = value;
            // Handle potential overflow in ref_count
            int new_ref_count = (*bucket)->ref_count + 1;
            if (new_ref_count > INT_MAX) new_ref_count = INT_MAX;
            (*bucket)->ref_count = new_ref_count;
            return;
        }
        bucket = &(*bucket)->next;
    }

    Entry* new_entry = malloc(sizeof(Entry));
    if (!new_entry) return;

    new_entry->key = key;
    new_entry->value = value;
    new_entry->ref_count = 1; // Starting with ref count of 1
    new_entry->next = *bucket;

    table->buckets[index] = new_entry;
    table->entry_count++;
    table->memory_usage_bytes += sizeof(Entry) + sizeof(unsigned long) + sizeof(double);
}

// Remove an entry, considering reference counting
void remove_entry(HashTable* table, unsigned long key) {
    if (!table || !table->buckets) return;

    size_t index = custom_hash(key, table->capacity);
    Entry** bucket = &table->buckets[index];

    while (*bucket) {
        if ((*bucket)->key == key) {
            // Decrement ref_count and remove if it reaches zero
            if (--(*bucket)->ref_count == 0) {
                *bucket = (*bucket)->next;
                free(*bucket);
                table->entry_count--;
                table->memory_usage_bytes -= sizeof(Entry) + sizeof(unsigned long) + sizeof(double);
            }
            return;
        }
        bucket = &(*bucket)->next;
    }
}

// Serialize hash table to a byte array
size_t serialize_table(const HashTable* table, uint8_t** out_buffer) {
    if (!table || !out_buffer) return 0;

    size_t serialized_size = sizeof(size_t); // Store entry_count first
    for (size_t i = 0; i < table->capacity; ++i) {
        Entry* bucket_entry = table->buckets[i];
        while (bucket_entry) {
            serialized_size += sizeof(unsigned long) + sizeof(double) + sizeof(int);
            bucket_entry = bucket_entry->next;
        }
    }

    *out_buffer = malloc(serialized_size);
    if (!*out_buffer) return 0;

    uint8_t* ptr = *out_buffer;
    memcpy(ptr, &table->entry_count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < table->capacity; ++i) {
        Entry* bucket_entry = table->buckets[i];
        while (bucket_entry) {
            memcpy(ptr, &(bucket_entry->key), sizeof(unsigned long));
            ptr += sizeof(unsigned long);
            memcpy(ptr, &(bucket_entry->value), sizeof(double));
            ptr += sizeof(double);
            memcpy(ptr, &(bucket_entry->ref_count), sizeof(int));
            ptr += sizeof(int);
            bucket_entry = bucket_entry->next;
        }
    }

    return serialized_size;
}

// Deserialize from a byte array to hash table
HashTable* deserialize_table(const uint8_t* buffer) {
    if (!buffer) return NULL;

    size_t entry_count;
    const uint8_t* ptr = buffer;
    memcpy(&entry_count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    HashTable* table = init_table(MAX_BUCKETS);
    if (!table || table->capacity < entry_count) {
        free(table);
        return NULL;
    }

    for (size_t i = 0; i < entry_count; ++i) {
        unsigned long key;
        double value;
        int ref_count;

        memcpy(&key, ptr, sizeof(unsigned long));
        ptr += sizeof(unsigned long);
        memcpy(&value, ptr, sizeof(double));
        ptr += sizeof(double);
        memcpy(&ref_count, ptr, sizeof(int));
        ptr += sizeof(int);

        Entry* new_entry = malloc(sizeof(Entry));
        if (!new_entry) {
            // Cleanup on failure
            while (table->buckets[0]) free(table->buckets[0]);
            free(table->buckets);
            free(table);
            return NULL;
        }

        new_entry->key = key;
        new_entry->value = value;
        new_entry->ref_count = ref_count;
        new_entry->next = table->buckets[custom_hash(key, table->capacity)];

        table->buckets[custom_hash(key, table->capacity)] = new_entry;
    }

    return table;
}

// Clean up hash table
void destroy_table(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        Entry* current = table->buckets[i];
        while (current) {
            Entry* next = current->next;
            free(current);
            current = next;
        }
    }

    free(table->buckets);
    free(table);
}

// Example usage
int main() {
    HashTable* table = init_table(1024);

    add_entry(table, 12345678UL, 42.0);
    remove_entry(table, 12345678UL);

    uint8_t* serialized_data;
    size_t data_size = serialize_table(table, &serialized_data);

    HashTable* new_table = deserialize_table(serialized_data);
    destroy_table(new_table);
    free(serialized_data);

    destroy_table(table);
    return 0;
}
```

