typedef struct {
    char *key;
    char *value;
    int usage_count;
    double performance_metric;
    char *message_buffer;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t max_memory_budget; // in bytes
} Collection;

void initialize_collection(Collection *collection, size_t initial_capacity, size_t memory_budget) {
    collection->records = malloc(sizeof(Record*) * initial_capacity);
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->max_memory_budget = memory_budget;
    pthread_mutex_init(&collection->lock, NULL);
}

void destroy_collection(Collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->key);
        free(collection->records[i]->value);
        free(collection->records[i]->message_buffer);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
}

void resize_collection(Collection *collection, size_t new_capacity) {
    Record **new_records = realloc(collection->records, sizeof(Record*) * new_capacity);
    if (new_records) {
        collection->capacity = new_capacity;
        collection->records = new_records;
    }
}

int add_record(Collection *collection, const char *key, const char *value, const char *message) {
    pthread_mutex_lock(&collection->lock);

    size_t key_len = strlen(key);
    size_t value_len = strlen(value);
    size_t message_len = strlen(message);

    if (collection->count + 1 > collection->capacity)
        resize_collection(collection, collection->capacity ? collection->capacity * 2 : 4);

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failure
    }

    new_record->key = malloc(key_len + 1);
    new_record->value = malloc(value_len + 1);
    new_record->message_buffer = malloc(message_len + 1);

    if (!new_record->key || !new_record->value || !new_record->message_buffer) {
        free(new_record->key);
        free(new_record->value);
        free(new_record->message_buffer);
        free(new_record);
        pthread_mutex_unlock(&collection->lock);
        return -2; // Memory allocation failure
    }

    strcpy(new_record->key, key);
    strcpy(new_record->value, value);
    strcpy(new_record->message_buffer, message);

    new_record->usage_count = 0;
    new_record->performance_metric = 0.0;

    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

void update_record(Collection *collection, const char *key, const char *new_value) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->records[i]->key, key) == 0) {
            free(collection->records[i]->value);
            size_t new_value_len = strlen(new_value) + 1;
            collection->records[i]->value = realloc(collection->records[i]->value, new_value_len);

            if (!collection->records[i]->value) {
                pthread_mutex_unlock(&collection->lock);
                return; // Memory allocation failure
            }

            strcpy(collection->records[i]->value, new_value);
            collection->records[i]->usage_count++;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

int largest_integer_in_array() {
    int numbers[100];
    int count = 0;
    int number;

    printf("Enter integers (enter -1 to stop):\n");
    while (count < 100 && scanf("%d", &number) == 1 && number != -1) {
        numbers[count++] = number;
    }

    if (count == 0) return -1; // No input

    int largest = numbers[0];
    for (int i = 1; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    return largest;
}

int main() {
    size_t initial_capacity = 8;
    size_t memory_budget = 1024 * 1024; // 1 MB

    Collection collection;
    initialize_collection(&collection, initial_capacity, memory_budget);

    add_record(&collection, "key1", "value1", "Initial message");
    update_record(&collection, "key1", "updated_value");

    int largest = largest_integer_in_array();
    if (largest != -1) {
        printf("Largest integer: %d\n", largest);
    } else {
        printf("No valid integers were entered.\n");
    }

    destroy_collection(&collection);

    return 0;
}
