['Below is a C function that manages a dynamic collection of records in a multi-threaded environment as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    char status; // 'S' for success, 'F' for failure
} Record;

// Memory pool and lock for thread safety
#define POOL_SIZE 1024 * 64 // Example size
static uint8_t memory_pool[POOL_SIZE];
static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t offset_pointer = 0; // Tracks used memory

// Function prototypes
void* allocate_memory(size_t size);
void free_memory(void* ptr, size_t size);
int initialize_records(Record** records, size_t num_records);

// Allocate memory from the pool
void* allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_lock);
    if (offset_pointer + size > POOL_SIZE) {
        pthread_mutex_unlock(&memory_lock);
        fprintf(stderr, "Memory allocation failed: Out of pool space\n");
        return NULL;
    }
    void* ptr = &memory_pool[offset_pointer];
    offset_pointer += size;
    pthread_mutex_unlock(&memory_lock);
    return ptr;
}

// Free memory (not strictly necessary for fixed-size pool)
void free_memory(void* ptr, size_t size) {
    // No-op for fixed-size memory pool
}

int initialize_records(Record** records, size_t num_records) {
    if (!records || num_records <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    *records = (Record*)allocate_memory(num_records * sizeof(Record));
    if (*records == NULL) {
        return -2;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    // Sets for tracking used offsets and keys
    size_t offset_set[POOL_SIZE] = {0};
    int key_set[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        key_set[i] = -1;
    }

    pthread_mutex_t record_locks[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_init(&record_locks[i], NULL);
    }

    // Initialize records
    for (size_t i = 0; i < num_records; ++i) {
        int initialized = 0;
        while (!initialized) {
            long offset = rand() % POOL_SIZE;
            int key = rand() % num_records;

            pthread_mutex_lock(&memory_lock);
            if (!offset_set[offset] && !key_set[key]) {
                offset_set[offset] = 1; // Mark as used
                key_set[key] = 1;       // Mark as used
                initialized = 1;
            }
            pthread_mutex_unlock(&memory_lock);

            if (!initialized) {
                fprintf(stderr, "Initialization attempt failed for record %zu\n", i);
            }
        }

        pthread_mutex_lock(&record_locks[i]);
        (*records)[i].offset = offset;
        (*records)[i].key = key;
        (*records)[i].status = 'S'; // Mark as success
        pthread_mutex_unlock(&record_locks[i]);

        printf("Record %zu initialized with offset: %ld, key: %d\n", i, offset, key);
    }

    return 0; // Success
}

void cleanup(Record* records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_destroy(&record_locks[i]);
    }

    free_memory(records, num_records * sizeof(Record));
}

// Example usage
int main() {
    Record* records;
    size_t num_records = 10;

    int result = initialize_records(&records, num_records);
    if (result == 0) {
        // Use the records...

        cleanup(records, num_records); // Ensure resources are cleaned up
    }

    return result;
}
```

### Key Points:
- **Memory Pool**: A fixed-size memory pool is used to minimize allocation overhead.
- **Thread Safety**: Mutexes are employed for managing concurrent access and ensuring thread safety during record initialization and potential cleanup.
- **Error Handling**: The function includes checks for input validity, sufficient memory availability, and logs errors appropriately.
- **Random Initialization**: Unique offsets and keys are ensured by checking against used sets.
- **Resource Cleanup**: Proper cleanup is implemented to prevent resource leaks.']

