#define MAX_MEMORY_OFFSETS 1048576 // 1 MB for offsets
#define MAX_RECORDS_MEMORY 2097152 // 2 MB for records
#define OFFSET_THRESHOLD 10000
#define KEY_MAX_SIZE 50000
#define RECORD_INT_LIMIT 1000000
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 100

typedef struct {
    int value;
    long offset;
} record;

void log_warning(const char *message) {
    static bool warning_logged = false;
    if (!warning_logged || (time(NULL) % 10 == 0)) { // Delayed logging: logs every 10 seconds
        fprintf(stderr, "Warning: %s\n", message);
        warning_logged = true;
    }
}

int validate_and_insert_key(int key, int allowed_keys[], size_t num_allowed_keys, int keys[], size_t *size) {
    for (size_t i = 0; i < num_allowed_keys; ++i) {
        if (key == allowed_keys[i]) {
            for (size_t j = 0; j < *size; ++j) {
                if (keys[j] == key) return -1; // Key already exists
            }
            keys[(*size)++] = key;
            return 0;
        }
    }
    return -2; // Invalid key
}

int manage_memory(int allowed_keys[], size_t num_allowed_keys, int *error_code) {
    long *offsets = (long *)malloc(MAX_MEMORY_OFFSETS / sizeof(long));
    if (!offsets) { 
        *error_code = 1; 
        return -1;
    }

    int keys[KEY_MAX_SIZE];
    size_t key_count = 0;

    record *records = (record *)malloc(MAX_RECORDS_MEMORY / sizeof(record));
    if (!records) {
        free(offsets);
        *error_code = 2; 
        return -1;
    }

    srand(time(NULL));

    for (size_t i = 0; i < MAX_MEMORY_OFFSETS / sizeof(long); ++i) {
        offsets[i] = rand(); // Random offset generation

        if (i >= OFFSET_THRESHOLD) log_warning("Memory usage may become excessive.");
    }

    int key;
    for (int i = 0; i < KEY_MAX_SIZE; ++i) {
        key = allowed_keys[rand() % num_allowed_keys];
        if (validate_and_insert_key(key, allowed_keys, num_allowed_keys, keys, &key_count) != 0)
            break; // Stop on error
    }

    int sum_of_values = 0;
    size_t record_count = 0;

    while (record_count * sizeof(record) < MAX_RECORDS_MEMORY && sum_of_values <= RECORD_INT_LIMIT) {
        records[record_count].value = INT_RANGE_MIN + rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1);
        records[record_count].offset = record_count; // Unique offset based on index
        sum_of_values += records[record_count++].value;
    }

    *error_code = 0;
    return 0;
}

void cleanup(long *offsets, int keys[], size_t key_count, record *records) {
    free(offsets);
    free(records);

    // Assuming no dynamic allocation for keys in this context
}

int main() {
    int allowed_keys[] = {1, 2, 3, 4, 5}; // Example allowed keys
    size_t num_allowed_keys = sizeof(allowed_keys) / sizeof(allowed_keys[0]);
    int error_code;

    if (manage_memory(allowed_keys, num_allowed_keys, &error_code) != 0) {
        fprintf(stderr, "Error code: %d\n", error_code);
        return error_code;
    }

    // Cleanup after use
    cleanup(NULL, NULL, 0, NULL); // Actual pointers to be passed in real usage

    return 0;
}
