// Initialize records with dynamic memory allocation
record* init_records(size_t num_records, int min_value, int max_value) {
    if (num_records == 0 || min_value > max_value) return NULL;

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        log_operation("Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = rand(); // Generate a random offset
        records[i].key = i;         // Assign sequential keys
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    log_operation("Records initialized successfully.");
    return records;
}

// Free allocated memory for records
void free_records(record *records) {
    if (records) {
        free(records);
        log_operation("Memory freed.");
    }
}

// Update record values periodically
int update_record_values(record *records, size_t num_records, int min_value, int max_value) {
    if (!records || num_records == 0) return -1;

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    log_operation("Records updated.");
    return 0;
}

// Export record data to JSON format
char* export_to_json(const record *records, size_t num_records) {
    if (!records || num_records == 0) return NULL;

    size_t json_size = snprintf(NULL, 0, "[") + 1;
    for (size_t i = 0; i < num_records; ++i) {
        json_size += snprintf(NULL, 0, "{\"offset\":%ld,\"key\":%d,\"value\":%d}", records[i].offset, records[i].key, records[i].value);
        if (i < num_records - 1) json_size += 2; // For commas
    }
    json_size += 1; // Closing bracket

    char *json = malloc(json_size);
    if (!json) {
        log_operation("JSON allocation failed.");
        return NULL;
    }

    snprintf(json, json_size, "[");
    for (size_t i = 0; i < num_records; ++i) {
        snprintf(json + strlen(json), json_size - strlen(json), "{\"offset\":%ld,\"key\":%d,\"value\":%d}", records[i].offset, records[i].key, records[i].value);
        if (i < num_records - 1) strcat(json, ",");
    }
    strcat(json, "]");

    log_operation("Data exported to JSON.");
    return json;
}

// Logging function for operations
int log_operation(const char *message) {
    // Assume a logging framework is integrated here.
    printf("%s\n", message); // Placeholder for actual logging mechanism
    return 0;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    size_t num_records = 10000;
    int min_value = 1, max_value = 100;

    record *records = init_records(num_records, min_value, max_value);
    if (records) {
        update_record_values(records, num_records, min_value, max_value);

        char *json_data = export_to_json(records, num_records);
        if (json_data) {
            printf("%s\n", json_data);
            free(json_data);
        }

        free_records(records);
    }

    return 0;
}
