// Function to calculate ASCII sum of a string
int ascii_sum(const char *str) {
    int sum = 0;
    while (*str) {
        sum += (unsigned char)(*str++);
    }
    return sum;
}

// Modular function for filling struct's float field with weighted average based on ASCII sums
void initialize_struct_floats(CustomStruct* structs, double* doubles, char** strings, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        int str_ascii_sum = ascii_sum(strings[i]);
        structs[i].value = (float)(str_ascii_sum * doubles[i]); // Example weighted average calculation
    }
}

// Function to dynamically allocate and initialize arrays
int allocate_and_initialize(size_t num_elements, double** dbl_array, char*** str_array, CustomStruct*** struct_array) {
    if (!dbl_array || !str_array || !struct_array) return -1;

    *dbl_array = (double*)malloc(num_elements * sizeof(double));
    if (*dbl_array == NULL) {
        perror("Failed to allocate memory for double array");
        return -1;
