        free(*dbl_array);
        free(*str_array);
        return -1;
    }
    *str_array = str_array_ptrs;

    // Initialize strings array with example strings
    for (size_t i = 0; i < num_elements; ++i) {
        (*str_array)[i] = &((*str_array_ptrs)[i * 128]);
        snprintf((*str_array)[i], 128, "Example string %zu", i);
    }

    *struct_array = (CustomStruct**)malloc(num_elements * sizeof(CustomStruct*));
    if (*struct_array == NULL) {
        perror("Failed to allocate memory for struct array");
        free(*dbl_array);
        free(str_array_ptrs);
        return -1;
    }

    CustomStruct** structs_ptrs = (CustomStruct**)malloc(num_elements * sizeof(CustomStruct*) + num_elements * sizeof(CustomStruct));
    if (structs_ptrs == NULL) {
        perror("Failed to allocate memory for struct data");
        free(*dbl_array);
        free(str_array_ptrs);
        free(*struct_array);
        return -1;
    }
    *struct_array = structs_ptrs;

    // Initialize structs array
    for (size_t i = 0; i < num_elements; ++i) {
        (*structs_ptrs)[i].value = 0.0f;
        (*structs_ptrs)[i].str_ptr = (*str_array)[i];
        (*structs_ptrs)[i].index = i;
        (*struct_array)[i] = &((*structs_ptrs)[i]);
    }

    // Fill the float fields of structs with a weighted average based on ASCII sums
    initialize_struct_floats(*structs_ptrs, *dbl_array, *str_array, num_elements);

    return 0;
}

// Example usage and cleanup function
void free_allocated_resources(double* dbl_array, char** str_array, CustomStruct** struct_array, size_t num_elements) {
    free(dbl_array);
    free(str_array[0]); // Free the data block
    free(str_array);    // Free the array of pointers
    free(struct_array[0]); // Free the struct data block
    free(struct_array); // Free the array of pointers
}

int main() {
    size_t num_elements = 10;
    double* dbl_array = NULL;
    char** str_array = NULL;
    CustomStruct** structs_array = NULL;

    if (allocate_and_initialize(num_elements, &dbl_array, &str_array, &structs_array) == 0) {
