const { default: PQueue } = require('p-queue');
const pRetry = require('p-retry');

// Sample data for testing
const sampleData = [
  { value: 10, metadata: { flag: true, threshold: 5 }, dependency: { id: 1 } },
  { value: 20, metadata: { flag: false, threshold: 10 }, dependency: { id: 2 } },
  { value: 30, metadata: undefined, dependency: { id: 3 } },
  { value: 40, metadata: { flag: true, threshold: 15 }, dependency: { id: 4 } }
];

// Configuration
const MAX_RETRIES = 3;
const INITIAL_ACCUMULATOR_VALUE = 0;

// Helper function to get metadata with default values
function getMetadataWithDefaults(obj) {
  if (!obj.metadata) return { flag: false, threshold: 10 };
  return obj.metadata;
}

// Transformation logic for value
async function transformValue(value, multiplier) {
  // Simulate async processing
  await new Promise(resolve => setTimeout(resolve, 100));
  return value * multiplier;
}

// Callback to aggregate results
function aggregateResults(acc, value) {
  return acc + value;
}

// Function to process each object with retry logic
async function processObject(obj, multiplier, queue) {
  const { dependency } = obj;

  // Wait for dependencies to be processed (using Promise.all if needed)
  await queue.add(async () => {
    if (!dependency) throw new Error('Missing dependency');
    // Resolve dependencies here if necessary
  });

  try {
    return pRetry(
      async () => transformValue(obj.value, multiplier),
      { retries: MAX_RETRIES }
    );
  } catch (error) {
    console.error(`Failed to process object with id ${obj.dependency.id}:`, error);
    throw error;
  }
}

// Main function to run the processing pipeline
async function processPipeline(dataArray, transformMultiplier, initialAccumulator = INITIAL_ACCUMULATOR_VALUE) {
  const queue = new PQueue({ concurrency: 2 });
  let accumulator = initialAccumulator;

  for (const obj of dataArray) {
    const metadata = getMetadataWithDefaults(obj);

    if (!metadata.flag || obj.value < metadata.threshold) continue; // Filter based on criteria

    const transformedValue = await processObject(obj, transformMultiplier, queue);
    accumulator = aggregateResults(accumulator, transformedValue);
  }

  return accumulator;
}

// Execute the pipeline with sample data
processPipeline(sampleData, 2)
  .then(result => console.log('Aggregated Result:', result))
  .catch(error => console.error('Error processing pipeline:', error));
```"]

