    }

    return configs;
}

// Function to serialize config structures
void serialize_configs(const Config *configs, size_t count, unsigned char **output, size_t *output_size) {
    if (!configs || !count || !output || !output_size) return;

    size_t total_size = 0;
    for (size_t i = 0; i < count; ++i) {
        total_size += sizeof(double) + configs[i].length + 1; // Include null terminator
    }

    *output = malloc(total_size);
    if (!*output) {
        perror("Failed to allocate memory for serialization");
        return;
    }

    unsigned char *ptr = *output;
    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &configs[i].value, sizeof(double));
        ptr += sizeof(double);
        memcpy(ptr, configs[i].name, configs[i].length + 1); // Include null terminator
        ptr += configs[i].length + 1;
    }

    *output_size = total_size;
}

// Function to deserialize config structures
void deserialize_configs(const unsigned char *input, size_t input_size, Config **configs, size_t *count) {
    if (!input || !input_size || !configs || !count) return;

    *count = 0;
    const unsigned char *ptr = input;

    while (input_size >= sizeof(double)) {
        double value;
        memcpy(&value, ptr, sizeof(double));
        ptr += sizeof(double);

        size_t name_len = 0;
        while (input_size > 0 && *ptr != '\0') {
            ++name_len;
            ++ptr;
            --input_size;
        }

        if (input_size == 0) break;

        Config new_config;
        new_config.value = value;
        new_config.name = malloc(name_len + 1);
        memcpy(new_config.name, ptr - name_len, name_len + 1); // Include null terminator
        new_config.length = name_len;

        *configs = realloc(*configs, sizeof(Config) * (*count + 1));
        if (!*configs) {
            perror("Failed to allocate memory for deserialization");
            free(new_config.name);
            return;
        }

        (*configs)[*count++] = new_config;

        ptr += name_len + 1; // Move past the null terminator
        input_size -= (sizeof(double) + name_len + 1);
    }
}

