    printf("Enter numbers (Ctrl+D to end):\n");
    while (fgets(line, sizeof(line), stdin)) {
        if (capacity <= count) {
            capacity = capacity ? capacity * 2 : 4;
            numbers = realloc(numbers, capacity * sizeof(double));
            if (!numbers) {
                perror("Failed to allocate memory for numbers");
                break;
            }
        }

        char *endptr;
        double num = strtod(line, &endptr);
        if (line == endptr || errno == ERANGE) {
            fprintf(stderr, "Invalid input: %s", line);
            continue;
        }

        numbers[count++] = num;
        sum += num;
        if (num < min_value) {
            min_value = num;
        }
    }

    if (count > 0) {
        double average = sum / count;
        printf("Smallest value: %.2f\n", min_value);
        printf("Average value: %.2f\n", average);
    } else {
        printf("No valid numbers entered.\n");
