// Define the record structure
typedef struct {
    int value;
    long offset;
} Record;

// Function to allocate and initialize records
Record* create_records(size_t max_size, size_t count, int min_val, int max_val) {
    if (count * sizeof(Record) > max_size || count == 0) return NULL;

    Record* records = (Record*)malloc(max_size);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        records[i].offset = (long)i * sizeof(Record);
    }

    return records;
}

// Function to serialize data into a byte array
void serialize_records(const Record* records, size_t count, uint8_t** out_data, size_t* out_size, int is_big_endian) {
    if (!records || !out_data || !out_size) return;

    *out_size = count * sizeof(Record);
    *out_data = (uint8_t*)malloc(*out_size);
    if (!*out_data) {
        fprintf(stderr, "Memory allocation failed during serialization\n");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        uint32_t int_val = htobe32(records[i].value); // Convert to big-endian
        if (!is_big_endian) int_val = htole32(int_val); // Convert back if needed

        memcpy(*out_data + i * sizeof(Record), &int_val, sizeof(uint32_t));
        long offset = htobe64(records[i].offset);
        if (!is_big_endian) offset = htole64(offset);

        memcpy(*out_data + i * sizeof(Record) + sizeof(uint32_t), &offset, sizeof(long));
    }
}

// Function to deserialize data back into records
Record* deserialize_records(const uint8_t* data, size_t count, int is_big_endian) {
    if (!data || count == 0) return NULL;

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed during deserialization\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        uint32_t int_val;
        memcpy(&int_val, data + i * sizeof(Record), sizeof(uint32_t));
        if (!is_big_endian) int_val = le32toh(int_val);
        records[i].value = int_val;

        long offset;
        memcpy(&offset, data + i * sizeof(Record) + sizeof(uint32_t), sizeof(long));
        if (!is_big_endian) offset = le64toh(offset);
        records[i].offset = offset;
    }

    return records;
}

// Function to free allocated memory
void free_records(Record* records) {
    if (records) free(records);
}

