#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256

typedef struct {
    int value;
    char key[MAX_KEY_LENGTH];
    long offset;
} Record;

typedef struct {
    size_t record_count;
    size_t max_memory_budget;
    Record **records;
} RecordsManager;

// Thread-safe logging function
void log_message(const char *message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    FILE *logfile = fopen("memory_log.txt", "a");
    if (logfile != NULL) {
        fprintf(logfile, "%s\n", message);
        fclose(logfile);
    }
    pthread_mutex_unlock(&log_mutex);
}

// Function to check for integer overflow
int safe_add(int a, int b, int *result) {
    if ((b > 0) && (a > INT_MAX - b)) {
        log_message("Integer overflow detected");
        return -1;
    }
    if ((b < 0) && (a < INT_MIN - b)) {
        log_message("Integer underflow detected");
        return -1;
    }
    *result = a + b;
    return 0;
}

// Function to allocate and initialize records
RecordsManager* create_records(size_t record_count, size_t max_memory_budget) {
    RecordsManager *manager = malloc(sizeof(RecordsManager));
    if (manager == NULL) {
        log_message("Failed to allocate memory for RecordsManager");
        return NULL;
    }

    manager->record_count = 0;
    manager->max_memory_budget = max_memory_budget;
    manager->records = malloc(record_count * sizeof(Record*));

    if (manager->records == NULL) {
        free(manager);
        log_message("Failed to allocate memory for records array");
        return NULL;
    }

    // Start time measurement
    clock_t start_time = clock();

    size_t used_memory = 0;
    for (size_t i = 0; i < record_count && used_memory < max_memory_budget; ++i) {
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            log_message("Failed to allocate memory for a record");
            break;
        }

        // Initialize the record
        int value = rand() % 1000; // Example integer value generation
        snprintf(record->key, MAX_KEY_LENGTH, "key_%zu", i);
        record->offset = (long)i * 10;

        manager->records[i] = record;
        used_memory += sizeof(Record);

        if (!safe_add(manager->record_count, 1, &manager->record_count)) {
            log_message("Failed to update record count safely");
            break;
        }
    }

    // End time measurement
    clock_t end_time = clock();
    double time_taken = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    printf("Time taken: %.2f seconds\n", time_taken);
    printf("Average memory usage per record: %.2f bytes\n",
           manager->record_count > 0 ? (double)used_memory / manager->record_count : 0);

    return manager;
}

// Function to serialize records into a byte array
size_t serialize_records(const RecordsManager *manager, uint8_t **byte_array) {
    size_t total_size = sizeof(size_t); // For record count
    for (size_t i = 0; i < manager->record_count; ++i) {
        total_size += sizeof(manager->records[i]->value);
        total_size += strlen(manager->records[i]->key) + 1;
        total_size += sizeof(manager->records[i]->offset);
    }

    *byte_array = malloc(total_size);
    if (*byte_array == NULL) {
        log_message("Failed to allocate memory for serialization");
        return 0;
    }

    uint8_t *ptr = *byte_array;

    // Write record count
    memcpy(ptr, &manager->record_count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < manager->record_count; ++i) {
        Record *record = manager->records[i];

        // Serialize value
        int network_order_value;
        if (__BYTE_ORDER == __LITTLE_ENDIAN) {
            network_order_value = htonl(record->value);
        } else {
            network_order_value = record->value;
        }
        memcpy(ptr, &network_order_value, sizeof(int));
        ptr += sizeof(int);

        // Serialize key
        size_t key_length = strlen(record->key) + 1;
        memcpy(ptr, record->key, key_length);
        ptr += key_length;

        // Serialize offset
        long network_order_offset;
        if (__BYTE_ORDER == __LITTLE_ENDIAN) {
            network_order_offset = htobe64(record->offset);
        } else {
            network_order_offset = record->offset;
        }
        memcpy(ptr, &network_order_offset, sizeof(long));
        ptr += sizeof(long);
    }

    return total_size;
}

// Function to deserialize records from a byte array
RecordsManager* deserialize_records(const uint8_t *byte_array) {
    const size_t *record_count_ptr = (const size_t *)byte_array;
    size_t record_count = *record_count_ptr;
    byte_array += sizeof(size_t);

    RecordsManager *manager = create_records(record_count, 0);
    if (manager == NULL) return NULL;

    for (size_t i = 0; i < record_count; ++i) {
        Record *record = manager->records[i];

        // Deserialize value
        int network_order_value;
        memcpy(&network_order_value, byte_array, sizeof(int));
        byte_array += sizeof(int);
        if (__BYTE_ORDER == __LITTLE_ENDIAN) {
            record->value = ntohl(network_order_value);
        } else {
            record->value = network_order_value;
        }

        // Deserialize key
        char *key_ptr = (char *)byte_array;
        record->key[0] = '\0';
        while (*byte_array != '\0') {
            strncat(record->key, byte_array++, 1);
        }
        byte_array++;

        // Deserialize offset
        long network_order_offset;
        memcpy(&network_order_offset, byte_array, sizeof(long));
        byte_array += sizeof(long);
        if (__BYTE_ORDER == __LITTLE_ENDIAN) {
            record->offset = be64toh(network_order_offset);
        } else {
            record->offset = network_order_offset;
        }
    }

    return manager;
}

// Function to free all allocated memory
void free_records(RecordsManager *manager) {
    if (manager != NULL) {
        for (size_t i = 0; i < manager->record_count; ++i) {
            if (manager->records[i] != NULL) {
                free(manager->records[i]);
            }
        }
        free(manager->records);
        free(manager);
    }
}

int main() {
    size_t record_count = 100;
    size_t max_memory_budget = 1024 * 1024; // 1 MB

    RecordsManager *manager = create_records(record_count, max_memory_budget);
    if (manager == NULL) {
        log_message("Failed to create records");
        return EXIT_FAILURE;
    }

    uint8_t *serialized_data = NULL;
    size_t serialized_size = serialize_records(manager, &serialized_data);
    if (serialized_data == NULL || serialized_size == 0) {
        log_message("Serialization failed");
        free_records(manager);
        return EXIT_FAILURE;
    }

    RecordsManager *deserialized_manager = deserialize_records(serialized_data);
    if (deserialized_manager == NULL) {
        log_message("Deserialization failed");
        free(serialized_data);
        free_records(manager);
        return EXIT_FAILURE;
    }

    printf("Serialization and deserialization successful\n");

    free(serialized_data);
    free_records(manager);
    free_records(deserialized_manager);

    return EXIT_SUCCESS;
}
