#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <sys/time.h>

typedef struct {
    int value;
    long offset;
    unsigned long identifier;
    char *key;
    time_t timestamp;
} record;

unsigned long polynomial_rolling_hash(const char* str) {
    unsigned long hash = 0;
    const unsigned long p = 31;
    const unsigned long m = 1e9 + 9;
    for (int i = 0; str[i] != '\0'; i++) {
        hash = (hash * p + str[i]) % m;
    }
    return hash;
}

void log_error(const char* message) {
    FILE* log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

record* create_record(int value, long offset, const char* key, time_t timestamp, unsigned long identifier) {
    record* rec = malloc(sizeof(record));
    if (!rec) {
        log_error("Failed to allocate memory for record.");
        return NULL;
    }

    rec->value = value;
    rec->offset = offset;
    rec->key = strdup(key);
    if (!rec->key) {
        free(rec);
        log_error("Failed to duplicate key string.");
        return NULL;
    }
    rec->timestamp = timestamp;
    rec->identifier = identifier;

    return rec;
}

void serialize_record(const record* rec, uint8_t** buffer, size_t* size) {
    *buffer = malloc(sizeof(int) + sizeof(long) + sizeof(unsigned long) + strlen(rec->key) + 1 + sizeof(time_t));
    if (!(*buffer)) {
        log_error("Failed to allocate memory for serialization.");
        return;
    }

    uint8_t* ptr = *buffer;
    int value_net = htonl(rec->value);
    memcpy(ptr, &value_net, sizeof(int)); ptr += sizeof(int);

    long offset_net = htobe64(rec->offset);
    memcpy(ptr, &offset_net, sizeof(long)); ptr += sizeof(long);

    unsigned long id_net = htobe64(rec->identifier);
    memcpy(ptr, &id_net, sizeof(unsigned long)); ptr += sizeof(unsigned long);

    strcpy((char*)ptr, rec->key); ptr += strlen(rec->key) + 1;

    time_t ts_net = htonl(rec->timestamp);
    memcpy(ptr, &ts_net, sizeof(time_t));

    *size = ptr - *buffer;
}

void deserialize_record(const uint8_t* buffer, size_t size, record* rec) {
    const uint8_t* ptr = buffer;

    int value_net;
    memcpy(&value_net, ptr, sizeof(int)); ptr += sizeof(int);
    rec->value = ntohl(value_net);

    long offset_net;
    memcpy(&offset_net, ptr, sizeof(long)); ptr += sizeof(long);
    rec->offset = be64toh(offset_net);

    unsigned long id_net;
    memcpy(&id_net, ptr, sizeof(unsigned long)); ptr += sizeof(unsigned_long);
    rec->identifier = be64toh(id_net);

    char* key_end = (char*)ptr + size - ((const uint8_t*)rec->timestamp - buffer);
    strncpy(rec->key, (const char*)ptr, key_end - (const char*)ptr); 
    rec->key[key_end - (const char*)ptr] = '\0'; 
    ptr += strlen((const char*)ptr) + 1;

    time_t ts_net;
    memcpy(&ts_net, ptr, sizeof(time_t));
    rec->timestamp = ntohl(ts_net);
}

record** allocate_records(size_t count, size_t max_memory, int value_range, const char* prefix) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    record** records = malloc(count * sizeof(record*));
    if (!records) {
        log_error("Failed to allocate memory for records array.");
        return NULL;
    }

    struct timeval start_alloc, end_alloc;
    gettimeofday(&start_alloc, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);

        int value = rand() % value_range;
        long offset = rand();
        char key[256];
        snprintf(key, sizeof(key), "%s_%zu", prefix, i);

        time_t timestamp = time(NULL);
        unsigned long identifier = polynomial_rolling_hash(key);

        record* rec = create_record(value, offset, key, timestamp, identifier);
        if (!rec) {
            log_error("Failed to create record.");
            pthread_mutex_unlock(&lock);
            continue;
        }

        records[i] = rec;

        pthread_mutex_unlock(&lock);
    }

    gettimeofday(&end_alloc, NULL);

    double time_taken_alloc = (end_alloc.tv_sec - start_alloc.tv_sec) + 
                              (end_alloc.tv_usec - start_alloc.tv_usec) / 1e6;
    printf("Time taken to allocate records: %f seconds\n", time_taken_alloc);

    return records;
}

void free_records(record** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i]) {
            free(records[i]->key);
            free(records[i]);
        }
    }
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <num_records> <max_memory> <value_range>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_records = strtoul(argv[1], NULL, 10);
    size_t max_memory = strtoul(argv[2], NULL, 10);
    int value_range = atoi(argv[3]);

    record** records = allocate_records(num_records, max_memory, value_range, "record");
    if (!records) {
        return EXIT_FAILURE;
    }

    // Serialization example
    for (size_t i = 0; i < num_records; ++i) {
        uint8_t* buffer;
        size_t size;
        serialize_record(records[i], &buffer, &size);

        record deserialized_rec;
        deserialize_record(buffer, size, &deserialized_rec);

        // Check if the serialization-deserialization roundtrip is correct
        printf("Original: %d, Deserialized: %d\n", records[i]->value, deserialized_rec.value);

        free(buffer);  // Free serialized buffer after use
    }

    free_records(records, num_records);

    return EXIT_SUCCESS;
}
```

