import java.io.*;
import java.math.BigDecimal;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

// Transaction class definition
class Transaction {
    LocalDateTime timestamp;
    BigDecimal amount;
    List<String> categories;

    public Transaction(LocalDateTime timestamp, BigDecimal amount, List<String> categories) {
        this.timestamp = timestamp;
        this.amount = amount;
        this.categories = categories;
    }
}

// UserProfile class definition
class UserProfile {
    String userId;
    double[] values;
    Map<String, String> keyValuePairs;
    Collection<Transaction> transactions;

    public UserProfile(String userId, int arraySize) {
        this.userId = userId;
        this.values = new double[arraySize];
        this.keyValuePairs = new HashMap<>();
        this.transactions = new ArrayList<>();
    }

    // Serialize to binary format
    public byte[] serialize() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1024);  // Adjust size as necessary
        buffer.order(ByteOrder.LITTLE_ENDIAN);
        buffer.putInt(userId.length());
        for (char c : userId.toCharArray()) {
            buffer.put((byte) c);
        }

        buffer.putInt(values.length);
        for (double value : values) {
            buffer.putDouble(value);
        }

        buffer.putInt(keyValuePairs.size());
        for (Map.Entry<String, String> entry : keyValuePairs.entrySet()) {
            writeString(buffer, entry.getKey());
            writeString(buffer, entry.getValue());
        }

        buffer.putInt(transactions.size());
        for (Transaction transaction : transactions) {
            serializeTransaction(buffer, transaction);
        }

        return buffer.array();
    }

    private void serializeTransaction(ByteBuffer buffer, Transaction transaction) {
        writeLong(buffer, transaction.timestamp.toInstant().toEpochMilli());
        buffer.putDouble(transaction.amount.doubleValue());

        buffer.putInt(transaction.categories.size());
        for (String category : transaction.categories) {
            writeString(buffer, category);
        }
    }

    private static void writeString(ByteBuffer buffer, String str) {
        byte[] bytes = str.getBytes();
        buffer.putInt(bytes.length);
        buffer.put(bytes);
    }

    private static void writeLong(ByteBuffer buffer, long value) {
        for (int i = 0; i < Long.BYTES; i++) {
            buffer.put((byte) ((value >> (i * Byte.SIZE)) & 0xFF));
        }
    }

    // Deserialize from binary format
    public static UserProfile deserialize(byte[] data) throws IOException {
        ByteBuffer buffer = ByteBuffer.wrap(data);
        buffer.order(ByteOrder.LITTLE_ENDIAN);

        int userIdLength = buffer.getInt();
        char[] userIdChars = new char[userIdLength];
        for (int i = 0; i < userIdLength; i++) {
            userIdChars[i] = (char) buffer.get();
        }

        String userId = new String(userIdChars);
        UserProfile profile = new UserProfile(userId, 10); // Example size

        int valuesCount = buffer.getInt();
        for (int i = 0; i < valuesCount; i++) {
            profile.values[i] = buffer.getDouble();
        }

        int kvSize = buffer.getInt();
        for (int i = 0; i < kvSize; i++) {
            String key = readString(buffer);
            String value = readString(buffer);
            profile.keyValuePairs.put(key, value);
        }

        int transactionsCount = buffer.getInt();
        for (int i = 0; i < transactionsCount; i++) {
            Transaction transaction = deserializeTransaction(buffer);
            profile.transactions.add(transaction);
        }

        return profile;
    }

    private static Transaction deserializeTransaction(ByteBuffer buffer) throws IOException {
        long timestampMillis = readLong(buffer);
        BigDecimal amount = new BigDecimal(buffer.getDouble());
        int categoriesSize = buffer.getInt();

        List<String> categories = new ArrayList<>();
        for (int i = 0; i < categoriesSize; i++) {
            categories.add(readString(buffer));
        }

        return new Transaction(LocalDateTime.ofInstant(Instant.ofEpochMilli(timestampMillis), ZoneId.systemDefault()), amount, categories);
    }

    private static String readString(ByteBuffer buffer) throws IOException {
        int length = buffer.getInt();
        byte[] bytes = new byte[length];
        buffer.get(bytes);
        return new String(bytes);
    }

    private static long readLong(ByteBuffer buffer) {
        long value = 0;
        for (int i = 0; i < Long.BYTES; i++) {
            int shift = i * Byte.SIZE;
            value |= ((long) buffer.get() & 0xFFL) << shift;
        }
        return value;
    }

    // Free allocated memory
    public void freeResources() {
        values = null;
        keyValuePairs.clear();
        transactions.clear();
    }
}

// Function to generate financial report with concurrency and error handling
public class FinancialReportGenerator {

    private static final int DEFAULT_MAX_MEMORY_SIZE = 1024 * 1024; // 1 MB as default

    public static UserProfile createUserProfile(String userId, LocalDateTime startDate, LocalDateTime endDate,
                                                int maxMemorySize) {
        Random random = new SecureRandom();
        UserProfile profile = null;

        try (ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors())) {
            Semaphore semaphore = new Semaphore(maxMemorySize / 10000); // Example division factor

            CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
                try {
                    semaphore.acquire(); // Limit memory usage
                    profile = new UserProfile(userId, maxMemorySize / 10);

                    // Simulate data population and error handling
                    populateUserProfile(profile);

                    // Serialize to binary format
                    byte[] serializedData = profile.serialize();

                    // Deserialize back for integrity validation
                    UserProfile deserializedProfile = UserProfile.deserialize(serializedData);
                    if (!userId.equals(deserializedProfile.userId)) {
                        throw new IllegalStateException("Serialization failed");
                    }
                } catch (Exception e) {
                    System.err.println("Error in CompletableFuture: " + e.getMessage());
                } finally {
                    semaphore.release();
                }
            }, executor);

            future.get(); // Wait for completion

        } catch (Exception e) {
            System.err.println("Critical error: " + e.getMessage());
        }

        return profile;
    }

    private static void populateUserProfile(UserProfile profile) throws InterruptedException {
        Random random = new SecureRandom();

        // Initialize double values with checks against overflow
        for (int i = 0; i < profile.values.length; i++) {
            double value = random.nextDouble() * Math.pow(10, random.nextInt(7));
            if (!Double.isFinite(value)) {
                throw new ArithmeticException("Overflow detected");
            }
            profile.values[i] = value;
        }

        // Simulate adding transactions
        for (int i = 0; i < 5; i++) { // Example transaction count
            LocalDateTime timestamp = LocalDateTime.now().minusDays(random.nextInt(30));
            BigDecimal amount = BigDecimal.valueOf(random.nextDouble() * 100);
            List<String> categories = Arrays.asList("Food", "Transport", "Entertainment");

            Transaction transaction = new Transaction(timestamp, amount, categories);
            profile.transactions.add(transaction);
        }

        // Populate key-value pairs
        profile.keyValuePairs.put("Email", userId + "@example.com");
    }

    public static void main(String[] args) {
        UserProfile profile = createUserProfile("User123", LocalDateTime.now().minusDays(30), LocalDateTime.now(), DEFAULT_MAX_MEMORY_SIZE);

        if (profile != null) {
            try {
                byte[] serializedProfile = profile.serialize();
                System.out.println("Serialization successful.");

                // Deserialize and validate
                UserProfile deserializedProfile = UserProfile.deserialize(serializedProfile);
                assert profile.userId.equals(deserializedProfile.userId) : "Deserialization validation failed.";

            } catch (IOException e) {
                System.err.println("Serialization/Deserialization error: " + e.getMessage());
            } finally {
                if (profile != null) {
                    profile.freeResources(); // Free resources
                }
            }
        }
    }
}
