    }
}

// Error checking and logging helper
int safe_malloc(void **ptr, size_t size, const char *context) {
    *ptr = malloc(size);
    if (*ptr == NULL) {
        log_message("Memory allocation failed for: " context);
        return 0;
    }
    return 1;
}

RecordManager* create_record_manager(size_t max_memory_budget, size_t record_count) {
    RecordManager *manager = (RecordManager *)malloc(sizeof(RecordManager));
    if (!safe_malloc((void **)&manager->records, sizeof(Record*) * record_count, "records array")) {
        free(manager);
        return NULL;
    }

    manager->record_count = record_count;
    manager->max_memory_budget = max_memory_budget;
    pthread_mutex_init(&manager->lock, NULL);

    size_t used_memory = 0;
    for (size_t i = 0; i < record_count; ++i) {
        if (used_memory >= max_memory_budget) {
            log_message("Memory budget exceeded.");
            break;
        }

        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            log_message("Memory allocation failed for a record.");
            continue;
        }

        // Allocate key with some arbitrary length
        char *key = (char *)calloc(256, sizeof(char));
        if (!key) {
            free(record);
            log_message("Memory allocation failed for a key.");
            continue;
        }

        record->value = rand() % 1000; // Example value assignment
        strcpy(key, "ExampleKey");
        record->key = key;

        record->offset = rand();
        record->creation_time = time(NULL);
        record->last_accessed_time = record->creation_time;
        record->access_frequency = 0;

        manager->records[i] = record;
        used_memory += sizeof(Record) + strlen(key) + 1; // Approximate key size

        if (used_memory > max_memory_budget) {
            log_message("Memory budget exceeded after allocation.");
            break;
        }
    }

    return manager;
}

void free_record_manager(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->record_count && manager->records[i] != NULL; ++i) {
        free(manager->records[i]->key);
        free(manager->records[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void* serialize_record(Record *record, char **output_buffer) {
    size_t buffer_size = sizeof(int) + strlen(record->key) + 1 + sizeof(long) +
                         sizeof(time_t) + sizeof(unsigned int);
    *output_buffer = (char *)malloc(buffer_size);

    if (!(*output_buffer)) {
        log_message("Serialization memory allocation failed.");
        return NULL;
    }

    char *buffer_ptr = *output_buffer;
    // Serialize integer with endianness
    memcpy(buffer_ptr, &htons(record->value), sizeof(int));
    buffer_ptr += sizeof(int);

    strcpy(buffer_ptr, record->key);
    buffer_ptr += strlen(record->key) + 1;

    memcpy(buffer_ptr, &htonl((unsigned long)record->offset), sizeof(long));
    buffer_ptr += sizeof(long);

    memcpy(buffer_ptr, &htonl((unsigned long)record->creation_time), sizeof(time_t));
    buffer_ptr += sizeof(time_t);

    memcpy(buffer_ptr, &htons(record->access_frequency), sizeof(unsigned int));

    return *output_buffer;
}

void simulate_network_delay() {
    // Simulating random network delay
    struct timespec delay = { .tv_sec = 0, .tv_nsec = rand() % 1000000 };
    nanosleep(&delay, NULL);
}

// Example function to update records from an external source
void fetch_updates(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->record_count && manager->records[i] != NULL; ++i) {
        simulate_network_delay(); // Simulate delay

        // Fetch data here and update records
        Record *record = manager->records[i];
        record->value += rand() % 10;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example function to deserialize a byte array back into a record
Record* deserialize_record(const char *input_buffer) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        log_message("Deserialization memory allocation failed.");
        return NULL;
    }

    const char *buffer_ptr = input_buffer;

    // Deserialize integer with endianness
    int value;
    memcpy(&value, buffer_ptr, sizeof(int));
    record->value = ntohs(value);
    buffer_ptr += sizeof(int);

    size_t key_len = strlen(buffer_ptr) + 1;
    record->key = (char *)malloc(key_len);
    if (!record->key) {
        free(record);
        log_message("Memory allocation failed for deserialized key.");
        return NULL;
    }
    strcpy(record->key, buffer_ptr);
    buffer_ptr += key_len;

    long offset;
    memcpy(&offset, buffer_ptr, sizeof(long));
    record->offset = ntohl(offset);
    buffer_ptr += sizeof(long);

    time_t creation_time;
    memcpy(&creation_time, buffer_ptr, sizeof(time_t));
    record->creation_time = ntohl(creation_time);
    buffer_ptr += sizeof(time_t);

    unsigned int access_frequency;
    memcpy(&access_frequency, buffer_ptr, sizeof(unsigned int));
    record->access_frequency = ntohs(access_frequency);

    record->last_accessed_time = time(NULL); // Set to current time on deserialization

    return record;
}

int main() {
    size_t max_memory_budget = 1024 * 1024; // 1 MB
    size_t record_count = 100;

    RecordManager *manager = create_record_manager(max_memory_budget, record_count);
    if (!manager) {
        log_message("Failed to create record manager.");
        return EXIT_FAILURE;
    }

    char *serialized_data;
    for (size_t i = 0; i < manager->record_count && manager->records[i] != NULL; ++i) {
        serialized_data = serialize_record(manager->records[i], &serialized_data);
        if (!serialized_data) {
            log_message("Serialization failed for record " _SIZET_FORMAT ".");
        }
    }

    fetch_updates(manager);

    free_record_manager(manager);

    return EXIT_SUCCESS;
}
``` 

This code provides a basic framework that meets the requirements described, including handling memory allocation with error logging, concurrency management using mutexes, serialization/deserialization considering endianness, network delay simulation, and updating records from an external source. It also ensures graceful failure in case of errors during memory operations or serialization processes.']

