#define MAX_CONFIGS 1000

typedef struct {
    float value;
    char *name;
    size_t name_len;
} Config;

typedef struct {
    Config configs[MAX_CONFIGS];
    int count;
    size_t memory_limit;
    bool initialized;
} ConfigManager;

static unsigned long get_seed() {
    return (unsigned long)time(NULL);
}

void initialize_rng(unsigned long seed) {
    srand(seed);
}

float generate_random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

bool is_duplicate(ConfigManager *manager, const char *name, size_t name_len) {
    for (int i = 0; i < manager->count; ++i) {
        if (manager->configs[i].name_len == name_len &&
            strncmp(manager->configs[i].name, name, name_len) == 0) {
            return true;
        }
    }
    return false;
}

bool add_config(ConfigManager *manager, const char *name, float value) {
    size_t name_len = strlen(name);
    if (is_duplicate(manager, name, name_len)) {
        fprintf(stderr, "Duplicate configuration detected.\n");
        return false;
    }

    size_t required_memory = sizeof(Config) + name_len + 1; // Include null terminator
    if ((manager->count * sizeof(Config) + manager->memory_limit - required_memory) < 0) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return false;
    }

    Config *config = &manager->configs[manager->count++];
    config->value = value;
    config->name = (char *)malloc(name_len + 1);
    if (!config->name) {
        fprintf(stderr, "Memory allocation failed.\n");
        --manager->count; // Rollback count
        return false;
    }
    strncpy(config->name, name, name_len);
    config->name[name_len] = '\0';
    config->name_len = name_len;

    return true;
}

Config *get_config(ConfigManager *manager, const char *name) {
    size_t name_len = strlen(name);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->configs[i].name_len == name_len &&
            strncmp(manager->configs[i].name, name, name_len) == 0) {
            return &manager->configs[i];
        }
    }
    return NULL;
}

void initialize_config_manager(ConfigManager *manager, size_t memory_limit) {
    manager->count = 0;
    manager->memory_limit = memory_limit;
    manager->initialized = true;
    for (int i = 0; i < MAX_CONFIGS; ++i) {
        manager->configs[i].value = 0.0f;
        manager->configs[i].name = NULL;
        manager->configs[i].name_len = 0;
    }
}

void free_config_manager(ConfigManager *manager) {
    for (int i = 0; i < manager->count; ++i) {
        free(manager->configs[i].name);
    }
    manager->initialized = false;
}

// Example helper function to read floating-point numbers from standard input
void read_floats_from_input(float **float_array, int *size) {
    int capacity = 10;
    *float_array = malloc(capacity * sizeof(float));
    if (!*float_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    *size = 0;
    float value;
    printf("Enter floating-point numbers (Ctrl+D to end):\n");
    while (scanf("%f", &value) == 1) {
        if (*size >= capacity) {
            capacity *= 2;
            *float_array = realloc(*float_array, capacity * sizeof(float));
            if (!*float_array) {
                fprintf(stderr, "Memory allocation failed.\n");
                exit(EXIT_FAILURE);
            }
        }
        (*float_array)[*size++] = value;
    }
}

int main() {
    ConfigManager manager;
    initialize_config_manager(&manager, 1024 * 1024); // 1 MB memory limit

    unsigned long seed = get_seed();
    initialize_rng(seed);

    add_config(&manager, "config1", generate_random_float(0.0f, 100.0f));
    Config *config = get_config(&manager, "config1");
    if (config) {
        printf("Config found: %s with value %.2f\n", config->name, config->value);
    }

    free_config_manager(&manager);

    float *float_array;
    int size;
    read_floats_from_input(&float_array, &size);

    for (int i = 0; i < size; ++i) {
        printf("Read value: %.2f\n", float_array[i]);
    }

    free(float_array);
    return 0;
}
