MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->total_size = size;
    pool->memory_start = malloc(size);
    if (!pool->memory_start) {
        free(pool);
        return NULL;
    }
    return pool;
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    // Simple first-fit allocation for demonstration purposes
    static void *current_position = NULL;
    if (size > pool->total_size || !current_position) {
        current_position = pool->memory_start;
    }

    void *allocated_memory = current_position;
    current_position += size;

    if ((char*)current_position - (char*)pool->memory_start + size > pool->total_size) {
        return NULL; // Out of memory
    }

    return allocated_memory;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory_start);
    free(pool);
}

// Initialize the library context with a memory limit
int initialize_library(LibraryContext *context, size_t memory_limit) {
    if (!context || memory_limit == 0) return MEMORY_ERROR;

    MemoryPool *pool = create_memory_pool(memory_limit);
    if (!pool) return MEMORY_ERROR;

    context->memory_pool = pool;
    context->memory_limit = memory_limit;
    context->protocols = NULL;
    context->protocol_count = 0;

    // Set up other resources, locks etc.

    return MEMORY_OK;
}

// Clean-up function for library
void finalize_library(LibraryContext *context) {
    if (!context) return;

    free_memory_pool((MemoryPool*)context->memory_pool);
    // Free any loaded protocols and additional resources
}

// Create a message using the specified protocol
Message* create_message(const char *data, Protocol *protocol) {
    Message *msg = (Message *)allocate_from_pool((MemoryPool*)context->memory_pool, sizeof(Message));
    if (!msg) return NULL;

    msg->buffer_size = strlen(data) + 1;
    msg->buffer = (char *)allocate_from_pool((MemoryPool*)context->memory_pool, msg->buffer_size);
    if (!msg->buffer) {
        free(msg); // Handle memory clean-up
        return NULL;
    }

    strncpy(msg->buffer, data, msg->buffer_size);
    msg->timestamp = time(NULL);
    msg->ack_flag = false;

    protocol->parse(data, msg);

    return msg;
}

// Free a message and its resources
