    pthread_mutex_t *mutex = (pthread_mutex_t*)*lock;
    int res = pthread_mutex_lock(mutex);
    if (res != 0) return THREAD_ERROR; // Error handling
    return MEMORY_OK;
}

void release_lock(void *lock) {
    pthread_mutex_unlock((pthread_mutex_t*)lock);
}

