#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

#define MAX_SOCKETS 10000
#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit in bytes
#define SOCKET_AGE_THRESHOLD 300 // Age threshold in seconds

typedef struct {
    int fd;
    pthread_mutex_t lock;
    time_t last_accessed;
    unsigned char state; // Customizable states
    long stats_metric;
} NetworkSocket;

typedef struct {
    int seq_number;
    long timestamp;
    size_t payload_size;
    char *payload;
} Packet;

typedef struct SocketPool {
    NetworkSocket *sockets[MAX_SOCKETS];
    pthread_mutex_t pool_lock;
    size_t count;
    size_t memory_usage;
} SocketPool;

typedef struct {
    Packet **packets;
    size_t max_packets;
    pthread_rwlock_t packets_lock;
    size_t current_count;
} PacketArray;

// Function prototypes
SocketPool* create_socket_pool();
void destroy_socket_pool(SocketPool *pool);
NetworkSocket* acquire_socket(SocketPool *pool, int protocol_type);
void release_socket(SocketPool *pool, NetworkSocket *socket);
char* serialize_socket_pool(SocketPool *pool, size_t *size);
int deserialize_socket_pool(char *data, SocketPool *pool, size_t size);
PacketArray* create_packet_array(size_t max_packets);
void destroy_packet_array(PacketArray *array);
Packet* allocate_packet(PacketArray *array);

// Implementations
SocketPool* create_socket_pool() {
    SocketPool *pool = malloc(sizeof(SocketPool));
    if (!pool) return NULL;

    memset(pool, 0, sizeof(SocketPool));
    pthread_mutex_init(&pool->pool_lock, NULL);

    for (size_t i = 0; i < MAX_SOCKETS; ++i) {
        pool->sockets[i] = NULL;
    }

    return pool;
}

void destroy_socket_pool(SocketPool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->pool_lock);
    for (size_t i = 0; i < MAX_SOCKETS; ++i) {
        if (pool->sockets[i]) {
            close(pool->sockets[i]->fd);
            pthread_mutex_destroy(&pool->sockets[i]->lock);
            free(pool->sockets[i]);
        }
    }
    pthread_mutex_unlock(&pool->pool_lock);

    pthread_mutex_destroy(&pool->pool_lock);
    free(pool);
}

NetworkSocket* acquire_socket(SocketPool *pool, int protocol_type) {
    pthread_mutex_lock(&pool->pool_lock);

    for (size_t i = 0; i < MAX_SOCKETS; ++i) {
        NetworkSocket *socket = pool->sockets[i];
        if (!socket || difftime(time(NULL), socket->last_accessed) > SOCKET_AGE_THRESHOLD) {
            // Create or reuse a socket
            int fd = create_socket(protocol_type); // Placeholder for actual socket creation logic
            if (fd < 0) {
                pthread_mutex_unlock(&pool->pool_lock);
                return NULL;
            }

            socket = malloc(sizeof(NetworkSocket));
            if (!socket) {
                close(fd);
                pthread_mutex_unlock(&pool->pool_lock);
                return NULL;
            }

            memset(socket, 0, sizeof(NetworkSocket));
            pthread_mutex_init(&socket->lock, NULL);

