#define MAX_SOCKETS 10000
#define MAX_MEMORY_USAGE 1024 * 1024 * 10 // Example: 10 MB limit

typedef enum {
    SOCKET_OPEN,
    SOCKET_CLOSED,
    SOCKET_BUSY,
    SOCKET_ERROR,
