    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock; // Read-write lock for thread safety
} PacketArray;

SocketPool *create_socket_pool(size_t max_memory) {
    SocketPool *pool = (SocketPool *)malloc(sizeof(SocketPool));
    if (!pool) return NULL;

    memset(pool, 0, sizeof(SocketPool));
    pool->max_memory_limit = max_memory;
    pthread_mutex_init(&pool->pool_lock, NULL);
    pthread_cond_init(&pool->cond_var, NULL);

    for (int i = 0; i < MAX_SOCKETS; ++i) {
        Socket *socket = (Socket *)malloc(sizeof(Socket));
        if (!socket) {
            free_socket_pool(pool);
            return NULL;
        }
        socket->socket_fd = -1; // Invalid FD
        pthread_mutex_init(&socket->lock, NULL);
        pool->sockets[i] = socket;
    }

    return pool;
}

void free_socket_pool(SocketPool *pool) {
    if (!pool) return;

    for (int i = 0; i < MAX_SOCKETS; ++i) {
        Socket *socket = pool->sockets[i];
        pthread_mutex_destroy(&socket->lock);
        free(socket);
    }

    pthread_mutex_destroy(&pool->pool_lock);
    pthread_cond_destroy(&pool->cond_var);
    free(pool);
}

PacketArray *create_packet_array(size_t capacity, size_t max_memory) {
    PacketArray *array = (PacketArray *)malloc(sizeof(PacketArray));
    if (!array) return NULL;

    array->packets = (Packet **)calloc(capacity, sizeof(Packet *));
    if (!array->packets) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = capacity;
    pthread_rwlock_init(&array->rwlock, NULL);

    return array;
}

void free_packet_array(PacketArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        Packet *packet = array->packets[i];
        free(packet->payload_data);
        free(packet);
    }
    free(array->packets);

    pthread_rwlock_destroy(&array->rwlock);
    free(array);
}

void serialize_socket(Socket *socket, unsigned char **buffer, size_t *size) {
    if (!socket || !buffer || !size) return;

    // Example serialization logic
    unsigned int status = htobe32(socket->status); // Convert to big-endian
    unsigned long last_accessed = htobe64(socket->last_accessed);
    unsigned int packets_sent = htobe32(socket->packets_sent);
    unsigned int packets_received = htobe32(socket->packets_received);

    *size = sizeof(status) + sizeof(last_accessed) + sizeof(packets_sent) + sizeof(packets_received);
    *buffer = (unsigned char *)malloc(*size);
    if (!*buffer) return;

    memcpy(*buffer, &status, sizeof(status));
    memcpy(*buffer + sizeof(status), &last_accessed, sizeof(last_accessed));
    memcpy(*buffer + sizeof(status) + sizeof(last_accessed), &packets_sent, sizeof(packets_sent));
    memcpy(*buffer + *size - sizeof(packets_received), &packets_received, sizeof(packets_received));
}

void deserialize_socket(Socket *socket, unsigned char *buffer, size_t size) {
    if (!socket || !buffer || size < (4 * 3 + 4)) return;

    // Example deserialization logic
    unsigned int status;
    memcpy(&status, buffer, sizeof(status));
    socket->status = be32toh(status); // Convert from big-endian

    unsigned long last_accessed;
    memcpy(&last_accessed, buffer + sizeof(status), sizeof(last_accessed));
    socket->last_accessed = be64toh(last_accessed);

    unsigned int packets_sent;
    memcpy(&packets_sent, buffer + sizeof(status) + sizeof(last_accessed), sizeof(packets_sent));
    socket->packets_sent = be32toh(packets_sent);

    unsigned int packets_received;
    memcpy(&packets_received, buffer + size - sizeof(packets_received), sizeof(packets_received));
    socket->packets_received = be32toh(packets_received);
}

void manage_socket_pool(SocketPool *pool) {
    if (!pool) return;

    // Example logic to manage sockets
    pthread_mutex_lock(&pool->pool_lock);

    for (int i = 0; i < MAX_SOCKETS; ++i) {
        Socket *socket = pool->sockets[i];
        pthread_mutex_lock(&socket->lock);

        if (socket->status == SOCKET_CLOSED || socket->last_accessed + 3600 < time(NULL)) { // Example age threshold
            // Close and reset the socket
            close(socket->socket_fd);
            socket->socket_fd = -1;
            socket->status = SOCKET_CLOSED;
            socket->packets_sent = 0;
            socket->packets_received = 0;

            pthread_mutex_unlock(&socket->lock);
        } else {
            // Update last accessed time
            socket->last_accessed = time(NULL);
            pthread_mutex_unlock(&socket->lock);
        }
    }

    pthread_mutex_unlock(&pool->pool_lock);
}

void log_event(const char *event) {
    printf("[%ld] %s\n", time(NULL), event);
}

// Example function to handle concurrent network operations
