#include <stdint.h>

typedef enum {
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} severity;

#define MAX_LOG_MESSAGE_SIZE 256
#define UNIQUE_ID_RANGE 1000000

typedef struct {
    time_t timestamp;
    char message[MAX_LOG_MESSAGE_SIZE];
    severity level;
    unsigned long id;
} log_entry;

// Function to hash a given log entry ID
uint32_t hash_log_id(unsigned long log_id) {
    uint32_t hash = 5381;
    for (int i = 0; i < sizeof(log_id); ++i) {
        hash = ((hash << 5) + hash) + ((log_id >> (i * 8)) & 0xFF);
    }
    return hash;
}

// Helper function to generate a random log message
void generate_random_log_message(char* buffer, size_t length) {
    const char* vocabulary[] = {"INFO", "WARNING", "ERROR", "CRITICAL", "STARTUP", "SHUTDOWN"};
    int vocab_size = sizeof(vocabulary) / sizeof(vocabulary[0]);

    for (size_t i = 0; i < length - 1; ++i) {
        buffer[i] = vocabulary[rand() % vocab_size][rand() % strlen(vocabulary[rand() % vocab_size])];
    }
    buffer[length - 1] = '\0';
}

// Function to dynamically allocate and initialize log entries
log_entry* create_log_entries(size_t count, size_t max_memory_size, int* result) {
    srand((unsigned int)time(NULL));

    if (count * sizeof(log_entry) > max_memory_size) {
        *result = -1;
        return NULL;
    }

    log_entry* entries = malloc(count * sizeof(log_entry));
    if (!entries) {
        *result = -2;
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        entries[i].timestamp = time(NULL);
        generate_random_log_message(entries[i].message, MAX_LOG_MESSAGE_SIZE);
        entries[i].level = rand() % 4;

        unsigned long id = (rand() % UNIQUE_ID_RANGE) + 1;
        while (id > UNIQUE_ID_RANGE) { // Ensure ID is within range
            id %= UNIQUE_ID_RANGE;
        }
        entries[i].id = id;
    }

    *result = 0;
    return entries;
}

// Function to serialize log entry data into a byte array
size_t serialize_log_entries(log_entry* entries, size_t count, uint8_t** serialized_data) {
    size_t total_size = sizeof(size_t); // For storing the number of entries

    for (size_t i = 0; i < count; ++i) {
        total_size += sizeof(entries[i].timestamp);
        total_size += strlen(entries[i].message) + 1;
        total_size += sizeof(entries[i].level);
        total_size += sizeof(entries[i].id);
    }

    *serialized_data = malloc(total_size);
    if (!*serialized_data) return 0;

    uint8_t* ptr = *serialized_data;
    memcpy(ptr, &count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &entries[i].timestamp, sizeof(entries[i].timestamp));
        ptr += sizeof(entries[i].timestamp);

        size_t message_len = strlen(entries[i].message) + 1;
        memcpy(ptr, entries[i].message, message_len);
        ptr += message_len;

        memcpy(ptr, &entries[i].level, sizeof(entries[i].level));
        ptr += sizeof(entries[i].level);

        memcpy(ptr, &entries[i].id, sizeof(entries[i].id));
        ptr += sizeof(entries[i].id);
    }

    return total_size;
}

// Function to free allocated memory
void free_log_entries(log_entry* entries) {
    if (entries) free(entries);
}

// Helper function to find and print the longest log message from standard input
void print_longest_log_message() {
    char buffer[MAX_LOG_MESSAGE_SIZE];
    size_t max_length = 0;
    char* longest_message = NULL;

    printf("Enter log messages, type 'END' to finish:\n");

    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (strncmp(buffer, "END\n", 4) == 0) break;

        size_t length = strlen(buffer);
        if (length > max_length) {
            max_length = length;
            longest_message = strdup(buffer);
        }
    }

    if (longest_message) {
        printf("Longest log message: %s\n", longest_message);
        free(longest_message);
    } else {
        printf("No valid messages were entered.\n");
    }
}

int main() {
    int result;
    size_t max_memory_size = 1024 * 1024; // Example maximum memory limit
    log_entry* entries = create_log_entries(100, max_memory_size, &result);

    if (result == 0) {
        printf("Log entries created successfully.\n");

        uint8_t* serialized_data;
        size_t serialized_size = serialize_log_entries(entries, 100, &serialized_data);
        if (serialized_size > 0) {
            printf("Log entries serialized. Size: %zu bytes\n", serialized_size);

            // Example of freeing the serialized data
            free(serialized_data);
        }

        free_log_entries(entries);
    } else {
        fprintf(stderr, "Error creating log entries: %d\n", result);
    }

    print_longest_log_message();

    return 0;
}
