#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
    long offset;
} Record;

// Global variables
#define MAX_MEMORY 1024 * 1024 // Example max size in bytes, can be adjusted
static char* memory_pool = NULL;
static size_t memory_used = 0;
pthread_mutex_t memory_lock;

// Function prototypes
int initialize_records(Record** records, int count, int min_val, int max_val, unsigned int seed);
void free_resources(Record** records, int count);
void read_integers_and_find_largest();
char* generate_random_string(size_t length, const char* charset, unsigned int seed);
void serialize_data(const Record* records, int count, FILE* file);
void deserialize_data(Record** records, int* count, FILE* file);

// Initialize random number generator
void seed_rng(unsigned int seed) {
    srand(seed);
}

// Generate a random integer within range [min_val, max_val]
int random_int(int min_val, int max_val) {
    return rand() % (max_val - min_val + 1) + min_val;
}

// Allocate and initialize records
int initialize_records(Record** records, int count, int min_val, int max_val, unsigned int seed) {
    if (!records || !memory_pool) return -1;

    size_t record_size = sizeof(Record);
    if (record_size * count > MAX_MEMORY) return -1;

    pthread_mutex_lock(&memory_lock);

    *records = (Record*)malloc(record_size * count);
    if (*records == NULL) {
        pthread_mutex_unlock(&memory_lock);
        return -1;
    }

    memory_used += record_size * count;

    seed_rng(seed);
    for (int i = 0; i < count; ++i) {
        (*records)[i].value = random_int(min_val, max_val);
        // Initialize offset as needed
    }

    pthread_mutex_unlock(&memory_lock);

    return 0;
}

// Free allocated resources
void free_resources(Record** records, int count) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
    memory_used = 0;
}

// Read integers from stdin and find the largest
void read_integers_and_find_largest() {
    int n, max_val = INT_MIN;
    while (scanf("%d", &n) == 1) {
        if (n > max_val) {
            max_val = n;
        }
    }
    printf("Largest integer: %d\n", max_val);
}

// Generate a random string of specified length
char* generate_random_string(size_t length, const char* charset, unsigned int seed) {
    size_t charset_length = strlen(charset);
    char* result = (char*)malloc(length + 1);
    if (!result) return NULL;

    seed_rng(seed);

    for (size_t i = 0; i < length; ++i) {
        result[i] = charset[rand() % charset_length];
    }
    result[length] = '\0';

    return result;
}

// Serialize data to a binary file
void serialize_data(const Record* records, int count, FILE* file) {
    if (!records || !file) return;

    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; ++i) {
        // Handle endianness and data integrity
        uint32_t value_net = htonl(records[i].value);
        uint64_t offset_net = htonll(records[i].offset);

        fwrite(&value_net, sizeof(uint32_t), 1, file);
        fwrite(&offset_net, sizeof(uint64_t), 1, file);
    }
}

// Deserialize data from a binary file
void deserialize_data(Record** records, int* count, FILE* file) {
    if (!records || !file) return;

    fread(count, sizeof(int), 1, file);

    *records = (Record*)malloc(sizeof(Record) * (*count));
    for (int i = 0; i < *count; ++i) {
        uint32_t value_net;
        uint64_t offset_net;

        fread(&value_net, sizeof(uint32_t), 1, file);
        fread(&offset_net, sizeof(uint64_t), 1, file);

        (*records)[i].value = ntohl(value_net);
        (*records)[i].offset = htonll(offset_net);
    }
}

// Convert host to network long-long (big-endian)
uint64_t htonll(uint64_t value) {
    static const int num = 42;
    if (*(const char*)&num == 42) { // Little endian
        return ((uint64_t)htonl(value & 0xFFFFFFFFULL)) << 32 | htonl(value >> 32);
    } else { // Big endian
        return value;
    }
}

// Convert network to host long-long (big-endian)
uint64_t ntohll(uint64_t value) {
    return htonll(value); // Symmetric operation
}

int main() {
    pthread_mutex_init(&memory_lock, NULL);

    Record* records = NULL;
    if (initialize_records(&records, 100, 0, 100, 12345) == 0) {
        FILE* file = fopen("data.bin", "wb");
        serialize_data(records, 100, file);
        fclose(file);

        int count;
        file = fopen("data.bin", "rb");
        deserialize_data(&records, &count, file);
        fclose(file);

        free_resources(&records, count);
    }

    pthread_mutex_destroy(&memory_lock);
    return 0;
}
