#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
} Record;

void initializeRandomSeed() {
    srand((unsigned) time(NULL));
}

int generateRandomInt(int min, int max) {
    if (min > max) return -1; // Error case
    return rand() % (max - min + 1) + min;
}

char* serializeRecords(Record *records, size_t recordCount, size_t *size) {
    char *buffer = malloc(recordCount * sizeof(int) + recordCount * sizeof(long));
    if (!buffer) return NULL;

    for (size_t i = 0; i < recordCount; ++i) {
        int key = htobe32(records[i].key);
        long offset = htobe64(records[i].offset);

        memcpy(buffer + i * (sizeof(int) + sizeof(long)), &key, sizeof(int));
        memcpy(buffer + i * (sizeof(int) + sizeof(long)) + sizeof(int), &offset, sizeof(long));
    }

    *size = recordCount * (sizeof(int) + sizeof(long));
    return buffer;
}

Record* deserializeRecords(const char *buffer, size_t recordCount, size_t *size) {
    if (!buffer || recordCount == 0) return NULL;

    *size = recordCount * (sizeof(int) + sizeof(long));
    Record *records = malloc(recordCount * sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < recordCount; ++i) {
        int key;
        long offset;

        memcpy(&key, buffer + i * (sizeof(int) + sizeof(long)), sizeof(int));
        key = be32toh(key);

        memcpy(&offset, buffer + i * (sizeof(int) + sizeof(long)) + sizeof(int), sizeof(long));
        offset = be64toh(offset);

        records[i].key = key;
        records[i].offset = offset;
    }

    return records;
}

void freeRecords(Record **records) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
}

Record* manageMemory(size_t maxBytes, int minKey, int maxKey, long rangeOffset) {
    size_t recordSize = sizeof(int) + sizeof(long);
    size_t recordCount = maxBytes / recordSize;

    Record *records = malloc(recordCount * recordSize);
    if (!records) return NULL;

    for (size_t i = 0; i < recordCount; ++i) {
        records[i].key = generateRandomInt(minKey, maxKey);
        if (records[i].key == -1) {
            freeRecords(&records);
            return NULL;
        }
        records[i].offset = rand() % rangeOffset;
    }

    return records;
}
