<?php

function handleUserRequest($postData) {
    $dbConnection = new mysqli("localhost", "user", "password", "database");

    if ($dbConnection->connect_error) {
        return json_encode(['error' => 'Database connection failed']);
    }

    $response = ['message' => 'success'];

    // Input validation
    if (empty($postData['name']) || empty($postData['email']) || empty($postData['password'])) {
        return json_encode(['error' => 'Invalid input data']);
    }

    $name = $dbConnection->real_escape_string(trim($postData['name']));
    $email = $dbConnection->real_escape_string(trim($postData['email']));
    $password = password_hash($dbConnection->real_escape_string(trim($postData['password'])), PASSWORD_BCRYPT);

    if (isset($postData['id']) && is_numeric($postData['id'])) {
        // Update user
        $userId = intval($postData['id']);
        $stmt = $dbConnection->prepare("UPDATE users SET name=?, email=?, password=? WHERE id=?");
        $stmt->bind_param('sssi', $name, $email, $password, $userId);
    } else {
        // Create new user
        $stmt = $dbConnection->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
        $stmt->bind_param('sss', $name, $email, $password);
    }

    if (!$stmt || !$stmt->execute()) {
        return json_encode(['error' => 'Database operation failed']);
    }

    // Handle deletion
    if (isset($postData['delete']) && $postData['delete'] === true) {
        $userId = intval($postData['id']);
        $stmt = $dbConnection->prepare("DELETE FROM users WHERE id=?");
        $stmt->bind_param('i', $userId);

        if (!$stmt || !$stmt->execute()) {
            return json_encode(['error' => 'Deletion operation failed']);
        }
    }

    $stmt->close();
    $dbConnection->close();

    return json_encode($response);
}
