        exit(EXIT_FAILURE);
    }
    log_event("Initialized hash table.");
}

void insert_into_hash_table(int key, record *rec) {
    unsigned long index = hash_function(key);

    pthread_mutex_lock(&hash_table_lock);
    HashTableEntry *entry = create_hash_table_entry(key, rec);

    if (!entry) {
        free(rec);
        return;
    }

    entry->next = hash_table[index];
    hash_table[index] = entry;

    pthread_mutex_unlock(&hash_table_lock);
}

void free_resources(size_t num_entries) {
