#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record **records;
    void **key_index;
    void **hash_table;
    unsigned (*hash_function)(int);
} MemoryManager;

unsigned simple_hash(int key) {
    return (unsigned)key; // Simple modulus-based hash function, replace with a better one if necessary
}

MemoryManager* init_memory_manager(size_t initial_capacity, unsigned (*hash_fn)(int)) {
    MemoryManager *mm = malloc(sizeof(MemoryManager));
    mm->capacity = initial_capacity;
    mm->count = 0;
    mm->records = calloc(mm->capacity, sizeof(Record*));
    mm->key_index = calloc(initial_capacity, sizeof(void*));
    mm->hash_table = calloc(mm->capacity, sizeof(void*));
    mm->hash_function = hash_fn;

    return mm;
}

void resize_memory_manager(MemoryManager *mm) {
    size_t new_capacity = mm->capacity * 2;

    Record **new_records = realloc(mm->records, new_capacity * sizeof(Record*));
    if (!new_records) return; // Handle allocation failure
    memset(new_records + mm->capacity, 0, mm->capacity * sizeof(Record*));

    void **new_key_index = realloc(mm->key_index, new_capacity * sizeof(void*));
    if (!new_key_index) return; // Handle allocation failure

    void **new_hash_table = realloc(mm->hash_table, new_capacity * sizeof(void*));
    if (!new_hash_table) return; // Handle allocation failure
    memset(new_hash_table + mm->capacity, 0, mm->capacity * sizeof(void*));

    mm->records = new_records;
    mm->key_index = new_key_index;
    mm->hash_table = new_hash_table;
    mm->capacity = new_capacity;
}

void insert_record(MemoryManager *mm, Record *record) {
    if (mm->count == mm->capacity) {
        resize_memory_manager(mm);
    }

    unsigned index = mm->hash_function(record->key) % mm->capacity;

    while (mm->hash_table[index] != NULL) {
        index = (index + 1) % mm->capacity; // Open addressing with linear probing
    }

    mm->hash_table[index] = record;
    mm->records[mm->count++] = record;
    mm->key_index[record->key] = record;
}

Record* find_record(MemoryManager *mm, int key) {
    unsigned index = mm->hash_function(key) % mm->capacity;

    while (mm->hash_table[index] != NULL) {
        if (((Record*)mm->hash_table[index])->key == key) {
            return (Record*)mm->hash_table[index];
        }
        index = (index + 1) % mm->capacity;
    }

    return NULL;
}

void free_memory_manager(MemoryManager *mm) {
    for (size_t i = 0; i < mm->count; ++i) {
        free(mm->records[i]);
    }
    free(mm->records);
    free(mm->key_index);
    free(mm->hash_table);
    free(mm);
}

int main() {
    MemoryManager *mm = init_memory_manager(16, simple_hash);

    Record *rec1 = malloc(sizeof(Record));
    rec1->offset = 100;
    rec1->key = 1;
    insert_record(mm, rec1);

    Record *found = find_record(mm, 1);
    if (found) {
        printf("Found record with key %d and offset %ld\n", found->key, found->offset);
    } else {
        printf("Record not found.\n");
    }

    free_memory_manager(mm);

    return 0;
}
