['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char status;
    size_t index;
} entry;

typedef struct {
    entry *entries;
    entry **status_pointers;
    size_t count;
    size_t capacity;
} DynamicMemoryManager;

int custom_comparator(const void *a, const void *b) {
    entry *entryA = *(entry **)a;
    entry *entryB = *(entry **)b;

    if (entryA->index < entryB->index)
        return -1;
    else if (entryA->index > entryB->index)
        return 1;

    // Handle duplicates by comparing values
    if (entryA->value < entryB->value)
        return -1;
    else if (entryA->value > entryB->value)
        return 1;

    return 0; // Considered equal for sorting purposes
}

int initialize_manager(DynamicMemoryManager *manager, size_t initial_capacity) {
    manager->entries = malloc(initial_capacity * sizeof(entry));
    manager->status_pointers = malloc(initial_capacity * sizeof(entry *));
    if (!manager->entries || !manager->status_pointers)
        return -1; // Memory allocation failed

    manager->count = 0;
    manager->capacity = initial_capacity;

    return 0;
}

void free_manager(DynamicMemoryManager *manager) {
    free(manager->entries);
    free(manager->status_pointers);
    manager->entries = NULL;
    manager->status_pointers = NULL;
    manager->count = 0;
    manager->capacity = 0;
}

int add_entry(DynamicMemoryManager *manager, double value, char status, size_t index) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        entry *new_entries = realloc(manager->entries, new_capacity * sizeof(entry));
        entry **new_status_pointers = realloc(manager->status_pointers, new_capacity * sizeof(entry *));
        if (!new_entries || !new_status_pointers)
            return -1; // Memory allocation failed

        manager->entries = new_entries;
        manager->status_pointers = new_status_pointers;
        manager->capacity = new_capacity;
    }

    entry *new_entry = &manager->entries[manager->count++];
    new_entry->value = value;
    new_entry->status = status;
    new_entry->index = index;

    // Keep the list sorted
    qsort(manager->entries, manager->count, sizeof(entry), custom_comparator);

    return 0;
}

int update_status(DynamicMemoryManager *manager, size_t index, char new_status) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].index == index) {
            manager->entries[i].status = new_status;

            // Re-sort after update
            qsort(manager->entries, manager->count, sizeof(entry), custom_comparator);
            return 0;
        }
    }

    return -1; // Entry not found
}

int delete_entry(DynamicMemoryManager *manager, size_t index) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].index == index) {
            memmove(&manager->entries[i], &manager->entries[i + 1],
                    (manager->count - i - 1) * sizeof(entry));
            --manager->count;

            // Re-sort after deletion
            qsort(manager->entries, manager->count, sizeof(entry), custom_comparator);
            return 0;
        }
    }

    return -1; // Entry not found
}

entry* find_entry(DynamicMemoryManager *manager, size_t index) {
    entry target = { .index = index };
    entry *result = bsearch(&target, manager->entries, manager->count,
                            sizeof(entry), custom_comparator);
    return result;
}

int main() {
    DynamicMemoryManager manager;
    if (initialize_manager(&manager, 10) != 0) {
        fprintf(stderr, "Failed to initialize memory manager\n");
        return -1;
    }

    add_entry(&manager, 3.14, 'A', 2);
    add_entry(&manager, 2.71, 'B', 1);
    add_entry(&manager, 1.41, 'C', 3);

    entry *found = find_entry(&manager, 2);
    if (found) {
        printf("Found: %f, Status: %c, Index: %zu\n", found->value, found->status, found->index);
    }

    update_status(&manager, 2, 'D');
    delete_entry(&manager, 1);

    free_manager(&manager);
    return 0;
}
```']

