```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define STRING_LENGTH 50

typedef struct {
    char *data;
    int value;
} Record;

// Memory pool structure
typedef struct {
    void *pool;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables
MemoryPool mem_pool = {0};
int total_records_created = 0;
pthread_mutex_t records_lock;

void initialize_memory_pool(size_t block_size, size_t num_blocks) {
    pthread_mutex_init(&mem_pool.lock, NULL);
    mem_pool.block_size = block_size;
    mem_pool.num_blocks = num_blocks;
    mem_pool.pool = malloc(block_size * num_blocks);
}

void reset_memory_pool() {
    pthread_mutex_lock(&mem_pool.lock);
    memset(mem_pool.pool, 0, mem_pool.block_size * mem_pool.num_blocks);
    pthread_mutex_unlock(&mem_pool.lock);
}

void* allocate_from_pool(size_t size) {
    if (size > mem_pool.block_size) return NULL;

    pthread_mutex_lock(&mem_pool.lock);
    void *block = mem_pool.pool;
    mem_pool.pool = ((char*)mem_pool.pool) + mem_pool.block_size;
    pthread_mutex_unlock(&mem_pool.lock);

    return block;
}

void* allocate_string(size_t length) {
    char *str = (char *)allocate_from_pool(length + 1);
    if (!str) return NULL;
    return str;
}

void manage_memory_allocation(int num_records, int min_value, int max_value, int enable_logging) {
    if (num_records <= 0 || num_records > MAX_RECORDS) return;

    pthread_mutex_init(&records_lock, NULL);

    long *offsets = (long*)malloc(num_records * sizeof(long));
    int *keys = (int*)malloc(num_records * sizeof(int));
    Record *records = (Record*)malloc(num_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    FILE *log_file = enable_logging ? fopen("records.log", "a") : NULL;

    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % ((max_value - min_value) + 1) + min_value;
        records[i].value = keys[i];

        char *str_data = allocate_string(STRING_LENGTH);
        if (!str_data) continue;

        snprintf(str_data, STRING_LENGTH, "Record_%d", i);
        records[i].data = str_data;

        pthread_mutex_lock(&records_lock);
        total_records_created++;
        pthread_mutex_unlock(&records_lock);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Value: %d, String: %.10s\n", records[i].value, records[i].data);

        if (enable_logging && log_file) {
            fprintf(log_file, "%s", log_entry);
        } else {
            printf("%s", log_entry);
        }
    }

    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; ++i) {
        free(records[i].data); // Free string data
    }
    free(records);

    if (enable_logging && log_file) fclose(log_file);
}

void cleanup() {
    pthread_mutex_destroy(&records_lock);
    free(mem_pool.pool);
    pthread_mutex_destroy(&mem_pool.lock);
}

int main() {
    srand(time(NULL));

    initialize_memory_pool(sizeof(char) * STRING_LENGTH, MAX_RECORDS);

    // Example usage
    manage_memory_allocation(100, 1, 100, 1); // Enable logging

    reset_memory_pool();

    cleanup();
    return 0;
}
```

