async function initializeMemoryStructure(url, maxSize = 1024 * 1024) {
  const startTime = Date.now();

  if (typeof url !== 'string' || url.length === 0) {
    throw new Error('Invalid URL');
  }

  // Seed RNG with current time
  const seed = crypto.createHash('sha256').update(String(Date.now())).digest('hex');

  const offsetArray = [];
  const keyArray = [];
  const recordArray = [];

  try {
    // Allocate memory for the structure within maxSize constraint.
    let usedMemory = url.length; 
    while (usedMemory < maxSize) {
      const offsetValue = Math.floor(Math.random() * Number.MAX_SAFE_INTEGER);
      const intValue = Math.floor(Math.random() * Number.MAX_SAFE_INTEGER);

      if (offsetArray.length + 8 > maxSize - usedMemory || keyArray.length + 4 > maxSize - usedMemory) break;

      offsetArray.push(offsetValue);
      keyArray.push(intValue);

      recordArray.push({ value: intValue, offset: offsetValue });
      usedMemory += (8 + 4); // sizeof(long) + sizeof(int)
    }

    const serializedData = serializeData(url, offsetArray, keyArray, recordArray);

    const uploadedURL = await mockUploader(serializedData);

    return { url: uploadedURL, seed };

  } catch (error) {
    console.error('Error during initialization:', error);
    throw error;
  }
}

function serializeData(url, offsetArray, keyArray, recordArray) {
  // Serialize data considering endianness and integrity
  let buffer = Buffer.alloc(1024); // Placeholder allocation size for demonstration

  const urlBytes = Buffer.from(url, 'utf-8');
  buffer.writeUInt32BE(urlBytes.length, 0);
  urlBytes.copy(buffer, 4);

  let offsetIndex = 8 + urlBytes.length;
  for (const offset of offsetArray) {
    if (offsetIndex >= buffer.length) throw new Error('Buffer overflow');
    buffer.writeBigUInt64BE(BigInt(offset), offsetIndex);
    offsetIndex += 8;
  }

  const keyOffsetStart = offsetIndex;
  for (const key of keyArray) {
    if (keyOffsetStart + 4 >= buffer.length) throw new Error('Buffer overflow');
    buffer.writeInt32BE(key, keyOffsetStart);
    keyOffsetStart += 4;
  }

  let recordIndex = keyOffsetStart;
  for (const record of recordArray) {
    if (recordIndex + 12 >= buffer.length) throw new Error('Buffer overflow');
    buffer.writeInt32BE(record.value, recordIndex);
    buffer.writeBigUInt64BE(BigInt(record.offset), recordIndex + 4);
    recordIndex += 12;
  }

  return buffer.slice(0, offsetIndex + keyArray.reduce((sum, val) => sum + 4, 0) + recordArray.length * 12).toString('base64');
}
