#include <stdlib.h>
#include <stdint.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} Record;

void initializeMemory(long maxSize, int numRecords, int rangeMin, int rangeMax) {
    if (maxSize <= 0 || numRecords <= 0) return;

    srand(time(NULL));

    size_t usedMemory = sizeof(int) * 4 + sizeof(long) * 8; // Assume fixed sizes for offsets and keys
    long* offsetArray = malloc(sizeof(long) * maxSize);
    int* keyArray = malloc(sizeof(int) * maxSize);

    if (!offsetArray || !keyArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    Record* recordArray = malloc(sizeof(Record) * numRecords);
    if (!recordArray) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsetArray);
        free(keyArray);
        return;
    }

    for (int i = 0; i < numRecords && usedMemory + sizeof(Record) <= maxSize; ++i) {
        int keyValue = rangeMin + rand() % (rangeMax - rangeMin + 1);

        offsetArray[i] = rand();
        keyArray[i] = keyValue;

        recordArray[i].value = keyValue;
        recordArray[i].offset = rand();

        usedMemory += sizeof(Record);
    }

    // Cleanup
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}
