#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structures
typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    float x, y;
    int color_index;
} point;

typedef struct hash_node {
    char *key;
    point value;
    struct hash_node *next;
} hash_node;

// Function prototypes
void* manage_dynamic_memory(void (*custom_hash_func)(const char *, unsigned int *));
record** init_record_array(size_t initial_capacity);
int** init_key_index_array(size_t initial_capacity, record **records, size_t num_records);
hash_node** create_hash_table(size_t table_size, void (*custom_hash_func)(const char *, unsigned int *));

// Implementations
void* manage_dynamic_memory(void (*custom_hash_func)(const char *, unsigned int *)) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t record_capacity = 10;
    size_t key_index_capacity = 10;
    size_t hash_table_size = 100;

    record **records = init_record_array(record_capacity);
    int **key_indices = init_key_index_array(key_index_capacity, records, 0);
    hash_node **hash_table = create_hash_table(hash_table_size, custom_hash_func);

    // Example of adding data
    pthread_mutex_lock(&lock);
    size_t num_records = 0;

    for (size_t i = 0; i < record_capacity; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Handle error appropriately
        }

        records[i]->offset = (long)i;
        records[i]->key = (int)i;

        key_indices[i] = &((int){i});  // Store index

        unsigned int hash_value;
        custom_hash_func("example_key", &hash_value);

        size_t hash_index = hash_value % hash_table_size;
        hash_node *new_node = malloc(sizeof(hash_node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            // Handle error appropriately
        }

        new_node->key = strdup("example_key");
        float distance = sqrt(records[i]->offset);
        new_node->value.x = i;
        new_node->value.y = distance;
        new_node->value.color_index = (int)(distance / 10);

        new_node->next = hash_table[hash_index];
        hash_table[hash_index] = new_node;

        num_records++;
    }

    pthread_mutex_unlock(&lock);

    // Clean up
    for (size_t i = 0; i < record_capacity; ++i) {
        free(records[i]);
    }
    free(records);

    for (size_t i = 0; i < key_index_capacity; ++i) {
        free((void*)key_indices[i]);  // Cast away void*
    }
    free(key_indices);

    for (size_t i = 0; i < hash_table_size; ++i) {
        hash_node *current = hash_table[i];
        while (current) {
            hash_node *next = current->next;
            free(current->key);
            free(current);
            current = next;
        }
    }
    free(hash_table);

    pthread_mutex_destroy(&lock);

    return NULL;
}

record** init_record_array(size_t initial_capacity) {
    record **array = malloc(initial_capacity * sizeof(record *));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);  // Handle error appropriately
    }
    return array;
}

int** init_key_index_array(size_t initial_capacity, record **records, size_t num_records) {
    int **array = malloc(initial_capacity * sizeof(int *));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);  // Handle error appropriately
    }
    return array;
}

hash_node** create_hash_table(size_t table_size, void (*custom_hash_func)(const char *, unsigned int *)) {
    hash_node **table = malloc(table_size * sizeof(hash_node *));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);  // Handle error appropriately
    }

    for (size_t i = 0; i < table_size; ++i) {
        table[i] = NULL;
    }

    return table;
}
