### C Code: Dynamic List Management

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
    size_t max_memory_bytes;
} DynamicList;

int initialize_random_seed() {
    return (srand(time(NULL)) == 0);
}

int is_within_range(int min, int max) {
    return ((RAND_MAX >= max - min) && (rand() < RAND_MAX / 2));
}

DynamicList* create_dynamic_list(size_t max_memory_bytes, size_t record_size) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
    list->max_memory_bytes = max_memory_bytes;

    int error = initialize_random_seed();
    if (error != 0) {
        free(list);
        return NULL;
    }

    size_t initial_capacity = 10;
    list->records = malloc(initial_capacity * record_size);
    if (!list->records) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;

    return list;
}

int add_record(DynamicList *list, int min_key, int max_key) {
    size_t new_capacity = list->capacity * 2;
    size_t record_size = sizeof(Record);
    if (new_capacity * record_size > list->max_memory_bytes)
        return -1;

    Record *new_records = realloc(list->records, new_capacity * record_size);
    if (!new_records) return -1;

    list->records = new_records;
    list->capacity = new_capacity;

    Record new_record;
    new_record.key = (is_within_range(min_key, max_key)) ? rand() % (max_key - min_key + 1) + min_key : min_key;
    new_record.offset = rand();
    new_record.timestamp = time(NULL);

    list->records[list->count++] = new_record;

    return 0;
}

void free_dynamic_list(DynamicList *list) {
    if (list) {
        free(list->records);
        free(list);
    }
}
