```cpp
#include <iostream>
#include <string>
#include <nlohmann/json.hpp>
#include <sqlapi.h> // Assumed library for SQL integration

using json = nlohmann::json;

class UserManager {
public:
    UserManager() : dbConnection(nullptr) {}

    ~UserManager() { closeDatabase(); }

    std::string handleRequest(const std::string& requestPayload) {
        auto parsedJson = json::parse(requestPayload);

        if (!validateJson(parsedJson)) {
            return createErrorResponse("Invalid data format");
        }

        try {
            if (parsedJson.contains("id")) {
                updateUser(parsedJson);
            } else {
                createUser(parsedJson);
            }
            return createSuccessResponse();
        } catch (const std::exception& e) {
            logError(e.what());
            return createErrorResponse("Internal server error");
        }
    }

private:
    SAConnection dbConnection;

    void openDatabase() {
        if (!dbConnection.isConnected()) {
            try {
                // Configure connection details
                SADriver *driver = new SADODBCDriver();
                std::string connStr = "DSN=database_name;UID=user;PWD=password;";
                SAConnectOptions connectOptions;
                dbConnection.connect(connStr, connectOptions);
            } catch (SAException &e) {
                logError(e.ErrText());
            }
        }
    }

    void closeDatabase() {
        if (dbConnection.isConnected()) {
            dbConnection.disconnect();
        }
    }

    bool validateJson(const json& jsonData) const {
        return jsonData.contains("name") && jsonData.contains("email") &&
               jsonData.contains("password");
    }

    void createUser(const json& userData) {
        openDatabase();

        std::string query = "INSERT INTO users (name, email, password) VALUES ('" +
                            escapeString(userData["name"]) + "', '" +
                            escapeString(userData["email"]) + "', '" +
                            escapeString(userData["password"]) + "')";

        SADatabase db(dbConnection);
        try {
            SACommand cmd(&db, query.c_str());
            cmd.Execute();
        } catch (SAException &e) {
            logError(e.ErrText());
            throw;
        }
    }

    void updateUser(const json& userData) {
        openDatabase();

        std::string query = "UPDATE users SET name = '" +
                            escapeString(userData["name"]) + "', email = '" +
                            escapeString(userData["email"]) + "', password = '" +
                            escapeString(userData["password"]) + "' WHERE id = " +
                            userData.at("id").get<std::string>();

        SADatabase db(dbConnection);
        try {
            SACommand cmd(&db, query.c_str());
            cmd.Execute();
        } catch (SAException &e) {
            logError(e.ErrText());
            throw;
        }
    }

    std::string createSuccessResponse() const {
        return json{{"message", "success"}}.dump();
    }

    std::string createErrorResponse(const std::string& errorMessage) const {
        return json{{"error", errorMessage}}.dump();
    }

    void logError(const std::string& message) const {
        // Implement logging mechanism
        std::cerr << "Error: " << message << std::endl;
    }

    std::string escapeString(const std::string& str) const {
        // Proper escaping logic for SQL queries
        return "'" + str.replace(str.begin(), str.end(), '\'', "''") + "'";
    }

    void deleteUser(int userId) {
        openDatabase();

        std::string query = "DELETE FROM users WHERE id = " + std::to_string(userId);

        SADatabase db(dbConnection);
        try {
            SACommand cmd(&db, query.c_str());
            cmd.Execute();
        } catch (SAException &e) {
            logError(e.ErrText());
            throw;
        }
    }
};
