    char* random_str = (char*)malloc(length + 1);
    if (!random_str) {
        perror("Failed to allocate memory for random string");
        return NULL;
    }

    srand((unsigned int)time(NULL));
    size_t charset_len = strlen(charset);

    for (size_t i = 0; i < length; ++i) {
        random_str[i] = charset[rand() % charset_len];
    }
    random_str[length] = '\0';

    return random_str;
}

#include <openssl/evp.h>
#include <openssl/rand.h>

void hash_password(const char* password, unsigned char** out_hash) {
    if (!password || !out_hash) return;

    const EVP_MD* md = EVP_sha256();
    size_t len;
    *out_hash = (unsigned char*)malloc(EVP_MAX_MD_SIZE);
    if (!(*out_hash)) {
        perror("Failed to allocate memory for hash");
        return;
    }

    unsigned char salt[16];
    RAND_bytes(salt, sizeof(salt));

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, md, NULL);
    EVP_DigestUpdate(ctx, salt, sizeof(salt));
    EVP_DigestUpdate(ctx, password, strlen(password));
    EVP_DigestFinal_ex(ctx, *out_hash, &len);

    EVP_MD_CTX_free(ctx);
}

