        if (strcmp(sessions[i].token, token) == 0 && sessions[i].expiry > time(NULL)) {
            memset(sessions[i].token, 0, sizeof(sessions[i].token));
            sessions[i].expiry = 0;
            printf("Session ended: %s\n", token);
