Config* deserialize_configs(const uint8_t *input, size_t input_size, size_t *count) {
    if (!input || input_size == 0) return NULL;

    Config *configs = malloc(input_size / 52); // Assume max config size
    if (!configs) return NULL;

    const uint8_t *ptr = input;
    for (size_t i = 0; i < (input_size / 52); ++i) {
        double value;
        memcpy(&value, ptr, sizeof(double));
        ptr += sizeof(double);

        size_t len;
        memcpy(&len, ptr, sizeof(size_t));
        ptr += sizeof(size_t);

        char *name = malloc(len + 1);
        if (!name) break;

        memcpy(name, ptr, len + 1);
        ptr += (len + 1);

        configs[i].value = value;
        configs[i].name = name;
        configs[i].length = len;
    }

    *count = input_size / 52; // Assume fixed size for simplicity
    return configs;
}

void read_floats_and_calculate_stats() {
    printf("Enter floating-point numbers (type 'done' to finish):\n");

    double num, sum = 0.0, smallest = INFINITY;
    int count = 0;

    while (scanf("%lf", &num) == 1 || strcmp(getchar(), "done") != 0) {
        sum += num;
        if (num < smallest) smallest = num;
        ++count;

        // Clear input buffer
        while ((getchar()) != '\n');
    }

    if (count > 0) {
        double average = sum / count;
        printf("Smallest value: %f\n", smallest);
        printf("Average value: %f\n", average);
    } else {
        printf("No valid numbers entered.\n");
    }
}

char* generate_random_sentence(size_t length, const char *vocabulary[], size_t vocab_size) {
    char *sentence = malloc(length * (strlen(vocabulary[0]) + 1));
    if (!sentence) return NULL;

    srand(time(NULL)); // Seed the RNG
    int unique_count = 0;
    for (size_t i = 0; i < length; ++i) {
        const char *word = vocabulary[rand() % vocab_size];

        strcat(sentence, word);
        sentence[strlen(word)] = ' '; // Add space after each word

        if (++unique_count >= vocab_size / 2) break; // Limit unique words
    }

    sentence[length] = '\0'; // Ensure null-termination
    return sentence;
}
