#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example maximum memory usage limit (1MB)
#define SESSION_ID_LENGTH 16

typedef enum {
    ACTIVE,
    INACTIVE
} SessionStatus;

typedef struct {
    char sessionID[SESSION_ID_LENGTH];
    time_t lastActive;
    SessionStatus status;
} UserSession;

typedef struct Node {
    UserSession *session;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t currentMemoryUsage;
    pthread_mutex_t lock;
} SessionList;

// Function prototypes
void initSessionList(SessionList *list);
int addSession(SessionList *list, const char *sessionID, time_t lastActive, SessionStatus status);
UserSession* getSession(const SessionList *list, const char *sessionID);
int removeSession(SessionList *list, const char *sessionID);
int serializeSession(const UserSession *session, uint8_t **buffer, size_t *size);
int deserializeSession(const uint8_t *buffer, size_t size, UserSession *session);
char* generateUniqueSessionID(void);
void logEvent(const char *event);

// Initialize session list
void initSessionList(SessionList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->currentMemoryUsage = 0;
}

// Add a new session
int addSession(SessionList *list, const char *sessionID, time_t lastActive, SessionStatus status) {
    pthread_mutex_lock(&list->lock);

    // Check memory usage
    if (list->currentMemoryUsage + sizeof(UserSession) > MAX_MEMORY_USAGE) {
        logEvent("Memory limit reached");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node *newNode = (Node *)malloc(sizeof(Node));
    if (!newNode) {
        logEvent("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    UserSession *newSession = &newNode->session[0];
    strncpy(newSession->sessionID, sessionID, SESSION_ID_LENGTH);
    newSession->lastActive = lastActive;
    newSession->status = status;

    newNode->next = list->head;
    list->head = newNode;
    list->currentMemoryUsage += sizeof(UserSession);

    logEvent("Session added");
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Get a session by ID
UserSession* getSession(const SessionList *list, const char *sessionID) {
    pthread_mutex_lock((pthread_mutex_t *)&list->lock);

    Node *current = list->head;
    while (current) {
        if (strncmp(current->session->sessionID, sessionID, SESSION_ID_LENGTH) == 0) {
            pthread_mutex_unlock((pthread_mutex_t *)&list->lock);
            return current->session;
        }
        current = current->next;
    }

    logEvent("Session not found");
    pthread_mutex_unlock((pthread_mutex_t *)&list->lock);
    return NULL;
}

// Remove a session by ID
int removeSession(SessionList *list, const char *sessionID) {
    pthread_mutex_lock(&list->lock);

    Node **current = &list->head;
    while (*current) {
        if (strncmp((*current)->session->sessionID, sessionID, SESSION_ID_LENGTH) == 0) {
            Node *toDelete = *current;
            *current = toDelete->next;
            free(toDelete);
            list->currentMemoryUsage -= sizeof(UserSession);

            logEvent("Session removed");
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = &(*current)->next;
    }

    logEvent("Session not found for removal");
    pthread_mutex_unlock(&list->lock);
    return -1;
}

// Serialize a session
int serializeSession(const UserSession *session, uint8_t **buffer, size_t *size) {
    size_t bufferSize = sizeof(session->lastActive) + SESSION_ID_LENGTH + sizeof(session->status);
    *buffer = (uint8_t *)malloc(bufferSize);
    if (!*buffer) {
        logEvent("Failed to allocate memory for serialization");
        return -1;
    }

    uint8_t *ptr = *buffer;
    memcpy(ptr, &session->lastActive, sizeof(session->lastActive));
    ptr += sizeof(session->lastActive);

    memcpy(ptr, session->sessionID, SESSION_ID_LENGTH);
    ptr += SESSION_ID_LENGTH;

    memcpy(ptr, &session->status, sizeof(session->status));

    *size = bufferSize;
    logEvent("Session serialized");
    return 0;
}

// Deserialize a session
int deserializeSession(const uint8_t *buffer, size_t size, UserSession *session) {
    if (size < sizeof(session->lastActive) + SESSION_ID_LENGTH + sizeof(session->status)) {
        logEvent("Invalid buffer size for deserialization");
        return -1;
    }

    const uint8_t *ptr = buffer;

    memcpy(&session->lastActive, ptr, sizeof(session->lastActive));
    ptr += sizeof(session->lastActive);

    memcpy(session->sessionID, ptr, SESSION_ID_LENGTH);
    ptr += SESSION_ID_LENGTH;

    memcpy(&session->status, ptr, sizeof(session->status));

    logEvent("Session deserialized");
    return 0;
}

// Generate a unique session ID
char* generateUniqueSessionID(void) {
    char *id = (char *)malloc(SESSION_ID_LENGTH);
    if (!id) {
        logEvent("Failed to allocate memory for session ID");
        return NULL;
    }

    // Simple example using time and random number; replace with secure method as needed
    snprintf(id, SESSION_ID_LENGTH, "%lx%lu", time(NULL), rand());
    logEvent("Unique session ID generated");
    return id;
}

// Log events
void logEvent(const char *event) {
    printf("[%s] %s\n", __func__, event);
}
