#define MAX_MEMORY_USAGE 1024 * 1024  // Example limit, can be dynamically adjusted

typedef struct {
    int value;
    long offset;
    double timestamp;
} record_t;

typedef struct {
    char status_flag;
    short version_number;
} extended_metadata_t;

// Thread-safe random number generator
pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned int thread_safe_random(unsigned int min, unsigned int max) {
    static unsigned int seed;
    pthread_mutex_lock(&rand_mutex);
    if (seed == 0) {
        srand((unsigned int)time(NULL));
        seed = rand();
    }
    unsigned int result = min + (rand_r(&seed) % ((max - min) + 1));
    pthread_mutex_unlock(&rand_mutex);
    return result;
}

// Function to initialize and manage memory
int init_data_structures(int record_count, int key_range_min, int key_range_max,
