    if (!offsets || !keys || !records || !metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets); offset_mem = 0;
        free(keys); key_mem = 0;
        free(records); record_mem = 0;
        free(metadata); metadata_mem = 0;
        return -1;
    }

    // Initialize data structures
    for (int i = 0; i < record_count; ++i) {
