        offsets[i] = i * sizeof(record_t);  // Example offset assignment
        records[i].value = thread_safe_random(1, 100); // Random int value
        records[i].offset = offsets[i];
        records[i].timestamp = (double)time(NULL) + (double)i;
    }

    metadata->status_flag = 'A';  // Example status flag
    metadata->version_number = 1; // Example version number

    // Serialization example based on format
    if (strcmp(serialization_format, "binary") == 0) {
        FILE *file = fopen("data.bin", "wb");
