        fwrite(keys, sizeof(int), record_count, file);
        fwrite(offsets, sizeof(long), record_count, file);
        fwrite(records, sizeof(record_t), record_count, file);
        fwrite(metadata, sizeof(extended_metadata_t), 1, file);

