        uint32_t checksum = 0;
        for (int i = 0; i < record_count * (sizeof(int) + sizeof(long) + sizeof(record_t)) + sizeof(extended_metadata_t); ++i) {
            checksum += ((uint8_t *)offsets)[i % record_count];
        }

        fwrite(&checksum, sizeof(checksum), 1, file);
        fclose(file);

