                    keys[i], records[i].offset, records[i].value, records[i].timestamp);
        }
        fprintf(file, "</records>\n");
        fclose(file);

    } else {
        fprintf(stderr, "Unsupported serialization format\n");
        return -1;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(metadata);

    return 0;
}

