#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t current_size;
    size_t max_memory_limit;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_capacity, size_t max_memory_limit) {
    pthread_mutex_init(&array->lock, NULL);
    array->current_size = 0;
    array->max_memory_limit = max_memory_limit;

    size_t total_size = initial_capacity * (sizeof(long) + sizeof(int) + sizeof(Record));
    if (total_size > max_memory_limit) {
        fprintf(stderr, "Initial allocation exceeds maximum memory limit.\n");
        exit(EXIT_FAILURE);
    }

    array->offsets = malloc(initial_capacity * sizeof(long));
    array->keys = malloc(initial_capacity * sizeof(int));
    array->records = malloc(initial_capacity * sizeof(Record));

    if (!array->offsets || !array->keys || !array->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);

    size_t total_size = new_capacity * (sizeof(long) + sizeof(int) + sizeof(Record));
    if (total_size > array->max_memory_limit) {
        fprintf(stderr, "Resizing exceeds maximum memory limit.\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    long *new_offsets = realloc(array->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(array->keys, new_capacity * sizeof(int));
    Record *new_records = realloc(array->records, new_capacity * sizeof(Record));

    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed.\n");
        pthread_mutex_unlock(&array->lock);
        exit(EXIT_FAILURE);
    }

    array->offsets = new_offsets;
    array->keys = new_keys;
    array->records = new_records;

    size_t memory_used = total_size;
    if (memory_used > 0.8 * array->max_memory_limit) {
        printf("Warning: Memory usage is above 80% of the allocated limit.\n");
    }

    pthread_mutex_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    if (array->offsets) free(array->offsets);
    if (array->keys) free(array->keys);
    if (array->records) free(array->records);

    array->offsets = NULL;
    array->keys = NULL;
    array->records = NULL;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

void add_record(DynamicArray *array, int key, long offset, Record record) {
    pthread_mutex_lock(&array->lock);

    if (array->current_size >= ((size_t)(-1) / 3)) { // Prevent overflow
        fprintf(stderr, "Maximum size limit reached.\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    size_t new_capacity = array->current_size + 1;
    resize_dynamic_array(array, new_capacity);

    array->offsets[array->current_size] = offset;
    array->keys[array->current_size] = key;
    array->records[array->current_size] = record;

    ++array->current_size;

    pthread_mutex_unlock(&array->lock);
}

void serialize_data(const DynamicArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    size_t record_count = array->current_size;
    fwrite(&record_count, sizeof(size_t), 1, file);

    fwrite(array->offsets, sizeof(long), record_count, file);
    fwrite(array->keys, sizeof(int), record_count, file);
    for (size_t i = 0; i < record_count; ++i) {
        Record rec = array->records[i];
        fwrite(&rec.value, sizeof(int), 1, file);
        fwrite(&rec.offset, sizeof(long), 1, file);
    }

    fclose(file);

    pthread_mutex_unlock(&array->lock);
}

void deserialize_data(DynamicArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading.\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    size_t record_count;
    fread(&record_count, sizeof(size_t), 1, file);

    resize_dynamic_array(array, record_count);

    fread(array->offsets, sizeof(long), record_count, file);
    fread(array->keys, sizeof(int), record_count, file);
    for (size_t i = 0; i < record_count; ++i) {
        Record rec;
        fread(&rec.value, sizeof(int), 1, file);
        fread(&rec.offset, sizeof(long), 1, file);
        array->records[i] = rec;
    }

    array->current_size = record_count;

    fclose(file);

    pthread_mutex_unlock(&array->lock);
}

int main() {
    size_t max_memory_limit = 1024 * 1024; // 1 MB limit for demonstration
    DynamicArray array;
    init_dynamic_array(&array, 10, max_memory_limit);

    for (int i = 0; i < 20; ++i) {
        add_record(&array, i, i * 1000L, (Record){.value = i});
    }

    serialize_data(&array, "data.bin");
    free_dynamic_array(&array);

    DynamicArray new_array;
    init_dynamic_array(&new_array, 10, max_memory_limit);
    deserialize_data(&new_array, "data.bin");

    free_dynamic_array(&new_array);
    return 0;
}
