typedef struct {
    double value;
    char identifier[32];
} Config;

Config* allocate_configs(size_t count, size_t max_size, double min_value, double max_value) {
    if (max_size <= sizeof(Config) * count + count * 31 || count == 0) {
        return NULL;
    }

    Config *configs = malloc(sizeof(Config) * count);
    if (!configs) {
        perror("Failed to allocate memory for configs");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        double random_value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
        snprintf(configs[i].identifier, sizeof(configs[i].identifier), "Config_%zu", i + 1);
        configs[i].value = random_value;
    }

    return configs;
}

size_t serialize_configs(const Config *configs, size_t count, unsigned char **output) {
    if (!configs || !output) {
        return 0;
    }

    size_t total_size = sizeof(size_t) + count * (sizeof(double) + 31);
    *output = malloc(total_size);

    if (!*output) {
        perror("Failed to allocate memory for serialized data");
        return 0;
    }

    unsigned char *ptr = *output;

    memcpy(ptr, &count, sizeof(count));
    ptr += sizeof(count);

    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &configs[i].value, sizeof(double));
        ptr += sizeof(double);
        memcpy(ptr, configs[i].identifier, 31);
        ptr += 31;
    }

    return total_size;
}

Config* deserialize_configs(const unsigned char *data, size_t data_size, size_t *count) {
    if (!data || !count) {
        return NULL;
    }

    const unsigned char *ptr = data;

    memcpy(count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    Config *configs = malloc(sizeof(Config) * (*count));
    if (!configs) {
        perror("Failed to allocate memory for deserialized configs");
        return NULL;
    }

    for (size_t i = 0; i < *count; ++i) {
        memcpy(&configs[i].value, ptr, sizeof(double));
        ptr += sizeof(double);
        memcpy(configs[i].identifier, ptr, 31);
        ptr += 31;
    }

    return configs;
}

void find_largest_number() {
    size_t count;
    printf("Enter number of floating-point numbers: ");
    scanf("%zu", &count);

    if (count == 0) {
        printf("No numbers to process.\n");
        return;
    }

    double *numbers = malloc(count * sizeof(double));
    if (!numbers) {
        perror("Failed to allocate memory for numbers");
        return;
    }

    printf("Enter the floating-point numbers:\n");
    for (size_t i = 0; i < count; ++i) {
        scanf("%lf", &numbers[i]);
    }

    double largest = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("The largest number is: %.6f\n", largest);

    free(numbers);
}

int main() {
    size_t config_count = 5;
    size_t max_size = 1024 * 1024; // 1 MB for example
    double min_value = -10.0, max_value = 10.0;

    Config *configs = allocate_configs(config_count, max_size, min_value, max_value);
    if (!configs) {
        return EXIT_FAILURE;
    }

    unsigned char *serialized_data;
    size_t serialized_size = serialize_configs(configs, config_count, &serialized_data);

    if (serialized_data && serialized_size > 0) {
        size_t deserialized_count;
        Config *deserialized_configs = deserialize_configs(serialized_data, serialized_size, &deserialized_count);

        if (!deserialized_configs) {
            free(serialized_data);
            free(configs);
            return EXIT_FAILURE;
        }

        for (size_t i = 0; i < deserialized_count; ++i) {
            printf("Deserialized Config %zu: Value = %.6f, Identifier = %s\n", 
                   i + 1, deserialized_configs[i].value, deserialized_configs[i].identifier);
        }

        free(deserialized_configs);
    }

    free(serialized_data);
    free(configs);

    find_largest_number();

    return EXIT_SUCCESS;
}
