        if (ds.records[i]) free(ds.records[i]);
    }
    free(ds.records);
    EVP_CIPHER_CTX_free(ds.cipher_ctx);

    return -1; // Failure
}

void cleanup_data_structures(data_structures_t *ds, size_t records_count) {
    free(ds->offsets);
    free(ds->keys);
    for (size_t i = 0; i < records_count; ++i) {
        if (ds->records[i]) free(ds->records[i]);
    }
    free(ds->records);
    EVP_CIPHER_CTX_free(ds->cipher_ctx);
}

