#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

void initialize_data(long **offsets, int offset_count, int **keys, int key_count, record **records, int record_count, unsigned int seed) {
    // Seed random number generator
    srand(seed);

    if (offset_count > 0) {
        *offsets = malloc(offset_count * sizeof(long));
        if (*offsets == NULL) {
            perror("Failed to allocate memory for offsets");
            exit(EXIT_FAILURE);
        }
        for (int i = 0; i < offset_count; ++i) {
            (*offsets)[i] = rand() % 100; // Random value within a range
        }
    } else {
        *offsets = NULL;
    }

    if (key_count > 0) {
        *keys = malloc(key_count * sizeof(int));
        if (*keys == NULL) {
            perror("Failed to allocate memory for keys");
            exit(EXIT_FAILURE);
        }
        for (int i = 0; i < key_count; ++i) {
            (*keys)[i] = rand() % 100; // Random value within a range
        }
    } else {
        *keys = NULL;
    }

    if (record_count > 0) {
        *records = malloc(record_count * sizeof(record));
        if (*records == NULL) {
            perror("Failed to allocate memory for records");
            exit(EXIT_FAILURE);
        }

        int used_offsets[100] = {0};
        int used_keys[100] = {0};

        // Example range for random initialization
        const int min_value = 1;
        const int max_value = 10;

        for (int i = 0; i < record_count; ++i) {
            (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;

            // Ensure unique offset and key assignment
            int valid_assignment = 0;
            while (!valid_assignment) {
                long *offset_ptr = NULL;
                if (offset_count > 0) {
                    int random_offset_index = rand() % offset_count;
                    if (!used_offsets[random_offset_index]) {
                        offset_ptr = &((*offsets)[random_offset_index]);
                        used_offsets[random_offset_index] = 1;
                        valid_assignment = 1;
                    }
                }

                int *key_ptr = NULL;
                if (key_count > 0) {
                    int random_key_index = rand() % key_count;
                    if (!used_keys[random_key_index]) {
                        key_ptr = &((*keys)[random_key_index]);
                        used_keys[random_key_index] = 1;
                        valid_assignment = 1;
                    }
                }

                // Ensure we have found a unique assignment
                if (valid_assignment) {
                    (*records)[i].offset_ptr = offset_ptr;
                    (*records)[i].key_ptr = key_ptr;
                } else {
                    // Reset the used flag if no assignment is possible
                    for (int j = 0; j < offset_count && !valid_assignment; ++j) {
                        if (used_offsets[j]) used_offsets[j] = 0;
                    }
                    for (int k = 0; k < key_count && !valid_assignment; ++k) {
                        if (used_keys[k]) used_keys[k] = 0;
                    }
                }
            }
        }
    } else {
        *records = NULL;
    }
}

void cleanup_data(long **offsets, int **keys, record **records) {
    free(*offsets);
    *offsets = NULL;

    free(*keys);
    *keys = NULL;

    free(*records);
    *records = NULL;
}
