['Below is a simplified version of a multi-threaded C program to manage a scalable pool of network connections for a WebSocket server application. This code includes thread-safe connection management using mutexes and condition variables, memory allocation handling, and a TLS/SSL handshake setup.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

#define MAX_CONNECTIONS 1000
#define IDLE_TIMEOUT_THRESHOLD 300 // seconds

typedef enum { CONNECTED, DISCONNECTED, BUSY, ERROR } ConnectionStatus;

typedef struct {
    int socket_descriptor;
    long last_accessed_timestamp;
    ConnectionStatus status;
    unsigned int messages_sent;
    unsigned int messages_received;
} ClientConnection;

typedef struct {
    ClientConnection *connections;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    size_t count;
    size_t capacity;
    SSL_CTX *ssl_ctx;
} ConnectionPool;

void initialize_ssl_context(SSL_CTX **ctx, const char *cert_file, const char *key_file) {
    SSL_load_error_strings();
    OpenSSL_add_ssl_algorithms();

    *ctx = SSL_CTX_new(TLS_server_method());
    if (!*ctx) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    if (SSL_CTX_use_certificate_file(*ctx, cert_file, SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(*ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(*ctx);
        exit(EXIT_FAILURE);
    }

    if (!SSL_CTX_check_private_key(*ctx)) {
        fprintf(stderr, "Private key does not match the public certificate\n");
        SSL_CTX_free(*ctx);
        exit(EXIT_FAILURE);
    }
}

ConnectionPool *initialize_connection_pool(size_t max_capacity) {
    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;

    pool->connections = calloc(max_capacity, sizeof(ClientConnection));
    if (!pool->connections) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond_var, NULL);

    pool->count = 0;
    pool->capacity = max_capacity;

    initialize_ssl_context(&pool->ssl_ctx, "server-cert.pem", "server-key.pem");

    return pool;
}

int add_connection(ConnectionPool *pool, int socket_descriptor) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full
    }

    ClientConnection *connection = &pool->connections[pool->count++];
    connection->socket_descriptor = socket_descriptor;
    connection->last_accessed_timestamp = time(NULL);
    connection->status = CONNECTED;
    connection->messages_sent = 0;
    connection->messages_received = 0;

    pthread_mutex_unlock(&pool->lock);

    return 0; // Success
}

void remove_connection(ConnectionPool *pool, int socket_descriptor) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->connections[i].socket_descriptor == socket_descriptor) {
            memmove(&pool->connections[i], &pool->connections[i + 1],
                    (--pool->count - i) * sizeof(ClientConnection));
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void cleanup_connection_pool(ConnectionPool *pool) {
    if (pool) {
        free(pool->connections);
        SSL_CTX_free(pool->ssl_ctx);
        pthread_mutex_destroy(&pool->lock);
        pthread_cond_destroy(&pool->cond_var);
        free(pool);
    }
}

int main() {
    ConnectionPool *pool = initialize_connection_pool(MAX_CONNECTIONS);

    // Example of adding a connection
    int socket_fd = 1; // Placeholder for an actual socket descriptor
    if (add_connection(pool, socket_fd) == 0) {
        printf("Connection added successfully\n");
    } else {
        fprintf(stderr, "Failed to add connection\n");
    }

    // Cleanup when done
    cleanup_connection_pool(pool);

    return 0;
}
```

