    // Initialize the long array with increasing integers from 0 to 999
    for (int i = 0; i < 1000; ++i) {
        long_array[i] = i;
    }

    // Initialize the Fibonacci array
    if (fib_array[0] == 0 && fib_array[1] == 1) {
        for (int i = 2; i < 500; ++i) {
            fib_array[i] = fib_array[i - 1] + fib_array[i - 2];
        }
    }

    // Calculate the number of records
    int num_records = 1000 + 500;

    // Initialize records array by interleaving values from long and Fibonacci arrays
    for (int i = 0; i < num_records; ++i) {
        if (i % 2 == 0 && i < 1000) { 
            (*records)[i].field = long_array[i];
        } else if (i % 2 != 0 && (i - 1) / 2 < 500) {
            (*records)[i].field = fib_array[(i - 1) / 2];
        }
    }
}

void modify_records(Record* records, int num_records) {
    srand(time(NULL)); // Seed the random number generator
    for (int i = 1; i < num_records; i += 2) { 
        records[i].field += rand() % 100 + 1;
    }
}

long calculate_checksum(long* long_array, int* fib_array, Record* records, int num_records) {
    long checksum = 0;

    // Calculate checksum from the original arrays
    for (int i = 0; i < 1000; ++i) {
        checksum += long_array[i];
    }

    for (int i = 0; i < 500; ++i) {
        checksum += fib_array[i];
    }

    // Calculate checksum from modified records
    for (int i = 1; i < num_records; i += 2) { 
        checksum += records[i].field;
    }

    return checksum;
}

void manage_dynamic_arrays() {
    long* long_array = malloc(1000 * sizeof(long));
    int* fib_array = malloc(500 * sizeof(int));

    // Initialize Fibonacci array with starting values
    fib_array[0] = 0;
    fib_array[1] = 1;

    Record* records = malloc((1000 + 500) * sizeof(Record));

    if (!long_array || !fib_array || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    initialize_arrays(long_array, fib_array, &records);

    modify_records(records, 1000 + 500);

    long checksum = calculate_checksum(long_array, fib_array, records, 1000 + 500);
    printf("Checksum: %ld\n", checksum);

    free(long_array);
    free(fib_array);
    free(records);
}

int main() {
