#include <iostream>
#include <vector>
#include <random>
#include <string>
#include <mutex>
#include <memory>

class DynamicValueGenerator {
public:
    struct RangeConfig {
        long min;
        long max;
        int subMin;
        int subMax;
    };

private:
    std::vector<long> offsetValues;
    std::vector<int> keys;
    mutable std::mutex mtx;
    std::mt19937 gen;
    double rangeFloatMin, rangeFloatMax;
    int rangeIntMin, rangeIntMax;
    RangeConfig rangeConfig;

public:
    DynamicValueGenerator(long min, long max)
        : offsetValues(min, max + 1), keys(static_cast<int>(max - min + 1)),
          gen(std::random_device{}()),
          rangeFloatMin(0.0), rangeFloatMax(1.0),
          rangeIntMin(0), rangeIntMax(100) {
        std::fill(offsetValues.begin(), offsetValues.end(), min);
        std::iota(keys.begin(), keys.end(), min);
    }

    void updateRangeConfig(const RangeConfig& newConfig) {
        std::lock_guard<std::mutex> lock(mtx);
        rangeConfig = newConfig;
    }

    int generateRandomInt(bool inclusive = true) const {
        std::uniform_int_distribution<> dist(rangeIntMin, rangeIntMax - (inclusive ? 0 : 1));
        return dist(gen);
    }

    float generateRandomFloat(bool inclusive = true) const {
        std::uniform_real_distribution<> dist(rangeFloatMin, rangeFloatMax - (inclusive ? 0.0 : std::numeric_limits<float>::epsilon()));
        return dist(gen);
    }

    std::vector<int> generateIntSequence(int n) const {
        std::lock_guard<std::mutex> lock(mtx);
        std::uniform_int_distribution<> dist(rangeIntMin, rangeIntMax - 1);
        std::vector<int> sequence(n);
        for (int& value : sequence) {
            value = dist(gen);
        }
        return sequence;
    }

    std::vector<float> generateFloatSequence(int n) const {
        std::lock_guard<std::mutex> lock(mtx);
        std::uniform_real_distribution<> dist(rangeFloatMin, rangeFloatMax - 1.0f);
        std::vector<float> sequence(n);
        for (float& value : sequence) {
            value = dist(gen);
        }
        return sequence;
    }

    void setRange(double min, double max) {
        std::lock_guard<std::mutex> lock(mtx);
        rangeFloatMin = min;
        rangeFloatMax = max;
    }

    void setIntRange(int min, int max) {
        std::lock_guard<std::mutex> lock(mtx);
        rangeIntMin = min;
        rangeIntMax = max;
    }

    std::string toString() const {
        std::lock_guard<std::mutex> lock(mtx);
        return "Range: [" + std::to_string(rangeConfig.min) + ", " + std::to_string(rangeConfig.max) +
               "] Sub-Range: [" + std::to_string(rangeConfig.subMin) + ", " + std::to_string(rangeConfig.subMax) + "]";
    }
};

int main() {
    DynamicValueGenerator generator(0, 100);
    generator.setIntRange(10, 50);
    generator.setRange(0.0, 1.0);

    auto intSeq = generator.generateIntSequence(5);
    auto floatSeq = generator.generateFloatSequence(5);

    std::cout << "Random Int Sequence: ";
    for (int val : intSeq) {
        std::cout << val << " ";
    }
    std::cout << "\nRandom Float Sequence: ";
    for (float val : floatSeq) {
        std::cout << val << " ";
    }

    std::cout << "\nCurrent Range Settings: " << generator.toString() << std::endl;

    return 0;
}
