import pthread.h

#define NUM_THREADS 4 // Adjust based on your processor core count

typedef struct {
    long offset;
    int key;
    int* value;
} item;

typedef struct {
    item** items;
    size_t count;
    pthread_mutex_t lock; // For synchronizing access to shared resources
} processor;

void initialize_item(item* i, long off, int k, int v) {
    if (i != NULL) {
        i->offset = off;
        i->key = k;
        i->value = malloc(sizeof(int));
        if (i->value != NULL) {
            *i->value = v;
        }
    }
}

processor* create_processor(size_t item_count) {
    processor* p = malloc(sizeof(processor));
    pthread_mutex_init(&p->lock, NULL);

    p->items = malloc(item_count * sizeof(item*));
    if (p->items == NULL) {
        free(p);
        return NULL;
    }

    p->count = item_count;

    for (size_t i = 0; i < item_count; ++i) {
        p->items[i] = malloc(sizeof(item));
        initialize_item(p->items[i], i, i * 2, i * 3); // Example initialization
    }

    return p;
}

void process_item(void* arg) {
    processor* p = (processor*)arg;

    for (size_t i = 0; i < p->count; ++i) {
        pthread_mutex_lock(&p->lock);

        if (p->items[i] != NULL) {
            // Process item, e.g., print or modify
            printf("Processing: %ld, %d, %d\n", p->items[i]->offset, p->items[i]->key, *p->items[i]->value);
        }

        pthread_mutex_unlock(&p->lock);
    }
}

void destroy_processor(processor* p) {
    if (p != NULL) {
        for (size_t i = 0; i < p->count; ++i) {
            if (p->items[i] != NULL) {
                free(p->items[i]->value); // Free the allocated integer
                free(p->items[i]);
            }
        }

        free(p->items);
        pthread_mutex_destroy(&p->lock);
        free(p);
    }
}

void* worker_thread(void* arg) {
    processor* p = (processor*)arg;
    process_item(p);
    return NULL;
}

int main() {
    size_t item_count = 10; // Example count
    processor* proc = create_processor(item_count);

    if (proc == NULL) {
        fprintf(stderr, "Failed to allocate processor\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker_thread, proc);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_processor(proc);

    return EXIT_SUCCESS;
}
