```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LONG_ARRAY_SIZE 1000
#define MAX_INT_ARRAY_SIZE 500

typedef struct {
    int value;
} record;

typedef struct {
    double number;
    char *text;
} data_item;

int allowed_chars[] = { 'a', 'b', 'c', /* ... other allowed characters */ };
const size_t allowed_length = 10; // Example max length constraint for strings

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize an array of long values with increasing integers
long* init_long_array(size_t size) {
    if (size > MAX_LONG_ARRAY_SIZE) {
        size = MAX_LONG_ARRAY_SIZE;
    }
    long *array = malloc(size * sizeof(long));
    for (size_t i = 0; i < size; ++i) {
        array[i] = i;
    }
    return array;
}

// Function to initialize an array of Fibonacci numbers
int* init_fibonacci_array(size_t size) {
    if (size > MAX_INT_ARRAY_SIZE) {
        size = MAX_INT_ARRAY_SIZE;
    }
    int *array = malloc(size * sizeof(int));
    if (!array) return NULL;

    array[0] = 0;
    if (size > 1) array[1] = 1;

    for (size_t i = 2; i < size; ++i) {
        array[i] = array[i - 1] + array[i - 2];
    }
    return array;
}

// Function to check if a character is allowed
int is_allowed_char(char c) {
    for (size_t i = 0; i < sizeof(allowed_chars) / sizeof(int); ++i) {
        if (allowed_chars[i] == c)
            return 1;
    }
    return 0;
}

// Function to validate string against constraints
int validate_string(const char *str, size_t max_len) {
    size_t len = strlen(str);
    if (len > max_len) return 0;

    for (size_t i = 0; i < len; ++i) {
        if (!is_allowed_char(str[i])) return 0;
    }
    return 1;
}

// Function to initialize records from long and int arrays
record* init_record_array(const long *long_array, const int *int_array, size_t size) {
    record *records = malloc(size * sizeof(record));
    for (size_t i = 0; i < size && i < MAX_LONG_ARRAY_SIZE && i < MAX_INT_ARRAY_SIZE; ++i) {
        records[i].value = int_array[i] + long_array[i];
    }
    return records;
}

// Data item array structure
typedef struct {
    data_item *items;
    size_t capacity;
    size_t count;
} data_item_collection;

data_item_collection* create_data_item_collection(size_t initial_capacity) {
    data_item_collection *collection = malloc(sizeof(data_item_collection));
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->items = malloc(initial_capacity * sizeof(data_item));
    return collection;
}

// Function to resize the data item array
void resize_data_item_collection(data_item_collection *collection, size_t new_capacity) {
    pthread_mutex_lock(&mutex);
    data_item *new_items = realloc(collection->items, new_capacity * sizeof(data_item));
    if (new_items) {
        collection->capacity = new_capacity;
        collection->items = new_items;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to add an item to the collection
void add_data_item(data_item_collection *collection, double number, const char *text) {
    pthread_mutex_lock(&mutex);

    if (collection->count >= collection->capacity) {
        resize_data_item_collection(collection, collection->capacity * 2);
    }

    if (!validate_string(text, allowed_length)) {
        pthread_mutex_unlock(&mutex);
        fprintf(stderr, "Invalid string\n");
        return;
    }

    size_t len = strlen(text) + 1; // +1 for null terminator
    char *validated_text = malloc(len);

    strcpy(validated_text, text);

    collection->items[collection->count].number = number;
    collection->items[collection->count].text = validated_text;
    collection->count++;

    pthread_mutex_unlock(&mutex);
}

// Function to clean up the data item collection
void free_data_item_collection(data_item_collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->items[i].text);
    }
    free(collection->items);
    free(collection);
}

int main() {
    size_t long_size = MAX_LONG_ARRAY_SIZE;
    size_t int_size = MAX_INT_ARRAY_SIZE;

    // Initialize arrays
    long *long_array = init_long_array(long_size);
    int *fibonacci_array = init_fibonacci_array(int_size);

    // Calculate the number of records needed
    size_t record_count = long_size + int_size;
    record *records = init_record_array(long_array, fibonacci_array, record_count);

    // Example usage of data_item_collection
    data_item_collection *collection = create_data_item_collection(10);
    add_data_item(collection, 1.23, "test");
    add_data_item(collection, 4.56, "abc");

    for (size_t i = 0; i < collection->count; ++i) {
        printf("Item %zu: %.2f - %s\n", i, collection->items[i].number, collection->items[i].text);
    }

    // Clean up
    free_data_item_collection(collection);
    free(records);
    free(fibonacci_array);
    free(long_array);

    pthread_mutex_destroy(&mutex);

    return 0;
}
```

This program dynamically manages the memory for various arrays and ensures thread safety using mutexes. It includes validation of strings before adding them to a collection, resizing strategies for dynamic arrays, and proper cleanup routines. Adjust the `allowed_chars` array as needed based on your specific requirements.']

