#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <math.h>

// Define matrix structure
typedef struct {
    float data[10][10];
} Matrix;

// Node for linked list
typedef struct ListNode {
    float value;
    struct ListNode* next;
} ListNode;

// Hash table entry
typedef struct HashEntry {
    char* key;
    int value;
    struct HashEntry* next;
} HashEntry;

// Global variables with mutexes for synchronization
double *doubleArray = NULL;
ListNode *floatListHead = NULL;
Matrix *matrixArray = NULL;
HashEntry **hashTable = NULL;
int hashTableSize = 1000;
pthread_mutex_t hashMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeDataStructures() {
    // Allocate and initialize the array of doubles
    doubleArray = (double*)malloc(2000 * sizeof(double));
    for (int i = 0; i < 2000; ++i) {
        doubleArray[i] = exp((double)i / 100.0);
    }

    // Initialize linked list with powers of two
    floatListHead = NULL;
    ListNode* current = NULL;
    for (float power = 1.0f; power <= pow(2, 10); power *= 2) {
        ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
        newNode->value = power;
        newNode->next = NULL;
        if (current == NULL) {
            floatListHead = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    // Allocate and initialize the array of matrices
    int matrixCount = 5; // Define number of matrices for example purposes
    matrixArray = (Matrix*)malloc(matrixCount * sizeof(Matrix));
    float value = 0.0f;
    for (int i = 0; i < matrixCount; ++i) {
        for (int row = 0; row < 10; ++row) {
            for (int col = 0; col < 10; ++col) {
                matrixArray[i].data[row][col] = value++;
            }
        }
    }

    // Allocate and initialize the hash table
    hashTable = (HashEntry**)calloc(hashTableSize, sizeof(HashEntry*));
}

void multiplyMatrix(Matrix *matrix, float scalar) {
    for (int row = 0; row < 10; ++row) {
        for (int col = 0; col < 10; ++col) {
            matrix->data[row][col] *= scalar;
        }
    }
}

float generateRandomScalar() {
    return ((float)(rand() % 100 + 1)) / 10.0f * (rand() & 1 ? 1 : -1);
}

void* multiplyMatrices(void* arg) {
    int start = *(int*)arg;
    for (int i = start; i < 5; i += 2) { // Example: two threads
        float scalar = generateRandomScalar();
        multiplyMatrix(&matrixArray[i], scalar);
    }
    return NULL;
}

void insertIntoHashTable(const char* key, int value) {
    unsigned long hashValue = (unsigned long)key % hashTableSize;
    HashEntry* newEntry = (HashEntry*)malloc(sizeof(HashEntry));
    newEntry->key = strdup(key);
    newEntry->value = value;
    newEntry->next = NULL;

    pthread_mutex_lock(&hashMutex);
    HashEntry* current = hashTable[hashValue];
    if (current == NULL) {
        hashTable[hashValue] = newEntry;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntry;
    }
    pthread_mutex_unlock(&hashMutex);
}

int retrieveFromHashTable(const char* key, int *value) {
    unsigned long hashValue = (unsigned long)key % hashTableSize;
    pthread_mutex_lock(&hashMutex);
    HashEntry* current = hashTable[hashValue];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            *value = current->value;
            pthread_mutex_unlock(&hashMutex);
            return 1; // Success
        }
        current = current->next;
    }
    pthread_mutex_unlock(&hashMutex);
    return 0; // Not found
}

void freeDataStructures() {
    for (int i = 0; i < 2000; ++i) { /* No need to free doubles */ }

    ListNode* node = floatListHead;
    while (node != NULL) {
        ListNode* temp = node;
        node = node->next;
        free(temp);
    }

    // Free matrices
    free(matrixArray);

    // Free hash table
    for (int i = 0; i < hashTableSize; ++i) {
        HashEntry* entry = hashTable[i];
        while (entry != NULL) {
            HashEntry* temp = entry;
            entry = entry->next;
            free(temp->key);
            free(temp);
        }
    }
    free(hashTable);
}

int main() {
    initializeDataStructures();

    pthread_t threads[2];
    int thread_args[2] = {0, 1}; // Start indices for each thread

    pthread_create(&threads[0], NULL, multiplyMatrices, (void*)&thread_args[0]);
    pthread_create(&threads[1], NULL, multiplyMatrices, (void*)&thread_args[1]);

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Example usage of hash table
    insertIntoHashTable("example", 42);
    int value;
    if (retrieveFromHashTable("example", &value)) {
        printf("Value retrieved: %d\n", value);
    } else {
        printf("Key not found.\n");
    }

    freeDataStructures();
    return 0;
}
```

