['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_THRESHOLD 1000
#define OFFSET_RANGE_MIN 10
#define OFFSET_RANGE_MAX 50
#define KEY_RANGE_MIN 1
#define KEY_RANGE_MAX 100
#define VALUE_RANGE_MIN 1
#define VALUE_RANGE_MAX 20

typedef struct {
    int value;
} record;

// Hash function prototype
int hash_function(int key);

void manage_records(int num_records, int window_size) {
    if (num_records <= 0 || window_size <= 0) return;

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed random number generator

    int sum = 0;
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
        offsets[i] = hash_function(keys[i]) % (OFFSET_RANGE_MAX - OFFSET_RANGE_MIN + 1) + OFFSET_RANGE_MIN;

        int value;
        do {
            value = rand() % (VALUE_RANGE_MAX - VALUE_RANGE_MIN + 1) + VALUE_RANGE_MIN;
        } while (sum + value > MAX_THRESHOLD);

        records[i].value = value;
        sum += value;

        if ((i + 1) % window_size == 0 || i == num_records - 1) {
            // Sliding window mechanism: update offsets and keys
            long *new_offsets = realloc(offsets, (num_records + window_size) * sizeof(long));
            int *new_keys = realloc(keys, (num_records + window_size) * sizeof(int));

            if (!new_offsets || !new_keys) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(offsets);
                free(keys);
                free(records);
                exit(EXIT_FAILURE);
            }

            offsets = new_offsets;
            keys = new_keys;

            for (int j = num_records; j < num_records + window_size && j < 2 * num_records; ++j) {
                if (j >= num_records) {
                    keys[j] = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
