    }

    free(offsets);
    free(keys);
    free(records);
}

// Example hash function
int hash_function(int key) {
    return key * 2654435761 % (OFFSET_RANGE_MAX - OFFSET_RANGE_MIN + 1);
}

int main() {
    int num_records = 10;
    int window_size = 3;
    manage_records(num_records, window_size);
