```c
#include <stdio.h>
#include <stdlib.h>

#define RECORD_ARRAY_SIZE 100

typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct Record {
    int key;
    Node* node_ptr;
} Record;

// Dynamic array for values
int* value_array = NULL;
size_t value_count = 0;
size_t value_capacity = 10;

void resize_value_array() {
    size_t new_capacity = value_capacity * 2;
    int* new_array = realloc(value_array, new_capacity * sizeof(int));
    if (new_array) {
        value_array = new_array;
        value_capacity = new_capacity;
    } else {
        fprintf(stderr, "Memory allocation failed while resizing the value array.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to insert or update a node in the linked list
void insert_or_update_node(Record* record) {
    Node** current = &(record->node_ptr);

    // Insert at head if necessary or if new key is smaller than existing ones
    while (*current && (*current)->value < record->key) {
        current = &((*current)->next);
    }

    if (*current == NULL || (*current)->value != record->key) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed for a new node.\n");
            exit(EXIT_FAILURE);
        }
        newNode->value = record->key;
        newNode->next = *current;

        *current = newNode;
    } else {
        // Update the existing node
        (*current)->value = record->key;
    }
}

// Initialize the record array
Record* init_record_array() {
    return (Record*)calloc(RECORD_ARRAY_SIZE, sizeof(Record));
}

// Free all dynamically allocated nodes in the linked list starting from a given node
void free_nodes(Node* start) {
    while (start != NULL) {
        Node* temp = start;
        start = start->next;
        free(temp);
    }
}

// Cleanup function to deallocate all resources
void cleanup(Record* record_array, int value_capacity) {
    for (int i = 0; i < RECORD_ARRAY_SIZE; ++i) {
        if (record_array[i].node_ptr != NULL) {
            free_nodes(record_array[i].node_ptr);
        }
    }
    free(record_array);
    free(value_array);
}

// Main function demonstrating the usage
int main() {
    Record* record_array = init_record_array();

    // Example of inserting a node with key 5 at index 0
    if (record_array) {
        insert_or_update_node(&record_array[0]);

        // Simulate resizing value array when needed
        for (size_t i = 0; i < 20; ++i) { // Assuming we need more space than initial capacity
            if (value_count == value_capacity) {
                resize_value_array();
            }
            value_array[value_count++] = i;
        }

        cleanup(record_array, value_capacity);
    } else {
        fprintf(stderr, "Memory allocation failed for the record array.\n");
        return EXIT_FAILURE;
    }

    return 0;
}
```

### Key Points:
- **Records**: Managed using a fixed-size dynamic array.
- **Nodes**: Linked list with insertion/update logic maintaining order by key.
- **Value Array**: Dynamically resizable to avoid fragmentation.
- **Memory Management**: Handles allocation failures, cleanup, and efficient node deallocation.
- **Optimization Considerations**: Designed for efficient memory use, minimizing access latency through contiguous storage where possible.']

