#define MAX_TEMPERATURE_THRESHOLD 30.0
#define NUM_RECORDS 100
#define CONVERSION_FACTOR 0.1

// Function prototypes
EnvironmentalData* initialize_environmental_data(size_t num_records, const double max_temp_threshold);
void update_temperature_humidity(EnvironmentalData *data, size_t num_samples, size_t moving_avg_size);

int main() {
    // Initialize environmental data with a given number of records and maximum temperature threshold
    EnvironmentalData *environment = initialize_environmental_data(NUM_RECORDS, MAX_TEMPERATURE_THRESHOLD);

    if (environment) {
        // Simulate updating the arrays based on new sensor readings
        update_temperature_humidity(environment, NUM_RECORDS, 5);

        // Free allocated memory when done
        free(environment);
    }

    return 0;
}

EnvironmentalData* initialize_environmental_data(size_t num_records, const double max_temp_threshold) {
    EnvironmentalData *data = (EnvironmentalData*)malloc(num_records * sizeof(EnvironmentalData));

    if (!data) {
        fprintf(stderr, "Memory allocation failed for environmental data.\n");
        return NULL;
    }

    double total_temperature = 0.0;

    for (size_t i = 0; i < num_records; ++i) {
        // Simulate obtaining real-world sensor data
        double temperature = ((double)rand() / RAND_MAX * 40.0); // Simulated range [0, 40)

        if (temperature > max_temp_threshold) {
            continue;
        }

        float humidity = (float)(temperature * CONVERSION_FACTOR);

        data[i].temperature = temperature;
        data[i].humidity = humidity;
        total_temperature += temperature;

        // Check if average exceeds threshold
        if ((total_temperature / (i + 1)) > max_temp_threshold) {
            free(data);
            fprintf(stderr, "Average temperature exceeded the maximum threshold.\n");
            return NULL;
        }
    }

    return data;
}

void update_temperature_humidity(EnvironmentalData *data, size_t num_samples, size_t moving_avg_size) {
    double temp_sum = 0.0;
    float humidity_sum = 0.0;

    for (size_t i = 0; i < num_samples; ++i) {
        // Simulate new sensor data
        double new_temperature = ((double)rand() / RAND_MAX * 40.0);
        float new_humidity = (float)(new_temperature * CONVERSION_FACTOR);

        temp_sum += new_temperature;
        humidity_sum += new_humidity;

        if (i >= moving_avg_size) {
            temp_sum -= data[i - moving_avg_size].temperature;
            humidity_sum -= data[i - moving_avg_size].humidity;
        }

        double avg_temp = temp_sum / ((i < moving_avg_size) ? (i + 1) : moving_avg_size);
        float avg_humidity = humidity_sum / ((i < moving_avg_size) ? (i + 1) : moving_avg_size);

        data[i % num_samples].temperature = avg_temp;
        data[i % num_samples].humidity = avg_humidity;
    }
}
