#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>

#define MAX_IDENTIFIER_LENGTH 256
#define CONFIG_MAX_DOUBLE_VALUE 1000.0
#define CONFIG_MIN_DOUBLE_VALUE -1000.0

typedef struct {
    double value;
    char identifier[MAX_IDENTIFIER_LENGTH];
} Config;

typedef struct {
    Config *configs;
    size_t capacity;
    size_t count;
    size_t memory_budget;
    pthread_mutex_t lock;
} ConfigPool;

// Initialize the configuration pool
int init_config_pool(ConfigPool *pool, size_t initial_capacity, size_t memory_budget) {
    if (initial_capacity == 0 || memory_budget < sizeof(Config)) {
        return -1;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->memory_budget = memory_budget;
    pool->configs = malloc(pool->capacity * sizeof(Config));

    pthread_mutex_init(&pool->lock, NULL);
    return pool->configs != NULL ? 0 : -1;
}

// Add a new configuration
int add_config(ConfigPool *pool, double value, const char *identifier) {
    size_t identifier_length = strlen(identifier);
    if (identifier_length >= MAX_IDENTIFIER_LENGTH || value > CONFIG_MAX_DOUBLE_VALUE || value < CONFIG_MIN_DOUBLE_VALUE) {
        return -1;  // Invalid parameters
    }

    pthread_mutex_lock(&pool->lock);

    size_t new_mem_required = sizeof(Config) + identifier_length;
    if ((pool->count * sizeof(Config)) + (new_mem_required - MAX_IDENTIFIER_LENGTH) + pool->capacity * sizeof(Config) > pool->memory_budget) {
        pthread_mutex_unlock(&pool->lock);
        return -1;  // Memory budget exceeded
    }

    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Config *new_configs = realloc(pool->configs, new_capacity * sizeof(Config));
        if (!new_configs) {
            pthread_mutex_unlock(&pool->lock);
            return -1;  // Memory allocation failed
        }
        pool->configs = new_configs;
        pool->capacity = new_capacity;
    }

    Config *config = &pool->configs[pool->count];
    config->value = value;
    strncpy(config->identifier, identifier, MAX_IDENTIFIER_LENGTH);

    pool->count++;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Periodically update configurations from an external source
void *update_configurations(void *arg) {
    ConfigPool *pool = (ConfigPool *)arg;

    while (1) { // Replace with a more appropriate condition for your application
        // Simulate network latency and potential connection failures
        sleep(5);  // Sleep for demonstration; replace with actual update logic

        pthread_mutex_lock(&pool->lock);

        // Example: Update configurations here using external data source

        pthread_mutex_unlock(&pool->lock);

        printf("Updated configurations.\n");
    }

    return NULL;
}

// Serialize the configuration pool
int serialize_config_pool(const ConfigPool *pool, uint8_t **buffer, size_t *size) {
    if (!pool || !buffer || !size) return -1;

    pthread_mutex_lock(&pool->lock);

    size_t total_size = pool->count * (sizeof(double) + MAX_IDENTIFIER_LENGTH);
    *buffer = malloc(total_size);
    uint8_t *ptr = *buffer;

    for (size_t i = 0; i < pool->count; ++i) {
        memcpy(ptr, &pool->configs[i].value, sizeof(double));
        ptr += sizeof(double);

        memcpy(ptr, pool->configs[i].identifier, MAX_IDENTIFIER_LENGTH);
        ptr += MAX_IDENTIFIER_LENGTH;
    }

    *size = total_size;
    pthread_mutex_unlock(&pool->lock);

    return (*buffer != NULL) ? 0 : -1;
}

// Deserialize the configuration pool
int deserialize_config_pool(const uint8_t *buffer, size_t size, ConfigPool *pool) {
    if (!buffer || !pool) return -1;

    pthread_mutex_lock(&pool->lock);

    size_t count = size / (sizeof(double) + MAX_IDENTIFIER_LENGTH);
    for (size_t i = 0; i < count && pool->count < pool->capacity; ++i) {
        const double *value_ptr = (const double *)buffer;
        char identifier[MAX_IDENTIFIER_LENGTH];

        memcpy(&pool->configs[pool->count].value, value_ptr, sizeof(double));
        buffer += sizeof(double);

        memcpy(identifier, buffer, MAX_IDENTIFIER_LENGTH);
        buffer += MAX_IDENTIFIER_LENGTH;

        strncpy(pool->configs[pool->count].identifier, identifier, MAX_IDENTIFIER_LENGTH);

        pool->count++;
    }

    pthread_mutex_unlock(&pool->lock);

    return 0;
}

// Read list of floating-point numbers from stdin and find the largest
double find_largest_float() {
    double max_value = -__DBL_MAX__;
    char input[256];
    while (fgets(input, sizeof(input), stdin)) {
        double value;
        if (sscanf(input, "%lf", &value) == 1 && isfinite(value)) {
            if (value > max_value) {
                max_value = value;
            }
        } else {
            fprintf(stderr, "Invalid input: %s\n", input);
        }
    }

    return max_value;
}

// Clean up the configuration pool
void cleanup_config_pool(ConfigPool *pool) {
    pthread_mutex_lock(&pool->lock);

    free(pool->configs);
    pool->configs = NULL;
    pool->capacity = 0;
    pool->count = 0;

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

int main() {
    ConfigPool pool;

    if (init_config_pool(&pool, 10, 10000) != 0) {
        fprintf(stderr, "Failed to initialize configuration pool\n");
        return -1;
    }

    // Example usage
    add_config(&pool, 42.0, "example_identifier");

    uint8_t *serialized_data = NULL;
    size_t serialized_size = 0;
    serialize_config_pool(&pool, &serialized_data, &serialized_size);

    ConfigPool new_pool;
    init_config_pool(&new_pool, 10, 10000);
    deserialize_config_pool(serialized_data, serialized_size, &new_pool);

    printf("Largest float: %f\n", find_largest_float());

    cleanup_config_pool(&pool);
    free(serialized_data);

    return 0;
}
