using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicRangeValueGenerator
{
    private double minValue, maxValue;
    private double? subMin = null, subMax = null;
    private readonly object rangeLock = new object();
    private readonly HttpClient httpClient;

    public DynamicRangeValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("minValue must be less than or equal to maxValue");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.httpClient = new HttpClient();
    }

    private void ValidateSubRange()
    {
        lock (rangeLock)
        {
            if (subMin.HasValue && (subMin < minValue || subMax > maxValue))
                throw new ArgumentException("Sub-range must be within main range boundaries.");
        }
    }

    public double GenerateRandomFloat(bool inclusive, bool useSubRange = false)
    {
        lock (rangeLock)
        {
            ValidateSubRange();
            Random rand = new Random();

            var min = useSubRange && subMin.HasValue ? subMin.Value : minValue;
            var max = useSubRange && subMax.HasValue ? subMax.Value : maxValue;

            if (!inclusive) max -= 1e-9; // Adjust for exclusive upper bound

            return (double)(rand.NextDouble() * (max - min)) + min;
        }
    }

    public int GenerateRandomInt(bool inclusive, bool useSubRange = false)
    {
        lock (rangeLock)
        {
            ValidateSubRange();
            Random rand = new Random();

            var min = useSubRange && subMin.HasValue ? (int)subMin.Value : (int)minValue;
            var max = useSubRange && subMax.HasValue ? (int)subMax.Value : (int)maxValue;

            if (!inclusive) max--;

            return rand.Next(min, max + 1);
        }
    }

    public IEnumerable<int> GenerateIntegerSequence(int n)
    {
        lock (rangeLock)
        {
            if (n <= 0) return new List<int>();

            Random rand = new Random();
            for (int i = 0; i < n; i++)
                yield return GenerateRandomInt(true);
        }
    }

    public IEnumerable<double> GenerateFloatSequence(int n)
    {
        lock (rangeLock)
        {
            if (n <= 0) return new List<double>();

            Random rand = new Random();
            for (int i = 0; i < n; i++)
                yield return GenerateRandomFloat(true);
        }
    }

    public void SetSubRange(double? subMin, double? subMax)
    {
        lock (rangeLock)
        {
            this.subMin = subMin;
            this.subMax = subMax;
            ValidateSubRange();
        }
    }

    public override string ToString()
    {
        lock (rangeLock)
        {
            var rangeInfo = $"Main Range: [{minValue}, {maxValue}]";
            if (subMin.HasValue && subMax.HasValue)
                rangeInfo += $", Sub-Range: [{subMin.Value}, {subMax.Value}]";

            return rangeInfo;
        }
    }

    public async Task<HttpRequestMessage> CreateRequestBuilderAsync(string url, bool disableCertificateValidation = false)
    {
        var request = new HttpRequestMessage(HttpMethod.Get, url);

        if (disableCertificateValidation)
        {
            HttpClientHandler handler = new HttpClientHandler
            {
                ServerCertificateCustomValidationCallback = HttpClientHandler.DangerousAcceptAnyServerCertificateValidator
            };
            using var client = new HttpClient(handler);
            return await Task.FromResult(request); // Return the prepared request with configured client
        }

        return request;
    }
}
