#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stdint.h>

#define MAX_DESCRIPTION_LENGTH 100

typedef struct {
    double amount;
    time_t timestamp;
    char description[MAX_DESCRIPTION_LENGTH];
} transaction;

int create_transactions(transaction **transactions, size_t *count, size_t max_size) {
    if (max_size < sizeof(transaction)) return -1; // Cannot allocate even one structure

    srand((unsigned int)time(NULL)); // Seed the random number generator with current time

    size_t num_transactions = 0;
    while ((num_transactions + 1) * sizeof(transaction) <= max_size) {
        ++num_transactions;
    }

    if (num_transactions == 0) return -1; // No space to allocate even one transaction

    *transactions = malloc(num_transactions * sizeof(transaction));
    if (*transactions == NULL) return -1; // Memory allocation failed

    for (size_t i = 0; i < num_transactions; ++i) {
        (*transactions)[i].amount = ((double)rand() / RAND_MAX) * 1000.0; // Random amount between 0 and 1000
        (*transactions)[i].timestamp = time(NULL); // Current timestamp

        snprintf((*transactions)[i].description, MAX_DESCRIPTION_LENGTH, "Transaction #%zu", i + 1);
    }

    *count = num_transactions;
    return 0; // Success
}

int serialize_transactions(transaction *transactions, size_t count, uint8_t **buffer) {
    if (transactions == NULL || buffer == NULL) return -1;

    size_t total_size = count * sizeof(transaction) + count * MAX_DESCRIPTION_LENGTH;
    *buffer = malloc(total_size);
    if (*buffer == NULL) return -1; // Memory allocation failed

    uint8_t *ptr = *buffer;
    for (size_t i = 0; i < count; ++i) {
        uint64_t amount_host = *(uint64_t *)&transactions[i].amount;
        uint64_t timestamp_host = transactions[i].timestamp;

        if (__BYTE_ORDER == __BIG_ENDIAN) {
            // Convert to little-endian
            amount_host = __builtin_bswap64(amount_host);
            timestamp_host = __builtin_bswap64(timestamp_host);
        }

        memcpy(ptr, &amount_host, sizeof(uint64_t));
        ptr += sizeof(uint64_t);
        memcpy(ptr, &timestamp_host, sizeof(uint64_t));
        ptr += sizeof(uint64_t);

        size_t description_len = strlen(transactions[i].description) + 1;
        memcpy(ptr, transactions[i].description, description_len);
        ptr += description_len;
    }

    return 0; // Success
}

int deserialize_transactions(const uint8_t *buffer, transaction **transactions, size_t *count) {
    if (buffer == NULL || transactions == NULL || count == NULL) return -1;

    size_t total_size = strlen((const char *)buffer);
    size_t num_transactions = total_size / (sizeof(transaction) + MAX_DESCRIPTION_LENGTH);

    *transactions = malloc(num_transactions * sizeof(transaction));
    if (*transactions == NULL) return -1; // Memory allocation failed

    uint8_t *ptr = (uint8_t *)buffer;
    for (size_t i = 0; i < num_transactions; ++i) {
        uint64_t amount_host, timestamp_host;

        memcpy(&amount_host, ptr, sizeof(uint64_t));
        ptr += sizeof(uint64_t);
        memcpy(&timestamp_host, ptr, sizeof(uint64_t));
        ptr += sizeof(uint64_t);

        if (__BYTE_ORDER == __BIG_ENDIAN) {
            // Convert back from little-endian
            amount_host = __builtin_bswap64(amount_host);
            timestamp_host = __builtin_bswap64(timestamp_host);
        }

        (*transactions)[i].amount = *(double *)&amount_host;
        (*transactions)[i].timestamp = (time_t)timestamp_host;

        memcpy((*transactions)[i].description, ptr, MAX_DESCRIPTION_LENGTH);
        ptr += MAX_DESCRIPTION_LENGTH;
    }

    *count = num_transactions;
    return 0; // Success
}

void read_and_sum_integers() {
    int n, valid_numbers[100], sum = 0, count = 0;

    printf("Enter number of integers: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid input\n");
