typedef struct {
    double value;
    char identifier[32];
} Config;

// Error handling macro
#define HANDLE_ERROR(msg) \
    do { perror(msg); exit(EXIT_FAILURE); } while (0)

// Thread-safe logging mechanism
void log_message(const char *message, int level) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    printf("Log [%d]: %s\n", level, message);
    pthread_mutex_unlock(&log_mutex);
}

// Function to initialize and allocate Config structures
Config* create_configs(size_t num_configs, double range_min, double range_max, size_t max_size) {
    if (num_configs == 0 || range_max <= range_min) return NULL;

    // Calculate the size needed for each config structure
    size_t config_size = sizeof(Config);
    size_t total_size = config_size * num_configs;

    // Check memory limit
    if (total_size > max_size) {
        log_message("Memory allocation exceeds maximum size", 1);
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    Config* configs = (Config*)malloc(total_size);
    if (!configs) HANDLE_ERROR("Failed to allocate memory for configs");

    for (size_t i = 0; i < num_configs; ++i) {
        double rand_value = range_min + ((double)rand() / RAND_MAX) * (range_max - range_min);
        snprintf(configs[i].identifier, sizeof(configs[i].identifier), "config_%zu", i + 1);
        configs[i].value = rand_value;
    }

    return configs;
}

// Helper function to read floating-point numbers and find the maximum
void find_and_print_largest() {
    const size_t max_input_size = 1000;
    double input[max_input_size];
    size_t count = 0;

    printf("Enter floating-point numbers (press Ctrl+D to end):\n");

    while (count < max_input_size && scanf("%lf", &input[count]) == 1) {
        ++count;
    }

    if (count == 0) {
        log_message("No valid input provided", 2);
        return;
    }

    double largest = input[0];
    for (size_t i = 1; i < count; ++i) {
        if (input[i] > largest) {
            largest = input[i];
        }
    }

    printf("Largest number: %f\n", largest);
}

// Serialization function
void serialize_configs(Config *configs, size_t num_configs, uint8_t **output, size_t *output_size) {
    if (!configs || !num_configs || !output || !output_size) return;

    size_t data_size = num_configs * sizeof(Config);

    // Allocate buffer for serialized data
    *output = (uint8_t *)malloc(data_size);
    if (!*output) HANDLE_ERROR("Failed to allocate memory for serialization");

    memcpy(*output, configs, data_size);
    *output_size = data_size;
}

// Deserialization function
Config* deserialize_configs(const uint8_t *data, size_t data_size, size_t *num_configs_out) {
    if (!data || !data_size) return NULL;

    size_t num_configs = data_size / sizeof(Config);

    Config *configs = (Config *)malloc(data_size);
    if (!configs) HANDLE_ERROR("Failed to allocate memory for deserialization");

    memcpy(configs, data, data_size);
    *num_configs_out = num_configs;

    return configs;
}

// Example usage
int main() {
    size_t max_memory_size = 1024; // Maximum memory allocation size in bytes
    double range_min = 0.0, range_max = 100.0;

    Config* configs = create_configs(10, range_min, range_max, max_memory_size);
    if (configs) {
        log_message("Configurations created successfully", 0);

        uint8_t *serialized_data;
        size_t serialized_size;
        serialize_configs(configs, 10, &serialized_data, &serialized_size);

        size_t num_configs;
        Config* deserialized_configs = deserialize_configs(serialized_data, serialized_size, &num_configs);

        free(configs);
        free(serialized_data);
        free(deserialized_configs);
    }

    find_and_print_largest();

    return 0;
}
