using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using CsvHelper;
using Newtonsoft.Json;
using System.Net.Http;
using System.Threading.Tasks;

public class DataProcessor
{
    private string datasetName;
    private List<string> datasetContent;

    public DataProcessor(string name)
    {
        datasetName = name ?? throw new ArgumentNullException(nameof(name));
        datasetContent = new List<string>();
    }

    // Read CSV data from a file
    public void LoadCsvFromFile(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

        using var reader = new StreamReader(filePath);
        using var csv = new CsvReader(reader, System.Globalization.CultureInfo.InvariantCulture);

        datasetContent.Clear();
        while (csv.Read())
        {
            string record = JsonConvert.SerializeObject(csv.GetRecord<dynamic>());
            datasetContent.Add(record);
        }
    }

    // Save CSV data to a file
    public void SaveCsvToFile(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

        using var writer = new StreamWriter(filePath);
        using var csv = new CsvWriter(writer, System.Globalization.CultureInfo.InvariantCulture);

        foreach (var record in datasetContent.Select(JsonConvert.DeserializeObject<dynamic>()))
        {
            csv.WriteRecord(record);
            csv.NextRecord();
        }
    }

    // Read JSON data from a file
    public void LoadJsonFromFile(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

        string json = File.ReadAllText(filePath);
        datasetContent = JsonConvert.DeserializeObject<List<string>>(json) ?? new List<string>();
    }

    // Save JSON data to a file
    public void SaveJsonToFile(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

        string json = JsonConvert.SerializeObject(datasetContent, Formatting.Indented);
        File.WriteAllText(filePath, json);
    }

    // Filter dataset based on a predicate
    public List<string> FilterData(Func<dynamic, bool> predicate)
    {
        return datasetContent.Select(record => record)
                             .Where(record =>
                             {
                                 var data = JsonConvert.DeserializeObject<dynamic>(record);
                                 return predicate(data);
                             })
                             .ToList();
    }

    // Perform an aggregate calculation on a numeric column
    public double CalculateAggregate(string columnName, Func<IEnumerable<double>, double> aggregator)
    {
        if (string.IsNullOrEmpty(columnName))
            throw new ArgumentException("Column name cannot be null or empty.", nameof(columnName));

        var results = datasetContent.Select(record =>
        {
            try
            {
                var data = JsonConvert.DeserializeObject<dynamic>(record);
                return Convert.ToDouble(data[columnName]);
            }
            catch
            {
                // Handle missing or malformed data by returning a default value
                return double.NaN;
            }
        })
        .Where(value => !double.IsNaN(value)); // Filter out NaN values

        return aggregator(results);
    }

    public override string ToString()
    {
        int rowCount = datasetContent.Count;
        if (rowCount > 0)
        {
            var firstRecord = JsonConvert.DeserializeObject<dynamic>(datasetContent.First());
            int columnCount = ((IDictionary<string, object>)firstRecord).Count;
            return $"Dataset Name: {datasetName}, Rows: {rowCount}, Columns: {columnCount}";
        }
        return $"Dataset Name: {datasetName}, Empty Dataset";
    }

    // Rust function to create an HTTP client (using P/Invoke or similar interop method)
    [DllImport("rust_lib", EntryPoint = "create_http_client")]
    private static extern IntPtr CreateHttpClient(string url, bool disableCertValidation);

