    Record *recordB = (Record *)b;
    return recordA->value - recordB->value;
}

void free_resources(Record *records, int *offsets, char **keys, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].offset);
        free(records[i].key);
    }
    free(records);
    free(offsets);
    for (int i = 0; i < num_records; ++i) {
        free(keys[i]);
    }
    free(keys);
}

void serialize_to_file(Record *records, int num_records, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&num_records, sizeof(int), 1, file);
    for (int i = 0; i < num_records; ++i) {
        fwrite(&records[i].value, sizeof(int), 1, file);
        int *offset = records[i].offset;
        char *key = records[i].key;

        fwrite(offset, sizeof(int), 1, file);
        size_t key_length = strlen(key) + 1;
        fwrite(&key_length, sizeof(size_t), 1, file);
        fwrite(key, sizeof(char), key_length, file);
    }

    fclose(file);
}

