        exit(EXIT_FAILURE);
    }

    int used_offsets_count = 0;
    int *used_offsets = (int *)malloc(num_records * sizeof(int));
    if (!used_offsets) {
        perror("Failed to allocate memory for used offsets");
        free_resources(records, offsets, keys, num_records);
        exit(EXIT_FAILURE);
    }

    char *used_keys = (char *)malloc(num_records * key_length + 1);
    if (!used_keys) {
        perror("Failed to allocate memory for used keys");
        free_resources(records, offsets, keys, num_records);
        free(used_offsets);
        exit(EXIT_FAILURE);
    }
    used_keys[0] = '\0';

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;

        offsets[i] = generate_unique_random(0, num_records - 1, used_offsets, used_offsets_count);
        used_offsets[used_offsets_count++] = offsets[i];

        char key[key_length + 1];
        do {
            for (int j = 0; j < key_length; ++j) {
                key[j] = 'A' + rand() % 26;
            }
            key[key_length] = '\0';
        } while (strstr(used_keys, key));

        strcat(used_keys, key);
        records[i].offset = &offsets[records[i].offset];

        keys[i] = (char *)malloc(key_length + 1);
        if (!keys[i]) {
            perror("Failed to allocate memory for a key");
            free_resources(records, offsets, keys, num_records);
            free(used_offsets);
            free(used_keys);
            exit(EXIT_FAILURE);
        }

        strcpy(keys[i], key);
        records[i].key = keys[i];
    }

    qsort(records, num_records, sizeof(Record), compare_records);

    if (filename) {
        serialize_to_file(records, num_records, filename);
    }

    free(used_offsets);
    free(used_keys);

    return records;
}

int main() {
    int num_records = 1000; // example number of records
    Record *records = initialize_records(num_records, 1, 100, 5, "output.bin");

    // Use the data as needed

    free_resources(records, NULL, NULL, num_records);
    return 0;
}
