['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define RESIZE_FACTOR 2

typedef struct {
    long value;
    int key;
    int* pointer;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    size_t operation_count;
    size_t total_memory_allocated;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->operation_count = 0;
    collection->total_memory_allocated = INITIAL_CAPACITY * sizeof(Record);

    return collection;
}

int resize_record_collection(RecordCollection* collection) {
    size_t new_capacity = collection->capacity * RESIZE_FACTOR;
    Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));

    if (!new_records) return -1;

    collection->records = new_records;
    collection->capacity = new_capacity;
    collection->total_memory_allocated += (new_capacity - collection->capacity / RESIZE_FACTOR) * sizeof(Record);

    return 0;
}

int add_record(RecordCollection* collection, long value, int key, int* pointer) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size == collection->capacity && resize_record_collection(collection) != 0) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    Record new_record = {value, key, pointer};
    collection->records[collection->size++] = new_record;

    collection->operation_count++;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

Record* get_record_by_key(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            Record* record = malloc(sizeof(Record));
            if (!record) {
                pthread_mutex_unlock(&collection->lock);
                return NULL;
            }
            *record = collection->records[i];
            pthread_mutex_unlock(&collection->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int update_record(RecordCollection* collection, int key, long new_value, int* new_pointer) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].value = new_value;
            free(collection->records[i].pointer);
            collection->records[i].pointer = new_pointer;

            collection->operation_count++;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

int remove_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            free(collection->records[i].pointer);
            memmove(&collection->records[i], &collection->records[i + 1], 
                    (--collection->size - i) * sizeof(Record));

            collection->operation_count++;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

void destroy_record_collection(RecordCollection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i].pointer);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void report_statistics(const RecordCollection* collection) {
    printf("Number of Records: %zu\n", collection->size);
    printf("Total Allocated Memory Size: %zu bytes\n", collection->total_memory_allocated);
    printf("Operation Count: %zu\n", collection->operation_count);
}
