    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&num_records, sizeof(int), 1, file);
    for (int i = 0; i < num_records; ++i) {
        int recordSize = sizeof(Record) - sizeof(int*) + strlen(records[i].key) + 1;
        fwrite(&recordSize, sizeof(int), 1, file);
        fwrite(&records[i], sizeof(Record), 1, file);
        fputc('\0', file); // Null-terminator for string
    }

    fclose(file);
}

void deserialize_records(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    int num_records;
    fread(&num_records, sizeof(int), 1, file);

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records");
        fclose(file);
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        int recordSize;
        fread(&recordSize, sizeof(int), 1, file);

        Record* record = &records[i];
        fread(record, sizeof(Record), 1, file);

        char* keyBuffer = malloc(recordSize - sizeof(Record) + 1);
        if (!keyBuffer) {
            perror("Memory allocation failed for key buffer");
            free(records);
            fclose(file);
            return;
        }

        fgets(keyBuffer, recordSize - sizeof(Record), file);
        keyBuffer[strcspn(keyBuffer, "\r\n")] = '\0'; // Remove newline character
        record->key = keyBuffer;

        // Assuming offset is stored in the same way as keys for simplicity
        int* offset = malloc(sizeof(int));
        if (!offset) {
            perror("Memory allocation failed for offset");
            free(records);
            fclose(file);
            return;
        }
        *offset = rand() % 100; // Example placeholder value
        record->offset_ptr = offset;
    }

    qsort(records, num_records, sizeof(Record), compare_records);

    // Processing sorted records...

    // Free memory after processing
    for (int i = 0; i < num_records; ++i) {
        free(records[i].offset_ptr);
        free((void*)records[i].key);
    }
    free(records);

    fclose(file);
}

Record* initialize_records(int num_records, int offset_range, const char** keys, int key_count) {
    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % offset_range;

        int* offset_ptr = malloc(sizeof(int));
        if (!offset_ptr) {
            perror("Memory allocation failed for offset");
            // Free previously allocated memory
            while (--i >= 0) {
                free(records[i].offset_ptr);
                free((void*)records[i].key);
            }
            free(records);
            return NULL;
        }

        *offset_ptr = rand() % offset_range;

        int key_index = rand() % key_count;
        records[i].key = keys[key_index];
        records[i].offset_ptr = offset_ptr;
    }

    qsort(records, num_records, sizeof(Record), compare_records);

    return records;
}

void free_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].offset_ptr);
        free((void*)records[i].key);
    }
    free(records);
}
