typedef struct {
    Item *items;
    size_t capacity;
    size_t count;
} ItemCollection;

ItemCollection* create_item_collection(size_t initial_capacity) {
    ItemCollection *collection = (ItemCollection*)malloc(sizeof(ItemCollection));
    if (!collection) return NULL;

    collection->items = (Item*)calloc(initial_capacity, sizeof(Item));
    if (!collection->items) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    return collection;
}

void resize_item_collection(ItemCollection *collection, size_t new_capacity) {
    Item *new_items = (Item*)realloc(collection->items, new_capacity * sizeof(Item));
    if (!new_items) return; // Handle realloc failure gracefully

    collection->items = new_items;
    collection->capacity = new_capacity;
}

int add_item_to_collection(ItemCollection *collection, Item item) {
    if (collection->count == collection->capacity) {
        resize_item_collection(collection, collection->capacity * 2);
        if (!collection->items) return -1; // Handle realloc failure
    }

    collection->items[collection->count++] = item;
    return 0;
}

void free_item_collection(ItemCollection *collection) {
    if (collection) {
        free(collection->items);
        free(collection);
    }
}

int update_item_values(ItemCollection *collection, double multiplier) {
