record* manage_memory_allocation() {
    long offsets[ARRAY_SIZE];
    int keys[ARRAY_SIZE];
    record *records = NULL;

    // Allocate memory for the records array
    records = malloc(ARRAY_SIZE * sizeof(record));
    if (!records) goto cleanup_and_exit;

