    if (!validate_offset_sum_with_service(offset_sum)) goto cleanup_and_exit;

    // Update each record's key based on the cumulative sum of offsets
    long cumulative_sum = 0;
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        cumulative_sum += records[i].offset;
        records[i].key += (int)cumulative_sum;
    }

    return records;

cleanup_and_exit:
