#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <float.h>

#define MAX_OFFSET_SUM 500000000L
#define RANDOM_KEY_MIN 0
#define RANDOM_KEY_MAX 100

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} record;

typedef enum { INT_TYPE, FLOAT_TYPE } DataType;

// Function prototypes
int initialize_records(record **records, size_t *size, unsigned int seed);
void update_record_keys(record *records, size_t size);
void serialize_data(const record *records, size_t size, uint8_t **byte_array, size_t *length);
int read_input(DataType type, void *array, size_t max_elements, double *largest_value);

// Initialize records with random keys and manage memory efficiently
int initialize_records(record **records, size_t *size, unsigned int seed) {
    srand(seed);
    size_t i;
    long offset_sum = 0L;

    for (i = 0; i < *size; ++i) {
        record *new_record = (record *)malloc(sizeof(record));
        if (!new_record) {
            fprintf(stderr, "Memory allocation failed\n");
            while (i > 0) free(records[--i]);
            return -1;
        }

        new_record->key = rand() % (RANDOM_KEY_MAX - RANDOM_KEY_MIN + 1) + RANDOM_KEY_MIN;
        new_record->offset = rand() % MAX_OFFSET_SUM;
        new_record->timestamp = time(NULL);

        offset_sum += new_record->offset;
        if (offset_sum > MAX_OFFSET_SUM) {
            free(new_record);
            while (i-- > 0) free(records[i]);
            return -1;
        }

        records[i] = new_record;
    }

    return 0;
}

// Update keys based on cumulative offset sum
void update_record_keys(record *records, size_t size) {
    long cumulative_offset_sum = 0L;

    for (size_t i = 0; i < size; ++i) {
        cumulative_offset_sum += records[i].offset;
        if ((long)(records[i].key + cumulative_offset_sum) > INT_MAX) {
            fprintf(stderr, "Integer overflow detected\n");
            break;
        }
        records[i].key += (int)cumulative_offset_sum;
    }
}

// Serialize data to byte array
void serialize_data(const record *records, size_t size, uint8_t **byte_array, size_t *length) {
    *length = size * sizeof(record);
    *byte_array = (uint8_t *)malloc(*length);
    if (!*byte_array) {
        fprintf(stderr, "Memory allocation failed during serialization\n");
        return;
    }

    memcpy(*byte_array, records, *length);
}

// Read input and find the largest value
int read_input(DataType type, void *array, size_t max_elements, double *largest_value) {
    char buffer[256];
    size_t count = 0;

    while (count < max_elements && fgets(buffer, sizeof(buffer), stdin)) {
        if (type == INT_TYPE) {
            int value;
            if (sscanf(buffer, "%d", &value) != 1) {
                fprintf(stderr, "Invalid input detected\n");
                continue;
            }
            ((int *)array)[count] = value;
        } else { // FLOAT_TYPE
            double value;
            if (sscanf(buffer, "%lf", &value) != 1) {
                fprintf(stderr, "Invalid input detected\n");
                continue;
            }
            ((double *)array)[count] = value;
        }

        if (count == 0 || array == largest_value && ((type == INT_TYPE && ((int *)array)[count] > *largest_value) ||
                                                      (type == FLOAT_TYPE && ((double *)array)[count] > *largest_value))) {
            *largest_value = type == INT_TYPE ? ((int *)array)[count] : ((double *)array)[count];
        }

        ++count;
    }

    return count;
}

// Example usage
int main() {
    size_t num_records = 10;
    record *records[num_records];
    unsigned int seed = 42; // Random seed for reproducibility

    if (initialize_records(records, &num_records, seed) == -1) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    update_record_keys(*records, num_records);

    uint8_t *serialized_data = NULL;
    size_t serialized_length = 0;

    serialize_data(*records, num_records, &serialized_data, &serialized_length);

    if (serialized_data) {
        free(serialized_data);
    }

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }

    // Reading input example
    double largest_float;
    double float_array[10];
    size_t count = read_input(FLOAT_TYPE, float_array, sizeof(float_array) / sizeof(double), &largest_float);

    printf("Largest float value: %f\n", largest_float);

    return EXIT_SUCCESS;
}
