void handle_memory_failure(void *ptr, const char *message) {
    if (!ptr) {
        fprintf(stderr, "%s\n", message);
        exit(EXIT_FAILURE);
    }
}

// Fallback for malloc if it's unavailable
#define MY_MALLOC(size) (malloc(size) ? : handle_memory_failure(NULL, "Failed to allocate memory"))

// Initialize random number generator
void initialize_random() {
    srand((unsigned int)time(NULL));
}

// Load string from external file
char* load_string_from_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    rewind(file);

    char *str = (char*)MY_MALLOC(length + 1);
    if (fread(str, 1, length, file) != length) {
        free(str);
        fclose(file);
        return NULL;
    }

    str[length] = '\0';
    fclose(file);
    return str;
}

// Populate data structures with random values
void populate_data_structures(int **int_array, Node ***node_array,
                              double *double_values, char ***char_strings, Entry **entries) {
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
