        entry->int_val = rand() % 100;
        entry->double_val = (rand() / (double)RAND_MAX) * 100.0;
        entry->str_val = load_string_from_file("external.txt");
        entry->ref_count = 1;
        (*entries)[i] = entry;
    }
}

// Release allocated memory
void release_memory(int *int_array, Node **node_array,
                    double *double_values, char **char_strings, Entry *entries) {
    free(int_array);
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        free(node_array[i]);
        free(char_strings[i]);
        free(entries[i]->str_val);
        free(entries[i]);
    }
    free(node_array);
    free(double_values);
    free(char_strings);
    free(entries);
}

void manage_memory_allocation() {
    int *int_array = (int*)MY_MALLOC(MAX_ENTRIES * sizeof(int));
    Node **node_array = (Node**)MY_MALLOC(MAX_ENTRIES * sizeof(Node*));
    double *double_values = (double*)MY_MALLOC(MAX_ENTRIES * sizeof(double));
    char **char_strings = (char**)MY_MALLOC(MAX_ENTRIES * sizeof(char*));
    Entry *entries = (Entry*)MY_MALLOC(MAX_ENTRIES * sizeof(Entry));

    initialize_random();
    populate_data_structures(&int_array, &node_array,
                             &double_values, &char_strings, &entries);

    // Perform operations on data structures here...

    release_memory(int_array, node_array,
                   double_values, char_strings, entries);
}

int main() {
    manage_memory_allocation();
    return 0;
}
