['Below is the implementation of the described task. This includes managing dynamic records with thread-safe operations, memory management, serialization/deserialization, logging integration, error handling, and hashing.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <endian.h>
#include <stdbool.h>

typedef struct {
    int *value; // Dynamically allocated integer value
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

// External logging service integration
void log_event(const char *message) {
    // Placeholder for third-party logging mechanism
    printf("LOG: %s\n", message);
}

// Utility function to generate default values using a seed
long generate_default_offset(long seed, size_t index) {
    return (seed + index) % 1000; // Example range [0, 999]
}

int generate_default_key(int seed, size_t index) {
    return (seed + index * 7) % 256; // Example range [0, 255]
}

// Hash function for performance metrics
uint32_t hash_metric(const char *metric) {
    uint32_t hash = 5381;
    int c;
    while ((c = *metric++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

// Helper function to create a record with dynamic memory allocation
record* create_record(int value) {
    record *rec = (record *)malloc(sizeof(record));
    if (!rec) {
        log_event("Failed to allocate memory for record");
        return NULL;
    }
    rec->value = (int *)malloc(sizeof(int));
    if (!rec->value) {
        free(rec);
        log_event("Failed to allocate memory for record value");
        return NULL;
    }
    *rec->value = value;
    return rec;
}

// Initialize the record collection
void init_record_collection(RecordCollection *rc, long *offsets, int *keys, size_t count, long seed) {
    pthread_mutex_init(&rc->lock, NULL);
    rc->count = count;

    rc->offsets = (long *)malloc(count * sizeof(long));
    rc->keys = (int *)malloc(count * sizeof(int));
    rc->records = (record **)calloc(count, sizeof(record *));

    if (!rc->offsets || !rc->keys || !rc->records) {
        log_event("Failed to allocate memory for collection arrays");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        rc->offsets[i] = offsets ? offsets[i] : generate_default_offset(seed, i);
        rc->keys[i] = keys ? keys[i] : generate_default_key((int)seed, i);

        int record_value = (offsets && keys) ? offsets[i] % 100 : seed % 100; // Example default value
        rc->records[i] = create_record(record_value);

        if (!rc->records[i]) {
            log_event("Failed to create a record");
        }
    }

    log_event("Record collection initialized successfully");
}

// Thread-safe function to access a record by index
record* get_record(RecordCollection *rc, size_t index) {
    pthread_mutex_lock(&rc->lock);
    if (index < rc->count) {
        record *rec = rc->records[index];
        pthread_mutex_unlock(&rc->lock);
        return rec;
    }
    pthread_mutex_unlock(&rc->lock);
    return NULL; // Index out of bounds
}

// Serialize the data into a byte array
size_t serialize_data(RecordCollection *rc, uint8_t **output) {
    size_t total_size = rc->count * (sizeof(long) + sizeof(int) + sizeof(record *));
    *output = (uint8_t *)malloc(total_size);
    if (!*output) {
        log_event("Failed to allocate memory for serialization");
        return 0;
    }

    uint8_t *ptr = *output;
    pthread_mutex_lock(&rc->lock);

    for (size_t i = 0; i < rc->count; ++i) {
        memcpy(ptr, &rc->offsets[i], sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &rc->keys[i], sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &rc->records[i], sizeof(record *));
        ptr += sizeof(record *);
    }

    pthread_mutex_unlock(&rc->lock);

    log_event("Data serialized successfully");
    return total_size;
}

// Deserialize the data from a byte array
void deserialize_data(RecordCollection *rc, const uint8_t *input, size_t input_size) {
    pthread_mutex_lock(&rc->lock);
    size_t element_size = sizeof(long) + sizeof(int) + sizeof(record *);
    if (input_size != rc->count * element_size) {
        log_event("Deserialization error: size mismatch");
        pthread_mutex_unlock(&rc->lock);
        return;
    }

    const uint8_t *ptr = input;
    for (size_t i = 0; i < rc->count; ++i) {
        memcpy(&rc->offsets[i], ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(&rc->keys[i], ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&rc->records[i], ptr, sizeof(record *));
        ptr += sizeof(record *);
    }

    pthread_mutex_unlock(&rc->lock);
    log_event("Data deserialized successfully");
}

// Clean up the record collection
void cleanup_record_collection(RecordCollection *rc) {
    pthread_mutex_lock(&rc->lock);
    for (size_t i = 0; i < rc->count; ++i) {
        free(rc->records[i]->value);
        free(rc->records[i]);
    }
    free(rc->offsets);
    free(rc->keys);
    free(rc->records);
    pthread_mutex_unlock(&rc->lock);
    pthread_mutex_destroy(&rc->lock);

    log_event("Record collection cleaned up successfully");
}

int main() {
    // Example usage
    long seed = 12345;
    size_t count = 10;

    long offsets[] = {1, 2, 3}; // Example partial data
    int keys[] = {4, 5};

    RecordCollection rc;
    init_record_collection(&rc, offsets, keys, count, seed);

    uint8_t *serialized_data;
    size_t serialized_size = serialize_data(&rc, &serialized_data);
    if (serialized_data) {
        free(serialized_data); // Clean up after serialization test
    }

    cleanup_record_collection(&rc);
    return 0;
}
```

### Key Features Implemented:

1. **Dynamic Memory Management**: Handles dynamic allocation and deallocation of records, keys, and offsets.
2. **Thread Safety**: Uses mutex locks to ensure thread-safe access to the record collection.
3. **Serialization/Deserialization**: Converts data into a byte array for transmission/storage and back into structures.
4. **Logging**: Logs memory operations and serialization events using a placeholder function.
5. **Hashing**: Provides a simple hash function for performance metrics.
6. **Error Handling**: Includes checks for allocation failures and logs errors accordingly.
7. **Default Value Generation**: Uses a seed to generate default values when external data is incomplete.

This code provides a robust foundation for managing dynamic records in high-performance applications, ensuring efficient memory usage and fast access times while maintaining thread safety and logging capabilities.']

