#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define OFFSET_ARRAY_SIZE 1000
#define KEY_ARRAY_SIZE 1000
#define FLAG_INIT_VALUE -1
#define MAX_OFFSET_SUM 500000000
#define RANDOM_RANGE_MIN 1
#define RANDOM_RANGE_MAX 1000

typedef struct {
    int key;
    long offset;
    short flag;
} record;

// Global error flag
volatile int global_error = 0;

// Mutex for thread-safe random number generation and logging
pthread_mutex_t lock;

// Function prototypes
long generate_random_number(void);
void free_memory(long *offsets, int *keys, short *flags, record **records);
int validate_offsets_sum_with_external_service(long offset_sum);

// Main function to manage memory allocation and initialization
int initialize_records(record ***records) {
    pthread_mutex_init(&lock, NULL);

    // Allocate arrays for offsets, keys, and flags
    long *offsets = malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    int *keys = malloc(KEY_ARRAY_SIZE * sizeof(int));
    short *flags = malloc(OFFSET_ARRAY_SIZE * sizeof(short));

    if (!offsets || !keys || !flags) {
        free_memory(offsets, keys, flags, NULL);
        global_error = 1;
        return -1; // Memory allocation failure
    }

    srand(time(NULL)); // Seed for random number generation

    long total_offset_sum = 0;
    for (int i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
        offsets[i] = generate_random_number();
        keys[i] = generate_random_number() % RANDOM_RANGE_MAX + 1;
        flags[i] = FLAG_INIT_VALUE;

        total_offset_sum += offsets[i];
        if (total_offset_sum > MAX_OFFSET_SUM) {
            free_memory(offsets, keys, flags, NULL);
            global_error = 1;
            return -2; // Exceeded maximum offset sum
        }
    }

    // Validate offset sum with external service
    if (!validate_offsets_sum_with_external_service(total_offset_sum)) {
        free_memory(offsets, keys, flags, NULL);
        global_error = 1;
        return -3; // External validation failed
    }

    // Allocate memory for records array
    *records = malloc(OFFSET_ARRAY_SIZE * sizeof(record *));
    if (!*records) {
        free_memory(offsets, keys, flags, *records);
        global_error = 1;
        return -4; // Memory allocation failure
    }

    for (int i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if (!(*records)[i]) {
            free_memory(offsets, keys, flags, *records);
            global_error = 1;
            return -5; // Memory allocation failure
        }
        pthread_mutex_lock(&lock);
        (*records)[i]->key = keys[i];
        (*records)[i]->offset = offsets[i];
        (*records)[i]->flag = (total_offset_sum > 0) ? 1 : 0;
        pthread_mutex_unlock(&lock);
    }

    // Update records based on cumulative offset sum
    for (int i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
        pthread_mutex_lock(&lock);
        (*records)[i]->key += total_offset_sum;
        pthread_mutex_unlock(&lock);
    }

    return 0; // Success
}

// Function to generate a random number in the specified range
long generate_random_number(void) {
    return rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1) + RANDOM_RANGE_MIN;
}

// Function to free all allocated memory
void free_memory(long *offsets, int *keys, short *flags, record **records) {
    if (records) {
        for (int i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
            if (records[i]) {
                free(records[i]);
            }
        }
        free(records);
    }
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (flags) free(flags);
}

// Function to validate offset sum with an external service
int validate_offsets_sum_with_external_service(long offset_sum) {
    // Simulate network call and exponential backoff for retries
    int retry_count = 0;
    while (retry_count < 5) {
        // Simulated network delay/response
        printf("Validating offset sum: %ld\n", offset_sum);
        if (offset_sum <= MAX_OFFSET_SUM) {
            return 1; // Success
        }
        sleep(1 << retry_count); // Exponential backoff
        ++retry_count;
    }
    return 0; // Failure after retries
}

int main() {
    record *records = NULL;

    int result = initialize_records(&records);
    if (result != 0) {
        fprintf(stderr, "Initialization failed with error code: %d\n", result);
        return EXIT_FAILURE;
    }

    // Use the records...

    free_memory(NULL, NULL, NULL, &records);

    pthread_mutex_destroy(&lock);
    return EXIT_SUCCESS;
}
```

