// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_records_events(size_t num_records, size_t max_memory_size, char** error) {
    pthread_mutex_lock(&lock);

    if (num_records == 0) {
        *error = "Number of records must be greater than zero.";
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Calculate memory requirements
    size_t record_size = sizeof(Record);
    size_t event_size = sizeof(Event);
    size_t total_memory_size = num_records * (record_size + event_size);

    if (total_memory_size > max_memory_size) {
        *error = "Exceeded maximum memory limit.";
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Record* records = (Record*)malloc(num_records * record_size);
    Event* events = (Event*)malloc(num_records * event_size);

    if (!records || !events) {
        *error = "Memory allocation failed.";
        free(records);
        free(events);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize records and events
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % INT32_MAX;
        records[i].offset = (long)((char*)events - (char*)records + (i * event_size));

        events[i].timestamp = time(NULL); // Current timestamp
        events[i].type_id = i % 256;      // Example type ID
    }

    pthread_mutex_unlock(&lock);
    return malloc(total_memory_size);
}

void serialize_data(const Record* records, const Event* events, size_t num_records, uint8_t** serialized_data) {
    size_t record_size = sizeof(Record);
    size_t event_size = sizeof(Event);

    *serialized_data = (uint8_t*)malloc(num_records * (record_size + event_size));
    if (!(*serialized_data)) {
        fprintf(stderr, "Serialization memory allocation failed.\n");
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        memcpy((*serialized_data) + i * (record_size + event_size), &records[i], record_size);
        memcpy((*serialized_data) + i * (record_size + event_size) + record_size, &events[i], event_size);
    }
}

void deserialize_data(const uint8_t* serialized_data, size_t num_records, Record** records, Event** events) {
    size_t record_size = sizeof(Record);
    size_t event_size = sizeof(Event);

    *records = (Record*)malloc(num_records * record_size);
    *events = (Event*)malloc(num_records * event_size);

    if (!(*records) || !(*events)) {
        fprintf(stderr, "Deserialization memory allocation failed.\n");
        free(*records);
        free(*events);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        memcpy(&(*records)[i], serialized_data + i * (record_size + event_size), record_size);
        memcpy(&(*events)[i], serialized_data + i * (record_size + event_size) + record_size, event_size);
    }
}

