['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>

// Assuming 'record' structure definition
typedef struct {
    int value;
    long offset;
} record_t;

// Metadata for serialization
typedef struct {
    size_t offset_count;
    size_t key_count;
    size_t record_count;
    unsigned int random_seed;
} metadata_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_and_initialize(size_t max_size, size_t *offset_count, size_t *key_count, size_t *record_count,
                            long **offsets, int **keys, record_t ***records) {
    pthread_mutex_lock(&lock);

    if (max_size < sizeof(long) || max_size < sizeof(int) || max_size < sizeof(record_t)) {
        fprintf(stderr, "Insufficient maximum size.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    long total_offset_count = max_size / sizeof(long);
    int total_key_count = max_size / sizeof(int);
    record_t *records_buffer = (record_t *)malloc(max_size);

    if (!offsets || !keys || !records || !records_buffer) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Ensure not exceeding max_size with allocated components
    size_t bytes_used = (sizeof(long) * total_offset_count +
                         sizeof(int) * total_key_count + 
                         sizeof(record_t) * total_offset_count);

    if (bytes_used > max_size) {
        fprintf(stderr, "Calculated usage exceeds maximum size.\n");
        free(records_buffer);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    long *offsets_allocated = (long *)malloc(sizeof(long) * total_offset_count);
    int *keys_allocated = (int *)malloc(sizeof(int) * total_key_count);

    if (!offsets_allocated || !keys_allocated) {
        fprintf(stderr, "Memory allocation failed for arrays.\n");
        free(records_buffer);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *offsets = offsets_allocated;
    *keys = keys_allocated;
    *records = records_buffer;

    srand(time(NULL));

    for (size_t i = 0; i < total_offset_count; ++i) {
        (*offsets)[i] = rand() % 1000000L; // Random offset
        (*keys)[i] = rand() % 10000;       // Random key
        ((*records)[i]).value = (rand() % 10000); // Random value within range
        ((*records)[i]).offset = (*offsets)[i];    // Assign corresponding offset
    }

    *offset_count = total_offset_count;
    *key_count = total_key_count;
    *record_count = total_offset_count;

    pthread_mutex_unlock(&lock);
    return 0;
}

int serialize_data(long *offsets, int *keys, record_t *records, size_t offset_count, size_t key_count,
                   size_t record_count, unsigned char **serialized_data, metadata_t *metadata) {
    if (!serialized_data || !metadata) {
        fprintf(stderr, "Invalid serialization input.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);

    // Calculate the total data size needed
    size_t total_size = sizeof(metadata_t) + 
                        (sizeof(long) * offset_count) +
                        (sizeof(int) * key_count) + 
                        (sizeof(record_t) * record_count);

    unsigned char *buffer = (unsigned char *)malloc(total_size);

    if (!buffer) {
        fprintf(stderr, "Serialization memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    metadata->offset_count = offset_count;
    metadata->key_count = key_count;
    metadata->record_count = record_count;
    metadata->random_seed = rand();  // Seed used for reproducibility

    memcpy(buffer, metadata, sizeof(metadata_t));
    memcpy(buffer + sizeof(metadata_t), offsets, sizeof(long) * offset_count);
    memcpy(buffer + sizeof(metadata_t) + (sizeof(long) * offset_count),
           keys, sizeof(int) * key_count);
    memcpy(buffer + sizeof(metadata_t) + (sizeof(long) * offset_count) +
                        (sizeof(int) * key_count), records,
           sizeof(record_t) * record_count);

    // Convert to network byte order for cross-platform compatibility
    metadata->offset_count = htobe64(metadata->offset_count);
    metadata->key_count = htobe32(metadata->key_count);
    metadata->record_count = htobe64(metadata->record_count);
    metadata->random_seed = htobe32(metadata->random_seed);

    *serialized_data = buffer;

    pthread_mutex_unlock(&lock);
    return 0;
}

int deserialize_data(unsigned char *serialized_data, long **offsets, int **keys,
                     record_t **records, size_t *offset_count, size_t *key_count,
                     size_t *record_count) {
    if (!serialized_data || !offsets || !keys || !records ||
        !offset_count || !key_count || !record_count) {
        fprintf(stderr, "Invalid deserialization input.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);

    metadata_t metadata;
    memcpy(&metadata, serialized_data, sizeof(metadata_t));

    // Convert back from network byte order
    *offset_count = be64toh(metadata.offset_count);
    *key_count = be32toh(metadata.key_count);
    *record_count = be64toh(metadata.record_count);

    size_t total_size = sizeof(metadata_t) + 
                        (sizeof(long) * *offset_count) +
                        (sizeof(int) * *key_count) + 
                        (sizeof(record_t) * *record_count);

    if (total_size > strlen((const char *)serialized_data)) {
        fprintf(stderr, "Data corruption detected during deserialization.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    long *offsets_buffer = (long *)(serialized_data + sizeof(metadata_t));
    int *keys_buffer = (int *)(serialized_data +
                               sizeof(metadata_t) + 
                               (*offset_count * sizeof(long)));
    record_t *records_buffer = (record_t *)(serialized_data +
                                           sizeof(metadata_t) +
                                           ((*offset_count * sizeof(long)) +
                                            (*key_count * sizeof(int))));

    *offsets = offsets_buffer;
    *keys = keys_buffer;
    *records = records_buffer;

    pthread_mutex_unlock(&lock);
    return 0;
}

void free_resources(long *offsets, int *keys, record_t *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

// Example main function to demonstrate usage
int main() {
    size_t offset_count, key_count, record_count;
    long *offsets = NULL;
    int *keys = NULL;
    record_t *records = NULL;

    unsigned char *serialized_data = NULL;
    metadata_t metadata;

    if (allocate_and_initialize(1024 * 1024, &offset_count, &key_count, &record_count,
                                &offsets, &keys, &records) != 0) {
        fprintf(stderr, "Initialization failed.\n");
        return -1;
    }

    if (serialize_data(offsets, keys, records, offset_count, key_count, record_count,
                       &serialized_data, &metadata) != 0) {
        fprintf(stderr, "Serialization failed.\n");
        free_resources(offsets, keys, records);
        return -1;
    }

    // Example deserialization
    long *deserialized_offsets = NULL;
    int *deserialized_keys = NULL;
    record_t *deserialized_records = NULL;

    if (deserialize_data(serialized_data, &deserialized_offsets,
                         &deserialized_keys, &deserialized_records,
                         &offset_count, &key_count, &record_count) != 0) {
        fprintf(stderr, "Deserialization failed.\n");
        free_resources(offsets, keys, records);
        return -1;
    }

    // Clean up
    free(serialized_data);
    free_resources(offsets, keys, records);

    return 0;
}
