void initialize_memory_budget(size_t memory_budget, size_t *offsets_size, size_t *keys_size, record_t ***records) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Calculate necessary sizes considering alignment and padding overheads
    const size_t long_align = sizeof(long);
    const size_t int_align = sizeof(int);
    const size_t record_struct_size = sizeof(record_t);

    *offsets_size = memory_budget / 3;
    *keys_size = *offsets_size;

    // Calculate how many records can fit in the remaining budget
    size_t max_records = (memory_budget - (*offsets_size + *keys_size) * long_align) / record_struct_size;
    *records = (record_t **)malloc(sizeof(record_t *) * max_records);

    if (!*records || !(*records)[0]) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records
    for (size_t i = 0; i < max_records; ++i) {
        (*records)[i] = (record_t *)malloc(record_struct_size);

        if (!(*records)[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Initialize record
        unsigned int seed = (unsigned int)(time(NULL) ^ generate_unique_id("data_source_identifier"));
        (*records)[i]->value = rand_r(&seed);
        (*records)[i]->key = 0; // Assume key will be set later
        (*records)[i]->access_count = 0;
        (*records)[i]->average_access_time = 0.0;
    }

    // Cleanup lock
    pthread_mutex_destroy(&lock);

    long *offsets = (long *)malloc(*offsets_size * long_align);
    int *keys = (int *)malloc(*keys_size * int_align);

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Cleanup function
void cleanup(record_t **records, size_t records_size, long *offsets, int *keys) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < records_size; ++i) {
        free(records[i]);
    }

    free(records);
    free(offsets);
    free(keys);

    // Cleanup lock
    pthread_mutex_destroy(&lock);
}

// Generate a unique identifier in a thread-safe manner
unsigned long generate_unique_id(const char *data_source) {
    static unsigned long id = 0;
    static pthread_mutex_t id_lock;

    if (pthread_mutex_init(&id_lock, NULL)) {
        fprintf(stderr, "Mutex init has failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&id_lock);

    // Generate a unique ID based on data source and current time
    unsigned long new_id = (unsigned long)(time(NULL) ^ (uintptr_t)data_source);
    id ^= new_id;

    pthread_mutex_unlock(&id_lock);
    pthread_mutex_destroy(&id_lock);

    return id;
}

// Get current time in milliseconds for performance metrics
double get_current_time_ms() {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts)) {
        fprintf(stderr, "Failed to obtain clock time\n");
        exit(EXIT_FAILURE);
    }
    return (ts.tv_sec * 1000.0) + (ts.tv_nsec / 1e6);
}

