#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MEMORY_LIMIT 1024 * 1024 // 1MB for example

typedef struct {
    int key;
    int value;
    unsigned long usage_count;
    double performance_metric;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

typedef enum { SUCCESS, ALLOCATION_FAILURE, TYPE_MISMATCH } Status;

// Error logging function
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

Status initialize_collection(RecordCollection* collection, size_t initial_capacity) {
    if (collection == NULL || initial_capacity == 0) return ALLOCATION_FAILURE;

    pthread_mutex_init(&collection->lock, NULL);
    collection->capacity = initial_capacity;
    collection->size = 0;

    // Account for alignment and padding
    size_t record_size = sizeof(Record);
    char* buffer = (char*)malloc(record_size * initial_capacity);
    if (!buffer) {
        pthread_mutex_destroy(&collection->lock);
        return ALLOCATION_FAILURE;
    }

    collection->records = (Record*)buffer;

    return SUCCESS;
}

Status add_record(RecordCollection* collection, int key, int value) {
    if (collection == NULL || collection->capacity * sizeof(Record) > MEMORY_LIMIT) return ALLOCATION_FAILURE;

    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        char* buffer = realloc(collection->records, new_capacity * sizeof(Record));
        if (!buffer) {
            log_error("Failed to resize records array.");
            pthread_mutex_unlock(&collection->lock);
            return ALLOCATION_FAILURE;
        }
        collection->records = (Record*)buffer;
        collection->capacity = new_capacity;
    }

    Record* record = &collection->records[collection->size++];
    record->key = key;
    record->value = value;
    record->usage_count = 0;
    record->performance_metric = 0.0;

    pthread_mutex_unlock(&collection->lock);
    return SUCCESS;
}

void cleanup_collection(RecordCollection* collection) {
    if (collection == NULL) return;

    pthread_mutex_lock(&collection->lock);

    free(collection->records);
    collection->records = NULL;
    collection->capacity = 0;
    collection->size = 0;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

void* external_data_source(void* arg) {
    RecordCollection* collection = (RecordCollection*)arg;

    // Simulate fetching data
    int initial_keys[] = {1, 2, 3};
    int values[] = {10, 20, 30};

    for (size_t i = 0; i < sizeof(initial_keys) / sizeof(int); ++i) {
        add_record(collection, initial_keys[i], values[i]);
    }

    return NULL;
}

int main() {
    RecordCollection collection;
    Status status = initialize_collection(&collection, 2);
    if (status != SUCCESS) {
        log_error("Failed to initialize record collection.");
        return EXIT_FAILURE;
    }

    pthread_t data_thread;
    pthread_create(&data_thread, NULL, external_data_source, &collection);
    pthread_join(data_thread, NULL);

    cleanup_collection(&collection);

    return EXIT_SUCCESS;
}
