#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int value;
    unsigned int key;
    size_t duplicate_count;
    long creation_time; // For tracking statistics and versioning.
} Record;

typedef struct {
    long *offsets;
    unsigned int *keys;
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread-safe operations
} Collection;

int generate_unique_identifier() {
    static pthread_key_t key;
    if (pthread_key_create(&key, NULL)) return -1;

    void* value = pthread_getspecific(key);
    if (!value) {
        int identifier = time(NULL); // Simplified unique ID based on current time
        pthread_setspecific(key, &identifier);
        return identifier;
    }
    return *((int*)value);
}

void initialize_collection(Collection *collection) {
    pthread_mutex_init(&collection->lock, NULL);

    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;

    collection->offsets = malloc(sizeof(long) * collection->capacity);
    collection->keys = malloc(sizeof(unsigned int) * collection->capacity);
    collection->records = malloc(sizeof(Record) * collection->capacity);

    if (!collection->offsets || !collection->keys || !collection->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
}

int add_record(Collection *collection, unsigned int key, int value) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; i++) {
        if (collection->keys[i] == key) {
            collection->records[i].duplicate_count++;
            pthread_mutex_unlock(&collection->lock);
            return -1; // Duplicate key
        }
    }

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        long *new_offsets = realloc(collection->offsets, sizeof(long) * new_capacity);
        unsigned int *new_keys = realloc(collection->keys, sizeof(unsigned int) * new_capacity);
        Record *new_records = realloc(collection->records, sizeof(Record) * new_capacity);

        if (!new_offsets || !new_keys || !new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&collection->lock);
            return -2; // Memory allocation failure
        }

        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    size_t index = collection->count++;
    collection->keys[index] = key;
    int seed = generate_unique_identifier();
    srand(seed);
    collection->records[index].value = value;
    collection->records[index].key = key;
    collection->records[index].duplicate_count = 0;
    collection->records[index].creation_time = time(NULL);

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

void print_collection(const Collection *collection) {
    pthread_mutex_lock((pthread_mutex_t *)&collection->lock);

    printf("Collection (Count: %zu, Capacity: %zu)\n", collection->count, collection->capacity);
    for (size_t i = 0; i < collection->count; i++) {
        printf("Key: %u, Value: %d, Duplicates: %zu\n",
            collection->keys[i],
            collection->records[i].value,
            collection->records[i].duplicate_count
        );
    }

    pthread_mutex_unlock((pthread_mutex_t *)&collection->lock);
}

int main() {
    Collection collection;
    initialize_collection(&collection);

    add_record(&collection, 1, 100);
    add_record(&collection, 2, 200);
    add_record(&collection, 1, 150); // This will be a duplicate

    print_collection(&collection);

    free_collection(&collection);
    return 0;
}
``` 

This code initializes and manages a collection of records with dynamic memory allocation. It handles duplicates by incrementing their count and supports resizing the array when necessary. The `add_record` function ensures thread-safe operations using mutex locks, while `generate_unique_identifier` provides a unique seed for random number generation in a concurrent context. Memory management is addressed through proper cleanup to prevent leaks, with logging integrated for errors.']

