    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_sensors; ++i) {
        free((char*)sensor_data[i].alert_message);
    }

    total_memory_used -= num_sensors * sizeof(SensorData);

    free(sensor_data);

    pthread_mutex_unlock(&lock);
}

