['Below is a C implementation for managing a dynamic data structure with records of varying sizes and types, supporting concurrent access from multiple threads. The solution uses mutexes for thread safety and handles memory allocation efficiently.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    long value;
    char *unique_id;
} Record;

typedef struct {
    Record **records;
    size_t record_count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    int min_random_value;
    int max_random_value;
} DynamicDataStructure;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int initialize_dynamic_structure(DynamicDataStructure *dds, size_t record_count,
                                 int min_random_value, int max_random_value,
                                 size_t max_id_length) {
    if (record_count == 0 || min_random_value >= max_random_value)
        return -1;

    dds->records = calloc(record_count, sizeof(Record *));
    if (!dds->records) {
        log_error("Failed to allocate memory for records array");
        return -1;
    }

    pthread_mutex_init(&dds->mutex, NULL);
    pthread_cond_init(&dds->cond_var, NULL);

    dds->record_count = record_count;
    dds->min_random_value = min_random_value;
    dds->max_random_value = max_random_value;

    for (size_t i = 0; i < record_count; ++i) {
        dds->records[i] = malloc(sizeof(Record));
        if (!dds->records[i]) {
            log_error("Failed to allocate memory for a record");
            return -1;
        }

        dds->records[i]->key = (int)i;
        dds->records[i]->value = (long)(rand() % (max_random_value - min_random_value + 1) 
                                         + min_random_value);
        dds->records[i]->unique_id = malloc(max_id_length + 1);
        if (!dds->records[i]->unique_id) {
            log_error("Failed to allocate memory for unique identifier");
            return -1;
        }
        snprintf(dds->records[i]->unique_id, max_id_length + 1, "ID_%zu", i);
    }

    return 0;
}

void update_configuration(DynamicDataStructure *dds, int min_random_value,
                          int max_random_value) {
    pthread_mutex_lock(&dds->mutex);

    dds->min_random_value = min_random_value;
    dds->max_random_value = max_random_value;

    for (size_t i = 0; i < dds->record_count; ++i) {
        dds->records[i]->value = (long)(rand() % (max_random_value - min_random_value + 1)
                                         + min_random_value);
    }

    pthread_mutex_unlock(&dds->mutex);
}

void cleanup_dynamic_structure(DynamicDataStructure *dds) {
    if (!dds || !dds->records)
        return;

    for (size_t i = 0; i < dds->record_count; ++i) {
        free(dds->records[i]->unique_id);
        free(dds->records[i]);
    }
    free(dds->records);

    pthread_mutex_destroy(&dds->mutex);
    pthread_cond_destroy(&dds->cond_var);
}

void fetch_data_with_retry(DynamicDataStructure *dds, int retries, long delay_ms) {
    for (int attempt = 0; attempt < retries; ++attempt) {
        // Simulate data fetching and handling
        pthread_mutex_lock(&dds->mutex);

        if (/* simulate success condition */) {
            pthread_mutex_unlock(&dds->mutex);
            return;
        }

        pthread_mutex_unlock(&dds->mutex);

        // Handle delay between retries
        usleep(delay_ms * 1000); 
    }
}

// Usage example in a threaded environment

void* thread_function(void* arg) {
    DynamicDataStructure *dds = (DynamicDataStructure *)arg;

    pthread_mutex_lock(&dds->mutex);
    // Perform operations on dds
    pthread_mutex_unlock(&dds->mutex);

    return NULL;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex` to protect shared resources, ensuring thread-safe access.
- **Configuration Updates**: Supports runtime changes to configuration parameters without restarting the application.
- **Memory Management**: Allocates and deallocates memory efficiently for records and unique identifiers.
- **Retry Logic**: Implements basic retry logic for operations that depend on external data sources.']

