        }
        snprintf(record->unique_id, unique_id_len, "UID%zu", i);

        record->checksum = 0; // Calculate checksum here

        ds->records[i] = record;
        ++ds->used;
    }

    return ds;
}

void update_configuration(DynamicDataStructure* ds, int value_range_min, int value_range_max) {
