void free_data_structure(DynamicDataStructure* ds) {
    pthread_rwlock_wrlock(&ds->lock);
    for (size_t i = 0; i < ds->capacity; ++i) {
        if (ds->records[i]) {
            free(ds->records[i]->unique_id);
            free(ds->records[i]);
        }
    }
    free(ds->records);
    pthread_rwlock_unlock(&ds->lock);

    pthread_rwlock_destroy(&ds->lock);
    free(ds);
}

// Example of thread-safe access function
void read_record(const DynamicDataStructure* ds, int key, Record** out_record) {
    pthread_rwlock_rdlock(&ds->lock);
    for (size_t i = 0; i < ds->capacity; ++i) {
        if (ds->records[i] && ds->records[i]->key == key) {
            *out_record = ds->records[i];
            break;
        }
    }
    pthread_rwlock_unlock(&ds->lock);
}

