#include <openssl/evp.h>
#include <time.h>

#define MAX_CONNECTIONS 10000
#define TIMESTAMP_ARRAY_SIZE MAX_CONNECTIONS
#define CONNECTION_ID_ARRAY_SIZE MAX_CONNECTIONS

typedef enum {
    OPEN,
    CLOSED,
    BUSY,
    ERROR
} ConnectionState;

typedef struct {
    int id;
    ConnectionState state;
    long timestamp_open;
    long timestamp_close;
    long data_transferred; // bytes
    long last_used_timestamp;
} Connection;

typedef struct {
    Connection *connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    size_t max_memory_limit; // in bytes
    size_t current_memory_usage; // in bytes
    int connection_count;
    unsigned char aes_key[32]; // AES-256 key
    EVP_CIPHER_CTX *aes_ctx;
} ConnectionPool;

ConnectionPool pool;

void initialize_pool(size_t memory_limit) {
    pthread_mutex_init(&pool.lock, NULL);
    pool.max_memory_limit = memory_limit;
    pool.current_memory_usage = 0;
    pool.connection_count = 0;
    pool.aes_ctx = EVP_CIPHER_CTX_new();

    if (!EVP_EncryptInit_ex(pool.aes_ctx, EVP_aes_256_gcm(), NULL, pool.aes_key, NULL)) {
        perror("AES initialization failed");
        exit(EXIT_FAILURE);
    }
}

int create_connection() {
    pthread_mutex_lock(&pool.lock);

    if (pool.connection_count >= MAX_CONNECTIONS || 
        pool.current_memory_usage + sizeof(Connection) > pool.max_memory_limit) {
        pthread_mutex_unlock(&pool.lock);
        return -1;
    }

    Connection *conn = malloc(sizeof(Connection));
    if (!conn) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&pool.lock);
        return -1;
    }

    conn->id = rand() % CONNECTION_ID_ARRAY_SIZE;
    conn->state = rand() % 4; // Random state
    conn->timestamp_open = time(NULL);
    conn->data_transferred = 0;
    conn->last_used_timestamp = time(NULL);

    pool.connections[pool.connection_count++] = conn;
    pool.current_memory_usage += sizeof(Connection);

    pthread_mutex_unlock(&pool.lock);
    return conn->id;
}

void close_connection(int id) {
    pthread_mutex_lock(&pool.lock);

    for (int i = 0; i < pool.connection_count; ++i) {
        if (pool.connections[i]->id == id) {
            pool.current_memory_usage -= sizeof(Connection);
            free(pool.connections[i]);
            memmove(&pool.connections[i], &pool.connections[i + 1],
                    (pool.connection_count - i - 1) * sizeof(Connection *));
            --pool.connection_count;
            break;
        }
    }

    pthread_mutex_unlock(&pool.lock);
}

void cleanup_pool() {
    for (int i = 0; i < pool.connection_count; ++i) {
        free(pool.connections[i]);
    }
    EVP_CIPHER_CTX_free(pool.aes_ctx);
    pthread_mutex_destroy(&pool.lock);
}

