    size_t total_size = sizeof(sensor->temperature) + SENSOR_ID_MAX_LEN + sizeof(sensor->timestamp) + sizeof(sensor->status);
    *buffer = malloc(total_size);

    if (!*buffer) return 0;

    char *ptr = (char*)*buffer;
    memcpy(ptr, &sensor->temperature, sizeof(sensor->temperature));
    ptr += sizeof(sensor->temperature);

    // Ensure endianness compatibility
    uint16_t len = htobe16((uint16_t)strlen(sensor->id));
    memcpy(ptr, &len, sizeof(len));
    ptr += sizeof(len);
    memcpy(ptr, sensor->id, strlen(sensor->id));
    ptr += SENSOR_ID_MAX_LEN;

    uint64_t ts = htonll(sensor->timestamp); // Custom function to handle 64-bit endianness
    memcpy(ptr, &ts, sizeof(ts));
    ptr += sizeof(sensor->timestamp);

    memcpy(ptr, &sensor->status, sizeof(sensor->status));

    return total_size;
}

uint64_t htonll(uint64_t value) {
    static const int num = 42;
    if (*(char *)&num == 42)
        return ((uint64_t)htonl(value & 0xFFFFFFFFULL)) << 32 | htonl(value >> 32);
    else
        return ((uint64_t)htons(value & 0xFFFFULL)) << 48 |
               ((uint64_t)htons(value >> 16) & 0xFFFF0000ULL) << 32 |
               htonl(value >> 32);
}

// Deserialize sensor data from byte array
int deserialize_sensor(uint8_t *buffer, Sensor *sensor) {
    char *ptr = (char*)buffer;

    memcpy(&sensor->temperature, ptr, sizeof(sensor->temperature));
