    uLongf compressed_size = compressBound(data_size);
    *compressed_data = malloc(compressed_size);

    if (!*compressed_data) return 0;

    int result = compress((Bytef *)*compressed_data, &compressed_size, (const Bytef *)data, data_size);

    if (result != Z_OK) {
        free(*compressed_data);
        return 0;
    }

    return compressed_size;
}

size_t decompress_sensor_data(uint8_t *compressed_data, size_t compressed_size, uint8_t **decompressed_data) {
