#define MAX_RECORD_SIZE 256 // Example threshold for record size
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    long offset;
    int key;
    double average;
    char flag;
    unsigned int identifier;
    void *metadata;
} Record;

// Forward declarations
void log_message(int level, const char* message);
Record* create_record(long offset, int key, double average, char flag, unsigned int identifier, void *metadata);
