// Implementation
Record* create_record(long offset, int key, double average, char flag, unsigned int identifier, void *metadata) {
    if (sizeof(Record) + sizeof(void*) > MAX_RECORD_SIZE) {
        log_message(LOG_LEVEL_ERROR, "Record size exceeds maximum threshold.");
        return NULL;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for record creation.");
        return NULL;
    }

    record->offset = htobe64(offset);
    record->key = htobe32(key);
    record->average = htond(average); // Assume htond is implemented or use a library
    record->flag = flag;
    record->identifier = be32toh(identifier);
    record->metadata = metadata;

    return record;
}

int serialize_record(const Record *record, unsigned char **output) {
    if (!record || !output) return -1;

    size_t output_size = sizeof(Record) + sizeof(void*);
    *output = malloc(output_size);
    if (!*output) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for serialization.");
        return -1;
    }

    memcpy(*output, record, sizeof(Record));
    memcpy(*output + sizeof(Record), &record->metadata, sizeof(void*));

    // Compression logic here (omitted for brevity)

    return 0;
}

int deserialize_record(unsigned char *input, size_t input_size, Record **record) {
    if (!input || !record || input_size < sizeof(Record)) return -1;

    *record = malloc(sizeof(Record));
    if (!*record) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for deserialization.");
        return -1;
    }

    memcpy(*record, input, sizeof(Record));
    void **metadata_ptr = (void**)(input + sizeof(Record));
    (*record)->metadata = *metadata_ptr;

    // Endian conversion here

    return 0;
}

void free_record(Record *record) {
    if (!record) return;

    // Free metadata if necessary
    free(record);
}

void log_message(int level, const char* message) {
    if (level >= LOG_LEVEL_INFO) {
        printf("[INFO] %s\n", message);
    }
    if (level == LOG_LEVEL_ERROR) {
        fprintf(stderr, "[ERROR] %s\n", message);
    }
}
