using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class DynamicValueGenerator
{
    private readonly double minValue, maxValue;
    private double? subMin, subMax;

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue >= maxValue) throw new ArgumentException("Invalid range: min value must be less than max value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void SetSubRange(double? subMin, double? subMax)
    {
        if (subMin.HasValue && (subMin < minValue || subMin >= subMax))
            throw new ArgumentException("Invalid sub range: subMin is out of bounds.");

        if (subMax.HasValue && (subMax <= subMin || subMax > maxValue))
            throw new ArgumentException("Invalid sub range: subMax is out of bounds.");

        this.subMin = subMin;
        this.subMax = subMax;
    }

    public double[] GenerateRandomFloats(int n, bool inclusive = true)
    {
        if (n <= 0) return Array.Empty<double>();

        var rangeStart = GetRangeStart(inclusive);
        var rangeEnd = GetRangeEnd(inclusive);

        var rand = new Random();
        var result = new double[n];

        for (int i = 0; i < n; i++)
        {
            result[i] = (double)rand.NextDouble() * (rangeEnd - rangeStart) + rangeStart;
        }

        return result;
    }

    public int[] GenerateRandomIntegers(int n, bool inclusive = true)
    {
        if (n <= 0) return Array.Empty<int>();

        var rangeStart = GetRangeStart(inclusive);
        var rangeEnd = GetRangeEnd(inclusive);

        var rand = new Random();
        var result = new int[n];

        for (int i = 0; i < n; i++)
        {
            result[i] = rand.Next((int)rangeStart, (int)(inclusive ? rangeEnd + 1 : rangeEnd));
        }

        return result;
    }

    private double GetRangeStart(bool inclusive)
    {
        return subMin ?? minValue;
    }

    private double GetRangeEnd(bool inclusive)
    {
        return subMax.HasValue ? subMax.Value : (inclusive ? maxValue : maxValue - 1.0);
    }

    public async Task<HttpClient> CreateHttpClientAsync(bool disableCertificateValidation = false)
    {
        var handler = new HttpClientHandler();

        if (disableCertificateValidation)
        {
            handler.ServerCertificateCustomValidationCallback = 
                (message, cert, chain, errors) => true;
        }

        return await Task.Run(() => new HttpClient(handler));
    }
}
