use std::sync::{Arc, Mutex};
use reqwest::Client;
use tokio;

pub struct HttpClientFactory {
    clients: Arc<Mutex<Vec<Client>>>,
}

impl HttpClientFactory {
    pub fn new() -> Self {
        Self { 
            clients: Arc::new(Mutex::new(Vec::new())), 
        }
    }

    pub async fn create_client(&self, disable_ssl_verification: bool) -> Client {
        let mut clients = self.clients.lock().unwrap();

        if clients.is_empty() || clients[0].is_closed() {
            drop(clients); // Release the lock
            let client_builder = reqwest::ClientBuilder::new();

            let client = if disable_ssl_verification {
                client_builder.insecure()
            } else {
                client_builder
            }.build().expect("Failed to build HTTP Client");

            clients.push(client);
        }

        drop(clients); // Release the lock

        clients[0].clone()
    }
}
```

