#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <uuid/uuid.h>
#include <stdint.h>

#define MEMORY_BUDGET 1048576 // 1 MB for example

typedef struct {
    double amount;
    char status;
    time_t timestamp;
} transaction;

typedef struct {
    int value;
} record;

unsigned long hash_uuid(const uuid_t uuid) {
    unsigned long hash = 5381;
    const char *uuid_str = uuid_to_string(uuid, NULL);
    while (*uuid_str)
        hash = ((hash << 5) + hash) + (unsigned char)(*uuid_str++);
    free((void*)uuid_str);
    return hash;
}

int allocate_memory(transaction **transactions, long **offsets, int **keys, record **records,
                    size_t num_transactions, size_t num_offsets, size_t num_keys, size_t num_records) {
    if ((num_transactions * sizeof(transaction)) + 
        (num_offsets * sizeof(long)) + 
        (num_keys * sizeof(int)) + 
        (num_records * sizeof(record)) > MEMORY_BUDGET) {
        fprintf(stderr, "Memory allocation exceeds budget.\n");
        return -1;
    }

    *transactions = (transaction *)malloc(num_transactions * sizeof(transaction));
    if (!*transactions) return -1;

    *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!*offsets) {
        free(*transactions);
        return -1;
    }

    *keys = (int *)malloc(num_keys * sizeof(int));
    if (!*keys) {
        free(*transactions);
        free(*offsets);
        return -1;
    }

    *records = (record *)malloc(num_records * sizeof(record));
    if (!*records) {
        free(*transactions);
        free(*offsets);
        free(*keys);
        return -1;
    }

    return 0;
}

void initialize_transactions(transaction *transactions, size_t num_transactions) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_transactions; ++i) {
        uuid_t uuid;
        uuid_generate(uuid);
        unsigned long transaction_id = hash_uuid(uuid);

        transactions[i].amount = ((double)rand() / RAND_MAX) * 100.0; // example random amount
        transactions[i].status = 'A'; // example status
        transactions[i].timestamp = time(NULL); // current timestamp

        printf("Transaction ID: %lu\n", transaction_id);
    }
}

void initialize_records(record *records, size_t num_records) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100; // example range
    }
}

double read_and_validate_transactions(int count, double *total_sum) {
    double amount;
    *total_sum = 0.0;

    for (int i = 0; i < count; ++i) {
        printf("Enter transaction amount: ");
        if (scanf("%lf", &amount) != 1 || amount < 0) {
            fprintf(stderr, "Invalid input.\n");
            return -1;
        }
        *total_sum += amount;
    }

    return *total_sum;
}

void read_integers_and_count_frequencies(int count) {
    int num;
    printf("Enter %d integers:\n", count);
    int *input = (int *)malloc(count * sizeof(int));
    if (!input) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < count; ++i) {
        scanf("%d", &num);
        input[i] = num;
    }

    int max_value = *max_element(input, input + count) + 1;
    int *frequency = calloc(max_value, sizeof(int));
    if (!frequency) {
        free(input);
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < count; ++i) {
        frequency[input[i]]++;
    }

    printf("Unique integers and their frequencies:\n");
    for (int i = 0; i < max_value; ++i) {
        if (frequency[i] > 0) {
            printf("%d: %d\n", i, frequency[i]);
        }
    }

    free(input);
    free(frequency);
}

int main() {
    size_t num_transactions = 10;
    size_t num_offsets = 5;
    size_t num_keys = 8;
    size_t num_records = 15;

    transaction *transactions = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    if (allocate_memory(&transactions, &offsets, &keys, &records,
                        num_transactions, num_offsets, num_keys, num_records) != 0) {
        fprintf(stderr, "Failed to allocate memory.\n");
        return EXIT_FAILURE;
    }

    initialize_transactions(transactions, num_transactions);
    initialize_records(records, num_records);

    double total_sum = 0.0;
    if (read_and_validate_transactions(num_transactions, &total_sum) == -1) {
        fprintf(stderr, "Failed to read transactions.\n");
        free(transactions);
        free(offsets);
        free(keys);
        free(records);
        return EXIT_FAILURE;
    }

    printf("Total sum of valid transactions: %.2f\n", total_sum);

    read_integers_and_count_frequencies(20); // example input size

    free(transactions);
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
