// Function to allocate and initialize arrays with constraints
char* render_footer_and_allocate_arrays(int num_scripts, struct ScriptObject **scripts,
                                        long max_memory_limit) {

    const int key_range_min = 1;
    const int key_range_max = 1000;
    const size_t char_flag_size = sizeof(char);
    const size_t ulong_size = sizeof(long);
    const size_t int_size = sizeof(int);
    const size_t double_size = sizeof(double);
    const size_t uint_size = sizeof(unsigned int);

    // Calculate total memory needed
    size_t required_memory = num_scripts * (ulong_size + int_size + double_size + char_flag_size + uint_size);

    if (required_memory > max_memory_limit) {
        log_message("Memory limit exceeded, cannot allocate arrays.");
        return NULL;
    }

    long *offsets = malloc(num_scripts * ulong_size);
    int *keys = malloc(num_scripts * int_size);
    double *averages = malloc(num_scripts * double_size);
    char *flags = malloc(num_scripts * char_flag_size);
    unsigned int *identifiers = malloc(num_scripts * uint_size);

    if (!offsets || !keys || !averages || !flags || !identifiers) {
        log_message("Memory allocation failed.");
        free(offsets); free(keys); free(averages); free(flags); free(identifiers);
        return NULL;
    }

    // Initialize the arrays
    for (int i = 0; i < num_scripts; ++i) {
        offsets[i] = i * ulong_size;
        keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1); 
        averages[i] = (double)(rand() % 100) / 10.0; // Random doubles for example
        flags[i] = 'A';  // Example flag, could be more complex
        identifiers[i] = rand() & UINT_MAX;
    }

    // Render script tags as footer HTML
    size_t buffer_size = num_scripts * (256 + 64);  // Estimate of script tag size
    char *footer_html = malloc(buffer_size);
    if (!footer_html) {
        log_message("Failed to allocate memory for footer HTML.");
        free(offsets); free(keys); free(averages); free(flags); free(identifiers);
        return NULL;
    }

    strcpy(footer_html, "<div id='scripts'>\n");
    for (int i = 0; i < num_scripts; ++i) {
        char script_tag[256];
        snprintf(script_tag, sizeof(script_tag),
                 "<script key='%d' type='text/javascript'>%s</script>\n",
                 keys[i], scripts[i]->code);
        strcat(footer_html, script_tag);
    }
    strcat(footer_html, "</div>");

    log_message("Memory usage and allocation successful.");

    // Serialization example (not used here but would be integrated in a real scenario)
    unsigned char *serialized_data = NULL;
    size_t serialized_size = 0;
    if (serialize_data(offsets, num_scripts * ulong_size, &serialized_data, &serialized_size) != 0) {
        log_message("Serialization failed.");
        free(footer_html);
        footer_html = NULL;
    }

    // Free allocated arrays after use
    free(offsets); 
    free(keys);
    free(averages);
    free(flags);
    free(identifiers);

    return footer_html;  // Return the rendered HTML as a string
}

