// record.h
#ifndef RECORD_H
#define RECORD_H

#include <stdint.h>
#include <stdlib.h>

typedef struct {
    long offset;
    int key;
    double average;
    char flag;
    unsigned int identifier;
    void *metadata;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    size_t max_size_per_record; // in bytes
} RecordManager;

RecordManager* create_manager(size_t initial_capacity, size_t max_size_per_record);
void destroy_manager(RecordManager *manager);
int add_record(RecordManager *manager, const Record *record);
void update_record(RecordManager *manager, int index, const Record *record);

#endif // RECORD_H

// record.c
#include "record.h"
#include <string.h>
#include <stdio.h>

RecordManager* create_manager(size_t initial_capacity, size_t max_size_per_record) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->max_size_per_record = max_size_per_record;

    if (!manager->records) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_manager(RecordManager *manager) {
    if (manager) {
        free(manager->records);
        free(manager);
    }
}

int add_record(RecordManager *manager, const Record *record) {
    // Check size constraints
    size_t record_size = sizeof(record->offset) + sizeof(record->key)
                        + sizeof(record->average) + sizeof(record->flag)
                        + sizeof(record->identifier) + strlen((char*)record->metadata);

    if (record_size > manager->max_size_per_record) return -1;

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record *new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));

        if (!new_records) return -1;
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    memcpy(&manager->records[manager->count], record, sizeof(Record));
    manager->count++;

    return 0; // Success
}

void update_record(RecordManager *manager, int index, const Record *record) {
    if (index < 0 || index >= manager->count) return;
    memcpy(&manager->records[index], record, sizeof(Record));
}

