#define MAX_MEMORY 1024 * 1024 // Maximum memory size in bytes (e.g., 1MB)
#define INITIAL_CAPACITY 10

typedef struct {
    double timestamp;
    float temperature_reading;
    float humidity_reading;
    float wind_speed;
    int location_id;
    int station_id;
} weather_station_data;

typedef struct {
    float key;
    double offset;
} observation;

typedef struct {
    size_t capacity;
    size_t size;
    weather_station_data *data;
    double *offsets;
    float *keys;
    observation *observations;
} WeatherDataArray;

// Function prototypes
void initialize_weather_array(WeatherDataArray *array, size_t initial_capacity);
int resize_weather_array(WeatherDataArray *array, size_t new_capacity);
void free_weather_array(WeatherDataArray *array);
float random_float(float min, float max);
double random_double(double min, double max);
void log_error(const char *message);

// Function implementations

void initialize_weather_array(WeatherDataArray *array, size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_MEMORY / sizeof(weather_station_data)) {
        log_error("Invalid initial capacity.");
        return;
    }

    array->capacity = initial_capacity;
    array->size = 0;

    size_t memory_needed = initial_capacity * sizeof(weather_station_data) +
                           initial_capacity * sizeof(double) +
                           initial_capacity * sizeof(float) +
                           initial_capacity * sizeof(observation);

    if (memory_needed > MAX_MEMORY) {
        log_error("Memory needed exceeds maximum allowed.");
        return;
    }

    array->data = malloc(initial_capacity * sizeof(weather_station_data));
    array->offsets = malloc(initial_capacity * sizeof(double));
    array->keys = malloc(initial_capacity * sizeof(float));
    array->observations = malloc(initial_capacity * sizeof(observation));

    if (!array->data || !array->offsets || !array->keys || !array->observations) {
        log_error("Memory allocation failed.");
        free_weather_array(array);
    }
}

int resize_weather_array(WeatherDataArray *array, size_t new_capacity) {
    if (new_capacity == 0 || 
        array->capacity + sizeof(weather_station_data) * (new_capacity - array->capacity) +
        sizeof(double) * (new_capacity - array->capacity) +
        sizeof(float) * (new_capacity - array->capacity) +
        sizeof(observation) * (new_capacity - array->capacity) > MAX_MEMORY) {
        log_error("Invalid new capacity or memory limit exceeded.");
        return 0;
    }

    weather_station_data *new_data = realloc(array->data, new_capacity * sizeof(weather_station_data));
    double *new_offsets = realloc(array->offsets, new_capacity * sizeof(double));
    float *new_keys = realloc(array->keys, new_capacity * sizeof(float));
    observation *new_observations = realloc(array->observations, new_capacity * sizeof(observation));

    if (!new_data || !new_offsets || !new_keys || !new_observations) {
        log_error("Memory reallocation failed.");
        return 0;
    }

    array->data = new_data;
    array->offsets = new_offsets;
    array->keys = new_keys;
    array->observations = new_observations;
    array->capacity = new_capacity;

    return 1;
}

void free_weather_array(WeatherDataArray *array) {
    if (array->data) free(array->data);
    if (array->offsets) free(array->offsets);
    if (array->keys) free(array->keys);
    if (array->observations) free(array->observations);
    array->capacity = 0;
    array->size = 0;
}

float random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

double random_double(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    WeatherDataArray weather_array;
    initialize_weather_array(&weather_array, INITIAL_CAPACITY);

    if (!weather_array.data) return 1; // Initialization failed

    for (size_t i = 0; i < 50; ++i) { // Simulate adding data
        if (weather_array.size >= weather_array.capacity && !resize_weather_array(&weather_array, weather_array.capacity * 2)) {
            break;
        }

        weather_station_data new_data;
        new_data.timestamp = random_double(1609459200, time(NULL)); // Random timestamp
        new_data.temperature_reading = random_float(-20.0f, 50.0f);
        new_data.humidity_reading = random_float(0.0f, 100.0f);
        new_data.wind_speed = random_float(0.0f, 150.0f);
        new_data.location_id = rand() % 100;
        new_data.station_id = rand() % 50;

        weather_array.data[weather_array.size] = new_data;
        weather_array.offsets[weather_array.size] = random_double(-1.0, 1.0);
        weather_array.keys[weather_array.size] = random_float(0.0f, 10.0f);
        weather_array.observations[weather_array.size].key = random_float(0.0f, 10.0f);
        weather_array.observations[weather_array.size++].offset = random_double(-1.0, 1.0);
    }

    free_weather_array(&weather_array);

    return 0;
}
