#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int allocate_and_initialize(long *offsets, int *keys, record **records, int num_records) {
    if (num_records <= 0 || num_records > 10000) return -1; // Ensure valid range

    srand(time(NULL)); // Seed random number generator
    long step_size = sizeof(record);

    // Allocate memory for offsets and records
    offsets = malloc((num_records + 1) * sizeof(long));
    if (!offsets) return -1;
    *records = malloc(num_records * step_size);
    if (!*records) {
        free(offsets);
        return -1;
    }

    // Initialize the keys array with a temporary larger size to handle collisions
    int *temp_keys = calloc(num_records, sizeof(int));
    if (!temp_keys) {
        free(offsets);
        free(*records);
        return -1;
    }

    int key_range = 2 * num_records; // Increased range for better distribution and uniqueness

    // Initialize keys ensuring no duplicates
    for (int i = 0; i < num_records; ++i) {
        int unique_key_found;
        do {
            unique_key_found = 1;
            temp_keys[i] = rand() % key_range;

            for (int j = 0; j < i; ++j) {
                if (temp_keys[i] == temp_keys[j]) {
                    unique_key_found = 0;
                    break;
                }
            }

        } while (!unique_key_found);
    }

    // Allocate memory for keys and transfer from temporary array
    keys = malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        free(*records);
        free(temp_keys);
        return -1;
    }
    memcpy(keys, temp_keys, num_records * sizeof(int));

    // Initialize offsets and records arrays
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i * step_size;
        (*records)[i].value = rand() % key_range; // Random value within specified range
    }
    offsets[num_records] = num_records * step_size;

    free(temp_keys); // Free the temporary keys array

    return num_records;
}
