// Global variables to manage logging and system state.
static FILE* logFile = NULL;
int initializedKeys[MAX_RECORDS] = {0};

void initializeLogging(const char* logFilePath) {
    if (logFile != NULL) return; // Prevents multiple initializations
    logFile = fopen(logFilePath, "a");
    if (logFile == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void logOperation(const char* operationDescription) {
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", operationDescription);
        fflush(logFile); // Ensure logging is done in real time
    }
}

bool isKeyUnique(int key) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (initializedKeys[i] == key) return false;
    }
    return true;
}

long* allocateAndInitializeRecords(int numRecords, int valueRangeLow, int valueRangeHigh,
                                  int** keysArrayOut, Record*** recordsArrayOut, int* totalRecordsOut) {
    initializeLogging("system.log");

    if (numRecords <= 0 || numRecords > MAX_RECORDS || valueRangeLow >= valueRangeHigh) {
        logOperation("Invalid parameters provided to allocateAndInitializeRecords.");
        *totalRecordsOut = 0;
        return NULL;
    }

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));

    if (!offsets || !keys || !records) {
        logOperation("Memory allocation failed.");
        free(offsets);
        free(keys);
        free(records);
        *totalRecordsOut = 0;
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    int uniqueKeysGenerated = 0;

    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = i; // Simple offset initialization

        do {
            keys[i] = rand() % 100000 + valueRangeLow;
        } while (!isKeyUnique(keys[i]) && uniqueKeysGenerated < numRecords);

        if (uniqueKeysGenerated >= numRecords) { 
            logOperation("Failed to generate a sufficient number of unique keys.");
            free(offsets);
            free(keys);
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            *totalRecordsOut = 0;
            return NULL;
        }

        initializedKeys[uniqueKeysGenerated++] = keys[i];
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            logOperation("Memory allocation for record failed.");
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            free(offsets);
            free(keys);
            *totalRecordsOut = 0;
            return NULL;
        }

        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
        records[i]->value = rand() % (valueRangeHigh - valueRangeLow + 1) + valueRangeLow;

        logOperation("Record initialized.");
    }

    *keysArrayOut = keys;
    *recordsArrayOut = records;
    *totalRecordsOut = numRecords;

    return offsets;
}

void freeResources(int* keys, Record** records, int totalRecords) {
    for (int i = 0; i < totalRecords; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);

    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }
}

void exportToJson(const Record* records, int totalRecords, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open JSON file for writing");
        return;
    }

    fprintf(file, "[\n");
    for (int i = 0; i < totalRecords; ++i) {
        fprintf(file, "  {\"offset\": %ld, \"key\": %d, \"value\": %d}",
                records[i]->offset, records[i]->key, records[i]->value);
        if (i < totalRecords - 1) fprintf(file, ",");
        fprintf(file, "\n");
    }
    fprintf(file, "]\n");

    fclose(file);
}
