#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define KEY_LENGTH 16

typedef struct {
    int value;
    long offset;
    char key[KEY_LENGTH + 1]; // NULL-terminated string
} record;

// Global variables for records and mutex for thread safety
record *records = NULL;
size_t num_records = 0;
pthread_mutex_t lock;

// Function to generate a unique random key
void generate_unique_key(char *key, size_t len) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    int i;
    srand((unsigned)time(NULL));

    while (1) {
        for (i = 0; i < len - 1; i++) {
            key[i] = charset[rand() % (sizeof(charset) - 1)];
        }
        key[len - 1] = '\0';

        pthread_mutex_lock(&lock);
        int is_unique = 1;
        for (size_t j = 0; j < num_records && is_unique; j++) {
            if (strncmp(records[j].key, key, len) == 0) {
                is_unique = 0;
            }
        }
        pthread_mutex_unlock(&lock);

        if (is_unique) break;
    }
}

// Function to dynamically allocate and initialize records
void create_records(size_t n, int offset_step) {
    records = malloc(n * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; i++) {
        records[i].value = rand() % 100;
        records[i].offset = offset_step * i;
        generate_unique_key(records[i].key, KEY_LENGTH);
    }

    num_records = n;
}

// Function to serialize data into a binary format
void serialize_to_binary(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    fwrite(&num_records, sizeof(size_t), 1, file);
    for (size_t i = 0; i < num_records; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

// Function to serialize data into a JSON format
void serialize_to_json(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "[\n");
    for (size_t i = 0; i < num_records; i++) {
        fprintf(file, "  {\"value\": %d, \"offset\": %ld, \"key\": \"%s\"}%s\n",
                records[i].value, records[i].offset, records[i].key,
                i < num_records - 1 ? "," : "");
    }
    fprintf(file, "]");

    fclose(file);
}

// Function to deserialize data from a binary format
void deserialize_from_binary(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }

    fread(&num_records, sizeof(size_t), 1, file);
    records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; i++) {
        fread(&records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

// Helper function: read integers from input and print the largest
void find_largest_integer() {
    int max_int = INT_MIN;
    int value;

    printf("Enter integers (non-integer to stop):\n");

    while (scanf("%d", &value) == 1) {
        if (value > max_int) {
            max_int = value;
        }
    }

    if (max_int != INT_MIN)
        printf("Largest integer: %d\n", max_int);
}

int main(int argc, char *argv[]) {
    pthread_mutex_init(&lock, NULL);

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <number_of_records> <serialization_format>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num = atoi(argv[1]);
    const char *format = argv[2];

    create_records(num, 10);

    if (strcmp(format, "binary") == 0) {
        serialize_to_binary("output.bin");
    } else if (strcmp(format, "json") == 0) {
        serialize_to_json("output.json");
    } else {
        fprintf(stderr, "Unknown format: %s\n", format);
        return EXIT_FAILURE;
    }

    find_largest_integer();

    free(records);
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
