#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

// Entry structure definition
typedef struct {
    char *identifier;
    time_t timestamp;
    char *data;
} entry;

// Hash table node structure
typedef struct Node {
    entry e;
    struct Node* next;
} Node;

// Hash table structure
typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
} HashTable;

// Global variables to manage memory usage
size_t total_memory_usage = 0;
const size_t MAX_MEMORY_USAGE = 1024 * 1024; // Example max size limit (1MB)

// Forward declarations
HashTable* create_table(size_t capacity);
unsigned long custom_hash(const char* identifier, size_t capacity);
void insert_entry(HashTable* table, entry e);
entry* retrieve_entry(HashTable* table, const char* identifier);
void delete_entry(HashTable* table, const char* identifier);
int parse_log_file(FILE *file, HashTable** tables);
void serialize_table(HashTable* table, FILE* output);
void deserialize_table(HashTable* table, FILE* input);

// Function to create a hash table
HashTable* create_table(size_t capacity) {
    if (total_memory_usage + capacity * sizeof(Node*) > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return NULL;
    }

    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    total_memory_usage += sizeof(HashTable);

    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    total_memory_usage += capacity * sizeof(Node*);

    if (!table->buckets) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    table->size = 0;

    return table;
}

// Custom hash function
unsigned long custom_hash(const char* identifier, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *identifier++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash % capacity;
}

// Insert entry into the hash table
void insert_entry(HashTable* table, entry e) {
    if (total_memory_usage + sizeof(entry) > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return;
    }

    size_t index = custom_hash(e.identifier, table->capacity);
    Node* new_node = (Node*)malloc(sizeof(Node));
    total_memory_usage += sizeof(Node);

    if (!new_node) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    new_node->e = e;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    table->size++;
}

// Retrieve entry from the hash table
entry* retrieve_entry(HashTable* table, const char* identifier) {
    size_t index = custom_hash(identifier, table->capacity);
    Node* node = table->buckets[index];

    while (node) {
        if (strcmp(node->e.identifier, identifier) == 0)
            return &(node->e);

        node = node->next;
    }

    return NULL;
}

// Delete entry from the hash table
void delete_entry(HashTable* table, const char* identifier) {
    size_t index = custom_hash(identifier, table->capacity);
    Node* current = table->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (strcmp(current->e.identifier, identifier) == 0) {
            if (prev)
                prev->next = current->next;
            else
                table->buckets[index] = current->next;

            total_memory_usage -= sizeof(Node);
            free(current->e.data);
            total_memory_usage -= strlen(current->e.data) + 1;
            free((void*)current->e.identifier);
            total_memory_usage -= strlen(current->e.identifier) + 1;
            free(current);

            table->size--;
            return;
        }

        prev = current;
        current = current->next;
    }
}

// Parse log file and populate hash tables
int parse_log_file(FILE *file, HashTable** tables) {
    char line[256];
    entry e;

    while (fgets(line, sizeof(line), file)) {
        // Example parsing logic (simplified)
        char* token = strtok(line, " ");

        if (!token || strlen(token) > 31) continue; // Identifier too long

        e.identifier = strdup(token);
        total_memory_usage += strlen(e.identifier) + 1;

        token = strtok(NULL, " ");
        if (!token || strptime(token, "%Y-%m-%dT%H:%M:%SZ", NULL) == NULL)
            continue; // Malformed timestamp

        e.timestamp = time(NULL); // Simplification for demonstration

        token = strtok(NULL, "\n");
        e.data = strdup(token);
        total_memory_usage += strlen(e.data) + 1;

        if (tables[0]->size < tables[0]->capacity / 2)
            insert_entry(tables[0], e);
        else
            insert_entry(tables[1], e);
    }

    return 0;
}

// Serialize hash table to a binary file
void serialize_table(HashTable* table, FILE* output) {
    fwrite(&(table->size), sizeof(table->size), 1, output);

    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];

        while (node) {
            size_t id_len = strlen(node->e.identifier) + 1;
            fwrite(&id_len, sizeof(id_len), 1, output);
            fwrite(node->e.identifier, sizeof(char), id_len, output);

            time_t timestamp;
            memcpy(&timestamp, &(node->e.timestamp), sizeof(timestamp));
            fwrite(&timestamp, sizeof(time_t), 1, output);

            size_t data_len = strlen(node->e.data) + 1;
            fwrite(&data_len, sizeof(data_len), 1, output);
            fwrite(node->e.data, sizeof(char), data_len, output);

            node = node->next;
        }
    }
}

// Deserialize hash table from a binary file
void deserialize_table(HashTable* table, FILE* input) {
    fread(&(table->size), sizeof(table->size), 1, input);

    for (size_t i = 0; i < table->capacity && table->size > 0; ++i) {
        Node* node = NULL;

        while (table->buckets[i] == NULL || table->size-- > 0) {
            size_t id_len;
            fread(&id_len, sizeof(id_len), 1, input);

            char* identifier = (char*)malloc(id_len);
            total_memory_usage += id_len;

            fread(identifier, sizeof(char), id_len, input);

            time_t timestamp;
            fread(&timestamp, sizeof(time_t), 1, input);

            size_t data_len;
            fread(&data_len, sizeof(data_len), 1, input);

            char* data = (char*)malloc(data_len);
            total_memory_usage += data_len;

            fread(data, sizeof(char), data_len, input);

            if (!node) {
                node = (Node*)malloc(sizeof(Node));
                table->buckets[i] = node;
            } else {
                Node* new_node = (Node*)malloc(sizeof(Node));
                node->next = new_node;
                node = new_node;
            }

            total_memory_usage += sizeof(Node);

            node->e.identifier = identifier;
            node->e.timestamp = timestamp;
            node->e.data = data;

            node->next = NULL;
        }
    }
}

// Main function to demonstrate the functionality
int main() {
    HashTable* table1 = create_table(100);
    HashTable* table2 = create_table(100);

    if (!table1 || !table2) return 1;

    FILE *log_file = fopen("logfile.txt", "r");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    parse_log_file(log_file, (HashTable*[]){ table1, table2 });

    fclose(log_file);

    FILE *output = fopen("serialized.dat", "wb");
    serialize_table(table1, output);
    fclose(output);

    FILE *input = fopen("serialized.dat", "rb");
    HashTable* deserialized_table = create_table(100);

    if (deserialized_table) {
        deserialize_table(deserialized_table, input);
    }

    fclose(input);
    return 0;
}
