        ServerEntry *entry = malloc(sizeof(ServerEntry));
        if (!entry) {
            log_message("Memory allocation failed for server entry.");
            continue;
        }

        if (sscanf(line, "%[^:]:%d:%255s", entry->ip, &entry->port, entry->apiKey) == 3) {
            servers[server_count++] = entry;
        } else {
            free(entry);
        }
    }

    fclose(file);
}

void tls_connection(ServerEntry *entry) {
    SSL_CTX *ctx;
    SSL *ssl;
    BIO *bio;

    const SSL_METHOD *method = TLS_client_method();
    ctx = SSL_CTX_new(method);

    if (!ctx) {
        log_message("Failed to create SSL context.");
        return;
    }

    for (int retries = 0; retries < 3; retries++) {
        bio = BIO_new_ssl_connect(ctx);
        char connect_string[256];
        snprintf(connect_string, sizeof(connect_string), "%s:%d", entry->ip, entry->port);

        BIO_set_conn_hostname(bio, connect_string);
        if (BIO_do_connect(bio) <= 0) {
            log_message("Connection attempt failed.");
            sleep(1 << retries); // Exponential backoff
            continue;
        }

        ssl = SSL_new(ctx);
        SSL_set_bio(ssl, bio, bio);

        if (SSL_connect(ssl) <= 0) {
            log_message("TLS handshake failed.");
            BIO_free_all(bio);
            continue;
        }

        entry->latency = /* Calculate latency */;
        break;
    }

    // Cleanup
    SSL_shutdown(ssl);
    SSL_free(ssl);
    BIO_free_all(bio);
    SSL_CTX_free(ctx);

    log_message("TLS connection established.");
}

void process_servers() {
    for (int i = 0; i < server_count; ++i) {
        tls_connection(servers[i]);
    }
}

void cleanup() {
    for (int i = 0; i < server_count; ++i) {
        free(servers[i]);
    }
}

int main() {
    SSL_load_error_strings();
    OpenSSL_add_ssl_algorithms();

    read_config();
    process_servers();

    cleanup();

    EVP_cleanup();
    return 0;
}
