#include <openssl/ssl.h>
#include <openssl/err.h>
#include <curl/curl.h>
#include "crypto_lib.h"

#define MAX_RETRIES 5

typedef struct {
    char *server_url;
    char *oauth_token;
    double response_latency;
} ServerEntry;

typedef struct {
    ServerEntry *entries;
    size_t count;
} ConfigData;

void log_error(const char *message) {
    FILE *log_file = fopen("app_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Process response data
    return size * nmemb;
}

void free_config_data(ConfigData *config) {
    for (size_t i = 0; i < config->count; ++i) {
        free(config->entries[i].server_url);
        free(config->entries[i].oauth_token);
    }
    free(config->entries);
}

ConfigData load_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return (ConfigData){NULL, 0};

    ConfigData config;
    config.count = 0;

    // Read file and allocate memory dynamically
    // Assuming each line contains a server URL for simplicity
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        ServerEntry entry;
        entry.server_url = strdup(strtok(line, "\n"));
        entry.oauth_token = NULL;
        entry.response_latency = 0.0;

        config.entries = realloc(config.entries, sizeof(ServerEntry) * (++config.count));
        config.entries[config.count - 1] = entry;
    }
    fclose(file);
    return config;
}

void handle_ssl_error() {
    ERR_print_errors_fp(stderr);
    abort();
}

ServerEntry process_server_entry(const ServerEntry *entry) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char error_buffer[CURL_ERROR_SIZE] = {0};

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (!curl) return (ServerEntry){NULL, NULL, 0.0};

    double start_time = clock();
    int retries = 0;

    while (retries < MAX_RETRIES) {
        curl_easy_setopt(curl, CURLOPT_URL, entry->server_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        res = curl_easy_perform(curl);

        if (res == CURLE_OK) break;
        else {
            retries++;
            sleep(1 << retries);  // Exponential backoff
            log_error("Connection failed. Retrying...");
        }
    }

    double end_time = clock();
    ServerEntry result;
    result.server_url = strdup(entry->server_url);
    result.oauth_token = strdup("dummy_oauth_token");  // Replace with actual token retrieval logic
    result.response_latency = (end_time - start_time) / CLOCKS_PER_SEC;

    if (res != CURLE_OK) {
        snprintf(error_buffer, sizeof(error_buffer), "Error: %s", curl_easy_strerror(res));
        log_error(error_buffer);
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ConfigData config = load_config(argv[1]);

    for (size_t i = 0; i < config.count; ++i) {
        ServerEntry processed_entry = process_server_entry(&config.entries[i]);
        printf("Processed: %s, Token: %s, Latency: %.2f\n", processed_entry.server_url,
               processed_entry.oauth_token, processed_entry.response_latency);
    }

    free_config_data(&config);

    return 0;
}
