# Python Function: oauth2_auth.py

import requests

def authenticate_user(client_id, client_secret, token_url):
    data = {
        'client_id': client_id,
        'client_secret': client_secret,
        'grant_type': 'client_credentials'
    }
    response = requests.post(token_url, data=data)

    if response.status_code == 200:
        return response.json().get('access_token')
    else:
        raise Exception(f"Authentication failed: {response.content}")

def validate_and_fetch_user_info(access_token, user_info_url):
    headers = {'Authorization': f'Bearer {access_token}'}
    response = requests.get(user_info_url, headers=headers)

    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to fetch user info: {response.content}")

# Usage Example
if __name__ == "__main__":
    client_id = 'your_client_id'
    client_secret = 'your_client_secret'
    token_url = 'https://example.com/oauth/token'
    user_info_url = 'https://example.com/user/info'

    try:
        access_token = authenticate_user(client_id, client_secret, token_url)
        user_info = validate_and_fetch_user_info(access_token, user_info_url)
        print("User Info:", user_info)
    except Exception as e:
        print(str(e))
