#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example max memory usage in bytes

typedef struct Node {
    int value;
    struct Node* next;
    char* data;
} Node;

static unsigned long allocated_memory = 0;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    allocated_memory += size;
    if (allocated_memory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Maximum memory usage exceeded\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void safe_free(void* ptr, size_t size) {
    if (ptr) {
        free(ptr);
        allocated_memory -= size;
    }
}

void seed_random() {
    srand((unsigned int)time(NULL));
}

int generate_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Node* create_node(int value, const char* data_str, size_t data_size) {
    Node* node = safe_malloc(sizeof(Node));
    node->value = value;
    node->next = NULL;

    size_t str_size = strlen(data_str) + 1; // Include null terminator
    if (str_size > data_size) str_size = data_size; // Ensure it fits

    node->data = safe_malloc(str_size);
    strncpy(node->data, data_str, str_size - 1);
    node->data[str_size - 1] = '\0';

    return node;
}

void free_node(Node* node, size_t data_size) {
    if (node) {
        safe_free(node->data, data_size + 1); // Plus one for null terminator
        safe_free(node, sizeof(Node));
    }
}

uint8_t* serialize_data_structure(Node* head, size_t* out_size) {
    uint8_t* buffer = NULL;
    size_t current_offset = 0;

    Node* current = head;
    while (current != NULL) {
        // Estimate space for each node
        size_t value_size = sizeof(current->value);
        size_t data_size = strlen(current->data) + 1; // Include null terminator

        uint8_t* new_buffer = realloc(buffer, current_offset + value_size + sizeof(size_t) + data_size);
        if (!new_buffer) {
            fprintf(stderr, "Memory allocation failed during serialization\n");
            safe_free(buffer, current_offset);
            exit(EXIT_FAILURE);
        }
        buffer = new_buffer;

        // Serialize node
        memcpy(buffer + current_offset, &current->value, value_size);

        size_t data_len;
        memcpy(buffer + current_offset + value_size, &data_len, sizeof(data_len));
        memcpy(buffer + current_offset + value_size + sizeof(data_len), current->data, data_len);

        current_offset += value_size + sizeof(size_t) + data_len;

        current = current->next;
    }

    *out_size = current_offset;
    return buffer;
}

Node* deserialize_data_structure(const uint8_t* buffer, size_t size) {
    Node* head = NULL;
    Node** last_node_ptr = &head;

    size_t offset = 0;

    while (offset < size) {
        int value;
        memcpy(&value, buffer + offset, sizeof(value));
        offset += sizeof(value);

        size_t data_len;
        memcpy(&data_len, buffer + offset, sizeof(data_len));
        offset += sizeof(data_len);

        char* data = safe_malloc(data_len);
        memcpy(data, buffer + offset, data_len);
        offset += data_len;

        Node* new_node = create_node(value, data, data_len - 1); // Minus one because we've already allocated
        *last_node_ptr = new_node;
        last_node_ptr = &new_node->next;

        safe_free(data, data_len); // Free temporary buffer
    }

    return head;
}

void free_data_structure(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current, strlen(current->data));
        current = next;
    }
}

int main() {
    seed_random();

    Node* list_head = create_node(generate_random_value(1, 100), "Sample data", 20);
    list_head->next = create_node(generate_random_value(1, 100), "Another node", 15);

    size_t serialized_size;
    uint8_t* serialized_data = serialize_data_structure(list_head, &serialized_size);

    Node* deserialized_head = deserialize_data_structure(serialized_data, serialized_size);

    free(serialized_data); // Free the serialized data

    free_data_structure(deserialized_head);

    return 0;
}
