```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
import <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} record;

typedef struct node {
    record rec;
    struct node *next;
} node_t;

typedef struct {
    node_t *head;
    pthread_mutex_t lock;
} linked_list;

linked_list* init_list() {
    linked_list *list = malloc(sizeof(linked_list));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(linked_list *list) {
    node_t *current = list->head;
    while (current != NULL) {
        node_t *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int append_record(linked_list *list, record rec) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    new_node->rec = rec;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

uint32_t calculate_checksum(void *data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += ((unsigned char*)data)[i];
    }
    return checksum;
}

int serialize_data(linked_list *list, uint8_t **buffer, size_t *length) {
    if (!list || !buffer || !length) return -1;

    node_t *current = list->head;
    // Calculate length
    size_t total_size = 0;
    while (current != NULL) {
        total_size += sizeof(int) + sizeof(long);
        current = current->next;
    }

    total_size += sizeof(uint32_t); // For checksum

    *buffer = malloc(total_size);
    if (!*buffer) return -2;

    uint8_t *ptr = *buffer;
    current = list->head;
    while (current != NULL) {
        memcpy(ptr, &current->rec.value, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &current->rec.offset, sizeof(long));
        ptr += sizeof(long);
        current = current->next;
    }

    uint32_t checksum = calculate_checksum(*buffer, total_size - sizeof(uint32_t));
    memcpy(ptr, &checksum, sizeof(checksum));

    *length = total_size;

    return 0;
}

int deserialize_data(linked_list *list, const uint8_t *data, size_t length) {
    if (!list || !data) return -1;

    pthread_mutex_lock(&list->lock);

    node_t *current = list->head;
    while (current != NULL) {
        free(current);
        current = current->next;
    }

    const uint8_t *ptr = data;
    size_t records_count = (length - sizeof(uint32_t)) / (sizeof(int) + sizeof(long));

    for (size_t i = 0; i < records_count; ++i) {
        int value;
        long offset;

        memcpy(&value, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&offset, ptr, sizeof(long));
        ptr += sizeof(long);

        record rec = { .value = value, .offset = offset };
        append_record(list, rec);
    }

    uint32_t checksum;
    memcpy(&checksum, ptr, sizeof(checksum));

    if (calculate_checksum(data, length - sizeof(uint32_t)) != checksum) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Checksum mismatch
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void free_resources(linked_list *list, uint8_t *buffer) {
    free_list(list);
    if (buffer) free(buffer);
}

int main() {
    linked_list *list = init_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize list\n");
        return -1;
    }

    srand(time(NULL)); // For reproducibility
    int random_seed = rand();

    for (int i = 0; i < 10; ++i) {
        record rec = { .value = rand() % INT_MAX, .offset = (long)i * 100 };
        if (append_record(list, rec)) {
            fprintf(stderr, "Failed to append record\n");
            free_resources(list, NULL);
            return -1;
        }
    }

    uint8_t *buffer;
    size_t length;

    if (serialize_data(list, &buffer, &length) != 0) {
        fprintf(stderr, "Serialization failed\n");
        free_resources(list, buffer);
        return -1;
    }

    linked_list *deserialized_list = init_list();
    if (!deserialized_list) {
        fprintf(stderr, "Failed to initialize deserialized list\n");
        free_resources(list, buffer);
        return -1;
    }

    if (deserialize_data(deserialized_list, buffer, length) != 0) {
        fprintf(stderr, "Deserialization failed\n");
        free_resources(list, buffer);
        free_resources(deserialized_list, NULL);
        return -1;
    }

    printf("Serialization and deserialization successful!\n");

    free_resources(list, buffer);
    free_resources(deserialized_list, NULL);

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management**: Uses a linked list to manage memory dynamically.
- **Thread Safety**: Utilizes mutex locks for thread-safe access to shared resources.
- **Serialization/Deserialization**: Converts data structures to and from byte arrays with checksum validation.
- **Error Handling**: Checks for allocation failures and other errors, providing error codes and messages.
- **Memory Cleanup**: Ensures all allocated memory is freed upon completion or error.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_MEMORY_SIZE 1048576 // 1MB max size

typedef struct Edge {
    int destination_vertex_id;
    float weight;
    time_t timestamp; 
} Edge;

typedef struct Vertex {
    int identifier;
    char label[256];
    Edge *edges;
    size_t edge_count;
} Vertex;

typedef struct Graph {
    Vertex **vertices;
    size_t vertex_count;
    size_t max_vertex_count;
    uint8_t *allocated_memory;
    size_t allocated_size;
    size_t current_memory_usage;
} Graph;

void* safe_malloc(size_t size);
void* safe_realloc(void *ptr, size_t size);
Graph* create_graph();
int add_vertex(Graph *graph, int identifier, const char *label);
int add_edge(Graph *graph, int src_id, int dest_id, float weight, time_t timestamp);
void free_graph(Graph **graph);
size_t calculate_memory_usage(const Graph *graph);

// Memory management functions
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void* safe_realloc(void *ptr, size_t size) {
    void *new_ptr = realloc(ptr, size);
    if (!new_ptr) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(ptr);
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

// Graph functions
Graph* create_graph() {
    Graph *graph = (Graph*)safe_malloc(sizeof(Graph));
    graph->vertices = NULL;
    graph->vertex_count = 0;
    graph->max_vertex_count = 10; // Initial allocation for vertices
    graph->allocated_memory = safe_malloc(MAX_MEMORY_SIZE);
    graph->allocated_size = MAX_MEMORY_SIZE;
    graph->current_memory_usage = sizeof(Graph) + (graph->max_vertex_count * sizeof(Vertex*));
    graph->vertices = (Vertex**)safe_malloc(graph->max_vertex_count * sizeof(Vertex*));
    return graph;
}

int add_vertex(Graph *graph, int identifier, const char *label) {
    if ((graph->current_memory_usage + sizeof(Vertex)) > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Memory limit exceeded\n");
        return -1;
    }

    if (graph->vertex_count >= graph->max_vertex_count) {
        size_t new_max = graph->max_vertex_count * 2;
        Vertex **new_vertices = (Vertex**)safe_realloc(graph->vertices, new_max * sizeof(Vertex*));
        memset(new_vertices + graph->max_vertex_count, 0, graph->max_vertex_count * sizeof(Vertex*));

        graph->vertices = new_vertices;
        graph->max_vertex_count = new_max;
    }

    Vertex *vertex = (Vertex*)safe_malloc(sizeof(Vertex));
    vertex->identifier = identifier;
    strncpy(vertex->label, label, sizeof(vertex->label) - 1);
    vertex->edges = NULL;
    vertex->edge_count = 0;

    graph->vertices[graph->vertex_count] = vertex;
    graph->current_memory_usage += sizeof(Vertex);

    graph->vertex_count++;
    return 0;
}

int add_edge(Graph *graph, int src_id, int dest_id, float weight, time_t timestamp) {
    Vertex *src_vertex = NULL;
    for (size_t i = 0; i < graph->vertex_count; ++i) {
        if (graph->vertices[i]->identifier == src_id) {
            src_vertex = graph->vertices[i];
            break;
        }
    }

    if (!src_vertex) {
        fprintf(stderr, "Source vertex not found\n");
        return -1;
    }

    Edge *new_edge = (Edge*)safe_malloc(sizeof(Edge));
    new_edge->destination_vertex_id = dest_id;
    new_edge->weight = weight;
    new_edge->timestamp = timestamp;

    src_vertex->edges = (Edge*)safe_realloc(src_vertex->edges, 
                                            (src_vertex->edge_count + 1) * sizeof(Edge));

    memcpy(src_vertex->edges + src_vertex->edge_count, new_edge, sizeof(Edge));
    free(new_edge);

    src_vertex->edge_count++;
    graph->current_memory_usage += sizeof(Edge);

    return 0;
}

void free_graph(Graph **graph) {
    if (graph == NULL || *graph == NULL) return;

    for (size_t i = 0; i < (*graph)->vertex_count; ++i) {
        Vertex *v = (*graph)->vertices[i];
        free(v->edges);
    }

    free((*graph)->vertices);
    free((*graph)->allocated_memory);
    free(*graph);
    *graph = NULL;
}

size_t calculate_memory_usage(const Graph *graph) {
    size_t total_size = sizeof(Graph) + (graph->max_vertex_count * sizeof(Vertex*));
    for (size_t i = 0; i < graph->vertex_count; ++i) {
        Vertex *v = graph->vertices[i];
        total_size += sizeof(Vertex);
        total_size += v->edge_count * sizeof(Edge);
    }
    return total_size;
}

// Example main function to demonstrate usage
int main() {
    Graph *graph = create_graph();

    add_vertex(graph, 1, "Vertex A");
    add_vertex(graph, 2, "Vertex B");

    time_t now = time(NULL);
    add_edge(graph, 1, 2, 10.5, now);

    printf("Memory usage: %zu bytes\n", calculate_memory_usage(graph));

    free_graph(&graph);
    return 0;
}
```

