#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_MAX_RECORDS 1000
#define MAX_WORD_LENGTH 20
#define KEY_RANGE 10000

typedef struct {
    int key;
    char *value;
    time_t timestamp;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

static const char *default_word_pool[] = {"alpha", "beta", "gamma", "delta", "epsilon"};
static size_t default_word_count = sizeof(default_word_pool) / sizeof(const char *);

Record *create_record(int key, const char *value) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    record->value = strdup(value);
    if (!record->value) {
        free(record);
        return NULL;
    }
    record->timestamp = time(NULL);
    return record;
}

void destroy_record(Record *record) {
    if (record) {
        free(record->value);
        free(record);
    }
}

char *generate_random_word(const char **word_pool, size_t word_count) {
    size_t index = rand() % word_count;
    return strdup(word_pool[index]);
}

int resize_collection(RecordCollection *collection, size_t new_capacity) {
    Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
    if (!new_records) return -1;

    collection->records = new_records;
    memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(Record *));
    collection->capacity = new_capacity;
    return 0;
}

int add_record_to_collection(RecordCollection *collection, Record *record) {
    if (!collection || !record) return -1;

    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        if (resize_collection(collection, collection->capacity * 2) != 0) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
    }

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

RecordCollection *init_record_collection(size_t max_records) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = (max_records > DEFAULT_MAX_RECORDS ? max_records : DEFAULT_MAX_RECORDS);
    collection->records = calloc(collection->capacity, sizeof(Record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        destroy_record(collection->records[i]);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    RecordCollection *collection = init_record_collection(100);
    if (!collection) {
        fprintf(stderr, "Failed to initialize record collection.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 50; ++i) { // Add some records
        int key = rand() % KEY_RANGE;
        char *word = generate_random_word(default_word_pool, default_word_count);
        Record *record = create_record(key, word);

        if (!record || add_record_to_collection(collection, record) != 0) {
            fprintf(stderr, "Failed to add record with key %d.\n", key);
            destroy_record(record); // Clean up on failure
        } else {
            printf("Added record with key %d\n", key);
        }

        free(word);
    }

    destroy_record_collection(collection);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Dynamic Resizing**: The collection resizes itself when it reaches capacity.
- **Concurrency Support**: Uses `pthread_mutex` to ensure thread-safe access.
- **Memory Management**: Allocates and deallocates memory carefully to avoid leaks.
- **Error Handling**: Gracefully handles errors like memory allocation failures.
- **Random Word Generation**: Defaults to a predefined pool if external sources fail.']

