    if ((*container)->offsets == NULL) {
        free(*container);
        return -3; // Memory allocation failed
    }

    int found;
    for (long i = 0; i < n_offsets; ++i) {
        do {
            found = 0;
            (*container)->offsets[i] = rand() % (MAX_OFFSET + 1); // Random value between 0 and MAX_OFFSET
            for (long j = 0; j < i; ++j) {
                if ((*container)->offsets[j] == (*container)->offsets[i]) {
                    found = 1;
                    break;
                }
            }
        } while (found);
    }

    // Allocate memory for keys array and initialize with unique values from 0 to n_keys - 1
    (*container)->keys = (int *)malloc(n_keys * sizeof(int));
    if ((*container)->keys == NULL) {
        free((*container)->offsets);
        free(*container);
        return -4; // Memory allocation failed
    }

    for (int i = 0; i < n_keys; ++i) {
        (*container)->keys[i] = i;
    }

    // Allocate memory for records array and initialize with random values under max_sum constraint
    (*container)->records = (record_t *)malloc(n_records * sizeof(record_t));
    if ((*container)->records == NULL) {
        free((*container)->keys);
        free((*container)->offsets);
        free(*container);
        return -5; // Memory allocation failed
    }

    long sum = 0;
    for (long i = 0; i < n_records; ++i) {
        int value;
        do {
            value = min_val + rand() % (max_val - min_val + 1); // Random value between min_val and max_val
        } while ((sum + value > max_sum && i < n_records - 1) || 
                 (sum + value == max_sum && i != n_records - 1));

        (*container)->records[i].value = value;
        sum += value;
    }

    return 0; // Success
}

void free_records_container(records_container_t *container) {
    if (container) {
        if (container->offsets) free(container->offsets);
        if (container->keys) free(container->keys);
        if (container->records) free(container->records);
