```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Record structure definition
typedef struct {
    int value;
    char *str;
    time_t timestamp;
} Record;

// Configuration structure
typedef struct {
    size_t max_records;
    int min_key, max_key;
    int log_level; // 0: None, 1: Errors, 2: Debug
} Config;

// External data store simulation
typedef struct {
    pthread_mutex_t lock;
    long offset;
    Record *records;
    size_t count;
} DataStore;

// Function prototypes
void initialize_data_store(DataStore *store, size_t max_records);
void free_data_store(DataStore *store);
int generate_random_string(char *str, size_t max_length);
void populate_and_update_store(const Config *config, DataStore *store);
void log_message(int level, const char *message);

// Initialize the data store
void initialize_data_store(DataStore *store, size_t max_records) {
    pthread_mutex_init(&store->lock, NULL);
    store->offset = 0;
    store->records = malloc(max_records * sizeof(Record));
    if (!store->records) {
        log_message(1, "Memory allocation failed for records.");
        exit(EXIT_FAILURE);
    }
    store->count = 0;
}

// Free the data store resources
void free_data_store(DataStore *store) {
    pthread_mutex_lock(&store->lock);
    for (size_t i = 0; i < store->count; ++i) {
        if (store->records[i].str) {
            free(store->records[i].str);
        }
    }
    free(store->records);
    pthread_mutex_unlock(&store->lock);
    pthread_mutex_destroy(&store->lock);
}

// Generate a random string
int generate_random_string(char *str, size_t max_length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (max_length == 0 || !str) return -1;

    for (size_t i = 0; i < max_length; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[max_length] = '\0';
    return 0;
}

// Populate and update the data store
void populate_and_update_store(const Config *config, DataStore *store) {
    pthread_mutex_lock(&store->lock);

    for (size_t i = 0; i < config->max_records && store->count < config->max_records; ++i) {
        if (store->records == NULL || store->count >= config->max_records) break;

        Record *record = &store->records[store->count];
        record->value = rand() % (config->max_key - config->min_key + 1) + config->min_key;
        record->timestamp = time(NULL);

        char *str = malloc(51); // Allocate memory for string plus null terminator
        if (!str) {
            log_message(1, "Memory allocation failed for string.");
            break;
        }

        generate_random_string(str, 50);
        record->str = str;

        store->offset++;
        store->count++;

        // Log the operation based on config level
        if (config->log_level > 0) {
            log_message(config->log_level, "Record added.");
        }
    }

    pthread_mutex_unlock(&store->lock);
}

// Log messages according to the configured level
void log_message(int level, const char *message) {
    if (level <= config.log_level) {
        printf("%s\n", message);
    }
}

int main() {
    Config config = {10, 1, 100, 2}; // Example configuration
    DataStore store;

    srand(time(NULL)); // Seed random number generator
    initialize_data_store(&store, config.max_records);

    populate_and_update_store(&config, &store);

    free_data_store(&store);

    return 0;
}
```

