```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Define the structure for memory pool (simplified)
typedef struct {
    void *memory;
    size_t chunk_size;
    size_t total_chunks;
    pthread_mutex_t lock; // Ensure thread safety
} MemoryPool;

// Function declarations
MemoryPool* create_memory_pool(size_t chunk_size, size_t total_chunks);
void free_memory_pool(MemoryPool* pool);
long* allocate_long_array(MemoryPool *pool, int size);
int* allocate_int_array(MemoryPool *pool, int size);
record* allocate_record_array(MemoryPool *pool, int size);
void set_random_values(record *records, int min_val, int max_val);
void log_error(const char *message);

// Create a memory pool
MemoryPool* create_memory_pool(size_t chunk_size, size_t total_chunks) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory = malloc(chunk_size * total_chunks);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pool->chunk_size = chunk_size;
    pool->total_chunks = total_chunks;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Free a memory pool
void free_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->memory);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

long* allocate_long_array(MemoryPool *pool, int size) {
    long *array = NULL;

    pthread_mutex_lock(&pool->lock);
    array = (long*)malloc(size * sizeof(long));
    if (!array) {
        log_error("Failed to allocate long array");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);

    return array;
}

int* allocate_int_array(MemoryPool *pool, int size) {
    int *array = NULL;

    pthread_mutex_lock(&pool->lock);
    array = (int*)malloc(size * sizeof(int));
    if (!array) {
        log_error("Failed to allocate int array");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);

    return array;
}

record* allocate_record_array(MemoryPool *pool, int size) {
    record *records = NULL;

    pthread_mutex_lock(&pool->lock);
    records = (record*)malloc(size * sizeof(record));
    if (!records) {
        log_error("Failed to allocate record array");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);

    return records;
}

void set_random_values(record *records, int min_val, int max_val) {
    if (records == NULL) return;

    for (int i = 0; i < sizeof(records)/sizeof(record); ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void log_error(const char *message) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    FILE *log_file = fopen("error_log.txt", "a");

    if (!log_file) return;

    pthread_mutex_lock(&log_lock);
    fprintf(log_file, "%s\n", message);
    fflush(log_file); // Ensure it's written immediately
    pthread_mutex_unlock(&log_lock);

    fclose(log_file);
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Seed random number generator

    int array_size = 1000;
    int min_val = 1, max_val = 100;

    MemoryPool *pool = create_memory_pool(1024, 10);
    if (!pool) return EXIT_FAILURE;

    long *offsets = allocate_long_array(pool, array_size);
    int *keys = allocate_int_array(pool, array_size);
    record *records = allocate_record_array(pool, array_size);

    if (offsets && keys && records) {
        set_random_values(records, min_val, max_val);
        free(offsets);
        free(keys);
        free(records);
    }

    free_memory_pool(pool);

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Memory Pool:** A simplified memory pool is used to manage allocation in a thread-safe manner using `pthread_mutex_t`.

- **Error Logging:** Errors are logged with minimal performance impact by limiting the frequency of logging operations and locking access.

- **Random Number Generation:** Uses `rand()` seeded with current time; consider using an external library like `librandom` for more complex, thread-local random generation.

- **Thread Safety:** Memory allocation uses mutex locks to ensure that concurrent allocations are managed safely.

- **Modular Design:** The code is modular enough to allow easy integration and adjustments of parameters.']

