#include <string.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Collection;

void log_message(const char *message) {
    // Placeholder for integration with an external logging service
    printf("%s\n", message);
}

Collection* create_collection(size_t initial_capacity) {
    Collection *collection = (Collection *)malloc(sizeof(Collection));
    if (!collection) {
        log_message("Failed to allocate memory for collection.");
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    collection->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        log_message("Failed to allocate memory for records.");
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;

    log_message("Collection created successfully.");
    return collection;
}

int add_record(Collection *collection, int key, long offset) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->mutex);

    // Check for existing key
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->mutex);
            log_message("Duplicate key detected, record not added.");
            return -1;
        }
    }

    // Resize array if needed
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record *new_records = (Record *)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            log_message("Failed to allocate memory for record expansion.");
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;

        log_message("Collection resized successfully.");
    }

    // Add new record
    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    ++collection->count;

    pthread_mutex_unlock(&collection->mutex);
    log_message("Record added successfully.");

    return 0;
}

void destroy_collection(Collection *collection) {
    if (!collection) return;

    pthread_mutex_destroy(&collection->mutex);
    free(collection->records);
    free(collection);

    log_message("Collection destroyed.");
}
