```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_WORD_POOL_SIZE 10
#define MAX_STRING_LENGTH 100
#define KEY_RANGE_START 1

typedef struct {
    int key;
    char *value;
    time_t timestamp;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

const char *default_word_pool[] = {"alpha", "beta", "gamma", "delta", "epsilon"};
const int default_word_count = DEFAULT_WORD_POOL_SIZE;

// Thread-safe memory allocation and deallocation
void* thread_safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void thread_safe_free(void *ptr) {
    free(ptr);
}

// Function to initialize a record
Record* create_record(int key, const char* value) {
    Record *record = (Record*)thread_safe_malloc(sizeof(Record));
    record->key = key;
    record->value = strdup(value);  // Duplicate string safely

    if (!record->value) {
        perror("Failed to duplicate string");
        thread_safe_free(record);
        return NULL;
    }

    record->timestamp = time(NULL);

    return record;
}

// Function to resize the collection
int resize_collection(RecordCollection *collection, size_t new_capacity) {
    pthread_mutex_lock(&collection->lock);

    Record **new_records = (Record**)thread_safe_malloc(new_capacity * sizeof(Record*));
    if (!new_records) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        new_records[i] = collection->records[i];
    }

    thread_safe_free(collection->records);
    collection->records = new_records;
    collection->capacity = new_capacity;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

// Function to add a record
int add_record(RecordCollection *collection, int key, const char* value) {
    if (key < KEY_RANGE_START || collection->count >= collection->capacity) {
        if (resize_collection(collection, collection->capacity * 2)) {
            return -1;
        }
    }

    Record *record = create_record(key, value);
    if (!record) {
        return -1;
    }

    pthread_mutex_lock(&collection->lock);

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

// Function to initialize the collection
int init_collection(RecordCollection *collection, size_t max_capacity) {
    collection->capacity = max_capacity;
    collection->count = 0;
    collection->records = (Record**)thread_safe_malloc(max_capacity * sizeof(Record*));

    if (!collection->records) {
        return -1;
    }

    pthread_mutex_init(&collection->lock, NULL);

    return 0;
}

// Function to clean up the collection
void cleanup_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        thread_safe_free(collection->records[i]->value);
        thread_safe_free(collection->records[i]);
    }

    thread_safe_free(collection->records);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

// Example function to get a word from the pool (with fallback)
const char* get_word_from_pool() {
    static int index = 0;
    // Simulate API failure by returning NULL
    const char *word = default_word_pool[index % default_word_count];

    if (word) {
        index++;
    } else {
        word = "default";
    }

    return word;
}

// Function to demonstrate usage
int main() {
    RecordCollection collection;
    int init_result = init_collection(&collection, 10);

    if (init_result != 0) {
        fprintf(stderr, "Failed to initialize the record collection\n");
        return EXIT_FAILURE;
    }

    for (int i = KEY_RANGE_START; i < KEY_RANGE_START + 15; ++i) {
        const char *word = get_word_from_pool();
        int result = add_record(&collection, i, word);

        if (result != 0) {
            fprintf(stderr, "Failed to add record with key %d\n", i);
        }
    }

    // Clean up
    cleanup_collection(&collection);

    return EXIT_SUCCESS;
}
```

