#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

// Define constants for maximum sizes and cache size.
#define MAX_ARRAY_SIZE 10000
#define CACHE_SIZE 128

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t lock;
    size_t allocation_count;
    size_t fragmentation_level; // Simplified metric
    float cache_hit_rate;
} MemoryPool;

// Random number cache structure
typedef struct {
    int numbers[CACHE_SIZE];
    int index;
    pthread_rwlock_t rwlock;
} RandomCache;

MemoryPool *init_memory_pool(size_t max_size) {
    if (max_size > MAX_ARRAY_SIZE) return NULL;

    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->offsets = malloc(max_size * sizeof(long));
    pool->keys = malloc(max_size * sizeof(int));
    pool->current_size = 0;
    pool->max_size = max_size;
    pthread_mutex_init(&pool->lock, NULL);
    pool->allocation_count = 0;
    pool->fragmentation_level = 0; // Placeholder
    pool->cache_hit_rate = 0.0f;

    return pool;
}

void *resize_memory_pool(MemoryPool *pool, size_t new_size) {
    if (new_size > MAX_ARRAY_SIZE || new_size <= pool->current_size) return NULL;

    pthread_mutex_lock(&pool->lock);
    pool->offsets = realloc(pool->offsets, new_size * sizeof(long));
    pool->keys = realloc(pool->keys, new_size * sizeof(int));
    pool->max_size = new_size;
    pool->allocation_count++;
    pthread_mutex_unlock(&pool->lock);

    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    free(pool->offsets);
    free(pool->keys);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

record *init_records(size_t num_records) {
    record *records = malloc(num_records * sizeof(record));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = 0;
    }
    return records;
}

void free_records(record *records) {
    if (!records) return;
    free(records);
}

RandomCache *init_random_cache() {
    RandomCache *cache = malloc(sizeof(RandomCache));
    pthread_rwlock_init(&cache->rwlock, NULL);
    cache->index = 0;
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache->numbers[i] = rand();
    }
    return cache;
}

void free_random_cache(RandomCache *cache) {
    if (!cache) return;
    pthread_rwlock_destroy(&cache->rwlock);
    free(cache);
}

int get_random_number_from_cache(RandomCache *cache, int min_val, int max_val) {
    pthread_rwlock_rdlock(&cache->rwlock);

    if (cache->index < CACHE_SIZE) {
        int num = cache->numbers[cache->index];
        cache->index++;
        pthread_rwlock_unlock(&cache->rwlock);
        return ((num % (max_val - min_val + 1)) + min_val);
    }

    pthread_rwlock_unlock(&cache->rwlock);

    pthread_rwlock_wrlock(&cache->rwlock);
    if (cache->index >= CACHE_SIZE) {
        cache->numbers[0] = rand();
        for (int i = 1; i < CACHE_SIZE; ++i) {
            cache->numbers[i] = cache->numbers[i - 1];
        }
        cache->index = 1;
    }

    int num = cache->numbers[0];
    pthread_rwlock_unlock(&cache->rwlock);

    return ((num % (max_val - min_val + 1)) + min_val);
}

void populate_records(record *records, size_t num_records, RandomCache *cache, int min_val, int max_val) {
    if (!records || !cache || min_val > max_val) return;

    pthread_t threads[4];
    size_t chunk_size = num_records / 4;
    for (int i = 0; i < 4; ++i) {
        size_t start_idx = i * chunk_size;
        size_t end_idx = (i == 3) ? num_records : start_idx + chunk_size;

        pthread_create(&threads[i], NULL, (void *(*)(void *))[] (void *arg) -> void* {
            int *params = (int *)arg;
            for (size_t j = params[0]; j < params[1]; ++j) {
                records[j].value = get_random_number_from_cache(cache, min_val, max_val);
            }
            return NULL;
        }, &start_idx);

        pthread_join(threads[i], NULL);
    }
}

void cleanup(MemoryPool *pool, record *records, RandomCache *cache) {
    free_memory_pool(pool);
    free_records(records);
    free_random_cache(cache);
}
