    // Allocate and initialize identifiers.
    size_t charArraySize = 256 * count; // Example identifier size.
    if (charArraySize > maxMemory - totalSize) {
        free(records);
        return NULL;
    }

    char* idData = malloc(charArraySize);
    if (!idData) {
