#include <stdio.h>
#include <stdlib.h>
import pthread.h

#define INITIAL_CAPACITY 10
#define RESIZE_FACTOR 2

typedef enum {
    TASK_PENDING,
    TASK_RUNNING,
    TASK_COMPLETED
} TaskStatus;

typedef struct {
    int id;
    int priority;
    TaskStatus status;
} Task;

typedef struct {
    Task *tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int operation_count;
    int error_count;
} TaskList;

void log_operation(TaskList *list, const char *message) {
    printf("%s\n", message);  // Simple logging mechanism
}

TaskList* create_task_list(size_t max_capacity) {
    TaskList *list = malloc(sizeof(TaskList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for TaskList.\n");
        return NULL;
    }

    list->tasks = malloc(max_capacity * sizeof(Task));
    if (!list->tasks) {
        free(list);
        fprintf(stderr, "Memory allocation failed for tasks array.\n");
        return NULL;
    }

    list->capacity = max_capacity;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);

    list->operation_count = 0;
    list->error_count = 0;

    log_operation(list, "TaskList initialized.");
    return list;
}

void destroy_task_list(TaskList *list) {
    if (list) {
        free(list->tasks);
        pthread_mutex_destroy(&list->lock);
        pthread_cond_destroy(&list->cond_var);
        free(list);

        log_operation(list, "TaskList destroyed.");
    }
}

int add_task(TaskList *list, Task task) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * RESIZE_FACTOR;
        Task *new_tasks = realloc(list->tasks, new_capacity * sizeof(Task));

        if (!new_tasks) {
            pthread_mutex_unlock(&list->lock);
            log_operation(list, "Failed to resize task array.");
            return -1;  // Error
        }

        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }

    list->tasks[list->size++] = task;

    pthread_cond_signal(&list->cond_var);
    pthread_mutex_unlock(&list->lock);

    log_operation(list, "Task added.");
    return 0; // Success
}

