```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DESCRIPTION_LENGTH 256

typedef struct {
    int key;
    long offset;
    char *description;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Collection;

Collection* collection_create(size_t initial_capacity) {
    Collection *collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) {
        fprintf(stderr, "Failed to allocate memory for collection.\n");
        return NULL;
    }

    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!collection->records) {
        fprintf(stderr, "Failed to allocate memory for records array.\n");
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    if (pthread_mutex_init(&collection->mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex.\n");
        free(collection->records);
        free(collection);
        return NULL;
    }

    return collection;
}

void log_error(const char *message) {
    // Placeholder for logging functionality
    printf("Error: %s\n", message);
}

int add_record(Collection *collection, int key, long offset, const char *description) {
    if (pthread_mutex_lock(&collection->mutex) != 0) {
        log_error("Failed to lock mutex.");
        return -1;
    }

    // Check for existing key
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            pthread_mutex_unlock(&collection->mutex);
            log_error("Duplicate key detected.");
            return -1;
        }
    }

    // Validate description length
    size_t desc_len = strlen(description);
    if (desc_len > MAX_DESCRIPTION_LENGTH || memchr(description, '\0', MAX_DESCRIPTION_LENGTH)) {
        pthread_mutex_unlock(&collection->mutex);
        log_error("Description validation failed.");
        return -1;
    }

    // Resize array if needed
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            log_error("Failed to resize records array.");
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    // Allocate and initialize new record
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->mutex);
        log_error("Failed to allocate memory for record.");
        return -1;
    }

    char *desc_copy = (char*)malloc((desc_len + 1) * sizeof(char));
    if (!desc_copy) {
        free(record);
        pthread_mutex_unlock(&collection->mutex);
        log_error("Failed to allocate memory for description.");
        return -1;
    }

    record->key = key;
    record->offset = offset;
    strncpy(desc_copy, description, MAX_DESCRIPTION_LENGTH);
    desc_copy[MAX_DESCRIPTION_LENGTH] = '\0';
    record->description = desc_copy;

    collection->records[collection->count++] = record;
    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

void free_collection(Collection *collection) {
    if (pthread_mutex_lock(&collection->mutex) != 0) {
        log_error("Failed to lock mutex for freeing.");
        return;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->description);
        free(collection->records[i]);
    }

    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);

    if (pthread_mutex_destroy(&collection->mutex) != 0) {
        log_error("Failed to destroy mutex.");
    }

    free(collection);
}

int main() {
    Collection *collection = collection_create(10);
    if (!collection) return -1;

    add_record(collection, 1, 100, "Description one");
    add_record(collection, 2, 200, "Description two");

    free_collection(collection);

    return 0;
}
```

This code provides a basic implementation of the task requirements. It uses mutexes to ensure thread safety and handles memory allocation failures gracefully by logging errors and cleaning up resources where necessary. The `add_record` function checks for duplicate keys and validates description lengths before adding new records.']

