#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_BUFFER_SIZE 256
#define MEMORY_LIMIT 1024 * 1024 // 1 MB
#define DEFAULT_PRIORITY_LEVEL 10

typedef struct {
    char buffer[MAX_BUFFER_SIZE];
    time_t timestamp;
    bool acknowledged;
    int priority;
} Message;

typedef struct Node {
    Message message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t memory_usage;
} PriorityQueue;

void init_priority_queue(PriorityQueue* pq) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
    pq->memory_usage = 0;
}

Message create_message(const char* content, int priority) {
    Message msg;
    strncpy(msg.buffer, content, MAX_BUFFER_SIZE - 1);
    msg.timestamp = time(NULL); // Seed with current time
    msg.acknowledged = false;
    msg.priority = priority;
    return msg;
}

void enqueue(PriorityQueue* pq, Message msg) {
    pthread_mutex_lock(&pq->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&pq->lock);
        return;
    }

    new_node->message = msg;
    pq->memory_usage += sizeof(Node);

    if (pq->head == NULL || pq->head->message.priority < msg.priority) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next != NULL && current->next->message.priority >= msg.priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq->lock);
}

bool dequeue(PriorityQueue* pq, Message* msg) {
    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL) {
        pthread_mutex_unlock(&pq->lock);
        return false;
    }

    Node* temp = pq->head;
    *msg = temp->message;
    pq->head = pq->head->next;
    free(temp);
    pq->memory_usage -= sizeof(Node);

    pthread_mutex_unlock(&pq->lock);
    return true;
}

void process_messages(PriorityQueue* pq) {
    Message msg;
    while (dequeue(pq, &msg)) {
        // Simulate message processing
        printf("Processing message: %s\n", msg.buffer);
        msg.acknowledged = true;  // Update acknowledgment status
    }
}

void read_messages_from_file(const char* filename, PriorityQueue* pq) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[MAX_BUFFER_SIZE];
    while (fgets(line, sizeof(line), file)) {
        // Simulate parsing and adding message
        enqueue(pq, create_message(line, DEFAULT_PRIORITY_LEVEL));
    }

    fclose(file);
}

void log_event(const char* event) {
    printf("Log: %s\n", event);  // Simple logging mechanism
}

int main() {
    PriorityQueue pq;
    init_priority_queue(&pq);

    read_messages_from_file("messages.txt", &pq);
    process_messages(&pq);

    log_event("Message processing completed");

    return 0;
}
