    Record *records;
    size_t count;
    size_t capacity;
    size_t max_size; // Maximum memory size for the records
    pthread_mutex_t lock; // Synchronization primitive
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity, size_t max_size) {
    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->max_size = max_size;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void log_error(const char *message) {
    // Simple logging function
    fprintf(stderr, "Error: %s\n", message);
}

int add_record(RecordCollection *collection, Record record) {
    size_t record_size = sizeof(record);

    pthread_mutex_lock(&collection->lock);

    if (collection->count * collection->capacity + record_size > collection->max_size) {
        log_error("Exceeded maximum memory size limit.");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;

        Record *new_records = (Record *)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            log_error("Memory allocation failed during capacity expansion.");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count] = record;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void free_record_collection(RecordCollection *collection) {
    if (collection) {
        if (collection->records) {
            free(collection->records);
        }
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

uint8_t* serialize_record_collection(const RecordCollection *collection, size_t *output_size) {
    uint8_t *byte_array = NULL;
    size_t total_size = 0;

    pthread_mutex_lock((pthread_mutex_t *)&collection->lock);

    // Calculate the total size needed for serialization
    total_size = collection->count * (sizeof(uint32_t) + sizeof(uint64_t) + 256 + 128);

    byte_array = (uint8_t *)malloc(total_size);
    if (!byte_array) {
        log_error("Memory allocation failed during serialization.");
        pthread_mutex_unlock((pthread_mutex_t *)&collection->lock);
        *output_size = 0;
        return NULL;
    }

    uint8_t *ptr = byte_array;
    for (size_t i = 0; i < collection->count; ++i) {
        Record record = collection->records[i];

        // Ensure endianness consistency during serialization
        uint32_t key_be = htonl(record.key);
        uint64_t offset_be = htonll(record.offset);

        memcpy(ptr, &key_be, sizeof(key_be));
        ptr += sizeof(key_be);

        memcpy(ptr, &offset_be, sizeof(offset_be));
        ptr += sizeof(offset_be);

        memcpy(ptr, record.value, 256);
        ptr += 256;

        memcpy(ptr, record.metadata, 128);
        ptr += 128;
    }

    pthread_mutex_unlock((pthread_mutex_t *)&collection->lock);
    *output_size = total_size;
    return byte_array;
}

uint64_t htonll(uint64_t value) {
    static const int num = sizeof("ABCD") - 1;

    if (num == 4) {
        uint32_t high_part = htonl((uint32_t)(value >> 32));
        uint32_t low_part = htonl((uint32_t)value);
        return ((uint64_t)low_part << 32) | high_part;
    } else {
        uint16_t high_part = htons((uint16_t)((value & 0x00000000FFFFFFFFULL) >> 48));
        uint16_t middle_high = htons((uint16_t)((value & 0x0000FFFF00000000ULL) >> 32));
        uint16_t middle_low = htons((uint16_t)((value & 0x00FF000000000000ULL) >> 16));
        uint16_t low_part = htons((uint16_t)(value & 0x000000000000FFFFULL));

        return ((uint64_t)high_part << 48) |
               ((uint64_t)middle_high << 32) |
               ((uint64_t)middle_low << 16) |
                (uint64_t)low_part;
    }
}

int main() {
    RecordCollection *collection = create_record_collection(10, 1024 * 1024); // Example values

    if (!collection) {
        log_error("Failed to initialize record collection.");
        return -1;
    }

    Record sample_record = { .key = 12345, .offset = 67890, 
                             .value = "Sample", .metadata = "Metadata" };

    add_record(collection, sample_record);

    size_t serialized_size;
    uint8_t *serialized_data = serialize_record_collection(collection, &serialized_size);
    if (serialized_data) {
        printf("Serialization succeeded. Data size: %zu bytes.\n", serialized_size);
        free(serialized_data); // Free the serialized data
    }

    free_record_collection(collection);

    return 0;
}
