```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

typedef struct {
    size_t max_size;
    size_t avg_threshold;
} Constraints;

typedef struct {
    unsigned int min;
    unsigned int max;
} Range;

typedef struct RandomHelper {
    time_t seed;
} RandomHelper;

Record* create_record(int key, long offset) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;
    new_record->key = key;
    new_record->offset = offset;
    new_record->next = NULL;
    return new_record;
}

void free_records(Record* head) {
    while (head) {
        Record* temp = head;
        head = head->next;
        free(temp);
    }
}

int insert_record(Record** head, int key, long offset, Constraints constraints) {
    Record* new_record = create_record(key, offset);
    if (!new_record) return -1;

    size_t record_size = sizeof(int) + sizeof(long) + sizeof(void*);
    size_t current_usage = 0;
    Record* temp = *head;

    while (temp) {
        current_usage += record_size;
        temp = temp->next;
    }

    if ((current_usage + record_size) > constraints.max_size || 
        (current_usage / (*head ? temp - *head : 1)) > constraints.avg_threshold) {
        free(new_record);
        return -2; // Memory limit exceeded or average size threshold exceeded
    }

    new_record->next = *head;
    *head = new_record;
    return 0;
}

RandomHelper* init_random_helper() {
    RandomHelper* helper = (RandomHelper*)malloc(sizeof(RandomHelper));
    if (!helper) return NULL;
    helper->seed = time(NULL);
    srand(helper->seed);
    return helper;
}

int random_int(Range range, RandomHelper* helper) {
    if (!helper) return -1;
    int r = rand() % (range.max - range.min + 1) + range.min;
    if ((r < range.min) || (r > range.max)) return -2; // Overflow/Underflow
    return r;
}

float random_float(Range range, RandomHelper* helper) {
    float min = (float)range.min;
    float max = (float)range.max;
    return min + ((float)rand() / RAND_MAX) * (max - min);
}

uint8_t* serialize_records(Record* head, size_t* length) {
    if (!head) return NULL;

    Record* temp = head;
    size_t total_size = 0;

    while (temp) {
        total_size += sizeof(int) + sizeof(long) + sizeof(void*);
        temp = temp->next;
    }

    uint8_t* buffer = (uint8_t*)malloc(total_size);
    if (!buffer) return NULL;

    temp = head;
    size_t offset = 0;

    while (temp) {
        memcpy(buffer + offset, &temp->key, sizeof(int));
        memcpy(buffer + offset + sizeof(int), &temp->offset, sizeof(long));
        offset += sizeof(int) + sizeof(long);
        temp = temp->next;
    }

    *length = total_size;
    return buffer;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

Record* initialize_records(size_t max_size, size_t avg_threshold, int num_records, Range key_range, RandomHelper* helper) {
    if (!helper || !num_records) return NULL;

    Constraints constraints = {max_size, avg_threshold};
    Record* head = NULL;

    for (int i = 0; i < num_records; ++i) {
        int key = random_int(key_range, helper);
        long offset = rand() % 100000L;

        if (insert_record(&head, key, offset, constraints) != 0) {
            log_error("Failed to insert record");
            free_records(head);
            return NULL;
        }
    }

    return head;
}

int main() {
    RandomHelper* helper = init_random_helper();
    if (!helper) {
        log_error("Failed to initialize random helper");
        return EXIT_FAILURE;
    }

    Range key_range = {1, 100};
    Record* records = initialize_records(1024, 64, 10, key_range, helper);

    if (!records) {
        log_error("Failed to initialize records");
        free(helper);
        return EXIT_FAILURE;
    }

    size_t length;
    uint8_t* serialized_data = serialize_records(records, &length);

    if (!serialized_data) {
        log_error("Serialization failed");
        free_records(records);
        free(helper);
        return EXIT_FAILURE;
    }

    printf("Serialized data length: %zu\n", length);

    // Cleanup
    free(serialized_data);
    free_records(records);
    free(helper);

    return EXIT_SUCCESS;
}
