#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>
#include <time.h>

#define CACHE_SIZE 100
#define TIMEOUT_SECONDS 5

typedef struct {
    char hostname[256];
    struct in_addr ip;
    time_t timestamp;
} CacheEntry;

typedef struct {
    CacheEntry entries[CACHE_SIZE];
    pthread_mutex_t lock;
} DNSCache;

DNSCache cache = {{0}, PTHREAD_MUTEX_INITIALIZER};

int initialize_cache() {
    pthread_mutex_init(&cache.lock, NULL);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        memset(cache.entries[i].hostname, 0, sizeof(cache.entries[i].hostname));
    }
    return 0;
}

void destroy_cache() {
    pthread_mutex_destroy(&cache.lock);
}

static int is_cache_valid(CacheEntry *entry) {
    if (time(NULL) - entry->timestamp > TIMEOUT_SECONDS) {
        memset(entry->hostname, 0, sizeof(entry->hostname));
        return 0;
    }
    return 1;
}

int get_from_cache(const char *hostname, struct in_addr *ip) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache.entries[i].hostname, hostname) == 0 && is_cache_valid(&cache.entries[i])) {
            memcpy(ip, &cache.entries[i].ip, sizeof(struct in_addr));
            pthread_mutex_unlock(&cache.lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache.lock);
    return 0;
}

void update_cache(const char *hostname, struct in_addr ip) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache.entries[i].hostname, hostname) == 0) {
            memcpy(&cache.entries[i].ip, &ip, sizeof(struct in_addr));
            cache.entries[i].timestamp = time(NULL);
            pthread_mutex_unlock(&cache.lock);
            return;
        } else if (!cache.entries[i].hostname[0]) {
            strncpy(cache.entries[i].hostname, hostname, sizeof(cache.entries[i].hostname) - 1);
            memcpy(&cache.entries[i].ip, &ip, sizeof(struct in_addr));
            cache.entries[i].timestamp = time(NULL);
            pthread_mutex_unlock(&cache.lock);
            return;
        }
    }
    pthread_mutex_unlock(&cache.lock);
}

int resolve_hostname_async(const char *hostname, struct in_addr *ip, int timeout) {
    if (!get_from_cache(hostname, ip)) {
        struct addrinfo hints, *res = NULL;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;

        pthread_t thread;
        void* (*resolve_thread_func)(void*);
        resolve_thread_func = malloc(sizeof(*resolve_thread_func));

        struct async_data {
            const char *hostname;
            struct in_addr *ip;
            int status;
        } data = { hostname, ip, -1 };

        *resolve_thread_func = (void *(*)(void*))[] (void* arg) -> void* {
            struct async_data* adata = (struct async_data*)arg;

            if (getaddrinfo(adata->hostname, NULL, &hints, &res) == 0) {
                struct in_addr addr;
                memcpy(&addr, res->ai_addr, sizeof(addr));
                pthread_mutex_lock(&cache.lock);
                update_cache(adata->hostname, addr);
                pthread_mutex_unlock(&cache.lock);

                adata->status = 0; // Success
                *adata->ip = addr;

            } else {
                adata->status = -1; // Failure
            }

            freeaddrinfo(res);
            return NULL;
        };

        data.status = -2; // Not started

        if (pthread_create(&thread, NULL, resolve_thread_func, &data) != 0) {
            perror("Failed to create thread");
            return -1;
        }

        pthread_detach(thread);

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += timeout;

        while (data.status == -2) { // Waiting for resolution
            if (pthread_mutex_lock(&cache.lock) != 0) {
                perror("Mutex lock failed");
                return -1;
            }

            if (get_from_cache(data.hostname, data.ip)) {
                pthread_mutex_unlock(&cache.lock);
                break; // Cache hit after async resolution
            }

            pthread_mutex_unlock(&cache.lock);

            if (nanosleep(&(ts.tv_nsec), &ts) == -1 && errno == EINTR) {
                continue;
            }

            break; // Timeout occurred
        }

        free(resolve_thread_func);
    }

    return cache.entries[CACHE_SIZE-1].hostname[0] ? 0 : -2; // Cache miss or not resolved in time
}

int main() {
    initialize_cache();
    struct in_addr ip;
    int result = resolve_hostname_async("example.com", &ip, TIMEOUT_SECONDS);

    if (result == 0) {
        printf("Resolved IP: %s\n", inet_ntoa(ip));
    } else {
        fprintf(stderr, "Resolution failed with error code %d\n", result);
    }

    destroy_cache();
    return 0;
}
```

### Key Points

- **Asynchronous Resolution**: Uses POSIX threads to handle DNS resolution without blocking the main execution thread.
- **Timeout Mechanism**: Waits for a specified period and exits if no response is received, ensuring the application does not hang indefinitely.
- **Caching with Expiry**: Maintains an in-memory cache of resolved hostnames with timestamps to avoid stale data.
- **Thread Safety**: Uses mutex locks to protect shared resources from concurrent access issues.
- **Error Handling**: Provides error codes for various failure scenarios (e.g., timeout, DNS resolution failure). 

This implementation can be expanded or optimized based on specific application needs and deployment environments.']

