```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jansson.h> // JSON library for serialization

#define MAX_MEMORY_USAGE 1048576 // 1MB limit
#define LOCK_TIMEOUT 5

typedef struct Record {
    int key;
    double value;
    char *metadata;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    size_t memory_usage;
} RecordList;

// Function declarations
RecordList* create_record_list();
void destroy_record_list(RecordList *list);
int add_record(RecordList *list, int key, double value, const char *metadata);
int delete_record(RecordList *list, int key);
int update_record(RecordList *list, int key, double new_value, const char *new_metadata);
void refresh_records_from_api(RecordList *list);
void log_memory_usage(const RecordList *list);

// Function implementations
RecordList* create_record_list() {
    RecordList *list = (RecordList*)malloc(sizeof(RecordList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->memory_usage = 0;
    return list;
}

void destroy_record_list(RecordList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->record.metadata);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_record(RecordList *list, int key, double value, const char *metadata) {
    if (pthread_mutex_trylock(&list->lock) != 0) return -1;

    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->record.key = key;
    new_node->record.value = value;
    new_node->record.metadata = strdup(metadata);

    size_t metadata_size = strlen(metadata) + 1;
    list->memory_usage += sizeof(Record) + metadata_size;

    if (list->memory_usage > MAX_MEMORY_USAGE) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory limit exceeded
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    log_memory_usage(list);
    return 0;
}

int delete_record(RecordList *list, int key) {
    if (pthread_mutex_trylock(&list->lock) != 0) return -1;

    Node **indirect = &list->head;
    while (*indirect != NULL && (*indirect)->record.key != key) {
        indirect = &(*indirect)->next;
    }

    if (*indirect == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Record not found
    }

    Node *to_delete = *indirect;
    *indirect = to_delete->next;

    list->memory_usage -= sizeof(Record) + strlen(to_delete->record.metadata) + 1;
    free(to_delete->record.metadata);
    free(to_delete);

    pthread_mutex_unlock(&list->lock);
    log_memory_usage(list);
    return 0;
}

int update_record(RecordList *list, int key, double new_value, const char *new_metadata) {
    if (pthread_mutex_trylock(&list->lock) != 0) return -1;

    Node *current = list->head;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Record not found
    }

    free(current->record.metadata);
    current->record.value = new_value;

    size_t metadata_size = strlen(new_metadata) + 1;
    list->memory_usage -= strlen(current->record.metadata) + 1;
    current->record.metadata = strdup(new_metadata);
    list->memory_usage += metadata_size;

    pthread_mutex_unlock(&list->lock);
    log_memory_usage(list);
    return 0;
}

void refresh_records_from_api(RecordList *list) {
    if (pthread_mutex_trylock(&list->lock) != 0) return;

    // Simulate API call and response handling
    json_error_t error;
    json_t *root = json_loads("[{\"key\":1,\"value\":10.5,\"metadata\":\"data from api\"}]", 0, &error);

    if (!root) {
        fprintf(stderr, "Error loading JSON: %s\n", error.text);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    size_t index;
    json_t *value;

    json_array_foreach(root, index, value) {
        int key = json_integer_value(json_object_get(value, "key"));
        double val = json_real_value(json_object_get(value, "value"));
        const char *metadata = json_string_value(json_object_get(value, "metadata"));

        delete_record(list, key);
        add_record(list, key, val, metadata);
    }

    json_decref(root);
    pthread_mutex_unlock(&list->lock);
}

void log_memory_usage(const RecordList *list) {
    printf("Current memory usage: %zu bytes\n", list->memory_usage);
}

int main() {
    RecordList *record_list = create_record_list();

    add_record(record_list, 1, 10.5, "Initial metadata");
    update_record(record_list, 1, 15.0, "Updated metadata");

    refresh_records_from_api(record_list);

    destroy_record_list(record_list);
    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex` for thread-safe operations.
- **Memory Management**: Manages memory usage and limits with checks.
- **Serialization**: Utilizes Jansson library for JSON serialization/deserialization.
- **Error Handling**: Includes basic error handling for mutex locks and API calls.
- **Logging**: Logs memory usage after each operation.']

