void retry_operation(void (*operation)(int**, size_t*), int max_retries, const char* description) {
    int attempts = 0;
    while (attempts < max_retries) {
        if (operation(NULL, NULL) == 0) {
            printf("Operation '%s' succeeded on attempt %d\n", description, attempts + 1);
            return;
        } else {
            printf("Operation '%s' failed on attempt %d, retrying...\n", description, attempts + 1);
            attempts++;
        }
    }
    fprintf(stderr, "Operation '%s' failed after %d attempts.\n", description, max_retries);
}

int compare_records(const void *a, const void *b) {
    record *recordA = (record *)a;
    record *recordB = (record *)b;

    return (recordA->key - recordB->key);
}

void verify_integrity(record *records, size_t records_count, long *offsets_array) {
    for (size_t i = 0; i < records_count; ++i) {
        if (!records[i].offset_ptr || (records[i].offset_ptr >= offsets_array && 
           records[i].offset_ptr < offsets_array + records_count)) {
            printf("Record %zu is valid.\n", i);
        } else {
            fprintf(stderr, "Record %zu has a dangling pointer!\n", i);
        }
    }

    for (size_t i = 1; i < records_count; ++i) {
        if (records[i-1].key > records[i].key) {
            fprintf(stderr, "Records are not sorted correctly at index %zu.\n", i);
        }
    }
}

record* initialize_records(int **keys_array, size_t keys_count, int max_retries) {
    // Allocate memory for the offsets array
    long *offsets_array = (long *)malloc(keys_count * sizeof(long));
    if (!offsets_array) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return NULL;
    }

    // Initialize all offset pointers to null
    memset(offsets_array, 0, keys_count * sizeof(long));

    // Allocate memory for the records array
    record *records = (record *)malloc(keys_count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(offsets_array);
        return NULL;
    }

    retry_operation(fetch_data, max_retries, "Data fetch operation");

    // Assign keys and offsets in records
    for (size_t i = 0; i < keys_count; ++i) {
        records[i].key = (*keys_array)[i];
        records[i].offset_ptr = &offsets_array[i]; // Safely point to the corresponding offset
    }

    // Sort records by key values
    qsort(records, keys_count, sizeof(record), compare_records);

    // Verify the integrity of the sorted records
    verify_integrity(records, keys_count, offsets_array);

    return records;
}

void cleanup_resources(record *records, size_t records_count, long *offsets_array) {
    free(offsets_array);
    free(records);
}
