#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define ARRAY_SIZE 1000
#define CACHE_SIZE 100

typedef struct {
    int value;
    time_t timestamp;
    unsigned char status_flag;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    time_t *timestamps;
    unsigned char *status_flags;
    pthread_mutex_t lock;
    FILE *log_file;
} DataStore;

typedef struct {
    Record *cache;
    size_t index_map[CACHE_SIZE];
    size_t used_entries;
    pthread_rwlock_t cache_lock;
} Cache;

void log_operation(DataStore *ds, const char *operation) {
    if (ds->log_file) {
        pthread_mutex_lock(&ds->lock);
        fprintf(ds->log_file, "%s\n", operation);
        fflush(ds->log_file);
        pthread_mutex_unlock(&ds->lock);
    }
}

int init_random_seed() {
    unsigned int seed;
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp) {
        fread(&seed, sizeof(seed), 1, fp);
        fclose(fp);
    } else {
        time_t t = time(NULL);
        srand((unsigned int)t ^ getpid());
        seed = rand();
    }
    return seed;
}

Cache* init_cache() {
    Cache *cache = malloc(sizeof(Cache));
    cache->cache = malloc(sizeof(Record) * CACHE_SIZE);
    memset(cache->index_map, -1, sizeof(size_t) * CACHE_SIZE);
    cache->used_entries = 0;
    pthread_rwlock_init(&cache->cache_lock, NULL);
    return cache;
}

DataStore* create_data_store(const char *log_filename) {
    DataStore *ds = malloc(sizeof(DataStore));

    ds->offsets = malloc(sizeof(long) * ARRAY_SIZE);
    ds->keys = malloc(sizeof(int) * ARRAY_SIZE);
    ds->records = malloc(sizeof(Record) * ARRAY_SIZE);
    ds->timestamps = malloc(sizeof(time_t) * ARRAY_SIZE);
    ds->status_flags = malloc(sizeof(unsigned char) * ARRAY_SIZE);

    pthread_mutex_init(&ds->lock, NULL);

    ds->log_file = fopen(log_filename, "a");
    if (!ds->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    srand(init_random_seed());

    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        ds->offsets[i] = rand() % 100000;
        ds->keys[i] = rand() % 10000;
        ds->records[i].value = rand() % 100;
        ds->records[i].timestamp = time(NULL);
        ds->records[i].status_flag = rand() % 2;
        ds->timestamps[i] = time(NULL);
        ds->status_flags[i] = rand() % 2;

        char log_msg[256];
        snprintf(log_msg, sizeof(log_msg), "Initialized record %zu", i);
        log_operation(ds, log_msg);
    }

    ds->cache = init_cache();

    return ds;
}

void free_data_store(DataStore *ds) {
    if (ds) {
        pthread_mutex_lock(&ds->lock);

        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds->timestamps);
        free(ds->status_flags);

        fclose(ds->log_file);
        log_operation(ds, "Closed log file and freed data arrays");

        pthread_mutex_unlock(&ds->lock);

        free_cache(ds->cache);
    }
}

void free_cache(Cache *cache) {
    if (cache) {
        pthread_rwlock_destroy(&cache->cache_lock);
        free(cache->cache);
        free(cache);
    }
}

Record* cache_lookup(Cache *cache, int key) {
    Record *record = NULL;
    pthread_rwlock_rdlock(&cache->cache_lock);

    for (size_t i = 0; i < CACHE_SIZE && cache->used_entries > 0; ++i) {
        if (cache->index_map[i] == key) {
            record = &cache->cache[i];
            break;
        }
    }

    pthread_rwlock_unlock(&cache->cache_lock);
    return record;
}

void cache_update(Cache *cache, int key, Record new_record) {
    size_t index_to_replace = -1;
    pthread_rwlock_wrlock(&cache->cache_lock);

    for (size_t i = 0; i < CACHE_SIZE && cache->used_entries > 0; ++i) {
        if (cache->index_map[i] == key) {
            cache->cache[i] = new_record;
            index_to_replace = -1;
            break;
        } else if (index_to_replace == -1 && cache->index_map[i] == -1) {
            index_to_replace = i;
        }
    }

    if (index_to_replace != -1) {
        cache->cache[index_to_replace] = new_record;
        cache->index_map[index_to_replace] = key;
    }

    pthread_rwlock_unlock(&cache->cache_lock);
}

int main() {
    DataStore *ds = create_data_store("operations.log");

    // Example usage
    Record *cached_rec = cache_lookup(ds->cache, ds->keys[0]);
    if (cached_rec) {
        printf("Cache hit: %d\n", cached_rec->value);
    } else {
        printf("Cache miss\n");
        Record new_record = { .value = 42, .timestamp = time(NULL), .status_flag = 1 };
        cache_update(ds->cache, ds->keys[0], new_record);
    }

    free_data_store(ds);

    return 0;
}
