#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <math.h>
#include <string.h>

#define MAX_MEMORY 1024 * 1024 // Example memory limit (1 MB)
#define LOG_FILE "memory_log.txt"

typedef struct {
    int x;
    int y;
    float z;
} Point;

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    double* floats;
    Point* points;
    size_t count;
} DataStructures;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_allocated_memory = 0;

void log_memory_operation(const char *operation, const void *ptr, size_t size) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "[%ld] %s: %p (%zu bytes)\n", now, operation, ptr, size);
        fclose(log_file);
    }
}

void* allocate_memory(size_t *allocated_size, const char *operation, size_t requested_size) {
    void *ptr = malloc(requested_size);
    if (ptr != NULL && pthread_mutex_lock(&lock) == 0) {
        if ((total_allocated_memory + requested_size) <= MAX_MEMORY) {
            total_allocated_memory += requested_size;
            log_memory_operation(operation, ptr, requested_size);
            *allocated_size = requested_size;
            pthread_mutex_unlock(&lock);
            return ptr;
        } else {
            free(ptr);
            pthread_mutex_unlock(&lock);
        }
    }
    return NULL;
}

void deallocate_memory(void *ptr, size_t allocated_size) {
    if (pthread_mutex_lock(&lock) == 0) {
        total_allocated_memory -= allocated_size;
        log_memory_operation("FREE", ptr, allocated_size);
        free(ptr);
        pthread_mutex_unlock(&lock);
    }
}

double generate_normal_distribution(double mean, double stddev) {
    static int hasSpare = 0;
    static double spare;

    if (hasSpare) {
        hasSpare = 0;
        return mean + spare * stddev;
    }

    double u1, u2, w, mult;

    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);

        w = pow(-2.0 * log(u1), 0.5);
        mult = w * u2;

        spare = mult;
        hasSpare = 1;

    } while (w * w >= 1.0);

    return mean + stddev * mult;
}

void initialize_data_structures(DataStructures *ds, size_t count) {
    ds->count = count;

    size_t offset_size = count * sizeof(long);
    if ((ds->offsets = allocate_memory(NULL, "ALLOC", offset_size)) == NULL) return;

    size_t key_size = count * sizeof(int);
    if ((ds->keys = allocate_memory(NULL, "ALLOC", key_size)) == NULL) {
        deallocate_memory(ds->offsets, offset_size);
        return;
    }

    size_t record_size = count * sizeof(record);
    if ((ds->records = allocate_memory(NULL, "ALLOC", record_size)) == NULL) {
        deallocate_memory(ds->keys, key_size);
        deallocate_memory(ds->offsets, offset_size);
        return;
    }

    size_t float_size = count * sizeof(double);
    if ((ds->floats = allocate_memory(NULL, "ALLOC", float_size)) == NULL) {
        deallocate_memory(ds->records, record_size);
        deallocate_memory(ds->keys, key_size);
        deallocate_memory(ds->offsets, offset_size);
        return;
    }

    size_t point_size = count * sizeof(Point);
    if ((ds->points = allocate_memory(NULL, "ALLOC", point_size)) == NULL) {
        deallocate_memory(ds->floats, float_size);
        deallocate_memory(ds->records, record_size);
        deallocate_memory(ds->keys, key_size);
        deallocate_memory(ds->offsets, offset_size);
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        ds->points[i].x = (int)generate_normal_distribution(0.0, 1.0);
        ds->points[i].y = (int)generate_normal_distribution(0.0, 1.0);
        ds->points[i].z = (float)generate_normal_distribution(0.0, 1.0);

        // Initializing other structures as needed
    }
}

void free_data_structures(DataStructures *ds) {
    if (ds->offsets != NULL) deallocate_memory(ds->offsets, ds->count * sizeof(long));
    if (ds->keys != NULL) deallocate_memory(ds->keys, ds->count * sizeof(int));
    if (ds->records != NULL) deallocate_memory(ds->records, ds->count * sizeof(record));
    if (ds->floats != NULL) deallocate_memory(ds->floats, ds->count * sizeof(double));
    if (ds->points != NULL) deallocate_memory(ds->points, ds->count * sizeof(Point));
}

int main() {
    DataStructures ds;
    size_t count = 1000; // Example count
    initialize_data_structures(&ds, count);

    // Use the data structures...

    free_data_structures(&ds);

    return 0;
}
