#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define HASH_TABLE_SIZE 1024
#define NOT_FOUND -1

typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    pthread_mutex_t lock[HASH_TABLE_SIZE];
} HashTable;

HashTable* create_table() {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(HASH_TABLE_SIZE, sizeof(Record *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        pthread_mutex_init(&table->lock[i], NULL);
    }

    return table;
}

void free_table(HashTable *table) {
    if (!table) return;

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Record *current = table->buckets[i];
        while (current) {
            Record *temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(table->buckets);

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        pthread_mutex_destroy(&table->lock[i]);
    }

    free(table);
}

unsigned int hash(int key) {
    return key % HASH_TABLE_SIZE;
}

int add_record(HashTable *table, int key, long offset) {
    if (!table) return -1;

    unsigned int index = hash(key);

    pthread_mutex_lock(&table->lock[index]);

    Record *current = table->buckets[index];
    while (current) {
        if (current->key == key) {
            current->offset = offset;
            pthread_mutex_unlock(&table->lock[index]);
            return 0; // Key already exists, updated the value
        }
        current = current->next;
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&table->lock[index]);
        return -1;
    }

    new_record->key = key;
    new_record->offset = offset;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;

    pthread_mutex_unlock(&table->lock[index]);
    return 0; // Successfully added
}

long search_key(HashTable *table, int key) {
    if (!table) return NOT_FOUND;

    unsigned int index = hash(key);

    pthread_mutex_lock(&table->lock[index]);

    Record *current = table->buckets[index];
    while (current) {
        if (current->key == key) {
            long offset = current->offset;
            pthread_mutex_unlock(&table->lock[index]);
            return offset; // Key found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock[index]);
    return NOT_FOUND; // Key not found
}
```

This code provides a concurrent hash table implementation for managing records with unique integer keys and long integer offsets. It uses mutex locks to ensure thread-safe operations on the hash table.']

['```java
import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.logging.*;

public class ConfigManager {

    private static final String CONFIG_FILE_PATH = "config.cfg";
    private static final String METADATA_FILE_PATH = "metadata.meta";
    private static final String TEMP_DIR = System.getProperty("java.io.tmpdir");
    private static final Logger logger = Logger.getLogger(ConfigManager.class.getName());
    private static final String SERVER_URL = "https://example.com/config.cfg";

    public static void main(String[] args) {
        setupLogger();
        try {
            while (true) {
                checkAndUpdateConfigFile();
                Thread.sleep(60000); // Check every minute
            }
        } catch (InterruptedException e) {
            logger.log(Level.INFO, "Application interrupted");
        }
    }

    private static void setupLogger() throws IOException {
        FileHandler fileHandler = new FileHandler("config_manager.log", true);
        fileHandler.setFormatter(new SimpleFormatter());
        logger.addHandler(fileHandler);
        logger.setLevel(Level.ALL);
    }

    private static void checkAndUpdateConfigFile() {
        try {
            Path configPath = Paths.get(CONFIG_FILE_PATH);
            if (!Files.exists(configPath)) {
                fetchNewConfig();
            } else {
                String expectedChecksum = readMetadata();
                String actualChecksum = calculateChecksum(configPath);

                if (expectedChecksum == null || !expectedChecksum.equals(actualChecksum)) {
                    logger.log(Level.INFO, "Configuration file is corrupted or outdated. Fetching new version...");
                    fetchNewConfig();
                }
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error checking configuration file", e);
        }
    }

    private static String readMetadata() throws IOException {
        Path metaPath = Paths.get(METADATA_FILE_PATH);
        if (!Files.exists(metaPath)) return null;

        try (BufferedReader reader = Files.newBufferedReader(metaPath)) {
            return reader.readLine();
        }
    }

    private static String calculateChecksum(Path path) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new FileInputStream(path.toFile())) {
            byte[] buffer = new byte[8192];
            int read;
            while ((read = is.read(buffer)) != -1) {
                digest.update(buffer, 0, read);
            }
        }
        byte[] hashBytes = digest.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void fetchNewConfig() {
        try {
            HttpURLConnection connection = (HttpURLConnection) new URL(SERVER_URL).openConnection();
            int responseCode = connection.getResponseCode();

            if (responseCode == 200) {
                Path tempPath = Files.createTempFile(TEMP_DIR, "config", ".tmp");
                Files.copy(connection.getInputStream(), tempPath);

                String checksum = calculateChecksum(tempPath);
                writeMetadata(checksum);

                Files.move(tempPath, Paths.get(CONFIG_FILE_PATH), StandardCopyOption.REPLACE_EXISTING);
                logger.log(Level.INFO, "Configuration file updated successfully.");
            } else {
                logger.log(Level.WARNING, "Failed to fetch configuration file. Server response: " + responseCode);
            }
        } catch (IOException | NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "Error fetching new configuration", e);
        }
    }

    private static void writeMetadata(String checksum) throws IOException {
        Path metaPath = Paths.get(METADATA_FILE_PATH);
        try (BufferedWriter writer = Files.newBufferedWriter(metaPath)) {
            writer.write(checksum);
        }
    }
}
```

This Java application periodically checks the integrity of a configuration file by comparing its checksum with metadata. If the file is missing, corrupted, or outdated, it fetches a new version from a remote server. The program handles network issues and logs detailed information about the update process. It uses temporary files efficiently and resumes operations after interruptions.']

