            {
                _logger.LogError("Invalid document format.");
                return;
            }

            var cacheKey = GetCacheKey(inputFilePath);
            if (_cache.TryGetValue(cacheKey, out var cachedData))
            {
                GenerateReport(cachedData, outputHtmlPath);
                return;
            }

            var extractedInfo = ExtractInformationFromDocument(documentBytes);
            var processedData = await ProcessWithWebServiceAsync(extractedInfo);

            _cache.TryAdd(cacheKey, processedData);
            GenerateReport(processedData, outputHtmlPath);
        }
        catch (Exception ex)
