        self._registry_lock = threading.Lock()
        self._factory_registry: Dict[str, Callable[..., Any]] = {}
        self.logger_enabled = True

    def log(self, message: str) -> None:
        if self.logger_enabled:
            print(f"[LOG] {message}")

    def add_factory_function(self, id_: str, factory_func: Callable[..., Any]) -> None:
        with self._registry_lock:
            self._factory_registry[id_] = factory_func
        self.log(f"Factory function added for ID: {id_}")

    def create_instance(self, id_: str, *args, **kwargs) -> Any:
        with self._registry_lock:
            if id_ not in self._factory_registry:
                raise ValueError(f"No factory registered under ID: {id_}")
            factory_func = self._factory_registry[id_]

        instance = factory_func(*args, **kwargs)
        self.log(f"Instance created for ID: {id_} with args {args}, kwargs {kwargs}")
        return instance

    def parse_json(self, json_str: str) -> Any:
        try:
            data = json.loads(json_str)
            self.log("JSON parsed successfully")
            return self._deserialize(data)
        except (json.JSONDecodeError, TypeError) as e:
            self.log(f"Failed to parse JSON: {str(e)}")
            raise

    def _deserialize(self, obj: Any) -> Any:
        if isinstance(obj, dict):
            id_ = obj.get("type_id")
            if id_ and id_ in self._factory_registry:
                return self.create_instance(id_, **obj)
            else:
                return {k: self._deserialize(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [self._deserialize(item) for item in obj]
        else:
            return obj

    def update_configuration(self, new_config: Dict[str, Any]) -> None:
        with self._registry_lock:
            # Simulate dynamic updates to the registry
            self.log("Updating configuration dynamically")
            # Update logic can be implemented here based on `new_config`

# Example subclass and factory function
class CustomData:
