['Below is a possible implementation of your requirements using C. This code demonstrates dynamic management of records with a custom allocator, logging, and hash table integration.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MEMORY_BUDGET 1024 * 1024 // 1MB for example
#define LOG_FILE "memory_log.txt"
#define HASH_TABLE_SIZE 101

typedef struct {
    int value;
    long offset;
    int key;
} record;

typedef struct {
    void* start;
    size_t size;
} memory_block;

static pthread_mutex_t allocator_lock = PTHREAD_MUTEX_INITIALIZER;
static FILE* log_file;
static size_t total_memory_used = 0;
static record* records = NULL;
static int keys_count = 0;
static long* offsets = NULL;
static int hash_table[HASH_TABLE_SIZE];
static int max_records = 1000; // Example maximum

// Custom memory allocator functions
void custom_allocator_init(size_t block_size) {
    pthread_mutex_lock(&allocator_lock);
    total_memory_used = 0;
    pthread_mutex_unlock(&allocator_lock);
}

void* custom_alloc(size_t size) {
    pthread_mutex_lock(&allocator_lock);

    if (total_memory_used + size > MEMORY_BUDGET) {
        log_memory_status("Allocation failed: Memory budget exceeded");
        pthread_mutex_unlock(&allocator_lock);
        return NULL;
    }

    void* ptr = malloc(size);
    if (!ptr) {
        log_memory_status("Allocation failed: malloc returned NULL");
    } else {
        total_memory_used += size;
        log_memory_status("Memory allocated");
    }

    pthread_mutex_unlock(&allocator_lock);
    return ptr;
}

void custom_free(void* ptr, size_t size) {
    pthread_mutex_lock(&allocator_lock);

    if (ptr) {
        free(ptr);
        total_memory_used -= size;
        log_memory_status("Memory freed");
    }

    pthread_mutex_unlock(&allocator_lock);
}

// Logging functions
void log_init(const char* filename, int verbosity) {
    log_file = fopen(filename, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
}

void log_memory_status(const char* message) {
    pthread_mutex_lock(&allocator_lock);

    fprintf(log_file, "%s - Total Memory Used: %zu bytes\n", message, total_memory_used);
    fflush(log_file);

    pthread_mutex_unlock(&allocator_lock);
}

// Hash table functions
unsigned int hash_function(int key) {
    return key % HASH_TABLE_SIZE;
}

int find_free_slot() {
    for (int i = 0; i < keys_count; ++i) {
        if (hash_table[i] == -1)
            return i;
    }
    return -1;
}

void insert_into_hash_table(int key, int index) {
    unsigned int hash_index = hash_function(key);
    while (hash_table[hash_index] != -1 && hash_table[hash_index] != key) {
        hash_index = (hash_index + 1) % HASH_TABLE_SIZE;
    }
    hash_table[hash_index] = index;
}

int hash_lookup(int key) {
    unsigned int hash_index = hash_function(key);
    while (hash_table[hash_index] != -1) {
        if (hash_table[hash_index] == key)
            return hash_index;
        hash_index = (hash_index + 1) % HASH_TABLE_SIZE;
    }
    return -1;
}

// Main function to manage records
int manage_records(int keys[], size_t num_keys, int min_value, int max_value) {
    custom_allocator_init(sizeof(record));
    log_init(LOG_FILE, 1);

    offsets = (long*)custom_alloc(num_keys * sizeof(long));
    if (!offsets) return -1;

    records = (record*)custom_alloc(max_records * sizeof(record));
    if (!records) {
        custom_free(offsets, num_keys * sizeof(long));
        return -1;
    }

    memset(hash_table, -1, HASH_TABLE_SIZE * sizeof(int));

    for (size_t i = 0; i < num_keys; ++i) {
        int key = keys[i];
        long offset = (long)(rand() % max_records);
        offsets[i] = offset;

        int free_slot_index = find_free_slot();
        if (free_slot_index == -1 || records_count >= max_records) break;

        records[free_slot_index].value = rand() % (max_value - min_value + 1) + min_value;
        records[free_slot_index].offset = offset;
        records[free_slot_index].key = key;

        insert_into_hash_table(key, free_slot_index);
    }

    return 0; // Success
}

int main() {
    srand(time(NULL));

    int keys[] = {1, 2, 3, 4, 5};
    size_t num_keys = sizeof(keys) / sizeof(keys[0]);

    if (manage_records(keys, num_keys, 10, 100) != 0) {
        fprintf(stderr, "Failed to manage records\n");
    }

    return 0;
}
```

### Explanation
- **Custom Allocator**: Implements a simple memory management system with logging.
- **Logging**: Logs allocation and deallocation events to a file.
- **Hash Table**: Uses open addressing with linear probing for efficient key-to-record mapping.
- **Concurrency**: Utilizes mutexes for thread-safe operations.
- **Memory Management**: Ensures operations are within a defined memory budget.

This code provides a robust starting point, balancing usability, maintainability, and scalability. Adjust parameters like `MEMORY_BUDGET` and `HASH_TABLE_SIZE` as needed for your specific application.']

