#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <arpa/inet.h> // For htonl/ntohl
#include <unistd.h>
#include <errno.h>

#define MAX_ARRAY_SIZE 1024
#define RECORD_COUNT 100
#define RANDOM_STRING_LENGTH 16
#define HASH_ITERATIONS 1

typedef struct {
    int value;
    long offset;
} record_t;

// Function Prototypes
record_t* create_records(int min_val, int max_val);
void free_records(record_t *records, size_t count);
int serialize_records(const record_t *records, size_t count, uint8_t **byte_array, size_t *size);
int deserialize_records(const uint8_t *byte_array, size_t size, record_t **records, size_t *count);
void log_performance_metrics(size_t memory_usage, double processing_time, int throughput);
char* generate_random_string(size_t length, const char *charset);
unsigned long hash_string(const char *str);

// Global variables for logging
pthread_mutex_t log_mutex;

// Function to create and initialize records
record_t* create_records(int min_val, int max_val) {
    pthread_mutex_lock(&log_mutex);

    record_t *records = NULL;
    size_t count = RECORD_COUNT;
    srand(time(NULL));

    if (count > MAX_ARRAY_SIZE / sizeof(record_t)) {
        fprintf(stderr, "Error: Exceeding maximum array size limit.\n");
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }

    records = malloc(sizeof(record_t) * count);
    if (!records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
        records[i].offset = (long)rand();
    }

    pthread_mutex_unlock(&log_mutex);
    return records;
}

// Function to free allocated memory for records
void free_records(record_t *records, size_t count) {
    if (records) {
        free(records);
    }
}

// Function to serialize records into a byte array
int serialize_records(const record_t *records, size_t count, uint8_t **byte_array, size_t *size) {
    pthread_mutex_lock(&log_mutex);

    size_t total_size = count * sizeof(record_t);
    if (!byte_array || !size) {
        fprintf(stderr, "Invalid arguments for serialization.\n");
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    *byte_array = malloc(total_size);
    if (!*byte_array) {
        perror("Failed to allocate memory for serialized data");
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    memcpy(*byte_array, records, total_size);

    // Ensure endianness consistency
    for (size_t i = 0; i < count; ++i) {
        ((int*)*byte_array)[2 * i] = htonl(records[i].value);
        ((long*)*byte_array)[2 * i + 1] = htonll(records[i].offset); // Assuming htonll exists
    }

    *size = total_size;
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

// Function to deserialize byte array back into records
int deserialize_records(const uint8_t *byte_array, size_t size, record_t **records, size_t *count) {
    pthread_mutex_lock(&log_mutex);

    if (!byte_array || !records || !count) {
        fprintf(stderr, "Invalid arguments for deserialization.\n");
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    size_t rec_count = size / sizeof(record_t);
    *records = malloc(sizeof(record_t) * rec_count);
    if (!*records) {
        perror("Failed to allocate memory for deserialized records");
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    memcpy(*records, byte_array, size);

    // Restore endianness
    for (size_t i = 0; i < rec_count; ++i) {
        (*records)[i].value = ntohl(((int*)byte_array)[2 * i]);
        (*records)[i].offset = htonll(((long*)byte_array)[2 * i + 1]); // Assuming htonll exists
    }

    *count = rec_count;
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

// Function to log performance metrics
void log_performance_metrics(size_t memory_usage, double processing_time, int throughput) {
    printf("Memory Usage: %zu bytes\n", memory_usage);
    printf("Processing Time: %.2f seconds\n", processing_time);
    printf("Throughput: %d records/second\n", throughput);
}

// Function to generate a random string
char* generate_random_string(size_t length, const char *charset) {
    size_t charset_size = strlen(charset);
    char *random_str = malloc(length + 1);

    if (!random_str) {
        perror("Failed to allocate memory for random string");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < length; ++i) {
        random_str[i] = charset[rand() % charset_size];
    }
    random_str[length] = '\0';

    return random_str;
}

// Function to hash a string using a secure algorithm
unsigned long hash_string(const char *str) {
    // Simple example using FNV-1a hashing for demonstration purposes
    unsigned long hash = 14695981039346656037UL; 
    const unsigned char *p = (const unsigned char*) str;

    while (*p) {
        hash ^= (unsigned long)*p++;
        hash *= 1099511628211UL;
    }

    return hash;
}

// Helper function for htonll
static inline uint64_t htonll(uint64_t x) {
    static const int num = 42;
    if (*(const char *)&num == 42)
        return (uint64_t)(htonl((x << 32) >> 32)) << 32 | htonl(x >> 32);
    else
        return (uint64_t)(htons((x << 48) >> 48)) << 16 |
               (uint64_t)(htons((x << 32) >> 48)) << 32 |
               (uint64_t)(htons((x << 16) >> 48)) << 48 | htons(x >> 32);
}

// Main function
int main() {
    pthread_mutex_init(&log_mutex, NULL);

    record_t *records = create_records(1, 100);
    if (!records) return EXIT_FAILURE;

    size_t serialized_size;
    uint8_t *serialized_data;
    serialize_records(records, RECORD_COUNT, &serialized_data, &serialized_size);

    record_t *deserialized_records = NULL;
    size_t deserialized_count = 0;
    deserialize_records(serialized_data, serialized_size, &deserialized_records, &deserialized_count);

    char *random_string = generate_random_string(RANDOM_STRING_LENGTH, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");
    printf("Random String: %s\n", random_string);

    const char *test_str = "TestString";
    unsigned long hash_value = hash_string(test_str);
    printf("Hash of '%s': %lu\n", test_str, hash_value);

    free_records(records, RECORD_COUNT);
    free(serialized_data);
    free(deserialized_records);
    free(random_string);

    pthread_mutex_destroy(&log_mutex);
    return EXIT_SUCCESS;
}
