record* get_record_by_reverse_key(const record *records, size_t count) {
    record *sorted_records = malloc(count * sizeof(record));
    if (!sorted_records) return NULL;

    for (size_t i = 0; i < count; ++i) {
        sorted_records[i] = records[i];
    }

    // Simple bubble sort to reverse by key
    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = 0; j < count - i - 1; ++j) {
            if (sorted_records[j].key < sorted_records[j + 1].key) {
                record temp = sorted_records[j];
                sorted_records[j] = sorted_records[j + 1];
                sorted_records[j + 1] = temp;
            }
        }
    }

    return sorted_records;
}

int main() {
    size_t initial_capacity = 10; 
    size_t max_memory_usage = 1024 * 1024; // 1 MB limit for example

    record *records = manage_records(initial_capacity, max_memory_usage, generate_random_values);

    if (!records) {
        fprintf(stderr, "Memory allocation failed or memory usage exceeded.\n");
        return EXIT_FAILURE;
    }

    size_t current_count = initial_capacity;

    // Example usage: retrieve records in reverse key order
    record *reversed_records = get_record_by_reverse_key(records, current_count);
    if (!reversed_records) {
        fprintf(stderr, "Failed to sort records by key.\n");
    } else {
        for (size_t i = 0; i < current_count; ++i) {
            printf("Offset: %ld, Key: %d\n", reversed_records[i].offset, reversed_records[i].key);
        }
    }

    free(reversed_records);
    free_records(records);

    return EXIT_SUCCESS;
}
