```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <unistd.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit in bytes
#define RECORD_SIZE sizeof(record)
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    int value;
    long offset;
} record;

// Logging function
void log_message(int level, const char *message) {
    if (level >= LOG_LEVEL_INFO) { // Customize based on desired verbosity
        printf("[LOG %d] %s\n", level, message);
    }
}

// Random number generation within a range
int generate_random_int(int min, int max, unsigned int seed) {
    srand(seed);
    return rand() % (max - min + 1) + min;
}

// Memory allocation with retry mechanism
void *safe_malloc(size_t size, int retries) {
    void *ptr = NULL;
    while (retries-- > 0 && (ptr = malloc(size)) == NULL) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed. Retrying...");
        usleep(100000); // Retry after a delay
    }
    if (!ptr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Serialize record into byte array considering endianness
size_t serialize_record(record *rec, uint8_t **buffer, size_t buffer_size) {
    size_t required_size = 4 + 8; // int (4 bytes) + long (8 bytes)
    if (*buffer == NULL || buffer_size < required_size) {
        log_message(LOG_LEVEL_ERROR, "Buffer too small for serialization");
        return 0;
    }

    uint32_t value_network_order = htonl(rec->value);
    memcpy(*buffer, &value_network_order, sizeof(value_network_order));
    *buffer += sizeof(value_network_order);

    uint64_t offset_network_order = htonll(rec->offset);
    memcpy(*buffer, &offset_network_order, sizeof(offset_network_order));

    return required_size;
}

// Deserialize byte array back to record
void deserialize_record(uint8_t *buffer, record *rec) {
    rec->value = ntohl(*(uint32_t *)buffer);
    buffer += sizeof(rec->value);

    rec->offset = ntohll(*(uint64_t *)buffer);
}

// Convert uint64_t for network order (for endianness)
uint64_t htonll(uint64_t value) {
    if (__BYTE_ORDER == __BIG_ENDIAN)
        return value;
    const uint32_t high_part = htonl((uint32_t)(value >> 32));
    const uint32_t low_part = htonl((uint32_t)value);
    return (((uint64_t)low_part << 32) | (uint64_t)high_part);
}

// Convert uint64_t from network order
uint64_t ntohll(uint64_t value) {
    if (__BYTE_ORDER == __BIG_ENDIAN)
        return value;
    const uint32_t high_part = ntohl((uint32_t)(value >> 32));
    const uint32_t low_part = ntohl((uint32_t)value);
    return (((uint64_t)low_part << 32) | (uint64_t)high_part);
}

// Main function to create records
record *create_records(int num_records, int min_val, int max_val, long max_offset) {
    size_t record_memory = num_records * RECORD_SIZE;
    if (record_memory > MAX_MEMORY_LIMIT) {
        log_message(LOG_LEVEL_ERROR, "Requested memory exceeds limit");
        return NULL;
    }

    unsigned int seed = time(NULL);
    record *records = safe_malloc(record_memory, 3);

    for (int i = 0; i < num_records; ++i) {
        records[i].value = generate_random_int(min_val, max_val, seed + i);
        records[i].offset = rand() % (max_offset + 1); // Random long offset
    }

    log_message(LOG_LEVEL_INFO, "Records successfully created");
    return records;
}

// Cleanup function to delete allocated memory
void cleanup_records(record *records) {
    if (records != NULL) {
        free(records);
        log_message(LOG_LEVEL_INFO, "Memory freed for records");
    }
}

int main() {
    int num_records = 10; // Example number of records
    record *records = create_records(num_records, 0, 100, 9999L);

    if (records) {
        uint8_t *buffer = NULL;
        size_t buffer_size = 1024; // Example buffer size for serialization

        for (int i = 0; i < num_records; ++i) {
            buffer = safe_malloc(buffer_size, 3);
            size_t serialized_size = serialize_record(&records[i], &buffer, buffer_size);

            if (serialized_size > 0) {
                log_message(LOG_LEVEL_DEBUG, "Record serialized successfully");

                // Deserialize for demonstration
                record new_rec;
                deserialize_record((uint8_t *)buffer, &new_rec);

                free(buffer); // Free serialized data buffer after use
            }
        }

        cleanup_records(records);
    }

    return 0;
}
```

