['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_MEMORY_SIZE 1024 * 1024 // Maximum memory size in bytes

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    int key;
    char* string_value;
    time_t timestamp;
    long offset;
    Record record;
    void* metadata_ptr; // Pointer to corresponding metadata
} DynamicRecord;

typedef struct {
    pthread_mutex_t lock;
    size_t allocated_size;
    DynamicRecord** records;
    char** metadata;
    int record_count;
    int max_records;
} RecordManager;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int safe_random_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

uint8_t serialize_record(const DynamicRecord* record, uint8_t* buffer, size_t buffer_size, size_t* offset) {
    if (*offset + sizeof(record->key) + sizeof(record->timestamp) + strlen(record->string_value) + 1 + 
        sizeof(record->record.value) + sizeof(record->record.offset) + sizeof(record->offset) > buffer_size)
        return 0;

    memcpy(buffer + *offset, &record->key, sizeof(record->key));
    *offset += sizeof(record->key);

    memcpy(buffer + *offset, &record->timestamp, sizeof(record->timestamp));
    *offset += sizeof(record->timestamp);

    size_t str_len = strlen(record->string_value) + 1;
    memcpy(buffer + *offset, &str_len, sizeof(str_len));
    *offset += sizeof(str_len);

    memcpy(buffer + *offset, record->string_value, str_len);
    *offset += str_len;

    memcpy(buffer + *offset, &record->record.value, sizeof(record->record.value));
    *offset += sizeof(record->record.value);

    memcpy(buffer + *offset, &record->record.offset, sizeof(record->record.offset));
    *offset += sizeof(record->record.offset);

    memcpy(buffer + *offset, &record->offset, sizeof(record->offset));
    *offset += sizeof(record->offset);

    return 1;
}

int deserialize_record(uint8_t* buffer, size_t buffer_size, size_t offset, DynamicRecord* record) {
    if (offset + sizeof(record->key) + sizeof(record->timestamp) > buffer_size)
        return 0;

    memcpy(&record->key, buffer + offset, sizeof(record->key));
    offset += sizeof(record->key);

    memcpy(&record->timestamp, buffer + offset, sizeof(record->timestamp));
    offset += sizeof(record->timestamp);

    size_t str_len;
    memcpy(&str_len, buffer + offset, sizeof(str_len));
    offset += sizeof(str_len);

    record->string_value = malloc(str_len);
    if (!record->string_value) {
        log_error("Failed to allocate memory for string value during deserialization");
        return 0;
    }

    memcpy(record->string_value, buffer + offset, str_len);
    offset += str_len;

    memcpy(&record->record.value, buffer + offset, sizeof(record->record.value));
    offset += sizeof(record->record.value);

    memcpy(&record->record.offset, buffer + offset, sizeof(record->record.offset));
    offset += sizeof(record->record.offset);

    memcpy(&record->offset, buffer + offset, sizeof(record->offset));
    offset += sizeof(record->offset);

    return 1;
}

RecordManager* create_record_manager(int max_records) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) {
        log_error("Failed to allocate memory for RecordManager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->allocated_size = 0;
    manager->records = (DynamicRecord**)calloc(max_records, sizeof(DynamicRecord*));
    if (!manager->records) {
        log_error("Failed to allocate memory for records array");
        free(manager);
        return NULL;
    }

    manager->metadata = (char**)malloc(max_records * sizeof(char*));
    if (!manager->metadata) {
        log_error("Failed to allocate memory for metadata array");
        free(manager->records);
        free(manager);
        return NULL;
    }

    memset(manager->metadata, 0, max_records * sizeof(char*));

    manager->record_count = 0;
    manager->max_records = max_records;

    return manager;
}

void add_record(RecordManager* manager, int key, const char* string_value, time_t timestamp) {
    pthread_mutex_lock(&manager->lock);

    if (manager->record_count >= manager->max_records) {
        log_error("Maximum number of records reached");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    DynamicRecord* record = (DynamicRecord*)malloc(sizeof(DynamicRecord));
    if (!record) {
        log_error("Failed to allocate memory for new record");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->allocated_size += sizeof(*record);

    record->key = key;
    record->string_value = strdup(string_value);
    record->timestamp = timestamp;
    record->offset = rand() % 1000; // Example offset
    record->record.value = safe_random_int(1, 100); // Random value in range [1, 100]
    record->record.offset = rand() % 1000; // Example offset for inner record

    size_t metadata_size = strlen(string_value) + 1;
    manager->metadata[key] = (char*)malloc(metadata_size);
    if (!manager->metadata[key]) {
        log_error("Failed to allocate memory for metadata");
        free(record->string_value);
        free(record);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    strncpy(manager->metadata[key], string_value, metadata_size);

    record->metadata_ptr = manager->metadata[key];
    manager->records[manager->record_count++] = record;

    pthread_mutex_unlock(&manager->lock);
}

void serialize_data(RecordManager* manager, uint8_t** buffer) {
    size_t total_size = manager->allocated_size + sizeof(size_t); // Include space for number of records
    *buffer = (uint8_t*)malloc(total_size);
    if (!*buffer) {
        log_error("Failed to allocate memory for serialization buffer");
        return;
    }

    size_t offset = 0;
    memcpy(*buffer, &manager->record_count, sizeof(manager->record_count));
    offset += sizeof(manager->record_count);

    for (int i = 0; i < manager->record_count; ++i) {
        if (!serialize_record(manager->records[i], *buffer, total_size, &offset)) {
            log_error("Serialization failed due to insufficient buffer size");
            free(*buffer);
            *buffer = NULL;
            return;
        }
    }
}

void deserialize_data(uint8_t* buffer, size_t buffer_size, RecordManager** manager_out) {
    if (buffer == NULL || buffer_size < sizeof(size_t)) {
        log_error("Invalid buffer or size for deserialization");
        return;
    }

    size_t record_count;
    memcpy(&record_count, buffer, sizeof(record_count));
    uint8_t* offset = buffer + sizeof(record_count);

    RecordManager* manager = create_record_manager((int)record_count);
    if (!manager) {
        log_error("Failed to create record manager during deserialization");
        return;
    }

    for (size_t i = 0; i < record_count && offset - buffer < buffer_size; ++i) {
        DynamicRecord* record = (DynamicRecord*)malloc(sizeof(DynamicRecord));
        if (!record || !deserialize_record(buffer, buffer_size, offset - buffer, record)) {
            log_error("Failed to deserialize record");
            free(manager);
            return;
        }

        manager->records[manager->record_count++] = record;
    }

    *manager_out = manager;
}

void free_records(RecordManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->record_count; ++i) {
        free(manager->records[i]->string_value);
        free((char*)manager->records[i]->metadata_ptr);
        free(manager->records[i]);
    }

    free(manager->records);
    for (int i = 0; i < manager->max_records; ++i) {
        if (manager->metadata[i]) {
            free(manager->metadata[i]);
        }
    }
    free(manager->metadata);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    srand(time(NULL));

    RecordManager* manager = create_record_manager(10);
    if (!manager) return 1;

    add_record(manager, 1, "Record One", time(NULL));
    add_record(manager, 2, "Record Two", time(NULL));

    uint8_t* serialized_data;
    serialize_data(manager, &serialized_data);

    RecordManager* deserialized_manager;
    deserialize_data(serialized_data, 0, &deserialized_manager); // Assuming buffer size is determined elsewhere

    free_records(manager);
    if (deserialized_manager) {
        free_records(deserialized_manager);
    }

    free(serialized_data);

    return 0;
}
