#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_MEMORY 1024 * 1024 // Example: 1MB limit for total allocation
#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int id;
    long offset;
    char buffer[BUFFER_SIZE];
} record_t;

typedef struct {
    record_t *records[MAX_RECORDS];
    size_t count;
    atomic_size_t memory_used;
    pthread_mutex_t lock;
} record_array_t;

static void log_message(const char *message) {
    printf("%s\n", message);
}

record_array_t* initialize_record_array() {
    record_array_t *arr = malloc(sizeof(record_array_t));
    if (!arr) return NULL;

    arr->count = 0;
    atomic_store(&arr->memory_used, 0);
    pthread_mutex_init(&arr->lock, NULL);

    log_message("Record array initialized.");
    return arr;
}

void free_record_array(record_array_t *arr) {
    if (arr) {
        for (size_t i = 0; i < arr->count; ++i) {
            free(arr->records[i]);
        }

        pthread_mutex_destroy(&arr->lock);
        log_message("Record array freed.");
        free(arr);
    }
}

void seed_random() {
    srand((unsigned int)time(NULL));
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record_t* create_record(long offset) {
    record_t *rec = malloc(sizeof(record_t));
    if (!rec) return NULL;

    rec->id = generate_random_int(0, INT_MAX);
    rec->offset = offset;
    snprintf(rec->buffer, BUFFER_SIZE, "RandomString%d", rand());

    size_t size = sizeof(*rec) + strlen(rec->buffer);
    return rec;
}

int add_record(record_array_t *arr, long offset) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count >= MAX_RECORDS || 
        atomic_load(&arr->memory_used) + sizeof(record_t *) > MAX_MEMORY) {

        log_message("Failed to add record: Exceeded limits.");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    record_t *new_rec = create_record(offset);
    if (!new_rec) {
        log_message("Memory allocation failed for new record.");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    size_t size = sizeof(*new_rec) + strlen(new_rec->buffer);
    atomic_fetch_add(&arr->memory_used, size);

    arr->records[arr->count++] = new_rec;

    log_message("Record added successfully.");
    pthread_mutex_unlock(&arr->lock);
    return 0;
}

size_t serialize_records(const record_array_t *arr, uint8_t **output) {
    pthread_mutex_lock((pthread_mutex_t*)&arr->lock);

    size_t total_size = arr->count * (sizeof(int) + sizeof(long) + BUFFER_SIZE);
    *output = malloc(total_size);

    if (!*output) {
        log_message("Serialization failed: Memory allocation error.");
        pthread_mutex_unlock((pthread_mutex_t*)&arr->lock);
        return 0;
    }

    uint8_t *ptr = *output;
    for (size_t i = 0; i < arr->count; ++i) {
        memcpy(ptr, &arr->records[i]->id, sizeof(int));
        ptr += sizeof(int);

        memcpy(ptr, &arr->records[i]->offset, sizeof(long));
        ptr += sizeof(long);

        memcpy(ptr, arr->records[i]->buffer, BUFFER_SIZE);
        ptr += BUFFER_SIZE;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&arr->lock);
    log_message("Records serialized successfully.");
    return total_size;
}

int deserialize_records(const uint8_t *input, size_t input_size, record_array_t *arr) {
    if (input_size % (sizeof(int) + sizeof(long) + BUFFER_SIZE)) {
        log_message("Deserialization failed: Invalid data size.");
        return -1;
    }

    pthread_mutex_lock(&arr->lock);
    arr->count = 0;

    const uint8_t *ptr = input;
    for (size_t i = 0; i < input_size / (sizeof(int) + sizeof(long) + BUFFER_SIZE); ++i) {
        if (add_record(arr, *(long*)ptr)) {
            log_message("Deserialization failed: Memory allocation error.");
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }

        ptr += sizeof(int);
        ptr += sizeof(long);
        ptr += BUFFER_SIZE;
    }

    pthread_mutex_unlock(&arr->lock);
    log_message("Records deserialized successfully.");
    return 0;
}

int find_largest_int(const int *array, size_t length) {
    if (!length) return -1;

    int largest = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
    return largest;
}

void read_integers() {
    int n, *arr;
    printf("Enter the number of integers:\n");
    scanf("%d", &n);

    arr = malloc(n * sizeof(int));
    if (!arr) {
        log_message("Memory allocation failed for integer array.");
        return;
    }

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &arr[i]);
    }

    find_largest_int(arr, n);
    free(arr);
}

int main() {
    seed_random();

    record_array_t *record_arr = initialize_record_array();
    if (!record_arr) return -1;

    for (long i = 0; i < MAX_RECORDS; ++i) {
        add_record(record_arr, i);
    }

    uint8_t *serialized_data;
    size_t data_size = serialize_records(record_arr, &serialized_data);

    record_array_t *new_record_arr = initialize_record_array();
    deserialize_records(serialized_data, data_size, new_record_arr);

    free(serialized_data);

    read_integers();

    free_record_array(new_record_arr);
    free_record_array(record_arr);

    return 0;
}
