#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int *value;
    int isValid;
    time_t timestamp;
} Record;

// Function to allocate memory for a long array
long* allocateLongArray(size_t size) {
    if (size <= 0) return NULL;

    long *arr = (long*)malloc(sizeof(long) * size);
    if (!arr) return NULL; // Memory allocation failed

    return arr;
}

// Function to allocate memory for an int array
int* allocateIntArray(size_t size) {
    if (size <= 0) return NULL;

    int *arr = (int*)malloc(sizeof(int) * size);
    if (!arr) return NULL; // Memory allocation failed

    return arr;
}

// Function to initialize and randomly populate the int array with unique values
void initializeIntArray(int *array, size_t size, int min_val, int max_val) {
    if (!array || size == 0 || min_val >= max_val) return;

    srand((unsigned int)time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < size; ++i) {
        array[i] = min_val + rand() % (max_val - min_val + 1);
    }

    // Ensure all values are unique
    for (size_t i = 0; i < size - 1; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            while (array[i] == array[j]) {
                array[j] = min_val + rand() % (max_val - min_val + 1);
            }
        }
    }
}

// Function to allocate memory for the record array and initialize it
Record* allocateAndInitializeRecords(size_t numRecords, int *intArray) {
    if (numRecords == 0 || !intArray) return NULL;

    Record *records = (Record*)malloc(sizeof(Record) * numRecords);
    if (!records) return NULL; // Memory allocation failed

    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = &intArray[i];
        records[i].isValid = 1;
        records[i].timestamp = time(NULL); // Capture current timestamp
    }

    return records;
}

// Main function to allocate and manage resources, ensuring cleanup in case of failure
void* createDataStructures(size_t longSize, size_t intSize, size_t recordSize, int min_val, int max_val) {
    if (longSize == 0 || intSize == 0 || recordSize == 0) return NULL;

    // Allocate memory for all structures
    long *longArray = allocateLongArray(longSize);
    if (!longArray) goto cleanup;

    int *intArray = allocateIntArray(intSize);
    if (!intArray) goto cleanup_long;

    Record *records = allocateAndInitializeRecords(recordSize, intArray);
    if (!records) goto cleanup_int;

    initializeIntArray(intArray, recordSize, min_val, max_val);

    // Return a pointer to an anonymous struct holding all allocated resources
    typedef struct {
        long *longs;
        int *ints;
        Record *recs;
    } AllData;

    AllData *allData = (AllData*)malloc(sizeof(AllData));
    if (!allData) goto cleanup_records;

    allData->longs = longArray;
    allData->ints = intArray;
    allData->recs = records;

    return allData;

cleanup_records:
    free(records);
cleanup_int:
    free(intArray);
cleanup_long:
    free(longArray);

cleanup:
    // No further resources to clean up
    return NULL; // Indicate allocation failure
}

int main() {
    size_t longSize = 10, intSize = 5, recordSize = 3;
    int min_val = 1, max_val = 100;

    void *dataStructures = createDataStructures(longSize, intSize, recordSize, min_val, max_val);

    if (!dataStructures) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Use the allocated structures here

    // Cleanup
    AllData *allData = (AllData*)dataStructures;
    free(allData->recs);
    free(allData->ints);
    free(allData->longs);
    free(allData);

    return EXIT_SUCCESS;
}
```

### Design Decisions and Trade-offs:
1. **System Dependencies**: The function is designed to use only the standard C library, making it portable and minimizing dependencies.
2. **Performance Constraints**: To enhance performance, `initializeIntArray` ensures unique values without significant overhead by using a simple nested loop for uniqueness checks after random initialization. This approach is straightforward but may need optimization if `intSize` grows very large.
3. **Scalability**: The function uses dynamic memory allocation and can handle various input sizes efficiently. Memory allocations are done only once per structure type, reducing the impact of frequent allocations/deallocations.
4. **Resource Management**: Comprehensive error handling is implemented to ensure that any allocated resources are freed in case of failure at any step, preventing memory leaks.

This approach balances efficiency, usability, maintainability, and scalability while minimizing external dependencies and ensuring robust resource management.']

