    *count = 0;
}

// Calculate average accuracy from multiple logs
double calculate_average_accuracy(const char *log_paths[], size_t num_logs, const Config *config) {
    double total_accuracy = 0.0;

    for (size_t i = 0; i < num_logs; ++i) {
        load_sensor_data(log_paths[i], config);
        // Calculate accuracy for each log and accumulate
    }

    return total_accuracy / num_logs;
}

// Serialize a data point to file
void serialize_data_point(FILE *file, DataPoint data_point) {
    fwrite(&data_point.identifier, sizeof(char), 1, file);
    size_t values_count = data_point.values_count;
    fwrite(&values_count, sizeof(size_t), 1, file);
    if (values_count > 0) {
        fwrite(data_point.sensor_values, sizeof(unsigned short), values_count, file);
    }
}

// Deserialize a data point from file
DataPoint deserialize_data_point(FILE *file) {
    DataPoint dp;
    fread(&dp.identifier, sizeof(char), 1, file);
    size_t values_count;
    fread(&values_count, sizeof(size_t), 1, file);

    if (values_count > 0) {
        dp.sensor_values = malloc(values_count * sizeof(unsigned short));
        if (!dp.sensor_values) {
            perror("Failed to allocate memory for sensor values");
            exit(EXIT_FAILURE);
        }
        fread(dp.sensor_values, sizeof(unsigned short), values_count, file);
    } else {
        dp.sensor_values = NULL;
    }

    dp.values_count = values_count;
    return dp;
}

// Main function
int main() {
    Config config = read_config();

    // Example usage with hardcoded log paths
    const char *log_paths[] = {"log1.txt", "log2.txt"};
    size_t num_logs = sizeof(log_paths) / sizeof(log_paths[0]);

    double average_accuracy = calculate_average_accuracy(log_paths, num_logs, &config);
    printf("Average accuracy: %f\n", average_accuracy);

    return 0;
}
