            free(collection->records);
            return -1;
        }
        size_t str_len = strlen(str) + 1;
        rec->string = malloc(str_len);
        if (!rec->string) {
            perror("Failed to allocate memory for string");
            free(str);
            free(collection->records);
            return -1;
        }
        strcpy(rec->string, str);
        free(str);

        // Allocate additional space
        collection->current_memory_usage += sizeof(Record) + str_len;

        if (collection->current_memory_usage > MEMORY_BUDGET) {
            fprintf(stderr, "Memory budget exceeded\n");
            for (size_t j = 0; j <= i; ++j) {
                free(collection->records[j].string);
            }
            free(collection->records);
            return -1;
        }

        rec->key = i;
        rec->offset = rand() % 1000000L;
        rec->value = (rand() % (value_range_max - value_range_min + 1)) + value_range_min;

        // Log memory usage
        printf("Memory usage after record %zu: %zu bytes\n", i, collection->current_memory_usage);
    }

    return 0;
}

// Function to serialize the data structure into a byte array
int serialize_record_collection(const RecordCollection *collection, unsigned char **buffer) {
    size_t total_size = sizeof(size_t); // for record_count
    for (size_t i = 0; i < collection->record_count; ++i) {
        total_size += sizeof(int) + sizeof(long) + sizeof(int) + strlen(collection->records[i].string) + 1;
    }

    *buffer = malloc(total_size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization buffer");
        return -1;
    }

    unsigned char *ptr = *buffer;
    memcpy(ptr, &collection->record_count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < collection->record_count; ++i) {
        Record *rec = &collection->records[i];
        memcpy(ptr, &rec->key, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &rec->offset, sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &rec->value, sizeof(int));
        ptr += sizeof(int);

        size_t str_len = strlen(rec->string) + 1;
        memcpy(ptr, rec->string, str_len);
        ptr += str_len;
    }

    return 0;
}

// Function to deserialize the byte array back into the data structure
int deserialize_record_collection(const unsigned char *buffer, RecordCollection *collection) {
    const unsigned char *ptr = buffer;

    size_t record_count;
    memcpy(&record_count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if (record_count < 0 || record_count > MAX_RECORDS) {
        fprintf(stderr, "Invalid number of records in deserialization\n");
        return -1;
    }

    collection->records = malloc(record_count * sizeof(Record));
    if (!collection->records) {
        perror("Failed to allocate memory for records during deserialization");
        return -1;
    }
    collection->record_count = record_count;

    for (size_t i = 0; i < record_count; ++i) {
        Record *rec = &collection->records[i];

        memcpy(&rec->key, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&rec->offset, ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(&rec->value, ptr, sizeof(int));
        ptr += sizeof(int);

        size_t str_len = strlen((const char *)ptr) + 1;
        rec->string = malloc(str_len);
        if (!rec->string) {
            perror("Failed to allocate memory for string during deserialization");
            for (size_t j = 0; j < i; ++j) {
                free(collection->records[j].string);
            }
            free(collection->records);
            return -1;
        }
        memcpy(rec->string, ptr, str_len);
        ptr += str_len;
    }

    return 0;
}

// Function to clean up the memory used by the record collection
void cleanup_record_collection(RecordCollection *collection) {
    for (size_t i = 0; i < collection->record_count; ++i) {
        free(collection->records[i].string);
    }
    free(collection->records);
    printf("Memory cleaned up successfully\n");
}

int main() {
    RecordCollection collection;
    if (init_record_collection(&collection, 10, 1, 100) != 0) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return EXIT_FAILURE;
    }

    unsigned char *buffer = NULL;
    if (serialize_record_collection(&collection, &buffer) != 0) {
        fprintf(stderr, "Failed to serialize record collection\n");
        cleanup_record_collection(&collection);
        return EXIT_FAILURE;
    }

    RecordCollection new_collection;
    if (deserialize_record_collection(buffer, &new_collection) != 0) {
        fprintf(stderr, "Failed to deserialize record collection\n");
        free(buffer);
        cleanup_record_collection(&collection);
        return EXIT_FAILURE;
    }

    printf("Deserialization successful, %zu records loaded.\n", new_collection.record_count);

    free(buffer);
    cleanup_record_collection(&collection);
    cleanup_record_collection(&new_collection);

    return EXIT_SUCCESS;
}
