#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>

typedef struct {
    double x;
    double y;
} Point;

void freeMemory(double* doublesArray, Point* pointsArray) {
    if (doublesArray != NULL) {
        free(doublesArray);
    }
    if (pointsArray != NULL) {
        free(pointsArray);
    }
}

int serializeData(const double* doublesArray, const Point* pointsArray, size_t doubleCount, size_t pointCount, uint8_t** buffer, size_t* bufferSize) {
    if (!doublesArray || !pointsArray || !buffer || !bufferSize) return -1;

    *bufferSize = sizeof(double) * doubleCount + sizeof(Point) * pointCount;
    *buffer = (uint8_t*)malloc(*bufferSize);
    if (*buffer == NULL) return -2;

    uint8_t* ptr = *buffer;
    for (size_t i = 0; i < doubleCount; ++i) {
        memcpy(ptr, &doublesArray[i], sizeof(double));
        ptr += sizeof(double);
    }
    for (size_t i = 0; i < pointCount; ++i) {
        memcpy(ptr, &pointsArray[i], sizeof(Point));
        ptr += sizeof(Point);
    }

    return 0;
}

int deserializeData(const uint8_t* buffer, size_t bufferSize, double** doublesArray, Point** pointsArray, size_t* doubleCount, size_t* pointCount) {
    if (!buffer || !doublesArray || !pointsArray || !doubleCount || !pointCount) return -1;

    *doublesArray = (double*)malloc(bufferSize / 2);
    *pointsArray = (Point*)(*(uint8_t**)(((char*)*doublesArray) + bufferSize / 2));

    if (*doublesArray == NULL || *pointsArray == NULL) {
        freeMemory(*doublesArray, *pointsArray);
        return -2;
    }

    uint8_t* ptr = (uint8_t*)buffer;
    for (size_t i = 0; i < bufferSize / (2 * sizeof(double)); ++i) {
        memcpy(&((*doublesArray)[i]), ptr, sizeof(double));
        ptr += sizeof(double);
    }
    for (size_t i = 0; i < bufferSize / (2 * sizeof(Point)); ++i) {
        memcpy(&((*pointsArray)[i]), ptr, sizeof(Point));
        ptr += sizeof(Point);
    }

    *doubleCount = bufferSize / (2 * sizeof(double));
    *pointCount = bufferSize / (2 * sizeof(Point));

    return 0;
}

int initializeAndSerialize(size_t doubleCount, size_t pointCount, uint8_t** buffer, size_t* bufferSize) {
    if (!buffer || !bufferSize) return -1;

    // Total memory budget
    const size_t totalMemoryBudget = (doubleCount + pointCount * 2) * sizeof(double);

    double* doublesArray = (double*)malloc(totalMemoryBudget);
    Point* pointsArray = (Point*)malloc((totalMemoryBudget / sizeof(double)) / 2 * sizeof(Point));

    if (!doublesArray || !pointsArray) {
        freeMemory(doublesArray, pointsArray);
        return -2;
    }

    // Seed random number generator
    srand(time(NULL));

    for (size_t i = 0; i < doubleCount; ++i) {
        doublesArray[i] = ((double)rand() / RAND_MAX) * 100.0;  // Example range [0, 100)
    }

    for (size_t i = 0; i < pointCount; ++i) {
        pointsArray[i].x = ((double)rand() / RAND_MAX) * 100.0;
        pointsArray[i].y = ((double)rand() / RAND_MAX) * 100.0;
    }

    int result = serializeData(doublesArray, pointsArray, doubleCount, pointCount, buffer, bufferSize);

    freeMemory(doublesArray, pointsArray);

    return result;
}

int main() {
    uint8_t* buffer;
    size_t bufferSize;

    if (initializeAndSerialize(10, 5, &buffer, &bufferSize) == 0) {
        printf("Serialization successful. Buffer Size: %zu\n", bufferSize);

        double* deserializedDoubles = NULL;
        Point* deserializedPoints = NULL;
        size_t doubleCount, pointCount;

        if (deserializeData(buffer, bufferSize, &deserializedDoubles, &deserializedPoints, &doubleCount, &pointCount) == 0) {
            printf("Deserialization successful.\n");

            // Free the deserialized data
            freeMemory(deserializedDoubles, deserializedPoints);
        } else {
            printf("Deserialization failed.\n");
        }

        free(buffer);  // Free the serialized buffer
    } else {
        printf("Initialization and Serialization failed.\n");
    }

    return 0;
}
