#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_MEMORY_SIZE 10485760 // 10 MB limit for example
#define LOG_FILE "processor.log"

typedef struct {
    char **records;
    size_t *offsets;
    int *keys;
    unsigned char **serialized_data;
    pthread_mutex_t lock;
} BatchProcessor;

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

BatchProcessor* initialize_batch_processor(int num_streams) {
    BatchProcessor *bp = malloc(sizeof(BatchProcessor));
    if (!bp) return NULL;

    pthread_mutex_init(&bp->lock, NULL);

    bp->records = malloc(num_streams * sizeof(char *));
    bp->offsets = malloc(num_streams * sizeof(size_t));
    bp->keys = malloc(num_streams * sizeof(int));
    bp->serialized_data = malloc(num_streams * sizeof(unsigned char *));

    if (!bp->records || !bp->offsets || !bp->keys || !bp->serialized_data) {
        log_event("Memory allocation error");
        free(bp);
        return NULL;
    }

    for (int i = 0; i < num_streams; ++i) {
        bp->records[i] = NULL;
        bp->offsets[i] = 0;
        bp->keys[i] = -1;
        bp->serialized_data[i] = NULL;
    }

    log_event("BatchProcessor initialized successfully");
    return bp;
}

void free_batch_processor(BatchProcessor *bp, int num_streams) {
    if (!bp) return;

    pthread_mutex_lock(&bp->lock);
    for (int i = 0; i < num_streams; ++i) {
        free(bp->records[i]);
        free(bp->serialized_data[i]);
    }
    free(bp->records);
    free(bp->offsets);
    free(bp->keys);
    free(bp->serialized_data);
    pthread_mutex_unlock(&bp->lock);

    pthread_mutex_destroy(&bp->lock);
    free(bp);

    log_event("BatchProcessor resources freed");
}

void serialize_record(const char *record, unsigned char **output) {
    size_t len = strlen(record);
    *output = malloc(len + 1); // Assuming no additional serialization logic

    if (*output) {
        memcpy(*output, record, len + 1);
    } else {
        log_event("Serialization memory allocation error");
    }
}

void process_streams(BatchProcessor *bp, FILE **streams, int num_streams) {
    char buffer[1024];
    size_t current_memory_usage = 0;

    for (int i = 0; i < num_streams; ++i) {
        if (!fgets(buffer, sizeof(buffer), streams[i])) continue;

        pthread_mutex_lock(&bp->lock);
        size_t record_size = strlen(buffer);

        // Enforce memory limit
        if ((current_memory_usage + record_size) > MAX_MEMORY_SIZE) {
            log_event("Memory allocation limit exceeded");
            break;
        }

        bp->records[i] = strdup(buffer);
        current_memory_usage += record_size;

        serialize_record(bp->records[i], &bp->serialized_data[i]);

        pthread_mutex_unlock(&bp->lock);

        if (!bp->records[i] || !bp->serialized_data[i]) {
            log_event("Error processing stream");
            break;
        }
    }
}

void batch_processor(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input_file1> <input_file2> ... <input_fileN>\n", argv[0]);
        return;
    }

    srand(time(NULL));

    int num_streams = argc - 1;
    FILE **streams = malloc(num_streams * sizeof(FILE *));
    if (!streams) {
        log_event("Memory allocation error for file streams");
        return;
    }

    for (int i = 0; i < num_streams; ++i) {
        streams[i] = fopen(argv[i + 1], "r");
        if (!streams[i]) {
            log_event("Error opening input file");
        }
    }

    BatchProcessor *bp = initialize_batch_processor(num_streams);
    if (!bp) return;

    process_streams(bp, streams, num_streams);

    for (int i = 0; i < num_streams; ++i) {
        if (streams[i]) fclose(streams[i]);
    }

    free(streams);
    free_batch_processor(bp, num_streams);
}
```

