#include "record_manager.h"
#include <string.h>
#include <errno.h>

#define BUFFER_SIZE 256

// Load configuration from a file
int load_config(const char *filename, int *max_records, size_t *memory_limit, int *min_value, int *max_value) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    // Example config loading (simple parsing for demonstration)
    fscanf(file, "%d %zu %d %d", max_records, memory_limit, min_value, max_value);
    fclose(file);

    return 0;
}

// Initialize records with random values
void initialize_records(Record **records, int max_records, size_t memory_limit, int min_value, int max_value) {
    seed_random();
    *records = malloc(max_records * sizeof(Record));
    if (!*records) {
        perror("Failed to allocate records");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < max_records; ++i) {
        (*records)[i].value = get_random_int(min_value, max_value);
        (*records)[i].offset = rand() % 100000;
        size_t buffer_size = BUFFER_SIZE + sizeof(int);
        if (buffer_size * max_records > memory_limit) {
            fprintf(stderr, "Memory limit exceeded\n");
            exit(EXIT_FAILURE);
        }
        (*records)[i].buffer = malloc(buffer_size);
        if (!(*records)[i].buffer) {
            perror("Failed to allocate buffer");
            free_records(*records, i); // Free partially allocated records
            exit(EXIT_FAILURE);
        }
    }
}

// Free allocated resources for records
void free_records(Record *records, int max_records) {
    for (int i = 0; i < max_records; ++i) {
        free(records[i].buffer);
    }
    free(records);
}

// Seed the random number generator
void seed_random() {
    srand((unsigned int)time(NULL));
}

// Get a random integer within a specified range
int get_random_int(int min, int max) {
    if (min > max) return min;
    return rand() % (max - min + 1) + min;
}
