['Here's a C function that addresses your requirements. It uses dynamic memory management, threading, and caching mechanisms. This example assumes POSIX threads (pthreads) for concurrency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct CacheEntry {
    long *offsets;
    int *keys;
    record *records;
    size_t offsets_size;
    size_t keys_size;
    size_t records_size;
    pthread_mutex_t lock;
    struct CacheEntry *next;
} CacheEntry;

static CacheEntry *cache_head = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

CacheEntry* find_cache_entry(size_t offsets_size, size_t keys_size, size_t records_size) {
    CacheEntry *entry = cache_head;
    while (entry) {
        if (entry->offsets_size == offsets_size && entry->keys_size == keys_size && entry->records_size == records_size)
            return entry;
        entry = entry->next;
    }
    return NULL;
}

void release_cache_entry(CacheEntry *entry) {
    pthread_mutex_lock(&cache_lock);
    if (entry == cache_head) {
        cache_head = entry->next;
    } else {
        CacheEntry *prev = cache_head;
        while (prev && prev->next != entry)
            prev = prev->next;
        if (prev)
            prev->next = entry->next;
    }
    pthread_mutex_unlock(&cache_lock);
}

void add_cache_entry(CacheEntry *entry) {
    pthread_mutex_lock(&cache_lock);
    entry->next = cache_head;
    cache_head = entry;
    pthread_mutex_unlock(&cache_lock);
}

CacheEntry* allocate_memory(size_t offsets_size, size_t keys_size, size_t records_size) {
    CacheEntry *entry = find_cache_entry(offsets_size, keys_size, records_size);

    if (entry) {
        return entry;
    }

    entry = malloc(sizeof(CacheEntry));
    if (!entry) {
        perror("Failed to allocate cache entry");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&entry->lock, NULL);
    entry->offsets = malloc(offsets_size * sizeof(long));
    entry->keys = malloc(keys_size * sizeof(int));
    entry->records = malloc(records_size * sizeof(record));

    if (!entry->offsets || !entry->keys || !entry->records) {
        free(entry->offsets);
        free(entry->keys);
        free(entry->records);
        free(entry);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    entry->offsets_size = offsets_size;
    entry->keys_size = keys_size;
    entry->records_size = records_size;

    srand(time(NULL));
    for (size_t i = 0; i < records_size; ++i) {
        entry->records[i].value = rand() % 100; // Random number between 0 and 99
    }

    add_cache_entry(entry);

    return entry;
}

void free_memory(CacheEntry *entry) {
    pthread_mutex_lock(&entry->lock);
    free(entry->offsets);
    free(entry->keys);
    free(entry->records);
    pthread_mutex_unlock(&entry->lock);
    pthread_mutex_destroy(&entry->lock);
    free(entry);
}

void resize_memory(CacheEntry *entry, size_t new_offsets_size, size_t new_keys_size, size_t new_records_size) {
    pthread_mutex_lock(&entry->lock);

    entry->offsets = realloc(entry->offsets, new_offsets_size * sizeof(long));
    entry->keys = realloc(entry->keys, new_keys_size * sizeof(int));

    if (new_records_size > entry->records_size) {
        record *temp = realloc(entry->records, new_records_size * sizeof(record));
        if (temp) {
            entry->records = temp;
            for (size_t i = entry->records_size; i < new_records_size; ++i) {
                entry->records[i].value = rand() % 100; // Random number between 0 and 99
            }
        } else {
            perror("Failed to resize records");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(&entry->lock);

    entry->offsets_size = new_offsets_size;
    entry->keys_size = new_keys_size;
    entry->records_size = new_records_size;
}

void* manage_memory(void *args) {
    size_t offsets_size = *(size_t *)args;
    size_t keys_size = *(size_t *)((char *)args + sizeof(size_t));
    size_t records_size = *(size_t *)((char *)args + 2 * sizeof(size_t));

    CacheEntry *entry = allocate_memory(offsets_size, keys_size, records_size);

    // Simulate work with the memory
    pthread_mutex_lock(&entry->lock);
    printf("Offsets: %ld\nKeys: %d\nRecord Value: %d\n",
           entry->offsets[0], entry->keys[0], entry->records[0].value);
    pthread_mutex_unlock(&entry->lock);

    // Simulate resizing
    resize_memory(entry, offsets_size + 10, keys_size + 5, records_size + 3);

    free_memory(entry);

    return NULL;
}

int main() {
    size_t offsets_size = 100;
    size_t keys_size = 50;
    size_t records_size = 20;

    pthread_t thread1, thread2;

    void *args1 = malloc(3 * sizeof(size_t));
    void *args2 = malloc(3 * sizeof(size_t));

    *(size_t *)args1 = offsets_size;
    *(size_t *)((char *)args1 + sizeof(size_t)) = keys_size;
    *(size_t *)((char *)args1 + 2 * sizeof(size_t)) = records_size;

    *(size_t *)args2 = offsets_size + 10;
    *(size_t *)((char *)args2 + sizeof(size_t)) = keys_size + 5;
    *(size_t *)((char *)args2 + 2 * sizeof(size_t)) = records_size + 3;

    pthread_create(&thread1, NULL, manage_memory, args1);
    pthread_create(&thread2, NULL, manage_memory, args2);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free(args1);
    free(args2);

    return 0;
}
```

### Key Features:
- **Memory Management**: Dynamically allocates memory for arrays and structures.
- **Thread Safety**: Uses mutexes to ensure safe access in a multithreaded environment.
- **Caching Mechanism**: Reuses previously allocated memory blocks if they match the requested sizes, minimizing allocations.
- **Dynamic Resizing**: Supports resizing of arrays while maintaining data integrity.
- **Random Initialization**: Initializes `record` values with random numbers within a specified range.

This implementation balances efficiency and usability for high-concurrency environments.']

