                try {
                    future.get();
                } catch (InterruptedException | ExecutionException e) {
                    logger.error("Error processing batch job", e);
                }
            }

        } catch (IOException | InterruptedException e) {
            logger.error("Failed to start the batch processing service", e);
        } finally {
            executorService.shutdown();
        }
