#define MAX_KEY 1000
#define MAX_ELEMENTS 10000

typedef struct {
    long value;
} record;

int initialize_data(long *offsets, int *keys, record **records) {
    int i, j;
    size_t n = sizeof(keys) / sizeof(keys[0]);

    // Allocate memory for arrays
    offsets = (long *)malloc(n * sizeof(long));
    if (!offsets) return -1;

    keys = (int *)malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1;
    }

    *records = (record *)malloc(n * sizeof(record));
    if (!(*records)) {
        free(offsets);
        free(keys);
        return -1;
    }

    // Initialize keys with random values
    for (i = 0; i < n; ++i) {
        keys[i] = rand() % MAX_KEY;
    }

    // Retry mechanism to ensure unique offsets
    int success = 0;
    while (!success) {
        int is_unique = 1;

        // Calculate offsets and check uniqueness
        for (i = 0; i < n; ++i) {
            offsets[i] = keys[i] % MAX_KEY;

            for (j = 0; j < i; ++j) {
                if (offsets[i] == offsets[j]) {
                    is_unique = 0;
                    break;
                }
            }

            if (!is_unique) break;
        }

        // If not unique, retry with new keys
        if (!is_unique) {
            free(offsets);
            free(keys);
            free(*records);

            offsets = (long *)malloc(n * sizeof(long));
            if (!offsets) return -1;

            keys = (int *)malloc(n * sizeof(int));
            if (!keys) {
                free(offsets);
                return -1;
            }

            *records = (record *)malloc(n * sizeof(record));
            if (!(*records)) {
                free(offsets);
                free(keys);
                return -1;
            }
        } else {
            success = 1;
        }
    }

    // Initialize records
    for (i = 0; i < n; ++i) {
        (*records)[i].value = offsets[i] + keys[i];

        // Ensure unique random values in a given range, example [0, 10000]
        long unique_value;
        do {
            unique_value = rand() % MAX_KEY;
        } while (unique_value == ((*records)[i].value)); // Simplistic uniqueness check
        (*records)[i].value = unique_value;
    }

    return 0; // Success
}

void cleanup(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
