void* manage_memory(void *arg) {
    // Arguments passed to the function should be a structure containing necessary parameters
    // e.g., initial sizes, max sizes, ranges etc.

    typedef struct {
        size_t initial_offset_size;
        size_t initial_key_size;
        int min_value;
        int max_value;
        size_t num_records;
    } Config;

    Config *config = (Config *)arg;

    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;
    int *unique_keys = malloc(config->initial_key_size * sizeof(int));
    if (!unique_keys) {
        perror("Failed to allocate unique keys");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    size_t current_offset_size = config->initial_offset_size;
    size_t current_key_size = config->initial_key_size;
    size_t total_records = 0;

    while (total_records < config->num_records) {
        pthread_mutex_lock(&lock);

        // Dynamic resizing if needed
        if (total_records >= current_offset_size) {
            current_offset_size *= 2;
            offsets = realloc(offsets, current_offset_size * sizeof(long));
            if (!offsets) {
                perror("Failed to reallocate offsets");
                break;
            }
        }

        if (total_records >= current_key_size) {
            current_key_size *= 2;
            keys = realloc(keys, current_key_size * sizeof(int));
            if (!keys) {
                perror("Failed to reallocate keys");
                break;
            }
        }

        int new_key = rand() % (config->max_value - config->min_value + 1) + config->min_value;

        // Ensure uniqueness
        int unique = 0;
        for (size_t i = 0; i < total_records; ++i) {
            if (keys[i] == new_key) {
                unique = 1;
                break;
            }
        }

        if (!unique) {
            keys[total_records] = new_key;
            offsets[total_records++] = rand(); // Simulate offset
        }

        pthread_mutex_unlock(&lock);
    }

    records = malloc(total_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate records");
        free(offsets);
        free(keys);
        free(unique_keys);
        return NULL;
    }

    for (size_t i = 0; i < total_records; ++i) {
        records[i].value = keys[i];
        records[i].timestamp = time(NULL); // Initialize timestamp
    }

    // Periodic garbage collection logic or any other cleanup can be implemented here

    printf("Memory management completed with %zu records.\n", total_records);

    free(offsets);
    free(keys);
    free(records);
    free(unique_keys);

    return NULL;
}

int main() {
    Config config = {10, 10, 0, 100, 10000000}; // Example configuration

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_memory, &config)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    if (pthread_join(thread_id, NULL)) {
        fprintf(stderr, "Error joining thread\n");
        return 2;
    }

    return 0;
}
```

### Design Decisions:
- **Thread Safety:** Used `pthread_mutex_t` to ensure exclusive access to shared resources, preventing data races.
- **Dynamic Resizing:** Arrays are dynamically resized using `realloc`, which helps in efficiently managing memory and handling large datasets.
- **Random Initialization & Uniqueness:** Ensured uniqueness by checking the newly generated key against existing keys before storing it.
- **Error Handling:** Included checks for successful memory allocation to prevent leaks and handle failures gracefully.
- **Concurrency Support:** Designed for concurrent execution, enabling efficient resource management across multiple threads.

### Trade-offs:
- **Efficiency vs. Complexity:** While `realloc` is used for dynamic resizing, this approach adds complexity but provides better memory efficiency compared to static arrays.
- **Thread Safety Overhead:** Mutexes introduce some overhead but are necessary for ensuring data consistency in a multithreaded environment.
- **Resource Management:** Proper resource cleanup ensures that the system remains stable and prevents leaks even when errors occur.']

