#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB in bytes
#define MAX_RECORDS 10000
#define KEY_RANGE 1000

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    FILE *log_file;
} logger_t;

void log_error(logger_t *logger, const char *message) {
    pthread_mutex_lock(&logger->lock);
    time_t now = time(NULL);
    fprintf(logger->log_file, "[%s] ERROR: %s\n", ctime(&now), message);
    fflush(logger->log_file);
    pthread_mutex_unlock(&logger->lock);
}

int initialize_memory(long *offset_array, int *key_array, record **record_array,
                      size_t offset_size, size_t key_size, size_t record_count,
                      logger_t *logger) {
    if (offset_size > MAX_MEMORY_USAGE || key_size > MAX_MEMORY_USAGE ||
        sizeof(record) * record_count > MAX_MEMORY_USAGE) {
        log_error(logger, "Memory allocation request exceeds maximum allowed.");
        return -1;
    }

    long total_memory = offset_size + key_size + sizeof(record) * record_count;
    if (total_memory > MAX_MEMORY_USAGE) {
        log_error(logger, "Total memory usage would exceed 1 MB.");
        return -1;
    }

    offset_array = malloc(offset_size);
    if (!offset_array) {
        log_error(logger, "Failed to allocate memory for offsets.");
        return -1;
    }
    memset(offset_array, 0, offset_size);

    key_array = malloc(key_size);
    if (!key_array) {
        free(offset_array);
        log_error(logger, "Failed to allocate memory for keys.");
        return -1;
    }
    memset(key_array, 0, key_size);

    *record_array = malloc(sizeof(record) * record_count);
    if (!*record_array) {
        free(offset_array);
        free(key_array);
        log_error(logger, "Failed to allocate memory for records.");
        return -1;
    }

    for (size_t i = 0; i < record_count; ++i) {
        (*record_array)[i].value = 0;
    }

    return 0;
}

void *assign_random_values(void *args) {
    size_t start_index, end_index, step;
    record *records;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    srand((unsigned int)(tv.tv_sec + tv.tv_usec));

    start_index = ((thread_args_t *)args)->start_index;
    end_index = ((thread_args_t *)args)->end_index;
    records = ((thread_args_t *)args)->records;

    for (size_t i = start_index; i < end_index; i += step) {
        if (i >= end_index) break;
        records[i].value = rand() % KEY_RANGE;
    }

    return NULL;
}

int set_random_values(record *record_array, size_t record_count, int num_threads) {
    pthread_t threads[num_threads];
    thread_args_t args[num_threads];

    size_t chunk_size = (record_count + num_threads - 1) / num_threads;

    for (int i = 0; i < num_threads; ++i) {
        args[i].start_index = i * chunk_size;
        args[i].end_index = (i + 1) * chunk_size;
        if (args[i].end_index > record_count) args[i].end_index = record_count;
        args[i].records = record_array;

        pthread_create(&threads[i], NULL, assign_random_values, &args[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

long search_record(int *key_array, record *record_array, size_t key_size, size_t record_count, int key) {
    for (size_t i = 0; i < key_size && i < record_count; ++i) {
        if (key_array[i] == key) {
            return (long)i;
        }
    }

    return -1L;
}

int compare_records(const void *a, const void *b) {
    record *rec_a = (record *)a;
    record *rec_b = (record *)b;
    return rec_a->value - rec_b->value;
}

void sort_records(record *record_array, size_t record_count) {
    qsort(record_array, record_count, sizeof(record), compare_records);
}

int main() {
    long offset_array[MAX_MEMORY_USAGE / sizeof(long)];
    int key_array[MAX_MEMORY_USAGE / sizeof(int)];
    record *record_array = NULL;

    logger_t logger;
    pthread_mutex_init(&logger.lock, NULL);
    logger.log_file = fopen("app_log.txt", "a");

    size_t offset_size = 1024 * sizeof(long);
    size_t key_size = 512 * sizeof(int);
    size_t record_count = 5000;

    if (initialize_memory(offset_array, key_array, &record_array,
                          offset_size, key_size, record_count, &logger) != 0) {
        log_error(&logger, "Initialization failed.");
        return -1;
    }

    set_random_values(record_array, record_count, 4);

    sort_records(record_array, record_count);

    int search_key = 123; // Example search key
    long offset = search_record(key_array, record_array, key_size / sizeof(int), record_count, search_key);
    if (offset != -1) {
        printf("Key %d found at offset %ld.\n", search_key, offset);
    } else {
        printf("Key %d not found.\n", search_key);
    }

    free(offset_array);
    free(key_array);
    free(record_array);

    fclose(logger.log_file);
    pthread_mutex_destroy(&logger.lock);

    return 0;
}
