#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <fcntl.h>
#include <sys/epoll.h>

#define MAX_REQUESTS 100
#define BUFFER_SIZE 4096

typedef enum { LOW, MEDIUM, HIGH } Priority;
typedef enum { PENDING, IN_PROGRESS, COMPLETED, FAILED } RequestStatus;

typedef struct {
    char *request_url;
    char *request_data;
    char *response_buffer;
    size_t response_size;
    RequestStatus request_status;
    Priority priority;
} Network_Request;

typedef struct Node {
    Network_Request request;
    struct Node* next;
} Node;

Node* request_queue = NULL;
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t condition_var = PTHREAD_COND_INITIALIZER;

int epoll_fd;
pthread_t background_thread;

void initialize_buffers(Network_Request *request, size_t data_size) {
    request->response_buffer = (char *)malloc(BUFFER_SIZE);
    if (!request->response_buffer) exit(EXIT_FAILURE);

    request->request_data = (char *)malloc(data_size + 1);
    if (!request->request_data) {
        free(request->response_buffer);
        exit(EXIT_FAILURE);
    }
}

void enqueue_request(Network_Request new_request) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return;

    node->request = new_request;
    pthread_mutex_lock(&queue_mutex);

    node->next = request_queue;
    request_queue = node;

    pthread_cond_signal(&condition_var);
    pthread_mutex_unlock(&queue_mutex);
}

Network_Request dequeue_request() {
    pthread_mutex_lock(&queue_mutex);

    while (request_queue == NULL) {
        pthread_cond_wait(&condition_var, &queue_mutex);
    }

    Node* head = request_queue;
    Network_Request req = head->request;

    request_queue = head->next;
    free(head);

    pthread_mutex_unlock(&queue_mutex);
    return req;
}

void* handle_network_requests(void *arg) {
    while (1) {
        Network_Request request = dequeue_request();

        // Set up socket and perform network operations
        int sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) continue;

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(80);

        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

        if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            close(sockfd);
            continue;
        }

        // Send request
        write(sockfd, request.request_data, strlen(request.request_data));

        // Use epoll for asynchronous I/O
        struct epoll_event ev, events[MAX_REQUESTS];
        ev.events = EPOLLIN | EPOLLET;
        ev.data.fd = sockfd;

        if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, sockfd, &ev) < 0) continue;

        int nfds = epoll_wait(epoll_fd, events, MAX_REQUESTS, -1);
        for (int n = 0; n < nfds; ++n) {
            if (events[n].data.fd == sockfd && (events[n].events & EPOLLIN)) {
                ssize_t count = read(sockfd, request.response_buffer, BUFFER_SIZE);
                if (count == -1) {
                    if (errno != EAGAIN) continue;
                } else if (count == 0) {
                    close(sockfd);
                }
            }
        }

        close(sockfd);
    }
}

int main() {
    epoll_fd = epoll_create1(0);
    if (epoll_fd < 0) exit(EXIT_FAILURE);

    pthread_create(&background_thread, NULL, handle_network_requests, NULL);

    // Example usage
    Network_Request req;
    strcpy(req.request_url, "http://example.com");
    initialize_buffers(&req, strlen("GET / HTTP/1.1\r\nHost: example.com\r\n\r\n"));

    enqueue_request(req);

    pthread_join(background_thread, NULL);
    return 1;
}
