#include <pthread.h>

typedef struct {
    int value;
    long offset;
    char identifier;
    bool status_flag;
    int associated_value;
    long associated_offset;
    char *metadata;
} Record;

typedef struct {
    Record *records;
    int num_records;
    size_t max_size;
    pthread_mutex_t mutex;
} Collection;

int serialize_record(const Record *record, uint8_t **buffer, size_t *size) {
    if (!record || !buffer || !size)
        return -1;

    const size_t record_size = sizeof(record->value) + sizeof(record->offset) +
                               sizeof(record->identifier) + sizeof(record->status_flag) +
                               sizeof(record->associated_value) + sizeof(record->associated_offset) +
                               strlen(record->metadata) + 1;

    *buffer = malloc(record_size);
    if (!*buffer)
        return -2;

    uint8_t *ptr = *buffer;
    ptr += serialize_int(ptr, record->value);
    ptr += serialize_long(ptr, record->offset);
    memcpy(ptr++, &record->identifier, sizeof(char));
    ptr += serialize_bool(ptr, record->status_flag);
    ptr += serialize_int(ptr, record->associated_value);
    ptr += serialize_long(ptr, record->associated_offset);
    strcpy((char*)ptr, record->metadata);

    *size = ptr - *buffer;
    return 0;
}

int deserialize_record(Record *record, const uint8_t *buffer) {
    if (!record || !buffer)
        return -1;

    const uint8_t *ptr = buffer;
    ptr += deserialize_int(ptr, &record->value);
    ptr += deserialize_long(ptr, &record->offset);
    memcpy(&record->identifier, ptr++, sizeof(char));
    ptr += deserialize_bool(ptr, &record->status_flag);
    ptr += deserialize_int(ptr, &record->associated_value);
    ptr += deserialize_long(ptr, &record->associated_offset);
    record->metadata = strdup((const char*)ptr);

    return 0;
}

int serialize_int(uint8_t **buffer, int value) {
    uint32_t net_val;

    if (ntohl(value) != value)
        net_val = htonl(value);
    else
        net_val = value;

    *buffer = malloc(sizeof(net_val));
    if (*buffer == NULL)
        return -1;

    memcpy(*buffer, &net_val, sizeof(net_val));
    return sizeof(net_val);
}

int deserialize_int(const uint8_t **buffer, int *value) {
    const uint32_t net_val;

    memcpy(&net_val, *buffer, sizeof(net_val));
    *value = ntohl(net_val);

    *buffer += sizeof(net_val);
    return 0;
}

// Similarly implement serialize_long, deserialize_long,
// serialize_bool, and deserialize_bool functions

Collection* initialize_collection(size_t max_size) {
    Collection *col = malloc(sizeof(Collection));
