void initialize_directory_and_records(char **dir_path, Record *records) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);

    // Check and set directory path
    if (*dir_path == NULL) {
        char *env_dir = getenv("DIR_PATH");
        if (env_dir != NULL) {
            size_t len = strlen(env_dir) + 1;
            *dir_path = malloc(len);
            strncpy(*dir_path, env_dir, len);
        } else {
            // Set a default directory path
            const char *default_dir = "/tmp/my_program";
            size_t len = strlen(default_dir) + 1;
            *dir_path = malloc(len);
            strncpy(*dir_path, default_dir, len);

            // Create directory if it doesn't exist
            create_directory_if_not_exists(*dir_path);
        }
    }

    log_message("Directory path set to: ");
    log_message(*dir_path);

    // Seed random number generator
    srand(time(NULL));

    // Initialize records with random values
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = VALUE_MIN + rand() % (VALUE_MAX - VALUE_MIN + 1);
    }

    log_message("Records initialized.");

    pthread_mutex_unlock(&lock);
}

void create_directory_if_not_exists(const char *path) {
    struct stat st;

    if (stat(path, &st) != 0 || !S_ISDIR(st.st_mode)) {
        mkdir(path, S_IRWXU | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH);
        log_message("Created directory: ");
        log_message(path);
    }
}

void setup_logging() {
    // Redirect stdout to a log file
    int fd = open("/tmp/my_program.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd != -1) {
        dup2(fd, STDOUT_FILENO);
        close(fd);
    }
}

void log_message(const char *message) {
    printf("%s\n", message);
}
