#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long *offset;
    int key;
} Record;

Record* create_records(long size_offsets, int size_keys, const long* initial_offsets, const int* initial_keys) {
    if (size_offsets > 1000 || size_keys > 500 || size_keys < size_offsets / 2) {
        fprintf(stderr, "Invalid sizes: Offsets must not exceed 1000 and Keys must be at least half of offsets but not more than 500.\n");
        exit(EXIT_FAILURE);
    }

    long *offsets = (long *)malloc(size_offsets * sizeof(long));
    int *keys = (int *)malloc(size_keys * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets); // Free any allocated memory before exit
        free(keys);
        exit(EXIT_FAILURE);
    }

    Record *records = (Record *)malloc(size_keys * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for record structures.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Initialize offsets and keys with provided initial values or zero
    for (int i = 0; i < size_offsets; ++i) {
        offsets[i] = (initial_offsets && i < size_offsets) ? initial_offsets[i] : 0;
    }

    for (int j = 0; j < size_keys; ++j) {
        keys[j] = (initial_keys && j < size_keys) ? initial_keys[j] : 0;
    }

    // Initialize records
    for (int k = 0; k < size_keys; ++k) {
        records[k].offset = &offsets[k];
        records[k].key = keys[k];
    }

    return records;
}

void free_records(Record *records, int size_keys) {
    if (records) {
        free(records);
    }
}

int main() {
    long initial_offsets[] = {10, 20, 30}; // Example initial offsets
    int initial_keys[] = {1, 2, 3};       // Example initial keys

    Record *records = create_records(5, 4, initial_offsets, initial_keys);

    // Use records...

    free_records(records, 4);  // Ensure to pass the correct size for freeing memory

    return 0;
}
```

### Key Points:

- The function `create_records` allocates and initializes an array of `Record` structures.
