#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
    long *offset_ptr;
} record;

void cleanup(long *offsets, int *keys, record *records, size_t num_records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].offset_ptr) free(records[i].offset_ptr);
    }
    if (records) free(records);
}

int initialize_dataset(size_t *num_records, size_t max_int_range, size_t memory_threshold) {
    size_t record_size = sizeof(int) + sizeof(long*);
    size_t total_memory = 0;

    // Calculate the maximum number of records that can be allocated within the threshold
    while (total_memory + (*num_records) * record_size + *num_records * sizeof(long) + *num_records * sizeof(int) > memory_threshold) {
        --(*num_records);
        if (*num_records == 0) return -1; // Cannot allocate even a single record
    }

    long *offsets = (long *)malloc(*num_records * sizeof(long));
    int *keys = (int *)malloc(*num_records * sizeof(int));
    record *records = (record *)malloc(*num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        cleanup(offsets, keys, records, *num_records);
        return -1;
    }

    for (size_t i = 0; i < *num_records; ++i) {
        offsets[i] = i; // Example offset initialization
        keys[i] = rand() % max_int_range; // Random key within the specified range
        records[i].value = keys[i]; // Initialize record value with the key
        records[i].offset_ptr = &offsets[i]; // Point to the corresponding offset

        total_memory += sizeof(long) + sizeof(int) + record_size;
    }

    printf("Total memory used: %zu\n", total_memory);
    return 0; // Success
}

int main() {
    size_t num_records = 10000; // Example number of records
    size_t max_int_range = 100; // Maximum value for keys
    size_t memory_threshold = 50 * 1024 * 1024; // 50 MB threshold

    int result = initialize_dataset(&num_records, max_int_range, memory_threshold);
    if (result == -1) {
        fprintf(stderr, "Failed to allocate memory within the given constraints.\n");
        return EXIT_FAILURE;
    }

    // Use the dataset...

    // Cleanup after use
    cleanup(NULL, NULL, NULL, num_records);

    return EXIT_SUCCESS;
}
```

### Explanation:
