#include <sys/stat.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define CACHE_EXPIRATION_TIME 60 // seconds

typedef struct {
    int value;
} Record;

typedef struct {
    char *path;
    time_t last_accessed;
} CacheEntry;

CacheEntry config_cache = {NULL, 0};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    printf("[LOG]: %s\n", message);
}

char* get_directory_path() {
    pthread_mutex_lock(&lock);

    const char *dir_path_env = getenv("DIR_PATH");
    if (dir_path_env != NULL) {
        size_t len = strlen(dir_path_env) + 1;
        char *path = malloc(len);
        if (path == NULL) {
            log_message("Failed to allocate memory for directory path.");
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        strcpy(path, dir_path_env);
        log_message("Using existing DIR_PATH environment variable.");
    } else {
        const char *default_dir = "./default_directory";
        size_t len = strlen(default_dir) + 1;
        char *path = malloc(len);
        if (path == NULL) {
            log_message("Failed to allocate memory for directory path.");
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        strcpy(path, default_dir);
        setenv("DIR_PATH", default_dir, 1);
        log_message("Created new DIR_PATH environment variable.");
    }

    pthread_mutex_unlock(&lock);
    return path;
}

Record* initialize_records(int count, int min_val, int max_val) {
    Record *records = malloc(count * sizeof(Record));
    if (records == NULL) {
        log_message("Failed to allocate memory for records.");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    log_message("Initialized record values.");
    return records;
}

CacheEntry* get_cached_config(const char *config_path) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&lock);

    if (config_cache.path != NULL && 
        strcmp(config_cache.path, config_path) == 0 &&
        difftime(current_time, config_cache.last_accessed) < CACHE_EXPIRATION_TIME) {

        log_message("Returning cached configuration.");
        pthread_mutex_unlock(&lock);
        return &config_cache;
    }

    // Load configuration from file
    int fd = open(config_path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open config file");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char *content = malloc(1024); // Assuming max config size is 1024 bytes
    if (content == NULL) {
        close(fd);
        log_message("Failed to allocate memory for config content.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    ssize_t read_size = read(fd, content, 1023);
    if (read_size == -1) {
        perror("Failed to read config file");
        free(content);
        close(fd);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    content[read_size] = '\0';

    if (config_cache.path != NULL) {
        free(config_cache.path);
    }
    config_cache.path = strdup(config_path);
    strncpy(config_cache.content, content, read_size + 1);
    config_cache.last_accessed = current_time;

    close(fd);
    log_message("Updated cached configuration.");
    pthread_mutex_unlock(&lock);

    return &config_cache;
}

void free_resources(char *path, Record *records) {
    if (records != NULL) {
        free(records);
    }
    if (path != NULL) {
        free(path);
    }
    if (config_cache.path != NULL) {
        free(config_cache.path);
    }
    log_message("Freed allocated resources.");
}

int main() {
    char *dir_path = get_directory_path();
    if (dir_path == NULL) return EXIT_FAILURE;

    Record *records = initialize_records(MAX_RECORDS, 1, 100);
    if (records == NULL) {
        free_resources(dir_path, NULL);
        return EXIT_FAILURE;
    }

    CacheEntry *cached_config = get_cached_config("/path/to/config");
    // Assume some operations with cached config here

    free_resources(dir_path, records);

    return EXIT_SUCCESS;
}
