#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 500

typedef struct {
    long *offsets;
    int keys[MAX_KEYS];
    size_t num_offsets;
    size_t num_keys;
    pthread_mutex_t mutex;
} RecordCollection;

// Function to initialize the record collection
int init_record_collection(RecordCollection *collection, size_t num_offsets) {
    if (num_offsets > MAX_OFFSETS || num_offsets == 0) return -1;

    collection->num_offsets = num_offsets;
    collection->num_keys = num_offsets / 2 > MAX_KEYS ? MAX_KEYS : num_offsets / 2;

    long *offsets = (long *)calloc(num_offsets, sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return -1;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    collection->offsets = offsets;
    memset(collection->keys, 0, collection->num_keys * sizeof(int));

    // Log initialization
    printf("Initialized record collection with %zu offsets and %zu keys.\n", num_offsets, collection->num_keys);

    return 0;
}

// Function to safely access the records concurrently
void update_record(RecordCollection *collection, size_t index, int value) {
    if (index >= collection->num_keys) {
        fprintf(stderr, "Invalid key index: %zu\n", index);
        return;
    }

    pthread_mutex_lock(&collection->mutex);

    collection->keys[index] = value;

    // Log update
    printf("Updated record at index %zu to value %d.\n", index, value);

    pthread_mutex_unlock(&collection->mutex);
}

// Function to free the resources
void cleanup_record_collection(RecordCollection *collection) {
    if (collection->offsets) {
        free(collection->offsets);
    }
    pthread_mutex_destroy(&collection->mutex);

    // Log cleanup
    printf("Cleaned up record collection.\n");
}

// Example usage
int main() {
    RecordCollection collection;

    size_t num_offsets = 800; // User-defined, ensure within limits

    if (init_record_collection(&collection, num_offsets) != 0) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return EXIT_FAILURE;
    }

    update_record(&collection, 10, 42);

    cleanup_record_collection(&collection);

    return EXIT_SUCCESS;
}
```

