['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct OffsetListNode {
    long offset;
    struct OffsetListNode* next;
} OffsetListNode;

typedef struct KeyValueEntry {
    int key;
    OffsetListNode* offsets;
    pthread_mutex_t lock; // Mutex for thread-safe access
} KeyValueEntry;

typedef struct HashTable {
    size_t capacity;
    size_t size;
    KeyValueEntry** entries;
    pthread_rwlock_t rwlock; // Read-write lock for the table
} HashTable;

unsigned int hash(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

HashTable* create_table() {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    table->entries = calloc(table->capacity, sizeof(KeyValueEntry*));
    if (!table->entries) {
        free(table);
        return NULL;
    }

    pthread_rwlock_init(&table->rwlock, NULL);
    return table;
}

void expand_table(HashTable* table);

KeyValueEntry* find_entry(HashTable* table, int key) {
    unsigned int index = hash(key, table->capacity);
    KeyValueEntry* entry = table->entries[index];

    while (entry && entry->key != key) {
        entry = entry->next;
    }

    return entry;
}

void insert_offset(HashTable* table, int key, long offset) {
    pthread_rwlock_wrlock(&table->rwlock);

    KeyValueEntry* entry = find_entry(table, key);
    if (!entry) {
        entry = malloc(sizeof(KeyValueEntry));
        if (!entry) {
            pthread_rwlock_unlock(&table->rwlock);
            return;
        }

        entry->key = key;
        entry->offsets = NULL;
        pthread_mutex_init(&entry->lock, NULL);

        unsigned int index = hash(key, table->capacity);
        entry->next = table->entries[index];
        table->entries[index] = entry;

        table->size++;
    }

    OffsetListNode* new_node = malloc(sizeof(OffsetListNode));
    if (!new_node) {
        pthread_mutex_unlock(&entry->lock);
        pthread_rwlock_unlock(&table->rwlock);
        return;
    }

    new_node->offset = offset;
    new_node->next = entry->offsets;
    entry->offsets = new_node;

    pthread_mutex_unlock(&entry->lock);

    if ((double)table->size / table->capacity >= LOAD_FACTOR_THRESHOLD) {
        expand_table(table);
    }

    pthread_rwlock_unlock(&table->rwlock);
}

void delete_key(HashTable* table, int key) {
    pthread_rwlock_wrlock(&table->rwlock);

    unsigned int index = hash(key, table->capacity);
    KeyValueEntry** entry_ptr = &table->entries[index];

    while (*entry_ptr && (*entry_ptr)->key != key) {
        entry_ptr = &(*entry_ptr)->next;
    }

    if (*entry_ptr) {
        KeyValueEntry* entry_to_delete = *entry_ptr;
        pthread_mutex_lock(&entry_to_delete->lock);

        OffsetListNode* node = entry_to_delete->offsets;
        while (node) {
            OffsetListNode* next_node = node->next;
            free(node);
            node = next_node;
        }

        pthread_mutex_unlock(&entry_to_delete->lock);
        pthread_mutex_destroy(&entry_to_delete->lock);

        *entry_ptr = entry_to_delete->next;
        free(entry_to_delete);

        table->size--;
    }

    pthread_rwlock_unlock(&table->rwlock);
}

void expand_table(HashTable* table) {
    size_t new_capacity = table->capacity * 2;
    KeyValueEntry** new_entries = calloc(new_capacity, sizeof(KeyValueEntry*));

    if (!new_entries) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        KeyValueEntry* entry = table->entries[i];

        while (entry) {
            unsigned int new_index = hash(entry->key, new_capacity);

            KeyValueEntry* next_entry = entry->next;
            entry->next = new_entries[new_index];
            new_entries[new_index] = entry;

            entry = next_entry;
        }
    }

    free(table->entries);
    table->entries = new_entries;
    table->capacity = new_capacity;
}

void cleanup_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        KeyValueEntry* entry = table->entries[i];

        while (entry) {
            OffsetListNode* node = entry->offsets;

            while (node) {
                OffsetListNode* next_node = node->next;
                free(node);
                node = next_node;
            }

            pthread_mutex_destroy(&entry->lock);

            KeyValueEntry* next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }

    free(table->entries);
    pthread_rwlock_destroy(&table->rwlock);
    free(table);
}

void populate_table(HashTable* table, int key, long offset) {
    insert_offset(table, key, offset);
}

int main() {
    HashTable* table = create_table();

    // Populate the table with some data
    populate_table(table, 1, 1000L);
    populate_table(table, 2, 2000L);

    // Cleanup resources
    cleanup_table(table);

    return 0;
}
```

This implementation includes a dynamic key-value store using a hash table for fast lookups. It supports concurrent access with synchronization primitives and handles memory management to avoid leaks. The code expands the hash table when necessary to maintain efficiency.']

