    pool->num_clients = 0;
    pool->num_servers = num_servers;
    pool->server_ips = ips;
    pool->server_ports = ports;
    pool->max_retry_attempts = max_attempts;

    for (size_t i = 0; i < num_servers; ++i) {
        int sock = socket(AF_INET, SOCK_STREAM | SOCK_DGRAM, 0); // Example: TCP/UDP
        if (sock == -1) {
            perror("Socket creation failed");
            continue;
        }

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        inet_pton(AF_INET, ips[i], &server_addr.sin_addr);
        server_addr.sin_port = htons(ports[i]);

        if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("Connection failed");
            close(sock);
            continue;
        }

        pool->server_sockets[i] = sock;
    }
}

void cleanup_service_pool(ServicePool *pool) {
    for (size_t i = 0; i < pool->num_clients; ++i) {
        close(pool->clients[i].client_socket);
    }
    for (size_t j = 0; j < pool->num_servers; ++j) {
        if (pool->server_sockets[j] != -1) {
            close(pool->server_sockets[j]);
        }
    }
    pthread_mutex_destroy(&pool.lock);
}

int exponential_backoff(int attempt, unsigned int base_interval_ms) {
    return base_interval_ms * (1 << attempt) + rand() % 100; // Add jitter
}

