        {PROTOCOL_UDP, 3, 1, 4},
        {PROTOCOL_HTTP, 4, 3, 2},
        {PROTOCOL_HTTPS, 5, 4, 1},
        {PROTOCOL_WEBSOCKETS, 4, 3, 3}
    };

    int best_index = -1;
    int best_score = -1;

