// dynamic_collection.h
#ifndef DYNAMIC_COLLECTION_H
#define DYNAMIC_COLLECTION_H

#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    int key;
    long offset;
    char *identifier;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Collection;

Collection* create_collection(size_t initial_capacity);
int add_record(Collection *collection, int key, long offset, const char *identifier);
int update_record(Collection *collection, int key, long new_offset, const char *new_identifier);
int remove_record(Collection *collection, int key);
void destroy_collection(Collection *collection);

// Serialization and deserialization
size_t serialize_records(const Collection *collection, uint8_t **output);
int deserialize_records(uint8_t *input, size_t length, Collection *collection);

#endif // DYNAMIC_COLLECTION_H

// dynamic_collection.c
#include "dynamic_collection.h"
#include <string.h>
#include <stdio.h>

Collection* create_collection(size_t initial_capacity) {
    Collection *collection = (Collection *)malloc(sizeof(Collection));
    collection->records = (Record **)calloc(initial_capacity, sizeof(Record *));
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

int add_record(Collection *collection, int key, long offset, const char *identifier) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = (Record **)realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        memset(new_records + collection->capacity, 0, collection->capacity * sizeof(Record *));
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }
    record->key = key;
    record->offset = offset;
    record->identifier = strdup(identifier);

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_record(Collection *collection, int key, long new_offset, const char *new_identifier) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = collection->records[i];
        if (record->key == key) {
            record->offset = new_offset;
            free(record->identifier);
            record->identifier = strdup(new_identifier);
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Record not found
}

int remove_record(Collection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]->identifier);
            free(collection->records[i]);
            memmove(&collection->records[i], &collection->records[i + 1],
                    (collection->count - i - 1) * sizeof(Record *));
            collection->count--;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Record not found
}

void destroy_collection(Collection *collection) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->identifier);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Serialization and deserialization functions
size_t serialize_records(const Collection *collection, uint8_t **output) {
    size_t total_size = sizeof(size_t); // For storing the count

    for (size_t i = 0; i < collection->count; ++i) {
        total_size += sizeof(int) + sizeof(long) + strlen(collection->records[i]->identifier) + 1;
    }

    *output = (uint8_t *)malloc(total_size);
    if (!*output) return 0;

    uint8_t *ptr = *output;
    *(size_t *)ptr = collection->count;
    ptr += sizeof(size_t);

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = collection->records[i];
        memcpy(ptr, &record->key, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &record->offset, sizeof(long));
        ptr += sizeof(long);
        size_t str_len = strlen(record->identifier) + 1;
        memcpy(ptr, record->identifier, str_len);
        ptr += str_len;
    }

    return total_size;
}

int deserialize_records(uint8_t *input, size_t length, Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    if (length < sizeof(size_t)) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Invalid input
    }

    const size_t count = *(size_t *)input;
    input += sizeof(size_t);

    for (size_t i = 0; i < count; ++i) {
        if (length < sizeof(int) + sizeof(long)) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Invalid input
        }

        int key;
        long offset;

        memcpy(&key, input, sizeof(int));
        input += sizeof(int);
        memcpy(&offset, input, sizeof(long));
        input += sizeof(long);

        const char *identifier = (const char *)input;
        size_t str_len = strlen(identifier) + 1;
        if (length < str_len) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Invalid input
        }

        add_record(collection, key, offset, identifier);

        input += str_len;
        length -= sizeof(int) + sizeof(long) + str_len;
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Function to allocate and initialize arrays
void allocate_and_initialize_arrays(size_t num_records, int *keys, long *offsets, Record **records, int min_val, int max_val) {
    keys = (int *)malloc(num_records * sizeof(int));
    offsets = (long *)malloc(num_records * sizeof(long));
    records = (Record **)malloc(num_records * sizeof(Record *));

    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        offsets[i] = rand();
        Record *record = (Record *)malloc(sizeof(Record));
        record->key = keys[i];
        record->offset = offsets[i];
        record->identifier = NULL; // Placeholder for identifier
        records[i] = record;
    }
}

// Non-blocking recursive traversal for a DOM tree
typedef struct Node {
    void *data;
    struct Node **children;
    size_t child_count;
} Node;

void traverse_dom(Node *root, void (*func)(Node *)) {
    if (!root) return;

    func(root);

    for (size_t i = 0; i < root->child_count; ++i) {
        traverse_dom(root->children[i], func);
    }
}

// Example function to apply during traversal
void example_func(Node *node) {
