typedef struct MemoryPool {
    size_t size;
    void* start;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize the memory pool
int initMemoryPool(MemoryPool* pool, size_t size) {
    pool->size = size;
    pool->start = malloc(size);
    if (pool->start == NULL) return -1;
    pthread_mutex_init(&pool->lock, NULL);
    return 0;
}

// Function to allocate memory from the pool
void* poolAllocate(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    void* ptr = malloc(size); // Simplified for demonstration; use a real pool allocator here
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to free memory back to the pool
void poolFree(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    free(ptr); // Simplified; integrate with custom deallocator
    pthread_mutex_unlock(&pool->lock);
}

// Function to generate a random integer within range
int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Thread-safe function to manage records in the memory pool
void* manageRecords(void* arg) {
    struct {
        MemoryPool* pool;
        size_t recordCount;
        int minValue;
        int maxValue;
    } *params = (struct {
        MemoryPool* pool;
        size_t recordCount;
        int minValue;
        int maxValue;
    } *)arg;

    Record* records = (Record*)poolAllocate(params->pool, params->recordCount * sizeof(Record));
    if (!records) return NULL; // Handle allocation failure

    for (size_t i = 0; i < params->recordCount; ++i) {
        records[i].value = getRandomInt(params->minValue, params->maxValue);
    }

    printf("Allocated %zu records with values in range [%d, %d]\n", params->recordCount, params->minValue, params->maxValue);

    // Simulate concurrent updates
    for (size_t i = 0; i < params->recordCount; ++i) {
        pthread_mutex_lock(&params->pool->lock);
        records[i].value += getRandomInt(1, 10); // Update values
        pthread_mutex_unlock(&params->pool->lock);
    }

    printf("Updated %zu records\n", params->recordCount);

    poolFree(params->pool, records);
    return NULL;
}

int main() {
    srand(time(NULL));

    MemoryPool pool;
    if (initMemoryPool(&pool, 1024) != 0) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return -1;
    }

    pthread_t thread;
    struct {
        MemoryPool* pool;
        size_t recordCount;
        int minValue;
        int maxValue;
    } params = {&pool, 10, 0, 100};

    if (pthread_create(&thread, NULL, manageRecords, &params) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return -1;
    }

    pthread_join(thread, NULL);

    // Cleanup
    free(pool.start);
    pthread_mutex_destroy(&pool.lock);

    return 0;
}
