#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MAX_MEMORY_USAGE (10 * 1024 * 1024) // 10 MB

typedef struct {
    double value;
    char identifier[3];
} data_point;

typedef struct {
    data_point* point;
    float average;
    time_t timestamp;
} summary_statistics;

typedef struct {
    size_t requested_size;
    const char* reason;
} allocation_log_entry;

typedef struct {
    allocation_log_entry* entries;
    size_t count;
    size_t capacity;
} allocation_log;

void log_failed_allocation(allocation_log* log, size_t size, const char* reason) {
    if (log->count >= log->capacity) {
        size_t new_capacity = log->capacity ? log->capacity * 2 : 4;
        log->entries = realloc(log->entries, new_capacity * sizeof(allocation_log_entry));
        if (!log->entries) return;
        log->capacity = new_capacity;
    }
    log->entries[log->count].requested_size = size;
    strncpy(log->entries[log->count].reason, reason, 256);
    log->entries[log->count].reason[255] = '\0';
    log->count++;
}

void free_allocation_log(allocation_log* log) {
    if (log->entries) {
        free(log->entries);
        log->entries = NULL;
    }
    log->count = 0;
    log->capacity = 0;
}

int create_data_and_summary(int element_count, double range_min, double range_max, unsigned int seed, allocation_log* log) {
    if (element_count <= 0 || element_count > MAX_ELEMENTS) return -1;

    size_t data_point_size = sizeof(data_point);
    size_t summary_statistics_size = sizeof(summary_statistics);

    size_t total_memory_usage = element_count * (data_point_size + summary_statistics_size);
    if (total_memory_usage > MAX_MEMORY_USAGE) {
        log_failed_allocation(log, total_memory_usage, "Exceeds maximum memory usage");
        return -1;
    }

    data_point* data_points = malloc(element_count * data_point_size);
    if (!data_points) {
        log_failed_allocation(log, element_count * data_point_size, "Out of memory");
        return -1;
    }

    summary_statistics* summaries = malloc(element_count * summary_statistics_size);
    if (!summaries) {
        free(data_points);
        log_failed_allocation(log, element_count * summary_statistics_size, "Out of memory");
        return -1;
    }

    srand(seed);

    double total_value = 0.0;

    for (int i = 0; i < element_count; ++i) {
        data_point* dp = &data_points[i];
        dp->value = range_min + ((double)rand() / RAND_MAX) * (range_max - range_min);
        snprintf(dp->identifier, sizeof(dp->identifier), "%02d", i);

        total_value += dp->value;
    }

    for (int i = 0; i < element_count; ++i) {
        summaries[i].point = &data_points[i];
        summaries[i].average = (float)(total_value / element_count);
        summaries[i].timestamp = time(NULL);
    }

    // Simulate periodic recalculations of averages
    for (int recalc = 0; recalc < 5; ++recalc) {
        total_value = 0.0;
        for (int i = 0; i < element_count; ++i) {
            total_value += data_points[i].value;
        }
        for (int i = 0; i < element_count; ++i) {
            summaries[i].average = (float)(total_value / element_count);
            summaries[i].timestamp = time(NULL);
        }
    }

    free(data_points);
    free(summaries);

    return 0;
}

int main() {
    allocation_log log = {NULL, 0, 0};
    int result = create_data_and_summary(1000, 0.0, 1.0, 12345, &log);

    if (result != 0) {
        printf("Failed to allocate memory:\n");
        for (size_t i = 0; i < log.count; ++i) {
            printf("Requested size: %zu, Reason: %s\n", log.entries[i].requested_size, log.entries[i].reason);
        }
    }

    free_allocation_log(&log);

    return result;
}
