#include <time.h>

#define ERROR_MSG(msg) do { \
    fprintf(stderr, "%s\n", msg); \
    exit(EXIT_FAILURE); \
} while (0)

typedef struct record {
    int value;
    long *offset_ptr;
    int *key_ptr;
    struct record *next_record;  // Pointer to another record forming a linked list
} record;

// Function prototypes
void initialize_records(long n, int m, record **records, int k, int low, int high);
void set_random_values(record *records, int k, int low, int high);
void assign_pointers(record *records, long *offsets, int *keys, int k, int n, int m);
void free_memory(long *offsets, int *keys, record **records, int k);
void insert_into_linked_list(record *head, record *new_node, int max_size);
void traverse_and_operate(record *records, int k);
void garbage_collect(record *records, int k);

int main() {
    int n = 10;  // Example size for offsets array
    int m = 5;   // Example size for keys array (must be at least half of n)
    int k = 3;   // Number of records
    int low = 1, high = 100;
    int max_linked_list_size = 2;

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    offsets = (long *)malloc(n * sizeof(long));
    if (!offsets) ERROR_MSG("Failed to allocate memory for offsets");

    keys = (int *)malloc(m * sizeof(int));
    if (!keys) {
        free(offsets);
        ERROR_MSG("Failed to allocate memory for keys");
    }

    records = (record *)calloc(k, sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        ERROR_MSG("Failed to allocate memory for records");
    }

    initialize_records(n, m, &records, k, low, high);
    assign_pointers(records, offsets, keys, k, n, m);

    // Example operations on linked lists
    for (int i = 0; i < k; ++i) {
        record *new_node = (record *)malloc(sizeof(record));
        if (!new_node) ERROR_MSG("Failed to allocate memory for new node");
        new_node->value = rand() % 50 + 1; // Random value
        new_node->offset_ptr = NULL;
        new_node->key_ptr = &keys[i % m];  // Example key assignment
        new_node->next_record = NULL;

        insert_into_linked_list(&records[i], new_node, max_linked_list_size);
    }

    traverse_and_operate(records, k);
    garbage_collect(records, k);

    free_memory(offsets, keys, &records, k);

    return 0;
}

void initialize_records(long n, int m, record **records, int k, int low, int high) {
    for (int i = 0; i < k; ++i) {
        (*records)[i].value = rand() % (high - low + 1) + low;
        (*records)[i].offset_ptr = NULL;
        (*records)[i].key_ptr = NULL;
        (*records)[i].next_record = NULL;

        if ((*records)[i].offset_ptr != NULL) {
            ERROR_MSG("Offset pointer not initialized to NULL");
        }
    }
}

void set_random_values(record *records, int k, int low, int high) {
    for (int i = 0; i < k; ++i) {
        records[i].value = rand() % (high - low + 1) + low;
    }
}

void assign_pointers(record *records, long *offsets, int *keys, int k, int n, int m) {
    for (int i = 0; i < k && i < n; ++i) {
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i % m];
    }
}

void free_memory(long *offsets, int *keys, record **records, int k) {
    for (int i = 0; i < k; ++i) {
        while ((*records)[i].next_record != NULL) {
            record *temp = (*records)[i].next_record;
            (*records)[i].next_record = temp->next_record;
            free(temp);
        }
    }
    free(*records);
    free(offsets);
    free(keys);
}

void insert_into_linked_list(record *head, record *new_node, int max_size) {
    if (!*head) {
        *head = new_node;
        return;
    }

    record *current = *head;
    while (current->next_record && current->next_record != head) {
        current = current->next_record;
    }

    if (!current->next_record || max_size <= 1) {
        new_node->next_record = *head;
        current->next_record = new_node;
    }
}

void traverse_and_operate(record *records, int k) {
    for (int i = 0; i < k; ++i) {
        record *current = &records[i];
        do {
            printf("Record value: %d\n", current->value);
            current = current->next_record;
        } while (current && current != &records[i]);
    }
}

void garbage_collect(record *records, int k) {
    for (int i = 0; i < k; ++i) {
        record *current = records[i].next_record;
        while (current && current->next_record) {
            if (!current->value) { // Example condition to free nodes
                record *temp = current;
                current = current->next_record;
                temp->next_record = NULL;
                free(temp);
            } else {
                current = current->next_record;
            }
        }
    }
}
