config_entry* initialize_configurations(size_t count, char **names, int *defaults, bool *actives) {
    config_entry *configs = malloc(sizeof(config_entry) * count);
    if (!configs) return NULL;

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&config_lock);

        configs[i].name = strdup(names[i]);
        configs[i].default_value = defaults[i];
        configs[i].active = actives[i];

        // Validate name
        bool valid_name = false;
        for (int j = 0; j < ALLOWED_NAMES_COUNT; ++j) {
            if (strcmp(configs[i].name, allowed_names[j]) == 0) {
                valid_name = true;
                break;
            }
        }

        // Validate default value and active flag
        if (!valid_name || configs[i].default_value > max_default_value || !configs[i].active) {
            free(config_entry *configs);
            pthread_mutex_unlock(&config_lock);
            return NULL;
        }

        // Initialize current value with a random value within the threshold
        srand(time(NULL));
        int range = (int)(max_default_value * threshold_percentage);
        configs[i].current_value = configs[i].default_value + rand() % (range + 1);

        pthread_mutex_unlock(&config_lock);
    }

    return configs;
}

void free_configurations(config_entry *configs, size_t count) {
    if (!configs) return;

    for (size_t i = 0; i < count; ++i) {
        free(configs[i].name);
    }
    free(configs);
}

int main() {
    // Example usage
    char *config_names[MAX_CONFIGS] = {"setting1", "setting2"};
    int config_defaults[MAX_CONFIGS] = {50, 30};
    bool config_actives[MAX_CONFIGS] = {true, true};

    FILE_SYSTEM_METHOD *method = select_file_system_method(2048, false, 0.3);
    if (method) {
        printf("Selected method: %d\n", method->type);
        free_file_system_method(method);
    }

    config_entry *configs = initialize_configurations(2, config_names, config_defaults, config_actives);
    if (configs) {
        for (int i = 0; i < 2; ++i) {
            printf("Config %s: default=%d, current=%d\n", configs[i].name, configs[i].default_value, configs[i].current_value);
        }
        free_configurations(configs, 2);
    }

    return 0;
}
