}

// Serialize the data into a byte array
int serialize_data(const DataBatch *batch, uint8_t **buffer, size_t *size) {
    size_t header_size = sizeof(VERSION);
    size_t keys_size = sizeof(int) * batch->num_records;
    size_t offsets_size = sizeof(long) * batch->num_records;
    size_t records_size = sizeof(Record) * batch->num_records;

    *size = header_size + keys_size + offsets_size + records_size;
    *buffer = safe_malloc(*size);

    uint8_t *ptr = *buffer;

    // Serialize version
    memcpy(ptr, &VERSION, header_size);
    ptr += header_size;

    // Serialize keys
    for (size_t i = 0; i < batch->num_records; ++i) {
        int net_key = htonl(batch->keys[i]);
        memcpy(ptr, &net_key, sizeof(int));
        ptr += sizeof(int);
    }

    // Serialize offsets
    for (size_t i = 0; i < batch->num_records; ++i) {
        long net_offset = htonll(batch->offsets[i]);
        memcpy(ptr, &net_offset, sizeof(long));
        ptr += sizeof(long);
    }

    // Serialize records
    for (size_t i = 0; i < batch->num_records; ++i) {
        int net_value = htonl(batch->records[i].value);
        long net_record_offset = htonll(batch->records[i].offset);

        memcpy(ptr, &net_value, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &net_record_offset, sizeof(long));
        ptr += sizeof(long);
    }

    return 0;
}

// Convert host byte order to network byte order for long
long htonll(long value) {
    if (__BYTE_ORDER == __BIG_ENDIAN)
        return value;
    int32_t a = (value >> 32) & 0xffffffffL;
    int32_t b = value & 0xffffffffL;
    if (__BYTE_ORDER == __LITTLE_ENDIAN)
        return ((long)(htonl(b)) << 32) | htonl(a);
    else
        abort(); // should not be reached
}

// Compress data using a simple algorithm (e.g., RLE, custom compression, etc.)
