int read_integers_from_stdin(int **array, size_t array_size) {
    *array = safe_malloc(sizeof(int) * array_size);
    for (size_t i = 0; i < array_size; ++i) {
        if (scanf("%d", &(*array)[i]) != 1) {
            fprintf(stderr, "Failed to read integer from stdin\n");
            return -1;
        }
    }
    return 0;
}

// Find the first occurrence of a target integer
int find_first_occurrence(const int *array, size_t size, int target) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] == target) {
            return (int)i;
        }
    }
    return -1;
}

