from abc import ABC, abstractmethod
import zlib
import lzma

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class CompressionAlgorithm(ABC):
    @abstractmethod
    def compress(self, data: bytes) -> bytes:
        pass

    @abstractmethod
    def decompress(self, compressed_data: bytes) -> bytes:
        pass

class LZ77Compression(CompressionAlgorithm):
    def compress(self, data: bytes) -> bytes:
        # Implement LZ77 compression logic here
        return data  # Placeholder for actual implementation

    def decompress(self, compressed_data: bytes) -> bytes:
        # Implement LZ77 decompression logic here
        return compressed_data  # Placeholder for actual implementation

class DEFLATECompression(CompressionAlgorithm):
    def compress(self, data: bytes) -> bytes:
        return zlib.compress(data)

    def decompress(self, compressed_data: bytes) -> bytes:
        return zlib.decompress(compressed_data)

class CompressionManager:
    def __init__(self):
        self.algorithms = {
            'LZ77': LZ77Compression(),
            'DEFLATE': DEFLATECompression(),
            # Add other algorithms like LZ78, LZW
        }

    def select_algorithm(self, data: bytes) -> CompressionAlgorithm:
        # Logic to select the best algorithm based on data characteristics
        return self.algorithms['DEFLATE']  # Default choice

    def compress_data(self, data: bytes) -> bytes:
        try:
            algo = self.select_algorithm(data)
            logger.info("Compressing data using %s", type(algo).__name__)
            return algo.compress(data)
        except Exception as e:
            logger.error("Compression error: %s", str(e))
            # Fallback to a default or secondary algorithm
            return self.algorithms['DEFLATE'].compress(data)

    def decompress_data(self, compressed_data: bytes) -> bytes:
        try:
            algo = self.select_algorithm(compressed_data)
            logger.info("Decompressing data using %s", type(algo).__name__)
            return algo.decompress(compressed_data)
        except Exception as e:
            logger.error("Decompression error: %s", str(e))
            raise

class RecordManager:
    def __init__(self, max_records=10000):
        self.max_records = max_records
        self.records = []
        self.keys = set()

    def generate_records(self, offset_range=(0, 100000), key_range=(1, 5000)):
        for _ in range(self.max_records):
            while True:
                key = random.randint(*key_range)
                if key not in self.keys:
                    break
            value = random.randint(1, 100)
            offset = random.randint(*offset_range)
            record = {'offset': offset, 'key': key, 'value': value}
            self.records.append(record)
            self.keys.add(key)

    def export_to_json(self, file_path):
        try:
            with open(file_path, 'w') as f:
                json.dump(self.records, f)
            logger.info("Exported records to JSON")
        except Exception as e:
            logger.error("Failed to export to JSON: %s", str(e))

    def export_to_csv(self, file_path):
        try:
            with open(file_path, 'w', newline='') as f:
                writer = csv.DictWriter(f, fieldnames=['offset', 'key', 'value'])
                writer.writeheader()
                writer.writerows(self.records)
            logger.info("Exported records to CSV")
        except Exception as e:
            logger.error("Failed to export to CSV: %s", str(e))

def main():
    # Initialize managers
    compression_manager = CompressionManager()
    record_manager = RecordManager()

    # Generate and manage records
    record_manager.generate_records()

    # Export data for analysis
    record_manager.export_to_json('records.json')
    record_manager.export_to_csv('records.csv')

if __name__ == "__main__":
    main()
```

### Key Points:
- **Compression Framework**: Supports multiple compression algorithms with a fallback mechanism.
- **Record Management**: Dynamically generates unique records and exports them in JSON/CSV formats.
- **Logging**: Integrated logging captures operations for performance analysis.
- **Robustness**: Handles errors gracefully, ensuring system stability.']

