    time_t timestamp;
    bool ack;
} Message;

typedef struct {
    Message* messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageArray;

void log_event(const char* level, const char* message) {
    printf("[%s] %s\n", level, message);
}

MessageArray* init_message_array(size_t initial_capacity) {
    MessageArray* array = malloc(sizeof(MessageArray));
    if (!array) {
        log_event("ERROR", "Failed to allocate memory for MessageArray");
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    array->messages = calloc(initial_capacity, sizeof(Message));
    if (!array->messages) {
        free(array);
        log_event("ERROR", "Failed to allocate memory for messages");
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;

    log_event("INFO", "MessageArray initialized successfully");

    // Seed random number generator
    srand((unsigned int)time(NULL));

    return array;
}

bool add_message(MessageArray* array, const char* content, bool ack) {
    pthread_mutex_lock(&array->lock);

    if (sizeof(Message) * (array->count + 1) > MAX_MEMORY) {
        log_event("WARNING", "Memory limit reached. Cannot add more messages.");
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Message* new_messages = realloc(array->messages, new_capacity * sizeof(Message));
        if (!new_messages) {
            log_event("ERROR", "Failed to reallocate memory for messages");
            pthread_mutex_unlock(&array->lock);
            return false;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    Message* msg = &array->messages[array->count++];
    msg->content = strdup(content);
    if (!msg->content) {
        log_event("ERROR", "Failed to allocate memory for message content");
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    msg->timestamp = (time_t)(rand() % 86400); // Random timestamp within a day
    msg->ack = ack;

    pthread_mutex_unlock(&array->lock);

    log_event("INFO", "Message added successfully");

    return true;
}

void serialize_message(const Message* message, uint8_t** buffer, size_t* length) {
    *length = sizeof(message->timestamp) + 1 + strlen(message->content);
    *buffer = malloc(*length);

    if (!*buffer) {
        log_event("ERROR", "Failed to allocate memory for serialization");
        return;
    }

    uint8_t* ptr = *buffer;

    // Serialize timestamp
    memcpy(ptr, &htonl(*(uint32_t*)&message->timestamp), sizeof(message->timestamp));
    ptr += sizeof(message->timestamp);

    // Serialize content length
    *(ptr++) = (uint8_t)strlen(message->content);

    // Serialize content
    memcpy(ptr, message->content, strlen(message->content));

    log_event("INFO", "Message serialized successfully");
}

void deserialize_message(const uint8_t* buffer, size_t length, Message* message) {
    const uint8_t* ptr = buffer;

    // Deserialize timestamp
    memcpy(&message->timestamp, &ntohl(*(uint32_t*)ptr), sizeof(message->timestamp));
    ptr += sizeof(message->timestamp);

    // Deserialize content length
    uint8_t content_length = *(ptr++);

    // Allocate and deserialize content
    message->content = malloc(content_length + 1);
    if (!message->content) {
        log_event("ERROR", "Failed to allocate memory for deserialized content");
        return;
    }

    memcpy(message->content, ptr, content_length);
    message->content[content_length] = '\0';

    log_event("INFO", "Message deserialized successfully");
}

void free_message_array(MessageArray* array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->messages[i].content);
    }

    free(array->messages);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);

    log_event("INFO", "MessageArray freed successfully");
}
```

### Key Points:
- **Memory Management**: The `add_message` function handles dynamic resizing and ensures memory usage does not exceed a predefined limit.
- **Thread Safety**: A mutex is used to ensure thread-safe access to the message array.
- **Serialization/Deserialization**: Messages are serialized into a compact binary format, considering endianness for cross-platform compatibility.
- **Logging**: Simple logging captures events at different verbosity levels.
- **Error Handling**: Graceful handling of memory allocation failures and other potential errors.

This implementation is modular and can be extended or modified to meet future requirements.']

