['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    long *offset_ptr;
    int key;
    struct record *next; // Pointer to form a linked list of records
} record;

// Function prototypes
void initialize_records(int k, int low, int high, long *offsets, int n);
void free_memory(long *offsets, record *records[], int k);
record* create_record_node(int value, int key, long offset_value, long *offsets, int n);
void insert_into_linked_list(record *head, record *new_node, int max_size);
void delete_from_linked_list(record **head, int key, int max_size);
void garbage_collect(records *, int k);

// Function to manage memory for multiple interconnected data structures
void manage_memory(int n, int m, int k, int low, int high, int max_linked_list_size) {
    if (m < n / 2) {
        printf("Error: 'm' must be at least half of 'n'.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offset values
    long *offsets = malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for keys
    int *keys = malloc(m * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize arrays with random values within the range [low, high]
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        offsets[i] = rand() % (high - low + 1) + low;
    }
    for (int i = 0; i < m; ++i) {
        keys[i] = rand() % (high - low + 1) + low;
    }

    // Allocate and initialize records
    record **records = malloc(k * sizeof(record *));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }
    initialize_records(k, low, high, offsets, n);

    // Assign long pointers to corresponding offset values
    for (int i = 0; i < k && i < n; ++i) {
        records[i]->offset_ptr = &offsets[i];
    }

    // Example operations: Insert and delete nodes in linked lists
    for (int i = 0; i < k; ++i) {
        if (records[i]) {
            record *new_node = create_record_node(rand() % (high - low + 1) + low, keys[i % m], offsets[i % n], offsets, n);
            insert_into_linked_list(records[i], new_node, max_linked_list_size);
            delete_from_linked_list(&records[i], records[i]->key, max_linked_list_size);
        }
    }

    // Perform garbage collection
    for (int i = 0; i < k; ++i) {
        if (records[i]) {
            garbage_collect(records + i, max_linked_list_size);
        }
    }

    // Free all allocated memory
    free_memory(offsets, records, k);
}

// Function to initialize records with random values and NULL long pointers
void initialize_records(int k, int low, int high, long *offsets, int n) {
    for (int i = 0; i < k; ++i) {
        record *rec = malloc(sizeof(record));
        if (!rec) {
            fprintf(stderr, "Memory allocation failed for record.\n");
            exit(EXIT_FAILURE);
        }
        rec->value = rand() % (high - low + 1) + low;
        rec->offset_ptr = NULL;
        rec->key = i; // Example key assignment
        rec->next = NULL;
    }
}

// Function to create a new record node
record* create_record_node(int value, int key, long offset_value, long *offsets, int n) {
    record *new_node = malloc(sizeof(record));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new record node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->value = value;
    new_node->key = key;
    new_node->offset_ptr = &offset_value;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a new node into the linked list
void insert_into_linked_list(record *head, record *new_node, int max_size) {
    if (!head || !new_node) return;

    record *current = head;
    while (current->next && current->next != head) { // Circular linked list check
        current = current->next;
    }
    if (!current->next || (max_size > 0 && count_nodes(head, max_size - 1) < max_size)) {
        current->next = new_node;
    } else {
        free(new_node);
    }
}

// Function to delete a node from the linked list by key
void delete_from_linked_list(record **head, int key, int max_size) {
    if (!head || !*head) return;

    record *current = *head;
    record *prev = NULL;

    while (current && current->key != key) {
        prev = current;
        current = current->next;
        if (current == *head) break; // Circular linked list check
    }

    if (current) {
        if (prev) {
            prev->next = current->next;
        } else { // Deleting head
            record *last = *head;
            while (last->next != *head) last = last->next;
            if ((*head)->next == *head) {
                free(*head);
                *head = NULL;
            } else {
                last->next = (*head)->next;
                free(*head);
                *head = current->next;
            }
        }
        free(current);

        // If max_size is enforced, remove the oldest node if exceeded
        if (max_size > 0) {
            int count = count_nodes(*head, max_size - 1);
            if (count > max_size) {
                record *to_delete = *head;
                for (int i = 0; i < max_size - 1; ++i) {
                    to_delete = to_delete->next;
                }
                delete_from_linked_list(&(*head), to_delete->key, max_size);
            }
        }
    }
}

// Function to count nodes in the linked list up to a certain limit
int count_nodes(record *head, int limit) {
    if (!head) return 0;

    int count = 1;
    record *current = head->next;
    while (current && current != head && count < limit) {
        ++count;
        current = current->next;
    }
    return count;
}

// Function to perform garbage collection
void garbage_collect(record **head, int max_size) {
    if (!head || !*head) return;

    record *current = *head;
    while (current && current != *head) {
        if (max_size > 0 && count_nodes(*head, max_size - 1) > max_size) {
            delete_from_linked_list(head, current->key, max_size);
        }
        current = current->next;
    }
}

// Function to free all allocated memory
void free_memory(long *offsets, record **records, int k) {
    free(offsets);

    for (int i = 0; i < k; ++i) {
        if (records[i]) {
            record *current = records[i];
            while (current && current != records[i]) {
                record *next = current->next;
                free(current);
                current = next;
            }
            free(records[i]);
        }
    }

    free(records);
}
