        case PROTOCOL_HTTP_1_1: return 2048;
        case PROTOCOL_WEBSOCKET: return 4096;
        case PROTOCOL_MQTT: return 256;
        default: return 0;
    }
}

// Function to select the protocol dynamically
ProtocolType select_protocol(Message *message) {
    int network_conditions = get_network_conditions();

    if (network_conditions < 50 && message->size <= get_message_size_threshold(PROTOCOL_TCP)) {
        return PROTOCOL_TCP;
    } else if (network_conditions >= 50 && message->size <= get_message_size_threshold(PROTOCOL_UDP)) {
        return PROTOCOL_UDP;
    } else if (message->priority > 5) {
        return PROTOCOL_WEBSOCKET; // Prioritize low latency
    }

    // Default or fallback protocol
    return message->preferred_protocol;
}

// Function to send a message with retry mechanism
