int offsets_capacity = 0, keys_capacity = 0;
long *offsets = NULL;
int *keys = NULL;
record **records = NULL;
size_t num_records = 0;
size_t records_capacity = 0;

// Utility functions
void handle_memory_error(void *ptr) {
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

long lrand_range(long min, long max) {
    return rand() % (max - min + 1) + min;
}

double gaussian_random(double mean, double stddev) {
    static const double epsilon = 1e-10;
    static double z0, z1;
    static int use_last = 0;

    if (use_last) {
        use_last = 0;
        return z1 * stddev + mean;
    }

    do {
        double u1 = (double)rand() / RAND_MAX;
        double u2 = (double)rand() / RAND_MAX;

        z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
        z1 = sqrt(-2.0 * log(u1)) * sin(2.0 * M_PI * u2);
    } while (z0 == 0);

    use_last = 1;

    return z0 * stddev + mean;
}

void resize_offsets(long new_capacity) {
    long *new_offsets = realloc(offsets, new_capacity * sizeof(long));
    handle_memory_error(new_offsets);
    offsets = new_offsets;
    offsets_capacity = new_capacity;
}

void resize_keys(int new_capacity) {
    int *new_keys = realloc(keys, new_capacity * sizeof(int));
    handle_memory_error(new_keys);
    keys = new_keys;
    keys_capacity = new_capacity;
}

void resize_records(size_t new_capacity) {
    record **new_records = realloc(records, new_capacity * sizeof(record *));
    handle_memory_error(new_records);
    records = new_records;
    records_capacity = new_capacity;
}

int check_for_duplicates(long timestamp, long *offsets, size_t num_offsets) {
    for (size_t i = 0; i < num_offsets; ++i) {
        if (offsets[i] == timestamp) return 1;
    }
    return 0;
}

void add_sensor_data(sensor_data **sensor_array, size_t *array_size, size_t *capacity,
                     long timestamp, double sensor_reading, const char *device_type, int location_id) {
    if (*array_size >= *capacity) {
        size_t new_capacity = (*capacity == 0) ? INITIAL_CAPACITY : *capacity * 2;
        sensor_data *new_sensor_array = realloc(*sensor_array, new_capacity * sizeof(sensor_data));
        handle_memory_error(new_sensor_array);
        *sensor_array = new_sensor_array;
        *capacity = new_capacity;
    }
    sensor_data *data = &(*sensor_array)[*array_size];
    data->timestamp = timestamp;
    data->sensor_reading = sensor_reading;
    strncpy(data->device_type, device_type, sizeof(data->device_type) - 1);
    data->location_id = location_id;
    (*array_size)++;
}

void process_batch(sensor_data **sensor_array, size_t *num_records,
                   record ***records_array, long batch_start_timestamp,
                   int min_record_value, int max_record_value, double stddev) {
    if (num_records + MAX_BATCH_SIZE > records_capacity) {
        resize_records(records_capacity == 0 ? MAX_BATCH_SIZE : records_capacity * 2);
    }

    for (size_t i = 0; i < MAX_BATCH_SIZE && (*num_records < num_records); ++i) {
        long timestamp = batch_start_timestamp + lrand_range(1, 1000);
        if (!check_for_duplicates(timestamp, offsets, *num_records)) {
            double sensor_reading = gaussian_random(50.0, stddev);

            add_sensor_data(sensor_array, &(*num_records), &(records_capacity),
                            timestamp, sensor_reading, "sensorX", lrand_range(1, 100));

            record *rec = malloc(sizeof(record));
            handle_memory_error(rec);
            rec->value = lrand_range(min_record_value, max_record_value);

            (*records_array)[*num_records] = rec;
            offsets[(*num_records)++] = timestamp;
        }
    }

    keys[(*num_records)-1] = *num_records - 1; // Example: mapping last processed record's index.
}

void serialize_data(sensor_data **sensor_array, size_t num_entries,
                    uint8_t **serialized_data, size_t *data_size) {
    *data_size = num_entries * sizeof(sensor_data);
    *serialized_data = malloc(*data_size);
    handle_memory_error(*serialized_data);

    memcpy(*serialized_data, *sensor_array, *data_size);
}

// Example main function
int main() {
    srand((unsigned int)time(NULL));

    size_t sensor_capacity = 0;
    size_t num_sensor_entries = 0;
    sensor_data *sensors = NULL;

    long initial_timestamp = time(NULL);

    offsets = malloc(INITIAL_CAPACITY * sizeof(long));
    keys = malloc(INITIAL_CAPACITY * sizeof(int));
    handle_memory_error(offsets);
    handle_memory_error(keys);

    records_capacity = INITIAL_CAPACITY;
