    if (current_time - rate_limit->last_reset_time > TIME_WINDOW_SECONDS) {
        pthread_mutex_lock(&lock);
        rate_limit->last_reset_time = current_time;
        rate_limit->request_count = 0;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_lock(&lock);
    unsigned long count = ++rate_limit->request_count;
    int is_limited = (count > RATE_LIMIT_MAX_REQUESTS);
    pthread_mutex_unlock(&lock);

    if (is_limited) {
        printf("Rate limit exceeded for user %d\n", user_id);
    }

    return is_limited;
}

