typedef enum {
    SENSOR_TEMPERATURE,
    SENSOR_HUMIDITY,
    SENSOR_PRESSURE,
    // Add more categories as needed
} Category;

typedef struct {
    time_t timestamp;
    Category category;
    double value;
} DataPoint;

// Thread-safe mutex for memory management
static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;

int is_valid_category(Category category) {
    switch (category) {
        case SENSOR_TEMPERATURE:
        case SENSOR_HUMIDITY:
        case SENSOR_PRESSURE:
            return 1;
        default:
            return 0;
    }
}

DataPoint* initialize_data_points(size_t number_of_points, double min_value, double max_value, time_t start_date, Category (*get_category)(size_t), double (*generate_value)(double, double)) {
    pthread_mutex_lock(&data_mutex);

    DataPoint *points = (DataPoint *)malloc(number_of_points * sizeof(DataPoint));
    if (!points) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&data_mutex);
        return NULL;
    }

    for (size_t i = 0; i < number_of_points; ++i) {
        points[i].timestamp = start_date + i;

        Category category = get_category(i);
        if (!is_valid_category(category)) {
            printf("Invalid category at index %zu\n", i);
            free(points);
            pthread_mutex_unlock(&data_mutex);
            return NULL;
        }
        points[i].category = category;

        points[i].value = generate_value(min_value, max_value);
    }

    pthread_mutex_unlock(&data_mutex);
    return points;
}

void cleanup_data_points(DataPoint *points) {
    if (points) {
        free(points);
    }
}
