    *buffer = malloc(count * sizeof(sensor_data));
    if (!(*buffer)) {
        perror("Serialization memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; ++i) {
        memcpy(&((*buffer)[i * sizeof(sensor_data)]), &data_array[i], sizeof(sensor_data));
    }

