#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct TreeNode {
    int value;
    struct TreeNode *left;
    struct TreeNode *right;
    struct TreeNode *parent;
    int num_children;
    time_t last_modified; // Timestamp for metadata
} TreeNode;

// Function to allocate memory for an array of TreeNodes
TreeNode* allocateTreeNodes(int n) {
    if (n <= 0) {
        fprintf(stderr, "Invalid number of nodes.\n");
        exit(EXIT_FAILURE);
    }

    TreeNode *nodes = malloc(n * sizeof(TreeNode));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for tree nodes.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each node
    for (int i = 0; i < n; ++i) {
        nodes[i].value = -1;
        nodes[i].left = NULL;
        nodes[i].right = NULL;
        nodes[i].parent = NULL;
        nodes[i].num_children = 0;
        nodes[i].last_modified = time(NULL);
    }

    return nodes;
}

// Function to verify all pointers are initialized to NULL
void verifyNodePointers(TreeNode *nodes, int n) {
    for (int i = 0; i < n; ++i) {
        if (nodes[i].left || nodes[i].right || nodes[i].parent) {
            fprintf(stderr, "Pointer not initialized correctly for node %d.\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to insert a new TreeNode into the BST
TreeNode* insertNode(TreeNode *root, int value) {
    if (!root) return NULL;

    TreeNode *new_node = malloc(sizeof(TreeNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        exit(EXIT_FAILURE);
    }

    new_node->value = value;
    new_node->left = new_node->right = new_node->parent = NULL;
    new_node->num_children = 0;
    new_node->last_modified = time(NULL);

    TreeNode *current = root, *parent = NULL;
    while (current) {
        parent = current;
        if (value < current->value)
            current = current->left;
        else
            current = current->right;
    }

    new_node->parent = parent;
    if (!parent) {
        // This means the tree was empty, and new_node is now root.
        return new_node;
    }

    if (value < parent->value)
        parent->left = new_node;
    else
        parent->right = new_node;

    if (new_node->left || new_node->right) {
        ++parent->num_children;
    }

    // Update last_modified timestamp for the parent node
    parent->last_modified = time(NULL);

    return root; // Return the root of the tree
}

// Function to delete a TreeNode from the BST
TreeNode* deleteNode(TreeNode *root, int value) {
    if (!root) return NULL;

    TreeNode *current = root;
    while (current && current->value != value) {
        if (value < current->value)
            current = current->left;
        else
            current = current->right;
    }

    if (!current) return root; // Node not found

    TreeNode *parent = current->parent;

    if (!current->left && !current->right) { // Leaf node
        if (current == root) {
            free(current);
            return NULL;
        }
        if (current == parent->left)
            parent->left = NULL;
        else
            parent->right = NULL;
    } else if (current->left || current->right) { // Node with one or two children

        TreeNode *child;
        if (!current->left) {
            child = current->right;
        } else if (!current->right) {
            child = current->left;
        } else { // Two children
            TreeNode *successor_parent = current;
            TreeNode *successor = current->right;

            while (successor->left) {
                successor_parent = successor;
                successor = successor->left;
            }

            if (successor != current->right) {
                successor_parent->left = successor->right;
                if (successor->right)
                    successor->right->parent = successor_parent;
                successor->right = current->right;
                current->right->parent = successor;
            }
            child = successor;
            child->left = current->left;
            current->left->parent = child;
        }

        if (current == root) {
            free(current);
            return child; // Child becomes new root
        }

        if (current == parent->left)
            parent->left = child;
        else
            parent->right = child;

        child->parent = parent;
    } else { // Node with two children handled in above logic
        return root;
    }

    free(current);
    --(parent->num_children);

    // Update last_modified timestamp for the parent node
    if (parent) {
        parent->last_modified = time(NULL);
    }

    return root;
}

// Helper function to perform inorder traversal and store results in a string
void inorderTraversal(TreeNode *root, char **result) {
    static int index = 0;

    if (!root) return;

    inorderTraversal(root->left, result);

    if (index > 0) 
        (*result)[index++] = ' ';

    asprintf(&(*result), "%s%d", *result, root->value);
    ++index;

    inorderTraversal(root->right, result);
}

// Helper function to perform level-order traversal and store results in a list
void* levelOrderTraversal(TreeNode *root) {
    if (!root) return NULL;

    int capacity = 10;
    void **queue = malloc(capacity * sizeof(void *));
    int front = 0, rear = 0;

    queue[rear++] = root;
    while (front < rear) {
        TreeNode *node = (TreeNode *)queue[front++];

        if (!node->left && !node->right && front == rear) 
            break; // Last node reached

        if (node->left)
            queue[(rear++) % capacity] = node->left;
        else
            queue[(rear++) % capacity] = NULL;

        if (node->right)
            queue[(rear++) % capacity] = node->right;
        else
            queue[(rear++) % capacity] = NULL;

        // Resize the queue dynamically if needed
        if (rear == capacity) {
            capacity *= 2;
            queue = realloc(queue, capacity * sizeof(void *));
        }
    }

    return queue; 
}

// Example of usage:
int main() {
    int n = 10;
    TreeNode *nodes = allocateTreeNodes(n);
    verifyNodePointers(nodes, n);

    TreeNode *root = nodes;
    root->value = 5;

    insertNode(root, 3);
    insertNode(root, 7);
    insertNode(root, 2);
    insertNode(root, 4);

    char *inorder_result = NULL;
    inorderTraversal(root, &inorder_result);
    printf("Inorder: %s\n", inorder_result);
    free(inorder_result);

    void *level_order_list = levelOrderTraversal(root);
    // Process or print the level order list

    deleteNode(root, 3);

    return 0;
}
