```cpp
#include <iostream>
#include <vector>
#include <random>
#include <ctime>
#include <cstring>
#include <stdexcept>
#include <sstream>

class DynamicMemoryManager {
public:
    struct Record {
        int value;
        long offset;
    };

private:
    std::vector<Record> records;
    int minRange, maxRange;
    size_t maxSizeBytes;
    unsigned char* memoryBuffer;

public:
    DynamicMemoryManager(int minRange, int maxRange, size_t maxSizeBytes)
        : minRange(minRange), maxRange(maxRange), maxSizeBytes(maxSizeBytes), memoryBuffer(nullptr) {
        if (minRange > maxRange || maxSizeBytes <= 0) {
            throw std::invalid_argument("Invalid range or maximum size.");
        }
    }

    ~DynamicMemoryManager() {
        freeAll();
    }

    void initializeRecords(size_t numRecords) {
        if (numRecords <= 0) return;

        size_t recordSize = sizeof(Record);
        size_t totalSize = numRecords * recordSize;

        if (totalSize > maxSizeBytes) throw std::overflow_error("Exceeds maximum memory size.");

        records.resize(numRecords);
        memoryBuffer = new (std::nothrow) unsigned char[totalSize];
        if (!memoryBuffer) throw std::bad_alloc();

        srand(static_cast<unsigned>(time(nullptr)));
        for (auto& record : records) {
            record.value = generateRandomInt(minRange, maxRange);
            record.offset = static_cast<long>(rand());
            memcpy(memoryBuffer + (&record - &records[0]) * recordSize,
                   &record, sizeof(Record));
        }
    }

    int generateRandomInt(int min, int max) const {
        if (min > max) return 0;
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(min, max);
        return dis(gen);
    }

    float generateRandomFloat(float min, float max) const {
        if (min > max) return 0.0f;
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(min, max);
        return dis(gen);
    }

    void serializeData(unsigned char* buffer, size_t bufferSize) const {
        if (!buffer || bufferSize < records.size() * sizeof(Record)) {
            throw std::invalid_argument("Invalid buffer or size.");
        }
        memcpy(buffer, memoryBuffer, records.size() * sizeof(Record));
    }

    void deserializeData(const unsigned char* buffer, size_t bufferSize) {
        if (!buffer || bufferSize != records.size() * sizeof(Record)) {
            throw std::invalid_argument("Invalid buffer or size.");
        }
        memcpy(memoryBuffer, buffer, bufferSize);
    }

    void freeAll() {
        delete[] memoryBuffer;
        memoryBuffer = nullptr;
        records.clear();
    }

    std::string toString() const {
        std::ostringstream oss;
        oss << "DynamicMemoryManager(minRange=" << minRange
            << ", maxRange=" << maxRange << ")";
        return oss.str();
    }
};

