['```cpp
#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <cstring>
#include <stdexcept>
#include <ctime>

class DynamicMemoryManager {
private:
    struct Record {
        int randomInt;
        long offset;

        void serialize(char* buffer) const {
            std::memcpy(buffer, &randomInt, sizeof(randomInt));
            std::memcpy(buffer + sizeof(randomInt), &offset, sizeof(offset));
        }

        static Record deserialize(const char* buffer) {
            Record record;
            std::memcpy(&record.randomInt, buffer, sizeof(record.randomInt));
            std::memcpy(&record.offset, buffer + sizeof(record.randomInt), sizeof(record.offset));
            return record;
        }
    };

    int minRange, maxRange;
    size_t memoryLimit;
    std::vector<char> memoryPool;
    std::mutex mtx;
    std::default_random_engine rng;

public:
    DynamicMemoryManager(int minRange, int maxRange, size_t memoryLimit)
        : minRange(minRange), maxRange(maxRange), memoryLimit(memoryLimit) {
        std::time_t currentTime = std::time(nullptr);
        rng.seed(static_cast<unsigned>(currentTime));
    }

    Record* allocateRecord() {
        std::lock_guard<std::mutex> lock(mtx);

        size_t recordSize = sizeof(Record::randomInt) + sizeof(Record::offset);
        if (memoryPool.size() + recordSize > memoryLimit) {
            throw std::runtime_error("Memory limit exceeded");
        }

        char* buffer = &memoryPool[memoryPool.size()];
        memoryPool.resize(memoryPool.size() + recordSize);

        Record& record = *reinterpret_cast<Record*>(buffer);
        std::uniform_int_distribution<int> dist(minRange, maxRange);
        record.randomInt = dist(rng);
        record.offset = static_cast<long>(rng());

        return &record;
    }

    void serialize(char* buffer) const {
        std::lock_guard<std::mutex> lock(mtx);

        if (memoryPool.size() != 0 && buffer == nullptr) {
            throw std::invalid_argument("Buffer must not be null");
        }

        size_t serializedSize = memoryPool.size();
        std::memcpy(buffer, memoryPool.data(), serializedSize);
    }

    void deserialize(const char* buffer, size_t bufferSize) {
        std::lock_guard<std::mutex> lock(mtx);

        if (buffer == nullptr || bufferSize != memoryPool.size()) {
            throw std::invalid_argument("Invalid buffer or size");
        }

        std::memcpy(memoryPool.data(), buffer, bufferSize);
    }

    void freeAll() {
        std::lock_guard<std::mutex> lock(mtx);
        memoryPool.clear();
    }

    std::vector<int> generateRandomIntegers(size_t n, int min, int max) const {
        if (n <= 0 || min > max) return {};

        std::vector<int> integers(n);
        std::uniform_int_distribution<int> dist(min, max);

        for (size_t i = 0; i < n; ++i) {
            integers[i] = dist(rng);
        }

        return integers;
    }

    std::vector<float> generateRandomFloats(size_t n, float min, float max) const {
        if (n <= 0 || min > max) return {};

        std::vector<float> floats(n);
        std::uniform_real_distribution<float> dist(min, max);

        for (size_t i = 0; i < n; ++i) {
            floats[i] = dist(rng);
        }

        return floats;
    }

    void toString() const {
        std::cout << "Range: [" << minRange << ", " << maxRange
                  << "] Memory Limit: " << memoryLimit << " bytes\n";
    }
};
```

This implementation of `DynamicMemoryManager` provides a thread-safe, memory-efficient way to manage and serialize records containing random integers and offsets. It supports concurrent access with mutex protection, efficient allocation using a dynamic vector as the pool, and serialization/deserialization mechanisms considering endianness by directly managing byte arrays. The class also includes error handling for invalid inputs and resource management functions like `freeAll`.']

