#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

typedef struct {
    int value;
    long offset;
    uint32_t checksum;
} record;

uint32_t compute_checksum(record *r) {
    return (uint32_t)(r->value + r->offset);
}

int serialize_data(const record *records, const size_t count, unsigned char **out_buffer, size_t *out_size) {
    // Calculate the size needed for serialization
    size_t total_size = sizeof(size_t);  // For storing the number of records
    total_size += count * (sizeof(int) + sizeof(long) + sizeof(uint32_t));

    *out_buffer = malloc(total_size);
    if (*out_buffer == NULL) {
        return -1;  // Memory allocation failed
    }

    unsigned char *ptr = *out_buffer;
    memcpy(ptr, &count, sizeof(size_t)); 
    ptr += sizeof(size_t);

    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &(records[i].value), sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &(records[i].offset), sizeof(long));
        ptr += sizeof(long);
        memcpy(ptr, &(records[i].checksum), sizeof(uint32_t));
        ptr += sizeof(uint32_t);
    }

    *out_size = total_size;
    return 0; // Success
}

int deserialize_data(const unsigned char *in_buffer, size_t in_size, record **out_records, size_t *out_count) {
    if (in_size < sizeof(size_t)) {
        return -1;  // Invalid input data
    }

    const unsigned char *ptr = in_buffer;
    memcpy(out_count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if (*out_count == 0 || in_size != (*out_count) * (sizeof(int) + sizeof(long) + sizeof(uint32_t)) + sizeof(size_t)) {
        return -1;  // Invalid record count or size mismatch
    }

    *out_records = malloc(*out_count * sizeof(record));
    if (*out_records == NULL) {
        return -2;  // Memory allocation failed
    }

    for (size_t i = 0; i < *out_count; ++i) {
        memcpy(&((*out_records)[i].value), ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&((*out_records)[i].offset), ptr, sizeof(long));
        ptr += sizeof(long);
        memcpy(&((*out_records)[i].checksum), ptr, sizeof(uint32_t));
        ptr += sizeof(uint32_t);

        if ((*out_records)[i].checksum != compute_checksum(&((*out_records)[i]))) {
            free(*out_records);
            return -3;  // Checksum mismatch
        }
    }

    return 0; // Success
}

void log_message(const char *message) {
    printf("Log: %s\n", message);
}

int initialize_arrays(size_t max_size, size_t record_count, int min_val, int max_val,
                      long **offset_array, int **key_array, record ***record_array, uint32_t **checksum_array) {

    if (max_size < (record_count * (sizeof(long) + sizeof(int) + sizeof(record) + sizeof(uint32_t)))) {
        log_message("Insufficient memory available.");
        return -1;  // Not enough space
    }

    srand(time(NULL));

    *offset_array = malloc(record_count * sizeof(long));
    if (*offset_array == NULL) { 
        log_message("Failed to allocate memory for offset array."); 
        return -2;
    }

    *key_array = malloc(record_count * sizeof(int));
    if (*key_array == NULL) {
        free(*offset_array);
        log_message("Failed to allocate memory for key array.");
        return -3;
    }

    *record_array = malloc(record_count * sizeof(record));
    if (*record_array == NULL) {
        free(*offset_array);
        free(*key_array);
        log_message("Failed to allocate memory for record array.");
        return -4;
    }

    *checksum_array = malloc(record_count * sizeof(uint32_t));
    if (*checksum_array == NULL) {
        free(*offset_array);
        free(*key_array);
        free(*record_array);
        log_message("Failed to allocate memory for checksum array.");
        return -5;
    }

    for (size_t i = 0; i < record_count; ++i) {
        (*offset_array)[i] = rand() % 1000000L;
        (*key_array)[i] = (rand() % (max_val - min_val + 1)) + min_val;

        (*record_array)[i].value = (*key_array)[i];
        (*record_array)[i].offset = (*offset_array)[i];
        (*record_array)[i].checksum = compute_checksum(&((*record_array)[i]));

        (*checksum_array)[i] = (*record_array)[i].checksum;
    }

    return 0; // Success
}

void free_memory(long *offset_array, int *key_array, record **record_array, uint32_t *checksum_array) {
    if (offset_array != NULL) free(offset_array);
    if (key_array != NULL) free(key_array);
    if (record_array != NULL && *record_array != NULL) free(*record_array);
    if (checksum_array != NULL) free(checksum_array);
}
