#include <stdexcept>

#ifdef __linux__
#include <unistd.h>
#endif

class NetworkResourcePool {
public:
    struct Resource {
        int socketDescriptor;
        std::chrono::time_point<std::chrono::steady_clock> lastAccessed;
        unsigned int timeout;
    };

private:
    std::vector<Resource> resources;
    size_t maxConnections;
    unsigned int defaultTimeout;
    mutable std::mutex poolMutex;

public:
    NetworkResourcePool(size_t maxConnections, unsigned int defaultTimeout)
        : maxConnections(maxConnections), defaultTimeout(defaultTimeout) {
        seedRandomGenerator();
        initializeResources();
    }

    void seedRandomGenerator() {
#ifdef __linux__
        pid_t pid = getpid();
        std::hash<std::string> hasher;
        auto hashValue = hasher(std::to_string(pid) + std::to_string(std::this_thread::get_id()));
#else
        unsigned int seed = static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count());
        std::mt19937_64 generator(seed);
#endif
    }

    void initializeResources() {
        resources.reserve(maxConnections);
        for (size_t i = 0; i < maxConnections; ++i) {
            Resource resource{ -1, std::chrono::steady_clock::now(), defaultTimeout };
            resources.push_back(resource);
        }
    }

    bool acquireResource(int& socketDescriptor) {
        std::unique_lock<std::mutex> lock(poolMutex);

        for (auto& resource : resources) {
            if (resource.socketDescriptor == -1) {
                // Simulate socket descriptor allocation
                resource.socketDescriptor = static_cast<int>(std::rand() % 1000);
                resource.lastAccessed = std::chrono::steady_clock::now();
                return true;
            }
        }

        return false; // No available resources
    }

    void releaseResource(int socketDescriptor) {
        std::unique_lock<std::mutex> lock(poolMutex);

        for (auto& resource : resources) {
            if (resource.socketDescriptor == socketDescriptor) {
                resource.socketDescriptor = -1;
                return;
            }
        }

        throw std::runtime_error("Invalid socket descriptor");
    }

    void serializeState(std::ostream& out) const {
        std::unique_lock<std::mutex> lock(poolMutex);

        size_t resourcesCount = resources.size();
        out.write(reinterpret_cast<const char*>(&resourcesCount), sizeof(resourcesCount));

        for (const auto& resource : resources) {
            int socketDescriptor = resource.socketDescriptor;
            unsigned long long lastAccessed = resource.lastAccessed.time_since_epoch().count();
            unsigned int timeout = resource.timeout;

            out.write(reinterpret_cast<const char*>(&socketDescriptor), sizeof(socketDescriptor));
            out.write(reinterpret_cast<const char*>(&lastAccessed), sizeof(lastAccessed));
            out.write(reinterpret_cast<const char*>(&timeout), sizeof(timeout));
        }
    }

    void deserializeState(std::istream& in) {
        std::unique_lock<std::mutex> lock(poolMutex);

        size_t resourcesCount;
        in.read(reinterpret_cast<char*>(&resourcesCount), sizeof(resourcesCount));

        resources.clear();
        for (size_t i = 0; i < resourcesCount; ++i) {
            int socketDescriptor;
            unsigned long long lastAccessed;
            unsigned int timeout;

            in.read(reinterpret_cast<char*>(&socketDescriptor), sizeof(socketDescriptor));
            in.read(reinterpret_cast<char*>(&lastAccessed), sizeof(lastAccessed));
            in.read(reinterpret_cast<char*>(&timeout), sizeof(timeout));

            Resource resource{ socketDescriptor, std::chrono::steady_clock::time_point(std::chrono::milliseconds(lastAccessed)), timeout };
            resources.push_back(resource);
        }
    }

    int generateRandomInt(int min, int max) {
        if (min > max) throw std::invalid_argument("Invalid range");

        std::uniform_int_distribution<> distribution(min, max);
        return distribution(seedRandomGenerator());
    }

    double generateRandomDouble(double min, double max, bool inclusive = true) {
        if (min > max) throw std::invalid_argument("Invalid range");

        std::uniform_real_distribution<> distribution(inclusive ? min : min + 1e-9, inclusive ? max - 1e-9 : max);
        return distribution(seedRandomGenerator());
    }

    std::string toString() const {
        std::unique_lock<std::mutex> lock(poolMutex);
        std::ostringstream oss;
        oss << "NetworkResourcePool: MaxConnections = " << maxConnections
            << ", DefaultTimeout = " << defaultTimeout;
        return oss.str();
    }

private:
    std::mt19937_64 seedRandomGenerator() {
#ifdef __linux__
        pid_t pid = getpid();
        std::hash<std::string> hasher;
        auto hashValue = hasher(std::to_string(pid) + std::to_string(std::this_thread::get_id()));
        return std::mt19937_64(hashValue);
#else
        unsigned int seed = static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count());
        return std::mt19937_64(seed);
#endif
    }
};

// Placeholder function for creating an HTTP client in Rust
extern "C" void createHttpClient() {
    // Implement Rust FFI call here to create an HTTP client.
}

