#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structures
struct item {
    char *buffer;
    int index;
};

struct config {
    float threshold;
    char *name;
};

struct log_entry {
    time_t timestamp;
    char *message;
};

// Logging mechanism
void log_event(const char *event) {
    printf("Log: %s\n", event);
}

// Function to manage dynamic memory allocation and deallocation
void manage_memory(int num_items, int num_configs) {
    struct item **items = NULL;
    struct config *configs = NULL;
    struct log_entry **log_entries = NULL;

    // Allocate memory for items array
    items = (struct item **)malloc(num_items * sizeof(struct item *));
    if (!items) { 
        perror("Failed to allocate memory for items");
        return; 
    }
    log_event("Allocated memory for items");

    // Initialize and allocate individual items
    for (int i = 0; i < num_items; ++i) {
        items[i] = (struct item *)malloc(sizeof(struct item));
        if (!items[i]) { 
            perror("Failed to allocate memory for an item");
            break;
        }
        items[i]->buffer = strdup("dummy_buffer");
        if (!items[i]->buffer) { 
            perror("Failed to duplicate string for buffer");
            free(items[i]);
            continue;
        }
        items[i]->index = i;
        log_event("Initialized and allocated memory for an item");
    }

    // Allocate memory for configs array
    configs = (struct config *)malloc(num_configs * sizeof(struct config));
    if (!configs) { 
        perror("Failed to allocate memory for configs");
        goto cleanup_items; 
    }
    log_event("Allocated memory for configs");

    // Initialize and allocate individual configs
    for (int i = 0; i < num_configs; ++i) {
        configs[i].threshold = (float)i * 1.5;
        configs[i].name = strdup("config_name");
        if (!configs[i].name) { 
            perror("Failed to duplicate string for config name");
            break;
        }
        log_event("Initialized and allocated memory for a config");
    }

    // Allocate memory for log_entries array
    log_entries = (struct log_entry **)malloc(num_items * sizeof(struct log_entry *));
    if (!log_entries) { 
        perror("Failed to allocate memory for log entries");
        goto cleanup_configs;
    }
    log_event("Allocated memory for log entries");

    // Initialize and allocate individual log entries
    time_t current_time = time(NULL);
    for (int i = 0; i < num_items; ++i) {
        log_entries[i] = (struct log_entry *)malloc(sizeof(struct log_entry));
        if (!log_entries[i]) { 
            perror("Failed to allocate memory for a log entry");
            break;
        }
        log_entries[i]->timestamp = current_time + i;
        char msg[50];
        snprintf(msg, sizeof(msg), "Log message %d", i);
        log_entries[i]->message = strdup(msg);
        if (!log_entries[i]->message) { 
            perror("Failed to duplicate string for log message");
            free(log_entries[i]);
            continue;
        }
        log_event("Initialized and allocated memory for a log entry");
    }

cleanup_configs:
    // Free configs array
    for (int i = 0; i < num_configs; ++i) {
        if (configs && configs[i].name) {
            free(configs[i].name);
        }
    }
    free(configs);
    log_event("Deallocated memory for configs");

cleanup_items:
    // Free items array
    for (int i = 0; i < num_items; ++i) {
        if (items && items[i]) {
            free(items[i]->buffer);
            free(items[i]);
        }
    }
    free(items);
    log_event("Deallocated memory for items");

    // Free log_entries array
    for (int i = 0; i < num_items; ++i) {
        if (log_entries && log_entries[i]) {
            free(log_entries[i]->message);
            free(log_entries[i]);
        }
    }
    free(log_entries);
    log_event("Deallocated memory for log entries");
}

int main() {
    manage_memory(3, 2); // Example usage
    return 0;
}
