#define INITIAL_CAPACITY 10

void resize_array(void **array, size_t *capacity, size_t element_size);
int populate_offsets(long *offsets, size_t length);
int populate_keys(int *keys, size_t length);
double gaussian_random(double mean, double stddev);

// Error handling macro
#define HANDLE_ERROR(msg) \
    do { perror(msg); exit(EXIT_FAILURE); } while (0)

// Function prototypes
void manage_sensor_data(size_t initial_capacity, size_t batch_size);
void serialize_data(sensor_data *records, size_t count, unsigned char **out_buffer, size_t *buffer_len);
size_t compress_and_checksum(unsigned char *data, size_t data_len, unsigned char **compressed_data, size_t *compressed_len);

// Main function
int main() {
    time_t now;
    srand((unsigned int)time(&now));

    manage_sensor_data(INITIAL_CAPACITY, 5);
    return 0;
}

void resize_array(void **array, size_t *capacity, size_t element_size) {
    size_t new_capacity = (*capacity) * 2;
    void *new_array = realloc(*array, new_capacity * element_size);
    if (!new_array) HANDLE_ERROR("Failed to reallocate memory");

    *array = new_array;
    *capacity = new_capacity;
}

int populate_offsets(long *offsets, size_t length) {
    for (size_t i = 0; i < length; i++) {
        offsets[i] = (long)i;
    }
    return 0;
}

int populate_keys(int *keys, size_t length) {
    for (size_t i = 0; i < length; i++) {
        if ((int64_t)i > INT_MAX) return -1;
        keys[i] = (int)i;
    }
    return 0;
}

double gaussian_random(double mean, double stddev) {
    static int hasSpare = 0;
    static double spare;

    if (hasSpare) {
        hasSpare = 0;
        return mean + stddev * spare;
    }

    double u1, u2, w, mult;

    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);

        w = sqrt(-2.0 * log(u1)) * sin(2 * M_PI * u2);
        mult = sqrt(-2.0 * log(u1)) * cos(2 * M_PI * u2);
    } while (w * w > 1.0);

    spare = mult;
    hasSpare = 1;

    return mean + stddev * w;
}

void manage_sensor_data(size_t initial_capacity, size_t batch_size) {
    sensor_data *records = NULL;
    size_t capacity = initial_capacity;
    size_t count = 0;

    resize_array((void**)&records, &capacity, sizeof(sensor_data));

    while (1) { // Simulate continuous data feed
        if (count + batch_size > capacity) {
            resize_array((void**)&records, &capacity, sizeof(sensor_data));
        }

        for (size_t i = 0; i < batch_size; i++) {
            records[count].timestamp = time(NULL);
            records[count].sensor_reading = gaussian_random(100.0, 15.0); // Mean 100, Stddev 15
            snprintf(records[count].device_type, sizeof(records[count].device_type), "Device_%zu", count % 5 + 1);
            records[count].location_id = (int)(rand() % 10) + 1;

            count++;
        }

        unsigned char *serialized_data = NULL;
        size_t serialized_len;

        serialize_data(records, count, &serialized_data, &serialized_len);

        unsigned char *compressed_data = NULL;
        size_t compressed_len;

        compress_and_checksum((unsigned char *)records, count * sizeof(sensor_data), &compressed_data, &compressed_len);
    }
}

void serialize_data(sensor_data *records, size_t count, unsigned char **out_buffer, size_t *buffer_len) {
    // Calculate buffer length needed
    size_t version = 1;
    size_t header_size = sizeof(version) + (sizeof(size_t) * 2); 
    size_t record_size = sizeof(records[0]);
    *buffer_len = header_size + count * record_size;

    *out_buffer = malloc(*buffer_len);
    if (!*out_buffer) HANDLE_ERROR("Failed to allocate memory for serialized data");

    unsigned char *ptr = *out_buffer;
    memcpy(ptr, &version, sizeof(version));
    ptr += sizeof(version);

    size_t host_count = count;
    memcpy(ptr, &host_count, sizeof(host_count)); // Store number of records
    ptr += sizeof(host_count);

    size_t host_record_size = record_size;
    memcpy(ptr, &host_record_size, sizeof(host_record_size)); // Store record size
    ptr += sizeof(host_record_size);

    for (size_t i = 0; i < count; ++i) {
        sensor_data *record = &records[i];

        time_t host_timestamp = htonl(record->timestamp);
        memcpy(ptr, &host_timestamp, sizeof(time_t));
        ptr += sizeof(time_t);

        double host_reading;
        memcpy(&host_reading, &record->sensor_reading, sizeof(double)); // Store as bytes
        for (size_t j = 0; j < sizeof(double); ++j) {
            ptr[j] = host_reading[j];
        }
        ptr += sizeof(double);

        size_t str_len = strlen(record->device_type);
        memcpy(ptr, &str_len, sizeof(str_len)); // Store string length
        ptr += sizeof(str_len);
        memcpy(ptr, record->device_type, str_len); 
        ptr += str_len;

        int host_location_id = htonl(record->location_id);
        memcpy(ptr, &host_location_id, sizeof(int));
        ptr += sizeof(int);
    }
}

size_t compress_and_checksum(unsigned char *data, size_t data_len, unsigned char **compressed_data, size_t *compressed_len) {
    // Simulate compression with a simple run-length encoding (RLE)
    // This is just a placeholder; use proper compression libraries like zlib in practice.
    unsigned char buffer[1024];
    size_t buf_size = 0;

    for (size_t i = 0; i < data_len;) {
        unsigned char val = data[i];
        size_t count = 1;

        while ((i + count) < data_len && data[i] == data[i + count]) {
            ++count;
        }

        buffer[buf_size++] = count;
        buffer[buf_size++] = val;
        i += count;
    }

    *compressed_data = malloc(buf_size);
    if (!*compressed_data) HANDLE_ERROR("Failed to allocate memory for compressed data");

    memcpy(*compressed_data, buffer, buf_size);
    *compressed_len = buf_size;

    // Calculate a simple checksum (sum of all bytes)
    unsigned int checksum = 0;
    for (size_t i = 0; i < buf_size; ++i) {
        checksum += (*compressed_data)[i];
    }

    printf("Checksum: %u\n", checksum); // For demonstration purposes

    return *compressed_len;
}
```

