    int reliability;      // e.g., 1-10 scale
    int latency;          // in milliseconds
    int bandwidth;        // in Mbps
    double success_rate;  // Historical performance metric, 0.0 to 1.0
} NETWORK_PROTOCOL;

typedef struct {
    pthread_mutex_t lock;
    int active_connections[MAX_PROTOCOLS];
    int max_connections;
} NetworkManager;

NetworkManager network_manager = {PTHREAD_MUTEX_INITIALIZER, {0}, 100};

void log_event(const char *message) {
    time_t now;
    time(&now);
    printf("[%s] %s\n", ctime(&now), message);
}

int select_protocol() {
    // Placeholder for sophisticated protocol selection logic
    // In a real implementation, analyze network conditions, application requirements,
    // system load, and historical patterns here.

    static int last_used = -1;
    for (int i = 0; i < MAX_PROTOCOLS; ++i) {
        if (network_manager.active_connections[i] < network_manager.max_connections) {
            last_used = (last_used + 1) % MAX_PROTOCOLS;
            return last_used;
        }
    }
    // Fallback to last used protocol
    return last_used >= 0 ? last_used : PROTOCOL_TCP; 
}

void exponential_backoff(int *attempt) {
    int base_delay_ms = 100; // Base delay in milliseconds
    int max_delay_ms = 2000; // Max delay in milliseconds

    int delay_ms = base_delay_ms << (*attempt);
    if (delay_ms > max_delay_ms) {
        delay_ms = max_delay_ms;
    }
    // Introduce jitter: a small random value added to the delay
    srand(time(NULL));
    delay_ms += rand() % 100;

    usleep(delay_ms * 1000); // Convert ms to us for usleep

    (*attempt)++;
}

NETWORK_PROTOCOL* initialize_protocol(ProtocolType type) {
    static NETWORK_PROTOCOL protocols[MAX_PROTOCOLS] = {
        {PROTOCOL_TCP, 9, 50, 100, 0.99},
        {PROTOCOL_UDP, 5, 10, 150, 0.95},
        {PROTOCOL_HTTP1_1, 7, 70, 80, 0.97},
        {PROTOCOL_HTTPS, 8, 80, 60, 0.98},
        {PROTOCOL_WEBSOCKETS, 6, 60, 120, 0.96}
    };

    for (int i = 0; i < MAX_PROTOCOLS; ++i) {
        if (protocols[i].type == type) {
            return &protocols[i];
        }
    }
    return NULL;
}

NETWORK_PROTOCOL* choose_network_protocol() {
    pthread_mutex_lock(&network_manager.lock);

    int attempt = 0;
    while (attempt <= 5) { // Max retries
        ProtocolType selected_protocol = select_protocol();
        log_event("Selected protocol for communication.");

        NETWORK_PROTOCOL *protocol = initialize_protocol(selected_protocol);
        if (protocol != NULL && network_manager.active_connections[selected_protocol] < network_manager.max_connections) {
            pthread_mutex_unlock(&network_manager.lock);

            log_event("Protocol initialized successfully.");
            return protocol;
        }

        exponential_backoff(&attempt);
    }

    pthread_mutex_unlock(&network_manager.lock);
    log_event("Failed to select a suitable protocol after retries.");
    return NULL; // Indicate failure
}

int main() {
    NETWORK_PROTOCOL *chosen_protocol = choose_network_protocol();
    if (chosen_protocol != NULL) {
        printf("Chosen Protocol: %d\n", chosen_protocol->type);
    } else {
        fprintf(stderr, "No suitable protocol could be selected.\n");
    }
    return 0;
}
