```cpp
// DynamicValueGenerator.cpp

#include "DynamicValueGenerator.h"
#include <iostream>
#include <cstring>

DynamicValueGenerator::DynamicValueGenerator()
: config_{0, 100, 0.0, 1.0}, rng_(std::random_device{}()) {
    initializeRandomEngine();
}

DynamicValueGenerator::~DynamicValueGenerator() {}

void DynamicValueGenerator::setConfig(const Config& config) {
    std::lock_guard<std::mutex> lock(mutex_);
    config_ = config;
    intDist_ = std::uniform_int_distribution<int>(config.minValue, config.maxValue);
    floatDist_ = std::normal_distribution<double>(config.mean, config.stddev);
}

DynamicValueGenerator::Record DynamicValueGenerator::generateRecord() const {
    std::lock_guard<std::mutex> lock(mutex_);
    Record record;
    record.integer = intDist_(rng_);
    record.offset = static_cast<long>(floatDist_(rng_));
    size_t buffer_size = rand() % 100 + 1; // Random buffer length
    char* buffer = new char[buffer_size];
    for (size_t i = 0; i < buffer_size; ++i) {
        buffer[i] = 'a' + static_cast<char>(rand() % 26);
    }
    record.buffer.assign(buffer, buffer_size);
    delete[] buffer;
    return record;
}

std::vector<DynamicValueGenerator::Record> DynamicValueGenerator::generateRecords(size_t count) const {
    std::lock_guard<std::mutex> lock(mutex_);
    if (count * calculateSize() > MAX_MEMORY_SIZE) {
        throw std::runtime_error("Exceeds maximum memory allocation size");
    }
    std::vector<Record> records(count);
    for (auto& record : records) {
        record = generateRecord();
    }
    return records;
}

void DynamicValueGenerator::initializeRandomEngine() {
    // Initialize the random engine with a time-based seed
    unsigned seed = static_cast<unsigned>(std::chrono::system_clock::now().time_since_epoch().count());
    rng_.seed(seed);
}

size_t DynamicValueGenerator::calculateSize() noexcept {
    return sizeof(Record) + 100; // Estimate buffer size for serialization/deserialization
}
