container *create_container(long *input_offsets, size_t num_offsets, int max_key_value, size_t num_records,
                            enum cipher_mode mode) {
    srand(time(NULL));

    container *cont = malloc(sizeof(container));
    if (!cont) return NULL;

    // Allocate unique offsets with no duplicates
