    if (!unique_offsets) goto error;
    size_t offset_index = 0;

    for (size_t i = 0; i < num_offsets; ++i) {
        int already_exists = 0;
        for (size_t j = 0; j < offset_index; ++j) {
            if (input_offsets[i] == unique_offsets[j]) {
                already_exists = 1;
                break;
            }
        }

        if (!already_exists) {
            unique_offsets[offset_index++] = input_offsets[i];
        } else if (i == num_offsets - 1 && offset_index == 0) {
            goto error; // No valid offsets found
        }
    }

    cont->offsets = malloc(offset_index * sizeof(long));
    if (!cont->offsets) goto error;
    memcpy(cont->offsets, unique_offsets, offset_index * sizeof(long));
    free(unique_offsets);
    cont->num_offsets = offset_index;

    // Allocate and validate keys
    int *unique_keys = malloc(num_offsets * sizeof(int));
    if (!unique_keys) goto error;
    size_t key_index = 0;

    for (size_t i = 0; i < num_offsets; ++i) {
        if ((rand() % max_key_value + 1) <= max_key_value) {
            unique_keys[key_index++] = rand() % max_key_value + 1;
        }
    }

    cont->keys = malloc(key_index * sizeof(int));
    if (!cont->keys) goto error;
    memcpy(cont->keys, unique_keys, key_index * sizeof(int));
    free(unique_keys);
    cont->num_keys = key_index;

    // Allocate and initialize records
    record **records = malloc(num_records * sizeof(record *));
    if (!records) goto error;

    for (size_t i = 0; i < num_records; ++i) {
