class ConfigManager:
    def __init__(self):
        self.devices = {}
        self.encryption_keys = {}

    def add_device(self, device_id, capabilities):
        self.devices[device_id] = {
            'capabilities': capabilities,
            'encryption_algorithm': None
        }

    def select_encryption_algorithm(self, device_id):
        device = self.devices[device_id]
        if 'AES-256' in device['capabilities']:
            return 'AES-256'
        elif 'AES-128' in device['capabilities']:
            return 'AES-128'
        elif 'ChaCha20' in device['capabilities']:
            return 'ChaCha20'
        else:
            raise Exception("No suitable encryption algorithm found")

    def set_encryption_algorithm(self, device_id):
        try:
            alg = self.select_encryption_algorithm(device_id)
            self.devices[device_id]['encryption_algorithm'] = alg
        except Exception as e:
            print(f"Error selecting algorithm: {e}")

    def generate_key(self, device_id):
        key_size = 32 if self.devices[device_id]['encryption_algorithm'] == 'AES-256' else \
                   16 if self.devices[device_id]['encryption_algorithm'] == 'AES-128' else 32
        return os.urandom(key_size)

    def update_encryption_key(self, device_id):
        new_key = self.generate_key(device_id)
        self.encryption_keys[device_id] = new_key

    def encrypt_data(self, device_id, data):
        key = self.encryption_keys.get(device_id)
        if not key:
            raise Exception("No encryption key available")

        alg = self.devices[device_id]['encryption_algorithm']

        iv = os.urandom(16)  # Initialization vector
        cipher = Cipher(
            algorithms.AES(key) if 'AES' in alg else algorithms.ChaCha20(key, iv),
            modes.GCM(iv) if 'AES' in alg else None,
            backend=default_backend()
        )
        encryptor = cipher.encryptor()
        encrypted_data = encryptor.update(data.encode()) + encryptor.finalize()

        return {
            'iv': urlsafe_b64encode(iv).decode(),
            'ciphertext': urlsafe_b64encode(encrypted_data).decode(),
            'tag': urlsafe_b64encode(encryptor.tag).decode() if 'AES' in alg else None
        }

    def decrypt_data(self, device_id, encrypted_package):
        key = self.encryption_keys.get(device_id)
        iv = urlsafe_b64decode(encrypted_package['iv'])

        alg = self.devices[device_id]['encryption_algorithm']
        cipher = Cipher(
            algorithms.AES(key) if 'AES' in alg else algorithms.ChaCha20(key, iv),
            modes.GCM(iv, urlsafe_b64decode(encrypted_package['tag'])) if 'AES' in alg else None,
            backend=default_backend()
        )
        decryptor = cipher.decryptor()

        return (decryptor.update(urlsafe_b64decode(encrypted_package['ciphertext']))
                + decryptor.finalize()).decode()

    def deploy_ota_update(self, device_id, update_payload):
        self.set_encryption_algorithm(device_id)
        encrypted_data = self.encrypt_data(device_id, json.dumps(update_payload))
        return encrypted_data

# Example Usage
