// Utility functions for endianness handling
uint64_t htonll(uint64_t value) {
#ifdef _WIN32
    uint64_t ret;
    *((unsigned long long*) &ret) = __builtin_bswap64(value);
    return ret;
#else
    if (ntohl(1) != 1) {
        const unsigned char *b = (const unsigned char *) &value;
        return ((uint64_t)b[0] << 56)
            | ((uint64_t)b[1] << 48)
            | ((uint64_t)b[2] << 40)
            | ((uint64_t)b[3] << 32)
            | ((uint64_t)b[4] << 24)
            | ((uint64_t)b[5] << 16)
            | ((uint64_t)b[6] << 8)
            | ((uint64_t)b[7]);
    } else {
        return value;
    }
#endif
}

float gaussian_random(float mean, float stddev) {
    static int hasSpare = 0;
    static float spare;
    if (hasSpare) {
        hasSpare = 0;
        return mean + stddev * spare;
    }

    float u1, u2, s;
    do {
        u1 = rand() / (RAND_MAX + 1.0f);
        u2 = rand() / (RAND_MAX + 1.0f);

        s = u1 * u1 + u2 * u2;
    } while (s >= 1.0 || s == 0);

    float multiplier = sqrtf(-2.0f * logf(s) / s);
    spare = u2 * multiplier;
    hasSpare = 1;

    return mean + stddev * (u1 * multiplier);
}

void resize_sensor_dataset(sensor_dataset **dataset, size_t new_capacity) {
    sensor_data *new_records = realloc((*dataset)->records, sizeof(sensor_data) * new_capacity);
    if (!new_records) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    int *new_offsets = realloc((*dataset)->offsets, (*dataset)->count + 1);
    if (!new_offsets) {
        free(new_records);
        perror("Failed to reallocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    int *new_keys = realloc((*dataset)->keys, (*dataset)->count);
    if (!new_keys) {
        free(new_records);
        free(new_offsets);
        perror("Failed to reallocate memory for keys");
        exit(EXIT_FAILURE);
    }

    (*dataset)->records = new_records;
    (*dataset)->capacity = new_capacity;
    memmove(&(*dataset)->offsets[*dataset->count + 1], &(*dataset)->offsets[*dataset->count], 
            (sizeof(int) * (new_capacity - (*dataset->count + 1))));
    memset(&(*dataset)->offsets[*dataset->count + 1], 0, sizeof(int) * (new_capacity - (*dataset->count + 1)));
    memmove(&(*dataset)->keys[*dataset->count], &(*dataset)->keys[0],
            sizeof(int) * (*dataset->count));
    memset(&(*dataset)->keys[0], 0, sizeof(int) * new_keys);

}

int add_sensor_data(sensor_dataset *ds, uint64_t timestamp, float sensor_reading, 
                    const char *device_type, int location_id) {
    if (ds->count >= ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        resize_sensor_dataset(&ds, new_capacity);
    }

    sensor_data *record = &ds->records[ds->offsets[ds->count]];
    record->timestamp = htonll(timestamp);
    record->sensor_reading = sensor_reading; // Assuming float is consistent
    strncpy(record->device_type, device_type, sizeof(record->device_type) - 1);
    record->location_id = location_id;

    ds->keys[ds->count] = ds->count;
    ds->offsets[++(ds->count)] = ds->capacity; // Set next offset for batch processing

    return 0;
}

void initialize_dataset(sensor_dataset **dataset, size_t initial_capacity) {
    *dataset = calloc(1, sizeof(sensor_dataset) + (sizeof(int) * initial_capacity));
    if (!*dataset) {
        perror("Failed to allocate memory for dataset");
        exit(EXIT_FAILURE);
    }

    (*dataset)->records = malloc(sizeof(sensor_data) * initial_capacity);
    if (!(*dataset)->records) {
        free(*dataset);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    (*dataset)->capacity = initial_capacity;
    (*dataset)->count = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        (*dataset)->offsets[i] = i * sizeof(sensor_data);
        if (i > 0) {
            (*dataset)->keys[i-1] = i - 1;
        }
    }
    // Allocate one extra offset for end
    int *extra_offsets = realloc((*dataset)->offsets, (initial_capacity + 1) * sizeof(int));
    if (!extra_offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    (*dataset)->offsets = extra_offsets;
}

void free_dataset(sensor_dataset **ds) {
    if (ds && *ds) {
        free((*ds)->records);
        free(*ds);
        *ds = NULL;
    }
}

// Main processing function
int main() {
    srand(time(NULL));

    sensor_dataset *dataset = NULL;
    initialize_dataset(&dataset, 10);

    for (int i = 0; i < 100; ++i) {
        add_sensor_data(dataset, time(NULL) + i, gaussian_random(50.0f, 5.0f), "SensorTypeA", rand() % 100);
    }

    // Serialization and compression would go here

    free_dataset(&dataset);

    return 0;
}
