#define MAX_POOL_SIZE 1024

typedef enum {
    ESTABLISHED,
    PENDING,
    FAILED
} ConnectionState;

typedef struct CustomAttribute {
    char key[64];
    char value[256];
} CustomAttribute;

typedef struct DatabaseConnection {
    char databaseName[128];
    ConnectionState state;
    int timeout;
    CustomAttribute *customAttributes;
    size_t numCustomAttributes;
    void *connectionHandle; // Generic pointer to handle
} DatabaseConnection;

typedef struct ConnectionPool {
    DatabaseConnection *connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionPool;

// Function prototypes
int initialize_connection_pool(ConnectionPool *pool, size_t max_size);
int add_database_connection(ConnectionPool *pool, const char *db_name, int timeout, CustomAttribute customAttributes[], size_t numCustomAttributes);
void free_connection_pool(ConnectionPool *pool);
void serialize_pool(ConnectionPool *pool, unsigned char **buffer, size_t *bufferSize);
int deserialize_pool(unsigned char *buffer, size_t bufferSize, ConnectionPool *pool);

// Initialize the connection pool
int initialize_connection_pool(ConnectionPool *pool, size_t max_size) {
    if (max_size > MAX_POOL_SIZE) return -1;

    pthread_mutex_init(&pool->lock, NULL);
    pool->connections = malloc(max_size * sizeof(DatabaseConnection));
    if (!pool->connections) {
        perror("Failed to allocate memory for connections");
        return -1;
    }
    pool->capacity = max_size;
    pool->size = 0;

    printf("Connection pool initialized with capacity %zu\n", max_size);
    return 0;
}

// Add a new database connection
int add_database_connection(ConnectionPool *pool, const char *db_name, int timeout, CustomAttribute customAttributes[], size_t numCustomAttributes) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity) {
        fprintf(stderr, "Connection pool is full\n");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    DatabaseConnection *conn = &pool->connections[pool->size];
    strncpy(conn->databaseName, db_name, sizeof(conn->databaseName));
    conn->state = PENDING; // Initial state
    conn->timeout = timeout;
    conn->customAttributes = malloc(numCustomAttributes * sizeof(CustomAttribute));
    if (!conn->customAttributes) {
        perror("Failed to allocate memory for custom attributes");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    memcpy(conn->customAttributes, customAttributes, numCustomAttributes * sizeof(CustomAttribute));
    conn->numCustomAttributes = numCustomAttributes;
    conn->connectionHandle = NULL; // Placeholder

    pool->size++;
    printf("Added new connection for database: %s\n", db_name);

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Free all allocated memory in the connection pool
void free_connection_pool(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->connections[i].customAttributes) {
            free(pool->connections[i].customAttributes);
        }
    }

    free(pool->connections);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);

    printf("Connection pool freed\n");
}

