    if (initialize_connection_pool(&pool, 10) != 0) {
        fprintf(stderr, "Failed to initialize connection pool\n");
        return EXIT_FAILURE;
    }

    CustomAttribute attrs[] = {{"key1", "value1"}, {"key2", "value2"}};
