#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB maximum memory allocation
#define FLOAT_MIN -1000.0f
#define FLOAT_MAX 1000.0f

typedef struct {
    float value;
    double timestamp;
} Measurement;

void initialize_data_structures(double **doubles, char **chars, Measurement **measurements, size_t count) {
    // Seed the random number generator with current time
    srand((unsigned int)time(NULL));

    *doubles = (double *)malloc(count * sizeof(double));
    if (!*doubles) {
        perror("Failed to allocate memory for doubles");
        exit(EXIT_FAILURE);
    }

    *chars = (char *)malloc(count * sizeof(char));
    if (!*chars) {
        perror("Failed to allocate memory for chars");
        free(*doubles);
        exit(EXIT_FAILURE);
    }

    *measurements = (Measurement *)malloc(count * sizeof(Measurement));
    if (!*measurements) {
        perror("Failed to allocate memory for measurements");
        free(*doubles);
        free(*chars);
        exit(EXIT_FAILURE);
    }

    // Populate the arrays
    for (size_t i = 0; i < count; ++i) {
        (*doubles)[i] = ((double)rand() / RAND_MAX) * 100.0;

        (*chars)[i] = (char)(rand() % 256);

        float fValue = FLOAT_MIN + (((float)rand() / RAND_MAX) * (FLOAT_MAX - FLOAT_MIN));
        if (fValue < FLOAT_MIN || fValue > FLOAT_MAX) {
            fprintf(stderr, "Float value overflow detected: %f\n", fValue);
            exit(EXIT_FAILURE);
        }

        (*measurements)[i].value = fValue;
        (*measurements)[i].timestamp = time(NULL) + (double)(rand() % 1000);
    }

    // Log memory usage
    size_t used_memory = count * (sizeof(double) + sizeof(char) + sizeof(Measurement));
    printf("Memory Usage: %zu bytes\n", used_memory);

    if (used_memory > MAX_MEMORY) {
        fprintf(stderr, "Memory usage exceeded limit of %zu bytes.\n", MAX_MEMORY);
        exit(EXIT_FAILURE);
    }
}

void serialize_data(const double *doubles, const char *chars, const Measurement *measurements, size_t count, FILE *file) {
    if (!file) return;

    fwrite(&count, sizeof(size_t), 1, file); // Write the count

    for (size_t i = 0; i < count; ++i) {
        double d = htobe64(doubles[i]);
        char c = chars[i];
        float f = htole32(measurements[i].value);
        double t = htobe64(measurements[i].timestamp);

        fwrite(&d, sizeof(double), 1, file);
        fwrite(&c, sizeof(char), 1, file);
        fwrite(&f, sizeof(float), 1, file);
        fwrite(&t, sizeof(double), 1, file);
    }
}

void deserialize_data(double **doubles, char **chars, Measurement **measurements, size_t *count, FILE *file) {
    if (!file) return;

    fread(count, sizeof(size_t), 1, file);

    *doubles = (double *)malloc(*count * sizeof(double));
    *chars = (char *)malloc(*count * sizeof(char));
    *measurements = (Measurement *)malloc(*count * sizeof(Measurement));

    for (size_t i = 0; i < *count; ++i) {
        double d;
        char c;
        float f;
        double t;

        fread(&d, sizeof(double), 1, file);
        fread(&c, sizeof(char), 1, file);
        fread(&f, sizeof(float), 1, file);
        fread(&t, sizeof(double), 1, file);

        (*doubles)[i] = be64toh(d);
        (*chars)[i] = c;
        (*measurements)[i].value = le32tohf(f);
        (*measurements)[i].timestamp = be64toh(t);
    }
}

int main() {
    size_t count = 1000; // Example number of elements
    double *doubles, *deserialized_doubles;
    char *chars, *deserialized_chars;
    Measurement *measurements, *deserialized_measurements;

    initialize_data_structures(&doubles, &chars, &measurements, count);

    FILE *file = fopen("data.bin", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    serialize_data(doubles, chars, measurements, count, file);
    fclose(file);

    file = fopen("data.bin", "rb");
    if (!file) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }

    deserialize_data(&deserialized_doubles, &deserialized_chars, &deserialized_measurements, &count, file);
    fclose(file);

    // Clean up
    free(doubles);
    free(chars);
    free(measurements);
    free(deserialized_doubles);
    free(deserialized_chars);
    free(deserialized_measurements);

    return 0;
}
