#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structures
typedef struct {
    float value;
    double timestamp;
} Measurement;

typedef struct {
    int id;
    long offset;
} Record;

// Function prototypes
void initialize_data(long max_size, size_t offsets_count, size_t keys_count, 
                     size_t measurements_count, size_t records_count);
size_t serialize_data(void **buffer, long *serialized_size);
int deserialize_data(const void *buffer, size_t buffer_size,
                     long **offsets, int **keys, Measurement **measurements, Record **records);
void free_resources(long *offsets, int *keys, Measurement *measurements, Record *records);

// Main function
void initialize_data(long max_size, size_t offsets_count, size_t keys_count, 
                     size_t measurements_count, size_t records_count) {
    // Calculate sizes
    long offset_size = sizeof(long) * offsets_count;
    long key_size = sizeof(int) * keys_count;
    long measurement_size = sizeof(Measurement) * measurements_count;
    long record_size = sizeof(Record) * records_count;

    // Check if total size exceeds max_size
    if (offset_size + key_size + measurement_size + record_size > max_size) {
        fprintf(stderr, "Exceeds maximum allowed memory size.\n");
        return;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Allocate and initialize offsets array
    long *offsets = (long *)malloc(offset_size);
    if (!offsets) {
        perror("Failed to allocate offsets");
        return;
    }
    for (size_t i = 0; i < offsets_count; ++i) {
        offsets[i] = (long)i;
    }

    // Allocate and initialize keys array
    int *keys = (int *)malloc(key_size);
    if (!keys) {
        perror("Failed to allocate keys");
        free(offsets);
        return;
    }
    for (size_t i = 0; i < keys_count; ++i) {
        keys[i] = (int)i;
    }

    // Allocate and initialize measurements array
    Measurement *measurements = (Measurement *)malloc(measurement_size);
    if (!measurements) {
        perror("Failed to allocate measurements");
        free(offsets);
        free(keys);
        return;
    }
    for (size_t i = 0; i < measurements_count; ++i) {
        measurements[i].value = (float)(rand() % 100.0f); // Random float between 0 and 99
        measurements[i].timestamp = (double)rand();       // Random double timestamp
    }

    // Allocate and initialize records array
    Record *records = (Record *)malloc(record_size);
    if (!records) {
        perror("Failed to allocate records");
        free(offsets);
        free(keys);
        free(measurements);
        return;
    }
    for (size_t i = 0; i < records_count; ++i) {
        records[i].id = rand() % 1000; // Random int ID
        records[i].offset = offsets[rand() % offsets_count]; // Random offset from offsets array
    }

    // Serialize data
    void *serialized_data;
    long serialized_size;
    if (serialize_data(&serialized_data, &serialized_size) != 0) {
        fprintf(stderr, "Serialization failed.\n");
        free_resources(offsets, keys, measurements, records);
        return;
    }

    // Deserialize data (for demonstration)
    long *deserialized_offsets;
    int *deserialized_keys;
    Measurement *deserialized_measurements;
    Record *deserialized_records;
    if (deserialize_data(serialized_data, serialized_size,
                         &deserialized_offsets, &deserialized_keys,
                         &deserialized_measurements, &deserialized_records) != 0) {
        fprintf(stderr, "Deserialization failed.\n");
    } else {
        // Use deserialized data as needed
    }

    // Free resources
    free_resources(offsets, keys, measurements, records);
    if (serialized_data) {
        free(serialized_data);
    }
}

size_t serialize_data(void **buffer, long *serialized_size) {
    // Calculate total size for serialization
    size_t offsets_count = 10; // Example count
    size_t keys_count = 10;    // Example count
    size_t measurements_count = 10; // Example count
    size_t records_count = 10; // Example count

    *serialized_size = sizeof(long) * offsets_count + sizeof(int) * keys_count +
                       sizeof(Measurement) * measurements_count + sizeof(Record) * records_count;

    *buffer = malloc(*serialized_size);
    if (!*buffer) {
        perror("Failed to allocate buffer for serialization");
        return 0;
    }

    // Serialize data
