    memcpy((char *)*buffer + sizeof(long) * offsets_count + sizeof(int) * keys_count +
                      sizeof(Measurement) * measurements_count,
           records, sizeof(Record) * records_count);

    return *serialized_size;
}

int deserialize_data(const void *buffer, size_t buffer_size,
                     long **offsets, int **keys, Measurement **measurements, Record **records) {
    // Example counts
