    memcpy(*measurements,
           (char *)buffer + sizeof(long) * offsets_count + sizeof(int) * keys_count,
           sizeof(Measurement) * measurements_count);

    *records = (Record *)malloc(sizeof(Record) * records_count);
    if (!*records) {
        free(*offsets);
        free(*keys);
        free(*measurements);
        return -1;
    }
    memcpy(*records,
           (char *)buffer + sizeof(long) * offsets_count + sizeof(int) * keys_count +
                      sizeof(Measurement) * measurements_count,
           sizeof(Record) * records_count);

    return 0;
}

void free_resources(long *offsets, int *keys, Measurement *measurements, Record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (measurements) free(measurements);
    if (records) free(records);
}
