// Define structure for records
typedef struct {
    int value;
    long offset;
} Record;

// Function to serialize a record into bytes considering endianness
void serializeRecord(const Record *record, uint8_t *buffer) {
    buffer[0] = (record->value >> 24) & 0xFF;
    buffer[1] = (record->value >> 16) & 0xFF;
    buffer[2] = (record->value >> 8) & 0xFF;
    buffer[3] = record->value & 0xFF;

    buffer[4] = (record->offset >> 56) & 0xFF;
    buffer[5] = (record->offset >> 48) & 0xFF;
    buffer[6] = (record->offset >> 40) & 0xFF;
    buffer[7] = (record->offset >> 32) & 0xFF;
    buffer[8] = (record->offset >> 24) & 0xFF;
    buffer[9] = (record->offset >> 16) & 0xFF;
    buffer[10] = (record->offset >> 8) & 0xFF;
    buffer[11] = record->offset & 0xFF;
}

// Function to deserialize bytes back into a record
void deserializeRecord(const uint8_t *buffer, Record *record) {
    record->value = ((int)(buffer[0] << 24) | (int)(buffer[1] << 16) |
                     (int)(buffer[2] << 8) | (int)(buffer[3]));
    record->offset = ((long)(buffer[4] << 56) | (long)(buffer[5] << 48) |
                      (long)(buffer[6] << 40) | (long)(buffer[7] << 32) |
                      (long)(buffer[8] << 24) | (long)(buffer[9] << 16) |
                      (long)(buffer[10] << 8) | (long)(buffer[11]));
}

// Function to allocate memory and initialize arrays
int allocateAndInitialize(int numElements, long maxSize,
                          long **offsets, int **keys, Record ***records) {
