    if (!*offsets) {
        perror("Failed to allocate offsets");
        return -1;
    }

    *keys = (int *)malloc(keySize);
    if (!*keys) {
        free(*offsets);
        perror("Failed to allocate keys");
        return -1;
    }

    *records = (Record **)malloc(recordSize);
    if (!*records) {
        free(*offsets);
        free(*keys);
        perror("Failed to allocate records");
        return -1;
    }

    // Initialize arrays
    for (int i = 0; i < numElements; ++i) {
        (*offsets)[i] = rand() % ((long)INT_MAX / 2);
        (*keys)[i] = rand() % INT_MAX;
        (*records)[i]->value = (*keys)[i];
        (*records)[i]->offset = (*offsets)[i];
    }

    return 0; // Success
}

// Function to free allocated memory
void freeMemory(long *offsets, int *keys, Record **records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

