#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import time.h

#define MEMORY_LIMIT 1024 * 1024 // Example limit: 1MB
#define MAX_FLOAT_RANGE 100.0f
#define DOUBLE_PRECISION_EPOCH 1970
#define NUM_SCENARIOS 10

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} status_code;

typedef struct {
    float value;
    double timestamp;
} measurement;

typedef struct {
    char* message;
    time_t timestamp;
    status_code severity;
} log_entry;

typedef struct {
    log_entry* log;
    float average_duration;
    double last_update;
} audit_summary;

typedef struct {
    void** data;
    size_t allocated_size;
    size_t used_size;
    size_t element_size;
} dynamic_array;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

dynamic_array* create_dynamic_array(size_t element_size) {
    dynamic_array* array = (dynamic_array*)safe_malloc(sizeof(dynamic_array));
    array->data = NULL;
    array->allocated_size = 0;
    array->used_size = 0;
    array->element_size = element_size;
    return array;
}

int add_element(dynamic_array* array, void* element) {
    if (!array || !element) return -1;

    if (array->used_size == array->allocated_size) {
        size_t new_size = array->allocated_size ? array->allocated_size * 2 : 4;
        if ((array->allocated_size + new_size) * array->element_size > MEMORY_LIMIT) {
            fprintf(stderr, "Memory limit exceeded\n");
            return -1;
        }
        void** new_data = (void**)safe_malloc(new_size * sizeof(void*));
        memcpy(new_data, array->data, array->used_size * sizeof(void*));
        free(array->data);
        array->data = new_data;
        array->allocated_size = new_size;
    }

    ((void**)array->data)[array->used_size++] = element;
    return 0;
}

measurement create_measurement(float value, double timestamp) {
    if (value > MAX_FLOAT_RANGE || value < -MAX_FLOAT_RANGE) {
        fprintf(stderr, "Float overflow detected\n");
        exit(EXIT_FAILURE);
    }
    measurement m = {value, timestamp};
    return m;
}

log_entry create_log_entry(const char* message, time_t timestamp, status_code severity) {
    log_entry entry;
    entry.message = strdup(message);
    if (!entry.message) {
        fprintf(stderr, "Failed to duplicate string\n");
        exit(EXIT_FAILURE);
    }
    entry.timestamp = timestamp;
    entry.severity = severity;
    return entry;
}

audit_summary create_audit_summary(log_entry* log) {
    audit_summary summary;
    summary.log = log;
    summary.average_duration = 0.0f; // Placeholder for actual computation
    summary.last_update = time(NULL);
    return summary;
}

void serialize_data(const dynamic_array* float_array, const dynamic_array* char_array, 
                    const dynamic_array* measurement_array, const dynamic_array* log_array,
                    const dynamic_array* audit_array) {
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(&float_array->used_size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < float_array->used_size; ++i) {
        double value = *(double*)((void**)float_array->data)[i];
        fwrite(&value, sizeof(double), 1, file);
    }

    fwrite(&char_array->used_size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < char_array->used_size; ++i) {
        char value = *(char*)((void**)char_array->data)[i];
        fwrite(&value, sizeof(char), 1, file);
    }

    fwrite(&measurement_array->used_size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < measurement_array->used_size; ++i) {
        const measurement* m = (const measurement*)((void**)measurement_array->data)[i];
        fwrite(m, sizeof(measurement), 1, file);
    }

    fwrite(&log_array->used_size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < log_array->used_size; ++i) {
        const log_entry* entry = (const log_entry*)((void**)log_array->data)[i];
        size_t len = strlen(entry->message) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(entry->message, sizeof(char), len, file);
        fwrite(&entry->timestamp, sizeof(time_t), 1, file);
        fwrite(&entry->severity, sizeof(status_code), 1, file);
    }

    fwrite(&audit_array->used_size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < audit_array->used_size; ++i) {
        const audit_summary* summary = (const audit_summary*)((void**)audit_array->data)[i];
        size_t log_index = ((log_entry*)summary->log - (log_entry*)log_array->data[0]);
        fwrite(&log_index, sizeof(size_t), 1, file);
        fwrite(&summary->average_duration, sizeof(float), 1, file);
        fwrite(&summary->last_update, sizeof(double), 1, file);
    }

    fclose(file);
}

void deserialize_data(dynamic_array* float_array, dynamic_array* char_array, 
                      dynamic_array* measurement_array, dynamic_array* log_array,
                      dynamic_array* audit_array) {
    FILE* file = fopen("data.bin", "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    size_t float_count, char_count, measurement_count, log_count, audit_count;
    fread(&float_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < float_count; ++i) {
        double value;
        fread(&value, sizeof(double), 1, file);
        add_element(float_array, safe_malloc(sizeof(double)));
        *(double*)((void**)float_array->data)[float_array->used_size - 1] = value;
    }

    fread(&char_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < char_count; ++i) {
        char value;
        fread(&value, sizeof(char), 1, file);
        add_element(char_array, safe_malloc(sizeof(char)));
        *(char*)((void**)char_array->data)[char_array->used_size - 1] = value;
    }

    fread(&measurement_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < measurement_count; ++i) {
        measurement m;
        fread(&m, sizeof(measurement), 1, file);
        add_element(measurement_array, safe_malloc(sizeof(measurement)));
        memcpy((void**)measurement_array->data)[measurement_array->used_size - 1], &m, sizeof(measurement));
    }

    fread(&log_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < log_count; ++i) {
        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        char* message = (char*)safe_malloc(len * sizeof(char));
        fread(message, sizeof(char), len, file);

        time_t timestamp;
        status_code severity;
        fread(&timestamp, sizeof(time_t), 1, file);
        fread(&severity, sizeof(status_code), 1, file);

        add_element(log_array, safe_malloc(sizeof(log_entry)));
        log_entry* entry = (log_entry*)((void**)log_array->data)[log_array->used_size - 1];
        entry->message = message;
        entry->timestamp = timestamp;
        entry->severity = severity;
    }

    fread(&audit_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < audit_count; ++i) {
        size_t log_index;
        float average_duration;
        double last_update;
        fread(&log_index, sizeof(size_t), 1, file);
        fread(&average_duration, sizeof(float), 1, file);
        fread(&last_update, sizeof(double), 1, file);

        add_element(audit_array, safe_malloc(sizeof(audit_summary)));
        audit_summary* summary = (audit_summary*)((void**)audit_array->data)[audit_array->used_size - 1];
        summary->log = (log_entry*)log_array->data[log_index];
        summary->average_duration = average_duration;
        summary->last_update = last_update;
    }

    fclose(file);
}

int main() {
    srand((unsigned int)time(NULL));

    dynamic_array* float_array = create_dynamic_array(sizeof(double));
    dynamic_array* char_array = create_dynamic_array(sizeof(char));
    dynamic_array* measurement_array = create_dynamic_array(sizeof(measurement));
    dynamic_array* log_array = create_dynamic_array(sizeof(log_entry));
    dynamic_array* audit_array = create_dynamic_array(sizeof(audit_summary));

    // Example: Populate arrays with data
    for (int i = 0; i < NUM_SCENARIOS; ++i) {
        double float_value = ((double)rand() / RAND_MAX) * MAX_FLOAT_RANGE;
        add_element(float_array, safe_malloc(sizeof(double)));
        *(double*)((void**)float_array->data)[float_array->used_size - 1] = float_value;

        char char_value = 'A' + (char)(rand() % 26);
        add_element(char_array, safe_malloc(sizeof(char)));
        *(char*)((void**)char_array->data)[char_array->used_size - 1] = char_value;

        double timestamp = time(NULL) + (double)i;
        measurement m = create_measurement(float_value, timestamp);
        add_element(measurement_array, safe_malloc(sizeof(measurement)));
        memcpy((void**)measurement_array->data)[measurement_array->used_size - 1], &m, sizeof(measurement));

        char* message = "Example log message";
        time_t ts = time(NULL);
        status_code severity = (status_code)(rand() % 4);
        log_entry entry = create_log_entry(message, ts, severity);
        add_element(log_array, safe_malloc(sizeof(log_entry)));
        memcpy((void**)log_array->data)[log_array->used_size - 1], &entry, sizeof(log_entry));

        audit_summary summary = create_audit_summary((log_entry*)log_array->data[0]);
        add_element(audit_array, safe_malloc(sizeof(audit_summary)));
