    def __init__(self, max_memory):
        self.sockets = []
        self.lock = threading.Lock()
        self.memory_limit = max_memory
        self.total_memory_used = 0

    # Add socket to pool
    def add_socket(self, sock: socket_t):
        with self.lock:
            if self.total_memory_used + sizeof(socket_t) > self.memory_limit:
                raise MemoryError("Exceeded memory limit")
            self.sockets.append(sock)
            self.total_memory_used += sizeof(socket_t)

    # Remove and free socket
    def remove_socket(self, sock: socket_t):
        with self.lock:
            if sock in self.sockets:
                self.sockets.remove(sock)
                self.total_memory_used -= sizeof(socket_t)

    # Serialize pool to byte array
    def serialize_pool(self) -> bytes:
        with self.lock:
            data = b''
            for sock in self.sockets:
                data += struct.pack('iIqQ', sock.id, sock.status, sock.last_accessed,
                                    sock.packets_sent, sock.packets_received)
            return data

    # Deserialize from byte array
    @staticmethod
    def deserialize_pool(data: bytes) -> list:
        sockets = []
        offset = 0
        while offset < len(data):
            id_, status, last_accessed, packets_sent, packets_received = struct.unpack('iIqQ', data[offset:offset + 28])
            sock = socket_t(id_, status, last_accessed, packets_sent, packets_received)
            sockets.append(sock)
            offset += 28
        return sockets

    # Free all resources
    def cleanup(self):
        with self.lock:
            for sock in self.sockets:
                self.remove_socket(sock)

# Packet management class
class PacketManager:
    def __init__(self, max_packets):
        self.packets = []
        self.lock = threading.Lock()
        self.max_memory_limit = MAX_MEMORY_LIMIT // 2 # Example split

    # Add packet to the pool
    def add_packet(self, seq: int, timestamp: long, payload: bytes) -> None:
        with self.lock:
            if len(self.packets) >= MAX_PACKETS:
                raise MemoryError("Exceeded max packets limit")

            packet = packet_t(seq, timestamp, payload, len(payload))
            self.packets.append(packet)

    # Remove and free packet
    def remove_packet(self, packet: packet_t) -> None:
        with self.lock:
            if packet in self.packets:
                self.packets.remove(packet)
                del packet.payload

# Function to handle socket operations concurrently
