#include <time.h>

typedef enum {
    STATUS_OK,
    STATUS_ERROR
} Status;

typedef struct {
    float temperature;
    time_t timestamp;
    Status status;
} DataPoint;

typedef struct Node {
    DataPoint data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    float total_temp; // For efficient moving average calculation
    float max_memory_usage; // in bytes
    float temp_range_min, temp_range_max;
} DataCollection;

// Function prototypes
DataCollection* create_data_collection(float max_memory, float min_temp, float max_temp);
void destroy_data_collection(DataCollection* collection);
int add_data_point(DataCollection* collection, float temperature, Status status);
float calculate_moving_average(DataCollection* collection);
void log_event(const char* message);

// Create a new data collection
DataCollection* create_data_collection(float max_memory, float min_temp, float max_temp) {
    DataCollection* collection = (DataCollection*)malloc(sizeof(DataCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->total_temp = 0.0f;
    collection->max_memory_usage = max_memory;
    collection->temp_range_min = min_temp;
    collection->temp_range_max = max_temp;

    log_event("DataCollection created");
    return collection;
}

// Destroy the data collection
void destroy_data_collection(DataCollection* collection) {
    if (!collection) return;

    Node* current = collection->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&collection->lock);
    free(collection);

    log_event("DataCollection destroyed");
}

// Add a new data point to the collection
int add_data_point(DataCollection* collection, float temperature, Status status) {
    if (!collection || temperature < collection->temp_range_min || temperature > collection->temp_range_max)
        return -1;

    pthread_mutex_lock(&collection->lock);

    // Check memory usage (simplified check here)
    size_t estimated_size = sizeof(Node);
    while ((estimated_size * collection->count) > collection->max_memory_usage) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Memory limit exceeded, unable to add new data point");
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        log_event("Failed to allocate memory for new data point");
        return -1;
    }

    new_node->data.temperature = temperature;
    new_node->data.timestamp = time(NULL);
    new_node->data.status = status;

    new_node->next = collection->head;
    collection->head = new_node;
    collection->count++;
    collection->total_temp += temperature;

    pthread_mutex_unlock(&collection->lock);

    log_event("Data point added successfully");
    return 0;
}

// Calculate the moving average of temperatures
float calculate_moving_average(DataCollection* collection) {
    if (!collection || collection->count == 0)
        return 0.0f;

    pthread_mutex_lock(&collection->lock);

    float avg = collection->total_temp / (float)collection->count;

    pthread_mutex_unlock(&collection->lock);

    log_event("Moving average calculated");
    return avg;
}

// Log events for debugging and monitoring
void log_event(const char* message) {
    // Simplified logging mechanism
    printf("[%s] %s\n", time(NULL), message);
}
```

This code defines a C function set to manage a dynamic collection of `DataPoint` structures, adhering to memory constraints and ensuring thread safety with mutex locks. The functions allow for the addition of data points, calculation of a moving average, and logging of events for monitoring purposes.']

