        return -1;
    }

    // Allocate memory for records and extended records
    records = malloc(5 * record_size);
    extended_records = malloc(5 * extended_record_size);

    if (!records || !extended_records) {
        free(offsets);
        free(keys);
        free(records);
        free(extended_records);
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    // Seed random number generator
