        offsets[i] = rand() % 1000000L;  // Example offset value
        keys[i] = rand() % 100;

        records[i].value = range_min + (rand() % (range_max - range_min + 1));
        records[i].offset = offsets[i];

        extended_records[i].base = records[i];
        extended_records[i].timestamp = (double)rand();
        extended_records[i].status_flag = 'A' + rand() % 26;  // Example status flag
    }

    // Serialize data
    uint8_t *serialized_data;
    size_t serialized_size = serialize_data(extended_records, 5 * extended_record_size, &serialized_data);

    if (serialized_size == 0) {
        fprintf(stderr, "Serialization failed.\n");
        free(offsets);
        free(keys);
        free(records);
        free(extended_records);
        return -1;
    }

    // Deserialize data back to verify
    ExtendedRecord deserialized_records[5];
    deserialize_data(serialized_data, serialized_size, &deserialized_records);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(extended_records);
    free(serialized_data);

    return 0;
}

int main() {
