    long *offsets;
    int *keys;
    record *records;
    size_t n;
    pthread_mutex_t lock;
} data_structure;

// Error logging and graceful termination
void handle_allocation_failure(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

data_structure* initialize_data_structure(size_t n, int memory_limit, int max_value, int sort_arrays) {
    size_t memory_usage;
    data_structure *ds = malloc(sizeof(data_structure));
    if (!ds) handle_allocation_failure("Failed to allocate memory for data structure.");

    ds->offsets = calloc(n, sizeof(long));
    if (!ds->offsets) handle_allocation_failure("Failed to allocate memory for offsets.");
    memory_usage = n * sizeof(long);

    ds->keys = malloc(n * sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        handle_allocation_failure("Failed to allocate memory for keys.");
    }
    memory_usage += n * sizeof(int);

    ds->records = calloc(n, sizeof(record));
    if (!ds->records) {
        free(ds->offsets);
        free(ds->keys);
        handle_allocation_failure("Failed to allocate memory for records.");
    }
    memory_usage += n * sizeof(record);

    if (memory_usage > memory_limit) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        handle_allocation_failure("Memory usage exceeds limit.");
    }

    ds->n = n;
    pthread_mutex_init(&ds->lock, NULL);

    // Populate keys with unique values
    int *used_values = calloc(max_value + 1, sizeof(int));
    if (!used_values) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        handle_allocation_failure("Failed to allocate memory for used values.");
    }

    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        int key;
        do {
            key = rand() % (max_value + 1);
        } while (used_values[key]);
        used_values[key] = 1;
        ds->keys[i] = key;

        // Hash the keys using a placeholder cryptographic function
        // hash_key(&ds->keys[i]); // Assume this is defined elsewhere
    }
    free(used_values);

    if (sort_arrays) {
        qsort(ds->offsets, n, sizeof(long), (int (*)(const void *, const void *))strcmp);
        qsort(ds->keys, n, sizeof(int), (int (*)(const void *, const void *))strcmp);
    }

    return ds;
}

void free_data_structure(data_structure *ds) {
    if (!ds) return;
    pthread_mutex_destroy(&ds->lock);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

// Example usage
int main() {
    size_t n = 1000;
    int memory_limit = 1024 * 1024; // 1MB limit for example
    int max_value = 999;

    data_structure *ds = initialize_data_structure(n, memory_limit, max_value, 1);

    // Further operations...

    free_data_structure(ds);
    return 0;
}
