#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import time

typedef struct Item {
    int id;
    float value;
    struct Item *next;
} Item;

// Hash table for efficient ID lookup
#define HASH_TABLE_SIZE 10007 // A prime number to reduce collisions
typedef struct HashNode {
    int id;
    struct HashNode *next;
} HashNode;

HashNode* hashTable[HASH_TABLE_SIZE];

unsigned long hash(int id) {
    return (unsigned long)id % HASH_TABLE_SIZE;
}

int isIdUnique(int id) {
    unsigned long index = hash(id);
    HashNode *node = hashTable[index];
    while (node) {
        if (node->id == id)
            return 0; // ID already exists
        node = node->next;
    }
    return 1; // ID is unique
}

void addIdToHashTable(int id) {
    unsigned long index = hash(id);
    HashNode *newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for HashNode.\n");
        exit(EXIT_FAILURE);
    }
    newNode->id = id;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
}

void freeHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode *node = hashTable[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
}

void initializeCollection(int minId, int maxId, double minFloat, double maxFloat, size_t itemCount) {
    if (minId >= maxId || itemCount <= 0) return;

    // Initialize hash table
    memset(hashTable, 0, sizeof(HashNode*) * HASH_TABLE_SIZE);

    // Seed the random number generator
    srand(time(NULL));

    Item *head = NULL;

    for (size_t i = 0; i < itemCount; ++i) {
        int id;
        do {
            id = minId + rand() % ((maxId - minId) + 1);
        } while (!isIdUnique(id));

        addIdToHashTable(id);

        float value = (float)(minFloat + ((double)rand() / RAND_MAX * (maxFloat - minFloat)));

        Item *newItem = (Item*)malloc(sizeof(Item));
        if (!newItem) {
            fprintf(stderr, "Memory allocation failed for Item.\n");
            freeHashTable();
            exit(EXIT_FAILURE);
        }

        newItem->id = id;
        newItem->value = value;
        newItem->next = head;
        head = newItem;
    }

    // Example: Iterate through the items
    for (Item *current = head; current != NULL; current = current->next) {
        printf("ID: %d, Value: %.2f\n", current->id, current->value);
    }

    freeHashTable();
}

int main() {
    initializeCollection(1, 1000, 0.0, 10.0, 100);
    return 0;
}
