#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "crypto_hashing_library.h" // Replace with actual library header

#define MAX_MEMORY_LIMIT 1024 * 1024 * 10 // Example memory limit in bytes

typedef struct {
    int value;
    unsigned long hashed_key;
    long offset;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t initial_capacity) {
    pool->count = 0;
    pool->capacity = initial_capacity;
    pool->offsets = (long *)malloc(initial_capacity * sizeof(long));
    pool->keys = (int *)malloc(initial_capacity * sizeof(int));
    pthread_mutex_init(&pool->lock, NULL);
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->offsets);
    free(pool->keys);
    pthread_mutex_destroy(&pool->lock);
}

size_t get_current_usage(MemoryPool *pool) {
    return (sizeof(long) + sizeof(int)) * pool->count;
}

int allocate_more_memory(MemoryPool *pool, size_t additional_space) {
    pthread_mutex_lock(&pool->lock);

    if (get_current_usage(pool) + additional_space > MAX_MEMORY_LIMIT) {
        // Handle memory pressure by evicting or reducing usage
        printf("Memory limit exceeded. Evicting less frequently accessed data.\n");
        pthread_mutex_unlock(&pool->lock);
        return 0; // Indicate failure to allocate more memory
    }

    size_t new_capacity = pool->capacity + additional_space;
    long *new_offsets = (long *)realloc(pool->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(pool->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&pool->lock);
        return 0; // Allocation failure
    }

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->capacity = new_capacity;

    pthread_mutex_unlock(&pool->lock);
    return 1; // Success
}

void handle_allocation_failure(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

int initialize_arrays(MemoryPool *pool, size_t n, int max_value, int sort, unsigned long seed) {
    if (!allocate_more_memory(pool, n * (sizeof(long) + sizeof(int)))) {
        handle_allocation_failure("Failed to allocate memory for arrays.");
    }

    pool->count = n;
    srand(seed);

    for (size_t i = 0; i < n; ++i) {
        int value;
        do {
            value = rand() % (max_value + 1);
        } while (i > 0 && value == pool->keys[i - 1]); // Ensure uniqueness

        pool->keys[i] = value;

        if (!allocate_more_memory(pool, sizeof(long))) {
            handle_allocation_failure("Failed to allocate memory for more offsets.");
        }
    }

    for (size_t i = 0; i < n; ++i) {
        pool->offsets[i] = rand() % 10000; // Example offset generation
    }

    if (sort) {
        qsort(pool->keys, n, sizeof(int), compare_ints);
        qsort(pool->offsets, n, sizeof(long), compare_longs);
    }
}

int compare_ints(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int compare_longs(const void *a, const void *b) {
    return (*(long *)a - *(long *)b);
}

void populate_records(Record *records, size_t n, int max_value, unsigned long seed) {
    srand(seed);

    for (size_t i = 0; i < n; ++i) {
        int value;
        do {
            value = rand() % (max_value + 1);
        } while (i > 0 && value == records[i - 1].value); // Ensure uniqueness

        records[i].value = value;
        records[i].hashed_key = crypto_hash_function(value); // Replace with actual hashing function
    }
}

