    time_t creation_time;
    time_t modification_time;
} Metadata;

// Global variables for concurrency and logging
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
char log_buffer[LOG_BUFFER_SIZE];
FILE *log_file = NULL;

// Logging function
void log_message(const char* message) {
    pthread_mutex_lock(&mutex);
    snprintf(log_buffer, LOG_BUFFER_SIZE, "%s", message);
    if (log_file) fprintf(log_file, "%s\n", log_buffer);
    printf("%s\n", log_buffer); // Also print to stdout for visibility.
    fflush(log_file);
    pthread_mutex_unlock(&mutex);
}

// Memory usage check
int is_memory_above_threshold(size_t threshold) {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    return (usage.ru_maxrss > threshold);
}

void* serialize_data(void *data_structure);

// Compress function (simple example)
size_t compress_data(const void* input, size_t input_size, void** output) {
    // Placeholder for actual compression logic.
