#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_RECORDS 100
#define MAX_STRING_LENGTH 256
#define INT_MIN_VAL 0
#define INT_MAX_VAL 1000

typedef struct {
    uint32_t offset;
    char key[16];
    time_t timestamp;
    int status_flag;
    char string_data[MAX_STRING_LENGTH];
} Record;

typedef struct {
    size_t max_memory_limit; // in bytes
    int serialize_host_order;
    int truncate_strings;
    int max_string_length;
} Metadata;

typedef struct {
    Record *records[MAX_RECORDS];
    pthread_mutex_t mutex;
    Metadata metadata;
} RecordFramework;

RecordFramework* initialize_framework(size_t max_memory, int host_order, int truncate_str, int max_str_len) {
    RecordFramework *framework = (RecordFramework *)malloc(sizeof(RecordFramework));
    if (!framework) {
        fprintf(stderr, "Memory allocation failed for framework\n");
        return NULL;
    }

    framework->metadata.max_memory_limit = max_memory;
    framework->metadata.serialize_host_order = host_order;
    framework->metadata.truncate_strings = truncate_str;
    framework->metadata.max_string_length = max_str_len;

    pthread_mutex_init(&framework->mutex, NULL);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            return NULL;
        }

        // Initialize fields randomly
        record->offset = rand() % 1000;
        snprintf(record->key, sizeof(record->key), "Key%d", rand() % 10000);
        record->timestamp = time(NULL);
        record->status_flag = rand() % 2;
        snprintf(record->string_data, MAX_STRING_LENGTH, "StringData_%d", rand() % 1000);

        // Truncate strings if needed
        if (framework->metadata.truncate_strings && strlen(record->string_data) > framework->metadata.max_string_length) {
            record->string_data[framework->metadata.max_string_length] = '\0';
        }

        framework->records[i] = record;
    }

    return framework;
}

void serialize_framework(RecordFramework *framework, uint8_t **output, size_t *output_size) {
    if (!framework || !output || !output_size) return;

    pthread_mutex_lock(&framework->mutex);

    // Calculate total size required for serialization
    size_t estimated_size = 0;
    for (int i = 0; i < MAX_RECORDS; ++i) {
        estimated_size += sizeof(uint32_t) + sizeof(framework->records[i]->key);
        estimated_size += sizeof(time_t) + sizeof(int);
        estimated_size += strlen(framework->records[i]->string_data) + 1;
    }

    *output = (uint8_t *)malloc(estimated_size);
    if (!*output) {
        fprintf(stderr, "Memory allocation failed for serialization output\n");
        pthread_mutex_unlock(&framework->mutex);
        return;
    }

    uint8_t *ptr = *output;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        Record *record = framework->records[i];

        // Serialize offset
        *(uint32_t *)ptr = framework->metadata.serialize_host_order ? 
            htole32(record->offset) : record->offset;
        ptr += sizeof(uint32_t);

        // Serialize key
        memcpy(ptr, record->key, sizeof(record->key));
        ptr += sizeof(record->key);

        // Serialize timestamp
        *(time_t *)ptr = framework->metadata.serialize_host_order ? 
            htole64(record->timestamp) : record->timestamp;
        ptr += sizeof(time_t);

        // Serialize status_flag
        int status = framework->metadata.serialize_host_order ?
            htole32(record->status_flag) : record->status_flag;
        memcpy(ptr, &status, sizeof(int));
        ptr += sizeof(int);

        // Serialize string_data
        memcpy(ptr, record->string_data, strlen(record->string_data) + 1);
        ptr += strlen(record->string_data) + 1;
    }

    *output_size = ptr - (*output);
    pthread_mutex_unlock(&framework->mutex);
}

void cleanup_framework(RecordFramework *framework) {
    if (!framework) return;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        free(framework->records[i]);
    }

    pthread_mutex_destroy(&framework->mutex);
    free(framework);
}

int main() {
    srand(time(NULL));

    RecordFramework *framework = initialize_framework(1024 * 1024, 1, 1, MAX_STRING_LENGTH);
    if (!framework) return EXIT_FAILURE;

    uint8_t *serialized_data;
    size_t serialized_size;

    serialize_framework(framework, &serialized_data, &serialized_size);

    printf("Serialized data size: %zu bytes\n", serialized_size);

    free(serialized_data);
    cleanup_framework(framework);

    return EXIT_SUCCESS;
}
```

