int read_integers_from_input(int** array) {
    int capacity = 10;
    *array = (int*)allocate_memory(sizeof(int) * capacity);
    if (!*array) {
        return -1;
    }

    int count = 0, value;
    while (scanf("%d", &value) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            *array = realloc(*array, sizeof(int) * capacity);
            if (!*array) return -1; // Failed to reallocate
        }
        (*array)[count++] = value;
    }

    if (count == 0) return -1; // No input

    *array = realloc(*array, sizeof(int) * count); // Resize to actual number of inputs
    return count;
}

int find_most_frequent_value(int* array, int size) {
    FrequencyNode* nodes = NULL;

    for (int i = 0; i < size; ++i) {
        int key = array[i];

        FrequencyNode* current = nodes;
        while (current) {
            if (atomic_load(&current->key) == key) {
                atomic_fetch_add(&current->frequency, 1);
                break;
            }
            current = current->next;
        }

        // Node not found, create a new one
        if (!current) {
            FrequencyNode* new_node = (FrequencyNode*)allocate_memory(sizeof(FrequencyNode));
            if (!new_node) continue; // Skip on allocation failure

            atomic_store(&new_node->key, key);
            atomic_init(&new_node->frequency, 1);

            new_node->next = nodes;
            nodes = new_node;
        }
    }

    FrequencyNode* current = nodes;
    int max_key = -1, max_frequency = 0;

    while (current) {
        if (atomic_load(&current->frequency) > max_frequency) {
            max_key = atomic_load(&current->key);
            max_frequency = atomic_load(&current->frequency);
        }
        FrequencyNode* next = current->next;
        deallocate_memory(current, sizeof(FrequencyNode));
        current = next;
    }

    return max_key;
}

void log_event(const char* message) {
    printf("%s\n", message); // Replace with a real logging mechanism if needed
}
