Node* hashMap[HASH_MAP_SIZE];

unsigned long custom_hash(int key) {
    return (unsigned long)key * 2654435761 % HASH_MAP_SIZE;
}

void hash_map_insert(int key) {
    unsigned long index = custom_hash(key);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for hash map node");
        exit(EXIT_FAILURE);
    }
    newNode->key = key;
    newNode->next = hashMap[index];
    hashMap[index] = newNode;
}

int hash_map_contains(int key) {
    unsigned long index = custom_hash(key);
    Node* current = hashMap[index];
    while (current) {
        if (current->key == key) return 1;
        current = current->next;
    }
    return 0;
}

