// Binary search tree node for keys
typedef struct BSTNode {
    int key;
    struct BSTNode* left;
    struct BSTNode* right;
} BSTNode;

BSTNode* bst_insert(BSTNode* root, int key) {
    if (!root) return (BSTNode*)custom_alloc(sizeof(BSTNode));
    BSTNode* node = (BSTNode*)custom_alloc(sizeof(BSTNode));
    if (!node) exit(EXIT_FAILURE);

    node->key = key;
    node->left = node->right = NULL;

    if (key < root->key)
        root->left = bst_insert(root->left, key);
    else
        root->right = bst_insert(root->right, key);

    return root;
}

int bst_contains(BSTNode* root, int key) {
    while (root) {
        if (key == root->key) return 1;
        root = (key < root->key) ? root->left : root->right;
    }
    return 0;
}

// Circular buffer for records
typedef struct CircularBuffer {
    Record* array;
    size_t head, tail, capacity;
} CircularBuffer;

CircularBuffer* create_circular_buffer(size_t capacity) {
    CircularBuffer* cb = (CircularBuffer*)custom_alloc(sizeof(CircularBuffer));
    if (!cb) exit(EXIT_FAILURE);

    cb->array = (Record*)custom_alloc(capacity * sizeof(Record));
    if (!cb->array) exit(EXIT_FAILURE);

    cb->capacity = capacity;
    cb->head = cb->tail = 0;

    return cb;
}

void circular_buffer_push(CircularBuffer* cb, Record record) {
    cb->array[cb->tail] = record;
    cb->tail = (cb->tail + 1) % cb->capacity;
    if (cb->tail == cb->head) { // Buffer is full
        fprintf(stderr, "Circular buffer overflow\n");
        exit(EXIT_FAILURE);
    }
}

Record circular_buffer_pop(CircularBuffer* cb) {
    if (cb->head == cb->tail) {
        fprintf(stderr, "Circular buffer underflow\n");
        exit(EXIT_FAILURE);
    }
    Record record = cb->array[cb->head];
    cb->head = (cb->head + 1) % cb->capacity;
    return record;
}

// Function to manage memory allocation and initialization
void* manage_memory(size_t offset_size, size_t key_size, size_t record_count, int value_range_min, int value_range_max) {
    long* offsets = (long*)custom_alloc(offset_size * sizeof(long));
    if (!offsets) goto fail;

    int* keys = (int*)custom_alloc(key_size * sizeof(int));
    if (!keys) goto fail;

    BSTNode* bst_root = NULL;
    CircularBuffer* record_buffer = create_circular_buffer(record_count);
    if (!record_buffer) goto fail;

    // Initialize offsets and keys
    for (size_t i = 0; i < offset_size && i < key_size; ++i) {
        offsets[i] = i;
        int unique_key = -1;
        while (unique_key == -1 || hash_map_contains(unique_key) || bst_contains(bst_root, unique_key)) {
            unique_key = rand() % value_range_max;
        }
        keys[i] = unique_key;
        hash_map_insert(unique_key);
        bst_root = bst_insert(bst_root, unique_key);
    }

    // Initialize records with random values
    for (size_t i = 0; i < record_count; ++i) {
        int value;
        do {
            value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        } while (!hash_map_contains(value)); // Ensure unique

        Record rec = { .value = value, .offset_ptr = &offsets[i % offset_size] };
        circular_buffer_push(record_buffer, rec);
    }

    return record_buffer;

fail:
    custom_free_all();
    return NULL;
}

