#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int id;
    long offset;
    char buffer[BUFFER_SIZE];
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t mutex;
    unsigned char key[32]; // Supports up to 256-bit keys
    EVP_CIPHER_CTX *cipher_ctx;
    const EVP_CIPHER *cipher_type;
} RecordCollection;

RecordCollection collection = {0};

void init_library(const EVP_CIPHER *cipher, size_t key_size) {
    pthread_mutex_init(&collection.mutex, NULL);
    RAND_bytes(collection.key, key_size / 8);
    collection.cipher_type = cipher;
    collection.cipher_ctx = EVP_CIPHER_CTX_new();
}

void cleanup_library() {
    for (size_t i = 0; i < collection.count; ++i) {
        free(collection.records[i]);
    }
    EVP_CIPHER_CTX_free(collection.cipher_ctx);
    pthread_mutex_destroy(&collection.mutex);
}

int add_record(int id, long offset, const char *data) {
    pthread_mutex_lock(&collection.mutex);

    if (collection.count >= MAX_RECORDS) {
        pthread_mutex_unlock(&collection.mutex);
        return -1;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection.mutex);
        return -2;
    }

    record->id = id;
    record->offset = offset;
    strncpy(record->buffer, data, BUFFER_SIZE - 1);
    record->buffer[BUFFER_SIZE - 1] = '\0';

    collection.records[collection.count++] = record;

    pthread_mutex_unlock(&collection.mutex);
    return 0;
}

void encrypt_record(Record *record) {
    EVP_CIPHER_CTX_init(collection.cipher_ctx);

    int len, ciphertext_len;
    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, EVP_CIPHER_iv_length(collection.cipher_type));

    if (1 != EVP_EncryptInit_ex(collection.cipher_ctx, collection.cipher_type,
                                NULL, collection.key, iv)) {
        fprintf(stderr, "Encryption init failed\n");
        return;
    }

    unsigned char ciphertext[BUFFER_SIZE + EVP_MAX_BLOCK_LENGTH];
    if (1 != EVP_EncryptUpdate(collection.cipher_ctx, ciphertext, &len, 
                               (unsigned char *)record->buffer, strlen(record->buffer))) {
        fprintf(stderr, "Encryption update failed\n");
        return;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(collection.cipher_ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Encryption final failed\n");
        return;
    }
    ciphertext_len += len;

    // Replace plaintext with ciphertext
    memcpy(record->buffer, iv, sizeof(iv));
    memcpy(record->buffer + sizeof(iv), ciphertext, ciphertext_len);
}

int read_integers(int **array, size_t *size) {
    int n, capacity = 10;
    *array = malloc(capacity * sizeof(int));
    if (!*array) return -1;

    *size = 0;
    while (scanf("%d", &n) == 1) {
        if (*size >= capacity) {
            capacity *= 2;
            *array = realloc(*array, capacity * sizeof(int));
            if (!*array) return -2;
        }
        (*array)[(*size)++] = n;
    }

    return 0;
}

int find_largest_integer(const int *array, size_t size) {
    if (size == 0) return INT_MIN;

    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

void free_integers(int *array) {
    free(array);
}
